/*
 * MLX91219 Hall-Effect Current Sensor Reader via ADS1115 ADC
 * Board:  Raspberry Pi 4 Model B
 * Bus:    I2C bus 1 (GPIO2 = SDA, GPIO3 = SCL)
 * Sensor: MLX91219 ADDR -> GND, analog output -> ADS1115 AIN0
 * API:    pigpio (modern, actively maintained)
 *
 * Build:  gcc -O2 -Wall -o mlx91219 mlx91219.c -lpigpio -lrt
 * Run:    sudo ./mlx91219
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- ADS1115 constants (registers 0x01..0x2D) ---- */
#define ADS1115_ADDR        0x48
#define ADS1115_REG_CONV    0x00
#define ADS1115_REG_CONFIG  0x01

/* Config register bit fields (16-bit, big-endian on the wire) */
#define ADS1115_CFG_OS      0x8000  /* Operational status / single-shot start */
#define ADS1115_CFG_MUX     0x4000  /* MUX[14:12] = 100 -> AIN0 vs GND */
#define ADS1115_CFG_PGA     0x0200  /* PGA[11:9] = 001 -> ±4.096 V */
#define ADS1115_CFG_MODE   0x0100  /* MODE[8:6]  = 10  -> single-shot */
#define ADS1115_CFG_DR     0x0080  /* DR[5:3]   = 100 -> 128 SPS */
#define ADS1115_CFG_CQUE    0x0003  /* COMP_QUE[1:0] = 11 -> disable comparator */

#define ADS1115_PGA_4_096V  4.096f
#define ADS1115_MAX_COUNT   32767.0f  /* 16-bit signed, positive range */

#define I2C_BUS             1
#define SAMPLE_PERIOD_US    500000   /* 500 ms */
#define CONV_WAIT_US        10000    /* 10 ms (128 SPS -> ~8 ms; 10 ms is safe) */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit value to an ADS1115 register (big-endian on the wire). */
static int ads1115_write_reg(int handle, uint8_t reg, uint16_t value)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)(value >> 8);
    buf[2] = (char)(value & 0xFF);

    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(reg=0x%02X, val=0x%04X) failed\n",
                reg, value);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit value from an ADS1115 register (big-endian on the wire). */
static int ads1115_read_reg(int handle, uint8_t reg, uint16_t *out)
{
    char buf[2];

    if (i2cWriteDevice(handle, (char *)&reg, 1) != 1) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(reg=0x%02X) failed\n", reg);
        return -1;
    }

    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "[ERROR] i2cReadDevice(reg=0x%02X) failed\n", reg);
        return -1;
    }

    *out = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Trigger a single-shot conversion on AIN0 and read the result. */
static int ads1115_read_ain0(int handle, int16_t *raw_out)
{
    uint16_t config = ADS1115_CFG_OS
                    | ADS1115_CFG_MUX
                    | ADS1115_CFG_PGA
                    | ADS1115_CFG_MODE
                    | ADS1115_CFG_DR
                    | ADS1115_CFG_CQUE;

    if (ads1115_write_reg(handle, ADS1115_REG_CONFIG, config) != 0)
        return -1;

    /* Wait for conversion to complete (128 SPS -> ~8 ms; 10 ms is safe). */
    gpioDelay(CONV_WAIT_US);

    uint16_t conv_raw = 0;
    if (ads1115_read_reg(handle, ADS1115_REG_CONV, &conv_raw) != 0)
        return -1;

    *raw_out = (int16_t)conv_raw;
    return 0;
}

/* ------------------------------------------------------------------ */
static float raw_to_current(int16_t raw)
{
    return (float)raw / ADS1115_MAX_COUNT * ADS1115_PGA_4_096V;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus 1 at ADS1115 ADDR = 0x48 --- */
    g_i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, ADS1115_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Verify sensor presence by reading the config register --- */
    uint16_t cfg = 0;
    if (ads1115_read_reg(g_i2c_handle, ADS1115_REG_CONFIG, &cfg) != 0) {
        fprintf(stderr, "[FATAL] ADS1115 not responding on bus %d addr 0x%02X\n",
                I2C_BUS, ADS1115_ADDR);
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers for graceful shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MLX91219 via ADS1115 (I2C bus %d, ADDR->GND, AIN0) running.\n"
           "Press Ctrl+C to exit.\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        int16_t raw = 0;
        if (ads1115_read_ain0(g_i2c_handle, &raw) != 0) {
            fprintf(stderr, "[WARN] ADC read failed; retrying next cycle.\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        float current = raw_to_current(raw);
        printf("Current: %.4f A\n", current);
        fflush(stdout);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

