/*
 * Flame sensor monitoring with MCP3008 ADC on Raspberry Pi 3 Model B+.
 *
 * Wiring:
 *   KY-026 D0  -> BCM GPIO4  (SPI0 MISO)
 *   KY-026 VCC -> 3.3 V
 *   KY-026 GND -> GND
 *   MCP3008 VDD -> 3.3 V
 *   MCP3008 VREF -> 3.3 V
 *   MCP3008 AGND -> GND
 *   MCP3008 DGND -> GND
 *   MCP3008 CLK  -> BCM GPIO11 (SPI0 SCLK)
 *   MCP3008 DOUT -> BCM GPIO9  (SPI0 MISO)
 *   MCP3008 DIN  -> BCM GPIO10 (SPI0 MOSI)
 *   MCP3008 CS   -> BCM GPIO8  (SPI0 CE0)
 *
 * Build:  gcc -O2 -Wall -Wextra -o flame_monitor flame_monitor.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define FLAME_SENSOR_PIN 4
#define SPI_CHANNEL     0          /* CE0 on GPIO8 */
#define SPI_SPEED       1000000    /* 1 MHz */
#define SPI_FLAGS       0          /* Mode 0, active-low CE */
#define MCP3008_CHANNEL 0          /* A0 on CH0 */
#define LOG_FILE        "flame_data.csv"
#define SAMPLE_PERIOD_US 1000000  /* 1 second */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a single-ended channel from the MCP3008.
 * Returns 0–1023 on success, -1 on SPI transfer failure.
 */
static int mcp3008_read(int spi_handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care bits)
     *   tx[2] = 0x00                       (don't-care, clocks out low 2 bits)
     * Result: 10-bit value assembled from rx[1] (low 2 bits) and rx[2] (8 bits).
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d): %s\n",
                ret, strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;
}

static int read_flame_sensor(int spi_handle)
{
    int adc_value = mcp3008_read(spi_handle, MCP3008_CHANNEL);
    if (adc_value < 0) {
        return -1;
    }

    /* KY-026 D0 is active-high; return 1 if the line reads HIGH. */
    return (adc_value & 0x01) ? 1 : 0;
}

static float calculate_temperature(int adc_value)
{
    /*
     * Approximate temperature from the analog reading.
     * Assumes a known reference voltage (e.g., 3.3 V) and a linear
     * sensor response.  A more accurate calibration would require
     * a known temperature at a known ADC value.
     */
    if (adc_value < 0 || adc_value > 1023) {
        return -1.0f;
    }
    return (float)adc_value * 0.01f;
}

static int log_data(FILE *fp, int flame_detected, float temperature)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%d,%.2f\n", timestamp, flame_detected, temperature) < 0) {
        fprintf(stderr, "fprintf to log file failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    int spi_handle = -1;
    FILE *fp = NULL;
    int ret_code = EXIT_FAILURE;

    /* --- Install signal handlers for graceful shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        goto cleanup;
    }

    /* --- Open SPI0 CE0 at 1 MHz, mode 0 --- */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (channel %d, speed %d): %s\n",
                SPI_CHANNEL, SPI_SPEED, pigpio_error(spi_handle));
        goto cleanup;
    }

    /* --- Open log file (append mode) --- */
    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    /* Write CSV header if the file is empty */
    if (ftell(fp) == 0) {
        if (fprintf(fp, "timestamp,flame_detected,temperature_c\n") < 0) {
            fprintf(stderr, "Failed to write CSV header: %s\n", strerror(errno));
            goto cleanup;
        }
        if (fflush(fp) != 0) {
            fprintf(stderr, "fflush header failed: %s\n", strerror(errno));
            goto cleanup;
        }
    }

    printf("Flame sensor monitoring started. Logging to %s\n", LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        int flame_detected = read_flame_sensor(spi_handle);
        float temperature = calculate_temperature(flame_detected);

        if (log_data(fp, flame_detected, temperature) != 0) {
            fprintf(stderr, "Logging failed; continuing.\n");
        }

        if (temperature < 0.0f) {
            fprintf(stderr, "Warning: temperature calculation failed; skipping.\n");
        }

        /* Sleep 1 second using pigpio's microsecond delay */
        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down gracefully...\n");
    ret_code = EXIT_SUCCESS;

cleanup:
    if (fp != NULL) {
        if (fclose(fp) != 0) {
            fprintf(stderr, "fclose failed: %s\n", strerror(errno));
        }
    }
    if (spi_handle >= 0) {
        if (spiClose(spi_handle) != 0) {
            fprintf(stderr, "spiClose failed\n");
        }
    }
    gpioTerminate();
    return ret_code;
}

