#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 27
#define I2C_BUS 1
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_CONFIG_BASE 0x8000
#define ADS1115_CONFIG_MUX_AIN0 0x4000
#define ADS1115_CONFIG_PGA_4_096V 0x0200
#define ADS1115_CONFIG_MODE_SINGLE 0x0100
#define ADS1115_CONFIG_DR_128_SPS 0x0080
#define DEBOUNCE_DELAY_MS 50
#define POLL_DELAY_MS 100
#define BUZZER_DURATION_MS 2000
#define TEMP_THRESHOLD_C 60.0f
#define LOG_FILE "fire_log.txt"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    if (log_file) {
        fprintf(log_file, "%s: %s\n", timestamp, message);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file not open.\n");
        return -1;
    }
    return 0;
}

static int read_flame_sensor(void) {
    int level = gpioRead(FLAME_SENSOR_PIN);
    if (level < 0) {
        fprintf(stderr, "Error: Failed to read flame sensor GPIO %d.\n", FLAME_SENSOR_PIN);
        return -1;
    }
    gpioDelay(DEBOUNCE_DELAY_MS * 1000);
    int confirmed = gpioRead(FLAME_SENSOR_PIN);
    if (confirmed < 0) {
        fprintf(stderr, "Error: Failed to read flame sensor GPIO %d after debounce.\n", FLAME_SENSOR_PIN);
        return -1;
    }
    return (level == confirmed) ? 1 : 0;
}

static int read_temperature(void) {
    char config[3];
    config[0] = ADS1115_REG_CONFIG;
    config[1] = ADS1115_CONFIG_BASE | ADS1115_CONFIG_MUX_AIN0 | ADS1115_CONFIG_PGA_4_096V |
                ADS1115_CONFIG_MODE_SINGLE | ADS1115_CONFIG_DR_128_SPS;
    config[2] = 0x00;

    if (i2cWriteDevice(i2c_handle, config, 3) < 0) {
        fprintf(stderr, "Error: Failed to write ADS1115 config.\n");
        return -1;
    }

    char reg[1] = {ADS1115_REG_CONVERSION};
    if (i2cWriteDevice(i2c_handle, reg, 1) < 0) {
        fprintf(stderr, "Error: Failed to set ADS1115 conversion register pointer.\n");
        return -1;
    }

    char data[2];
    if (i2cReadDevice(i2c_handle, data, 2) < 0) {
        fprintf(stderr, "Error: Failed to read ADS1115 conversion data.\n");
        return -1;
    }

    int16_t raw = (data[0] << 8) | data[1];
    return (int)raw;
}

static void activate_buzzer(int duration_ms) {
    gpioWrite(BUZZER_PIN, 1);
    gpioDelay(duration_ms * 1000);
    gpioWrite(BUZZER_PIN, 0);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return 1;
    }

    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: Failed to set flame sensor pin mode.\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set buzzer pin mode.\n");
        gpioTerminate();
        return 1;
    }
    gpioWrite(BUZZER_PIN, 0);

    i2c_handle = i2cOpen(I2C_BUS, 0, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d.\n", I2C_BUS);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: Failed to register SIGINT handler: %s\n", strerror(errno));
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Fire detection system started. Press Ctrl+C to exit.\n");

    while (running) {
        int flame = read_flame_sensor();
        int temp = read_temperature();

        if (flame < 0 || temp < 0) {
            fprintf(stderr, "Error: Sensor read failure, continuing.\n");
        } else {
            if (flame && temp > 0) {
                log_event("Fire detected!");
                activate_buzzer(BUZZER_DURATION_MS);
            } else if (flame) {
                log_event("Flame detected!");
            } else if (temp > 0) {
                float temp_c = (float)temp * 0.0048828125f;
                char msg[64];
                snprintf(msg, sizeof(msg), "Temperature: %.2f C", temp_c);
                log_event(msg);
            }
        }

        gpioDelay(POLL_DELAY_MS * 1000);
    }

    printf("\nShutting down...\n");
    gpioWrite(BUZZER_PIN, 0);
    if (log_file) {
        fclose(log_file);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    return 0;
}

