/*
 * Raspberry Pi 5 – MLX91219 current sensor via MCP3008 ADC, fan control
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V
 *   MCP3008 VREF -> 3.3 V
 *   MCP3008 AGND -> GND
 *   MCP3008 DGND -> GND
 *   MCP3008 CLK  -> GPIO11 (SPI0 SCLK)
 *   MCP3008 DOUT -> GPIO9  (SPI0 MISO)
 *   MCP3008 DIN  -> GPIO10 (SPI0 MOSI)
 *   MCP3008 CS   -> GPIO8  (SPI0 CE0)
 *   MCP3008 CH0  -> MLX91219 analog output
 *   Fan control  -> GPIO18 (BCM)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o current_monitor current_monitor.c -lm
 *
 * Run:
 *   sudo ./current_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <linux/gpio.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U
#define SPI_BITS        8
#define SPI_MODE        SPI_MODE_0

#define FAN_GPIO_LINE   18          /* BCM 18 */
#define FAN_CHIP_NAME   "gpiochip4" /* RP1 on Pi 5 */
#define FAN_CHIP_DEFAULT "gpiochip0"

#define LOG_FILE        "current_log.txt"
#define SAMPLE_PERIOD_S 1

#define ADC_CHANNEL     0
#define ADC_MAX_VALUE   1023       /* MCP3008 is 10-bit */

/* Thresholds (milliamps) */
#define CURRENT_THRESHOLD 5000.0f

/* Sensor-absent / bus-fail sentinel values */
#define ADC_ZERO       0
#define ADC_FULL       (ADC_MAX_VALUE + 1)

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* SPI helpers                                                         */
/* ------------------------------------------------------------------ */

static int spi_open(const char *device)
{
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", device, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

/*
 * MCP3008 single-ended read.
 * Returns 0–1023 on success, or -1 on SPI error, or -2 if sensor absent
 * (all-zero or all-one).
 */
static int mcp3008_read(int fd, uint8_t channel)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid ADC channel %u\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI frame (mode 0, MSB-first):
     *   Byte 0: 0x01                       (start bit)
     *   Byte 1: (0x08 | channel) << 4      (single-ended + channel)
     *   Byte 2: 0x00                       (clock out remaining bits)
     * Result: 10-bit value assembled from the last 2 bits of rx[1] and
     *        rx[2].
     */
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = sizeof(tx);
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE: %s\n", strerror(errno));
        return -1;
    }

    int adc = ((rx[1] & 0x03) << 8) | rx[2];

    /* Sensor-absent heuristic: all bits zero or all bits full */
    if (adc == ADC_ZERO || adc == ADC_FULL) {
        fprintf(stderr, "ADC saturated (raw=%d) – sensor absent or bus fault\n", adc);
        return -2;
    }

    return adc;
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */

static int gpio_init(int *chip, unsigned int line)
{
    *chip = -1;
    if (line <= 31) {
        /* Pi 5 has BCM GPIOs 0–31 on gpiochip4 (RP1) */
        *chip = open("/dev/gpiochip4", O_RDWR);
        if (*chip < 0) {
            *chip = open("/dev/gpiochip0", O_RDWR);
            if (*chip < 0) {
                fprintf(stderr, "open(gpiochip): %s\n", strerror(errno));
                return -1;
            }
        }
    } else {
        /* Fall back to gpiochip0 for lines 32–53 */
        *chip = open("/dev/gpiochip0", O_RDWR);
        if (*chip < 0) {
            fprintf(stderr, "open(gpiochip0): %s\n", strerror(errno));
            return -1;
        }
    }

    unsigned int offset = line;
    if (ioctl(*chip, GPIO_GET_LINE, &offset) < 0) {
        fprintf(stderr, "GPIO_GET_LINE: %s\n", strerror(errno));
        close(*chip);
        *chip = -1;
        return -1;
    }

    if (ioctl(*chip, GPIO_SET_LINE_MODE, &offset) < 0) {
        fprintf(stderr, "GPIO_SET_LINE_MODE: %s\n", strerror(errno));
        close(*chip);
        *chip = -1;
        return -1;
    }

    if (ioctl(*chip, GPIO_SET_LINE_VALUE, &offset) < 0) {
        fprintf(stderr, "GPIO_SET_LINE_VALUE: %s\n", strerror(errno));
        close(*chip);
        *chip = -1;
        return -1;
    }

    return 0;
}

static int gpio_set(int chip, unsigned int line, int value)
{
    if (chip < 0) {
        return -1;
    }

    unsigned int offset = line;
    if (ioctl(chip, GPIO_SET_LINE_VALUE, &offset) < 0) {
        fprintf(stderr, "GPIO_SET_LINE_VALUE: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */

static int log_current(int current)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime: buffer too small\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s, Current: %d\n", ts, current) < 0) {
        fprintf(stderr, "fprintf: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    int spi_fd = -1;
    int gpio_chip = -1;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    spi_fd = spi_open(SPI_DEVICE);
    if (spi_fd < 0) {
        return EXIT_FAILURE;
    }

    if (gpio_init(&gpio_chip, FAN_GPIO_LINE) < 0) {
        close(spi_fd);
        return EXIT_FAILURE;
    }

    printf("Monitoring MLX91219 on MCP3008 CH0 (SPI0 CE0). Ctrl+C to exit.\n");

    while (g_running) {
        int current = mcp3008_read(spi_fd, ADC_CHANNEL);

        if (current < 0) {
            /* SPI error already reported; keep fan in safe state */
            if (gpio_set(gpio_chip, FAN_GPIO_LINE, 0) < 0) {
                fprintf(stderr, "Failed to turn fan off during error\n");
            }
            sleep(SAMPLE_PERIOD_S);
            continue;
        }

        if (log_current(current) < 0) {
            fprintf(stderr, "Logging failed; continuing\n");
        }

        int fan_on = (current > CURRENT_THRESHOLD) ? 1 : 0;
        if (gpio_set(gpio_chip, FAN_GPIO_LINE, fan_on) < 0) {
            fprintf(stderr, "Failed to set fan GPIO\n");
        }

        sleep(SAMPLE_PERIOD_S);
    }

    /* Graceful shutdown */
    printf("\nShutting down...\n");
    gpio_set(gpio_chip, FAN_GPIO_LINE, 0);
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (gpio_chip >= 0) {
        close(gpio_chip);
    }
    printf("Fan OFF, SPI closed, exiting.\n");
    return EXIT_SUCCESS;
}

