            if (gpio_set(gpio_chip, FAN_GPIO_LINE, 0) < 0) {
                fprintf(stderr, "Failed to turn fan off during error\n");
            }
            sleep(SAMPLE_PERIOD_S);
            continue;
        }

        if (log_current(current) < 0) {
            fprintf(stderr, "Logging failed; continuing\n");
        }

        int fan_on = (current > CURRENT_THRESHOLD) ? 1 : 0;
        if (gpio_set(gpio_chip, FAN_GPIO_LINE, fan_on) < 0) {
            fprintf(stderr, "Failed to set fan GPIO\n");
        }

        sleep(SAMPLE_PERIOD_S);
    }

    /* Graceful shutdown */
    printf("\nShutting down...\n");
    gpio_set(gpio_chip, FAN_GPIO_LINE, 0);
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (gpio_chip >= 0) {
        close(gpio_chip);
    }
    printf("Fan OFF, SPI closed, exiting.\n");
    return EXIT_SUCCESS;
}

