/*
 * Raspberry Pi 4 Model B – Honeywell MICS-4514 CO sensor logger
 *
 * Wiring:
 *   MICS-4514 SDA  -> Pi GPIO2  (I2C bus 1, pin 3)
 *   MICS-4514 SCL  -> Pi GPIO3  (I2C bus 1, pin 5)
 *   MICS-4514 VDD  -> 3.3 V
 *   MICS-4514 GND  -> GND
 *
 * NOTE: The MICS-4514 is a digital (MOS) sensor; it does not have an
 * analog I2C output.  This program assumes an external 16-bit ADC
 * (e.g. ADS1115) is connected between the MICS-4514 and the Pi.
 *
 * Build:  gcc -O2 -Wall -Wextra -o co_logger co_logger.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define LOG_FILE       "co_log.txt"
#define SAMPLE_PERIOD  5          /* seconds between samples */
#define ADC_RESOLUTION 16         /* 16-bit ADC (ADS1115) */

/* MICS-4514 register addresses (digital output) */
#define MICS_REG_CO_A  0x00
#define MICS_REG_CO_B  0x01

/* ADS1115 register addresses (16-bit ADC) */
#define ADS_REG_CONV   0x00
#define ADS_REG_CONFIG 0x01

/* ADS1115 config: single-shot, AIN0, +/-4.096 V, 128 SPS, continuous */
#define ADS_CONFIG_BASE 0x8000  /* OS bit */
#define ADS_CONFIG_MUX   0x4000  /* AIN0 vs GND */
#define ADS_CONFIG_PGA   0x0200  /* +/-4.096 V */
#define ADS_CONFIG_MODE 0x0100  /* single-shot */
#define ADS_CONFIG_DR    0x0080  /* 128 SPS */
#define ADS_CONFIG_CQUE  0x0003  /* disable comparator */

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write16(int fd, uint8_t reg, uint16_t val)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(val >> 8);
    buf[2] = (uint8_t)(val & 0xFF);

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write16: write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t reg_buf = reg;
    uint8_t data[2];

    if (write(fd, &reg_buf, 1) != 1) {
        fprintf(stderr, "i2c_read16: write reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, data, 2) != 2) {
        fprintf(stderr, "i2c_read16: read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* ADS1115                                                             */
/* ------------------------------------------------------------------ */
static int ads1115_init(int fd)
{
    /* Disable comparator so we read the conversion directly. */
    if (i2c_write16(fd, ADS_REG_CONFIG, ADS_CONFIG_CQUE) == -1)
        return -1;
    return 0;
}

static int ads1115_read(int fd, int16_t *raw)
{
    uint16_t cfg;
    uint16_t conv;

    /* Trigger a single-shot conversion on AIN0. */
    cfg = ADS_CONFIG_BASE | ADS_CONFIG_MUX | ADS_CONFIG_PGA |
          ADS_CONFIG_MODE | ADS_CONFIG_DR;
    if (i2c_write16(fd, ADS_REG_CONFIG, cfg) == -1)
        return -1;

    /* Wait for conversion to complete (~8 ms at 128 SPS). */
    usleep(10000);

    if (i2c_read16(fd, ADS_REG_CONV, &conv) == -1)
        return -1;

    *raw = (int16_t)conv;
    return 0;
}

/* ------------------------------------------------------------------ */
/* MICS-4514 (digital)                                                  */
/* ------------------------------------------------------------------ */
static int mics_read(int fd, int16_t *raw)
{
    uint16_t a, b;

    if (i2c_read16(fd, MICS_REG_CO_A, &a) == -1)
        return -1;
    if (i2c_read16(fd, MICS_REG_CO_B, &b) == -1)
        return -1;

    *raw = (int16_t)((a << 8) | b);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Calibration                                                         */
/* ------------------------------------------------------------------ */
/*
 * Placeholder logarithmic calibration curve.
 * Replace with your sensor-specific calibration data.
 */
static double calibrate_ppm(int16_t raw)
{
    /* Raw ADC counts scaled to a 0–1 range. */
    double normalized = (double)raw / (double)(1 << ADC_RESOLUTION);

    /* Logarithmic curve: ppm = a * log10(r) + b */
    return 0.5 * log10(normalized + 1.0);
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_data(double ppm)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "log_data: fopen(%s) failed: %s\n",
                LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "log_data: localtime_r failed: %s\n",
                strerror(errno));
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, %.2f ppm\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, ppm);

    if (fclose(fp) != 0) {
        fprintf(stderr, "log_data: fclose failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int i2c_fd = -1;
    int ret_code = EXIT_FAILURE;

    if (install_signal_handlers() == -1)
        goto cleanup;

    /* Open I2C bus. */
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd == -1) {
        fprintf(stderr, "main: open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        goto cleanup;
    }

    /* Acquire the MICS-4514 slave address. */
    if (ioctl(i2c_fd, I2C_SLAVE, 0x44) == -1) {
        fprintf(stderr, "main: ioctl(I2C_SLAVE, 0x44) failed: %s\n",
                strerror(errno));
        goto cleanup;
    }

    /* Initialize ADS1115 ADC. */
    if (ads1115_init(i2c_fd) == -1) {
        fprintf(stderr, "main: ADS1115 initialization failed (sensor absent or bus error)\n");
        goto cleanup;
    }

    printf("CO sensor logger started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_PERIOD);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        int16_t raw = 0;

        if (mics_read(i2c_fd, &raw) == -1) {
            fprintf(stderr, "main: MICS-4514 read failed – sensor absent or bus error\n");
            /* Brief pause before retrying to avoid log flooding on persistent error. */
            sleep(1);
            continue;
        }

        double ppm = calibrate_ppm(raw);

        if (log_data(ppm) == -1) {
            fprintf(stderr, "main: logging failed\n");
        } else {
            printf("CO: %.2f ppm\n", ppm);
        }

        /* Sleep in 1-second increments so signals are caught promptly. */
        for (int i = 0; i < SAMPLE_PERIOD && g_running; i++)
            sleep(1);
    }

    printf("\nShutting down cleanly.\n");
    ret_code = EXIT_SUCCESS;

cleanup:
    if (i2c_fd != -1)
        close(i2c_fd);
    return ret_code;
}

