code:
/*
 * Flame sensor monitor using AZDelivery KY-026 module and MCP3008 ADC.
 *
 * Wiring (Raspberry Pi 3 Model B+):
 *   KY-026 D0  -> GPIO 4  (BCM)
 *   KY-026 VCC -> 3.3 V
 *   KY-026 GND -> GND
 *   MCP3008 VDD -> 3.3 V
 *   MCP3008 VREF -> 3.3 V
 *   MCP3008 AGND -> GND
 *   MCP3008 DGND -> GND
 *   MCP3008 CLK  -> GPIO 11 (BCM)
 *   MCP3008 DOUT -> GPIO 9  (BCM)
 *   MCP3008 DIN  -> GPIO 10 (BCM)
 *   MCP3008 CS   -> GPIO 8  (BCM)
 *   MCP3008 CH0  -> KY-026 A0
 *
 * Build:  gcc -O2 -Wall -Wextra -o flame_monitor flame_monitor.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#include <pigpio.h>

/* ---- Pin / bus definitions ------------------------------------------------ */
#define FLAME_SENSOR_PIN  4          /* BCM 4  - KY-026 D0 */
#define SPI_CHANNEL       0          /* pigpio SPI channel 0 maps to CE0 / GPIO 8 */
#define SPI_SPEED         1000000    /* 1 MHz */
#define SPI_FLAGS         0          /* Mode 0, active-low CE */

/* ---- Application constants ----------------------------------------------- */
#define LOG_FILE          "flame_data.csv"
#define SAMPLE_INTERVAL_S 1
#define ADC_CHANNEL       0          /* MCP3008 CH0 */

/* ---- Globals for signal-safe cleanup ------------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static FILE *g_log_fp    = NULL;

/* -------------------------------------------------------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* -------------------------------------------------------------------------- */
/* Read MCP3008 single-ended channel (0–7). Returns 0–1023 or -1 on error.   */
static int mcp3008_read(int handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI protocol (3 bytes):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, padded)
     *   tx[2] = 0x00                       (clock out low 2 bits)
     * Result: rx[1] low 2 bits + rx[2] 8 bits.
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d): %s\n",
                ret, strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;
}

/* -------------------------------------------------------------------------- */
static int log_data(FILE *fp, int flame_present, float temperature)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    if (t == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%d,%.2f\n", ts, flame_present, temperature) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* -------------------------------------------------------------------------- */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* -------------------------------------------------------------------------- */
int main(void)
{
    /* ---- Initialize pigpio ---------------------------------------------- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Open SPI0 CE0 at 1 MHz, mode 0 ---------------------------------- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (channel %d, %d Hz): %s\n",
                SPI_CHANNEL, SPI_SPEED, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Open log file --------------------------------------------------- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "timestamp,flame_present,temperature_c\n");
        fflush(g_log_fp);
    }

    /* ---- Signal handling ----------------------------------------------- */
    struct sigaction sa;
