/*
 * MICS-4514 Dual MOS Sensor (CO/NO2) Air Quality Monitor
 * Board:  Raspberry Pi 4 Model B
 * Bus:    I2C bus 1 (GPIO2 = SDA, GPIO3 = SCL)
 * Sensor: SGX Sensortech MICS-4514
 *
 * Reads OX (CO) and RED (NO2) channels from the sensor and logs CO
 * concentration to co_log.txt every 5 seconds.  If CO exceeds 25 ppm,
 * an alert is appended to alert_log.txt.
 *
 * Build:  gcc -O2 -Wall -Wextra -o air_monitor air_monitor.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <math.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MICS4514_ADDR  0x68

/* MICS-4514 register addresses (16-bit, big-endian on the bus) */
#define REG_OX_ADC     0x00
#define REG_NO2_ADC    0x04

#define CO_THRESHOLD   25.0f
#define LOG_FILE       "co_log.txt"
#define ALERT_FILE     "alert_log.txt"
#define SAMPLE_PERIOD  5

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* Write a 16-bit value to a 16-bit register (big-endian on the bus). */
static int i2c_write_reg16(int fd, uint8_t reg, uint16_t val)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(val >> 8);
    buf[2] = (uint8_t)(val & 0xFF);

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write_reg16(0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a 16-bit value from a 16-bit register (big-endian on the bus). */
static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t reg_buf = reg;
    uint8_t data[2];

    if (write(fd, &reg_buf, 1) != 1) {
        fprintf(stderr, "i2c_read_reg16 write(0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }

    if (read(fd, data, 2) != 2) {
        fprintf(stderr, "i2c_read_reg16 read(0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }

    *out = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

/* Read the two 16-bit ADC channels from the MICS-4514. */
static int read_mics4514(int fd, uint16_t *ox, uint16_t *no2)
{
    if (i2c_read_reg16(fd, REG_OX_ADC, ox) < 0)
        return -1;
    if (i2c_read_reg16(fd, REG_NO2_ADC, no2) < 0)
        return -1;
    return 0;
}

/* Convert raw OX ADC value to CO concentration in ppm. */
static float calculate_co_ppm(uint16_t raw)
{
    /* Placeholder calibration: 0x8000 -> 0 ppm, 0x1000 -> 25 ppm */
    return (float)raw / 256.0f * 25.0f;
}

/* Append a CO reading to the log file. */
static int log_co_reading(float ppm)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, %.2f ppm\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, ppm);
    } else {
        fprintf(fp, "(time-error), %.2f ppm\n", ppm);
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose(%s): %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    return 0;
}

/* Append an alert entry to the alert log file. */
static int log_alert(float ppm)
{
    FILE *fp = fopen(ALERT_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", ALERT_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, CO alert: %.2f ppm\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, ppm);
    } else {
        fprintf(fp, "(time-error), CO alert: %.2f ppm\n", ppm);
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose(%s): %s\n", ALERT_FILE, strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    /* Install signal handlers for graceful shutdown. */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        goto cleanup;
    }

    /* Open the I2C bus. */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        goto cleanup;
    }

    if (ioctl(fd, I2C_SLAVE, MICS4514_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                MICS4514_ADDR, strerror(errno));
        goto cleanup;
    }

    printf("MICS-4514 air quality monitor started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_PERIOD);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t raw_ox = 0, raw_no2 = 0;

        if (read_mics4514(fd, &raw_ox, &raw_no2) < 0) {
            fprintf(stderr, "Sensor read error; retrying in %d s.\n",
                    SAMPLE_PERIOD);
            sleep(SAMPLE_PERIOD);
            continue;
        }

        float ppm = calculate_co_ppm(raw_ox);

        if (log_co_reading(ppm) < 0) {
            fprintf(stderr, "Failed to log CO reading.\n");
        }

        if (ppm >= CO_THRESHOLD) {
            printf("CO alert: %.2f ppm\n", ppm);
            if (log_alert(ppm) < 0) {
                fprintf(stderr, "Failed to log alert.\n");
            }
        }

        sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down cleanly.\n");
    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0)
        close(fd);
    return rc;
}

