/*
 * Raspberry Pi 4 Model B – dual IMP23ABSU microphone sound-pressure-level logger.
 *
 * Wiring:
 *   IMP23ABSU OUT1  -> GPIO2 (BCM2)  [I2C bus 1, pin 3]
 *   IMP23ABSU OUT2  -> GPIO3 (BCM3)  [I2C bus 1, pin 5]
 *   IMP23ABSU VDD    -> 3.3 V
 *   IMP23ABSU GND    -> GND
 *
 * I2C bus 1 is emulated via bit-banging on the Pi's GPIO2/3 (BCM2/3).
 * A 0.1 µA current-sense resistor is recommended between the microphone
 * OUT pin and the Pi's GND to enable the onboard ADC (ADC1) to drive
 * the IMP23ABSU OUT pin to a defined logic level.
 *
 * Build:  gcc -O2 -Wall -Wextra -o audio_logger audio_logger.c
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define GPIO2_OFFSET   2
#define GPIO3_OFFSET   3
#define LOG_FILE       "audio_log.txt"
#define SAMPLE_PERIOD  100000          /* 100 ms in microseconds */
#define ERROR_VALUE    (-999.0f)

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/*
 * Bit-bang a single I2C transaction: write a 2-byte command, then
 * read `len` bytes back.  Returns 0 on success, -1 on error.
 */
static int i2c_write_read(int fd, const uint8_t *cmd, size_t len,
                          uint8_t *buf, size_t buf_len)
{
    if (len == 0 || buf_len == 0)
        return -1;

    /* Write the command byte(s). */
    if (write(fd, cmd, len) != (ssize_t)len) {
        fprintf(stderr, "i2c write failed: %s\n", strerror(errno));
        return -1;
    }

    /* Read the response. */
    if (read(fd, buf, buf_len) != (ssize_t)buf_len) {
        fprintf(stderr, "i2c read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read a 16-bit big-endian sample from the IMP23ABSU.
 * Returns 0 on success and stores the sample in *out; returns -1 on error.
 */
static int read_microphone_sample(int fd, float *out)
{
    uint8_t cmd[2] = {0x00, 0x00};   /* dummy command to clock out data */
    uint8_t buf[2] = {0};

    if (i2c_write_read(fd, cmd, 2, buf, sizeof(buf)) != 0)
        return -1;

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *out = (float)raw;
    return 0;
}

static float calculate_average(const float *samples, int n)
{
    float sum = 0.0f;
    for (int i = 0; i < n; i++)
        sum += samples[i];
    return sum / (float)n;
}

static int log_data(float average)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        fclose(fp);
        return -1;
    }

    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, %.2f\n", ts, average);
    fclose(fp);
    return 0;
}

int main(void)
{
    if (install_signal_handlers() != 0)
        return EXIT_FAILURE;

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, 0) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE) failed: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("Audio logger started. Logging to %s every %d ms.\n",
           LOG_FILE, SAMPLE_PERIOD / 1000);

    while (g_running) {
        float samples[2] = {ERROR_VALUE, ERROR_VALUE};

        if (read_microphone_sample(fd, &samples[0]) != 0) {
            fprintf(stderr, "Sensor 1 read failed; logging error.\n");
            samples[0] = ERROR_VALUE;
        }

        if (read_microphone_sample(fd, &samples[1]) != 0) {
            fprintf(stderr, "Sensor 2 read failed; logging error.\n");
            samples[1] = ERROR_VALUE;
        }

        float avg = calculate_average(samples, 2);
        if (log_data(avg) != 0)
            fprintf(stderr, "Failed to log data.\n");

        usleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down cleanly.\n");
    close(fd);
    return EXIT_SUCCESS;
}

