/*
 * Raspberry Pi 4 Model B – Dual ADMP401 MEMS Microphone RMS Sampler
 *
 * Hardware:
 *   MCP3008 ADC on SPI0 (CE0 = GPIO8, CE1 = GPIO9, MISO = GPIO9, MOSI = GPIO10, SCLK = GPIO11)
 *   LED on GPIO27 (BCM)
 *
 * Behavior:
 *   - Acquires 100 samples (1 ms window) from each of two ADMP401 microphones
 *   - Computes RMS for each channel
 *   - Logs timestamp, mic1 RMS, mic2 RMS to audio_events.csv
 *   - Lights LED for 500 ms if either RMS exceeds a threshold
 *   - Handles SIGINT cleanly
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_FLAGS   0

#define LED_PIN     27
#define SAMPLE_RATE_MS 1
#define WINDOW_MS   100
#define WINDOW_SAMPLES (WINDOW_MS * 1000 / SAMPLE_RATE_MS)
#define LED_ON_MS   500
#define HIGH_THRESHOLD 0.5f

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Read a single-ended channel from the MCP3008 via SPI. */
static int read_mcp3008(int spi_handle, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: start bit, SGL/DIFF=1, D2 D1 D0, then 10-bit result */
    char tx[3] = { 0x01, (char)(0x80 | (channel << 4)), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (ret=%d)\n", ret);
        return -1;
    }

    /* 10-bit result: low 2 bits of rx[1] + 8 bits of rx[2] */
    return ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
}

static float calculate_rms(const int *samples, int num_samples) {
    double sum_sq = 0.0;
    for (int i = 0; i < num_samples; i++) {
        double v = (double)samples[i];
        sum_sq += v * v;
    }
    return (float)(sum_sq / num_samples);
}

static void log_data(FILE *fp, float rms1, float rms2) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(fp, "%s,%.2f,%.2f\n", ts, rms1, rms2);
    fflush(fp);
}

int main(void) {
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- LED pin --- */
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    /* --- SPI open --- */
    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle=%d)\n", spi_handle);
        gpioWrite(LED_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- CSV file --- */
    FILE *fp = fopen("audio_events.csv", "a");
    if (!fp) {
        fprintf(stderr, "Failed to open audio_events.csv\n");
        spiClose(spi_handle);
        gpioWrite(LED_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler\n");
        fclose(fp);
        spiClose(spi_handle);
        gpioWrite(LED_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Sampling ADMP401 microphones. Press Ctrl+C to stop.\n");

    int samples1[WINDOW_SAMPLES];
    int samples2[WINDOW_SAMPLES];

    while (running) {
        /* Sample mic1 */
        for (int i = 0; i < WINDOW_SAMPLES; i++) {
            int v = read_mcp3008(spi_handle, 0);
            if (v < 0) {
                fprintf(stderr, "Failed to read mic1 sample %d\n", i);
                running = 0;
                break;
            }
            samples1[i] = v;
        }
        if (!running) break;

        /* Sample mic2 */
        for (int i = 0; i < WINDOW_SAMPLES; i++) {
            int v = read_mcp3008(spi_handle, 1);
            if (v < 0) {
                fprintf(stderr, "Failed to read mic2 sample %d\n", i);
                running = 0;
                break;
            }
            samples2[i] = v;
        }
        if (!running) break;

        float rms1 = calculate_rms(samples1, WINDOW_SAMPLES);
        float rms2 = calculate_rms(samples2, WINDOW_SAMPLES);

        log_data(fp, rms1, rms2);

        /* LED control */
        if (rms1 > HIGH_THRESHOLD || rms2 > HIGH_THRESHOLD) {
            gpioWrite(LED_PIN, 1);
            gpioDelay(LED_ON_MS * 1000);
            gpioWrite(LED_PIN, 0);
        }

        gpioDelay(SAMPLE_RATE_MS * 1000);
    }

    /* --- Cleanup --- */
    gpioWrite(LED_PIN, 0);
    fclose(fp);
    spiClose(spi_handle);
    gpioTerminate();

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

