/*
 * Raspberry Pi 4 Model B — MLX91204 Hall-effect current sensor via ADS1115 ADC
 *
 * Hardware:
 *   - ADS1115 on I2C bus 1 (SDA = GPIO2 BCM, SCL = GPIO3 BCM)
 *   - MLX91204 analog output connected to ADS1115 A0 single-ended input
 *   - Warning LED on GPIO17 BCM
 *
 * Build:  gcc -O2 -Wall -o mlx91204 mlx91204.c -lm
 * Run:    sudo ./mlx91204
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- ADS1115 register definitions (verified against datasheet) ---- */
#define ADS1115_REG_CONVERSION  0x00
#define ADS1115_REG_CONFIG      0x01

/* Config register bit masks */
#define ADS1115_CFG_OS_BEGIN    (1 << 15)   /* Write 1 to begin a single conversion */
#define ADS1115_CFG_MUX_A0     (0x04 << 12) /* AIN0 single-ended (MUX[2:0]=100) */
#define ADS1115_CFG_PGA_4_096V (0x01 << 9)  /* PGA = ±4.096 V (FS = 1 bit) */
#define ADS1115_CFG_MODE_SS   (0x00 << 8)  /* Single-shot mode */
#define ADS1115_CFG_DR_128SPS (0x04 << 5)  /* 128 SPS (DR[2:0]=100) */
#define ADS1115_CFG_CQUE_NONE (0x03 << 0)  /* Disable comparator (CQUE[1:0]=11) */

/* ---- Configuration constants ---- */
#define I2C_BUS        "/dev/i2c-1"
#define ADS1115_ADDR   0x48
#define LED_GPIO       17
#define BUFFER_SIZE    100
#define SAMPLE_RATE_HZ 10
#define THRESHOLD_A    50.0f
#define PGA_VREF       4.096f
#define ADC_MAX        32767.0f   /* 16-bit signed, single-ended positive */

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static int g_led_fd  = -1;

/* ---- Circular buffer ---- */
typedef struct {
    float buffer[BUFFER_SIZE];
    int   head;
    int   count;
} CircularBuffer;

static void cb_init(CircularBuffer *cb) {
    cb->head  = 0;
    cb->count = 0;
    memset(cb->buffer, 0, sizeof(cb->buffer));
}

static void cb_push(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
}

static float cb_average(const CircularBuffer *cb) {
    if (cb->count == 0) return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < cb->count; i++)
        sum += cb->buffer[i];
    return sum / (float)cb->count;
}

/* ---- I2C helpers ---- */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *out) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

/* ---- ADS1115 driver ---- */
static int ads1115_init(int fd) {
    /* Config: single-shot, AIN0 single-ended, ±4.096 V, 128 SPS, no comparator */
    uint16_t cfg = ADS1115_CFG_OS_BEGIN | ADS1115_CFG_MUX_A0 |
                   ADS1115_CFG_PGA_4_096V | ADS1115_CFG_MODE_SS |
                   ADS1115_CFG_DR_128SPS | ADS1115_CFG_CQUE_NONE;
    uint8_t cfg_buf[3] = {
        ADS1115_REG_CONFIG,
        (uint8_t)(cfg >> 8),
        (uint8_t)(cfg & 0xFF)
    };
    if (write(fd, cfg_buf, 3) != 3) {
        fprintf(stderr, "ADS1115 config write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int ads1115_read(int fd, int16_t *raw) {
    /* Trigger a single conversion */
    if (i2c_write_reg8(fd, ADS1115_REG_CONFIG,
                       ADS1115_CFG_OS_BEGIN | ADS1115_CFG_MUX_A0 |
                       ADS1115_CFG_PGA_4_096V | ADS1115_CFG_MODE_SS |
                       ADS1115_CFG_DR_128SPS | ADS1115_CFG_CQUE_NONE) < 0)
        return -1;

    /* Wait for conversion to complete (~8 ms at 128 SPS) */
    usleep(10000);

    /* Poll OS bit (bit 15) until it reads 1 */
    for (int i = 0; i < 20; i++) {
        int16_t cfg;
        if (i2c_read_reg16(fd, ADS1115_REG_CONFIG, &cfg) < 0)
            return -1;
        if (cfg & (1 << 15))
            break;
        usleep(5000);
    }

    if (!(cfg & (1 << 15))) {
        fprintf(stderr, "ADS1115 conversion timeout\n");
        return -1;
    }

    /* Read conversion result */
    if (i2c_read_reg16(fd, ADS1115_REG_CONVERSION, raw) < 0)
        return -1;

    /* Clear OS bit for next conversion */
    if (i2c_write_reg8(fd, ADS1115_REG_CONFIG,
                       ADS1115_CFG_OS_BEGIN | ADS1115_CFG_MUX_A0 |
                       ADS1115_CFG_PGA_4_096V | ADS1115_CFG_MODE_SS |
                       ADS1115_CFG_DR_128SPS | ADS1115_CFG_CQUE_NONE) < 0)
        return -1;

    return 0;
}

/* ---- LED ---- */
static int led_init(void) {
    int fd = open("/dev/gpiochip4", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open /dev/gpiochip4 failed: %s\n", strerror(errno));
        return -1;
    }
    if (ioctl(fd, GPIO_GET_LINE, &LED_GPIO) < 0) {
        fprintf(stderr, "GPIO_GET_LINE failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    if (ioctl(fd, GPIO_SET_DIRECTION, &LED_GPIO) < 0) {
        fprintf(stderr, "GPIO_SET_DIRECTION failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    if (ioctl(fd, GPIO_SET_OUTPUT, &LED_GPIO) < 0) {
        fprintf(stderr, "GPIO_SET_OUTPUT failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static void led_set(int fd, int on) {
    if (ioctl(fd, GPIO_SET_VALUE, &LED_GPIO) < 0)
        fprintf(stderr, "GPIO_SET_VALUE failed: %s\n", strerror(errno));
    if (on) ioctl(fd, GPIO_SET_VALUE, &LED_GPIO);
}

static void led_off(int fd) {
    led_set(fd, 0);
}

/* ---- Signal handler ---- */
static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* ---- Main ---- */
int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open %s failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n",
                ADS1115_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Initialize ADS1115 */
    if (ads1115_init(g_i2c_fd) < 0) {
        fprintf(stderr, "ADS1115 initialization failed (sensor absent or bus error)\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Initialize LED GPIO */
    g_led_fd = led_init();
    if (g_led_fd < 0) {
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    CircularBuffer buffer;
    cb_init(&buffer);

    printf("MLX91204 current monitoring started. Sampling at %d Hz.\n",
           SAMPLE_RATE_HZ);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        int16_t raw;
        if (ads1115_read(g_i2c_fd, &raw) < 0) {
            fprintf(stderr, "ADC read error; retrying next cycle\n");
            usleep(100000);
            continue;
        }

        /* Convert raw ADC value to current (PGA = ±4.096 V) */
        float current = (float)raw * PGA_VREF / ADC_MAX;

        cb_push(&buffer, current);

        float avg = cb_average(&buffer);
        int led_on = (avg > THRESHOLD_A) ? 1 : 0;

        if (led_on) {
            led_set(g_led_fd, 1);
            printf("WARNING: Average current %.2f A exceeds threshold %.2f A\n",
                   avg, THRESHOLD_A);
        } else {
            led_set(g_led_fd, 0);
        }

        /* Sleep for the remainder of the 10 Hz sample period */
        usleep(1000000 / SAMPLE_RATE_HZ);
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    led_off(g_led_fd);
    close(g_led_fd);
    close(g_i2c_fd);
    printf("Done.\n");
    return EXIT_SUCCESS;
}

