    }

    /* Initialize ADS1115 */
    if (ads1115_init(g_i2c_fd) < 0) {
        fprintf(stderr, "ADS1115 initialization failed (sensor absent or bus error)\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Initialize LED GPIO */
    g_led_fd = led_init();
    if (g_led_fd < 0) {
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    CircularBuffer buffer;
    cb_init(&buffer);

    printf("MLX91204 current monitoring started. Sampling at %d Hz.\n",
           SAMPLE_RATE_HZ);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        int16_t raw;
        if (ads1115_read(g_i2c_fd, &raw) < 0) {
