/*
 * TCS34725 color sensor logger for Raspberry Pi 4 Model B
 * Uses pigpio for I2C communication.
 *
 * Wiring:
 *   TCS34725 SDA -> GPIO 2 (I2C bus 1 SDA)
 *   TCS34725 SCL -> GPIO 3 (I2C bus 1 SCL)
 *   TCS34725 VDD -> 3.3 V
 *   TCS34725 GND -> GND
 *   TCS34725 A0  -> (not connected)
 *
 * Build: gcc -Wall -Wextra -O2 -o color_logger color_logger.c -lpigpio -lrt
 * Run:   sudo ./color_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- TCS34725 constants ---- */
#define TCS34725_I2C_BUS        1
#define TCS34725_I2C_ADDR       0x29

#define TCS34725_COMMAND_BIT    0x80
#define TCS34725_ENABLE         0x00
#define TCS34725_ATIME          0x01
#define TCS34725_CONTROL        0x0F
#define TCS34725_ID             0x12
#define TCS34725_CDATA          0x14
#define TCS34725_RDATA          0x16
#define TCS34725_GDATA          0x18
#define TCS34725_BDATA          0x1A

#define TCS34725_ENABLE_PON     0x01
#define TCS34725_ENABLE_AEN     0x02

#define TCS34725_ID_VALUE       0x44

/* ---- Globals ---- */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

/* ---- I2C helpers ---- */
static int i2c_write_byte(uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(i2c_handle, reg | TCS34725_COMMAND_BIT, value);
    if (rc < 0) {
        fprintf(stderr, "Warning: i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
    }
    return rc;
}

static int i2c_read_byte(uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(i2c_handle, reg | TCS34725_COMMAND_BIT);
    if (rc < 0) {
        fprintf(stderr, "Warning: i2cReadByteData(reg=0x%02X) failed: %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int i2c_read_word(uint8_t reg, uint16_t *value)
{
    int rc = i2cReadWordData(i2c_handle, reg | TCS34725_COMMAND_BIT);
    if (rc < 0) {
        fprintf(stderr, "Warning: i2cReadWordData(reg=0x%02X) failed: %d\n", reg, rc);
        return -1;
    }
    *value = (uint16_t)rc;
    return 0;
}

/* ---- Sensor initialization ---- */
static int tcs34725_init(void)
{
    uint8_t id = 0;

    /* Verify sensor identity */
    if (i2c_read_byte(TCS34725_ID, &id) < 0) {
        fprintf(stderr, "Error: cannot read TCS34725 ID register.\n");
        return -1;
    }
    if (id != TCS34725_ID_VALUE) {
        fprintf(stderr, "Error: unexpected TCS34725 ID 0x%02X (expected 0x%02X).\n",
                id, TCS34725_ID_VALUE);
        return -1;
    }

    /* Power on */
    if (i2c_write_byte(TCS34725_ENABLE, TCS34725_ENABLE_PON) < 0)
        return -1;
    gpioDelay(3000); /* 3 ms power-on delay */

    /* Enable RGBC ADC */
    if (i2c_write_byte(TCS34725_ENABLE, TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN) < 0)
        return -1;

    /* Set integration time (ATIME) to 2.4 ms (0x00) */
    if (i2c_write_byte(TCS34725_ATIME, 0x00) < 0)
        return -1;

    /* Set control register: 16-bit resolution, no high-time, no fault queue */
    if (i2c_write_byte(TCS34725_CONTROL, 0x00) < 0)
        return -1;

    return 0;
}

/* ---- Read color data ---- */
static int tcs34725_read_color(uint16_t *clear, uint16_t *red,
                               uint16_t *green, uint16_t *blue)
{
    if (i2c_read_word(TCS34725_CDATA, clear) < 0) return -1;
    if (i2c_read_word(TCS34725_RDATA, red)   < 0) return -1;
    if (i2c_read_word(TCS34725_GDATA, green) < 0) return -1;
    if (i2c_read_word(TCS34725_BDATA, blue)  < 0) return -1;
    return 0;
}

/* ---- Logging ---- */
static void log_color_data(uint16_t clear, uint16_t red,
                           uint16_t green, uint16_t blue)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, clear, red, green, blue);
    fflush(log_file);
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
