    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                TCS34725_I2C_BUS, TCS34725_I2C_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (tcs34725_init() < 0) {
        fprintf(stderr, "Error: TCS34725 initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen("color_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: cannot open color_log.csv for appending.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Clear,Red,Green,Blue\n");
        fflush(log_file);
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("TCS34725 color logger started. Logging to color_log.csv every 1 s.\n");
    printf("Press Ctrl+C to stop.\n");

    uint16_t clear, red, green, blue;
    int consecutive_errors = 0;

    while (program_running) {
        if (tcs34725_read_color(&clear, &red, &green, &blue) == 0) {
            log_color_data(clear, red, green, blue);
            consecutive_errors = 0;
        } else {
            consecutive_errors++;
            fprintf(stderr, "Error: failed to read color data (consecutive: %d).\n",
                    consecutive_errors);
            if (consecutive_errors >= 3) {
                fprintf(stderr, "Error: three consecutive I2C failures. Exiting.\n");
                break;
            }
        }

        /* Sleep 1 s without blocking the signal */
        for (int i = 0; i < 10 && program_running; i++)
            gpioDelay(100000); /* 100 ms */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
