/*
 * Raspberry Pi Zero W - Dual Grove Moisture Sensor Logger
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3V (Pin 1)
 *   MCP3008 VREF -> 3.3V (Pin 1)
 *   MCP3008 AGND -> GND  (Pin 6)
 *   MCP3008 DGND -> GND  (Pin 6)
 *   MCP3008 CLK  -> GPIO11 (BCM 11, SCLK)
 *   MCP3008 DOUT -> GPIO9  (BCM 9,  MISO)
 *   MCP3008 DIN  -> GPIO10 (BCM 10, MOSI)
 *   MCP3008 CS   -> GPIO8  (BCM 8,  CE0)
 *   Sensor 1     -> MCP3008 CH0
 *   Sensor 2     -> MCP3008 CH1
 *
 * Build: gcc -O2 -Wall -o moisture_logger moisture_logger.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_BITS         8
#define SPI_MODE         0

#define SENSOR1_CHANNEL 0
#define SENSOR2_CHANNEL 1

#define LOG_FILE        "moisture_log.csv"
#define SAMPLE_INTERVAL 5

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a single-ended channel from the MCP3008.
 * Returns 0-1023 on success, -1 on SPI transfer failure.
 */
static int read_mcp3008(int fd, uint8_t channel)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid channel %u\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI protocol (Mode 0, MSB-first):
     *   Byte 0: 0x01  (Start bit)
     *   Byte 1: (0x08 | channel) << 4  (Single-ended + channel select)
     *   Byte 2: 0x00  (Don't care, clocks out low 2 bits)
     *
     * Response:
     *   rx[1] bits 1:0  -> result bits 9:8
     *   rx[2]          -> result bits 7:0
     */
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = sizeof(tx);
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static void log_data(FILE *fp, int moisture1, int moisture2)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }

    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%d,%d\n", timestamp, moisture1, moisture2);
    fflush(fp);
}

int main(void)
{
    int spi_fd = -1;
    FILE *fp = NULL;
    int ret = EXIT_FAILURE;

    /* --- Signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* --- Open SPI device --- */
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", SPI_DEVICE, strerror(errno));
        goto cleanup;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        goto cleanup;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        goto cleanup;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* --- Open log file --- */
    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    /* Write header if file is empty */
    if (ftell(fp) == 0) {
        fprintf(fp, "Timestamp,Moisture1,Moisture2\n");
        fflush(fp);
    }

    printf("Logging moisture data to %s every %d seconds. Press Ctrl+C to stop.\n",
           LOG_FILE, SAMPLE_INTERVAL);

    /* --- Main sampling loop --- */
    while (g_running) {
        int moisture1 = read_mcp3008(spi_fd, SENSOR1_CHANNEL);
        int moisture2 = read_mcp3008(spi_fd, SENSOR2_CHANNEL);

        if (moisture1 < 0) {
            fprintf(stderr, "Error reading sensor 1 (channel %d)\n", SENSOR1_CHANNEL);
        }
        if (moisture2 < 0) {
            fprintf(stderr, "Error reading sensor 2 (channel %d)\n", SENSOR2_CHANNEL);
        }

        if (moisture1 >= 0 && moisture2 >= 0) {
            log_data(fp, moisture1, moisture2);
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down cleanly.\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (fp != NULL) {
        fclose(fp);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    return ret;
}

