/*
 * MLX91211 Current Sensor Monitor via MCP3008 ADC on Raspberry Pi 4
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V
 *   MCP3008 VREF -> 3.3 V
 *   MCP3008 AGND -> GND
 *   MCP3008 DGND -> GND
 *   MCP3008 CLK  -> GPIO11 (BCM)
 *   MCP3008 DOUT -> GPIO9  (BCM)
 *   MCP3008 DIN  -> GPIO10 (BCM)
 *   MCP3008 CS   -> GPIO8  (BCM)
 *   MCP3008 CH0  -> MLX91211 analog output
 *   Motor shutdown -> GPIO17 (BCM)
 *
 * Build: gcc -O2 -Wall -o current_monitor current_monitor.c -lpigpio -lrt
 * Run:   sudo ./current_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_BITS        8
#define SPI_MODE        0

#define ADC_CHANNEL     0
#define ADC_MAX_VALUE   1023
#define ADC_VREF        3.3f

#define MOTOR_SHUTDOWN_PIN 17
#define OVERCURRENT_THRESHOLD 10.0f
#define SAMPLE_INTERVAL_SEC 1
#define MAX_SPI_RETRIES 3

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int spi_init(void)
{
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n",
                SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI max speed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

static int read_adc(int fd, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read sequence (3 bytes):
     *   tx[0] = 0x01  (start bit)
     *   tx[1] = (0x08 | channel) << 4  (single-ended + channel)
     *   tx[2] = 0x00  (don't care, clocks out low 2 bits)
     * Result: 10-bit value in rx[1] (low 2 bits) and rx[2] (8 bits).
     */
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = 3;
    tr.speed_hz = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs = 0;
    tr.cs_change = 0;

    for (int attempt = 1; attempt <= MAX_SPI_RETRIES; attempt++) {
        if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) >= 0) {
            int value = ((rx[1] & 0x03) << 8) | rx[2];
            return value;
        }
        fprintf(stderr, "SPI transfer failed (attempt %d/%d): %s\n",
                attempt, MAX_SPI_RETRIES, strerror(errno));
        if (attempt < MAX_SPI_RETRIES)
            gpioDelay(100000); /* 100 ms backoff */
    }

    fprintf(stderr, "SPI transfer failed after %d attempts\n", MAX_SPI_RETRIES);
    return -1;
}

static float adc_to_current(int adc_value)
{
    return ((float)adc_value / (float)ADC_MAX_VALUE) * ADC_VREF * 1000.0f;
}

static int log_current(float current)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }

    if (fprintf(g_log_file, "%s,%.2f\n", timestamp, current) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MOTOR_SHUTDOWN_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", MOTOR_SHUTDOWN_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(MOTOR_SHUTDOWN_PIN, 1) < 0) {
        fprintf(stderr, "Failed to initialize GPIO%d high\n", MOTOR_SHUTDOWN_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_spi_fd = spi_init();
    if (g_spi_fd < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen("current_log.csv", "a+");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error opening current_log.csv: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    if (fseek(g_log_file, 0, SEEK_END) == 0) {
        long file_size = ftell(g_log_file);
        if (file_size == 0) {
            if (fprintf(g_log_file, "Timestamp,Current_A\n") < 0) {
                fprintf(stderr, "Error writing header: %s\n", strerror(errno));
                cleanup();
                return EXIT_FAILURE;
            }
            fflush(g_log_file);
        }
    } else {
        fprintf(stderr, "Error seeking in log file: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Monitoring MLX91211 current sensor on MCP3008 channel %d...\n",
           ADC_CHANNEL);
    printf("Sampling every %d second(s). Press Ctrl+C to exit.\n",
           SAMPLE_INTERVAL_SEC);

    while (g_running) {
        int adc_value = read_adc(g_spi_fd, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read failed; continuing after delay.\n");
            gpioDelay(SAMPLE_INTERVAL_SEC * 1000000);
            continue;
        }

        float current = adc_to_current(adc_value);

        if (log_current(current) < 0) {
            fprintf(stderr, "Logging failed; continuing.\n");
        }

        printf("Current: %.2f A\n", current);

        if (current > OVERCURRENT_THRESHOLD) {
            printf("Overcurrent detected! Shutting down motor.\n");
            if (gpioWrite(MOTOR_SHUTDOWN_PIN, 0) < 0) {
                fprintf(stderr, "Failed to drive GPIO%d low\n", MOTOR_SHUTDOWN_PIN);
            } else {
                gpioDelay(SAMPLE_INTERVAL_SEC * 1000000);
                if (gpioWrite(MOTOR_SHUTDOWN_PIN, 1) < 0) {
                    fprintf(stderr, "Failed to drive GPIO%d high\n", MOTOR_SHUTDOWN_PIN);
                }
            }
        }

        gpioDelay(SAMPLE_INTERVAL_SEC * 1000000);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

