/*
 * MLX90817 pressure logger for Raspberry Pi Zero W
 * I2C bus 1, pressure register 0x00 (kPa)
 * Logs one CSV line per second:  timestamp,pressure_kPa
 * Build:  gcc -O2 -Wall -Wextra -o mlx90817_log mlx90817_log.c
 */
#define _POSIX_C_SOURCE 200809L

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MLX90817_ADDR  0x00
#define PRESSURE_REG   0x00
#define LOG_FILE       "pressure_log.csv"
#define SAMPLE_PERIOD  1          /* seconds */

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/*
 * Open the I2C bus and target the MLX90817.
 * Returns a valid file descriptor (>= 0) on success, or -1 on failure.
 */
static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

/*
 * Read the pressure register (0x00) as a 16-bit big-endian value.
 * Returns 0 on success and stores the pressure in *out_kPa.
 * Returns -1 on I2C read failure.
 */
static int read_pressure(int fd, float *out_kPa)
{
    uint8_t reg = PRESSURE_REG;
    ssize_t w = write(fd, &reg, 1);
    if (w != 1) {
        fprintf(stderr, "I2C write(reg 0x%02X): %s\n",
                reg, w < 0 ? strerror(errno) : "short write");
        return -1;
    }

    uint8_t buf[2];
    ssize_t r = read(fd, buf, sizeof(buf));
    if (r != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C read(reg 0x%02X): %s\n",
                reg, r < 0 ? strerror(errno) : "short read");
        return -1;
    }

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *out_kPa = (float)raw / 1000.0f;
    return 0;
}

static int log_pressure(FILE *fp, float pressure)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time(): %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_utc;
    if (gmtime_r(&now, &tm_utc) == NULL) {
        fprintf(stderr, "gmtime_r() failed\n");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%.2f\n", ts, pressure) < 0) {
        fprintf(stderr, "fprintf() failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush() failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    if (install_signal_handlers() != 0)
        return EXIT_FAILURE;

    int fd = i2c_open(I2C_BUS, MLX90817_ADDR);
    if (fd < 0)
        return EXIT_FAILURE;

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    /* Write header only if file is empty */
    if (fseek(fp, 0, SEEK_END) != 0) {
        fprintf(stderr, "fseek(0): %s\n", strerror(errno));
        fclose(fp);
        close(fd);
        return EXIT_FAILURE;
    }
    long sz = ftell(fp);
    if (sz < 0) {
        fprintf(stderr, "ftell(): %s\n", strerror(errno));
        fclose(fp);
        close(fd);
        return EXIT_FAILURE;
    }
    if (sz == 0) {
        if (fprintf(fp, "timestamp,pressure_kPa\n") < 0 || fflush(fp) != 0) {
            fprintf(stderr, "write(header): %s\n", strerror(errno));
            fclose(fp);
            close(fd);
            return EXIT_FAILURE;
        }
    }

    while (g_running) {
        float pressure;
        if (read_pressure(fd, &pressure) == 0) {
            if (log_pressure(fp, pressure) != 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
        } else {
            fprintf(stderr, "Sensor read failed; continuing.\n");
        }
        sleep(SAMPLE_PERIOD);
    }

    fprintf(stderr, "\nShutting down cleanly...\n");
    if (fclose(fp) != 0)
        fprintf(stderr, "fclose(): %s\n", strerror(errno));
    if (close(fd) != 0)
        fprintf(stderr, "close(fd): %s\n", strerror(errno));
    return EXIT_SUCCESS;
}

