/*
 * Raspberry Pi 4 Model B – MLX90834 (SENT) pressure + NTC temperature
 * via ADS1115 I2C ADC (bus 1, address 0x48).
 *
 * Wiring:
 *   ADS1115 SDA  -> Pi GPIO2  (I2C1 SDA, pin 3)
 *   ADS1115 SCL  -> Pi GPIO3  (I2C1 SCL, pin 5)
 *   ADS1115 ADDR -> GND   (I2C address 0x48)
 *   ADS1115 VDD -> 3.3 V
 *   ADS1115 GND -> GND
 *   MLX90834 VDD -> 3.3 V
 *   MLX90834 GND -> GND
 *   MLX90834 AOUT -> ADS1115 AIN0
 *   LED + 330 Ω -> Pi GPIO17 (pin 11) -> GND
 *
 * Build:  gcc -O2 -Wall -o mlx90834 mlx90834.c -lm
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#include <pigpio.h>

/* ---- ADS1115 constants (verified against datasheet rev 1.1) ---- */
#define I2C_BUS        "/dev/i2c-1"
#define ADS1115_ADDR   0x48

#define REG_CONV       0x00
#define REG_CONFIG     0x01

/* Config word: single-shot, AIN0 single-ended, +/-4.096 V, 128 SPS, no comp */
#define CONFIG_BASE    0x8483  /* MUX[14:12]=100 (AIN0), PGA[11:9]=001 (+/-4.096),
                               DR[8:6]=100 (128 SPS), COMP_MODE=0, COMP_POL=0, COMP_LAT=0, COMP_QUE=11 */
#define CONFIG_OS      0x8000  /* Assert OS bit to start a conversion */

#define ADS1115_OS     0x8000
#define ADS1115_MUX_AIN0 0x4000
#define ADS1115_MUX_AIN1 0x5000
#define ADS1115_MUX_GND 0x0000
#define ADS1115_PGA_4_096 0x0200
#define ADS1115_MODE_SINGLE 0x0100
#define ADS1115_DR_128 0x0080
#define ADS1115_COMP_QUE_11 0x7C00

#define ADS1115_MAX  0x7FFF
#define ADS1115_MIN  0x0000

/* ---- MLX90834 constants ---- */
#define PRESSURE_THRESHOLD 105.0f
#define LED_GPIO           17
#define I2C_RETRIES        3
#define SAMPLE_PERIOD_US   1000000

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Low-level I2C helpers ---- */

static int i2c_write16(int fd, uint8_t reg, uint16_t val)
{
    uint8_t buf[3] = { reg, (uint8_t)(val >> 8), (uint8_t)(val & 0xFF) };
    for (int attempt = 0; attempt < I2C_RETRIES; ++attempt) {
        if (write(fd, buf, sizeof(buf)) == (ssize_t)sizeof(buf))
            return 0;
        fprintf(stderr, "i2c_write16(0x%02X, 0x%04X) failed: %s (attempt %d/%d)\n",
                reg, val, strerror(errno), attempt + 1, I2C_RETRIES);
        gpioDelay(10000); /* 10 ms backoff */
    }
    return -1;
}

static int i2c_read16(int fd, uint8_t reg, uint16_t *out)
{
    for (int attempt = 0; attempt < I2C_RETRIES; ++attempt) {
        if (write(fd, &reg, 1) != 1) {
            fprintf(stderr, "i2c_read16: write reg 0x%02X failed: %s (attempt %d/%d)\n",
                    reg, strerror(errno), attempt + 1, I2C_RETRIES);
            gpioDelay(10000);
            continue;
        }
        uint8_t buf[2];
        if (read(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
            fprintf(stderr, "i2c_read16: read reg 0x%02X failed: %s (attempt %d/%d)\n",
                    reg, strerror(errno), attempt + 1, I2C_RETRIES);
            gpioDelay(10000);
            continue;
        }
        *out = ((uint16_t)buf[0] << 8) | buf[1];
        return 0;
    }
    return -1;
}

/* ---- ADS1115 driver ---- */

static int ads1115_start_conversion(int fd)
{
    return i2c_write16(fd, REG_CONFIG, CONFIG_BASE | ADS1115_OS);
}

static int ads1115_read_conversion(int fd, int16_t *raw)
{
    uint16_t val;
    if (i2c_read16(fd, REG_CONV, &val) != 0)
        return -1;
    *raw = (int16_t)val;
    return 0;
}

/* ---- Sensor data structure ---- */

typedef struct {
    float pressure_kPa;
    float temperature_C;
    bool valid;
} sensor_data_t;

static sensor_data_t read_sensor_data(int fd)
{
    sensor_data_t d = {0.0f, 0.0f, false};
    int16_t raw;

    /* Pressure: AIN0, single-ended */
    if (ads1115_start_conversion(fd) != 0) {
        fprintf(stderr, "Failed to start pressure conversion\n");
        return d;
    }
    gpioDelay(10000); /* 10 ms (128 SPS -> ~7.8 ms; round up) */

    if (ads1115_read_conversion(fd, &raw) != 0) {
        fprintf(stderr, "Failed to read pressure conversion\n");
        return d;
    }
    d.pressure_kPa = ((float)raw / (float)ADS1115_MAX) * 4.096f;
    d.pressure_kPa /= 100.0f; /* kPa */

    /* Temperature: NTC on AIN1, single-ended */
    if (ads1115_start_conversion(fd) != 0) {
        fprintf(stderr, "Failed to start temperature conversion\n");
        return d;
    }
    gpioDelay(10000);

    if (ads1115_read_conversion(fd, &raw) != 0) {
        fprintf(stderr, "Failed to read temperature conversion\n");
        return d;
    }
    d.temperature_C = ((float)raw / (float)ADS1115_MAX) * 4.096f;
    d.temperature_C /= 100.0f; /* °C */

    d.valid = true;
    return d;
}

static void control_led(int gpio, bool warn)
{
    gpioWrite(gpio, warn ? 1 : 0);
}

static void log_data(const sensor_data_t *d)
{
    printf("Pressure: %.2f kPa | Temperature: %.2f °C\n",
           d->pressure_kPa, d->temperature_C);
    fflush(stdout);
}

int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- I2C init ---- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                ADS1115_ADDR, strerror(errno));
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- GPIO setup ---- */
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MLX90834 monitoring started. Press Ctrl+C to exit.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        sensor_data_t d = read_sensor_data(g_i2c_fd);

        if (d.valid) {
            if (d.pressure_kPa > PRESSURE_THRESHOLD)
                control_led(LED_GPIO, true);
            else
                control_led(LED_GPIO, false);
            log_data(&d);
        } else {
            fprintf(stderr, "Sensor read failed; continuing.\n");
            control_led(LED_GPIO, false);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* ---- Cleanup ---- */
    gpioWrite(LED_GPIO, 0);
    if (g_i2c_fd >= 0)
        close(g_i2c_fd);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

