 *   MCP3008 DGND -> GND  (pin 6)
 *   MCP3008 CLK  -> GPIO11 (BCM, SCLK)
 *   MCP3008 DOUT -> GPIO9  (BCM, MISO)
 *   MCP3008 DIN  -> GPIO10 (BCM, MOSI)
 *   MCP3008 CS   -> GPIO8  (BCM, CE0)
 *   MCP3008 CH0  -> MLX91209 analog output
 *   GPIO27       -> motor shutdown (HIGH = shutdown)
 *
 * Build:  gcc -O2 -Wall -o current_monitor current_monitor.c -lpigpio -lrt
 * Run:    sudo ./current_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MOTOR_SHUTDOWN_PIN 27
#define CURRENT_THRESHOLD 10.0f   /* Amperes */
#define ADC_CHANNEL       0       /* MCP3008 single-ended channel 0 */
#define SPI_BAUD          1000000 /* 1 MHz */
#define SPI_FLAGS         0       /* Mode 0, active-low CE */
#define SAMPLE_PERIOD_US  100000 /* 100 ms */
#define LOG_FILE          "current_log.txt"

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;
static int g_spi_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                         */
/* ------------------------------------------------------------------ */
static int gpio_init(void)
{
    if (gpioSetMode(MOTOR_SHUTDOWN_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for pin %d\n", MOTOR_SHUTDOWN_PIN);
        return -1;
    }
    if (gpioWrite(MOTOR_SHUTDOWN_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite failed for pin %d\n", MOTOR_SHUTDOWN_PIN);
        return -1;
    }
    return 0;
}

static void gpio_cleanup(void)
{
    gpioWrite(MOTOR_SHUTDOWN_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* MCP3008 read                                                         */
/* ------------------------------------------------------------------ */
/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care)
 *   tx[2] = 0x00                       (clock out remaining bits)
 * Result: 10-bit value in ((rx[1] & 0x03) << 8) | rx[2]
 */
static int mcp3008_read(int handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: spiXfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Error: ADC value out of range: %d\n", adc_value);
        return -1;
    }
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Current conversion                                                    */
/* ------------------------------------------------------------------ */
/*
 * MLX91209 (analog output) is assumed to be a voltage proportional to
 * current.  A 3.3 V reference maps to 3.3 V / 1023 counts = 0.003255 V/count.
 * Current (A) = (V / 0.003255) * 1000.
 */
static float adc_to_current(int adc_value)
{
    if (adc_value < 0 || adc_value > 1023) {
        return 0.0f;
    }
    float voltage = (float)adc_value * (3.3f / 1023.0f);
    return (voltage / 0.003255f) * 1000.0f;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_current(float current)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return -1;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return -1;
    }

    if (fprintf(g_log_fp, "%s, Current: %.2f A\n", timestamp, current) < 0) {
        fprintf(stderr, "Error: fprintf to log failed\n");
        return -1;
    }
    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "Error: fflush failed\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Shutdown logic                                                       */
/* ------------------------------------------------------------------ */
static void shutdown_motor(void)
{
    if (gpioWrite(MOTOR_SHUTDOWN_PIN, 1) < 0) {
        fprintf(stderr, "Warning: failed to set shutdown pin HIGH\n");
    }
    printf("OVERCURRENT DETECTED! Shutting down motor.\n");
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpio_cleanup();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- GPIO init --- */
    if (gpio_init() < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- SPI init --- */
    g_spi_handle = spiOpen(0, SPI_BAUD, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (handle %d)\n", g_spi_handle);
        gpio_cleanup();
        return EXIT_FAILURE;
    }

    /* --- Log file --- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s'\n", LOG_FILE);
        spiClose(g_spi_handle);
        gpio_cleanup();
        return EXIT_FAILURE;
    }

    /* --- Signals --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction failed; continuing without signal handlers\n");
    }

    printf("Monitoring current on MCP3008 channel %d. Press Ctrl+C to exit.\n",
           ADC_CHANNEL);

    /* --- Main loop --- */
    while (g_running) {
        int adc_value = mcp3008_read(g_spi_handle, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: ADC read failed; retrying in 1 s\n");
            gpioDelay(1000000);
            continue;
        }

        float current = adc_to_current(adc_value);

        if (log_current(current) < 0) {
            fprintf(stderr, "Error: logging failed; continuing\n");
        }

        if (current > CURRENT_THRESHOLD) {
            shutdown_motor();
            break;
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    cleanup();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

