        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    int spi_fd = spi_init();
    if (spi_fd < 0) {
        return 1;
    }

    printf("Methane monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_adc(spi_fd, ADC_CHANNEL);
        if (adc_value < 0) {
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        double methane_ppm = calculate_methane_ppm(adc_value);
        if (methane_ppm < 0) {
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        log_data(methane_ppm);
        check_leak(methane_ppm);

        sleep(SAMPLE_INTERVAL);
    }

    close(spi_fd);
    printf("Methane monitoring stopped.\n");
    return 0;
}

