/*
 * MLX90830 Pressure Sensor Reader via ADS1115 ADC on Raspberry Pi 4 Model B
 *
 * Wiring:
 *   ADS1115 SDA -> GPIO2 (BCM)
 *   ADS1115 SCL -> GPIO3 (BCM)
 *   ADS1115 ADDR -> GND  (I2C address 0x48)
 *   ADS1115 VDD -> 3.3 V
 *   ADS1115 GND -> GND
 *   MLX90830 VOUT -> ADS1115 AIN0
 *   MLX90830 GND -> GND
 *
 * Build: gcc -O2 -Wall -o pressure_logger pressure_logger.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <math.h>
#include <pigpio.h>

/* ---- ADS1115 I2C configuration ---- */
#define I2C_BUS        1
#define I2C_ADDR       0x48

/* ADS1115 register addresses */
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG     0x01

/* Config register bit masks */
#define ADS1115_CFG_OS_BEGIN   0x8000  /* Begin a single conversion */
#define ADS1115_CFG_MUX_AIN0   0x4000  /* AIN0 single-ended */
#define ADS1115_CFG_PGA_4V   0x0200  /* PGA = 4.096 V (default) */
#define ADS1115_CFG_MODE_CONT 0x0000  /* Continuous conversion mode */
#define ADS1115_CFG_DR_128   0x0080  /* 128 SPS */
#define ADS1115_CFG_CQUE_NONE 0x0003  /* Disable comparator */

/* ---- MLX90830 pressure range ---- */
#define MIN_PRESSURE_KPA 0.0f
#define MAX_PRESSURE_KPA 100.0f

/* ---- Sampling ---- */
#define SAMPLE_RATE_HZ 1
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit value to an ADS1115 register.                        */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int ads1115_write_reg(int handle, uint8_t reg, uint16_t value)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)(value >> 8);
    buf[2] = (char)(value & 0xFF);

    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "i2cWriteDevice failed (reg 0x%02X): %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit value from an ADS1115 register.                       */
/* Returns 0 on success and stores the value in *out; -1 on failure.   */
/* ------------------------------------------------------------------ */
static int ads1115_read_reg(int handle, uint8_t reg, uint16_t *out)
{
    char buf[2];

    if (i2cWriteDevice(handle, (char *)&reg, 1) != 1) {
        fprintf(stderr, "i2cWriteDevice (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "i2cReadDevice failed (reg 0x%02X): %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Trigger a conversion and read the raw ADC value.                   */
/* Returns 0 on success and stores the signed 16-bit value in *raw; -1 on failure. */
/* ------------------------------------------------------------------ */
static int ads1115_read_raw(int handle, int16_t *raw)
{
    uint16_t cfg;
    uint16_t conv;

    /* Build config: begin single conversion, mux AIN0, PGA 4.096 V, 128 SPS */
    cfg = ADS1115_CFG_OS_BEGIN | ADS1115_CFG_MUX_AIN0 |
         ADS1115_CFG_PGA_4V | ADS1115_CFG_MODE_CONT |
         ADS1115_CFG_DR_128 | ADS1115_CFG_CQUE_NONE;

    if (ads1115_write_reg(handle, ADS1115_REG_CONFIG, cfg) != 0)
        return -1;

    /* Wait for conversion to complete (~8 ms at 128 SPS) */
    gpioDelay(10000);

    if (ads1115_read_reg(handle, ADS1115_REG_CONFIG, &cfg) != 0)
        return -1;

    /* Verify OS bit is set (bit 15) */
    if (!(cfg & 0x8000)) {
        fprintf(stderr, "ADS1115 conversion not complete (OS=0x%04X)\n", cfg);
        return -1;
    }

    if (ads1115_read_reg(handle, ADS1115_REG_CONVERSION, &conv) != 0)
        return -1;

    *raw = (int16_t)conv;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Convert raw ADC value to pressure in kPa.                           */
/* MLX90830 is an analog sensor; the ADS1115 provides a digital     */
/* reading proportional to the voltage.  The conversion below assumes */
/* a known sensor resistance and supply voltage.                      */
/* ------------------------------------------------------------------ */
static float raw_to_pressure_kpa(int16_t raw)
{
    /* PGA = 4.096 V -> 1 bit = 125 µV */
    const float v_per_bit = 0.000125f;

    /* Sensor voltage at 0 kPa (assumed) */
    const float v0 = 0.0f;

    /* Linear approximation: V = v0 + raw * v_per_bit */
    float v = v0 + (float)raw * v_per_bit;

    /* Convert voltage to pressure (kPa) */
    return v * 100.0f;  /* MLX90830 output is proportional to voltage */
}

/* ------------------------------------------------------------------ */
static int validate_pressure(float pressure)
{
    return (pressure >= MIN_PRESSURE_KPA && pressure <= MAX_PRESSURE_KPA);
}

/* ------------------------------------------------------------------ */
static int log_pressure(float pressure)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    if (fprintf(g_log_file, "%s, %.2f kPa\n", timestamp, pressure) < 0) {
        fprintf(stderr, "fprintf to log file failed: %s\n", strerror(errno));
        return -1;
    }
    fflush(g_log_file);
    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    int16_t raw;
    float pressure;
    int consecutive_errors = 0;

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (bus %d, addr 0x%02X): %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_file = fopen("pressure_log.txt", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "fopen pressure_log.txt failed: %s\n", strerror(errno));
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Write CSV header if file is empty ---- */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,pressure_kPa\n");
        fflush(g_log_file);
    }

    /* ---- Install signal handler ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Pressure monitoring started. Press Ctrl-C to exit.\n");

    /* ---- Main sampling loop ---- */
    while (g_running) {
        if (ads1115_read_raw(g_i2c_handle, &raw) != 0) {
            consecutive_errors++;
            fprintf(stderr, "ADC read error (consecutive: %d)\n", consecutive_errors);
            if (consecutive_errors >= 10) {
                fprintf(stderr, "Too many consecutive errors; aborting.\n");
                break;
            }
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        consecutive_errors = 0;
        pressure = raw_to_pressure_kpa(raw);

        if (validate_pressure(pressure)) {
            if (log_pressure(pressure) != 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
        } else {
            fprintf(stderr, "Pressure out of range: %.2f kPa\n", pressure);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

