/*
 * Raspberry Pi 3 Model B+ - Honeywell HIH-4602-A Humidity Sensor Logger
 *
 * Hardware:
 *   - MCP3208 12-bit ADC on SPI0 (CE0 = GPIO8, BCM)
 *   - HIH-4602-A analog output connected to MCP3208 channel 0
 *
 * Build: gcc -Wall -Wextra -O2 -o humidity_logger humidity_logger.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_BITS        8
#define SPI_MODE        SPI_MODE_0

#define ADC_CHANNEL     0
#define ADC_MAX_VALUE   4095
#define ADC_RESOLUTION  12

#define HUMIDITY_THRESHOLD 80.0f
#define LOG_FILE          "humidity_log.txt"
#define EMAIL_RECIPIENT   "recipient@example.com"
#define EMAIL_SUBJECT     "Humidity Alert"
#define EMAIL_BODY        "Humidity exceeded threshold."

#define SAMPLE_INTERVAL_S 5

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * MCP3208 SPI protocol (Mode 0, MSB first):
 *   Byte 0: Start bit (0x01)
 *   Byte 1: SGL/DIFF=1 (single-ended) + D2 D1 D0 (channel) + don't care
 *   Byte 2: Don't care
 *
 * Response:
 *   Byte 1: bits 7-6 undefined, bit 5 undefined, bits 4-0 = 2 MSBs of result
 *   Byte 2: bits 7-6 undefined, bits 5-0 = 6 LSBs of result
 */
static int read_adc(int spi_fd, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {
        0x01,
        (unsigned char)((0x08 | channel) << 4),
        0x00
    };
    unsigned char rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
        .len           = 3,
        .speed_hz      = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs   = 0,
        .cs_change     = 0,
        .tx_nbits      = 0,
        .rx_nbits      = 0,
        .pad           = 0
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    int value = ((rx[1] & 0x0F) << 8) | rx[2];
    return value;
}

static float calculate_humidity(int adc_value)
{
    if (adc_value < 0) return -1.0f;
    if (adc_value > ADC_MAX_VALUE) adc_value = ADC_MAX_VALUE;

    float humidity = ((float)adc_value / (float)ADC_MAX_VALUE) * 100.0f;
    if (humidity < 0.0f) humidity = 0.0f;
    if (humidity > 100.0f) humidity = 100.0f;
    return humidity;
}

static float calculate_temperature(int adc_value)
{
    if (adc_value < 0) return -1.0f;
    if (adc_value > ADC_MAX_VALUE) adc_value = ADC_MAX_VALUE;

    float voltage = ((float)adc_value / (float)ADC_MAX_VALUE) * 3.3f;
    float resistance = (3.3f - voltage) / voltage;
    float temp = 25.0f + (100.0f / 115.0f) * (1.0f - powf(resistance, 1.0f / 3.0f));
    return temp;
}

static int log_data(float humidity, float temperature)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Failed to open log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        perror("localtime_r failed");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%.2f,%.2f\n", timestamp, humidity, temperature) < 0) {
        perror("Failed to write to log file");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("Failed to close log file");
        return -1;
    }

    return 0;
}

static int send_email_alert(float humidity)
{
    FILE *fp = popen("ssmtp " EMAIL_RECIPIENT, "w");
    if (!fp) {
        perror("Failed to open ssmtp pipe");
        return -1;
    }

    fprintf(fp, "To: %s\n", EMAIL_RECIPIENT);
    fprintf(fp, "Subject: %s\n", EMAIL_SUBJECT);
    fprintf(fp, "\n");
    fprintf(fp, "%s\n", EMAIL_BODY);

    if (pclose(fp) == -1) {
        perror("Failed to close ssmtp pipe");
        return -1;
    }

    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT) failed");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM) failed");
        return EXIT_FAILURE;
    }

    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return EXIT_FAILURE;
    }

    unsigned char mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    unsigned char bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    unsigned int speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI max speed");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    printf("Humidity sensor logging started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int adc_value = read_adc(spi_fd, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read failed, retrying in %d seconds...\n", SAMPLE_INTERVAL_S);
            sleep(SAMPLE_INTERVAL_S);
            continue;
        }

        float humidity = calculate_humidity(adc_value);
        float temperature = calculate_temperature(adc_value);

        if (log_data(humidity, temperature) != 0) {
            fprintf(stderr, "Failed to log data.\n");
        }

        if (humidity > HUMIDITY_THRESHOLD) {
            printf("Humidity alert! Humidity: %.2f%%, Temperature: %.2f°C\n", humidity, temperature);
            if (send_email_alert(humidity) != 0) {
                fprintf(stderr, "Failed to send email alert.\n");
            }
        }

        sleep(SAMPLE_INTERVAL_S);
    }

    printf("\nExiting gracefully...\n");
    close(spi_fd);
    return EXIT_SUCCESS;
}

