/*
 * TMP36 temperature logger via MCP3208 ADC on Raspberry Pi 5.
 *
 * Wiring:
 *   TMP36 VCC  -> 3.3 V (pin 1)
 *   TMP36 GND  -> GND   (pin 9)
 *   TMP36 OUT  -> MCP3208 CH0 (pin 1)
 *   MCP3208 VDD -> 3.3 V
 *   MCP3208 VREF-> 3.3 V
 *   MCP3208 CH0 -> TMP36 OUT
 *   MCP3208 CS   -> GPIO8  (BCM 8, gpiochip4)
 *   MCP3208 SCLK -> GPIO11 (BCM 11)
 *   MCP3208 DIN  -> GPIO10 (BCM 10)
 *   MCP3208 DOUT -> GPIO9  (BCM 9)
 *   MCP3208 CS/SHDN -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o tmp36_log tmp36_log.c -lpigpio -lrt
 * Run:    sudo ./tmp36_log
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U   /* 1 MHz */
#define SPI_BITS        8
#define SPI_MODE        0

#define ADC_CHANNEL     0          /* MCP3208 CH0 */
#define ADC_MAX_VALUE   4095        /* 12-bit */
#define ADC_VREF        3.3f       /* MCP3208 VDD/VREF tied to 3.3 V */

#define LOG_FILE        "temperature_log.csv"
#define SAMPLE_PERIOD_US 1000000U  /* 1 second */

#define MIN_TEMP_C      (-40.0f)
#define MAX_TEMP_C      125.0f

static volatile sig_atomic_t g_running = 1;
static int  g_spi_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int spi_init(void)
{
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

/* ------------------------------------------------------------------ */
static int spi_transfer(uint8_t *tx, uint8_t *rx, size_t len)
{
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = len;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int read_adc(uint16_t *value)
{
    uint8_t tx[3] = { 0x01, (uint8_t)(0x80 | (ADC_CHANNEL << 4)), 0x00 };
    uint8_t rx[3] = { 0 };

    if (spi_transfer(tx, rx, sizeof(tx)) < 0)
        return -1;

    *value = ((uint16_t)(rx[1] & 0x0F) << 8) | rx[2];
    return 0;
