    /* MCP3008 single-ended read: start bit, SGL/DIFF=1, D2 D1 D0 */
    uint8_t tx[3] = {
        0x01,
        (uint8_t)((0x08 | channel) << 4),
        0x00
    };
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = 3;
    tr.speed_hz = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs = SPI_DELAY_US;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    /* 10-bit result: low 2 bits of rx[1] << 8 | rx[2] */
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int read_accelerometer(int fd, int *x, int *y, int *z)
{
    int x_raw = mcp3008_read(fd, ADC_CHANNEL_X);
    int y_raw = mcp3008_read(fd, ADC_CHANNEL_Y);
    int z_raw = mcp3008_read(fd, ADC_CHANNEL_Z);

    if (x_raw < 0 || y_raw < 0 || z_raw < 0) {
        return -1;
    }

    *x = x_raw;
    *y = y_raw;
    *z = z_raw;
    return 0;
}

static int log_data(FILE *fp, int x, int y, int z)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%d,%d,%d\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, x, y, z) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int detect_impact(int x, int y, int z, int threshold)
{
    float x_g = (float)x / ADC_RESOLUTION * ADC_VREF;
    float y_g = (float)y / ADC_RESOLUTION * ADC_VREF;
    float z_g = (float)z / ADC_RESOLUTION * ADC_VREF;

    float magnitude = sqrtf(x_g * x_g + y_g * y_g + z_g * z_g);
    return (magnitude > threshold) ? 1 : 0;
}

static int log_impact(FILE *fp)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,IMPACT DETECTED\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    g_spi_fd = spi_init();
    if (g_spi_fd < 0) {
        return 1;
    }

    g_log_fp = fopen(LOG_FILE_NAME, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n",
                LOG_FILE_NAME, strerror(errno));
        cleanup();
        return 1;
    }

    printf("ADXL335 via MCP3008 logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        int x, y, z;
        if (read_accelerometer(g_spi_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "ADC read error, continuing...\n");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        if (log_data(g_log_fp, x, y, z) < 0) {
            fprintf(stderr, "Log write error, continuing...\n");
        }

        if (detect_impact(x, y, z, IMPACT_THRESHOLD)) {
            if (log_impact(g_log_fp) < 0) {
                fprintf(stderr, "Impact log write error.\n");
            }
        }

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return 0;
}

