/*
 * Raspberry Pi Zero W – Si1172 Optical Heart Rate Sensor logger
 *
 * Reads Heart Rate (HR) and SpO₂ from a Si1172‑A30‑GMR on I2C bus 1
 * and logs timestamp, HR (bpm), SpO₂ (%), and an error flag to
 * biometric_log.csv once per second.  The Si1172 requires a proprietary
 * algorithm to convert raw PPG samples to true HR and SpO₂; this program
 * logs the raw 16-bit IR and RED ADC values as proxy values and documents
 * the limitation in comments.
 *
 * Build:  gcc -O2 -Wall -Wextra -o si1172_logger si1172_logger.c -lm
 * Run:    ./si1172_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define I2C_BUS              1
#define SI1172_ADDR          0x60          /* Si1172‑A30‑GMR default I2C address */

/* Si1172 register addresses */
#define SI1172_REG_PART_ID    0x00
#define SI1172_REG_HW_KEY     0x01
#define SI1172_REG_INT_CFG   0x02
#define SI1172_REG_IRQ_ENABLE 0x03
#define SI1172_REG_IRQ_STATUS 0x04
#define SI1172_REG_MEAS_RATE  0x05
#define SI1172_REG_ALS_RATE   0x06
#define SI1172_REG_ALS_IR     0x08
#define SI1172_REG_ALS_RED    0x09
#define SI1172_REG_ALS_VIS    0x0A
#define SI1172_REG_ALS_DATA0  0x0B
#define SI1172_REG_ALS_DATA1  0x0C
#define SI1172_REG_ALS_DATA2  0x0D
#define SI1172_REG_ALS_DATA3  0x0E
#define SI1172_REG_ALS_DATA4  0x0F
#define SI1172_REG_ALS_DATA5  0x10
#define SI1172_REG_ALS_DATA6  0x11
#define SI1172_REG_ALS_DATA7  0x12
#define SI1172_REG_ALS_DATA8  0x13
#define SI1172_REG_ALS_DATA9  0x14
#define SI1172_REG_ALS_DATA10 0x15
#define SI1172_REG_ALS_DATA11 0x16
#define SI1172_REG_ALS_DATA12 0x17
#define SI1172_REG_ALS_DATA13 0x18
#define SI1172_REG_ALS_DATA14 0x19
#define SI1172_REG_ALS_DATA15 0x1A
#define SI1172_REG_ALS_DATA16 0x1B
#define SI1172_REG_ALS_DATA17 0x1C
#define SI1172_REG_ALS_DATA18 0x1D
#define SI1172_REG_ALS_DATA19 0x1E
#define SI1172_REG_ALS_DATA20 0x1F
#define SI1172_REG_ALS_DATA21 0x20
#define SI1172_REG_ALS_DATA22 0x21
#define SI1172_REG_ALS_DATA23 0x22
#define SI1172_REG_ALS_DATA24 0x23
#define SI1172_REG_ALS_DATA25 0x24
#define SI1172_REG_ALS_DATA26 0x25
#define SI1172_REG_ALS_DATA27 0x26
#define SI1172_REG_ALS_DATA28 0x27
#define SI1172_REG_ALS_DATA29 0x28
#define SI1172_REG_ALS_DATA30 0x29
#define SI1172_REG_ALS_DATA31 0x2A
#define SI1172_REG_ALS_DATA32 0x2B
#define SI1172_REG_ALS_DATA33 0x2C
#define SI1172_REG_ALS_DATA34 0x2D
#define SI1172_REG_ALS_DATA35 0x2E
#define SI1172_REG_ALS_DATA36 0x2F
#define SI1172_REG_ALS_DATA37 0x30
#define SI1172_REG_ALS_DATA38 0x31
#define SI1172_REG_ALS_DATA39 0x32
#define SI1172_REG_ALS_DATA40 0x33
#define SI1172_REG_ALS_DATA41 0x34
#define SI1172_REG_ALS_DATA42 0x35
#define SI1172_REG_ALS_DATA43 0x36
#define SI1172_REG_ALS_DATA44 0x37
#define SI1172_REG_ALS_DATA45 0x38
#define SI1172_REG_ALS_DATA46 0x39
#define SI1172_REG_ALS_DATA47 0x3A
#define SI1172_REG_ALS_DATA48 0x3B
#define SI1172_REG_ALS_DATA49 0x3C
#define SI1172_REG_ALS_DATA50 0x3D
#define SI1172_REG_ALS_DATA51 0x3E
#define SI1172_REG_ALS_DATA52 0x3F

#define SI1172_HW_KEY_VAL     0x17          /* recommended unlock value */

/* ------------------------------- Globals --------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* --------------------------- Forward declarations ------------------------- */

static int  si1172_write_reg(uint8_t reg, uint8_t val);
static int  si1172_read_reg(uint8_t reg, uint8_t *val);
static int  si1172_read_block(uint8_t reg, uint8_t *buf, uint32_t len);
static int  si1172_init(void);
static int  si1172_read_ppg(uint16_t *ir, uint16_t *red);
static int  si1172_log_sample(uint32_t ts, uint16_t ir, uint16_t red, int err);
static void signal_handler(int sig);
static void cleanup(void);

/* ------------------------------ Signal handler --------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------ I2C helpers ------------------------------ */

/*
 * Write a single byte to a Si1172 register.
 * Returns 0 on success, -1 on error.
 */
static int si1172_write_reg(uint8_t reg, uint8_t val)
{
    int rc = i2cWriteByteData(g_i2c_handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read a single byte from a Si1172 register.
 * Returns 0 on success, -1 on error.
 */
static int si1172_read_reg(uint8_t reg, uint8_t *val)
{
    int rc = i2cReadByteData(g_i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

/*
 * Read a block of bytes starting at `reg` (auto-increment).
 * Returns 0 on success, -1 on error.
 */
static int si1172_read_block(uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(g_i2c_handle, reg, (char *)buf, len);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadI2CBlockData(reg=0x%02X, len=%u) failed: %s\n",
                reg, len, strerror(errno));
        return -1;
    }
    if ((uint32_t)rc != len) {
        fprintf(stderr, "[WARN] Short read: got %d of %u bytes from reg 0x%02X\n",
                rc, len, reg);
        return -1;
    }
    return 0;
}

/*
 * Initialize the Si1172 sensor.
 * Returns 0 on success, -1 on error.
 */
static int si1172_init(void)
{
    uint8_t part_id = 0;

    /* --- Verify sensor presence --- */
    if (si1172_read_reg(SI1172_REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "[ERROR] Cannot read PART_ID – sensor may be absent or bus error.\n");
        return -1;
    }
    if (part_id != 0x00 && part_id != 0x01) {
        fprintf(stderr, "[WARN] Unexpected PART_ID 0x%02X (expected 0x00 or 0x01). Continuing anyway.\n",
                part_id);
    }

    /* --- Software reset --- */
    if (si1172_write_reg(SI1172_REG_HW_KEY, SI1172_HW_KEY_VAL) != 0)
        return -1;
    gpioDelay(10000);  /* 10 ms settle after unlock */

    /* --- Configure measurement rate (100 ms) --- */
    if (si1172_write_reg(SI1172_REG_MEAS_RATE, 0x0A) != 0)
        return -1;

    /* --- Enable ALS interrupts (optional) --- */
    if (si1172_write_reg(SI1172_REG_INT_CFG, 0x00) != 0)
        return -1;

    /* --- Clear any pending IRQ status --- */
    if (si1172_read_reg(SI1172_REG_IRQ_STATUS, &part_id) != 0)
        return -1;

    return 0;
}

/*
 * Read the 16-bit IR and RED PPG data registers.
 * Returns 0 on success, -1 on error.
 */
static int si1172_read_ppg(uint16_t *ir, uint16_t *red)
{
    uint8_t buf[4];

    if (si1172_read_block(SI1172_REG_ALS_IR, buf, 4) != 0)
        return -1;

    *ir = (uint16_t)((buf[2] << 8) | buf[1]);
    *red = (uint16_t)((buf[3] << 8) | buf[0]);
    return 0;
}

/*
 * Log one sample to the CSV file.
 * Timestamp is a Unix epoch (seconds since 1970).
 * Returns 0 on success, -1 on error.
 */
static int si1172_log_sample(uint32_t ts, uint16_t ir, uint16_t red, int err)
{
    if (fprintf(g_log_file, "%u,%u,%u,%d\n", (unsigned)ts, (unsigned)ir, (unsigned)red, err) < 0) {
        fprintf(stderr, "[ERROR] fprintf to log file failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "[ERROR] fflush of log file failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------- Cleanup --------------------------------- */

static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* --------------------------------- Main ---------------------------------- */

int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus 1 at the Si1172 address --- */
    g_i2c_handle = i2cOpen(I2C_BUS, SI1172_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, SI1172_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Initialize the Si1172 sensor --- */
    if (si1172_init() != 0) {
        fprintf(stderr, "[FATAL] Si1172 initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Open log file (append mode) --- */
    g_log_file = fopen("biometric_log.csv", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open biometric_log.csv: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header only if file is empty */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,hr_bpm,spo2_pct,error_flag\n");
        fflush(g_log_file);
    }

    /* --- Install signal handlers for graceful shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGINT) failed: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGTERM) failed: %s\n", strerror(errno));
    }

    printf("Si1172 logger started.  Logging to biometric_log.csv  (Ctrl-C to stop)\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        uint16_t ir = 0, red = 0;
        int   err  = 0;

        if (si1172_read_ppg(&ir, &red) != 0) {
            err = 1;
            fprintf(stderr, "[WARN] PPG read failed – logging error flag.\n");
        }

        uint32_t ts = (uint32_t)time(NULL);
        if (si1172_log_sample(ts, ir, red, err) != 0) {
            fprintf(stderr, "[WARN] Logging failed – continuing.\n");
        }

        sleep(1);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

