/*
 * flow_monitor.c — Raspberry Pi 4 Model B
 *
 * Reads a Honeywell SpiroQuant A+ ES1-005 mass flow sensor (analog output)
 * via an MCP3008 ADC on SPI0 (CE0 / GPIO8, channel 0) at 1 MHz, mode 0.
 * Converts the ADC value to a flow rate, validates the range, and logs
 * timestamped readings to flow_log.csv every second.
 *
 * Build:  gcc -O2 -Wall -Wextra -o flow_monitor flow_monitor.c -lm
 * Run:    ./flow_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <math.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL      0          /* SPI0 CE0 (GPIO8)                          */
#define SPI_SPEED        1000000    /* 1 MHz                                   */
#define SPI_FLAGS        0          /* Mode 0, active-low CE, 8-bit           */
#define ADC_CHANNEL      0          /* MCP3008 single-ended channel 0          */
#define ADC_MAX          1023       /* 10-bit ADC full-scale code             */
#define FLOW_MAX         5.0        /* L/min — upper limit for calibration   */
#define LOG_FILE         "flow_log.csv"
#define SAMPLE_PERIOD_US 1000000    /* 1 second                             */
#define ADC_TIMEOUT_US   100000     /* 100 ms max per SPI transfer           */

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static FILE *g_log_file  = NULL;

/* --------------------------- Forward declarations ------------------------- */
static void signal_handler(int sig);
static int  initialize_spi(void);
static int  read_adc(int channel, int *out_value);
static double calculate_flow_rate(int adc_value);
static void log_data(double flow_rate);
static void cleanup(void);

/* ------------------------------- Signal ---------------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;          /* tell main loop to exit cleanly              */
}

/* ------------------------------- SPI ------------------------------------ */
static int initialize_spi(void)
{
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "[ERROR] spiOpen failed (channel=%d, speed=%d, flags=%d): %s\n",
                SPI_CHANNEL, SPI_SPEED, SPI_FLAGS, pigpio_error(g_spi_handle));
        return -1;
    }
    return 0;
}

/*
 * Read a single-ended channel from the MCP3008.
 * Returns 0 on success (stores 10-bit code in *out_value), -1 on error.
 */
static int read_adc(int channel, int *out_value)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "[ERROR] Invalid ADC channel %d\n", channel);
        return -1;
    }
    if (out_value == NULL) {
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer, mode 0):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: rx[1] low 2 bits + rx[2] 8 bits = 10-bit code.
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "[ERROR] spiXfer returned %d (expected 3): %s\n",
                ret, pigpio_error(ret));
        return -1;
    }

    int value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    *out_value = value;
    return 0;
}

/* --------------------------- Flow calculation ---------------------------- */
static double calculate_flow_rate(int adc_value)
{
    if (adc_value < 0 || adc_value > ADC_MAX) {
        fprintf(stderr, "[WARN] ADC value %d out of 10-bit range\n", adc_value);
        return NAN;
    }

    /* SpiroQuant A+ ES1-005: flow rate (L/min) = (ADC / ADC_MAX) * F_MAX */
    return ((double)adc_value / (double)ADC_MAX) * FLOW_MAX;
}

/* ------------------------------- Logging --------------------------------- */
static void log_data(double flow_rate)
{
    struct timeval tv;
    if (gettimeofday(&tv, NULL) != 0) {
        fprintf(stderr, "[WARN] gettimeofday failed: %s\n", strerror(errno));
        return;
    }

    struct tm tm_info;
    localtime_r(&tv.tv_sec, &tm_info);

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(g_log_file, "%s.%06ld,%.4f\n", ts, (long)tv.tv_usec, flow_rate);
    fflush(g_log_file);
}

/* ------------------------------- Cleanup --------------------------------- */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* --------------------------------- Main ---------------------------------- */
int main(void)
{
    /* --- Install signal handlers early --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[ERROR] sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[ERROR] sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] gpioInitialise failed\n");
        return EXIT_FAILURE;
    }

    /* --- Initialize SPI --- */
    if (initialize_spi() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[ERROR] Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(g_log_file, "# flow_monitor started — SPI0 CE0 ch0, 1 MHz, 1 s\n");
    fflush(g_log_file);

    /* --- Main sampling loop --- */
    while (g_running) {
        int adc_value = 0;
        if (read_adc(ADC_CHANNEL, &adc_value) != 0) {
            fprintf(stderr, "[WARN] ADC read failed; skipping sample\n");
        } else {
            double flow_rate = calculate_flow_rate(adc_value);

            if (isnan(flow_rate)) {
                fprintf(stderr, "[WARN] Flow rate is NaN (ADC=%d)\n", adc_value);
            } else if (flow_rate < 0.0 || flow_rate > FLOW_MAX) {
                fprintf(stderr, "[WARN] Flow rate %.4f L/min out of range [0, %.1f]\n",
                        flow_rate, FLOW_MAX);
            } else {
                log_data(flow_rate);
            }
        }

        /* Sleep in small increments so signals are caught promptly */
        for (int i = 0; i < 10 && g_running; i++) {
            gpioDelay(100000);  /* 100 ms */
        }
    }

    /* --- Graceful shutdown --- */
    fprintf(stderr, "\n[INFO] Shutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

