/*
 * Raspberry Pi Zero W – TDK ICP-10125 I2C environmental monitor
 *
 * Wiring:
 *   ICP-10125 SDA  -> GPIO2 (pin 3, I2C bus 1 SDA)
 *   ICP-10125 SCL  -> GPIO3 (pin 5, I2C bus 1 SCL)
 *   ICP-10125 VDD  -> 3.3 V
 *   ICP-10125 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o icp10125_monitor icp10125_monitor.c
 */

#define _POSIX_C_SOURCE 200809L

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define ICP10125_ADDR  0x68

/* ICP-10125 high-precision measurement command (datasheet, bit 0 = 1) */
#define ICP10125_MEASURE_HP 0x80

/* Conversion time for high-precision mode (datasheet) */
#define ICP10125_CONV_MS  50

/* Sampling interval */
#define SAMPLE_INTERVAL_S 5

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

/*
 * Send a 1-byte command to the ICP-10125.
 * Returns 0 on success, -1 on error.
 */
static int icp10125_write_cmd(int fd, uint8_t cmd)
{
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write cmd 0x%02X failed: %s\n",
                cmd, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read `len` bytes from the ICP-10125 into `buf`.
 * Returns 0 on success, -1 on error.
 */
static int icp10125_read(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C read short: got %zd of %zu bytes\n", n, len);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* ICP-10125 calibration (datasheet)                                   */
/* ------------------------------------------------------------------ */
/*
 * Pressure (Pa)  = 0.5 * (P_raw - 0.5) * 2^16  -  16384.0
 * Temperature (°C) = 0.5 * (T_raw - 0.5) * 2^16  -  16384.0
 */
static void icp10125_calculate(const uint16_t raw[3],
                               float *pressure, float *temperature)
{
    float p = 0.5f * ((float)raw[0] - 0.5f) * 65536.0f;
    float t = 0.5f * ((float)raw[1] - 0.5f) * 65536.0f;

    *pressure    = p - 16384.0f;
    *temperature = t - 16384.0f;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, float temperature, float pressure)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.2f\n", ts, temperature, pressure);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = i2c_open(I2C_BUS, ICP10125_ADDR);
    if (g_i2c_fd < 0) {
        return EXIT_FAILURE;
    }

    /* Open CSV log */
    g_log_fp = fopen("environmental_data.csv", "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(environmental_data.csv) failed: %s\n",
                strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "timestamp,temperature_c,pressure_pa\n");
        fflush(g_log_fp);
    }

    printf("ICP-10125 environmental monitor started. Press Ctrl+C to stop.\n");

    while (g_running) {
        uint8_t cmd = ICP10125_MEASURE_HP;
        uint8_t buf[6];

        /* Issue high-precision measurement command */
        if (icp10125_write_cmd(g_i2c_fd, cmd) < 0) {
            fprintf(stderr, "Measurement command failed; retrying in %d s.\n",
                    SAMPLE_INTERVAL_S);
            sleep(SAMPLE_INTERVAL_S);
            continue;
        }

        /* Wait for conversion to complete */
        usleep(ICP10125_CONV_MS * 1000);

        /* Read 6-byte result: [P_msb P_lsb T_msb T_lsb CRC] */
        if (icp10125_read(g_i2c_fd, buf, sizeof(buf)) < 0) {
            fprintf(stderr, "Failed to read sensor data; retrying in %d s.\n",
                    SAMPLE_INTERVAL_S);
            sleep(SAMPLE_INTERVAL_S);
            continue;
        }

        /* Validate CRC (simplified polynomial 0x0D, init 0x00) */
        uint8_t crc = 0x00;
        for (int i = 0; i < 4; i++) {
            crc ^= buf[i];
            for (int b = 0; b < 8; b++) {
                if (crc & 0x80)
                    crc = (uint8_t)((crc << 1) ^ 0x0D);
                else
                    crc = (uint8_t)(crc << 1);
            }
        }
        if (crc != buf[4]) {
            fprintf(stderr, "CRC mismatch: computed 0x%02X, received 0x%02X\n",
                    crc, buf[4]);
            sleep(SAMPLE_INTERVAL_S);
            continue;
        }

        /* Convert raw ADC values to physical units */
        uint16_t raw_p = ((uint16_t)buf[0] << 8) | buf[1];
        uint16_t raw_t = ((uint16_t)buf[2] << 8) | buf[3];
        float pressure, temperature;
        icp10125_calculate(&raw_p, &pressure, &temperature);

        /* Log to CSV */
        log_data(g_log_fp, temperature, pressure);

        /* Display on console */
        printf("Temperature: %.2f °C, Pressure: %.2f Pa\n",
               temperature, pressure);

        /* Wait for next sample */
        sleep(SAMPLE_INTERVAL_S);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

