/*
 * Raspberry Pi 3 Model B+ — Dual MP23ABS1 noise-cancellation demo
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V
 *   MCP3008 VREF -> 3.3 V
 *   MCP3008 AGND -> GND
 *   MCP3008 DGND -> GND
 *   MCP3008 CLK  -> GPIO11 (SPI0 SCLK)
 *   MCP3008 DOUT -> GPIO9  (SPI0 MISO)
 *   MCP3008 DIN  -> GPIO10 (SPI0 MOSI)
 *   MCP3008 CS   -> GPIO8  (SPI0 CE0)
 *   MCP3008 CH0  -> Microphone A
 *   MCP3008 CH1  -> Microphone B
 *
 * Build:  gcc -O2 -Wall -Wextra -o noise_cancellation noise_cancellation.c -lpigpio -lrt
 * Run:    sudo ./noise_cancellation 1 1
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL    0          /* SPI0 CE0 (GPIO8)                          */
#define SPI_SPEED      1000000    /* 1 MHz                                     */
#define SPI_FLAGS      0          /* Mode 0, active-low CE                      */

#define MCP3008_CHANNEL_A 0        /* CH0 — Microphone A                        */
#define MCP3008_CHANNEL_B 1        /* CH1 — Microphone B                        */

#define SAMPLE_RATE     16000      /* 16 kHz audio output rate                   */
#define NUM_CHANNELS    2          /* 2 microphones                                */
#define NUM_SAMPLES     (SAMPLE_RATE * 4) /* 4 samples per channel per second       */

#define GAIN_A          1.0f
#define GAIN_B          1.0f

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* --------------------------- Signal handling ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- MCP3008 helpers ----------------------------- */
/*
 * Read a single-ended channel from the MCP3008.
 * Returns 0–1023 on success, or -1 on error.
 */
static int mcp3008_read_channel(int handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: rx[1] low 2 bits + rx[2] 8 bits
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: spiXfer failed on channel %d (ret=%d): %s\n",
                channel, ret, strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;
}

/* --------------------------- Noise cancellation -------------------------- */
/*
 * Simple noise-cancellation algorithm.
 *   sample_a  = raw ADC value from microphone A
 *   sample_b  = raw ADC value from microphone B
 *   gain_a   = user-specified gain for microphone A
 *   gain_b   = user-specified gain for microphone B
 *
 * Returns the difference (B - A) scaled to the [-1, 1] range.
 */
static float noise_cancellation(float sample_a, float sample_b,
                                float gain_a, float gain_b)
{
    float diff = (float)(sample_b - sample_a);
    float norm = (gain_a * sample_a + gain_b * sample_b) / (gain_a + gain_b);
    float scaled = diff - norm;

    if (scaled > 1.0f)   scaled = 1.0f;
    if (scaled < -1.0f)  scaled = -1.0f;
    return scaled;
}

/* --------------------------- CSV output --------------------------------- */
static void print_csv(float *audio, int num_samples)
{
    printf("Sample,Audio_A,Audio_B,Audio_C\n");
    for (int i = 0; i < num_samples; i++) {
        printf("%d,%.4f,%.4f,%.4f\n", i, audio[i * NUM_CHANNELS],
               audio[i * NUM_CHANNELS + 1], noise_cancellation(audio[i * NUM_CHANNELS],
                                                               audio[i * NUM_CHANNELS + 1],
                                                               GAIN_A, GAIN_B));
    }
    fflush(stdout);
}

/* ------------------------------- Main ----------------------------------- */
int main(int argc, char *argv[])
{
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <gain_a> <gain_b>\n", argv[0]);
        fprintf(stderr, "  gain_a — gain applied to microphone A\n");
        fprintf(stderr, "  gain_b — gain applied to microphone B\n");
        return EXIT_FAILURE;
    }

    float gain_a = (float)atof(argv[1]);
    float gain_b = (float)atof(argv[2]);
    if (gain_a <= 0.0f || gain_b <= 0.0f) {
        fprintf(stderr, "Error: gains must be positive\n");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open SPI0 CE0 at 1 MHz, mode 0 --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (handle=%d): %s\n",
                g_spi_handle, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGTERM) failed: %s\n", strerror(errno));
    }

    /* --- Allocate audio buffers --- */
    float *audio_a = malloc(NUM_SAMPLES * sizeof(float));
    float *audio_b = malloc(NUM_SAMPLES * sizeof(float));
    if (!audio_a || !audio_b) {
        fprintf(stderr, "Error: memory allocation failed\n");
        free(audio_a);
        free(audio_b);
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Main sampling loop --- */
    while (g_running) {
        for (int i = 0; i < NUM_SAMPLES; i++) {
            int val_a = mcp3008_read_channel(g_spi_handle, MCP3008_CHANNEL_A);
            int val_b = mcp3008_read_channel(g_spi_handle, MCP3008_CHANNEL_B);

            if (val_a < 0 || val_b < 0) {
                fprintf(stderr, "Error: SPI read failure on sample %d\n", i);
                /* Continue sampling; do not abort on transient bus errors. */
                continue;
            }

            /* Convert 10-bit ADC value to 16-bit signed PCM */
            int16_t raw_a = (int16_t)((val_a * 32767) / 1023.0f);
            int16_t raw_b = (int16_t)((val_b * 32767) / 1023.0f);

            audio_a[i] = (float)raw_a;
            audio_b[i] = (float)raw_b;
        }

        print_csv(audio_a, NUM_SAMPLES);
        gpioDelay(100000); /* 100 ms between samples */
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    free(audio_a);
    free(audio_b);
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

