#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_MODE        0
#define SPI_BITS        8
#define MCP3008_CHANNEL 0
#define BUZZER_GPIO     18
#define LOG_FILE        "flame_log.txt"
#define TEMP_FILE       "ambient_temp.txt"
#define SAMPLE_DELAY_US 500000
#define MAX_RETRIES     3
#define ADC_MAX         1023

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_mcp3008(int fd, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {
        0x01,
        (unsigned char)((0x08 | channel) << 4),
        0x00
    };
    unsigned char rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
        .len           = 3,
        .speed_hz      = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs   = 0,
        .cs_change     = 0,
        .tx_nbits      = 0,
        .rx_nbits      = 0,
        .pad           = 0
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float read_temperature(void) {
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Warning: cannot open %s: %s (using default 25.0 C)\n",
                TEMP_FILE, strerror(errno));
        return 25.0f;
    }

    float temp = -1.0f;
    if (fscanf(fp, "%f", &temp) != 1) {
        fprintf(stderr, "Warning: cannot parse %s (using default 25.0 C)\n", TEMP_FILE);
        temp = 25.0f;
    }
    fclose(fp);

    return temp;
}

static float adc_to_voltage(int adc) {
    return (float)adc * 3.3f / (float)ADC_MAX;
}

static float voltage_to_compensated_voltage(float v, float t) {
    return v * (1.0f + 0.01f * (t - 25.0f));
}

static void log_data(int raw, float v, float cv, float t, int flame) {
    time_t now = time(NULL);
    struct tm tmv;
    char ts[32];
    localtime_r(&now, &tmv);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tmv);

    fprintf(g_log_fp, "%s,%d,%.3f,%.3f,%.2f,%d\n", ts, raw, v, cv, t, flame);
    fflush(g_log_fp);
}

static void cleanup(void) {
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioWrite(BUZZER_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", SPI_DEVICE, strerror(errno));
        gpioTerminate();
        return 1;
    }

    unsigned char mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    unsigned char bits = SPI_BITS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    unsigned int speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    if (gpioSetMode(BUZZER_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d) failed\n", BUZZER_GPIO);
        cleanup();
        return 1;
    }
    gpioWrite(BUZZER_GPIO, 0);

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int raw = -1;
        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            raw = read_mcp3008(g_spi_fd, MCP3008_CHANNEL);
            if (raw >= 0 && raw <= ADC_MAX) {
                break;
            }
            fprintf(stderr, "ADC read attempt %d/%d failed\n", attempt + 1, MAX_RETRIES);
            if (attempt < MAX_RETRIES - 1) {
                usleep(10000);
            }
        }

        if (raw < 0) {
            fprintf(stderr, "ADC read failed after %d attempts; buzzer OFF for safety\n", MAX_RETRIES);
            gpioWrite(BUZZER_GPIO, 0);
            usleep(SAMPLE_DELAY_US);
            continue;
        }

        float v = adc_to_voltage(raw);
        float t = read_temperature();
        float cv = voltage_to_compensated_voltage(v, t);

        int flame = (cv > 0.5f) ? 1 : 0;
        if (flame) {
            gpioWrite(BUZZER_GPIO, 1);
        } else {
            gpioWrite(BUZZER_GPIO, 0);
        }

        log_data(raw, v, cv, t, flame);

        usleep(SAMPLE_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

