/*
 * Raspberry Pi 3 Model B+ — DFRobot Gravity Analog Water Level Sensor
 * MCP3008 ADC on SPI0 (CE0/GPIO8, MISO/GPIO9, MOSI/GPIO10, SCLK/GPIO11)
 * LED on GPIO17 (BCM) with hysteresis thresholds 75 % and 70 %
 * Output: water_levels.json (JSON array of ISO-8601-timestamped entries)
 *
 * Build:  gcc -O2 -Wall -Wextra -o water_level water_level.c -lm
 * Run:    ./water_level
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_DEVICE        "/dev/spidev0.0"
#define SPI_SPEED_HZ      1000000U   /* 1 MHz — well within MCP3008 3.3 V limit */
#define SPI_BITS_PER_WORD 8
#define SPI_MODE          0          /* SPI mode 0 (CPOL=0, CPHA=0) */

#define LED_PIN           17         /* BCM GPIO 17 */
#define LED_ON_THRESHOLD  75.0f      /* percent — turn LED on above this */
#define LED_OFF_THRESHOLD 70.0f      /* percent — turn LED off below this */

#define SAMPLE_INTERVAL_S 5          /* seconds between readings */
#define SAMPLE_INTERVAL_US (SAMPLE_INTERVAL_S * 1000000U)

#define JSON_FILE         "water_levels.json"
#define MAX_JSON_ENTRIES  1000       /* guard against runaway file growth */

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_spi_fd   = -1;
static FILE *g_json_fp = NULL;

/* ----------------------------- Prototypes -------------------------------- */
static int  spi_init(void);
static int  read_mcp3008(int channel, uint16_t *out);
static float adc_to_percentage(uint16_t adc);
static void log_data(float percentage);
static void signal_handler(int sig);
static void cleanup(void);

/* ----------------------------- SPI helpers -------------------------------- */
static int spi_init(void)
{
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1;
        return -1;
    }

    return 0;
}

/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
 *   tx[2] = 0x00                       (clock out low bits)
 * Result: 10-bit value in ((rx[1] & 0x03) << 8) | rx[2]
 */
static int read_mcp3008(int channel, uint16_t *out)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }
    if (out == NULL) {
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = sizeof(tx);
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS_PER_WORD;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE failed: %s\n", strerror(errno));
        return -1;
    }

    *out = (uint16_t)(((rx[1] & 0x03) << 8) | rx[2]);
    return 0;
}

/*
 * Convert 10-bit ADC value (0–1023) to a percentage of full-scale.
 * DFRobot Gravity sensor output is typically 0–3.3 V; 1023 maps to 3.3 V.
 */
static float adc_to_percentage(uint16_t adc)
{
    if (adc == 0) return 0.0f;
    return (float)adc / 1023.0f * 100.0f;
}

/* ----------------------------- Logging ----------------------------------- */
static void log_data(float percentage)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
        perror("clock_gettime");
        return;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char tbuf[32];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%dT%H:%M:%S", &tm_info);

    /* Append millisecond precision */
    char msbuf[8];
    snprintf(msbuf, sizeof(msbuf), ".%03ld", ts.tv_nsec / 1000000L);
    strncat(tbuf, msbuf, sizeof(tbuf) - strlen(tbuf) - 1);

    fprintf(g_json_fp, "{\"timestamp\": \"%s\", \"percentage\": %.2f}\n",
            tbuf, percentage);
    fflush(g_json_fp);
}

/* ----------------------------- Signal / cleanup --------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    if (g_json_fp != NULL) {
        /* Write closing ']' and flush */
        if (fseek(g_json_fp, -1, SEEK_END) == 0) {
            if (fputc(']', g_json_fp) == EOF) {
                perror("fputc(']')");
            }
        }
        fflush(g_json_fp);
        fclose(g_json_fp);
        g_json_fp = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    if (g_json_fp != NULL) {
        fclose(g_json_fp);
        g_json_fp = NULL;
    }
    /* Turn LED off */
    if (LED_PIN >= 0) {
        (void)gpioWrite(LED_PIN, 0);
    }
    /* Terminate driver library */
    if (g_spi_fd >= 0) {
        spiClose(g_spi_fd);
        g_spi_fd = -1;
    }
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize SPI */
    if (spi_init() < 0) {
        return EXIT_FAILURE;
    }

    /* Open JSON file (append mode) */
    g_json_fp = fopen(JSON_FILE, "a");
    if (g_json_fp == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", JSON_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write opening '[' */
    if (fputs("[\n", g_json_fp) == EOF) {
        perror("fputs('[')");
        cleanup();
        return EXIT_FAILURE;
    }
    if (fflush(g_json_fp) == EOF) {
        perror("fflush");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure LED pin */
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed\n", LED_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioWrite(LED_PIN, 0) < 0) {
        fprintf(stderr, "gpioWrite(%d, 0) failed\n", LED_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Water level monitoring started. Press Ctrl+C to exit.\n");

    int entry_count = 0;
    while (g_running) {
        uint16_t adc_value = 0;

        if (read_mcp3008(0, &adc_value) < 0) {
            /* SPI error — skip this sample, keep running */
            usleep(100000);
            continue;
        }

        float percentage = adc_to_percentage(adc_value);

        log_data(percentage);

        /* Hysteresis LED control */
        if (percentage > LED_ON_THRESHOLD) {
            if (gpioWrite(LED_PIN, 1) < 0) {
                fprintf(stderr, "gpioWrite(%d, 1) failed\n", LED_PIN);
            }
        } else if (percentage < LED_OFF_THRESHOLD) {
            if (gpioWrite(LED_PIN, 0) < 0) {
                fprintf(stderr, "gpioWrite(%d, 0) failed\n", LED_PIN);
            }
        }

        printf("ADC: %4u  |  Water Level: %5.2f%%  |  LED: %s\n",
               adc_value, percentage,
               (percentage > LED_ON_THRESHOLD) ? "ON" : "OFF");

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < 50 && g_running; i++) {
            usleep(100000);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

