            if (fputc(']', g_json_fp) == EOF) {
                perror("fputc(']')");
            }
        }
        fflush(g_json_fp);
        fclose(g_json_fp);
        g_json_fp = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    if (g_json_fp != NULL) {
        fclose(g_json_fp);
        g_json_fp = NULL;
    }
    /* Turn LED off */
    if (LED_PIN >= 0) {
        (void)gpioWrite(LED_PIN, 0);
    }
    /* Terminate driver library */
    if (g_spi_fd >= 0) {
        spiClose(g_spi_fd);
        g_spi_fd = -1;
    }
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize SPI */
    if (spi_init() < 0) {
        return EXIT_FAILURE;
    }

    /* Open JSON file (append mode) */
    g_json_fp = fopen(JSON_FILE, "a");
    if (g_json_fp == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", JSON_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write opening '[' */
    if (fputs("[\n", g_json_fp) == EOF) {
        perror("fputs('[')");
        cleanup();
        return EXIT_FAILURE;
    }
    if (fflush(g_json_fp) == EOF) {
        perror("fflush");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure LED pin */
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed\n", LED_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioWrite(LED_PIN, 0) < 0) {
        fprintf(stderr, "gpioWrite(%d, 0) failed\n", LED_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Water level monitoring started. Press Ctrl+C to exit.\n");

    int entry_count = 0;
    while (g_running) {
        uint16_t adc_value = 0;

        if (read_mcp3008(0, &adc_value) < 0) {
            /* SPI error — skip this sample, keep running */
            usleep(100000);
            continue;
        }

        float percentage = adc_to_percentage(adc_value);

        log_data(percentage);

        /* Hysteresis LED control */
        if (percentage > LED_ON_THRESHOLD) {
            if (gpioWrite(LED_PIN, 1) < 0) {
                fprintf(stderr, "gpioWrite(%d, 1) failed\n", LED_PIN);
            }
        } else if (percentage < LED_OFF_THRESHOLD) {
            if (gpioWrite(LED_PIN, 0) < 0) {
                fprintf(stderr, "gpioWrite(%d, 0) failed\n", LED_PIN);
            }
        }

        printf("ADC: %4u  |  Water Level: %5.2f%%  |  LED: %s\n",
               adc_value, percentage,
               (percentage > LED_ON_THRESHOLD) ? "ON" : "OFF");

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < 50 && g_running; i++) {
            usleep(100000);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

