/*
 * Raspberry Pi Zero W – Honeywell AWM7300V airflow logger
 *
 * Hardware:
 *   MCP3008 10-bit ADC on SPI0 (CE0 = physical pin 24, SCLK = 23, MOSI = 19, MISO = 21)
 *   AWM7300V analog output wired to MCP3008 channel 0
 *
 * Build:  gcc -O2 -Wall -Wextra -o airflow_logger airflow_logger.c
 * Run:    ./airflow_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U   /* 1 MHz – well within MCP3008 200 kHz–3.2 MHz range */
#define SPI_BITS        8
#define SPI_MODE        SPI_MODE_0
#define ADC_CHANNEL     0
#define LOG_FILE        "airflow_log.csv"
#define SAMPLE_PERIOD_US 100000U  /* 100 ms */
#define ADC_MAX_VALUE   1023       /* 10-bit ADC */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* SPI helpers                                                         */
/* ------------------------------------------------------------------ */
static int spi_open(const char *device)
{
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", device, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "ioctl(SPI_IOC_WR_MODE): %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "ioctl(SPI_IOC_WR_BITS_PER_WORD): %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "ioctl(SPI_IOC_WR_MAX_SPEED_HZ): %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

/*
 * MCP3008 single-ended read.
 * 3-byte transfer: [start] [SGL|D2|D1|D0|0|0|0|0] [don't-care]
 * Result: 10-bit value in ((rx[1] & 0x03) << 8) | rx[2].
 */
static int mcp3008_read(int fd, uint8_t channel)
{
    if (channel > 7) {
        fprintf(stderr, "mcp3008_read: invalid channel %u\n", channel);
        return -1;
    }

    uint8_t tx[3] = {
        0x01,
        (uint8_t)((0x08 | channel) << 4),
        0x00
    };
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = sizeof(tx);
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "ioctl(SPI_IOC_MESSAGE): %s\n", strerror(errno));
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_open(const char *path)
{
    FILE *fp = fopen(path, "a+");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", path, strerror(errno));
        return -1;
    }

    /* Write header only if file is empty */
    if (fseek(fp, 0, SEEK_END) == 0) {
        long sz = ftell(fp);
        if (sz == 0) {
            if (fputs("timestamp,adc_value,lpm\n", fp) == EOF) {
                fprintf(stderr, "fputs(header): %s\n", strerror(errno));
                fclose(fp);
                return -1;
            }
        }
    } else {
        fprintf(stderr, "fseek: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    return fp;
}

static int log_sample(FILE *fp, int adc_value, float lpm)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time(): %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r: %s\n", strerror(errno));
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime: buffer too small\n");
        return -1;
    }

    if (fprintf(fp, "%s,%d,%.2f\n", ts, adc_value, lpm) < 0) {
        fprintf(stderr, "fprintf: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(int spi_fd, FILE *fp)
{
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    if (fp) {
        fclose(fp);
        fp = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int spi_fd = -1;
    FILE *fp = NULL;
    int ret = EXIT_FAILURE;

    if (install_signal_handlers() != 0) {
        goto done;
    }

    spi_fd = spi_open(SPI_DEVICE);
    if (spi_fd < 0) {
        goto done;
    }

    fp = log_open(LOG_FILE);
    if (!fp) {
        goto done;
    }

    printf("Airflow logger started. Logging to %s every 100 ms. Press Ctrl+C to stop.\n",
           LOG_FILE);

    while (g_running) {
        int adc = mcp3008_read(spi_fd, ADC_CHANNEL);
        if (adc < 0) {
            fprintf(stderr, "ADC read failed; continuing.\n");
        } else {
            float lpm = (float)adc * 0.1f;   /* placeholder: calibrate per datasheet */
            if (log_sample(fp, adc, lpm) != 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
        }

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly...\n");
    ret = EXIT_SUCCESS;

done:
    cleanup(spi_fd, fp);
    return ret;
}

