/*
 * plant_monitor.c — Raspberry Pi Zero W
 *
 * Monitors a HiLetgo Soil Moisture Sensor (analog resistive) on a MCP3008 ADC
 * (SPI bus 0, CE0, 500 kHz, single-ended, channel 0) and logs timestamped
 * moisture readings to plant_data.txt every 60 s.  On moisture < 30 % the
 * recipient email address is piped to msmtp via popen.
 *
 * Build:  gcc -O2 -Wall -Wextra -o plant_monitor plant_monitor.c -lpthread -lrt
 * Run:    ./plant_monitor [-s spi_channel] [-c adc_channel] [-m min] [-M max]
 *         [-t threshold] [-i interval] [-e email] [-c config]
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <sys/types.h>
#include <sys/wait.h>

#define DEFAULT_SPI_CHANNEL      0
#define DEFAULT_ADC_CHANNEL     0
#define DEFAULT_MIN_CALIB       0
#define DEFAULT_MAX_CALIB       1023
#define DEFAULT_THRESHOLD       30
#define DEFAULT_INTERVAL        60
#define DEFAULT_EMAIL           "recipient@example.com"
#define DEFAULT_CONFIG_FILE     "msmtprc"
#define LOG_FILE                "plant_data.txt"
#define SPI_DEVICE              "/dev/spidev0.0"
#define SPI_SPEED_HZ            500000
#define SPI_BITS                8
#define SPI_MODE                 0

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int spi_init(const char *device, uint8_t mode, uint8_t bits, uint32_t speed)
{
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("open(SPI device)");
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl(SPI_IOC_WR_MODE)");
        close(fd);
        return -1;
    }
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl(SPI_IOC_WR_BITS_PER_WORD)");
        close(fd);
        return -1;
    }
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl(SPI_IOC_WR_MAX_SPEED_HZ)");
        close(fd);
        return -1;
    }
    return fd;
}

/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
 *   tx[2] = 0x00                       (clock out low bits)
 * Result: 10-bit value in ((rx[1] & 0x03) << 8) | rx[2].
 */
static int mcp3008_read(int fd, uint8_t channel)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid ADC channel %u\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = sizeof(tx);
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("ioctl(SPI_IOC_MESSAGE)");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float calibrate(int raw, int min, int max)
{
    if (max <= min) {
        fprintf(stderr, "Invalid calibration range min=%d max=%d\n", min, max);
        return -1.0f;
    }
    if (raw < 0) raw = 0;
    if (raw > 1023) raw = 1023;
    return ((float)(raw - min) / (float)(max - min)) * 100.0f;
}

static int log_data(const char *filename, float moisture)
{
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        perror("fopen(log file)");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, %.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, moisture);

    if (fclose(fp) != 0) {
        perror("fclose(log file)");
        return -1;
    }
    return 0;
}

static int send_email_alert(const char *email, float moisture, int threshold)
{
