        "Subject: Plant Moisture Alert\n\n"
        "Plant moisture level is below threshold (%.2f%% < %d%%).\n",
        moisture, threshold);

    if (body_len < 0 || (size_t)body_len >= sizeof(body)) {
        fprintf(stderr, "Email body buffer too small\n");
        return -1;
    }

    char command[512];
    int cmd_len = snprintf(command, sizeof(command),
        "echo \"Subject: Plant Moisture Alert\\n\\nPlant moisture level is below threshold (%.2f%% < %d%%).\\n\" | msmtp -c %s %s",
        moisture, threshold, DEFAULT_CONFIG_FILE, email);

