/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* SPI                                                                 */
/* ------------------------------------------------------------------ */
static int spi_init(const char *device)
{
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", device, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "ioctl(SPI_IOC_WR_MODE): %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "ioctl(SPI_IOC_WR_BITS_PER_WORD): %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "ioctl(SPI_IOC_WR_MAX_SPEED_HZ): %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
 *   tx[2] = 0x00                       (clock out remaining bits)
 * Result: 10-bit value assembled from rx[1] (low 2 bits) and rx[2] (8 bits).
 */
static int mcp3008_read(int fd, uint8_t channel)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid channel %u\n", channel);
        return -1;
    }

    uint8_t tx[3] = {
        0x01,
        (uint8_t)((0x08 | channel) << 4),
        0x00
    };
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = sizeof(tx);
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE: %s\n", strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Pressure conversion                                               */
/* ------------------------------------------------------------------ */
static float adc_to_pressure(int adc_value)
{
    if (adc_value < 0)   adc_value = 0;
    if (adc_value > ADC_MAX_VALUE) adc_value = ADC_MAX_VALUE;

    float voltage = ((float)adc_value / (float)ADC_MAX_VALUE) * ADC_VREF;
    return (voltage / ADC_VREF) * 100.0f;   /* 0–100 kPa */
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                   */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        snprintf(buf, len, "1970-01-01T00:00:00");
        return;
    }
    struct tm tmv;
    if (localtime_r(&now, &tmv) == NULL) {
        snprintf(buf, len, "1970-01-01T00:00:00");
        return;
    }
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tmv);
}

