/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int spi_fd = -1;
    int consecutive_errors = 0;

    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    spi_fd = spi_init(SPI_DEVICE);
    if (spi_fd < 0) {
        return EXIT_FAILURE;
    }

    printf("MLX90823 pressure sensor reader started.\n");
    printf("SPI device : %s\n", SPI_DEVICE);
    printf("Speed      : %u Hz\n", SPI_SPEED_HZ);
    printf("Bits       : %d\n", SPI_BITS);
    printf("Channel    : CH%d\n", ADC_CHANNEL);
    printf("VREF       : %.2f V\n", ADC_VREF);
    printf("Sample period : %d s\n", SAMPLE_PERIOD_S);
    printf("Press Ctrl+C to exit.\n\n");

    while (g_running) {
        int adc_value = mcp3008_read(spi_fd, ADC_CHANNEL);

        if (adc_value < 0) {
            consecutive_errors++;
            fprintf(stderr, "SPI read error (%d consecutive)\n",
                    consecutive_errors);
            if (consecutive_errors >= MAX_CONSECUTIVE_ERRORS) {
                fprintf(stderr, "Too many consecutive SPI errors; aborting.\n");
                break;
            }
            sleep(SAMPLE_PERIOD_S);
            continue;
        }

        consecutive_errors = 0;

        /* Sensor-absent / wiring-fault detection */
        if (adc_value == 0) {
            fprintf(stderr, "Warning: ADC reads 0 — sensor may be absent or shorted to GND.\n");
        } else if (adc_value == ADC_MAX_VALUE) {
            fprintf(stderr, "Warning: ADC saturated at %d — sensor may be shorted to VREF or disconnected.\n",
                    ADC_MAX_VALUE);
        }

        float pressure = adc_to_pressure(adc_value);
        char ts[32];
        get_timestamp(ts, sizeof(ts));

        printf("[%s] ADC=%4d  Voltage=%.3f V  Pressure=%.2f kPa\n",
               ts, adc_value,
               (float)adc_value * ADC_VREF / ADC_MAX_VALUE,
               pressure);

        sleep(SAMPLE_PERIOD_S);
    }

    /* Clean shutdown */
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

