    /* --- Main sampling loop --- */
    while (g_running) {
        int adc_value = read_mcp3008(spi_fd, ADC_CHANNEL);

        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value (code %d). Retrying in %d s.\n",
                    adc_value, SAMPLE_INTERVAL);
        } else {
            time_t rawtime;
            time(&rawtime);
            struct tm timeinfo;
            localtime_r(&rawtime, &timeinfo);
            char timestamp[32];
