        fprintf(stderr, "Error getting local time\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
            return;
        }
    }

    fprintf(log_file, "%s", timestamp);
    for (int i = 0; i < NUM_SENSORS; i++) {
        fprintf(log_file, ",%.3f", voltages[i]);
    }
    fprintf(log_file, "\n");
    fflush(log_file);
}

static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (spi_init() < 0) {
        return 1;
    }

    printf("Starting environmental data logging. Press Ctrl+C to stop.\n");

    while (running) {
        float voltages[NUM_SENSORS];
        int error = 0;

        for (int i = 0; i < NUM_SENSORS; i++) {
            int adc_value = read_mcp3008(i);
            if (adc_value < 0) {
                fprintf(stderr, "Error reading sensor %d\n", i);
                voltages[i] = -1.0f;
                error = 1;
                break;
            }
            voltages[i] = convert_to_voltage(adc_value);
        }

        if (!error) {
            log_data(voltages);
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

