/*
 * Raspberry Pi 3 Model B+ — Vegetronix VH400 soil moisture monitor
 *
 * Hardware:
 *   - MCP3008 10-bit ADC on SPI bus 0, CE0 (BCM 8), 1 MHz, mode 0
 *     VDD  -> 3.3 V (pin 1)
 *     VREF -> 3.3 V (pin 1)
 *     AGND -> GND  (pin 6)
 *     DGND -> GND  (pin 6)
 *     CLK  -> BCM 11 (SCLK)
 *     DOUT -> BCM 9  (MISO)
 *     DIN  -> BCM 10 (MOSI)
 *     CS   -> BCM 8  (CE0)
 *   - Vegetronix VH400 analog output wired to MCP3008 channel 0
 *   - 12 V water pump via relay on BCM 17 (active-high)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o vh400_monitor vh400_monitor.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL    0          /* CE0 (BCM 8) */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* mode 0, active-low CE */

#define PUMP_GPIO      17          /* BCM 17 — active-high relay */

#define MOISTURE_THRESHOLD_LOW  300   /* turn pump ON below this */
#define MOISTURE_THRESHOLD_HIGH 600   /* turn pump OFF above this */

#define BUFFER_SIZE  20
#define SAMPLE_PERIOD_S 5

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* --------------------------- Circular Buffer ----------------------------- */
typedef struct {
    time_t timestamp;
    int    moisture_level;
    bool   pump_state;
} MoistureData;

static MoistureData g_buffer[BUFFER_SIZE];
static int          g_buf_head = 0;   /* next write slot */
static int          g_buf_tail = 0;   /* oldest entry */

/* --------------------------- Forward declarations ------------------------- */
static void signal_handler(int sig);
static int  initialize(void);
static void cleanup(void);
static void add_to_buffer(int moisture_level, bool pump_state);
static void print_buffer(void);
static int  read_mcp3008(int channel);
static void control_pump(int moisture_level);

/* ------------------------------- Main ------------------------------------ */
int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return EXIT_FAILURE;
    }

    printf("VH400 soil moisture monitor started. Sampling every %d s.\n",
           SAMPLE_PERIOD_S);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        int moisture_level = read_mcp3008(0);
        if (moisture_level < 0) {
            fprintf(stderr, "SPI read error — skipping sample.\n");
        } else {
            bool pump_state = (moisture_level < MOISTURE_THRESHOLD_LOW);
            control_pump(moisture_level);
            add_to_buffer(moisture_level, pump_state);
            print_buffer();
        }
        sleep(SAMPLE_PERIOD_S);
    }

    cleanup();
    return EXIT_SUCCESS;
}

/* --------------------------- Initialization -------------------------------- */
static int initialize(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    /* Configure pump GPIO as output, ensure pump is OFF */
    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PUMP_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(PUMP_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to initialise GPIO %d to LOW\n", PUMP_GPIO);
        gpioTerminate();
        return -1;
    }

    /* Open SPI bus 0, channel 0, 1 MHz, mode 0 */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle=%d)\n", g_spi_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

/* --------------------------- Cleanup -------------------------------------- */
static void cleanup(void)
{
    /* Ensure pump is OFF before releasing resources */
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioWrite(PUMP_GPIO, 0);
    gpioTerminate();
}

/* --------------------------- Signal handler ------------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- Read MCP3008 ------------------------------- */
/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care)
 *   tx[2] = 0x00                       (clock out remaining bits)
 * Result: 10-bit value in ((rx[1] & 0x03) << 8) | rx[2]
 */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int bytes = spiXfer(g_spi_handle, tx, rx, 3);
    if (bytes != 3) {
        fprintf(stderr, "spiXfer returned %d (expected 3)\n", bytes);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;
}

/* --------------------------- Pump control -------------------------------- */
static void control_pump(int moisture_level)
{
    bool pump_state = (moisture_level < MOISTURE_THRESHOLD_LOW);

    if (gpioWrite(PUMP_GPIO, pump_state ? 1 : 0) != 0) {
        fprintf(stderr, "gpioWrite failed on GPIO %d\n", PUMP_GPIO);
    }

    if (pump_state != g_buffer[g_buf_head].pump_state) {
        g_buffer[g_buf_head].pump_state = pump_state;
        g_buf_head = (g_buf_head + 1) % BUFFER_SIZE;
        if (g_buf_head == g_buf_tail) {
            g_buf_tail = (g_buf_tail + 1) % BUFFER_SIZE;
        }
    }
}

/* --------------------------- Buffer helpers ------------------------------ */
static void add_to_buffer(int moisture_level, bool pump_state)
{
    time(&g_buffer[g_buf_head].timestamp);
    g_buffer[g_buf_head].moisture_level = moisture_level;
    g_buffer[g_buf_head].pump_state = pump_state;

    g_buf_head = (g_buf_head + 1) % BUFFER_SIZE;
    if (g_buf_head == g_buf_tail) {
        g_buf_tail = (g_buf_tail + 1) % BUFFER_SIZE;
    }
}

static void print_buffer(void)
{
    printf("\n--- Moisture Log (%d entries) ---\n", BUFFER_SIZE);
    int start = (g_buf_tail == g_buf_head) ? g_buf_tail : g_buf_tail;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        char ts[32];
        struct tm *tm_info = localtime(&g_buffer[idx].timestamp);
        if (tm_info) {
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);
        } else {
            strncpy(ts, "----", sizeof(ts));
        }
        printf("[%s] Moisture: %d, Pump: %s\n",
               ts,
               g_buffer[idx].moisture_level,
               g_buffer[idx].pump_state ? "ON" : "OFF");
    }
    printf("--- End of Log ---\n\n");
}

/* --------------------------- Main loop ----------------------------------- */

