/*
 * MAX30102 Pulse Oximeter Monitor for Raspberry Pi Zero W
 * I2C bus 1, continuous sampling every 1 second.
 * Writes readings below 95 % SpO2 or above 100 BPM heart rate to
 * health_log.txt with an ISO 8601 timestamp.
 * Handles SIGINT / SIGTERM and cleans up resources.
 *
 * Build:  gcc -O2 -Wall -Wextra -o max30102_monitor max30102_monitor.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

/* ---- MAX30102 constants (per datasheet) ---- */
#define MAX30102_I2C_ADDR 0x57

#define REG_INTR_STATUS_1   0x00
#define REG_INTR_STATUS_2   0x01
#define REG_INTR_ENABLE_1   0x02
#define REG_INTR_ENABLE_2   0x03
#define REG_FIFO_WR_PTR     0x04
#define REG_OVF_COUNTER     0x05
#define REG_FIFO_RD_PTR     0x06
#define REG_FIFO_DATA       0x07
#define REG_FIFO_CONFIG     0x08
#define REG_MODE_CONFIG     0x09
#define REG_SPO2_CONFIG     0x0A
#define REG_LED1_PA         0x0C
#define REG_LED2_PA         0x0D
#define REG_PART_ID         0xFF

#define EXPECTED_PART_ID    0x15

/* ---- Globals for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void log_error(const char *msg)
{
    FILE *fp = fopen("error.log", "a");
    if (!fp) {
        fprintf(stderr, "[ERROR] Cannot open error.log: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02dT%02d:%02d:%02d %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    }
    fclose(fp);
    fprintf(stderr, "[ERROR] %s\n", msg);
}

/* ------------------------------------------------------------------ */
static void log_health_data(int spo2, int heart_rate)
{
    FILE *fp = fopen("health_log.txt", "a");
    if (!fp) {
        log_error("Cannot open health_log.txt for appending");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02dT%02d:%02d:%02d, SpO2: %d%%, Heart Rate: %dBPM\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, spo2, heart_rate);
    }
    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Write one byte to a register; returns 0 on success, -1 on error.   */
static int reg_write(uint8_t reg, uint8_t val)
{
    int rc = i2cWriteByteData(g_i2c_handle, reg, val);
    if (rc < 0) {
        char buf[128];
        snprintf(buf, sizeof(buf), "I2C write failed: reg=0x%02X val=0x%02X rc=%d", reg, val, rc);
        log_error(buf);
    }
    return rc;
}

/* ------------------------------------------------------------------ */
/* Read one byte from a register; returns 0 on success, -1 on error.  */
static int reg_read(uint8_t reg, uint8_t *val)
{
    int rc = i2cReadByteData(g_i2c_handle, reg);
    if (rc < 0) {
        char buf[128];
        snprintf(buf, sizeof(buf), "I2C read failed: reg=0x%02X rc=%d", reg, rc);
        log_error(buf);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian register pair; returns 0 on success.   */
static int reg_read16(uint8_t reg, uint16_t *val)
{
    int rc = i2cReadWordData(g_i2c_handle, reg);
    if (rc < 0) {
        char buf[128];
        snprintf(buf, sizeof(buf), "I2C read16 failed: reg=0x%02X rc=%d", reg, rc);
        log_error(buf);
        return -1;
    }
    *val = (uint16_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
static int init_max30102(void)
{
    uint8_t part_id = 0;

    /* Verify Part ID */
    if (reg_read(REG_PART_ID, &part_id) != 0) {
        log_error("Cannot read Part ID register");
        return -1;
    }
    if (part_id != EXPECTED_PART_ID) {
        char buf[128];
        snprintf(buf, sizeof(buf),
                 "Unexpected Part ID: 0x%02X (expected 0x%02X)",
                 part_id, EXPECTED_PART_ID);
        log_error(buf);
        return -1;
    }
    printf("MAX30102 detected (Part ID 0x%02X)\n", part_id);

    /* Clear interrupts */
    if (reg_write(REG_INTR_STATUS_1, 0x00) != 0) return -1;
    if (reg_write(REG_INTR_STATUS_2, 0x00) != 0) return -1;

    /* Clear FIFO counters */
    if (reg_write(REG_OVF_COUNTER, 0x00) != 0) return -1;
    if (reg_write(REG_FIFO_WR_PTR, 0x00) != 0) return -1;
    if (reg_write(REG_FIFO_RD_PTR, 0x00) != 0) return -1;

    /* FIFO config: 32 samples, 4.2 MHz ODR, no auto-increment */
    if (reg_write(REG_FIFO_CONFIG, 0x4D) != 0) return -1;

    /* Mode: SpO2 + HR, no shutdown */
    if (reg_write(REG_MODE_CONFIG, 0x03) != 0) return -1;

    /* SpO2 config: 665 nm, 795 nm, 4.2 MHz ODR, 100 Hz, 50 Hz */
    if (reg_write(REG_SPO2_CONFIG, 0x27) != 0) return -1;

    /* LED pulse amplitude */
    if (reg_write(REG_LED1_PA, 0x24) != 0) return -1;
    if (reg_write(REG_LED2_PA, 0x24) != 0) return -1;

    /* Enable both interrupt sources */
