    /* Read 24-bit FIFO data (3 bytes) */
    if (reg_read(REG_FIFO_DATA, &status) != 0) return -1;
    if (reg_read16(REG_FIFO_DATA, &fifo_data) != 0) return -1;

    /* Clear interrupt by writing to INTR_STATUS_1 */
    if (reg_write(REG_INTR_STATUS_1, 0x01) != 0) return -1;

    /* SpO2: 0.5 * (0xFF - (fifo_data & 0x00FF)) */
    *spo2 = (int)(((uint16_t)(0xFF - (fifo_data & 0x00FF)) >> 8) * 0.5 + 0.5);

    /* Heart rate: (fifo_data >> 16) & 0x1FFF */
    *heart_rate = (int)((fifo_data >> 16) & 0x1FFF);

    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at MAX30102 address */
    g_i2c_handle = i2cOpen(1, MAX30102_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (init_max30102() != 0) {
        fprintf(stderr, "MAX30102 initialization failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Monitoring SpO2 and heart rate. Press Ctrl+C to stop.\n");

    /* Main loop */
    while (g_running) {
        int spo2 = 0, heart_rate = 0;

        if (read_max30102(&spo2, &heart_rate) == 0) {
            if (spo2 < 95) {
                log_health_data(spo2, heart_rate);
            }
            if (heart_rate > 100) {
                log_health_data(spo2, heart_rate);
            }
