/*
 * MCP3008 3-channel SPI reader for Raspberry Pi Zero W
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V (pin 1)
 *   MCP3008 VREF -> 3.3 V (pin 1)
 *   MCP3008 AGND -> GND  (pin 6)
 *   MCP3008 DGND -> GND  (pin 6)
 *   MCP3008 CLK  -> GPIO11 (SPI0 SCLK, pin 23)
 *   MCP3008 DOUT -> GPIO9  (SPI0 MISO, pin 21)
 *   MCP3008 DIN  -> GPIO10 (SPI0 MOSI, pin 19)
 *   MCP3008 CS   -> GPIO8  (SPI0 CE0,  pin 24)
 *   MCP3008 CH0  -> analog sensor 0
 *   MCP3008 CH1  -> analog sensor 1
 *   MCP3008 CH2  -> analog sensor 2
 *
 * Build:  gcc -O2 -Wall -Wextra -o analog_reader analog_reader.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define SPI_CHANNEL    0          /* SPI0 CE0 (GPIO8) */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */
#define NUM_CHANNELS   3
#define LOG_FILE       "analog_log.csv"
#define SAMPLE_PERIOD  500000     /* 500 ms in microseconds */

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* MCP3008 read                                                         */
/* ------------------------------------------------------------------ */
/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care)
 *   tx[2] = 0x00                       (clock out remaining bits)
 * Result: 10-bit value in rx[1] (low 2 bits) and rx[2] (8 bits).
 */
static int read_mcp3008(int channel, int *out_value)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }
    if (g_spi_handle < 0) {
        fprintf(stderr, "SPI handle invalid\n");
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "spiXfer failed on channel %d (ret=%d): %s\n",
                channel, ret, strerror(errno));
        return -1;
    }

    *out_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Voltage conversion                                                  */
/* ------------------------------------------------------------------ */
static float voltage_from_raw(int raw)
{
    /* MCP3008 is 10-bit, VREF = 3.3 V */
    return (raw / 1023.0f) * 3.3f;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_data(int channel, float voltage)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_utc;
    if (gmtime_r(&now, &tm_utc) == NULL) {
        fprintf(stderr, "gmtime_r() failed\n");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }

    if (fprintf(g_log_file, "%s,%d,%.3f\n", ts, channel, voltage) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- open SPI --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (channel %d, %d Hz): %s\n",
                SPI_CHANNEL, SPI_SPEED, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- open log file --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "Timestamp,Channel,Voltage\n");
        fflush(g_log_file);
    }

    /* --- signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MCP3008 reader started. Logging to %s every %d ms.\n",
           LOG_FILE, SAMPLE_PERIOD / 1000);
    printf("Press Ctrl+C to stop.\n");

    /* --- main loop --- */
    while (g_running) {
        int raw[NUM_CHANNELS];
        int ok = 1;

        for (int i = 0; i < NUM_CHANNELS; i++) {
            if (read_mcp3008(i, &raw[i]) != 0) {
                fprintf(stderr, "SPI read failed on channel %d; retrying next cycle.\n", i);
                ok = 0;
                break;
            }
        }

        if (!ok) {
            gpioDelay(SAMPLE_PERIOD);
            continue;
        }

        float voltages[NUM_CHANNELS];
        for (int i = 0; i < NUM_CHANNELS; i++)
            voltages[i] = voltage_from_raw(raw[i]);

        for (int i = 0; i < NUM_CHANNELS; i++) {
            if (log_data(i, voltages[i]) != 0) {
                fprintf(stderr, "Logging failed for channel %d; continuing.\n", i);
            }
        }

        gpioDelay(SAMPLE_PERIOD);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

