    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }

    if (fprintf(g_log_file, "%s,%d,%.3f\n", ts, channel, voltage) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- open SPI --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (channel %d, %d Hz): %s\n",
                SPI_CHANNEL, SPI_SPEED, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- open log file --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "Timestamp,Channel,Voltage\n");
        fflush(g_log_file);
    }

    /* --- signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MCP3008 reader started. Logging to %s every %d ms.\n",
           LOG_FILE, SAMPLE_PERIOD / 1000);
    printf("Press Ctrl+C to stop.\n");

    /* --- main loop --- */
    while (g_running) {
        int raw[NUM_CHANNELS];
        int ok = 1;

        for (int i = 0; i < NUM_CHANNELS; i++) {
            if (read_mcp3008(i, &raw[i]) != 0) {
                fprintf(stderr, "SPI read failed on channel %d; retrying next cycle.\n", i);
                ok = 0;
                break;
            }
        }

        if (!ok) {
            gpioDelay(SAMPLE_PERIOD);
            continue;
        }

        float voltages[NUM_CHANNELS];
        for (int i = 0; i < NUM_CHANNELS; i++)
            voltages[i] = voltage_from_raw(raw[i]);

        for (int i = 0; i < NUM_CHANNELS; i++) {
            if (log_data(i, voltages[i]) != 0) {
                fprintf(stderr, "Logging failed for channel %d; continuing.\n", i);
            }
        }

        gpioDelay(SAMPLE_PERIOD);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

