/*
 * Door lock controller for Raspberry Pi 5 (Bookworm, kernel 6.6+)
 *
 * Hardware:
 *   - ADS1115 ADC on /dev/i2c-1 (I2C slave address 0x48)
 *       SDA -> GPIO2 (BCM), SCL -> GPIO3 (BCM), A0 -> GP2Y0A21YK0F analog out
 *   - 5 V relay module on GPIO17 (BCM), active-high
 *   - Magnetic reed switch on GPIO27 (BCM), active-low (pull-up enabled)
 *
 * Behavior:
 *   - Calibrate baseline distance (10 samples, 50 ms apart) on GP2Y0A21YK0F
 *   - Sample ADS1115 channel 0 every 200 ms; when distance < threshold
 *     energize relay for 3 s, then read reed sensor and log event
 *   - On SIGINT/SIGTERM: de-energize relay, release I2C, close log, exit
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADS1115_ADDR   0x48

#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG     0x01

/* Config: single-shot, AIN0 single-ended, +/-4.096 V, 128 SPS, no comparator */
#define ADS1115_CFG_BASE 0x8000 | (0x4000) | (0x0000) | (0x0100) | (0x0080) | (0x0003)

#define RELAY_GPIO      17
#define REED_GPIO       27

#define LOG_FILE        "/var/log/door_events.log"
#define SAMPLE_PERIOD_US 200000   /* 200 ms */
#define CALIB_SAMPLES   10
#define CALIB_DELAY_US  50000     /* 50 ms */
#define RELAY_PULSE_US  3000000   /* 3 s */
#define THRESHOLD_US    1000      /* 1 ms */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write16(int fd, uint8_t reg, uint16_t val)
{
    uint8_t buf[3] = { reg, (uint8_t)(val >> 8), (uint8_t)(val & 0xFF) };
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "i2c_write16(0x%02X, 0x%04X) failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t reg_buf = reg;
    if (write(fd, &reg_buf, 1) != 1) {
        fprintf(stderr, "i2c_read16 write(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    uint8_t data[2];
    ssize_t n = read(fd, data, 2);
    if (n != 2) {
        fprintf(stderr, "i2c_read16 read(0x%02X) failed: got %zd bytes: %s\n",
                reg, n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }
    *out = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* ADS1115                                                             */
/* ------------------------------------------------------------------ */
static int ads1115_read(int fd, int16_t *out)
{
    uint16_t cfg = ADS1115_CFG_BASE;
    if (i2c_write16(fd, ADS1115_REG_CONFIG, cfg) < 0)
        return -1;

    /* Wait for conversion to complete (~8 ms at 128 SPS) */
    usleep(10000);

    uint16_t raw;
    if (i2c_read16(fd, ADS1115_REG_CONVERSION, &raw) < 0)
        return -1;

    *out = (int16_t)raw;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Calibration                                                         */
/* ------------------------------------------------------------------ */
static int calibrate(int fd, int *baseline)
{
    printf("Calibrating baseline distance (Ctrl-C to stop)...\n");
    long sum = 0;
    int valid = 0;

    for (int i = 0; i < CALIB_SAMPLES && g_running; i++) {
        int16_t v;
        if (ads1115_read(fd, &v) < 0) {
            fprintf(stderr, "Calibration read %d failed: I2C error\n", i);
            continue;
        }
        sum += v;
        valid++;
        usleep(CALIB_DELAY_US);
    }

    if (valid == 0) {
        fprintf(stderr, "Calibration failed: no valid samples\n");
        return -1;
    }

    *baseline = (int)(sum / valid);
    printf("Baseline distance: %d\n", *baseline);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Relay control                                                      */
/* ------------------------------------------------------------------ */
static void relay_on(void)
{
    if (g_i2c_fd < 0) {
        /* Assume relay is directly driven via GPIO; if I2C is open
         * we still drive the line. */
        if (g_log) {
            fprintf(g_log, "Relay ON\n");
            fflush(g_log);
        }
        if (g_i2c_fd >= 0) {
            /* Write GPIO17 high via I2C (if we have a bus) */
            uint8_t buf[3] = { RELAY_GPIO, 0x01, 0x00 };
            if (write(g_i2c_fd, buf, 3) != 3)
                fprintf(stderr, "I2C write relay ON failed: %s\n", strerror(errno));
        }
    }
}

static void relay_off(void)
{
    if (g_i2c_fd < 0) {
        if (g_log) {
            fprintf(g_log, "Relay OFF\n");
            fflush(g_log);
        }
        /* If I2C is open, drive GPIO17 low */
        if (g_i2c_fd >= 0) {
            uint8_t buf[3] = { RELAY_GPIO, 0x00, 0x00 };
            if (write(g_i2c_fd, buf, 3) != 3)
                fprintf(stderr, "I2C write relay OFF failed: %s\n", strerror(errno));
        }
    }
}

/* ------------------------------------------------------------------ */
/* Reed sensor (active-low)                                            */
/* ------------------------------------------------------------------ */
static int reed_read(void)
{
    if (g_i2c_fd < 0) {
        /* Assume relay drives GPIO directly; if I2C is open, drive
         * GPIO27 low. */
        if (g_i2c_fd >= 0) {
            uint8_t buf[3] = { REED_GPIO, 0x00, 0x00 };
            if (write(g_i2c_fd, buf, 3) != 3)
                fprintf(stderr, "I2C write reed LOW failed: %s\n", strerror(errno));
        }
        return 0; /* assume open */
    }
    return 0; /* I2C not used for reed */
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_event(const char *event)
{
    if (!g_log) return;

    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
        fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
        return;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char ts_str[32];
    strftime(ts_str, sizeof(ts_str), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(g_log, "%s.%03ld: %s\n", ts_str, ts.tv_nsec / 1000000, event);
    fflush(g_log);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    /* Open log file */
    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return 1;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        fclose(g_log);
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n",
                ADS1115_ADDR, strerror(errno));
        close(g_i2c_fd);
        fclose(g_log);
        return 1;
    }

    /* Calibrate */
    if (calibrate(g_i2c_fd, NULL) < 0) {
        fprintf(stderr, "Calibration failed; aborting.\n");
        close(g_i2c_fd);
        fclose(g_log);
        return 1;
    }

    /* Configure relay GPIO via I2C (GPIO17) */
    if (g_i2c_fd >= 0) {
        uint8_t buf[3] = { RELAY_GPIO, 0x00, 0x00 }; /* ensure low */
        if (write(g_i2c_fd, buf, 3) != 3)
            fprintf(stderr, "Initial relay GPIO setup failed: %s\n", strerror(errno));
    }

    /* Configure reed GPIO via I2C (GPIO27) */
    if (g_i2c_fd >= 0) {
        uint8_t buf[3] = { REED_GPIO, 0x00, 0x00 }; /* ensure low (open) */
        if (write(g_i2c_fd, buf, 3) != 3)
            fprintf(stderr, "Initial reed GPIO setup failed: %s\n", strerror(errno));
    }

    printf("Monitoring started. Press Ctrl-C to exit.\n");

    int baseline = 0;
    if (g_i2c_fd >= 0)
        baseline = (int)(ads1115_read(g_i2c_fd, NULL) + 0.5);

    while (g_running) {
        int16_t raw;
        if (ads1115_read(g_i2c_fd, &raw) < 0) {
            fprintf(stderr, "ADC read failed; skipping cycle\n");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        int distance = (int)raw;
        if (distance < baseline + THRESHOLD_US) {
            printf("Distance %d < baseline %d; activating relay\n",
                   distance, baseline);
            relay_on();
            usleep(RELAY_PULSE_US);
            relay_off();

            int reed = reed_read();
            if (reed == 0) {
                log_event("door opened");
            } else {
                log_event("door not opened");
            }
        }

        usleep(SAMPLE_PERIOD_US);
    }

    /* Cleanup */
    relay_off();
    if (g_i2c_fd >= 0)
        close(g_i2c_fd);
    if (g_log) {
        fclose(g_log);
        g_log = NULL;
    }
    printf("Shutdown complete.\n");
    return 0;
}

