/*
 * soil_moisture_logger.c
 *
 * Raspberry Pi 5 — three MCP3008 ADCs (soil moisture sensors) via shared
 * SPI0 (MOSI=GPIO10, MISO=GPIO9, SCLK=GPIO11), manual CS control on
 * GPIO8, GPIO7, GPIO25.  Logs to soil_moisture_log.csv every 5 s.
 *
 * Build:  gcc -O2 -Wall -Wextra -o soil_moisture_logger soil_moisture_logger.c
 * Run:    ./soil_moisture_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define NUM_CHIPS      3
#define SPI_DEVICE     "/dev/spidev0.0"
#define SPI_SPEED_HZ   1000000U
#define SPI_MODE       0
#define SPI_BITS       8
#define LOG_FILE       "soil_moisture_log.csv"
#define SAMPLE_PERIOD  5          /* seconds between samples */
#define CS_PIN_OFFSET  8          /* GPIO8 = CS0 */

static volatile sig_atomic_t g_running = 1;

/* ---- signal handler ---------------------------------------------------- */
static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ---- MCP3008 single-ended read ---------------------------------------- */
/*
 * MCP3008 SPI protocol (Mode 0, MSB-first):
 *   tx[0] = 0x01                       start bit
 *   tx[1] = (0x08 | channel) << 4      SGL/DIFF=1 (single-ended) + channel
 *   tx[2] = 0x00                       padding
 *   rx[1] bits 1..0  + rx[2] bits 7..0  -> 10-bit result
 */
static int mcp3008_read(int spi_fd, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = sizeof(tx);
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    int value = ((rx[1] & 0x03) << 8) | rx[2];
    return value;                       /* 0..1023 */
}

/* ---- CSV logging ------------------------------------------------------- */
static int log_open(const char *path)
{
    int fd = open(path, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", path, strerror(errno));
        return -1;
    }
    if (lseek(fd, 0, SEEK_END) == 0) {
        /* file is new/empty — write header */
        if (fputs("timestamp,sensor1,sensor2,sensor3\n", fd) == EOF) {
            fprintf(stderr, "fputs(header) failed: %s\n", strerror(errno));
            close(fd);
            return -1;
        }
    }
    return fd;
}

static void log_sample(FILE *fp, int v1, int v2, int v3)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%d,%d,%d\n", ts, v1, v2, v3);
    fflush(fp);
}

/* ---- main ---------------------------------------------------------------- */
int main(void)
{
    /* ---- signal handling ----------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- open SPI device ----------------------------------------------- */
    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", SPI_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        close(spi_fd);
        return EXIT_FAILURE;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        close(spi_fd);
        return EXIT_FAILURE;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        close(spi_fd);
        return EXIT_FAILURE;
    }

    /* ---- manual chip-select lines -------------------------------------- */
    int cs_pins[NUM_CHIPS] = { CS_PIN_OFFSET, CS_PIN_OFFSET - 1, CS_PIN_OFFSET - 2 };
    for (int i = 0; i < NUM_CHIPS; i++) {
        if (ioctl(spi_fd, SPI_IOC_WR_CS_CHANGE, &i) < 0) {
            fprintf(stderr, "SPI_IOC_WR_CS_CHANGE failed for chip %d: %s\n",
                    i, strerror(errno));
            close(spi_fd);
            return EXIT_FAILURE;
        }
    }

    /* ---- open CSV file ----------------------------------------------- */
    int log_fd = log_open(LOG_FILE);
    if (log_fd < 0) {
        close(spi_fd);
        return EXIT_FAILURE;
    }

    /* ---- main sampling loop ------------------------------------------- */
    while (g_running) {
        int v[NUM_CHIPS];
        for (int i = 0; i < NUM_CHIPS; i++) {
            if (mcp3008_read(spi_fd, i) < 0) {
                v[i] = -1;
            } else {
                v[i] = mcp3008_read(spi_fd, i);
            }
        }
        log_sample(log_fd, v[0], v[1], v[2]);
        sleep(SAMPLE_PERIOD);
    }

    /* ---- graceful shutdown -------------------------------------------- */
    if (log_fd >= 0) {
        fclose(log_fd);
    }
    close(spi_fd);
    return EXIT_SUCCESS;
}

