/*
 * Raspberry Pi 4 Model B – Vegetronix VH400 soil-moisture monitor
 *
 * Hardware:
 *   MCP3008 ADC on SPI0 (CE0 = GPIO 8, 1 MHz, mode 0)
 *     VH400 analog output wired to MCP3008 channel 0
 *   Relay-driven water pump on GPIO 18 (BCM, active-high)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o irrigation irrigation.c -lpigpio -lrt
 *   (pigpio must be installed; run as root or with appropriate permissions.)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <getopt.h>
#include <pigpio.h>

#define DEFAULT_THRESHOLD      30.0f   /* percent of 0-3 V range */
#define DEFAULT_PUMP_DURATION 10       /* seconds */
#define DEFAULT_SLEEP_INTERVAL 60      /* seconds */
#define MAX_RETRIES            3
#define SPI_CHANNEL            0       /* CE0 */
#define SPI_SPEED              1000000 /* 1 MHz */
#define SPI_FLAGS              0       /* mode 0, active-low CE */
#define PUMP_GPIO              18
#define ADC_CHANNEL            0       /* MCP3008 channel 0 */
#define ADC_MAX_VALUE          1023    /* 10-bit ADC */
#define ADC_VREF               3.3f    /* ADC reference voltage */
#define VH400_V_MIN            0.0f    /* VH400 output at dry soil */
#define VH400_V_MAX            3.0f    /* VH400 output at fully wet soil */
#define LOG_FILE               "irrigation.log"

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* ------------------------------------------------------------------ */
/* Logging                                                            */
/* ------------------------------------------------------------------ */
static void log_event(const char *msg)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(log)");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    } else {
        fprintf(fp, "[unknown time] %s\n", msg);
    }
    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Signal handling                                                    */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* MCP3008 read with retry                                          */
/* ------------------------------------------------------------------ */
/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (single-ended + channel, upper nibble)
 *   tx[2] = 0x00                       (clock out remaining bits)
 *   rx[1] bits 1..0 + rx[2] bits 7..0  -> 10-bit result
 */
static int read_mcp3008(int channel, int *out_value)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }
    if (out_value == NULL) {
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    for (int attempt = 1; attempt <= MAX_RETRIES; ++attempt) {
