/*
 * sound_peak_detector.c
 *
 * Raspberry Pi 3 Model B+ — MAX4466 electret microphone amplifier
 *  -> MCP3008 ADC (SPI0, CE0/GPIO8, CLK/GPIO11, MOSI/GPIO10, MISO/GPIO9)
 *  -> channel 0
 *
 * Build:  gcc -O2 -Wall -Wextra -o sound_peak_detector sound_peak_detector.c
 * Run:    ./sound_peak_detector
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U   /* 1 MHz — well within MCP3008 3.3 V limit */
#define SPI_BITS        8
#define SPI_MODE        SPI_MODE_0

#define ADC_CHANNEL     0
#define LOG_FILE        "/var/log/sound_events.log"
#define SAMPLE_PERIOD_US 10000U   /* 10 ms */
#define PEAK_WINDOW     100        /* 100 samples for dynamic threshold */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_event(int sample_value)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("time()");
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime: buffer too small\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s, Sample Value: %d\n", ts, sample_value) < 0) {
        perror("fprintf");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* MCP3008 single-ended read                                          */
/* ------------------------------------------------------------------ */
/*
 * MCP3008 SPI protocol (Mode 0, MSB-first):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (single-ended + channel, upper nibble)
 *   tx[2] = 0x00                       (clock out remaining bits)
 *   rx[1] bits 1..0  + rx[2] bits 7..0
 *   10-bit result = ((rx[1] & 0x03) << 8) | rx[2]
 */
static int mcp3008_read(int spi_fd, uint8_t channel)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid ADC channel %u\n", channel);
        return -1;
    }

    uint8_t tx[3] = {
        0x01,
        (uint8_t)((0x08 | channel) << 4),
        0x00
    };
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = sizeof(tx);
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("ioctl(SPI_IOC_MESSAGE)");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

/* ------------------------------------------------------------------ */
/* Dynamic threshold peak detection                                   */
/* ------------------------------------------------------------------ */
static int detect_peak(int sample_value, int *peak_history, int history_len,
                       int *peak_count, int *peak_index)
{
    if (sample_value > *peak_history) {
        *peak_history = sample_value;
        *peak_index  = (*peak_count == 0) ? 0 : (*peak_index + 1) % history_len;
        (*peak_count)++;
        return 1;
    }
    (*peak_count) = 0;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int spi_fd = -1;
    int ret_code = EXIT_FAILURE;

    if (install_signal_handlers() != 0) {
        goto cleanup;
    }

    /* Open SPI device */
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open(" SPI_DEVICE ")");
        goto cleanup;
    }

    /* Configure SPI mode */
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl(SPI_IOC_WR_MODE)");
        goto cleanup;
    }

    /* Configure SPI bits per word */
    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl(SPI_IOC_WR_BITS_PER_WORD)");
        goto cleanup;
    }

    /* Configure SPI max speed */
    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl(SPI_IOC_WR_MAX_SPEED_HZ)");
        goto cleanup;
    }

    printf("Sound peak detection started. Logging to %s\n", LOG_FILE);
    printf("Sampling MCP3008 channel %u at %u Hz, window %d samples.\n",
           ADC_CHANNEL, SPI_SPEED_HZ / 1000U, PEAK_WINDOW);

    int peak_history[PEAK_WINDOW];
    memset(peak_history, 0, sizeof(peak_history));
    int peak_count = 0;
    int peak_index = 0;

    while (g_running) {
        int sample_value = mcp3008_read(spi_fd, ADC_CHANNEL);
        if (sample_value < 0) {
            fprintf(stderr, "ADC read failed; continuing.\n");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        if (detect_peak(sample_value, peak_history, PEAK_WINDOW,
                         &peak_count, &peak_index)) {
            if (log_event(sample_value) != 0) {
                fprintf(stderr, "Failed to log peak event.\n");
            } else {
                printf("Peak detected: %d\n", sample_value);
            }
        }

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly.\n");
    ret_code = EXIT_SUCCESS;

cleanup:
    if (spi_fd >= 0) {
        if (close(spi_fd) != 0) {
            perror("close(spi_fd)");
        }
    }
    return ret_code;
}

