#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define PCF8591_ADDR   0x40
#define PCF8591_REG    0x00
#define PCF8591_CH0    0x01

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_sigint_handler(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return -1;
    }
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_write_reg8(0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t *val)
{
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    if (install_sigint_handler() == -1)
        goto cleanup;

    fd = open(I2C_BUS, O_RDWR);
    if (fd == -1) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        goto cleanup;
    }

    if (ioctl(fd, I2C_SLAVE, PCF8591_ADDR) == -1) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                PCF8591_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Dummy write so the PCF8591 returns the result of the *previous* conversion. */
    if (i2c_write_reg8(fd, PCF8591_REG) == -1)
        goto cleanup;

    while (g_running) {
        uint8_t dummy;
        if (i2c_read_reg8(fd, &dummy) == -1)
            goto cleanup;

        uint8_t ch0;
        if (i2c_read_reg8(fd, &ch0) == -1)
            goto cleanup;

        printf("AIN0: %3u\n", ch0);
        fflush(stdout);

        usleep(100000);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fd != -1)
        close(fd);
    return rc;
}

