#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01
#define GPIO_PIN 27
#define BUFFER_SIZE 10
#define THRESHOLD_GAUSS 500.0
#define ADC_MAX 32767.0
#define ADC_VREF 3.3
#define SAMPLE_RATE_HZ 1
#define SAMPLE_DELAY_US (1000000 / SAMPLE_RATE_HZ)

#define CONFIG_OS_SINGLE 0x8000
#define CONFIG_MUX_AIN0 0x4000
#define CONFIG_PGA_4_096V 0x0200
#define CONFIG_MODE_SINGLE 0x0100
#define CONFIG_DR_128SPS 0x0080

typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static CircularBuffer gauss_buffer;
static int buffer_initialized = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus %d at addr 0x%02X: %s",
               I2C_BUS, ADS1115_ADDR, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_gpio(void) {
    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO%d as output: %s",
               GPIO_PIN, strerror(errno));
        return -1;
    }
    if (gpioWrite(GPIO_PIN, 0) != 0) {
        syslog(LOG_ERR, "Failed to initialize GPIO%d LOW: %s",
               GPIO_PIN, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_circular_buffer(void) {
    gauss_buffer.head = 0;
    gauss_buffer.count = 0;
    memset(gauss_buffer.buffer, 0, sizeof(gauss_buffer.buffer));
    buffer_initialized = 1;
    return 0;
}

static int read_ads1115(int16_t *raw) {
    uint16_t config = CONFIG_OS_SINGLE | CONFIG_MUX_AIN0 |
                      CONFIG_PGA_4_096V | CONFIG_MODE_SINGLE |
                      CONFIG_DR_128SPS;

    char config_buf[3];
    config_buf[0] = ADS1115_REG_CONFIG;
    config_buf[1] = (config >> 8) & 0xFF;
    config_buf[2] = config & 0xFF;

    if (i2cWriteDevice(i2c_handle, config_buf, 3) != 0) {
        syslog(LOG_ERR, "Failed to write ADS1115 config: %s",
               strerror(errno));
        return -1;
    }

    gpioDelay(10000);

    char reg_buf[1] = {ADS1115_REG_CONVERSION};
    if (i2cWriteDevice(i2c_handle, reg_buf, 1) != 0) {
        syslog(LOG_ERR, "Failed to set ADS1115 conversion register pointer: %s",
               strerror(errno));
        return -1;
    }

    char read_buf[2];
    if (i2cReadDevice(i2c_handle, read_buf, 2) != 2) {
        syslog(LOG_ERR, "Failed to read ADS1115 conversion: %s",
               strerror(errno));
        return -1;
    }

    *raw = (int16_t)((read_buf[0] << 8) | read_buf[1]);
    return 0;
}

static float convert_to_gauss(int16_t raw) {
    float voltage = (raw / ADC_MAX) * ADC_VREF;
    if (voltage < 0.0f || voltage > ADC_VREF) {
        syslog(LOG_WARNING, "Voltage out of range: %.3f V", voltage);
        return 0.0f;
    }
    return voltage * 100.0f;
}

static void update_circular_buffer(float gauss) {
    if (buffer_initialized) {
        gauss_buffer.buffer[gauss_buffer.head] = gauss;
        gauss_buffer.head = (gauss_buffer.head + 1) % BUFFER_SIZE;
        if (gauss_buffer.count < BUFFER_SIZE) {
            gauss_buffer.count++;
        }
    }
}

static float calculate_average(void) {
    if (!buffer_initialized || gauss_buffer.count == 0) {
        return 0.0f;
    }
    float sum = 0.0f;
    for (int i = 0; i < gauss_buffer.count; i++) {
        sum += gauss_buffer.buffer[i];
    }
    return sum / gauss_buffer.count;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(GPIO_PIN, 0);
    gpioTerminate();
    closelog();
}

int main(void) {
    openlog("hall_sensor_monitor", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to set signal handlers: %s", strerror(errno));
        closelog();
        return 1;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialization failed: %s", strerror(errno));
        closelog();
        return 1;
    }

    if (init_i2c() != 0 || init_gpio() != 0) {
        cleanup();
        return 1;
    }

    if (init_circular_buffer() != 0) {
        cleanup();
        return 1;
    }

    syslog(LOG_INFO, "Hall sensor monitoring started (threshold: %.1f Gauss)",
           THRESHOLD_GAUSS);

    while (running) {
        int16_t raw;
        if (read_ads1115(&raw) == 0) {
            float gauss = convert_to_gauss(raw);
            update_circular_buffer(gauss);
            float avg = calculate_average();

            if (avg > THRESHOLD_GAUSS) {
                syslog(LOG_WARNING, "Threshold exceeded: %.2f Gauss (avg: %.2f Gauss)",
                       gauss, avg);
                if (gpioWrite(GPIO_PIN, 1) != 0) {
                    syslog(LOG_ERR, "Failed to set GPIO%d HIGH: %s",
                           GPIO_PIN, strerror(errno));
                }
            } else {
                if (gpioWrite(GPIO_PIN, 0) != 0) {
                    syslog(LOG_ERR, "Failed to set GPIO%d LOW: %s",
                           GPIO_PIN, strerror(errno));
                }
            }
        } else {
            syslog(LOG_ERR, "ADC read failed, skipping sample");
        }

        gpioDelay(SAMPLE_DELAY_US);
    }

    syslog(LOG_INFO, "Shutting down...");
    cleanup();
    return 0;
}

