/*
 * Raspberry Pi Zero W – Vegetronix VH400 soil moisture monitor
 *
 * Hardware:
 *   - MCP3008 ADC on SPI0 CE0 (CE0 = GPIO8), 1 MHz, SPI mode 0
 *   - Vegetronix VH400 sensor on MCP3008 channel 0
 *   - Relay-driven water pump on GPIO18 (BCM)
 *
 * Behavior:
 *   - Polls the ADC every 60 s; when the 10-bit reading drops below
 *     threshold 300, the pump runs for 10 s, the event is logged, and
 *     the pump is turned off.
 *   - SIGINT / SIGTERM → pump off, SPI closed, resources released, exit.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U
#define SPI_MODE        SPI_MODE_0
#define SPI_BITS        8
#define ADC_CHANNEL     0
#define MOISTURE_THRESHOLD 300
#define PUMP_GPIO       18
#define PUMP_DURATION_S 10
#define POLL_INTERVAL_S 60
#define LOG_FILE        "watering_events.txt"

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;
static int g_pump_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* SPI helpers                                                         */
/* ------------------------------------------------------------------ */
static int spi_init(void)
{
    uint8_t mode = SPI_MODE;
    uint8_t bits = SPI_BITS;
    uint32_t speed = SPI_SPEED_HZ;

    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        perror("open(" SPI_DEVICE ")");
        return -1;
    }

    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl(SPI_IOC_WR_MODE)");
        goto fail;
    }
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl(SPI_IOC_WR_BITS_PER_WORD)");
        goto fail;
    }
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl(SPI_IOC_WR_MAX_SPEED_HZ)");
        goto fail;
    }
    return 0;

fail:
    close(g_spi_fd);
    g_spi_fd = -1;
    return -1;
}

/*
 * MCP3008 single-ended read.
 * 3-byte transfer: [start] [SGL|D2|D1|D0|0|0|0|0|0|0] [0x00]
 * Result: bits 9..0 are in rx[1] (low 2 bits) and rx[2] (8 bits).
 */
static int mcp3008_read(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = {
        0x01,
        (uint8_t)((0x08 | channel) << 4),
        0x00
    };
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = 3;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("ioctl(SPI_IOC_MESSAGE)");
        return -1;
    }

    int adc = ((rx[1] & 0x03) << 8) | rx[2];
    return adc;
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */
static int gpio_init(void)
{
    int fd = open("/dev/gpiochip0", O_RDWR);
    if (fd < 0) {
        perror("open(/dev/gpiochip0)");
        return -1;
    }

    if (ioctl(fd, GPIO_GET_LINE_VALUE, PUMP_GPIO) < 0) {
        /* GPIO not yet configured – treat as absent */
    }

    if (ioctl(fd, GPIO_SET_LINE_MODE, PUMP_GPIO, GPIOD_LINE_MODE_OUTPUT) < 0) {
        perror("ioctl(GPIO_SET_LINE_MODE)");
        close(fd);
        return -1;
    }

    if (ioctl(fd, GPIO_SET_LINE_VALUE, PUMP_GPIO, GPIOD_LINE_VALUE_INACTIVE) < 0) {
        perror("ioctl(GPIO_SET_LINE_VALUE)");
        close(fd);
        return -1;
    }

    g_pump_fd = fd;
    return 0;
}

static int gpio_write(int value)
{
    if (g_pump_fd < 0) {
        return -1;
    }
    if (ioctl(g_pump_fd, GPIO_SET_LINE_VALUE, PUMP_GPIO, value) < 0) {
        perror("ioctl(GPIO_SET_LINE_VALUE)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_event(int moisture_level)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d - Moisture: %d\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, moisture_level);
    } else {
        fprintf(fp, "[timestamp error] - Moisture: %d\n", moisture_level);
    }

    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_pump_fd >= 0) {
        (void)gpio_write(GPIOD_LINE_VALUE_INACTIVE);
        close(g_pump_fd);
        g_pump_fd = -1;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (spi_init() < 0) {
        return EXIT_FAILURE;
    }

    if (gpio_init() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int moisture = mcp3008_read(ADC_CHANNEL);

        if (moisture < 0) {
            fprintf(stderr, "ADC read error – skipping cycle\n");
        } else if (moisture < MOISTURE_THRESHOLD) {
            printf("Moisture below threshold (%d < %d). Activating pump.\n",
                   moisture, MOISTURE_THRESHOLD);

            if (gpio_write(GPIOD_LINE_VALUE_ACTIVE) < 0) {
                fprintf(stderr, "Failed to activate pump\n");
            } else {
                log_event(moisture);

                /* Sleep in 1 s increments so SIGINT is caught promptly. */
                for (int i = 0; i < PUMP_DURATION_S && g_running; i++) {
                    sleep(1);
                }

                if (gpio_write(GPIOD_LINE_VALUE_INACTIVE) < 0) {
                    fprintf(stderr, "Failed to deactivate pump\n");
                } else {
                    printf("Pump deactivated.\n");
                }
            }
        }

        /* Sleep in 1 s increments so SIGINT is caught promptly. */
        for (int i = 0; i < POLL_INTERVAL_S && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

