/*
 * YL-83 rain sensor reader via MCP3008 ADC on Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V (pin 1)
 *   MCP3008 VREF -> 3.3 V (pin 1)
 *   MCP3008 AGND -> GND
 *   MCP3008 DGND -> GND
 *   MCP3008 CLK  -> GPIO11 (SPI0 SCLK, pin 23)
 *   MCP3008 DOUT -> GPIO9  (SPI0 MISO, pin 21)
 *   MCP3008 DIN  -> GPIO10 (SPI0 MOSI, pin 19)
 *   MCP3008 CS   -> GPIO8  (SPI0 CE0,  pin 24)
 *   MCP3008 CH0  -> YL-83 analog output (0 V = dry, 3.3 V = wet)
 *
 * Build:  gcc -O2 -Wall -Wextra -o rain_sensor rain_sensor.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#include <linux/spi/spidev.h>
#include <fcntl.h>
#include <sys/ioctl.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U   /* 1 MHz */
#define SPI_BITS        8
#define SPI_MODE        SPI_MODE_0

#define ADC_CHANNEL     0          /* MCP3008 single-ended channel 0 */
#define ADC_MAX_VALUE   1023       /* 10-bit ADC */
#define VREF            3.3f       /* MCP3008 VREF tied to 3.3 V */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/*
 * Read a single-ended sample from the MCP3008.
 * Returns 0 on success and stores the 10-bit result in *out_value.
 * Returns -1 on SPI transfer failure.
 */
static int mcp3008_read(int spi_fd, uint8_t channel, uint16_t *out_value)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid channel %u (must be 0-7)\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: rx[1] low 2 bits + rx[2] 8 bits = 10-bit value.
     */
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = sizeof(tx);
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    uint16_t value = ((uint16_t)(rx[1] & 0x03) << 8) | rx[2];
    *out_value = value;
    return 0;
}

static void log_data(uint16_t adc_value)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    float intensity = (float)adc_value / (float)ADC_MAX_VALUE * VREF;
    if (intensity < 0.0f) intensity = 0.0f;
    if (intensity > 1.0f) intensity = 1.0f;

    printf("%s  ADC: %4u  Intensity: %.2f\n", timestamp, adc_value, intensity);
    fflush(stdout);
}

int main(void)
{
    int spi_fd = -1;
    int ret_code = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", SPI_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        goto cleanup;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        goto cleanup;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Rain sensor monitoring started on %s (mode %u, %u bits, %u Hz).\n",
           SPI_DEVICE, mode, bits, speed);
    printf("Press Ctrl-C to exit.\n");
    fflush(stdout);

    while (g_running) {
        uint16_t adc_value = 0;

        if (mcp3008_read(spi_fd, ADC_CHANNEL, &adc_value) < 0) {
            fprintf(stderr, "SPI read error; retrying next cycle.\n");
        } else {
            log_data(adc_value);
        }

        sleep(1);
    }

    printf("\nShutting down gracefully.\n");
    ret_code = EXIT_SUCCESS;

cleanup:
    if (spi_fd >= 0) {
        if (close(spi_fd) < 0) {
            fprintf(stderr, "close(spi_fd) failed: %s\n", strerror(errno));
            ret_code = EXIT_FAILURE;
        }
    }
    return ret_code;
}

