code:
/*
 * Honeywell SS49E Hall-Effect Sensor Monitor via ADS1115 ADC
 * Board:  Raspberry Pi 4 Model B
 * Bus:    I2C bus 1 (GPIO2 = SDA, GPIO3 = SCL)
 * ADC:    ADS1115 at I2C address 0x48
 * Sensor: Honeywell SS49E (linear, 0.5 mT/G typical)
 * LED:    GPIO17 (BCM)
 *
 * Build:  gcc -O2 -Wall -o ss49e_monitor ss49e_monitor.c -lpigpio -lrt
 * Run:    sudo ./ss49e_monitor [-t threshold_gauss]
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <getopt.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define ADS1115_ADDR         0x48
#define ADS1115_REG_CONV     0x00
#define ADS1115_REG_CONFIG   0x01

#define LED_GPIO             17
#define DEFAULT_THRESHOLD    100.0f   /* Gauss */
#define SAMPLE_PERIOD_US     100000   /* 100 ms */
#define BLINK_DURATION_US    1000000  /* 1 s total (50 ms on + 50 ms off) */
#define BLINK_HALF_PERIOD_US 50000    /* 50 ms */

/* ADS1115 config bits */
#define ADS1115_OS_BEGIN     0x8000
#define ADS1115_MUX_AIN0_GND 0x4000
#define ADS1115_PGA_4_096V   0x0200
#define ADS1115_MODE_SINGLE  0x0100
#define ADS1115_DR_128SPS    0x0080
#define ADS1115_CQUE_NONE    0x0003

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static float g_threshold = DEFAULT_THRESHOLD;

/* --------------------------- Function prototypes ------------------------- */
static int  ads1115_init(int handle);
static int  ads1115_read(int handle, int16_t *raw);
static float raw_to_gauss(int16_t raw);
static void blink_led(int gpio, int duration_us);
static void signal_handler(int sig);
static void cleanup(int handle);

/* ------------------------------- Main ------------------------------------ */
int main(int argc, char *argv[])
{
    int opt;
    int i2c_handle = -1;

    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                g_threshold = (float)atof(optarg);
                if (g_threshold <= 0.0f) {
                    fprintf(stderr, "Threshold must be positive.\n");
                    return EXIT_FAILURE;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold_gauss]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output.\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* Open I2C bus to ADS1115 */
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X: %s\n",
                I2C_BUS, ADS1115_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize ADS1115 */
    if (ads1115_init(i2c_handle) != 0) {
        fprintf(stderr, "ADS1115 initialization failed.\n");
        cleanup(i2c_handle);
        return EXIT_FAILURE;
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Monitoring SS49E sensor on ADS1115 (I2C bus %d, addr 0x%02X). "
           "Threshold: %.2f Gauss. Press Ctrl+C to exit.\n",
           I2C_BUS, ADS1115_ADDR, g_threshold);

    /* Main sampling loop */
    while (g_running) {
        int16_t raw;
        if (ads1115_read(i2c_handle, &raw) == 0) {
            float gauss = raw_to_gauss(raw);
            printf("Magnetic field: %.2f Gauss\n", gauss);

            if (gauss > g_threshold) {
                printf("Threshold exceeded! Blinking LED for 1 s.\n");
                blink_led(LED_GPIO, BLINK_DURATION_US);
            }
        } else {
            fprintf(stderr, "ADC read error: %s\n", strerror(errno));
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    cleanup(i2c_handle);
    return EXIT_SUCCESS;
}

/* --------------------------- ADS1115 helpers ----------------------------- */
static int ads1115_init(int handle)
{
    uint16_t config = ADS1115_OS_BEGIN
                    | ADS1115_MUX_AIN0_GND
                    | ADS1115_PGA_4_096V
                    | ADS1115_MODE_SINGLE
                    | ADS1115_DR_128SPS
                    | ADS1115_CQUE_NONE;

    char buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;

    if (i2cWriteDevice(handle, buf, 3) != 0) {
        fprintf(stderr, "Failed to write ADS1115 config: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int ads1115_read(int handle, int16_t *raw)
{
    char reg = ADS1115_REG_CONV;
    char data[2];

    /* Point to conversion register */
    if (i2cWriteDevice(handle, &reg, 1) != 0) {
        fprintf(stderr, "Failed to set conversion register pointer: %s\n",
                strerror(errno));
        return -1;
    }

    /* Read 2 bytes */
    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "Failed to read conversion data: %s\n", strerror(errno));
        return -1;
    }

    *raw = (int16_t)(((uint16_t)data[0] << 8) | (uint8_t)data[1]);
    return 0;
}

static float raw_to_gauss(int16_t raw)
{
    /* SS49E: 0.5 mT/G typical, 1 mT/G max. 4.096 V PGA => 1 V = 2000 Gauss */
    return (float)raw * 2000.0f / 1000.0f;
}

/* ------------------------------- LED blink ------------------------------- */
static void blink_led(int gpio, int duration_us)
{
    for (int elapsed = 0; elapsed < duration_us && g_running; elapsed += BLINK_HALF_PERIOD_US) {
        gpioWrite(gpio, 1);
        gpioDelay(BLINK_HALF_PERIOD_US);
        gpioWrite(gpio, 0);
        gpioDelay(BLINK_HALF_PERIOD_US);
    }
}

/* --------------------------- Signal handler ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(int handle)
{
    if (handle >= 0) {
        i2cClose(handle);
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

