#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <errno.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_FLAGS 0
#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD_LOW 30
#define MOISTURE_THRESHOLD_HIGH 35
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "soil_moisture"
#define MQTT_CONTROL_TOPIC "pump_control"
#define SAMPLE_INTERVAL 60
#define ADC_CHANNEL 0

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static int mqtt_client_id = -1;
static int mqtt_qos = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        syslog(LOG_ERR, "Invalid ADC channel %d", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        syslog(LOG_ERR, "SPI transfer failed on channel %d", channel);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int control_pump(int state) {
    if (gpioWrite(PUMP_GPIO, state) != 0) {
        syslog(LOG_ERR, "Failed to write GPIO %d", PUMP_GPIO);
        return -1;
    }
    return 0;
}

static int publish_moisture(int moisture) {
    char payload[16];
    snprintf(payload, sizeof(payload), "%d", moisture);

    int rc = mosquitto_publish(mqtt_client_id, NULL, MQTT_TOPIC, strlen(payload), payload, MQTT_QOS, false);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT publish failed: %s", mosquitto_strerror(rc));
        return -1;
    }
    return 0;
}

static int control_pump_mqtt(int moisture) {
    if (moisture < 0 || moisture > 100) {
        syslog(LOG_ERR, "Invalid moisture value %d", moisture);
        return -1;
    }

    if (moisture < MOISTURE_THRESHOLD_LOW) {
        if (control_pump(1) == 0) {
            syslog(LOG_INFO, "Moisture low (%d%%), pump ON", moisture);
        } else {
            syslog(LOG_ERR, "Failed to turn pump ON");
        }
    } else if (moisture > MOISTURE_THRESHOLD_HIGH) {
        if (control_pump(0) == 0) {
            syslog(LOG_INFO, "Moisture high (%d%%), pump OFF", moisture);
        } else {
            syslog(LOG_ERR, "Failed to turn pump OFF");
        }
    }
    return 0;
}

static int mqtt_subscribe_callback(void *userdata, const char *topic, int qos) {
    (void)userdata;
    syslog(LOG_INFO, "Subscribed to topic: %s (QoS: %d)", topic, qos);
    return 0;
}

static int mqtt_connect_callback(void *userdata, int result) {
    (void)userdata;
    if (result == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "MQTT connected");
        if (mosquitto_subscribe(mqtt_client_id, NULL, MQTT_CONTROL_TOPIC, MQTT_QOS) != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "Failed to subscribe to control topic: %s", mosquitto_strerror(errno));
            return MOSQ_ERR_SUCCESS;
        }
        return MOSQ_ERR_SUCCESS;
    } else {
        syslog(LOG_ERR, "MQTT connect failed: %s", mosquitto_strerror(result));
        return MOSQ_ERR_SUCCESS;
    }
}

static int mqtt_disconnect_callback(void *userdata, int rc) {
    (void)userdata;
    syslog(LOG_INFO, "MQTT disconnected (rc=%d)", rc);
    return 0;
}

int main(void) {
    openlog("soil_moisture_control", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO %d as output", PUMP_GPIO);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    gpioWrite(PUMP_GPIO, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        syslog(LOG_ERR, "SPI open failed: %s", pigpio_error(spi_handle));
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    mqtt_client_id = mosquitto_new(NULL, true, NULL);
    if (!mqtt_client_id) {
        syslog(LOG_ERR, "MQTT client creation failed");
        spiClose(spi_handle);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    mosquitto_connect_callback_set(mqtt_client_id, mqtt_connect_callback);
    mosquitto_disconnect_callback_set(mqtt_client_id, mqtt_disconnect_callback);
    mosquitto_subscribe_callback_set(mqtt_client_id, mqtt_subscribe_callback);

    int rc = mosquitto_connect(mqtt_client_id, MQTT_BROKER, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT connect failed: %s", mosquitto_strerror(rc));
        mosquitto_destroy(mqtt_client_id);
        mqtt_client_id = -1;
        spiClose(spi_handle);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Soil moisture control started");

    while (running) {
        int moisture = read_mcp3008(ADC_CHANNEL);
        if (moisture < 0) {
            syslog(LOG_ERR, "Failed to read moisture sensor");
        } else {
            if (publish_moisture(moisture) != 0) {
                syslog(LOG_ERR, "Failed to publish moisture data");
            }
            control_pump_mqtt(moisture);
        }

        for (int i = 0; i < SAMPLE_INTERVAL && running; i++) {
            sleep(1);
        }
    }

    syslog(LOG_INFO, "Shutting down");
    control_pump(0);
    if (spi_handle >= 0) spiClose(spi_handle);
    if (mqtt_client_id >= 0) {
        mosquitto_disconnect(mqtt_client_id);
        mosquitto_destroy(mqtt_client_id);
    }
    mosquitto_lib_cleanup();
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

