/*
 * MCP3008 3-channel analog reader for Raspberry Pi Zero W
 * SPI0, CE0 (chip enable 0), 5-second CSV logging.
 *
 * Build:  gcc -O2 -Wall -Wextra -o mcp3008_log mcp3008_log.c
 * Run:    ./mcp3008_log
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000          /* 1 MHz */
#define SPI_BITS        8
#define SPI_MODE        SPI_MODE_0
#define VREF            3.3
#define LOG_FILE        "sensor_data.csv"
#define SAMPLE_PERIOD_S 5

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/*
 * MCP3008 single-ended read (channel 0–7).
 * 3-byte transfer: [start] [SGL|D2|D1|D0|0|0|0|0] [0x00]
 * Result: bits 9..0 are in rx[1] (low 2 bits) and rx[2] (8 bits).
 */
static int mcp3008_read(int fd, uint8_t channel)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid channel %u\n", channel);
        return -1;
    }

    uint8_t tx[3] = {
        0x01,
        (uint8_t)((0x08 | channel) << 4),
        0x00
    };
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = sizeof(tx);
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI_IOC_MESSAGE");
        return -1;
    }

    int value = ((rx[1] & 0x03) << 8) | rx[2];
    return value;
}

static float voltage(int adc)
{
    return (adc / 1023.0f) * VREF;
}

static int log_data(const char *filename, float v0, float v1, float v2)
{
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%.3f,%.3f,%.3f\n", ts, v0, v1, v2) < 0) {
        perror("fprintf");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }
    return 0;
}

int main(void)
{
    if (install_signal_handlers() != 0)
        return EXIT_FAILURE;

    int spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open(" SPI_DEVICE ")");
        return EXIT_FAILURE;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("SPI_IOC_WR_MODE");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("SPI_IOC_WR_BITS_PER_WORD");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("SPI_IOC_WR_MAX_SPEED_HZ");
        close(spi_fd);
        return EXIT_FAILURE;
    }

    printf("MCP3008 logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        int adc0 = mcp3008_read(spi_fd, 0);
        int adc1 = mcp3008_read(spi_fd, 1);
        int adc2 = mcp3008_read(spi_fd, 2);

        if (adc0 < 0 || adc1 < 0 || adc2 < 0) {
            fprintf(stderr, "SPI transfer error; aborting.\n");
            break;
        }

        float v0 = voltage(adc0);
        float v1 = voltage(adc1);
        float v2 = voltage(adc2);

        if (log_data(LOG_FILE, v0, v1, v2) != 0) {
            fprintf(stderr, "Logging failed; aborting.\n");
            break;
        }

        printf("Ch0=%.3fV Ch1=%.3fV Ch2=%.3fV\n", v0, v1, v2);

        /* Sleep in 1-second increments so signals are caught promptly. */
        for (int i = 0; i < SAMPLE_PERIOD_S && g_running; i++)
            sleep(1);
    }

    if (close(spi_fd) != 0)
        perror("close(spi_fd)");

    /* Release the driver library so the device is available for other apps. */
    if (ioctl(spi_fd, SPI_IOC_RD_MODE, &mode) >= 0)
        ioctl(spi_fd, SPI_IOC_WR_MODE, &mode);
    if (ioctl(spi_fd, SPI_IOC_RD_BITS_PER_WORD, &bits) >= 0)
        ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits);
    if (ioctl(spi_fd, SPI_IOC_RD_MAX_SPEED_HZ, &speed) >= 0)
        ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed);

    printf("MCP3008 logging stopped.\n");
    return EXIT_SUCCESS;
}

