/*
 * Vibration monitor using MAX9814 + MCP3008 + two hardware-PWM motors.
 *
 * Hardware (Raspberry Pi 3 Model B+):
 *   MCP3008 SPI0 CE0  -> /dev/spidev0.0
 *   MCP3008 CH0     -> MAX9814 OUT
 *   MAX9814 OUT     -> transistor (e.g. 2N3905) -> GPIO17
 *   MAX9814 GND     -> transistor GND -> GPIO27
 *   MAX9814 VDD     -> 3.3 V
 *   MAX9814 GAIN    -> 1 kΩ to 10 kΩ
 *   MAX9814 F/F    -> 1 kΩ to 10 kΩ
 *   MAX9814 GAIN    -> 1 kΩ to 10 kΩ
 *   MAX9814 GND     -> GND
 *   MAX9814 VDD     -> 3.3 V
 *
 * Build:  gcc -O2 -Wall -o vib_mon vib_mon.c -lpigpio -lrt
 * Run:    sudo ./vib_mon
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U
#define SPI_BITS        8U
#define SPI_MODE        0

#define MOTOR1_GPIO     17
#define MOTOR2_GPIO     27

#define PWM_FREQUENCY   100U
#define PWM_RANGE       1000U
#define PWM_DUTY_50    500U
#define PWM_DUTY_0     0U
#define PWM_DUTY_100   1000U

#define NOISE_THRESHOLD 500
#define SAMPLE_PERIOD_US 10000U
#define LOG_FILE        "vibration_log.txt"

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;

/* ------------------------------------------------------------------ */
/* Logging                                                            */
/* ------------------------------------------------------------------ */
static void log_event(const char *msg)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "log_event: fopen(%s): %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    } else {
        fprintf(fp, "[unknown] %s\n", msg);
    }
    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* SPI                                                             */
/* ------------------------------------------------------------------ */
static int spi_init(void)
{
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "spi_init: open(%s): %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "spi_init: SPI_IOC_WR_MODE: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "spi_init: SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "spi_init: SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

/*
 * MCP3008 single-ended read (3-byte transfer).
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4       (single-ended + channel)
 *   tx[2] = 0x00                       (don't care)
 * Result: 10-bit value in ((rx[1] & 0x03) << 8) | rx[2].
 */
static int mcp3008_read(int fd, uint8_t channel)
{
    if (channel > 7) {
        fprintf(stderr, "mcp3008_read: invalid channel %u\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = sizeof(tx);
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "mcp3008_read: SPI_IOC_MESSAGE: %s\n", strerror(errno));
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

/* ------------------------------------------------------------------ */
/* Motor control                                                      */
/* ------------------------------------------------------------------ */
static void motor1_on(void)
{
    gpioPWM(MOTOR1_GPIO, PWM_DUTY_100);
}

static void motor1_off(void)
{
    gpioPWM(MOTOR1_GPIO, PWM_DUTY_0);
}

static void motor2_on(void)
{
    gpioPWM(MOTOR2_GPIO, PWM_DUTY_100);
}

static void motor2_off(void)
{
    gpioPWM(MOTOR2_GPIO, PWM_DUTY_0);
}

/* ------------------------------------------------------------------ */
/* Signal handling                                                    */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                            */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    motor1_off();
    motor2_off();

    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }

    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "main: gpioInitialise failed\n");
        return EXIT_FAILURE;
    }

    /* --- motor GPIO setup --- */
    if (gpioSetMode(MOTOR1_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "main: gpioSetMode(MOTOR1) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(MOTOR2_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "main: gpioSetMode(MOTOR2) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(MOTOR1_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "main: gpioSetPWMfrequency(MOTOR1) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(MOTOR2_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "main: gpioSetPWMfrequency(MOTOR2) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(MOTOR1_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "main: gpioSetPWMrange(MOTOR1) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(MOTOR2_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "main: gpioSetPWMrange(MOTOR2) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- SPI init --- */
    g_spi_fd = spi_init();
    if (g_spi_fd < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- signals --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "main: sigaction(SIGINT): %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "main: sigaction(SIGTERM): %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Vibration monitor running.  Ctrl+C to exit.\n");
    log_event("Vibration monitor started");

    /* --- main loop --- */
    while (g_running) {
        int noise = mcp3008_read(g_spi_fd, 0);
        if (noise < 0) {
            /* SPI error: skip this sample, keep motors off for safety. */
            motor1_off();
            motor2_off();
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        int v1 = (noise > NOISE_THRESHOLD) ? 1 : 0;
        int v2 = (noise > NOISE_THRESHOLD) ? 1 : 0;

        if (v1) {
            motor1_on();
        } else {
            motor1_off();
        }
        if (v2) {
            motor2_on();
        } else {
            motor2_off();
        }

        if (v1 && v2) {
            log_event("Vibration event: both motors engaged");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    log_event("Vibration monitor stopped");
    cleanup();
    return EXIT_SUCCESS;
}

