/*
 * tamper_log.c — Raspberry Pi 5
 *
 * Logs sound (MAX9814 via MCP3008 ADC) and light (BH1750) data to
 * tamper_log.csv every 5 s.  On I2C/SPI errors the error code is logged
 * alongside the sensor values.  SIGINT/SIGTERM releases all resources.
 *
 * Build:  gcc -O2 -Wall -Wextra -o tamper_log tamper_log.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <math.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <linux/i2c-dev.h>

#define CSV_FILENAME      "tamper_log.csv"
#define SPI_DEVICE        "/dev/spidev0.0"
#define I2C_DEVICE         "/dev/i2c-1"
#define BH1750_ADDR        0x5C
#define BH1750_CONT_HRES   0x10
#define BH1750_MEAS_MS     180
#define ADC_CHANNEL        0
#define SAMPLE_INTERVAL_S  5

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* SPI helpers                                                         */
/* ------------------------------------------------------------------ */

static int spi_open(const char *device)
{
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", device, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE_0;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = 8;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = 1000000; /* 1 MHz */
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

/*
 * MCP3008 single-ended read.
 * 3-byte transfer: [0x01] [SGL|D2|D1|D0<<4] [0x00]
 * Result: ((rx[1] & 0x03) << 8) | rx[2]
 */
static int mcp3008_read(int fd, uint8_t channel)
{
    if (channel > 7) {
        fprintf(stderr, "mcp3008_read: invalid channel %u\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = 3;
    tr.speed_hz      = 1000000;
    tr.bits_per_word = 8;
    tr.delay_usecs   = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE: %s\n", strerror(errno));
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

/* ------------------------------------------------------------------ */
/* BH1750 helpers                                                      */
/* ------------------------------------------------------------------ */

static int bh1750_open(int *fd_out)
{
    int fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_DEVICE, strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "I2C_SLAVE 0x%02X: %s\n", BH1750_ADDR, strerror(errno));
        close(fd);
        return -1;
    }

    *fd_out = fd;
    return 0;
}

static int bh1750_read(int fd, float *lux_out)
{
    if (fd < 0) {
        fprintf(stderr, "bh1750_read: invalid fd\n");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "I2C_SLAVE: %s\n", strerror(errno));
        return -1;
    }

    /* Trigger one-shot measurement */
    if (ioctl(fd, I2C_RDWR, 0) < 0) {
        fprintf(stderr, "I2C_RDWR: %s\n", strerror(errno));
        return -1;
    }

    usleep(BH1750_MEAS_MS * 1000);

    uint8_t buf[2];
    ssize_t n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "bh1750_read: read returned %zd (%s)\n", n, strerror(errno));
        return -1;
    }

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* CSV logging                                                         */
/* ------------------------------------------------------------------ */

static int csv_open(const char *filename)
{
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", filename, strerror(errno));
        return -1;
    }

    /* Write header only if file is empty */
    if (fseek(fp, 0, SEEK_END) == 0 && ftell(fp) == 0) {
        fprintf(fp, "timestamp,sound_level_db,light_level_lux,error_code\n");
    }
    return 0;
}

static void csv_log(FILE *fp, float sound, float light, int err_code)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r: %s\n", strerror(errno));
        return;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.2f,%d\n", ts, sound, light, err_code);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int spi_fd = spi_open(SPI_DEVICE);
    if (spi_fd < 0) {
        return EXIT_FAILURE;
    }

    int bh1750_fd = -1;
    if (bh1750_open(&bh1750_fd) < 0) {
        close(spi_fd);
        return EXIT_FAILURE;
    }

    if (csv_open(CSV_FILENAME) < 0) {
        close(spi_fd);
        close(bh1750_fd);
        return EXIT_FAILURE;
    }

    printf("Logging started.  Ctrl+C to stop.\n");

    while (g_running) {
        int adc = mcp3008_read(spi_fd, ADC_CHANNEL);
        int lux_ok = 0;
        int err_code = 0;

        if (adc < 0) {
            err_code = -1;
        } else {
            float sound = (float)adc;
            lux_ok = bh1750_read(bh1750_fd, &lux_ok);
            if (lux_ok < 0) {
                err_code = -2;
            }
        }

        csv_log(csv_file, sound, lux_ok, err_code);
        printf("Sound: %.2f dB  Light: %.2f lux  Err: %d\n",
               sound, lux_ok, err_code);

        /* Sleep SAMPLE_INTERVAL_S, but wake early on signal */
        for (int i = 0; i < SAMPLE_INTERVAL_S && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");

    if (bh1750_fd >= 0) {
        close(bh1750_fd);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (csv_file) {
        fclose(csv_file);
    }

    return EXIT_SUCCESS;
}

