/*
 * Raspberry Pi 4 Model B – Vegetronix VH400 soil-moisture monitor
 *
 * Hardware:
 *   - MCP3008 10-bit ADC on SPI0 (CE0 / GPIO 8), 1 MHz, channel 0
 *   - Vegetronix VH400 0–3 V soil-moisture sensor on MCP3008 CH0
 *   - Relay-driven water pump on BCM GPIO 17 (active-high)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o vh400_monitor vh400_monitor.c -lpigpio -lrt
 *   (pigpio must be installed; run as root or with appropriate permissions.)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL      0          /* CE0 (GPIO 8)                          */
#define SPI_SPEED        1000000    /* 1 MHz                                */
#define SPI_FLAGS        0          /* Mode 0, active-low CE                */
#define ADC_CHANNEL      0          /* MCP3008 single-ended channel 0       */
#define PUMP_GPIO        17         /* BCM GPIO 17 (active-high relay)      */
#define MOISTURE_THRESHOLD 30       /* Percent moisture below which pump   */
#define SAMPLE_INTERVAL  60         /* Seconds between readings             */
#define MAX_RETRIES      3          /* SPI read retries per sample          */
#define ADC_MAX          1023       /* 10-bit ADC full-scale code           */

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static bool g_pigpio_inited = false;

/* --------------------------- Forward declarations ------------------------- */
static void signal_handler(int sig);
static int  initialize(void);
static void cleanup(void);
static int  read_mcp3008(int channel, int *out_value);
static int  calculate_moisture_percentage(int adc_value);
static void control_pump(int pump_state);
static void log_data(int adc_value, int moisture_percentage);

/* ------------------------------- Signal handler --------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------- Initialization ---------------------------- */
static int initialize(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] pigpio initialisation failed (code %d).\n",
                gpioInitialise());
        return -1;
    }
    g_pigpio_inited = true;

    /* Pump GPIO as output, initially OFF (relay de-energised) */
    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "[ERROR] gpioSetMode(%d) failed.\n", PUMP_GPIO);
        return -1;
    }
    if (gpioWrite(PUMP_GPIO, 0) < 0) {
        fprintf(stderr, "[ERROR] gpioWrite(%d, 0) failed.\n", PUMP_GPIO);
        return -1;
    }

    /* Open SPI0 CE0 at 1 MHz, mode 0 */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "[ERROR] spiOpen(CE0, %d, 0) failed (code %d).\n",
                SPI_SPEED, g_spi_handle);
        return -1;
    }

    return 0;
}

/* ------------------------------- Cleanup ---------------------------------- */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    if (g_pigpio_inited) {
        gpioWrite(PUMP_GPIO, 0);   /* Pump off */
        gpioTerminate();
        g_pigpio_inited = false;
    }
}

/* --------------------------- Read MCP3008 --------------------------------- */
/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care)
 *   tx[2] = 0x00                       (clock out remaining bits)
 * Result: 10-bit value assembled from rx[1] (low 2 bits) and rx[2] (8 bits).
 */
static int read_mcp3008(int channel, int *out_value)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "[ERROR] Invalid ADC channel %d.\n", channel);
        return -1;
    }
    if (out_value == NULL) {
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "[ERROR] spiXfer returned %d (expected 3).\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    *out_value = adc_value;
    return 0;
}

/* --------------------------- Moisture calculation ------------------------- */
static int calculate_moisture_percentage(int adc_value)
{
    if (adc_value < 0) {
        return -1;
    }
    if (adc_value > ADC_MAX) {
        adc_value = ADC_MAX;
    }
    return (int)(((float)adc_value / (float)ADC_MAX) * 100.0f);
}

/* ------------------------------- Pump control ----------------------------- */
static void control_pump(int pump_state)
{
    if (gpioWrite(PUMP_GPIO, pump_state) < 0) {
        fprintf(stderr, "[WARN] gpioWrite(%d, %d) failed.\n",
                PUMP_GPIO, pump_state);
    }
}

/* ------------------------------- Logging ---------------------------------- */
static void log_data(int adc_value, int moisture_percentage)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "[WARN] time() failed.\n");
        return;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "[WARN] localtime_r() failed.\n");
        return;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &tm_info) == 0) {
        fprintf(stderr, "[WARN] strftime() failed.\n");
        return;
    }

    printf("[%s] ADC: %4d  Moisture: %3d%%  Pump: %s\n",
           timestamp, adc_value, moisture_percentage,
           pump_state ? "ON" : "OFF");
    fflush(stdout);
}

/* --------------------------------- Main ----------------------------------- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[ERROR] sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[ERROR] sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize() != 0) {
        return EXIT_FAILURE;
    }

    printf("VH400 soil-moisture monitor started.\n");
    printf("  SPI0 CE0 @ %d Hz, channel %d\n", SPI_SPEED, ADC_CHANNEL);
    printf("  Pump on BCM GPIO %d, threshold %d%%\n", PUMP_GPIO, MOISTURE_THRESHOLD);
    printf("  Logging every %d s. Press Ctrl+C to exit.\n\n",
           SAMPLE_INTERVAL);

    while (g_running) {
        int adc_value = -1;
        int retries = 0;

        while (retries < MAX_RETRIES && g_running) {
            if (read_mcp3008(ADC_CHANNEL, &adc_value) == 0) {
                break;
            }
            retries++;
            if (retries < MAX_RETRIES) {
                fprintf(stderr, "[WARN] SPI read attempt %d/%d failed.\n",
                        retries, MAX_RETRIES);
                gpioDelay(100000);  /* 100 ms back-off */
            }
        }

        if (adc_value < 0) {
            fprintf(stderr, "[ERROR] Failed to read ADC after %d attempts.\n",
                    MAX_RETRIES);
            /* Continue loop; sensor may recover. */
        } else {
            int moisture = calculate_moisture_percentage(adc_value);
            if (moisture < 0) {
                fprintf(stderr, "[ERROR] Invalid moisture calculation.\n");
            } else {
                log_data(adc_value, moisture);

                if (moisture < MOISTURE_THRESHOLD) {
                    control_pump(1);
                    printf("[INFO] Moisture below threshold (%d%% < %d%%) – pump ON.\n",
                           moisture, MOISTURE_THRESHOLD);
                } else {
                    control_pump(0);
                    printf("[INFO] Moisture above threshold (%d%% >= %d%%) – pump OFF.\n",
                           moisture, MOISTURE_THRESHOLD);
                }
            }
        }

        /* Sleep in 1 s increments so signals are caught promptly. */
        for (int i = 0; i < SAMPLE_INTERVAL && g_running; i++) {
            gpioDelay(1000000);
        }
    }

    printf("\n[INFO] Shutting down...\n");
    cleanup();
    printf("[INFO] Program terminated.\n");
    return EXIT_SUCCESS;
}

