/*
 * Air Quality Monitor — Raspberry Pi 3 Model B+
 * Sensor : MQ-135 (via MCP3008 ADC on SPI0 CE0, mode 0, 1 MHz)
 * Fan    : GPIO18 (BCM, active-high)
 *
 * Build  : gcc -O2 -Wall -o air_quality air_quality.c -lpigpio -lrt
 * Run    : sudo ./air_quality
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL    0          /* SPI0 CE0 (BCM 8) */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* mode 0, active-low CE */

#define FAN_GPIO       18         /* BCM 18 */

#define CO2_THRESHOLD  700.0f     /* ppm — fan ON */
#define SAMPLE_PERIOD  5          /* seconds between samples */

#define LOG_FILE       "air_quality.log"

/* MCP3008 command bits (single-ended, channel 0–7) */
#define MCP3008_START  0x01
#define MCP3008_SGL    0x80       /* single-ended */
#define MCP3008_CH0    0x00       /* channel 0 */

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static FILE *g_log_fp    = NULL;

/* --------------------------- Function prototypes -------------------------- */
static int  read_mcp3008(int channel, int *adc_out);
static float adc_to_co2_ppm(int adc_value);
static void control_fan(float co2_ppm);
static void log_data(float co2_ppm, int fan_state);
static void signal_handler(int sig);
static void cleanup(void);

/* ------------------------------- SPI ------------------------------------- */
/*
 * Read a single-ended sample from the MCP3008.
 * Returns 0 on success (adc_out set), -1 on error.
 */
static int read_mcp3008(int channel, int *adc_out)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "read_mcp3008: invalid channel %d\n", channel);
        return -1;
    }
    if (adc_out == NULL) {
        return -1;
    }

    /* MCP3008 SPI frame (3 bytes):
     *   tx[0] = 0x01                       start bit
     *   tx[1] = (0x80 | (channel << 4))    SGL/DIFF=1 + channel
     *   tx[2] = 0x00                       don't-care (clocks out low 2 bits)
     * Result: rx[1] low 2 bits + rx[2] 8 bits = 10-bit value
     */
    char tx[3] = { MCP3008_START,
