/*
 * Door-opening system for Raspberry Pi Zero W
 *
 * Hardware:
 *   - GP2Y0A21YK0F IR distance sensor -> MCP3008 ADC channel 0
 *   - MCP3008 SPI connected to SPI0 (CE0 / GPIO8, SCLK / GPIO11, MOSI / GPIO10, MISO / GPIO9)
 *   - Relay module on GPIO17 (BCM) connected to a 5 V relay module
 *
 * Behavior:
 *   - Polls the ADC every 100 ms.
 *   - When the distance (ADC code 0-1023) is below 20 cm, energizes the relay.
 *   - Debounces: waits 1 s after a detection before re-arming.
 *   - Logs each detection event with a timestamp to door_events.log.
 *   - Handles SIGINT for clean shutdown.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o door_system door_system.c -lpigpio -lrt
 *   (pigpio must be installed; run as root or with appropriate permissions)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL      0          /* MCP3008 on SPI0 CE0 (GPIO8)            */
#define SPI_SPEED        1000000    /* 1 MHz                                 */
#define SPI_FLAGS        0          /* Mode 0, active-low CE                  */
#define ADC_CHANNEL      0          /* GP2Y0A21YK0F on MCP3008 CH0         */
#define RELAY_GPIO       17         /* BCM 17                                  */
#define DISTANCE_THRESHOLD_CM 20.0f /* Below this the relay is energized     */
#define DEBOUNCE_DELAY_S  1         /* Seconds after a detection             */
#define POLL_INTERVAL_US 100000     /* 100 ms between polls                   */
#define LOG_FILE         "door_events.log"

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;
static FILE *g_log_fp = NULL;

/* --------------------------- Function prototypes ------------------------- */
static int  read_adc(int channel);
static float adc_to_cm(int adc_value);
static void control_relay(int state);
static void log_event(void);
static void cleanup(void);
static void signal_handler(int sig);

/* ------------------------------- SPI ------------------------------------- */
/*
 * Read a single-ended sample from the MCP3008.
 * Returns 0-1023 on success, -1 on error.
 */
static int read_adc(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: rx[1] low 2 bits + rx[2] 8 bits = 10-bit value
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d): %s\n",
                ret, strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

/* --------------------------- Distance conversion ------------------------- */
/*
 * Convert ADC code (0-1023) to distance in cm.
 * GP2Y0A21YK0F: ~1 cm at ~10 cm, ~80 cm at ~2 cm, ~150 cm at ~8 cm.
 * A simple linear approximation is used here; calibrate for your specific
 * sensor and environment.
 */
static float adc_to_cm(int adc_value)
{
    if (adc_value < 0)   adc_value = 0;
    if (adc_value > 1023) adc_value = 1023;

    /* Inverse mapping: higher ADC = closer */
    float cm = 100.0f - ((float)adc_value / 1023.0f) * 100.0f;
    if (cm < 0.0f)   cm = 0.0f;
    if (cm > 150.0f) cm = 150.0f;
    return cm;
}

/* ------------------------------- Relay ---------------------------------- */
static void control_relay(int state)
{
    if (gpioWrite(RELAY_GPIO, state) != 0) {
        fprintf(stderr, "Failed to write GPIO %d\n", RELAY_GPIO);
        return;
    }
    printf("Relay %s\n", state ? "energized" : "de-energized");
}

/* ------------------------------- Logging --------------------------------- */
static void log_event(void)
{
    if (g_log_fp == NULL) {
        fprintf(stderr, "Log file not open\n");
        return;
    }

    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return;
    }

    if (fprintf(g_log_fp, "%s - Door opened\n", ts) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
    }
    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
    }
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    /* Ensure relay is de-energized */
    if (g_spi_handle >= 0) {
        control_relay(0);
    }
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------ Signal handler --------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------------- main ---------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure relay GPIO */
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    control_relay(0); /* start with relay off */

    /* Open SPI bus for MCP3008 */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (channel %d, speed %d): %s\n",
                SPI_CHANNEL, SPI_SPEED, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Cannot open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
    }

    printf("Door-opening system started.  Ctrl+C to exit.\n");

    time_t last_detection = 0;

    while (g_running) {
        int adc = read_adc(ADC_CHANNEL);
        if (adc < 0) {
            fprintf(stderr, "ADC read error; retrying in 100 ms\n");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        float cm = adc_to_cm(adc);
        printf("ADC=%4d  Distance=%.2f cm  Relay=%s\n",
               adc, cm, (cm < DISTANCE_THRESHOLD_CM) ? "ON" : "OFF");

        if (cm < DISTANCE_THRESHOLD_CM) {
            time_t now = time(NULL);
            if (now == (time_t)-1) {
                fprintf(stderr, "time() failed: %s\n", strerror(errno));
            } else if (difftime(now, last_detection) >= DEBOUNCE_DELAY_S) {
                control_relay(1);
                log_event();
                last_detection = now;
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

