/*
 * Raspberry Pi Zero W – Vegetronix VH400 soil-moisture sensor via MCP3008 ADC
 *   SPI channel 0 (CE0 / GPIO8), 1 MHz, SPI mode 0
 *   ASCO RedHat 8210 series proportional solenoid valve on GPIO17 (BCM)
 *   PWM: 100 Hz, duty-cycle range 0–100 (0 = off, 100 = 100 %)
 *
 * Build:  gcc -O2 -Wall -Wextra -o irrigation irrigation.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_DEVICE        "/dev/spidev0.0"
#define SPI_SPEED_HZ      1000000U   /* 1 MHz */
#define SPI_MODE          SPI_MODE_0
#define SPI_BITS_PER_WORD 8

#define VALVE_GPIO         17         /* BCM pin number */
#define PWM_FREQUENCY_HZ  100
#define PWM_RANGE          100        /* duty-cycle range 0–100 */

#define LOG_FILE           "irrigation.log"
#define SAMPLE_COUNT       3
#define SAMPLE_DELAY_US    100000     /* 100 ms between samples */
#define REPORT_INTERVAL_S  5          /* log every 5 s */

/* MCP3008 single-ended channel 0 */
#define ADC_CHANNEL        0

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_spi_fd   = -1;
static FILE *g_log_fp  = NULL;

/* --------------------------- Forward declarations ------------------------- */
static int  spi_init(void);
static int  read_adc(int channel);
static int  calculate_average(const int *samples, int count);
static int  set_valve_pwm(int duty_cycle);
static void log_data(int adc1, int adc2, int adc3, int avg, int duty);
static void signal_handler(int sig);
static void cleanup(void);

/* --------------------------- SPI / MCP3008 ------------------------------- */
static int spi_init(void)
{
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1;
        return -1;
    }

    return 0;
}

/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
 *   tx[2] = 0x00                       (clock out low bits)
 *   rx[1] bits 1..0 + rx[2] bits 7..0  -> 10-bit result
 */
static int read_adc(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = sizeof(tx);
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS_PER_WORD;
    tr.delay_usecs   = 0;

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE: %s\n", strerror(errno));
        return -1;
    }

    int value = ((rx[1] & 0x03) << 8) | rx[2];
    return value;
}

/* --------------------------- Valve control ------------------------------- */
static int set_valve_pwm(int duty_cycle)
{
    if (duty_cycle < 0)   duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;

    if (duty_cycle == 0) {
        if (gpioPWM(VALVE_GPIO, 0) < 0) {
            fprintf(stderr, "gpioPWM(0): %s\n", strerror(errno));
            return -1;
        }
        return 0;
    }

    if (gpioPWM(VALVE_GPIO, duty_cycle) < 0) {
        fprintf(stderr, "gpioPWM(%d): %s\n", duty_cycle, strerror(errno));
        return -1;
    }
    return 0;
}

/* --------------------------- Logging ------------------------------------- */
static void log_data(int adc1, int adc2, int adc3, int avg, int duty)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32] = { 0 };
    if (t)
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    fprintf(g_log_fp, "%s, ADC1=%d, ADC2=%d, ADC3=%d, Avg=%d, Duty=%d\n",
            ts, adc1, adc2, adc3, avg, duty);
    fflush(g_log_fp);
}

/* --------------------------- Signal / cleanup ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
}

/* --------------------------------- main ---------------------------------- */
int main(void)
{
    /* --- Install signal handlers early --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Initialize SPI --- */
    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Configure valve GPIO for PWM --- */
    if (gpioSetMode(VALVE_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d): %s\n", VALVE_GPIO, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(VALVE_GPIO, PWM_FREQUENCY_HZ) < 0) {
        fprintf(stderr, "gpioSetPWMfrequency(%d): %s\n", VALVE_GPIO, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(VALVE_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "gpioSetPWMrange(%d): %s\n", VALVE_GPIO, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (set_valve_pwm(0) < 0) {
        fprintf(stderr, "Initial valve PWM set failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Irrigation controller started. Logging to %s every %d s.\n",
           LOG_FILE, REPORT_INTERVAL_S);
    printf("Press Ctrl+C to exit.\n");

    int adc_samples[SAMPLE_COUNT];
    int consecutive_failures = 0;

    while (g_running) {
        int success = 1;

        for (int i = 0; i < SAMPLE_COUNT; i++) {
            int v = read_adc(ADC_CHANNEL);
            if (v < 0) {
                success = 0;
                break;
            }
            adc_samples[i] = v;
            usleep(SAMPLE_DELAY_US);
        }

        if (!success) {
            consecutive_failures++;
            if (consecutive_failures >= 10) {
                fprintf(stderr, "Too many consecutive ADC failures; aborting.\n");
                break;
            }
            continue;
        }
        consecutive_failures = 0;

        int avg = calculate_average(adc_samples, SAMPLE_COUNT);

        if (set_valve_pwm(avg) < 0) {
            fprintf(stderr, "Failed to set valve PWM.\n");
        }

        log_data(adc_samples[0], adc_samples[1], adc_samples[2], avg, avg);

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < REPORT_INTERVAL_S * 10 && g_running; i++)
            usleep(100000);
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    set_valve_pwm(0);
    cleanup();
    return EXIT_SUCCESS;
}

/* --------------------------- Helpers ------------------------------------- */
static int calculate_average(const int *samples, int count)
{
    if (count <= 0) return 0;
    int sum = 0;
    for (int i = 0; i < count; i++)
        sum += samples[i];
    return sum / count;
}

