/*
 * Raspberry Pi Zero W – YL-69 soil moisture sensor via MCP3008 ADC
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V (pin 1)
 *   MCP3008 VREF -> 3.3 V (pin 1)
 *   MCP3008 AGND -> GND
 *   MCP3008 DGND -> GND
 *   MCP3008 CLK  -> GPIO11 (SPI0 SCLK, pin 23)
 *   MCP3008 DOUT -> GPIO9  (SPI0 MISO, pin 21)
 *   MCP3008 DIN  -> GPIO10 (SPI0 MOSI, pin 19)
 *   MCP3008 CS   -> GPIO8  (SPI0 CE0,  pin 24)
 *   MCP3008 CH0  -> YL-69 analog out (A0)
 *   YL-69 VCC    -> 3.3 V
 *   YL-69 GND    -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o soil_moisture soil_moisture.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U   /* 1 MHz */
#define SPI_MODE        SPI_MODE_0
#define SPI_BITS        8
#define ADC_CHANNEL     0          /* MCP3008 single-ended channel 0 */
#define ADC_MAX_VALUE   1023       /* 10-bit ADC */
#define SAMPLE_INTERVAL 5         /* seconds between samples */
#define MAX_RETRIES     5
#define LOG_FILE        "soil_data.txt"

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* SPI helpers                                                         */
/* ------------------------------------------------------------------ */
static int spi_open(const char *device)
{
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("open(SPI device)");
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl(SPI_IOC_WR_MODE)");
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl(SPI_IOC_WR_BITS_PER_WORD)");
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl(SPI_IOC_WR_MAX_SPEED_HZ)");
        close(fd);
        return -1;
    }

    return fd;
}

/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
 *   tx[2] = 0x00                       (clock out remaining bits)
 * Result: 10-bit value assembled from rx[1] (low 2 bits) and rx[2] (8 bits).
 */
static int mcp3008_read(int fd, uint8_t channel, uint16_t *out_value)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid ADC channel %u\n", channel);
        return -1;
    }

    uint8_t tx[3] = {
        0x01,
        (uint8_t)((0x08 | channel) << 4),
        0x00
    };
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = sizeof(tx);
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("ioctl(SPI_IOC_MESSAGE)");
        return -1;
    }

    *out_value = (uint16_t)(((rx[1] & 0x03) << 8) | rx[2]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Data logging                                                         */
/* ------------------------------------------------------------------ */
static int log_data(const char *filename, const char *timestamp,
                    int adc_value, int moisture_pct, const char *status)
{
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        perror("fopen(log file)");
        return -1;
    }

    if (status[0] != '\0') {
        fprintf(fp, "%s, ADC: %d, Moisture: %d%%, Status: %s\n",
                timestamp, adc_value, moisture_pct, status);
    } else {
        fprintf(fp, "%s, ADC: %d, Moisture: %d%%\n",
                timestamp, adc_value, moisture_pct);
    }

    if (fclose(fp) != 0) {
        perror("fclose(log file)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int spi_fd = -1;
    int rc = EXIT_FAILURE;

    if (install_signal_handlers() != 0) {
        goto cleanup;
    }

    spi_fd = spi_open(SPI_DEVICE);
    if (spi_fd < 0) {
        goto cleanup;
    }

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t adc_value = 0;
        int retries = 0;
        int success = 0;

        while (retries < MAX_RETRIES && g_running) {
            if (mcp3008_read(spi_fd, ADC_CHANNEL, &adc_value) == 0) {
                success = 1;
                break;
            }

            retries++;
            if (retries < MAX_RETRIES) {
                fprintf(stderr, "SPI read attempt %d/%d failed (errno=%d: %s)\n",
                        retries, MAX_RETRIES, errno, strerror(errno));
                if (retries < MAX_RETRIES) {
                    sleep(1 << retries);
                }
            }
        }

        if (success) {
            int moisture_pct = (int)(((float)adc_value / (float)ADC_MAX_VALUE) * 100.0f);
            if (moisture_pct < 0)   moisture_pct = 0;
            if (moisture_pct > 100) moisture_pct = 100;

            time_t now = time(NULL);
            struct tm tm_buf;
            struct tm *t = localtime_r(&now, &tm_buf);
            char timestamp[32];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

            if (log_data(LOG_FILE, timestamp, adc_value, moisture_pct, "OK") != 0) {
                fprintf(stderr, "Failed to log data.\n");
            } else {
                printf("%s  ADC: %4u  Moisture: %3d%%\n",
                       timestamp, adc_value, moisture_pct);
            }
        } else {
            fprintf(stderr, "Failed to read ADC after %d retries.\n", MAX_RETRIES);
            if (log_data(LOG_FILE, "ERROR", 0, 0, "SPI_ERROR") != 0) {
                fprintf(stderr, "Failed to log error data.\n");
            }
        }

        /* Sleep in 1-second increments so signals are caught promptly. */
        for (int i = 0; i < SAMPLE_INTERVAL && g_running; i++) {
            sleep(1);
        }
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (spi_fd >= 0) {
        if (close(spi_fd) != 0) {
            perror("close(SPI fd)");
        }
    }
    printf("\nSoil moisture monitoring stopped.\n");
    return rc;
}

