/*
 * Theremin-like instrument for Raspberry Pi Zero W
 * HC-SR04 ultrasonic sensor + photoresistor (LDR) + MCP3008 ADC
 * PWM output on GPIO18 (BCM), Trig on GPIO23 (BCM), Echo on GPIO24 (BCM)
 *
 * Build: gcc -O2 -Wall -o theremin theremin.c -lpthread -lrt
 * Run:   sudo ./theremin
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <pthread.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define BCM_TRIG_PIN      23
#define BCM_ECHO_PIN      24
#define BCM_PWM_PIN       18

#define SPI_DEVICE        "/dev/spidev0.0"
#define PWM_DEVICE        "/sys/class/pwm/pwmchip0/export"
#define PWM_UNEXPORT      "/sys/class/pwm/pwmchip0/unexport"

#define CONFIG_FILE       "theremin_config.txt"
#define SPI_SPEED_HZ      1000000
#define SPI_BITS          8
#define SPI_DELAY_USECS   0

#define MAX_DISTANCE_CM   400.0f
#define MIN_DISTANCE_CM   2.0f
#define MAX_VOLUME        100
#define MIN_VOLUME        0

#define ECHO_TIMEOUT_US   30000
#define TRIG_PULSE_US     10
#define LOOP_DELAY_US     10000

#define PWM_PERIOD_NS     1000000  /* 1 kHz */
#define PWM_DUTY_NS       0

static volatile sig_atomic_t g_running = 1;
static volatile uint32_t g_last_tick = 0;
static volatile uint32_t g_last_echo_tick = 0;
static volatile float g_distance = MAX_DISTANCE_CM;
static volatile float g_volume = 0.0f;

static int g_spi_fd = -1;
static int g_pwm_exported = 0;
static int g_pwm_unexported = 0;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void sleep_us(uint32_t us)
{
    struct timespec ts = { us / 1000000, (long)(us % 1000000) * 1000 };
    nanosleep(&ts, NULL);
}

static int spi_init(void)
{
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE_0;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1; return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1; return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1; return -1;
    }

    return 0;
}

static int spi_close(void)
{
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    return 0;
}

static int spi_read_adc(int channel)
{
    if (g_spi_fd < 0) return -1;

    uint8_t tx[3] = { 0x01, (uint8_t)(0x80 | (channel << 4)), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
        .len           = 3,
        .speed_hz      = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs   = SPI_DELAY_USECS,
    };

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE: %s\n", strerror(errno));
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int pwm_init(void)
{
    int fd = open(PWM_DEVICE, O_WRONLY);
    if (fd < 0) {
        if (errno == EBUSY) {
            g_pwm_exported = 1;
            fd = open(PWM_DEVICE, O_WRONLY);
            if (fd < 0) {
                fprintf(stderr, "PWM export: %s\n", strerror(errno));
                return -1;
            }
        } else {
            fprintf(stderr, "open(%s): %s\n", PWM_DEVICE, strerror(errno));
            return -1;
        }
    }

    /* Set period to 1 ms (1 kHz) */
    if (lseek(fd, 0, SEEK_SET) < 0) {
        fprintf(stderr, "lseek period: %s\n", strerror(errno));
        close(fd); return -1;
    }
    if (write(fd, "1000000", 8) < 0) {
        fprintf(stderr, "write period: %s\n", strerror(errno));
        close(fd); return -1;
    }

    /* Set duty cycle to 0 */
    if (lseek(fd, 0, SEEK_SET) < 0) {
        fprintf(stderr, "lseek duty: %s\n", strerror(errno));
        close(fd); return -1;
    }
    if (write(fd, "0", 1) < 0) {
        fprintf(stderr, "write duty: %s\n", strerror(errno));
        close(fd); return -1;
    }

    close(fd);
    g_pwm_exported = 1;
    return 0;
}

static int pwm_unexport(void)
{
    int fd = open(PWM_DEVICE, O_WRONLY);
    if (fd < 0) {
        if (errno == EBUSY) {
            g_pwm_unexported = 1;
            return 0;
        }
        fprintf(stderr, "open(%s): %s\n", PWM_DEVICE, strerror(errno));
        return -1;
    }

    if (lseek(fd, 0, SEEK_SET) < 0) {
        fprintf(stderr, "lseek unexport: %s\n", strerror(errno));
        close(fd); return -1;
    }
    if (write(fd, "0", 1) < 0) {
        fprintf(stderr, "write unexport: %s\n", strerror(errno));
        close(fd); return -1;
    }

    close(fd);
    g_pwm_unexported = 1;
    return 0;
}

static int pwm_set_duty(int duty_ns)
{
    int fd = open(PWM_DEVICE, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "open PWM duty: %s\n", strerror(errno));
        return -1;
    }

    if (lseek(fd, 0, SEEK_SET) < 0) {
        fprintf(stderr, "lseek duty: %s\n", strerror(errno));
        close(fd); return -1;
    }
    if (write(fd, "0", 1) < 0) {
        fprintf(stderr, "write duty: %s\n", strerror(errno));
        close(fd); return -1;
    }

    char buf[32];
    snprintf(buf, sizeof(buf), "%d", duty_ns);
    if (write(fd, buf, strlen(buf)) < 0) {
        fprintf(stderr, "write duty: %s\n", strerror(errno));
        close(fd); return -1;
    }

    close(fd);
    return 0;
}

static void pwm_stop(void)
{
    if (g_pwm_unexported) {
        return;
    }
    if (g_pwm_exported) {
        pwm_unexport();
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

static void calibrate(void)
{
    printf("Calibrating...\n");
    printf("Place your hand near the LDR to set the volume.\n");
    sleep_us(500000);

    int v = spi_read_adc(0);
    if (v < 0) {
        fprintf(stderr, "ADC read failed during calibration\n");
        return;
    }
    g_volume = (float)v / 1023.0f * MAX_VOLUME;
    printf("Volume: %.2f%%\n", g_volume * 100.0f);

    printf("Measure distance with the HC-SR04.\n");
    sleep_us(500000);

    int d = spi_read_adc(0);
    if (d < 0) {
        fprintf(stderr, "ADC read failed during calibration\n");
        return;
    }
    g_distance = (float)d / 1023.0f * MAX_DISTANCE_CM;
    printf("Distance: %.2f cm\n", g_distance);

    FILE *fp = fopen(CONFIG_FILE, "w");
    if (!fp) {
        fprintf(stderr, "Failed to write config: %s\n", strerror(errno));
        return;
    }
    fprintf(fp, "distance=%.2f\nvolume=%.2f\n", g_distance, g_volume);
    fclose(fp);
    printf("Calibration saved to %s\n", CONFIG_FILE);
}

static void load_config(void)
{
    FILE *fp = fopen(CONFIG_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Config file not found; using defaults\n");
        return;
    }

    float d, v;
    if (fscanf(fp, "distance=%.2f\nvolume=%.2f\n", &d, &v) == 2) {
        g_distance = d;
        g_volume = v;
        printf("Loaded: distance=%.2f cm, volume=%.2f%%\n", g_distance, g_volume * 100.0f);
    } else {
        fprintf(stderr, "Invalid config; using defaults\n");
    }
    fclose(fp);
}

static void set_pwm_frequency(int freq_hz)
{
    int fd = open(PWM_DEVICE, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "open PWM freq: %s\n", strerror(errno));
        return;
    }

    if (lseek(fd, 0, SEEK_SET) < 0) {
        fprintf(stderr, "lseek freq: %s\n", strerror(errno));
        close(fd); return;
    }
    if (write(fd, "0", 1) < 0) {
        fprintf(stderr, "write freq: %s\n", strerror(errno));
        close(fd); return;
    }

    char buf[32];
    snprintf(buf, sizeof(buf), "%d", freq_hz);
    if (write(fd, buf, strlen(buf)) < 0) {
        fprintf(stderr, "write freq: %s\n", strerror(errno));
        close(fd); return;
    }

    close(fd);
}

static void generate_tone(float distance, float volume)
{
    int freq = (int)(500 + (distance - 2.0f) * 100.0f);
    if (freq < 20) freq = 20;
    if (freq > 2000) freq = 2000;

    int duty_ns = (int)((float)PWM_PERIOD_NS * volume / 100.0f);
    if (duty_ns < 0) duty_ns = 0;
    if (duty_ns > PWM_PERIOD_NS) duty_ns = PWM_PERIOD_NS;

    set_pwm_frequency(freq);
    pwm_set_duty(duty_ns);
}

static void echo_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        g_last_tick = tick;
    } else if (level == 0) {
        if (g_last_tick != 0) {
            uint32_t diff = tick - g_last_tick;
            g_last_echo_tick = tick;
            float dist = (float)diff / 58.0f;
            if (dist > MAX_DISTANCE_CM) dist = MAX_DISTANCE_CM;
            if (dist < MIN_DISTANCE_CM) dist = MIN_DISTANCE_CM;
            g_distance = dist;
        }
    }
}

