        }

        log_data(aqi);
        control_fan(aqi);

        for (int i = 0; i < SAMPLE_INTERVAL && !terminate; i++) {
            sleep(1);
        }
    }

    cleanup();
    printf("Air quality monitoring stopped.\n");
    return 0;
}

