/*
 * MQ-3 Alcohol Sensor Monitor via MCP3008 ADC on Raspberry Pi Zero W
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V (Pin 1)
 *   MCP3008 VREF -> 3.3 V (Pin 1)
 *   MCP3008 AGND -> GND
 *   MCP3008 DGND -> GND
 *   MCP3008 CLK  -> GPIO11 (SPI0 SCLK)
 *   MCP3008 DOUT -> GPIO9  (SPI0 MISO)
 *   MCP3008 DIN  -> GPIO10 (SPI0 MOSI)
 *   MCP3008 CS   -> GPIO8  (SPI0 CE0)
 *   MCP3008 CH0  -> MQ-3 analog out
 *
 * Build: gcc -O2 -Wall -o alcohol_monitor alcohol_monitor.c -lpigpio -lrt
 * Run:   sudo ./alcohol_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define SPI_CHANNEL    0          /* SPI0 CE0 (GPIO8) */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* Mode 0, 8-bit words, active-low CE */
#define ADC_CHANNEL    0          /* MCP3008 single-ended channel 0 */
#define ADC_MAX_VALUE  1023       /* 10-bit ADC */
#define ADC_VREF       3.3        /* Reference voltage */

#define SAMPLE_INTERVAL_S 1
#define MAX_RETRIES      3
#define RETRY_DELAY_US   100000   /* 100 ms */
#define LOG_FILE         "alcohol_log.txt"

#define THRESHOLD_HIGH   50.0f    /* ppm */
#define THRESHOLD_LOW    20.0f    /* ppm */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper (ISO 8601 UTC)                                     */
/* ------------------------------------------------------------------ */
static int get_iso8601_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        return -1;
    }
    struct tm tm_utc;
    if (gmtime_r(&now, &tm_utc) == NULL) {
        return -1;
    }
    if (strftime(buf, len, "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read MCP3008 single-ended channel (0-7)                              */
/* Returns 0-1023 on success, -1 on error.                              */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int spi_handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI protocol (Mode 0, 8-bit words):
     *   Byte 0: 0x01  (start bit)
     *   Byte 1: (0x08 | channel) << 4  (single-ended + channel select)
     *   Byte 2: 0x00  (don't care, clocked out to capture low byte)
     *
     * Response:
     *   rx[0] = don't care
     *   rx[1] = [null bit, b9, b8] in the two low bits
     *   rx[2] = b7..b0
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d): %s\n",
                ret, strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Convert ADC count to voltage                                          */
/* ------------------------------------------------------------------ */
static float adc_to_voltage(int adc_value)
{
    return ((float)adc_value / (float)ADC_MAX_VALUE) * ADC_VREF;
}

/* ------------------------------------------------------------------ */
/* Log a reading with timestamp                                          */
/* ------------------------------------------------------------------ */
static int log_reading(FILE *fp, float voltage, const char *status)
{
    char ts[32];
    if (get_iso8601_timestamp(ts, sizeof(ts)) != 0) {
        fprintf(stderr, "Failed to generate timestamp\n");
        return -1;
    }

    if (fprintf(fp, "%s, Voltage: %.3f V, Status: %s\n",
                ts, voltage, status) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "Failed to flush log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open SPI0 CE0 at 1 MHz, Mode 0 --- */
    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (channel %d, %d Hz): %s\n",
                SPI_CHANNEL, SPI_SPEED, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
    }

    printf("Alcohol monitoring started. Logging to '%s'. Press Ctrl+C to exit.\n",
           LOG_FILE);

    /* --- Main sampling loop --- */
    while (g_running) {
        int adc_value = -1;
        int retries = 0;

        /* Retry loop for transient SPI errors */
        while (retries < MAX_RETRIES && g_running) {
            adc_value = read_mcp3008(spi_handle, ADC_CHANNEL);
            if (adc_value >= 0) {
                break;
            }
            retries++;
            if (retries < MAX_RETRIES) {
                fprintf(stderr, "SPI read error (attempt %d/%d)\n",
                        retries, MAX_RETRIES);
                gpioDelay(RETRY_DELAY_US);
            }
        }

        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC after %d attempts.\n",
                    MAX_RETRIES);
            /* Continue sampling; sensor may recover */
            sleep(SAMPLE_INTERVAL_S);
            continue;
        }

        /* Sensor-absent / wiring-fault detection */
        if (adc_value == 0 || adc_value == ADC_MAX_VALUE) {
            fprintf(stderr,
                    "Warning: ADC reading at rail (%d) — sensor absent or "
                    "not connected.\n", adc_value);
        }

        float voltage = adc_to_voltage(adc_value);

        /* Determine status string */
        const char *status = "Unknown";
        if (voltage > THRESHOLD_HIGH) {
            status = "Alcohol detected! Limit exceeded.";
        } else if (voltage < THRESHOLD_LOW) {
            status = "Sobriety confirmed.";
        } else {
            status = "Alcohol level within acceptable range.";
        }

        if (log_reading(g_log_fp, voltage, status) != 0) {
            fprintf(stderr, "Logging failed; continuing.\n");
        }

        printf("Voltage: %.3f V, Status: %s\n", voltage, status);

        sleep(SAMPLE_INTERVAL_S);
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    cleanup();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

