/*
 * Raspberry Pi 4 Model B – Dual Motor Control via MCP3008 ADC
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V
 *   MCP3008 VREF -> 3.3 V
 *   MCP3008 AGND -> GND
 *   MCP3008 DGND -> GND
 *   MCP3008 CLK  -> GPIO11 (SCLK)
 *   MCP3008 DOUT -> GPIO9  (MISO)
 *   MCP3008 DIN  -> GPIO10 (MOSI)
 *   MCP3008 CS   -> GPIO8  (CE0)
 *   MCP3008 CH0  -> Potentiometer 1 (0–3.3 V)
 *   MCP3008 CH1  -> Potentiometer 2 (0–3.3 V)
 *   Motor 1 AIN  -> GPIO18 (PWM)
 *   Motor 1 PW   -> GPIO24 (PWM)
 *   Motor 1 DIR  -> GPIO23 (Output)
 *   Motor 2 AIN  -> GPIO25 (PWM)
 *   Motor 2 PW   -> GPIO25 (PWM)
 *   Motor 2 DIR  -> GPIO25 (Output)
 *
 * Build: gcc -O2 -Wall -o motor_control motor_control.c -lpigpio -lrt
 * Run:   sudo ./motor_control
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL    0          /* MCP3008 on CE0 (GPIO8)                  */
#define SPI_SPEED      1000000    /* 1 MHz                                 */
#define SPI_FLAGS      0          /* Mode 0, active-low CE                   */

#define MOTOR1_PWM_PIN 18
#define MOTOR1_DIR_PIN 23
#define MOTOR2_PWM_PIN 24
#define MOTOR2_DIR_PIN 25

#define ACCELERATION_DURATION  2.0   /* seconds                          */
#define DECELERATION_DURATION 2.0   /* seconds                          */
#define PAUSE_DURATION        5.0   /* seconds                          */
#define LOOP_DELAY            0.1   /* seconds                          */
#define PWM_RANGE             255
#define PWM_FREQUENCY         1000   /* Hz                               */

/* ----------------------------- Globals ---------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* ----------------------------- Prototypes -------------------------------- */
static int  read_mcp3008(int channel);
static void set_motor_speed(int motor, int speed);
static void accelerate_motor(int motor);
static void hold_speed(int motor, int speed);
static void decelerate_motor(int motor);
static void reverse_motors(void);
static void cleanup(void);
static void signal_handler(int sig);

/* ----------------------------- MCP3008 ----------------------------------- */
/*
 * Read a single-ended channel from the MCP3008.
 * Returns 0–1023 on success, or -1 on SPI error.
 */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI protocol (3 bytes):
     *   Byte 0: 0x01                       (start bit)
     *   Byte 1: (0x08 | channel) << 4      (single-ended + channel)
     *   Byte 2: 0x00                       (don't care)
     *
     * Response:
     *   rx[0] = ignored
     *   rx[1] = [null bit][b9 b8] in lower nibble
     *   rx[2] = b7..b0
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;
}

/* ----------------------------- Motor Control ----------------------------- */
static void set_motor_speed(int motor, int speed)
{
    if (speed < 0) speed = 0;
    if (speed > PWM_RANGE) speed = PWM_RANGE;

    int pwm_pin = (motor == 1) ? MOTOR1_PWM_PIN : MOTOR2_PWM_PIN;
    int dir_pin = (motor == 1) ? MOTOR1_DIR_PIN : MOTOR2_DIR_PIN;

    if (speed > 0) {
        gpioPWM(pwm_pin, speed);
        gpioWrite(dir_pin, 1);
    } else {
        gpioPWM(pwm_pin, 0);
        gpioWrite(dir_pin, 0);
    }
}

static void accelerate_motor(int motor)
{
    int speed = 0;
    for (int i = 0; i <= PWM_RANGE && g_running; i++) {
        set_motor_speed(motor, i);
        time_sleep(LOOP_DELAY);
    }
}

static void hold_speed(int motor, int speed)
{
    set_motor_speed(motor, speed);
    time_sleep(ACCELERATION_DURATION);
}

static void decelerate_motor(int motor)
{
    for (int i = PWM_RANGE; i >= 0 && g_running; i--) {
        set_motor_speed(motor, i);
        time_sleep(LOOP_DELAY);
    }
}

static void reverse_motors(void)
{
    /* Motor 1 forward, Motor 2 backward */
    set_motor_speed(1, PWM_RANGE);
    set_motor_speed(2, -PWM_RANGE);
    time_sleep(0.1);
    set_motor_speed(1, 0);
    set_motor_speed(2, 0);
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    /* Stop PWM on both motors */
    gpioPWM(MOTOR1_PWM_PIN, 0);
    gpioPWM(MOTOR2_PWM_PIN, 0);

    /* Ensure motors are stopped */
    gpioWrite(MOTOR1_DIR_PIN, 0);
    gpioWrite(MOTOR2_DIR_PIN, 0);

    /* Close SPI */
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }

    /* Terminate pigpio */
    gpioTerminate();
}

/* ----------------------------- Signal Handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure motor pins */
    gpioSetMode(MOTOR1_PWM_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR1_DIR_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR2_PWM_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR2_DIR_PIN, PI_OUTPUT);

    /* Set PWM range and frequency */
    gpioSetPWMrange(MOTOR1_PWM_PIN, PWM_RANGE);
    gpioSetPWMrange(MOTOR2_PWM_PIN, PWM_RANGE);
    gpioSetPWMfrequency(MOTOR1_PWM_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR2_PWM_PIN, PWM_FREQUENCY);

    /* Open SPI */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", g_spi_handle);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Motor control started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int v1 = read_mcp3008(0);
        int v2 = read_mcp3008(1);

        if (v1 < 0 || v2 < 0) {
            fprintf(stderr, "SPI read error – skipping cycle\n");
            time_sleep(1.0);
            continue;
        }

        /* Map 10-bit ADC to 0–255 */
        int speed1 = (int)(((float)v1 / 1023.0f) * PWM_RANGE);
        int speed2 = (int)(((float)v2 / 1023.0f) * PWM_RANGE);

        printf("Pot1: %4d  Pot2: %4d  Speed1: %3d  Speed2: %3d\n",
               v1, v2, speed1, speed2);

        /* Accelerate both motors */
        accelerate_motor(1);
        accelerate_motor(2);

        /* Hold constant speed for 2 seconds */
        hold_speed(1, speed1);
        hold_speed(2, speed2);

        /* Decelerate both motors */
        decelerate_motor(1);
        decelerate_motor(2);

        /* Pause between cycles */
        time_sleep(PAUSE_DURATION);

        /* Reverse direction */
        reverse_motors();
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

