    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Motor control started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int v1 = read_mcp3008(0);
        int v2 = read_mcp3008(1);

        if (v1 < 0 || v2 < 0) {
            fprintf(stderr, "SPI read error – skipping cycle\n");
            time_sleep(1.0);
            continue;
        }

        /* Map 10-bit ADC to 0–255 */
        int speed1 = (int)(((float)v1 / 1023.0f) * PWM_RANGE);
        int speed2 = (int)(((float)v2 / 1023.0f) * PWM_RANGE);

        printf("Pot1: %4d  Pot2: %4d  Speed1: %3d  Speed2: %3d\n",
               v1, v2, speed1, speed2);

        /* Accelerate both motors */
        accelerate_motor(1);
        accelerate_motor(2);

        /* Hold constant speed for 2 seconds */
        hold_speed(1, speed1);
        hold_speed(2, speed2);

        /* Decelerate both motors */
        decelerate_motor(1);
        decelerate_motor(2);

        /* Pause between cycles */
        time_sleep(PAUSE_DURATION);

        /* Reverse direction */
        reverse_motors();
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

