/*
 * Raspberry Pi 3 Model B+ — MAX9814 Electret Microphone Amplifier (via MCP3008 ADC)
 * SPI:  CS=GPIO8, MOSI=GPIO10, MISO=GPIO9, SCLK=GPIO11
 * LED:  GPIO17 (BCM)
 *
 * Build: gcc -O2 -Wall -o mic_monitor mic_monitor.c -lpigpio -lrt
 * Run:   sudo ./mic_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LED_PIN          17
#define SPI_CHANNEL      0          /* MCP3008 on CE0 (GPIO8) */
#define SPI_SPEED        1000000    /* 1 MHz */
#define SPI_FLAGS        0          /* Mode 0, active-low CE */
#define ADC_CHANNEL      0          /* MCP3008 single-ended channel 0 */
#define DEBOUNCE_US      10000      /* 10 ms debounce */
#define SAMPLE_PERIOD_US 10000      /* 10 ms sample interval */
#define CALIBRATION_SEC  5          /* calibration window */
#define MAX_SAMPLES      50         /* samples for baseline */

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read 10-bit value from MCP3008 single-ended channel (0–7).           */
/* Returns 0–1023 on success, -1 on error.                              */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI protocol (Mode 0, MSB first):
     *   Byte 0: 0x01  (start bit)
     *   Byte 1: (0x08 | channel) << 4  (single-ended + channel)
     *   Byte 2: 0x00  (don't care, clocked out to capture low byte)
     *
     * Response: bits 9..0 are in rx[1] (low 2 bits) and rx[2] (8 bits).
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "spiXfer failed (ret=%d)\n", ret);
        return -1;
    }

    int adc = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure LED pin --- */
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    /* --- Open SPI bus to MCP3008 --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle=%d)\n", g_spi_handle);
        gpioWrite(LED_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Monitoring sound levels (Ctrl+C to exit)...\n");

    /* --- Calibration: average first CALIBRATION_SEC * SAMPLE_PERIOD_US samples --- */
    uint32_t sum = 0;
    int valid = 0;
    for (int i = 0; i < MAX_SAMPLES && g_running; i++) {
        int v = read_mcp3008(g_spi_handle, ADC_CHANNEL);
        if (v < 0) {
            fprintf(stderr, "ADC read error during calibration\n");
            cleanup();
            return EXIT_FAILURE;
        }
        sum += v;
        valid++;
        gpioDelay(SAMPLE_PERIOD_US);
    }

    if (valid == 0 || !g_running) {
        fprintf(stderr, "Calibration failed or interrupted\n");
        cleanup();
        return EXIT_FAILURE;
    }

    int baseline = sum / valid;
    printf("Calibration complete. Baseline = %d\n", baseline);

    /* --- Main loop: sample and compare with debounce --- */
    bool led_on = false;
    uint32_t last_toggle = 0;

    while (g_running) {
        int v = read_mcp3008(g_spi_handle, ADC_CHANNEL);
        if (v < 0) {
            fprintf(stderr, "ADC read error\n");
            break;
        }

        uint32_t now = gpioTick();
        if (now - last_toggle < DEBOUNCE_US) {
            /* Within debounce window — ignore */
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }
        last_toggle = now;

        bool exceed = (v > baseline);

        if (exceed && !led_on) {
            gpioWrite(LED_PIN, 1);
            led_on = true;
            printf("Sound level exceeded baseline (v=%d, baseline=%d) — LED ON\n", v, baseline);
        } else if (!exceed && led_on) {
            gpioWrite(LED_PIN, 0);
            led_on = false;
            printf("Sound level below baseline — LED OFF\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* --- Graceful cleanup --- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

