/*
 * Propane Leak Detector — Raspberry Pi 4 Model B
 *
 * Hardware:
 *   - Raspberry Pi 4 Model B (SPI0, CE0 / GPIO 8)
 *   - MCP3008 ADC on SPI0, channel 0 (single-ended)
 *   - Honeywell MICROpeL MP-741 combustible gas sensor
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V
 *   MCP3008 VREF -> 3.3 V
 *   MCP3008 AGND -> GND
 *   MCP3008 DGND -> GND
 *   MCP3008 CLK  -> GPIO 11 (SPI0 SCLK)
 *   MCP3008 DOUT -> GPIO 9  (SPI0 MISO)
 *   MCP3008 DIN  -> GPIO 10 (SPI0 MOSI)
 *   MCP3008 CS   -> GPIO 8  (SPI0 CE0)
 *   MCP3008 CH0  -> MP-741 analog output
 *   MP-741 VCC   -> 5 V
 *   MP-741 GND   -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o gas_detector gas_detector.c -lpigpio -lrt
 *   Run with sudo (pigpio requires root).
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0          /* CE0 / GPIO 8 */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */
#define ADC_CHANNEL    0          /* MCP3008 single-ended channel 0 */
#define ADC_MAX_VALUE  1023       /* 10-bit ADC */
#define VREF           3.3        /* MCP3008 reference voltage */
#define SAMPLE_PERIOD  1          /* seconds between readings */
#define RETRY_DELAY    0.1        /* 100 ms back-off on error */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* MCP3008 read                                                         */
/* ------------------------------------------------------------------ */
/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care bits)
 *   tx[2] = 0x00                       (clock out remaining bits)
 * Result: 10-bit value assembled from rx[1] (low 2 bits) and rx[2] (8 bits).
 */
static int mcp3008_read(int spi_handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Voltage conversion                                                  */
/* ------------------------------------------------------------------ */
static float adc_to_voltage(int adc_value)
{
    return ((float)adc_value / (float)ADC_MAX_VALUE) * VREF;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(float voltage, float ppm)
{
    FILE *fp = fopen("gas_log.txt", "a");
    if (!fp) {
        perror("Error opening gas_log.txt");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, %.3f, %.3f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                voltage, ppm);
    } else {
        fprintf(fp, "[timestamp-error], %.3f, %.3f\n", voltage, ppm);
    }

    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Install signal handlers for graceful shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open SPI0 CE0 at 1 MHz, mode 0 --- */
    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Propane Leak Detector running. Press Ctrl+C to exit.\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        int adc_value = mcp3008_read(spi_handle, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read failed; retrying in %.1f s...\n",
                    RETRY_DELAY);
            time_sleep(RETRY_DELAY);
            continue;
        }

        float voltage = adc_to_voltage(adc_value);
        float ppm = voltage * 100.0;   /* placeholder calibration curve */

        printf("Voltage: %.3f V, PPM: %.3f\n", voltage, ppm);

        log_data(voltage, ppm);

        time_sleep(SAMPLE_PERIOD);
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    spiClose(spi_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

