 *   MCP3008 DGND -> GND  (pin 6)
 *   MCP3008 CLK  -> GPIO11 (BCM 11, SCLK)
 *   MCP3008 DOUT -> GPIO9  (BCM 9,  MISO)
 *   MCP3008 DIN  -> GPIO10 (BCM 10, MISO)
 *   MCP3008 CS   -> GPIO8  (BCM 8,  CE0)
 *   MCP3008 CH0  -> ADXL335 X-out
 *   MCP3008 CH1  -> ADXL335 Y-out
 *   MCP3008 CH2  -> ADXL335 Z-out
 *   ADXL335 VCC  -> 3.3 V
 *   ADXL335 GND  -> GND
 *   ADXL335 SDA  -> GPIO2 (BCM 2, optional if using breakout)
 *
 * Build: gcc -O2 -Wall -o adxl335_mcp3008 adxl335_mcp3008.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U
#define SPI_BITS        8U
#define SPI_MODE        SPI_MODE_0

#define ADC_CHANNEL_X   0
#define ADC_CHANNEL_Y   1
#define ADC_CHANNEL_Z   2

#define ADC_MAX_VALUE   1023U
#define ADC_VREF        3.3f

#define SAMPLE_PERIOD_US 100000U  /* 10 Hz */

/* Kalman filter parameters */
#define Q_ANGLE       0.001f
#define Q_BIAS        0.003f
#define R_MEASUREMENT 0.03f

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* SPI helpers                                                         */
/* ------------------------------------------------------------------ */

static int spi_init(const char *device)
{
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("open(" SPI_DEVICE ")");
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl(SPI_IOC_WR_MODE)");
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl(SPI_IOC_WR_BITS_PER_WORD)");
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl(SPI_IOC_WR_MAX_SPEED_HZ)");
        close(fd);
        return -1;
    }

    return fd;
}

/*
 * MCP3008 single-ended read.
 * Returns 0..1023 on success, -1 on error.
 */
static int mcp3008_read(int fd, uint8_t channel)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid channel %u\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI frame (mode 0, MSB-first):
     *   Byte 0: 0x01  (start bit)
     *   Byte 1: (0x08 | channel) << 4  -> single-ended + channel, upper nibble
     *   Byte 2: 0x00  (don't care, clocked out to read low byte)
     *
     * Response:
     *   Byte 1: bits 7..2 undefined, bit 1 = null bit, bits 0..0 = result MSB..LSB
     *   Byte 2: bits 7..0 = result LSB..MSB
     */
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = sizeof(tx);
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("ioctl(SPI_IOC_MESSAGE)");
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Kalman filter                                                      */
/* ------------------------------------------------------------------ */

typedef struct {
    float state;
    float error;
    float P[2][2];
} kalman_state_t;

static void kalman_init(kalman_state_t *s)
{
    s->state        = 0.0f;
    s->error        = 0.0f;
    s->P[0][0]      = 1.0f;
    s->P[0][1]      = 0.0f;
    s->P[1][0]      = 0.0f;
    s->P[1][1]      = 1.0f;
}

static float kalman_update(kalman_state_t *s, float measurement)
{
    float y = measurement - s->state;
    float S = s->P[0][0] + s->P[1][1];

    float K0 = s->P[0][0] / S;
    float K1 = s->P[1][0] / S;

    s->state += K0 * y;
    s->error += K1 * y;

    s->P[0][0] -= K0 * s->P[0][0];
    s->P[0][1] -= K0 * s->P[0][1];
    s->P[1][0] -= K1 * s->P[0][0];
    s->P[1][1] -= K1 * s->P[1][1];

    return s->state;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    int spi_fd = spi_init(SPI_DEVICE);
    if (spi_fd < 0) {
        return EXIT_FAILURE;
    }

    printf("ADXL335 via MCP3008 on %s (10 Hz). Ctrl+C to exit.\n", SPI_DEVICE);

    while (g_running) {
        int x_raw = mcp3008_read(spi_fd, ADC_CHANNEL_X);
        int y_raw = mcp3008_read(spi_fd, ADC_CHANNEL_Y);
        int z_raw = mcp3008_read(spi_fd, ADC_CHANNEL_Z);

        if (x_raw < 0 || y_raw < 0 || z_raw < 0) {
            fprintf(stderr, "SPI read error; continuing.\n");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        float x_g = (float)x_raw / (float)ADC_MAX_VALUE * ADC_VREF * 9.8f;
        float y_g = (float)y_raw / (float)ADC_MAX_VALUE * ADC_VREF * 9.8f;
        float z_g = (float)z_raw / (float)ADC_MAX_VALUE * ADC_VREF * 9.8f;

        kalman_state_t kx, ky, kz;
        kalman_init(&kx); kalman_init(&ky); kalman_init(&kz);

        float x_filt = kalman_update(&kx, x_g);
        float y_filt = kalman_update(&ky, y_g);
        float z_filt = kalman_update(&kz, z_g);

        printf("X: %+.4f g  Y: %+.4f g  Z: %+.4f g\n", x_filt, y_filt, z_filt);

        usleep(SAMPLE_PERIOD_US);
    }

    if (close(spi_fd) < 0) {
        perror("close(spi_fd)");
        return EXIT_FAILURE;
    }
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

