 * Build:  gcc -O2 -Wall -Wextra -o magnetic_monitor magnetic_monitor.c
 * Run:    sudo ./magnetic_monitor   (or ensure user is in the 'gpio' group)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>

#include <gpiod.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define SENSOR1_PIN  4
#define SENSOR2_PIN  17
#define SENSOR3_PIN  27

/* ---- Magnetic field limits (millitesla) ---- */
#define MIN_MILLITESLA (-100.0f)
#define MAX_MILLITESLA  100.0f

/* ---- Sampling interval (microseconds) ---- */
#define SAMPLE_INTERVAL_US 100000

/* ---- Log file path ---- */
#define LOG_FILE "magnetic_log.txt"

/* ---- Global state for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static struct gpiod_chip  *g_chip   = NULL;
static struct gpiod_line  *g_line1 = NULL;
static struct gpiod_line  *g_line2 = NULL;
static struct gpiod_line  *g_line3 = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read a GPIO line value. Returns 0 or 1, or -1 on error.            */
static int read_sensor(struct gpiod_line *line)
{
    int val = gpiod_line_get_value(line);
    if (val < 0) {
        fprintf(stderr, "Error reading GPIO line: %s\n", strerror(errno));
        return -1;
    }
    return val;
}

/* ------------------------------------------------------------------ */
/* Convert a digital state (0 or 1) to a magnetic field strength in mT. */
static float state_to_millitesla(int state)
{
    if (state == 1) {
        return MAX_MILLITESLA;
    }
    if (state == 0) {
        return MIN_MILLITESLA;
    }
    return 0.0f;  /* should never happen */
}

/* ------------------------------------------------------------------ */
/* Log the three magnetic field values to the CSV file.               */
static int log_data(float v1, float v2, float v3)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f,%.2f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                v1, v2, v3);
    } else {
        fprintf(fp, "1970-01-01 00:00:00,%.2f,%.2f,%.2f\n", v1, v2, v3);
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "Warning: fflush failed: %s\n", strerror(errno));
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Warning: fclose failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Release all GPIO resources.                                        */
static void cleanup(void)
{
    if (g_line1)  gpiod_line_release(g_line1);
    if (g_line2)  gpiod_line_release(g_line2);
    if (g_line3)  gpiod_line_release(g_line3);
    if (g_chip)   gpiod_chip_close(g_chip);
    g_line1 = g_line2 = g_line3 = NULL;
    g_chip   = NULL;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGTERM) failed: %s\n", strerror(errno));
    }

    /* ---- Open the default gpiochip (gpiochip0 on RPi 3B+) ---- */
    g_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!g_chip) {
        fprintf(stderr, "Error opening gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Get lines for the three sensors ---- */
    g_line1 = gpiod_chip_get_line(g_chip, SENSOR1_PIN);
    if (!g_line1) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", SENSOR1_PIN, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    g_line2 = gpiod_chip_get_line(g_chip, SENSOR2_PIN);
    if (!g_line2) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", SENSOR2_PIN, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    g_line3 = gpiod_chip_get_line(g_chip, SENSOR3_PIN);
    if (!g_line3) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", SENSOR3_PIN, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Request each line as input ---- */
    if (gpiod_line_request_input(g_line1, "drv5055_monitor") < 0) {
        fprintf(stderr, "Error requesting GPIO %d as input: %s\n", SENSOR1_PIN, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_input(g_line2, "drv5055_monitor") < 0) {
        fprintf(stderr, "Error requesting GPIO %d as input: %s\n", SENSOR2_PIN, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_input(g_line3, "drv5055_monitor") < 0) {
        fprintf(stderr, "Error requesting GPIO %d as input: %s\n", SENSOR3_PIN, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("DRV5055VA Hall-Effect sensor monitor started.\n");
    printf("Logging to %s every %d ms. Press Ctrl-C to stop.\n",
           LOG_FILE, SAMPLE_INTERVAL_US / 1000);

    /* ---- Main sampling loop ---- */
    while (g_running) {
        int s1 = read_sensor(g_line1);
        int s2 = read_sensor(g_line2);
        int s3 = read_sensor(g_line3);

        if (s1 < 0 || s2 < 0 || s3 < 0) {
            fprintf(stderr, "Sensor read error — skipping this sample.\n");
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        float m1 = state_to_millitesla(s1);
        float m2 = state_to_millitesla(s2);
        float m3 = state_to_millitesla(s3);

        if (m1 < MIN_MILLITESLA || m1 > MAX_MILLITESLA) {
            fprintf(stderr, "Warning: sensor1 value %.2f mT out of range — skipping log.\n", m1);
        }
        if (m2 < MIN_MILLITESLA || m2 > MAX_MILLITESLA) {
            fprintf(stderr, "Warning: sensor2 value %.2f mT out of range — skipping log.\n", m2);
        }
        if (m3 < MIN_MILLITESLA || m3 > MAX_MILLITESLA) {
            fprintf(stderr, "Warning: sensor3 value %.2f mT out of range — skipping log.\n", m3);
        }

        if (log_data(m1, m2, m3) != 0) {
            fprintf(stderr, "Error logging data — continuing.\n");
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    cleanup();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

