/*
 * Soil moisture monitor with pump control using MCP3008 ADC and pigpio.
 *
 * Hardware (Raspberry Pi 4 Model B):
 *   - MCP3008 ADC on SPI0 (CE0, 500 kHz, mode 0)
 *   - Soil moisture sensor on MCP3008 channel 0 (single-ended)
 *   - Pump relay on GPIO17 (BCM), active-high
 *
 * Build:  gcc -O2 -Wall -o watering watering.c -lpigpio -lrt
 * Run:    sudo ./watering
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0          /* CE0 */
#define SPI_SPEED      500000     /* 500 kHz */
#define SPI_FLAGS      0          /* mode 0, active-low CE */
#define PUMP_GPIO      17
#define MOISTURE_THRESHOLD 30.0f
#define LOG_FILE       "watering.log"
#define SAMPLE_INTERVAL 60        /* seconds between readings */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;

/* ------------------------------------------------------------------ */
/* Logging                                                            */
/* ------------------------------------------------------------------ */
static void log_event(const char *msg)
{
    if (!g_log)
        return;

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }

    fprintf(g_log, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    fflush(g_log);
}

/* ------------------------------------------------------------------ */
/* Signal handling                                                    */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* MCP3008 read (single-ended, channel 0-7)                           */
/* Returns 0-1023 on success, -1 on error.                             */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int spi_handle, int channel)
{
    if (channel < 0 || channel > 7) {
        log_event("Invalid MCP3008 channel requested");
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
     *   tx[2] = 0x00                       (clock out low bits)
     * Result: 10-bit value in rx[1] (low 2 bits) and rx[2] (8 bits).
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        log_event("SPI transfer failed");
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Moisture percentage (0-100)                                       */
/* ------------------------------------------------------------------ */
static float calculate_moisture(int adc_value)
{
    if (adc_value < 0)   adc_value = 0;
    if (adc_value > 1023) adc_value = 1023;
    return ((float)adc_value / 1023.0f) * 100.0f;
}

/* ------------------------------------------------------------------ */
/* Pump control                                                      */
/* ------------------------------------------------------------------ */
static void control_pump(int pump_state)
{
    if (gpioWrite(PUMP_GPIO, pump_state) != 0) {
        log_event("Failed to write pump GPIO");
        return;
    }
    log_event(pump_state ? "Pump ON" : "Pump OFF");
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                            */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Ensure pump is off before releasing pigpio */
    gpioWrite(PUMP_GPIO, 0);
    gpioTerminate();
    if (g_log) {
        log_event("Program terminated");
        fclose(g_log);
        g_log = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- open log file --- */
    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        perror("fopen(" LOG_FILE ")");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_event("Program started");

    /* --- pump GPIO setup --- */
    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        log_event("Failed to set pump GPIO mode");
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(PUMP_GPIO, 0);   /* pump off at start */

    /* --- SPI open --- */
    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        log_event("SPI open failed");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- signals --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* --- main loop --- */
    int pump_state = 0;   /* 0 = off, 1 = on */
    int consecutive_errors = 0;

    while (g_running) {
        int adc = read_mcp3008(spi_handle, 0);
        if (adc < 0) {
            consecutive_errors++;
            log_event("ADC read error");
            if (consecutive_errors >= 10) {
                log_event("Too many consecutive ADC errors, aborting");
                break;
            }
            sleep(SAMPLE_INTERVAL);
            continue;
        }
        consecutive_errors = 0;

        float moisture = calculate_moisture(adc);
        char msg[128];
        snprintf(msg, sizeof(msg),
                 "Moisture: %.2f%% (ADC=%d)", moisture, adc);
        log_event(msg);

        if (moisture < MOISTURE_THRESHOLD && !pump_state) {
            control_pump(1);
            pump_state = 1;
        } else if (moisture >= MOISTURE_THRESHOLD && pump_state) {
            control_pump(0);
            pump_state = 0;
        }

        sleep(SAMPLE_INTERVAL);
    }

    cleanup();
    return EXIT_SUCCESS;
}

