#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <stdbool.h>
#include <pigpio.h>

#define MQTT_BROKER "tcp://mqtt.eclipseprojects.io:1883"
#define MQTT_CLIENT_ID "rpi_led_control"
#define MQTT_TOPIC "home/led_control"
#define LED_GPIO 17
#define JSON_PARSER "json_parser.c"
#define MAX_RECONNECT_DELAY 60
#define MIN_RECONNECT_DELAY 1

static volatile sig_atomic_t running = 1;
static int gpio_initialized = 0;
static int mqtt_initialized = 0;
static int reconnect_delay = MIN_RECONNECT_DELAY;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "%s: %s\n", timestamp, message);
}

static int parse_json(const char *json_string, int *led_state) {
    char *json_copy = strdup(json_string);
    if (json_copy == NULL) {
        log_error("Failed to allocate memory for JSON copy");
        return -1;
    }

    char *key = strtok(json_copy, ":");
    char *value = strtok(NULL, ":");
    free(json_copy);

    if (key == NULL || value == NULL) {
        log_error("JSON format error: expected key:value pair");
        return -1;
    }

    if (strcmp(key, "led_state") != 0) {
        log_error("Invalid JSON key: expected 'led_state'");
        return -1;
    }

    if (strcmp(value, "true") != 0 && strcmp(value, "False") != 0 && strcmp(value, "false") != 0) {
        log_error("Invalid JSON value: expected 'true' or 'false'");
        return -1;
    }

    *led_state = (strcmp(value, "true") == 0) ? 1 : 0;
    return 0;
}

static int control_led(int led_state) {
    if (gpio_initialized) {
        if (gpioWrite(LED_GPIO, led_state) != 0) {
            log_error("Failed to write to GPIO");
            return -1;
        }
    }
    return 0;
}

static void reconnect_mqtt() {
    log_error("Attempting to reconnect to MQTT broker...");

    int rc = mosquitto_reconnect(mqtt);
    if (rc != MOSQ_ERR_SUCCESS) {
        log_error("MQTT reconnect failed");
        return;
    }

    rc = mosquitto_loop_start(mqtt);
    if (rc != MOSQ_ERR_SUCCESS) {
        log_error("Failed to start MQTT loop after reconnect");
        mosquitto_disconnect(mqtt);
        mqtt_initialized = 0;
        return;
    }

    log_error("MQTT reconnected successfully");
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        log_error("Failed to set up signal handlers");
        return 1;
    }

    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return 1;
    }
    gpio_initialized = 1;

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        log_error("Failed to set GPIO mode");
        gpioTerminate();
        return 1;
    }

    int rc = mosquitto_lib_init();
    if (rc != MOSQ_ERR_SUCCESS) {
        log_error("mosquitto_lib_init failed");
        gpioTerminate();
        return 1;
    }

    mqtt = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (mqtt == NULL) {
        log_error("Failed to create MQTT client");
        mosquitto_lib_cleanup();
        gpioTerminate();
        return 1;
    }
    mqtt_initialized = 1;

    rc = mosquitto_connect(mqtt, MQTT_BROKER, 1883, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        log_error("Failed to connect to MQTT broker");
        mosquitto_destroy(mqtt);
        mosquitto_lib_cleanup();
        gpioTerminate();
        return 1;
    }

    rc = mosquitto_subscribe(mqtt, NULL, MQTT_TOPIC, 0);
    if (rc != MOSQ_ERR_SUCCESS) {
        log_error("Failed to subscribe to MQTT topic");
        mosquitto_disconnect(mqtt);
        mosquitto_destroy(mqtt);
        mosquitto_lib_cleanup();
        gpioTerminate();
        return 1;
    }

    log_error("MQTT connection established successfully");

    while (running) {
        char buffer[256];
        int bytes_read = mosquitto_read(mqtt, buffer, sizeof(buffer) - 1);

        if (bytes_read > 0) {
            buffer[bytes_read] = '\0';
            int led_state;
            if (parse_json(buffer, &led_state) == 0) {
                if (control_led(led_state) != 0) {
                    log_error("Failed to control LED");
                }
            } else {
                log_error("Failed to parse JSON");
            }
        } else if (bytes_read == 0) {
            log_error("MQTT read returned 0 bytes");
        } else {
            log_error("MQTT read error");
            reconnect_mqtt();
        }

        sleep(1);
    }

    log_error("Shutting down...");

    if (gpio_initialized) {
        gpioWrite(LED_GPIO, 0);
    }

    if (mqtt_initialized) {
        mosquitto_disconnect(mqtt);
        mosquitto_destroy(mqtt);
        mosquitto_lib_cleanup();
    }

    if (gpio_initialized) {
        gpioTerminate();
    }

    return 0;
}

