/*
 * KY038 Sound Sensor Monitor for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   KY038 DO  -> GPIO17 (BCM)
 *   KY038 VCC -> 3.3 V (pin 1)
 *   KY038 GND -> GND  (pin 9)
 *   Alarm LED -> GPIO18 (BCM) via 330 Ω resistor
 *
 * The KY038 digital output (DO) is LOW when sound exceeds the onboard
 * potentiometer threshold.  We read the pin and invert the value so that
 * 1 in the console indicates a sound event.
 *
 * Build:  gcc -O2 -Wall -Wextra -o sound_monitor sound_monitor.c -lpigpio -lrt
 * Run:    sudo ./sound_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <pigpio.h>

#define SOUND_SENSOR_PIN 17          /* KY038 DO  (BCM) */
#define ALARM_LED_PIN    18          /* Alarm LED (BCM) */

#define POLL_DELAY_US   100000       /* 100 ms between readings */
#define ALARM_DURATION_S 1           /* Alarm on for 1 s */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly               */
/* ------------------------------------------------------------------ */
static void signal_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — release all GPIO resources                         */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Release the alarm LED line if it was acquired */
    if (gpioInitialise() >= 0) {
        gpioWrite(ALARM_LED_PIN, 0);   /* best-effort LED off */
        gpioSetMode(ALARM_LED_PIN, PI_INPUT);
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Install signal handlers for graceful shutdown ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio library ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (code %d).\n",
                gpioInitialise());
        return EXIT_FAILURE;
    }

    /* ---- Configure sound sensor pin as input ---- */
    if (gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n",
                SOUND_SENSOR_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Configure alarm LED pin as output and ensure it is OFF ---- */
    if (gpioSetMode(ALARM_LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n",
                ALARM_LED_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioWrite(ALARM_LED_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize GPIO%d LOW.\n",
                ALARM_LED_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Sound sensor monitoring started.\n");
    printf("  Sensor DO : GPIO%d (KY038 DO, LOW = sound event)\n",
           SOUND_SENSOR_PIN);
    printf("  Alarm LED : GPIO%d\n", ALARM_LED_PIN);
    printf("Press Ctrl-C to exit.\n");

    /* ---- Main polling loop ---- */
    while (g_running) {
        int level = gpioRead(SOUND_SENSOR_PIN);

        if (level < 0) {
            fprintf(stderr, "Error: gpioRead failed on GPIO%d (code %d).\n",
                    SOUND_SENSOR_PIN, level);
            break;
        }

        /* KY038 DO is LOW when sound exceeds the threshold; invert */
        int sound_detected = (level == 0) ? 1 : 0;

        printf("Sound level: %d\n", sound_detected);

        if (sound_detected) {
            printf("Sound event detected — activating alarm LED.\n");

            if (gpioWrite(ALARM_LED_PIN, 1) != 0) {
                fprintf(stderr, "Error: failed to turn on alarm LED.\n");
                break;
            }

            /* Sleep in small increments so SIGINT is caught promptly */
            for (int i = 0; i < ALARM_DURATION_S * 10 && g_running; i++) {
                gpioDelay(100000);   /* 100 ms */
            }

            if (gpioWrite(ALARM_LED_PIN, 0) != 0) {
                fprintf(stderr, "Error: failed to turn off alarm LED.\n");
                break;
            }
            printf("Alarm deactivated.\n");
        }

        /* 100 ms delay between readings */
        gpioDelay(POLL_DELAY_US);
    }

    /* ---- Graceful cleanup ---- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

