        fprintf(stderr, "Error: pigpio initialization failed (code %d).\n",
                gpioInitialise());
        return EXIT_FAILURE;
    }

    /* ---- Configure sound sensor pin as input ---- */
    if (gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n",
                SOUND_SENSOR_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Configure alarm LED pin as output and ensure it is OFF ---- */
    if (gpioSetMode(ALARM_LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n",
                ALARM_LED_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioWrite(ALARM_LED_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize GPIO%d LOW.\n",
                ALARM_LED_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Sound sensor monitoring started.\n");
    printf("  Sensor DO : GPIO%d (KY038 DO, LOW = sound event)\n",
           SOUND_SENSOR_PIN);
    printf("  Alarm LED : GPIO%d\n", ALARM_LED_PIN);
    printf("Press Ctrl-C to exit.\n");

    /* ---- Main polling loop ---- */
    while (g_running) {
        int level = gpioRead(SOUND_SENSOR_PIN);

        if (level < 0) {
            fprintf(stderr, "Error: gpioRead failed on GPIO%d (code %d).\n",
                    SOUND_SENSOR_PIN, level);
            break;
        }

        /* KY038 DO is LOW when sound exceeds the threshold; invert */
        int sound_detected = (level == 0) ? 1 : 0;

        printf("Sound level: %d\n", sound_detected);

        if (sound_detected) {
            printf("Sound event detected — activating alarm LED.\n");

            if (gpioWrite(ALARM_LED_PIN, 1) != 0) {
                fprintf(stderr, "Error: failed to turn on alarm LED.\n");
                break;
            }

            /* Sleep in small increments so SIGINT is caught promptly */
            for (int i = 0; i < ALARM_DURATION_S * 10 && g_running; i++) {
                gpioDelay(100000);   /* 100 ms */
            }

            if (gpioWrite(ALARM_LED_PIN, 0) != 0) {
                fprintf(stderr, "Error: failed to turn off alarm LED.\n");
                break;
            }
            printf("Alarm deactivated.\n");
        }

        /* 100 ms delay between readings */
        gpioDelay(POLL_DELAY_US);
    }

    /* ---- Graceful cleanup ---- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

