#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>
#include <linux/gpiochip.h>

#define GPIO_CHIP_PATH "/dev/gpiochip0"
#define GPIO_LINE_OFFSET 17
#define LOG_FILE_PATH "/var/log/vibration_shutdown.log"
#define CONSUMER_LABEL "vibration-monitor"
#define POLL_TIMEOUT_MS 1000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signum) {
    (void)signum;
    program_running = 0;
}

static void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE_PATH, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) != NULL) {
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
        fprintf(fp, "%s: %s\n", timestamp, message);
    } else {
        fprintf(fp, "(unknown time): %s\n", message);
    }

    if (fclose(fp) != 0) {
        perror("Error closing log file");
    }
}

static int request_falling_edge_event(int gpio_fd, const char *consumer_label) {
    struct gpio_request_config config = {
        .consumer = consumer_label,
        .request_type = GPIOD_LINE_REQUEST_EVENT_FALLING_EDGE,
        .flags = 0,
    };

    if (ioctl(gpio_fd, GPIOD_LINE_REQUEST, &config) < 0) {
        perror("Error requesting falling edge event");
        return -1;
    }

    return 0;
}

static int read_event(int gpio_fd, struct gpio_event event) {
    struct gpio_event_buffer buffer = {
        .size = 1,
        .events = &event,
    };

    if (ioctl(gpio_fd, GPIOD_LINE_EVENT_READ, &buffer) < 0) {
        perror("Error reading event");
        return -1;
    }

    return 0;
}

int main(void) {
    int gpio_fd = -1;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Error installing SIGINT handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Error installing SIGTERM handler");
        return EXIT_FAILURE;
    }

    gpio_fd = open(GPIO_CHIP_PATH, O_RDWR);
    if (gpio_fd < 0) {
        perror("Error opening GPIO chip");
        return EXIT_FAILURE;
    }

    if (ioctl(gpio_fd, GPIO_GET_LINE EINVAL, NULL) < 0) {
        perror("Error getting GPIO line offset");
        goto cleanup_gpio;
    }

    if (ioctl(gpio_fd, GPIO_GET_LINE_OFFSET, &GPIO_LINE_OFFSET) < 0) {
        perror("Error getting GPIO line offset");
        goto cleanup_gpio;
    }

    if (ioctl(gpio_fd, GPIO_GET_LINE_DIRECTION, &GPIO_LINE_OFFSET) < 0) {
        perror("Error getting GPIO line direction");
        goto cleanup_gpio;
    }

    if (ioctl(gpio_fd, GPIO_GET_LINE_VALUE, &GPIO_LINE_OFFSET) < 0) {
        perror("Error getting GPIO line value");
        goto cleanup_gpio;
    }

    if (ioctl(gpio_fd, GPIO_SET_LINE_DIRECTION, &GPIO_LINE_OFFSET) < 0) {
        perror("Error setting GPIO line direction");
        goto cleanup_gpio;
    }

    if (ioctl(gpio_fd, GPIO_SET_LINE_VALUE, &GPIO_LINE_OFFSET) < 0) {
        perror("Error setting GPIO line value");
        goto cleanup_gpio;
    }

    if (request_falling_edge_event(gpio_fd, CONSUMER_LABEL) < 0) {
        goto cleanup_gpio;
    }

    printf("Vibration monitoring started on GPIO%d. Press Ctrl+C to exit.\n", GPIO_LINE_OFFSET);

    while (program_running) {
        struct timespec ts = { .tv_sec = POLL_TIMEOUT_MS / 1000, .tv_nsec = (POLL_TIMEOUT_MS % 1000) * 1000000L };
        int r = select(gpio_fd + 1, NULL, NULL, NULL, &ts);

        if (r < 0) {
            if (errno == EINTR) {
                continue;
            }
            perror("Error in select()");
            break;
        }

        if (r == 0) {
            continue;
        }

        struct gpio_event event;
        if (read_event(gpio_fd, event) < 0) {
            break;
        }

        if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
            char message[256];
            snprintf(message, sizeof(message), "Vibration detected on GPIO%d", GPIO_LINE_OFFSET);
            log_event(message);
            printf("%s\n", message);

            system("sudo shutdown -h now");
            break;
        }
    }

    ret = EXIT_SUCCESS;

cleanup_gpio:
    if (gpio_fd >= 0) {
        if (ioctl(gpio_fd, GPIOD_LINE_RELEASE, &GPIO_LINE_OFFSET) < 0) {
            perror("Error releasing GPIO line");
        }
        close(gpio_fd);
    }

    return ret;
}

