    dig_P8 = (int16_t)(data[20] | (data[21] << 8));
    dig_P9 = (int16_t)(data[22] | (data[23] << 8));
    return 0;
}

static int read_raw_data(int32_t *raw_temp, int32_t *raw_press) {
    uint8_t data[6];
    if (i2cReadI2CBlockData(i2c_handle, BMP280_REG_PRESS_MSB, (char *)data, 6) != 6) {
        fprintf(stderr, "Error: Failed to read raw pressure/temperature data from BMP280\n");
        return -1;
    }
    *raw_press = ((int32_t)data[0] << 12) | ((int32_t)data[1] << 4) | ((int32_t)data[2] >> 4);
    *raw_temp = ((int32_t)data[3] << 12) | ((int32_t)data[4] << 4) | ((int32_t)data[5] >> 4);
    return 0;
}

static double compensate_temperature(int32_t raw_temp) {
    double var1 = ((double)raw_temp / 16384.0 - (double)dig_T1 / 1024.0) * (double)dig_T2;
    double var2 = ((double)raw_temp / 131072.0 - (double)dig_T1 / 8192.0) *
                  ((double)raw_temp / 131072.0 - (double)dig_T1 / 8192.0) * (double)dig_T3;
    return (var1 + var2) / 5120.0;
}

static double compensate_pressure(int32_t raw_press, double temp_compensated) {
    double var1 = (double)temp_compensated / 2.0 - 64000.0;
    double var2 = var1 * var1 * (double)dig_P6 / 32768.0;
    var2 = var2 + var1 * (double)dig_P5 * 2.0;
    var2 = (var2 / 4.0) + ((double)dig_P4 * 65536.0);
    var1 = ((double)dig_P3 * var1 * var1 / 524288.0 + (double)dig_P2 * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * (double)dig_P1;
    if (var1 == 0.0) return 0.0;
    double p = 1048576.0 - (double)raw_press;
    p = (p - (var2 / 4096.0)) * 6250.0 / var1;
    var1 = (double)dig_P9 * p * p / 2147483648.0;
    var2 = p * (double)dig_P8 / 32768.0;
    p = p + (var1 + var2 + (double)dig_P7) / 16.0;
    return p;
}

static double calculate_altitude(double pressure) {
    return 44330.0 * (1.0 - pow(pressure / 1013.25, 0.1903));
}

static int log_altitude(double altitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: Failed to get local time\n");
        return -1;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);
    if (fprintf(log_file, "%s,%.2f\n", timestamp, altitude) < 0) {
        fprintf(stderr, "Error: Failed to write to log file\n");
        return -1;
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error: Failed to flush log file\n");
        return -1;
    }
    return 0;
}

static int initialize_bmp280(void) {
    int chip_id = i2cReadByteData(i2c_handle, BMP280_REG_ID);
    if (chip_id < 0) {
        fprintf(stderr, "Error: Failed to read chip ID from BMP280\n");
        return -1;
    }
    if (chip_id != BMP280_CHIP_ID) {
        fprintf(stderr, "Error: Invalid chip ID 0x%02X (expected 0x%02X). Sensor not present.\n", chip_id, BMP280_CHIP_ID);
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, BMP280_REG_RESET, BMP280_RESET_CMD) < 0) {
        fprintf(stderr, "Error: Failed to reset BMP280\n");
        return -1;
    }
    gpioDelay(2000);
    if (read_calibration_data() != 0) return -1;
    if (i2cWriteByteData(i2c_handle, BMP280_REG_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write config register\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, BMP280_REG_CTRL_MEAS, 0x27) < 0) {
        fprintf(stderr, "Error: Failed to write ctrl_meas register\n");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set up signal handlers\n");
        return 1;
    }
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus 1 at address 0x%02X\n", BMP280_I2C_ADDR);
        gpioTerminate();
        return 1;
    }
    if (initialize_bmp280() != 0) {
        fprintf(stderr, "Error: BMP280 initialization failed\n");
        cleanup();
        return 1;
    }
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }
    printf("BMP280 initialized. Logging altitude to %s every %d seconds. Press Ctrl+C to exit.\n", LOG_FILE, SAMPLE_INTERVAL_SEC);
    while (running) {
        int32_t raw_temp, raw_press;
        if (read_raw_data(&raw_temp, &raw_press) == 0) {
            double temp_compensated = compensate_temperature(raw_temp);
            double pressure = compensate_pressure(raw_press, temp_compensated);
            double altitude = calculate_altitude(pressure);
            if (log_altitude(altitude) != 0) {
                fprintf(stderr, "Warning: Failed to log altitude data\n");
            }
        } else {
            fprintf(stderr, "Warning: Failed to read sensor data, retrying next cycle\n");
        }
        for (int i = 0; i < SAMPLE_INTERVAL_SEC && running; i++) {
            gpioSleep(PI_TIME_RELATIVE, 1, 0);
        }
    }
    printf("\nExiting gracefully...\n");
    cleanup();
    return 0;
}

