#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_BITS         8
#define SPI_MODE         0
#define MCP3008_CHANNEL  0
#define BUFFER_SIZE      120
#define SAMPLE_INTERVAL  5
#define LOG_FILE         "temp_log.dat"

typedef struct {
    float buffer[BUFFER_SIZE];
    int   head;
    int   count;
} CircularBuffer;

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int init_spi(void) {
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Error: cannot open %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error: SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error: SPI_IOC_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error: SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    return 0;
}

static int read_mcp3008(int channel) {
    if (g_spi_fd < 0) return -1;

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
        .len           = 3,
        .speed_hz      = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs   = 0,
        .cs_change     = 0,
    };

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error: SPI_IOC_MESSAGE failed: %s\n", strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static float adc_to_celsius(int adc_value) {
    return (float)adc_value * 0.0625f;
}

static void cb_init(CircularBuffer *cb) {
    memset(cb->buffer, 0, sizeof(cb->buffer));
    cb->head  = 0;
    cb->count = 0;
}

static void cb_add(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
}

static void cb_write_file(CircularBuffer *cb) {
    FILE *fp = fopen(LOG_FILE, "wb+");
    if (!fp) {
        fprintf(stderr, "Error: cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }

    size_t items = (size_t)cb->count;
    if (items > BUFFER_SIZE) items = BUFFER_SIZE;

    for (int i = 0; i < items; i++) {
        float v = cb->buffer[(cb->head - i + BUFFER_SIZE) % BUFFER_SIZE];
        if (fwrite(&v, sizeof(v), 1, fp) != 1) {
            fprintf(stderr, "Error: fwrite failed: %s\n", strerror(errno));
            fclose(fp);
            return;
        }
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error: fclose failed: %s\n", strerror(errno));
    }
}

static void cb_print(CircularBuffer *cb) {
    printf("Temperature: ");
    for (int i = 0; i < cb->count; i++) {
        int idx = (cb->head - cb->count + BUFFER_SIZE) % BUFFER_SIZE;
        printf("%.2f", cb->buffer[idx]);
        if (i < cb->count - 1) printf(" ");
    }
    printf(" °C\n");
    fflush(stdout);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return 1;
    }

    if (init_spi() < 0) {
        return 1;
    }

    CircularBuffer cb;
    cb_init(&cb);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int adc = read_mcp3008(MCP3008_CHANNEL);
        if (adc < 0) {
            fprintf(stderr, "Warning: ADC read failed, skipping sample\n");
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        float temp = adc_to_celsius(adc);
        cb_add(&cb, temp);
        cb_print(&cb);

        cb_write_file(&cb);

        sleep(SAMPLE_INTERVAL);
    }

    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }

    printf("\nExiting gracefully.\n");
    return 0;
}

