#define BH1750_PWR_ON   0x01
#define BH1750_RESET    0x07
#define BH1750_CONT_HRES 0x10  /* high-resolution, 1 lx resolution, ~120 ms */

/* ---- MCP3008 ---- */
#define MCP3008_START_BIT 0x01
#define MCP3008_ADC_MAX  1023

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
