    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */

static int i2c_write_byte(int fd, uint8_t byte)
{
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write(0x%02X) failed: %s\n", byte, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int fd, uint8_t *out)
{
    uint8_t buf;
    ssize_t n = read(fd, &buf, 1);
    if (n != 1) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    *out = buf;
    return 0;
}

static int bh1750_init(int fd)
{
    if (i2c_write_byte(fd, BH1750_PWR_ON) < 0) return -1;
    if (i2c_write_byte(fd, BH1750_RESET) < 0) return -1;
    return 0;
}

static int bh1750_read_lux(int fd, float *lux_out)
{
    if (i2c_write_byte(fd, BH1750_CONT_HRES) < 0) return -1;

    /* 120 ms conversion time — poll every 5 ms until data-ready */
    for (int i = 0; i < 24; i++) {
        uint8_t status;
        if (i2c_read_byte(fd, &status) < 0) return -1;
        if (status & 0x01) break;          /* bit 0 = data ready */
        usleep(5000);
    }

    uint8_t raw;
    if (i2c_read_byte(fd, &raw) < 0) return -1;

    /* 16-bit result, big-endian */
    uint16_t val = ((uint16_t)(raw & 0x7F) << 8) | raw >> 7;
    *lux_out = (float)val / 1.2f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* SPI / MCP3008 helpers                                               */
/* ------------------------------------------------------------------ */

static int spi_init(void)
{
    int fd = open(SPI_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", SPI_BUS, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE_0;
    uint8_t bits = 8;
    uint32_t speed = 1000000;  /* 1 MHz */

    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        close(fd); return -1;
    }
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        close(fd); return -1;
    }
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        close(fd); return -1;
    }
    return fd;
}

/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (single-ended + channel)
 *   tx[2] = 0x00                       (don't care)
