    tr.bits_per_word = 8;
    tr.delay_usecs = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE failed: %s\n", strerror(errno));
        return -1;
    }

    *adc_out = ((rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

