/*
 * KY026 Flame Sensor Monitor for Raspberry Pi 5
 * Reads digital output on BCM pin 17, logs to flame_events.log, prints alarm.
 *
 * Build:  gcc -O2 -Wall -Wextra -o flame_monitor flame_monitor.c -lpigpio -lrt
 * Run:    sudo ./flame_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLAME_PIN      17          /* BCM pin number */
#define LOG_FILE       "flame_events.log"
#define POLL_INTERVAL  1           /* seconds between readings */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly               */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a timestamped CSV line to the log file                      */
/* ------------------------------------------------------------------ */
static int log_event(int pin, int state)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("time()");
        fclose(fp);
        return -1;
    }

    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        perror("localtime_r()");
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%d,%d\n", ts, pin, state) < 0) {
        perror("fprintf()");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose()");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure flame sensor pin ---- */
    if (gpioSetMode(FLAME_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_INPUT) failed\n", FLAME_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Enable internal pull-down so the pin reads LOW when no flame. */
    if (gpioSetPullUpDown(FLAME_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "gpioSetPullUpDown(%d, PI_PUD_DOWN) failed\n", FLAME_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Main polling loop ---- */
    while (g_running) {
        int level = gpioRead(FLAME_PIN);
        if (level < 0) {
            fprintf(stderr, "gpioRead(%d) failed\n", FLAME_PIN);
            gpioTerminate();
            return EXIT_FAILURE;
        }

        if (log_event(FLAME_PIN, level) != 0) {
            /* Logging failed — keep running but report the error. */
            fprintf(stderr, "Warning: failed to log event (pin=%d, state=%d)\n",
                    FLAME_PIN, level);
        }

        if (level == 1) {
            printf("ALARM: Flame detected on GPIO %d\n", FLAME_PIN);
            fflush(stdout);
        }

        sleep(POLL_INTERVAL);
    }

    /* ---- Clean shutdown ---- */
    gpioTerminate();
    return EXIT_SUCCESS;
}

