    if (log_file != NULL) {
        fprintf(log_file, "%s, Sensor %d, Moisture Level: %d\n", timestamp, sensor_id, moisture_level);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
