#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RELAY1_PIN 17
#define RELAY2_PIN 22
#define RELAY3_PIN 23
#define RELAY4_PIN 24

#define RELAY_COUNT 4

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static int safe_set_mode(unsigned pin, unsigned mode)
{
    if (gpioSetMode(pin, mode) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, %u) failed\n", pin, mode);
        return -1;
    }
    return 0;
}

static int safe_set_value(unsigned pin, unsigned level)
{
    if (gpioWrite(pin, level) != 0) {
        fprintf(stderr, "Error: gpioWrite(%u, %u) failed\n", pin, level);
        return -1;
    }
    return 0;
}

static int safe_set_all_values(void)
{
    if (safe_set_value(RELAY1_PIN, 0) != 0) return -1;
    if (safe_set_value(RELAY2_PIN, 0) != 0) return -1;
    if (safe_set_value(RELAY3_PIN, 0) != 0) return -1;
    if (safe_set_value(RELAY4_PIN, 0) != 0) return -1;
    return 0;
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (safe_set_mode(RELAY1_PIN, PI_OUTPUT) != 0 ||
        safe_set_mode(RELAY2_PIN, PI_OUTPUT) != 0 ||
        safe_set_mode(RELAY3_PIN, PI_OUTPUT) != 0 ||
        safe_set_mode(RELAY4_PIN, PI_OUTPUT) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (safe_set_all_values() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        for (int i = 0; i < RELAY_COUNT && running; i++) {
            unsigned pin = RELAY1_PIN + i;
            if (safe_set_value(pin, 1) != 0) break;
            printf("Relay %d (BCM pin %u) activated\n", i + 1, pin);
            sleep(1);
            if (!running) break;
            if (safe_set_value(pin, 0) != 0) break;
            printf("Relay %d (BCM pin %u) deactivated\n", i + 1, pin);
            sleep(1);
        }
    }

    safe_set_all_values();
    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return EXIT_SUCCESS;
}

