    if (safe_set_all_values() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        for (int i = 0; i < RELAY_COUNT && running; i++) {
            unsigned pin = RELAY1_PIN + i;
            if (safe_set_value(pin, 1) != 0) break;
            printf("Relay %d (BCM pin %u) activated\n", i + 1, pin);
            sleep(1);
            if (!running) break;
            if (safe_set_value(pin, 0) != 0) break;
            printf("Relay %d (BCM pin %u) deactivated\n", i + 1, pin);
            sleep(1);
        }
    }

    safe_set_all_values();
    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return EXIT_SUCCESS;
}

