/*
 * rain.c — Raspberry Pi 3 Model B+
 *
 * Reads a Seeed Studio Grove Rain Sensor via an MCP3008 on SPI channel 0
 * (mode 0, 1 MHz), logs rain level with timestamp to rain_log.txt once per
 * second, and drives a L298N DC motor on GPIO17/18 (IN1/IN2) and GPIO27
 * (PWM) to close or open the window based on a rain threshold of 5.
 *
 * Build:  gcc -O2 -Wall -Wextra -o rain rain.c -lthe -lrt -lpthread
 * Run:    sudo ./rain
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <the/driver.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_DEVICE        "/dev/spidev0.0"
#define SPI_SPEED_HZ      1000000U   /* 1 MHz */
#define SPI_BITS_PER_WORD 8
#define SPI_MODE          0

#define RAIN_THRESHOLD    5
#define MOTOR_FORWARD     1
#define MOTOR_REVERSE    -1
#define MOTOR_STOP       0
#define MOTOR_RUN_TIME_S 3
#define POLL_INTERVAL_S  1

#define LOG_FILE          "rain_log.txt"
#define LOG_LINE_MAX      256

/* L298N driver pins (BCM numbering) */
#define MOTOR_IN1_PIN     17
#define MOTOR_IN2_PIN     18
#define MOTOR_ENA_PIN     27

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_spi_fd   = -1;
static FILE    *g_log_file = NULL;

/* --------------------------- Function prototypes ------------------------- */
static int  spi_init(void);
static int  spi_read_channel(int channel, uint16_t *out);
static int  read_rain_level(uint16_t *level);
static int  log_rain_level(uint16_t level);
static int  control_window(int close_window);
static void signal_handler(int sig);
static void cleanup(void);

/* ------------------------------- SPI ------------------------------------- */
static int spi_init(void)
{
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Error: cannot open %s: %s\n",
                SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error: SPI_IOC_WR_MODE failed: %s\n",
                strerror(errno));
        close(g_spi_fd); g_spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error: SPI_IOC_WR_BITS_PER_WORD failed: %s\n",
                strerror(errno));
        close(g_spi_fd); g_spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error: SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n",
                strerror(errno));
        close(g_spi_fd); g_spi_fd = -1;
        return -1;
    }

    return 0;
}

/*
 * MCP3008 single-ended read.
 * 3-byte transfer: [start] [SGL|D2|D1|D0|0|0|0|0] [0x00]
 * Result: bits 9..0 are in rx[1] (low 2 bits) and rx[2] (8 bits).
 */
static int spi_read_channel(int channel, uint16_t *out)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid MCP3008 channel %d\n", channel);
        return -1;
    }
    if (out == NULL) {
        return -1;
    }

    uint8_t tx[3] = {
        0x01,
        (uint8_t)((0x08 | channel) << 4),
        0x00
    };
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = 3;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS_PER_WORD;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error: SPI_IOC_MESSAGE failed: %s\n",
                strerror(errno));
        return -1;
    }

    *out = ((uint16_t)(rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

/* --------------------------- Rain sensor ------------------------------- */
static int read_rain_level(uint16_t *level)
{
    if (level == NULL) {
        return -1;
    }

    if (spi_read_channel(0, level) < 0) {
        return -1;
    }

    /* Grove Rain Sensor: 0 = dry, 1023 = soaked */
    return 0;
}

/* --------------------------- Logging ------------------------------------ */
static int log_rain_level(uint16_t level)
{
    if (g_log_file == NULL) {
        return -1;
    }

    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "Error: time() failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    if (t == NULL) {
        fprintf(stderr, "Error: localtime_r() failed\n");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t) == 0) {
        fprintf(stderr, "Error: strftime() failed\n");
        return -1;
    }

    if (fprintf(g_log_file, "%s, Rain Level: %u\n", ts, level) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed: %s\n",
                strerror(errno));
        return -1;
    }

    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "Warning: fflush failed: %s\n", strerror(errno));
    }

    return 0;
}

/* --------------------------- Motor control ------------------------------ */
static int control_window(int close_window)
{
    if (close_window != MOTOR_FORWARD && close_window != MOTOR_REVERSE &&
        close_window != MOTOR_STOP) {
        fprintf(stderr, "Error: invalid motor direction %d\n", close_window);
        return -1;
    }

    if (the_driver_init() < 0) {
        fprintf(stderr, "Error: the_driver_init() failed\n");
        return -1;
    }

    int in1_pin  = BCM_PIN_TO_GPIO(MOTOR_IN1_PIN);
    int in2_pin  = BCM_PIN_TO_GPIO(MOTOR_IN2_PIN);
    int ena_pin  = BCM_PIN_TO_GPIO(MOTOR_ENA_PIN);

    if (in1_pin < 0 || in2_pin < 0 || ena_pin < 0) {
        fprintf(stderr, "Error: BCM pin mapping invalid\n");
        the_driver_cleanup();
        return -1;
    }

    int direction = close_window;
    int speed     = 150;          /* 0–255 */

    if (direction == MOTOR_FORWARD) {
        the_driver_set_direction(in1_pin, in2_pin, 1);
        the_driver_set_pwm(ena_pin, speed);
    } else if (direction == MOTOR_REVERSE) {
        the_driver_set_direction(in1_pin, in2_pin, 0);
        the_driver_set_pwm(ena_pin, speed);
    } else {
        the_driver_set_direction(in1_pin, in2_pin, 0);
        the_driver_set_pwm(ena_pin, 0);
    }

    /* Sleep in 100 ms slices so we can respond to signals promptly. */
    for (int i = 0; i < MOTOR_RUN_TIME_S * 10 && g_running; i++) {
        usleep(100000);
    }

    the_driver_set_direction(in1_pin, in2_pin, 0);
    the_driver_set_pwm(ena_pin, 0);

    the_driver_cleanup();
    return 0;
}

/* --------------------------- Signal handling ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- Cleanup ------------------------------------- */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    the_driver_cleanup();
}

/* --------------------------------- main ---------------------------------- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction(SIGINT) failed: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction(SIGTERM) failed: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    if (spi_init() < 0) {
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: cannot open %s: %s\n",
                LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    int window_closed = 0;

    while (g_running) {
        uint16_t rain_level = 0;

        if (read_rain_level(&rain_level) < 0) {
            fprintf(stderr, "Error: failed to read rain level\n");
        } else {
            if (log_rain_level(rain_level) < 0) {
                fprintf(stderr, "Error: failed to log rain level\n");
            }

            int close_window = (rain_level > RAIN_THRESHOLD) ? 1 : 0;

            if (close_window != window_closed) {
                if (control_window(close_window) < 0) {
                    fprintf(stderr, "Error: motor control failed\n");
                }
                window_closed = close_window;
            }
        }

        /* Sleep in 100 ms slices so signals are caught promptly. */
        for (int i = 0; i < POLL_INTERVAL_S * 10 && g_running; i++) {
            usleep(100000);
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

