    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error: SPI_IOC_MESSAGE failed: %s\n",
                strerror(errno));
        return -1;
    }

    *out = ((uint16_t)(rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

/* --------------------------- Rain sensor ------------------------------- */
static int read_rain_level(uint16_t *level)
{
    if (level == NULL) {
        return -1;
    }

    if (spi_read_channel(0, level) < 0) {
        return -1;
    }

    /* Grove Rain Sensor: 0 = dry, 1023 = soaked */
    return 0;
}

/* --------------------------- Logging ------------------------------------ */
static int log_rain_level(uint16_t level)
{
    if (g_log_file == NULL) {
        return -1;
    }

    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "Error: time() failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    if (t == NULL) {
        fprintf(stderr, "Error: localtime_r() failed\n");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t) == 0) {
        fprintf(stderr, "Error: strftime() failed\n");
        return -1;
    }

    if (fprintf(g_log_file, "%s, Rain Level: %u\n", ts, level) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed: %s\n",
                strerror(errno));
        return -1;
    }

    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "Warning: fflush failed: %s\n", strerror(errno));
    }

    return 0;
}

/* --------------------------- Motor control ------------------------------ */
static int control_window(int close_window)
{
    if (close_window != MOTOR_FORWARD && close_window != MOTOR_REVERSE &&
        close_window != MOTOR_STOP) {
        fprintf(stderr, "Error: invalid motor direction %d\n", close_window);
        return -1;
    }

    if (the_driver_init() < 0) {
        fprintf(stderr, "Error: the_driver_init() failed\n");
        return -1;
    }

    int in1_pin  = BCM_PIN_TO_GPIO(MOTOR_IN1_PIN);
    int in2_pin  = BCM_PIN_TO_GPIO(MOTOR_IN2_PIN);
    int ena_pin  = BCM_PIN_TO_GPIO(MOTOR_ENA_PIN);

    if (in1_pin < 0 || in2_pin < 0 || ena_pin < 0) {
        fprintf(stderr, "Error: BCM pin mapping invalid\n");
        the_driver_cleanup();
        return -1;
    }

    int direction = close_window;
    int speed     = 150;          /* 0–255 */

    if (direction == MOTOR_FORWARD) {
        the_driver_set_direction(in1_pin, in2_pin, 1);
        the_driver_set_pwm(ena_pin, speed);
    } else if (direction == MOTOR_REVERSE) {
        the_driver_set_direction(in1_pin, in2_pin, 0);
        the_driver_set_pwm(ena_pin, speed);
    } else {
        the_driver_set_direction(in1_pin, in2_pin, 0);
        the_driver_set_pwm(ena_pin, 0);
    }

    /* Sleep in 100 ms slices so we can respond to signals promptly. */
    for (int i = 0; i < MOTOR_RUN_TIME_S * 10 && g_running; i++) {
        usleep(100000);
    }

    the_driver_set_direction(in1_pin, in2_pin, 0);
    the_driver_set_pwm(ena_pin, 0);

    the_driver_cleanup();
    return 0;
}

/* --------------------------- Signal handling ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- Cleanup ------------------------------------- */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    the_driver_cleanup();
}

/* --------------------------------- main ---------------------------------- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction(SIGINT) failed: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction(SIGTERM) failed: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    if (spi_init() < 0) {
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: cannot open %s: %s\n",
                LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    int window_closed = 0;

    while (g_running) {
        uint16_t rain_level = 0;

        if (read_rain_level(&rain_level) < 0) {
            fprintf(stderr, "Error: failed to read rain level\n");
        } else {
            if (log_rain_level(rain_level) < 0) {
                fprintf(stderr, "Error: failed to log rain level\n");
            }

            int close_window = (rain_level > RAIN_THRESHOLD) ? 1 : 0;

            if (close_window != window_closed) {
                if (control_window(close_window) < 0) {
                    fprintf(stderr, "Error: motor control failed\n");
                }
                window_closed = close_window;
            }
        }

        /* Sleep in 100 ms slices so signals are caught promptly. */
        for (int i = 0; i < POLL_INTERVAL_S * 10 && g_running; i++) {
            usleep(100000);
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

