/*
 * Clap detection with MAX9814 microphone on Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   MAX9814 OUT  -> BCM GPIO26 (ADC input)
 *   MAX9814 VDD -> 3.3 V
 *   MAX9814 GND -> GND
 *   LED anode    -> BCM GPIO16 via 330 Ω resistor
 *   LED cathode  -> GND
 *
 * The MAX9814 has an internal 12-bit ADC; this program bit-bangs a
 * 10-bit ADC via a 10-bit shift register on BCM GPIO26, sampling at
 * 100 Hz and detecting a clap (falling edge) with a 50 ms debounce.
 * On a valid clap, the LED is pulsed for 500 ms.
 *
 * Build:  gcc -O2 -Wall -Wextra -o clap clap.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

/* ----------------------------- Configuration ----------------------------- */

#define ADC_PIN        26          /* BCM GPIO26 — bit-banged 10-bit ADC input */
#define LED_PIN        16          /* BCM GPIO16 — LED control              */

#define SAMPLE_RATE_HZ  100        /* 10 ms per sample (100 Hz)            */
#define DEBOUNCE_MS    50          /* 50 ms debounce window                */
#define LED_PULSE_MS   500         /* LED on-time per clap                 */
#define POLL_DELAY_US  10000       /* 10 ms between samples                */

/* ----------------------------- Globals ---------------------------------- */

static volatile sig_atomic_t g_running = 1;

/* ----------------------------- Signal handler ---------------------------- */

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ----------------------------- Timestamp --------------------------------- */

static void print_timestamp(void)
{
    time_t now = time(NULL);
    struct tm tmv;
    char buf[32];

    if (localtime_r(&now, &tmv) != NULL) {
        strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &tmv);
        printf("[%s] ", buf);
    } else {
        printf("[unknown] ");
    }
}

/* ----------------------------- LED helpers -------------------------------- */

static void led_on(void)
{
    if (g_running) {
        if (gpioWrite(LED_PIN, 1) < 0)
            perror("gpioWrite(LED on)");
    }
}

static void led_off(void)
{
    if (g_running) {
        if (gpioWrite(LED_PIN, 0) < 0)
            perror("gpioWrite(LED off)");
    }
}

/* ----------------------------- ADC bit-bang -------------------------------- */

/*
 * MAX9814 internal ADC: 12-bit, 0–4095.  We bit-bang a 10-bit ADC on
 * BCM GPIO26 using a shift register.  Each sample takes ~10 ms.
 * Returns the 10-bit value (0–1023) or -1 on error.
 */
static int adc_read(void)
{
    int value = 0;

    /* --- Rising edge: start of sample --- */
    if (gpioWrite(ADC_PIN, 1) < 0) {
        perror("gpioWrite(ADC high)");
        return -1;
    }
    usleep(1);  /* settle */

    /* --- Sample: 10-bit read --- */
    for (int i = 0; i < 10; i++) {
        if (gpioWrite(ADC_PIN, 0) < 0) {
            perror("gpioWrite(ADC low)");
            return -1;
        }
        usleep(1);

        /* Read 10 data bits, MSB first */
        for (int b = 9; b >= 0; b--) {
            if (gpioRead(ADC_PIN) == 0) {
                value |= (1 << b);
            }
            usleep(1);
        }
    }

    /* --- Falling edge: end of sample --- */
    if (gpioWrite(ADC_PIN, 1) < 0) {
        perror("gpioWrite(ADC high)");
        return -1;
    }
    usleep(1);

    return value;
}

/* ----------------------------- Clap detection ----------------------------- */

static bool clap_detected(int current, int last, int *last_clap_ms)
{
    /* Falling edge: clap detected */
    if (current == 0 && last != 0) {
        if (*last_clap_ms == 0) {
            *last_clap_ms = (int)(clock() / 1000.0);  /* ms */
        }

        int elapsed = (int)(clock() / 1000.0) - *last_clap_ms;
        if (elapsed >= DEBOUNCE_MS) {
            *last_clap_ms = (int)(clock() / 1000.0);
            return true;
        }
    }
    return false;
}

/* ----------------------------- Main --------------------------------------- */

int main(void)
{
    /* --- Signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure ADC pin as output (bit-bang) --- */
    if (gpioSetMode(ADC_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(ADC) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Configure LED pin as output --- */
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(LED) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure LED is off at start */
    led_off();

    int last_sample = 1;   /* assume no input at start */
    int last_clap_ms = 0;

    printf("Clap detection started.  Press Ctrl+C to exit.\n");

    while (g_running) {
        int sample = adc_read();
        if (sample < 0) {
            print_timestamp();
            fprintf(stderr, "ADC read error — continuing\n");
            usleep(POLL_DELAY_US);
            continue;
        }

        bool clap = clap_detected(sample, last_sample, &last_clap_ms);

        if (clap) {
            print_timestamp();
            printf("Clap detected!\n");
            led_on();
            usleep(LED_PULSE_MS * 1000);
            led_off();
        }

        last_sample = sample;
        usleep(POLL_DELAY_US);
    }

    /* --- Cleanup --- */
    led_off();
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

