/*
 * Soil Moisture Monitor with MCP3008 ADC and Relay Pump Control
 * Board:  Raspberry Pi 3 Model B+
 * SPI:    CE0 (GPIO8), SCLK=GPIO11, MOSI=GPIO10, MISO=GPIO9
 * ADC:    MCP3008, single-ended channel 0
 * Pump:   12 V submersible pump via relay on GPIO17 (BCM)
 *
 * Build:  gcc -O2 -Wall -o soil_monitor soil_monitor.c -lpigpio -lrt
 * Run:    sudo ./soil_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0          /* CE0 */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */

#define ADC_CHANNEL    0          /* MCP3008 single-ended channel 0 */
#define ADC_MAX_VALUE  1023       /* 10-bit ADC */

#define PUMP_GPIO      17         /* BCM 17 */
#define PUMP_ON        1          /* Relay is active-high */

#define MOISTURE_THRESHOLD 50     /* Percentage */
#define SAMPLE_INTERVAL   60      /* Seconds */
#define LOG_FILE         "soil_moisture.log"

static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read MCP3008 single-ended channel (0-7)                              */
/* Returns 0-1023 on success, -1 on SPI error, -2 on invalid channel  */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI protocol (3 bytes):
     *   Byte 0: 0x01  (start bit)
     *   Byte 1: (0x08 | channel) << 4  -> single-ended + channel, upper nibble
     *   Byte 2: 0x00  (don't care, clocks out low 2 bits)
     *
     * Response:
     *   rx[0] = ignored
     *   rx[1] = [null bit][b9 b8] in upper nibble
     *   rx[2] = b7..b0
     */
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(SPI_CHANNEL, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: SPI transfer failed (ret=%d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    if (adc_value < 0 || adc_value > ADC_MAX_VALUE) {
        fprintf(stderr, "Error: ADC value out of range: %d\n", adc_value);
        return -1;
    }
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Convert ADC value to moisture percentage                           */
/* ------------------------------------------------------------------ */
static int adc_to_moisture_pct(int adc_value)
{
    if (adc_value < 0) adc_value = 0;
    if (adc_value > ADC_MAX_VALUE) adc_value = ADC_MAX_VALUE;
    return (int)(((float)adc_value / (float)ADC_MAX_VALUE) * 100.0f);
}

/* ------------------------------------------------------------------ */
/* Log a reading                                                        */
/* ------------------------------------------------------------------ */
static void log_data(int moisture_pct, int pump_status)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32] = { 0 };

    if (t) {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    } else {
        snprintf(ts, sizeof(ts), "UNKNOWN");
    }

    fprintf(g_log, "%s, Moisture: %d%%, Pump: %s\n",
            ts, moisture_pct, pump_status ? "ON" : "OFF");
    fflush(g_log);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log) {
        fclose(g_log);
        g_log = NULL;
    }
    /* Ensure pump is off before terminating pigpio */
    gpioWrite(PUMP_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- SPI init --------------------------------------------------- */
    int spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Pump GPIO init --------------------------------------------- */
    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: cannot set GPIO%d as output\n", PUMP_GPIO);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(PUMP_GPIO, 0);  /* Pump off at startup */

    /* --- Log file --------------------------------------------------- */
    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        fprintf(stderr, "Error: cannot open log file '%s'\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handling -------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");
    printf("Sampling every %d seconds. Threshold: %d%%\n",
           SAMPLE_INTERVAL, MOISTURE_THRESHOLD);

    /* --- Main loop -------------------------------------------------- */
    while (g_running) {
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: ADC read failed, retrying in %d s\n",
                    SAMPLE_INTERVAL);
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        int moisture_pct = adc_to_moisture_pct(adc_value);

        int pump_status = (moisture_pct < MOISTURE_THRESHOLD) ? PUMP_ON : 0;

        if (gpioWrite(PUMP_GPIO, pump_status) != 0) {
            fprintf(stderr, "Warning: failed to write pump GPIO %d\n", PUMP_GPIO);
        }

        log_data(moisture_pct, pump_status);

        printf("ADC: %4d  Moisture: %3d%%  Pump: %s\n",
               adc_value, moisture_pct, pump_status ? "ON" : "OFF");

        sleep(SAMPLE_INTERVAL);
    }

    /* --- Graceful shutdown ----------------------------------------- */
    printf("\nShutting down...\n");
    cleanup();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

