        fprintf(stderr, "Failed to set LED pin %d as output\n", LED_PIN);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    gpioWrite(LED_PIN, 0);

    printf("Monitoring magnetic field on MCP3008 channel %d. Press Ctrl+C to exit.\n", ADC_CHANNEL);

    while (running) {
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read failed, retrying in 100ms...\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        float magnetic_field = adc_to_magnetic_field(adc_value);
        printf("ADC: %4d, Magnetic Field: %.2f mT\n", adc_value, magnetic_field);

