/*
 * Raspberry Pi Zero W – MLX91211 current sensor via MCP3008 ADC on SPI0
 *
 * Wiring:
 *   MCP3008 VDD  -> 3V3 (Pi pin 1)
 *   MCP3008 VREF -> 3V3 (Pi pin 1)
 *   MCP3008 AGND -> GND
 *   MCP3008 DGND -> GND
 *   MCP3008 CLK  -> GPIO11 (SPI0 SCLK)
 *   MCP3008 DOUT -> GPIO9  (SPI0 MISO)
 *   MCP3008 DIN  -> GPIO10 (SPI0 MOSI)
 *   MCP3008 CS   -> GPIO8  (SPI0 CE0)
 *   MCP3008 CH0  -> MLX91211 analog output
 *   MLX91211 VDD -> 3V3
 *   MLX91211 GND -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o current_monitor current_monitor.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#include <linux/spi/spidev.h>
#include <sys/ioctl.h>
#include <fcntl.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U
#define SPI_BITS        8
#define SPI_MODE        SPI_MODE_0
#define ADC_CHANNEL     0
#define ADC_MAX_VALUE   1023U
#define ADC_VREF        3.3f
#define SAMPLE_PERIOD_US 100000U
#define LOG_FILE        "current_log.txt"

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/*
 * Read a single-ended sample from the MCP3008.
 * Returns 0 on success and stores the 10-bit result in *out_value.
 * Returns -1 on SPI transfer failure.
 */
static int mcp3008_read(int spi_fd, uint8_t channel, uint16_t *out_value)
{
    if (channel > 7U) {
        fprintf(stderr, "Invalid ADC channel %u\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: rx[1] low 2 bits + rx[2] 8 bits = 10-bit value.
     */
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = sizeof(tx);
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("SPI transfer failed");
        return -1;
    }

    *out_value = (uint16_t)(((rx[1] & 0x03) << 8) | rx[2]);
    return 0;
}

static float adc_to_current(uint16_t adc_value, float vref)
{
    return ((float)adc_value / (float)ADC_MAX_VALUE) * vref;
}

static int log_current(FILE *fp, float current)
{
    time_t     rawtime;
    struct tm  timeinfo;
    char       timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        perror("localtime_r failed");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s %.2f A\n", timestamp, current) < 0) {
        perror("fprintf to log file failed");
        return -1;
    }

    if (fflush(fp) != 0) {
        perror("fflush failed");
        return -1;
    }

    return 0;
}

int main(void)
{
    int      spi_fd = -1;
    FILE    *log_fp = NULL;
    int      rc     = EXIT_SUCCESS;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT) failed");
        return EXIT_FAILURE;
    }

    /* Open the SPI device */
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open(" SPI_DEVICE ") failed");
        return EXIT_FAILURE;
    }

    /* Configure SPI mode */
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("SPI_IOC_WR_MODE failed");
        rc = EXIT_FAILURE;
        goto cleanup_spi;
    }

    /* Configure SPI bits per word */
    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("SPI_IOC_WR_BITS_PER_WORD failed");
        rc = EXIT_FAILURE;
        goto cleanup_spi;
    }

    /* Configure SPI max speed */
    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("SPI_IOC_WR_MAX_SPEED_HZ failed");
        rc = EXIT_FAILURE;
        goto cleanup_spi;
    }

    /* Open the log file in append mode */
    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        perror("fopen(" LOG_FILE ") failed");
        rc = EXIT_FAILURE;
        goto cleanup_spi;
    }

    printf("Monitoring MLX91211 on MCP3008 channel %d every %d ms. Press Ctrl+C to stop.\n",
           ADC_CHANNEL, SAMPLE_PERIOD_US / 1000U);

    while (g_running) {
        uint16_t adc_value = 0;

        if (mcp3008_read(spi_fd, ADC_CHANNEL, &adc_value) != 0) {
            fprintf(stderr, "SPI read error – skipping sample\n");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        float current = adc_to_current(adc_value, ADC_VREF);

        if (current < 0.0f || current > 5.0f) {
            fprintf(stderr, "Warning: current %.2f A out of 0–5 V range – skipping sample\n", current);
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        if (log_current(log_fp, current) != 0) {
            fprintf(stderr, "Logging failed – continuing\n");
        }

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nExiting cleanly.\n");

    if (log_fp != NULL) {
        if (fclose(log_fp) != 0) {
            perror("fclose(log_fp) failed");
            rc = EXIT_FAILURE;
        }
    }

cleanup_spi:
    if (spi_fd >= 0) {
        if (close(spi_fd) != 0) {
            perror("close(spi_fd) failed");
            rc = EXIT_FAILURE;
        }
    }

    return rc;
}

