        return -1;
    }

    if (fflush(fp) != 0) {
        perror("fflush failed");
        return -1;
    }

    return 0;
}

int main(void)
{
    int      spi_fd = -1;
    FILE    *log_fp = NULL;
    int      rc     = EXIT_SUCCESS;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT) failed");
        return EXIT_FAILURE;
    }

    /* Open the SPI device */
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open(" SPI_DEVICE ") failed");
        return EXIT_FAILURE;
    }

    /* Configure SPI mode */
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("SPI_IOC_WR_MODE failed");
        rc = EXIT_FAILURE;
        goto cleanup_spi;
    }

    /* Configure SPI bits per word */
    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("SPI_IOC_WR_BITS_PER_WORD failed");
        rc = EXIT_FAILURE;
        goto cleanup_spi;
    }

    /* Configure SPI max speed */
    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("SPI_IOC_WR_MAX_SPEED_HZ failed");
        rc = EXIT_FAILURE;
        goto cleanup_spi;
    }

    /* Open the log file in append mode */
    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        perror("fopen(" LOG_FILE ") failed");
        rc = EXIT_FAILURE;
        goto cleanup_spi;
    }

    printf("Monitoring MLX91211 on MCP3008 channel %d every %d ms. Press Ctrl+C to stop.\n",
           ADC_CHANNEL, SAMPLE_PERIOD_US / 1000U);

    while (g_running) {
        uint16_t adc_value = 0;

        if (mcp3008_read(spi_fd, ADC_CHANNEL, &adc_value) != 0) {
            fprintf(stderr, "SPI read error – skipping sample\n");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        float current = adc_to_current(adc_value, ADC_VREF);

        if (current < 0.0f || current > 5.0f) {
            fprintf(stderr, "Warning: current %.2f A out of 0–5 V range – skipping sample\n", current);
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        if (log_current(log_fp, current) != 0) {
            fprintf(stderr, "Logging failed – continuing\n");
        }

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nExiting cleanly.\n");

    if (log_fp != NULL) {
        if (fclose(log_fp) != 0) {
            perror("fclose(log_fp) failed");
            rc = EXIT_FAILURE;
        }
    }

cleanup_spi:
    if (spi_fd >= 0) {
        if (close(spi_fd) != 0) {
            perror("close(spi_fd) failed");
            rc = EXIT_FAILURE;
        }
    }

    return rc;
}

