#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define DEBOUNCE_READINGS 5
#define DEBOUNCE_DELAY_US 2000
#define POLL_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor(int pin) {
    int sum = 0;
    for (int i = 0; i < DEBOUNCE_READINGS; i++) {
        int v = gpioRead(pin);
        if (v < 0) {
            fprintf(stderr, "Error: gpioRead failed on pin %d (rc=%d)\n", pin, v);
            return -1;
        }
        sum += v;
        if (i < DEBOUNCE_READINGS - 1)
            gpioDelay(DEBOUNCE_DELAY_US);
    }
    return (sum > (DEBOUNCE_READINGS / 2)) ? 0 : 1;
}

static void log_sensor(int pin, int state) {
    printf("Sensor %d: %s\n", pin, state ? "0" : "1");
}

static void check_alert(int s1, int s2) {
    if (s1 == 0 && s2 == 0) {
        printf("ALERT: Both sensors detect object\n");
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for pin %d\n", SENSOR_1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for pin %d\n", SENSOR_2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for pin %d\n", SENSOR_1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for pin %d\n", SENSOR_2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Proximity sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int s1 = read_sensor(SENSOR_1_PIN);
        int s2 = read_sensor(SENSOR_2_PIN);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "Error: sensor read failed, exiting\n");
            break;
        }

        log_sensor(SENSOR_1_PIN, s1);
        log_sensor(SENSOR_2_PIN, s2);
        check_alert(s1, s2);

        if (gpioDelay(POLL_INTERVAL_US) < 0) {
            fprintf(stderr, "Error: gpioDelay failed\n");
            break;
        }
    }

    gpioTerminate();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

