#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include "driver.h"

#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define MCP3008_CHANNEL 0
#define READ_DELAY 60
#define MIN_ADC 300
#define MAX_ADC 800
#define LOG_FILE "soil_moisture_log.csv"

static int spi_handle = -1;
static volatile sig_atomic_t program_running = 1;

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = {0x01, (uint8_t)((0x08 | channel) << 4), 0x00};
    uint8_t rx[3] = {0};

    if (spi_transfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static double calculate_moisture_level(int adc_value) {
    if (adc_value < MIN_ADC) adc_value = MIN_ADC;
    if (adc_value > MAX_ADC) adc_value = MAX_ADC;
    return (double)(adc_value - MIN_ADC) / (MAX_ADC - MIN_ADC) * 100.0;
}

static void log_data(double moisture_level) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f\n", timestamp, moisture_level);
    fclose(fp);

    printf("%s,%.2f\n", timestamp, moisture_level);
}

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static int spi_setup(spi_config_t config) {
    spi_handle = spi_open(config.channel, config.baud, config.flags);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: spi_open failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

int main(void) {
    spi_config_t config = {
        .channel = SPI_CHANNEL,
        .baud = SPI_BAUD,
        .flags = 0
    };

    if (spi_setup(config) != 0) {
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Could not register signal handler\n");
        spi_close(spi_handle);
        spi_close_config(config);
        return 1;
    }

    printf("Soil Moisture Monitoring Started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value, retrying in %d seconds...\n", READ_DELAY);
            sleep(READ_DELAY);
            continue;
        }

        double moisture_level = calculate_moisture_level(adc_value);
        log_data(moisture_level);

        sleep(READ_DELAY);
    }

    printf("\nExiting gracefully...\n");
    spi_close(spi_handle);
    spi_close_config(config);
    return 0;
}

