#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <errno.h>
#include <syslog.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>

#define GPIO_CHIP "/dev/gpiochip0"
#define GPIO_PIN 17
#define DEBOUNCE_DELAY_MS 200
#define POLL_INTERVAL_MS 50
#define IMAGE_DIR "/home/pi/security_cam/"
#define MAX_FILENAME_LENGTH 256

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int gpio_init(void) {
    int fd = open(GPIO_CHIP, O_RDWR);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open GPIO chip %s: %s", GPIO_CHIP, strerror(errno));
        return -1;
    }
    if (ioctl(fd, GPIO_GET_LINE EINVAL) < 0) {
        syslog(LOG_ERR, "Failed to get GPIO line %d: %s", GPIO_PIN, strerror(errno));
        close(fd);
        return -1;
    }
    if (ioctl(fd, GPIO_SET_MODE, GPIO_PIN) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO %d as input: %s", GPIO_PIN, strerror(errno));
        close(fd);
        return -1;
    }
    if (ioctl(fd, GPIO_SET_PUD, GPIO_PIN) < 0) {
        syslog(LOG_ERR, "Failed to set pull-down on GPIO %d: %s", GPIO_PIN, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int gpio_read(int fd) {
    int val = 0;
    if (ioctl(fd, GPIO_GET_VALUE, &val) < 0) {
        syslog(LOG_ERR, "Failed to read GPIO %d: %s", GPIO_PIN, strerror(errno));
        return -1;
    }
    return val;
}

static int capture_image(const char *filename) {
    pid_t pid = fork();
    if (pid < 0) {
        syslog(LOG_ERR, "Failed to fork for capture: %s", strerror(errno));
        return -1;
    }
    if (pid == 0) {
        execlp("libcamera-still", "libcamera-still", "-o", filename, "--nopreview", "-q", "85", (char *)NULL);
        _exit(127);
    }
    int status = 0;
    if (waitpid(pid, &status, 0) < 0) {
        syslog(LOG_ERR, "Failed to wait for libcamera-still: %s", strerror(errno));
        return -1;
    }
    if (WIFEXITED(status) && WEXITSTATUS(status) == 0) {
        return 0;
    }
    syslog(LOG_ERR, "libcamera-still exited with status %d", WEXITSTATUS(status));
    return -1;
}

static int ensure_image_dir(void) {
    struct stat st;
    if (stat(IMAGE_DIR, &st) == 0) {
        if (S_ISDIR(st.st_mode)) {
            return 0;
        }
        syslog(LOG_ERR, "Path %s exists but is not a directory", IMAGE_DIR);
        return -1;
    }
    if (mkdir(IMAGE_DIR, 0755) < 0) {
        syslog(LOG_ERR, "Failed to create directory %s: %s", IMAGE_DIR, strerror(errno));
        return -1;
    }
    return 0;
}

static int get_timestamp(char *buf, size_t len) {
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        syslog(LOG_ERR, "Failed to get local time");
        return -1;
    }
    if (strftime(buf, len, "%Y%m%d_%H%M%S", timeinfo) == 0) {
        syslog(LOG_ERR, "Failed to format timestamp");
        return -1;
    }
    return 0;
}

static int save_image(const char *filename) {
    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) {
        syslog(LOG_ERR, "Failed to open %s for writing: %s", filename, strerror(errno));
        return -1;
    }
    if (fwrite("image_data", 1, 1, fp) != 1) {
        syslog(LOG_ERR, "Failed to write image header to %s", filename);
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        syslog(LOG_ERR, "Failed to close %s: %s", filename, strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    openlog("security_cam", LOG_PID | LOG_CONS, LOG_USER);
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to register SIGINT handler: %s", strerror(errno));
        closelog();
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to register SIGTERM handler: %s", strerror(errno));
        closelog();
        return 1;
    }

    int gpio_fd = gpio_init();
    if (gpio_fd < 0) {
        closelog();
        return 1;
    }

    if (ensure_image_dir() < 0) {
        close(gpio_fd);
        closelog();
        return 1;
    }

    syslog(LOG_INFO, "Security camera system started");

    while (running) {
        int val = gpio_read(gpio_fd);
        if (val < 0) {
            syslog(LOG_ERR, "GPIO read error, retrying...");
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }

        if (val == 1) {
            syslog(LOG_INFO, "Motion detected on GPIO %d", GPIO_PIN);
            char timestamp[32];
            if (get_timestamp(timestamp, sizeof(timestamp)) == 0) {
                char filename[MAX_FILENAME_LENGTH];
                snprintf(filename, sizeof(filename), "%s/%s_%s.jpg", IMAGE_DIR, timestamp, "motion");
                syslog(LOG_INFO, "Capturing image: %s", filename);
                if (capture_image(filename) == 0) {
                    if (save_image(filename) == 0) {
                        syslog(LOG_INFO, "Image saved successfully");
                    } else {
                        syslog(LOG_ERR, "Failed to save image data");
                    }
                } else {
                    syslog(LOG_ERR, "Failed to capture image");
                }
            } else {
                syslog(LOG_ERR, "Failed to get timestamp");
            }
            usleep(DEBOUNCE_DELAY_MS * 1000);
            int confirmed = gpio_read(gpio_fd);
            if (confirmed < 0) {
                syslog(LOG_ERR, "GPIO read error after debounce");
            } else if (confirmed == 1) {
