/*
 * OV5647 grayscale capture for Raspberry Pi 3 Model B+
 * Uses libcamera C API (libcamera-apps) for mmap-based streaming.
 *
 * Build:  gcc -O2 -Wall -Wextra -o ov5647_capture ov5647_capture.c -lpthread -lrt
 * Run:    ./ov5647_capture /dev/video0
 *
 * Default output: image_0001.pgm  image_0002.pgm  ...  image_9999.pgm
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>

#define DEFAULT_DEVICE "/dev/video0"
#define MAX_FRAMES 10000
#define FRAME_SIZE  (OV5647_WIDTH * OV5647_HEIGHT * 1)  /* 1 byte/grayscale */

static volatile sig_atomic_t g_stop = 0;

static void sig_handler(int signo)
{
    (void)signo;
    g_stop = 1;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int xioctl(int fd, unsigned long request, void *arg)
{
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r < 0 && errno == EINTR);
    return r;
}

static int open_device(const char *device)
{
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", device, strerror(errno));
        return -1;
    }
    return fd;
}

static int init_camera(int fd)
{
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    unsigned int n_buffers = 4;

    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "VIDIOC_QUERYCAP: %s\n", strerror(errno));
        return -1;
    }
    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", device);
        return -1;
    }
    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O\n", device);
        return -1;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = OV5647_WIDTH;
    fmt.fmt.pix.height = OV5647_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_GRAY8;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "VIDIOC_S_FMT: %s\n", strerror(errno));
        return -1;
    }

    memset(&req, 0, sizeof(req));
    req.count = n_buffers;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "VIDIOC_REQBUFS: %s\n", strerror(errno));
        return -1;
    }

    for (unsigned int i = 0; i < req.count; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (xioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            fprintf(stderr, "VIDIOC_QUERYBUF[%u]: %s\n", i, strerror(errno));
            return -1;
        }

        void *buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        if (buffer == MAP_FAILED) {
            fprintf(stderr, "mmap[%u]: %s\n", i, strerror(errno));
            return -1;
        }

        if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            fprintf(stderr, "VIDIOC_QBUF[%u]: %s\n", i, strerror(errno));
            return -1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        fprintf(stderr, "VIDIOC_STREAMON: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int capture_frame(int fd, unsigned char *frame, size_t frame_size)
{
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = 2;
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);
    if (r < 0) {
        if (errno == EINTR) {
            return -1;
        }
        fprintf(stderr, "select: %s\n", strerror(errno));
        return -1;
    }
    if (r == 0) {
        fprintf(stderr, "select timeout\n");
        return -1;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        fprintf(stderr, "VIDIOC_DQBUF: %s\n", strerror(errno));
        return -1;
    }

    if (buf.index >= req.count) {
        fprintf(stderr, "DQBUF index %u out of range\n", buf.index);
        return -1;
    }

    memcpy(frame, buffer, frame_size);
    if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        fprintf(stderr, "VIDIOC_QBUF: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int save_frame(const unsigned char *frame, size_t frame_size, const char *filename)
{
    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", filename, strerror(errno));
        return -1;
    }

    if (fwrite(frame, 1, frame_size, fp) != frame_size) {
        fprintf(stderr, "fwrite: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose: %s\n", strerror(errno));
        return -1;
    }

    printf("Saved %s (%u bytes)\n", filename, frame_size);
    return 0;
}

int main(int argc, char *argv[])
{
    const char *device = (argc > 1) ? argv[1] : DEFAULT_DEVICE;

    if (install_signal_handlers() < 0) {
        return EXIT_FAILURE;
    }

    int fd = open_device(device);
    if (fd < 0) {
        return EXIT_FAILURE;
    }

    if (init_camera(fd) < 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    unsigned char *buffers = malloc(req.count * sizeof(unsigned char *));
    if (!buffers) {
        fprintf(stderr, "malloc: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    for (unsigned int i = 0; i < req.count; i++) {
        buffers[i] = (unsigned char *)buf.m.offset;
    }

    unsigned int frame_number = 0;
    int consecutive_errors = 0;

    while (!g_stop) {
        unsigned char *frame = NULL;
        int rc = capture_frame(fd, frame, FRAME_SIZE);

        if (rc == 0) {
            if (save_frame(frame, FRAME_SIZE, "image_000" + frame_number) < 0) {
                fprintf(stderr, "Failed to save frame %u\n", frame_number);
            } else {
                frame_number++;
                if (frame_number > MAX_FRAMES) {
                    break;
                }
            }
            consecutive_errors = 0;
        } else {
            consecutive_errors++;
            fprintf(stderr, "Frame capture failed (attempt %d)\n", consecutive_errors);
            if (consecutive_errors >= 10) {
                fprintf(stderr, "Too many consecutive errors, aborting\n");
                break;
            }
        }

        if (g_stop) {
            break;
        }

        usleep(10000);
    }

    for (unsigned int i = 0; i < req.count; i++) {
        if (buffers[i]) {
            if (munmap(buffers[i], buf.m.offset) < 0) {
                fprintf(stderr, "munmap[%u]: %s\n", i, strerror(errno));
            }
        }
    }
    free(buffers);

    if (xioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        fprintf(stderr, "VIDIOC_STREAMOFF: %s\n", strerror(errno));
    }

    if (close(fd) < 0) {
        fprintf(stderr, "close: %s\n", strerror(errno));
    }

    printf("Program finished.\n");
    return EXIT_SUCCESS;
}

