static volatile sig_atomic_t g_stop = 0;

static void sig_handler(int signo) {
    (void)signo;
    g_stop = 1;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int capture_frame(int fd, unsigned char **buffer, size_t *buffer_size) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("VIDIOC_DQBUF");
        return -1;
    }

    if (buf.bytesused == 0) {
        fprintf(stderr, "Warning: captured frame has zero bytes used\n");
        return -1;
    }

    *buffer = (unsigned char *)buf.m.offset;
    *buffer_size = buf.bytesused;
    return 0;
}

static int write_jpeg(const unsigned char *data, size_t size) {
    FILE *fp = fopen(IMAGE_FILE, "wb");
    if (!fp) {
        perror("fopen image.jpg");
        return -1;
    }
    if (fwrite(data, 1, size, fp) != size) {
        perror("fwrite");
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }
    return 0;
}

int main(void) {
    int fd = -1;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    unsigned char *buffers[NUM_BUFFERS];
    size_t buffer_sizes[NUM_BUFFERS];
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction SIGINT");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction SIGTERM");
        return EXIT_FAILURE;
    }

    fd = open(DEVICE_NAME, O_RDWR, 0);
    if (fd < 0) {
        perror("open " DEVICE_NAME);
        return EXIT_FAILURE;
    }

    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("VIDIOC_QUERYCAP");
        goto cleanup;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", DEVICE_NAME);
        goto cleanup;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O\n", DEVICE_NAME);
        goto cleanup;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("VIDIOC_S_FMT");
        goto cleanup;
    }

    if (fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_MJPEG) {
        fprintf(stderr, "Device does not support MJPEG format\n");
        goto cleanup;
    }

    memset(&req, 0, sizeof(req));
    req.count = NUM_BUFFERS;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("VIDIOC_REQBUFS");
        goto cleanup;
    }

    if (req.count < 2) {
        fprintf(stderr, "Insufficient buffer memory on %s\n", DEVICE_NAME);
        goto cleanup;
    }

    for (int i = 0; i < req.count; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (xioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("VIDIOC_QUERYBUF");
            goto cleanup;
        }

        buffers[i] = (unsigned char *)mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        if (buffers[i] == MAP_FAILED) {
            perror("mmap");
            buffers[i] = NULL;
            goto cleanup;
        }
        buffer_sizes[i] = buf.length;
    }

    for (int i = 0; i < req.count; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("VIDIOC_QBUF");
            goto cleanup;
        }
    }

    if (xioctl(fd, VIDIOC_STREAMON, &fmt) < 0) {
        perror("VIDIOC_STREAMON");
        goto cleanup;
    }

    unsigned char *frame = NULL;
    size_t frame_size = 0;

    while (!g_stop) {
        if (capture_frame(fd, &frame, &frame_size) < 0) {
            break;
        }

        if (write_jpeg(frame, frame_size) < 0) {
            break;
        }

        if (g_stop) {
            break;
        }
    }

    if (xioctl(fd, VIDIOC_STREAMOFF, &fmt) < 0) {
        perror("VIDIOC_STREAMOFF");
    }

    for (int i = 0; i < req.count; i++) {
        if (buffers[i]) {
            if (munmap(buffers[i], buffer_sizes[i]) < 0) {
                perror("munmap");
            }
            buffers[i] = NULL;
        }
    }

    if (close(fd) < 0) {
        perror("close");
        ret = EXIT_FAILURE;
    } else {
        ret = EXIT_SUCCESS;
    }

    return ret;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return ret;
}

