/*
 * Camera pan-tilt mount control using Raspberry Pi GPIO software PWM.
 *
 * Wiring (BCM numbering):
 *   GPIO4  -> Pan servo signal
 *   GPIO5  -> Tilt servo signal
 *   GPIO6  -> Tilt-up button (active-low, internal pull-up)
 *   GPIO7  -> Tilt-down button (active-low, internal pull-up)
 *   GPIO8  -> Pan-left button (active-low, internal pull-up)
 *   GPIO9  -> Pan-right button (active-low, internal pull-up)
 *
 * Servo PWM: 50 Hz, 20 ms period, 1 ms–2 ms pulse width -> 50–100 duty (0–1000).
 * Servo mid-position: 75 (1,750 us).
 *
 * Build:  gcc -O2 -Wall -Wextra -o pan_tilt pan_tilt.c
 */

#define _GNU_SOURCE
#include <errno.h>
#include <fcntl.h>
#include <signal.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

#include <linux/pwm.h>
#include <sys/ioctl.h>

#define BCM_PIN_TO_GPIO  456789012345678  /* BCM 4 -> 5, BCM 5 -> 6, BCM 6 -> 7, BCM 8 -> 9, BCM 9 -> 10 */
#define PWM_PERIOD_NS    20000000L       /* 20 ms = 50 Hz */
#define PWM_DUTY_MAX     1000
#define SERVO_MIN_US    1000
#define SERVO_MAX_US    2000
#define SERVO_MID_US    1750
#define SERVO_MIN       25
#define SERVO_MAX       125
#define SERVO_MID       75
#define STEP            5
#define POLL_MS         50
#define PWM_BUF_SIZE    64

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int pwm_write(int fd, const struct pwm_output *out)
{
    if (ioctl(fd, PWM_SET_MODE, out) < 0) {
        perror("pwm_set_mode");
        return -1;
    }
    if (ioctl(fd, PWM_SET_RANGE, &out->range) < 0) {
        perror("pwm_set_range");
        return -1;
    }
    if (ioctl(fd, PWM_SET_DUTY, &out->duty) < 0) {
        perror("pwm_set_duty");
        return -1;
    }
    return 0;
}

static int pwm_init(int fd, unsigned int gpio, unsigned int freq, unsigned int duty)
{
    struct pwm_output out;
    memset(&out, 0, sizeof(out));
    out.gpio = gpio;
    out.freq = freq;
    out.duty = duty;

    if (ioctl(fd, PWM_MOTE, &out) < 0) {
        perror("pwm_mote");
        return -1;
    }
    return 0;
}

static int pwm_set(int fd, unsigned int gpio, unsigned int duty)
{
    struct pwm_output out;
    memset(&out, 0, sizeof(out));
    out.gpio = gpio;
    out.duty = duty;

    if (ioctl(fd, PWM_SET_DUTY, &out) < 0) {
        perror("pwm_set_duty");
        return -1;
    }
    return 0;
}

static int pwm_read(int fd, unsigned int gpio)
{
    struct pwm_output out;
    memset(&out, 0, sizeof(out));
    out.gpio = gpio;

    if (ioctl(fd, PWM_GET_DUTY, &out) < 0) {
        perror("pwm_get_duty");
        return -1;
    }
    return out.duty;
}

static int pwm_set_period(int fd, unsigned int period_ns)
{
    struct pwm_period period;
    memset(&period, 0, sizeof(period));
    period.period_ns = period_ns;

    if (ioctl(fd, PWM_SET_PERIOD, &period) < 0) {
        perror("pwm_set_period");
        return -1;
    }
    return 0;
}

static int pwm_enable(int fd, unsigned int gpio, bool enable)
{
    struct pwm_enable enable_val;
    memset(&enable_val, 0, sizeof(enable_val));
    enable_val.gpio = gpio;
    enable_val.enable = enable;

    if (ioctl(fd, PWM_SET_ENABLE, &enable_val) < 0) {
        perror("pwm_set_enable");
        return -1;
    }
    return 0;
}

static int pwm_disable(int fd, unsigned int gpio)
{
    return pwm_enable(fd, gpio, false);
}

static int pwm_set_mode(int fd, unsigned int gpio, unsigned int mode)
{
    struct pwm_mode mode_val;
    memset(&mode_val, 0, sizeof(mode_val));
    mode_val.gpio = gpio;
    mode_val.mode = mode;

    if (ioctl(fd, PWM_SET_MODE, &mode_val) < 0) {
        perror("pwm_set_mode");
        return -1;
    }
    return 0;
}

static int pwm_set_range(int fd, unsigned int gpio, unsigned int range)
{
    struct pwm_range range_val;
    memset(&range_val, 0, sizeof(range_val));
    range_val.gpio = gpio;
    range_val.range = range;

    if (ioctl(fd, PWM_SET_RANGE, &range_val) < 0) {
        perror("pwm_set_range");
        return -1;
    }
    return 0;
}

static int pwm_init_servo(int fd, unsigned int gpio, unsigned int freq, unsigned int duty)
{
    if (pwm_set_period(fd, PWM_PERIOD_NS) < 0) return -1;
    if (pwm_set_mode(fd, gpio, PWM_MODE_OUTPUT) < 0) return -1;
    if (pwm_set_range(fd, gpio, PWM_DUTY_MAX) < 0) return -1;
    if (pwm_write(fd, (struct pwm_output){.gpio = gpio, .freq = freq, .duty = duty}) < 0) return -1;
    return 0;
}

static int pwm_set_servo(int fd, unsigned int gpio, unsigned int duty)
{
    if (pwm_set_range(fd, gpio, PWM_DUTY_MAX) < 0) return -1;
    return pwm_write(fd, (struct pwm_output){.gpio = gpio, .duty = duty});
}

static int pwm_disable_servo(int fd, unsigned int gpio)
{
    return pwm_enable(fd, gpio, false);
}

static int pwm_read_servo(int fd, unsigned int gpio)
{
    struct pwm_output out;
    memset(&out, 0, sizeof(out));
    out.gpio = gpio;

    if (ioctl(fd, PWM_GET_DUTY, &out) < 0) {
        perror("pwm_get_duty");
        return -1;
    }
    return out.duty;
}

static int pwm_set_output(int fd, unsigned int gpio, unsigned int duty)
{
    struct pwm_output out;
    memset(&out, 0, sizeof(out));
    out.gpio = gpio;
    out.duty = duty;

    if (ioctl(fd, PWM_SET_DUTY, &out) < 0) {
        perror("pwm_set_duty");
        return -1;
    }
    return 0;
}

static int pwm_init_input(int fd, unsigned int gpio)
{
    struct pwm_input input;
    memset(&input, 0, sizeof(input));
    input.gpio = gpio;

    if (ioctl(fd, PWM_SET_INPUT, &input) < 0) {
        perror("pwm_set_input");
        return -1;
    }
    return 0;
}

static int pwm_read_input(int fd, unsigned int gpio)
{
    struct pwm_input input;
    memset(&input, 0, sizeof(input));
    input.gpio = gpio;

    if (ioctl(fd, PWM_GET_INPUT, &input) < 0) {
        perror("pwm_get_input");
        return -1;
    }
    return input.value;
}

static int pwm_enable_input(int fd, unsigned int gpio, bool enable)
{
    struct pwm_enable enable_val;
    memset(&enable_val, 0, sizeof(enable_val));
    enable_val.gpio = gpio;
    enable_val.enable = enable;

    if (ioctl(fd, PWM_SET_ENABLE, &enable_val) < 0) {
        perror("pwm_set_enable");
        return -1;
    }
    return 0;
}

static int pwm_disable_input(int fd, unsigned int gpio)
{
    return pwm_enable_input(fd, gpio, false);
}

static int pwm_set_input_flags(int fd, unsigned int gpio, unsigned int flags)
{
    struct pwm_input_flags flags_val;
    memset(&flags_val, 0, sizeof(flags_val));
    flags_val.gpio = gpio;
    flags_val.flags = flags;

    if (ioctl(fd, PWM_SET_INPUT_FLAGS, &flags_val) < 0) {
        perror("pwm_set_input_flags");
        return -1;
    }
    return 0;
}

static int pwm_init_pwm(int fd)
{
    if (pwm_set_period(fd, PWM_PERIOD_NS) < 0) return -1;
    if (pwm_set_mode(fd, BCM_PIN_TO_GPIO, PWM_MODE_OUTPUT) < 0) return -1;
    if (pwm_set_range(fd, BCM_PIN_TO_GPIO, PWM_DUTY_MAX) < 0) return -1;
    if (pwm_write(fd, (struct pwm_output){.gpio = BCM_PIN_TO_GPIO, .duty = 0}) < 0) return -1;
    return 0;
}

static void cleanup_pwm(int fd)
{
    pwm_disable_servo(fd, BCM_PIN_TO_GPIO);
    pwm_disable_input(fd, BCM_PIN_TO_GPIO);
    pwm_disable(fd, BCM_PIN_TO_GPIO);
    close(fd);
}

int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    fd = open("/dev/pwm", O_RDWR);
    if (fd < 0) {
        perror("open /dev/pwm");
        return EXIT_FAILURE;
    }

    if (pwm_init_pwm(fd) < 0) {
        fprintf(stderr, "Failed to initialize PWM\n");
        goto cleanup;
    }

    if (pwm_init_servo(fd, BCM_PIN_TO_GPIO, 50, SERVO_MID) < 0) {
        fprintf(stderr, "Failed to initialize servo\n");
        goto cleanup;
    }

    if (pwm_init_input(fd, BCM_PIN_TO_GPIO) < 0) {
        fprintf(stderr, "Failed to initialize input\n");
        goto cleanup;
    }

    if (pwm_set_input_flags(fd, BCM_PIN_TO_GPIO, PWM_INPUT_FLAG_BIAS_PULL_UP) < 0) {
        fprintf(stderr, "Failed to set input flags\n");
        goto cleanup;
    }

    int pan_pos = SERVO_MID;
    int tilt_pos = SERVO_MID;
    int pan_dir  = 0;
    int tilt_dir = 0;

    while (g_running) {
        int pan_left  = pwm_read_input(fd, BCM_PIN_TO_GPIO);
        int pan_right = pwm_read_input(fd, BCM_PIN_TO_GPIO + 1);
        int tilt_up   = pwm_read_input(fd, BCM_PIN_TO_GPIO + 2);
        int tilt_down = pwm_read_input(fd, BCM_PIN_TO_GPIO + 3);

        if (pan_left < 0 || pan_right < 0 || tilt_up < 0 || tilt_down < 0) {
            fprintf(stderr, "Error reading button states\n");
            break;
        }

        if (pan_left && pan_pos < SERVO_MAX) {
            pan_pos += STEP;
            if (pan_pos > SERVO_MAX) pan_pos = SERVO_MAX;
            pan_dir = 1;
        } else if (pan_right && pan_pos > SERVO_MIN) {
            pan_pos -= STEP;
            if (pan_pos < SERVO_MIN) pan_pos = SERVO_MIN;
            pan_dir = -1;
        }

        if (tilt_up && tilt_pos < SERVO_MAX) {
            tilt_pos += STEP;
            if (tilt_pos > SERVO_MAX) tilt_pos = SERVO_MAX;
            tilt_dir = 1;
        } else if (tilt_down && tilt_pos > SERVO_MIN) {
            tilt_pos -= STEP;
            if (tilt_pos < SERVO_MIN) tilt_pos = SERVO_MIN;
            tilt_dir = -1;
        }

        if (pan_dir != 0) {
            if (pwm_set_servo(fd, BCM_PIN_TO_GPIO, SERVO_MIN + pan_pos) < 0) break;
            pan_dir = 0;
        }
        if (tilt_dir != 0) {
            if (pwm_set_servo(fd, BCM_PIN_TO_GPIO + 1, SERVO_MIN + tilt_pos) < 0) break;
            tilt_dir = 0;
        }

        usleep(POLL_MS * 1000);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        pwm_disable_servo(fd, BCM_PIN_TO_GPIO);
        pwm_disable_input(fd, BCM_PIN_TO_GPIO);
        pwm_disable(fd, BCM_PIN_TO_GPIO);
        close(fd);
    }
    return rc;
}

