#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <sys/stat.h>
#include <time.h>
#include <signal.h>
#include <stdint.h>
#include <stdbool.h>

#define VIDEO_DEVICE "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define JPEG_QUALITY 75
#define BLUR_SIZE 3
#define SELECT_TIMEOUT_SEC 2

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int install_signal_handler(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return -1;
    }
    return 0;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int capture_frame(int fd, uint8_t **buffer, size_t *buffer_size) {
    *buffer = NULL;
    *buffer_size = 0;

    struct {
        int type;
        size_t length;
        uint8_t *pixels;
    } buffers[2];

    buffers[0].type = XVID_FRAME_CAPTURE;
    buffers[0].length = IMAGE_WIDTH * IMAGE_HEIGHT * 2;
    buffers[1].type = XVID_FRAME_CAPTURE;
    buffers[1].length = IMAGE_WIDTH * IMAGE_HEIGHT * 2;

    if (xioctl(fd, VIDIOC_REQBUFS, buffers) == -1) {
        perror("VIDIOC_REQBUFS");
        return -1;
    }

    if (buffers[0].length == 0) {
        fprintf(stderr, "No buffers allocated\n");
        return -1;
    }

    if (xioctl(fd, VIDIOC_QUERYBUF, &buffers[0]) == -1) {
        perror("VIDIOC_QUERYBUF");
        return -1;
    }

    if (xioctl(fd, VIDIOC_QBUF, &buffers[0]) == -1) {
        perror("VIDIOC_QBUF");
        return -1;
    }

    fd_set fds;
    struct timeval tv;
    FD_ZERO(&fds);
    FD_SET(fd, &fds);
    tv.tv_sec = SELECT_TIMEOUT_SEC;
    tv.tv_usec = 0;

    int r = select(fd + 1, &fds, NULL, NULL, &tv);
    if (r == -1) {
        if (errno == EINTR) return 0;
        perror("select");
        return -1;
    }
    if (r == 0) {
        fprintf(stderr, "select timeout\n");
        return -1;
    }

    if (xioctl(fd, VIDIOC_DQBUF, &buffers[0]) == -1) {
        perror("VIDIOC_DQBUF");
        return -1;
    }

    *buffer = malloc(buffers[0].length);
    if (*buffer == NULL) {
        perror("malloc");
        return -1;
    }
    memcpy(*buffer, buffers[0].pixels, buffers[0].length);

    if (xioctl(fd, VIDIOC_STREAMOFF, &buffers[0].type) == -1) {
        perror("VIDIOC_STREAMOFF");
        free(*buffer);
        return -1;
    }

    *buffer_size = buffers[0].length;
    return 0;
}

static void blur_image(uint8_t *rgb, int width, int height, int blur_size) {
    int half = blur_size / 2;
    for (int y = 0; y < height; y++) {
        for (int x = 0; x < width; x++) {
            int r = 0, g = 0, b = 0;
            for (int dy = -half; dy <= half; dy++) {
                for (int dx = -half; dx <= half; dx++) {
                    int ny = y + dy;
                    int nx = x + dx;
                    if (ny >= 0 && ny < height && nx >= 0 && nx < width) {
                        int idx = (ny * width + nx) * 3;
                        r += rgb[idx];
                        g += rgb[idx + 1];
                        b += rgb[idx + 2];
                    }
                }
            }
            int count = 0;
            for (int dy = -half; dy <= half; dy++) {
                for (int dx = -half; dx <= half; dx++) {
                    int ny = y + dy;
                    int nx = x + dx;
                    if (ny >= 0 && ny < height && nx >= 0 && nx < width) {
                        count++;
                    }
                }
            }
            int avg_r = r / count;
            int avg_g = g / count;
            int avg_b = b / count;
            int idx = (y * width + x) * 3;
            rgb[idx] = avg_r;
            rgb[idx + 1] = avg_g;
            rgb[idx + 2] = avg_b;
        }
    }
}

static int encode_jpeg(uint8_t *rgb, int width, int height, int quality, const char *filename) {
    int row_padded = (width * 3 + 3) & (~3);
    int row_stride = width * 3;
    int image_size = row_padded * height;
    int data_size = image_size + 8;

    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) {
        perror("fopen");
        return -1;
    }

    unsigned char *jpeg = malloc(data_size);
    if (jpeg == NULL) {
        perror("malloc");
        fclose(fp);
        return -1;
    }

    memset(jpeg, 0, data_size);

    unsigned char *row = malloc(row_padded);
    if (row == NULL) {
        perror("malloc");
        free(jpeg);
        fclose(fp);
        return -1;
    }

    memset(row, 0, row_padded);

    unsigned char *rgb_ptr = rgb;
    unsigned char *jpeg_ptr = jpeg;

    for (int y = 0; y < height; y++) {
        memcpy(row, rgb_ptr, width * 3);
        memcpy(row + width * 3, row, row_padded - width * 3);
        memcpy(jpeg_ptr, row, row_padded);
        jpeg_ptr += row_padded;
        rgb_ptr += width * 3;
    }

    int rc = fwrite(jpeg, 1, data_size, fp);
    free(row);
    free(jpeg);
    fclose(fp);
    return (rc == data_size) ? 0 : -1;
}

static void cleanup(int fd, uint8_t *buffer, size_t buffer_size) {
    if (buffer != NULL) {
        if (xioctl(fd, VIDIOC_STREAMON, &buffer[0].type) == -1) {
            perror("VIDIOC_STREAMON");
        }
        free(buffer);
    }
    if (fd >= 0) {
        close(fd);
    }
}

int main(void) {
    int fd = -1;
    uint8_t *buffer = NULL;
    size_t buffer_size = 0;

    if (install_signal_handler() == -1) {
        return EXIT_FAILURE;
    }

    fd = open(VIDEO_DEVICE, O_RDWR);
    if (fd == -1) {
        perror("open");
        return EXIT_FAILURE;
    }

    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));
    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) == -1) {
        perror("VIDIOC_QUERYCAP");
        cleanup(fd, buffer, buffer_size);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        cleanup(fd, buffer, buffer_size);
        return EXIT_FAILURE;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        cleanup(fd, buffer, buffer_size);
        return EXIT_FAILURE;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(fd, VIDIOC_S_FMT, &fmt) == -1) {
        perror("VIDIOC_S_FMT");
        cleanup(fd, buffer, buffer_size);
        return EXIT_FAILURE;
    }

    if (fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_YUYV) {
        fprintf(stderr, "Unexpected pixel format: %d\n", fmt.fmt.pix.pixelformat);
        cleanup(fd, buffer, buffer_size);
        return EXIT_FAILURE;
    }

    struct v4l2_streamparm sp;
    memset(&sp, 0, sizeof(sp));
    sp.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    sp.parm.capture_timebase.numerator = 1;
    sp.parm.capture_timebase.denominator = SELECT_TIMEOUT_SEC * 1000000;

    if (xioctl(fd, VIDIOC_S_PARM, &sp) == -1) {
        perror("VIDIOC_S_PARM");
        cleanup(fd, buffer, buffer_size);
        return EXIT_FAILURE;
    }

    if (xioctl(fd, VIDIOC_STREAMON, &fmt) == -1) {
        perror("VIDIOC_STREAMON");
        cleanup(fd, buffer, buffer_size);
        return EXIT_FAILURE;
    }

    time_t rawtime;
    struct tm *timeinfo;
    char filename[64];
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y%m%d_%H%M%S", timeinfo);
    snprintf(filename, sizeof(filename), "capture_%s.jpg", timestamp);

    uint8_t *rgb = malloc(IMAGE_WIDTH * IMAGE_HEIGHT * 3);
    if (rgb == NULL) {
        perror("malloc");
        cleanup(fd, buffer, buffer_size);
        return EXIT_FAILURE;
    }

    printf("Capturing frame...\n");
    if (capture_frame(fd, &buffer, &buffer_size) == 0) {
        printf("Frame captured.\n");
    } else {
