#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"

static void print_frame_interval(const struct v4l2_frameintervals *intervals)
{
    printf("  Frame intervals: %zu\n", intervals->nintervals);
    for (unsigned int i = 0; i < intervals->nintervals; i++) {
        printf("    %u -> %u\n", intervals->intervals[i].start, intervals->intervals[i].end);
    }
}

static void print_resolution(const struct v4l2_frmsizeenum *size)
{
    printf("    Resolution: %ux%u\n", size->width, size->height);
    printf("    Frame rate: %u/%u\n", size->framerate.numerator, size->framerate.denominator);
    if (size->flags & V4L2_FRMSIZE_FLAG_AUTOFOCUS) {
        printf("    Autofocus: yes\n");
    } else {
        printf("    Autofocus: no\n");
    }
}

int main(void)
{
    int fd = -1;
    struct v4l2_capability cap;
    struct v4l2_frmsizeenum size;
    struct v4l2_fmtdesc fmt;
    struct v4l2_control ctrl;
    unsigned int focus_auto_fd = -1;
    int ret = EXIT_FAILURE;

    memset(&cap, 0, sizeof(cap));
    memset(&fmt, 0, sizeof(fmt));
    memset(&ctrl, 0, sizeof(ctrl));

    fd = open(DEVICE_NAME, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", DEVICE_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        goto cleanup;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s does not support video capture\n", DEVICE_NAME);
        goto cleanup;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O\n", DEVICE_NAME);
        goto cleanup;
    }

    if (ioctl(fd, VIDIOC_QUERYFRAMESIZES, &size) < 0) {
        fprintf(stderr, "Error querying frame sizes: %s\n", strerror(errno));
        goto cleanup;
    }

    if (size.nframesize < 1) {
        fprintf(stderr, "%s does not support any frame sizes\n", DEVICE_NAME);
        goto cleanup;
    }

    printf("Supported frame sizes:\n");
    for (unsigned int i = 0; i < size.nframesize; i++) {
        print_resolution(&size.internframesize[i]);
    }

    if (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &fmt) < 0) {
        fprintf(stderr, "Error enumerating frame intervals: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("  Frame interval descriptors:\n");
    printf("    %u -> %u\n", fmt.nintervals, fmt.intervals[0].start);
    print_frame_interval(&fmt);

    if (ioctl(fd, VIDIOC_QUERYCTRL, &ctrl) < 0) {
        fprintf(stderr, "Error querying focus control: %s\n", strerror(errno));
        goto cleanup;
    }

    focus_auto_fd = ctrl.id;
    printf("  Focus control ID: %u\n", focus_auto_fd);

    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "Error re-querying capabilities: %s\n", strerror(errno));
        goto cleanup;
    }

    if (!(cap.capabilities & V4L2_CAP_FOCUS_AUTO)) {
        printf("  Autofocus: no\n");
    } else {
        printf("  Autofocus: yes\n");
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return ret;
}

