#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define UP_BUTTON_PIN 6
#define DOWN_BUTTON_PIN 7
#define LEFT_BUTTON_PIN 8
#define RIGHT_BUTTON_PIN 9

#define MIN_PULSE_WIDTH 1000
#define MAX_PULSE_WIDTH 2000
#define CENTER_PULSE_WIDTH 1500
#define STEP_SIZE 10
#define LOOP_DELAY_US 50000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_servo_pulse_width(int pin, int pulse_width) {
    if (pulse_width < MIN_PULSE_WIDTH) {
        pulse_width = MIN_PULSE_WIDTH;
    } else if (pulse_width > MAX_PULSE_WIDTH) {
        pulse_width = MAX_PULSE_WIDTH;
    }
    if (gpioServo(pin, pulse_width) < 0) {
        fprintf(stderr, "Error: gpioServo failed on pin %d\n", pin);
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    gpioServo(PAN_SERVO_PIN, 0);
    gpioServo(TILT_SERVO_PIN, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for pan servo pin %d\n", PAN_SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for tilt servo pin %d\n", TILT_SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(UP_BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for UP button pin %d\n", UP_BUTTON_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(DOWN_BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for DOWN button pin %d\n", DOWN_BUTTON_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(LEFT_BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for LEFT button pin %d\n", LEFT_BUTTON_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(RIGHT_BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for RIGHT button pin %d\n", RIGHT_BUTTON_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(UP_BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for UP button pin %d\n", UP_BUTTON_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(DOWN_BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for DOWN button pin %d\n", DOWN_BUTTON_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(LEFT_BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for LEFT button pin %d\n", LEFT_BUTTON_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(RIGHT_BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown failed for RIGHT button pin %d\n", RIGHT_BUTTON_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(PAN_SERVO_PIN, 50) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed for pan servo pin %d\n", PAN_SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(TILT_SERVO_PIN, 50) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed for tilt servo pin %d\n", TILT_SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(PAN_SERVO_PIN, 2000000) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed for pan servo pin %d\n", PAN_SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(TILT_SERVO_PIN, 2000000) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed for tilt servo pin %d\n", TILT_SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioServo(PAN_SERVO_PIN, CENTER_PULSE_WIDTH) < 0) {
        fprintf(stderr, "Error: failed to set initial pan servo position\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioServo(TILT_SERVO_PIN, CENTER_PULSE_WIDTH) < 0) {
        fprintf(stderr, "Error: failed to set initial tilt servo position\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
