/*
 * PIR-triggered camera capture for Raspberry Pi Zero W.
 *
 * Hardware:
 *   HC-SR501 PIR sensor  -> Raspberry Pi Zero W
 *   VCC                  -> 5 V (pin 2 or 4)
 *   GND                 -> GND  (pin 6)
 *   OUT                  -> GPIO17 (BCM 17, physical pin 11)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o motion_capture motion_capture.c
 *
 * Run:
 *   ./motion_capture
 */

#define _POSIX_C_SOURCE 200809L

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>

#define GPIO_CHIP_NAME  "gpiochip0"
#define GPIO_PIN        17
#define DEBOUNCE_MS     50
#define LOG_FILE        "/home/pi/motion_capture.log"
#define IMAGE_DIR       "/home/pi/images"
#define CAPTURE_CMD     "camera_capture"
#define CAPTURE_OPTS    " -o %s -w 640 -h 480 -q 85 -t 2000 -n"
#define CAPTURE_FMT     "YYYYMMDD_HHMMSS_mmm.jpg"

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_message(const char *msg)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(log)");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
