#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define WIDTH 200
#define HEIGHT 150
#define YUYV_SIZE (WIDTH * HEIGHT * 2)
#define CAPTURE_TIMEOUT_SEC 2

static volatile sig_atomic_t g_stop = 0;

static void sig_handler(int signo) {
    (void)signo;
    g_stop = 1;
}

static int xioctl(int fd, unsigned long request, void *arg) {
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int capture_frame(int fd, unsigned char *buffer, size_t *out_size) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("VIDIOC_DQBUF");
        return -1;
    }

    if (g_stop) {
        fprintf(stderr, "Interrupted by signal during capture.\n");
        xioctl(fd, VIDIOC_QBUF, &buf);
        return -1;
    }

    size_t got = 0;
    if (buf.bytesused > YUYV_SIZE) {
        fprintf(stderr, "Warning: buffer has %zu bytes, expected %zu\n", buf.bytesused, YUYV_SIZE);
        buf.bytesused = YUYV_SIZE;
    }
    memcpy(buffer, buf.buffer, buf.bytesused);
    *out_size = buf.bytesused;
    return 0;
}

static int write_cropped_yuv(const unsigned char *yuv, size_t size, const char *filename) {
    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        perror("fopen");
        return -1;
    }
    if (fwrite(yuv, 1, size, fp) != size) {
        perror("fwrite");
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }
    return 0;
}

int main(void) {
    int fd = -1;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    unsigned char *buffer = NULL;
    size_t buffer_size = 0;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction SIGINT");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction SIGTERM");
        return EXIT_FAILURE;
    }

    fd = open(DEVICE_NAME, O_RDWR);
    if (fd < 0) {
        perror("open");
        return EXIT_FAILURE;
    }

    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("VIDIOC_QUERYCAP");
        goto cleanup;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "%s is not a video capture device\n", DEVICE_NAME);
        goto cleanup;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "%s does not support streaming I/O\n", DEVICE_NAME);
        goto cleanup;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("VIDIOC_S_FMT");
        goto cleanup;
    }

    if (fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_YUYV) {
        fprintf(stderr, "Device does not support YUYV format\n");
        goto cleanup;
    }

    memset(&req, 0, sizeof(req));
    req.count = 1;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("VIDIOC_REQBUFS");
        goto cleanup;
    }

    if (req.count < 1) {
        fprintf(stderr, "Insufficient buffer memory\n");
        goto cleanup;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (xioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        perror("VIDIOC_QUERYBUF");
        goto cleanup;
    }

    buffer_size = buf.length;
    buffer = mmap(NULL, buffer_size, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer == MAP_FAILED) {
        perror("mmap");
        buffer = NULL;
        goto cleanup;
    }

    if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("VIDIOC_QBUF");
        goto cleanup;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("VIDIOC_STREAMON");
        goto cleanup;
    }

    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);
    tv.tv_sec = CAPTURE_TIMEOUT_SEC;
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);
    if (r < 0) {
        if (errno == EINTR) {
            if (g_stop) {
                fprintf(stderr, "Interrupted by signal during select.\n");
                goto cleanup;
            }
            goto capture_frame;
        }
        perror("select");
        goto cleanup;
    }
    if (r == 0) {
        fprintf(stderr, "Select timeout: no frame within %d seconds.\n", CAPTURE_TIMEOUT_SEC);
        goto cleanup;
    }

capture_frame:
    size_t got = 0;
    if (capture_frame(fd, buffer, &got) < 0) {
        goto cleanup;
    }

    if (got != YUYV_SIZE) {
        fprintf(stderr, "Warning: captured %zu bytes, expected %zu\n", got, YUYV_SIZE);
    }

    if (write_cropped_yuv(buffer, got, "cropped.yuv") < 0) {
        goto cleanup;
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        if (xioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
            perror("VIDIOC_STREAMOFF");
        }
    }
    if (buffer) {
        munmap(buffer, buffer_size);
    }
    if (fd >= 0) {
        close(fd);
    }
    return ret;
}

