        fprintf(stderr, "Select timeout: no frame within %d seconds.\n", CAPTURE_TIMEOUT_SEC);
        goto cleanup;
    }

capture_frame:
    size_t got = 0;
    if (capture_frame(fd, buffer, &got) < 0) {
        goto cleanup;
    }

    if (got != YUYV_SIZE) {
        fprintf(stderr, "Warning: captured %zu bytes, expected %zu\n", got, YUYV_SIZE);
    }

    if (write_cropped_yuv(buffer, got, "cropped.yuv") < 0) {
        goto cleanup;
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        if (xioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
            perror("VIDIOC_STREAMOFF");
        }
    }
    if (buffer) {
        munmap(buffer, buffer_size);
    }
    if (fd >= 0) {
        close(fd);
    }
    return ret;
}

