/*
 * Raspberry Pi 4 Model B — dual SG90 servo controller with arrow-key input.
 *
 * Wiring:
 *   Pan  servo signal -> GPIO17 (BCM)
 *   Tilt servo signal -> GPIO18 (BCM)
 *   VCC -> 5 V (pin 2 or 4)
 *   GND -> GND (pin 6 or 9)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o servo_arrow servo_arrow.c -lpigpio -lrt
 *   (pigpio must be installed via sudo pigpio run or similar.)
 *
 * Run:
 *   sudo ./servo_arrow
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <unistd.h>
#include <pigpio.h>

#define PAN_GPIO        17
#define TILT_GPIO       18
#define PWM_FREQ_HZ     50          /* 50 Hz — typical for 10 ms period */
#define PWM_RANGE       255         /* 8-bit resolution */
#define SERVO_MIN_US    500        /* 0 degrees   */
#define SERVO_MAX_US    2500       /* 180 degrees */
#define STEP_DEG        5
#define STEP_DELAY_US   100000     /* 100 ms between commands */
#define NEUTRAL_DEG     90

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int set_servo_angle(int gpio, int angle)
{
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;

    int pulse_us = SERVO_MIN_US +
                   (int)((long)angle * (SERVO_MAX_US - SERVO_MIN_US) / 180);

    if (gpioPWM(gpio, pulse_us) < 0) {
        fprintf(stderr, "Error: gpioPWM(%d, %d) failed\n", gpio, pulse_us);
        return -1;
    }
    return 0;
}

int main(void)
{
    /* --- Install SIGINT handler for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (run as root?)\n");
        return EXIT_FAILURE;
    }

    /* --- Configure PWM on both GPIOs --- */
    if (gpioSetPWMfrequency(PAN_GPIO, PWM_FREQ_HZ) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency(%d) failed\n", PAN_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(TILT_GPIO, PWM_FREQ_HZ) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency(%d) failed\n", TILT_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(PAN_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange(%d) failed\n", PAN_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(TILT_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange(%d) failed\n", TILT_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Start both servos at neutral position --- */
    if (set_servo_angle(PAN_GPIO, NEUTRAL_DEG) != 0 ||
        set_servo_angle(TILT_GPIO, NEUTRAL_DEG) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Pan/Tilt Servo Control (arrow keys + q)\n");
    printf("  ^  -> Pan + 5 deg\n");
    printf("  v  -> Pan - 5 deg\n");
    printf("  <  -> Tilt - 5 deg\n");
    printf("  >  -> Tilt + 5 deg\n");
    printf("  q  -> Quit\n");
    printf("Pan: %3d deg  Tilt: %3d deg\n", NEUTRAL_DEG, NEUTRAL_DEG);
    fflush(stdout);

    int pan_angle = NEUTRAL_DEG;
    int tilt_angle = NEUTRAL_DEG;

    while (g_running) {
        int c = getchar();

        if (c == 'q') {
            break;
        }
        if (c == '\n' || c == '\r') {
            /* Line feed / carriage return — discard */
            continue;
        }

        switch (c) {
        case '^':
            pan_angle += STEP_DEG;
            if (pan_angle > 180) pan_angle = 180;
            break;
        case 'v':
            pan_angle -= STEP_DEG;
            if (pan_angle < 0) pan_angle = 0;
            break;
        case '<':
            tilt_angle -= STEP_DEG;
            if (tilt_angle < 0) tilt_angle = 0;
            break;
        case '>':
            tilt_angle += STEP_DEG;
            if (tilt_angle > 180) tilt_angle = 180;
            break;
        default:
            /* Ignore unexpected characters */
            continue;
        }

        if (set_servo_angle(PAN_GPIO, pan_angle) != 0 ||
            set_servo_angle(TILT_GPIO, tilt_angle) != 0) {
            fprintf(stderr, "Warning: servo command failed, continuing...\n");
            continue;
        }

        printf("Pan: %3d deg  Tilt: %3d deg\n", pan_angle, tilt_angle);
        fflush(stdout);
        usleep(STEP_DELAY_US);
    }

    /* --- Clean shutdown: neutral position, terminate pigpio --- */
    set_servo_angle(PAN_GPIO, NEUTRAL_DEG);
    set_servo_angle(TILT_GPIO, NEUTRAL_DEG);
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

