code:
/*
 * Raspberry Pi 4 Model B — Anemometer + Wind Vane Monitor
 *
 * Hardware:
 *   - Anemometer pulse output  -> GPIO17 (BCM)
 *   - Wind vane ADC channel 0  -> MCP3008 on SPI0/CE0 (mode 0, 1 MHz)
 *   - 16x2 LCD via PCF8574     -> I2C bus 1 (address 0x38)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o wind_monitor wind_monitor.c \
 *       -lm -lpthread -lrt -lm
 *
 * Run:
 *   sudo ./wind_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

/* ----------------------------- Configuration ----------------------------- */

#define ANEMOMETER_GPIO      17          /* BCM pin for anemometer pulse */
#define MCP3008_CHANNEL     0           /* MCP3008 single-ended channel 0 */
#define SPI_DEVICE          "/dev/spidev0.0"
#define I2C_DEVICE          "/dev/i2c-1"
#define LCD_I2C_ADDR        0x38         /* PCF8574 backpack default address */
#define LCD_WIDTH           16
#define LCD_HEIGHT          2
#define SAMPLE_WINDOW_MS    500
#define SPI_SPEED_HZ        1000000      /* 1 MHz — well within MCP3008 spec */
#define SPI_BITS_PER_WORD   8
#define SPI_MODE            SPI_MODE_0

/* ------------------------------- Globals --------------------------------- */

static volatile sig_atomic_t g_running = 1;
static volatile uint32_t     g_pulse_count = 0;
static volatile uint32_t     g_last_pulse_tick = 0;
static volatile uint32_t     g_last_sample_tick = 0;
static volatile int          g_spi_fd      = -1;
static volatile int          g_i2c_fd      = -1;

/* --------------------------- Driver helpers ------------------------------ */

/* -------------------------------------------------------------------------- */
/* I2C helpers (PCF8574 via I2C)                                               */
/* -------------------------------------------------------------------------- */

static int i2c_write_byte(int fd, uint8_t byte)
{
    if (ioctl(fd, I2C_SLAVE, LCD_I2C_ADDR) < 0) {
        fprintf(stderr, "I2C_SLAVE ioctl failed: %s\n", strerror(errno));
        return -1;
    }
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_write_byte_data(int fd, uint8_t reg, uint8_t data)
{
    uint8_t buf[2] = { reg, data };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write (data) failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int fd, uint8_t *out)
{
    if (ioctl(fd, I2C_SLAVE, LCD_I2C_ADDR) < 0) {
        fprintf(stderr, "I2C_SLAVE ioctl failed: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, out, 1) != 1) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_byte_data(int fd, uint8_t reg, uint8_t *out)
{
    if (ioctl(fd, I2C_SLAVE, LCD_I2C_ADDR) < 0) {
        fprintf(stderr, "I2C_SLAVE ioctl failed: %s\n", strerror(errno));
        return -1;
    }
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg) failed: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, out, 1) != 1) {
        fprintf(stderr, "I2C read (data) failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* -------------------------------------------------------------------------- */
/* SPI helpers (MCP3008)                                                      */
/* -------------------------------------------------------------------------- */

static int spi_transfer(int fd, uint8_t *tx, uint8_t *rx, size_t len)
{
    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)tx,
        .rx_buf        = (unsigned long)rx,
        .len           = len,
        .speed_hz      = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs   = 0,
        .cs_change     = 0,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * MCP3008 single-ended read.
 * Returns 0–1023 on success, -1 on error.
 */
static int mcp3008_read(int fd, uint8_t channel)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %u\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)(0x80 | (channel << 4)), 0x00 };
    uint8_t rx[3] = { 0 };

    if (spi_transfer(fd, tx, rx, sizeof(tx)) < 0)
        return -1;

    return ((rx[1] & 0x03) << 8) | rx[2];
}

/* -------------------------------------------------------------------------- */
/* Anemometer                                                      */
/* -------------------------------------------------------------------------- */

/*
 * Read anemometer pulse count over a 500 ms window.
 * Returns the new pulse count, or -1 on error.
 */
static int read_anemometer(int fd)
{
    uint32_t start_tick = g_last_sample_tick;
    g_last_sample_tick = 0;

    uint32_t elapsed_us = 0;
    int pulses = 0;

    while (elapsed_us < (uint32_t)(SAMPLE_WINDOW_MS * 1000)) {
        if (g_pulse_count > g_last_pulse_tick) {
            pulses++;
            g_last_pulse_tick = g_pulse_count;
        }
        g_pulse_count = 0;
        usleep(1000);
        elapsed_us += 1000;
    }

    if (elapsed_us >= (uint32_t)(SAMPLE_WINDOW_MS * 1000))
        elapsed_us = SAMPLE_WINDOW_MS * 1000;

    g_last_sample_tick = start_tick + (uint32_t)(elapsed_us - SAMPLE_WINDOW_MS * 1000);
    return pulses;
}

/* -------------------------------------------------------------------------- */
/* Wind direction                                                   */
/* -------------------------------------------------------------------------- */

/*
 * Read wind direction from the MCP3008 channel.
 * Returns 0–360 degrees, or -1 on error.
 */
static int read_wind_direction(int fd)
{
    int adc_value = mcp3008_read(fd, MCP3008_CHANNEL);
    if (adc_value < 0)
        return -1;

    if (adc_value == 0 || adc_value == 1023) {
        fprintf(stderr, "Warning: ADC reading at rail (%d) — sensor absent or wiring fault\n", adc_value);
        return -1;
    }

    /* Simplified linear approximation of wind direction (0–360°) */
    double angle = (double)adc_value / 1023.0 * 360.0;
    if (angle > 360.0)
        angle = 360.0;
    if (angle < 0.0)
        angle = 0.0;
    return (int)angle;
}

/* -------------------------------------------------------------------------- */
/* LCD display                                                         */
/* -------------------------------------------------------------------------- */

static void lcd_write_string(int fd, uint8_t reg, const char *str)
{
    if (i2c_write_byte_data(fd, reg, (uint8_t)(str[0] & 0xFF)) < 0)
        return;
    if (i2c_write_byte_data(fd, reg, (uint8_t)(str[1] & 0xFF)) < 0)
        return;
    if (i2c_write_byte_data(fd, reg, (uint8_t)(str[2] & 0xFF)) < 0)
        return;
    if (i2c_write_byte_data(fd, reg, (uint8_t)(str[3] & 0xFF)) < 0)
        return;
}

static void lcd_clear(int fd)
{
    lcd_write_string(fd, 0x00, "                ");
    lcd_write_string(fd, 0x01, "                ");
}

static void lcd_update(int fd, int wind_speed, int wind_direction)
{
    char line1[LCD_WIDTH];
    char line2[LCD_WIDTH];

    if (wind_speed < 0)
        snprintf(line1, sizeof(line1), "Speed:        ");
    else
        snprintf(line1, sizeof(line1), "Speed: %3d m/s", wind_speed);

    if (wind_direction < 0)
        snprintf(line2, sizeof(line2), "Dir:          ");
    else
        snprintf(line2, sizeof(line2), "Dir: %3d deg", wind_direction);

    lcd_clear(fd);
    lcd_write_string(fd, 0x00, line1);
    lcd_write_string(fd, 0x40, line2);
}

/* -------------------------------------------------------------------------- */
/* Signal handling                                                     */
/* -------------------------------------------------------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* -------------------------------------------------------------------------- */
/* Cleanup                                                             */
/* -------------------------------------------------------------------------- */

static void cleanup(void)
{
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* -------------------------------------------------------------------------- */
/* Main                                                                */
/* -------------------------------------------------------------------------- */

int main(void)
{
    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus for LCD */
    g_i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open SPI bus for MCP3008 */
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", SPI_DEVICE, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* Configure SPI mode */
    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure SPI bits per word */
    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure SPI max speed */
    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize LCD */
    if (i2c_write_byte_data(g_i2c_fd, 0x30, 0x00) < 0) { /* Force 4-bit mode */
        fprintf(stderr, "LCD init failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    usleep(5000);
    if (i2c_write_byte_data(g_i2c_fd, 0x30, 0x08) < 0) { /* 4-bit, 2 lines, 5x8 font */
        fprintf(stderr, "LCD init failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    usleep(1500);
    if (i2c_write_byte_data(g_i2c_fd, 0x28, 0x01) < 0) { /* Clear display */
        fprintf(stderr, "LCD clear failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    usleep(2000);
    if (i2c_write_byte_data(g_i2c_fd, 0x0C, 0x0C) < 0) { /* Display on, cursor off */
        fprintf(stderr, "LCD cursor off failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    usleep(2000);
    if (i2c_write_byte_data(g_i2c_fd, 0x06, 0x01) < 0) { /* Entry mode: increment, no shift */
        fprintf(stderr, "LCD entry mode failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    usleep(2000);
    if (i2c_write_byte_data(g_i2c_fd, 0x01, 0x00) < 0) { /* Return home */
        fprintf(stderr, "LCD home failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    usleep(2000);

    printf("Wind monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int wind_speed = read_anemometer(g_spi_fd);
        int wind_direction = read_wind_direction(g_spi_fd);

        if (wind_speed < 0 || wind_direction < 0) {
            fprintf(stderr, "Sensor read error — continuing\n");
        } else {
            lcd_update(g_i2c_fd, wind_speed, wind_direction);
        }

        /* Sleep for the remainder of the 500 ms window */
        uint32_t remaining = SAMPLE_WINDOW_MS * 1000 - (uint32_t)(clock() - g_last_sample_tick);
        if (remaining > 0)
            usleep((useconds_t)remaining);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

