/*
 * Water Flow Rate Monitor using YF-S201 sensor on Raspberry Pi 3 Model B+
 * Sensor: YF-S201 pulse output -> GPIO17 (BCM, physical pin 11)
 * LCD1602: I2C bus 1 (SDA=GPIO2/physical pin 3, SCL=GPIO3/physical pin 5)
 * Build: gcc -O2 -Wall -o flow_monitor flow_monitor.c -lpigpio -li2c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SENSOR_GPIO          17          /* BCM pin for YF-S201 pulse output */
#define I2C_BUS              1           /* /dev/i2c-1 on RPi 3B+ */
#define LCD_WIDTH            16          /* LCD1602 character width */
#define LCD_HEIGHT            2          /* LCD1602 line count */
#define SAMPLE_INTERVAL_US   1000000     /* 1 second in microseconds */
#define ZERO_PULSE_COUNT     5           /* consecutive zero pulses = sensor absent */

/* ----------------------------- Globals ---------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ----------------------------- Prototypes -------------------------------- */
static void signal_handler(int sig);
static int  init_gpio(void);
static int  init_i2c(void);
static int  lcd_write_nibble(uint8_t nibble, uint8_t rs);
static int  lcd_send_byte(uint8_t data, bool rs);
static int  lcd_command(uint8_t cmd);
static int  lcd_data(uint8_t data);
static int  lcd_init(void);
static int  lcd_clear(void);
static int  lcd_set_cursor(uint8_t row, uint8_t col);
static int  lcd_write_string(const char *str);
static void cleanup(void);

/* ----------------------------- Signal Handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- GPIO / I2C -------------------------------- */
static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(SENSOR_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SENSOR_GPIO);
        gpioTerminate();
        return -1;
    }

    /* YF-S201 pulse output is open-drain; enable internal pull-down so the
     * line reads LOW when the sensor is idle. */
    if (gpioSetPullUpDown(SENSOR_GPIO, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Warning: failed to set pull-down on GPIO%d.\n", SENSOR_GPIO);
    }

    /* Optional: enable internal pull-up for the open-drain output if the
     * sensor is disconnected. */
    if (gpioSetPullUpDown(SENSOR_GPIO, PI_PUD_UP) < 0) {
        fprintf(stderr, "Warning: failed to set pull-up on GPIO%d.\n", SENSOR_GPIO);
    }

    return 0;
}

static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, 0, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed on bus %d (handle=%d).\n",
                I2C_BUS, g_i2c_handle);
        return -1;
    }
    return 0;
}

/*
 * Send a nibble to the LCD controller (4-bit mode).
 * rs: 0 = command, 1 = data
 */
static int lcd_write_nibble(uint8_t nibble, uint8_t rs)
{
    uint8_t hi = (nibble & 0xF0) | (rs ? 0x04 : 0x00);
    uint8_t lo = ((nibble << 4) & 0xF0) | (rs ? 0x02 : 0x00);

    if (i2cWriteByteData(g_i2c_handle, 0x00, hi) < 0) {
        fprintf(stderr, "Error: i2cWriteByteData (nibble hi) failed.\n");
        return -1;
    }
    if (i2cWriteByteData(g_i2c_handle, 0x00, lo) < 0) {
        fprintf(stderr, "Error: i2cWriteByteData (nibble lo) failed.\n");
        return -1;
    }
    return 0;
}

static int lcd_send_byte(uint8_t data, bool rs)
{
    if (lcd_write_nibble(data >> 4, rs) < 0)
        return -1;
    if (lcd_write_nibble(data & 0x0F, rs) < 0)
        return -1;
    return 0;
}

static int lcd_command(uint8_t cmd)
{
    return lcd_send_byte(cmd, false);
}

static int lcd_data(uint8_t data)
{
    return lcd_send_byte(data, true);
}

static int lcd_init(void)
{
    /* Wait > 50 ms after power-up for the LCD to power up. */
    gpioDelay(50000);

    /* Force 4-bit mode. */
    if (lcd_write_nibble(0x30, false) < 0) return -1;
    gpioDelay(5000);                       /* 4.1 ms */

    if (lcd_write_nibble(0x30, false) < 0) return -1;
    gpioDelay(1000);                       /* 1.52 ms */

    if (lcd_write_nibble(0x30, false) < 0) return -1;
    gpioDelay(1000);                       /* 1.52 ms */

    if (lcd_write_nibble(0x20, false) < 0) return -1; /* switch to 4-bit */

    if (lcd_command(0x28) < 0) return -1; /* 2-line, 5x8 font */
    if (lcd_command(0x0C) < 0) return -1; /* display on, cursor off */
    if (lcd_command(0x06) < 0) return -1; /* entry mode: increment, no shift */
    if (lcd_command(0x01) < 0) return -1; /* clear display */
    gpioDelay(2000);                      /* 2 ms */
    return 0;
}

static int lcd_clear(void)
{
    return lcd_command(0x01);
}

static int lcd_set_cursor(uint8_t row, uint8_t col)
{
    uint8_t addr = (row == 0) ? 0x80 : 0xC0;
    addr += col;
    return lcd_command(addr);
}

static int lcd_write_string(const char *str)
{
    while (*str) {
        if (lcd_data((uint8_t)*str) < 0)
            return -1;
        str++;
    }
    return 0;
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (init_gpio() < 0)
        return EXIT_FAILURE;

    if (init_i2c() < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (lcd_init() < 0) {
        fprintf(stderr, "Error: LCD initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Allow LCD to settle after power-up. */
    gpioDelay(200000);

    printf("Water flow rate monitoring started. Press Ctrl+C to exit.\n");

    int zero_count = 0;
    uint32_t last_pulse_tick = 0;
    uint32_t start_tick = gpioTick();

    while (g_running) {
        uint32_t now = gpioTick();

        /* YF-S201 pulse output is active-high; count rising edges. */
        if (gpioRead(SENSOR_GPIO) == 1) {
            if (last_pulse_tick == 0) {
                last_pulse_tick = now;
                zero_count = 0;
            } else if ((now - last_pulse_tick) > 1000) {
                /* Debounce: ignore pulses that arrive too quickly. */
                last_pulse_tick = now;
                zero_count = 0;
            }
        } else {
            if (last_pulse_tick != 0) {
                zero_count++;
                last_pulse_tick = 0;
            }
        }

        /* Sample every 1 s. */
        if ((now - start_tick) >= SAMPLE_INTERVAL_US) {
            start_tick = now;

            if (zero_count >= ZERO_PULSE_COUNT) {
                /* Sensor absent or not connected. */
                fprintf(stderr, "Warning: no pulses detected for %d consecutive "
                                "samples. Sensor may be absent or disconnected.\n",
                                zero_count);
                lcd_clear();
                lcd_set_cursor(0, 0);
                lcd_write_string("Sensor Absent");
                lcd_set_cursor(1, 0);
                lcd_write_string("Check wiring");
                gpioDelay(2000000);
                lcd_clear();
                lcd_set_cursor(0, 0);
                lcd_write_string("Flow Rate:");
                lcd_set_cursor(1, 0);
                lcd_write_string("0.00 L/min");
                zero_count = 0;
            } else {
                /* Count pulses in the last second. */
                int pulses = gpioRead(SENSOR_GPIO);
                if (pulses < 0) {
                    fprintf(stderr, "Error: gpioRead failed on GPIO%d.\n", SENSOR_GPIO);
                    zero_count = 0;
                } else {
                    int count = pulses;
                    if (count < 0) count = 0;
                    if (count > 100) count = 100; /* sanity cap */
                    zero_count = count;
                }

                /* Flow rate: pulses per second * (1 L/s / 60 s/min) */
                float flow_rate = (float)zero_count / 60.0f;

                lcd_clear();
                lcd_set_cursor(0, 0);
                lcd_write_string("Flow Rate:");
                lcd_set_cursor(1, 0);
                char buf[LCD_WIDTH + 1];
                snprintf(buf, sizeof(buf), "%6.2f L/min", flow_rate);
                lcd_write_string(buf);
            }
        }

        gpioDelay(10000); /* 10 ms poll interval */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

