#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <stdbool.h>
#include <pigpio.h>

#define NUM_ROWS 8
#define NUM_COLS 8

#define ROW_PINS {17, 18, 27, 22, 23, 24, 25, 4}
#define COL_PINS {5, 6, 12, 13, 19, 16, 26, 20}

static const int row_pins[NUM_ROWS] = ROW_PINS;
static const int col_pins[NUM_COLS] = COL_PINS;

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    for (int i = 0; i < NUM_ROWS; i++) {
        gpioWrite(row_pins[i], 0);
    }
    for (int i = 0; i < NUM_COLS; i++) {
        gpioWrite(col_pins[i], 1);
    }
    gpioTerminate();
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    for (int i = 0; i < NUM_ROWS; i++) {
        if (gpioSetMode(row_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set row pin %d as output\n", row_pins[i]);
            cleanup();
            return -1;
        }
        if (gpioWrite(row_pins[i], 0) != 0) {
            fprintf(stderr, "Error: failed to initialise row pin %d to LOW\n", row_pins[i]);
            cleanup();
            return -1;
        }
    }

    for (int i = 0; i < NUM_COLS; i++) {
        if (gpioSetMode(col_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set col pin %d as output\n", col_pins[i]);
            cleanup();
            return -1;
        }
        if (gpioWrite(col_pins[i], 1) != 0) {
            fprintf(stderr, "Error: failed to initialise col pin %d to HIGH\n", col_pins[i]);
            cleanup();
            return -1;
        }
    }

    return 0;
}

static void shift_left(int *pattern, int size) {
    for (int i = size - 1; i > 0; i--) {
        pattern[i] = pattern[i - 1];
    }
    pattern[0] = 0;
}

static void shift_right(int *pattern, int size) {
    for (int i = 1; i < size; i++) {
        pattern[i] = pattern[i - 1];
    }
    pattern[0] = 0;
}

static void draw_frame(int row_pattern, int col_pattern) {
    for (int r = 0; r < NUM_ROWS; r++) {
        if (gpioWrite(row_pins[r], 1) != 0) {
            fprintf(stderr, "Error: failed to set row pin %d HIGH\n", row_pins[r]);
            cleanup();
            exit(EXIT_FAILURE);
        }
    }

    for (int c = 0; c < NUM_COLS; c++) {
        if (gpioWrite(col_pins[c], 0) != 0) {
            fprintf(stderr, "Error: failed to set col pin %d LOW\n", col_pins[c]);
            cleanup();
            exit(EXIT_FAILURE);
        }
    }

    for (int r = 0; r < NUM_ROWS; r++) {
        if (gpioWrite(row_pins[r], row_pattern & (1 << r)) != 0) {
            fprintf(stderr, "Error: failed to set row pin %d\n", row_pins[r]);
            cleanup();
            exit(EXIT_FAILURE);
        }
    }

    for (int c = 0; c < NUM_COLS; c++) {
        if (gpioWrite(col_pins[c], col_pattern & (1 << c)) != 0) {
            fprintf(stderr, "Error: failed to set col pin %d\n", col_pins[c]);
            cleanup();
            exit(EXIT_FAILURE);
        }
    }

    gpioDelay(800);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    int row_pattern = 0xFF;
    int col_pattern = 0xFF;

    while (running) {
        draw_frame(row_pattern, col_pattern);

        shift_left(&row_pattern, NUM_ROWS);
        shift_right(&col_pattern, NUM_COLS);
    }

    cleanup();
    return EXIT_SUCCESS;
}

