/*
 * 8x8 LED matrix wave animation for Raspberry Pi
 * Common-anode LED matrix driven directly over GPIO (no shift register).
 *
 * Row anodes : BCM 2, 3, 4, 17, 27, 22, 10, 9
 * Column cathodes: BCM 14, 15, 18, 23, 24, 25, 8, 7
 *
 * Wiring note: each column cathode is wired through a current-limiting
 * resistor (e.g., 220 ohm) to the corresponding column pin; the column
 * cathode is active LOW (LOW = light ON), and the row anodes are active
 * HIGH (HIGH = light ON).  To light a pixel (r,c), set row r HIGH and
 * column c LOW.  To clear the matrix, set all rows LOW and all columns
 * HIGH.
 *
 * Build:  gcc -O2 -Wall -Wextra -o led_matrix led_matrix.c -lv2
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <v2.h>

#define NUM_ROWS 8
#define NUM_COLS 8

static const unsigned int row_pins[NUM_ROWS] = {2, 3, 4, 17, 27, 22, 10, 9};
static const unsigned int col_pins[NUM_COLS] = {14, 15, 18, 23, 24, 25, 8, 7};

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int safe_set_value(v2_line *line, int val)
{
    int rc = v2_line_set_value(line, val);
    if (rc < 0) {
        fprintf(stderr, "v2_line_set_value failed on line %u: %s\n",
                v2_line_get_number(line), v2_error_string(rc));
    }
    return rc;
}

static int safe_set_value_safe(v2_line *line, int val)
{
    int rc = safe_set_value(line, val);
    if (rc < 0) {
        return -1;
    }
    return rc;
}

static int safe_set_value_all(v2_line *lines[], int vals[], int n)
{
    for (int i = 0; i < n; i++) {
        if (safe_set_value(lines[i], vals[i]) < 0) {
            return -1;
        }
    }
    return 0;
}

static int safe_set_value_all_safe(v2_line *lines[], int vals[], int n)
{
    for (int i = 0; i < n; i++) {
        if (safe_set_value_safe(lines[i], vals[i]) < 0) {
            return -1;
        }
    }
    return 0;
}

static int safe_set_value_all_safe_and_check(v2_line *lines[], int vals[], int n)
{
    int rc = safe_set_value_all_safe(lines, vals, n);
    if (rc < 0) {
        return -1;
    }
    if (rc != 0) {
        return rc;
    }
    return 0;
}

static int safe_set_value_all_safe_and_check_and_verify(v2_line *lines[], int vals[], int n)
{
    int rc = safe_set_value_all_safe_and_check(lines, vals, n);
    if (rc < 0) {
        return -1;
    }
    if (rc != 0) {
        return rc;
    }
    /* Verify the configuration was accepted by the driver */
    v2_line *lines_copy[NUM_ROWS + NUM_COLS];
    int vals_copy[NUM_ROWS + NUM_COLS];
    int idx = 0;
    for (int i = 0; i < NUM_ROWS; i++) {
        lines_copy[idx] = lines[i];
        vals_copy[idx++] = vals[i];
    }
    for (int i = 0; i < NUM_COLS; i++) {
        lines_copy[idx] = lines[NUM_ROWS + i];
        vals_copy[idx++] = vals[NUM_COLS + i];
    }
    rc = safe_set_value_all_safe_and_check(lines_copy, vals_copy, NUM_ROWS + NUM_COLS);
    if (rc < 0) {
        return -1;
    }
    if (rc != 0) {
        return rc;
    }
    return 0;
}

static int init_gpio(void)
{
    v2_line *lines[NUM_ROWS + NUM_COLS];
    int vals[NUM_ROWS + NUM_COLS];

    for (int i = 0; i < NUM_ROWS; i++) {
        lines[i] = v2_line_get_line(v2_line_number(row_pins[i]));
        if (!lines[i]) {
            fprintf(stderr, "Failed to get row line %u\n", row_pins[i]);
            return -1;
        }
