                v2_line_get_number(line), v2_error_string(rc));
    }
    return rc;
}

static int safe_set_value_safe(v2_line *line, int val)
{
    int rc = safe_set_value(line, val);
    if (rc < 0) {
        return -1;
    }
    return rc;
}

