        if (!lines[NUM_ROWS + i]) {
            fprintf(stderr, "Failed to get col line %u\n", col_pins[i]);
            return -1;
        }
        vals[NUM_ROWS + i] = V2_LINE_VALUE_ACTIVE;
    }

    if (safe_set_value_all_safe_and_check_and_verify(lines, vals, NUM_ROWS + NUM_COLS) < 0) {
        fprintf(stderr, "Failed to clear matrix\n");
        return -1;
    }
    return 0;
}

static int set_pixel(int row, int col)
{
    v2_line *lines[NUM_ROWS + NUM_COLS];
    int vals[NUM_ROWS + NUM_COLS];

