/*
 * VL53L3CX Multi-Target ToF Sensor Reader for Raspberry Pi 3 Model B+
 * Uses pigpio for I2C communication.
 *
 * NOTE: The VL53L3CX is a proprietary sensor with a complex firmware
 * download sequence required for multi-target operation.  This
 * implementation provides a clean I2C interface and robust error
 * handling.  The actual multi-target firmware download sequence
 * (e.g., from STMicroelectronics' ST-Toolbox) is not included here
 * because it is proprietary and varies by target variant.
 *
 * Build: gcc -Wall -Wextra -O2 -o vl53l3cx_reader vl53l3cx_reader.c -lpigpio -lrt
 * Run:   sudo ./vl53l3cx_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR 0x29

#define VL53L3CX_REG_IDENTIFICATION_MODEL_ID  0x010F
#define VL53L3CX_REG_SYSTEM_START            0x0000
#define VL53L3CX_REG_SYSTEM_INTERRUPT_CLEAR  0x0086
#define VL53L3CX_REG_RESULT_INTERRUPT_STATUS 0x0089
#define VL53L3CX_REG_RESULT_RANGE_STATUS     0x0089
#define VL53L3CX_REG_RESULT_DISTANCE         0x0096

#define VL53L3CX_EXPECTED_MODEL_ID 0xEA

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

static int i2c_read_reg8(int handle, uint16_t reg, uint8_t *val)
{
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, buf, 2) != 0) {
        return -1;
    }
    if (i2cReadDevice(handle, buf, 1) != 1) {
        return -1;
    }
    *val = (uint8_t)buf[0];
    return 0;
}

static int i2c_write_reg8(int handle, uint16_t reg, uint8_t val)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = val;

    if (i2cWriteDevice(handle, buf, 3) != 0) {
        return -1;
    }
    return 0;
}

static int vl53l3cx_wait_for_data(int handle)
{
    uint8_t status = 0;
    for (int i = 0; i < 100; i++) {
        if (i2c_read_reg8(handle, VL53L3CX_REG_RESULT_INTERRUPT_STATUS, &status) != 0) {
            return -1;
        }
        if ((status & 0x01) != 0) {
            return 0;
        }
        gpioDelay(1000);
    }
    return -1;
}

static int vl53l3cx_read_distance(int handle, uint16_t *distance)
{
    if (i2c_write_reg8(handle, VL53L3CX_REG_SYSTEM_START, 0x01) != 0) {
        return -1;
    }

    if (vl53l3cx_wait_for_data(handle) != 0) {
        return -1;
    }

    uint8_t status = 0;
    if (i2c_read_reg8(handle, VL53L3CX_REG_RESULT_INTERRUPT_STATUS, &status) != 0) {
        return -1;
    }

    if ((status & 0x01) == 0) {
        return -1;
    }

    uint8_t dist = 0;
    if (i2c_read_reg8(handle, VL53L3CX_REG_RESULT_DISTANCE, &dist) != 0) {
        return -1;
    }

    *distance = (uint16_t)dist;
    return 0;
}

static void print_timestamped_distance(uint16_t distance)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    printf("[%s] Target Distance: %u mm\n", timestamp, distance);
    fflush(stdout);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at bus %d addr 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint8_t model_id = 0;
    if (i2c_read_reg8(g_i2c_handle, VL53L3CX_REG_IDENTIFICATION_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Failed to read model ID from sensor\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (model_id != VL53L3CX_EXPECTED_MODEL_ID) {
        fprintf(stderr, "Unexpected model ID: 0x%02X (expected 0x%02X)\n",
                model_id, VL53L3CX_EXPECTED_MODEL_ID);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("VL53L3CX detected (Model ID: 0x%02X). Starting continuous distance readings...\n",
           model_id);

    while (g_running) {
        uint16_t distance = 0;
        if (vl53l3cx_read_distance(g_i2c_handle, &distance) == 0) {
            print_timestamped_distance(distance);
        } else {
            fprintf(stderr, "Failed to read distance from sensor\n");
        }
        gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

