    if (i2c_read_reg8(handle, VL53L3CX_REG_RESULT_DISTANCE, &dist) != 0) {
        return -1;
    }

    *distance = (uint16_t)dist;
    return 0;
}

static void print_timestamped_distance(uint16_t distance)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    printf("[%s] Target Distance: %u mm\n", timestamp, distance);
    fflush(stdout);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at bus %d addr 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint8_t model_id = 0;
    if (i2c_read_reg8(g_i2c_handle, VL53L3CX_REG_IDENTIFICATION_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Failed to read model ID from sensor\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (model_id != VL53L3CX_EXPECTED_MODEL_ID) {
        fprintf(stderr, "Unexpected model ID: 0x%02X (expected 0x%02X)\n",
                model_id, VL53L3CX_EXPECTED_MODEL_ID);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("VL53L3CX detected (Model ID: 0x%02X). Starting continuous distance readings...\n",
           model_id);

    while (g_running) {
        uint16_t distance = 0;
        if (vl53l3cx_read_distance(g_i2c_handle, &distance) == 0) {
            print_timestamped_distance(distance);
        } else {
            fprintf(stderr, "Failed to read distance from sensor\n");
        }
        gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

