/*
 * MLX75031 Time-of-Flight distance logger for Raspberry Pi Zero W
 *
 * Wiring:
 *   MLX75031 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   MLX75031 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   MLX75031 VDD  -> 3.3 V
 *   MLX75031 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o mlx75031_log mlx75031_log.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MLX75031_ADDR  0x50
#define LOG_FILE       "depth_log.csv"
#define SAMPLE_MS      100

/* MLX75031 register addresses (16-bit, big-endian on the bus) */
#define MLX75031_REG_DISTANCE  0x00
#define MLX75031_REG_CONFIG    0x01

/* Config: 100 ms sample period, 50 Hz update rate, 16-bit distance */
#define MLX75031_CONFIG_VALUE  0x0002

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit value to an 16-bit-addressed MLX75031 register.     */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int mlx75031_write_reg16(int fd, uint16_t reg, uint16_t value)
{
    uint8_t buf[4];
    buf[0] = (uint8_t)(reg >> 8);
    buf[1] = (uint8_t)(reg & 0xFF);
    buf[2] = (uint8_t)(value >> 8);
    buf[3] = (uint8_t)(value & 0xFF);

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "mlx75031_write_reg16: write to reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit value from an 16-bit-addressed MLX75031 register.    */
/* Returns 0 on success and stores the value in *out; -1 on error.    */
/* ------------------------------------------------------------------ */
static int mlx75031_read_reg16(int fd, uint16_t reg, uint16_t *out)
{
    uint8_t addr[2];
    uint8_t data[2];

    addr[0] = (uint8_t)(reg >> 8);
    addr[1] = (uint8_t)(reg & 0xFF);

    if (write(fd, addr, sizeof(addr)) != (ssize_t)sizeof(addr)) {
        fprintf(stderr, "mlx75031_read_reg16: write addr 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (read(fd, data, sizeof(data)) != (ssize_t)sizeof(data)) {
        fprintf(stderr, "mlx75031_read_reg16: read from reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the MLX75031: configure sample period and update rate.   */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int mlx75031_init(int fd)
{
    if (mlx75031_write_reg16(fd, MLX75031_REG_CONFIG, MLX75031_CONFIG_VALUE) != 0) {
        fprintf(stderr, "mlx75031_init: failed to write config register\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read the distance register; returns -1 on error.                   */
/* ------------------------------------------------------------------ */
static int mlx75031_read_distance(int fd, int *distance)
{
    uint16_t raw;

    if (mlx75031_read_reg16(fd, MLX75031_REG_DISTANCE, &raw) != 0)
        return -1;

    *distance = (int)raw;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Append one CSV row: timestamp, distance.                            */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, int distance)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "log_data: localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "log_data: strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%d\n", ts, distance) < 0) {
        fprintf(stderr, "log_data: fprintf failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "log_data: fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Open the I2C bus and target the MLX75031.                           */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int i2c_open(void)
{
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "i2c_open: open %s failed: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, MLX75031_ADDR) < 0) {
        fprintf(stderr, "i2c_open: ioctl I2C_SLAVE 0x%02X failed: %s\n",
                MLX75031_ADDR, strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

/* ------------------------------------------------------------------ */
/* Close the I2C handle and the log file.                              */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = i2c_open();
    if (g_i2c_fd < 0)
        return EXIT_FAILURE;

    if (mlx75031_init(g_i2c_fd) != 0) {
        fprintf(stderr, "MLX75031 init failed; sensor may be absent or bus error.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header only if file is empty */
    if (fseek(g_log_fp, 0, SEEK_END) == 0) {
        long sz = ftell(g_log_fp);
        if (sz == 0)
            fprintf(g_log_fp, "timestamp,distance\n");
    } else {
        fprintf(stderr, "fseek failed: %s\n", strerror(errno));
    }

    printf("MLX75031 logger started. Logging to %s every %d ms. Press Ctrl+C to stop.\n",
           LOG_FILE, SAMPLE_MS);

    while (g_running) {
        int distance;

        if (mlx75031_read_distance(g_i2c_fd, &distance) != 0) {
            fprintf(stderr, "I2C read error; logging -1 and re-opening bus.\n");
            if (g_log_fp != NULL) {
                if (log_data(g_log_fp, -1) != 0)
                    fprintf(stderr, "log_data failed; continuing.\n");
            }
            close(g_i2c_fd);
            g_i2c_fd = -1;
            usleep(100000);
            g_i2c_fd = i2c_open();
            if (g_i2c_fd < 0) {
                fprintf(stderr, "Re-open failed; exiting.\n");
                break;
            }
            if (mlx75031_init(g_i2c_fd) != 0) {
                fprintf(stderr, "Re-init failed; exiting.\n");
                break;
            }
            continue;
        }

        if (log_data(g_log_fp, distance) != 0)
            fprintf(stderr, "log_data failed; continuing.\n");

        usleep(SAMPLE_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

