static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int si1145_write_byte(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %s\n",
                reg, value, pigpio_error(rc));
    }
    return rc;
}

static int si1145_write_word(int handle, uint8_t reg, uint16_t value)
{
    int rc = i2cWriteWordData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "i2cWriteWordData(reg=0x%02X, val=0x%04X) failed: %s\n",
                reg, value, pigpio_error(rc));
    }
    return rc;
}

static int si1145_read_byte(int handle, uint8_t reg)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "i2cReadByteData(reg=0x%02X) failed: %s\n",
                reg, pigpio_error(rc));
    }
    return rc;
}

static int si1145_read_word(int handle, uint8_t reg)
{
    int rc = i2cReadWordData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "i2cReadWordData(reg=0x%02X) failed: %s\n",
                reg, pigpio_error(rc));
    }
    return rc;
}

static int si1145_write_command(int handle, uint8_t cmd)
{
    if (si1145_write_byte(handle, SI1145_REG_COMMAND, cmd) < 0)
        return -1;
    gpioDelay(SI1145_CMD_DELAY_US);
    return 0;
}

static int si1145_wait_for_command(int handle, uint8_t cmd, uint32_t timeout_us)
{
    uint32_t start = gpioTick();
    while (g_running) {
        int b = si1145_read_byte(handle, SI1145_REG_COMMAND);
        if (b < 0)
            return -1;
        if (b == cmd)
            return 0;
        if ((gpioTick() - start) > timeout_us)
            return -1;
    }
    return -1;
}

static int si1145_init(int handle)
{
    int part_id = si1145_read_byte(handle, SI1145_REG_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Cannot read PART_ID — sensor absent or bus error.\n");
        return -1;
    }
    if (part_id != 0x45) {
        fprintf(stderr, "Unexpected PART_ID 0x%02X (expected 0x45).\n", part_id);
        return -1;
    }

    if (si1145_write_byte(handle, SI1145_REG_HW_KEY, SI1145_HW_KEY_VAL) < 0)
        return -1;

    if (si1145_write_word(handle, SI1145_REG_MEAS_RATE0, 0x00) < 0)
        return -1;
    if (si1145_write_word(handle, SI1145_REG_MEAS_RATE1, 0x00) < 0)
        return -1;
    if (si1145_write_word(handle, SI1145_REG_PS_RATE, 0x00) < 0)
        return -1;
    if (si1145_write_word(handle, SI1145_REG_ALS_RATE, 0x00) < 0)
        return -1;

    if (si1145_write_command(handle, SI1145_CMD_RESET) < 0)
        return -1;
    gpioDelay(SI1145_RESET_DELAY_US);

