/*
 * E18-D50NK IR proximity sensor → falling-edge timestamped log + LED blink.
 *
 * Board : Raspberry Pi 5 (BCM numbering)
 * Sensor: E18-D50NK on GPIO 4  (physical pin 7)  — LOW  when object detected
 * LED   : GPIO 17 (physical pin 11) — 100 ms on/off pulse on detection
 *
 * Build:  gcc -O2 -Wall -Wextra -o proximity proximity.c -lpigpio -lrt
 * Run   :  sudo ./proximity
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define SENSOR_PIN      4
#define LED_PIN         17
#define LOG_FILE        "proximity.log"
#define POLL_DELAY_US   100000          /* 100 ms */
#define LED_ON_US       100000          /* 100 ms */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper (ISO 8601 UTC)                                    */
/* ------------------------------------------------------------------ */
static int get_iso8601_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        return -1;
    }

    struct tm tm_utc;
    if (gmtime_r(&now, &tm_utc) == NULL) {
        return -1;
    }

    if (strftime(buf, len, "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_event(const char *timestamp)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    if (fprintf(fp, "%s Object detected\n", timestamp) < 0) {
        fprintf(stderr, "Error writing to %s: %s\n", LOG_FILE, strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* LED blink                                                             */
/* ------------------------------------------------------------------ */
static void blink_led(void)
{
    if (gpioWrite(LED_PIN, 1) < 0) {
        fprintf(stderr, "Warning: gpioWrite(LED on) failed\n");
        return;
    }
    gpioDelay(LED_ON_US);
    if (gpioWrite(LED_PIN, 0) < 0) {
        fprintf(stderr, "Warning: gpioWrite(LED off) failed\n");
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure sensor pin as input ---- */
    if (gpioSetMode(SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode(SENSOR_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Configure LED pin as output ---- */
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(LED_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Ensure LED is off ---- */
    if (gpioWrite(LED_PIN, 0) < 0) {
        fprintf(stderr, "gpioWrite(LED off) initial failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Proximity sensor monitoring started.\n");
    printf("  Sensor : GPIO %d (BCM)\n", SENSOR_PIN);
    printf("  LED    : GPIO %d (BCM)\n", LED_PIN);
    printf("  Log    : %s\n", LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    /* ---- Main polling loop ---- */
    int last_state = 1;   /* assume no object at startup (HIGH) */
    int first_sample = 1;

    while (g_running) {
        int level = gpioRead(SENSOR_PIN);
        if (level < 0) {
            fprintf(stderr, "gpioRead(SENSOR_PIN) failed\n");
            break;
        }

        /* Falling edge: HIGH → LOW  → object detected */
        if (first_sample || level == 0 && last_state == 1) {
            char timestamp[32];
            if (get_iso8601_timestamp(timestamp, sizeof(timestamp)) == 0) {
                if (log_event(timestamp) == 0) {
                    printf("%s Object detected\n", timestamp);
                    blink_led();
                } else {
                    fprintf(stderr, "Failed to log event.\n");
                }
            } else {
                fprintf(stderr, "Failed to get timestamp.\n");
            }
        }

        last_state = level;
        first_sample = 0;
        gpioDelay(POLL_DELAY_US);
    }

    /* ---- Cleanup ---- */
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

