#define SI1145_REG_MEAS_RATE0 0x08
#define SI1145_REG_MEAS_RATE1 0x09
#define SI1145_REG_ALS_VIS_DATA0 0x22
#define SI1145_REG_ALS_VIS_DATA1 0x23
#define SI1145_REG_PS1_DATA0 0x26
#define SI1145_REG_PS1_DATA1 0x27

#define SI1145_PART_ID 0x45
#define SI1145_HW_KEY_VAL 0x17
#define SI1145_MEAS_RATE_1HZ 0x0A
#define SI1145_MEAS_RATE_0HZ 0x00

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int write_reg(uint8_t reg, uint8_t val) {
    int rc = i2cWriteByteData(i2c_handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%02X (rc=%d)\n", val, reg, rc);
        return -1;
    }
    return 0;
}

static int read_reg(uint8_t reg, uint8_t *val) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X (rc=%d)\n", reg, rc);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int read_word(uint8_t reg_low, uint16_t *val) {
    uint8_t lo, hi;
    if (read_reg(reg_low, &lo) < 0) return -1;
    if (read_reg(reg_low + 1, &hi) < 0) return -1;
    *val = (uint16_t)((hi << 8) | lo);
    return 0;
}

static int init_si1145(void) {
    uint8_t part_id;
    if (read_reg(SI1145_REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "Cannot read PART_ID — sensor may be absent\n");
        return -1;
    }
    if (part_id != SI1145_PART_ID) {
        fprintf(stderr, "Unexpected PART_ID 0x%02X (expected 0x%02X)\n", part_id, SI1145_PART_ID);
        return -1;
    }
    printf("Si1145 detected (PART_ID=0x%02X)\n", part_id);

    if (write_reg(SI1145_REG_HW_KEY, SI1145_HW_KEY_VAL) < 0) return -1;
    if (write_reg(SI1145_REG_MEAS_RATE0, SI1145_MEAS_RATE_1HZ) < 0) return -1;
    if (write_reg(SI1145_REG_MEAS_RATE1, SI1145_MEAS_RATE_1HZ) < 0) return -1;

    return 0;
}

static int read_proximity(uint16_t *prox) {
    return read_word(SI1145_REG_PS1_DATA0, prox);
}

static int read_ambient_light(uint16_t *light) {
    return read_word(SI1145_REG_ALS_VIS_DATA0, light);
}

static void log_data(uint16_t prox, uint16_t light) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(log_file, "%s,%u,%u\n", timestamp, prox, light);
    fflush(log_file);
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X (rc=%d)\n", I2C_BUS, SI1145_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_si1145() < 0) {
        fprintf(stderr, "Si1145 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s'\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    printf("Logging Si1145 data to %s — press Ctrl+C to stop\n", LOG_FILE);

    while (!terminate) {
        uint16_t prox, light;

        if (read_proximity(&prox) < 0 || read_ambient_light(&light) < 0) {
            fprintf(stderr, "I2C read error — continuing\n");
        } else {
            log_data(prox, light);
            printf("Proximity: %u, Ambient Light: %u\n", prox, light);
        }

        sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

