/*
 * HC-SR04 ultrasonic distance measurement on Raspberry Pi Zero W
 *
 * Wiring:
 *   HC-SR04 TRIGGER -> GPIO 17 (BCM)
 *   HC-SR04 ECHO    -> GPIO 27 (BCM) via 1k/2k voltage divider (5 V -> 3.3 V)
 *   HC-SR04 VCC     -> 5 V (external supply, not the Pi 3.3 V pin)
 *   HC-SR04 GND     -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o hcsr04 hcsr04.c
 */

#define _POSIX_C_SOURCE 200809L

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <math.h>

#define TRIGGER_PIN      17
#define ECHO_PIN         27

#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US  30000   /* 30 ms max echo wait */
#define LOOP_INTERVAL_S  60      /* seconds between readings */
#define MIN_DISTANCE_CM  2.0
#define MAX_DISTANCE_CM  400.0
#define BELOW_WATER_CM   15.0
#define LOG_FILE         "distance_log.txt"

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Measure distance in centimetres.
 * Returns >= 0 on success, -1.0 on timeout / error.
 */
static double measure_distance(void)
{
    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "gpioWrite(trigger, 0) failed: %s\n", strerror(errno));
        return -1.0;
    }
    usleep(5);

    /* 10 µs trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "gpioWrite(trigger, 1) failed: %s\n", strerror(errno));
        return -1.0;
    }
    usleep(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "gpioWrite(trigger, 0) failed: %s\n", strerror(errno));
        return -1.0;
    }

    /* Wait for echo rising edge (timeout if sensor absent) */
    uint32_t start_tick = 0;
    uint32_t deadline = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if (gpioTick() >= deadline) {
            fprintf(stderr, "Timeout waiting for echo rising edge (sensor absent?)\n");
            return -1.0;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge (timeout if echo stuck high) */
    deadline = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if (gpioTick() >= deadline) {
            fprintf(stderr, "Timeout waiting for echo falling edge\n");
            return -1.0;
        }
    }
    uint32_t end_tick = gpioTick();

    uint32_t pulse_us = end_tick - start_tick;
    if (pulse_us == 0) {
        fprintf(stderr, "Invalid pulse width: %u\n", pulse_us);
        return -1.0;
    }

    /* Speed of sound ~343 m/s => distance = (pulse_us * 343) / 2 / 1e6 */
    double distance_cm = (double)pulse_us * 0.0343 / 2.0;

    if (distance_cm < MIN_DISTANCE_CM || distance_cm > MAX_DISTANCE_CM) {
        fprintf(stderr, "Distance out of range: %.2f cm\n", distance_cm);
        return -1.0;
    }

    return distance_cm;
}

static void log_distance(FILE *fp, double distance_cm)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    if (t == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);

    if (distance_cm < 0.0) {
        fprintf(fp, "%s, ERROR\n", ts);
    } else {
        fprintf(fp, "%s, %.2f cm\n", ts, distance_cm);
    }
    fflush(fp);
}

int main(void)
{
    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open log file */
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise() failed\n");
        fclose(fp);
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(TRIGGER_PIN) failed\n");
        goto cleanup;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode(ECHO_PIN) failed\n");
        goto cleanup;
    }

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "gpioWrite(TRIGGER_PIN, 0) failed\n");
        goto cleanup;
    }
    usleep(100000); /* 100 ms settle */

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (g_running) {
        double distance = measure_distance();

        if (distance < 0.0) {
            fprintf(stderr, "Measurement failed; skipping log entry.\n");
        } else {
            log_distance(fp, distance);

            if (distance < BELOW_WATER_CM) {
                fprintf(stderr, "Time to water the plant!\n");
            }
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < LOOP_INTERVAL_S && g_running; i++) {
            sleep(1);
        }
    }

cleanup:
    printf("\nShutting down...\n");
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    fclose(fp);
    return EXIT_SUCCESS;
}

