 * APDS-9960 Proximity & Color Logger for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   APDS-9960 SDA  -> GPIO 2  (I2C bus 1 SDA)
 *   APDS-9960 SCL  -> GPIO 3  (I2C bus 1 SCL)
 *   APDS-9960 VDD  -> 3.3 V
 *   APDS-9960 GND  -> GND
 *   APDS-9960 ADDR -> GND  (I2C address 0x69)
 *
 * Build:  gcc -O2 -Wall -o color_proximity color_proximity.c -lpigpio -lrt
 * Run:    sudo ./color_proximity
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define APDS9960_I2C_ADDR  0x69
#define APDS9960_BUS       1

/* APDS-9960 register addresses */
#define APDS9960_ENABLE    0x80
#define APDS9960_ATIME     0x81
#define APDS9960_WTIME     0x83
#define APDS9960_CONFIG    0x8D
#define APDS9960_ID        0x92
#define APDS9960_STATUS    0x93
#define APDS9960_CDATAL    0x94
#define APDS9960_CDATAH    0x95
#define APDS9960_RDATAL    0x96
#define APDS9960_RDATAH    0x97
#define APDS9960_GDATAL    0x98
#define APDS9960_GDATAH    0x99
#define APDS9960_BDATAL    0x9A
#define APDS9960_BDATAH    0x9B
#define APDS9960_PDATA0    0x9C
#define APDS9960_PDATA1    0x9D

#define APDS9960_ENABLE_PON  0x01
#define APDS9960_ENABLE_AEN  0x02
#define APDS9960_ENABLE_PEN  0x04
#define APDS9960_ENABLE_WEN  0x08
#define APDS9960_ENABLE_REN  0x10
#define APDS9960_ENABLE_GEN  0x20
#define APDS9960_ENABLE_BEN  0x40
#define APDS9960_ENABLE_PSR  0x80

#define PROXIMITY_THRESHOLD 200
#define LOG_FILE           "color_proximity_log.csv"
#define POLL_DELAY_US      100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int apds_write_byte(int handle, uint8_t reg, uint8_t value)
{
    char buf[2] = { (char)reg, (char)value };
    return i2cWriteDevice(handle, buf, 2);
}

static int apds_read_byte(int handle, uint8_t reg, uint8_t *out)
{
    char reg_buf[1] = { (char)reg };
    if (i2cWriteDevice(handle, reg_buf, 1) < 0)
        return -1;
    char data[1];
    if (i2cReadDevice(handle, data, 1) != 1)
        return -1;
    *out = (uint8_t)data[0];
    return 0;
}

static int apds_read_word(int handle, uint8_t reg, uint16_t *out)
{
    char reg_buf[1] = { (char)reg };
    if (i2cWriteDevice(handle, reg_buf, 1) < 0)
        return -1;
    char data[2];
    if (i2cReadDevice(handle, data, 2) != 2)
        return -1;
    *out = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor initialization                                               */
/* ------------------------------------------------------------------ */
static int apds9960_init(int handle)
{
    uint8_t id = 0;
    if (apds_read_byte(handle, APDS9960_ID, &id) < 0) {
        fprintf(stderr, "Error: cannot read APDS9960 ID register.\n");
        return -1;
    }
    if (id != 0x53) {
        fprintf(stderr, "Error: unexpected APDS9960 ID 0x%02X (expected 0x53).\n", id);
        return -1;
    }

    /* Power on */
    if (apds_write_byte(handle, APDS9960_ENABLE, APDS9960_ENABLE_PON) < 0) {
        fprintf(stderr, "Error: cannot power on APDS9960.\n");
        return -1;
    }
    gpioDelay(10000);  /* 10 ms power-up delay */

    /* Set integration time (ATIME) ~ 100 ms */
    if (apds_write_byte(handle, APDS9960_ATIME, 0x0A) < 0) {
        fprintf(stderr, "Error: cannot set ATIME.\n");
        return -1;
    }

    /* Set conversion time (WTIME) ~ 100 ms */
    if (apds_write_byte(handle, APDS9960_WTIME, 0x0A) < 0) {
        fprintf(stderr, "Error: cannot set WTIME.\n");
        return -1;
    }

    /* Configure: enable RGBC ADC, proximity sensing */
    if (apds_write_byte(handle, APDS9960_CONFIG, APDS9960_ENABLE_REN | APDS9960_ENABLE_GEN | APDS9960_ENABLE_BEN | APDS9960_ENABLE_PSR) < 0) {
        fprintf(stderr, "Error: cannot configure APDS9960.\n");
        return -1;
    }

    /* Wait for first conversion to complete */
    gpioDelay(150000);  /* 150 ms */

    return 0;
}

/* ------------------------------------------------------------------ */
/* Data acquisition                                                    */
/* ------------------------------------------------------------------ */
static int apds9960_read_data(int handle, uint16_t *r, uint16_t *g,
                              uint16_t *b, uint16_t *p)
{
    if (apds_read_word(handle, APDS9960_CDATAL, r) < 0) return -1;
    if (apds_read_word(handle, APDS9960_CDATAH, g) < 0) return -1;
    if (apds_read_word(handle, APDS9960_RDATAL, b) < 0) return -1;
    if (apds_read_word(handle, APDS9960_RDATAH, r) < 0) return -1;
    if (apds_read_word(handle, APDS9960_GDATAH, g) < 0) return -1;
    if (apds_read_word(handle, APDS9960_BDATAH, b) < 0) return -1;
    if (apds_read_word(handle, APDS9960_PDATA0, p) < 0) return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* CSV logging                                                         */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, uint16_t r, uint16_t g, uint16_t b, uint16_t p)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed.\n");
        return -1;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%u,%u,%u,%u\n", ts, r, g, b, p) < 0) {
        fprintf(stderr, "Error: fprintf to CSV failed.\n");
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "Error: fflush failed.\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(APDS9960_BUS, APDS9960_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d).\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (apds9960_init(g_i2c_handle) < 0) {
        fprintf(stderr, "Error: APDS9960 initialisation failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("fopen");
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(fp, "# timestamp,r,g,b,p\n");
    fflush(fp);

    printf("Logging to %s. Press Ctrl+C to stop.\n", LOG_FILE);

    while (g_running) {
        uint16_t r, g, b, p;
        if (apds9960_read_data(g_i2c_handle, &r, &g, &b, &p) == 0) {
            if (p > PROXIMITY_THRESHOLD) {
                if (log_data(fp, r, g, b, p) == 0) {
                    printf("Proximity %u > %d: R=%u G=%u B=%u\n", p, PROXIMITY_THRESHOLD, r, g, b);
                } else {
                    fprintf(stderr, "Warning: log_data failed.\n");
                }
            }
        } else {
            fprintf(stderr, "Warning: I2C read error, re-initialising sensor...\n");
            i2cClose(g_i2c_handle);
            g_i2c_handle = -1;
            gpioDelay(100000);
            g_i2c_handle = i2cOpen(APDS9960_BUS, APDS9960_I2C_ADDR, 0);
            if (g_i2c_handle < 0) {
                fprintf(stderr, "Error: i2cOpen failed after recovery.\n");
                break;
            }
            if (apds9960_init(g_i2c_handle) < 0) {
                fprintf(stderr, "Error: APDS9960 re-initialisation failed.\n");
                break;
            }
        }
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    fclose(fp);
    cleanup();
    return EXIT_SUCCESS;
}

