#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define CSV_FILE       "heartrate.csv"
#define SAMPLE_PERIOD  100000   /* microseconds (100 ms) */
#define SI1182_ADDR    0x53

/* Si1182 proximity data registers (16-bit, big-endian on the bus) */
#define SI1182_REG_PROX_DATA0  0x00
#define SI1182_REG_PROX_DATA1  0x01
#define SI1182_REG_PROX_DATA2  0x02
#define SI1182_REG_PROX_DATA3  0x03

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* Write a 16-bit value to a 16-bit register (big-endian on the bus). */
static int i2c_write_reg16(int fd, uint8_t reg, uint16_t value)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(value >> 8);
    buf[2] = (uint8_t)(value & 0xFF);
    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write_reg16(0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a 16-bit value from a 16-bit register (big-endian on the bus). */
static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t reg_buf = reg;
    if (write(fd, &reg_buf, 1) != 1) {
        fprintf(stderr, "i2c_read_reg16 write(0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t data[2];
    if (read(fd, data, 2) != 2) {
        fprintf(stderr, "i2c_read_reg16 read(0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    *out = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

/* Read the 4 proximity data registers and return the sum as beats per minute. */
static int read_proximity(int fd, int *bpm)
{
    uint16_t p0, p1, p2, p3;
    if (i2c_read_reg16(fd, SI1182_REG_PROX_DATA0, &p0) < 0) return -1;
    if (i2c_read_reg16(fd, SI1182_REG_PROX_DATA1, &p1) < 0) return -1;
    if (i2c_read_reg16(fd, SI1182_REG_PROX_DATA2, &p2) < 0) return -1;
    if (i2c_read_reg16(fd, SI1182_REG_PROX_DATA3, &p3) < 0) return -1;
    int sum = (p0 + p1 + p2 + p3) / 4;
    *bpm = sum;
    return 0;
}

static void get_timestamp(char *buf, size_t len)
{
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tm);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SI1182_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n", SI1182_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    FILE *csv = fopen(CSV_FILE, "a");
    if (!csv) {
        fprintf(stderr, "fopen(%s): %s\n", CSV_FILE, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    while (running) {
        int bpm;
        if (read_proximity(fd, &bpm) < 0) {
            fprintf(stderr, "Warning: proximity read failed, skipping sample\n");
        } else {
            char ts[32];
            get_timestamp(ts, sizeof(ts));
            if (fprintf(csv, "%s,%d\n", ts, bpm) < 0) {
                fprintf(stderr, "fprintf: %s\n", strerror(errno));
            } else {
                fflush(csv);
            }
        }
        usleep(SAMPLE_PERIOD);
    }

    fclose(csv);
    close(fd);
    return EXIT_SUCCESS;
}

