/*
 * Raspberry Pi 4 Model B – TDK CH101 ultrasonic distance sensor
 * I2C bus 1, address 0x20
 * Samples every 200 ms, logs to distance_log.txt with timestamps
 * and exits cleanly on SIGINT.
 *
 * Build:  gcc -O2 -Wall -Wextra -o ch101_chrono ch101_chrono.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define CH101_ADDR     0x20
#define LOG_FILE       "distance_log.txt"
#define SAMPLE_MS      200
#define TRIGGER_MS     50

/* CH101 register addresses */
#define CH101_REG_CTRL  0x00
#define CH101_REG_DIST  0x04

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* Write one byte to a CH101 register; returns 0 on success, -1 on error. */
static int ch101_write_reg(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read one byte from a CH101 register; returns 0 on success, -1 on error. */
static int ch101_read_reg(int fd, uint8_t reg, uint8_t *out)
{
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    n = read(fd, out, 1);
    if (n != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Trigger a measurement and read the 16-bit distance result. */
static int ch101_read_distance(int fd, uint16_t *distance_mm)
{
    uint8_t ctrl = 0x01;   /* start measurement */
    if (ch101_write_reg(fd, CH101_REG_CTRL, ctrl) != 0)
        return -1;

    /* Wait for conversion to complete (poll bit 0 of REG_CTRL) */
    uint8_t ctrl2 = 0x00;
    for (int i = 0; i < 20; i++) {
        if (ch101_read_reg(fd, CH101_REG_CTRL, &ctrl2) != 0)
            return -1;
        if (ctrl2 & 0x01)
            break;
        usleep(2000);
    }
    if (ctrl2 & 0x01) {
        fprintf(stderr, "CH101 conversion timeout\n");
        return -1;
    }

    uint8_t dist = 0;
    if (ch101_read_reg(fd, CH101_REG_DIST, &dist) != 0)
        return -1;

    *distance_mm = (uint16_t)dist;
    return 0;
}

static void get_timestamp(char *buf, size_t len)
{
    time_t t = time(NULL);
    struct tm tmv;
    localtime_r(&t, &tmv);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tmv);
}

int main(void)
{
    int fd = -1;
    FILE *log = NULL;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, CH101_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                CH101_ADDR, strerror(errno));
        goto cleanup;
    }

    log = fopen(LOG_FILE, "a");
    if (!log) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    printf("CH101 distance chronometer started (I2C 0x%02X on %s).\n",
           CH101_ADDR, I2C_BUS);
    printf("Press Ctrl-C to stop.\n");

    while (g_running) {
        uint16_t dist = 0;
        char ts[32];

        get_timestamp(ts, sizeof(ts));

        if (ch101_read_distance(fd, &dist) == 0) {
            fprintf(log, "%s, %u\n", ts, dist);
            fflush(log);
            printf("%s, %u mm\n", ts, dist);
        } else {
            fprintf(stderr, "%s, I2C read error – skipping sample\n", ts);
        }

        usleep(SAMPLE_MS * 1000);
    }

    printf("\nShutting down cleanly.\n");
    rc = EXIT_SUCCESS;

cleanup:
    if (log) fclose(log);
    if (fd >= 0) close(fd);
    return rc;
}

