/*
 * Raspberry Pi Zero W – TDK InvenSense ICU‑20201 ultrasonic ToF sensor
 *
 * Reads distance from the ICU‑20201 on I2C bus 1 (address 0x29),
 * drives an LED on GPIO 17 (BCM) when distance < 20 cm, and logs
 * each reading with an ISO-8601 timestamp to distance_log.txt.
 *
 * Build:  gcc -O2 -Wall -Wextra -o distance_monitor distance_monitor.c -lpigpio -lrt
 * Run:    sudo ./distance_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS          1
#define I2C_ADDR         0x29
#define LED_PIN          17
#define DISTANCE_THRESHOLD_CM 20.0f
#define SAMPLE_PERIOD_US  100000   /* 100 ms */
#define LOG_FILE         "distance_log.txt"

/* ICU‑20201 register addresses */
#define REG_DISTANCE_LSB   0x00
#define REG_DISTANCE_MSB   0x01
#define REG_RANGE_LSB      0x02
#define REG_RANGE_MSB      0x03
#define REG_CONFIG        0x0A
#define REG_INT_STATUS    0x0B
#define REG_INT_ENABLE    0x0C
#define REG_HW_KEY        0x0F

/* Config: 50 ms measurement cycle, 100 Hz update rate, no interrupt */
#define CONFIG_VALUE      0x0000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int handle, uint8_t reg, uint8_t value)
{
    char buf[2] = { (char)reg, (char)value };
    if (i2cWriteDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "i2cWriteDevice(reg=0x%02X, val=0x%02X) failed: %s\n",
                reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int handle, uint8_t reg, uint8_t *out)
{
    char cmd = (char)reg;
    if (i2cWriteDevice(handle, &cmd, 1) != 1) {
        fprintf(stderr, "i2cWriteDevice(reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    char data;
    if (i2cReadDevice(handle, &data, 1) != 1) {
        fprintf(stderr, "i2cReadDevice(reg=0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = (uint8_t)data;
    return 0;
}

static int i2c_read_reg16(int handle, uint8_t reg, uint16_t *out)
{
    char cmd = (char)reg;
    if (i2cWriteDevice(handle, &cmd, 1) != 1) {
        fprintf(stderr, "i2cWriteDevice(reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    char data[2];
    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "i2cReadDevice(reg=0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = ((uint16_t)(uint8_t)data[1] << 8) | (uint8_t)data[0];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor initialization                                               */
/* ------------------------------------------------------------------ */
static int sensor_init(int handle)
{
    /* Software reset via HW_KEY write (0x00) */
    if (i2c_write_reg8(handle, REG_HW_KEY, 0x00) != 0)
        return -1;
    gpioDelay(10000); /* 10 ms settle after reset */

    /* Configure: 50 ms measurement cycle, 100 Hz update rate, no interrupt */
    if (i2c_write_reg8(handle, REG_CONFIG, CONFIG_VALUE) != 0)
        return -1;

    /* Clear any pending interrupt */
    if (i2c_read_reg8(handle, REG_INT_STATUS, NULL) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Distance measurement                                               */
/* ------------------------------------------------------------------ */
static int read_distance_cm(int handle, float *distance_cm)
{
    uint16_t raw;
    if (i2c_read_reg16(handle, REG_DISTANCE_LSB, &raw) != 0)
        return -1;

    /* 16-bit raw value; ICU‑20201 distance is 0–65535 */
    *distance_cm = (float)raw / 256.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_distance(float distance_cm)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(g_log_file, "%s, Distance: %.2f cm\n", timestamp, distance_cm) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- LED pin setup --- */
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    /* --- I2C open --- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Sensor init --- */
    if (sensor_init(g_i2c_handle) != 0) {
        fprintf(stderr, "Sensor initialization failed (sensor may be absent or bus error)\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Log file --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Signals --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Distance monitoring started. Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        float distance_cm;
        if (read_distance_cm(g_i2c_handle, &distance_cm) != 0) {
            fprintf(stderr, "Distance read failed; continuing.\n");
        } else {
            int led_state = (distance_cm < DISTANCE_THRESHOLD_CM) ? 1 : 0;
            gpioWrite(LED_PIN, led_state);

            if (log_distance(distance_cm) != 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
