    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %s\n",
                reg, val, strerror(errno));
    }
    return rc;
}

static int read_reg(int handle, uint8_t reg)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %s\n",
                reg, strerror(errno));
    }
    return rc;
}

static int init_icu20201(int handle)
{
    int who = read_reg(handle, ICU20201_WHO_AM_I);
    if (who < 0) {
        fprintf(stderr, "Cannot read WHO_AM_I — sensor absent or bus error.\n");
        return -1;
    }
    if (who != ICU20201_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X.\n",
                who, ICU20201_WHO_AM_I_VAL);
        return -1;
    }

    if (write_reg(handle, ICU20201_CTRL_REG1, ICU20201_CTRL_REG1_VAL) < 0)
        return -1;
    if (write_reg(handle, ICU20201_CTRL_REG2, ICU20201_CTRL_REG2_VAL) < 0)
        return -1;

    return 0;
}

static int read_distance_mm(int handle)
{
    /* Trigger a measurement by writing RANGE_REG = 1 */
    if (write_reg(handle, ICU20201_RANGE_REG, ICU20201_RANGE_REG_VAL) < 0)
        return -1;

    /* Wait for measurement to complete (TDO goes low) */
    for (int i = 0; i < 20; i++) {
        int status = read_reg(handle, ICU20201_RESULT_REG);
        if (status < 0)
            return -1;
        if (status == 0)
            return 0;  /* measurement ready */
        gpioDelay(1000); /* 1 ms */
    }

    fprintf(stderr, "Measurement timeout.\n");
    return -1;
}

static void log_reading(int distance_mm)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d  Distance: %d mm\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, distance_mm);
    } else {
        fprintf(fp, "[timestamp error]  Distance: %d mm\n", distance_mm);
    }

    fclose(fp);
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioSetMode(LED_GPIO, PI_INPUT);
    gpioTerminate();
}

int main(int argc, char *argv[])
{
    int threshold_mm = DEFAULT_THRESHOLD_MM;

    if (argc > 1) {
        threshold_mm = atoi(argv[1]);
        if (threshold_mm <= 0) {
            fprintf(stderr, "Threshold must be a positive integer.\n");
            return EXIT_FAILURE;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, 0, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (bus %d): %s\n",
                I2C_BUS, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_icu20201(g_i2c_handle) < 0) {
        fprintf(stderr, "ICU-20201 initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ICU-20201 TDOF reader started. Threshold: %d mm. Press Ctrl+C to exit.\n",
           threshold_mm);

    while (g_running) {
        int distance = read_distance_mm(g_i2c_handle);

        if (distance < 0) {
            fprintf(stderr, "Read error — continuing.\n");
        } else {
            log_reading(distance);

            if (distance < threshold_mm) {
                gpioWrite(LED_GPIO, 1);
            } else {
                gpioWrite(LED_GPIO, 0);
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

