/*
 * Intrusion detection using an Omron B5L-LD50-07050 3D TOF sensor.
 *
 * Hardware:
 *   - Raspberry Pi Zero W
 *   - Omron B5L-LD50-07050 3D TOF sensor (I2C address 0x28)
 *     VDD  -> 3.3 V
 *     GND  -> GND
 *     SDA  -> GPIO2 (pin 3, I2C bus 1)
 *     SCL  -> GPIO3 (pin 5, I2C bus 1)
 *
 * The sensor returns a 15-byte frame after a measurement request.
 * Byte 0 = 0x01 (header)
 * Bytes 1..7 = 0x00 (padding)
 * Bytes 8..9 = 0x00 (padding)
 * Byte 10 = 0x00 (padding)
 * Bytes 11..12 = distance (big-endian, mm)
 * Bytes 13..15 = 0xFF (padding)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o intrusion intrusion.c
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define I2C_ADDR       0x28
#define LOG_FILE       "intrusion_log.txt"
#define THRESHOLD_MM   1000
#define NUM_SAMPLES    10
#define SAMPLE_DELAY_MS 100
#define MEAS_DELAY_MS  10
#define MEAS_CMD_LEN   4
#define RESP_LEN       15

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handler(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int fd, const uint8_t *cmd, size_t len)
{
    if (write(fd, cmd, len) != (ssize_t)len) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_data(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "I2C read failed: expected %zu bytes, got %zd (%s)\n",
                len, n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor read                                                         */
/* ------------------------------------------------------------------ */
/*
 * Returns 0 on success and fills *distance_mm.
 * Returns -1 on any I2C error.
 */
static int read_sensor_distance(int fd, int *distance_mm)
{
    uint8_t cmd[MEAS_CMD_LEN] = {
        0x01, 0x00, 0x00, 0x00
    };
    uint8_t resp[RESP_LEN];

    if (i2c_write_cmd(fd, cmd, MEAS_CMD_LEN) == -1)
        return -1;

    usleep(MEAS_DELAY_MS * 1000);

    if (i2c_read_data(fd, resp, RESP_LEN) == -1)
        return -1;

    /* Byte 0 must be 0x01 (header). */
    if (resp[0] != 0x01) {
        fprintf(stderr, "Sensor response header mismatch: 0x%02X (expected 0x01)\n",
                resp[0]);
        return -1;
    }

    /* Distance is in bytes 11 and 12 (big-endian, mm). */
    *distance_mm = ((int)resp[11] << 8) | resp[12];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_intrusion(int fd, int avg_distance_mm)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Average Distance: %d mm\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, avg_distance_mm);

    if (fclose(fp) != 0)
        fprintf(stderr, "Warning: fclose(%s) failed: %s\n",
                LOG_FILE, strerror(errno));
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int distances[NUM_SAMPLES];
    int idx = 0;
    int count = 0;
    long sum = 0;
    int rc = EXIT_FAILURE;

    if (install_signal_handler() == -1)
        goto cleanup;

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd == -1) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        goto cleanup;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, I2C_ADDR) == -1) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                I2C_ADDR, strerror(errno));
        goto cleanup;
    }

    printf("Intrusion detection started. Press Ctrl-C to exit.\n");

    while (g_running) {
        for (int i = 0; i < NUM_SAMPLES && g_running; i++) {
            int d;
            if (read_sensor_distance(g_i2c_fd, &d) == -1) {
                fprintf(stderr, "Sensor read failed; continuing.\n");
                continue;
            }
            distances[idx] = d;
            sum += d;
            idx = (idx + 1) % NUM_SAMPLES;
            if (idx == 0)
                count++;
            usleep(SAMPLE_DELAY_MS * 1000);
        }

        if (count == NUM_SAMPLES) {
            int avg = (sum / NUM_SAMPLES);
            if (avg < THRESHOLD_MM) {
                printf("Average distance: %d mm < %d mm — potential intrusion!\n",
                       avg, THRESHOLD_MM);
                log_intrusion(g_i2c_fd, avg);
            }
        }
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (g_i2c_fd != -1) {
        if (close(g_i2c_fd) == -1)
            fprintf(stderr, "Warning: close(%s) failed: %s\n",
                    I2C_BUS, strerror(errno));
        g_i2c_fd = -1;
    }
    return rc;
}

