code:
/*
 * VL53L0X Time-of-Flight distance sensor reader for Raspberry Pi 3 Model B+
 * Uses pigpio for I2C communication.
 *
 * Wiring:
 *   VL53L0X SDA -> GPIO 2 (I2C bus 1 SDA)
 *   VL53L0X SCL -> GPIO 3 (I2C bus 1 SCL)
 *   VL53L0X VDD -> 3.3 V
 *   VL53L0X GND -> GND
 *
 * Build: gcc -Wall -Wextra -O2 -o vl53l0x_reader vl53l0x_reader.c -lpigpio -lrt
 * Run:   sudo ./vl53l0x_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- VL53L0X register addresses ---- */
#define VL53L0X_REG_IDENTIFICATION_MODEL_ID   0x010F
#define VL53L0X_REG_SYSTEM_MODE_START         0x0000
#define VL53L0X_REG_RESULT_INTERRUPT_STATUS   0x0014
#define VL53L0X_REG_RESULT_DISTANCE           0x0014
#define VL53L0X_REG_SYSTEM_INTERRUPT_CLEAR    0x0016

#define VL53L0X_MODEL_ID_EXPECTED             0xEA
#define VL53L0X_I2C_BUS                        1
#define VL53L0X_I2C_ADDR                        0x60
#define VL53L0X_SYSTEM_MODE_START_VALUE        0x01
#define VL53L0X_RESULT_INTERRUPT_STATUS_MASK  0x01
#define VL53L0X_RESULT_INTERRUPT_CLEAR_VALUE   0x01
#define VL53L0X_DISTANCE_REG_MASK              0x00FF
#define VL53L0X_DISTANCE_REG_RESULT            0x00FF
#define VL53L0X_RESULT_INTERRUPT_STATUS_TIMEOUT_MS 100

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;

    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "I2C write to reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int handle, uint16_t reg, uint8_t *value)
{
    char reg_buf[2];
    char data_buf[1];

    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, reg_buf, 2) != 2) {
        fprintf(stderr, "I2C write (reg select 0x%04X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (i2cReadDevice(handle, data_buf, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *value = (uint8_t)data_buf[0];
    return 0;
}

static int i2c_read_reg16(int handle, uint16_t reg, uint16_t *value)
{
    char reg_buf[2];
    char data_buf[2];

    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, reg_buf, 2) != 2) {
        fprintf(stderr, "I2C write (reg select 0x%04X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (i2cReadDevice(handle, data_buf, 2) != 2) {
        fprintf(stderr, "I2C read 16-bit from reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *value = ((uint8_t)data_buf[0] << 8) | (uint8_t)data_buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* VL53L0X helpers                                                     */
/* ------------------------------------------------------------------ */
static int vl53l0x_init(int handle)
{
    uint8_t model_id = 0;

    if (i2c_read_reg8(handle, VL53L0X_REG_IDENTIFICATION_MODEL_ID,
                       &model_id) != 0) {
        fprintf(stderr, "Failed to read model ID register.\n");
        return -1;
    }

    if (model_id != VL53L0X_MODEL_ID_EXPECTED) {
        fprintf(stderr,
                "Unexpected model ID 0x%02X (expected 0x%02X). "
                "Sensor not present or wrong device.\n",
                model_id, VL53L0X_MODEL_ID_EXPECTED);
        return -1;
    }

    printf("VL53L0X detected (model ID 0x%02X).\n", model_id);

    if (i2c_write_reg8(handle, VL53L0X_REG_SYSTEM_MODE_START,
                        VL53L0X_SYSTEM_MODE_START_VALUE) != 0) {
        fprintf(stderr, "Failed to start VL53L0X.\n");
        return -1;
    }

    return 0;
}

static int vl53l0x_read_distance(int handle, uint16_t *distance_mm)
{
    uint8_t status = 0;
    uint16_t dist = 0;

    /* Poll RESULT_INTERRUPT_STATUS for up to 100 ms */
    for (int i = 0; i < VL53L0X_RESULT_INTERRUPT_STATUS_TIMEOUT_MS; i++) {
