    if (i2c_read_reg16(handle, VL53L0X_REG_RESULT_DISTANCE,
                        &dist) != 0) {
        return -1;
    }

    /* Clear the interrupt so the next measurement can be triggered */
    if (i2c_write_reg8(handle, VL53L0X_REG_SYSTEM_INTERRUPT_CLEAR,
                        VL53L0X_RESULT_INTERRUPT_CLEAR_VALUE) != 0) {
        return -1;
    }

    *distance_mm = dist;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
