    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %s\n",
                VL53L0X_I2C_BUS, VL53L0X_I2C_ADDR, strerror(errno));
        gpioTerminate();
