    if (vl53l0x_init(g_i2c_handle) != 0) {
        fprintf(stderr, "VL53L0X initialization failed.\n");
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("VL53L0X initialized. Reading distance every 500 ms...\n");

    while (g_running) {
        uint16_t distance = 0;

        if (vl53l0x_read_distance(g_i2c_handle, &distance) == 0) {
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[80];

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp),
