/*
 * Si1182 Proximity Sensor Reader for Raspberry Pi 3 Model B+
 * Bus: I2C-1 (GPIO2 = SDA, GPIO3 = SCL)
 * Reads 16-bit proximity data every 500 ms and prints it to stdout.
 *
 * Build:  gcc -O2 -Wall -Wextra -o si1182_prox si1182_prox.c
 * Run:    ./si1182_prox
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- Si1182 register map (per datasheet) ---- */
#define SI1182_I2C_ADDR        0x60
#define SI1182_REG_PART_ID     0x00
#define SI1182_REG_HW_KEY      0x07
#define SI1182_REG_MEAS_RATE0  0x08
#define SI1182_REG_MEAS_RATE1  0x09
#define SI1182_REG_PS1_DATA0   0x22
#define SI1182_REG_PS1_DATA1   0x23

#define SI1182_PART_ID         0x82
#define SI1182_HW_KEY_VAL      0x17

/* ---- I2C helpers ---- */
static int i2c_write_byte(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int fd, uint8_t reg, uint8_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = val;
    return 0;
}

static int i2c_read_word(int fd, uint8_t reg_lo, uint16_t *out)
{
    uint8_t lo, hi;
    if (i2c_read_byte(fd, reg_lo, &lo) < 0) return -1;
    if (i2c_read_byte(fd, reg_lo + 1, &hi) < 0) return -1;
    *out = (uint16_t)((hi << 8) | lo);
    return 0;
}

/* ---- Si1182 driver ---- */
typedef struct {
    int fd;
    bool initialized;
} Si1182;

static int si1182_init(Si1182 *s)
{
    s->fd = -1;
    s->initialized = false;

    s->fd = open("/dev/i2c-1", O_RDWR);
    if (s->fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(s->fd, I2C_SLAVE, SI1182_I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                SI1182_I2C_ADDR, strerror(errno));
        close(s->fd);
        s->fd = -1;
        return -1;
    }

    /* Verify sensor presence by reading PART_ID */
    uint8_t part_id;
    if (i2c_read_byte(s->fd, SI1182_REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "Si1182 not responding at 0x%02X (sensor absent or bus error)\n",
                SI1182_I2C_ADDR);
        close(s->fd);
        s->fd = -1;
        return -1;
    }
    if (part_id != SI1182_PART_ID) {
        fprintf(stderr, "Unexpected PART_ID 0x%02X (expected 0x%02X) - wrong sensor?\n",
                part_id, SI1182_PART_ID);
        close(s->fd);
        s->fd = -1;
        return -1;
    }

    /* Software reset */
    if (i2c_write_byte(s->fd, SI1182_REG_HW_KEY, SI1182_HW_KEY_VAL) < 0) {
        close(s->fd);
        s->fd = -1;
        return -1;
    }
    usleep(10000); /* 10 ms settle after reset */

    /* Set measurement rate: 0x00 = 1 sample per 1 s (manual mode) */
    if (i2c_write_byte(s->fd, SI1182_REG_MEAS_RATE0, 0x00) < 0) {
        close(s->fd);
        s->fd = -1;
        return -1;
    }
    if (i2c_write_byte(s->fd, SI1182_REG_MEAS_RATE1, 0x00) < 0) {
        close(s->fd);
        s->fd = -1;
        return -1;
    }

    s->initialized = true;
    printf("Si1182 initialized (PART_ID=0x%02X)\n", part_id);
    return 0;
}

static int si1182_read_proximity(Si1182 *s, uint16_t *prox)
{
    if (!s->initialized) {
        fprintf(stderr, "Si1182 not initialized\n");
        return -1;
    }
    return i2c_read_word(s->fd, SI1182_REG_PS1_DATA0, prox);
}

static void si1182_close(Si1182 *s)
{
    if (s->fd >= 0) {
        close(s->fd);
        s->fd = -1;
    }
}

static void cleanup_handler(int signum)
{
    (void)signum;
    fprintf(stderr, "\nCaught signal, cleaning up...\n");
    si1182_close(&s);
    exit(0);
}

int main(void)
{
    Si1182 sensor;
    memset(&sensor, 0, sizeof(sensor));

    /* Install SIGINT handler for clean Ctrl+C exit */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = cleanup_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (si1182_init(&sensor) < 0) {
        fprintf(stderr, "Si1182 initialization failed\n");
        return 1;
    }

    printf("Starting proximity readings every 500 ms (Ctrl+C to stop)...\n");

    while (1) {
        uint16_t prox;
        if (si1182_read_proximity(&sensor, &prox) == 0) {
            printf("Proximity: %u\n", prox);
        } else {
            fprintf(stderr, "Failed to read proximity data\n");
        }
        usleep(500000); /* 500 ms */
    }

    /* Unreachable, but kept for completeness */
    si1182_close(&sensor);
    return 0;
}

