/*
 * MLX75030 Time-of-Flight distance reader for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   MLX75030 SDA  -> GPIO2  (pin 3, I2C bus 1 SDA)
 *   MLX75030 SCL  -> GPIO3  (pin 5, I2C bus 1 SCL)
 *   MLX75030 VDD  -> 3.3 V
 *   MLX75030 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o mlx75030 mlx75030.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MLX75030_ADDR  0x50

/* MLX75030 register addresses (16-bit, big-endian on the bus) */
#define REG_DISTANCE   0x00
#define REG_CONFIG     0x01

/* Config: 100 ms measurement interval, 50 Hz update rate, no interrupt */
#define CONFIG_VALUE   0x000A

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int i2c_write_reg16(int fd, uint16_t reg, uint16_t value)
{
    uint8_t buf[4];
    buf[0] = (uint8_t)((reg >> 8) & 0xFF);
    buf[1] = (uint8_t)(reg & 0xFF);
    buf[2] = (uint8_t)((value >> 8) & 0xFF);
    buf[3] = (uint8_t)(value & 0xFF);

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write_reg16(0x%04X): write failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint16_t reg, uint16_t *out)
{
    uint8_t reg_buf[2];
    uint8_t data[2];

    reg_buf[0] = (uint8_t)((reg >> 8) & 0xFF);
    reg_buf[1] = (uint8_t)(reg & 0xFF);

    if (write(fd, reg_buf, sizeof(reg_buf)) != (ssize_t)sizeof(reg_buf)) {
        fprintf(stderr, "i2c_read_reg16(0x%04X): write (reg select) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (read(fd, data, sizeof(data)) != (ssize_t)sizeof(data)) {
        fprintf(stderr, "i2c_read_reg16(0x%04X): read failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    if (install_signal_handlers() == -1)
        goto cleanup;

    fd = open(I2C_BUS, O_RDWR);
    if (fd == -1) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        goto cleanup;
    }

    if (ioctl(fd, I2C_SLAVE, MLX75030_ADDR) == -1) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                MLX75030_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Verify the sensor is present by reading the config register. */
    uint16_t cfg = 0;
    if (i2c_read_reg16(fd, REG_CONFIG, &cfg) == -1) {
        fprintf(stderr, "MLX75030 not responding at 0x%02X on %s\n",
                MLX75030_ADDR, I2C_BUS);
        goto cleanup;
    }

    if (i2c_write_reg16(fd, REG_CONFIG, CONFIG_VALUE) == -1) {
        fprintf(stderr, "Failed to configure MLX75030\n");
        goto cleanup;
    }

    printf("MLX75030 initialised (config=0x%04X). Reading distance every 500 ms...\n",
           cfg);
    fflush(stdout);

    while (g_running) {
        uint16_t dist = 0;
        if (i2c_read_reg16(fd, REG_DISTANCE, &dist) == -1) {
            fprintf(stderr, "I2C read error; will retry next cycle.\n");
        } else {
            printf("Distance: %u mm\n", (unsigned)dist);
            fflush(stdout);
        }

        /* Sleep 500 ms, but wake early on signal. */
        struct timespec ts = { .tv_sec = 0, .tv_nsec = 500 * 1000 * 1000 };
        while (nanosleep(&ts, &ts) == -1 && errno == EINTR && g_running)
            ;
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fd != -1)
        close(fd);
    return rc;
}

