/*
 * Raspberry Pi Zero W - TI OPT3101 Time-of-Flight Sensor Reader
 *
 * Reads distance and ambient light data from the OPT3101 on I2C bus 1.
 * Periodically logs the data to the console with robust error handling.
 *
 * Wiring:
 *   OPT3101 SDA -> GPIO2 (Pin 3)
 *   OPT3101 SCL -> GPIO3 (Pin 5)
 *   OPT3101 VDD -> 3.3V
 *   OPT3101 GND -> GND
 *
 * Build: gcc -o opt3101_reader opt3101_reader.c -lpigpio -lrt
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS 1
#define OPT3101_ADDR 0x20

#define REG_CHIP_ID 0x00
#define REG_DISTANCE_CH0 0x04
#define REG_AMBIENT_LIGHT 0x06

#define CHIP_ID_EXPECTED 0x3101

#define POLL_INTERVAL_US 500000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

static int read_register(uint8_t reg, uint16_t *value) {
    char buf[2];
    int rc = i2cReadI2CBlockData(i2c_handle, reg, buf, 2);
    if (rc != 2) {
        return -1;
    }
    *value = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

static int write_register(uint8_t reg, uint16_t value) {
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)((value >> 8) & 0xFF);
    buf[2] = (char)(value & 0xFF);
    int rc = i2cWriteI2CBlockData(i2c_handle, reg, buf + 1, 2);
    if (rc != 2) {
        return -1;
    }
    return 0;
}

static int init_opt3101(void) {
    uint16_t chip_id = 0;
    if (read_register(REG_CHIP_ID, &chip_id) != 0) {
        fprintf(stderr, "Error: Failed to read CHIP_ID register.\n");
        return -1;
    }
    if (chip_id != CHIP_ID_EXPECTED) {
        fprintf(stderr, "Error: Unexpected CHIP_ID 0x%04X (expected 0x%04X).\n",
                chip_id, CHIP_ID_EXPECTED);
        return -1;
    }
    printf("OPT3101 detected (CHIP_ID = 0x%04X).\n", chip_id);

    if (write_register(REG_DISTANCE_CH0, 0x0001) != 0) {
        fprintf(stderr, "Error: Failed to configure DISTANCE_CH0.\n");
        return -1;
    }
    if (write_register(REG_AMBIENT_LIGHT, 0x0001) != 0) {
        fprintf(stderr, "Error: Failed to configure AMBIENT_LIGHT.\n");
        return -1;
    }

    return 0;
}

static int read_sensor_data(uint16_t *distance, uint16_t *ambient_light) {
    uint16_t dist_raw = 0, light_raw = 0;

    if (read_register(REG_DISTANCE_CH0, &dist_raw) != 0) {
        fprintf(stderr, "Error: Failed to read DISTANCE_CH0.\n");
        return -1;
    }
    if (read_register(REG_AMBIENT_LIGHT, &light_raw) != 0) {
        fprintf(stderr, "Error: Failed to read AMBIENT_LIGHT.\n");
        return -1;
    }

    *distance = dist_raw;
    *ambient_light = light_raw;
    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, OPT3101_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device on bus %d at addr 0x%02X.\n",
                I2C_BUS, OPT3101_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_opt3101() != 0) {
        fprintf(stderr, "Error: OPT3101 initialisation failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Starting periodic readings (Ctrl-C to stop)...\n");

    while (running) {
        uint16_t distance = 0, ambient_light = 0;

        if (read_sensor_data(&distance, &ambient_light) == 0) {
            printf("Distance: %u mm, Ambient Light: %u\n", distance, ambient_light);
        } else {
            fprintf(stderr, "Error: Failed to read sensor data.\n");
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

