        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Timing helpers                                                     */
/* ------------------------------------------------------------------ */
static uint64_t now_us(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        perror("clock_gettime");
        return 0;
    }
    return (uint64_t)ts.tv_sec * 1000000ULL + (uint64_t)ts.tv_nsec / 1000ULL;
}

static void sleep_us(uint64_t us)
{
    struct timespec ts;
    ts.tv_sec  = (time_t)(us / 1000000ULL);
    ts.tv_nsec = (long)((us % 1000000ULL) * 1000ULL);
    nanosleep(&ts, NULL);
}

/* ------------------------------------------------------------------ */
/* HC-SR04 measurement                                                */
/* ------------------------------------------------------------------ */
/*
 * Returns:
 *   >= 0  : distance in centimetres (rounded to 2 decimal places)
 *   -1.0  : echo never went high (sensor absent or not responding)
 *   -2.0  : echo never went low (timeout or stuck high)
 *   -3.0  : pulse too short (invalid measurement)
 *   -4.0  : pulse too long (> 38 ms, HC-SR04 max range)
 */
static double measure_distance(void)
{
    uint64_t t0 = now_us();

    /* Issue 10 µs trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) != 0) {
        fprintf(stderr, "gpioWrite(trigger high) failed\n");
        return -1.0;
    }
    sleep_us(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "gpioWrite(trigger low) failed\n");
        return -1.0;
    }

    /* Wait for echo rising edge (timeout if sensor absent) */
    uint64_t deadline = t0 + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if (now_us() >= deadline) {
            fprintf(stderr, "Timeout waiting for echo rising edge (sensor absent?)\n");
            return -1.0;
        }
    }
    uint64_t rise = now_us();

    /* Wait for echo falling edge (timeout if stuck high) */
    deadline = rise + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if (now_us() >= deadline) {
            fprintf(stderr, "Timeout waiting for echo falling edge (stuck high?)\n");
            return -2.0;
        }
    }
    uint64_t fall = now_us();

    uint64_t pulse_us = fall - rise;
    if (pulse_us < MIN_RANGE_US) {
        fprintf(stderr, "Invalid pulse: %llu µs (too short)\n", (unsigned long long)pulse_us);
        return -3.0;
    }
    if (pulse_us > MAX_RANGE_US) {
        fprintf(stderr, "Invalid pulse: %llu µs (out of range, max %d µs)\n",
                (unsigned long long)pulse_us, MAX_RANGE_US);
        return -4.0;
    }

    /* distance = (pulse_us * 34300 cm/s) / 2 */
    double distance_cm = (double)pulse_us * 34300.0 / 2000000.0;
    return distance_cm;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_distance(double distance_cm)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32] = {0};
    if (t != NULL) {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    } else {
        snprintf(ts, sizeof(ts), "<unknown-time>");
    }
    printf("[%s] Distance: %.2f cm\n", ts, distance_cm);
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Ensure trigger is left low */
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(TRIGGER_PIN) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(ECHO_PIN) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "gpioWrite(TRIGGER_PIN, 0) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Allow sensor to settle */
    sleep_us(100000); /* 100 ms */

    printf("HC-SR04 distance measurement started.\n");
    printf("  Trigger: GPIO %d | Echo: GPIO %d | Interval: %d s\n",
           TRIGGER_PIN, ECHO_PIN, READ_INTERVAL_S);
    printf("  Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (g_running) {
        double distance = measure_distance();

        if (distance >= 0.0) {
            log_distance(distance);
        } else {
            fprintf(stderr, "Measurement failed (code %d)\n", (int)distance);
        }

        /* Sleep READ_INTERVAL_S, but wake early on signal */
        for (int i = 0; i < READ_INTERVAL_S && g_running; i++) {
            sleep_us(1000000ULL); /* 1 s */
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

