/*
 * IWR1443 mmWave range-profile monitor with intrusion detection.
 *
 * Board:  Raspberry Pi 3 Model B+
 * UART:   /dev/serial0 (physical pins 14/15, 3.3 V logic)
 * LED:    GPIO 17 (BCM) — active-high alert indicator
 *
 * Build:  gcc -O2 -Wall -Wextra -o intrusion intrusion.c -lpigpio -lrt
 * Run:    sudo ./intrusion
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <sys/select.h>
#include <pigpio.h>

#define UART_DEVICE      "/dev/serial0"
#define LED_GPIO         17
#define INTRUSION_LOG    "intrusion_log.csv"
#define RANGE_PROFILE_LEN 128          /* 64 little-endian 16-bit bins × 2 bytes */
#define MAGIC_WORD_LEN   8
#define TARGET_THRESHOLD 1.0f          /* meters */
#define ALERT_DURATION_US 2000000      /* 2 s in microseconds */
#define POLL_INTERVAL_US  100000       /* 100 ms */
#define READ_BUF_LEN      1024

/* IWR1443 magic word (little-endian 8 bytes) */
static const uint8_t MAGIC_WORD[MAGIC_WORD_LEN] = {
    0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08
};

static volatile sig_atomic_t g_running = 1;
static int  g_uart_fd = -1;
static FILE *g_log_fp  = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int init_uart(const char *device)
{
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", device, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "tcgetattr: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    /* 115200 8N1, raw mode */
    tty.c_cflag  = CS8 | CLOCAL | CREAD;
    tty.c_iflag  = 0;
    tty.c_oflag  = 0;
    tty.c_lflag  = 0;
    tty.c_cc[VMIN]  = 0;
    tty.c_cc[VTIME] = 1;                 /* 100 ms inter-byte timeout */

    if (cfsetispeed(&tty, B115200) != 0 || cfsetospeed(&tty, B115200) != 0) {
        fprintf(stderr, "cfsetspeed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "tcsetattr: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

/* ------------------------------------------------------------------ */
static void log_intrusion(float distance)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);

    if (fprintf(g_log_fp, "%s,%.2f\n", ts, distance) < 0) {
        fprintf(stderr, "fprintf to log: %s\n", strerror(errno));
        return;
    }
    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "fflush log: %s\n", strerror(errno));
    }
}

/* ------------------------------------------------------------------ */
static void trigger_alert(void)
{
    if (gpioWrite(LED_GPIO, 1) < 0) {
        fprintf(stderr, "gpioWrite(LED on) failed\n");
        return;
    }
    gpioDelay(ALERT_DURATION_US);
    if (gpioWrite(LED_GPIO, 0) < 0) {
        fprintf(stderr, "gpioWrite(LED off) failed\n");
    }
}

/* ------------------------------------------------------------------ */
static bool detect_target(const uint8_t *data)
{
    for (int i = 0; i <= 64 - 1; i++) {
        uint16_t bin = (uint16_t)((data[2 * i + 1] << 8) | data[2 * i]);
        if (bin > 0 && bin <= (uint16_t)TARGET_THRESHOLD) {
            return true;
        }
    }
    return false;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d) failed\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* ---- UART init ---- */
    g_uart_fd = init_uart(UART_DEVICE);
    if (g_uart_fd < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Log file ---- */
    g_log_fp = fopen(INTRUSION_LOG, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s): %s\n", INTRUSION_LOG, strerror(errno));
        close(g_uart_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "timestamp,distance_m\n");
        fflush(g_log_fp);
    }

    /* ---- Signals ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Monitoring IWR1443 range profile on %s (LED on GPIO %d)...\n",
           UART_DEVICE, LED_GPIO);
    printf("Press Ctrl+C to exit.\n");

    uint8_t read_buf[READ_BUF_LEN];
    size_t  read_len = 0;
    bool    have_magic = false;
    uint8_t magic_buf[MAGIC_WORD_LEN];

    while (g_running) {
        fd_set rfds;
        FD_ZERO(&rfds);
        FD_SET(g_uart_fd, &rfds);

        struct timeval tv = { .tv_sec = 0, .tv_usec = POLL_INTERVAL_US };

        int rc = select(g_uart_fd + 1, &rfds, NULL, NULL, &tv);
        if (rc < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "select: %s\n", strerror(errno));
            break;
        }
        if (rc == 0) continue;                 /* timeout — loop back */

        ssize_t n = read(g_uart_fd, read_buf + read_len, sizeof(read_buf) - read_len);
        if (n < 0) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) continue;
            fprintf(stderr, "read: %s\n", strerror(errno));
            break;
        }
        if (n == 0) {
            /* Device disappeared — attempt to reopen */
            close(g_uart_fd);
            g_uart_fd = -1;
            gpioDelay(100000);
            g_uart_fd = init_uart(UART_DEVICE);
            if (g_uart_fd < 0) {
                fprintf(stderr, "Reinit UART failed; aborting.\n");
                break;
            }
            continue;
        }

        read_len += (size_t)n;

        /* Scan for magic word */
        if (!have_magic) {
            for (size_t i = 0; i <= read_len - MAGIC_WORD_LEN; i++) {
                if (memcmp(read_buf + i, MAGIC_WORD, MAGIC_WORD_LEN) == 0) {
                    memcpy(magic_buf, read_buf + i, MAGIC_WORD_LEN);
                    have_magic = true;
                    read_len = 0;            /* wait for full profile */
                    break;
                }
            }
            continue;
        }

        /* Full profile received — check for target */
        if (read_len >= RANGE_PROFILE_LEN) {
            if (detect_target(magic_buf)) {
                log_intrusion((float)magic_buf[0] / 256.0f);
                trigger_alert();
            }
            read_len = 0;
            have_magic = false;
        }
    }

    /* ---- Cleanup ---- */
    if (g_uart_fd >= 0) {
        close(g_uart_fd);
        g_uart_fd = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

