/*
 * obstacle_buzzer.c — E18-D80NK IR obstacle detector with active-low
 *  (0 = obstacle detected) and active-high buzzer on a Raspberry Pi 4.
 *
 * Wiring:
 *   E18-D80NK  -> GPIO 17 (active-low)
 *   Buzzer     -> GPIO 18 (active-high)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o obstacle_buzzer obstacle_buzzer.c -lpigpio -lrt
 *   (must be run as root or with appropriate gpio access)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_PIN      17
#define BUZZER_PIN      18
#define LOG_FILE        "obstacle_log.txt"
#define POLL_DELAY_US   100000   /* 100 ms */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_event(const char *message)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        return;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("time()");
        fclose(fp);
        return;
    }

    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return;
    }

    if (fprintf(fp, "%s: %s\n", timestamp, message) < 0) {
        perror("fprintf");
    }

    if (fclose(fp) != 0) {
        perror("fclose");
    }
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */
static int safe_set_mode(unsigned pin, unsigned mode)
{
    if (gpioSetMode(pin, mode) != 0) {
        fprintf(stderr, "gpioSetMode(%u, %u) failed\n", pin, mode);
        return -1;
    }
    return 0;
}

static int safe_write(unsigned pin, unsigned level)
{
    if (gpioWrite(pin, level) != 0) {
        fprintf(stderr, "gpioWrite(%u, %u) failed\n", pin, level);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (safe_set_mode(SENSOR_PIN, PI_INPUT) != 0 ||
        safe_set_mode(BUZZER_PIN, PI_OUTPUT) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Start with buzzer off */
    if (safe_write(BUZZER_PIN, 0) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int last_state = -1;   /* force initial log */

    while (g_running) {
        int sensor_value = gpioRead(SENSOR_PIN);
        if (sensor_value < 0) {
            fprintf(stderr, "gpioRead(%d) failed\n", SENSOR_PIN);
            break;
        }

        /* E18-D80NK is active-low: 0 => obstacle detected */
        int obstacle_detected = (sensor_value == 0);

        if (obstacle_detected != last_state) {
            if (safe_write(BUZZER_PIN, obstacle_detected ? 1 : 0) != 0) {
                break;
            }
            last_state = obstacle_detected;
            log_event(obstacle_detected ? "Obstacle detected" : "Obstacle cleared");
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* Graceful shutdown: ensure buzzer is off */
    safe_write(BUZZER_PIN, 0);
    gpioTerminate();

    log_event("Program terminated");
    return EXIT_SUCCESS;
}

