/*
 * Raspberry Pi 4 Model B – TDK Chirp ICU-20201 ultrasonic TOF sensor
 *
 * I2C bus 1, address 0x20 (ADDR pin tied to GND).
 * Reads distance every 100 ms, logs to distance_log.txt, and asserts
 * BCM 17 on alert when distance < 10.0 cm.
 *
 * Build:  gcc -O2 -Wall -Wextra -o tof_monitor tof_monitor.c -lpigpio -lrt
 * Run:    sudo ./tof_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define I2C_ADDR             0x20          /* ICU-20201 ADDR pin tied to GND */
#define DISTANCE_THRESHOLD_CM 10.0f
#define ALERT_GPIO            17            /* BCM 17 */
#define LOG_FILE              "distance_log.txt"
#define SAMPLE_PERIOD_US      100000        /* 100 ms */
#define MAX_RETRIES           3
#define MAX_DISTANCE_CM       400.0f        /* sanity cap */

/* ICU-20201 register map (16-bit, big-endian on the bus) */
#define REG_RESULT_DIST      0x00
#define REG_RESULT_STATUS    0x01
#define REG_COMMAND          0x02
#define REG_DEVICE_ID        0x03
#define REG_RESET            0x04
#define REG_INT_CONFIG       0x05
#define REG_INT_ENABLE       0x06
#define REG_INT_MODE         0x07
#define REG_INT_CLEAR        0x08
#define REG_FIFO_CONFIG      0x09
#define REG_FIFO_DATA        0x0A
#define REG_FIFO_COUNT       0x0B
#define REG_FIFO_STATUS      0x0C
#define REG_FIFO_DATA_MASK   0x0F
#define REG_FIFO_COUNT_MASK  0x0F
#define REG_FIFO_STATUS_MASK 0x0F
#define REG_FIFO_DATA_SHIFT  12
#define REG_FIFO_COUNT_SHIFT 12
#define REG_FIFO_STATUS_SHIFT 12

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* --------------------------- Forward declarations ------------------------ */
static void signal_handler(int sig);
static int  init_i2c(void);
static int  read_distance_cm(float *distance_cm);
static int  log_distance(float distance_cm);
static void trigger_alert(void);
static void cleanup(void);

/* ------------------------------- Signal handler -------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------- I2C helpers ----------------------------- */
static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, I2C_ADDR, pigpio_error(g_i2c_handle));
        return -1;
    }

    /* Probe the device by reading the device ID register (0x03). */
    int id = i2cReadByteData(g_i2c_handle, REG_DEVICE_ID);
    if (id < 0) {
        fprintf(stderr, "[ERROR] Device ID read failed: %s\n", pigpio_error(id));
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }
    if (id == 0x00) {
        fprintf(stderr, "[WARN] Device ID 0x00 – sensor may be absent or not responding.\n");
    }

    return 0;
}

/*
 * Read a 16-bit big-endian register.
 * Returns 0 on success, -1 on error.
 */
static int read_reg16(int handle, uint8_t reg, uint16_t *out)
{
    int hi = i2cReadByteData(handle, reg);
    if (hi < 0) return -1;
    int lo = i2cReadByteData(handle, reg + 1);
    if (lo < 0) return -1;
    *out = ((uint16_t)hi << 8) | (uint16_t)lo;
    return 0;
}

/*
 * Read a 16-bit big-endian register and interpret the lower 4 bits as a
 * status flag (bits 3:0).  Returns 0 on success, -1 on error.
 */
static int read_reg16_status(int handle, uint8_t reg, uint16_t *out)
{
    int hi = i2cReadByteData(handle, reg);
    if (hi < 0) return -1;
    int lo = i2cReadByteData(handle, reg + 1);
    if (lo < 0) return -1;
    *out = ((uint16_t)hi << 8) | (uint16_t)lo;
    return 0;
}

/*
 * Write a single byte to a register.
 * Returns 0 on success, -1 on error.
 */
static int write_reg8(int handle, uint8_t reg, uint8_t val)
{
    return i2cWriteByteData(handle, reg, val);
}

/*
 * Read the distance register (0x00) and convert to centimetres.
 * Returns 0 on success, -1 on error.
 */
static int read_distance_cm(float *distance_cm)
{
    uint16_t raw;
    if (read_reg16(g_i2c_handle, REG_RESULT_DIST, &raw) != 0) {
        fprintf(stderr, "[ERROR] Failed to read distance register.\n");
        return -1;
    }

    /* Sanity cap: a zero or negative reading is likely an error. */
    if (raw == 0 || raw == 0xFFFF) {
        fprintf(stderr, "[WARN] Distance raw=0x%04X – possible sensor error.\n", raw);
        return -1;
    }

    /* Convert 16-bit big-endian to centimetres (per ICU-20201 datasheet). */
    *distance_cm = (float)raw / 10.0f;
    return 0;
}

/*
 * Append a timestamped distance reading to the log file.
 * Returns 0 on success, -1 on error.
 */
static int log_distance(float distance_cm)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "[ERROR] time() failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    if (t == NULL) {
        fprintf(stderr, "[ERROR] localtime_r() failed.\n");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t) == 0) {
        fprintf(stderr, "[ERROR] strftime() failed.\n");
        return -1;
    }

    if (fprintf(g_log_file, "%s, Distance: %.2f cm\n", ts, distance_cm) < 0) {
        fprintf(stderr, "[ERROR] fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "[WARN] fflush failed: %s\n", strerror(errno));
    }

    return 0;
}

/*
 * Assert the alert GPIO for 1 s, then deassert.
 */
static void trigger_alert(void)
{
    if (gpioWrite(ALERT_GPIO, 1) < 0) {
        fprintf(stderr, "[WARN] gpioWrite(high) failed on BCM %d.\n", ALERT_GPIO);
    }
    gpioDelay(1000000);   /* 1 s */
    if (gpioWrite(ALERT_GPIO, 0) < 0) {
        fprintf(stderr, "[WARN] gpioWrite(low) failed on BCM %d.\n", ALERT_GPIO);
    }
}

/* ------------------------------- Cleanup --------------------------------- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    /* Ensure alert GPIO is left low. */
    gpioWrite(ALERT_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------- Main ------------------------------------ */
int main(void)
{
    /* Install signal handlers for clean shutdown. */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialise pigpio. */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure alert GPIO as output, initially low. */
    if (gpioSetMode(ALERT_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "[ERROR] gpioSetMode(%d, PI_OUTPUT) failed.\n", ALERT_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(ALERT_GPIO, 0) < 0) {
        fprintf(stderr, "[ERROR] gpioWrite(%d, 0) failed.\n", ALERT_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialise I2C. */
    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode. */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[ERROR] Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ICU-20201 TOF monitor started.  Threshold: %.1f cm  |  Log: %s\n",
           DISTANCE_THRESHOLD_CM, LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    /* Main sampling loop. */
    while (g_running) {
        float distance_cm = 0.0f;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (read_distance_cm(&distance_cm) == 0) {
                ok = 1;
                break;
            }
            fprintf(stderr, "[WARN] Read attempt %d/%d failed.\n",
                    attempt + 1, MAX_RETRIES);
            if (attempt < MAX_RETRIES - 1) {
                gpioDelay(100000);   /* 100 ms back-off */
            }
        }

        if (ok) {
            if (log_distance(distance_cm) != 0) {
                fprintf(stderr, "[ERROR] Logging failed; continuing.\n");
            }

            if (distance_cm < DISTANCE_THRESHOLD_CM) {
                trigger_alert();
            }
        } else {
            fprintf(stderr, "[ERROR] All %d read attempts failed; continuing.\n",
                    MAX_RETRIES);
        }

        /* Sleep for the remainder of the 100 ms period. */
        if (g_running) {
            gpioDelay(SAMPLE_PERIOD_US);
        }
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

