#define CH201_REG_SYSTEM_INTERRUPT_GPIO_INT_EN_NB 0xFE
#define CH201_REG_SYSTEM_INTERRUPT_GPIO_INT_CLR_NB 0xFF

#define CH201_REG_RESULT_DISTANCE 0x10
#define CH201_REG_RESULT_INTERRUPT_STATUS 0x11

#define CH201_I2C_ADDR 0x29
#define I2C_BUS "/dev/i2c-1"
#define LED_GPIO 18
#define BLINK_HALF_CYCLES_PER_SAMPLE 1
#define SAMPLE_PERIOD_US 100000
#define MAX_RETRIES 3
#define RETRY_DELAY_US 10000

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void handle_signal(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        ssize_t n = write(fd, buf, sizeof(buf));
        if (n == (ssize_t)sizeof(buf))
            return 0;
        if (n < 0)
            fprintf(stderr, "I2C write to reg 0x%02X failed (attempt %d): %s\n",
                    reg, attempt + 1, strerror(errno));
        else
            fprintf(stderr, "I2C write to reg 0x%02X short: %zd bytes (attempt %d)\n",
                    reg, n, attempt + 1);
        if (attempt < MAX_RETRIES - 1)
            usleep(RETRY_DELAY_US);
    }
    return -1;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        ssize_t n = write(fd, &reg, 1);
        if (n != 1) {
            fprintf(stderr, "I2C write (reg select 0x%02X) failed (attempt %d): %s\n",
                    reg, attempt + 1, strerror(errno));
            if (attempt < MAX_RETRIES - 1)
                usleep(RETRY_DELAY_US);
            continue;
        }
        n = read(fd, out, 1);
        if (n == 1)
            return 0;
        if (n < 0)
            fprintf(stderr, "I2C read from reg 0x%02X failed (attempt %d): %s\n",
                    reg, attempt + 1, strerror(errno));
        else
            fprintf(stderr, "I2C read from reg 0x%02X short: %zd bytes (attempt %d)\n",
                    reg, n, attempt + 1);
        if (attempt < MAX_RETRIES - 1)
            usleep(RETRY_DELAY_US);
    }
    return -1;
}

static int i2c_read_reg16_be(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        ssize_t n = write(fd, &reg, 1);
        if (n != 1) {
            fprintf(stderr, "I2C write (reg select 0x%02X) failed (attempt %d): %s\n",
                    reg, attempt + 1, strerror(errno));
            if (attempt < MAX_RETRIES - 1)
                usleep(RETRY_DELAY_US);
            continue;
        }
        n = read(fd, buf, 2);
        if (n == 2) {
            *out = ((uint16_t)buf[0] << 8) | buf[1];
            return 0;
        }
        if (n < 0)
            fprintf(stderr, "I2C read16 from reg 0x%02X failed (attempt %d): %s\n",
                    reg, attempt + 1, strerror(errno));
        else
            fprintf(stderr, "I2C read16 from reg 0x%02X short: %zd bytes (attempt %d)\n",
                    reg, n, attempt + 1);
        if (attempt < MAX_RETRIES - 1)
            usleep(RETRY_DELAY_US);
    }
    return -1;
}

static int ch201_init(int fd)
{
    uint8_t model_id = 0;
    if (i2c_read_reg8(fd, CH201_REG_IDENTIFICATION_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Cannot read CH201 model ID — sensor absent or bus error.\n");
        return -1;
    }
    printf("CH201 detected (model ID = 0x%02X).\n", model_id);

    /* Clear any latched interrupt so we can start fresh. */
    if (i2c_write_reg8(fd, CH201_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0)
        return -1;

    /* Set GPIO interrupt to assert on any new sample-ready event. */
    if (i2c_write_reg8(fd, CH201_REG_SYSTEM_INTERRUPT_GPIO_INT_EN_1, 0x01) != 0)
        return -1;

    return 0;
}

static int ch201_read_distance(int fd, uint16_t *distance)
{
    uint8_t status = 0;
    if (i2c_read_reg8(fd, CH201_REG_RESULT_INTERRUPT_STATUS, &status) != 0)
        return -1;

    if ((status & 0x01) == 0)
        return 1;  /* no new sample ready yet */

    uint16_t dist = 0;
    if (i2c_read_reg16_be(fd, CH201_REG_RESULT_DISTANCE, &dist) != 0)
        return -1;

    /* Clear the interrupt so the next sample can be reported. */
    if (i2c_write_reg8(fd, CH201_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0)
        return -1;

    *distance = dist;
    return 0;
}

static void set_led(int gpio, int on)
{
    if (gpioWrite(gpio, on ? 1 : 0) < 0)
        fprintf(stderr, "Warning: gpioWrite(%d, %d) failed: %s\n",
                gpio, on, strerror(errno));
}

static void blink_led(int gpio, int half_cycles)
{
    for (int i = 0; i < half_cycles && g_running; i++)
        set_led(gpio, i % 2);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, CH201_I2C_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                CH201_I2C_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    if (ch201_init(g_i2c_fd) != 0) {
        fprintf(stderr, "CH201 initialization failed.\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("Starting distance readings (Ctrl+C to stop)...\n");

    while (g_running) {
        uint16_t distance = 0;
        int rc = ch201_read_distance(g_i2c_fd, &distance);

        if (rc == 0) {
            time_t now = time(NULL);
            struct tm tm_buf;
            struct tm *t = localtime_r(&now, &tm_buf);
            char ts[32];
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
            printf("%s  Distance: %u mm\n", ts, distance);
            printf("  LED half-cycles: %d\n", BLINK_HALF_CYCLES_PER_SAMPLE);
        } else if (rc < 0) {
            fprintf(stderr, "I2C read error — continuing.\n");
        }

        blink_led(LED_GPIO, BLINK_HALF_CYCLES_PER_SAMPLE);
    }

    /* Graceful shutdown: ensure LED is off. */
    set_led(LED_GPIO, 0);
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

