/*
 * MLX75030 Time-of-Flight Distance Logger for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   MLX75030 SDA -> GPIO2 (I2C bus 1 SDA, pin 3)
 *   MLX75030 SCL -> GPIO3 (I2C bus 1 SCL, pin 5)
 *   MLX75030 VDD -> 3.3 V (pin 1)
 *   MLX75030 GND -> GND  (pin 6)
 *
 * Build:  gcc -O2 -Wall -o mlx75030_logger mlx75030_logger.c -lpigpio -lrt
 * Run:    sudo ./mlx75030_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x50          /* MLX75030 default I2C address */
#define LOG_FILE       "distance_log.csv"
#define SAMPLE_US      100000        /* 100 ms sampling interval */
#define MAX_RETRIES    3
#define MEAS_DELAY_US  50000         /* 50 ms measurement settle time */
#define READ_LEN       2             /* 2 bytes distance result */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int handle, const uint8_t *cmd, uint8_t len)
{
    if (i2cWriteDevice(handle, (char *)cmd, len) != 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice failed (cmd len=%u): %s\n",
                len, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int handle, uint8_t *buf, uint8_t len)
{
    int n = i2cReadDevice(handle, (char *)buf, len);
    if (n != len) {
        fprintf(stderr, "[ERROR] i2cReadDevice returned %d (expected %u): %s\n",
                n, len, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* MLX75030 measurement sequence                                       */
/* ------------------------------------------------------------------ */
/*
 * Trigger a measurement and read the 2-byte distance result.
 * Returns 0 on success and stores distance in *out_cm; -1 on error.
 */
static int read_distance_cm(int handle, int *out_cm)
{
    uint8_t cmd[1] = { 0x01 };  /* Start measurement command */

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2c_write_cmd(handle, cmd, sizeof(cmd)) != 0) {
            gpioDelay(10000);  /* 10 ms back-off before retry */
            continue;
        }

        gpioDelay(MEAS_DELAY_US);

        uint8_t data[READ_LEN];
        if (i2c_read_bytes(handle, data, READ_LEN) != 0) {
            gpioDelay(10000);
            continue;
        }

        int raw = ((int)data[0] << 8) | data[1];
        *out_cm = raw;  /* distance in centimetres */
        return 0;
    }

    fprintf(stderr, "[ERROR] Distance read failed after %d attempts.\n", MAX_RETRIES);
    return -1;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_data(const char *filename, int distance_cm)
{
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "[ERROR] Cannot open %s: %s\n", filename, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%d\n", ts, distance_cm) < 0) {
        fprintf(stderr, "[ERROR] fprintf to log failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "[WARN] fclose failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* --- I2C open --------------------------------------------------- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers ------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction failed: %s\n", strerror(errno));
    }

    printf("MLX75030 distance logger started. Logging to %s every 100 ms.\n",
           LOG_FILE);
    printf("Press Ctrl+C to stop.\n");

    /* --- Main loop -------------------------------------------------- */
    while (g_running) {
        int distance_cm = 0;
        if (read_distance_cm(g_i2c_handle, &distance_cm) == 0) {
            if (log_data(LOG_FILE, distance_cm) != 0) {
                fprintf(stderr, "[WARN] Logging failed for this sample.\n");
            }
        } else {
            fprintf(stderr, "[WARN] Skipping sample due to read failure.\n");
        }

        /* Sleep in small increments so signals are caught promptly */
        for (int i = 0; i < 10 && g_running; i++) {
            gpioDelay(SAMPLE_US / 10);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

