/*
 * TCRT5000 IR Obstacle Avoidance Logger for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   Sensor 1 (left)  -> GPIO 17 (physical pin 11, BCM)
 *   Sensor 2 (right) -> GPIO 27 (physical pin 13, BCM)
 *   VCC             -> 3.3 V (physical pin 1)
 *   GND             -> GND  (physical pin 9)
 *
 * Behavior:
 *   Polls each sensor every 10 ms.  Debounces each channel with a 50 ms
 *   software delay after a state change.  Logs every state transition
 *   to proximity_log.txt with an ISO 8601 UTC timestamp, sensor ID, and
 *   event type ('DETECTED' or 'CLEARED').
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o proximity_logger proximity_logger.c
 *
 * Run:
 *   ./proximity_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#include <pigpio.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 27
#define DEBOUNCE_MS   50
#define POLL_MS       10
#define LOG_FILE      "proximity_log.txt"

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */
static void get_iso8601_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        snprintf(buf, len, "1970-01-01T00:00:00Z");
        return;
    }
    struct tm tm_utc;
    if (gmtime_r(&now, &tm_utc) == NULL) {
        snprintf(buf, len, "1970-01-01T00:00:00Z");
        return;
    }
    strftime(buf, len, "%Y-%m-%dT%H:%M:%SZ", &tm_utc);
}

static void log_event(int sensor_id, const char *event_type)
{
    char ts[32];
    get_iso8601_timestamp(ts, sizeof(ts));

    if (fprintf(g_log_fp, "%s - Sensor %d - %s\n", ts, sensor_id, event_type) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
    } else {
        fflush(g_log_fp);
    }
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */
static int read_sensor(int gpio)
{
    int v = gpioRead(gpio);
    if (v < 0) {
        fprintf(stderr, "gpioRead(%d) failed: %s\n", gpio, pigpio_error(v));
        return -1;
    }
    return v;
}

static void log_sensor_state(int sensor_id, int last_state, int current_state)
{
    if (current_state == last_state) {
        return;                 /* no transition */
    }

    if (current_state == 1) {
        log_event(sensor_id, "DETECTED");
    } else {
        log_event(sensor_id, "CLEARED");
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure GPIO pins ---- */
    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_1_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_2_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Enable internal pull-downs so sensors read LOW when idle */
    if (gpioSetPullUpDown(SENSOR_1_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO %d\n", SENSOR_1_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR_2_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO %d\n", SENSOR_2_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Proximity logger started.  Press Ctrl+C to exit.\n");

    /* ---- Main polling loop ---- */
    int last_state_1 = -1;   /* unknown initial state */
    int last_state_2 = -1;

    while (g_running) {
        int s1 = read_sensor(SENSOR_1_GPIO);
        int s2 = read_sensor(SENSOR_2_GPIO);

        if (s1 < 0 || s2 < 0) {
            /* Read error — back off briefly and retry */
            gpioDelay(POLL_MS * 1000);
            continue;
        }

        /* Log current state */
        log_sensor_state(1, last_state_1, s1);
        log_sensor_state(2, last_state_2, s2);

        last_state_1 = s1;
        last_state_2 = s2;

        /* Software debounce: wait 50 ms after a state change */
        gpioDelay(DEBOUNCE_MS * 1000);
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");

    /* Release GPIO resources via pigpio */
    gpioSetPullUpDown(SENSOR_1_GPIO, PI_PUD_OFF);
    gpioSetPullUpDown(SENSOR_2_GPIO, PI_PUD_OFF);
    gpioTerminate();

    /* Close log file */
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }

    printf("Proximity logger stopped.\n");
    return EXIT_SUCCESS;
}

