#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define CH101_ADDR     0x68
#define CSV_FILE       "distance_log.csv"
#define POLL_TIMEOUT_MS 50
#define SAMPLE_DELAY_MS 500

/* CH-101 register addresses */
#define REG_MEAS_STATUS   0x00
#define REG_DISTANCE      0x04
#define REG_COMMAND       0x0F

/* Command opcodes */
#define CMD_RESET         0x01
#define CMD_START         0x02

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_csv = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int fd, uint8_t reg, uint8_t *out)
{
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    n = read(fd, out, 1);
    if (n != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_word(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];
    if (i2c_read_byte(fd, reg, &buf[0]) < 0)
        return -1;
    if (i2c_read_byte(fd, reg + 1, &buf[1]) < 0)
        return -1;
    *out = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int ch101_reset(int fd)
{
    if (i2c_write_byte(fd, REG_COMMAND, CMD_RESET) < 0)
        return -1;
    usleep(10000);
    return 0;
}

static int ch101_start(int fd)
{
    if (i2c_write_byte(fd, REG_COMMAND, CMD_START) < 0)
        return -1;
    return 0;
}

static int ch101_wait_ready(int fd, int timeout_ms)
{
    uint8_t status;
    for (int i = 0; i < timeout_ms; i++) {
        if (i2c_read_byte(fd, REG_MEAS_STATUS, &status) < 0)
            return -1;
        if ((status & 0x01) == 0)
            return 0;
        usleep(1000);
    }
    fprintf(stderr, "CH-101 measurement timeout after %d ms\n", timeout_ms);
    return -1;
}

static int read_distance(int fd, uint16_t *distance_mm)
{
    if (ch101_wait_ready(fd, POLL_TIMEOUT_MS) < 0)
        return -1;
    if (i2c_read_word(fd, REG_DISTANCE, distance_mm) < 0)
        return -1;
    return 0;
}

static void log_data(FILE *fp, uint16_t distance_mm)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }
    if (fprintf(fp, "%s,%u\n", ts, distance_mm) < 0) {
        fprintf(stderr, "fprintf to CSV failed: %s\n", strerror(errno));
        return;
    }
    if (fflush(fp) != 0)
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, CH101_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                CH101_ADDR, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    if (ch101_reset(g_i2c_fd) < 0) {
        fprintf(stderr, "CH-101 reset failed\n");
        close(g_i2c_fd);
        return 1;
    }

    if (ch101_start(g_i2c_fd) < 0) {
        fprintf(stderr, "CH-101 start failed\n");
        close(g_i2c_fd);
        return 1;
    }

    g_csv = fopen(CSV_FILE, "a");
    if (g_csv == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", CSV_FILE, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    while (g_running) {
        uint16_t distance_mm;
        if (read_distance(g_i2c_fd, &distance_mm) == 0) {
            log_data(g_csv, distance_mm);
        } else {
            fprintf(stderr, "Skipping sample due to I2C error\n");
        }
        usleep(SAMPLE_DELAY_MS * 1000);
    }

    fprintf(stderr, "\nShutting down cleanly...\n");
    if (g_csv != NULL) {
        fflush(g_csv);
        fclose(g_csv);
        g_csv = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return 0;
}

