#define MLX75030_I2C_BUS        "/dev/i2c-1"
#define MLX75030_I2C_ADDR       0x50

#define MLX75030_REG_DISTANCE   0x00
#define MLX75030_REG_CONFIG     0x01

/* Config: 100 ms sample period, 50 Hz update rate, 0.5 m range, no interrupts */
#define MLX75030_CONFIG_VALUE   0x0000

/* ---- Globals ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ---- Signal handler ---- */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ---- Millisecond timestamp ---- */
static void get_timestamp_ms(char *buf, size_t len)
{
    struct timespec ts;
    struct tm tm_info;

    clock_gettime(CLOCK_REALTIME, &ts);
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm_info);
    size_t used = strlen(buf);
    snprintf(buf + used, len - used, ".%03ld", ts.tv_nsec / 1000000L);
}

/* ---- I2C helpers ---- */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s (wrote %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    n = read(fd, out, 1);
    if (n != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    n = read(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C read16 from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

/* ---- Sensor init ---- */
static int mlx75030_init(int fd)
{
    if (i2c_write_reg8(fd, MLX75030_REG_CONFIG, MLX75030_CONFIG_VALUE) != 0) {
        fprintf(stderr, "Failed to configure MLX75030\n");
        return -1;
    }
    return 0;
}

/* ---- Read distance ---- */
static int mlx75030_read_distance(int fd, uint16_t *distance)
{
    for (int attempt = 0; attempt < 3; attempt++) {
        if (i2c_read_reg16(fd, MLX75030_REG_DISTANCE, distance) == 0)
            return 0;

        if (attempt < 2)
            usleep(10000); /* 10 ms backoff */
    }
    return -1;
}

/* ---- Main ---- */
int main(void)
{
    /* Install SIGINT handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(MLX75030_I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", MLX75030_I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the sensor's I2C address */
    if (ioctl(g_i2c_fd, I2C_SLAVE, MLX75030_I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                MLX75030_I2C_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (mlx75030_init(g_i2c_fd) != 0) {
        fprintf(stderr, "MLX75030 initialization failed (sensor may be absent or bus error)\n");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    printf("MLX75030 initialized. Reading distance every 100 ms. Press Ctrl-C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        uint16_t distance = 0;
        char ts[32];

        if (mlx75030_read_distance(g_i2c_fd, &distance) == 0) {
            get_timestamp_ms(ts, sizeof(ts));
            printf("%s Distance: %u mm\n", ts, distance);
            fflush(stdout);
        } else {
            fprintf(stderr, "Failed to read distance after 3 attempts\n");
        }

        usleep(100000); /* 100 ms */
    }

    /* Graceful cleanup */
    printf("\nShutting down...\n");
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return EXIT_SUCCESS;
}

