#define VL53L4CX_REG_SYSTEM_INTERRUPT_CLEAR 0x0001
#define VL53L4CX_REG_RESULT_INTERRUPT_STATUS 0x0014
#define VL53L4CX_REG_RESULT_DISTANCE       0x001E

