/*
 * VL53L1X Time-of-Flight Distance Sensor with Buzzer Alert
 * Board:  Raspberry Pi 4 Model B
 * Bus:    I2C bus 1 (GPIO 2 = SDA, GPIO 3 = SCL)
 * Sensor: VL53L1X
 * Buzzer: GPIO 22 (BCM, active-high)
 *
 * Build:  gcc -O2 -Wall -o vl53l1x_buzzer vl53l1x_buzzer.c -lpigpio -lrt
 * Run:    sudo ./vl53l1x_buzzer
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Configuration ---- */
#define I2C_BUS            1
#define VL53L1X_ADDR       0x60
#define BUZZER_PIN         22
#define DISTANCE_THRESHOLD 100   /* mm */
#define POLL_DELAY_US      500000 /* 500 ms */

/* ---- VL53L1X register addresses ---- */
#define VL53L1X_REG_SOFT_RESET              0x00
#define VL53L1X_REG_I2C_SLAVE_DEVICE_ID     0x010F
#define VL53L1X_REG_SYSTEM_MODE_START       0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS     0x0089
#define VL53L1X_REG_RESULT_DISTANCE        0x0096

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers (16-bit register addressing)                            */
/* ------------------------------------------------------------------ */
static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint32_t len)
{
    char addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, addr, 2) != 0)
        return -1;
    return i2cReadDevice(handle, (char *)buf, len);
}

/* ------------------------------------------------------------------ */
/* VL53L1X initialization                                               */
/* ------------------------------------------------------------------ */
static int vl53l1x_init(int handle)
{
    uint8_t id[8];

    /* 1. Soft reset */
    if (i2c_write_reg16(handle, VL53L1X_REG_SOFT_RESET, 0x00) != 0) {
        fprintf(stderr, "Error: VL53L1X soft reset write failed.\n");
        return -1;
    }
    gpioDelay(1000); /* 1 ms */

    /* 2. Verify device identity */
    if (i2c_read_reg16(handle, VL53L1X_REG_I2C_SLAVE_DEVICE_ID, id, 8) != 8) {
        fprintf(stderr, "Error: Failed to read VL53L1X device ID.\n");
        return -1;
    }
    if (id[0] != 0xEA || id[1] != 0x40) {
        fprintf(stderr, "Error: Unexpected device ID 0x%02X%02X (expected 0xEA 0x40).\n",
                id[0], id[1]);
        return -1;
    }

    /* 3. Start continuous ranging mode */
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_MODE_START, 0x40) != 0) {
        fprintf(stderr, "Error: Failed to start continuous ranging.\n");
        return -1;
    }
    gpioDelay(1000); /* 1 ms */
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read distance in mm; returns -1 on error                          */
/* ------------------------------------------------------------------ */
static int vl53l1x_read_distance(int handle)
{
    uint8_t status;
    uint8_t dist_buf[2];
    int distance;

    /* 1. Check if new ranging data is available */
    if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_RANGE_STATUS, &status, 1) != 1) {
        fprintf(stderr, "Error: Failed to read range status.\n");
        return -1;
    }
    if ((status & 0x01) == 0) {
        /* No new data yet — poll loop will trigger a fresh read */
        return -1;
    }

    /* 2. Read 2-byte distance result */
    if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_DISTANCE, dist_buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read distance data.\n");
        return -1;
    }

    distance = (dist_buf[0] << 8) | dist_buf[1];
    return distance;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        /* Put sensor in standby mode before closing */
        (void)i2c_write_reg16(g_i2c_handle, VL53L1X_REG_SYSTEM_MODE_START, 0x00);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(BUZZER_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int distance;
    bool alert;

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure buzzer pin ---- */
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output.\n", BUZZER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(BUZZER_PIN, 0);

    /* ---- Open I2C bus ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X (code %d).\n",
                I2C_BUS, VL53L1X_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Initialize sensor ---- */
    if (vl53l1x_init(g_i2c_handle) != 0) {
        fprintf(stderr, "Error: VL53L1X initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Register signal handler ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("VL53L1X distance monitoring started. Press Ctrl+C to exit.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        distance = vl53l1x_read_distance(g_i2c_handle);

        if (distance >= 0) {
            alert = (distance < DISTANCE_THRESHOLD);
            if (gpioWrite(BUZZER_PIN, alert ? 1 : 0) != 0) {
                fprintf(stderr, "Warning: Failed to write buzzer pin.\n");
            }
            printf("Distance: %d mm  |  Buzzer: %s\n",
                   distance, alert ? "ON" : "OFF");
        } else {
            fprintf(stderr, "Warning: Distance read failed; skipping cycle.\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

