        fprintf(stderr, "Error: VL53L1X soft reset write failed.\n");
        return -1;
    }
    gpioDelay(1000); /* 1 ms */

    /* 2. Verify device identity */
    if (i2c_read_reg16(handle, VL53L1X_REG_I2C_SLAVE_DEVICE_ID, id, 8) != 8) {
        fprintf(stderr, "Error: Failed to read VL53L1X device ID.\n");
        return -1;
    }
    if (id[0] != 0xEA || id[1] != 0x40) {
        fprintf(stderr, "Error: Unexpected device ID 0x%02X%02X (expected 0xEA 0x40).\n",
                id[0], id[1]);
        return -1;
    }

    /* 3. Start continuous ranging mode */
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_MODE_START, 0x40) != 0) {
        fprintf(stderr, "Error: Failed to start continuous ranging.\n");
        return -1;
    }
    gpioDelay(1000); /* 1 ms */
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read distance in mm; returns -1 on error                          */
/* ------------------------------------------------------------------ */
static int vl53l1x_read_distance(int handle)
{
    uint8_t status;
    uint8_t dist_buf[2];
    int distance;

    /* 1. Check if new ranging data is available */
    if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_RANGE_STATUS, &status, 1) != 1) {
        fprintf(stderr, "Error: Failed to read range status.\n");
        return -1;
    }
    if ((status & 0x01) == 0) {
        /* No new data yet — poll loop will trigger a fresh read */
        return -1;
    }

    /* 2. Read 2-byte distance result */
    if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_DISTANCE, dist_buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read distance data.\n");
        return -1;
    }

    distance = (dist_buf[0] << 8) | dist_buf[1];
    return distance;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        /* Put sensor in standby mode before closing */
        (void)i2c_write_reg16(g_i2c_handle, VL53L1X_REG_SYSTEM_MODE_START, 0x00);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(BUZZER_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int distance;
    bool alert;

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure buzzer pin ---- */
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output.\n", BUZZER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(BUZZER_PIN, 0);

    /* ---- Open I2C bus ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X (code %d).\n",
                I2C_BUS, VL53L1X_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Initialize sensor ---- */
    if (vl53l1x_init(g_i2c_handle) != 0) {
        fprintf(stderr, "Error: VL53L1X initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Register signal handler ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("VL53L1X distance monitoring started. Press Ctrl+C to exit.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        distance = vl53l1x_read_distance(g_i2c_handle);

        if (distance >= 0) {
            alert = (distance < DISTANCE_THRESHOLD);
            if (gpioWrite(BUZZER_PIN, alert ? 1 : 0) != 0) {
                fprintf(stderr, "Warning: Failed to write buzzer pin.\n");
            }
            printf("Distance: %d mm  |  Buzzer: %s\n",
                   distance, alert ? "ON" : "OFF");
        } else {
            fprintf(stderr, "Warning: Distance read failed; skipping cycle.\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

code:
/*
 * Parking Assist System - Raspberry Pi 4 Model B
 * HC-SR04 Ultrasonic Sensor + SG90 Servo
 *
 * Wiring:
 *   HC-SR04 TRIG -> GPIO 23 (BCM)
 *   HC-SR04 ECHO -> GPIO 24 (BCM) [use voltage divider if ECHO is 5V]
 *   SG90 Signal  -> GPIO 17 (BCM)
 *   SG90 VCC     -> 5V, GND -> GND
 *
 * Build: gcc -Wall -Wextra -O2 -o parking_assist parking_assist.c -lpigpio -lrt
 * Run:   sudo ./parking_assist
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      23
#define ECHO_PIN         24
#define SERVO_PIN        17

#define SPEED_OF_SOUND   34300.0          /* cm/s at ~20 °C */
#define MIN_DISTANCE_CM  2.0
#define MAX_DISTANCE_CM  400.0
#define MIN_ANGLE        -90.0
#define MAX_ANGLE        90.0
#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US  50000             /* 50 ms */
#define LOOP_DELAY_US    200000            /* 200 ms */
#define LOG_FILE         "sensor_data.log"

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Distance measurement via pigpio                                  */
/* ------------------------------------------------------------------ */
/*
 * Returns distance in cm, or -1.0 on timeout / error.
 * Uses gpioTrigger() for the 10 µs trigger pulse and gpioRead() for the
 * echo pulse width.  The echo pulse is read until the line goes low
 * again (timeout if it stays high too long).
 */
static float measure_distance(void)
{
    uint32_t start_tick, end_tick, timeout_tick;

    /* Issue 10 µs trigger pulse */
    if (gpioTrigger(TRIGGER_PIN, TRIGGER_PULSE_US, 1) < 0) {
        fprintf(stderr, "Error: gpioTrigger failed on TRIGGER_PIN %d\n", TRIGGER_PIN);
        return -1.0;
    }

    /* Wait for echo to go high (start of pulse) */
    timeout_tick = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: echo start timeout (sensor absent or wiring fault)\n");
            return -1.0;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo to go low (end of pulse) */
    timeout_tick = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: echo end timeout (sensor timeout)\n");
            return -1.0;
        }
    }
    end_tick = gpioTick();

    uint32_t pulse_us = end_tick - start_tick;
    float distance = (pulse_us * SPEED_OF_SOUND) / 2000000.0;

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        fprintf(stderr, "Warning: distance %.2f cm out of range [%.0f-%.0f]\n",
                distance, MIN_DISTANCE_CM, MAX_DISTANCE_CM);
        return -1.0;
    }
    return distance;
}

/* ------------------------------------------------------------------ */
/* Servo control via pigpio                                     */
/* ------------------------------------------------------------------ */
static int set_servo_angle(float angle)
{
    if (angle < MIN_ANGLE) angle = MIN_ANGLE;
    if (angle > MAX_ANGLE) angle = MAX_ANGLE;

    /* SG90: 0° = 500 µs, 180° = 2500 µs, linear interpolation */
    int pulse_us = (int)(500 + (angle / 90.0) * 2000);
    if (gpioServo(SERVO_PIN, pulse_us) < 0) {
        fprintf(stderr, "Error: gpioServo failed on SERVO_PIN %d\n", SERVO_PIN);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(float distance)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[64];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s, Distance: %.2f cm\n", ts, distance);
    } else {
        fprintf(fp, "(no timestamp), Distance: %.2f cm\n", distance);
    }

    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Stop servo pulses */
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for TRIGGER_PIN %d\n", TRIGGER_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for ECHO_PIN %d\n", ECHO_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for SERVO_PIN %d\n", SERVO_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(1000);  /* 1 ms settle */

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Error: sigaction failed");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Parking Assist System started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float distance = measure_distance();

        if (distance > 0.0) {
            log_data(distance);
            set_servo_angle(distance);
        } else {
            fprintf(stderr, "Warning: sensor read failed, skipping cycle\n");
        }

        gpioDelay(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

