/*
 * VL53L1X Time-of-Flight Distance Sensor with Buzzer Alert
 * Board:  Raspberry Pi 3 Model B+
 * Bus:    I2C bus 1 (GPIO2 = SDA, GPIO3 = SCL)
 * Sensor: VL53L1X
 * Buzzer: GPIO23 (BCM)
 *
 * Build:  gcc -O2 -Wall -o vl53l1x_buzzer vl53l1x_buzzer.c -lpigpio -lrt
 * Run:    sudo ./vl53l1x_buzzer
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/ipc.h>
#include <sys/msg.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS          "/dev/i2c-1"
#define VL53L1X_ADDR     0x60
#define BUZZER_GPIO       23
#define DISTANCE_THRESHOLD 100
#define MSG_QUEUE_NAME   "/vl53l1x_queue"
#define POLL_DELAY_US     50000   /* 50 ms */
#define MEASURE_DELAY_US  100000  /* 100 ms timing budget */

/* VL53L1X register addresses */
#define VL53L1X_REG_SOFT_RESET              0x00
#define VL53L1X_REG_I2C_SLAVE_DEVICE_ID     0x010F
#define VL53L1X_REG_SYSTEM_MODE_START       0x0000
#define VL53L1X_REG_RESULT_INTERRUPT_STATUS 0x0014
#define VL53L1X_REG_RESULT_DISTANCE         0x0096
#define VL53L1X_REG_RESULT_RANGE_STATUS     0x0089

#define VL53L1X_EXPECTED_ID 0xEA

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static int g_msg_id = -1;
static int g_gpio_ready = 0;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint16_t reg, uint8_t value)
{
    uint8_t buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;

    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "I2C write to reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint16_t reg, uint8_t *value)
{
    uint8_t addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;

    if (write(fd, addr, 2) != 2) {
        fprintf(stderr, "I2C write (addr) to reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint16_t reg, uint16_t *value)
{
    uint8_t addr[2];
    uint8_t buf[2];

    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;

    if (write(fd, addr, 2) != 2) {
        fprintf(stderr, "I2C write (addr) to reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read16 from reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *value = (buf[0] << 8) | buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* VL53L1X driver                                                      */
/* ------------------------------------------------------------------ */
static int vl53l1x_init(int fd)
{
    uint8_t id = 0;

    if (i2c_read_reg8(fd, VL53L1X_REG_I2C_SLAVE_DEVICE_ID, &id) != 0)
        return -1;

    if (id != VL53L1X_EXPECTED_ID) {
        fprintf(stderr, "VL53L1X device ID mismatch: got 0x%02X, expected 0x%02X\n",
                id, VL53L1X_EXPECTED_ID);
        return -1;
    }

    /* Soft reset */
    if (i2c_write_reg8(fd, VL53L1X_REG_SOFT_RESET, 0x00) != 0)
        return -1;
    gpioDelay(1000); /* 1 ms */

    /* Start continuous ranging */
    if (i2c_write_reg8(fd, VL53L1X_REG_SYSTEM_MODE_START, 0x40) != 0)
        return -1;

    return 0;
}

static int vl53l1x_read_distance(int fd, uint16_t *distance_mm)
{
    uint8_t status = 0;
    uint16_t raw = 0;

    /* Check if new data is available */
    if (i2c_read_reg8(fd, VL53L1X_REG_RESULT_INTERRUPT_STATUS, &status) != 0)
        return -1;

    if ((status & 0x01) == 0)
        return 1; /* No new data yet */

    /* Read distance */
    if (i2c_read_reg16(fd, VL53L1X_REG_RESULT_DISTANCE, &raw) != 0)
        return -1;

    *distance_mm = raw;

    /* Clear interrupt by writing to the status register */
    if (i2c_write_reg8(fd, VL53L1X_REG_RESULT_INTERRUPT_STATUS, 0x01) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Message queue                                                      */
/* ------------------------------------------------------------------ */
static int msg_queue_init(void)
{
    key_t key = ftok(MSG_QUEUE_NAME, 0);
    if (key == (key_t)-1) {
        perror("ftok");
        return -1;
    }

    g_msg_id = msgget(key, IPC_CREAT | 0666);
    if (g_msg_id == (int)-1) {
        perror("msgget");
        return -1;
    }
    return 0;
}

static int msg_queue_send(const char *msg)
{
    if (msg == NULL) {
        msg = strdup("null");
        if (msg == NULL) {
            perror("strdup");
            return -1;
        }
    }

    struct msghdr m;
    struct msgbuf *mb = NULL;

    memset(&m, 0, sizeof(m));
    mb = (struct msgbuf *)malloc(sizeof(struct msgbuf));
    if (mb == NULL) {
        perror("malloc");
        return -1;
    }

    mb->msg_type = 1;
    mb->msg_len = (size_t)strlen(msg);
    memcpy(mb->msg_ptr, msg, mb->msg_len);

    m.msg_type = 1;
    m.msg_io_flg = MSG_WRONLY;
    m.msg_cur = mb;
    m.msg_len = sizeof(struct msgbuf);

    if (msgsnd(g_msg_id, &m, mb->msg_len, IPC_NOWAIT) == -1) {
        perror("msgsnd");
        free(mb);
        return -1;
    }

    free(mb);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_fd != -1) {
        i2cClose(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_msg_id != -1) {
        if (msgctl(g_msg_id, IPC_RMID, NULL) == -1)
            perror("msgctl(IPC_RMID)");
        g_msg_id = -1;
    }
    if (g_gpio_ready) {
        gpioWrite(BUZZER_GPIO, 0);
        gpioTerminate();
        g_gpio_ready = 0;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }
    g_gpio_ready = 1;

    if (gpioSetMode(BUZZER_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", BUZZER_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(BUZZER_GPIO, 0);

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd == -1) {
        perror("open I2C bus");
        cleanup();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, VL53L1X_ADDR) == -1) {
        perror("ioctl I2C_SLAVE");
        cleanup();
        return EXIT_FAILURE;
    }

    if (vl53l1x_init(g_i2c_fd) != 0) {
        fprintf(stderr, "VL53L1X initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (msg_queue_init() != 0) {
        fprintf(stderr, "Message queue initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("VL53L1X distance sensor running. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t distance = 0;
        int rc = vl53l1x_read_distance(g_i2c_fd, &distance);

        if (rc == 0) {
            char msg[32];
            snprintf(msg, sizeof(msg), "Distance: %u mm", distance);
            if (msg_queue_send(msg) != 0)
                fprintf(stderr, "Failed to send message\n");
            if (distance < DISTANCE_THRESHOLD)
                gpioWrite(BUZZER_GPIO, 1);
            else
                gpioWrite(BUZZER_GPIO, 0);
        } else if (rc < 0) {
            fprintf(stderr, "I2C read error, attempting re-init...\n");
            if (vl53l1x_init(g_i2c_fd) != 0)
                fprintf(stderr, "Re-init failed, retrying in 1 s...\n");
            gpioDelay(1000000);
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

