/*
 * Parking sensor using HC-SR04 ultrasonic sensor on Raspberry Pi 3 Model B+.
 *
 * Wiring:
 *   HC-SR04 VCC  -> 5V  (pin 2)
 *   HC-SR04 GND  -> GND (pin 6)
 *   HC-SR04 TRIG -> GPIO17 (BCM, pin 11)
 *   HC-SR04 ECHO -> GPIO27 (BCM, pin 13)
 *   Buzzer      -> GPIO22 (BCM, pin 15)
 *
 * Build:  gcc -O2 -Wall -Wextra -o parking_sensor parking_sensor.c -lpigpio -lrt
 * Run:    sudo ./parking_sensor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      17
#define ECHO_PIN         27
#define BUZZER_PIN       22

#define SPEED_OF_SOUND   34300.0          /* cm/s at 20 °C */
#define MIN_DISTANCE_CM  2.0
#define MAX_DISTANCE_CM  400.0
#define BUZZER_THRESHOLD_CM 30.0
#define TIMEOUT_US       30000            /* 30 ms timeout for echo */
#define LOOP_DELAY_US    100000           /* 100 ms between measurements */
#define TRIGGER_PULSE_US 10

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */
static int safe_set_mode(unsigned pin, unsigned mode)
{
    if (gpioSetMode(pin, mode) < 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, %u) failed\n", pin, mode);
        return -1;
    }
    return 0;
}

static int safe_write(unsigned pin, unsigned level)
{
    if (gpioWrite(pin, level) < 0) {
        fprintf(stderr, "Error: gpioWrite(%u, %u) failed\n", pin, level);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* HC-SR04 measurement                                                */
/* ------------------------------------------------------------------ */
/*
 * Returns:
 *   >= 0  : distance in cm (valid if `ok` is true)
 *   -1.0  : timeout (no echo received)
 *   -2.0  : out-of-range (distance < MIN_DISTANCE_CM or > MAX_DISTANCE_CM)
 *   -3.0  : GPIO write error
 */
static double measure_distance(void)
{
    /* Ensure trigger starts LOW */
    if (safe_write(TRIGGER_PIN, 0) < 0)
        return -3.0;

    /* 10 µs trigger pulse */
    if (safe_write(TRIGGER_PIN, 1) < 0)
        return -3.0;
    gpioDelay(TRIGGER_PULSE_US);
    if (safe_write(TRIGGER_PIN, 0) < 0)
        return -3.0;

    uint32_t start_tick = 0, end_tick = 0;
    int      echo_state = 0;   /* 0 = waiting for rising edge, 1 = waiting for falling edge */

    /* Wait for echo rising edge (timeout) */
    for (;;) {
        int v = gpioRead(ECHO_PIN);
        if (v < 0) {
            return -3.0;
        }
        if (v == 1 && echo_state == 0) {
            echo_state = 1;
            start_tick = gpioTick();
            break;
        }
        if (echo_state == 1) {
            gpioDelay(100);       /* yield CPU */
        }
    }

    /* Wait for echo falling edge (timeout) */
    for (;;) {
        int v = gpioRead(ECHO_PIN);
        if (v < 0) {
            return -3.0;
        }
        if (v == 0 && echo_state == 1) {
            echo_state = 0;
            end_tick = gpioTick();
            break;
        }
        if (echo_state == 0) {
            gpioDelay(100);
        }
    }

    /* pigpio ticks are 32-bit microseconds; handle wraparound */
    uint32_t diff = end_tick - start_tick;   /* correct even across wrap */

    double distance = (diff * SPEED_OF_SOUND) / 2000000.0;

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        return -2.0;
    }

    return distance;
}

/* ------------------------------------------------------------------ */
/* Buzzer control                                                      */
/* ------------------------------------------------------------------ */
static void control_buzzer(double distance)
{
    if (distance < BUZZER_THRESHOLD_CM) {
        safe_write(BUZZER_PIN, 1);
    } else {
        safe_write(BUZZER_PIN, 0);
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins --- */
    if (safe_set_mode(TRIGGER_PIN, PI_OUTPUT) < 0 ||
        safe_set_mode(ECHO_PIN, PI_INPUT)   < 0 ||
        safe_set_mode(BUZZER_PIN, PI_OUTPUT) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure known initial states */
    safe_write(TRIGGER_PIN, 0);
    safe_write(BUZZER_PIN, 0);

    /* --- Register signal handler for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    printf("Parking sensor running. Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        double distance = measure_distance();

        if (distance < 0.0) {
            if (distance == -1.0) {
                fprintf(stderr, "Warning: no echo received (sensor absent or wiring fault)\n");
            } else if (distance == -2.0) {
                fprintf(stderr, "Warning: distance out of range (%.2f cm)\n", distance);
            } else {
                fprintf(stderr, "Warning: GPIO write error\n");
            }
            control_buzzer(-1.0);   /* ensure buzzer off on error */
        } else {
            printf("Distance: %.2f cm\n", distance);
            control_buzzer(distance);
        }

        gpioDelay(LOOP_DELAY_US);
    }

    /* --- Clean shutdown --- */
    safe_write(BUZZER_PIN, 0);
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

