    /* pigpio ticks are 32-bit microseconds; handle wraparound */
    uint32_t diff = end_tick - start_tick;   /* correct even across wrap */

    double distance = (diff * SPEED_OF_SOUND) / 2000000.0;

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        return -2.0;
    }

    return distance;
}

/* ------------------------------------------------------------------ */
/* Buzzer control                                                      */
/* ------------------------------------------------------------------ */
static void control_buzzer(double distance)
{
    if (distance < BUZZER_THRESHOLD_CM) {
        safe_write(BUZZER_PIN, 1);
    } else {
        safe_write(BUZZER_PIN, 0);
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins --- */
    if (safe_set_mode(TRIGGER_PIN, PI_OUTPUT) < 0 ||
        safe_set_mode(ECHO_PIN, PI_INPUT)   < 0 ||
        safe_set_mode(BUZZER_PIN, PI_OUTPUT) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure known initial states */
    safe_write(TRIGGER_PIN, 0);
    safe_write(BUZZER_PIN, 0);

    /* --- Register signal handler for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    printf("Parking sensor running. Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        double distance = measure_distance();

        if (distance < 0.0) {
            if (distance == -1.0) {
                fprintf(stderr, "Warning: no echo received (sensor absent or wiring fault)\n");
            } else if (distance == -2.0) {
                fprintf(stderr, "Warning: distance out of range (%.2f cm)\n", distance);
            } else {
                fprintf(stderr, "Warning: GPIO write error\n");
            }
            control_buzzer(-1.0);   /* ensure buzzer off on error */
        } else {
            printf("Distance: %.2f cm\n", distance);
            control_buzzer(distance);
        }

        gpioDelay(LOOP_DELAY_US);
    }

    /* --- Clean shutdown --- */
    safe_write(BUZZER_PIN, 0);
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

