/*
 * HC-SR04 ultrasonic distance measurement on Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   TRIG -> GPIO 23 (physical pin 16, BCM 23, output)
 *   ECHO -> GPIO 24 (physical pin 18, BCM 24, input, 5 V level-shifter/divider needed)
 *   VCC  -> 5 V, GND -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o hcsr04 hcsr04.c -lpigpio -lrt
 * Run:    sudo ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TRIG_PIN      23
#define ECHO_PIN      24

#define TRIG_PULSE_US 10          /* HC-SR04 trigger pulse width            */
#define SAMPLE_PERIOD_US 200000   /* 5 Hz sampling interval                */
#define ECHO_TIMEOUT_US 30000     /* HC-SR04 max echo wait (~30 m)          */
#define MIN_PULSE_US    100       /* noise / spurious pulse filter          */
#define MAX_PULSE_US    30000     /* HC-SR04 max echo wait (~30 m)          */
#define ECHO_TIMEOUT_MS 60        /* no-echo timeout                         */

/* ------------------------------------------------------------------ */
/* Shared state between callback and main thread                     */
/* ------------------------------------------------------------------ */

static volatile uint32_t g_rising_tick = 0;
static volatile uint32_t g_falling_tick = 0;
static volatile bool     g_echo_seen   = false;
static volatile bool     g_running     = true;

static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = false;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper (microseconds)                                   */
/* ------------------------------------------------------------------ */

static uint32_t now_us(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        return 0;
    }
    return (uint32_t)ts.tv_sec * 1000U + (uint32_t)(ts.tv_nsec / 1000000U);
}

/* ------------------------------------------------------------------ */
/* Alert callback — runs in pigpio thread                               */
/* ------------------------------------------------------------------ */

static void echo_alert(int gpio, int level, uint32_t tick)
{
    (void)gpio;

    if (level == 1) {
        /* Rising edge */
        g_rising_tick = tick;
        g_echo_seen   = false;
    } else if (level == 0) {
        /* Falling edge */
        g_falling_tick = tick;
        g_echo_seen   = true;
    }
    /* level == 2 (timeout) is ignored here */
}

/* ------------------------------------------------------------------ */
/* Distance calculation                                               */
/* ------------------------------------------------------------------ */

static double calculate_distance(uint32_t rising_tick, uint32_t falling_tick)
{
    uint32_t pulse_us = falling_tick - rising_tick;          /* wraps correctly on 32-bit tick */

    if (pulse_us < MIN_PULSE_US) {
        fprintf(stderr, "[WARN] Pulse too short (%u us) — noise/spurious\n",
                pulse_us);
        return -1.0;
    }
    if (pulse_us > MAX_PULSE_US) {
        fprintf(stderr, "[WARN] Pulse too long (%u us) — out of range\n",
                pulse_us);
        return -1.0;
    }

    /* distance = (pulse_us * speed_of_sound) / 2 */
    return (double)pulse_us * 0.0343 / 2.0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */

static void log_distance(double distance)
{
    time_t     rawtime;
    struct tm  timeinfo;
    char       timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    printf("[%s] Distance: %.2f m\n", timestamp, distance);

    if (g_log_file) {
        fprintf(g_log_file, "%s,%.2f\n", timestamp, distance);
        fflush(g_log_file);
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */

static void cleanup(void)
{
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- GPIO configuration ---- */
    if (gpioSetMode(TRIG_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "[FATAL] Failed to set TRIG_PIN %d as output\n", TRIG_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "[FATAL] Failed to set ECHO_PIN %d as input\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "[WARN] Failed to set pull-down on ECHO_PIN %d\n", ECHO_PIN);
    }

    /* Ensure trigger starts LOW */
    if (gpioWrite(TRIG_PIN, 0) != 0) {
        fprintf(stderr, "[FATAL] Failed to initialise TRIG_PIN %d LOW\n", TRIG_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_file = fopen("distance_log.txt", "a");
    if (!g_log_file) {
        perror("[FATAL] fopen distance_log.txt");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Register alert callback ---- */
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_alert, NULL) != 0) {
        fprintf(stderr, "[FATAL] Failed to register alert on ECHO_PIN %d\n", ECHO_PIN);
        fclose(g_log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[WARN] sigaction");
    }

    printf("HC-SR04 distance measurement started.\n");
    printf("  TRIG: GPIO %d | ECHO: GPIO %d | Log: distance_log.txt\n",
           TRIG_PIN, ECHO_PIN);
    printf("  Press Ctrl+C to exit.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        /* Reset echo state before triggering */
        g_echo_seen   = false;
        g_rising_tick = 0;
        g_falling_tick = 0;

        /* Issue 10 µs trigger pulse */
        if (gpioWrite(TRIG_PIN, 1) != 0) {
            fprintf(stderr, "[WARN] gpioWrite TRIG high failed\n");
        }
        gpioDelay(TRIG_PULSE_US);
        if (gpioWrite(TRIG_PIN, 0) != 0) {
            fprintf(stderr, "[WARN] gpioWrite TRIG low failed\n");
        }

        /* Wait for falling edge with timeout */
        uint32_t start_wait = now_us();
        while (!g_echo_seen && g_running) {
            if (now_us() - start_wait > ECHO_TIMEOUT_US) {
                fprintf(stderr, "[WARN] Echo timeout — no object within %d us\n",
                        ECHO_TIMEOUT_US);
                break;
            }
            gpioDelay(100);  /* poll every 100 µs */
        }

        if (!g_running) {
            break;
        }

        if (g_echo_seen) {
            uint32_t rising = g_rising_tick;
            uint32_t falling = g_falling_tick;
            double distance = calculate_distance(rising, falling);
            if (distance >= 0.0) {
                log_distance(distance);
            }
        }
    }

    /* ---- Cleanup ---- */
    printf("\nShutting down...\n");
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);  /* unregister callback */
    gpioWrite(TRIG_PIN, 0);
    cleanup();
    return EXIT_SUCCESS;
}

