code:
/*
 * Smart Parking Gate - Raspberry Pi 4 Model B
 * Sensor : VL53L1X Time-of-Flight (I2C bus 1, shutdown on GPIO23, interrupt on GPIO24)
 * Actuator: Servo motor on hardware PWM (GPIO18)
 * Log    : parking_log.txt
 *
 * Build  : gcc -O2 -Wall -o parking_gate parking_gate.c -lpigpio -lrt
 * Run    : sudo ./parking_gate
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define VL53L1X_ADDR         0x29
#define VL53L1X_SHUTDOWN_PIN 23   /* BCM GPIO 23 */
#define VL53L1X_INT_PIN     24   /* BCM GPIO 24 */
#define SERVO_PIN           18   /* BCM GPIO 18 (hardware PWM) */

#define DISTANCE_THRESHOLD_CLOSE 50.0f   /* cm - open gate */
#define DISTANCE_THRESHOLD_CLOSE_2 60.0f /* cm - close gate */
#define LOG_FILE              "parking_log.txt"

/* VL53L1X register addresses */
#define VL53L1X_REG_SOFT_RESET              0x0000
#define VL53L1X_REG_I2C_SLAVE_DEVICE_ID     0x010F
#define VL53L1X_REG_SYSTEM_MODE_START       0x0000
#define VL53L1X_REG_RESULT_INTERRUPT_STATUS 0x0089
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK  0x0096
#define VL53L1X_REG_RESULT_DISTANCE        0x0096

/* Expected model IDs */
#define VL53L1X_MODEL_ID_EXPECTED 0xEA

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;

/* ----------------------------- Prototypes -------------------------------- */
static int  vl53l1x_write16(int handle, uint16_t reg, uint8_t value);
static int  vl53l1x_read16(int handle, uint16_t reg, uint8_t *buf, uint32_t len);
static int  vl53l1x_init(int handle);
static int  vl53l1x_read_distance(int handle, float *distance_cm);
static void log_event(const char *event, float distance);
static void signal_handler(int sig);
static void cleanup(void);

/* ----------------------------- VL53L1X helpers ---------------------------- */

/*
 * Write a single byte to a 16-bit VL53L1X register.
 * pigpio i2cWriteI2CBlockData sends the 2-byte address + 1-byte data as a
 * single I2C block, which the VL53L1X expects (MSB first).
 */
static int vl53l1x_write16(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;

    if (i2cWriteI2CBlockData(handle, buf[0], &buf[1], 1) < 0) {
        fprintf(stderr, "[VL53L1X] write16 failed at reg 0x%04X\n", reg);
        return -1;
    }
    return 0;
}

/*
 * Read `len` bytes from a 16-bit VL53L1X register.
 * i2cReadI2CBlockData sends the 2-byte address, then reads `len` bytes.
 */
static int vl53l1x_read16(int handle, uint16_t reg, uint8_t *buf, uint32_t len)
{
    char addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;

    if (i2cWriteI2CBlockData(handle, addr[0], &addr[1], 1) < 0) {
        fprintf(stderr, "[VL53L1X] read16: failed to set register address 0x%04X\n", reg);
        return -1;
    }
    if (i2cReadI2CBlockData(handle, addr[0], (char *)buf, len) < 0) {
        fprintf(stderr, "[VL53L1X] read16: failed to read %u bytes from 0x%04X\n", len, reg);
        return -1;
    }
    return 0;
}

/*
 * Initialize the VL53L1X sensor.
 * Returns 0 on success, -1 on failure.
 */
static int vl53l1x_init(int handle)
{
    uint8_t id_buf[2] = {0};

    /* 1. Soft reset */
    if (vl53l1x_write16(handle, VL53L1X_REG_SOFT_RESET, 0x00) < 0)
        return -1;
    gpioDelay(1000); /* 1 ms */

    if (vl53l1x_write16(handle, VL53L1X_REG_SOFT_RESET, 0x01) < 0)
        return -1;
    gpioDelay(1000);

    /* 2. Verify model ID */
    if (vl53l1x_read16(handle, VL53L1X_REG_I2C_SLAVE_DEVICE_ID, id_buf, 2) < 0)
        return -1;

    uint16_t model_id = (id_buf[0] << 8) | id_buf[1];
    if (model_id != VL53L1X_MODEL_ID_EXPECTED) {
        fprintf(stderr, "[VL53L1X] unexpected model ID 0x%04X (expected 0x%04X)\n",
                model_id, VL53L1X_MODEL_ID_EXPECTED);
        return -1;
    }

    /* 3. Start ranging (mode 1) */
    if (vl53l1x_write16(handle, VL53L1X_REG_SYSTEM_MODE_START, 0x40) < 0)
        return -1;

    gpioDelay(1000); /* 1 ms settle */
    return 0;
}

/*
 * Read the distance in centimetres from the VL53L1X.
 * Returns 0 on success and stores the distance in *distance_cm;
 * returns -1 on I2C error.
 */
static int vl53l1x_read_distance(int handle, float *distance_cm)
{
    uint8_t status_buf[1] = {0};
    uint8_t dist_buf[2]  = {0};

    /* 1. Check if a new measurement is ready */
    if (vl53l1x_read16(handle, VL53L1X_REG_RESULT_INTERRUPT_STATUS, status_buf, 1) < 0)
        return -1;

    if (!(status_buf[0] & 0x01)) {
        /* No new data yet - wait briefly and retry */
        gpioDelay(1000);
        return -1;
    }

    /* 2. Read the distance */
    if (vl53l1x_read16(handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK, dist_buf, 2) < 0)
        return -1;

    uint16_t raw = (dist_buf[0] << 8) | dist_buf[1];
    *distance_cm = (float)raw / 10.0f;
    return 0;
}

/* ----------------------------- Logging ----------------------------------- */
static void log_event(const char *event, float distance)
{
