    if (vl53l1x_read16(handle, VL53L1X_REG_RESULT_INTERRUPT_STATUS, status_buf, 1) < 0)
        return -1;

    if (!(status_buf[0] & 0x01)) {
        /* No new data yet - wait briefly and retry */
        gpioDelay(1000);
        return -1;
    }

    /* 2. Read the distance */
    if (vl53l1x_read16(handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK, dist_buf, 2) < 0)
        return -1;

    uint16_t raw = (dist_buf[0] << 8) | dist_buf[1];
