    /* Open I2C bus 1 at address 0x29 */
    int i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X (err %d)\n",
                I2C_BUS, VL53L1X_ADDR, i2c_handle);
