        return EXIT_FAILURE;
    }

    /* Configure shutdown pin as output, default HIGH (deselected) */
    gpioSetMode(VL53L1X_SHUTDOWN_PIN, PI_OUTPUT);
    gpioWrite(VL53L1X_SHUTDOWN_PIN, 1);

    /* Configure interrupt pin as input */
