/*
 * VL53L1X Time-of-Flight Distance Sensor with Motor Control
 * Board:  Raspberry Pi 4 Model B
 * Library: pigpio (I2C + GPIO)
 *
 * Wiring:
 *   VL53L1X SDA -> GPIO2  (I2C bus 1 SDA)
 *   VL53L1X SCL -> GPIO3  (I2C bus 1 SCL)
 *   VL53L1X VDD -> 3.3 V
 *   VL53L1X GND -> GND
 *   Motor FWD  -> GPIO17
 *   Motor REV  -> GPIO18
 *   Distance  -> GPIO24 (rising edge triggers a read)
 *
 * Build:  gcc -O2 -Wall -o vl53l1x_motor vl53l1x_motor.c -lpigpio -lrt
 * Run:    sudo ./vl53l1x_motor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Pin / I2C / sensor definitions ---- */
#define I2C_BUS            1
#define I2C_ADDR           0x60      /* VL53L1X default 7-bit address */
#define DISTANCE_PIN       24        /* Rising edge on this pin triggers a read */
#define FWD_PIN            17
#define REV_PIN            18

#define THRESHOLD_CLOSE    100       /* mm  - run forward below this */
#define THRESHOLD_FAR      300       /* mm  - run backward above this */
#define POLL_TIMEOUT_US    100000    /* 100 ms max wait for data-ready */

/* VL53L1X register addresses */
#define VL53L1X_REG_SOFT_RESET              0x00
#define VL53L1X_REG_SYSTEM_START            0x01
#define VL53L1X_REG_RESULT_RANGE_STATUS     0x00
#define VL53L1X_REG_RESULT_DISTANCE         0x14
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR  0x00
#define VL53L1X_REG_SYSTEM_INTERRUPT       0x01

/* ---- Globals ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ---- Prototypes ---- */
static void signal_handler(int sig);
static void distance_isr(int gpio, int level, uint32_t tick, void *userdata);
static int  i2c_write_reg8(int handle, uint8_t reg, uint8_t val);
static int  i2c_read_reg8(int handle, uint8_t reg, uint8_t *val);
static int  i2c_read_reg16(int handle, uint8_t reg, uint16_t *val);
static int  vl53l1x_init(int handle);
static int  vl53l1x_read_distance(int handle, uint16_t *distance_mm);
static void motor_forward(void);
static void motor_backward(void);
static void motor_stop(void);
static void cleanup(void);

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- ISR: rising edge on DISTANCE_PIN triggers a read ---- */
static void distance_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio; (void)level; (void)tick; (void)userdata;

    uint16_t distance = 0;
    if (vl53l1x_read_distance(g_i2c_handle, &distance) == 0) {
        printf("Distance: %u mm\n", distance);
        fflush(stdout);

        if (distance < THRESHOLD_CLOSE) {
            motor_forward();
        } else if (distance > THRESHOLD_FAR) {
            motor_backward();
        } else {
            motor_stop();
        }
    } else {
        fprintf(stderr, "Error reading distance (I2C bus error).\n");
    }
}

/* ---- I2C register helpers (exponential backoff) ---- */
static int i2c_write_reg8(int handle, uint8_t reg, uint8_t val)
{
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %d\n",
                reg, val, rc);
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int handle, uint8_t reg, uint8_t *val)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %d\n", reg, rc);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int i2c_read_reg16(int handle, uint8_t reg, uint16_t *val)
{
    int rc = i2cReadWordData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read16 failed (reg 0x%02X): %d\n", reg, rc);
        return -1;
    }
    /* pigpio returns (high<<8)|low; VL53L1X is little-endian */
    *val = (uint16_t)rc;
    return 0;
}

/* ---- VL53L1X initialization ---- */
static int vl53l1x_init(int handle)
{
    /* Soft reset */
    if (i2c_write_reg8(handle, VL53L1X_REG_SOFT_RESET, 0x00) < 0)
        return -1;
    gpioDelay(1000);  /* 1 ms */

    /* Clear any pending interrupt */
    if (i2c_write_reg8(handle, VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0)
        return -1;

    /* Start continuous ranging */
    if (i2c_write_reg8(handle, VL53L1X_REG_SYSTEM_START, 0x40) < 0)
        return -1;

    return 0;
}

/* ---- Read one distance sample ---- */
static int vl53l1x_read_distance(int handle, uint16_t *distance_mm)
{
    uint8_t status = 0;
    int retries = 0;
    const int max_retries = 10;

    /* Poll data-ready bit (bit 0 of RESULT_RANGE_STATUS) */
    while (retries < max_retries) {
        if (i2c_read_reg8(handle, VL53L1X_REG_RESULT_RANGE_STATUS, &status) < 0)
            return -1;
        if (status & 0x01)
            break;
        gpioDelay(1000);  /* 1 ms */
        retries++;
    }

    if (retries >= max_retries) {
        fprintf(stderr, "Timeout waiting for data-ready.\n");
        return -1;
    }

    /* Read 16-bit distance (little-endian) */
    if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_DISTANCE, distance_mm) < 0)
        return -1;

    /* Clear interrupt so the next measurement can be triggered */
    if (i2c_write_reg8(handle, VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0)
        return -1;

    return 0;
}

/* ---- Motor control ---- */
static void motor_forward(void)
{
    gpioWrite(FWD_PIN, 1);
    gpioWrite(REV_PIN, 0);
}

static void motor_backward(void)
{
    gpioWrite(FWD_PIN, 0);
    gpioWrite(REV_PIN, 1);
}

static void motor_stop(void)
{
    gpioWrite(FWD_PIN, 0);
    gpioWrite(REV_PIN, 0);
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    motor_stop();
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ---- Main ---- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at VL53L1X address */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d addr 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (vl53l1x_init(g_i2c_handle) < 0) {
        fprintf(stderr, "VL53L1X initialization failed (sensor absent or bus error).\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure motor pins as outputs */
    gpioSetMode(FWD_PIN, PI_OUTPUT);
    gpioSetMode(REV_PIN, PI_OUTPUT);
    motor_stop();

    /* Configure distance pin as input with pull-down */
    gpioSetMode(DISTANCE_PIN, PI_INPUT);
    gpioSetPullUpDown(DISTANCE_PIN, PI_PUD_DOWN);

    /* Register ISR on rising edge */
    if (gpioSetISRFuncEx(DISTANCE_PIN, RISING_EDGE, 0, distance_isr, NULL) < 0) {
        fprintf(stderr, "Failed to set ISR on GPIO%d.\n", DISTANCE_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("VL53L1X distance sensor running. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        gpioDelay(100000);  /* 100 ms */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

