#define REV_PIN            18

#define THRESHOLD_CLOSE    100       /* mm  - run forward below this */
#define THRESHOLD_FAR      300       /* mm  - run backward above this */
#define POLL_TIMEOUT_US    100000    /* 100 ms max wait for data-ready */

/* VL53L1X register addresses */
#define VL53L1X_REG_SOFT_RESET              0x00
#define VL53L1X_REG_SYSTEM_START            0x01
#define VL53L1X_REG_RESULT_RANGE_STATUS     0x00
#define VL53L1X_REG_RESULT_DISTANCE         0x14
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR  0x00
#define VL53L1X_REG_SYSTEM_INTERRUPT       0x01

/* ---- Globals ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ---- Prototypes ---- */
static void signal_handler(int sig);
static void distance_isr(int gpio, int level, uint32_t tick, void *userdata);
static int  i2c_write_reg8(int handle, uint8_t reg, uint8_t val);
static int  i2c_read_reg8(int handle, uint8_t reg, uint8_t *val);
static int  i2c_read_reg16(int handle, uint8_t reg, uint16_t *val);
static int  vl53l1x_init(int handle);
static int  vl53l1x_read_distance(int handle, uint16_t *distance_mm);
static void motor_forward(void);
static void motor_backward(void);
static void motor_stop(void);
static void cleanup(void);

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- ISR: rising edge on DISTANCE_PIN triggers a read ---- */
static void distance_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio; (void)level; (void)tick; (void)userdata;

    uint16_t distance = 0;
    if (vl53l1x_read_distance(g_i2c_handle, &distance) == 0) {
        printf("Distance: %u mm\n", distance);
        fflush(stdout);

        if (distance < THRESHOLD_CLOSE) {
            motor_forward();
        } else if (distance > THRESHOLD_FAR) {
            motor_backward();
        } else {
            motor_stop();
        }
    } else {
        fprintf(stderr, "Error reading distance (I2C bus error).\n");
    }
}

/* ---- I2C register helpers (exponential backoff) ---- */
static int i2c_write_reg8(int handle, uint8_t reg, uint8_t val)
{
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %d\n",
                reg, val, rc);
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int handle, uint8_t reg, uint8_t *val)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %d\n", reg, rc);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int i2c_read_reg16(int handle, uint8_t reg, uint16_t *val)
{
    int rc = i2cReadWordData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read16 failed (reg 0x%02X): %d\n", reg, rc);
        return -1;
    }
    /* pigpio returns (high<<8)|low; VL53L1X is little-endian */
    *val = (uint16_t)rc;
    return 0;
}

/* ---- VL53L1X initialization ---- */
static int vl53l1x_init(int handle)
{
    /* Soft reset */
    if (i2c_write_reg8(handle, VL53L1X_REG_SOFT_RESET, 0x00) < 0)
        return -1;
    gpioDelay(1000);  /* 1 ms */

    /* Clear any pending interrupt */
    if (i2c_write_reg8(handle, VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0)
        return -1;

    /* Start continuous ranging */
    if (i2c_write_reg8(handle, VL53L1X_REG_SYSTEM_START, 0x40) < 0)
        return -1;

    return 0;
}

/* ---- Read one distance sample ---- */
static int vl53l1x_read_distance(int handle, uint16_t *distance_mm)
{
    uint8_t status = 0;
    int retries = 0;
    const int max_retries = 10;

    /* Poll data-ready bit (bit 0 of RESULT_RANGE_STATUS) */
    while (retries < max_retries) {
        if (i2c_read_reg8(handle, VL53L1X_REG_RESULT_RANGE_STATUS, &status) < 0)
            return -1;
        if (status & 0x01)
            break;
        gpioDelay(1000);  /* 1 ms */
        retries++;
    }

    if (retries >= max_retries) {
        fprintf(stderr, "Timeout waiting for data-ready.\n");
        return -1;
    }

    /* Read 16-bit distance (little-endian) */
    if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_DISTANCE, distance_mm) < 0)
        return -1;

    /* Clear interrupt so the next measurement can be triggered */
    if (i2c_write_reg8(handle, VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0)
        return -1;

    return 0;
}

/* ---- Motor control ---- */
static void motor_forward(void)
{
    gpioWrite(FWD_PIN, 1);
    gpioWrite(REV_PIN, 0);
}

static void motor_backward(void)
{
    gpioWrite(FWD_PIN, 0);
    gpioWrite(REV_PIN, 1);
}

static void motor_stop(void)
{
    gpioWrite(FWD_PIN, 0);
    gpioWrite(REV_PIN, 0);
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    motor_stop();
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ---- Main ---- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at VL53L1X address */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d addr 0x%02X: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (vl53l1x_init(g_i2c_handle) < 0) {
        fprintf(stderr, "VL53L1X initialization failed (sensor absent or bus error).\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure motor pins as outputs */
    gpioSetMode(FWD_PIN, PI_OUTPUT);
    gpioSetMode(REV_PIN, PI_OUTPUT);
    motor_stop();

    /* Configure distance pin as input with pull-down */
    gpioSetMode(DISTANCE_PIN, PI_INPUT);
    gpioSetPullUpDown(DISTANCE_PIN, PI_PUD_DOWN);

    /* Register ISR on rising edge */
    if (gpioSetISRFuncEx(DISTANCE_PIN, RISING_EDGE, 0, distance_isr, NULL) < 0) {
        fprintf(stderr, "Failed to set ISR on GPIO%d.\n", DISTANCE_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("VL53L1X distance sensor running. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        gpioDelay(100000);  /* 100 ms */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

code:
/*
 * Proximity-based interactive art installation for Raspberry Pi 3 Model B+.
 *
 * Hardware:
 *   - MPR121 capacitive touch sensor on I2C bus 1 (/dev/i2c-1)
 *     (GPIO 2 / SDA, GPIO 3 / SCL)
 *   - 4-bit LED pattern on BCM GPIO 17, 18, 27, 22
 *
 * Behavior:
 *   Polls the MPR121 touch status every 50 ms.  When any electrode
 *   detects a touch, drives the LED pattern corresponding to the
 *   electrode number (0-11) and logs the event with a timestamp.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o proximity_art proximity_art.c \
 *       -li2c -lpigpio -lrt
 *
 * Run:
 *   sudo ./proximity_art
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

/* ---- MPR121 constants -------------------------------------------------- */
#define MPR121_ADDR        0x5C
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECONFIG     0x5E
#define MPR121_SOFTRESET     0x80
#define MPR121_TOUCHTH_0     0x41
#define MPR121_RELEASETH_0  0x42
#define MPR121_MHDR          0x2B
#define MPR121_NHDR          0x2C
#define MPR121_NCLR          0x2D
#define MPR121_FDLR          0x2E
#define MPR121_MHDF          0x2F
#define MPR121_NHDF          0x30
#define MPR121_NCLF          0x31
#define MPR121_FDLF          0x32
#define MPR121_NHDT          0x33
#define MPR121_NCLT          0x34
#define MPR121_FDLT          0x35

#define I2C_BUS             "/dev/i2c-1"
#define GPIO_LED0            17
#define GPIO_LED1            18
#define GPIO_LED2            27
#define GPIO_LED3            22
#define NUM_ELECTRODES       12
#define POLL_DELAY_US        50000   /* 50 ms */
#define LOG_FILE             "proximity_art.log"

/* ---- Globals ---------------------------------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd   = -1;
static FILE *g_log_fp  = NULL;

/* ---- Prototypes ------------------------------------------------------- */
static void signal_handler(int sig);
static int  mpr121_write(uint8_t reg, uint8_t val);
static int  mpr121_read(uint8_t reg, uint8_t *val);
static int  mpr121_init(void);
static int  mpr121_read_touch(uint16_t *status);
static void led_pattern(uint8_t num);
static void log_event(uint8_t num);
static void cleanup(void);

/* ------------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------------ */
static int mpr121_write(uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(g_i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------------ */
static int mpr121_read(uint8_t reg, uint8_t *val)
{
    if (write(g_i2c_fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(g_i2c_fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------------ */
static int mpr121_init(void)
{
    /* Soft reset */
    if (mpr121_write(MPR121_SOFTRESET, 0x63) < 0)
        return -1;
    usleep(1000);

    /* Probe: read back the MPR121 address after reset */
    uint8_t probe;
    if (mpr121_read(MPR121_ADDR, &probe) < 0)
        return -1;
    if (probe != MPR121_ADDR) {
        fprintf(stderr, "MPR121 not detected at 0x%02X (got 0x%02X)\n",
                MPR121_ADDR, probe);
        return -1;
    }

    /* Baseline filter settings (rising/falling) */
    if (mpr121_write(MPR121_MHDR, 0x01) < 0) return -1;
    if (mpr121_write(MPR121_NHDR, 0x01) < 0) return -1;
    if (mpr121_write(MPR121_NCLR, 0x0E) < 0) return -1;
    if (mpr121_write(MPR121_FDLR, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_MHDF, 0x01) < 0) return -1;
    if (mpr121_write(MPR121_NHDF, 0x01) < 0) return -1;
    if (mpr121_write(MPR121_NCLF, 0x0E) < 0) return -1;
    if (mpr121_write(MPR121_FDLF, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_NHDT, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_NCLT, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_FDLT, 0x00) < 0) return -1;

    /* Touch / release thresholds for all 12 electrodes */
    for (int i = 0; i < NUM_ELECTRODES; i++) {
        if (mpr121_write(MPR121_TOUCHTH_0 + i * 2, 0x0F) < 0) return -1;
        if (mpr121_write(MPR121_RELEASETH_0 + i * 2, 0x0A) < 0) return -1;
    }

    /* Enable all 12 electrodes, baseline tracking */
    if (mpr121_write(MPR121_ELECONFIG, 0x0C) < 0) return -1;

    return 0;
}

/* ------------------------------------------------------------------------ */
static int mpr121_read_touch(uint16_t *status)
{
    uint8_t lo, hi;
    if (mpr121_read(MPR121_TOUCHSTATUS_L, &lo) < 0) return -1;
    if (mpr121_read(MPR121_TOUCHSTATUS_H, &hi) < 0) return -1;
    *status = ((uint16_t)hi << 8) | lo;
    return 0;
}

/* ------------------------------------------------------------------------ */
static void led_pattern(uint8_t num)
{
    if (num > 11) num = 11;
    int bits = (num & 0x07) ? 1 : 0;
    if (bits) {
        gpioWrite(GPIO_LED0, 1);
        gpioWrite(GPIO_LED1, 0);
        gpioWrite(GPIO_LED2, 0);
        gpioWrite(GPIO_LED3, 0);
    } else {
        gpioWrite(GPIO_LED0, 0);
        gpioWrite(GPIO_LED1, 0);
        gpioWrite(GPIO_LED2, 0);
        gpioWrite(GPIO_LED3, 0);
    }
}

/* ------------------------------------------------------------------------ */
static void log_event(uint8_t num)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(g_log_fp, "%s - Electrode %u touched\n", ts, num);
    fflush(g_log_fp);
}

/* ------------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Turn off LEDs */
    gpioWrite(GPIO_LED0, 0);
    gpioWrite(GPIO_LED1, 0);
    gpioWrite(GPIO_LED2, 0);
    gpioWrite(GPIO_LED3, 0);

    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------------ */
int main(void)
{
    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure LED GPIOs as outputs */
    int led_pins[4] = { GPIO_LED0, GPIO_LED1, GPIO_LED2, GPIO_LED3 };
    for (int i = 0; i < 4; i++) {
        if (gpioSetMode(led_pins[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", led_pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
        gpioWrite(led_pins[i], 0);
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                MPR121_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize MPR121 */
    if (mpr121_init() < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Proximity art started.  Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (g_running) {
        uint16_t status;
        if (mpr121_read_touch(&status) < 0) {
            fprintf(stderr, "I2C read error; continuing\n");
            usleep(POLL_DELAY_US);
            continue;
        }

        for (int i = 0; i < NUM_ELECTRODES; i++) {
            if (status & (1u << i)) {
                led_pattern(i);
                log_event(i);
            }
        }

        usleep(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

