/* ------------------------------------------------------------------------ */
static int mpr121_read_touch(uint16_t *status)
{
    uint8_t lo, hi;
    if (mpr121_read(MPR121_TOUCHSTATUS_L, &lo) < 0) return -1;
    if (mpr121_read(MPR121_TOUCHSTATUS_H, &hi) < 0) return -1;
    *status = ((uint16_t)hi << 8) | lo;
    return 0;
}

/* ------------------------------------------------------------------------ */
static void led_pattern(uint8_t num)
{
    if (num > 11) num = 11;
    int bits = (num & 0x07) ? 1 : 0;
    if (bits) {
        gpioWrite(GPIO_LED0, 1);
        gpioWrite(GPIO_LED1, 0);
        gpioWrite(GPIO_LED2, 0);
        gpioWrite(GPIO_LED3, 0);
    } else {
        gpioWrite(GPIO_LED0, 0);
        gpioWrite(GPIO_LED1, 0);
        gpioWrite(GPIO_LED2, 0);
        gpioWrite(GPIO_LED3, 0);
    }
}

/* ------------------------------------------------------------------------ */
static void log_event(uint8_t num)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(g_log_fp, "%s - Electrode %u touched\n", ts, num);
    fflush(g_log_fp);
}

/* ------------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Turn off LEDs */
    gpioWrite(GPIO_LED0, 0);
    gpioWrite(GPIO_LED1, 0);
    gpioWrite(GPIO_LED2, 0);
    gpioWrite(GPIO_LED3, 0);

    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------------ */
int main(void)
{
    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure LED GPIOs as outputs */
    int led_pins[4] = { GPIO_LED0, GPIO_LED1, GPIO_LED2, GPIO_LED3 };
    for (int i = 0; i < 4; i++) {
        if (gpioSetMode(led_pins[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", led_pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
        gpioWrite(led_pins[i], 0);
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                MPR121_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize MPR121 */
    if (mpr121_init() < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Proximity art started.  Press Ctrl+C to exit.\n");

    /* Main polling loop */
    while (g_running) {
        uint16_t status;
        if (mpr121_read_touch(&status) < 0) {
            fprintf(stderr, "I2C read error; continuing\n");
            usleep(POLL_DELAY_US);
            continue;
        }

        for (int i = 0; i < NUM_ELECTRODES; i++) {
            if (status & (1u << i)) {
                led_pattern(i);
                log_event(i);
            }
        }

        usleep(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

