/*
 * HC-SR04 ultrasonic distance measurement on Raspberry Pi Zero W.
 *
 * Trigger:  GPIO17 (BCM, output)
 * Echo:     GPIO18 (BCM, input)
 *
 * Build:   gcc -O2 -Wall -Wextra -o hcsr04 hcsr04.c
 * Run:     ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define TRIGGER_PIN      17
#define ECHO_PIN         18

#define SPEED_OF_SOUND   343.0          /* m/s at 20 °C */
#define MIN_DISTANCE_CM  2.0
#define MAX_DISTANCE_CM  400.0
#define LOG_FILE         "distance_log.txt"
#define SAMPLE_PERIOD_S  1
#define TRIGGER_PULSE_US 5
#define ECHO_TIMEOUT_US  30000          /* 30 ms */
#define LOOP_TIMEOUT_S   30             /* 30 s between measurements */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* Write a single timestamped distance line to the log file. */
static int log_distance(FILE *fp, double distance_cm)
{
    time_t     now;
    struct tm  utc;
    char       ts[32];

    time(&now);
    gmtime_r(&now, &utc);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &utc);

    if (fprintf(fp, "%s,%.2f\n", ts, distance_cm) < 0) {
        perror("fprintf");
        return -1;
    }
    if (fflush(fp) != 0) {
        perror("fflush");
        return -1;
    }
    return 0;
}

/*
 * Measure distance in centimetres.
 * Returns distance on success, or -1.0 on error/timeout/sensor-absent.
 */
static double measure_distance(int trigger_pin, int echo_pin)
{
    /* Ensure trigger starts low. */
    if (gpioWrite(trigger_pin, 0) < 0) {
        fprintf(stderr, "gpioWrite(trigger, 0) failed\n");
        return -1.0;
    }
    usleep(TRIGGER_PULSE_US);

    /* 10 µs trigger pulse. */
    if (gpioWrite(trigger_pin, 1) < 0) {
        fprintf(stderr, "gpioWrite(trigger, 1) failed\n");
        return -1.0;
    }
    usleep(10);
    if (gpioWrite(trigger_pin, 0) < 0) {
        fprintf(stderr, "gpioWrite(trigger, 0) failed\n");
        return -1.0;
    }

    /* Wait for echo rising edge (timeout 30 ms). */
    uint32_t start_tick = 0;
    uint32_t elapsed = 0;
    while (gpioRead(echo_pin) == 0) {
        if (elapsed >= ECHO_TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo rising edge (sensor absent?)\n");
            return -1.0;
        }
        usleep(1);
        elapsed++;
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge (timeout 30 ms). */
    elapsed = 0;
    while (gpioRead(echo_pin) == 1) {
        if (elapsed >= ECHO_TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo falling edge\n");
            return -1.0;
        }
        usleep(1);
        elapsed++;
    }
    uint32_t end_tick = gpioTick();

    double pulse_us = (double)(end_tick - start_tick);
    double distance_cm = (pulse_us / 1000000.0) * SPEED_OF_SOUND / 2.0;

    if (distance_cm < MIN_DISTANCE_CM || distance_cm > MAX_DISTANCE_CM) {
        fprintf(stderr, "Distance %.2f cm out of range [%.0f-%.0f]\n",
                distance_cm, MIN_DISTANCE_CM, MAX_DISTANCE_CM);
        return -1.0;
    }
    return distance_cm;
}

int main(void)
{
    FILE *fp = NULL;
    int  rc  = EXIT_FAILURE;

    /* --- Install SIGINT handler for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise() failed\n");
        goto cleanup;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(TRIGGER_PIN) failed\n");
        goto cleanup;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode(ECHO_PIN) failed\n");
        goto cleanup;
    }

    /* Ensure trigger starts low. */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "gpioWrite(TRIGGER_PIN, 0) failed\n");
        goto cleanup;
    }

    printf("HC-SR04 distance measurement started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_PERIOD_S);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        double distance = measure_distance(TRIGGER_PIN, ECHO_PIN);

        if (distance > 0.0) {
            if (log_distance(fp, distance) != 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
        } else {
            fprintf(stderr, "Measurement failed; logging error line.\n");
            if (log_distance(fp, -1.0) != 0) {
                fprintf(stderr, "Failed to log error line.\n");
            }
        }

        /* Sleep SAMPLE_PERIOD_S, but wake early on SIGINT. */
        for (int i = 0; i < SAMPLE_PERIOD_S && g_running; i++) {
            sleep(1);
        }
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fp) {
        fclose(fp);
    }
    gpioTerminate();
    return rc;
}

