/*
 * HC-SR04 Ultrasonic Distance Measurement — Raspberry Pi Zero W
 *
 * Wiring:
 *   HC-SR04 TRIG -> GPIO17 (BCM)
 *   HC-SR04 ECHO -> GPIO18 (BCM) via 1k/2k voltage divider (3.3 V safe)
 *   VCC         -> 5 V (or 3.3 V if the divider is used)
 *   GND         -> GND
 *
 * Build:
 *   gcc -O2 -Wall -o hcsr04 hcsr04.c -lm
 *
 * Run:
 *   ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define TRIGGER_PIN      17
#define ECHO_PIN         18
#define LOG_FILE         "distance_log.txt"
#define TRIGGER_PULSE_US 10
#define SAMPLE_PERIOD_US 1000000   /* 1 second */
#define ECHO_TIMEOUT_US  30000     /* 25 ms — ~4 m round trip */
#define MIN_PULSE_US     58        /* ~1 cm  */
#define MAX_PULSE_US     25000     /* ~4 m  */

static volatile sig_atomic_t g_running = 1;
static volatile uint32_t    g_start_tick = 0;
static volatile uint32_t    g_pulse_us    = 0;
static volatile int         g_echo_seen  = 0;
static FILE                 *g_log_fp     = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* ISR: captures rising and falling edges of the echo pulse           */
/* ------------------------------------------------------------------ */
static void echo_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        /* Rising edge — echo pulse starts */
        g_start_tick = tick;
        g_echo_seen  = 0;
    } else if (level == 0) {
        /* Falling edge — echo pulse ends */
        if (g_start_tick != 0) {
            uint32_t pulse_us = tick - g_start_tick; /* pigpio ticks are 32-bit; subtraction wraps correctly */
            g_pulse_us = pulse_us;
            g_echo_seen = 1;
        }
    }
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */
static void log_reading(float distance)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t == NULL) {
        snprintf(ts, sizeof(ts), "1970-01-01 00:00:00");
    } else {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    }

    if (g_log_fp != NULL) {
        fprintf(g_log_fp, "%s, Distance: %.2f meters\n", ts, distance);
        fflush(g_log_fp);
    } else {
        fprintf(stderr, "Error: log file is not open.\n");
    }
}

static void trigger_sensor(void)
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, NULL, NULL);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO --- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN %d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts LOW */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(1000); /* 1 ms settle */

    /* --- Open log file --- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Register ISR --- */
    if (gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, echo_isr, NULL) != 0) {
        fprintf(stderr, "Error: failed to register ISR on ECHO_PIN %d.\n", ECHO_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started.\n");
    printf("TRIG: GPIO%d, ECHO: GPIO%d, Log: %s\n", TRIGGER_PIN, ECHO_PIN, LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        trigger_sensor();

        /* Wait for echo with timeout */
        uint32_t waited = 0;
        while (!g_echo_seen && waited < ECHO_TIMEOUT_US) {
            gpioDelay(100); /* 100 µs */
            waited += 100;
        }

        if (g_echo_seen) {
            /* Validate pulse width */
            if (g_pulse_us > 0 && g_pulse_us >= MIN_PULSE_US && g_pulse_us <= MAX_PULSE_US) {
                float distance = (float)g_pulse_us / 58.0f; /* 58 µs per cm */
                log_reading(distance);
            } else {
                fprintf(stderr, "Warning: invalid pulse width %u µs (out of range %d–%d µs).\n",
                        g_pulse_us, MIN_PULSE_US, MAX_PULSE_US);
            }
        } else {
            fprintf(stderr, "Warning: echo timeout (no valid pulse received).\n");
        }

        /* Sleep until next sample period (interruptible by signals) */
        uint32_t remaining = SAMPLE_PERIOD_US;
        while (remaining > 0 && g_running) {
            uint32_t chunk = (remaining > 100000) ? 100000 : remaining;
            gpioDelay(chunk);
            remaining -= chunk;
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

