/*
 * VL53L1X ToF sensor reader for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   VL53L1X SDA  -> GPIO2  (I2C bus 1 SDA)
 *   VL53L1X SCL  -> GPIO3  (I2C bus 1 SCL)
 *   VL53L1X XSHUT -> GPIO27 (BCM)  [active-low, HIGH = enabled]
 *   VL53L1X VDD  -> 3.3 V
 *   VL53L1X GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o vl53l1x_reader vl53l1x_reader.c -lpigpio -lrt
 * Run:    sudo ./vl53l1x_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <pigpio.h>

/* ---- VL53L1X constants (from ST datasheet) ---- */
#define VL53L1X_ADDR            0x60
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID  0x010F
#define VL53L1X_REG_SYSTEM_START            0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS     0x0089
#define VL53L1X_REG_RESULT_DISTANCE         0x0096
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR  0x0086
#define VL53L1X_REG_SYSTEM_INTERRUPT_CONFIG 0x0087
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG     0x0088

#define VL53L1X_MODEL_ID_EXPECTED 0xEA

/* ---- GPIO / I2C ---- */
#define I2C_BUS        1
#define I2C_ADDR       VL53L1X_ADDR
#define XSHUT_PIN      27          /* BCM 27 */

/* ---- Timing ---- */
#define SAMPLE_PERIOD_US 100000   /* 100 ms */
#define MAX_RETRIES      3

/* ---- Globals ---- */
static int  g_i2c_handle = -1;
static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_read_word(int handle, uint16_t reg, uint16_t *out)
{
    char buf[2];
    int rc = i2cReadI2CBlockData(handle, reg, buf, 2);
    if (rc != 2) {
        syslog(LOG_ERR, "I2C read failed at reg 0x%04X (rc=%d): %s",
               reg, rc, strerror(errno));
        return -1;
    }
    *out = (uint16_t)((uint8_t)buf[0] | ((uint8_t)buf[1] << 8));
    return 0;
}

static int i2c_write_word(int handle, uint16_t reg, uint16_t val)
{
    char buf[2];
    buf[0] = (char)(val & 0xFF);
    buf[1] = (char)((val >> 8) & 0xFF);
    int rc = i2cWriteI2CBlockData(handle, reg, buf, 2);
    if (rc != 2) {
        syslog(LOG_ERR, "I2C write failed at reg 0x%04X (rc=%d): %s",
               reg, rc, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* VL53L1X driver                                                      */
/* ------------------------------------------------------------------ */
static int vl53l1x_init(int handle)
{
    uint16_t model_id = 0;

    /* Verify device identity */
    if (i2c_read_word(handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id) != 0) {
        syslog(LOG_ERR, "Cannot read model ID; sensor may be absent.");
        return -1;
    }
    if (model_id != VL53L1X_MODEL_ID_EXPECTED) {
        syslog(LOG_ERR, "Unexpected model ID 0x%04X (expected 0x%04X).",
               model_id, VL53L1X_MODEL_ID_EXPECTED);
        return -1;
    }
    syslog(LOG_INFO, "VL53L1X detected (model ID 0x%04X).", model_id);

    /* Clear any pending interrupt */
    if (i2c_write_word(handle, VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, 0x0001) != 0)
        return -1;

    /* Clear any pending range status */
    if (i2c_write_word(handle, VL53L1X_REG_RESULT_RANGE_STATUS, 0x0001) != 0)
        return -1;

    /* Start continuous ranging (bit 0 = START) */
    if (i2c_write_word(handle, VL53L1X_REG_SYSTEM_START, 0x0001) != 0)
        return -1;

    /* Configure interrupt: clear on new sample (bit 0 = CLEAR) */
    if (i2c_write_word(handle, VL53L1X_REG_SYSTEM_INTERRUPT_CONFIG, 0x0001) != 0)
        return -1;

    /* Set range config: 100 ms inter-measurement period (bits 12:10 = 000) */
    if (i2c_write_word(handle, VL53L1X_REG_SYSTEM_RANGE_CONFIG, 0x0000) != 0)
        return -1;

    syslog(LOG_INFO, "VL53L1X initialized: ranging started.");
    return 0;
}

static int vl53l1x_read_distance(int handle, uint16_t *distance_mm)
{
    uint16_t status = 0, dist = 0;

    /* Poll range status bit 0 (new sample ready) */
    for (int i = 0; i < MAX_RETRIES; i++) {
        if (i2c_read_word(handle, VL53L1X_REG_RESULT_RANGE_STATUS, &status) != 0)
            return -1;
        if (status & 0x0001)
            break;
        gpioDelay(2000);  /* 2 ms */
    }
    if (!(status & 0x0001)) {
        syslog(LOG_ERR, "Timeout waiting for VL53L1X data-ready flag.");
        return -1;
    }

    /* Read distance */
    if (i2c_read_word(handle, VL53L1X_REG_RESULT_DISTANCE, &dist) != 0)
        return -1;

    /* Clear interrupt so the next measurement can be sampled */
    if (i2c_write_word(handle, VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, 0x0001) != 0)
        return -1;

    *distance_mm = dist;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    openlog("vl53l1x_reader", LOG_PID | LOG_CONS, LOG_USER);

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction failed: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialization failed.");
        closelog();
        return EXIT_FAILURE;
    }

    /* Configure XSHUT pin as output, HIGH = sensor enabled (active-low) */
    if (gpioSetMode(XSHUT_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO%d as output.", XSHUT_PIN);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioWrite(XSHUT_PIN, 1) != 0) {
        syslog(LOG_ERR, "Failed to write HIGH to GPIO%d.", XSHUT_PIN);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        syslog(LOG_ERR, "i2cOpen failed on bus %d addr 0x%02X (rc=%d): %s",
               I2C_BUS, I2C_ADDR, g_i2c_handle, strerror(errno));
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (vl53l1x_init(g_i2c_handle) != 0) {
        syslog(LOG_ERR, "VL53L1X initialization failed.");
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "VL53L1X reader started. Sampling every 100 ms.");

    /* Main sampling loop */
    while (g_running) {
        uint16_t distance = 0;
        bool ok = (vl53l1x_read_distance(g_i2c_handle, &distance) == 0);

        time_t now = time(NULL);
        struct tm tm_buf;
        struct tm *t = localtime_r(&now, &tm_buf);
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

        if (ok) {
            syslog(LOG_INFO, "%s Distance: %u mm", ts, distance);
        } else {
            syslog(LOG_ERR, "%s Error reading distance.", ts);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* ---- Cleanup ---- */
    syslog(LOG_INFO, "Shutting down.");
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(XSHUT_PIN, 0);   /* power down sensor */
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

