        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (vl53l1x_init(g_i2c_handle) != 0) {
        syslog(LOG_ERR, "VL53L1X initialization failed.");
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        gpioTerminate();
