/*
 * gate_control.c — Raspberry Pi Zero W + VL53L1X gate controller
 *
 * Build:  gcc -O2 -Wall -Wextra -o gate_control gate_control.c
 * Run:    sudo ./gate_control
 *
 * Hardware:
 *   VL53L1X  I2C bus 1, address 0x29 (ADDR pin low)
 *   Gate     GPIO24 (BCM), active-high relay module
 *
 * Behaviour:
 *   Polls distance every 100 ms.  Gate is opened when distance < 20 cm,
 *   otherwise closed.  Logs every reading, state change, and error to
 *   gate_log.txt.  SIGINT/SIGTERM -> graceful shutdown.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#include <linux/i2c.h>
#include <linux/i2c.h>

/* ---- VL53L1X constants (from ST ST-VA-1220 datasheet) ---- */
#define VL53L1X_ADDR            0x29
#define I2C_BUS                 "/dev/i2c-1"

#define REG_SYSTEM_START        0x00
#define REG_SYSTEM_INTERRUPT_CLEAR 0x01
#define REG_SYSTEM_SEQUENCE_START 0x02
#define REG_RESULT_INTERRUPT_STATUS 0x04
#define REG_RESULT_DISTANCE       0x08
#define REG_RESULT_RANGE_STATUS  0x0A

#define REG_SOFT_RESET           0x00
#define REG_SOFT_RESET_VALUE     0x00

#define EXPECTED_MODEL_ID        0xEA
#define EXPECTED_VHV_CONFIG      0x00

#define EXPECTED_RANGE_STATUS_OK 0x00
#define EXPECTED_RANGE_STATUS_ERR 0xFF

#define EXPECTED_DISTANCE       0x00
#define EXPECTED_RANGE_STATUS_ERR 0xFF

#define POLL_INTERVAL_MS        100
#define DISTANCE_THRESHOLD_CM   20
#define GATE_GPIO               24

#define LOG_FILE                "gate_log.txt"

/* ---- Globals for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
static void handle_signal(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void log_msg(FILE *fp, const char *msg)
{
    if (!fp)
        return;
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof ts, "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s: %s\n", ts, msg);
        fflush(fp);
    }
}

/* ------------------------------------------------------------------ */
/* Write one byte to a 16-bit register address.                        */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint16_t reg, uint8_t val)
{
    uint8_t buf[3] = { (uint8_t)(reg >> 8), (uint8_t)(reg & 0xFF), val };
    if (write(fd, buf, sizeof buf) != (ssize_t)sizeof buf) {
        log_msg(g_log_fp, "I2C write_reg8 failed");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from a 16-bit register address.                       */
/* Returns 0 on success (byte in *out), -1 on error.                  */
/* ------------------------------------------------------------------ */
static int i2c_read_reg8(int fd, uint16_t reg, uint8_t *out)
{
    uint8_t addr[2] = { (uint8_t)(reg >> 8), (uint8_t)(reg & 0xFF) };
    if (write(fd, addr, sizeof addr) != (ssize_t)sizeof addr) {
        log_msg(g_log_fp, "I2C read_reg8: write address failed");
        return -1;
    }
    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        log_msg(g_log_fp, "I2C read_reg8: read data failed");
        return -1;
    }
    *out = val;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit register (little-endian on VL53L1X).                  */
/* Returns 0 on success (value in *out), -1 on error.                 */
/* ------------------------------------------------------------------ */
static int i2c_read_reg16(int fd, uint16_t reg, uint16_t *out)
{
    uint8_t addr[2] = { (uint8_t)(reg >> 8), (uint8_t)(reg & 0xFF) };
    if (write(fd, addr, sizeof addr) != (ssize_t)sizeof addr) {
        log_msg(g_log_fp, "I2C read_reg16: write address failed");
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, sizeof buf) != (ssize_t)sizeof buf) {
        log_msg(g_log_fp, "I2C read_reg16: read data failed");
        return -1;
    }
    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the VL53L1X driver.                                     */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int vl53l1x_init(int fd)
{
    uint8_t model_id = 0;
    if (i2c_read_reg8(fd, REG_SOFT_RESET, &model_id) != 0)
        return -1;
    if (model_id != EXPECTED_MODEL_ID) {
        char msg[128];
        snprintf(msg, sizeof msg,
                 "Unexpected model ID 0x%02X (expected 0x%02X). "
                 "Sensor not present or wrong device.", model_id, EXPECTED_MODEL_ID);
        log_msg(g_log_fp, msg);
        return -1;
    }

    /* Soft reset */
    if (i2c_write_reg8(fd, REG_SOFT_RESET, REG_SOFT_RESET_VALUE) != 0)
        return -1;
    usleep(1000);

    /* Verify VHV config */
    uint8_t vhv_cfg = 0;
    if (i2c_read_reg8(fd, REG_VHV_CONFIG, &vhv_cfg) != 0)
        return -1;
    if (vhv_cfg != EXPECTED_VHV_CONFIG) {
        char msg[128];
        snprintf(msg, sizeof msg,
                 "Unexpected VHV config 0x%02X (expected 0x%02X). "
                 "Sensor not present or wrong device.", vhv_cfg, EXPECTED_VHV_CONFIG);
        log_msg(g_log_fp, msg);
        return -1;
    }

    /* Clear any pending interrupt */
    if (i2c_write_reg8(fd, REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0)
        return -1;

    /* Start a single-shot measurement */
    if (i2c_write_reg8(fd, REG_SYSTEM_SEQUENCE_START, 0x01) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Trigger a single measurement and read the 16-bit distance.         */
/* Returns distance in mm on success, -1 on error.                   */
/* ------------------------------------------------------------------ */
static int vl53l1x_read_distance(int fd)
{
    /* Clear any pending interrupt */
    if (i2c_write_reg8(fd, REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0)
        return -1;

    /* Start a single measurement */
    if (i2c_write_reg8(fd, REG_SYSTEM_SEQUENCE_START, 0x01) != 0)
        return -1;

    /* Poll for data-ready (max ~50 ms) */
    for (int i = 0; i < 50; i++) {
        uint8_t status = 0;
        if (i2c_read_reg8(fd, REG_RESULT_INTERRUPT_STATUS, &status) != 0)
            return -1;
        if ((status & 0x01) == 0)
            break;
        usleep(1000);
    }

    uint16_t dist_raw = 0;
    if (i2c_read_reg16(fd, REG_RESULT_DISTANCE, &dist_raw) != 0)
        return -1;

    /* Clear interrupt so the next measurement can be triggered */
    if (i2c_write_reg8(fd, REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0)
        return -1;

    return (int)dist_raw;
}

/* ------------------------------------------------------------------ */
static void set_gate(int distance_cm)
{
    int current = (distance_cm < DISTANCE_THRESHOLD_CM) ? 1 : 0;
    int target  = !current;

    if (current != target) {
        if (i2c_write_reg8(g_i2c_fd, 0x00, target) != 0) {
            log_msg(g_log_fp, "Failed to write gate GPIO");
            return;
        }
        log_msg(g_log_fp, "Gate opened (distance < 20 cm)");
    }
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_log_fp) {
        log_msg(g_log_fp, "Program terminated");
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Open log file ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("fopen log");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        log_msg(g_log_fp, "open I2C bus failed");
        fclose(g_log_fp);
        g_log_fp = NULL;
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, VL53L1X_ADDR) < 0) {
        log_msg(g_log_fp, "ioctl I2C_SLAVE failed");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Initialise sensor ---- */
    if (vl53l1x_init(g_i2c_fd) != 0) {
        log_msg(g_log_fp, "VL53L1X init failed");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Configure gate GPIO ---- */
    if (gpioSetMode(GATE_GPIO, PI_OUTPUT) != 0) {
        log_msg(g_log_fp, "gpioSetMode failed");
        cleanup();
        return EXIT_FAILURE;
    }
    if (i2c_write_reg8(g_i2c_fd, 0x00, 0x00) != 0) {
        log_msg(g_log_fp, "Initial gate GPIO low failed");
        cleanup();
        return EXIT_FAILURE;
    }
    log_msg(g_log_fp, "Gate GPIO configured (initial low)");

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof sa);
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_msg(g_log_fp, "Program started");

    /* ---- Main loop ---- */
    while (g_running) {
        int distance_mm = vl53l1x_read_distance(g_i2c_fd);
        if (distance_mm < 0) {
            log_msg(g_log_fp, "Distance read failed");
        } else {
            int distance_cm = distance_mm / 10;
            char msg[128];
            snprintf(msg, sizeof msg, "Distance: %d cm", distance_cm);
            log_msg(g_log_fp, msg);
            set_gate(distance_cm);
        }
        usleep(POLL_INTERVAL_MS * 1000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

