/*
 * HC-SR04 ultrasonic distance measurement with servo tracking.
 *
 * Board:  Raspberry Pi 4 Model B
 * Library: pigpio (hardware PWM on GPIO18, 50 kHz)
 *
 * Wiring:
 *   HC-SR04 TRIG -> GPIO23 (BCM)
 *   HC-SR04 ECHO -> GPIO24 (BCM) [use voltage divider if ECHO is 5 V]
 *   SG90 signal -> GPIO18 (BCM, hardware PWM)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o distance_panning distance_panning.c -lpigpio -lrt
 * Run:
 *   sudo ./distance_panning
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define TRIGGER_PIN      23
#define ECHO_PIN         24
#define SERVO_PIN        18

/* ---- Timing constants ---- */
#define TRIGGER_PULSE_US 10          /* HC-SR04 trigger pulse width (µs)   */
#define SAMPLE_PERIOD_US 100000      /* 100 ms between trigger pulses       */
#define ECHO_TIMEOUT_US  30000       /* 30 ms echo timeout                 */
#define SERVO_SETTLE_US  2000        /* SG90 startup settling time (µs)   */
#define SERVO_MIN_US     500         /* 0 degrees   (µs)                    */
#define SERVO_MAX_US     2500        /* 180 degrees (µs)                   */
#define SERVO_NEUTRAL_US 1500        /* 90 degrees (µs)                   */
#define SERVO_MIN_ANGLE  0.0f
#define SERVO_MAX_ANGLE  180.0f
#define SERVO_NEUTRAL_ANGLE 90.0f

/* ---- Distance range ---- */
#define MIN_DISTANCE_CM  2.0f
#define MAX_DISTANCE_CM  400.0f

/* ---- Moving-average window ---- */
#define MOVING_AVG_WINDOW 5

/* ---- Shared state ---- */
static volatile uint32_t g_pulse_width = 0;
static volatile bool     g_new_pulse   = false;
static volatile bool     g_echo_seen   = false;
static volatile sig_atomic_t g_running  = 1;
static FILE              *g_log_file   = NULL;

/* ---- Globals for callback ---- */
static volatile uint32_t g_start_tick = 0;
static volatile uint32_t g_end_tick   = 0;
static volatile bool     g_echo_done  = false;

/* ---- Function prototypes ---- */
static void  trigger_pulse(void);
static void  echo_callback(int gpio, int level, uint32_t tick);
static void  set_servo_angle(float angle);
static void  log_data(float distance, float angle);
static void  signal_handler(int sig);
static void  cleanup(void);
static int   api_call(int action, int angle);
static int   api_set_servo_angle(int angle);
static int   api_get_servo_angle(int *angle);
static int   api_set_servo_pulsewidth(int pulsewidth);
static int   api_get_servo_pulsewidth(int *pulsewidth);

/* ------------------------------------------------------------------ */
/*  pigpio helpers                                                      */
/* ------------------------------------------------------------------ */

/*
 * Issue a pigpio API call with the given integer argument.
 * Returns 0 on success, -1 on failure.
 */
static int api_call(int action, int arg)
{
    int rc = gpioCallAPI(action, arg);
    if (rc < 0) {
        fprintf(stderr, "gpioCallAPI(%d, %d) failed: %d\n", action, arg, rc);
    }
    return rc;
}

/*
 * Set the servo angle via the API.
 * Returns 0 on success, -1 on failure.
 */
static int api_set_servo_angle(int angle)
{
    return api_call(PI_SET_SERVO_ANGLE, angle);
}

/*
 * Read the current servo angle from the API.
 * Returns 0 on success, -1 on failure.
 */
static int api_get_servo_angle(int *angle)
{
    return api_call(PI_GET_SERVO_ANGLE, (int)angle);
}

/*
 * Set the servo pulse width via the API.
 * Returns 0 on success, -1 on failure.
 */
static int api_set_servo_pulsewidth(int pulsewidth)
{
    return api_call(PI_SET_SERVO_PULSEWIDTH, pulsewidth);
}

/*
 * Read the current servo pulse width from the API.
 * Returns 0 on success, -1 on failure.
 */
static int api_get_servo_pulsewidth(int *pulsewidth)
{
    return api_call(PI_GET_SERVO_PULSEWIDTH, (int)pulsewidth);
}

/* ------------------------------------------------------------------ */
/*  Servo control                                                       */
/* ------------------------------------------------------------------ */

static void set_servo_angle(float angle)
{
    if (angle < SERVO_MIN_ANGLE) angle = SERVO_MIN_ANGLE;
    if (angle > SERVO_MAX_ANGLE) angle = SERVO_MAX_ANGLE;

    int pulsewidth = (int)(SERVO_MIN_US +
                           (angle / SERVO_MAX_ANGLE) *
                           (SERVO_MAX_US - SERVO_MIN_US));

    if (api_set_servo_pulsewidth(pulsewidth) != 0) {
        fprintf(stderr, "Failed to set servo pulsewidth\n");
        return;
    }
}

/* ------------------------------------------------------------------ */
/*  Moving-average filter                                               */
/* ------------------------------------------------------------------ */

static float moving_average(float new_value, float *buffer, int *index,
                             int window_size)
{
    buffer[*index] = new_value;
    *index = (*index + 1) % window_size;

    float sum = 0.0f;
    for (int i = 0; i < window_size; i++) {
        sum += buffer[i];
    }
    return sum / (float)window_size;
}

/* ------------------------------------------------------------------ */
/*  Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/*  Echo callback                                                      */
/* ------------------------------------------------------------------ */

static void echo_callback(int gpio, int level, uint32_t tick)
{
    (void)gpio;

    if (level == 1) {
        g_start_tick = tick;
        g_echo_done  = false;
    } else if (level == 0 && g_start_tick != 0) {
        g_end_tick = tick;
        g_echo_done = true;
    }
}

/* ------------------------------------------------------------------ */
/*  Trigger pulse                                                       */
/* ------------------------------------------------------------------ */

static void trigger_pulse(void)
{
    if (gpioWrite(TRIGGER_PIN, 1) != 0) {
        fprintf(stderr, "gpioWrite(TRIGGER, 1) failed\n");
        return;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "gpioWrite(TRIGGER, 0) failed\n");
    }
}

/* ------------------------------------------------------------------ */
/*  Logging                                                             */
/* ------------------------------------------------------------------ */

static void log_data(float distance, float angle)
{
    if (g_log_file == NULL) {
        fprintf(stderr, "Log file not open\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(g_log_file, "%s,%.2f,%.2f\n", ts, distance, angle);
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
/*  Cleanup                                                             */
/* ------------------------------------------------------------------ */

static void cleanup(void)
{
    /* Stop servo PWM signal */
    gpioPWM(SERVO_PIN, 0);

    /* Close log file */
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }

    /* Release pigpio resources */
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/*  Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_file = fopen("distance_log.csv", "w");
    if (g_log_file == NULL) {
        perror("fopen(distance_log.csv)");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header */
    fprintf(g_log_file, "timestamp,distance_cm,servo_angle_deg\n");
    fflush(g_log_file);

    /* Configure trigger pin as output, initial low */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(TRIGGER) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "gpioWrite(TRIGGER, 0) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure echo pin as input */
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(ECHO) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register echo interrupt callback */
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "gpioSetAlertFuncEx(ECHO) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure servo pin as PWM output */
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(SERVO) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize servo to neutral position */
    if (api_set_servo_angle((int)SERVO_NEUTRAL_ANGLE) != 0) {
        fprintf(stderr, "Failed to initialize servo\n");
        cleanup();
        return EXIT_FAILURE;
    }
    gpioDelay(SERVO_SETTLE_US);

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }

    float distance_buffer[MOVING_AVG_WINDOW] = {0.0f};
    int    buffer_index = 0;
    int    buffer_count = 0;

    printf("HC-SR04 distance measurement started. Press Ctrl+C to stop.\n");

    while (g_running) {
        trigger_pulse();

        /* Wait for echo with timeout */
        uint32_t start_wait = gpioTick();
        while (!g_echo_done && g_running) {
            if ((gpioTick() - start_wait) > ECHO_TIMEOUT_US) {
                fprintf(stderr, "Echo timeout\n");
                break;
            }
            gpioDelay(100);
        }

        if (g_echo_done) {
            uint32_t diff = g_end_tick - g_start_tick;
            float distance = (float)diff / 58.0f;  /* cm */

            /* Sanity check */
            if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
                fprintf(stderr, "Distance out of range: %.2f cm\n", distance);
                distance = -1.0f;
            }

            /* Moving-average filter */
            distance_buffer[buffer_index] = distance;
            buffer_index = (buffer_index + 1) % MOVING_AVG_WINDOW;
            if (buffer_count < MOVING_AVG_WINDOW) buffer_count++;

            float avg_distance = moving_average(distance, distance_buffer,
                                                  &buffer_index, MOVING_AVG_WINDOW);

            /* Update servo angle */
            set_servo_angle(avg_distance);

            /* Log data */
            log_data(avg_distance, (float)SERVO_NEUTRAL_ANGLE);
        }

        /* Sleep for the remainder of the 100 ms period */
        if (g_running) {
            gpioDelay(SAMPLE_PERIOD_US - ECHO_TIMEOUT_US);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

