/*
 * Si1102 Proximity Sensor Monitor for Raspberry Pi Zero W
 * Uses pigpio for I2C and GPIO control.
 *
 * Build: gcc -o si1102_monitor si1102_monitor.c -lpigpio -lrt
 * Run:   sudo ./si1102_monitor [-a i2c_address] [-t threshold]
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS 1
#define I2C_ADDR_DEFAULT 0x60
#define INTERRUPT_GPIO 27
#define PROXIMITY_THRESHOLD_DEFAULT 1000
#define LOG_FILE "proximity.log"

/* Si1102 Register Addresses */
#define SI1102_REG_PART_ID 0x00
#define SI1102_REG_HW_KEY 0x07
#define SI1102_REG_MEAS_RATE 0x08
#define SI1102_REG_PS_LED21 0x0F
#define SI1102_REG_PS1_DATA0 0x10
#define SI1102_REG_PS1_DATA1 0x11
#define SI1102_REG_PS1_CONFIG 0x12
#define SI1102_REG_PS1_INT_CFG 0x13
#define SI1102_REG_PS1_INT_EN 0x14
#define SI1102_REG_PS1_INT_STATUS 0x15

#define SI1102_PART_ID 0x00
#define SI1102_HW_KEY_VAL 0x17

/* Si1102 Commands */
#define SI1102_CMD_PS_FORCE 0x0B
#define SI1102_CMD_PS_AUTO 0x0A

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t interrupt_flag = 0;
static volatile uint16_t proximity_value = 0;
static int i2c_address = I2C_ADDR_DEFAULT;
static int proximity_threshold = PROXIMITY_THRESHOLD_DEFAULT;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "I2C write error at reg 0x%02X: %s\n", reg, strerror(errno));
    }
    return result;
}

static int i2c_read_byte(int handle, uint8_t reg) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "I2C read error at reg 0x%02X: %s\n", reg, strerror(errno));
    }
    return result;
}

static int i2c_read_word(int handle, uint8_t reg) {
    int result = i2cReadWordData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "I2C read word error at reg 0x%02X: %s\n", reg, strerror(errno));
    }
    return result;
}

static int initialize_i2c(int bus, int address) {
    i2c_handle = i2cOpen(bus, address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X on bus %d: %s\n", address, bus, strerror(errno));
        return -1;
    }
    return 0;
}

static int initialize_gpio(int pin) {
    if (gpioSetMode(pin, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", pin);
        return -1;
    }
    if (gpioSetPullUpDown(pin, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", pin);
        return -1;
    }
    return 0;
}

static int initialize_sensor(int handle) {
    int part_id = i2c_read_byte(handle, SI1102_REG_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Failed to read Part ID\n");
        return -1;
    }
    if (part_id != SI1102_PART_ID) {
        fprintf(stderr, "Unexpected Part ID: 0x%02X (expected 0x%02X)\n", part_id, SI1102_PART_ID);
        return -1;
    }

    if (i2c_write_byte(handle, SI1102_REG_HW_KEY, SI1102_HW_KEY_VAL) < 0) {
        fprintf(stderr, "Failed to write HW_KEY\n");
        return -1;
    }

    if (i2c_write_byte(handle, SI1102_REG_MEAS_RATE, 0x00) < 0) {
        fprintf(stderr, "Failed to write MEAS_RATE\n");
        return -1;
    }

    if (i2c_write_byte(handle, SI1102_REG_PS_LED21, 0x0F) < 0) {
        fprintf(stderr, "Failed to write PS_LED21\n");
        return -1;
    }

    if (i2c_write_byte(handle, SI1102_REG_PS1_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Failed to write PS1_CONFIG\n");
        return -1;
    }

    if (i2c_write_byte(handle, SI1102_REG_PS1_INT_CFG, 0x00) < 0) {
        fprintf(stderr, "Failed to write PS1_INT_CFG\n");
        return -1;
    }

    if (i2c_write_byte(handle, SI1102_REG_PS1_INT_EN, 0x01) < 0) {
        fprintf(stderr, "Failed to write PS1_INT_EN\n");
        return -1;
    }

    if (i2c_write_byte(handle, SI1102_REG_PS1_INT_STATUS, 0x00) < 0) {
        fprintf(stderr, "Failed to write PS1_INT_STATUS\n");
        return -1;
    }

    if (i2c_write_byte(handle, SI1102_REG_PS1_DATA0, 0x00) < 0) {
        fprintf(stderr, "Failed to write PS1_DATA0\n");
        return -1;
    }

    if (i2c_write_byte(handle, SI1102_REG_PS1_DATA1, 0x00) < 0) {
        fprintf(stderr, "Failed to write PS1_DATA1\n");
        return -1;
    }

    return 0;
}

static int read_proximity(int handle) {
    if (i2c_write_byte(handle, SI1102_REG_PS_FORCE, SI1102_CMD_PS_FORCE) < 0) {
        fprintf(stderr, "Failed to trigger PS_FORCE\n");
        return -1;
    }
    gpioDelay(10000); /* 10ms delay for measurement */

    int data0 = i2c_read_byte(handle, SI1102_REG_PS1_DATA0);
    int data1 = i2c_read_byte(handle, SI1102_REG_PS1_DATA1);

    if (data0 < 0 || data1 < 0) {
        fprintf(stderr, "Failed to read proximity data\n");
        return -1;
    }

    proximity_value = (uint16_t)((data1 << 8) | data0);
    return 0;
}

static void log_data(FILE *file, uint16_t proximity_value, const char *status) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(file, "%04d-%02d-%02d %02d:%02d:%02d, %u, %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            proximity_value, status);
    fflush(file);
}

static void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data) {
    (void)gpio;
    (void)tick;
    (void)user_data;

    if (level == 1) {
        if (read_proximity(i2c_handle) == 0) {
            const char *status = (proximity_value <= proximity_threshold) ? "SAFE" : "ALERT";
            log_data(log_file, proximity_value, status);
        }
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int opt;

    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = (int)strtol(optarg, NULL, 0);
                break;
            case 't':
                proximity_threshold = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (i2c_address <= 0 || i2c_address > 0x7F) {
        fprintf(stderr, "Invalid I2C address: %d\n", i2c_address);
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (initialize_i2c(I2C_BUS, i2c_address) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (initialize_gpio(INTERRUPT_GPIO) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    if (initialize_sensor(i2c_handle) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set SIGINT handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFuncEx(INTERRUPT_GPIO, RISING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function for GPIO %d\n", INTERRUPT_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Proximity sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        if (interrupt_flag) {
            interrupt_flag = 0;
        }
        gpioDelay(100000); /* 100ms */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

