/*
 * HC-SR04 distance-to-frequency theremin for Raspberry Pi Zero W.
 *
 * Wiring:
 *   HC-SR04 VCC  -> 5V (pin 2)
 *   HC-SR04 GND  -> GND (pin 6)
 *   HC-SR04 Trig -> GPIO23 (BCM, pin 16)  - 10 µs trigger pulse
 *   HC-SR04 Echo -> GPIO24 (BCM, pin 18)   - 3.3 V echo pulse
 *   Speaker     -> 8 Ω resistor -> GPIO18 (BCM, pin 12) -> voice coil
 *
 * Build:  gcc -O2 -Wall -o theremin theremin.c -lm
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <math.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>

#include <pigpio.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define TRIGGER_PIN  23          /* HC-SR04 trigger line  */
#define ECHO_PIN     24          /* HC-SR04 echo line     */
#define PWM_PIN      18          /* Hardware PWM0 (GPIO18) */

/* ---- Physical constants ---- */
#define SPEED_OF_SOUND_CM_PER_S  34300.0   /* cm/s at 20 °C */
#define MIN_DISTANCE_CM          2.0
#define MAX_DISTANCE_CM          200.0
#define MIN_FREQUENCY_HZ         200
#define MAX_FREQUENCY_HZ         2000
#define PWM_DUTY_CYCLE           128        /* 50 % of 0–255 range */

/* ---- Timing ---- */
#define TRIGGER_PULSE_US         10
#define ECHO_TIMEOUT_US          200000     /* 200 ms */
#define LOOP_DELAY_US            100000     /* 100 ms */

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_pwm_handle = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Measure distance (cm) from the HC-SR04.                             */
/* Returns >= 0 on success, -1.0 on timeout, -2.0 on out-of-range.     */
/* ------------------------------------------------------------------ */
static double measure_distance(void)
{
    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "gpioWrite(trigger, 0) failed: %s\n", strerror(errno));
        return -1.0;
    }
    gpioDelay(5);  /* settle */

    /* 10 µs trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "gpioWrite(trigger, 1) failed: %s\n", strerror(errno));
        return -1.0;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "gpioWrite(trigger, 0) failed: %s\n", strerror(errno));
        return -1.0;
    }

    /* Wait for echo rising edge (timeout) */
    uint32_t start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - start_tick) > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo rising edge\n");
            return -1.0;
        }
    }
    uint32_t echo_start = gpioTick();

    /* Wait for echo falling edge (timeout) */
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - echo_start) > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo falling edge\n");
            return -1.0;
        }
    }
    uint32_t echo_end = gpioTick();

    uint32_t pulse_us = echo_end - echo_start;
    if (pulse_us == 0) {
        fprintf(stderr, "Invalid pulse duration (0 µs)\n");
        return -1.0;
    }

    /* distance = (pulse_us * speed_of_sound) / 2 */
    double distance = (double)pulse_us * SPEED_OF_SOUND_CM_PER_S / 2.0 / 1000000.0;

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        fprintf(stderr, "Distance %.2f cm out of range [%.0f, %.0f]\n",
                distance, MIN_DISTANCE_CM, MAX_DISTANCE_CM);
        return -2.0;
    }

    return distance;
}

/* ------------------------------------------------------------------ */
/* Map distance to frequency (Hz).                                     */
/* ------------------------------------------------------------------ */
static int distance_to_frequency(double distance)
{
    if (distance < MIN_DISTANCE_CM) distance = MIN_DISTANCE_CM;
    if (distance > MAX_DISTANCE_CM) distance = MAX_DISTANCE_CM;

    double norm = (distance - MIN_DISTANCE_CM) /
                  (MAX_DISTANCE_CM - MIN_DISTANCE_CM);
    double freq = MIN_FREQUENCY_HZ +
                  (MAX_FREQUENCY_HZ - MIN_FREQUENCY_HZ) * norm;

    int freq_int = (int)freq;
    if (freq_int < MIN_FREQUENCY_HZ) freq_int = MIN_FREQUENCY_HZ;
    if (freq_int > MAX_FREQUENCY_HZ) freq_int = MAX_FREQUENCY_HZ;
    return freq_int;
}

/* ------------------------------------------------------------------ */
/* Set PWM frequency and duty cycle.                                  */
/* ------------------------------------------------------------------ */
static int set_pwm_frequency(int frequency_hz)
{
    if (frequency_hz <= 0) {
        fprintf(stderr, "Invalid frequency %d Hz\n", frequency_hz);
        return -1;
    }

    /* pigpio hardware PWM frequency is in Hz; use 1 MHz range */
    int freq = frequency_hz;
    if (gpioSetPWMfrequency(PWM_PIN, freq) < 0) {
        fprintf(stderr, "gpioSetPWMfrequency(%d) failed: %s\n",
                freq, strerror(errno));
        return -1;
    }

    /* 50 % duty cycle (0–255 range) */
    if (gpioPWM(PWM_PIN, PWM_DUTY_CYCLE) < 0) {
        fprintf(stderr, "gpioPWM(%d) failed: %s\n",
                PWM_DUTY_CYCLE, strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure GPIO pins ---- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(TRIGGER_PIN) failed: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode(ECHO_PIN) failed: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(PWM_PIN) failed: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "gpioWrite(TRIGGER_PIN, 0) failed: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioDelay(1000);  /* 1 ms settle */

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Main loop ---- */
    double previous_frequency = 0;
    int previous_pwm_status = -1;  /* force initial re-init */

    while (g_running) {
        double distance = measure_distance();

        if (distance < 0.0) {
            /* Error already reported; preserve previous frequency */
            if (previous_pwm_status == 0) {
                previous_pwm_status = set_pwm_frequency(previous_frequency);
            }
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        if (distance == -2.0) {
            /* Out of range; preserve previous frequency */
            if (previous_pwm_status == 0) {
                previous_pwm_status = set_pwm_frequency(previous_frequency);
            }
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        int frequency = distance_to_frequency(distance);
        if (set_pwm_frequency(frequency) < 0) {
            /* PWM init failed; keep previous frequency */
            if (previous_pwm_status == 0) {
                previous_pwm_status = 1;  /* indicate failure */
            }
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        previous_frequency = frequency;
        previous_pwm_status = 0;

        printf("Distance: %.2f cm  ->  Frequency: %d Hz\n",
               distance, frequency);
        fflush(stdout);

        gpioDelay(LOOP_DELAY_US);
    }

    /* ---- Clean shutdown ---- */
    printf("\nShutting down...\n");
    if (g_pwm_handle >= 0) {
        gpioPWM(PWM_PIN, 0);  /* silence speaker */
        gpioSetPWMfrequency(PWM_PIN, 0);
        gpioPWM(PWM_PIN, 0);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

