#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define TRIGGER_PIN  23
#define ECHO_PIN     24
#define BUZZER_PIN   18

/* ---- Physical constants ---- */
#define SPEED_OF_SOUND_CM_PER_US  0.0343   /* cm per microsecond */
#define MIN_DISTANCE_CM           5.0
#define MAX_DISTANCE_CM           50.0
#define MIN_FREQUENCY_HZ          200
#define MAX_FREQUENCY_HZ          2000
#define ECHO_TIMEOUT_US           100000   /* 100 ms */
#define LOOP_DELAY_US             10000   /* 10 ms */

/* ---- Timing ---- */
#define TRIGGER_PULSE_US          10
#define ECHO_TIMEOUT_US           100000

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_pigpio_initialized = 0;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* HC-SR04 measurement                                                */
/* ------------------------------------------------------------------ */
/*
 * Returns distance in cm, or -1.0 on timeout / error.
 * Uses pigpio's microsecond-precise gpioDelay for the trigger pulse.
 */
static double measure_distance(void)
{
    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger, 0) failed\n");
        return -1.0;
    }
    gpioDelay(5);  /* let pull-down settle */

    /* 10 us trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger, 1) failed\n");
        return -1.0;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger, 0) failed\n");
        return -1.0;
    }

    uint32_t start_tick = 0, end_tick = 0;
    uint32_t deadline;

    /* Wait for echo rising edge */
    deadline = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - deadline) >= 0) {
            fprintf(stderr, "Error: echo rising-edge timeout\n");
            return -1.0;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge */
    deadline = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - deadline) >= 0) {
            fprintf(stderr, "Error: echo falling-edge timeout\n");
            return -1.0;
        }
    }
    end_tick = gpioTick();

    uint32_t pulse_us = end_tick - start_tick;
    double distance = (double)pulse_us * SPEED_OF_SOUND_CM_PER_US / 2.0;

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        fprintf(stderr, "Warning: distance %.2f cm out of range [%.0f-%.0f]\n",
