/*
 * ICU-20201 Ultrasonic ToF Sensor SPI Reader for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   ICU-20201 CS  -> GPIO8  (BCM 8, SPI0 CE0)
 *   ICU-20201 SCLK -> GPIO11 (BCM 11, SPI0 SCLK)
 *   ICU-20201 DOUT -> GPIO9  (BCM 9,  SPI0 MISO)
 *   ICU-20201 DIN  -> GPIO10 (BCM 10, SPI0 MOSI)
 *   ICU-20201 VDD  -> 3.3 V
 *   ICU-20201 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -o icu20201_reader icu20201_reader.c
 * Run:    sudo ./icu20201_reader   (SPI requires root or gpio group access)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U   /* 1 MHz */
#define SPI_BITS        8
#define SPI_MODE        SPI_MODE_0
#define CS_PIN          8          /* BCM 8 */
#define CS_LINE_OFFSET  8
#define LOG_FILE        "distance_log.csv"
#define SAMPLE_DELAY_US 100000U    /* 100 ms */
#define MAX_DISTANCE_MM 5000       /* ICU-20201 range: 200–5000 mm */

static volatile sig_atomic_t g_running = 1;
static int  g_spi_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) == -1)
        perror("sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* SPI helpers                                                         */
/* ------------------------------------------------------------------ */
static int spi_init(void)
{
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "ioctl(SPI_IOC_WR_MODE): %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "ioctl(SPI_IOC_WR_BITS_PER_WORD): %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "ioctl(SPI_IOC_WR_MAX_SPEED_HZ): %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

/*
 * Read a 16-bit big-endian word from the ICU-20201.
 * The sensor returns data on the falling edge of CS (active-low).
 * We assert CS low, send 4 dummy bytes, then read 2 data bytes.
 * The 16-bit result is returned in *out_mm.
 */
static int spi_read_word(uint16_t *out_mm)
{
    if (g_spi_fd < 0)
        return -1;

    /* Assert CS (active-low) */
    if (ioctl(g_spi_fd, SPI_IOC_CS_CHANGE, &(uint8_t){0}) < 0) {
        fprintf(stderr, "ioctl(SPI_IOC_CS_CHANGE): %s\n", strerror(errno));
        return -1;
    }

    /* Send 4 dummy clock cycles to clock out the data */
    uint8_t tx[4] = {0, 0, 0, 0};
    uint8_t rx[4] = {0, 0, 0, 0};

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = 4;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "ioctl(SPI_IOC_MESSAGE): %s\n", strerror(errno));
        /* Deassert CS on error */
        (void)ioctl(g_spi_fd, SPI_IOC_CS_CHANGE, &(uint8_t){1});
        return -1;
    }

    /* Deassert CS */
    if (ioctl(g_spi_fd, SPI_IOC_CS_CHANGE, &(uint8_t){1}) < 0) {
        fprintf(stderr, "ioctl(SPI_IOC_CS_CHANGE): %s\n", strerror(errno));
        return -1;
    }

    /* Data is big-endian: rx[0] = MSB, rx[1] = LSB */
    *out_mm = ((uint16_t)rx[0] << 8) | rx[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_distance(uint16_t distance_mm)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(g_log_fp, "%s,%u\n", timestamp, distance_mm) < 0) {
        fprintf(stderr, "fprintf to log: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(g_log_fp) == EOF) {
        fprintf(stderr, "fflush log: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    install_signal_handlers();

    g_spi_fd = spi_init();
    if (g_spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "timestamp,distance_mm\n");
        fflush(g_log_fp);
    }

    printf("ICU-20201 SPI reader started. Logging to %s\n", LOG_FILE);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        uint16_t distance_mm = 0;

        if (spi_read_word(&distance_mm) == 0) {
            if (distance_mm > MAX_DISTANCE_MM) {
                fprintf(stderr, "Warning: distance %u mm exceeds range. "
                                "Sensor may be absent or miswired.\n",
                        distance_mm);
            }

            if (log_distance(distance_mm) != 0) {
                fprintf(stderr, "Logging failed for distance %u mm.\n",
                        distance_mm);
            }
        } else {
            fprintf(stderr, "SPI read error. Continuing.\n");
        }

        usleep(SAMPLE_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

