/*
 * Si1120 ambient-light and proximity sensor reader for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   Si1120 SDA  -> GPIO2 (pin 3, I2C bus 1 SDA)
 *   Si1120 SCL  -> GPIO3 (pin 5, I2C bus 1 SCL)
 *   Si1120 VDD  -> 3.3 V
 *   Si1120 GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o si1120_reader si1120_reader.c
 *
 * Run:
 *   ./si1120_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- Si1120 constants (datasheet) ---- */
#define SI1120_I2C_ADDR        0x60
#define SI1120_REG_PART_ID     0x00
#define SI1120_REG_HW_KEY      0x07
#define SI1120_REG_MEAS_RATE0  0x08
#define SI1120_REG_ALS_RATE0   0x09
#define SI1120_REG_PS_RATE0    0x0A
#define SI1120_REG_ALS_DATA0   0x22
#define SI1120_REG_PS1_DATA0   0x24
#define SI1120_REG_COMMAND     0x30
#define SI1120_CMD_RESET       0x01
#define SI1120_CMD_PS_FORCE    0x05
#define SI1120_CMD_ALS_FORCE   0x06

#define SI1120_PART_ID_EXPECTED 0x82
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "si1120_log.txt"
#define SAMPLE_INTERVAL_US 500000
#define MAX_RETRIES 3
#define RETRY_DELAY_US 10000

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Low-level I2C helpers ---- */

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s (wrote %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    n = read(fd, out, 1);
    if (n != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16_le(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];
    if (i2c_read_reg8(fd, reg, buf) < 0)
        return -1;
    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

/* ---- Si1120 driver ---- */

static int si1120_reset(int fd)
{
    if (i2c_write_reg8(fd, SI1120_REG_COMMAND, SI1120_CMD_RESET) < 0)
        return -1;
    usleep(10000); /* 10 ms reset settling time */
    return 0;
}

static int si1120_verify_part_id(int fd)
{
    uint8_t part_id = 0;
    if (i2c_read_reg8(fd, SI1120_REG_PART_ID, &part_id) < 0)
        return -1;
    if (part_id != SI1120_PART_ID_EXPECTED) {
        fprintf(stderr, "Unexpected part ID 0x%02X (expected 0x%02X)\n",
                part_id, SI1120_PART_ID_EXPECTED);
        return -1;
    }
    return 0;
}

static int si1120_init(int fd)
{
    if (si1120_reset(fd) < 0) {
        fprintf(stderr, "Si1120 reset failed\n");
        return -1;
    }
    if (si1120_verify_part_id(fd) < 0) {
        fprintf(stderr, "Si1120 part ID verification failed\n");
        return -1;
    }
    /* Hardware key write (required per datasheet) */
    if (i2c_write_reg8(fd, SI1120_REG_HW_KEY, 0x00) < 0)
        return -1;
    /* Measurement rate: 0x00 = 1 Hz ALS, 0x00 = 1 Hz PS */
    if (i2c_write_reg8(fd, SI1120_REG_MEAS_RATE0, 0x00) < 0)
        return -1;
    if (i2c_write_reg8(fd, SI1120_REG_ALS_RATE0, 0x00) < 0)
        return -1;
    if (i2c_write_reg8(fd, SI1120_REG_PS_RATE0, 0x00) < 0)
        return -1;
    return 0;
}

static int si1120_read_data(int fd, uint16_t *ambient_light, uint16_t *proximity)
{
    if (i2c_write_reg8(fd, SI1120_REG_COMMAND, SI1120_CMD_ALS_FORCE) < 0)
        return -1;
    usleep(10000); /* 10 ms conversion time */

    if (i2c_read_reg16_le(fd, SI1120_REG_ALS_DATA0, ambient_light) < 0)
        return -1;
    if (i2c_read_reg16_le(fd, SI1120_REG_PS1_DATA0, proximity) < 0)
        return -1;
    return 0;
}

static int log_data(FILE *fp, uint16_t ambient_light, uint16_t proximity)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }
    if (fprintf(fp, "%s, Ambient Light: %u, Proximity: %u\n",
                timestamp, ambient_light, proximity) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    int fd = -1;
    FILE *fp = NULL;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        goto cleanup;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        goto cleanup;
    }

    if (ioctl(fd, I2C_SLAVE, SI1120_I2C_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                SI1120_I2C_ADDR, strerror(errno));
        goto cleanup;
    }

    if (si1120_init(fd) < 0) {
        fprintf(stderr, "Si1120 initialization failed\n");
        goto cleanup;
    }

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    printf("Si1120 logging started. Press Ctrl-C to stop.\n");

    while (g_running) {
        uint16_t ambient_light = 0, proximity = 0;
        int ok = 0;

        for (int attempt = 1; attempt <= MAX_RETRIES && g_running; ++attempt) {
            if (si1120_read_data(fd, &ambient_light, &proximity) == 0) {
                ok = 1;
                break;
            }
            fprintf(stderr, "Read attempt %d/%d failed; retrying in %d ms...\n",
                    attempt, MAX_RETRIES, RETRY_DELAY_US / 1000);
            usleep(RETRY_DELAY_US);
        }

        if (ok) {
            if (log_data(fp, ambient_light, proximity) < 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            } else {
                printf("Ambient Light: %u, Proximity: %u\n",
                       ambient_light, proximity);
            }
        } else {
            fprintf(stderr, "Failed to read Si1120 after %d attempts.\n",
                    MAX_RETRIES);
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fp != NULL) {
        if (fclose(fp) != 0)
            fprintf(stderr, "fclose failed: %s\n", strerror(errno));
    }
    if (fd >= 0) {
        close(fd);
    }
    return rc;
}

