#define SI1145_CMD_PS_FORCE_CONT_SINGLE 0xFE
#define SI1145_CMD_PS_FORCE_CONT_SINGLE 0xFF

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int write_reg(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%02X: %s\n", value, reg, strerror(errno));
    }
    return rc;
}

static int read_reg(uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int read_reg16(uint8_t reg, uint16_t *value) {
    int rc = i2cReadWordData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint16_t)rc;
    return 0;
}

static int init_si1145(void) {
    uint8_t part_id = 0;
    if (read_reg(SI1145_REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "Failed to read Part ID\n");
        return -1;
    }
    if (part_id != 0x45) {
        fprintf(stderr, "Unexpected Part ID: 0x%02X (expected 0x45)\n", part_id);
        return -1;
    }

    if (write_reg(SI1145_REG_HW_KEY, 0x17) < 0) return -1;
    if (write_reg(SI1145_REG_MEAS_RATE0, 0x00) < 0) return -1;
    if (write_reg(SI1145_REG_COMMAND, SI1145_CMD_PS_AUTO_CONT) < 0) return -1;
    return 0;
}

static int read_proximity(uint16_t *proximity) {
    if (read_reg16(SI1145_REG_PS1_DATA0, proximity) < 0) return -1;
    return 0;
}

static void log_data(uint16_t proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %u\n", timestamp, proximity);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (init_si1145() < 0) {
        fprintf(stderr, "Si1145 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("proximity_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Si1145 proximity logging started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        uint16_t proximity = 0;
        int retries = 3;
        int success = 0;

        while (retries > 0 && !terminate) {
            if (read_proximity(&proximity) == 0) {
                success = 1;
                break;
            }
            retries--;
            if (retries > 0) {
                fprintf(stderr, "Retrying read_proximity...\n");
                gpioDelay(100000);
            }
        }

        if (success) {
            log_data(proximity);
        } else {
            fprintf(stderr, "Failed to read proximity after 3 retries.\n");
        }

        gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
    return 0;
}

