/*
 * HC-SR04 Ultrasonic Distance Sensor with Buzzer Alert
 * Board:  Raspberry Pi 4 Model B
 * Pins:   GPIO17 (BCM) - Trigger
 *         GPIO18 (BCM) - Echo (rising/falling edge alert)
 *         GPIO27 (BCM) - Buzzer
 *
 * Build:  gcc -O2 -Wall -o hcsr04_buzzer hcsr04_buzzer.c -lpigpio -lrt
 * Run:    sudo ./hcsr04_buzzer
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TRIGGER_PIN      17
#define ECHO_PIN         18
#define BUZZER_PIN       27

#define SPEED_OF_SOUND   34300.0   /* cm/s at 20 °C */
#define DISTANCE_THRESHOLD 20.0     /* cm */
#define TRIGGER_PULSE_US 10
#define LOOP_DELAY_US    1000000   /* 1 second */
#define ECHO_TIMEOUT_US  30000     /* 30 ms max echo wait */

/* Shared state between the echo callback and the main thread */
static volatile uint32_t g_start_tick = 0;
static volatile uint32_t g_end_tick   = 0;
static volatile bool     g_echo_state = false; /* false = waiting for start, true = waiting for end */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler for clean shutdown on SIGINT / SIGTERM              */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* pigpio alert callback for the HC-SR04 echo pin                    */
/* ------------------------------------------------------------------ */
static void echo_callback(int gpio, int level, uint32_t tick)
{
    (void)gpio;

    if (level == 1) {
        /* Rising edge: echo pulse starts */
        g_start_tick  = tick;
        g_echo_state  = true;
    } else if (level == 0) {
        /* Falling edge: echo pulse ends */
        g_end_tick    = tick;
        g_echo_state  = false;
    }
    /* level == 2 indicates a watchdog timeout; ignore here */
}

/* ------------------------------------------------------------------ */
/* Compute distance from a single echo pulse width (microseconds)     */
/* ------------------------------------------------------------------ */
static double calculate_distance(uint32_t pulse_us)
{
    return ((double)pulse_us / 1000000.0) * SPEED_OF_SOUND / 2.0;
}

/* ------------------------------------------------------------------ */
/* Trigger the HC-SR04 with a 10 µs pulse                              */
/* ------------------------------------------------------------------ */
static void trigger_sensor(void)
{
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to set trigger high\n");
        return;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger low\n");
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Initialise pigpio driver ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d)\n",
                gpioInitialise());
        return EXIT_FAILURE;
    }

    /* ---- Configure GPIO pins ---- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set trigger pin %d as output\n",
                TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set echo pin %d as input\n",
                ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set buzzer pin %d as output\n",
                BUZZER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure known initial states */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise trigger pin low\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(BUZZER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise buzzer pin low\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Register echo alert callback ---- */
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) < 0) {
        fprintf(stderr, "Error: failed to register alert callback on pin %d\n",
                ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started.\n");
    printf("  Trigger: GPIO%d | Echo: GPIO%d | Buzzer: GPIO%d\n",
           TRIGGER_PIN, ECHO_PIN, BUZZER_PIN);
    printf("  Threshold: %.1f cm | Poll: every 1 s\n", DISTANCE_THRESHOLD);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* ---- Main measurement loop ---- */
    while (g_running) {
        /* Reset echo state before triggering */
        g_echo_state = false;
        g_start_tick = 0;
        g_end_tick   = 0;

        trigger_sensor();

        /* Wait for the echo callback to record the pulse width */
        uint32_t wait_start = gpioTick();
        while (g_running && !g_echo_state) {
            if ((gpioTick() - wait_start) > ECHO_TIMEOUT_US) {
                fprintf(stderr, "Warning: echo timeout (no object detected)\n");
                break;
            }
            gpioDelay(100); /* 100 µs poll to avoid busy-waiting */
        }

        if (!g_running) {
            break;
        }

        if (g_echo_state) {
            uint32_t pulse_us = g_end_tick - g_start_tick;
            double distance = calculate_distance(pulse_us);

            printf("Distance: %.2f cm\n", distance);
            fflush(stdout);

            if (distance < DISTANCE_THRESHOLD) {
                if (gpioWrite(BUZZER_PIN, 1) < 0) {
                    fprintf(stderr, "Error: failed to activate buzzer\n");
                }
            } else {
                if (gpioWrite(BUZZER_PIN, 0) < 0) {
                    fprintf(stderr, "Error: failed to deactivate buzzer\n");
                }
            }
        }

        /* Sleep for the remainder of the 1-second cycle */
        gpioDelay(LOOP_DELAY_US);
    }

    /* ---- Clean shutdown ---- */
    printf("\nShutting down...\n");
    gpioWrite(BUZZER_PIN, 0);
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

