/*
 * gate_control.c — VL53L1X gate controller for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   VL53L1X SDA  -> GPIO2  (I2C bus 1)
 *   VL53L1X SCL  -> GPIO3  (I2C bus 1)
 *   VL53L1X VDD  -> 3.3 V
 *   VL53L1X GND  -> GND
 *   Gate servo  -> GPIO18 (BCM, hardware PWM)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o gate_control gate_control.c -lpigpio -lrt
 *   (pigpio must be installed; run as root or with appropriate permissions.)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define VL53L1X_ADDR         0x60          /* default 7-bit address          */
#define GATE_GPIO            18            /* BCM 18 — hardware PWM         */
#define PWM_RANGE            1000          /* 0–1000 → 0–1 ms pulse width   */
#define PWM_FREQ             1000          /* 1 kHz carrier frequency       */
#define LOG_FILE             "gate_log.txt"
#define DISTANCE_THRESHOLD_FAR 250          /* mm — gate opens when > 250   */
#define DISTANCE_THRESHOLD_CLOSE 200         /* mm — gate closes when < 200 */
#define POLL_DELAY_US        100000         /* 100 ms between readings      */
#define MAX_DISTANCE_MM       4000          /* sanity cap for readings      */

/* VL53L1X register addresses (16-bit, big-endian on the bus) */
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID  0x010F
#define VL53L1X_REG_SYSTEM_RANGE_START       0x0000
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK  0x0089
#define VL53L1X_REG_RESULT_DISTANCE         0x0096

/* ------------------------------- Globals --------------------------------- */
static int      i2c_handle = -1;
static FILE    *log_file   = NULL;
static volatile sig_atomic_t terminate = 0;

/* --------------------------- Forward declarations ------------------------ */
static int  vl53l1x_init(void);
static int  vl53l1x_read_distance(uint16_t *distance_mm);
static void gate_control(uint16_t distance_mm);
static void log_event(const char *event);
static void signal_handler(int sig);
static void cleanup(void);

/* ------------------------------- Main ----------------------------------- */
int main(void)
{
    /* --- pigpio init ---------------------------------------------------- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* --- I2C open -------------------------------------------------------- */
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (bus %d, addr 0x%02X): %s\n",
                I2C_BUS, VL53L1X_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Sensor init ----------------------------------------------------- */
    if (vl53l1x_init() != 0) {
        fprintf(stderr, "Error: VL53L1X initialisation failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Log file -------------------------------------------------------- */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Signal handling ------------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed: %s\n",
                strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGTERM) failed: %s\n",
                strerror(errno));
    }

    /* --- Gate GPIO setup ------------------------------------------------- */
    if (gpioSetMode(GATE_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, OUTPUT) failed.\n", GATE_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(GATE_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: gpioSetPWMrange(%d, %d) failed.\n",
                GATE_GPIO, PWM_RANGE);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(GATE_GPIO, PWM_FREQ) != PWM_FREQ) {
        fprintf(stderr, "Warning: PWM frequency on GPIO%d did not reach %d Hz.\n",
                GATE_GPIO, PWM_FREQ);
    }
    /* Start with gate closed (PWM off) */
    gpioPWM(GATE_GPIO, 0);

    /* --- Main loop ------------------------------------------------------- */
    uint16_t distance_mm = 0;
    int      gate_state   = 0;          /* 0 = closed, 1 = open */

    while (!terminate) {
        if (vl53l1x_read_distance(&distance_mm) == 0) {
            gate_control(distance_mm);
        } else {
            fprintf(stderr, "Warning: I2C read error — continuing.\n");
        }
        gpioDelay(POLL_DELAY_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

/* --------------------------- VL53L1X helpers ----------------------------- */
static int vl53l1x_init(void)
{
    uint16_t model_id = 0;

    /* 1. Verify model ID so we know the sensor is present and responding. */
    if (i2cReadWordData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID) < 0) {
        fprintf(stderr, "Error: cannot read model ID register.\n");
        return -1;
    }
    model_id = (uint16_t)i2cReadWordData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID);
    if (model_id == 0xFFFF) {
        fprintf(stderr, "Error: invalid model ID read (0xFFFF).\n");
        return -1;
    }
    if (model_id != 0xEA00) {
        fprintf(stderr, "Error: unexpected model ID 0x%04X (expected 0xEA00).\n",
                model_id);
        return -1;
    }
    printf("VL53L1X detected (model ID 0x%04X).\n", model_id);

    /* 2. Set timing budget to 50 ms (0x0034) — the default is 50 ms anyway. */
    if (i2cWriteWordData(i2c_handle, 0x0014, 0x0034) < 0) {
        fprintf(stderr, "Error: cannot set timing budget.\n");
        return -1;
    }

    /* 3. Start ranging. */
    if (i2cWriteWordData(i2c_handle, VL53L1X_REG_SYSTEM_RANGE_START, 0x0001) < 0) {
        fprintf(stderr, "Error: cannot start ranging.\n");
        return -1;
    }

    return 0;
}

static int vl53l1x_read_distance(uint16_t *distance_mm)
{
    char buf[2] = {0, 0};
    int   rc;

    /* Read 16-bit distance register (0x0096) — pigpio i2cReadWordData
     * returns the word as a 16-bit value on success. */
    rc = i2cReadWordData(i2c_handle, VL53L1X_REG_RESULT_DISTANCE);
    if (rc < 0) {
        fprintf(stderr, "Error: i2cReadWordData(0x%04X) failed: %s\n",
                VL53L1X_REG_RESULT_DISTANCE, strerror(errno));
        return -1;
    }

    /* Clear the start bit (bit 0) to read the next measurement. */
    *distance_mm = (uint16_t)rc & 0x7FFF;
    return 0;
}

static void gate_control(uint16_t distance_mm)
{
    int pulse_width = 0;

    if (distance_mm > DISTANCE_THRESHOLD_FAR) {
        pulse_width = 1000;          /* 1 ms — gate opens */
    } else if (distance_mm < DISTANCE_THRESHOLD_CLOSE) {
