/*
 * HC-SR04 ultrasonic distance measurement with servo angle control.
 *
 * Board:  Raspberry Pi 4 Model B
 * Sensor: HC-SR04
 *   Trigger: GPIO23 (BCM)  -> 5 V supply
 *   Echo:    GPIO24 (BCM)  -> 5 V supply (use voltage divider if sensor is 5 V)
 *   GND:     Common ground with Pi
 * Servo:   SG90 on GPIO18 (BCM), 5 V supply
 *
 * Build:  gcc -O2 -Wall -Wextra -o hcsr04_servo hcsr04_servo.c
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>

#include <pigpio.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define TRIGGER_PIN      23
#define ECHO_PIN         24
#define SERVO_PIN        18

/* ---- HC-SR04 timing constants ---- */
#define TRIGGER_PULSE_US 10          /* 10 µs trigger pulse */
#define ECHO_TIMEOUT_US  50000       /* 50 ms max echo wait */
#define SERVO_SETTLE_US  500         /* 500 µs between commands */
#define SERVO_MIN_US     500         /* 0°   -> 500 µs */
#define SERVO_MAX_US     2500        /* 180° -> 2500 µs */
#define SERVO_MIN_ANGLE  0.0f
#define SERVO_MAX_ANGLE  180.0f
#define SERVO_MIN_DIST   2.0f        /* HC-SR04 minimum rated range */
#define SERVO_MAX_DIST   400.0f      /* HC-SR04 maximum rated range */
#define SERVO_MIN_CM     20.0f       /* Below this -> 0° */
#define SERVO_MAX_CM     200.0f      /* Above this -> 180° */

/* ---- Servo pulse-width mapping ---- */
static const int pulse_widths[181];
static const float distance_cm[181];

static void init_servo_mapping(void)
{
    for (int i = 0; i < 181; i++) {
        pulse_widths[i] = (i < 90) ? (int)((float)i * 2500.0f / 90.0f) : (int)((float)(180 - i) * 2500.0f / 90.0f);
        distance_cm[i]  = (float)i;
    }
}

/* ---- Signal handling ---- */
static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ---- HC-SR04 measurement ---- */
/*
 * Returns distance in cm, or -1.0 on timeout / error.
 */
static float measure_distance(int trigger_pin, int echo_pin)
{
    uint32_t start_tick, end_tick, timeout_tick;

    /* Ensure trigger starts low */
    if (gpioWrite(trigger_pin, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger, 0) failed\n");
        return -1.0f;
    }
    gpioDelay(5);  /* settle */

    /* 10 µs trigger pulse */
    if (gpioWrite(trigger_pin, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger, 1) failed\n");
        return -1.0f;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(trigger_pin, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger, 0) failed\n");
        return -1.0f;
    }

    /* Wait for echo rising edge (timeout) */
    timeout_tick = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(echo_pin) == 0) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: echo rising-edge timeout (sensor absent or not responding)\n");
            return -1.0f;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge (timeout) */
    timeout_tick = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(echo_pin) == 1) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: echo falling-edge timeout\n");
            return -1.0f;
        }
    }
    end_tick = gpioTick();

    uint32_t elapsed = end_tick - start_tick;
    float distance = (float)elapsed / 58.0f;  /* speed of sound = 343 m/s */

    if (distance < SERVO_MIN_DIST || distance > SERVO_MAX_DIST) {
        fprintf(stderr, "Warning: distance %.2f cm out of valid range [%.0f, %.0f]\n",
                distance, SERVO_MIN_DIST, SERVO_MAX_DIST);
        return -1.0f;
    }
    return distance;
}

/* ---- Servo control via pigpio pulse-width API ---- */
static int set_servo_angle(int gpio_pin, float angle)
{
    if (angle < SERVO_MIN_ANGLE) angle = SERVO_MIN_ANGLE;
    if (angle > SERVO_MAX_ANGLE) angle = SERVO_MAX_ANGLE;

    int pulse_us = pulse_widths[(int)(angle + 0.5f) * 181 / 180.0f];
    if (gpioServo(gpio_pin, pulse_us) < 0) {
        fprintf(stderr, "Error: gpioServo(%d, %d) failed\n", gpio_pin, pulse_us);
        return -1;
    }
    gpioDelay(SERVO_SETTLE_US);
    return 0;
}

/* ---- Driver API wrapper ---- */
static int driver_init(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(TRIGGER, OUTPUT) failed\n");
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(ECHO, INPUT) failed\n");
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(SERVO, OUTPUT) failed\n");
        gpioTerminate();
        return -1;
    }

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) initial state failed\n");
        gpioTerminate();
        return -1;
    }
    gpioDelay(50);

    init_servo_mapping();
    return 0;
}

static int driver_set_servo_angle(int gpio_pin, float angle)
{
    return set_servo_angle(gpio_pin, angle);
}

static int driver_stop_servo(int gpio_pin)
{
    return set_servo_angle(gpio_pin, 0.0f);
}

static int driver_cleanup(void)
{
    /* Stop servo first for safety */
    if (gpioServo(SERVO_PIN, 0) < 0) {
        fprintf(stderr, "Warning: gpioServo(0) cleanup failed\n");
    }
    gpioDelay(SERVO_SETTLE_US);
    gpioTerminate();
    return 0;
}

/* ---- Main ---- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    if (driver_init() != 0) {
        return EXIT_FAILURE;
    }

    printf("HC-SR04 + servo control started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float distance = measure_distance(TRIGGER_PIN, ECHO_PIN);
        if (distance < 0.0f) {
            fprintf(stderr, "Sensor read error; stopping servo for safety.\n");
            if (driver_stop_servo(SERVO_PIN) != 0) {
                fprintf(stderr, "Warning: failed to stop servo\n");
            }
            gpioDelay(500000);  /* 500 ms back-off */
            continue;
        }

        float angle = 0.0f;
        if (distance < SERVO_MIN_CM) angle = SERVO_MIN_ANGLE;
        else if (distance > SERVO_MAX_CM) angle = SERVO_MAX_ANGLE;
        else angle = (distance - SERVO_MIN_CM) / (SERVO_MAX_CM - SERVO_MIN_CM) * (SERVO_MAX_ANGLE - SERVO_MIN_ANGLE) + SERVO_MIN_ANGLE;

        if (set_servo_angle(SERVO_PIN, angle) != 0) {
            fprintf(stderr, "Warning: failed to set servo angle\n");
        }

        printf("Distance: %.2f cm  ->  Angle: %.1f°\n", distance, angle);

        gpioDelay(100000);  /* 100 ms between measurements */
    }

    printf("\nShutting down...\n");
    if (driver_stop_servo(SERVO_PIN) != 0) {
        fprintf(stderr, "Warning: failed to stop servo during shutdown\n");
    }
    if (driver_cleanup() != 0) {
        fprintf(stderr, "Warning: driver cleanup failed\n");
    }
    return EXIT_SUCCESS;
}

