/*
 * Si7005 humidity & temperature sensor reader for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   Si7005 SDA  -> GPIO2 (pin 3, I2C bus 1 SDA)
 *   Si7005 SCL  -> GPIO3 (pin 5, I2C bus 1 SCL)
 *   Si7005 VDD  -> 3.3 V
 *   Si7005 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o si7005 si7005.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- Si7005 constants -------------------------------------------------- */
#define SI7005_ADDR            0x60
#define SI7005_REG_TEMP       0x05
#define SI7005_REG_HUMIDITY   0x06
#define SI7005_REG_CONFIG     0x01

#define SI7005_CONFIG_MEASRATE 0x01   /* 1 sample per conversion */
#define SI7005_CONFIG_MODE    0x00   /* Continuous mode */
#define SI7005_CONFIG_TRES   0x00   /* 0.5 °C */
#define SI7005_CONFIG_HRES   0x00   /* 0.5 %RH */

#define SI7005_MEAS_DELAY_US  10000  /* 10 ms between config and read */
#define SI7005_CONV_DELAY_US  10000  /* 10 ms conversion time */
#define SI7005_READ_DELAY_US  10000  /* 10 ms between read and next config */
#define SAMPLE_INTERVAL_S     2

/* ---- I2C -------------------------------------------------------------- */
#define I2C_BUS_DEV "/dev/i2c-1"

/* ---- Globals ---------------------------------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ---- Signal handler --------------------------------------------------- */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ---- Low-level I2C helpers -------------------------------------------- */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write_reg8(0x%02X, 0x%02X) failed: %s\n",
                reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "i2c_read_reg8: write reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    n = read(fd, out, 1);
    if (n != 1) {
        fprintf(stderr, "i2c_read_reg8: read reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- Si7005 driver ---------------------------------------------------- */
typedef struct {
    int fd;
    bool opened;
} Si7005;

static int si7005_open(Si7005 *s)
{
    s->fd = open(I2C_BUS_DEV, O_RDWR);
    if (s->fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS_DEV, strerror(errno));
        return -1;
    }
    if (ioctl(s->fd, I2C_SLAVE, SI7005_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                SI7005_ADDR, strerror(errno));
        close(s->fd);
        s->fd = -1;
        return -1;
    }
    s->opened = true;
    return 0;
}

static int si7005_init(Si7005 *s)
{
    if (si7005_open(s) < 0)
        return -1;

    if (i2c_write_reg8(s->fd, SI7005_REG_CONFIG,
                       SI7005_CONFIG_MEASRATE | SI7005_CONFIG_MODE |
                       SI7005_CONFIG_TRES | SI7005_CONFIG_HRES) < 0) {
        fprintf(stderr, "Si7005 init failed: could not write CONFIG register.\n");
        return -1;
    }
    return 0;
}

static int si7005_read_temperature(Si7005 *s, float *temp_c)
{
    uint8_t raw;
    if (i2c_read_reg8(s->fd, SI7005_REG_TEMP, &raw) < 0)
        return -1;
    int16_t raw16 = (int16_t)((raw & 0x0F) << 8 | raw >> 4);
    *temp_c = (float)raw16 / 10.0f;
    return 0;
}

static int si7005_read_humidity(Si7005 *s, float *hum)
{
    uint8_t raw;
    if (i2c_read_reg8(s->fd, SI7005_REG_HUMIDITY, &raw) < 0)
        return -1;
    int16_t raw16 = (int16_t)((raw & 0x0F) << 8 | raw >> 4);
    *hum = (float)raw16 / 10.0f;
    return 0;
}

/* ---- Main ------------------------------------------------------------- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    Si7005 sensor;
    memset(&sensor, 0, sizeof(sensor));

    if (si7005_init(&sensor) < 0) {
        fprintf(stderr, "Si7005 initialization failed. Exiting.\n");
        return EXIT_FAILURE;
    }

    printf("Si7005 initialized on %s (addr 0x%02X).\n", I2C_BUS_DEV, SI7005_ADDR);
    printf("Logging temperature and humidity every %d s. Press Ctrl+C to stop.\n",
           SAMPLE_INTERVAL_S);

    while (g_running) {
        float temperature, humidity;

        if (si7005_read_temperature(&sensor, &temperature) < 0) {
            fprintf(stderr, "Temperature read failed; re-opening I2C bus.\n");
            if (sensor.opened) {
                close(sensor.fd);
                sensor.opened = false;
            }
            sleep(1);
            if (si7005_init(&sensor) < 0) {
                fprintf(stderr, "Re-initialization failed. Exiting.\n");
                return EXIT_FAILURE;
            }
            continue;
        }

        if (si7005_read_humidity(&sensor, &humidity) < 0) {
            fprintf(stderr, "Humidity read failed; re-opening I2C bus.\n");
            if (sensor.opened) {
                close(sensor.fd);
                sensor.opened = false;
            }
            sleep(1);
            if (si7005_init(&sensor) < 0) {
                fprintf(stderr, "Re-initialization failed. Exiting.\n");
                return EXIT_FAILURE;
            }
            continue;
        }

        printf("Temperature: %.2f C, Humidity: %.2f %%RH\n", temperature, humidity);
        fflush(stdout);

        /* Sleep in 100 ms increments so SIGINT is caught promptly. */
        for (int i = 0; i < SAMPLE_INTERVAL_S * 10 && g_running; i++)
            usleep(100000);
    }

    printf("\nShutting down gracefully.\n");
    if (sensor.opened) {
        close(sensor.fd);
        sensor.opened = false;
    }
    return EXIT_SUCCESS;
}

