/*
 * MPU-6050 I2C reader for Raspberry Pi 3 Model B+
 * Bus: I2C-1 (SDA=GPIO2 BCM, SCL=GPIO3 BCM)
 * Reads accel/gyro data every 100 ms and prints to stdout.
 *
 * Build:  gcc -O2 -Wall -o mpu6050 mpu6050.c
 * Run:    ./mpu6050
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- MPU-6050 constants (verified against datasheet) ---- */
#define I2C_BUS        "/dev/i2c-1"
#define MPU6050_ADDR   0x68

#define REG_SMPLRT_DIV  0x19
#define REG_CONFIG     0x1A
#define REG_GYRO_CONFIG 0x1B
#define REG_ACCEL_CONFIG 0x1C
#define REG_ACCEL_XOUT_H 0x3B
#define REG_PWR_MGMT_1   0x6B
#define REG_WHO_AM_I     0x75

#define WHO_AM_I_VAL    0x68

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write_reg8(0x%02X, 0x%02X) failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int i2c_read_block(int fd, uint8_t reg, uint8_t *dst, size_t len)
{
    /* Write the register pointer */
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_block: write reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    /* Read len bytes back */
    ssize_t n = read(fd, dst, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "i2c_read_block: read %zu bytes from 0x%02X failed: %s\n",
                len, reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int mpu6050_init(int fd)
{
    uint8_t who = 0;

    /* Verify sensor identity */
    if (i2c_read_block(fd, REG_WHO_AM_I, &who, 1) != 0) {
        fprintf(stderr, "Cannot read WHO_AM_I — sensor absent or bus error.\n");
        return -1;
    }
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X.\n",
                who, WHO_AM_I_VAL);
        return -1;
    }

    /* Wake the device (clear SLEEP bit) */
    if (i2c_write_reg8(fd, REG_PWR_MGMT_1, 0x00) != 0)
        return -1;
    usleep(100 * 1000);  /* allow oscillator to stabilize */

    /* Sample rate divider = 7 → 1 kHz / (1 + 7) = 125 Hz */
    if (i2c_write_reg8(fd, REG_SMPLRT_DIV, 0x07) != 0)
        return -1;

    /* DLPF_CFG = 3 → 8 Hz bandwidth, 1.2 ms delay */
    if (i2c_write_reg8(fd, 0x1F, 0x03) != 0)
        return -1;

    /* Gyro full-scale range ±250 °/s (FS_SEL = 0) */
    if (i2c_write_reg8(fd, REG_GYRO_CONFIG, 0x00) != 0)
        return -1;

    /* Accel full-scale range ±2 g (AFS_SEL = 0) */
    if (i2c_write_reg8(fd, REG_ACCEL_CONFIG, 0x00) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
static int mpu6050_read(int fd,
                        int16_t *ax, int16_t *ay, int16_t *az,
                        int16_t *gx, int16_t *gy, int16_t *gz)
{
    uint8_t buf[14];

    if (i2c_read_block(fd, REG_ACCEL_XOUT_H, buf, sizeof(buf)) != 0)
        return -1;

    /* Accel: 14 bytes starting at 0x3B → 6 regs × 2 bytes each */
    *ax = (int16_t)((buf[0]  << 8) | buf[1]);
    *ay = (int16_t)((buf[2]  << 8) | buf[3]);
    *az = (int16_t)((buf[4]  << 8) | buf[5]);
    /* Temperature (buf[6..7]) is not used here */

    /* Gyro: 14 bytes starting at 0x3B → 6 regs × 2 bytes each */
    *gx = (int16_t)((buf[8]  << 8) | buf[9]);
    *gy = (int16_t)((buf[10] << 8) | buf[11]);
    *gz = (int16_t)((buf[12] << 8) | buf[13]);

    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Set slave address ---- */
    if (ioctl(g_i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                MPU6050_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* ---- Initialize sensor ---- */
    if (mpu6050_init(g_i2c_fd) != 0) {
        fprintf(stderr, "MPU-6050 initialization failed.\n");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    printf("MPU-6050 ready on %s (addr 0x%02X). Logging every 100 ms.\n",
           I2C_BUS, MPU6050_ADDR);
    printf("Press Ctrl+C to stop.\n\n");

    /* ---- Main loop ---- */
    while (g_running) {
        int16_t ax, ay, az, gx, gy, gz;

        if (mpu6050_read(g_i2c_fd, &ax, &ay, &az, &gx, &gy, &gz) == 0) {
            printf("Accel: X=%6d  Y=%6d  Z=%6d  |  Gyro: X=%6d  Y=%6d  Z=%6d\n",
                   ax, ay, az, gx, gy, gz);
        } else {
            fprintf(stderr, "Read error — continuing.\n");
        }

        usleep(100 * 1000);  /* 100 ms */
    }

    /* ---- Clean shutdown ---- */
    printf("\nShutting down...\n");
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    printf("Done.\n");
    return EXIT_SUCCESS;
}

