/*
 * SHT40 Temperature & Humidity Sensor Reader for Raspberry Pi 4 Model B
 * Uses pigpio for I2C communication.
 *
 * Wiring:
 *   SHT40 VDD  -> 3.3V (Pin 1)
 *   SHT40 GND  -> GND  (Pin 9)
 *   SHT40 SDA  -> GPIO2 / I2C1 SDA (Pin 3)
 *   SHT40 SCL  -> GPIO3 / I2C1 SCL (Pin 5)
 *
 * Build: gcc -Wall -Wextra -O2 -o sht40_reader sht40_reader.c -lpigpio -lrt
 * Run:   sudo ./sht40_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SHT40_ADDR     0x44
#define READ_INTERVAL  5          /* seconds between readings */
#define MEAS_DELAY_US  10000      /* 10 ms measurement wait */
#define MAX_RETRIES    3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF)                        */
/* ------------------------------------------------------------------ */
static uint8_t sht40_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_open(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SHT40_ADDR, g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }
    return 0;
}

static int sht40_trigger_measurement(void)
{
    /*
     * High repeatability measurement command (datasheet):
     *   0x2C 0x36
     */
    uint8_t cmd[2] = { 0x2C, 0x36 };
    int rc = i2cWriteDevice(g_i2c_handle, (char *)cmd, 2);
    if (rc < 0) {
        fprintf(stderr, "Error: i2cWriteDevice (trigger) failed: %d\n", rc);
        return -1;
    }
    return 0;
}

static int sht40_read_data(uint8_t *data, size_t len)
{
    int rc = i2cReadDevice(g_i2c_handle, (char *)data, len);
    if (rc != (int)len) {
        fprintf(stderr, "Error: i2cReadDevice expected %zu bytes, got %d\n",
                len, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor read                                                         */
/* ------------------------------------------------------------------ */
static int sht40_read(float *temperature, float *humidity)
{
    uint8_t data[6];

    if (sht40_trigger_measurement() != 0)
        return -1;

    gpioDelay(MEAS_DELAY_US);

    if (sht40_read_data(data, sizeof(data)) != 0)
        return -1;

    /* Validate CRC-8 for temperature bytes */
    if (sht40_crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "Error: temperature CRC mismatch (calc=0x%02X, got=0x%02X)\n",
                sht40_crc8(&data[0], 2), data[2]);
        return -1;
    }

    /* Validate CRC-8 for humidity bytes */
    if (sht40_crc8(&data[3], 2) != data[5]) {
        fprintf(stderr, "Error: humidity CRC mismatch (calc=0x%02X, got=0x%02X)\n",
                sht40_crc8(&data[3], 2), data[5]);
        return -1;
    }

    uint16_t temp_raw = ((uint16_t)data[0] << 8) | data[1];
    uint16_t hum_raw  = ((uint16_t)data[3] << 8) | data[4];

    *temperature = -45.0f + 175.0f * (float)temp_raw / 65535.0f;
    *humidity    = 100.0f * (float)hum_raw  / 65535.0f;

    /* Clamp humidity to valid physical range */
    if (*humidity < 0.0f)   *humidity = 0.0f;
    if (*humidity > 100.0f) *humidity = 100.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Register signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Open I2C bus */
    if (i2c_open() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("SHT40 sensor reader started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float temperature, humidity;

        if (sht40_read(&temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n",
                   temperature, humidity);
        } else {
            fprintf(stderr, "Error: sensor read failed. Re-opening I2C bus.\n");
            if (i2c_open() != 0) {
                fprintf(stderr, "Error: I2C re-open failed. Exiting.\n");
                break;
            }
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < READ_INTERVAL && g_running; i++)
            sleep(1);
    }

    /* Cleanup */
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

