/*
 * MLX90614ESF-BAA infrared temperature logger for Raspberry Pi 3 Model B+
 * Bus: /dev/i2c-1  Address: 0x5C  (default for MLX90614ESF-BAA)
 * Reads ambient and object temperatures every 5 seconds and appends
 * timestamped readings to temperature_log.csv.
 *
 * Build:  gcc -O2 -Wall -Wextra -o mlx90614_logger mlx90614_logger.c
 * Run:    ./mlx90614_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MLX90614_ADDR  0x5C
#define LOG_FILE       "temperature_log.csv"
#define SAMPLE_PERIOD  5          /* seconds between readings */

/* MLX90614ESF-BAA register addresses */
#define REG_AMBIENT_TEMP  0x00
#define REG_OBJECT_TEMP   0x01
#define REG_CONFIG        0x0F

/* Config register bits */
#define CFG_MODE_A       0x01
#define CFG_MODE_B       0x02
#define CFG_MODE_OSC     0x04
#define CFG_MODE_INT     0x08
#define CFG_INT_EN       0x10
#define CFG_INT_MODE     0x20
#define CFG_INT_POL      0x40
#define CFG_INT_QUE      0x80

/* Config value for default operation: ambient + object, no interrupt */
#define CFG_DEFAULT      (CFG_MODE_A | CFG_MODE_B | CFG_MODE_OSC | CFG_MODE_INT | CFG_INT_EN | CFG_INT_MODE | CFG_INT_POL | CFG_INT_QUE)

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit value to an 8-bit register (big-endian on the wire).  */
static int i2c_write_reg16(int fd, uint8_t reg, uint16_t val)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(val >> 8);
    buf[2] = (uint8_t)(val & 0xFF);

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write_reg16(0x%02X): write failed: %s\n",
                reg, strerror(errno));
        return -1;
