/*
 * Raspberry Pi Zero W – Sensirion STS30-DIS Temperature Logger
 *
 * Wiring:
 *   STS30-DIS SDA  -> GPIO2 (pin 3, I2C bus 1 SDA)
 *   STS30-DIS SCL  -> GPIO3 (pin 5, I2C bus 1 SCL)
 *   STS30-DIS VDD  -> 3.3 V
 *   STS30-DIS GND  -> GND
 *
 * I2C address: 0x48 (ADDR pin tied to GND)
 *
 * Build:  gcc -O2 -Wall -Wextra -o enclosure_temp enclosure_temp.c
 */

#define _POSIX_C_SOURCE 200809L

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define STS30_ADDR     0x48
#define LOG_FILE       "enclosure_temp_log.txt"
#define ERROR_LOG_FILE "error_log.txt"
#define SAMPLE_INTERVAL_SEC 5

/* STS30-DIS temperature-only measurement command (no clock stretching) */
#define STS30_CMD_TEMP  0x361F

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a 16-bit command to the STS30-DIS (no data payload). */
static int sts30_write_cmd(int fd, uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "sts30_write_cmd: write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* Read exactly `len` bytes from the STS30-DIS. */
static int sts30_read_bytes(int fd, uint8_t *buf, size_t len)
{
    size_t total = 0;
    while (total < len) {
        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "sts30_read_bytes: read failed: %s\n", strerror(errno));
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "sts30_read_bytes: unexpected EOF (sensor may be absent)\n");
            return -1;
        }
        total += (size_t)n;
    }
    return 0;
}

/* Read the 2-byte temperature result from the STS30-DIS. */
static int sts30_read_temperature(int fd, float *temperature)
{
    if (sts30_write_cmd(fd, STS30_CMD_TEMP) < 0)
        return -1;

    /* STS30-DIS needs ~45 ms for the conversion to complete. */
    usleep(45000);

    uint8_t data[2];
    if (sts30_read_bytes(fd, data, sizeof(data)) < 0)
        return -1;

    int16_t raw = (int16_t)((data[0] << 8) | data[1]);
    *temperature = (float)raw / 10.0f;
    return 0;
}

static void log_temperature(float temperature)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "log_temperature: fopen(%s) failed: %s\n",
                LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "log_temperature: localtime_r failed\n");
        fclose(fp);
        return;
    }

    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, %.2f\n", timestamp, temperature);
    fclose(fp);
}

static void log_error(const char *message)
{
    FILE *fp = fopen(ERROR_LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "log_error: fopen(%s) failed: %s\n",
                ERROR_LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "log_error: localtime_r failed\n");
        fclose(fp);
        return;
    }

    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, %s\n", timestamp, message);
    fclose(fp);
}

int main(void)
{
    /* Install signal handlers for graceful shutdown. */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        log_error("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, STS30_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                STS30_ADDR, strerror(errno));
        log_error("Failed to set I2C slave address");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("STS30-DIS logger started. Logging to %s every %d s. Press Ctrl+C to stop.\n",
           LOG_FILE, SAMPLE_INTERVAL_SEC);

    while (g_running) {
        float temperature;
        if (sts30_read_temperature(fd, &temperature) == 0) {
            printf("Temperature: %.2f °C\n", temperature);
            log_temperature(temperature);
        } else {
            log_error("Failed to read temperature from STS30-DIS");
        }

        /* Sleep in 1-second increments so signals are caught promptly. */
        for (int i = 0; i < SAMPLE_INTERVAL_SEC && g_running; i++)
            sleep(1);
    }

    printf("\nShutting down...\n");
    close(fd);
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

