/*
 * SDP810‑125Pa differential pressure sensor logger for Raspberry Pi Zero W
 * I2C bus 1, address 0x60 (7-bit), continuous measurement mode.
 *
 * Build:  gcc -O2 -Wall -Wextra -o sdp810_logger sdp810_logger.c
 * Run:    ./sdp810_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x60          /* 7-bit Sensirion I2C address */
#define LOG_FILE       "pressure_log.csv"
#define SAMPLE_PERIOD  1             /* seconds between measurements */
#define MEAS_DELAY_US  2000          /* 2 ms conversion time (datasheet) */

/* SDP810 continuous measurement command (datasheet, big-endian on wire) */
static const uint8_t CMD_CONT_MEAS[2] = { 0x36, 0x88 };

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF)                        */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void get_iso8601_utc(char *buf, size_t len)
{
    time_t now = time(NULL);
    struct tm tm_utc;
    gmtime_r(&now, &tm_utc);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%SZ", &tm_utc);
}

/* ------------------------------------------------------------------ */
/* Append a CSV row with CRC validation                               */
/* ------------------------------------------------------------------ */
static int log_data(const char *ts, float pressure, float temperature)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    /* Write header if file is empty */
    if (fseek(fp, 0, SEEK_END) == 0) {
        long sz = ftell(fp);
        if (sz == 0)
            fprintf(fp, "Timestamp,Pressure_Pa,Temperature_C\n");
    }

    if (fprintf(fp, "%s,%.2f,%.2f\n", ts, pressure, temperature) < 0) {
        fprintf(stderr, "fprintf: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose(%s): %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one 9-byte measurement frame from the SDP810                    */
/* Returns 0 on success, -1 on I/O or CRC error.                       */
/* ------------------------------------------------------------------ */
static int read_sdp810(int handle, float *pressure, float *temperature)
{
    uint8_t buf[9];
    int n = i2cReadDevice(handle, (char *)buf, sizeof(buf));
    if (n != (int)sizeof(buf)) {
        fprintf(stderr, "i2cReadDevice: expected %zu bytes, got %d (%s)\n",
                sizeof(buf), n, n < 0 ? pigpio_error(n) : "short read");
        return -1;
    }

    /* CRC validation of each 3-byte group */
    for (int i = 0; i < 3; i++) {
        if (crc8(&buf[i * 3], 2) != buf[i * 3 + 2]) {
            fprintf(stderr, "CRC mismatch on group %d\n", i);
            return -1;
        }
    }

    int16_t dp_raw  = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t temp_raw = (int16_t)((buf[3] << 8) | buf[4]);
    uint16_t scale_dp = (uint16_t)((buf[6] << 8) | buf[7]);
    uint16_t scale_temp = (uint16_t)((buf[9] << 8) | buf[10]);

    if (scale_dp == 0 || scale_temp == 0) {
        fprintf(stderr, "Invalid scale factor (0) from sensor\n");
        return -1;
    }

    *pressure    = (float)dp_raw  / (float)scale_dp;
    *temperature = (float)temp_raw / (float)scale_temp;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise failed\n");
        return EXIT_FAILURE;
    }

    /* --- I2C open --------------------------------------------------- */
    int handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "i2cOpen(bus=%d, addr=0x%02X): %s\n",
                I2C_BUS, I2C_ADDR, pigpio_error(handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Sensor configuration: continuous measurement -------------- */
    if (i2cWriteDevice(handle, (char *)CMD_CONT_MEAS, 2) != 0) {
        fprintf(stderr, "Failed to send continuous-measurement command\n");
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Allow first conversion to complete */
    gpioDelay(MEAS_DELAY_US);

    /* --- Signal handlers ------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* --- Main loop -------------------------------------------------- */
    while (g_running) {
        char ts[32];
        get_iso8601_utc(ts, sizeof(ts));

        float pressure, temperature;
        if (read_sdp810(handle, &pressure, &temperature) == 0) {
            if (log_data(ts, pressure, temperature) != 0) {
                fprintf(stderr, "Logging failed; continuing\n");
            }
        } else {
            fprintf(stderr, "%s: read/sensor error\n", ts);
        }

        /* Sleep SAMPLE_PERIOD seconds, checking g_running every 100 ms */
        for (int i = 0; i < SAMPLE_PERIOD * 10 && g_running; i++)
            gpioDelay(100000);  /* 100 ms */
    }

    /* --- Cleanup --------------------------------------------------- */
    i2cClose(handle);
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

