/*
 * SHT40 humidity & temperature logger for Raspberry Pi 3 Model B+
 * Bus: I2C-1 (SDA=GPIO2, SCL=GPIO3), 7-bit address 0x44
 * Command: high repeatability measurement (0x2B)
 * Read: 6 bytes (T_MSB, T_LSB, T_CRC, RH_MSB, RH_LSB, RH_CRC)
 * CRC-8: polynomial 0x31, init 0xFF
 * Build: gcc -O2 -Wall -o sht40_log sht40_log.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SHT40_ADDR     0x44
#define MEASURE_CMD    0x2B   /* high repeatability, clock stretching disabled */
#define MEASURE_DELAY_MS 10
#define LOG_INTERVAL_S  5
#define LOG_FILE       "sht40_log.txt"

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) == -1)
        perror("sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* Sensirion CRC-8 (polynomial 0x31, init 0xFF, no final XOR)          */
/* ------------------------------------------------------------------ */
static uint8_t sensirion_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int fd, uint8_t cmd)
{
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write(0x%02X) failed: %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C read short: got %zd of %zu bytes\n", n, len);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor read                                                         */
/* ------------------------------------------------------------------ */
static int read_sht40(int fd, float *temperature, float *humidity)
{
    uint8_t data[6];

    if (i2c_write_cmd(fd, MEASURE_CMD) != 0)
        return -1;

    usleep(MEASURE_DELAY_MS * 1000);

    if (i2c_read_bytes(fd, data, sizeof(data)) != 0)
        return -1;

    /* CRC validation */
    if (sensirion_crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }
    if (sensirion_crc8(&data[3], 2) != data[5]) {
        fprintf(stderr, "Humidity CRC mismatch\n");
        return -1;
    }

    uint16_t t_raw = ((uint16_t)data[0] << 8) | data[1];
    uint16_t h_raw = ((uint16_t)data[3] << 8) | data[4];

    *temperature = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *humidity    = 100.0f * (float)h_raw / 65535.0f;

    /* Sanity range checks */
    if (*temperature < -45.0f || *temperature > 125.0f) {
        fprintf(stderr, "Temperature out of range: %.2f C\n", *temperature);
        return -1;
    }
    if (*humidity < 0.0f || *humidity > 100.0f) {
        fprintf(stderr, "Humidity out of range: %.2f %%\n", *humidity);
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, float temperature, float humidity)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Temperature: %.2f C, Humidity: %.2f %%\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                temperature, humidity) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    install_signal_handlers();

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SHT40_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE (0x%02X) failed: %s\n",
                SHT40_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("SHT40 logger started. Logging to %s every %d s. Press Ctrl+C to stop.\n",
           LOG_FILE, LOG_INTERVAL_S);

    while (g_running) {
        float temperature, humidity;

        if (read_sht40(g_i2c_fd, &temperature, &humidity) == 0) {
            if (log_data(g_log_fp, temperature, humidity) != 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            } else {
                printf("Temperature: %.2f C, Humidity: %.2f %%\n",
                       temperature, humidity);
            }
        } else {
            fprintf(stderr, "Sensor read failed; will retry next cycle.\n");
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < LOG_INTERVAL_S && g_running; i++)
            sleep(1);
    }

    printf("\nShutting down cleanly.\n");
    cleanup();
    return EXIT_SUCCESS;
}

