/*
 * SDP31 differential pressure & temperature logger for Raspberry Pi Zero W.
 *
 * Wiring:
 *   SDP31 SDA  -> GPIO2  (pin 3, I2C bus 1)
 *   SDP31 SCL  -> GPIO3  (pin 5, I2C bus 1)
 *   SDP31 VDD  -> 3.3 V
 *   SDP31 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o sdp31_logger sdp31_logger.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x60
#define LOG_FILE       "airflow.log"
#define SAMPLE_PERIOD  100000          /* microseconds (100 ms) */
#define MAX_RETRIES    3
#define TRIGGER_DELAY  1000            /* microseconds (1 ms) */
#define MEAS_DELAY     1000            /* microseconds (1 ms)  */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    struct tm tmv;
    if (localtime_r(&now, &tmv) != NULL)
        strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tmv);
    else
        snprintf(buf, len, "1970-01-01 00:00:00");
}

static void log_error(const char *msg)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));
    fprintf(stderr, "[%s] ERROR: %s (errno=%d: %s)\n",
            ts, msg, errno, strerror(errno));
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int handle, uint8_t cmd)
{
    int rc = i2cWriteByte(handle, cmd);
    if (rc < 0) {
        char buf[128];
        snprintf(buf, sizeof(buf), "i2cWriteByte(0x%02X) failed: %d", cmd, rc);
        log_error(buf);
    }
    return rc;
}

static int i2c_read_bytes(int handle, uint8_t *buf, int len)
{
    int rc = i2cReadDevice(handle, (char *)buf, len);
    if (rc != len) {
        char buf[128];
        snprintf(buf, sizeof(buf), "i2cReadDevice expected %d bytes, got %d", len, rc);
        log_error(buf);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* SDP31 sensor                                                         */
/* ------------------------------------------------------------------ */
/*
 * Trigger continuous measurement and read the 6-byte response.
 * Returns 0 on success, -1 on persistent failure.
 */
static int read_sdp31(int handle, float *pressure_pa, float *temp_c)
{
    uint8_t data[6];

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        /* Trigger continuous measurement (0x36) */
        if (i2c_write_cmd(handle, 0x36) < 0) {
            if (attempt < MAX_RETRIES - 1)
                gpioDelay(2 * 1000);          /* 2 ms backoff */
            continue;
        }

        /* Wait for the first conversion to complete */
        gpioDelay(MEAS_DELAY);

        /* Read 6 bytes: pressure(2)+crc, temperature(2)+crc */
        if (i2c_read_bytes(handle, data, 6) < 0) {
            if (attempt < MAX_RETRIES - 1)
                gpioDelay(4 * 1000);          /* 4 ms backoff */
            continue;
        }

        /* CRC check (polynomial 0x31, init 0xFF) */
        uint8_t crc = 0xFF;
        for (int i = 0; i < 2; i++) {
            crc ^= data[i];
            for (int b = 0; b < 8; b++)
                crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
        }
        if (crc != data[2]) {
            char buf[128];
            snprintf(buf, sizeof(buf), "CRC mismatch: calc=0x%02X recv=0x%02X", crc, data[2]);
            log_error(buf);
            if (attempt < MAX_RETRIES - 1)
                gpioDelay(8 * 1000);          /* 8 ms backoff */
            continue;
        }

        /* Read temperature (bytes 3-4) */
        uint8_t t_crc = 0xFF;
        for (int i = 0; i < 2; i++) {
            t_crc ^= data[3 + i];
            for (int b = 0; b < 8; b++)
                t_crc = (t_crc & 0x80) ? (t_crc << 1) ^ 0x31 : (t_crc << 1);
        }
        if (t_crc != data[5]) {
            char buf[128];
            snprintf(buf, sizeof(buf), "Temperature CRC mismatch: calc=0x%02X recv=0x%02X", t_crc, data[5]);
            log_error(buf);
            if (attempt < MAX_RETRIES - 1)
                gpioDelay(16 * 1000);         /* 16 ms backoff */
            continue;
        }

        /* Convert raw values */
        int16_t raw_p = (int16_t)((data[0] << 8) | data[1]);
        int16_t raw_t = (int16_t)((data[3] << 8) | data[4]);

        *pressure_pa    = (float)raw_p / 60.0f;   /* Pa  */
        *temp_c         = (float)raw_t / 200.0f;  /* °C  */

        return 0;
    }

    log_error("SDP31 read failed after all retries");
    return -1;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, float pressure_pa, float temp_c)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));
    if (fprintf(fp, "%s,%.2f,%.2f\n", ts, pressure_pa, temp_c) < 0) {
        log_error("fprintf to log file failed");
        return -1;
    }
    if (fflush(fp) != 0) {
        log_error("fflush on log file failed");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(int i2c_handle, FILE *fp)
{
    if (i2c_handle >= 0)
        i2cClose(i2c_handle);
    if (fp != NULL)
        fclose(fp);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int i2c_handle = -1;
    FILE *fp = NULL;

    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- I2C open --- */
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        char buf[128];
        snprintf(buf, sizeof(buf), "i2cOpen(bus=%d, addr=0x%02X) failed: %d", I2C_BUS, I2C_ADDR, i2c_handle);
        log_error(buf);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Log file --- */
    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        log_error("fopen log file failed");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        log_error("sigaction failed");
        cleanup(i2c_handle, fp);
        return EXIT_FAILURE;
    }

    printf("SDP31 logger started. Logging to %s every %d ms. Press Ctrl+C to stop.\n",
           LOG_FILE, SAMPLE_PERIOD / 1000);

    /* --- Main loop --- */
    while (g_running) {
        float pressure_pa = 0.0f, temp_c = 0.0f;

        if (read_sdp31(i2c_handle, &pressure_pa, &temp_c) == 0) {
            if (log_data(fp, pressure_pa, temp_c) < 0) {
                /* Non-fatal: keep sampling, but report the error once */
                log_error("Logging failed for this sample");
            }
        } else {
            /* Non-fatal: skip this sample, keep running */
        }

        gpioDelay(SAMPLE_PERIOD);
    }

    printf("\nShutting down...\n");
    cleanup(i2c_handle, fp);
    return EXIT_SUCCESS;
}

