/*
 * Si7015 Temperature & Humidity Sensor Reader for Raspberry Pi 3 Model B+
 * Uses pigpio for I2C communication.
 *
 * Wiring:
 *   Si7015 SDA -> GPIO2 (Pin 3)
 *   Si7015 SCL -> GPIO3 (Pin 5)
 *   Si7015 VDD -> 3.3V
 *   Si7015 GND -> GND
 *
 * Build: gcc -o si7015_reader si7015_reader.c -lpigpio -lrt
 * Run:   sudo ./si7015_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI7015_ADDR 0x44
#define LOG_FILE "sensor_data.txt"
#define SAMPLE_INTERVAL_SEC 5
#define MEASUREMENT_TIMEOUT_MS 20

/* Si7015 Commands (No Hold Master mode) */
#define SI7015_MEASURE_TEMP_HOLD  0x06
#define SI7015_MEASURE_HUMID_HOLD 0x05
#define SI7015_RESET               0xFE

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI7015_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at address 0x%02X on bus %d (pigpio error %d).\n",
                SI7015_ADDR, I2C_BUS, i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int reset_sensor(void) {
    if (i2cWriteByte(i2c_handle, SI7015_RESET) != 0) {
        fprintf(stderr, "Error: Failed to send reset command to Si7015.\n");
        return -1;
    }
    gpioDelay(15000); /* 15 ms reset settling time */
    return 0;
}

static int read_measurement(uint8_t cmd, uint16_t *raw) {
    if (i2cWriteByte(i2c_handle, cmd) != 0) {
        fprintf(stderr, "Error: Failed to write measurement command 0x%02X to Si7015.\n", cmd);
        return -1;
    }

    /* Poll until data is ready (no hold master mode) */
    for (int i = 0; i < MEASUREMENT_TIMEOUT_MS; i++) {
        gpioDelay(1000); /* 1 ms */
        if (i2cReadByte(i2c_handle) >= 0) {
            break;
        }
        gpioDelay(1000);
    }

    if (i2cReadByte(i2c_handle) < 0) {
        fprintf(stderr, "Error: Failed to read measurement data after %d ms.\n", MEASUREMENT_TIMEOUT_MS);
        return -1;
    }

    int msb = i2cReadByte(i2c_handle);
    int lsb = i2cReadByte(i2c_handle);

    if (msb < 0 || lsb < 0) {
        fprintf(stderr, "Error: Failed to read measurement data (MSB: %d, LSN: %d).\n", msb, lsb);
        return -1;
    }

    *raw = ((uint16_t)msb << 8) | (uint16_t)lsb;
    return 0;
}

static int read_temperature(float *temp) {
    uint16_t raw;
    if (read_measurement(SI7015_MEASURE_TEMP_HOLD, &raw) != 0) {
        return -1;
    }
    *temp = ((float)raw / 65536.0f) * 165.0f - 40.0f;
    return 0;
}

static int read_humidity(float *hum) {
    uint16_t raw;
    if (read_measurement(SI7015_MEASURE_HUMID_HOLD, &raw) != 0) {
        return -1;
    }
    *hum = ((float)raw / 65536.0f) * 100.0f;
    return 0;
}

static void log_data(float temp, float hum) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, temp, hum);
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
    printf("%s, Temperature: %.2f C, Humidity: %.2f %%\n", timestamp, temp, hum);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to register SIGINT handler: %s\n", strerror(errno));
    }

    if (init_i2c() != 0) {
        return EXIT_FAILURE;
    }

    if (reset_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Si7015 sensor reader started. Logging to %s every %d seconds. Press Ctrl+C to exit.\n",
           LOG_FILE, SAMPLE_INTERVAL_SEC);

    while (running) {
        float temperature, humidity;

        if (read_temperature(&temperature) == 0 && read_humidity(&humidity) == 0) {
            log_data(temperature, humidity);
        } else {
            fprintf(stderr, "Error: Failed to read sensor data.\n");
        }

        /* Sleep in 1-second increments to allow signal handler to interrupt promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

