/*
 * SDP800-500Pa differential-pressure logger for Raspberry Pi 3 Model B+.
 *
 * Wiring:
 *   SDP800 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   SDP800 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   SDP800 VDD  -> 3.3 V
 *   SDP800 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o airflow airflow.c
 * Run:    ./airflow   (user must be in the 'i2c' group or run with
 *                  appropriate permissions; the program does not
 *                  set the I2C address or use a persistent device
 *                  tree, so root is not strictly required)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SDP800_ADDR    0x60
#define LOG_FILE       "airflow_data.txt"
#define SAMPLE_PERIOD  100000          /* microseconds (100 ms) */
#define TRIGGER_DELAY  45000           /* microseconds (45 ms)   */

/* SDP800 continuous measurement, mass flow mode, 9-byte frame */
static const uint8_t CMD_CONT_MEAS[2] = { 0x36, 0x88 };

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* CRC-8 polynomial 0x31, init 0xFF, as used by Sensirion */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

static int i2c_write(int fd, const uint8_t *buf, size_t len)
{
    if (write(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "i2c_write: write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "i2c_read: read failed (got %zd of %zu): %s\n",
                n, len, n < 0 ? strerror(errno) : "short read");
        return -1;
    }
    return 0;
}

static int sdp800_trigger(int fd)
{
    return i2c_write(fd, CMD_CONT_MEAS, sizeof(CMD_CONT_MEAS));
}

static int sdp800_read(int fd, float *pressure, float *temperature)
{
    uint8_t raw[9];

    if (i2c_read(fd, raw, sizeof(raw)) != 0)
        return -1;

    /* Validate CRCs for each 3-byte word */
    if (crc8(&raw[0], 2) != raw[2]) {
        fprintf(stderr, "sdp800_read: pressure CRC mismatch\n");
        return -1;
    }
    if (crc8(&raw[3], 2) != raw[5]) {
        fprintf(stderr, "sdp800_read: temperature CRC mismatch\n");
        return -1;
    }
    if (crc8(&raw[6], 2) != raw[8]) {
        fprintf(stderr, "sdp800_read: scale-factor CRC mismatch\n");
        return -1;
    }

    int16_t raw_p = (int16_t)((raw[0] << 8) | raw[1]);
    int16_t raw_t = (int16_t)((raw[3] << 8) | raw[4]);
    int16_t raw_f = (int16_t)((raw[6] << 8) | raw[7]);

    *pressure    = (float)raw_p / 60.0f;   /* Pa  */
    *temperature = (float)raw_t / 200.0f;  /* °C  */
    return 0;
}

static int log_data(const char *filename, float pressure, float temperature)
{
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "log_data: fopen failed: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "log_data: localtime_r failed\n");
        fclose(fp);
        return -1;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.2f,%.2f\n", ts, pressure, temperature) < 0) {
        fprintf(stderr, "log_data: fprintf failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "log_data: fclose failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SDP800_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                SDP800_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (sdp800_trigger(fd) != 0) {
        fprintf(stderr, "Failed to trigger SDP800 continuous measurement.\n");
        close(fd);
        return EXIT_FAILURE;
    }

    /* First conversion is ready after ~45 ms */
    usleep(TRIGGER_DELAY);

    printf("SDP800 logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        float pressure, temperature;

        if (sdp800_read(fd, &pressure, &temperature) != 0) {
            fprintf(stderr, "Sensor read error; continuing.\n");
        } else {
            if (log_data(LOG_FILE, pressure, temperature) != 0) {
                fprintf(stderr, "Logging error; continuing.\n");
            } else {
                printf("%s  Pressure: %.2f Pa  Temperature: %.2f °C\n",
                       LOG_FILE, pressure, temperature);
            }
        }

        /* Sleep in 1 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD / 1000 && g_running; i++)
            usleep(1000);
    }

    printf("\nShutting down cleanly.\n");
    close(fd);
    return EXIT_SUCCESS;
}

