/*
 * STS30 Temperature Logger for Raspberry Pi Zero W
 * Uses pigpio for I2C communication.
 * Logs temperature readings to enclosure_temp_log.txt with timestamps.
 * Logs errors to error_log.txt with timestamps.
 * Handles SIGINT for graceful shutdown.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define STS30_ADDR 0x48
#define LOG_FILE "enclosure_temp_log.txt"
#define ERROR_LOG_FILE "error_log.txt"
#define SAMPLE_INTERVAL_SEC 5
#define MEASUREMENT_DELAY_MS 15

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static FILE *error_log_file = NULL;

/* CRC-8 calculation for Sensirion STS30 sensors */
static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);

    if (error_log_file) {
        fprintf(error_log_file, "%s - ERROR: %s\n", timestamp, message);
        fflush(error_log_file);
    }
    fprintf(stderr, "%s - ERROR: %s\n", timestamp, message);
}

static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

static int read_temperature(float *temperature) {
    uint8_t cmd[2] = {0x36, 0x08}; // Single shot, high repeatability, clock stretching disabled
    uint8_t buf[3];
    int result;

    result = i2cWriteDevice(I2C_BUS, (char *)cmd, 2);
    if (result != 0) {
        log_error("Failed to write measurement command to STS30");
        return -1;
    }

    gpioDelay(MEASUREMENT_DELAY_MS * 1000);

    result = i2cReadDevice(I2C_BUS, (char *)buf, 3);
    if (result != 3) {
        log_error("Failed to read temperature data from STS30");
        return -1;
    }

    if (crc8(buf, 2) != buf[2]) {
        log_error("Temperature CRC check failed");
        return -1;
    }

    int16_t raw_temperature = (buf[0] << 8) | buf[1];
    *temperature = (float)raw_temperature / 10.0f;
    return 0;
}

