    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);

    fprintf(log_file, "%s - Temperature: %.2f C\n", timestamp, temperature);
