    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    error_log_file = fopen(ERROR_LOG_FILE, "a");
    if (error_log_file == NULL) {
        perror("Error opening error log file");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("STS30 Temperature Logger started. Press Ctrl+C to exit.\n");

    while (running) {
        if (read_temperature(&temperature) == 0) {
            log_temperature(temperature);
        } else {
            log_error("Failed to read temperature");
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down gracefully...\n");
    if (log_file) fclose(log_file);
    if (error_log_file) fclose(error_log_file);
    gpioTerminate();
    return 0;
}

