/*
 * SHT40 Greenhouse Monitor — Raspberry Pi 3 Model B+
 * Bus:  /dev/i2c-1  (BCM pins 2/3)
 * Sensor: Sensirion SHT40 at address 0x44
 * Command: 0x2B  (high repeatability, clock stretching disabled)
 * Response: 6 bytes  T_MSB T_LSB T_CRC RH_MSB RH_LSB RH_CRC
 * CRC-8:  polynomial 0x31, init 0xFF
 * Logging: sht40_log.txt  every 5 s  (Ctrl+C = clean shutdown)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SHT40_ADDR     0x44
#define CMD_MEASURE    0x2B
#define LOG_FILE       "sht40_log.txt"
#define SAMPLE_PERIOD  5          /* seconds between readings */
#define MEASURE_DELAY  8500        /* microseconds (>= 8.5 ms) */

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion: poly 0x31, init 0xFF, no final XOR)               */
/* ------------------------------------------------------------------ */
static uint8_t sht_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t t = time(NULL);
    struct tm tmv;
    localtime_r(&t, &tmv);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tmv);
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int fd, uint8_t cmd)
{
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "[I2C] write(0x%02X) failed: %s\n",
                cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "[I2C] read(%zu bytes) failed: %s\n",
                len, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor read                                                         */
/* ------------------------------------------------------------------ */
static int read_sht40(int fd, float *temperature, float *humidity)
{
    uint8_t buf[6];

    if (i2c_write_cmd(fd, CMD_MEASURE) < 0)
        return -1;

    usleep(MEASURE_DELAY);

    if (i2c_read_bytes(fd, buf, sizeof(buf)) < 0)
        return -1;

    /* Validate CRCs */
    if (sht_crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "[SHT40] temperature CRC mismatch\n");
        return -1;
    }
    if (sht_crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "[SHT40] humidity CRC mismatch\n");
        return -1;
    }

    uint16_t t_raw = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t rh_raw = ((uint16_t)buf[3] << 8) | buf[4];

    *temperature = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *humidity    = 100.0f * (float)rh_raw / 65535.0f;

    /* Sanity range checks */
    if (*temperature < -45.0f || *temperature > 125.0f ||
        *humidity < 0.0f || *humidity > 100.0f) {
        fprintf(stderr, "[SHT40] out-of-range reading: T=%.2f H=%.2f\n",
                *temperature, *humidity);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, float temperature, float humidity)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));

    if (fprintf(fp, "%s, Temperature: %.2f C, Humidity: %.2f %%\n",
                ts, temperature, humidity) < 0) {
        fprintf(stderr, "[LOG] write failed: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "[I2C] open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SHT40_ADDR) < 0) {
        fprintf(stderr, "[I2C] ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                SHT40_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "[LOG] fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("SHT40 greenhouse monitor started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_PERIOD);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        float temperature, humidity;

        if (read_sht40(g_i2c_fd, &temperature, &humidity) == 0) {
            if (log_data(g_log_fp, temperature, humidity) < 0) {
                fprintf(stderr, "[MAIN] logging failed; continuing.\n");
            } else {
                printf("%s  T=%.2f C  RH=%.2f %%\n",
                       __TIME__, temperature, humidity);
            }
        } else {
            fprintf(stderr, "[MAIN] sensor read failed; continuing.\n");
        }

        /* Sleep in 1 s increments so SIGINT is responsive */
        for (int i = 0; i < SAMPLE_PERIOD && g_running; i++)
            sleep(1);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

