        } else {
            fprintf(stderr, "[MAIN] sensor read failed; continuing.\n");
        }

        /* Sleep in 1 s increments so SIGINT is responsive */
        for (int i = 0; i < SAMPLE_PERIOD && g_running; i++)
            sleep(1);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

code:
/*
 * SDP800-500Pa differential pressure monitor for Raspberry Pi 3 Model B+
 * Bus: /dev/i2c-1  Address: 0x68  (SDP800 default)
 * Reads pressure and temperature every 1 s, validates CRC-8, logs to
 * airflow_data.txt with timestamps.
 *
 * Build:  gcc -O2 -Wall -Wextra -o sdp800_monitor sdp800_monitor.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SDP800_ADDR    0x68
#define LOG_FILE       "airflow_data.txt"
#define SAMPLE_PERIOD  1          /* seconds between samples */
#define MEAS_DELAY_US  2000       /* 2 ms conversion time (datasheet) */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF)                        */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int fd, uint8_t cmd)
{
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write(0x%02X) failed: %s\n",
                cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C read short: got %zd, expected %zu\n",
                n, len);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor operations                                                    */
/* ------------------------------------------------------------------ */
static int sdp800_start_continuous(int fd)
{
    /*
     * Continuous measurement command (datasheet):
     *   0x36 0x08 0x00 0x00 0x00 0x00 0x00 0x00
     *   - 0x36 = start continuous measurement
     *   - 0x08 = 8 bytes of data (2 pressure + 2 temp + 2 CRC)
     *   - 0x00 = 0 delay
     *   - 0x00 = 0
     *   - 0x00 = 0
     *   - 0x00 = 0
     *   - 0x00 = 0
     *   - 0x00 = 0
     */
    uint8_t cmd[8] = {0x36, 0x08, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00};
    if (i2c_write_cmd(fd, cmd[0]) != 0) return -1;
    if (i2c_write_cmd(fd, cmd[1]) != 0) return -1;
    if (i2c_write_cmd(fd, cmd[2]) != 0) return -1;
    if (i2c_write_cmd(fd, cmd[3]) != 0) return -1;
    if (i2c_write_cmd(fd, cmd[4]) != 0) return -1;
    if (i2c_write_cmd(fd, cmd[5]) != 0) return -1;
    if (i2c_write_cmd(fd, cmd[6]) != 0) return -1;
    if (i2c_write_cmd(fd, cmd[7]) != 0) return -1;

    /* Datasheet: conversion time >= 1 ms; 2 ms is safe */
    usleep(MEAS_DELAY_US);
    return 0;
}

static int sdp800_read(int fd, float *pressure, float *temperature)
{
    uint8_t buf[8];

    if (i2c_read_bytes(fd, buf, sizeof(buf)) != 0)
        return -1;

    /* CRC validation */
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Pressure CRC mismatch\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }

    int16_t raw_pressure = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_temp     = (int16_t)((buf[3] << 8) | buf[4]);

    *pressure    = (float)raw_pressure / 60.0f;   /* Pa  */
    *temperature = (float)raw_temp / 200.0f;      /* °C  */

    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_data(float pressure, float temperature, const char *filename)
{
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", filename, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.2f\n", ts, pressure, temperature);
    fclose(fp);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(int i2c_fd, FILE *log_fp)
{
    if (i2c_fd >= 0) {
        /* Best-effort stop; ignore errors during shutdown */
        (void)i2c_write_cmd(i2c_fd, 0x00);
        close(i2c_fd);
    }
    if (log_fp) {
        fclose(log_fp);
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int i2c_fd = -1;
    FILE *log_fp = NULL;
    int rc = EXIT_FAILURE;

    if (install_signal_handlers() != 0)
        goto done;

    /* Open I2C bus */
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        goto done;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SDP800_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                SDP800_ADDR, strerror(errno));
        goto done;
    }

    /* Start continuous measurement */
    if (sdp800_start_continuous(i2c_fd) != 0) {
        fprintf(stderr, "SDP800 start continuous failed\n");
        goto done;
    }

    /* Open log file */
    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        goto done;
    }

    printf("SDP800 monitoring started. Logging to %s\n", LOG_FILE);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        float pressure, temperature;

        if (sdp800_read(i2c_fd, &pressure, &temperature) == 0) {
            printf("Pressure: %.2f Pa, Temperature: %.2f °C\n",
                   pressure, temperature);
            if (log_data(pressure, temperature, LOG_FILE) != 0) {
                fprintf(stderr, "Logging failed; continuing\n");
            }
        } else {
            fprintf(stderr, "Read failed; will retry next cycle\n");
        }

        /* Sleep SAMPLE_PERIOD seconds, but wake early on signal */
        for (int s = 0; s < SAMPLE_PERIOD && g_running; s++)
            sleep(1);
    }

    printf("\nShutting down cleanly...\n");
    rc = EXIT_SUCCESS;

done:
    cleanup(i2c_fd, log_fp);
    return rc;
}

