/*
 * Si7021 Temperature Monitor with Hysteresis Fan Control
 * Board:  Raspberry Pi 4 Model B
 * Bus:    I2C bus 1 (GPIO2 = SDA, GPIO3 = SCL), Si7021 @ 0x44
 * Fan:    GPIO18 (BCM), active-high
 *
 * Build:  gcc -O2 -Wall -o si7021_fan si7021_fan.c -lpigpio -lrt
 * Run:    sudo ./si7021_fan
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SI7021_ADDR    0x44
#define FAN_GPIO       18
#define TEMP_THRESHOLD_HIGH  28.0f
#define TEMP_THRESHOLD_LOW   27.0f
#define BUFFER_SIZE      60
#define SAMPLE_INTERVAL_S  2
#define MAX_RETRIES      3
#define RETRY_DELAY_US   10000   /* 10 ms */
#define DEBOUNCE_DELAY_US 10000  /* 10 ms */

/* Si7021 commands (MSB first) */
#define CMD_MEASURE_TEMP_HOLD   0xE3
#define CMD_MEASURE_HUMIDITY_HOLD 0xE5

typedef struct {
    time_t timestamp;
    float  temperature;
    float  humidity;
} SensorData;

typedef struct {
    SensorData data[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ---- */

static int i2c_write_cmd(int handle, uint8_t cmd)
{
    char buf[1] = { (char)cmd };
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cWriteDevice(handle, buf, 1);
        if (rc == 0)
            return 0;
        fprintf(stderr, "I2C write 0x%02X failed (attempt %d/%d): %s\n",
                cmd, attempt + 1, MAX_RETRIES, strerror(errno));
        if (attempt < MAX_RETRIES - 1)
            gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

static int i2c_read_block(int handle, uint8_t *buf, int len)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cReadDevice(handle, (char *)buf, len);
        if (rc == len)
            return 0;
        fprintf(stderr, "I2C read failed (attempt %d/%d): rc=%d, %s\n",
                attempt + 1, MAX_RETRIES, rc, strerror(errno));
        if (attempt < MAX_RETRIES - 1)
            gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

/* ---- Sensor read ---- */

static int read_temperature(int handle, float *out)
{
    if (i2c_write_cmd(handle, CMD_MEASURE_TEMP_HOLD) != 0)
        return -1;

    gpioDelay(10000); /* 10 ms conversion time */

    uint8_t buf[2];
    if (i2c_read_block(handle, buf, 2) != 0)
        return -1;

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *out = -46.85f + 175.72f * (float)raw / 65536.0f;
    return 0;
}

static int read_humidity(int handle, float *out)
{
    if (i2c_write_cmd(handle, CMD_MEASURE_HUMIDITY_HOLD) != 0)
        return -1;

    gpioDelay(10000); /* 10 ms conversion time */

    uint8_t buf[2];
    if (i2c_read_block(handle, buf, 2) != 0)
        return -1;

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *out = -6.0f + 125.0f * (float)raw / 65536.0f;
    return 0;
}

/* ---- Circular buffer ---- */

static void buffer_init(CircularBuffer *buf)
{
    buf->head  = 0;
    buf->count = 0;
}

static void buffer_add(CircularBuffer *buf, time_t ts, float temp, float hum)
{
    buf->data[buf->head].timestamp  = ts;
    buf->data[buf->head].temperature = temp;
    buf->data[buf->head].humidity   = hum;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count < BUFFER_SIZE)
        buf->count++;
}

static void buffer_print(CircularBuffer *buf)
{
    printf("\n--- Sensor Data Buffer ---\n");
    int start = (buf->count < BUFFER_SIZE) ? 0 : buf->head;
    for (int i = 0; i < buf->count; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        char ts[32];
        struct tm tmv;
        localtime_r(&buf->data[idx].timestamp, &tmv);
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tmv);
        printf("[%s] Temp: %.2f C, Hum: %.2f %%\n",
               ts, buf->data[idx].temperature, buf->data[idx].humidity);
    }
    printf("--- End of Buffer ---\n\n");
}

/* ---- Fan control ---- */

static void fan_set(int on)
{
    if (gpioWrite(FAN_GPIO, on ? 1 : 0) != 0)
        fprintf(stderr, "Warning: gpioWrite(%d) failed\n", on ? 1 : 0);
}

static void fan_control(float temp)
{
    static bool fan_on = false;
    if (temp > TEMP_THRESHOLD_HIGH && !fan_on) {
        fan_set(true);
        fan_on = true;
        printf("Fan ON  (T=%.2f C)\n", temp);
    } else if (temp < TEMP_THRESHOLD_LOW && fan_on) {
        fan_set(false);
        fan_on = false;
        printf("Fan OFF (T=%.2f C)\n", temp);
    }
}

/* ---- Main ---- */

int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- I2C open ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, SI7021_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Fan GPIO setup ---- */
    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed\n", FAN_GPIO);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    fan_set(false);

    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Buffers ---- */
    CircularBuffer sensor_data;
    buffer_init(&sensor_data);

    printf("Si7021 monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float temperature = 0.0f, humidity = 0.0f;
        time_t now = time(NULL);

        if (read_temperature(g_i2c_handle, &temperature) != 0) {
            fprintf(stderr, "Temperature read failed; sensor may be absent.\n");
            /* Keep fan in safe state (off) on sensor failure */
            fan_set(false);
            gpioDelay(SAMPLE_INTERVAL_S * 1000000);
            continue;
        }

        if (read_humidity(g_i2c_handle, &humidity) != 0) {
            fprintf(stderr, "Humidity read failed; sensor may be absent.\n");
            gpioDelay(SAMPLE_INTERVAL_S * 1000000);
            continue;
        }

        buffer_add(&sensor_data, now, temperature, humidity);
        buffer_print(&sensor_data);

        fan_control(temperature);

        gpioDelay(SAMPLE_INTERVAL_S * 1000000);
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    fan_set(false);
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

