/*
 * SCD40 CO2 Monitor for Raspberry Pi Zero W
 * Uses pigpio for I2C communication.
 * Logs CO2, Temperature, and Humidity to air_quality.log.
 * Handles SIGINT for graceful shutdown.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SCD40_I2C_ADDR 0x27
#define I2C_BUS 1
#define LOG_FILE "air_quality.log"
#define MEASUREMENT_INTERVAL 5
#define STARTUP_DELAY 1

/* SCD40 Commands */
#define SCD40_START_PERIODIC_MEASUREMENT 0x361F
#define SCD40_STOP_PERIODIC_MEASUREMENT 0x361F
#define SCD40_GET_DATA_READY 0x361F
#define SCD40_READ_MEASUREMENT 0x361F

/* CRC-8 parameters for SCD40 (polynomial 0x31, init 0xFF) */
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* CRC-8 calculation for SCD40 */
static uint8_t scd40_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int bit = 0; bit < 8; bit++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

/* Write a 16-bit command to the SCD40 */
static int scd40_write_command(int handle, uint16_t command) {
    uint8_t buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    if (i2cWriteDevice(handle, (char *)buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to write command 0x%04X to SCD40\n", command);
        return -1;
    }
    return 0;
}

/* Read a 9-byte measurement block from the SCD40 */
static int scd40_read_measurement(int handle, uint8_t *data) {
    if (i2cReadDevice(handle, (char *)data, 9) != 9) {
        fprintf(stderr, "Error: Failed to read 9-byte measurement block from SCD40\n");
        return -1;
    }
    return 0;
}

/* Check if data is ready */
static int scd40_data_ready(int handle) {
    if (scd40_write_command(handle, SCD40_GET_DATA_READY) != 0) {
        return -1;
    }
    gpioDelay(10000); /* 10 ms delay for command processing */
    uint8_t data[3];
    if (scd40_read_measurement(handle, data) != 0) {
        return -1;
    }
    if (scd40_crc8(data, 2) != data[2]) {
        fprintf(stderr, "Error: CRC mismatch on data ready flag\n");
        return -1;
    }
    uint16_t ready = (data[0] << 8) | data[1];
    return (int)ready;
}

/* Read measurement data and parse CO2, Temperature, Humidity */
static int scd40_read_measurement_data(int handle, uint8_t *data, float *co2, float *temperature, float *humidity) {
    if (scd40_read_measurement(handle, data) != 0) {
        return -1;
    }

    /* Verify CRC for each 2-byte word */
    for (int i = 0; i < 6; i++) {
        if (scd40_crc8(&data[i * 3], 2) != data[i * 3 + 2]) {
            fprintf(stderr, "Error: CRC mismatch on measurement word %d\n", i);
            return -1;
        }
    }

    /* Extract values */
    uint16_t co2_raw = (data[0] << 8) | data[1];
    uint16_t temp_raw = (data[3] << 8) | data[4];
    uint16_t hum_raw = (data[6] << 8) | data[7];

    *co2 = (float)co2_raw;
    *temperature = (float)temp_raw / 100.0f;
    *humidity = (float)hum_raw / 100.0f;

    return 0;
}

/* Log data to file */
static int log_data(FILE *fp, float co2, float temperature, float humidity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    if (fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f,%.2f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                co2, temperature, humidity) < 0) {
        fprintf(stderr, "Error: Failed to write to log file\n");
        return -1;
    }
    fflush(fp);
    return 0;
}

int main() {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    /* Open I2C connection */
    i2c_handle = i2cOpen(I2C_BUS, SCD40_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at address 0x%02X on bus %d\n", SCD40_I2C_ADDR, I2C_BUS);
        gpioTerminate();
        return 1;
    }

    /* Open log file */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file %s\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Register signal handler */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    /* Start periodic measurement */
    if (scd40_write_command(i2c_handle, SCD40_START_PERIODIC_MEASUREMENT) != 0) {
        fprintf(stderr, "Error: Failed to start periodic measurement\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Wait for first measurement to be ready */
    gpioDelay(STARTUP_DELAY * 1000000);

    /* Main loop */
    while (!terminate) {
        int ready = scd40_data_ready(i2c_handle);
        if (ready < 0) {
            fprintf(stderr, "Error: Failed to check data ready status\n");
            gpioDelay(MEASUREMENT_INTERVAL * 1000000);
            continue;
        }

        if (ready > 0) {
            uint8_t data[9];
            if (scd40_read_measurement_data(i2c_handle, data) != 0) {
                fprintf(stderr, "Error: Failed to read measurement data\n");
            } else {
                float co2, temperature, humidity;
                if (scd40_read_measurement_data(i2c_handle, data, &co2, &temperature, &humidity) == 0) {
                    if (log_data(log_file, co2, temperature, humidity) != 0) {
                        fprintf(stderr, "Error: Failed to log data\n");
                    }
                } else {
                    fprintf(stderr, "Error: Failed to parse measurement data\n");
                }
            }
        }

        gpioDelay(MEASUREMENT_INTERVAL * 1000000);
    }

    /* Graceful shutdown */
    printf("\nShutting down...\n");
    scd40_write_command(i2c_handle, SCD40_STOP_PERIODIC_MEASUREMENT);
    gpioDelay(100000); /* 100 ms delay for stop command to take effect */
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

