                    fprintf(stderr, "Error: Failed to parse measurement data\n");
                }
            }
        }

        gpioDelay(MEASUREMENT_INTERVAL * 1000000);
    }

    /* Graceful shutdown */
    printf("\nShutting down...\n");
    scd40_write_command(i2c_handle, SCD40_STOP_PERIODIC_MEASUREMENT);
    gpioDelay(100000); /* 100 ms delay for stop command to take effect */
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

