/*
 * SCD40 CO2 monitor for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   SCD40 SDA  -> GPIO2  (I2C bus 1 SDA)
 *   SCD40 SCL  -> GPIO3  (I2C bus 1 SCL)
 *   SCD40 VDD  -> 3.3 V
 *   SCD40 GND  -> GND
 *   CO2 warning LED + 330 ohm resistor -> GPIO17 -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o scd40_monitor scd40_monitor.c -lpigpio -lrt
 *   (pigpio must be installed via: sudo apt install pigpio)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

/* ---- SCD40 constants ---------------------------------------------------- */
#define SCD40_I2C_BUS        1
#define SCD40_I2C_ADDR       0x27          /* SCD40 default 7-bit address */
#define SCD40_CMD_START      0x0010        /* Start continuous measurement */
#define SCD40_CMD_READ_MEAS  0x2000        /* Read measurement (no delay) */
#define SCD40_MEAS_DELAY_US  20000         /* 20 ms measurement settle */
#define SCD40_READ_DELAY_US  50000         /* 50 ms between reads */
#define SCD40_CRC_POLY       0x31         /* SCD4x CRC polynomial */
#define SCD40_CRC_INIT       0xFF         /* SCD4x CRC init value */
#define SCD40_CRC_INPUT_MASK 0x0F         /* SCD4x CRC input mask */
#define SCD40_CO2_THRESHOLD  1000.0f       /* CO2 warning threshold (ppm) */
#define SCD40_BUFFER_SIZE    20
#define SCD40_LED_PIN        17            /* BCM 17 */

/* ---- Data structure ---------------------------------------------------- */
typedef struct {
    float co2;
    float temperature;
    float humidity;
} sensor_data_t;

/* ---- Circular buffer --------------------------------------------------- */
typedef struct {
    sensor_data_t data[SCD40_BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

static circular_buffer_t g_buffer = {0};
static int g_i2c_handle = -1;
static volatile sig_atomic_t g_running = 1;

/* ---- CRC-8 (Sensirion polynomial 0x31, init 0xFF) ---------------------- */
static uint8_t scd4x_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = SCD40_CRC_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ SCD40_CRC_POLY);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc & SCD40_CRC_INPUT_MASK;
}

/* ---- Signal handling --------------------------------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ------------------------------------------------------- */
static int i2c_write_cmd(uint16_t cmd)
{
    char buf[2] = { (char)((cmd >> 8) & 0xFF), (char)(cmd & 0xFF) };
    if (i2cWriteDevice(g_i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "I2C write failed (cmd 0x%04X): %s\n",
                cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(uint8_t *buf, int len)
{
    int n = i2cReadDevice(g_i2c_handle, (char *)buf, len);
    if (n != len) {
        fprintf(stderr, "I2C read failed (expected %d, got %d): %s\n",
                len, n, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- Sensor read ------------------------------------------------------- */
static int read_scd40(sensor_data_t *out)
{
    uint8_t buf[9];          /* 3 words × 3 bytes (2 data + 1 CRC) */
    int16_t raw_co2, raw_t, raw_h;

    /* Trigger a single measurement read */
    if (i2c_write_cmd(SCD40_CMD_READ_MEAS) != 0)
        return -1;

    gpioDelay(SCD40_MEAS_DELAY_US);

    if (i2c_read_bytes(buf, sizeof(buf)) != 0)
        return -1;

    /* Validate CRC for each 2-byte word */
    for (int i = 0; i < 3; i++) {
        if (scd4x_crc8(&buf[i * 3], 2) != buf[i * 3 + 2]) {
            fprintf(stderr, "CRC mismatch on word %d\n", i);
            return -1;
        }
    }

    raw_co2 = (int16_t)((buf[0] << 8) | buf[1]);
    raw_t   = (int16_t)((buf[3] << 8) | buf[4]);
    raw_h   = (int16_t)((buf[6] << 8) | buf[7]);

    out->co2    = (float)raw_co2;
    out->temperature = (float)raw_t / 100.0f;
    out->humidity  = (float)raw_h / 100.0f;

    return 0;
}

/* ---- Circular buffer --------------------------------------------------- */
static void buffer_add(circular_buffer_t *buf, sensor_data_t d)
{
    buf->data[buf->head] = d;
    buf->head = (buf->head + 1) % SCD40_BUFFER_SIZE;
    if (buf->count < SCD40_BUFFER_SIZE)
        buf->count++;
}

static void buffer_print(const circular_buffer_t *buf)
{
    printf("\n--- Last %d readings ---\n", buf->count);
    for (int i = 0; i < buf->count; i++) {
        int idx = (buf->head - buf->count + i + SCD40_BUFFER_SIZE)
                 % SCD40_BUFFER_SIZE;
        printf("  [%2d] CO2=%.0f ppm  T=%.1f C  RH=%.1f %%\n",
               i, buf->data[idx].co2, buf->data[idx].temperature,
               buf->data[idx].humidity);
    }
}

/* ---- Cleanup ---------------------------------------------------------- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cWriteByte(g_i2c_handle, 0x00);   /* stop measurement */
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(SCD40_LED_PIN, 0);
    gpioTerminate();
}

/* ---- Main -------------------------------------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure LED pin */
    if (gpioSetMode(SCD40_LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", SCD40_LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(SCD40_LED_PIN, 0);

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(SCD40_I2C_BUS, SCD40_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d addr 0x%02X: %s\n",
                SCD40_I2C_BUS, SCD40_I2C_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Start continuous measurement */
    if (i2c_write_cmd(SCD40_CMD_START) != 0) {
        fprintf(stderr, "Failed to start SCD40 measurement\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("SCD40 CO2 monitor running. Press Ctrl+C to stop.\n");

    /* Main loop */
    while (g_running) {
        sensor_data_t data;
        if (read_scd40(&data) == 0) {
            buffer_add(&g_buffer, data);
            printf("CO2: %.0f ppm  T: %.1f C  RH: %.1f %%\n",
                   data.co2, data.temperature, data.humidity);

            if (data.co2 > SCD40_CO2_THRESHOLD)
                gpioWrite(SCD40_LED_PIN, 1);
            else
                gpioWrite(SCD40_LED_PIN, 0);

            buffer_print(&g_buffer);
        } else {
            fprintf(stderr, "Sensor read failed; continuing.\n");
        }

        gpioDelay(SCD40_READ_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

