/*
 * TMP05 temperature logger for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   TMP05 VCC  -> 3.3 V (pin 1)
 *   TMP05 GND  -> GND   (pin 9)
 *   TMP05 SCK  -> GPIO4 (BCM 4, physical pin 7)  [PWM output]
 *
 * The TMP05 digital output is a PWM-style stream of high and low
 * pulses whose width encodes the temperature.  We measure the
 * high-pulse width (TH) and the total cycle width (TL) and
 * compute temperature = (TH / TL) * 165 - 40  (°C).
 *
 * Build:  gcc -O2 -Wall -Wextra -o tmp05_logger tmp05_logger.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/time.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <sys/types.h>

#define GPIO_CHIP_NAME  "gpiochip4"   /* BCM GPIO4 on Pi 4 */
#define GPIO_LINE       4             /* BCM 4 */
#define LOG_FILE        "temperature_log.txt"
#define SAMPLE_INTERVAL 5             /* seconds between samples */
#define MAX_CONSECUTIVE_ERRORS 3
#define PWM_TIMEOUT_US   50000        /* 50 ms per edge wait */

/* TMP05 conversion constants (datasheet) */
#define TMP05_TEMP_MIN   (-40.0f)
#define TMP05_TEMP_MAX   150.0f
#define TMP05_SCALE      165.0f
#define TMP05_OFFSET     40.0f

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    struct tm tmv;
    if (localtime_r(&now, &tmv) != NULL)
        strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tmv);
    else
        snprintf(buf, len, "UNKNOWN");
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_message(const char *msg)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return;
    }
    char ts[32];
    get_timestamp(ts, sizeof(ts));
    fprintf(fp, "%s,%s\n", ts, msg);
    fclose(fp);
}

static void log_temperature(float temp)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));
    char msg[128];
    snprintf(msg, sizeof(msg), "TEMPERATURE,%.2f", temp);
    log_message(msg);
}

static void log_error(const char *msg)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));
    char msg2[128];
    snprintf(msg2, sizeof(msg2), "ERROR,%s", msg);
    log_message(msg2);
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */
static int gpio_init(void)
{
    int fd = open("/dev/gpiochip4", O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", "/dev/gpiochip4", strerror(errno));
        return -1;
    }

    unsigned int offset = GPIO_LINE;
    struct gpiod_chip *chip = gpiod_chip_open(fd);
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, offset);
    if (!line) {
        fprintf(stderr, "gpiod_chip_get_line(%u): %s\n",
                offset, strerror(errno));
        gpiod_chip_close(chip);
        close(fd);
        return -1;
    }

    /* Request the line as input with pull-down disabled (external
     * pull-up drives the TMP05 digital output). */
    if (gpiod_line_request_input(line, "tmp05_logger") < 0) {
        fprintf(stderr, "gpiod_line_request_input: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        close(fd);
        return -1;
    }

    return fd;
}

/*
 * Measure a single edge (high or low) by waiting for the line to
 * reach the desired value and recording the high-pulse width in
 * microseconds.  Returns the pulse width in microseconds, or -1 on
 * timeout or error.
 */
static long measure_edge(int fd, int target, long timeout_us)
{
    struct gpiod_line *line;
    unsigned int offset = GPIO_LINE;

    line = gpiod_chip_get_line(gpiod_chip_open(fd), offset);
    if (!line) {
        fprintf(stderr, "gpiod_chip_get_line: %s\n", strerror(errno));
        return -1;
    }

    /* Wait for the line to reach the target value. */
    struct timespec start, now;
    clock_gettime(CLOCK_MONOTONIC, &start);

    while (1) {
        int val = gpiod_line_get_value(line);
        if (val < 0) {
            fprintf(stderr, "gpiod_line_get_value: %s\n", strerror(errno));
            return -1;
        }
        if (val == target)
            return (long)(clock_gettime(CLOCK_MONOTONIC, &now) -
                         start.tv_sec) * 1000000L +
                   (now.tv_nsec - start.tv_nsec) / 1000L;

        clock_gettime(CLOCK_MONOTONIC, &start);
        long elapsed = (start.tv_sec - clock_gettime(CLOCK_MONOTONIC, &start)) * 1000000L +
                       (start.tv_nsec - clock_gettime(CLOCK_MONOTONIC, &start)) / 1000L;
        if (elapsed > timeout_us)
            return -1;
    }
}

/*
 * Read one complete TMP05 cycle: measure the high-pulse width
 * (TH) and the total cycle width (TL).  Returns 0 on success,
 * -1 on error.
 */
static int read_tmp05(int fd, float *temperature)
{
    long th = measure_edge(fd, 1, PWM_TIMEOUT_US);   /* high pulse */
    if (th < 0)
        return -1;

    long tl = measure_edge(fd, 0, PWM_TIMEOUT_US);   /* low pulse  */
    if (tl < 0)
        return -1;

    if (tl == 0) {
        log_error("Invalid reading: total cycle time is zero");
        return -1;
    }

    float temp = ((float)th / (float)tl) * TMP05_SCALE - TMP05_OFFSET;
    if (temp < TMP05_TEMP_MIN || temp > TMP05_TEMP_MAX) {
        char msg[128];
        snprintf(msg, sizeof(msg), "Out of range: %.2f", temp);
        log_error(msg);
        return -1;
    }

    *temperature = temp;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int fd = gpio_init();
    if (fd < 0) {
        fprintf(stderr, "Failed to initialize GPIO\n");
        return EXIT_FAILURE;
    }

    log_message("GPIO initialized successfully");

    int consecutive_errors = 0;

    while (g_running) {
        float temperature;
        if (read_tmp05(fd, &temperature) == 0) {
            log_temperature(temperature);
            consecutive_errors = 0;
        } else {
            consecutive_errors++;
            if (consecutive_errors >= MAX_CONSECUTIVE_ERRORS) {
                log_error("SENSOR MALFUNCTION");
                consecutive_errors = MAX_CONSECUTIVE_ERRORS;
            }
        }

        /* Sleep SAMPLE_INTERVAL seconds, but wake early on signal */
        for (int i = 0; i < SAMPLE_INTERVAL && g_running; i++)
            sleep(1);
    }

    /* Clean shutdown */
    log_message("Shutdown requested");
    gpiod_line_release(gpiod_chip_get_line(gpiod_chip_open(fd), GPIO_LINE));
    gpiod_chip_close(gpiod_chip_open(fd));
    close(fd);
    return EXIT_SUCCESS;
}

