/*
 * greenhouse_env.c — SHT35 environmental logger for Raspberry Pi 4 Model B
 *
 * Reads temperature and humidity from a Sensirion SHT35‑DIS‑B sensor on I2C bus 1
 * with high-repeatability, clock-stretching-disabled measurement command.
 * Adds a sinusoidal offset over a one-hour period and logs to
 * "environmental_data.txt" every 5 seconds.
 *
 * Build:  gcc -O2 -Wall -Wextra -o greenhouse_env greenhouse_env.c
 * Run:    ./greenhouse_env
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <math.h>
#include <pigpio.h>

#define I2C_BUS              1
#define SHT35_ADDR           0x24
#define LOG_FILE             "environmental_data.txt"
#define SAMPLE_INTERVAL_S    5
#define MAX_RETRIES          3
#define MEAS_DELAY_US        15000   /* 15 ms conversion time */
#define MAX_OFFSET_C         2.0f
#define MAX_OFFSET_RH        5.0f
#define SHT35_CMD_MEASURE    0x2E    /* high repeatability, clock-stretching disabled */
#define SHT35_CMD_RESET      0x30    /* software reset */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF)                        */
/* ------------------------------------------------------------------ */
static uint8_t sht35_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* SHT35 measurement                                                    */
/* ------------------------------------------------------------------ */
static int sht35_measure(int handle, float *temperature, float *humidity)
{
    uint8_t cmd = SHT35_CMD_MEASURE;
    uint8_t data[6];

    /* Send measurement command */
    if (i2cWriteDevice(handle, (char *)&cmd, 1) != 0) {
        fprintf(stderr, "[SHT35] i2cWriteDevice failed: %s\n", strerror(errno));
        return -1;
    }

    /* Wait for conversion to complete */
    gpioDelay(MEAS_DELAY_US);

    /* Read 6 bytes: T_MSB T_LSB T_CRC  RH_MSB RH_LSB RH_CRC */
    if (i2cReadDevice(handle, (char *)data, 6) != 6) {
        fprintf(stderr, "[SHT35] i2cReadDevice failed: %s\n", strerror(errno));
        return -1;
    }

    /* Validate CRC for temperature word */
    if (sht35_crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "[SHT35] temperature CRC mismatch\n");
        return -1;
    }

    /* Validate CRC for humidity word */
    if (sht35_crc8(&data[3], 2) != data[5]) {
        fprintf(stderr, "[SHT35] humidity CRC mismatch\n");
        return -1;
    }

    /* Convert raw values to physical units */
    uint16_t t_raw = ((uint16_t)data[0] << 8) | data[1];
    uint16_t h_raw = ((uint16_t)data[3] << 8) | data[4];

    *temperature = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *humidity    = 100.0f * (float)h_raw / 65535.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Offset calculation (sinusoidal over one hour)                       */
/* ------------------------------------------------------------------ */
static void apply_offset(float *temperature, float *humidity,
                         float t_offset, float h_offset,
                         float t_start, float t_end,
                         float t_current)
{
    float elapsed = (float)(t_current - t_start) / 3600.0f;
    float phase = elapsed * 2.0f * M_PIf / 3600.0f;
    float t_offset_scaled = t_offset * (1.0f - cosf(phase));
    float h_offset_scaled = h_offset * (1.0f - cosf(phase));

    *temperature += t_offset_scaled;
    *humidity    += h_offset_scaled;
}

/* ------------------------------------------------------------------ */
/* Log data with timestamp                                              */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, float temperature, float humidity)
{
    time_t rawtime;
    struct tm tm_info;
    char timestamp[32];

    time(&rawtime);
    gmtime_r(&rawtime, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm_info);

    fprintf(fp, "%s, Temperature: %.2f C, Humidity: %.2f %%\n",
            timestamp, temperature, humidity);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    float temperature, humidity;
    float t_offset = 0.0f, h_offset = 0.0f;
    float t_start = 0.0f;
    int retries;

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus --- */
    g_i2c_handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (bus %d, addr 0x%02X): %s\n",
                I2C_BUS, SHT35_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* --- Reset sensor --- */
    if (i2cWriteByte(g_i2c_handle, SHT35_CMD_RESET) != 0) {
        fprintf(stderr, "Warning: SHT35 reset write failed: %s\n", strerror(errno));
    }
    gpioDelay(15000); /* allow reset to complete */

    /* --- Main loop --- */
    while (g_running) {
        retries = 0;
        int success = 0;

        while (retries < MAX_RETRIES && !success) {
            if (sht35_measure(g_i2c_handle, &temperature, &humidity) == 0) {
                success = 1;
            } else {
                retries++;
                if (retries < MAX_RETRIES) {
                    fprintf(stderr, "[SHT35] retry %d/%d\n", retries, MAX_RETRIES);
                    gpioDelay(1000000); /* 1 s */
                }
            }
        }

        if (success) {
            time_t rawtime;
            struct tm tm_info;
            char timestamp[32];

            time(&rawtime);
            gmtime_r(&rawtime, &tm_info);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm_info);

            printf("%s  T=%.2f C  RH=%.2f %%\n", timestamp, temperature, humidity);
            log_data(g_log_file, temperature, humidity);
        } else {
            fprintf(stderr, "[SHT35] all %d retries exhausted — logging NaN\n",
                    MAX_RETRIES);
            log_data(g_log_file, NAN, NAN);
        }

        /* Apply sinusoidal offset over one-hour period */
        if (t_start == 0.0f) {
            t_start = time_time();
        }

        if (g_running) {
            gpioDelay(SAMPLE_INTERVAL_S * 1000000);
        }
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

