    if (i2cWriteByte(g_i2c_handle, SHT35_CMD_RESET) != 0) {
        fprintf(stderr, "Warning: SHT35 reset write failed: %s\n", strerror(errno));
    }
    gpioDelay(15000); /* allow reset to complete */

    /* --- Main loop --- */
    while (g_running) {
        retries = 0;
        int success = 0;

        while (retries < MAX_RETRIES && !success) {
            if (sht35_measure(g_i2c_handle, &temperature, &humidity) == 0) {
                success = 1;
            } else {
                retries++;
                if (retries < MAX_RETRIES) {
                    fprintf(stderr, "[SHT35] retry %d/%d\n", retries, MAX_RETRIES);
                    gpioDelay(1000000); /* 1 s */
                }
            }
        }

        if (success) {
            time_t rawtime;
            struct tm tm_info;
            char timestamp[32];

            time(&rawtime);
            gmtime_r(&rawtime, &tm_info);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm_info);

            printf("%s  T=%.2f C  RH=%.2f %%\n", timestamp, temperature, humidity);
            log_data(g_log_file, temperature, humidity);
        } else {
            fprintf(stderr, "[SHT35] all %d retries exhausted — logging NaN\n",
                    MAX_RETRIES);
            log_data(g_log_file, NAN, NAN);
        }

        /* Apply sinusoidal offset over one-hour period */
        if (t_start == 0.0f) {
            t_start = time_time();
        }

        if (g_running) {
            gpioDelay(SAMPLE_INTERVAL_S * 1000000);
        }
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

