/*
 * SDP810-125Pa differential pressure sensor reader for Raspberry Pi 3 Model B+
 * Uses pigpio for I2C communication.
 *
 * Wiring:
 *   SDP810 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   SDP810 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   SDP810 VDD  -> 3.3 V
 *   SDP810 GND  -> GND
 *
 * Build: gcc -O2 -Wall -o airflow airflow.c -lpigpio -lrt
 * Run:   sudo ./airflow
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x60
#define CSV_FILENAME   "airflow.csv"
#define SAMPLE_PERIOD  1.0   /* seconds between samples */
#define CONV_TIME_US   45000 /* SDP810 conversion time ~45 ms */

/* Continuous measurement command (16-bit, big-endian on the wire) */
static const uint8_t CMD_CONT_MEAS[2] = { 0x36, 0x88 };

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (polynomial 0x31, init 0xFF, no final XOR) — matches SDP810 spec  */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Read one 9-byte measurement frame and convert to physical values   */
/* ------------------------------------------------------------------ */
static int read_sdp810(float *pressure, float *temperature)
{
    uint8_t buf[9];

    /* Send continuous measurement command */
    if (i2cWriteDevice(g_i2c_fd, (char *)CMD_CONT_MEAS, 2) != 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice failed (sensor may be absent)\n");
        return -1;
    }

    /* Wait for conversion to complete */
    gpioDelay(CONV_TIME_US);

    /* Read 9 bytes: pressure(2)+crc, temperature(2)+crc, scale(2)+crc */
    int n = i2cReadDevice(g_i2c_fd, (char *)buf, sizeof(buf));
    if (n != (int)sizeof(buf)) {
        fprintf(stderr, "[ERROR] i2cReadDevice returned %d (expected %zu)\n",
                n, sizeof(buf));
        return -1;
    }

    /* Validate CRCs */
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "[ERROR] Pressure CRC mismatch\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "[ERROR] Temperature CRC mismatch\n");
        return -1;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "[ERROR] Scale factor CRC mismatch\n");
        return -1;
    }

    /* Convert raw values to physical units (datasheet formulas) */
    int16_t raw_pressure    = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_temperature = (int16_t)((buf[3] << 8) | buf[4]);
    int16_t scale_factor    = (int16_t)((buf[6] << 8) | buf[7]);

    if (scale_factor == 0) {
        fprintf(stderr, "[ERROR] Invalid scale factor (0)\n");
        return -1;
    }

    *pressure    = (float)raw_pressure    / (float)scale_factor;
    *temperature = (float)raw_temperature / 200.0f;  /* °C */

    return 0;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped reading to the CSV file                        */
/* ------------------------------------------------------------------ */
static int log_data(float pressure, float temperature)
{
    FILE *fp = fopen(CSV_FILENAME, "a");
    if (!fp) {
        perror("[ERROR] fopen CSV");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("[ERROR] localtime_r");
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            pressure, temperature);

    if (fclose(fp) != 0) {
        perror("[ERROR] fclose CSV");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        i2cClose(g_i2c_fd);
        g_i2c_fd = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (addr 0x%02X): %d\n",
                I2C_ADDR, g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[WARN] sigaction");
    }

    printf("SDP810-125Pa reader started. Logging to %s every %.1f s.\n",
           CSV_FILENAME, SAMPLE_PERIOD);
    printf("Press Ctrl+C to stop.\n");

    float pressure, temperature;

    while (g_running) {
        if (read_sdp810(&pressure, &temperature) == 0) {
            if (log_data(pressure, temperature) != 0) {
                fprintf(stderr, "[WARN] Logging failed; continuing.\n");
            }
        } else {
            fprintf(stderr, "[WARN] Sensor read failed; will retry.\n");
        }

        /* Sleep in small increments so signals are caught promptly */
        for (int i = 0; i < 10 && g_running; i++)
            time_sleep(SAMPLE_PERIOD / 10.0);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

