/*
 * SHT35‑DIS‑B temperature/humidity logger for Raspberry Pi Zero W.
 *
 * Wiring:
 *   SHT35 VDD  -> 3.3 V (pin 1)
 *   SHT35 GND  -> GND   (pin 9)
 *   SHT35 SDA  -> GPIO2 / I2C bus 1 SDA (pin 3)
 *   SHT35 SCL  -> GPIO3 / I2C bus 1 SCL (pin 5)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o sht35_logger sht35_logger.c
 *
 * Run:
 *   ./sht35_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SHT35_ADDR     0x44          /* SHT35‑DIS‑B default I2C address */
#define CSV_FILENAME   "environment.csv"
#define SAMPLE_PERIOD  5             /* seconds between samples */
#define MEAS_DELAY_US  15000         /* 15 ms measurement settle */
#define MAX_RETRIES    3

/* SHT35 single-shot, high repeatability, clock stretching disabled */
#define SHT35_CMD_MSB  0x2C
#define SHT35_CMD_LSB  0x06

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0)
        perror("warning: sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) != 0)
        perror("warning: sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF)                        */
/* ------------------------------------------------------------------ */
static uint8_t sht35_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int handle, uint8_t msb, uint8_t lsb)
{
    uint8_t cmd[2] = { msb, lsb };
    if (i2cWriteDevice(handle, (char *)cmd, 2) != 2) {
        fprintf(stderr, "I2C write failed (cmd 0x%02X%02X): %s\n",
                msb, lsb, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int handle, uint8_t *buf, size_t len)
{
    int n = i2cReadDevice(handle, (char *)buf, len);
    if (n != (int)len) {
        fprintf(stderr, "I2C read failed (expected %zu, got %d): %s\n",
                len, n, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* SHT35 measurement                                                  */
/* ------------------------------------------------------------------ */
static int sht35_read(int handle, float *temperature, float *humidity)
{
    uint8_t data[6];

    if (i2c_write_cmd(handle, SHT35_CMD_MSB, SHT35_CMD_LSB) != 0)
        return -1;

    gpioDelay(MEAS_DELAY_US);

    if (i2c_read_bytes(handle, data, sizeof(data)) != 0)
        return -1;

    /* Validate CRC-8 over the first four bytes */
    if (sht35_crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }
    if (sht35_crc8(&data[3], 2) != data[5]) {
        fprintf(stderr, "Humidity CRC mismatch\n");
        return -1;
    }

    uint16_t t_raw = ((uint16_t)data[0] << 8) | data[1];
    uint16_t h_raw = ((uint16_t)data[3] << 8) | data[4];

    *temperature = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *humidity    = 100.0f * (float)h_raw / 65535.0f;

    /* Clamp humidity to valid physical range */
    if (*humidity < 0.0f)   *humidity = 0.0f;
    if (*humidity > 100.0f) *humidity = 100.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* CSV logging                                                         */
/* ------------------------------------------------------------------ */
static int log_data(float temperature, float humidity)
{
    FILE *fp = fopen(CSV_FILENAME, "a+");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", CSV_FILENAME, strerror(errno));
        return -1;
    }

    /* Write header if file is empty */
    if (fseek(fp, 0, SEEK_END) != 0) {
        fprintf(stderr, "fseek failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    long fsize = ftell(fp);
    if (fsize == 0) {
        fprintf(fp, "Timestamp,Temperature (C),Humidity (%%)\n");
        fflush(fp);
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.2f\n", ts, temperature, humidity);
    fflush(fp);

    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    install_signal_handlers();

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (bus %d, addr 0x%02X): %s\n",
                I2C_BUS, SHT35_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    float temperature, humidity;
    int consecutive_failures = 0;

    while (g_running) {
        if (sht35_read(g_i2c_handle, &temperature, &humidity) == 0) {
            consecutive_failures = 0;
            if (log_data(temperature, humidity) != 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
        } else {
            consecutive_failures++;
            fprintf(stderr, "Sensor read failed (attempt %d/%d)\n",
                    consecutive_failures, MAX_RETRIES);

            if (consecutive_failures >= MAX_RETRIES) {
                fprintf(stderr, "Max consecutive failures reached; aborting.\n");
                break;
            }
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD * 10 && g_running; i++)
            gpioDelay(100000);
    }

    cleanup();
    return EXIT_SUCCESS;
}

