/*
 * greenhouse_monitor.c — Si7021 greenhouse monitor for Raspberry Pi Zero W
 *
 * Wiring:
 *   Si7021 SDA  -> GPIO 2  (I2C bus 1 SDA, physical pin 3)
 *   Si7021 SCL  -> GPIO 3  (I2C bus 1 SCL, physical pin 5)
 *   Si7021 VDD  -> 3.3 V
 *   Si7021 GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o greenhouse_monitor greenhouse_monitor.c
 *
 * Run:
 *   ./greenhouse_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SI7021_ADDR    0x44          /* default Si7021 I2C address */
#define LOG_FILE       "environment.log"
#define SAMPLE_PERIOD  5             /* seconds between samples */
#define MAX_RETRIES    10            /* consecutive read failures before reset */
#define MEAS_TIMEOUT   100000        /* microseconds (100 ms) */

/* Si7021 commands (MSB first) */
#define CMD_MEASURE_RH   0xE5
#define CMD_MEASURE_T   0xE3
#define CMD_RESET       0xFE

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (polynomial 0x31, init 0x00, no final XOR) — Si7021 datasheet  */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0x00;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Low-level I2C helpers                                               */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int fd, uint8_t cmd)
{
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "[ERROR] I2C write(0x%02X) failed: %s\n",
                cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "[ERROR] I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "[ERROR] I2C short read: got %zd of %zu bytes\n",
                n, len);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor reset                                                         */
/* ------------------------------------------------------------------ */
static int sensor_reset(int fd)
{
    if (i2c_write_cmd(fd, CMD_RESET) < 0)
        return -1;
    usleep(15000);                       /* datasheet: max 15 ms */
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one measurement (RH or T) with timeout                          */
/* ------------------------------------------------------------------ */
static int read_measurement(int fd, uint8_t cmd, float *out, const char *label)
{
    uint8_t buf[3];
    int attempt;

    for (attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2c_write_cmd(fd, cmd) < 0)
            return -1;

        /* Si7021 conversion time: ~7 ms for RH, ~15 ms for T */
        usleep(10000);

        if (i2c_read_bytes(fd, buf, 3) < 0)
            return -1;

        if (crc8(buf, 2) != buf[2]) {
            fprintf(stderr, "[ERROR] CRC mismatch on %s data\n", label);
            return -1;
        }

        uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
        *out = -45.0f + 175.0f * (float)raw / 65535.0f;

        if (cmd == CMD_MEASURE_RH)
            return 0;
    }

    fprintf(stderr, "[ERROR] %s read failed after %d attempts\n",
            label, MAX_RETRIES);
    return -1;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t t = time(NULL);
    struct tm tmv;
    if (localtime_r(&t, &tmv) != NULL)
        strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tmv);
    else
        snprintf(buf, len, "1970-01-01T00:00:00");
}

/* ------------------------------------------------------------------ */
/* CSV logging                                                         */
/* ------------------------------------------------------------------ */
static int log_data(const char *ts, float temp, float rh)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "[ERROR] Cannot open %s: %s\n",
                LOG_FILE, strerror(errno));
        return -1;
    }
    fprintf(fp, "%s,%.2f,%.2f\n", ts, temp, rh);
    fclose(fp);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "[ERROR] sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "[ERROR] Cannot open %s: %s\n",
                I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SI7021_ADDR) < 0) {
        fprintf(stderr, "[ERROR] ioctl I2C_SLAVE 0x%02X failed: %s\n",
                SI7021_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Probe: try a zero-length write to confirm the sensor is present */
    if (write(g_i2c_fd, NULL, 0) < 0) {
        fprintf(stderr, "[ERROR] Si7021 not responding at 0x%02X: %s\n",
                SI7021_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is new/empty */
    {
        FILE *fp = fopen(LOG_FILE, "r");
        int need_header = (fp == NULL);
        if (fp) fclose(fp);
        if (need_header) {
            fp = fopen(LOG_FILE, "a");
            if (fp) {
                fprintf(fp, "timestamp,temperature_C,humidity_percent\n");
                fclose(fp);
            }
        }
    }

    printf("Greenhouse monitor started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_PERIOD);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        char ts[32];
        get_timestamp(ts, sizeof(ts));

        float temperature = 0.0f, humidity = 0.0f;
        int ok = 1;

        if (read_measurement(g_i2c_fd, CMD_MEASURE_RH, &humidity, "humidity") < 0) {
            fprintf(stderr, "[ERROR] Humidity read failed; resetting sensor.\n");
            if (sensor_reset(g_i2c_fd) < 0)
                fprintf(stderr, "[ERROR] Sensor reset failed.\n");
            ok = 0;
        }
        if (ok && read_measurement(g_i2c_fd, CMD_MEASURE_T, &temperature, "temperature") < 0) {
            fprintf(stderr, "[ERROR] Temperature read failed; resetting sensor.\n");
            if (sensor_reset(g_i2c_fd) < 0)
                fprintf(stderr, "[ERROR] Sensor reset failed.\n");
            ok = 0;
        }

        if (ok) {
            if (log_data(ts, temperature, humidity) < 0)
                fprintf(stderr, "[WARN] Logging failed.\n");
            else
                printf("%s  T=%.2f C  RH=%.2f %%\n", ts, temperature, humidity);
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD * 10 && g_running; i++)
            usleep(100000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

