        if (fwrite(&pressure_pa, sizeof(float), 1, g_log_fp) != 1 ||
            fwrite(&temperature_c, sizeof(float), 1, g_log_fp) != 1) {
            fprintf(stderr, "Error: file write failed: %s\n", strerror(errno));
            break;
        }
        fflush(g_log_fp);

        /* Sleep for the remainder of the 1 s period */
        gpioDelay(SAMPLE_PERIOD * 1000000);
    }

    /* --- Graceful shutdown ----------------------------------------- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

