/*
 * SDP800-500Pa differential pressure sensor reader for Raspberry Pi 3 Model B+
 * Uses pigpio for I2C communication.
 *
 * Wiring:
 *   SDP800 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   SDP800 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   SDP800 VDD  -> 3.3 V
 *   SDP800 GND  -> GND
 *
 * Build: gcc -O2 -Wall -o sdp800_log sdp800_log.c -lpigpio -lrt
 * Run:   sudo ./sdp800_log
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x60
#define LOG_FILE       "pressure_log.txt"
#define SAMPLE_PERIOD  5          /* seconds between readings */
#define CONV_TIME_MS   45         /* SDP800 conversion time (max) */

/* Continuous measurement command (0x36 0x2C 0x00 0x00 0x00 0x00 0x00 0x00) */
static const uint8_t CMD_CONT_MEAS[8] = {0x36, 0x2C, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00};

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF)                        */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 8-byte command to the sensor                                */
/* ------------------------------------------------------------------ */
static int sdp_write_cmd(int handle, const uint8_t *cmd, int len)
{
    if (i2cWriteDevice(handle, (char *)cmd, len) != len) {
        fprintf(stderr, "[ERROR] i2cWriteDevice failed (cmd 0x%02X%02X...)\n",
                cmd[0], cmd[1]);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read exactly `len` bytes from the sensor                            */
/* ------------------------------------------------------------------ */
static int sdp_read_data(int handle, uint8_t *buf, int len)
{
    int n = i2cReadDevice(handle, (char *)buf, len);
    if (n != len) {
        fprintf(stderr, "[ERROR] i2cReadDevice returned %d (expected %d)\n",
                n, len);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one 9-byte measurement frame and validate CRCs                 */
/* ------------------------------------------------------------------ */
static int sdp_read_measurement(int handle, float *pressure_pa)
{
    uint8_t buf[9];

    if (sdp_read_data(handle, buf, sizeof(buf)) != 0)
        return -1;

    /* Validate CRCs for each 3-byte word */
    for (int i = 0; i < 3; i++) {
        if (crc8(&buf[i * 3], 2) != buf[i * 3 + 2]) {
            fprintf(stderr, "[ERROR] CRC mismatch on word %d\n", i);
            return -1;
        }
    }

    /* Assemble 16-bit big-endian differential pressure */
    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *pressure_pa = (float)raw * 0.001f;   /* Pa */
    return 0;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped reading to the log file                         */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, float pressure)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed\n");
        return -1;
    }

    if (fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, %.2f Pa\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, pressure) < 0) {
        fprintf(stderr, "[ERROR] fprintf to log failed\n");
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "[ERROR] fflush failed\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- open I2C --- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- open log file --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open %s: ", LOG_FILE);
        perror("");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction failed; continuing without signal handlers\n");
    }

    printf("SDP800-500Pa logger started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_PERIOD);
    printf("Press Ctrl+C to stop.\n");

    /* --- main loop --- */
    while (g_running) {
        if (sdp_write_cmd(g_i2c_handle, CMD_CONT_MEAS, sizeof(CMD_CONT_MEAS)) != 0) {
            fprintf(stderr, "[WARN] Sensor command write failed; retrying next cycle\n");
        } else {
            /* SDP800 needs ~45 ms for the first conversion */
            gpioDelay(CONV_TIME_MS * 1000);

            float pressure;
            if (sdp_read_measurement(g_i2c_handle, &pressure) == 0) {
                if (log_data(g_log_file, pressure) != 0) {
                    fprintf(stderr, "[WARN] Logging failed; continuing\n");
                } else {
                    printf("Pressure: %.2f Pa\n", pressure);
                }
            } else {
                fprintf(stderr, "[WARN] Sensor read failed; continuing\n");
            }
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD * 10 && g_running; i++)
            gpioDelay(100 * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

