    /* --- open log file --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open %s: ", LOG_FILE);
        perror("");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction failed; continuing without signal handlers\n");
    }

    printf("SDP800-500Pa logger started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_PERIOD);
    printf("Press Ctrl+C to stop.\n");

    /* --- main loop --- */
    while (g_running) {
        if (sdp_write_cmd(g_i2c_handle, CMD_CONT_MEAS, sizeof(CMD_CONT_MEAS)) != 0) {
            fprintf(stderr, "[WARN] Sensor command write failed; retrying next cycle\n");
        } else {
            /* SDP800 needs ~45 ms for the first conversion */
            gpioDelay(CONV_TIME_MS * 1000);

            float pressure;
            if (sdp_read_measurement(g_i2c_handle, &pressure) == 0) {
                if (log_data(g_log_file, pressure) != 0) {
                    fprintf(stderr, "[WARN] Logging failed; continuing\n");
                } else {
                    printf("Pressure: %.2f Pa\n", pressure);
                }
            } else {
                fprintf(stderr, "[WARN] Sensor read failed; continuing\n");
            }
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD * 10 && g_running; i++)
            gpioDelay(100 * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

