static int read_register(int handle, uint8_t reg, uint16_t *out)
{
    char buf[2];

    if (i2cWriteByte(handle, reg) < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByte(reg=0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "[ERROR] i2cReadDevice(reg=0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

static int write_register(int handle, uint8_t reg, uint16_t value)
{
    char buf[2];
    buf[0] = (char)(value >> 8);
