}

static int calculate_flow_rate(float pressure)
{
    /* Placeholder: real implementation requires calibration curve.
     * For the HAFBLF0100A2AX5, flow rate (m³/s) ≈ k * pressure (Pa).
     * Here we return a linear proxy; replace with sensor-specific data. */
    return (int)(pressure * 0.5f);
}

/* --------------------------- Fan control -------------------------------- */
static int set_fan_speed(int gpio, int duty_percent)
{
    if (duty_percent < 0)   duty_percent = 0;
    if (duty_percent > 100) duty_percent = 100;

    int pwm_range = 255;          /* 8-bit duty resolution */
    int pwm_duty   = (pwm_range * duty_percent) / 100;

    if (gpioPWM(gpio, pwm_duty) < 0) {
        fprintf(stderr, "[ERROR] gpioPWM(%d, %d) failed: %s\n",
                gpio, pwm_duty, strerror(errno));
        return -1;
    }
    return 0;
}

/* --------------------------- Logging ------------------------------------ */
static void log_data(FILE *fp, float pressure)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed: %s\n", strerror(errno));
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, pressure);
    fflush(fp);
}

/* --------------------------- Signal / cleanup ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    /* Ensure fan is off before terminating pigpio */
    gpioPWM(FAN_GPIO, 0);
    gpioTerminate();
}

/* --------------------------------- main ---------------------------------- */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- I2C open --- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Verify chip ID --- */
    uint16_t chip_id = 0;
    if (read_register(g_i2c_handle, REG_CHIP_ID, &chip_id) < 0) {
        fprintf(stderr, "[FATAL] Cannot read chip ID — sensor absent or bus error\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (chip_id != EXPECTED_CHIP_ID) {
        fprintf(stderr, "[FATAL] Unexpected chip ID 0x%04X (expected 0x%04X)\n",
                chip_id, EXPECTED_CHIP_ID);
        cleanup();
        return EXIT_FAILURE;
    }
    printf("[INFO] Zephyr HAFBLF0100A2AX5 detected (chip ID 0x%04X)\n", chip_id);

    /* --- Log file --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Fan GPIO setup --- */
    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "[FATAL] gpioSetMode(%d, PI_OUTPUT) failed\n", FAN_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "[FATAL] gpioSetPWMfrequency(%d, %d) failed\n",
                FAN_GPIO, PWM_FREQUENCY);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(FAN_GPIO, 255) < 0) {
        fprintf(stderr, "[FATAL] gpioSetPWMrange(%d, 255) failed\n", FAN_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioPWM(FAN_GPIO, 0);   /* fan off at startup */

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "[WARN] sigaction(SIGINT) failed: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "[WARN] sigaction(SIGTERM) failed: %s\n", strerror(errno));
    }

    printf("[INFO] Sampling every %d ms. Press Ctrl+C to stop.\n",
           SAMPLE_PERIOD_US / 1000);

    /* --- Main loop --- */
    while (g_running) {
        float pressure = 0.0f;
        if (read_pressure(g_i2c_handle, &pressure) < 0) {
            fprintf(stderr, "[WARN] I2C read error — skipping sample\n");
        } else {
            int flow_rate = calculate_flow_rate(pressure);
            set_fan_speed(FAN_GPIO, flow_rate);
            log_data(g_log_file, pressure);
            printf("Pressure: %.2f Pa  Flow: %d\n", pressure, flow_rate);
        }
        gpioDelay(SAMPLE_PERIOD_US);   /* 100 ms */
    }

    printf("\n[INFO] Shutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

