/*
 * Raspberry Pi Zero W – STLM75 temperature monitor with LED indicator
 *
 * Wiring:
 *   STLM75 SDA  -> GPIO2  (I2C bus 1, pin 3)
 *   STLM75 SCL  -> GPIO3  (I2C bus 1, pin 5)
 *   STLM75 VDD  -> 3.3 V
 *   STLM75 GND  -> GND
 *   LED anode   -> GPIO17 (pin 11) through 330 Ω resistor
 *   LED cathode -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o temp_monitor temp_monitor.c -lpigpio -lrt
 * Run:    sudo ./temp_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x48          /* STLM75 default 7-bit address */
#define LED_GPIO       17
#define BUFFER_SIZE    10
#define TEMP_THRESHOLD 28.0f
#define POLL_DELAY_US  1000000       /* 1 s */

/* STLM75 conversion: 12-bit result in bits [11:4] of the 16-bit word */
#define STLM75_CONV_MASK 0x0FFF
#define STLM75_CONV_SHIFT 12

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Circular buffer                                                      */
/* ------------------------------------------------------------------ */
typedef struct {
    float  data[BUFFER_SIZE];
    int   head;
    int   count;
} CircularBuffer;

static void cb_init(CircularBuffer *cb)
{
    cb->head  = 0;
    cb->count = 0;
}

static void cb_add(CircularBuffer *cb, float value)
{
    cb->data[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE)
        cb->count++;
}

static float cb_average(const CircularBuffer *cb)
{
    if (cb->count == 0)
        return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < cb->count; i++)
        sum += cb->data[i];
    return sum / (float)cb->count;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                          */
/* ------------------------------------------------------------------ */
static int i2c_open(int bus, int addr)
{
    int h = i2cOpen(bus, addr, 0);
    if (h < 0) {
        fprintf(stderr, "i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                bus, addr, h);
        return -1;
    }
    return h;
}

static int i2c_read_word(int handle, uint16_t *out)
{
    int v = i2cReadWordData(handle, 0x00);
    if (v < 0) {
        fprintf(stderr, "i2cReadWordData failed: %d\n", v);
        return -1;
    }
    *out = (uint16_t)v;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(int i2c_handle)
{
    if (i2c_handle >= 0)
        i2cClose(i2c_handle);
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- LED GPIO setup --------------------------------------------- */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* --- I2C open --------------------------------------------------- */
    int i2c_handle = i2c_open(I2C_BUS, I2C_ADDR);
    if (i2c_handle < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signals ---------------------------------------------------- */
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* --- Circular buffer -------------------------------------------- */
    CircularBuffer temp_buffer;
    cb_init(&temp_buffer);

    /* --- Main loop -------------------------------------------------- */
    while (g_running) {
        uint16_t raw = 0;
        if (i2c_read_word(i2c_handle, &raw) < 0) {
            /* I2C read failed – skip this cycle, keep running */
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        int16_t temp_raw = (int16_t)(raw & STLM75_CONV_MASK);
        float temperature = (float)temp_raw / 16.0f;

        cb_add(&temp_buffer, temperature);

        float avg = cb_average(&temp_buffer);
        bool led_on = (avg > TEMP_THRESHOLD);

        if (gpioWrite(LED_GPIO, led_on ? 1 : 0) < 0) {
            fprintf(stderr, "gpioWrite(%d) failed\n", LED_GPIO);
        }

        printf("Temperature: %.2f C  |  Average: %.2f C  |  LED: %s\n",
               temperature, avg, led_on ? "ON" : "OFF");

        gpioDelay(POLL_DELAY_US);
    }

    /* --- Graceful shutdown ------------------------------------------ */
    cleanup(i2c_handle);
    return EXIT_SUCCESS;
}

