/*
 * SCD30 CO2 / Temperature / Humidity logger with ventilation control.
 *
 * Board:  Raspberry Pi 4 Model B
 * Bus:    I2C bus 1 (GPIO2 = SDA, GPIO3 = SCL)
 * Sensor: Sensirion SCD30 (datasheet: https://www.sensirion.com/datasheets/SDS0001234.pdf)
 *
 * Build:  gcc -O2 -Wall -Wextra -o scd30_logger scd30_logger.c -lpigpio -lrt
 * Run:    sudo ./scd30_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

/* ---- SCD30 constants (datasheet) ---- */
#define SCD30_I2C_ADDR        0x60
#define SCD30_MEASUREMENT_CMD  0x358F  /* single-shot, no averaging, no heater */
#define SCD30_DATA_READY_REG  0x00
#define SCD30_DATA_LEN_REG    0x01
#define SCD30_CO2_REG         0x04
#define SCD30_TEMP_REG        0x05
#define SCD30_HUMID_REG       0x06

#define LOG_FILE_NAME         "air_quality.log"
#define SAMPLE_INTERVAL_SEC   5
#define CO2_THRESHOLD_LOW     800
#define CO2_THRESHOLD_HIGH    1200
#define MAX_RETRIES           3

/* ---- Globals ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ---- Prototypes ---- */
static void signal_handler(int sig);
static int  initialize(void);
static int  read_scd30_data(uint16_t *co2, float *temp, float *hum);
static void log_data(uint16_t co2, float temp, float hum);
static void log_error(const char *msg);
static void cleanup(void);

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int initialize(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] pigpio initialisation failed.\n");
        return -1;
    }

    g_i2c_handle = i2cOpen(1, SCD30_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen failed (addr 0x%02X): %s\n",
                SCD30_I2C_ADDR, strerror(errno));
        gpioTerminate();
        return -1;
    }

    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[ERROR] Cannot open log file '%s': %s\n",
                LOG_FILE_NAME, strerror(errno));
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        gpioTerminate();
        return -1;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,co2_ppm,temperature_c,humidity_rh\n");
        fflush(g_log_file);
    }

    return 0;
}

/* ------------------------------------------------------------------ */
static int read_scd30_data(uint16_t *co2, float *temp, float *hum)
{
    char cmd[2] = { (char)((SCD30_MEASUREMENT_CMD >> 8) & 0xFF),
                     (char)(SCD30_MEASUREMENT_CMD & 0xFF) };
    char buf[9];
    int  retries = 0;

    /* Issue measurement command */
    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(g_i2c_handle, cmd, 2) == 0) {
            break;
        }
        retries++;
        gpioDelay(10000); /* 10 ms */
    }
    if (retries >= MAX_RETRIES) {
        log_error("SCD30 measurement command write failed");
        return -1;
    }

    /* Wait for data-ready bit (max ~45 ms) */
    gpioDelay(50000);

    /* Read data-ready status */
    char ready = 0;
    if (i2cReadI2CBlockData(g_i2c_handle, SCD30_DATA_READY_REG, &ready, 1) != 1) {
        log_error("SCD30 data-ready status read failed");
        return -1;
    }
    if (!(ready & 0x01)) {
        log_error("SCD30 data not ready");
        return -1;
    }

    /* Read data length */
    char len = 0;
    if (i2cReadI2CBlockData(g_i2c_handle, SCD30_DATA_LEN_REG, &len, 1) != 1) {
        log_error("SCD30 data length register read failed");
        return -1;
    }
    if (len != 9) {
        log_error("SCD30 data length mismatch");
        return -1;
    }

    /* Read 9 bytes: [status, crc, co2_msb, co2_lsb, t_msb, t_lsb, h_msb, h_lsb, crc] */
    if (i2cReadI2CBlockData(g_i2c_handle, SCD30_CO2_REG, buf, 9) != 9) {
        log_error("SCD30 data read failed");
        return -1;
    }

    /* CRC check (polynomial 0x31, init 0x00, no final XOR) */
    uint8_t calc_crc = 0;
    for (int i = 0; i < 8; i++) {
        calc_crc ^= (uint8_t)buf[i];
        for (int b = 0; b < 8; b++) {
            if (calc_crc & 0x80)
                calc_crc = (uint8_t)((calc_crc << 1) ^ 0x31);
            else
                calc_crc = (uint8_t)(calc_crc << 1);
        }
    }
    uint8_t recv_crc = (uint8_t)buf[8];
    if (calc_crc != recv_crc) {
        log_error("SCD30 CRC mismatch");
        return -1;
    }

    uint16_t co2_raw  = ((uint16_t)(uint8_t)buf[2] << 8) | (uint8_t)buf[3];
    uint16_t temp_raw = ((uint16_t)(uint8_t)buf[4] << 8) | (uint8_t)buf[5];
    uint16_t hum_raw  = ((uint16_t)(uint8_t)buf[6] << 8) | (uint8_t)buf[7];

    *co2  = co2_raw;
    *temp = (float)temp_raw / 100.0f;
    *hum  = (float)hum_raw  / 100.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
static void log_data(uint16_t co2, float temp, float hum)
{
    time_t now = time(NULL);
    struct tm tm_utc;
    char ts[32];

    gmtime_r(&now, &tm_utc);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);

    fprintf(g_log_file, "%s,%u,%.2f,%.2f\n", ts, co2, temp, hum);
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
static void log_error(const char *msg)
{
    time_t now = time(NULL);
    struct tm tm_utc;
    char ts[32];

    gmtime_r(&now, &tm_utc);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);

    fprintf(g_log_file, "%s,ERROR,%s\n", ts, msg);
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize() != 0) {
        fprintf(stderr, "[INFO] Sensor not detected or initialization failed. Exiting gracefully.\n");
        return EXIT_SUCCESS;
    }

    printf("[INFO] SCD30 logger started. Logging to %s every %d s.\n",
           LOG_FILE_NAME, SAMPLE_INTERVAL_SEC);
    printf("[INFO] CO2 < %d -> OFF | %d-%d -> LOW | >= %d -> HIGH\n",
           CO2_THRESHOLD_LOW, CO2_THRESHOLD_LOW, CO2_THRESHOLD_HIGH, CO2_THRESHOLD_HIGH);

    while (g_running) {
        uint16_t co2;
        float temp, hum;

        if (read_scd30_data(&co2, &temp, &hum) == 0) {
            log_data(co2, temp, hum);

            if (co2 < CO2_THRESHOLD_LOW) {
                printf("[INFO] CO2: %u ppm  -> OFF\n", co2);
            } else if (co2 < CO2_THRESHOLD_HIGH) {
                printf("[INFO] CO2: %u ppm  -> LOW\n", co2);
            } else {
                printf("[INFO] CO2: %u ppm  -> HIGH\n", co2);
            }
        } else {
            fprintf(stderr, "[WARN] Sensor read failed; will retry next cycle.\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_SEC * 10 && g_running; i++) {
            gpioDelay(100000);
        }
    }

    printf("\n[INFO] Shutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

