/*
 * SDP32 differential-pressure sensor reader for Raspberry Pi 3 Model B+.
 *
 * Wiring:
 *   SDP32 SDA  -> GPIO2  (pin 3, I2C bus 1)
 *   SDP32 SCL  -> GPIO3  (pin 5, I2C bus 1)
 *   SDP32 VDD  -> 3.3 V
 *   SDP32 GND  -> GND
 *
 * The SDP32 is a 9-byte big-endian device:
 *   [0..1]  pressure MSB/LSB, [2]  pressure CRC8
 *   [3..4]  temperature MSB/LSB, [5]  temperature CRC8
 *   [6..7]  scale-factor MSB/LSB, [8]  scale-factor CRC8
 *
 * Build:  gcc -O2 -Wall -Wextra -o sdp32_reader sdp32_reader.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SDP32_ADDR      0x60
#define SDP32_READ_CMD  0x361F  /* read differential pressure + temperature */
#define SDP32_DATA_LEN  9
#define SAMPLE_PERIOD_S 1000

static volatile sig_atomic_t g_stop = 0;

static void sig_handler(int signo)
{
    (void)signo;
    g_stop = 1;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) == -1)
        perror("sigaction(SIGTERM)");
}

/* Sensirion CRC-8 polynomial 0x31, init 0xFF, no final XOR. */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write(0x%04X) failed: %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_data(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C short read: got %zd of %zu bytes\n", n, len);
        return -1;
    }
    return 0;
}

static int read_sdp32(int fd, float *pressure_pa, float *temperature_c)
{
    uint8_t data[SDP32_DATA_LEN];

    if (i2c_write_cmd(fd, SDP32_READ_CMD) < 0)
        return -1;

    /* SDP32 conversion time is ~45 ms; allow a small margin. */
    usleep(50000);

    if (i2c_read_data(fd, data, SDP32_DATA_LEN) < 0)
        return -1;

    /* Verify CRCs. */
    if (crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "Pressure CRC mismatch\n");
        return -1;
    }
    if (crc8(&data[3], 2) != data[5]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }
    if (crc8(&data[6], 2) != data[8]) {
        fprintf(stderr, "Scale-factor CRC mismatch\n");
        return -1;
    }

    int16_t raw_pressure = (int16_t)((data[0] << 8) | data[1]);
    int16_t raw_temp     = (int16_t)((data[3] << 8) | data[4]);
    int16_t scale_factor = (int16_t)((data[6] << 8) | data[7]);

    if (scale_factor == 0) {
        fprintf(stderr, "Invalid scale factor (0) from sensor\n");
        return -1;
    }

    *pressure_pa    = (float)raw_pressure / (float)scale_factor;
    *temperature_c  = (float)raw_temp / 100.0f;

    return 0;
}

static void print_timestamp(void)
{
    time_t now = time(NULL);
    struct tm tmv;
    char ts[32];
    if (localtime_r(&now, &tmv) != NULL) {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tmv);
        printf("[%s] ", ts);
    } else {
        printf("[?time?] ");
    }
}

int main(int argc, char *argv[])
{
    int interval_s = SAMPLE_PERIOD_S;

    if (argc > 1) {
        char *endptr = NULL;
        long v = strtol(argv[1], &endptr, 10);
        if (endptr == argv[1] || *endptr != '\0' || v <= 0 || v > 3600) {
            fprintf(stderr, "Invalid interval '%s'. Using default %d s.\n",
                    argv[1], SAMPLE_PERIOD_S);
        } else {
            interval_s = (int)v;
        }
    }

    install_signal_handlers();

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SDP32_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                SDP32_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("SDP32 reader started on %s (addr 0x%02X). Sampling every %d s.\n",
           I2C_BUS, SDP32_ADDR, interval_s);
    printf("Press Ctrl+C to stop.\n\n");

    while (!g_stop) {
        float pressure_pa, temperature_c;

        if (read_sdp32(fd, &pressure_pa, &temperature_c) == 0) {
            print_timestamp();
            printf("Pressure: %.2f Pa, Temperature: %.2f C\n",
                   pressure_pa, temperature_c);
        } else {
            print_timestamp();
            fprintf(stderr, "Sensor read failed – sensor may be absent or bus error.\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly. */
        for (int i = 0; i < interval_s * 10 && !g_stop; i++)
            usleep(100000);
    }

    printf("\nShutting down cleanly.\n");
    close(fd);
    return EXIT_SUCCESS;
}

