/*
 * SDP810-125Pa differential pressure sensor reader for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   SDP810 SDA  -> GPIO2 (BCM 2, physical pin 3)
 *   SDP810 SCL  -> GPIO3 (BCM 3, physical pin 5)
 *   SDP810 VDD  -> 3.3 V
 *   SDP810 GND  -> GND
 *
 * I2C bus 1 (SDA: GPIO2, SCL: GPIO3).
 *
 * Build:  gcc -O2 -Wall -Wextra -o sdp810 sdp810.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SDP810_ADDR    0x60

/* SDP810-125Pa: 9-byte read, 3 words × (2 data bytes + 1 CRC byte) */
#define SDP810_READ_LEN 9
#define SDP810_MEAS_DELAY_MS 45
#define SAMPLE_PERIOD_S 1

/* Scale factors (SDP810-125Pa datasheet) */
#define PRESSURE_SCALE 0.001f
#define TEMPERATURE_SCALE 0.1f

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/*
 * CRC-8 as used by Sensirion: polynomial 0x31, init 0xFF.
 */
static uint8_t sdp_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/*
 * Write a 1-byte command to the SDP810.
 * Returns 0 on success, -1 on error.
 */
static int sdp_write_cmd(int fd, uint8_t cmd)
{
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write(0x%02X) failed: %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read `len` bytes from the SDP810.
 * Returns 0 on success, -1 on error.
 */
static int sdp_read_data(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C short read: got %zd of %zu bytes\n", n, len);
        return -1;
    }
    return 0;
}

/*
 * Trigger a measurement and wait for the conversion to complete.
 * Returns 0 on success, -1 on error.
 */
static int sdp_trigger_and_wait(int fd)
{
    if (sdp_write_cmd(fd, 0x3600) == -1)
        return -1;

    struct timespec ts = { 0, SDP810_MEAS_DELAY_MS * 1000000L };
    nanosleep(&ts, NULL);
    return 0;
}

/*
 * Read one 9-byte measurement frame from the SDP810.
 * Returns 0 on success, -1 on error.
 */
static int sdp_read_measurement(int fd, float *pressure, float *temperature)
{
    uint8_t data[SDP810_READ_LEN];

    if (sdp_trigger_and_wait(fd) == -1)
        return -1;

    if (sdp_read_data(fd, data, sizeof(data)) == -1)
        return -1;

    /* Validate CRC for each 3-byte word */
    for (int i = 0; i < 3; i++) {
        if (sdp_crc8(&data[i * 3], 2) != data[i * 3 + 2]) {
            fprintf(stderr, "CRC mismatch on word %d\n", i);
            return -1;
        }
    }

    int16_t raw_pressure = (int16_t)((data[0] << 8) | data[1]);
    int16_t raw_temp     = (int16_t)((data[3] << 8) | data[4]);

    *pressure    = (float)raw_pressure * PRESSURE_SCALE;
    *temperature = (float)raw_temp     * TEMPERATURE_SCALE;
    return 0;
}

int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    if (install_signal_handlers() == -1)
        goto cleanup;

    fd = open(I2C_BUS, O_RDWR);
    if (fd == -1) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        goto cleanup;
    }

    if (ioctl(fd, I2C_SLAVE, SDP810_ADDR) == -1) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                SDP810_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Verify the sensor is present by reading the model word */
    uint8_t model[2];
    if (sdp_read_data(fd, model, sizeof(model)) == -1) {
        fprintf(stderr, "SDP810 not responding on 0x%02X\n", SDP810_ADDR);
        goto cleanup;
    }

    printf("SDP810 detected (model=0x%02X). Sampling every %d s. Ctrl-C to stop.\n",
           (model[0] << 8) | model[1], SAMPLE_PERIOD_S);

    while (g_running) {
        float pressure, temperature;

        if (sdp_read_measurement(fd, &pressure, &temperature) == 0) {
            printf("Pressure: %.2f Pa, Temperature: %.2f °C\n",
                   pressure, temperature);
            fflush(stdout);
        } else {
            fprintf(stderr, "Read failed; will retry next cycle.\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD_S * 10 && g_running; i++)
            usleep(100000);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fd != -1)
        close(fd);
    return rc;
}

