                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    n = read(fd, out, 1);
    if (n != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int hdc1000_init(int fd)
{
    if (i2c_write_reg8(fd, HDC1000_REG_CONFIG, 0x00) < 0)
        return -1;
    return 0;
}

static int hdc1000_read_temp(int fd, float *temp_c)
{
    uint8_t raw;
    if (i2c_read_reg8(fd, HDC1000_REG_TEMP, &raw) < 0)
        return -1;
    int16_t raw16 = (int16_t)((raw & 0x0F) << 8 | raw >> 4);
    *temp_c = (float)raw16 / 16.0f;
    return 0;
}

static int hdc1000_read_humidity(int fd, float *humid_pct)
{
    uint8_t raw;
    if (i2c_read_reg8(fd, HDC1000_REG_HUMID, &raw) < 0)
        return -1;
    int16_t raw16 = (int16_t)((raw & 0x0F) << 8 | raw >> 4);
