        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n",
                HDC1000_ADDR, strerror(errno));
        close(g_fd);
        g_fd = -1;
        return EXIT_FAILURE;
    }

    if (hdc1000_init(g_fd) < 0) {
        fprintf(stderr, "HDC1000 init failed (sensor absent or bus error)\n");
        close(g_fd);
        g_fd = -1;
        return EXIT_FAILURE;
    }

    printf("HDC1000 initialized on %s (addr 0x%02X).\n", I2C_BUS, HDC1000_ADDR);
    printf("Reading every %d ms. Press Ctrl+C to exit.\n", SAMPLE_MS);

    while (g_running) {
        struct timespec ts = { 0, TEMP_CONV_MS * 1000000L };
        nanosleep(&ts, NULL);

        float temp_c, humid_pct;
        if (hdc1000_read_temp(g_fd, &temp_c) < 0 ||
            hdc1000_read_humidity(g_fd, &humid_pct) < 0) {
            fprintf(stderr, "Sensor read error — continuing.\n");
        } else {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temp_c, humid_pct);
            fflush(stdout);
        }

        struct timespec sleep_ts = { 0, SAMPLE_MS * 1000000L };
        while (g_running && nanosleep(&sleep_ts, &sleep_ts) < 0 && errno == EINTR) {
            /* retry after signal interruption */
        }
    }

    if (g_fd >= 0) {
        close(g_fd);
        g_fd = -1;
    }
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

