#define SI7051_REG_MEAS_RATE_CONFIG_13 0x25
#define SI7051_REG_MEAS_RATE_CONFIG_14 0x26
#define SI7051_REG_MEAS_RATE_CONFIG_15 0x27
#define SI7051_REG_MEAS_RATE_CONFIG_16 0x28
#define SI7051_REG_MEAS_RATE_CONFIG_17 0x29
#define SI7051_REG_MEAS_RATE_CONFIG_18 0x2A
#define SI7051_REG_MEAS_RATE_CONFIG_19 0x2B
#define SI7051_REG_MEAS_RATE_CONFIG_20 0x2C
#define SI7051_REG_MEAS_RATE_CONFIG_21 0x2D
#define SI7051_REG_MEAS_RATE_CONFIG_22 0x2E
#define SI7051_REG_MEAS_RATE_CONFIG_23 0x2F
#define SI7051_REG_MEAS_RATE_CONFIG_24 0x30
#define SI7051_REG_MEAS_RATE_CONFIG_25 0x31
#define SI7051_REG_MEAS_RATE_CONFIG_26 0x32
#define SI7051_REG_MEAS_RATE_CONFIG_27 0x33
#define SI7051_REG_MEAS_RATE_CONFIG_28 0x34
#define SI7051_REG_MEAS_RATE_CONFIG_29 0x35
#define SI7051_REG_MEAS_RATE_CONFIG_30 0x36
#define SI7051_REG_MEAS_RATE_CONFIG_31 0x37
#define SI7051_REG_MEAS_RATE_CONFIG_32 0x38
#define SI7051_REG_MEAS_RATE_CONFIG_33 0x39
#define SI7051_REG_MEAS_RATE_CONFIG_34 0x3A
#define SI7051_REG_MEAS_RATE_CONFIG_35 0x3B
#define SI7051_REG_MEAS_RATE_CONFIG_36 0x3C
#define SI7051_REG_MEAS_RATE_CONFIG_37 0x3D
#define SI7051_REG_MEAS_RATE_CONFIG_38 0x3E
#define SI7051_REG_MEAS_RATE_CONFIG_39 0x3F

#define SI7051_REG_TEMP_LOW_EXPECTED 0.5
#define SI7051_REG_TEMP_HIGH_EXPECTED 0.5

#define I2C_BUS_DEVICE I2C_BUS
#define READ_INTERVAL_SEC 5
#define MAX_RETRIES 3
#define TEMP_ERROR -999.0f

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t ret = write(fd, buf, sizeof(buf));
    if (ret != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s (ret=%zd)\n",
                reg, strerror(errno), ret);
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value)
{
    ssize_t ret = write(fd, &reg, 1);
    if (ret != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s (ret=%zd)\n",
                reg, strerror(errno), ret);
        return -1;
    }

    ret = read(fd, value, 1);
    if (ret != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s (ret=%zd)\n",
                reg, strerror(errno), ret);
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value)
{
    uint8_t buf[2];
    ssize_t ret = write(fd, &reg, 1);
    if (ret != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s (ret=%zd)\n",
                reg, strerror(errno), ret);
        return -1;
    }

    ret = read(fd, buf, sizeof(buf));
    if (ret != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C read 16-bit from reg 0x%02X failed: %s (ret=%zd)\n",
                reg, strerror(errno), ret);
        return -1;
    }

    /* Si7051 sends MSB first */
    *value = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int si7051_init(int fd)
{
    uint8_t int_cfg = 0x00;
    uint8_t meas_rate_cfg = 0x00;

    if (i2c_write_reg8(fd, SI7051_REG_INT_CFG, int_cfg) != 0)
        return -1;
    if (i2c_write_reg8(fd, SI7051_REG_MEAS_RATE_CONFIG_1, meas_rate_cfg) != 0)
        return -1;

    return 0;
}

static float si7051_read_temperature(int fd)
{
    uint16_t raw_temp;
    float temperature = TEMP_ERROR;

    if (i2c_read_reg16(fd, SI7051_REG_TEMP_LOW, &raw_temp) != 0)
        return TEMP_ERROR;

    /* Si7051 temperature resolution is 0.5 °C per LSB */
    temperature = (float)raw_temp * 0.5f;

    /* Sanity check: a valid reading should be within 0–125 °C */
    if (temperature < 0.0f || temperature > 125.0f) {
        fprintf(stderr, "Temperature reading out of range: %.2f °C\n", temperature);
        return TEMP_ERROR;
    }

    return temperature;
}

static void log_temperature(float temperature)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    printf("[%s] Temperature: %.2f °C\n", timestamp, temperature);
    fflush(stdout);
}

int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the I2C bus */
    fd = open(I2C_BUS_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the Si7051 device */
    if (ioctl(fd, I2C_SLAVE, SI7051_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire I2C bus access to 0x%02X: %s\n",
                SI7051_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Initialize the Si7051 sensor */
    if (si7051_init(fd) != 0) {
        fprintf(stderr, "Si7051 initialization failed (sensor may be absent or bus error)\n");
        goto cleanup;
    }

    printf("Si7051 temperature sensor initialized. Reading every %d seconds.\n",
           READ_INTERVAL_SEC);
    fflush(stdout);

    /* Main loop */
    while (g_running) {
        float temperature = TEMP_ERROR;

        for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
            temperature = si7051_read_temperature(fd);
            if (temperature != TEMP_ERROR)
                break;
            if (attempt < MAX_RETRIES - 1) {
                fprintf(stderr, "Read attempt %d/%d failed, retrying...\n",
                        attempt + 1, MAX_RETRIES);
                sleep(1);
            }
        }

        if (temperature != TEMP_ERROR) {
            log_temperature(temperature);
        } else {
            fprintf(stderr, "Failed to read temperature after %d attempts.\n",
                    MAX_RETRIES);
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < READ_INTERVAL_SEC && g_running; i++)
            sleep(1);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0)
        close(fd);

    if (rc == EXIT_SUCCESS)
        printf("\nExiting gracefully.\n");

    return rc;
}

