/*
 * MLX90833 Absolute Pressure Sensor Reader for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   MLX90833 SDA -> GPIO2 (pin 3, I2C bus 1)
 *   MLX90833 SCL -> GPIO3 (pin 5, I2C bus 1)
 *   MLX90833 VDD -> 3.3 V
 *   MLX90833 GND -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o mlx90833_reader mlx90833_reader.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MLX90833_ADDR  0x68

/* MLX90833 register addresses (16-bit, big-endian on the bus) */
#define REG_PRESSURE    0x00
#define REG_CONFIG      0x01

/* Config register bits */
#define CFG_MODE_NORMAL  0x00
#define CFG_OSR_1X       0x00
#define CFG_DR_1HZ       0x00

#define SAMPLE_PERIOD_MS 500
#define MAX_RETRIES      3

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) == -1)
        perror("sigaction(SIGTERM)");
}

/* Write a 16-bit value to a 16-bit register address (big-endian on the bus). */
static int i2c_write_reg16(int fd, uint8_t reg, uint16_t value)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)((value >> 8) & 0xFF);
    buf[2] = (uint8_t)(value & 0xFF);

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write_reg16(0x%02X): write failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a 16-bit value from a 16-bit register address (big-endian on the bus). */
static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t reg_buf = reg;

    if (write(fd, &reg_buf, 1) != 1) {
        fprintf(stderr, "i2c_read_reg16(0x%02X): write (reg select) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    uint8_t data[2];
    ssize_t n = read(fd, data, sizeof(data));
    if (n != (ssize_t)sizeof(data)) {
        fprintf(stderr, "i2c_read_reg16(0x%02X): read failed: got %zd bytes, %s\n",
                reg, n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }

    *out = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

static int init_sensor(int fd)
{
    if (i2c_write_reg16(fd, REG_CONFIG, CFG_MODE_NORMAL | CFG_OSR_1X |
                         CFG_DR_1HZ) != 0) {
        fprintf(stderr, "Failed to configure MLX90833 (sensor may be absent)\n");
        return -1;
    }
    return 0;
}

static int read_pressure(int fd, float *pressure_out)
{
    uint16_t raw;
    if (i2c_read_reg16(fd, REG_PRESSURE, &raw) != 0)
        return -1;

    /* Convert raw 16-bit value to pressure (Pa) */
    *pressure_out = (float)raw;
    return 0;
}

int main(void)
{
    install_signal_handlers();

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MLX90833_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                MLX90833_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (init_sensor(fd) != 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("MLX90833 initialized. Reading every %d ms. Press Ctrl+C to exit.\n",
           SAMPLE_PERIOD_MS);

    while (g_running) {
        float pressure;
        if (read_pressure(fd, &pressure) == 0) {
            time_t now = time(NULL);
            struct tm tm_info;
            char ts[32];

            if (localtime_r(&now, &tm_info) != NULL) {
                strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
                printf("[%s] Pressure: %.2f Pa\n", ts, pressure);
            } else {
                printf("[unknown time] Pressure: %.2f Pa\n", pressure);
            }
        } else {
            fprintf(stderr, "Failed to read pressure.\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly. */
        for (int i = 0; i < SAMPLE_PERIOD_MS / 100 && g_running; i++)
            usleep(100000);
    }

    printf("\nExiting cleanly.\n");
    close(fd);
    return EXIT_SUCCESS;
}

