/*
 * Raspberry Pi Zero W – TDK ICP-10101 barometric pressure sensor reader
 *
 * Wiring:
 *   ICP-10101 SDA  -> GPIO2  (pin 3, I2C bus 1)
 *   ICP-10101 SCL  -> GPIO3  (pin 5, I2C bus 1)
 *   ICP-10101 VDD  -> 3.3 V
 *   ICP-10101 GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o icp10101 icp10101.c
 *
 * Run:
 *   ./icp10101
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- ICP-10101 constants (datasheet) ---- */
#define ICP10101_ADDR        0x60
#define ICP10101_REG_TEMP   0x00
#define ICP10101_REG_PRESS  0x01
#define ICP10101_REG_CONFIG 0x02

#define ICP10101_CMD_MEASURE 0x01
#define ICP10101_CMD_RESET   0x80

/* Config: 0x00 = default, 0x01 = continuous measurement mode */
#define ICP10101_CFG_CONT   0x01

/* Measurement cycle time (ms) */
#define MEAS_DELAY_MS       7
#define SAMPLE_PERIOD_S     5

/* ---- Globals for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ---- Helpers ---- */
static void handle_signal(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) == -1)
        perror("sigaction(SIGTERM)");
}

/* ---- I2C helpers ---- */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_write_reg8(0x%02X, 0x%02X) failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8 write(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8 read(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = val;
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg16 write(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_read_reg16 read(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

/* ---- Sensor helpers ---- */
static int icp10101_reset(int fd)
{
    if (i2c_write_reg8(fd, ICP10101_REG_CONFIG, ICP10101_CMD_RESET) == -1)
        return -1;
    usleep(10000); /* 10 ms reset settle */
    return 0;
}

static int icp10101_init(int fd)
{
    if (icp10101_reset(fd) == -1) {
        fprintf(stderr, "ICP-10101 reset failed (sensor absent or bus error).\n");
        return -1;
    }
    if (i2c_write_reg8(fd, ICP10101_REG_CONFIG, ICP10101_CFG_CONT) == -1)
        return -1;
    return 0;
}

static int icp10101_read(int fd, float *temperature, float *pressure)
{
    /* Trigger continuous measurement mode */
    if (i2c_write_reg8(fd, ICP10101_REG_CONFIG, ICP10101_CFG_CONT) == -1)
        return -1;

    /* Issue measurement command */
    if (i2c_write_reg8(fd, ICP10101_REG_CONFIG, ICP10101_CMD_MEASURE) == -1)
        return -1;

    usleep(MEAS_DELAY_MS * 1000);

    /* Read temperature (2 bytes, big-endian) */
    uint16_t raw_t;
    if (i2c_read_reg16(fd, ICP10101_REG_TEMP, &raw_t) == -1)
        return -1;
