        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, ICP10101_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                ICP10101_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    if (icp10101_init(g_i2c_fd) == -1) {
        fprintf(stderr, "ICP-10101 initialization failed.\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("ICP-10101 initialized on /dev/i2c-1 (addr 0x%02X).\n", ICP10101_ADDR);
    printf("Sampling every %d s. Press Ctrl+C to exit.\n", SAMPLE_PERIOD_S);

    while (g_running) {
        float temperature, pressure;

        if (icp10101_read(g_i2c_fd, &temperature, &pressure) == 0) {
            char ts[32];
            get_timestamp(ts, sizeof(ts));
