/*
 * MLX90819 Pressure Sensor Reader for Raspberry Pi 5
 * Uses pigpio for I2C communication.
 *
 * Wiring:
 *   MLX90819 SDA -> GPIO 2 (I2C bus 1 SDA)
 *   MLX90819 SCL -> GPIO 3 (I2C bus 1 SCL)
 *   MLX90819 VDD -> 3.3 V
 *   MLX90819 GND -> GND
 *
 * Build: gcc -Wall -Wextra -O2 -o mlx90819 mlx90819.c -lpigpio -lrt
 * Run:   sudo ./mlx90819
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x68
#define SAMPLE_PERIOD  1.0   /* seconds */
#define MAX_RETRIES    3

/* MLX90819 register addresses (example values; adjust per datasheet) */
#define REG_PRESSURE   0x00
#define REG_CONFIG     0x01

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0)
        perror("warning: sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) != 0)
        perror("warning: sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        i2cClose(g_i2c_fd);
        g_i2c_fd = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/*
 * Write a single byte to a register.
 * Returns 0 on success, -1 on failure.
 */
static int write_register(uint8_t reg, uint8_t value)
{
    char buf[2];
    buf[0] = (char)reg;
    buf[1] = (char)value;

    if (i2cWriteDevice(g_i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "Error: I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/*
 * Read `len` bytes starting from `reg` into `buf`.
 * Returns 0 on success, -1 on failure.
 */
static int read_registers(uint8_t reg, uint8_t *buf, uint8_t len)
{
    char reg_buf[1] = { (char)reg };

    if (i2cWriteDevice(g_i2c_fd, reg_buf, 1) != 1) {
        fprintf(stderr, "Error: I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (i2cReadDevice(g_i2c_fd, (char *)buf, len) != len) {
        fprintf(stderr, "Error: I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/*
 * Read pressure from the MLX90819.
 * Returns 0 on success and stores the pressure value in *pressure.
 * Returns -1 on any I2C error.
 */
static int read_pressure(float *pressure)
{
    uint8_t buf[2];
    int16_t raw;

    if (read_registers(REG_PRESSURE, buf, 2) != 0)
        return -1;

    raw = (int16_t)((buf[0] << 8) | buf[1]);
    *pressure = (float)raw;
    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    float pressure;
    int  retries;
    bool ok;

    install_signal_handlers();

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_fd = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Error: i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Probe: try a register read to confirm the sensor is present */
    uint8_t probe[1];
    if (read_registers(REG_PRESSURE, probe, 1) != 0) {
        fprintf(stderr, "Error: MLX90819 not detected at 0x%02X on bus %d\n",
                I2C_ADDR, I2C_BUS);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MLX90819 pressure sensor reader started (bus %d, addr 0x%02X)\n",
           I2C_BUS, I2C_ADDR);
    fflush(stdout);

    while (g_running) {
        retries = 0;
        ok = false;

        while (retries < MAX_RETRIES && g_running) {
            if (read_pressure(&pressure) == 0) {
                ok = true;
                break;
            }
            retries++;
            if (retries < MAX_RETRIES)
                time_sleep(0.1);
        }

        if (ok) {
            time_t now = time(NULL);
            struct tm tm_info;
            char ts[32];

            if (localtime_r(&now, &tm_info) != NULL) {
                strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
                printf("[%s] Pressure: %.2f Pa\n", ts, pressure);
            } else {
                printf("[unknown time] Pressure: %.2f Pa\n", pressure);
            }
            fflush(stdout);
        } else {
            fprintf(stderr, "Error: Failed to read pressure after %d retries\n",
                    MAX_RETRIES);
        }

        /* Sleep for the remainder of the sample period */
        time_sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

