/*
 * SDP800-500Pa Differential Pressure Sensor Monitor
 * Board:  Raspberry Pi 3 Model B+
 * Bus:    I2C bus 1 (SDA=GPIO2, SCL=GPIO3)
 * Sensor: Sensirion SDP800-500Pa
 *
 * Reads differential pressure and temperature every 5 seconds,
 * logs to pressure_log.txt in CSV format, and exits cleanly on SIGINT/SIGTERM.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SDP800_ADDR    0x60
#define LOG_FILE       "pressure_log.txt"
#define SAMPLE_PERIOD  5          /* seconds between samples */
#define MEAS_DELAY_MS  45         /* SDP800 conversion time */

/* SDP800 9-byte measurement frame (3 words × 2 data bytes + 1 CRC byte) */
#define SDP800_FRAME_LEN 9

/* CRC-8 parameters used by Sensirion */
#define CRC8_POLY 0x31
#define CRC8_INIT 0xFF

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Sensirion CRC-8: polynomial 0x31, initial value 0xFF */
static uint8_t sensirion_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ CRC8_POLY);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/*
 * Read one 9-byte measurement frame from the SDP800.
 * Returns 0 on success, -1 on I2C error, -2 on CRC mismatch.
 */
static int sdp800_read(int fd, float *pressure, float *temperature)
{
    uint8_t buf[SDP800_FRAME_LEN];

