/*
 * Raspberry Pi Zero W – Honeywell HIH6130 I2C Temperature & Humidity Logger
 *
 * Wiring:
 *   HIH6130 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   HIH6130 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   HIH6130 VDD  -> 3.3 V
 *   HIH6130 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o env_logger env_logger.c
 * Run:    ./env_logger
 */

#define _POSIX_C_SOURCE 200809L

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define HIH6130_ADDR   0x27
#define LOG_FILE       "environmental_data.log"
#define LOG_SIZE_LIMIT 1048576  /* 1 MB */
#define SAMPLE_INTERVAL 5       /* seconds */
#define MEAS_DELAY_MS  40       /* HIH6130 conversion time */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */

static int i2c_write(int fd, const uint8_t *buf, size_t len)
{
    if (write(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* HIH6130 sensor                                                         */
/* ------------------------------------------------------------------ */

/*
 * Trigger a measurement and read the 2-byte result.
 * Returns 0 on success, -1 on I/O error, -2 on sensor error.
 */
static int read_hih6130(int fd, float *temperature, float *humidity)
{
    uint8_t cmd = 0x00;   /* Start measurement */
    uint8_t data[2];

    if (i2c_write(fd, &cmd, 1) < 0)
        return -1;

    usleep(MEAS_DELAY_MS * 1000);

    if (i2c_read(fd, data, 2) < 0)
        return -1;

    /* Status bits are the two most significant bits of the first byte */
    uint8_t status = (data[0] >> 6) & 0x03;
    if (status != 0x00) {
        fprintf(stderr, "HIH6130 status error: 0x%02X\n", status);
        return -2;
    }

    uint16_t raw_h = ((uint16_t)data[0] << 8) | data[1];
    uint16_t raw_t = ((uint16_t)data[1] << 8) | data[0];

    *humidity = (float)raw_h / 16383.0f * 100.0f;
    *temperature = (float)raw_t / 16383.0f * 165.0f - 40.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */

static void log_data(float temperature, float humidity)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(fp, "%s, Temperature: %.2f C, Humidity: %.2f %%\n",
            ts, temperature, humidity);
    fclose(fp);
}

static void ensure_log_size(int fd)
{
    if (fd < 0)
        return;

    /* Check file size without opening it */
    struct stat st;
    if (fstat(fd, &st) < 0) {
        fprintf(stderr, "fstat failed: %s\n", strerror(errno));
        return;
    }

    if (st.st_size > LOG_SIZE_LIMIT) {
        /* Roll back to the last newline */
        char buf[512];
        ssize_t pos = 0;
        ssize_t off = 0;
        while (off < st.st_size) {
            ssize_t n = read(fd, buf + pos, sizeof(buf) - 1 - pos);
            if (n < 0) {
                if (errno == EINTR)
                    continue;
                fprintf(stderr, "Rollback read failed: %s\n", strerror(errno));
                return;
            }
            if (n == 0)
                break;
            pos += n;
            off += n;
        }
        if (pos > 0) {
            /* Move cursor to the last newline */
            size_t last = pos - 1;
            while (last > 0 && buf[last - 1] != '\n') {
                last--;
            }
            if (last > 0) {
                size_t off2 = last;
                while (off2 > 0 && buf[off2 - 1] != '\n') {
                    off2--;
                }
                if (off2 > 0) {
                    if (lseek(fd, -off2, SEEK_CUR) < 0) {
                        fprintf(stderr, "lseek failed: %s\n", strerror(errno));
                        return;
                    }
                }
            }
        }
        /* Truncate */
        if (ftruncate(fd, last) < 0) {
            fprintf(stderr, "ftruncate failed: %s\n", strerror(errno));
        }
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, HIH6130_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                HIH6130_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("HIH6130 logger started on %s (addr 0x%02X). Press Ctrl+C to stop.\n",
           I2C_BUS, HIH6130_ADDR);

    while (g_running) {
        float temperature, humidity;

        int rc = read_hih6130(fd, &temperature, &humidity);
        if (rc == 0) {
            log_data(temperature, humidity);
            printf("T=%.2f C  H=%.2f %%\n", temperature, humidity);
        } else if (rc == -2) {
            fprintf(stderr, "Sensor read failed (status error).\n");
        } else {
            fprintf(stderr, "I2C read failed.\n");
        }

        /* Sleep SAMPLE_INTERVAL seconds, but wake early on signal */
        for (int i = 0; i < SAMPLE_INTERVAL && g_running; i++)
            sleep(1);
    }

    printf("\nShutting down...\n");
    close(fd);
    return EXIT_SUCCESS;
}

