/*
 * brake_pressure.c — Read brake pressure from a Melexis MLX90824 SENT sensor
 * on a Raspberry Pi 3 Model B+ using the SENT single-wire protocol.
 *
 * Wiring:
 *   MLX90824 VCC  -> 3.3 V (Pin 1)
 *   MLX90824 GND  -> GND   (Pin 9)
 *   MLX90824 SCK  -> GPIO4 (Pin 7, BCM 4)
 *   MLX90824 GND  -> GND   (Pin 9)
 *
 * Build:  gcc -O2 -Wall -Wextra -o brake_pressure brake_pressure.c
 * Run:    ./brake_pressure
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define SENT_GPIO_PIN      4
#define LOG_FILE           "pressure_log.txt"
#define READ_INTERVAL_SEC  1
#define SENT_TICK_US       3
#define SENT_SYNC_TICKS    56
#define SENT_MIN_TICKS     12
#define SENT_MAX_TICKS     271
#define SENT_NIBBLES        4
#define TIMEOUT_US         1000000  /* 1 s timeout for a full SENT frame */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* SENT frame parsing                                                    */
/* ------------------------------------------------------------------ */
/*
 * Returns 0 on success and fills *nibbles with the 4 SENT nibbles.
 * Returns -1 on timeout, -2 on checksum mismatch, -3 on out-of-range
 * tick count, -4 on any other bus error.
 */
static int read_sent_frame(uint8_t *nibbles)
{
    uint32_t start_tick = 0;
    uint32_t pulse_tick = 0;
    uint32_t elapsed = 0;
    int nibble_idx = 0;

    /* --- Wait for the start-of-frame (sync) pulse --- */
    while (g_running) {
        elapsed = 0;
        while (g_running) {
            elapsed = (uint32_t)(time_time() - start_tick);
            if (elapsed > TIMEOUT_US) {
                fprintf(stderr, "Error: SENT start-of-frame timeout (no sensor or wiring issue)\n");
                return -1;
            }
            if (gpioRead(SENT_GPIO_PIN) == 0) {
                break;
            }
            usleep(SENT_TICK_US);
        }
        if (!g_running) {
            return -1;
        }

        /* Wait for the end of the sync pulse (rising edge) */
        elapsed = 0;
        while (g_running) {
            elapsed = (uint32_t)(time_time() - start_tick);
            if (elapsed > TIMEOUT_US) {
                fprintf(stderr, "Error: SENT sync-pulse end timeout\n");
                return -1;
            }
            if (gpioRead(SENT_GPIO_PIN) == 1) {
                break;
            }
            usleep(SENT_TICK_US);
        }
        if (!g_running) {
            return -1;
        }

        /* Measure the sync pulse width */
        uint32_t sync_width = elapsed;
        if (sync_width < SENT_SYNC_TICKS * SENT_TICK_US) {
            fprintf(stderr, "Error: SENT sync-pulse width too short (%u us)\n", sync_width);
            return -1;
        }

        /* --- Wait for the first data nibble --- */
        start_tick = time_time();
        while (g_running) {
            elapsed = (uint32_t)(time_time() - start_tick);
            if (elapsed > TIMEOUT_US) {
                fprintf(stderr, "Error: SENT nibble %d timeout\n", nibble_idx);
                return -1;
            }
            if (gpioRead(SENT_GPIO_PIN) == 0) {
                break;
            }
            usleep(SENT_TICK_US);
        }
        if (!g_running) {
            return -1;
        }

        /* Measure the first data pulse width */
        start_tick = time_time();
        while (g_running) {
            elapsed = (uint32_t)(time_time() - start_tick);
            if (elapsed > TIMEOUT_US) {
                fprintf(stderr, "Error: SENT nibble %d pulse timeout\n", nibble_idx);
                return -1;
            }
            if (gpioRead(SENT_GPIO_PIN) == 1) {
                break;
            }
            usleep(SENT_TICK_US);
        }
        if (!g_running) {
            return -1;
        }

        uint32_t tick_count = (uint32_t)(elapsed / SENT_TICK_US);
        if (tick_count < SENT_MIN_TICKS || tick_count > SENT_MAX_TICKS) {
            fprintf(stderr, "Error: SENT nibble %d tick count out of range (%u ticks)\n",
                    nibble_idx, tick_count);
            return -3;
        }

        nibble_idx++;
        if (nibble_idx > SENT_NIBBLES) {
            fprintf(stderr, "Error: Unexpected number of nibbles (%d)\n", nibble_idx);
            return -1;
        }

        pulse_tick = tick_count;
    }

    /* --- Extract nibbles --- */
    uint32_t nibble_ticks[SENT_NIBBLES];
    if (nibble_idx < SENT_NIBBLES) {
        fprintf(stderr, "Error: Incomplete SENT frame (%d nibbles)\n", nibble_idx);
        return -1;
    }

    for (int i = 0; i < SENT_NIBBLES; i++) {
        nibble_ticks[i] = pulse_tick;
    }

    /* --- Checksum --- */
    uint8_t checksum = 0;
    for (int i = 0; i < SENT_NIBBLES; i++) {
        checksum += nibble_ticks[i];
    }
    uint8_t calc_checksum = (uint8_t)((checksum + 1) & 0x0F);
    if (calc_checksum != nibble_ticks[SENT_NIBBLES - 1]) {
        fprintf(stderr, "Error: SENT checksum mismatch (calc=0x%X, recv=0x%X)\n",
                calc_checksum, nibble_ticks[SENT_NIBBLES - 1]);
        return -2;
    }

    for (int i = 0; i < SENT_NIBBLES; i++) {
        nibbles[i] = (uint8_t)nibble_ticks[i];
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_pressure_data(const char *filename, const char *timestamp,
                             const uint8_t *nibbles)
{
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    char line[128];
    int len = snprintf(line, sizeof(line), "%s, Pressure: ", timestamp);
    if (len < 0 || len >= (int)sizeof(line)) {
        fprintf(stderr, "Error: timestamp formatting failed\n");
        fclose(fp);
        return -1;
    }

    for (int i = 0; i < SENT_NIBBLES; i++) {
        len += snprintf(line + len, sizeof(line) - len, "Nibble%d: %u ", i, nibbles[i]);
    }

    if (len < (int)sizeof(line)) {
        fprintf(fp, "%s\n", line);
    } else {
        fprintf(stderr, "Error: line too long for log entry\n");
    }

    if (fclose(fp) != 0) {
        perror("fclose(" LOG_FILE ")");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    /* --- Initialize GPIO --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: gpioInitialise() failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENT_GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_INPUT) failed\n", SENT_GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Brake pressure monitoring started. Logging to %s\n", LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        uint8_t nibbles[SENT_NIBBLES];
        int rc = read_sent_frame(nibbles);

        if (rc == 0) {
            time_t rawtime = time(NULL);
            struct tm *timeinfo = localtime(&rawtime);
            char timestamp[32];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            if (log_pressure_data(LOG_FILE, timestamp, nibbles) != 0) {
                fprintf(stderr, "Warning: failed to log pressure data\n");
            }
        } else if (rc == -1) {
            fprintf(stderr, "Warning: SENT read error, retrying in %d s\n",
                    READ_INTERVAL_SEC);
        } else {
            fprintf(stderr, "Warning: SENT read error (code %d), retrying in %d s\n",
                    rc, READ_INTERVAL_SEC);
        }

        sleep(READ_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    if (fclose(fp) != 0) {
        perror("fclose(" LOG_FILE ")");
    }
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

