/*
 * greenhouse_monitor.c — TMP117 greenhouse temperature logger for Raspberry Pi Zero W
 *
 * Build:  gcc -O2 -Wall -Wextra -o greenhouse_monitor greenhouse_monitor.c
 * Run:    ./greenhouse_monitor
 *
 * Hardware:
 *   TMP117 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   TMP117 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   TMP117 VDD  -> 3.3 V
 *   TMP117 GND  -> GND
 *
 * The TMP117 is addressed at I2C address 0x48.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define TMP117_ADDR    0x48
#define LOG_FILE       "greenhouse_temps.dat"
#define SAMPLE_PERIOD  60          /* seconds between readings */
#define MAX_RETRIES    3

/* TMP117 register addresses */
#define TMP117_REG_TEMP_L  0x00
#define TMP117_REG_TEMP_H  0x01
#define TMP117_REG_CONFIG 0x02

/* TMP117 config: 0x0000 -> 12-bit resolution, continuous conversion */
#define TMP117_CONFIG_VAL 0x0000

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
