/* Verify the TMP117 is present by reading the device ID register.     */
/* Returns 0 on success, -1 on failure.                               */
/* ------------------------------------------------------------------ */
static int verify_sensor(int fd)
{
    uint16_t id = 0;
    if (tmp117_read_reg16(fd, 0x00, &id) != 0)
        return -1;

