    if (i2c_write_reg8(i2c_fd, TMP117_REG_CONFIG, TMP117_CONFIG_DEFAULT) < 0) {
        fprintf(stderr, "Failed to configure TMP117\n");
        return -1;
    }
    return 0;
}

