    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (init_i2c() < 0) {
        return 1;
    }
    if (init_sensor() < 0) {
        cleanup();
        return 1;
    }

    printf("TMP117 temperature logger started. Sampling every %d seconds. Press Ctrl+C to exit.\n", SAMPLE_INTERVAL_SEC);

    while (running) {
        float temperature;
        if (read_temperature(&temperature) == 0) {
            add_to_buffer(temperature);
            printf("Temperature: %.2f C\n", temperature);
        } else {
            fprintf(stderr, "Failed to read temperature. Skipping this sample.\n");
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

