/*
 * SHTC3 Temperature & Humidity Logger for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   SHTC3 VDD  -> Pi Pin 1 (3.3 V)
 *   SHTC3 GND  -> Pi Pin 2 (GND)
 *   SHTC3 SDA  -> Pi GPIO2 / Pin 3 (I2C bus 1 SDA)
 *   SHTC3 SCL  -> Pi GPIO3 / Pin 4 (I2C bus 1 SCL)
 *
 * Build:  gcc -O2 -Wall -Wextra -o shtc3_logger shtc3_logger.c
 * Run:    ./shtc3_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x44
#define LOG_FILE       "shtc3_environment.log"
#define SAMPLE_PERIOD  5          /* seconds between readings */
#define CONV_WAIT_US   15000      /* 15 ms > 12.4 ms max conversion time */
#define MAX_RETRIES    3

/* SHTC3 command opcodes */
#define CMD_MEASURE_T_H  0x2C   /* temperature + humidity, clock stretching disabled */
#define CMD_RESET        0x30   /* software reset */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF)                        */
/* ------------------------------------------------------------------ */
static uint8_t shtc3_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Sensor reset                                                         */
/* ------------------------------------------------------------------ */
static int shtc3_reset(int handle)
{
    uint8_t cmd = CMD_RESET;
    if (i2cWriteDevice(handle, (char *)&cmd, 1) != 0) {
        fprintf(stderr, "[ERROR] Reset write failed: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(15000);                 /* 15 ms reset settling time */
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read temperature and humidity                                       */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int shtc3_read(int handle, float *temperature, float *humidity)
{
    uint8_t data[6];
    int16_t raw_t, raw_h;

    /* Send measurement command */
    uint8_t cmd = CMD_MEASURE_T_H;
    if (i2cWriteDevice(handle, (char *)&cmd, 1) != 0) {
        fprintf(stderr, "[ERROR] Measurement command failed: %s\n", strerror(errno));
        return -1;
    }

    gpioDelay(CONV_WAIT_US);          /* wait for conversion */

    /* Read 6 bytes: T_MSB, T_LSB, T_CRC, H_MSB, H_LSB, H_CRC */
    if (i2cReadDevice(handle, (char *)data, 6) != 6) {
        fprintf(stderr, "[ERROR] Read failed: %s\n", strerror(errno));
        return -1;
    }

    /* Validate CRCs */
    if (shtc3_crc8(&data[0], 2) != data[2]) {
        fprintf(stderr, "[ERROR] Temperature CRC mismatch\n");
        return -1;
    }
    if (shtc3_crc8(&data[3], 2) != data[5]) {
        fprintf(stderr, "[ERROR] Humidity CRC mismatch\n");
        return -1;
    }

    raw_t = (int16_t)((data[0] << 8) | data[1]);
    raw_h = (int16_t)((data[3] << 8) | data[4]);

    *temperature = -45.0f + 175.0f * (float)raw_t / 65535.0f;
    *humidity   = 100.0f * (float)raw_h / 65535.0f;

    /* Sanity range checks */
    if (*temperature < -40.0f || *temperature > 125.0f) {
        fprintf(stderr, "[WARN] Temperature out of range: %.2f C\n", *temperature);
        return -1;
    }
    if (*humidity < 0.0f || *humidity > 100.0f) {
        fprintf(stderr, "[WARN] Humidity out of range: %.2f %%\n", *humidity);
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Log a reading to file and stdout                                    */
/* ------------------------------------------------------------------ */
static void log_data(float temperature, float humidity)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "[ERROR] Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }

    fprintf(fp, "%s,%.2f,%.2f\n", ts, temperature, humidity);
    fclose(fp);

    printf("%s,%.2f,%.2f\n", ts, temperature, humidity);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (bus %d, addr 0x%02X): %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Reset sensor */
    if (shtc3_reset(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] Sensor reset failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGINT) failed: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGTERM) failed: %s\n", strerror(errno));
    }

    printf("SHTC3 logger started. Logging to %s every %d s. Press Ctrl+C to stop.\n",
           LOG_FILE, SAMPLE_PERIOD);

    int consecutive_failures = 0;

    while (g_running) {
        float temperature, humidity;

        if (shtc3_read(g_i2c_handle, &temperature, &humidity) == 0) {
            log_data(temperature, humidity);
            consecutive_failures = 0;
        } else {
            consecutive_failures++;
            fprintf(stderr, "[WARN] Read failed (%d consecutive)\n",
                    consecutive_failures);
            if (consecutive_failures >= MAX_RETRIES) {
                fprintf(stderr, "[FATAL] Max consecutive failures reached, aborting.\n");
                break;
            }
        }

        /* Sleep in 100 ms increments so SIGINT is responsive */
        for (int i = 0; i < SAMPLE_PERIOD * 10 && g_running; i++)
            gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

