    printf("%s,%.2f,%.2f\n", ts, temperature, humidity);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (bus %d, addr 0x%02X): %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Reset sensor */
    if (shtc3_reset(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] Sensor reset failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGINT) failed: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGTERM) failed: %s\n", strerror(errno));
    }

    printf("SHTC3 logger started. Logging to %s every %d s. Press Ctrl+C to stop.\n",
           LOG_FILE, SAMPLE_PERIOD);

    int consecutive_failures = 0;

    while (g_running) {
        float temperature, humidity;

        if (shtc3_read(g_i2c_handle, &temperature, &humidity) == 0) {
            log_data(temperature, humidity);
            consecutive_failures = 0;
        } else {
            consecutive_failures++;
            fprintf(stderr, "[WARN] Read failed (%d consecutive)\n",
                    consecutive_failures);
            if (consecutive_failures >= MAX_RETRIES) {
                fprintf(stderr, "[FATAL] Max consecutive failures reached, aborting.\n");
                break;
            }
        }

        /* Sleep in 100 ms increments so SIGINT is responsive */
        for (int i = 0; i < SAMPLE_PERIOD * 10 && g_running; i++)
            gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

