    if (i2c_write_reg8(fd, SI7202_REG_INT_EN_32, 0x00) != 0) return -1;

    /* Configure: 50 Hz output, 12-bit resolution */
    if (i2c_write_reg8(fd, SI7202_REG_CONFIG, 0x00) != 0) return -1;

    return 0;
}

static int read_sensor_data(int fd, float *temperature, float *speed)
{
    uint16_t raw_temp = 0, raw_speed = 0;
    int retries = MAX_RETRIES;

    while (retries > 0) {
        if (i2c_read_reg16(fd, SI7202_REG_TEMP, &raw_temp) == 0 &&
            i2c_read_reg16(fd, SI7202_REG_SPEED, &raw_speed) == 0) {
            *temperature = (float)raw_temp / 100.0f;
            *speed = (float)raw_speed / 100.0f;
            return 0;
        }
        retries--;
        if (retries > 0) {
            fprintf(stderr, "Sensor read failed, retrying (%d left)...\n", retries);
            sleep(0.1);
        }
    }

    fprintf(stderr, "Failed to read sensor data after %d retries.\n", MAX_RETRIES);
    *temperature = NAN;
    *speed = NAN;
    return -1;
}

static int log_data(FILE *fp, float temperature, float speed)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (isnan(temperature) || isnan(speed)) {
        fprintf(fp, "%s, NaN, NaN\n", timestamp);
    } else {
        fprintf(fp, "%s, %.2f, %.2f\n", timestamp, temperature, speed);
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SI7202_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                SI7202_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    if (init_si7202(g_i2c_fd) != 0) {
        fprintf(stderr, "Si7202 initialization failed.\n");
        cleanup();
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    /* Write header if file is empty */
    fseek(g_log_fp, 0, SEEK_END);
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "Timestamp, Temperature (C), Speed (rpm)\n");
        fflush(g_log_fp);
    }

    printf("Si7202 rotational speed & temperature logger started. Press Ctrl+C to stop.\n");

    while (g_running) {
        float temperature, speed;
        if (read_sensor_data(g_i2c_fd, &temperature, &speed) == 0) {
            if (log_data(g_log_fp, temperature, speed) != 0) {
                fprintf(stderr, "Failed to log data.\n");
            }
        } else {
            fprintf(stderr, "Sensor read failed; logging NaN values.\n");
            if (log_data(g_log_fp, NAN, NAN) != 0) {
                fprintf(stderr, "Failed to log NaN data.\n");
            }
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return 0;
}

