/*
 * TMP117 Temperature Logger for Raspberry Pi 3 Model B+
 * Reads temperature from a TMP117 sensor on the I2C bus and logs it
 * to temperature_log.txt once per second. Handles SIGINT for clean exit.
 *
 * Build: gcc -O2 -Wall -o tmp117_logger tmp117_logger.c -lpigpio -lrt
 * Run:   sudo ./tmp117_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x48
#define LOG_FILE       "temperature_log.txt"
#define SAMPLE_PERIOD  1.0   /* seconds */
#define MAX_REINIT_ATTEMPTS 3
#define MAX_REINIT_ATTEMPTS_PER_CYCLE 3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg(int handle, uint8_t reg, uint8_t value)
{
    char buf[2];
    buf[0] = (char)reg;
    buf[1] = (char)value;

    if (i2cWriteDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "i2cWriteDevice(reg=0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(int handle, uint8_t reg, uint8_t *value)
{
    if (i2cWriteDevice(handle, (char *)&reg, 1) != 1) {
        fprintf(stderr, "i2cWriteDevice(reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (i2cReadDevice(handle, (char *)value, 1) != 1) {
        fprintf(stderr, "i2cReadDevice(reg=0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int handle, uint8_t reg, int16_t *value)
{
    uint8_t buf[2];

    if (i2cWriteDevice(handle, (char *)&reg, 1) != 1) {
        fprintf(stderr, "i2cWriteDevice(reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (i2cReadDevice(handle, (char *)buf, 2) != 2) {
        fprintf(stderr, "i2cReadDevice(reg=0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *value = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* TMP117 temperature read                                              */
/* ------------------------------------------------------------------ */
static int read_temperature(int handle, float *temperature)
{
    int16_t raw;

    if (i2c_read_reg16(handle, 0x00, &raw) != 0)
        return -1;

    /* TMP117: 12-bit two's-complement, left-justified in 16-bit word.
     * Bits [15:4] hold the temperature; bits [3:0] are always 0. */
    int16_t temp_raw = raw & 0x0FFF;

    /* Sign-extend from 12 bits to 16 bits */
    if (temp_raw & 0x0800)
        temp_raw |= 0xF000;

    *temperature = (float)temp_raw / 16.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_temperature(float temperature)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    fprintf(fp, "%s, Temperature: %.2f C\n", timestamp, temperature);
    fclose(fp);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus --- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handler --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(stdout, "TMP117 logger started. Logging to %s. Press Ctrl+C to exit.\n",
            LOG_FILE);

    int consecutive_failures = 0;

    while (g_running) {
        float temperature;

        if (read_temperature(g_i2c_handle, &temperature) == 0) {
            consecutive_failures = 0;

            if (log_temperature(temperature) != 0) {
                fprintf(stderr, "Failed to log temperature.\n");
            } else {
                fprintf(stdout, "Temperature: %.2f C\n", temperature);
            }
        } else {
            consecutive_failures++;
            fprintf(stderr, "Failed to read temperature (attempt %d/%d).\n",
                    consecutive_failures, MAX_REINIT_ATTEMPTS);

            if (consecutive_failures >= MAX_REINIT_ATTEMPTS) {
                fprintf(stderr, "Max re-initialization attempts reached. Exiting.\n");
                break;
            }

            /* Attempt to re-initialize the I2C handle up to MAX_REINIT_ATTEMPTS_PER_CYCLE times */
            for (int attempt = 1; attempt <= MAX_REINIT_ATTEMPTS_PER_CYCLE && g_running; attempt++) {
                fprintf(stderr, "Re-initializing I2C (attempt %d/%d)...\n",
                        attempt, MAX_REINIT_ATTEMPTS_PER_CYCLE);

                if (g_i2c_handle >= 0) {
                    i2cClose(g_i2c_handle);
                    g_i2c_handle = -1;
                }

                gpioDelay(100000); /* 100 ms */

                g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
                if (g_i2c_handle < 0) {
                    fprintf(stderr, "i2cOpen failed (attempt %d/%d): %s\n",
                            attempt, MAX_REINIT_ATTEMPTS_PER_CYCLE, strerror(errno));
                    gpioDelay(100000);
                    continue;
                }

                if (read_temperature(g_i2c_handle, &temperature) == 0) {
                    break;
                }

                consecutive_failures = 0;
                fprintf(stderr, "Re-initialization attempt %d/%d failed.\n",
                        attempt, MAX_REINIT_ATTEMPTS_PER_CYCLE);
            }
        }

        /* Sleep for the sample period, but wake early on signal */
        for (int i = 0; i < 10 && g_running; i++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

