/*
 * Raspberry Pi Zero W – Honeywell HAFUHH0025PA3 flow sensor logger
 *
 * Wiring:
 *   VCC  -> 3V3 (Pin 1)
 *   GND  -> GND (Pin 9)
 *   SDA  -> GPIO2 / I2C bus 1 SDA (Pin 3)
 *   SCL  -> GPIO3 / I2C bus 1 SCL (Pin 5)
 *
 * The HAFUHH0025PA3 is a 4-wire (I2C) flow sensor that returns a 4-byte
 * payload on each I2C transaction.  The first two bytes contain the 14-bit
 * flow value (MSB first, 0.1 SLPM per count), and the last two bytes
 * contain the 12-bit temperature value (MSB first, 0.1 °C per count).
 *
 * Build:  gcc -O2 -Wall -Wextra -o flow_logger flow_logger.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define LOG_FILE       "flow_log.txt"
#define SAMPLE_PERIOD  1          /* seconds between samples */
#define MAX_RETRIES    3

/* HAFUHH0025PA3 – 4-byte payload, no register pointer write required */
#define HAFUHH0025_CMD_LEN 4
#define HAFUHH0025_CMD_VAL 0x00
#define HAFUHH0025_CMD_LEN 4

/* 14-bit flow resolution: 0.1 SLPM per count */
#define FLOW_SCALE 0.1f
/* 12-bit temperature resolution: 0.1 °C per count */
#define TEMP_SCALE 0.1f

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* Open the I2C bus and attempt to read the first 4-byte measurement.    */
/* Returns 0 on success, -1 on failure.                                 */
/* ------------------------------------------------------------------ */
static int init_i2c(void)
{
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return -1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, 0x50) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE): %s\n", strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return -1;
    }

    /*
     * Probe: attempt a single 4-byte read to confirm the sensor is
     * present and the I2C address is correct.
     */
    uint8_t probe[4] = {0};
    ssize_t n = read(g_i2c_fd, probe, sizeof(probe));
    if (n != (ssize_t)sizeof(probe)) {
        fprintf(stderr, "Initial probe read failed: %s\n", strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read the 4-byte measurement payload and convert to physical units.  */
/* Returns 0 on success, -1 on failure.                                 */
/* ------------------------------------------------------------------ */
static int read_flow_measurement(float *flow_slpm, float *temp_c)
{
    uint8_t buf[HAFUHH0025_CMD_LEN];
    ssize_t n = read(g_i2c_fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }

    /*
     * HAFUHH0025PA3 4-byte payload (no register pointer write):
     *   bytes 0-1  -> 14-bit flow (MSB first, 0.1 SLPM per count)
     *   bytes 2-3  -> 12-bit temperature (MSB first, 0.1 °C per count)
     */
    uint16_t flow_raw = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t temp_raw = ((uint16_t)buf[2] << 8) | buf[3];

    *flow_slpm = (float)flow_raw * FLOW_SCALE;
    *temp_c    = (float)temp_raw * TEMP_SCALE;
    return 0;
}

/* ------------------------------------------------------------------ */
static void log_data(float flow_slpm, float temp_c)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32] = {0};
    if (t)
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    else
        snprintf(ts, sizeof(ts), "<unknown-time>");

    fprintf(g_log_fp, "%s, Flow: %.2f SLPM, Temp: %.2f C\n",
            ts, flow_slpm, temp_c);
    fflush(g_log_fp);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    if (init_i2c() < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /*
     * The HAFUHH0025PA3 requires a brief warm-up after power-up.
     * The first two reads may return stale data; we log them anyway
     * and attempt re-initialization on subsequent failures.
     */
    for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
        float flow, temp;
        if (read_flow_measurement(&flow, &temp) == 0) {
            log_data(flow, temp);
            break;
        }
        fprintf(stderr, "Attempt %d/%d: initial read failed.\n",
                attempt + 1, MAX_RETRIES);
        if (attempt < MAX_RETRIES - 1)
            sleep(1);
    }

    if (g_running) {
        while (g_running) {
            float flow, temp;
            if (read_flow_measurement(&flow, &temp) == 0) {
                log_data(flow, temp);
            } else {
                fprintf(stderr, "Read failed; attempting re-init.\n");
                if (init_i2c() < 0) {
                    fprintf(stderr, "Re-init failed; exiting.\n");
                    break;
                }
            }
            sleep(SAMPLE_PERIOD);
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

