/*
 * dht11_bitbang.c — Raspberry Pi Zero W, single-wire DHT11 on GPIO4 (BCM 4, physical pin 7)
 *
 * Bit-bangs the DHT11 start signal (>= 18 ms low, then release), then samples
 * the 40 data bits (each ~50 us low + ~26-28 us high for '0', ~70 us high for '1').
 * Reads humidity integer, decimal, temperature integer, decimal, and verifies
 * the checksum.  On success writes a timestamped record to dht11_readings.txt.
 *
 * Build:  gcc -O2 -Wall -Wextra -o dht11_bitbang dht11_bitbang.c
 * Run:    ./dht11_bitbang
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#include <pigpio.h>

/* ---- Configuration ---- */
#define DHT11_GPIO          4          /* BCM 4, physical pin 7 */
#define DHT11_FILE          "dht11_readings.txt"
#define MAX_READINGS        100        /* max consecutive failures before abort */
#define READ_INTERVAL_US    2000000    /* 2 s between successful reads */
#define START_LOW_US        18000      /* >= 18 ms low to start signal */
#define RESPONSE_TIMEOUT_US 200        /* 200 us max for sensor response */
#define BIT_TIMEOUT_US      200        /* 200 us max per bit sample */
#define MAX_BITS            85         /* 40 data bits + 1 start + 1 response */

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_gpio_initialized = 0;

