/*
 * SHT31-D temperature & humidity logger for Raspberry Pi Zero W.
 *
 * Wiring:
 *   SHT31-D SDA  -> GPIO2 (BCM 2, I2C bus 1)
 *   SHT31-D SCL  -> GPIO3 (BCM 3, I2C bus 1)
 *   SHT31-D VDD  -> 3.3 V
 *   SHT31-D GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o sht31d_logger sht31d_logger.c -lm
 *
 * Run:
 *   ./sht31d_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <math.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#include <linux/i2c.h>

/* ---- SHT31-D constants -------------------------------------------------- */
#define SHT31_I2C_ADDR        0x44          /* SHT31-D default 7-bit address */
#define SHT31_MEASURE_CMD     0x2C          /* clock-stretching, high-repeatability, no clock stretching */
#define SHT31_MEASURE_DELAY_US 15000        /* 15 ms conversion time */
#define SHT31_DATA_LEN        6            /* 2 temp + 1 CRC + 2 humidity + 1 CRC */
#define SHT31_RETRY_COUNT     3
#define SHT31_RETRY_DELAY_US  10000        /* 10 ms between retries */

/* ---- Globals for signal-safe cleanup ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd   = -1;
static FILE    *g_log_file = NULL;

/* ------------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------------ */
/* CRC-8 as used by Sensirion SHT31 family: poly 0x31, init 0xFF           */
static uint8_t sht31_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------------ */
/* Write a 16-bit command to the SHT31-D (no data payload).                */
static int sht31_write_cmd(int fd, uint8_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "[ERROR] I2C write cmd 0x%02X failed: %s\n",
                cmd, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------------ */
/* Read exactly `len` bytes from the SHT31-D.                              */
static int sht31_read_data(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "[ERROR] I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "[ERROR] Short read: got %zd of %zu bytes\n", n, len);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------------ */
/* Read temperature and humidity from the SHT31-D.                          */
/* Returns 0 on success, -1 on persistent failure.                          */
static int sht31_read(int fd, float *temperature, float *humidity)
{
    uint8_t data[SHT31_DATA_LEN];

    for (int attempt = 0; attempt < SHT31_RETRY_COUNT; attempt++) {
        if (sht31_write_cmd(fd, SHT31_MEASURE_CMD) != 0) {
            usleep(SHT31_RETRY_DELAY_US);
            continue;
        }

        usleep(SHT31_MEASURE_DELAY_US);

        if (sht31_read_data(fd, data, sizeof(data)) != 0) {
            usleep(SHT31_RETRY_DELAY_US);
            continue;
        }

        /* Validate CRC for temperature (bytes 0–1, CRC byte 2) */
        if (sht31_crc8(&data[0], 2) != data[2]) {
            fprintf(stderr, "[WARN] Temperature CRC mismatch (attempt %d)\n",
                    attempt + 1);
            usleep(SHT31_RETRY_DELAY_US);
            continue;
        }

        /* Validate CRC for humidity (bytes 3–4, CRC byte 5) */
        if (sht31_crc8(&data[3], 2) != data[5]) {
            fprintf(stderr, "[WARN] Humidity CRC mismatch (attempt %d)\n",
                    attempt + 1);
            usleep(SHT31_RETRY_DELAY_US);
            continue;
        }

        uint16_t t_raw = (uint16_t)((data[0] << 8) | data[1]);
        uint16_t h_raw = (uint16_t)((data[3] << 8) | data[4]);

        *temperature = -45.0f + 175.0f * (float)t_raw / 65535.0f;
        *humidity    = 100.0f * (float)h_raw / 65535.0f;

        /* Clamp humidity to physical range */
        if (*humidity < 0.0f)   *humidity = 0.0f;
        if (*humidity > 100.0f) *humidity = 100.0f;

        return 0;
    }

    fprintf(stderr, "[ERROR] SHT31-D read failed after %d attempts\n",
            SHT31_RETRY_COUNT);
    return -1;
}

/* ------------------------------------------------------------------------ */
static void log_data(FILE *fp, float temperature, float humidity)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed: %s\n", strerror(errno));
        return;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.2f\n", ts, temperature, humidity);
    fflush(fp);
}

/* ------------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
}

/* ------------------------------------------------------------------------ */
int main(void)
{
    /* ---- Signal handling ----------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[ERROR] sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[ERROR] sigaction(SIGTERM): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus --------------------------------------------------- */
    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "[ERROR] open(/dev/i2c-1): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SHT31_I2C_ADDR) < 0) {
        fprintf(stderr, "[ERROR] ioctl(I2C_SLAVE, 0x%02X): %s\n",
                SHT31_I2C_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open log file -------------------------------------------------- */
    g_log_file = fopen("sht31d_data.log", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[ERROR] fopen(sht31d_data.log): %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(stderr, "SHT31-D logger started. Logging to sht31d_data.log\n");
    fprintf(stderr, "Press Ctrl+C to stop.\n");

    /* ---- Main loop ------------------------------------------------------ */
    while (g_running) {
        float temperature, humidity;

        if (sht31_read(g_i2c_fd, &temperature, &humidity) == 0) {
            log_data(g_log_file, temperature, humidity);
            printf("%s  T=%.2f C  H=%.2f %%\n",
                   "reading", temperature, humidity);
        } else {
            fprintf(stderr, "[ERROR] Skipping this sample due to sensor failure\n");
        }

        /* Sleep 5 s, but wake early on signal */
        for (int i = 0; i < 5 && g_running; i++)
            sleep(1);
    }

    fprintf(stderr, "\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

