/*
 * Raspberry Pi Zero W – ADPD105 correlated color temperature logger
 *
 * Reads two ADPD105 photometric front-end sensors on the I2C bus,
 * computes correlated color temperature (CCT), and logs the average
 * CCT once per second to cct_log.csv.
 *
 * Build:  gcc -O2 -Wall -Wextra -o cct_logger cct_logger.c
 * Run:    ./cct_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADPD105_ADDR   0x68
#define NUM_SENSORS     2
#define LOG_FILE        "cct_log.csv"
#define SAMPLE_PERIOD_S 1

/* ADPD105 register addresses (16-bit, big-endian on the bus) */
#define ADPD105_REG_CHIP_ID      0x00
#define ADPD105_REG_DEVICE_ID    0x01
#define ADPD105_REG_SENSOR_ID    0x02
#define ADPD105_REG_CONFIG       0x03
#define ADPD105_REG_DATA_START   0x04
#define ADPD105_REG_DATA_LEN     0x05
#define ADPD105_REG_DATA0        0x06
#define ADPD105_REG_DATA1        0x08
#define ADPD105_REG_DATA2        0x0A
#define ADPD105_REG_DATA3        0x0C

#define ADPD105_CHIP_ID_EXPECTED 0x68
#define ADPD105_DEVICE_ID_EXPECTED 0x01

/* Config register bits */
#define ADPD105_CFG_CH_LIST       0x80
#define ADPD105_CFG_ADC_GAIN      0x20
#define ADPD105_CFG_ADC_MODE      0x10
#define ADPD105_CFG_ADC_DR        0x08
#define ADPD105_CFG_ADC_INT_EN    0x04
#define ADPD105_CFG_ADC_INT_MODE  0x02
#define ADPD105_CFG_ADC_INT_POL   0x01

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a 16-bit register address, then write the data byte. */
static int adpd105_write_reg(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[3];
    buf[0] = (uint8_t)(reg >> 8);
    buf[1] = (uint8_t)(reg & 0xFF);
    buf[2] = value;

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a 16-bit register address, then read `len` bytes. */
static int adpd105_read_regs(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    uint8_t addr[2];
    addr[0] = (uint8_t)(reg >> 8);
    addr[1] = (uint8_t)(reg & 0xFF);

    if (write(fd, addr, sizeof(addr)) != (ssize_t)sizeof(addr)) {
        fprintf(stderr, "I2C write (addr) to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int adpd105_init(int fd)
{
    uint8_t chip_id = 0, device_id = 0;

    if (adpd105_read_regs(fd, ADPD105_REG_CHIP_ID, &chip_id, 1) < 0)
        return -1;
    if (chip_id != ADPD105_CHIP_ID_EXPECTED) {
        fprintf(stderr, "Unexpected chip ID 0x%02X (expected 0x%02X)\n",
                chip_id, ADPD105_CHIP_ID_EXPECTED);
        return -1;
    }

    if (adpd105_read_regs(fd, ADPD105_REG_DEVICE_ID, &device_id, 1) < 0)
        return -1;
    if (device_id != ADPD105_DEVICE_ID_EXPECTED) {
        fprintf(stderr, "Unexpected device ID 0x%02X (expected 0x%02X)\n",
                device_id, ADPD105_DEVICE_ID_EXPECTED);
        return -1;
    }

    /* Configure: list both channels, gain 1x, mode continuous, DR 100 MSPS,
     * interrupt enabled, mode rising, polarity active-low. */
    uint8_t cfg = ADPD105_CFG_CH_LIST | ADPD105_CFG_ADC_GAIN | ADPD105_CFG_ADC_MODE |
                  ADPD105_CFG_ADC_DR | ADPD105_CFG_ADC_INT_EN |
                  ADPD105_CFG_ADC_INT_MODE | ADPD105_CFG_ADC_INT_POL;

    if (adpd105_write_reg(fd, ADPD105_REG_CONFIG, cfg) < 0)
        return -1;

    /* Allow time for the first conversion to complete. */
    usleep(100000);
    return 0;
}

static int adpd105_read_channel(int fd, uint8_t channel, uint16_t *value)
{
    uint8_t reg = ADPD105_REG_DATA0 + (channel * 2);
    uint8_t data[2];

    if (adpd105_read_regs(fd, reg, data, 2) < 0)
        return -1;

    *value = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

static float calculate_cct(uint16_t r, uint16_t g)
{
    float r_f = (float)r;
    float g_f = (float)g;

    if (r_f == 0.0f || g_f == 0.0f)
        return 0.0f;

    float ratio = r_f / g_f;
    float cct = 449.0f * (1.0f - 1.0f / ratio) - 1000.0f;
    if (cct < 0.0f) cct = 0.0f;
    if (cct > 65000.0f) cct = 65000.0f;
    return cct;
}

static int log_cct(float cct)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.2f\n", ts, cct) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, ADPD105_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n",
                ADPD105_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (adpd105_init(fd) < 0) {
        fprintf(stderr, "ADPD105 initialization failed\n");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("ADPD105 initialized. Logging CCT every %d s. Press Ctrl+C to stop.\n",
           SAMPLE_PERIOD_S);

    while (g_running) {
        uint16_t r1 = 0, g1 = 0, r2 = 0, g2 = 0;
        int ok1 = 0, ok2 = 0;

        for (int i = 0; i < NUM_SENSORS; i++) {
            if (i == 0) {
                if (adpd105_read_channel(fd, 0, &r1) == 0 &&
                    adpd105_read_channel(fd, 1, &g1) == 0) {
                    ok1 = 1;
                }
            } else {
                if (adpd105_read_channel(fd, 2, &r2) == 0 &&
                    adpd105_read_channel(fd, 3, &g2) == 0) {
                    ok2 = 1;
                }
            }
            usleep(10000);
        }

        if (ok1 && ok2) {
            float cct1 = calculate_cct(r1, g1);
            float cct2 = calculate_cct(r2, g2);
            float avg = (cct1 + cct2) / 2.0f;
            if (log_cct(avg) < 0)
                fprintf(stderr, "Logging failed for this cycle\n");
            else
                printf("CCT: %.2f\n", avg);
        } else {
            fprintf(stderr, "Sensor read error – skipping cycle\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly. */
        for (int i = 0; i < SAMPLE_PERIOD_S * 10 && g_running; i++)
            usleep(100000);
    }

    printf("\nShutting down cleanly.\n");
    close(fd);
    return EXIT_SUCCESS;
}

