    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, ADPD105_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n",
                ADPD105_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (adpd105_init(fd) < 0) {
        fprintf(stderr, "ADPD105 initialization failed\n");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("ADPD105 initialized. Logging CCT every %d s. Press Ctrl+C to stop.\n",
           SAMPLE_PERIOD_S);

    while (g_running) {
        uint16_t r1 = 0, g1 = 0, r2 = 0, g2 = 0;
        int ok1 = 0, ok2 = 0;

        for (int i = 0; i < NUM_SENSORS; i++) {
            if (i == 0) {
                if (adpd105_read_channel(fd, 0, &r1) == 0 &&
                    adpd105_read_channel(fd, 1, &g1) == 0) {
                    ok1 = 1;
                }
            } else {
                if (adpd105_read_channel(fd, 2, &r2) == 0 &&
                    adpd105_read_channel(fd, 3, &g2) == 0) {
                    ok2 = 1;
                }
            }
            usleep(10000);
        }

        if (ok1 && ok2) {
            float cct1 = calculate_cct(r1, g1);
            float cct2 = calculate_cct(r2, g2);
            float avg = (cct1 + cct2) / 2.0f;
            if (log_cct(avg) < 0)
                fprintf(stderr, "Logging failed for this cycle\n");
            else
                printf("CCT: %.2f\n", avg);
        } else {
            fprintf(stderr, "Sensor read error – skipping cycle\n");
        }

        /* Sleep in 100 ms increments so signals are caught promptly. */
        for (int i = 0; i < SAMPLE_PERIOD_S * 10 && g_running; i++)
            usleep(100000);
    }

    printf("\nShutting down cleanly.\n");
    close(fd);
    return EXIT_SUCCESS;
}

