/*
 * MLX90824 Absolute Pressure Sensor Reader for Raspberry Pi 4 Model B
 *
 * Reads absolute pressure and temperature from an MLX90824 over I2C and logs
 * the readings with timestamps to pressure_log.txt every 2 seconds.
 *
 * Build: gcc -O2 -Wall -o mlx90824_reader mlx90824_reader.c -lm
 * Run:   sudo ./mlx90824_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <math.h>
#include <pigpio.h>

/* ---- Configuration ---- */
#define I2C_BUS              1
#define I2C_ADDR             0x68
#define LOG_FILE             "pressure_log.txt"
#define READ_INTERVAL_SEC    2
#define MAX_RETRIES          3

/* ---- MLX90824 Register Map (example) ---- */
#define REG_PRESSURE_MSB     0x00
#define REG_PRESSURE_LSB     0x01
#define REG_TEMP_MSB         0x02
#define REG_TEMP_LSB         0x03
#define REG_CONFIG           0x0F

/* ---- Globals for cleanup ---- */
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;
static volatile sig_atomic_t g_running = 1;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Timestamp helper ---- */
static void get_timestamp(char *buf, size_t len)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) != NULL)
        strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tm);
    else
        snprintf(buf, len, "UNKNOWN");
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ---- Write a single byte to a register ---- */
static int write_reg(uint8_t reg, uint8_t value)
{
    char buf[2] = { (char)reg, (char)value };
    if (i2cWriteDevice(g_i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(reg=0x%02X, val=0x%02X) failed: %s\n",
                reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- Read a 16-bit big-endian register pair ---- */
static int read_reg16(uint8_t reg_msb, uint16_t *out)
{
    char reg_buf[1] = { (char)reg_msb };
    char data[2]     = {0};

    if (i2cWriteDevice(g_i2c_handle, reg_buf, 1) != 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(reg=0x%02X) failed: %s\n",
                reg_msb, strerror(errno));
        return -1;
    }
    if (i2cReadDevice(g_i2c_handle, data, 2) != 2) {
        fprintf(stderr, "[ERROR] i2cReadDevice(reg=0x%02X) failed: %s\n",
                reg_msb, strerror(errno));
        return -1;
    }
    *out = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

/* ---- Read pressure and temperature ---- */
static int read_sensor_data(float *pressure, float *temperature)
{
    uint16_t raw_pressure, raw_temperature;

    if (read_reg16(REG_PRESSURE_MSB, &raw_pressure) != 0)
        return -1;
    if (read_reg16(REG_TEMP_MSB, &raw_temperature) != 0)
        return -1;

    /* Convert raw values to physical units (example calibration) */
    *pressure    = (float)raw_pressure / 100.0f;   /* Pa  */
    *temperature = (float)raw_temperature / 100.0f; /* °C  */

    return 0;
}

/* ---- Log a reading ---- */
static void log_data(float pressure, float temperature)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));

    fprintf(g_log_file, "%s, Pressure: %.2f Pa, Temperature: %.2f C\n",
            ts, pressure, temperature);
    fflush(g_log_file);
}

/* ---- Log an error ---- */
static void log_error(const char *msg)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));

    fprintf(g_log_file, "%s, ERROR: %s\n", ts, msg);
    fflush(g_log_file);
}

/* ---- Main ---- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_file) == 0)
        fprintf(g_log_file, "Timestamp,Pressure_Pa,Temperature_C\n");

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MLX90824 reader started. Logging to '%s' every %d s. "
           "Press Ctrl+C to stop.\n", LOG_FILE, READ_INTERVAL_SEC);

    /* Configure sensor (example: set gain/offset) */
    if (write_reg(REG_CONFIG, 0x01) != 0) {
        fprintf(stderr, "[WARN] Failed to configure sensor; continuing.\n");
    }

    /* Main loop */
    while (g_running) {
        float pressure = 0.0f, temperature = 0.0f;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (read_sensor_data(&pressure, &temperature) == 0) {
                ok = 1;
                break;
            }
            fprintf(stderr, "[WARN] Read attempt %d/%d failed; retrying...\n",
                    attempt + 1, MAX_RETRIES);
            sleep(1);
        }

        if (ok) {
            log_data(pressure, temperature);
        } else {
            log_error("Failed to read sensor data after retries");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < READ_INTERVAL_SEC * 10 && g_running; i++)
            gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

