        g_i2c_fd = -1;
        return -1;
    }

    return 0;
}

static int read_temperature(float *temperature)
{
    uint8_t reg = LM75B_REG_TEMP;
    uint8_t data[2];

    if (write(g_i2c_fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing temperature register: %s\n",
                strerror(errno));
        return -1;
    }

    if (read(g_i2c_fd, data, 2) != 2) {
        fprintf(stderr, "Error reading temperature data: %s\n",
                strerror(errno));
        return -1;
    }

    int16_t raw = (int16_t)((data[0] << 8) | data[1]);
    *temperature = (float)raw / 10.0f;
    return 0;
}

static void add_to_buffer(CircularBuffer *cb, float temperature)
{
    cb->buffer[cb->head] = temperature;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

static float calculate_average(const CircularBuffer *cb)
{
    if (cb->count == 0) {
        return 0.0f;
    }
    float sum = 0.0f;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / (float)cb->count;
}

static int control_fan(float average_temperature)
{
    static bool fan_on = false;

    if (average_temperature > TEMP_THRESHOLD_HIGH && !fan_on) {
        if (gpioWrite(FAN_GPIO, 1) == 0) {
            fan_on = true;
            printf("Fan ON  (avg=%.2f°C)\n", average_temperature);
        } else {
            fprintf(stderr, "Error turning fan ON: %s\n", strerror(errno));
        }
    } else if (average_temperature < TEMP_THRESHOLD_LOW && fan_on) {
        if (gpioWrite(FAN_GPIO, 0) == 0) {
            fan_on = false;
            printf("Fan OFF (avg=%.2f°C)\n", average_temperature);
        } else {
            fprintf(stderr, "Error turning fan OFF: %s\n", strerror(errno));
        }
    }
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n",
                strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering SIGTERM handler: %s\n",
                strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output: %s\n",
                FAN_GPIO, strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (gpioWrite(FAN_GPIO, 0) != 0) {
        fprintf(stderr, "Error initializing fan GPIO %d to LOW: %s\n",
                FAN_GPIO, strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (init_i2c() < 0) {
        gpioTerminate();
        return 1;
    }

    CircularBuffer temperature_buffer = {0};
    temperature_buffer.head = 0;
    temperature_buffer.count = 0;

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float temperature;

        if (read_temperature(&temperature) == 0) {
            add_to_buffer(&temperature_buffer, temperature);
            float average_temperature = calculate_average(&temperature_buffer);
            control_fan(average_temperature);
            printf("Temperature: %.2f°C, Average: %.2f°C\n",
                   temperature, average_temperature);
        } else {
            fprintf(stderr, "Failed to read temperature, retrying next cycle.\n");
        }

        sleep(SAMPLE_INTERVAL_S);
    }

    printf("\nShutting down...\n");
    gpioWrite(FAN_GPIO, 0);
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
    return 0;
}

