/*
 * Raspberry Pi 3 Model B+ — STTS2004 temperature monitor with hysteresis LED
 *
 * Wiring:
 *   STTS2004 SDA  -> GPIO2  (I2C bus 1)
 *   STTS2004 SCL  -> GPIO3  (I2C bus 1)
 *   STTS2004 VDD  -> 3.3 V
 *   STTS2004 GND  -> GND
 *   LED anode     -> GPIO17 (BCM) via 330 Ω resistor
 *   LED cathode   -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o temp_monitor temp_monitor.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#include <pigpio.h>

#define I2C_BUS        "/dev/i2c-1"
#define STTS2004_ADDR  0x48
#define LED_PIN        17
#define TEMP_HIGH      28.0f
#define TEMP_LOW       27.0f
#define POLL_INTERVAL  1

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/*
 * Read the 16-bit temperature register (0x00) from the STTS2004.
 * Returns 0 on success and stores the temperature in *out_celsius.
 * Returns -1 on I2C error.
 */
static int read_temperature(int fd, float *out_celsius)
{
    uint8_t reg = 0x00;
    uint8_t buf[2];

    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select) failed: %s\n", strerror(errno));
        return -1;
    }

    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read (temperature) failed: %s\n", strerror(errno));
        return -1;
    }

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *out_celsius = (float)raw / 256.0f;
    return 0;
}

static int set_led(int pin, int on)
{
    if (gpioWrite(pin, on) != 0) {
        fprintf(stderr, "gpioWrite(%d, %d) failed: %s\n", pin, on, strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    if (install_signal_handlers() != 0) {
        goto cleanup;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        goto cleanup;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        goto cleanup;
    }

    if (ioctl(fd, I2C_SLAVE, STTS2004_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                STTS2004_ADDR, strerror(errno));
        goto cleanup;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed\n", LED_PIN);
        goto cleanup;
    }

    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "gpioWrite(%d, 0) initial state failed\n", LED_PIN);
        goto cleanup;
    }

    while (g_running) {
        float temperature;

        if (read_temperature(fd, &temperature) != 0) {
            fprintf(stderr, "Temperature read failed; exiting.\n");
            goto cleanup;
        }

        printf("Temperature: %.2f °C\n", temperature);

        if (temperature > TEMP_HIGH) {
            if (set_led(LED_PIN, 1) != 0) {
                goto cleanup;
            }
        } else if (temperature < TEMP_LOW) {
            if (set_led(LED_PIN, 0) != 0) {
                goto cleanup;
            }
        }

        sleep(POLL_INTERVAL);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    return rc;
}

