/*
 * SDP800-500Pa differential pressure & temperature logger for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   SDP800 SDA  -> GPIO2  (pin 3, I2C bus 1)
 *   SDP800 SCL  -> GPIO3  (pin 5, I2C bus 1)
 *   SDP800 VDD  -> 3.3 V
 *   SDP800 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o sdp800_logger sdp800_logger.c
 */

#define _POSIX_C_SOURCE 200809L

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SDP800_ADDR    0x60
#define LOG_FILE       "flow_data.txt"
#define SAMPLE_PERIOD  1000000   /* microseconds (1 s) */
#define MEAS_DELAY_US  45000     /* 45 ms conversion time */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handler(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    return sigaction(SIGINT, &sa, NULL);
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF)                        */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_byte(int fd, uint8_t byte)
{
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "i2c_write_byte(0x%02X): write failed: %s\n",
                byte, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "i2c_read_bytes: read failed (got %zd of %zu): %s\n",
                n, len, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* SDP800 measurement                                                  */
/* ------------------------------------------------------------------ */
static int sdp800_start_measurement(int fd)
{
    /* Trigger a measurement by writing a zero byte to the device. */
    if (i2c_write_byte(fd, 0x00) < 0)
        return -1;
    usleep(MEAS_DELAY_US);
    return 0;
}

static int sdp800_read_measurement(int fd, float *pressure, float *temperature)
{
    uint8_t buf[9];

    if (i2c_read_bytes(fd, buf, sizeof(buf)) < 0)
        return -1;

    /* Validate CRCs for the two 16-bit data words. */
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "CRC error on pressure data\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "CRC error on temperature data\n");
        return -1;
    }

    int16_t raw_pressure = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_temp     = (int16_t)((buf[3] << 8) | buf[4]);

    *pressure    = (float)raw_pressure / 60.0f;   /* Pa   */
    *temperature = (float)raw_temp / 200.0f;      /* deg C */

    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_data(float pressure, float temperature)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, %.2f Pa, %.2f deg C\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            pressure, temperature);

    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose(%s): %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(int fd)
{
    if (fd >= 0) {
        close(fd);
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    if (install_signal_handler() != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SDP800_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                SDP800_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Probe: a zero-byte write confirms the sensor is present. */
    if (i2c_write_byte(fd, 0x00) < 0) {
        fprintf(stderr, "Sensor not responding at 0x%02X on %s\n",
                SDP800_ADDR, I2C_BUS);
        goto cleanup;
    }

    printf("SDP800 logger started. Logging to %s. Press Ctrl+C to stop.\n",
           LOG_FILE);

    while (g_running) {
        if (sdp800_start_measurement(fd) < 0) {
            fprintf(stderr, "Measurement start failed; retrying in 1 s.\n");
            usleep(SAMPLE_PERIOD);
            continue;
        }

        float pressure, temperature;
        if (sdp800_read_measurement(fd, &pressure, &temperature) < 0) {
            fprintf(stderr, "Measurement read failed; retrying in 1 s.\n");
            usleep(SAMPLE_PERIOD);
            continue;
        }

        if (log_data(pressure, temperature) < 0) {
            fprintf(stderr, "Logging failed; continuing.\n");
        }

        printf("Pressure: %.2f Pa, Temperature: %.2f deg C\n",
               pressure, temperature);

        usleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down gracefully.\n");
    rc = EXIT_SUCCESS;

cleanup:
    cleanup(fd);
    return rc;
}

