#define CMD_READ_TEMP_FROM_RH  0xE0

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    struct tm tmv;
    if (localtime_r(&now, &tmv) != NULL)
        strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tmv);
    else
        snprintf(buf, len, "1970-01-01 00:00:00");
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_error(const char *msg)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));

    if (g_log_file) {
        fprintf(g_log_file, "%s,ERROR,%s\n", ts, msg);
        fflush(g_log_file);
    }
    fprintf(stderr, "%s,ERROR,%s\n", ts, msg);
}

static void log_data(float temp, float hum)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));

    if (g_log_file) {
        fprintf(g_log_file, "%s,%.2f,%.2f\n", ts, temp, hum);
        fflush(g_log_file);
    }
    printf("%s,%.2f,%.2f\n", ts, temp, hum);
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int handle, uint8_t cmd)
{
    char buf[1] = { (char)cmd };
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cWriteDevice(handle, buf, 1);
        if (rc == 0)
            return 0;
        gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

static int i2c_read_block(int handle, uint8_t *buf, int len)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cReadDevice(handle, (char *)buf, len);
        if (rc == len)
            return 0;
        gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Sensor initialization                                               */
/* ------------------------------------------------------------------ */
static int init_sensor(int handle)
{
    /* Verify sensor presence by reading the electronic ID register */
    uint8_t id_buf[8];
    if (i2c_read_block(handle, id_buf, sizeof(id_buf)) != 0) {
        log_error("Failed to read Si7021 electronic ID");
        return -1;
    }

    /* Check the first byte of the ID (0x00) should be 0x15 for Si7021 */
    if (id_buf[0] != 0x15) {
        char msg[64];
        snprintf(msg, sizeof(msg),
                 "Unexpected Si7021 ID 0x%02X (expected 0x15)", id_buf[0]);
        log_error(msg);
        return -1;
    }

    /* Optional: read firmware revision for diagnostic purposes */
    uint8_t rev_buf[2];
    if (i2c_read_block(handle, rev_buf, sizeof(rev_buf)) != 0) {
        log_error("Failed to read Si7021 firmware revision");
        return -1;
    }

    printf("Si7021 detected (ID=0x%02X, Rev=0x%02X). Sampling every %d s.\n",
           id_buf[0], rev_buf[0], SAMPLE_PERIOD);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read temperature / humidity                                          */
/* ------------------------------------------------------------------ */
static int read_temperature(int handle, float *temp_c)
{
    /* Issue "Measure Temperature, No Master Hold" command */
    if (i2c_write_cmd(handle, CMD_MEASURE_TEMP_NOHOLD_CMD) != 0) {
        log_error("Failed to issue temperature measurement command");
        return -1;
    }

    /* Wait for conversion (max ~12 ms for 14-bit temp) */
    gpioDelay(15000);

    /* Read 2 bytes: MSB at 0x2C, LSB at 0x2D */
    uint8_t data[2];
    if (i2c_read_block(handle, data, 2) != 0) {
        log_error("Failed to read temperature data");
        return -1;
    }

    int16_t raw = (int16_t)((data[0] << 8) | data[1]);
    *temp_c = ((float)raw / 65536.0f) * 165.0f - 40.0f;
    return 0;
}

static int read_humidity(int handle, float *hum_pct)
{
    /* Issue "Measure Relative Humidity, No Master Hold" command */
    if (i2c_write_cmd(handle, CMD_MEASURE_RH_NOHOLD_CMD) != 0) {
        log_error("Failed to issue humidity measurement command");
        return -1;
    }

    /* Wait for conversion (max ~12 ms for 12-bit RH) */
    gpioDelay(15000);

    /* Read 2 bytes: MSB at 0x2A, LSB at 0x2B */
    uint8_t data[2];
    if (i2c_read_block(handle, data, 2) != 0) {
        log_error("Failed to read humidity data");
        return -1;
    }

    int16_t raw = (int16_t)((data[0] << 8) | data[1]);
    *hum_pct = ((float)raw / 65536.0f) * 100.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, 0x45, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x45: %d\n",
                I2C_BUS, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (init_sensor(g_i2c_handle) != 0) {
        fprintf(stderr, "Si7021 initialization failed; exiting.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        fprintf(stderr, "Failed to open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Starting environmental monitoring. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        float temp = 0.0f, hum = 0.0f;
        int ok = 1;

        if (read_temperature(g_i2c_handle, &temp) != 0) {
            ok = 0;
        } else if (read_humidity(g_i2c_handle, &hum) != 0) {
            ok = 0;
        } else {
            log_data(temp, hum);
        }

        if (ok) {
            sleep(SAMPLE_PERIOD);
        } else {
            /* On error, wait briefly before retrying */
            sleep(5);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

