#include <unistd.h>
#include <pigpio.h>

#define HDC1080_ADDR 0x38
#define I2C_BUS 1
#define LOG_FILE "enviro_log.txt"
#define SAMPLE_INTERVAL_SEC 5
#define CONVERSION_DELAY_US 20000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int hdc1080_read_register(int handle, uint8_t reg, uint8_t *value) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int hdc1080_write_register(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, rc);
        return -1;
    }
    return 0;
}

static int hdc1080_init(int handle) {
    uint8_t part_id;
    if (hdc1080_read_register(handle, 0x00, &part_id) != 0) {
        fprintf(stderr, "Failed to read Part ID from HDC1080\n");
        return -1;
    }
    if (part_id != 0x32) {
        fprintf(stderr, "Unexpected Part ID: 0x%02X (expected 0x32)\n", part_id);
        return -1;
    }
    if (hdc1080_write_register(handle, 0x01, 0x00) != 0) {
        fprintf(stderr, "Failed to reset HDC1080\n");
        return -1;
    }
    gpioDelay(10000);
    return 0;
}

static int hdc1080_read_temperature(int handle, float *temperature) {
    uint8_t data[3];
    if (hdc1080_write_register(handle, 0x02, 0x00) != 0) {
        fprintf(stderr, "Failed to trigger temperature measurement\n");
        return -1;
    }
    gpioDelay(CONVERSION_DELAY_US);
    if (hdc1080_read_register(handle, 0x04, &data[0]) != 0) return -1;
    if (hdc1080_read_register(handle, 0x05, &data[1]) != 0) return -1;
    if (hdc1080_read_register(handle, 0x06, &data[2]) != 0) return -1;
    uint16_t raw = ((uint16_t)data[0] << 8) | data[1];
    *temperature = (float)raw / 16.0f;
    return 0;
}

static int hdc1080_read_humidity(int handle, float *humidity) {
    uint8_t data[3];
    if (hdc1080_write_register(handle, 0x02, 0x00) != 0) {
        fprintf(stderr, "Failed to trigger humidity measurement\n");
        return -1;
    }
    gpioDelay(CONVERSION_DELAY_US);
    if (hdc1080_read_register(handle, 0x04, &data[0]) != 0) return -1;
    if (hdc1080_read_register(handle, 0x05, &data[1]) != 0) return -1;
    if (hdc1080_read_register(handle, 0x06, &data[2]) != 0) return -1;
    uint16_t raw = ((uint16_t)data[0] << 8) | data[1];
    *humidity = (float)raw / 16.0f;
    return 0;
}

static int log_data(const char *filename, float temperature, float humidity) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to set up signal handlers");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, HDC1080_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (hdc1080_init(i2c_handle) != 0) {
        fprintf(stderr, "HDC1080 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (running) {
        float temperature, humidity;
        if (hdc1080_read_temperature(i2c_handle, &temperature) != 0) {
            fprintf(stderr, "Error reading temperature, skipping log entry\n");
        } else if (hdc1080_read_humidity(i2c_handle, &humidity) != 0) {
            fprintf(stderr, "Error reading humidity, skipping log entry\n");
        } else {
            if (log_data(LOG_FILE, temperature, humidity) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

