/*
 * HVAC Pressure Monitor — Raspberry Pi Zero W
 * Sensor : Sensirion SDP810-500Pa (differential pressure)
 * Bus    : I2C bus 1 (GPIO2 = SDA, GPIO3 = SCL)
 * Log    : hvac_pressure_log.txt  (CSV: timestamp,pressure_Pa,temperature_C,notes)
 *
 * Build  : gcc -O2 -Wall -Wextra -o hvac_monitor hvac_monitor.c -lpigpio -lrt
 * Run    : sudo ./hvac_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x60
#define LOG_FILE       "hvac_pressure_log.txt"
#define SAMPLE_PERIOD  1          /* seconds between samples */
#define MEAS_DELAY_US  50000      /* 50 ms conversion time */
#define MAX_RETRIES    3

/* SDP810 9-byte result (big-endian, MSB first) */
#define SDP810_RESULT_LEN 9
#define SDP810_RESULT[0]  0x00
#define SDP810_RESULT[1]  0x00
#define SDP810_RESULT[2]  0x00   /* pressure raw (Pa) */
#define SDP810_RESULT[3]  0x00
#define SDP810_RESULT[4]  0x00   /* temperature raw (°C) */
#define SDP810_RESULT[5]  0x00
#define SDP810_RESULT[6]  0x00   /* scale factor */
#define SDP810_RESULT[7]  0x00
#define SDP810_RESULT[8]  0x00

/* CRC-8 parameters used by Sensirion */
#define CRC8_POLY  0x31
#define CRC8_INIT  0xFF

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF)                        */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ CRC8_POLY);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(uint8_t cmd)
{
    char buf[1] = { (char)cmd };
    if (i2cWriteDevice(g_i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(0x%02X) failed\n", cmd);
        return -1;
    }
    return 0;
}

static int i2c_read_block(uint8_t *buf, size_t len)
{
    if (i2cReadDevice(g_i2c_handle, (char *)buf, len) != (int)len) {
        fprintf(stderr, "[ERROR] i2cReadDevice(%zu bytes) failed\n", len);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor read                                                         */
/* ------------------------------------------------------------------ */
static int read_sdp810(float *pressure, float *temperature)
{
    uint8_t raw[SDP810_RESULT_LEN];

    /* Trigger a measurement */
    if (i2c_write_cmd(0x36) != 0)
        return -1;

    /* Wait for conversion to complete */
    gpioDelay(MEAS_DELAY_US);

    /* Read 9 bytes: pressure(2)+crc, temperature(2)+crc, scale(3)+crc */
    if (i2c_read_block(raw, SDP810_RESULT_LEN) != 0)
        return -1;

    /* Validate CRCs */
    if (crc8(&raw[0], 2) != raw[2]) {
        fprintf(stderr, "[ERROR] pressure CRC mismatch\n");
        return -1;
    }
    if (crc8(&raw[3], 2) != raw[5]) {
        fprintf(stderr, "[ERROR] temperature CRC mismatch\n");
        return -1;
    }
    if (crc8(&raw[6], 3) != raw[8]) {
        fprintf(stderr, "[ERROR] scale-factor CRC mismatch\n");
        return -1;
    }

    /* Convert raw values */
    int16_t p_raw = (int16_t)((raw[0] << 8) | raw[1]);
    int16_t t_raw = (int16_t)((raw[3] << 8) | raw[4]);
    uint16_t s_raw = (uint16_t)((raw[6] << 8) | raw[7]);

    *pressure    = (float)p_raw / 60.0f;   /* Pa  */
    *temperature = (float)t_raw / 200.0f;  /* °C */

    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_sample(float pressure, float temperature, const char *notes)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    fprintf(g_log_file, "%s,%.2f,%.2f,%s\n", ts, pressure, temperature, notes);
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] gpioInitialise() failed\n");
        return EXIT_FAILURE;
    }

    /* --- open I2C --------------------------------------------------- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- open log file ---------------------------------------------- */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        fprintf(stderr, "[FATAL] fopen(%s) failed\n", LOG_FILE);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_file) == 0)
        fprintf(g_log_file, "timestamp,pressure_Pa,temperature_C,notes\n");

    /* --- signal handling -------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGINT) failed\n");
    }

    printf("HVAC pressure monitor started.  Press Ctrl+C to stop.\n");

    /* --- main loop -------------------------------------------------- */
    while (g_running) {
        float pressure = 0.0f, temperature = 0.0f;
        char   notes[128];

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (read_sdp810(&pressure, &temperature) == 0) {
                snprintf(notes, sizeof(notes), "OK");
                log_sample(pressure, temperature, notes);
                break;
            }
            snprintf(notes, sizeof(notes), "read_error");
            log_sample(0.0f, 0.0f, notes);
            gpioDelay(100000);  /* 100 ms backoff */
        }

        if (!g_running)
            break;

        /* Sleep SAMPLE_PERIOD seconds, but wake early on signal */
        for (int s = 0; s < SAMPLE_PERIOD && g_running; s++)
            sleep(1);
    }

    /* --- cleanup ---------------------------------------------------- */
    cleanup();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

