/*
 * Raspberry Pi 4 Model B — TDK ICP-10125 barometric pressure sensor monitor
 *
 * Wiring:
 *   ICP-10125 SDA  -> GPIO2  (I2C bus 1, pin 3)
 *   ICP-10125 SCL  -> GPIO3  (I2C bus 1, pin 5)
 *   ICP-10125 VDD  -> 3.3 V
 *   ICP-10125 GND  -> GND
 *   LED anode     -> GPIO17 (BCM 17, pin 11) via 330 Ω resistor
 *   LED cathode   -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o icp10125_monitor icp10125_monitor.c -lpigpio -lrt
 *   (pigpio must be installed; run as root or with appropriate permissions.)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS            "/dev/i2c-1"
#define ICP10125_ADDR      0x68
#define GPIO_LED           17

#define PRESSURE_THRESHOLD 95000.0f   /* Pa */
#define POLL_INTERVAL_US   1000000   /* 1 s  */
#define TRIGGER_DELAY_US   20000     /* 20 ms */
#define LED_ON_US          500000    /* 500 ms */
#define LED_OFF_US         500000    /* 500 ms */

/* ICP-10125 6-byte read: [P_msb P_lsb T_msb T_lsb CRC_lo CRC_hi] */
#define ICP10125_READ_LEN 6

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd = -1;
static bool     g_pigpio_ready = false;

/* --------------------------- Forward declarations ------------------------- */
static int  i2c_open(void);
static int  i2c_read_block(int fd, uint8_t *buf, size_t len);
static int  i2c_close(void);
static int  gpio_init(void);
static int  gpio_set_led(int pin, int state);
static int  gpio_set_frequency(int pin, int freq);
static int  gpio_read(int pin);
static int  gpio_write(int pin, int level);
static int  gpio_toggle(int pin);
static int  gpio_set_mode(int pin, int mode);
static int  gpio_set_mode_input(int pin);
static int  gpio_set_mode_output(int pin);
static int  gpio_set_pwm(int pin, int duty);
static int  gpio_set_pwm_frequency(int pin, int freq);
static int  gpio_set_pwm_range(int pin, int range);
static int  gpio_set_pwm_duty(int pin, int duty);
static int  gpio_set_pwm_range_safe(int pin, int range);
static int  gpio_set_pwm_frequency_safe(int pin, int freq);
static int  gpio_set_pwm_duty_safe(int pin, int duty);
static int  gpio_set_pwm_range_safe(int pin, int range);
static int  gpio_set_pwm_frequency_safe(int pin, int freq);
static int  gpio_set_pwm_duty_safe(int pin, int duty);
static void signal_handler(int sig);
static void cleanup(void);
static int  crc8(const uint8_t *data, size_t len, uint8_t checksum);
static int  read_pressure(int fd, float *pressure);
static int  read_temperature(int fd, float *temperature);
static void blink_led(int pin, int frequency, int duration_us);
static void blink_led_warning(int pin, int frequency, int duration_us);
static void blink_led_off(int pin);
static void blink_led_off_safe(int pin);

/* ------------------------------- Main ------------------------------------ */
int main(void)
{
    /* --- Signal handling ----------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio ---------------------------------------------- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }
    g_pigpio_ready = true;

    /* --- Open I2C bus ---------------------------------------------------- */
    g_i2c_fd = i2c_open();
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n",
                I2C_BUS, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO17 as output for the LED ------------------------- */
    if (gpio_set_mode(GPIO_LED, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", GPIO_LED);
        cleanup();
        return EXIT_FAILURE;
    }
    gpio_set_mode_output(GPIO_LED, 0);

    /* --- Configure LED blink parameters ------------------------------- */
    gpio_set_frequency(GPIO_LED, 1000);   /* 1 Hz */
    gpio_set_mode_output(GPIO_LED, 0);

    printf("ICP-10125 monitor started. Press Ctrl+C to exit.\n");

    /* --- Main loop ------------------------------------------------------ */
    while (g_running) {
        float pressure = 0.0f, temperature = 0.0f;

        if (read_pressure(g_i2c_fd, &pressure) != 0) {
            fprintf(stderr, "Error reading pressure (I2C bus error or sensor absent)\n");
            gpio_write(GPIO_LED, 0);
            gpio_set_frequency(GPIO_LED, 1000);
            gpio_set_mode_output(GPIO_LED, 0);
            gpio_set_mode_input(GPIO_LED);
            gpio_set_mode_output(GPIO_LED);
            gpio_set_frequency(GPIO_LED, 1000);
            gpio_set_mode_output(GPIO_LED, 0);
            gpio_set_frequency(GPIO_LED, 1000);
            gpio_set_mode_output(GPIO_LED, 0);
            gpio_set_frequency(GPIO_LED, 1000);
            gpio_set_mode_output(GPIO_LED, 0);
            gpio_set_frequency(GPIO_LED, 1000);
            gpio_set_mode_output(GPIO_LED, 0);
            gpio_set_frequency(GPIO_LED, 1000);
            gpio_set_mode_output(GPIO_LED, 0);
            gpio_set_frequency(GPIO_LED, 1000);
