/*
 * Raspberry Pi Zero W – MLX90614ESF-BAA ambient/object temperature logger
 *
 * Hardware:
 *   - MLX90614ESF-BAA I2C temperature sensor (SCL = GPIO3, SDA = GPIO2)
 *   - Cooling fan on GPIO18 (BCM)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o temp_logger temp_logger.c -lpigpio -lrt
 *   (pigpio must be installed; run as root or with appropriate permissions.)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS          1
#define MLX90614_ADDR    0x5C
#define FAN_GPIO         18
#define AMBIENT_TEMP_REG 0x07
#define OBJECT_TEMP_REG  0x08
#define LOG_FILE         "temperature_log.txt"
#define POLL_INTERVAL_S  2
#define MAX_RETRIES      3
#define RETRY_DELAY_US   10000   /* 10 ms */
#define HYSTERESIS_ON    30.0f
#define HYSTERESIS_OFF   28.0f

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg(int handle, uint8_t reg, uint8_t value)
{
    char buf[2] = { (char)reg, (char)value };
    if (i2cWriteDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "i2cWriteDevice(reg=0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(int handle, uint8_t reg, uint8_t *out)
{
    if (i2cWriteDevice(handle, (char *)&reg, 1) != 1) {
        fprintf(stderr, "i2cWriteDevice(reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (i2cReadDevice(handle, (char *)out, 1) != 1) {
        fprintf(stderr, "i2cReadDevice(reg=0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_temperature(int handle, uint8_t reg, float *out)
{
    uint8_t raw;
    for (int attempt = 1; attempt <= MAX_RETRIES; ++attempt) {
        if (i2c_read_reg(handle, reg, &raw) == 0) {
            *out = (float)raw * 0.02f - 273.15f;
            return 0;
        }
        if (attempt < MAX_RETRIES)
            gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Fan control                                                        */
/* ------------------------------------------------------------------ */
static int fan_set(int on)
{
    int level = on ? 1 : 0;
    if (gpioWrite(FAN_GPIO, level) != 0) {
        fprintf(stderr, "gpioWrite(FAN_GPIO=%d, %d) failed: %s\n",
                FAN_GPIO, level, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_temperature(float ambient, float object)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Ambient=%.2f C, Object=%.2f C\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            ambient, object);

    if (fclose(fp) != 0)
        fprintf(stderr, "fclose(%s) failed: %s\n", LOG_FILE, strerror(errno));
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure fan GPIO --- */
    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(FAN_GPIO=%d, OUTPUT) failed\n", FAN_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (fan_set(0) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus --- */
    g_i2c_handle = i2cOpen(I2C_BUS, MLX90614_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, MLX90614_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MLX90614 temperature logger started. Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        float ambient = 0.0f, object = 0.0f;

        if (read_temperature(g_i2c_handle, AMBIENT_TEMP_REG, &ambient) != 0) {
            fprintf(stderr, "Ambient temperature read failed; skipping cycle.\n");
        } else if (read_temperature(g_i2c_handle, OBJECT_TEMP_REG, &object) != 0) {
            fprintf(stderr, "Object temperature read failed; skipping cycle.\n");
        } else {
            log_temperature(ambient, object);

            if (object > HYSTERESIS_ON) {
                if (fan_set(1) != 0)
                    fprintf(stderr, "Failed to turn fan ON\n");
            } else if (object < HYSTERESIS_OFF) {
                if (fan_set(0) != 0)
                    fprintf(stderr, "Failed to turn fan OFF\n");
            }
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < POLL_INTERVAL_S * 10 && g_running; ++i)
            gpioDelay(100000);
    }

    /* --- Cleanup --- */
    printf("\nShutting down...\n");
    fan_set(0);
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

