/*
 * SHT40 Temperature & Humidity Sensor Reader for Raspberry Pi 4 Model B
 * Uses pigpio for I2C communication and the built-in HTTP server API.
 *
 * Wiring:
 *   SHT40 VDD  -> 3.3V (Pin 1)
 *   SHT40 GND  -> GND  (Pin 9)
 *   SHT40 SDA  -> GPIO2 / I2C1 SDA (Pin 3)
 *   SHT40 SCL  -> GPIO3 / I2C1 SCL (Pin 5)
 *
 * Build: gcc -o sht40_server sht40_server.c -lpigpio -lrt -lpthread
 * Run:   sudo ./sht40_server
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define HTTP_PORT 8080
#define MAX_RETRIES 3
#define RETRY_DELAY_US 100000  /* 100 ms */

/* SHT40 commands */
#define SHT40_MEASURE_CMD 0x2E

/* SHT40 data: 2 bytes temperature, 2 bytes humidity, 2 bytes checksum */
typedef struct {
    unsigned short temperature;
    unsigned short humidity;
} sht40_data_t;

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at bus %d, addr 0x%02X (pigpio error %d).\n",
                I2C_BUS, SHT40_ADDR, i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int read_sht40(sht40_data_t *data) {
    unsigned char cmd = SHT40_MEASURE_CMD;
    unsigned char buf[6];

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        /* Send measurement command */
        if (i2cWriteDevice(i2c_handle, &cmd, 1) != 0) {
            fprintf(stderr, "Warning: I2C write failed (attempt %d/%d).\n",
                    attempt + 1, MAX_RETRIES);
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        /* Wait for measurement to complete (datasheet: typ 8.5 ms, max 10 ms) */
        gpioDelay(10000);  /* 10 ms */

        /* Read 6 bytes: T_MSB, T_LSB, H_MSB, H_LSB, H_CRC, T_CRC */
        if (i2cReadDevice(i2c_handle, buf, 6) != 6) {
            fprintf(stderr, "Warning: I2C read failed (attempt %d/%d).\n",
                    attempt + 1, MAX_RETRIES);
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        /* Verify checksums (CRC-8 polynomial 0x31, init 0x00) */
        unsigned char t_crc = 0;
        for (int i = 0; i < 2; i++) t_crc ^= buf[i];
        if (t_crc != buf[2]) {
            fprintf(stderr, "Warning: Temperature checksum mismatch (calc=0x%02X, got=0x%02X).\n",
                    t_crc, buf[2]);
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        unsigned char h_crc = 0;
        for (int i = 3; i < 5; i++) h_crc ^= buf[i];
        if (h_crc != buf[4]) {
            fprintf(stderr, "Warning: Humidity checksum mismatch (calc=0x%02X, got=0x%02X).\n",
                    h_crc, buf[4]);
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        /* Convert raw values to physical units */
        data->temperature = (unsigned short)((buf[0] << 8) | buf[1]);
        data->humidity    = (unsigned short)((buf[3] << 8) | buf[4]);

        /* Clamp humidity to 0-100 % */
        if (data->humidity > 100) data->humidity = 100;
        if (data->humidity < 0)   data->humidity = 0;

        return 0;
    }

    fprintf(stderr, "Error: SHT40 read failed after %d attempts.\n", MAX_RETRIES);
    return -1;
}

static void send_http_response(int client_fd, const sht40_data_t *data) {
    char html[512];
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    snprintf(html, sizeof(html),
             "<!DOCTYPE html><html><head><title>SHT40 Sensor</title>"
             "<meta http-equiv=\"refresh\" content=\"5\"></head>"
             "<body><h1>SHT40 Sensor</h1>"
             "<p>Timestamp: %s</p>"
             "<p>Temperature: %.1f &deg;C</p>"
             "<p>Humidity: %d%%</p>"
             "</body></html>",
             timestamp, data->temperature, data->humidity);

    size_t len = strlen(html);
    char header[256];
    int head_len = snprintf(header, sizeof(header),
                            "HTTP/1.1 200 OK\r\n"
                            "Content-Type: text/html\r\n"
                            "Content-Length: %zu\r\n"
                            "Connection: close\r\n"
                            "\r\n", len);

    if (head_len < 0 || (size_t)head_len >= sizeof(header)) {
        fprintf(stderr, "Error: Header buffer too small.\n");
        close(client_fd);
        return;
    }

    if (write(client_fd, header, head_len) != head_len) {
        fprintf(stderr, "Error: Failed to write HTTP header.\n");
        close(client_fd);
        return;
    }

    if (write(client_fd, html, len) != len) {
        fprintf(stderr, "Error: Failed to write HTTP body.\n");
        close(client_fd);
        return;
    }

    close(client_fd);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        return EXIT_FAILURE;
    }

    printf("SHT40 sensor reader started. Listening on http://localhost:%d/\n", HTTP_PORT);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        sht40_data_t data;
        if (read_sht40(&data) == 0) {
            printf("Temperature: %.1f &deg;C, Humidity: %d%%\n", data.temperature, data.humidity);
            int client_fd = socket(AF_INET, SOCK_STREAM, 0);
            if (client_fd < 0) {
                perror("socket");
                continue;
            }

            struct sockaddr_in addr;
            memset(&addr, 0, sizeof(addr));
            addr.sin_family = AF_INET;
            addr.sin_addr.s_addr = INADDR_ANY;
            addr.sin_port = htons(HTTP_PORT);

            if (bind(client_fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
                perror("bind");
                close(client_fd);
                continue;
            }

            if (listen(client_fd, 5) < 0) {
                perror("listen");
                close(client_fd);
                continue;
            }

            while (running) {
                struct sockaddr_in client_addr;
                socklen_t client_len = sizeof(client_addr);
                int client_fd2 = accept(client_fd, (struct sockaddr *)&client_addr, &client_len);
                if (client_fd2 < 0) {
                    if (errno == EINTR) break;
                    perror("accept");
                    continue;
                }

                send_http_response(client_fd2, &data);
            }

            close(client_fd);
            break;
        }

        sleep(1);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

