#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define TMP102_ADDR    0x48
#define LOG_FILE       "temperature_log.csv"
#define SAMPLE_INTERVAL 5

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handler(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    return 0;
}

static int i2c_write_byte(int fd, uint8_t reg)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C short read: got %zd of %zu bytes\n", n, len);
        return -1;
    }
    return 0;
}

static int read_temperature(int fd, float *temperature)
{
    uint8_t reg = 0x00;
    if (i2c_write_byte(fd, reg) == -1)
        return -1;

    uint8_t data[2];
    if (i2c_read_bytes(fd, data, 2) == -1)
        return -1;

    int16_t raw = (int16_t)((data[0] << 8) | data[1]);
    *temperature = (float)raw / 16.0f;
    return 0;
}

static int log_temperature(const char *filename, float temperature)
{
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", filename, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
