/*
 * HDC2010 Temperature & Humidity Sensor Reader
 * Board:  Raspberry Pi Zero W
 * Bus:    I2C bus 1 (GPIO2 = SDA, GPIO3 = SCL)
 * Sensor: TI HDC2010 at I2C address 0x48
 *
 * Reads temperature and humidity every 5 s, logging to stdout.
 * Handles I2C errors, transient failures, and Ctrl+C cleanly.
 *
 * Build:  gcc -O2 -Wall -Wextra -o hdc2010 hdc2010.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define I2C_BUS        "/dev/i2c-1"
#define HDC2010_ADDR   0x48

/* HDC2010 register addresses */
#define REG_TEMP_LOW    0x00
#define REG_TEMP_HIGH   0x01
#define REG_HUM_LOW     0x02
#define REG_HUM_HIGH    0x03
#define REG_MEAS_CONFIG 0x0F

/* MEASUREMENT_CONFIG bits */
#define MEAS_CONFIG_MODE 0x01   /* 0 = one-shot, 1 = continuous */
#define MEAS_CONFIG_TRES 0x02   /* 0 = 0.5 °C, 1 = 1.0 °C */
#define MEAS_CONFIG_HRES 0x04   /* 0 = 0.5 %RH, 1 = 1.0 %RH */
#define MEAS_CONFIG_TOUT 0x08   /* 0 = 1 s, 1 = 2 s */
#define MEAS_CONFIG_HOUT 0x10   /* 0 = 1 s, 1 = 2 s */
#define MEAS_CONFIG_DRATE 0x20  /* 0 = 1 Hz, 1 = 8 Hz */
#define MEAS_CONFIG_NAK  0x80   /* 0 = no NAK, 1 = NAK */

#define MEAS_TIMEOUT_MS  500
#define POLL_INTERVAL_US 10000   /* 10 ms */
#define SAMPLE_INTERVAL_S 5
#define MAX_RETRIES      3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write_reg8(0x%02X, 0x%02X) failed: %s\n",
                reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "i2c_read_reg8 write(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    n = read(fd, out, 1);
    if (n != 1) {
        fprintf(stderr, "i2c_read_reg8 read(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* HDC2010 sensor abstraction                                          */
/* ------------------------------------------------------------------ */
typedef struct {
    int fd;
    bool initialized;
} hdc2010_t;

static int hdc2010_init(hdc2010_t *h)
{
    h->fd = -1;
    h->initialized = false;

    h->fd = open(I2C_BUS, O_RDWR);
    if (h->fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }

    if (ioctl(h->fd, I2C_SLAVE, HDC2010_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                HDC2010_ADDR, strerror(errno));
        close(h->fd);
        h->fd = -1;
        return -1;
    }

    /* Probe: try reading the MEAS_CONFIG register */
    uint8_t cfg;
    if (i2c_read_reg8(h->fd, REG_MEAS_CONFIG, &cfg) < 0) {
        fprintf(stderr, "HDC2010 not responding at 0x%02X on %s\n",
                HDC2010_ADDR, I2C_BUS);
        close(h->fd);
        h->fd = -1;
        return -1;
    }

    /* Clear NAK so subsequent reads return data, not NAK bytes */
    if (i2c_write_reg8(h->fd, REG_MEAS_CONFIG, MEAS_CONFIG_NAK) < 0) {
        fprintf(stderr, "Failed to clear HDC2010 NAK\n");
        close(h->fd);
        h->fd = -1;
        return -1;
    }

    h->initialized = true;
    printf("HDC2010 initialized at 0x%02X on %s\n", HDC2010_ADDR, I2C_BUS);
    return 0;
}

static int hdc2010_read(hdc2010_t *h, float *temperature, float *humidity)
{
    if (!h->initialized) {
        fprintf(stderr, "HDC2010 not initialized\n");
        return -1;
    }

    /* Trigger one-shot measurement */
    if (i2c_write_reg8(h->fd, REG_MEAS_CONFIG,
                       MEAS_CONFIG_MODE | MEAS_CONFIG_TRES |
                       MEAS_CONFIG_HRES | MEAS_CONFIG_TOUT |
                       MEAS_CONFIG_HOUT | MEAS_CONFIG_DRATE) < 0) {
        fprintf(stderr, "Failed to trigger measurement\n");
        return -1;
    }

    /* Poll until data-ready or timeout */
    for (int elapsed = 0; elapsed < MEAS_TIMEOUT_MS; elapsed += POLL_INTERVAL_US / 1000) {
        uint8_t cfg;
        if (i2c_read_reg8(h->fd, REG_MEAS_CONFIG, &cfg) < 0) {
            fprintf(stderr, "Poll read failed during measurement\n");
            return -1;
        }
        if ((cfg & MEAS_CONFIG_NAK) == 0) {
            break;
        }
        usleep(POLL_INTERVAL_US);
    }

    if ((cfg & MEAS_CONFIG_NAK) != 0) {
        fprintf(stderr, "HDC2010 measurement timeout (NAK)\n");
        return -1;
    }

    /* Read 6 bytes: T_low, T_high, H_low, H_high, CRC */
    uint8_t data[6];
    if (i2c_read_reg8(h->fd, REG_TEMP_LOW, &data[0]) < 0 ||
        i2c_read_reg8(h->fd, REG_TEMP_HIGH, &data[1]) < 0 ||
        i2c_read_reg8(h->fd, REG_HUM_LOW,  &data[2]) < 0 ||
        i2c_read_reg8(h->fd, REG_HUM_HIGH, &data[3]) < 0) {
        fprintf(stderr, "Failed to read measurement data\n");
        return -1;
    }

    /* CRC-8 (polynomial 0x31, init 0xFF) */
    uint8_t crc = 0xFF;
    for (int i = 0; i < 4; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    if (crc != data[4]) {
        fprintf(stderr, "HDC2010 CRC mismatch (calc=0x%02X, recv=0x%02X)\n",
                crc, data[4]);
        return -1;
    }

    int16_t raw_temp = (int16_t)((data[1] << 8) | data[0]);
    int16_t raw_hum  = (int16_t)((data[3] << 8) | data[2]);

    *temperature = (float)raw_temp / 100.0f;
    *humidity    = (float)raw_hum  / 100.0f;

    return 0;
}

static void hdc2010_close(hdc2010_t *h)
{
    if (h->fd >= 0) {
        close(h->fd);
        h->fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    hdc2010_t sensor;
    if (hdc2010_init(&sensor) < 0) {
        fprintf(stderr, "HDC2010 initialization failed\n");
        return EXIT_FAILURE;
    }

    printf("Reading HDC2010 every %d s. Press Ctrl+C to exit.\n",
           SAMPLE_INTERVAL_S);

    while (g_running) {
        float temperature, humidity;

        if (hdc2010_read(&sensor, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n",
                   temperature, humidity);
        } else {
            fprintf(stderr, "Read failed; will retry next cycle.\n");
        }

        /* Sleep in 100 ms increments so SIGINT is caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_S * 10 && g_running; i++) {
            usleep(100000);
        }
    }

    printf("\nShutting down...\n");
    hdc2010_close(&sensor);
    return EXIT_SUCCESS;
}

