           SAMPLE_INTERVAL_S);

    while (g_running) {
        float temperature, humidity;

        if (hdc2010_read(&sensor, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n",
                   temperature, humidity);
        } else {
            fprintf(stderr, "Read failed; will retry next cycle.\n");
        }

        /* Sleep in 100 ms increments so SIGINT is caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_S * 10 && g_running; i++) {
            usleep(100000);
        }
    }

    printf("\nShutting down...\n");
    hdc2010_close(&sensor);
    return EXIT_SUCCESS;
}

