/*
 * SDP800-500Pa differential pressure sensor reader for Raspberry Pi 3 Model B+
 * Uses the pigpio I2C library (modern API, no wiringPi).
 *
 * Wiring:
 *   SDP800 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   SDP800 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   SDP800 VDD  -> 3.3 V
 *   SDP800 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o sdp800 sdp800.c -lpigpio -lrt
 * Run:    sudo ./sdp800
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SDP800_ADDR    0x60
#define READ_INTERVAL  500000   /* microseconds (500 ms) */
#define MEAS_DELAY_US  45000    /* microseconds (45 ms) */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF)                        */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call even if pigpio is not initialised     */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Read one 6-byte measurement frame from the SDP800                  */
/* Returns 0 on success, -1 on I/O error, -2 on CRC mismatch.         */
/* ------------------------------------------------------------------ */
static int read_sdp800(int handle, int16_t *pressure, int16_t *temperature)
{
    uint8_t buf[6];

    /*
     * The SDP800 requires a 0x36 command byte to start a measurement.
     * pigpio's i2cWriteDevice writes the command byte followed by the
     * register address (0x00) as a single 2-byte transaction.
     */
    if (i2cWriteDevice(handle, (char *)buf, 2) != 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice failed (sensor may be absent)\n");
        return -1;
    }

    gpioDelay(MEAS_DELAY_US);

    if (i2cReadDevice(handle, (char *)buf, 6) != 6) {
        fprintf(stderr, "[ERROR] i2cReadDevice failed\n");
        return -1;
    }

    /* Validate CRCs */
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "[ERROR] Pressure CRC mismatch\n");
        return -2;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "[ERROR] Temperature CRC mismatch\n");
        return -2;
    }

    *pressure    = (int16_t)((buf[0] << 8) | buf[1]);
    *temperature = (int16_t)((buf[3] << 8) | buf[4]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- I2C open --------------------------------------------------- */
    g_i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (handle=%d) — sensor may be absent\n",
                g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handling ------------------------------------------- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[WARN] sigaction(SIGTERM)");
    }

    printf("SDP800-500Pa reader started (I2C bus %d, addr 0x%02X)\n",
           I2C_BUS, SDP800_ADDR);
    printf("Press Ctrl+C to stop.\n\n");

    /* --- Main loop -------------------------------------------------- */
    while (g_running) {
        int16_t pressure = 0, temperature = 0;
        int rc = read_sdp800(g_i2c_handle, &pressure, &temperature);

        if (rc == 0) {
            printf("Pressure: %d Pa, Temperature: %d °C\n",
                   pressure, temperature);
        } else if (rc == -1) {
            fprintf(stderr, "[WARN] I2C read error — continuing\n");
        } else {
            fprintf(stderr, "[WARN] CRC error — continuing\n");
        }

        /* Sleep in small increments so SIGINT is caught promptly */
        for (int i = 0; i < 50 && g_running; i++) {
            gpioDelay(10000); /* 10 ms */
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

