code:
/*
 * PID-controlled reflow oven for Raspberry Pi 3 Model B+
 * MAX6675 thermocouple amplifier (SPI0, CE0) + solid-state relay on GPIO17.
 *
 * Build:  gcc -O2 -Wall -Wextra -o reflow reflow.c -lpthread -lrt
 * Run:    ./reflow
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <pthread.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_DEVICE        "/dev/spidev0.0"   /* CE0 on SPI0 */
#define SPI_SPEED_HZ      1000000           /* 1 MHz */
#define SPI_BITS_PER_WORD 8
#define SPI_MODE          SPI_MODE_0

#define SSR_GPIO          17               /* BCM 17 */
#define SSR_PULSE_US     1000000           /* 1 second on-time */

#define LOG_FILE          "reflow_log.csv"
#define PROFILE_FILE      "profile.txt"

#define SAMPLE_PERIOD_S   1                /* seconds between samples */
#define MAX_RETRIES       3                /* SPI retransmission attempts */

/* PID constants */
#define KP  0.1
#define KI  0.01
#define KD  0.001
#define MAX_OUTPUT 1.0
#define MIN_OUTPUT 0.0

/* MAX6675 conversion: 14-bit signed, 1.5 mV/LSB */
#define MAX6675_VREF 3.3
#define MAX6675_LSB   0.0015

/* ----------------------------- Globals ---------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;
static FILE *g_log_fp = NULL;
static pthread_mutex_t g_log_mutex = PTHREAD_MUTEX_INITIALIZER;

/* ----------------------------- Prototypes -------------------------------- */
static void signal_handler(int sig);
static int  spi_init(void);
static int  read_max6675(int fd, float *out_temp);
static float pid_update(float setpoint, float current, float *integral,
                         float *prev_error, float dt);
static void ssr_set(int on);
static void log_data(float temp);
static void load_profile(float *profile, int *n);
static void cleanup(void);

/* ----------------------------- Signal handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- SPI init ---------------------------------- */
static int spi_init(void)
{
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1; return -1;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1; return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        close(g_spi_fd); g_spi_fd = -1; return -1;
    }

    return 0;
}

/* ----------------------------- MAX6675 read ------------------------------ */
static int read_max6675(int fd, float *out_temp)
{
    if (out_temp == NULL) return -1;

    /* MAX6675 requires a 4-byte transfer: 4 start/flags + 2 data bytes */
    uint8_t tx[4] = {0, 0, 0, 0};
    uint8_t rx[4] = {0, 0, 0, 0};

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = 4;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS_PER_WORD;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI_IOC_MESSAGE: %s\n", strerror(errno));
        return -1;
    }

    /* rx[0] = 0x00 (reserved), rx[1] = 0x00 (reserved), rx[2..3] = data */
    uint16_t raw = ((uint16_t)rx[2] << 8) | rx[3];

    /* 14-bit signed thermocouple reading */
    int16_t signed_val = (int16_t)raw >> 2;
    if (signed_val & 0x2000) {
        signed_val |= 0xC000;   /* sign-extend */
    }

    *out_temp = (float)signed_val * MAX6675_LSB / MAX6675_VREF;
    return 0;
}

/* ----------------------------- PID --------------------------------------- */
static float pid_update(float setpoint, float current, float *integral,
                         float *prev_error, float dt)
{
    float error = setpoint - current;
    *integral += error * dt;
    /* anti-windup clamp */
    if (*integral > 100.0) *integral = 100.0;
    if (*integral < -100.0) *integral = -100.0;
    float derivative = (error - *prev_error) / dt;
    *prev_error = error;
    return KP * error + KI * (*integral) + KD * derivative;
}

/* ----------------------------- SSR -------------------------------------- */
static void ssr_set(int on)
{
    if (on) {
        if (gpioWrite(SSR_GPIO, 1) < 0)
            fprintf(stderr, "gpioWrite(1) failed: %s\n", strerror(errno));
    } else {
        if (gpioWrite(SSR_GPIO, 0) < 0)
            fprintf(stderr, "gpioWrite(0) failed: %s\n", strerror(errno));
    }
}

/* ----------------------------- Logging ---------------------------------- */
static void log_data(float temp)
{
    pthread_mutex_lock(&g_log_mutex);
    if (g_log_fp) {
        time_t now = time(NULL);
        struct tm tmv;
        char ts[32];
        localtime_r(&now, &tmv);
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tmv);
        fprintf(g_log_fp, "%s,%.2f\n", ts, temp);
        fflush(g_log_fp);
    }
    pthread_mutex_unlock(&g_log_mutex);
}

/* ----------------------------- Profile ----------------------------------- */
static void load_profile(float *profile, int *n)
{
    FILE *fp = fopen(PROFILE_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", PROFILE_FILE, strerror(errno));
        *n = 0;
        return;
    }

    *n = 0;
    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        *n++;
    }
    rewind(fp);

    for (int i = 0; i < *n; i++) {
        float t, temp;
        if (fscanf(fp, "%f,%f", &t, &temp) == 2) {
            profile[i] = temp;
        } else {
            fprintf(stderr, "Warning: malformed line %d in profile\n", i + 1);
        }
    }
    fclose(fp);
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    ssr_set(0);
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    pthread_mutex_destroy(&g_log_mutex);
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (spi_init() < 0) {
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    float profile[100];
    int n = 0;
    load_profile(profile, &n);
    if (n == 0) {
        fprintf(stderr, "No profile data found; using default target 50 C\n");
        profile[0] = 50.0f;
        n = 1;
    }

    float integral = 0.0f;
    float prev_error = 0.0f;
    float target = profile[0];
    float current = 0.0f;
    int ssr_on = 0;

    while (g_running) {
        float temp = 0.0f;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (read_max6675(g_spi_fd, &temp) == 0) {
                ok = 1;
                break;
            }
            fprintf(stderr, "SPI read attempt %d/%d failed\n", attempt + 1, MAX_RETRIES);
            if (attempt < MAX_RETRIES - 1) {
                usleep(100000);   /* 100 ms backoff */
            }
        }

        if (!ok) {
            fprintf(stderr, "MAX6675 read failed after %d attempts; skipping cycle\n",
                    MAX_RETRIES);
            sleep(SAMPLE_PERIOD_S);
            continue;
        }

        current = temp;
        float pid_out = pid_update(target, current, &integral, &prev_error,
                                    (float)SAMPLE_PERIOD_S);

        if (pid_out < 0.0f) pid_out = 0.0f;
        if (pid_out > 1.0f) pid_out = 1.0f;

        if (pid_out > 0.0f) {
            if (!ssr_on) {
                ssr_set(1);
                ssr_on = 1;
            }
        } else {
            if (ssr_on) {
                ssr_set(0);
                ssr_on = 0;
            }
        }

        log_data(current);

        /* Advance target to next point when we reach the current one */
        if (current >= target) {
            target = profile[(n > 0) ? (n - 1) : 0];
            if (n > 1) n--;
        }

        sleep(SAMPLE_PERIOD_S);
    }

    cleanup();
    return EXIT_SUCCESS;
}

