/*
 * PID-controlled greenhouse heater for Raspberry Pi 3 Model B+
 * Sensor : DS18B20 on /sys/bus/w1/devices/ (data line -> GPIO4)
 * Relay  : 12 V heater via relay on GPIO17 (active-high)
 * PWM    : hardware PWM on GPIO18 (BCM 18, physical pin 12)
 *
 * Build: gcc -O2 -Wall -o greenhouse greenhouse.c -lm
 * Run  : ./greenhouse [setpoint] [Kp] [Ki] [Kd]
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <math.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>

#define SENSOR_PATH "/sys/bus/w1/devices/28-00000xxxxxxx/w1_slave"
#define RELAY_GPIO 17
#define PWM_GPIO 18
#define LOG_FILE "greenhouse.log"
#define SAMPLE_INTERVAL_SEC 5
#define MAX_RETRIES 3

static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) == -1)
        perror("sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* Sensor helpers                                                     */
/* ------------------------------------------------------------------ */
static int read_raw_temperature(int fd, int16_t *raw_out)
{
    char buf[256];
    ssize_t n = read(fd, buf, sizeof(buf) - 1);
    if (n < 0) {
        if (errno == EINTR) return -1;
        fprintf(stderr, "read() failed: %s\n", strerror(errno));
        return -1;
    }
    if (n == 0) {
        fprintf(stderr, "read() returned 0 (sensor absent?)\n");
        return -1;
    }
    buf[n] = '\0';

    /* DS18B20 returns a line ending with "YES" or "NO" */
    char *yes = strpbrk(buf, "YES");
    if (!yes) {
        fprintf(stderr, "CRC check failed: no YES/NO\n");
        return -1;
    }
    *yes = '\0';

    char *endp = NULL;
    errno = 0;
    long temp = strtol(buf, &endp, 10);
    if (errno != 0 || endp == buf) {
        fprintf(stderr, "Failed to parse temperature: %s\n", buf);
        return -1;
    }

    *raw_out = (int16_t)temp;
    return 0;
}

static int read_temperature(float *out)
{
    int fd = open(SENSOR_PATH, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", SENSOR_PATH, strerror(errno));
        return -1;
    }

    int16_t raw;
    int ok = 0;
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (read_raw_temperature(fd, &raw) == 0) {
            ok = 1;
            break;
        }
        if (attempt < MAX_RETRIES - 1)
            usleep(100000); /* 100 ms backoff */
    }

    if (!ok) {
        close(fd);
        return -1;
    }

    /* DS18B20 returns temperature in 0.1 C increments */
    *out = (float)raw / 10.0f;
    close(fd);
    return 0;
}

/* ------------------------------------------------------------------ */
/* PID control                                                        */
/* ------------------------------------------------------------------ */
static float pid_control(float setpoint, float kp, float ki, float kd,
                         float current)
{
    static float integral = 0.0f;
    static float prev_error = 0.0f;

    float error = setpoint - current;
    integral += error;
    /* Anti-windup clamp */
    if (integral > 100.0f) integral = 100.0f;
    if (integral < -100.0f) integral = -100.0f;

    float derivative = error - prev_error;
    float output = kp * error + ki * integral + kd * derivative;

    prev_error = error;
    return output;
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */
static int set_relay(int state)
{
    int rc = (int)system("echo 0 > /sys/class/pwm/pwmchip0/export 2>/dev/null");
    if (rc != 0) {
        fprintf(stderr, "Warning: could not re-export PWM channel: %s\n",
                strerror(errno));
    }
    rc = (int)system("echo 1 > /sys/class/pwm/pwmchip0/pwm0/enable 2>/dev/null");
    if (rc != 0) {
        fprintf(stderr, "Warning: could not enable PWM channel: %s\n",
                strerror(errno));
        return -1;
    }
    rc = (int)system("echo 0 > /sys/class/pwm/pwmchip0/pwm0/period 2>/dev/null");
    if (rc != 0) {
        fprintf(stderr, "Warning: could not set PWM period: %s\n",
                strerror(errno));
        return -1;
    }
    rc = (int)system("echo 0 > /sys/class/pwm/pwmchip0/pwm0/duty_cycle 2>/dev/null");
    if (rc != 0) {
        fprintf(stderr, "Warning: could not set PWM duty cycle: %s\n",
                strerror(errno));
        return -1;
    }
    rc = (int)system("echo 1 > /sys/class/pwm/pwmchip0/pwm0/enable 2>/dev/null");
    if (rc != 0) {
        fprintf(stderr, "Warning: could not re-enable PWM channel: %s\n",
                strerror(errno));
        return -1;
    }
    if (state)
        return 0;
    rc = (int)system("echo 0 > /sys/class/pwm/pwmchip0/pwm0/enable 2>/dev/null");
    if (rc != 0) {
        fprintf(stderr, "Warning: could not disable PWM channel: %s\n",
                strerror(errno));
        return -1;
    }
    return 0;
}

static int set_pwm_duty(float duty_percent)
{
    if (duty_percent < 0.0f) duty_percent = 0.0f;
    if (duty_percent > 100.0f) duty_percent = 100.0f;

    int period_ns = 1000000000; /* 1 s = 1,000,000,000 ns */
    int duty_ns = (int)((period_ns * duty_percent) / 100.0f);

    char buf[64];
    int rc = snprintf(buf, sizeof(buf), "%d", duty_ns);
    if (rc < 0 || rc >= (int)sizeof(buf)) {
        fprintf(stderr, "Error formatting PWM duty string\n");
        return -1;
    }

    rc = (int)system("echo 0 > /sys/class/pwm/pwmchip0/pwm0/period 2>/dev/null");
    if (rc != 0) {
        fprintf(stderr, "Warning: could not set PWM period: %s\n",
                strerror(errno));
        return -1;
    }
    rc = (int)system("echo 0 > /sys/class/pwm/pwmchip0/pwm0/duty_cycle 2>/dev/null");
    if (rc != 0) {
        fprintf(stderr, "Warning: could not set PWM duty cycle: %s\n",
                strerror(errno));
        return -1;
    }
    rc = (int)system("echo %s > /sys/class/pwm/pwmchip0/pwm0/duty_cycle 2>/dev/null",
                     buf);
    if (rc != 0) {
        fprintf(stderr, "Warning: could not set PWM duty cycle: %s\n",
                strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(float avg_temp, float setpoint, float pid_out,
                     float pwm_duty)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    fprintf(g_log, "%s,%.2f,%.2f,%.2f,%.2f\n",
            ts, avg_temp, setpoint, pid_out, pwm_duty);
    fflush(g_log);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    float setpoint = 20.0f;
    float kp = 1.0f, ki = 0.1f, kd = 0.01f;

    if (argc > 1) setpoint = strtof(argv[1], NULL);
    if (argc > 2) kp = strtof(argv[2], NULL);
    if (argc > 3) ki = strtof(argv[3], NULL);
    if (argc > 4) kd = strtof(argv[4], NULL);

    if (setpoint <= 0.0f || kp <= 0.0f || ki <= 0.0f || kd <= 0.0f) {
        fprintf(stderr, "Invalid arguments: setpoint=%f Kp=%f Ki=%f Kd=%f\n",
                setpoint, kp, ki, kd);
        return EXIT_FAILURE;
    }

    install_signal_handlers();

    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Relay and PWM setup */
    if (set_relay(0) != 0) {
        fprintf(stderr, "Failed to initialize relay state\n");
        fclose(g_log);
        return EXIT_FAILURE;
    }
    if (set_pwm_duty(0.0f) != 0) {
        fprintf(stderr, "Failed to initialize PWM duty cycle\n");
        set_relay(0);
        fclose(g_log);
        return EXIT_FAILURE;
    }

    printf("Greenhouse PID controller started.  Setpoint=%.1f C  Kp=%.2f  Ki=%.2f  Kd=%.2f\n",
           setpoint, kp, ki, kd);

    while (g_running) {
        float current_temp;
        if (read_temperature(&current_temp) != 0) {
            fprintf(stderr, "Sensor read failed; retrying in %d s\n",
                    SAMPLE_INTERVAL_SEC);
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        float pid_out = pid_control(setpoint, kp, ki, kd, current_temp);
        float pwm_duty = (float)pid_out / 100.0f;

        if (set_pwm_duty(pwm_duty) != 0) {
            fprintf(stderr, "PWM duty set failed; continuing\n");
        }

        log_data(current_temp, setpoint, pid_out, pwm_duty);

        printf("T=%.2f C  Setpoint=%.2f C  PID Out=%.2f  PWM %.1f%%\n",
               current_temp, setpoint, pid_out, pwm_duty);

        sleep(SAMPLE_INTERVAL_SEC);
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    set_relay(0);
    set_pwm_duty(0.0f);
    if (g_log) {
        fclose(g_log);
        g_log = NULL;
    }
    printf("Resources released. Goodbye.\n");
    return EXIT_SUCCESS;
}

