/*
 * AHT20 humidity monitor with dehumidifier control on Raspberry Pi 5.
 *
 * Wiring:
 *   AHT20 SDA  -> GPIO2  (I2C bus 1, pin 3)
 *   AHT20 SCL  -> GPIO3  (I2C bus 1, pin 5)
 *   AHT20 VDD  -> 3.3 V
 *   AHT20 GND  -> GND
 *   Relay IN   -> GPIO17 (pin 11, active-high)
 *
 * Build:  gcc -O2 -Wall -Wextra -o aht20_monitor aht20_monitor.c -lpigpio -lrt
 * Run:    sudo ./aht20_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS        "/dev/i2c-1"
#define AHT20_ADDR     0x28
#define GPIO_DEHUMID   17
#define HUMIDITY_HIGH   60.0f
#define HUMIDITY_LOW    55.0f
#define POLL_INTERVAL   5          /* seconds between readings */
#define MEAS_DELAY_US   80000      /* 80 ms measurement wait */
#define RETRY_DELAY_US  10000      /* 10 ms between retries */
#define MAX_RETRIES     3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_byte(int fd, uint8_t byte)
{
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write(0x%02X) failed: %s\n",
                byte, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read failed (got %zd of %zu): %s\n",
                n, len, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* AHT20 measurement                                                  */
/* ------------------------------------------------------------------ */
/*
 * Trigger a measurement and read the 6-byte result.
 * Returns 0 on success, -1 on persistent failure.
 */
static int aht20_read_humidity(int fd, float *humidity)
{
    uint8_t cmd[2] = { 0x00, 0x00 };   /* trigger measurement */
    uint8_t data[6];
    int attempt;

    for (attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        if (i2c_write_byte(fd, cmd[0]) < 0) {
            gpioDelay(RETRY_DELAY_US);
            continue;
        }
        if (i2c_write_byte(fd, cmd[1]) < 0) {
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        gpioDelay(MEAS_DELAY_US);

        if (i2c_read_bytes(fd, data, sizeof(data)) < 0)
            continue;

        /* Status byte: bit 0 = busy, bit 1 = calibrated */
        if (data[0] & 0x01) {
            fprintf(stderr, "AHT20 busy (attempt %d/%d)\n",
                    attempt + 1, MAX_RETRIES);
            gpioDelay(RETRY_DELAY_US);
            continue;
        }
        if (!(data[0] & 0x02)) {
            fprintf(stderr, "AHT20 calibration failed (attempt %d/%d)\n",
                    attempt + 1, MAX_RETRIES);
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        uint32_t raw = ((uint32_t)data[1] << 12) |
                       ((uint32_t)data[2] << 4)  |
                       ((uint32_t)(data[3] >> 4));
        *humidity = 100.0f * (float)raw / 1048576.0f;
        return 0;
    }

    return -1;
}

/* ------------------------------------------------------------------ */
/* GPIO control                                                        */
/* ------------------------------------------------------------------ */
static void dehumidifier_set(int gpio, int on)
{
    if (gpioWrite(gpio, on ? 1 : 0) < 0)
        fprintf(stderr, "GPIO %d write failed: %s\n", gpio, strerror(errno));
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_humidity(float humidity)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32] = { 0 };
    if (t)
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    else
        snprintf(ts, sizeof(ts), "?");

    printf("[%s] Humidity: %.2f%%\n", ts, humidity);
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    /* Ensure dehumidifier is off before terminating pigpio */
    gpioWrite(GPIO_DEHUMID, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- GPIO setup --- */
    if (gpioSetMode(GPIO_DEHUMID, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_DEHUMID);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    dehumidifier_set(GPIO_DEHUMID, 0);

    /* --- I2C open --- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, AHT20_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                AHT20_ADDR, strerror(errno));
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- signals --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("AHT20 humidity monitor started. Ctrl+C to exit.\n");

    /* --- main loop --- */
    while (g_running) {
        float humidity;

        if (aht20_read_humidity(g_i2c_fd, &humidity) == 0) {
            log_humidity(humidity);

            if (humidity > HUMIDITY_HIGH)
                dehumidifier_set(GPIO_DEHUMID, 1);
            else if (humidity < HUMIDITY_LOW)
                dehumidifier_set(GPIO_DEHUMID, 0);
        } else {
            fprintf(stderr, "AHT20 read failed after %d retries; "
                            "sensor may be absent or bus error.\n",
                    MAX_RETRIES);
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < POLL_INTERVAL && g_running; ++i)
            sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

