#define I2C_BUS "/dev/i2c-1"
#define HTU21D_ADDR 0x45
#define HTTP_ENDPOINT "http://api.example.com/humidity"
#define POLL_INTERVAL 60
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_bytes(int fd, unsigned char *buf, int len) {
    int total = 0;
    while (total < len) {
        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) {
            if (errno == EINTR) continue;
            syslog(LOG_ERR, "I2C read error: %s", strerror(errno));
            return -1;
        }
        if (n == 0) {
            syslog(LOG_ERR, "I2C read: unexpected EOF");
            return -1;
        }
        total += n;
    }
    return 0;
}

static int i2c_write_bytes(int fd, unsigned char *buf, int len) {
    int total = 0;
    while (total < len) {
        ssize_t n = write(fd, buf + total, len - total);
        if (n < 0) {
            if (errno == EINTR) continue;
            syslog(LOG_ERR, "I2C write error: %s", strerror(errno));
            return -1;
        }
        if (n == 0) {
            syslog(LOG_ERR, "I2C write: unexpected EOF");
            return -1;
        }
        total += n;
    }
    return 0;
}

static int read_humidity(int fd, float *humidity) {
    unsigned char cmd[2] = {0xF5, 0x35};
    unsigned char buf[3];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2c_write_bytes(fd, cmd, 2) < 0) {
            retries++;
            sleep(1);
            continue;
        }

        if (i2c_read_bytes(fd, buf, 3) < 0) {
            retries++;
            sleep(1);
            continue;
        }

        if (buf[0] & 0x80) {
            syslog(LOG_ERR, "HTU21D fault bit set");
            return -1;
        }

        unsigned int raw = ((unsigned int)buf[0] << 8) | buf[1];
        *humidity = -6.0 + 125.0 * (raw / 65536.0);
        return 0;
    }

    syslog(LOG_ERR, "HTU21D read failed after %d retries", MAX_RETRIES);
    return -1;
}

static int post_data(const char *url, float humidity) {
    int sockfd = -1;
    struct sockaddr_in servaddr;
    char request[256];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        sockfd = socket(AF_INET, SOCK_STREAM, 0);
        if (sockfd < 0) {
            syslog(LOG_ERR, "Socket creation failed: %s", strerror(errno));
            retries++;
            sleep(1);
            continue;
        }

