#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <math.h>

#define BMP280_I2C_ADDR 0x76
#define BMP280_REG_CHIP_ID 0xD0
#define BMP280_REG_RESET 0xE0
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_CALIB 0x88
#define BMP280_CHIP_ID 0x58
#define RETRY_COUNT 3
#define SAMPLE_INTERVAL_SEC 2
#define CONVERSION_DELAY_MS 10

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

static int16_t dig_T1, dig_T2, dig_T3;
static int16_t dig_P1, dig_P2, dig_P3, dig_P4, dig_P5, dig_P6, dig_P7, dig_P8, dig_P9;
static int32_t t_fine;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg(uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(i2c_fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_reg(uint8_t reg, uint8_t *buf, size_t len) {
    if (write(i2c_fd, &reg, 1) != 1) return -1;
    if (read(i2c_fd, buf, len) != (ssize_t)len) return -1;
    return 0;
}

static int i2c_read_reg16(uint8_t reg, int16_t *out) {
    uint8_t buf[2];
    if (i2c_read_reg(reg, buf, 2) < 0) return -1;
    *out = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int i2c_read_reg24(uint8_t reg, int32_t *out) {
    uint8_t buf[3];
    if (i2c_read_reg(reg, buf, 3) < 0) return -1;
    *out = ((int32_t)buf[0] << 16) | ((int32_t)buf[1] << 8) | buf[2];
    *out >>= 8;
    return 0;
}

static int i2c_read_block(uint8_t reg, uint8_t *buf, size_t len) {
    if (write(i2c_fd, &reg, 1) != 1) return -1;
    if (read(i2c_fd, buf, len) != (ssize_t)len) return -1;
    return 0;
}

static int bmp280_init(void) {
    uint8_t chip_id;
    if (i2c_read_reg(BMP280_REG_CHIP_ID, &chip_id, 1) < 0) {
        fprintf(stderr, "Error: Failed to read chip ID: %s\n", strerror(errno));
        return -1;
    }
    if (chip_id != BMP280_CHIP_ID) {
        fprintf(stderr, "Error: Invalid chip ID 0x%02X (expected 0x%02X). Sensor not present.\n", chip_id, BMP280_CHIP_ID);
        return -1;
    }
    if (i2c_write_reg(BMP280_REG_RESET, 0xB6) < 0) {
        fprintf(stderr, "Error: Failed to reset sensor: %s\n", strerror(errno));
        return -1;
    }
    usleep(2000);
    if (i2c_write_reg(BMP280_REG_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write config register: %s\n", strerror(errno));
        return -1;
    }
    if (i2c_write_reg(BMP280_REG_CTRL_MEAS, 0x27) < 0) {
        fprintf(stderr, "Error: Failed to write ctrl_meas register: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int bmp280_read_calibration(void) {
    uint8_t cal[24];
    if (i2c_read_block(BMP280_REG_CALIB, cal, 24) < 0) {
        fprintf(stderr, "Error: Failed to read calibration data: %s\n", strerror(errno));
        return -1;
    }
    dig_T1 = (int16_t)((cal[1] << 8) | cal[0]);
    dig_T2 = (int16_t)((cal[3] << 8) | cal[2]);
    dig_T3 = (int16_t)((cal[5] << 8) | cal[4]);
    dig_P1 = (int16_t)((cal[7] << 8) | cal[6]);
    dig_P2 = (int16_t)((cal[9] << 8) | cal[8]);
    dig_P3 = (int16_t)((cal[11] << 8) | cal[10]);
    dig_P4 = (int16_t)((cal[13] << 8) | cal[12]);
    dig_P5 = (int16_t)((cal[15] << 8) | cal[14]);
    dig_P6 = (int16_t)((cal[17] << 8) | cal[16]);
    dig_P7 = (int16_t)((cal[19] << 8) | cal[18]);
    dig_P8 = (int16_t)((cal[21] << 8) | cal[20]);
    dig_P9 = (int16_t)((cal[23] << 8) | cal[22]);
    return 0;
}

static int bmp280_read_raw(int32_t *raw_t, int32_t *raw_p) {
    uint8_t data[6];
    if (i2c_read_block(BMP280_REG_PRESS_MSB, data, 6) < 0) {
        fprintf(stderr, "Error: Failed to read raw data: %s\n", strerror(errno));
        return -1;
    }
    *raw_p = ((int32_t)data[0] << 12) | ((int32_t)data[1] << 4) | (data[2] >> 4);
    *raw_t = ((int32_t)data[3] << 12) | ((int32_t)data[4] << 4) | (data[5] >> 4);
    return 0;
}

static double bmp280_compensate_temp(int32_t raw_t) {
    double v1 = ((double)raw_t / 16384.0 - (double)dig_T1 / 1024.0) * (double)dig_T2;
    double v2 = (((double)raw_t / 131072.0 - (double)dig_T1 / 8192.0) * ((double)raw_t / 131072.0 - (double)dig_T1 / 8192.0)) * (double)dig_T3;
    t_fine = (int32_t)(v1 + v2);
    return (v1 + v2) / 5120.0;
}

static double bmp280_compensate_press(int32_t raw_p) {
    double v1 = ((double)t_fine / 2.0) - 64000.0;
    double v2 = v1 * v1 * (double)dig_P6 / 32768.0;
    v2 = v2 + v1 * (double)dig_P5 * 2.0;
    v2 = (v2 / 4.0) + ((double)dig_P4 * 65536.0);
    v1 = ((double)dig_P3 * v1 * v1 / 524288.0 + (double)dig_P2 * v1) / 524288.0;
    v1 = (1.0 + v1 / 32768.0) * (double)dig_P1;
    if (v1 == 0.0) return 0.0;
    double p = 1048576.0 - (double)raw_p;
    p = (p - (v2 / 4096.0)) * 6250.0 / v1;
    v1 = (double)dig_P9 * p * p / 2147483648.0;
    v2 = p * (double)dig_P8 / 32768.0;
    p = p + (v1 + v2 + (double)dig_P7) / 16.0;
    return p / 100.0;
}

static void log_pressure(double pressure) {
    FILE *fp = fopen("pressure_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "Error: Failed to open log file: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, %.2f hPa\n", timestamp, pressure);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error: Failed to open /dev/i2c-1: %s\n", strerror(errno));
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, BMP280_I2C_ADDR) < 0) {
        fprintf(stderr, "Error: Failed to set I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }
    if (bmp280_init() < 0) {
        close(i2c_fd);
        return 1;
    }
    if (bmp280_read_calibration() < 0) {
        close(i2c_fd);
        return 1;
    }
    printf("BMP280 initialized. Monitoring pressure...\n");

    while (running) {
        int retries = RETRY_COUNT;
        int success = 0;
        while (retries > 0 && !success) {
            int32_t raw_t, raw_p;
            if (bmp280_read_raw(&raw_t, &raw_p) == 0) {
                double temp = bmp280_compensate_temp(raw_t);
                double press = bmp280_compensate_press(raw_p);
                if (press > 1020.0 || press < 980.0) {
                    log_pressure(press);
                }
                success = 1;
            } else {
                retries--;
                if (retries > 0) {
                    fprintf(stderr, "Retrying (%d/%d)...\n", retries, RETRY_COUNT);
                    close(i2c_fd);
                    i2c_fd = -1;
                    sleep(1);
                    i2c_fd = open("/dev/i2c-1", O_RDWR);
                    if (i2c_fd < 0) {
                        fprintf(stderr, "Error: Failed to reopen /dev/i2c-1: %s\n", strerror(errno));
                        break;
                    }
                    if (ioctl(i2c_fd, I2C_SLAVE, BMP280_I2C_ADDR) < 0) {
                        fprintf(stderr, "Error: Failed to set I2C slave address: %s\n", strerror(errno));
                        break;
                    }
                    if (bmp280_init() < 0) {
                        fprintf(stderr, "Error: BMP280 init failed after retry.\n");
                        break;
                    }
                    if (bmp280_read_calibration() < 0) {
                        fprintf(stderr, "Error: Calibration read failed after retry.\n");
                        break;
                    }
                }
            }
        }
        if (!success) {
            fprintf(stderr, "Error: Failed to read sensor after %d retries.\n", RETRY_COUNT);
        }
        if (running) sleep(SAMPLE_INTERVAL_SEC);
    }

    if (i2c_fd >= 0) {
        i2c_write_reg(BMP280_REG_CTRL_MEAS, 0x00);
        close(i2c_fd);
    }
    printf("\nExiting gracefully.\n");
    return 0;
}

