/*
 * Raspberry Pi 4B — TMP117 (temperature), AHT20 (humidity), PIR (motion)
 * All logging to daily CSV files: Timestamp,Temperature(C),Humidity(%%),MotionDetected
 *
 * TMP117  I2C 0x39  (ADDR pin to GND)
 * AHT20   I2C 0x72 (ADDR pin to VDD)
 * PIR     GPIO17 (gpiochip4 line 17, input)
 *
 * Build: gcc -O2 -Wall -Wextra -o logger logger.c -lgpiod -lrt
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define TMP117_ADDR    0x39
#define AHT20_ADDR     0x72
#define PIR_GPIO_LINE  17

#define SAMPLE_INTERVAL_S 1
#define MAX_RETRIES      3
#define RETRY_DELAY_MS   10

#define LOG_FILE_FMT     "data/%Y-%m-%d.csv"

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---------- I2C helpers ---------- */

static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE 0x%02X): %s\n", addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int i2c_write_byte(int fd, uint8_t byte)
{
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "i2c write(0x%02X): %s\n", byte, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "i2c read: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ---------- TMP117 temperature ---------- */

static int tmp117_read(int fd, float *temp_c)
{
    if (i2c_write(fd, 0x36) < 0) return -1;          /* trigger conversion */
    usleep(10000);                                   /* 10 ms */
    uint8_t buf[3];
    for (int attempt = 1; attempt <= MAX_RETRIES; attempt++) {
        if (i2c_read_block(fd, buf, sizeof(buf)) == 0) {
            uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
            *temp_c = (float)raw / 16.0f;
            return 0;
        }
        if (attempt < MAX_RETRIES)
            usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

/* ---------- AHT20 humidity ---------- */

static int aht20_read(int fd, float *rh)
{
    if (i2c_write(fd, 0x30) < 0) return -1;          /* reset */
    usleep(10000);
    if (i2c_write(fd, 0x32) < 0) return -1;          /* measure */
    usleep(10000);
    uint8_t buf[8];
    for (int attempt = 1; attempt <= MAX_RETRIES; attempt++) {
        if (i2c_read_block(fd, buf, sizeof(buf)) == 0) {
            uint32_t raw = ((uint32_t)buf[1] << 12) |
                           ((uint32_t)buf[2] << 4)  |
                           ((uint32_t)buf[3] >> 4);
            *rh = (float)raw / 1024.0f;
            return 0;
        }
        if (attempt < MAX_RETRIES)
            usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

/* ---------- PIR motion ---------- */

static int pir_read(struct gpiod_line *line, int *motion)
{
    int v = gpiod_line_get_value(line);
    if (v < 0) {
        fprintf(stderr, "gpiod_line_get_value: %s\n", strerror(errno));
        return -1;
    }
    *motion = (v == 1);
    return 0;
}

/* ---------- CSV logging ---------- */

static int log_open(const char *path, int *ok)
{
    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        fprintf(stderr, "localtime_r: %s\n", strerror(errno));
        return -1;
    }
    char fn[64];
    strftime(fn, sizeof(fn), LOG_FILE_FMT, &tm);
    FILE *fp = fopen(fn, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", fn, strerror(errno));
        return -1;
    }
    *ok = 1;
    return 0;
}

static void log_write(int fd, float temp, float rh, int motion)
{
    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        fprintf(stderr, "localtime_r: %s\n", strerror(errno));
        return;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fd, "%s,%.2f,%.2f,%d\n", ts, temp, rh, motion);
    fflush(fd);
}

/* ---------- main ---------- */

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- TMP117 --- */
    int tmp_fd = i2c_open(I2C_BUS, TMP117_ADDR);
    if (tmp_fd < 0) {
        fprintf(stderr, "TMP117 (0x%02X) not available; continuing.\n", TMP117_ADDR);
    }

    /* --- AHT20 --- */
    int aht_fd = i2c_open(I2C_BUS, AHT20_ADDR);
    if (aht_fd < 0) {
        fprintf(stderr, "AHT20 (0x%02X) not available; continuing.\n", AHT20_ADDR);
    }

    /* --- PIR via gpiod --- */
    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open: %s\n", strerror(errno));
        goto cleanup;
    }
    struct gpiod_line *pir = gpiod_chip_get_line(chip, PIR_GPIO_LINE);
    if (!pir) {
        fprintf(stderr, "gpiod_chip_get_line(%d): %s\n", PIR_GPIO_LINE, strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_input(pir, "pir-motion") < 0) {
        fprintf(stderr, "gpiod_line_request_input: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Starting data logger (TMP117, AHT20, PIR on GPIO17) every %d s.\n",
           SAMPLE_INTERVAL_S);

    while (g_running) {
        int ok = 0;
        float temp = 0.0f, rh = 0.0f, motion = 0;

        if (tmp_fd >= 0) {
            if (tmp117_read(tmp_fd, &temp) == 0) ok |= 1;
        }
        if (aht_fd >= 0) {
            if (aht20_read(aht_fd, &rh) == 0) ok |= 2;
        }
        if (pir) {
            if (pir_read(pir, &motion) == 0) ok |= 4;
        }

        if (ok) {
            int fd = open(LOG_FILE_FMT, O_WRONLY | O_CREAT | O_APPEND, 0644);
            if (fd < 0) {
                fprintf(stderr, "open(%s): %s\n", LOG_FILE_FMT, strerror(errno));
            } else {
                log_write(fd, temp, rh, motion);
                close(fd);
            }
        } else {
            fprintf(stderr, "Sensor read failed; skipping log entry.\n");
        }

        /* sleep but wake promptly on signal */
        for (int s = 0; s < SAMPLE_INTERVAL_S && g_running; s++)
            sleep(1);
    }

cleanup:
    if (pir) gpiod_line_release(pir);
    if (chip) gpiod_chip_close(chip);
    if (tmp_fd >= 0) close(tmp_fd);
    if (aht_fd >= 0) close(aht_fd);
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

