/*
 * RGB CPU-load indicator for Raspberry Pi Zero W
 *
 * Wiring (common-anode RGB LED):
 *   Red cathode  -> GPIO17 (physical pin 11)
 *   Green cathode-> GPIO22 (physical pin 15)
 *   Blue cathode -> GPIO27 (physical pin 13)
 *   Common cathode -> 3.3 V (external supply recommended)
 *
 * Build:  gcc -O2 -Wall -Wextra -o cpu_rgb cpu_rgb.c -lpigpio -lrt
 * Run:    sudo ./cpu_rgb
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <pigpio.h>

#define RED_PIN    17
#define GREEN_PIN  22
#define BLUE_PIN   27

#define SAMPLE_INTERVAL_US  500000   /* 500 ms */
#define PWM_RANGE          256       /* 0–255 clamped */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0)
        perror("warning: sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) != 0)
        perror("warning: sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* CPU load                                                         */
/* ------------------------------------------------------------------ */
static double calculate_cpu_load(void)
{
    FILE *fp = fopen("/proc/stat", "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening /proc/stat: %s\n", strerror(errno));
        return -1.0;
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) == NULL) {
        fprintf(stderr, "Error reading /proc/stat: %s\n", strerror(errno));
        fclose(fp);
        return -1.0;
    }
    fclose(fp);

    /* line should be:  cpu  user  nice  system  idle  iowait  irq  softirq  steal  guest  guest_nice  ... */
    if (strncmp(line, "cpu ", 4) != 0) {
        fprintf(stderr, "Unexpected format in /proc/stat\n");
        return -1.0;
    }

    unsigned long long user  = 0, nice = 0, system = 0, idle = 0, iowait = 0, irq = 0, softirq = 0, steal = 0;
    int ret = sscanf(line, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu",
                     &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal);
    if (ret != 8) {
        fprintf(stderr, "Unexpected format in /proc/stat (got %d fields)\n", ret);
        return -1.0;
    }

    unsigned long long prev_idle = idle + iowait;
    unsigned long long prev_total = user + nice + system + idle + iowait + irq + softirq + steal;

    if (prev_total == 0) {
        fprintf(stderr, "Warning: total CPU time is zero; cannot compute load\n");
        return -1.0;
    }

    unsigned long long cur_total = idle + iowait + user + nice + system + irq + softirq + steal;
    unsigned long long cur_idle = idle + iowait;

    unsigned long long total_diff = cur_total - prev_total;
    unsigned long long idle_diff  = cur_idle  - prev_idle;

    if (total_diff == 0) {
        fprintf(stderr, "Warning: no CPU time elapsed; cannot compute load\n");
        return -1.0;
    }

    return (double)(total_diff - idle_diff) / (double)total_diff * 100.0;
}

/* ------------------------------------------------------------------ */
/* Color mapping                                                      */
/* ------------------------------------------------------------------ */
static void map_cpu_to_color(double cpu, int *r, int *g, int *b)
{
    if (cpu < 0.0) cpu = 0.0;
    if (cpu > 100.0) cpu = 100.0;

    if (cpu <= 50.0) {
        *r = (int)(cpu * 5.0);
        *g = 255;
        *b = 0;
    } else {
        *r = 255;
        *g = (int)((100.0 - cpu) * 5.0);
        *b = 0;
    }
}

/* ------------------------------------------------------------------ */
/* LED control via pigpio hardware PWM                                  */
/* ------------------------------------------------------------------ */
static void set_led_color(int r, int g, int b)
{
    if (r < 0)   r = 0; if (r > PWM_RANGE)   r = PWM_RANGE;
    if (g < 0)   g = 0; if (g > PWM_RANGE)   g = PWM_RANGE;
    if (b < 0)   b = 0; if (b > PWM_RANGE)   b = PWM_RANGE;

    if (gpioHardwarePWM(RED_PIN, r, 0) != 0)
        fprintf(stderr, "Warning: gpioHardwarePWM(RED) failed\n");
    if (gpioHardwarePWM(GREEN_PIN, g, 0) != 0)
        fprintf(stderr, "Warning: gpioHardwarePWM(GREEN) failed\n");
    if (gpioHardwarePWM(BLUE_PIN, b, 0) != 0)
        fprintf(stderr, "Warning: gpioHardwarePWM(BLUE) failed\n");
}

static void led_off(void)
{
    gpioHardwarePWM(RED_PIN, 0, 0);
    gpioHardwarePWM(GREEN_PIN, 0, 0);
    gpioHardwarePWM(BLUE_PIN, 0, 0);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    install_signal_handlers();

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure PWM range and frequency for all three channels */
    if (gpioHardwarePWM_RANGE(RED_PIN, PWM_RANGE) != 0 ||
        gpioHardwarePWM_RANGE(GREEN_PIN, PWM_RANGE) != 0 ||
        gpioHardwarePWM_RANGE(BLUE_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range on any channel\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Start with LED off */
    led_off();

    while (g_running) {
        double cpu = calculate_cpu_load();
        if (cpu < 0.0) {
            fprintf(stderr, "CPU load calculation failed; retrying in 1 s\n");
            sleep(1);
            continue;
        }

        int r, g, b;
        map_cpu_to_color(cpu, &r, &g, &b);
        set_led_color(r, g, b);

        usleep(SAMPLE_INTERVAL_US);
    }

    /* Graceful shutdown */
    led_off();
    gpioTerminate();
    return EXIT_SUCCESS;
}

