#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <stdint.h>
#include <stdbool.h>

#define BMP280_I2C_ADDR 0x76
#define I2C_BUS "/dev/i2c-1"
#define UDP_SERVER_IP "192.168.1.100"
#define UDP_SERVER_PORT 5000
#define SAMPLE_INTERVAL_SEC 5

#define BMP280_REG_ID 0xD0
#define BMP280_REG_RESET 0xE0
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_CALIB 0x88

#define BMP280_CHIP_ID 0x58
#define BMP280_RESET_CMD 0xB6

typedef struct {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
} bmp280_calib_t;

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static int g_udp_sock = -1;
static bmp280_calib_t g_calib;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != (ssize_t)len) return -1;
    return 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, buf, len) != (ssize_t)len) return -1;
    return 0;
}

static int bmp280_read_calibration(int fd, bmp280_calib_t *cal) {
    uint8_t buf[24];
    if (i2c_read_block(fd, BMP280_REG_CALIB, buf, sizeof(buf)) < 0) return -1;
    cal->dig_T1 = (uint16_t)(buf[1] << 8 | buf[0]);
    cal->dig_T2 = (int16_t)(buf[3] << 8 | buf[2]);
    cal->dig_T3 = (int16_t)(buf[5] << 8 | buf[4]);
    cal->dig_P1 = (uint16_t)(buf[7] << 8 | buf[6]);
    cal->dig_P2 = (int16_t)(buf[9] << 8 | buf[8]);
    cal->dig_P3 = (int16_t)(buf[11] << 8 | buf[10]);
    cal->dig_P4 = (int16_t)(buf[13] << 8 | buf[12]);
    cal->dig_P5 = (int16_t)(buf[15] << 8 | buf[14]);
    cal->dig_P6 = (int16_t)(buf[17] << 8 | buf[16]);
    cal->dig_P7 = (int16_t)(buf[19] << 8 | buf[18]);
    cal->dig_P8 = (int16_t)(buf[21] << 8 | buf[20]);
    cal->dig_P9 = (int16_t)(buf[23] << 8 | buf[22]);
    return 0;
}

static int bmp280_init(int fd) {
    uint8_t id;
    if (i2c_read_reg(fd, BMP280_REG_ID, &id, 1) < 0) {
        fprintf(stderr, "Error: Failed to read chip ID: %s\n", strerror(errno));
        return -1;
    }
    if (id != BMP280_CHIP_ID) {
        fprintf(stderr, "Error: Invalid chip ID 0x%02X (expected 0x%02X)\n", id, BMP280_CHIP_ID);
        return -1;
    }
    if (i2c_write_reg(fd, BMP280_REG_RESET, BMP280_RESET_CMD) < 0) {
        fprintf(stderr, "Error: Failed to reset sensor: %s\n", strerror(errno));
        return -1;
    }
    usleep(2000);
    if (bmp280_read_calibration(fd, &g_calib) < 0) {
        fprintf(stderr, "Error: Failed to read calibration data: %s\n", strerror(errno));
        return -1;
    }
    if (i2c_write_reg(fd, BMP280_REG_CONFIG, 0x00) < 0) return -1;
    if (i2c_write_reg(fd, BMP280_REG_CTRL_MEAS, 0x27) < 0) return -1;
    return 0;
}

static int bmp280_read_raw(int fd, int32_t *raw_t, int32_t *raw_p) {
    uint8_t buf[6];
    if (i2c_read_block(fd, BMP280_REG_PRESS_MSB, buf, 6) < 0) return -1;
    *raw_p = (int32_t)((buf[0] << 12) | (buf[1] << 4) | (buf[2] >> 4));
    *raw_t = (int32_t)((buf[3] << 12) | (buf[4] << 4) | (buf[5] >> 4));
    return 0;
}

static int bmp280_compute(int32_t raw_t, int32_t raw_p, const bmp280_calib_t *cal, double *t, double *p) {
    int32_t var1, var2;
    var1 = ((((raw_t >> 3) - ((int32_t)cal->dig_T1 << 1))) * ((int32_t)cal->dig_T2)) >> 11;
    var2 = (((((raw_t >> 4) - ((int32_t)cal->dig_T1)) * ((raw_t >> 4) - ((int32_t)cal->dig_T1))) >> 12) * ((int32_t)cal->dig_T3)) >> 14;
    int32_t t_fine = var1 + var2;
    *t = (double)((t_fine * 5 + 128) >> 8) / 100.0;
    int64_t v1, v2, p_acc;
    v1 = ((int64_t)t_fine) - 128000;
    v2 = v1 * v1 * (int64_t)cal->dig_P6;
    v2 = v2 + ((v1 * (int64_t)cal->dig_P5) << 17);
    v2 = v2 + (((int64_t)cal->dig_P4) << 35);
    v1 = ((v1 * v1 * (int64_t)cal->dig_P3) >> 8) + ((v1 * (int64_t)cal->dig_P2) << 12);
    v1 = (((((int64_t)1) << 47) + v1)) * ((int64_t)cal->dig_P1) >> 33;
    if (v1 == 0) return -1;
    p_acc = 1048576 - raw_p;
    p_acc = (((p_acc << 31) - v2) * 3125) / v1;
    v1 = (((int64_t)cal->dig_P9) * (p_acc >> 13) * (p_acc >> 13)) >> 25;
    v2 = (((int64_t)cal->dig_P8) * p_acc) >> 19;
    p_acc = ((p_acc + v1 + v2) >> 8) + (((int64_t)cal->dig_P7) << 4);
    *p = (double)p_acc / 256.0;
    return 0;
}

static int format_json(double temp, double press, char *buf, size_t len) {
    int n = snprintf(buf, len, "{\"temperature\": %.2f, \"pressure\": %.2f}", temp, press);
    return (n < 0 || n >= (int)len) ? -1 : 0;
}

static int send_udp(const char *json, int sock) {
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port = htons(UDP_SERVER_PORT);
    if (inet_pton(AF_INET, UDP_SERVER_IP, &addr.sin_addr) <= 0) {
        fprintf(stderr, "Error: Invalid IP address: %s\n", strerror(errno));
        return -1;
    }
    if (sendto(sock, json, strlen(json), 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        fprintf(stderr, "Error: Failed to send UDP: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open i2c bus");
        return 1;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, BMP280_I2C_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(g_i2c_fd);
        return 1;
    }
    if (bmp280_init(g_i2c_fd) < 0) {
        fprintf(stderr, "Error: BMP280 initialization failed\n");
        close(g_i2c_fd);
        return 1;
    }
    g_udp_sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (g_udp_sock < 0) {
        perror("socket");
        close(g_i2c_fd);
        return 1;
    }
    while (g_running) {
        int32_t raw_t, raw_p;
        if (bmp280_read_raw(g_i2c_fd, &raw_t, &raw_p) < 0) {
            fprintf(stderr, "Error: Failed to read raw data: %s\n", strerror(errno));
        } else {
            double temp, press;
            if (bmp280_compute(raw_t, raw_p, &g_calib, &temp, &press) < 0) {
                fprintf(stderr, "Error: Failed to compute sensor values\n");
            } else {
                char json[128];
                if (format_json(temp, press, json, sizeof(json)) == 0) {
                    if (send_udp(json, g_udp_sock) < 0) {
                        fprintf(stderr, "Error: Failed to send UDP\n");
                    }
                } else {
                    fprintf(stderr, "Error: JSON formatting failed\n");
                }
            }
        }
        for (int i = 0; i < SAMPLE_INTERVAL_SEC && g_running; i++) {
            sleep(1);
        }
    }
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    if (g_udp_sock >= 0) close(g_udp_sock);
    return 0;
}

