/*
 * PWM fan control with MAX31855 temperature sensor on Raspberry Pi 4.
 *
 * Hardware:
 *   MAX31855 SPI0 CE0  ->  GPIO8  (BCM)
 *   MAX31855 VCC      ->  3.3 V
 *   MAX31855 GND      ->  GND
 *   MAX31855 Thermocouple -> 4.7 k thermocouple
 *   Fan PWM output    ->  GPIO18 (BCM) hardware PWM, 1 kHz, 0-255 duty
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o fan_ctrl fan_ctrl.c -lpigpio -lrt
 *   (pigpio must be installed; run as root or with appropriate permissions.)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FAN_GPIO          18
#define SPI_CHANNEL       0          /* SPI0 CE0 */
#define SPI_SPEED_HZ      500000     /* 500 kHz */
#define SPI_FLAGS         0          /* mode 0, active-low CE */
#define PWM_FREQUENCY     1000       /* 1 kHz */
#define PWM_RANGE         255        /* 8-bit duty resolution */
#define SAMPLE_PERIOD_US  1000000    /* 1 second */
#define BUFFER_SIZE       20

/* Piecewise fan curve (duty cycle %). */
static const float temp_to_duty[4] = {
    0.0f,   /* below 25 °C  -> 0 % */
    0.0f,   /* 25 °C .. 40 °C -> 0 % .. 50 % */
    50.0f,  /* 40 °C .. 60 °C -> 50 % .. 200 % */
    100.0f  /* above 60 °C -> 100 % */
};

/* ------------------------------------------------------------------ */
/* Circular buffer                                                      */
/* ------------------------------------------------------------------ */

typedef struct {
    time_t timestamp;
    float  temperature;
    int    duty_cycle;
} TemperatureData;

static TemperatureData circular_buffer[BUFFER_SIZE];
static int buffer_index = 0;

static void buffer_add(const TemperatureData *data)
{
    circular_buffer[buffer_index] = *data;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

static void buffer_print(const TemperatureData *data, int count)
{
    printf("\n--- Temperature Log (%d entries) ---\n", count);
    for (int i = 0; i < count; i++) {
        int idx = (buffer_index - 1 - i + BUFFER_SIZE) % BUFFER_SIZE;
        char ts[32];
        struct tm tm_info;
        localtime_r(&data[idx].timestamp, &tm_info);
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
        printf("[%s] Temp: %.2f °C  Duty: %d\n",
               ts, data[idx].temperature, data[idx].duty_cycle);
    }
    printf("--- End of log ---\n\n");
}

/* ------------------------------------------------------------------ */
/* MAX31855 driver (pigpio SPI)                                       */
/* ------------------------------------------------------------------ */

/*
 * MAX31855 32-bit SPI payload (MSB first):
 *   D[31:18]  Thermocouple temperature, signed 14-bit, 0.25 °C / LSB
 *   D[17]     Reserved
 *   D[16]     Fault bit
 *   D[15:4]   Internal cold-junction temperature, signed 12-bit, 0.0625 °C / LSB
 *   D[3]      Reserved
 *   D[2]      SCV fault (short to VCC)
 *   D[1]      SCG fault (short to GND)
 *   D[0]      GND fault
 */
static int max31855_read(int spi_handle, float *temperature)
{
    char tx[4] = {0, 0, 0, 0};
    char rx[4] = {0, 0, 0, 0};

    int ret = spiXfer(spi_handle, tx, rx, 4);
    if (ret != 4) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    uint32_t raw = ((uint32_t)(uint8_t)rx[0] << 24) |
                   ((uint32_t)(uint8_t)rx[1] << 16) |
                   ((uint32_t)(uint8_t)rx[2] <<  8) |
                   ((uint32_t)(uint8_t)rx[3]);

    if (raw & 0x00010000) {                 /* fault bit */
        if (raw & 0x00000004) fprintf(stderr, "MAX31855 fault: short to VCC\n");
        if (raw & 0x00000002) fprintf(stderr, "MAX31855 fault: short to GND\n");
        if (raw & 0x00000001) fprintf(stderr, "MAX31855 fault: short to GND\n");
        return -2;
    }

    /* Thermocouple temperature: bits 31:18, signed 14-bit */
    int16_t thermocouple_raw = (int16_t)((raw >> 18) & 0x3FFF);
    if (thermocouple_raw & 0x2000) {
        thermocouple_raw |= 0xC000;       /* sign-extend */
    }
    *temperature = (float)thermocouple_raw * 0.25f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Fan control                                                        */
/* ------------------------------------------------------------------ */

static int calculate_duty(float temperature)
{
    if (temperature < 25.0f) return 0;
    if (temperature < 40.0f) return (int)((temperature - 25.0f) * 2.0f);
    if (temperature < 60.0f) return (int)((temperature - 40.0f) * 5.0f + 50.0f);
    return 255;
}

static int set_fan_pwm(int duty_cycle)
{
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 255) duty_cycle = 255;
    if (gpioPWM(FAN_GPIO, duty_cycle) != 0) {
        fprintf(stderr, "gpioPWM failed for duty %d\n", duty_cycle);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Signal handling                                                    */
/* ------------------------------------------------------------------ */

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */

int main(void)
{
