    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        spiClose(spi_handle);
        gpioPWM(FAN_GPIO, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

