#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

#define BMP180_ADDR 0x77
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE
#define OSS 3
#define INTERRUPT_GPIO 2
#define LOG_FILE "altitude_log.txt"

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t logging_active = 0;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

static int16_t read_s16(int handle, uint8_t reg) {
    char buf[2];
    if (i2cReadI2CBlockData(handle, reg, buf, 2) != 2) return -1;
    return (int16_t)((buf[0] << 8) | buf[1]);
}
static uint16_t read_u16(int handle, uint8_t reg) {
    char buf[2];
    if (i2cReadI2CBlockData(handle, reg, buf, 2) != 2) return 0;
    return (uint16_t)((buf[0] << 8) | buf[1]);
}

static int read_calibration_data(int handle) {
    ac1 = read_s16(handle, BMP180_REG_CAL_AC1);
    ac2 = read_s16(handle, BMP180_REG_CAL_AC2);
    ac3 = read_s16(handle, BMP180_REG_CAL_AC3);
    ac4 = read_u16(handle, BMP180_REG_CAL_AC4);
    ac5 = read_u16(handle, BMP180_REG_CAL_AC5);
    ac6 = read_u16(handle, BMP180_REG_CAL_AC6);
    b1 = read_s16(handle, BMP180_REG_CAL_B1);
    b2 = read_s16(handle, BMP180_REG_CAL_B2);
    mb = read_s16(handle, BMP180_REG_CAL_MB);
    mc = read_s16(handle, BMP180_REG_CAL_MC);
    md = read_s16(handle, BMP180_REG_CAL_MD);
    if (ac1 == -1 || ac2 == -1 || ac3 == -1 || ac4 == 0 || ac5 == 0 || ac6 == 0 ||
        b1 == -1 || b2 == -1 || mb == -1 || mc == -1 || md == -1) {
        fprintf(stderr, "Error: Failed to read calibration data\n");
        return -1;
    }
    return 0;
}

static int read_raw_temperature(int handle, long *ut) {
    char buf[2];
    if (i2cWriteByteData(handle, BMP180_REG_CONTROL, 0x2E) < 0) return -1;
    gpioDelay(5000);
    if (i2cReadI2CBlockData(handle, BMP180_REG_MSB, buf, 2) != 2) return -1;
    *ut = (long)((buf[0] << 8) | buf[1]);
    return 0;
}

static int read_raw_pressure(int handle, long *up) {
    char buf[3];
    if (i2cWriteByteData(handle, BMP180_REG_CONTROL, 0x34 + (OSS << 6)) < 0) return -1;
    gpioDelay(2000 + (3000 << OSS));
    if (i2cReadI2CBlockData(handle, BMP180_REG_MSB, buf, 3) != 3) return -1;
    *up = ((long)buf[0] << 16 | (long)buf[1] << 8 | (long)buf[2]) >> (8 - OSS);
    return 0;
}

static double calculate_temperature(long ut, long *b5_out) {
    long x1 = ((ut - (long)ac6) * (long)ac5) >> 15;
    long x2 = ((long)mc << 11) / (x1 + (long)md);
    long b5 = x1 + x2;
    if (b5_out) *b5_out = b5;
    return ((b5 + 8) >> 4) / 10.0;
}

static double calculate_pressure(long up, long b5) {
    long b6 = b5 - 4000;
    long x1 = ((long)b2 * ((b6 * b6) >> 12)) >> 11;
    long x2 = ((long)ac2 * b6) >> 11;
    long x3 = x1 + x2;
    long b3 = (((((long)ac1) * 4 + x3) << OSS) + 2) >> 2;
    x1 = ((long)ac3 * b6) >> 13;
    x2 = ((long)b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    unsigned long b4 = ((unsigned long)ac4 * (unsigned long)(x3 + 32768)) >> 15;
    unsigned long b7 = ((unsigned long)up - b3) * (50000 >> OSS);
    long p;
    if (b7 < 0x80000000UL) p = (b7 * 2) / b4;
    else p = (b7 / b4) * 2;
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);
    return (double)p;
}

static void log_data(FILE *fp, double temperature, double pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, pressure);
    fflush(fp);
}

static void interrupt_handler(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)level; (void)tick; (void)user;
    logging_active = !logging_active;
    printf("Logging %s\n", logging_active ? "active" : "inactive");
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        gpioTerminate();
        return 1;
    }
    if (read_calibration_data(i2c_handle) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioSetMode(INTERRUPT_GPIO, PI_INPUT);
    gpioSetPullUpDown(INTERRUPT_GPIO, PI_PUD_UP);
    if (gpioSetISRFuncEx(INTERRUPT_GPIO, FALLING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set interrupt handler\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    printf("BMP180 logging started. Press Ctrl+C to exit.\n");
    while (running) {
        if (logging_active) {
            long ut, up, b5;
            if (read_raw_temperature(i2c_handle, &ut) != 0) {
                fprintf(stderr, "Error: Failed to read temperature\n");
            } else if (read_raw_pressure(i2c_handle, &up) != 0) {
                fprintf(stderr, "Error: Failed to read pressure\n");
            } else {
                double temperature = calculate_temperature(ut, &b5);
                double pressure = calculate_pressure(up, b5);
                log_data(log_file, temperature, pressure);
            }
        }
        gpioDelay(1000000);
    }
    printf("\nShutting down...\n");
    gpioSetISRFuncEx(INTERRUPT_GPIO, FALLING_EDGE, 0, NULL, NULL);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
    return 0;
}

