#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <pigpio.h>

#define BMP180_ADDR 0x77
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE
#define BMP180_OSS 0
#define BMP180_TEMP_CMD 0x2E
#define BMP180_PRESSURE_CMD 0x34 + (OSS << 6)
#define ALERT_GPIO 24
#define BUFFER_SIZE 60
#define DEVIATION_THRESHOLD 5.0
#define SAMPLE_INTERVAL_MS 50

typedef struct {
    time_t timestamp;
    float pressure;
} PressureData;

static PressureData circular_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;
static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_word(int handle, uint8_t reg, int16_t *out) {
    int msb = i2cReadByteData(handle, reg);
    if (msb < 0) return -1;
    int lsb = i2cReadByteData(handle, reg + 1);
    if (lsb < 0) return -1;
    *out = (int16_t)((msb << 8) | lsb);
    return 0;
}

static int read_calibration_data(int handle) {
    if (read_word(handle, BMP180_REG_CAL_AC1, &ac1) < 0) return -1;
    if (read_word(handle, BMP180_REG_CAL_AC2, &ac2) < 0) return -1;
    if (read_word(handle, BMP180_REG_CAL_AC3, &ac3) < 0) return -1;
    if (read_word(handle, BMP180_REG_CAL_AC4, &ac4) < 0) return -1;
    if (read_word(handle, BMP180_REG_CAL_AC5, &ac5) < 0) return -1;
    if (read_word(handle, BMP180_REG_CAL_AC6, &ac6) < 0) return -1;
    if (read_word(handle, BMP180_REG_CAL_B1, &b1) < 0) return -1;
    if (read_word(handle, BMP180_REG_CAL_B2, &b2) < 0) return -1;
    if (read_word(handle, BMP180_REG_CAL_MB, &mb) < 0) return -1;
    if (read_word(handle, BMP180_REG_CAL_MC, &mc) < 0) return -1;
    if (read_word(handle, BMP180_REG_CAL_MD, &md) < 0) return -1;
    return 0;
}

static int read_raw_temperature(int handle, int32_t *raw_temp) {
    if (i2cWriteByteData(handle, BMP180_REG_CONTROL, BMP180_TEMP_CMD) < 0) return -1;
    gpioDelay(5000);
    int msb = i2cReadByteData(handle, BMP180_REG_MSB);
    if (msb < 0) return -1;
    int lsb = i2cReadByteData(handle, BMP180_REG_LSB);
    if (lsb < 0) return -1;
    *raw_temp = (msb << 8) | lsb;
    return 0;
}

static int read_raw_pressure(int handle, int32_t *raw_pressure) {
    if (i2cWriteByteData(handle, BMP180_REG_CONTROL, BMP180_PRESSURE_CMD) < 0) return -1;
    gpioDelay(2000 + (3000 << OSS));
    int msb = i2cReadByteData(handle, BMP180_REG_MSB);
    if (msb < 0) return -1;
    int lsb = i2cReadByteData(handle, BMP180_REG_LSB);
    if (lsb < 0) return -1;
    int xlsb = i2cReadByteData(handle, BMP180_REG_XLSB);
    if (xlsb < 0) return -1;
    *raw_pressure = ((msb << 16) | (lsb << 8) | xlsb) >> (8 - OSS);
    return 0;
}

static float calculate_pressure(int32_t ut, int32_t up, int32_t *b5_out) {
    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + md);
    int32_t b5 = x1 + x2;
    *b5_out = b5;
    int32_t b6 = b5 - 4000;
    int32_t x3 = ((int32_t)b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x4 = ((int32_t)ac2 * b6) >> 11;
    int32_t b3 = (((((int32_t)ac1) * 4 + x3) << OSS) + 2) >> 2;
    uint32_t x5 = ((uint32_t)ac4 * (uint32_t)(x3 + x4 + 32768)) >> 15;
    uint32_t x6 = ((uint32_t)ac5 * b6) >> 13;
    uint32_t b4 = (x5 + x6 + 32768) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> OSS);
    int32_t p;
    if (b7 < 0x80000000) p = (b7 * 2) / b4;
    else p = (b7 / b4) * 2;
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);
    return (float)p / 100.0;
}

static void add_to_buffer(float pressure) {
    circular_buffer[buffer_index].timestamp = time(NULL);
    circular_buffer[buffer_index].pressure = pressure;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
}

static float calculate_average_pressure(void) {
    if (buffer_count == 0) return 0.0;
    float sum = 0.0;
    for (int i = 0; i < buffer_count; i++) {
        sum += circular_buffer[i].pressure;
    }
    return sum / buffer_count;
}

static void trigger_alert(void) {
    gpioWrite(ALERT_GPIO, 1);
    fprintf(stderr, "ALERT: Pressure deviation detected!\n");
}

static void timer_callback(void *user_data) {
    (void)user_data;
    int32_t ut, up, b5;
    if (read_raw_temperature(i2c_handle, &ut) < 0) {
        fprintf(stderr, "Error reading temperature: %s\n", strerror(errno));
        return;
    }
    if (read_raw_pressure(i2c_handle, &up) < 0) {
        fprintf(stderr, "Error reading pressure: %s\n", strerror(errno));
        return;
    }
    float pressure = calculate_pressure(ut, up, &b5);
    add_to_buffer(pressure);
    float avg = calculate_average_pressure();
    if (buffer_count > 0 && (pressure > avg + DEVIATION_THRESHOLD || pressure < avg - DEVIATION_THRESHOLD)) {
        trigger_alert();
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }
    if (read_calibration_data(i2c_handle) < 0) {
        fprintf(stderr, "Error reading calibration data: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioSetMode(ALERT_GPIO, PI_OUTPUT);
    gpioWrite(ALERT_GPIO, 0);
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    if (gpioSetTimerFuncEx(0, SAMPLE_INTERVAL_MS, timer_callback, NULL) < 0) {
        fprintf(stderr, "Error setting timer: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    while (running) {
        gpioDelay(1000000);
    }
    gpioSetTimerFuncEx(0, 0, NULL, NULL);
    gpioWrite(ALERT_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

