    if (i2cWriteByteData(handle, BMP180_REG_CONTROL, BMP180_PRESSURE_CMD) < 0) return -1;
    gpioDelay(2000 + (3000 << OSS));
    int msb = i2cReadByteData(handle, BMP180_REG_MSB);
    if (msb < 0) return -1;
    int lsb = i2cReadByteData(handle, BMP180_REG_LSB);
    if (lsb < 0) return -1;
    int xlsb = i2cReadByteData(handle, BMP180_REG_XLSB);
    if (xlsb < 0) return -1;
    *raw_pressure = ((msb << 16) | (lsb << 8) | xlsb) >> (8 - OSS);
    return 0;
}

static float calculate_pressure(int32_t ut, int32_t up, int32_t *b5_out) {
    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + md);
    int32_t b5 = x1 + x2;
    *b5_out = b5;
    int32_t b6 = b5 - 4000;
    int32_t x3 = ((int32_t)b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x4 = ((int32_t)ac2 * b6) >> 11;
    int32_t b3 = (((((int32_t)ac1) * 4 + x3) << OSS) + 2) >> 2;
    uint32_t x5 = ((uint32_t)ac4 * (uint32_t)(x3 + x4 + 32768)) >> 15;
    uint32_t x6 = ((uint32_t)ac5 * b6) >> 13;
    uint32_t b4 = (x5 + x6 + 32768) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> OSS);
    int32_t p;
    if (b7 < 0x80000000) p = (b7 * 2) / b4;
    else p = (b7 / b4) * 2;
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);
    return (float)p / 100.0;
}

static void add_to_buffer(float pressure) {
    circular_buffer[buffer_index].timestamp = time(NULL);
    circular_buffer[buffer_index].pressure = pressure;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
}

static float calculate_average_pressure(void) {
    if (buffer_count == 0) return 0.0;
    float sum = 0.0;
    for (int i = 0; i < buffer_count; i++) {
        sum += circular_buffer[i].pressure;
    }
    return sum / buffer_count;
}

static void trigger_alert(void) {
    gpioWrite(ALERT_GPIO, 1);
    fprintf(stderr, "ALERT: Pressure deviation detected!\n");
}

static void timer_callback(void *user_data) {
    (void)user_data;
    int32_t ut, up, b5;
    if (read_raw_temperature(i2c_handle, &ut) < 0) {
