            }
            if (log_data(temperature, duty) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        }

        for (int i = 0; i < LOG_INTERVAL && running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
    printf("Fan stopped and pigpio terminated.\n");
    return 0;
}

