/*
 * PID temperature regulation with MAX31865 PT100 RTD on SPI0 CE0,
 * 430-ohm reference resistor, 1 kHz hardware PWM on GPIO18, 500 kHz SPI.
 * Failsafe: heater off if temperature exceeds 80 C, SPI error, or fault.
 * SIGINT/SIGTERM: clean shutdown.
 */
#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <math.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define CONFIG_FILE "config.json"
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 500000
#define SPI_BITS 8
#define SPI_MODE 1
#define PWM_GPIO 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000
#define PWM_DUTY_MAX 100
#define PWM_DUTY_MIN 0
#define PWM_DUTY_OFF 0
#define PWM_PERIOD_US (1000000 / PWM_FREQUENCY)
#define LOOP_DELAY_US 100000
#define MAX_TEMP 80.0
#define MAX_RTD_R 430.0
#define PT100_R 100.0
#define PT100_A 0.0039083
#define PT100_B (-5.775e-7)
#define MAX_SPI_RETRIES 3
#define MAX_SPI_RETRY_DELAY_US 10000

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;
static double g_target_temp = 25.0;
static double g_kp = 1.0;
static double g_ki = 0.1;
static double g_kd = 0.01;
static double g_integral = 0.0;
static double g_prev_error = 0.0;
static double g_last_rtd = 0.0;
static double g_last_pid_output = 0.0;
static bool g_failsafe_active = false;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void log_error(const char *msg) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "[%s] ERROR: %s (errno: %s)\n", ts, msg, strerror(errno));
}

static int spi_init(void) {
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        log_error("open SPI device failed");
        return -1;
    }
    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        log_error("ioctl SPI_IOC_WR_MODE failed");
        close(g_spi_fd); g_spi_fd = -1; return -1;
    }
    uint8_t bits = SPI_BITS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        log_error("ioctl SPI_IOC_WR_BITS_PER_WORD failed");
        close(g_spi_fd); g_spi_fd = -1; return -1;
    }
    uint32_t speed = SPI_SPEED;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        log_error("ioctl SPI_IOC_WR_MAX_SPEED_HZ failed");
        close(g_spi_fd); g_spi_fd = -1; return -1;
    }
    return 0;
}

static int spi_read_rtd(double *rtd_out) {
    uint8_t tx[4] = {0, 0, 0, 0};
    uint8_t rx[4] = {0, 0, 0, 0};
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = 4;
    tr.speed_hz = SPI_SPEED;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs = 0;
    tr.cs_change = 0;
    for (int attempt = 0; attempt < MAX_SPI_RETRIES; attempt++) {
        if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) >= 0) {
            uint32_t raw = ((uint32_t)rx[0] << 24) |
                           ((uint32_t)rx[1] << 16) |
                           ((uint32_t)rx[2] << 8)  |
                           ((uint32_t)rx[3]);
            if (raw & 0x00010000) {
                uint32_t fault = raw & 0x00000007;
                if (fault & 0x01) {
                    log_error("MAX31865 fault bit 0 (sensor fault)");
                    return -1;
                }
