#define PWM_RANGE 1000
#define PWM_DUTY_MAX 100
#define PWM_DUTY_MIN 0
#define PWM_DUTY_OFF 0
#define PWM_PERIOD_US (1000000 / PWM_FREQUENCY)
#define LOOP_DELAY_US 100000
#define MAX_TEMP 80.0
#define MAX_RTD_R 430.0
