                return -1;
            }
            *rtd_out = rtd;
            return 0;
        }
        if (attempt < MAX_SPI_RETRIES - 1) {
            usleep(MAX_SPI_RETRY_DELAY_US);
        }
    }
    log_error("SPI transfer failed after retries");
    return -1;
}

