/*
 * Heater control with MAX31855 thermocouple amplifier and PI controller.
 *
 * Hardware (Raspberry Pi 3 Model B+):
 *   MAX31855 SPI0 CE0  -> GPIO8  (physical pin 24)
 *   MAX31855 MISO    -> GPIO9  (physical pin 21)
 *   MAX31855 MOSI    -> GPIO10 (physical pin 19)
 *   MAX31855 SCLK    -> GPIO11 (physical pin 23)
 *   Solid-state relay  -> GPIO17 (physical pin 11) with PWM
 *
 * Build:  gcc -O2 -Wall -Wextra -o heater_control heater_control.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define SPI_CHANNEL      0          /* SPI0 CE0 */
#define SPI_SPEED        2000000    /* 2 MHz */
#define SPI_FLAGS        0          /* Mode 0, active-low CS */

#define HEATER_GPIO      17
#define PWM_FREQUENCY    1000       /* 1 kHz */
#define PWM_RANGE        1000       /* duty 0..1000 */

#define TARGET_TEMP      25.0f
#define MAX_DUTY_CYCLE   80
#define LOG_FILE         "heater_log.csv"
#define SAMPLE_PERIOD_US 1000000    /* 1 s */

/* ------------------------------------------------------------------ */
/* Globals                                                            */
/* ------------------------------------------------------------------ */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                    */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */

static void log_data(float temperature, int duty_cycle)
{
    if (!g_log)
        return;

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(g_log, "%s,%.2f,%d\n", ts, temperature, duty_cycle);
    fflush(g_log);
}

/* ------------------------------------------------------------------ */
/* MAX31855 read                                                       */
/* ------------------------------------------------------------------ */

/*
 * MAX31855 32-bit SPI payload (MSB first):
 *   D[31:18]  Thermocouple temperature (0.25 °C / LSB)
 *   D[17]     Reserved
 *   D[16]     Fault bit
 *   D[15:4]   Internal reference-junction temp (0.0625 °C / LSB)
 *   D[3]      SCV fault (short to VCC)
 *   D[2]      OC  fault (open circuit)
 *   D[1]      GND fault (short to GND)
 *   D[0]      GND fault (short to VCC)
 */
static int read_max31855(int spi_handle, float *temperature)
{
    char rx[4] = {0, 0, 0, 0};
    int  bytes = spiRead(spi_handle, rx, 4);
    if (bytes != 4) {
        fprintf(stderr, "SPI read failed: expected 4 bytes, got %d\n", bytes);
        return -1;
    }

    uint32_t raw = ((uint32_t)(uint8_t)rx[0] << 24) |
                   ((uint32_t)(uint8_t)rx[1] << 16) |
                   ((uint32_t)(uint8_t)rx[2] <<  8) |
                   ((uint32_t)(uint8_t)rx[3]);

    if (raw & 0x00010000) {                 /* fault bit */
        if (raw & 0x00000004) fprintf(stderr, "MAX31855 fault: short to VCC\n");
        if (raw & 0x00000002) fprintf(stderr, "MAX31855 fault: open circuit\n");
        if (raw & 0x00000001) fprintf(stderr, "MAX31855 fault: short to GND\n");
        if (raw & 0x00000008) fprintf(stderr, "MAX31855 fault: short to VCC\n");
        return -2;                          /* fault */
    }

    int16_t temp_raw = (int16_t)(raw >> 18); /* D[31:18] */
    *temperature = (float)temp_raw * 0.25f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* PI controller with anti-windup                                      */
/* ------------------------------------------------------------------ */

static int pi_control(float current_temp, float target_temp,
                      int *duty_cycle, float *integral,
                      float *prev_error, float *prev_integral)
{
    float error = target_temp - current_temp;

    /* Anti-windup: clamp integral to prevent excessive overshoot */
    float integral_limit = 100.0f;
    float new_integral = *integral + error;
    if (new_integral > integral_limit) new_integral = integral_limit;
    if (new_integral < -integral_limit) new_integral = -integral_limit;

    *integral = new_integral;

    /* PI output */
    float output = *integral;

    /* Clamp output to safe duty cycle range */
    if (output > (float)MAX_DUTY_CYCLE) output = (float)MAX_DUTY_CYCLE;
    if (output < 0.0f) output = 0.0f;

    /* Update state */
    *prev_error = error;
    *prev_integral = new_integral;

    /* Convert duty cycle (0..100) to PWM duty (0..PWM_RANGE) */
    int duty = (int)(output * 10.0f);   /* 0..1000 */
    if (duty > PWM_RANGE) duty = PWM_RANGE;
    if (duty < 0) duty = 0;

    *duty_cycle = duty;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Heater control                                                      */
/* ------------------------------------------------------------------ */

static int heater_control(int duty_cycle)
{
    if (gpioPWM(HEATER_GPIO, duty_cycle) < 0) {
        fprintf(stderr, "gpioPWM failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */

static void cleanup(void)
{
    /* Turn off heater */
    if (gpioInitialise() >= 0) {
        gpioPWM(HEATER_GPIO, 0);
        gpioTerminate();
    }

    if (g_log) {
        fclose(g_log);
        g_log = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Heater GPIO setup --- */
    if (gpioSetMode(HEATER_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d) failed\n", HEATER_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY) < 0) {
