#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RED_PIN    17
#define GREEN_PIN  18
#define BLUE_PIN   27
#define PWM_RANGE  255
#define TEMP_FILE  "cpu_temp.txt"
#define POLL_US    500000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int set_pwm(int pin, int duty)
{
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;
    if (gpioPWM(pin, duty) < 0) {
        fprintf(stderr, "gpioPWM failed on pin %d: %s\n", pin, strerror(errno));
        return -1;
    }
    return 0;
}

static void set_led_color(int red, int green, int blue)
{
    set_pwm(RED_PIN,   PWM_RANGE - red);
    set_pwm(GREEN_PIN, PWM_RANGE - green);
    set_pwm(BLUE_PIN,  PWM_RANGE - blue);
}

static int read_cpu_temp(double *temp)
{
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", TEMP_FILE, strerror(errno));
        return -1;
    }

    int rc = fscanf(fp, "%lf", temp);
    if (rc != 1) {
        fprintf(stderr, "Failed to parse temperature from %s\n", TEMP_FILE);
        fclose(fp);
        return -1;
    }

    if (ferror(fp)) {
        fprintf(stderr, "Read error on %s: %s\n", TEMP_FILE, strerror(errno));
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

static void cleanup(void)
{
    set_pwm(RED_PIN,   PWM_RANGE);
    set_pwm(GREEN_PIN, PWM_RANGE);
    set_pwm(BLUE_PIN,  PWM_RANGE);
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(RED_PIN,   PI_OUTPUT) != 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(BLUE_PIN,  PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        cleanup();
        return 1;
    }

    if (gpioSetPWMrange(RED_PIN,   PWM_RANGE) != 0 ||
        gpioSetPWMrange(GREEN_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(BLUE_PIN,  PWM_RANGE) != 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        cleanup();
        return 1;
    }

    while (g_running) {
        double temp;
        if (read_cpu_temp(&temp) != 0) {
            fprintf(stderr, "Temperature read failed; skipping cycle\n");
        } else {
            int red, green, blue;
            if (temp < 40000.0) {
                red = 0; green = 0; blue = 255;
            } else if (temp < 60000.0) {
                red = 0; green = 255; blue = 0;
            } else {
                red = 255; green = 0; blue = 0;
            }
            set_led_color(red, green, blue);
            printf("Temperature: %.2f m°C  (R:%d G:%d B:%d)\n",
                   temp, red, green, blue);
            fflush(stdout);
        }
        usleep(POLL_US);
    }

    cleanup();
    return 0;
}

