/*
 * DHT22 -> HTTP JSON payload for Raspberry Pi 3 Model B+
 * Sensor data line : GPIO4 (BCM, physical pin 7)
 * HTTP endpoint   : http://yourserver.com/api/humidity
 *
 * Build: gcc -O2 -Wall -Wextra -o dht22_http dht22_http.c
 */

#define _POSIX_C_SOURCE 200809L

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <netdb.h>

#define DHT22_PIN        4
#define HTTP_HOST        "yourserver.com"
#define HTTP_PORT        80
#define HTTP_PATH        "/api/humidity"
#define MAX_RETRIES      3
#define MAX_RETRIES_DELAY 5
#define DHT22_START_LOW  1000   /* microseconds */
#define DHT22_START_HIGH 30     /* microseconds */
#define DHT22_RESP_LOW   80     /* microseconds */
#define DHT22_RESP_HIGH  80     /* microseconds */
#define DHT22_BIT_LOW   50     /* microseconds */
#define DHT22_BIT_HIGH  70     /* microseconds */
#define DHT22_TIMEOUT   1000   /* microseconds */

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static void sleep_us(unsigned int us)
{
    struct timespec ts = {
        .tv_sec  = us / 1000000U,
        .tv_nsec = (long)(us % 1000000U) * 1000L
    };
    nanosleep(&ts, NULL);
}

static void sleep_ms(unsigned int ms)
{
    sleep_us((unsigned int)(ms * 1000U));
}

/*
 * Wait for the line to reach the requested level, or return false if
 * the timeout elapses.
 */
static bool wait_level(int pin, int level, unsigned int timeout_us)
{
    unsigned int elapsed = 0;
    while (elapsed < timeout_us) {
        if (pin & level) return true;
        sleep_us(1);
        elapsed++;
    }
    return false;
}

/*
 * Read a bit from the DHT22 response.
 * Returns 0 or 1 on success, -1 on timeout.
 */
static int read_dht22_bit(int pin)
{
    /* Wait for the low phase of a 50 us transition */
    if (!wait_level(pin, 0, DHT22_TIMEOUT)) {
        fprintf(stderr, "DHT22: timeout waiting for response low\n");
        return -1;
    }

    /* Measure the high pulse width: ~26-28 us => '0', ~70 us => '1' */
    unsigned int high_us = 0;
    while (pin & 1) {
        sleep_us(1);
        high_us++;
        if (high_us >= DHT22_TIMEOUT) {
            fprintf(stderr, "DHT22: timeout waiting for response high\n");
            return -1;
        }
    }

    return (high_us > 50) ? 1 : 0;
}

/*
 * Read the 40-bit DHT22 payload.
 * Returns 0 on success, -1 on timeout or checksum error.
 */
static int read_dht22(int pin, float *temperature, float *humidity)
{
    uint8_t data[5] = {0};
    int bit_idx = 0;

    /* --- Start signal: pull low for >= 1 ms, then high for 30 us --- */
    if (pin & 0) {
        if (pin & 1) {
            fprintf(stderr, "DHT22: failed to pull line low (sensor absent?)\n");
            return -1;
        }
        sleep_us(DHT22_START_LOW);
    }
    if (pin & 1) {
        if (pin & 0) {
            fprintf(stderr, "DHT22: failed to release line high\n");
            return -1;
        }
        sleep_us(DHT22_START_HIGH);
    }

    /* --- Capture 40 data bits --- */
    for (bit_idx = 0; bit_idx < 40; bit_idx++) {
        int bit = read_dht22_bit(pin);
        if (bit < 0) return -1;
        data[bit_idx / 8] <<= 1;
        if (bit) data[bit_idx / 8] |= 1;
    }

    /* --- Checksum validation --- */
    uint8_t checksum = (uint8_t)(data[0] + data[1] + data[2] + data[3]);
    if (checksum != data[4]) {
        fprintf(stderr, "DHT22: checksum mismatch (calc=%u, got=%u)\n",
                checksum, data[4]);
        return -1;
    }

    /* --- Convert --- */
    uint16_t raw_h = (uint16_t)((data[0] << 8) | data[1]);
    uint16_t raw_t = (uint16_t)((data[2] << 8) | data[3]);

    *humidity = (float)raw_h / 10.0f;

    /* Handle negative temperature (bit 15 of raw_t) */
    if (raw_t & 0x8000) {
        *temperature = -(float)(raw_t & 0x7FFF) / 10.0f;
    } else {
        *temperature = (float)raw_t / 10.0f;
    }

    return 0;
}

static int post_data(const char *json)
{
    int sockfd = -1;
    struct addrinfo hints, *res = NULL, *rp;
    char request[1024];
    int ret = -1;

    memset(&hints, 0, sizeof(hints));
    hints.ai_family   = AF_INET;
    hints.ai_socktype = SOCK_STREAM;

    if (getaddrinfo(HTTP_HOST, NULL, &hints, &res) != 0) {
        fprintf(stderr, "getaddrinfo: %s\n", strerror(errno));
        return -1;
    }

    for (rp = res; rp; rp = rp->ai_next) {
        sockfd = socket(rp->ai_family, rp->ai_socktype, rp->ai_protocol);
        if (sockfd < 0) continue;

        if (connect(sockfd, rp->ai_addr, rp->ai_addrlen) == 0) {
            break;
        }
        close(sockfd);
        sockfd = -1;
    }

    freeaddrinfo(res);

    if (sockfd < 0) {
        fprintf(stderr, "connect: %s\n", strerror(errno));
        return -1;
    }

    /* HTTP request: POST /api/humidity with JSON body */
    int body_len = (int)strlen(json);
    int total_len = 1024 + body_len;
    snprintf(request, total_len,
             "POST %s HTTP/1.1\r\n"
             "Host: %s\r\n"
             "Content-Type: application/json\r\n"
             "Content-Length: %d\r\n"
             "Connection: close\r\n"
             "\r\n"
             "%s",
             HTTP_PATH, HTTP_HOST, body_len, json);

    size_t sent = 0;
    while (sent < (size_t)strlen(request)) {
        ssize_t w = send(sockfd, request + sent, strlen(request) - sent, 0);
        if (w <= 0) {
            fprintf(stderr, "send: %s\n", strerror(errno));
            goto cleanup;
        }
        sent += (size_t)w;
    }

    /* Read the HTTP response header to confirm 200 OK */
    char header[1024];
    ssize_t h = recv(sockfd, header, sizeof(header) - 1, 0);
    if (h < 0) {
        fprintf(stderr, "recv: %s\n", strerror(errno));
        goto cleanup;
    }
    if (h == 0) {
        fprintf(stderr, "server closed connection\n");
        goto cleanup;
    }
    header[h] = '\0';

    /* Look for "HTTP/1.[01] 200 OK" */
    if (strstr(header, "200 OK") == NULL) {
        fprintf(stderr, "HTTP error: %s\n", header);
        goto cleanup;
    }

    /* Read the JSON body */
    char body[1024];
    size_t b = 0;
    while (b < body_len) {
        ssize_t r = recv(sockfd, body + b, body_len - b, 0);
        if (r <= 0) {
            fprintf(stderr, "recv: %s\n", strerror(errno));
            goto cleanup;
        }
        b += (size_t)r;
    }

    printf("HTTP response: %s\n", body);
    ret = 0;

