#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <pigpio.h>

#define BMP180_ADDR 0x77
#define I2C_BUS "/dev/i2c-1"
#define BUTTON_GPIO 4
#define LOG_FILE "pressure_log.txt"
#define OSS 3
#define DEBOUNCE_US 200000

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t logging_enabled = 0;
static int i2c_fd = -1;

static int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write(int fd, uint8_t *buf, size_t len) {
    if (write(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "I2C read failed: expected %zu bytes, got %zd (%s)\n",
                len, n, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_calibration_data(int fd) {
    uint8_t reg;
    uint8_t data[22];

    reg = 0xAA;
    if (i2c_write(fd, &reg, 1) < 0) return -1;
    if (i2c_read(fd, data, 22) < 0) return -1;

    ac1 = (int16_t)((data[0] << 8) | data[1]);
    ac2 = (int16_t)((data[2] << 8) | data[3]);
    ac3 = (int16_t)((data[4] << 8) | data[5]);
    ac4 = (uint16_t)((data[6] << 8) | data[7]);
    ac5 = (uint16_t)((data[8] << 8) | data[9]);
    ac6 = (uint16_t)((data[10] << 8) | data[11]);
    b1  = (int16_t)((data[12] << 8) | data[13]);
    b2  = (int16_t)((data[14] << 8) | data[15]);
    mb  = (int16_t)((data[16] << 8) | data[17]);
    mc  = (int16_t)((data[18] << 8) | data[19]);
    md  = (int16_t)((data[20] << 8) | data[21]);

    if (ac1 == 0 || ac1 == -1 || ac2 == 0 || ac2 == -1 || ac3 == 0 || ac3 == -1) {
        fprintf(stderr, "Invalid calibration data (sensor absent or bus error)\n");
        return -1;
    }
    return 0;
}

static int read_raw_temperature(int fd, int32_t *ut) {
    uint8_t reg = 0xF4;
    uint8_t cmd[2] = {reg, 0x2E};
    uint8_t data[2];

    if (i2c_write(fd, cmd, 2) < 0) return -1;
    gpioDelay(5000);
    if (i2c_read(fd, data, 2) < 0) return -1;
    *ut = (int32_t)((data[0] << 8) | data[1]);
    return 0;
}

static int read_raw_pressure(int fd, int32_t *up) {
    uint8_t reg = 0xF6;
    uint8_t cmd[2] = {reg, 0x34 + (OSS << 6)};
    uint8_t data[3];

    if (i2c_write(fd, cmd, 2) < 0) return -1;
    gpioDelay(26000);
    if (i2c_read(fd, data, 3) < 0) return -1;
    *up = ((int32_t)data[0] << 16 | (int32_t)data[1] << 8 | data[2]) >> (8 - OSS);
    return 0;
}

static int32_t compute_b5(int32_t ut) {
    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    return x1 + x2;
}

static int32_t compute_pressure(int32_t up, int32_t b5) {
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)ac1) * 4 + x3) << OSS) + 2) >> 2;

    x1 = ((int32_t)ac3 * b6) >> 13;
    x2 = ((int32_t)b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> OSS);

    int32_t p;
    if (b7 < 0x80000000) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);
    return p;
}

static void log_pressure(int32_t pressure) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s, %d hPa\n", ts, pressure / 100);
    fclose(fp);
    printf("Pressure logged: %d hPa\n", pressure / 100);
}

static void button_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)userdata;
    static uint32_t last_tick = 0;
    if (level == 0) {
        if (tick - last_tick > DEBOUNCE_US) {
            logging_enabled = !logging_enabled;
            printf("Logging %s\n", logging_enabled ? "enabled" : "disabled");
        }
        last_tick = tick;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BMP180_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                BMP180_ADDR, strerror(errno));
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    if (read_calibration_data(i2c_fd) < 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(BUTTON_GPIO, PI_INPUT);
    gpioSetPullUpDown(BUTTON_GPIO, PI_PUD_UP);
    if (gpioSetAlertFunc(BUTTON_GPIO, button_callback) < 0) {
        fprintf(stderr, "Failed to set button alert\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    printf("BMP180 ready. Press button on GPIO %d to toggle logging.\n", BUTTON_GPIO);

    while (running) {
        if (logging_enabled) {
            int32_t ut, up, b5, pressure;
            if (read_raw_temperature(i2c_fd, &ut) < 0) {
                fprintf(stderr, "Temperature read failed\n");
            } else if (read_raw_pressure(i2c_fd, &up) < 0) {
                fprintf(stderr, "Pressure read failed\n");
            } else {
                b5 = compute_b5(ut);
                pressure = compute_pressure(up, b5);
                log_pressure(pressure);
            }
        }
        gpioDelay(2000000);
    }

    printf("\nShutting down...\n");
    gpioSetAlertFunc(BUTTON_GPIO, NULL);
    gpioTerminate();
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

