    start_tick = gpioTick();
    while (gpioRead(gpio) == 1) {
        if (gpioTick() - start_tick > 1000) {
            syslog(LOG_ERR, "DHT22 response timeout (low high)");
            return -1;
        }
    }
    start_tick = gpioTick();
    while (gpioRead(gpio) == 0) {
        if (gpioTick() - start_tick > 1000) {
            syslog(LOG_ERR, "DHT22 response timeout (low end)");
            return -1;
        }
    }
    start_tick = gpioTick();
    while (gpioRead(gpio) == 1) {
        if (gpioTick() - start_tick > 1000) {
            syslog(LOG_ERR, "DHT22 response timeout (high)");
            return -1;
        }
    }

    /* ---- Read 40 data bits ---- */
    for (i = 0; i < 40; i++) {
        start_tick = gpioTick();
        while (gpioRead(gpio) == 0) {
            if (gpioTick() - start_tick > 1000) {
                syslog(LOG_ERR, "DHT22 data timeout (bit %d low)", i);
                return -1;
            }
        }
        high_tick = gpioTick();
        while (gpioRead(gpio) == 1) {
            if (gpioTick() - high_tick > 1000) {
                syslog(LOG_ERR, "DHT22 data timeout (bit %d high)", i);
                return -1;
            }
        }
        end_tick = gpioTick();
        data[i / 8] <<= 1;
        if ((end_tick - start_tick) > 50) {
            data[i / 8] |= 1;
        }
    }

    /* ---- Checksum ---- */
    uint8_t checksum = (uint8_t)(data[0] + data[1] + data[2] + data[3]);
    if (checksum != data[4]) {
        syslog(LOG_ERR, "DHT22 checksum mismatch: calc=0x%02X recv=0x%02X", checksum, data[4]);
        return -1;
    }

    /* ---- Convert ---- */
    uint16_t raw_h = (data[0] << 8) | data[1];
    uint16_t raw_t = (data[2] << 8) | data[3];

    *humidity    = (float)raw_h / 10.0f;
    *temperature = (float)raw_t / 10.0f;
    if (raw_t & 0x8000) {
        *temperature = -(*temperature);
    }

    /* ---- Sanity range ---- */
    if (*humidity < 0.0f || *humidity > 100.0f ||
        *temperature < -40.0f || *temperature > 80.0f) {
        syslog(LOG_ERR, "DHT22 out-of-range: h=%.1f t=%.1f", *humidity, *temperature);
        return -1;
    }

    return 0;
}

/* ---- HTTP POST ---- */
static int post_humidity(float humidity, float temperature, const char *url)
{
    char json[256];
    int  ret = -1;
    int  attempt;

    snprintf(json, sizeof(json),
             "{\"humidity\":%.1f,\"temperature\":%.1f}",
             humidity, temperature);

    for (attempt = 0; attempt < API_POST_MAX_RETRIES; attempt++) {
        CURLcode res;
        struct curl_slist *headers = NULL;
        long http_code = 0;

        curl_easy_setopt(g_curl, CURLOPT_URL, url);
        curl_easy_setopt(g_curl, CURLOPT_POST, 1L);
        curl_easy_setopt(g_curl, CURLOPT_POSTFIELDS, json);
        curl_easy_setopt(g_curl, CURLOPT_POSTFIELDSIZE, (long)strlen(json));
        curl_easy_setopt(g_curl, CURLOPT_HTTPHEADER, headers);
        curl_easy_setopt(g_curl, CURLOPT_WRITEFUNCTION, curl_write_cb);
        curl_easy_setopt(g_curl, CURLOPT_TIMEOUT, 10L);
        curl_easy_setopt(g_curl, CURLOPT_CONNECTTIMEOUT, 5L);

        res = curl_easy_perform(g_curl);
        if (res != CURLE_OK) {
            char msg[256];
            snprintf(msg, sizeof(msg), "curl_easy_perform() failed: %s", curl_easy_strerror(res));
            syslog(LOG_ERR, "%s", msg);
            goto next_attempt;
        }

        curl_easy_getinfo(g_curl, CURLINFO_RESPONSE_CODE, &http_code);
        if (http_code >= 200 && http_code < 300) {
            syslog(LOG_INFO, "HTTP POST succeeded (code %ld)", http_code);
            ret = 0;
            break;
        }

        char msg[256];
        snprintf(msg, sizeof(msg), "HTTP POST failed (code %ld)", http_code);
        syslog(LOG_ERR, "%s", msg);
    next_attempt:
        if (attempt < API_POST_MAX_RETRIES - 1) {
            sleep(2);
        }
    }

    if (ret != 0) {
        syslog(LOG_ERR, "HTTP POST failed after %d attempts", API_POST_MAX_RETRIES);
    }
    return ret;
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_curl) {
        curl_easy_cleanup(g_curl);
        g_curl = NULL;
    }
    curl_global_cleanup();
    closelog();
}

static void curl_cleanup(void)
{
    curl_global_cleanup();
}

static void curl_init(void)
{
    g_curl = curl_easy_init();
    if (!g_curl) {
        syslog(LOG_ERR, "curl_easy_init() failed");
        exit(EXIT_FAILURE);
    }
}

/* ---- Write callback ---- */
static void curl_write_cb(char *ptr, size_t size, size_t nmemb, void *userp)
{
    (void)userp;
    size_t total = size * nmemb;
    char *buf = (char *)ptr;
    if (total > 0) {
        fwrite(buf, 1, total, stdout);
    }
}

/* ---- Parse options ---- */
static int parse_options(int argc, char *argv[])
{
    int opt;
    while ((opt = getopt(argc, argv, "s:")) != -1) {
        switch (opt) {
            case 's':
                strncpy(g_cfg.url, optarg, sizeof(g_cfg.url) - 1);
                g_cfg.url[sizeof(g_cfg.url) - 1] = '\0';
                break;
            default:
                fprintf(stderr, "Usage: %s [-s <url>]\n", argv[0]);
                return -1;
        }
    }
    return 0;
}

/* ---- Main ---- */
int main(int argc, char *argv[])
{
    int opt;
    float humidity, temperature;
    int rc = EXIT_FAILURE;

    openlog("dht22_post", LOG_PID | LOG_CONS, LOG_USER);

    parse_options(argc, argv);

    if (parse_options(argc, argv) != 0) {
        closelog();
        return EXIT_FAILURE;
    }

    if (curl_init() != 0) {
        closelog();
        return EXIT_FAILURE;
    }

    pthread_mutex_init(&g_cfg.lock, NULL);

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction() failed: %s", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "DHT22 humidity reader started (GPIO%d, %s)", DHT22_GPIO, g_cfg.url);

    while (g_running) {
        int ok = 0;

        for (int attempt = 0; attempt < DHT22_MAX_RETRIES && g_running; attempt++) {
            if (dht22_read(DHT22_GPIO, &humidity, &temperature) == 0) {
                ok = 1;
                break;
            }
            if (attempt < DHT22_MAX_RETRIES - 1) {
                sleep(DHT22_RETRY_DELAY_S);
            }
        }

        if (ok) {
            syslog(LOG_INFO, "DHT22: humidity=%.1f%% temperature=%.1fC", humidity, temperature);
            if (post_humidity(humidity, temperature, g_cfg.url) == 0) {
                syslog(LOG_INFO, "Data posted successfully");
            } else {
                syslog(LOG_ERR, "Failed to post data");
            }
            g_cfg.last_ok = time(NULL);
            g_cfg.retries_left = DHT22_MAX_RETRIES;
        } else {
            syslog(LOG_ERR, "DHT22 read failed after %d attempts", DHT22_MAX_RETRIES);
            g_cfg.last_fail = time(NULL);
            g_cfg.retries_left = DHT22_MAX_RETRIES;
        }

        /* ---- Sleep but wake early on signal ---- */
        for (int s = 0; s < DHT22_READ_INTERVAL_S && g_running; s++) {
            sleep(1);
        }
    }

    syslog(LOG_INFO, "Shutting down");
    rc = EXIT_SUCCESS;
    cleanup();
    return rc;
}

