#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/stat.h>

#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define FAN_STATE_FILE "/sys/class/thermal/cooling_device0/cur_state"
#define LOG_FILE "/var/log/fan_control.log"
#define POLL_INTERVAL_SEC 5

#define MAX_STATE 3

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
    return 0;
}

static int read_temperature(int *temp_out) {
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        perror("Error opening temperature file");
        return -1;
    }
    int temp = -1;
    if (fscanf(fp, "%d", &temp) != 1) {
        fprintf(stderr, "Error reading temperature from %s\n", TEMP_FILE);
        fclose(fp);
        return -1;
    }
    fclose(fp);
    if (temp < 0 || temp > 200000) {
        fprintf(stderr, "Invalid temperature value: %d\n", temp);
        return -1;
    }
    *temp_out = temp;
    return 0;
}

static int read_fan_state(int *state_out) {
    FILE *fp = fopen(FAN_STATE_FILE, "r");
    if (!fp) {
        perror("Error opening fan state file");
        return -1;
    }
    int state = -1;
    if (fscanf(fp, "%d", &state) != 1) {
        fprintf(stderr, "Error reading fan state from %s\n", FAN_STATE_FILE);
        fclose(fp);
        return -1;
    }
    fclose(fp);
    if (state < 0 || state > MAX_STATE) {
        fprintf(stderr, "Invalid fan state value: %d\n", state);
        return -1;
    }
    *state_out = state;
    return 0;
}

static int set_fan_state(int state) {
    FILE *fp = fopen(FAN_STATE_FILE, "w");
    if (!fp) {
        perror("Error opening fan state file for writing");
        return -1;
    }
    if (fprintf(fp, "%d", state) < 0) {
        perror("Error writing fan state");
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        perror("Error closing fan state file");
        return -1;
    }
    return 0;
}

static int validate_max_state(int max_state) {
    FILE *fp = fopen(FAN_STATE_FILE, "r");
    if (!fp) {
        perror("Error opening fan state file for max-state check");
        return -1;
    }
    int max = -1;
    if (fscanf(fp, "%d", &max) != 1) {
        fprintf(stderr, "Error reading max_state from %s\n", FAN_STATE_FILE);
        fclose(fp);
        return -1;
    }
    fclose(fp);
    if (max < 0 || max > MAX_STATE) {
        fprintf(stderr, "Invalid max_state value: %d\n", max);
        return -1;
    }
    if (max != MAX_STATE) {
        fprintf(stderr, "Warning: max_state in %s is %d, expected %d\n",
                FAN_STATE_FILE, max, MAX_STATE);
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (validate_max_state(MAX_STATE) != 0) {
        fprintf(stderr, "Failed to validate max_state in %s\n", FAN_STATE_FILE);
        return 1;
    }

    int current_state = -1;
    if (read_fan_state(&current_state) != 0) {
        fprintf(stderr, "Failed to read initial fan state\n");
        return 1;
    }

    if (log_event("Fan control service started") != 0) {
        fprintf(stderr, "Failed to log startup event\n");
    }

    while (running) {
        int temperature;
        if (read_temperature(&temperature) != 0) {
            fprintf(stderr, "Error reading temperature, retrying in %d seconds\n",
                    POLL_INTERVAL_SEC);
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        int new_state = -1;
        if (temperature < 45000) {
            new_state = 0;
        } else if (temperature < 55000) {
            new_state = 1;
        } else if (temperature < 65000) {
            new_state = 2;
        } else {
            new_state = 3;
        }

        if (new_state != current_state) {
            if (set_fan_state(new_state) == 0) {
                current_state = new_state;
                if (log_event("Fan speed changed to state") != 0) {
                    fprintf(stderr, "Failed to log fan speed change\n");
                }
            } else {
                fprintf(stderr, "Failed to set fan state to %d\n", new_state);
            }
        }

        sleep(POLL_INTERVAL_SEC);
    }

    if (log_event("Fan control service shutting down") != 0) {
        fprintf(stderr, "Failed to log shutdown event\n");
    }

    if (set_fan_state(0) != 0) {
        fprintf(stderr, "Failed to set fan to off state during shutdown\n");
    }

    return 0;
}

