/*
 * PID temperature controller for Raspberry Pi Zero W.
 *
 * Hardware:
 *   - MAX31855 thermocouple amplifier on SPI0 (CLK=GPIO11, CS=GPIO8/CE0, DO=GPIO9)
 *   - Resistive heater on GPIO18 (hardware PWM, 1 kHz, 0-100 % duty)
 *
 * Build:
 *   gcc -O2 -Wall -o heater_pid heater_pid.c -lpigpio -lrt
 *   (pigpio must be installed via: sudo apt install pigpio)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define HEATER_GPIO          18
#define SPI_CHANNEL          0          /* CE0 on GPIO8 */
#define SPI_BAUD             500000     /* 500 kHz */
#define PWM_FREQUENCY        1000       /* 1 kHz */
#define PWM_RANGE            100        /* 0-100 % duty */
#define LOG_FILE             "heater_log.txt"

#define TARGET_TEMP          50.0f
#define MAX_TEMP             100.0f
#define MIN_TEMP             0.0f

#define KP                  1.0f
#define KI                  0.1f
#define KD                  0.01f

/* ----------------------------- Globals ----------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int      g_spi_handle = -1;
static FILE    *g_log_file   = NULL;

/* ----------------------------- Prototypes -------------------------------- */

static void signal_handler(int sig);
static int  read_max31855(float *temperature, float *fault_code);
static void set_heater_pwm(int duty_percent);
static void log_data(float temperature, int duty_percent, float pid_output);
static void cleanup(void);

/* ----------------------------- Signal handler ----------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- MAX31855 read ------------------------------ */

/*
 * Read 4 bytes from the MAX31855 via SPI.
 * Returns 0 on success, -1 on SPI error, -2 on thermocouple fault.
 */
static int read_max31855(float *temperature, float *fault_code)
{
    char rx[4] = {0, 0, 0, 0};
    int  bytes_read;

    bytes_read = spiRead(g_spi_handle, rx, 4);
    if (bytes_read != 4) {
        fprintf(stderr, "SPI read error: expected 4 bytes, got %d (%s)\n",
                bytes_read, strerror(errno));
        return -1;
    }

    /* Fault bits occupy the top 2 bits of byte 0 */
    uint8_t fault = (uint8_t)rx[0] >> 6;
    if (fault & 0x01) {
        fprintf(stderr, "MAX31855 fault: open circuit\n");
        *fault_code = -1.0f;
        return -2;
    }
    if (fault & 0x02) {
        fprintf(stderr, "MAX31855 fault: short to GND\n");
        *fault_code = -2.0f;
        return -2;
    }
    if (fault & 0x04) {
        fprintf(stderr, "MAX31855 fault: short to VCC\n");
        *fault_code = -3.0f;
        return -2;
    }

    /* Thermocouple temperature: 14-bit signed, bits 31-18 */
    int16_t raw = ((int16_t)((uint8_t)rx[0] & 0x3F) << 8) | (uint8_t)rx[1];
    raw >>= 2;                       /* arithmetic shift keeps sign */

    *temperature = (float)raw * 0.25f; /* 0.25 °C per LSB */
    *fault_code  = (float)fault;
    return 0;
}

/* ----------------------------- Heater control ----------------------------- */

static void set_heater_pwm(int duty_percent)
{
    if (duty_percent < 0)   duty_percent = 0;
    if (duty_percent > 100) duty_percent = 100;

    int duty = (int)((float)duty_percent / 100.0f * PWM_RANGE);
    if (gpioPWM(HEATER_GPIO, duty) != 0) {
        fprintf(stderr, "gpioPWM failed for duty %d\n", duty);
    }
}

/* ----------------------------- Logging ------------------------------------ */

static void log_data(float temperature, int duty_percent, float pid_output)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32] = {0};

    if (t) {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    } else {
        snprintf(ts, sizeof(ts), "UNKNOWN");
    }

