#define SPI_CHANNEL          0          /* CE0 on GPIO8 */
#define SPI_BAUD             500000     /* 500 kHz */
#define PWM_FREQUENCY        1000       /* 1 kHz */
#define PWM_RANGE            100        /* 0-100 % duty */
#define LOG_FILE             "heater_log.txt"

#define TARGET_TEMP          50.0f
#define MAX_TEMP             100.0f
#define MIN_TEMP             0.0f

#define KP                  1.0f
#define KI                  0.1f
#define KD                  0.01f

/* ----------------------------- Globals ----------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int      g_spi_handle = -1;
static FILE    *g_log_file   = NULL;

/* ----------------------------- Prototypes -------------------------------- */

static void signal_handler(int sig);
