static void set_heater_pwm(int duty_percent);
static void log_data(float temperature, int duty_percent, float pid_output);
static void cleanup(void);

/* ----------------------------- Signal handler ----------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- MAX31855 read ------------------------------ */

/*
 * Read 4 bytes from the MAX31855 via SPI.
 * Returns 0 on success, -1 on SPI error, -2 on thermocouple fault.
 */
static int read_max31855(float *temperature, float *fault_code)
{
    char rx[4] = {0, 0, 0, 0};
    int  bytes_read;

    bytes_read = spiRead(g_spi_handle, rx, 4);
    if (bytes_read != 4) {
        fprintf(stderr, "SPI read error: expected 4 bytes, got %d (%s)\n",
                bytes_read, strerror(errno));
        return -1;
    }

    /* Fault bits occupy the top 2 bits of byte 0 */
    uint8_t fault = (uint8_t)rx[0] >> 6;
    if (fault & 0x01) {
        fprintf(stderr, "MAX31855 fault: open circuit\n");
        *fault_code = -1.0f;
        return -2;
    }
    if (fault & 0x02) {
        fprintf(stderr, "MAX31855 fault: short to GND\n");
        *fault_code = -2.0f;
        return -2;
    }
    if (fault & 0x04) {
        fprintf(stderr, "MAX31855 fault: short to VCC\n");
        *fault_code = -3.0f;
        return -2;
    }

    /* Thermocouple temperature: 14-bit signed, bits 31-18 */
    int16_t raw = ((int16_t)((uint8_t)rx[0] & 0x3F) << 8) | (uint8_t)rx[1];
    raw >>= 2;                       /* arithmetic shift keeps sign */

    *temperature = (float)raw * 0.25f; /* 0.25 °C per LSB */
    *fault_code  = (float)fault;
    return 0;
}

