/*
 * PWM fan controller for Raspberry Pi 4 Model B
 * Fan: Noctua NF-A4x10 5V PWM (PWM0 on GPIO18, physical pin 12)
 * Driver: pigpio (libpigpio)
 *
 * Build: gcc -O2 -Wall -o fan_ctrl fan_ctrl.c -lpigpio -lrt
 * Run:   sudo ./fan_ctrl
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FAN_GPIO          18
#define PWM_FREQUENCY     25000          /* 25 kHz — typical for 4-wire PWM fans */
#define PWM_RANGE         100            /* 0–100 % duty cycle */
#define LOG_FILE          "cooling_log.csv"
#define POLL_INTERVAL_S   5
#define TEMP_LOW          40.0f          /* °C — fan off below this */
#define TEMP_HIGH         70.0f          /* °C — fan full speed above this */
#define MAX_DUTY          100            /* percentage */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(float temperature, int duty_cycle)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s,%.2f,%d\n", ts, temperature, duty_cycle);
    } else {
        fprintf(fp, "(no-time),%.2f,%d\n", temperature, duty_cycle);
    }

    if (fclose(fp) != 0)
        perror("fclose(" LOG_FILE ")");
}

/* ------------------------------------------------------------------ */
/* Fan control                                                        */
/* ------------------------------------------------------------------ */
static int set_fan_speed(int duty_cycle)
{
    if (duty_cycle < 0)   duty_cycle = 0;
    if (duty_cycle > MAX_DUTY) duty_cycle = MAX_DUTY;

    int rc = gpioPWM(FAN_GPIO, duty_cycle);
    if (rc < 0) {
        fprintf(stderr, "gpioPWM(%d) failed: %s\n", duty_cycle, pigpio_error(rc));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Temperature measurement                                            */
/* ------------------------------------------------------------------ */
static float read_cpu_temperature(void)
{
    FILE *fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (!fp) {
        perror("fopen(/sys/class/thermal/thermal_zone0/temp)");
        return -1.0f;
    }

    char buf[32];
    if (!fgets(buf, sizeof(buf), fp)) {
        perror("fgets(/sys/class/thermal/thermal_zone0/temp)");
        fclose(fp);
        return -1.0f;
    }
    fclose(fp);

    long millideg = atol(buf);
    return (float)millideg / 1000.0f;
}

/* ------------------------------------------------------------------ */
/* Linear mapping: 40 °C -> 0 %  | 70 °C -> 100 %                     */
/* ------------------------------------------------------------------ */
static int map_temperature_to_duty(float temperature)
{
    if (temperature <= TEMP_LOW)
        return 0;
    if (temperature >= TEMP_HIGH)
        return MAX_DUTY;

    float frac = (temperature - TEMP_LOW) / (TEMP_HIGH - TEMP_LOW);
    int duty = (int)(frac * MAX_DUTY);
    if (duty < 0)   duty = 0;
    if (duty > MAX_DUTY) duty = MAX_DUTY;
    return duty;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Ensure fan is off before terminating pigpio */
    (void)gpioPWM(FAN_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- GPIO configuration ----------------------------------------- */
    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed\n", FAN_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- PWM frequency / range ------------------------------------- */
    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "gpioSetPWMfrequency(%d, %d) failed\n",
                FAN_GPIO, PWM_FREQUENCY);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(FAN_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "gpioSetPWMrange(%d, %d) failed\n",
                FAN_GPIO, PWM_RANGE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers -------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Log file header -------------------------------------------- */
    FILE *fp = fopen(LOG_FILE, "w");
    if (!fp) {
        perror("fopen(" LOG_FILE " (header))");
        cleanup();
        return EXIT_FAILURE;
    }
    fprintf(fp, "timestamp,temperature_c,duty_percent\n");
    if (fclose(fp) != 0)
        perror("fclose(header)");

    /* --- Main loop -------------------------------------------------- */
    while (g_running) {
        float temperature = read_cpu_temperature();
        if (temperature < 0.0f) {
            fprintf(stderr, "Temperature read failed; skipping cycle\n");
        } else {
            int duty = map_temperature_to_duty(temperature);
            if (set_fan_speed(duty) < 0) {
                fprintf(stderr, "Failed to set fan speed; aborting\n");
                break;
            }
            log_data(temperature, duty);
            printf("Temperature: %.2f °C  |  Duty: %d%%\n", temperature, duty);
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < POLL_INTERVAL_S && g_running; i++)
            sleep(1);
    }

    /* --- Graceful shutdown ------------------------------------------ */
    cleanup();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

