        return EXIT_FAILURE;
    }
    fprintf(fp, "timestamp,temperature_c,duty_percent\n");
    if (fclose(fp) != 0)
        perror("fclose(header)");

    /* --- Main loop -------------------------------------------------- */
    while (g_running) {
        float temperature = read_cpu_temperature();
        if (temperature < 0.0f) {
            fprintf(stderr, "Temperature read failed; skipping cycle\n");
        } else {
            int duty = map_temperature_to_duty(temperature);
            if (set_fan_speed(duty) < 0) {
                fprintf(stderr, "Failed to set fan speed; aborting\n");
