/*
 * Raspberry Pi Zero W – dual SLF3S-1300F liquid flow sensor logger
 *
 * Wiring:
 *   Sensor 1 (S1)  -> I2C bus 1, address 0x68
 *   Sensor 2 (S2)  -> I2C bus 1, address 0x69
 *   I2C multiplexer (e.g. Sensirion SF06) or direct wiring if no hub.
 *
 * Build:  gcc -O2 -Wall -Wextra -o flow_logger flow_logger.c
 * Run:    ./flow_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SENSOR1_ADDR   0x68
#define SENSOR2_ADDR   0x69
#define LOG_FILE       "flow_log.txt"
#define POLL_INTERVAL  1          /* seconds between readings */
#define MAX_RETRIES    3
#define READ_LEN       3          /* 2 data bytes + 1 CRC byte */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF)                        */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_open(uint8_t addr)
{
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

/*
 * Read one 3-byte measurement frame from the sensor.
 * Returns 0 on success (flows written to *f1, *f2), -1 on error.
 */
static int read_flow(int fd, float *f1, float *f2)
{
    uint8_t buf[READ_LEN];
    int n;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        n = read(fd, buf, READ_LEN);
        if (n == READ_LEN) {
            if (crc8(buf, 2) != buf[2]) {
                fprintf(stderr, "CRC mismatch (attempt %d)\n", attempt + 1);
                continue;
            }
            uint16_t raw1 = (uint16_t)((buf[0] << 8) | buf[1]);
            uint16_t raw2 = (uint16_t)((buf[3] << 8) | buf[4]);
            *f1 = (float)raw1 / 60.0f;   /* SLF3S-1300F: 60 counts/flow */
            *f2 = (float)raw2 / 60.0f;
            return 0;
        }
        if (n < 0)
            fprintf(stderr, "read: %s\n", strerror(errno));
        else
            fprintf(stderr, "read: short read (%d bytes)\n", n);
        if (attempt < MAX_RETRIES - 1)
            sleep(1);
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(float f1, float f2)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, f1, f2);
    }
    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int fd1 = i2c_open(SENSOR1_ADDR);
    if (fd1 < 0) return EXIT_FAILURE;

    int fd2 = i2c_open(SENSOR2_ADDR);
    if (fd2 < 0) {
        close(fd1);
        return EXIT_FAILURE;
    }

    while (g_running) {
        float f1 = 0.0f, f2 = 0.0f;
        int r1 = read_flow(fd1, &f1, &f2);
        int r2 = read_flow(fd2, &f1, &f2);

        if (r1 == 0) log_data(f1, f2);
        if (r2 == 0) log_data(f1, f2);

        sleep(POLL_INTERVAL);
    }

    /* Clean shutdown */
    close(fd1);
    close(fd2);
    return EXIT_SUCCESS;
}

