/*
 * Magnetic Rotary Encoder Monitor for Raspberry Pi 4 Model B
 * Encoder: Two TMAG5110A1 Hall-Effect latch sensors
 *   Channel A -> GPIO17 (open-drain, internal pull-up)
 *   Channel B -> GPIO18 (open-drain, internal pull-up)
 *
 * Build: gcc -O2 -Wall -o encoder_monitor encoder_monitor.c -lpigpio -lrt
 * Run:   sudo ./encoder_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define GPIO_A 17
#define GPIO_B 18
#define LOG_FILE "encoder_log.txt"
#define PULSES_PER_REV 360.0
#define SAMPLE_DELAY_US 10000  /* 10 ms */

/* Quadrature state machine: 2 bits (A, B) -> 0..3 */
static const int qstate[4] = {0, 1, 2, 3};

/* Quadrature transition table */
static const int qtable[4][4] = {
    {0, 1, 2, 3},
    {2, 3, 0, 1},
    {1, 0, 3, 2},
    {3, 2, 1, 0}
};

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Returns 0 on success, -1 on failure.                               */
static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(GPIO_A, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", GPIO_A);
        return -1;
    }
    if (gpioSetMode(GPIO_B, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", GPIO_B);
        return -1;
    }

    /* Enable internal pull-up resistors on both channels */
    if (gpioSetPullUpDown(GPIO_A, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d.\n", GPIO_A);
        return -1;
    }
    if (gpioSetPullUpDown(GPIO_B, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d.\n", GPIO_B);
        return -1;
    }

    /* Allow pull-ups to settle */
    gpioDelay(10000);  /* 10 ms */

    return 0;
}

/* ------------------------------------------------------------------ */
/* Returns 0 on success, -1 on failure.                               */
static int open_log_file(void)
{
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Returns 0 on success, -1 on failure.                               */
static int log_position(double position)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed.\n");
        return -1;
    }

    if (fprintf(g_log_fp, "%s, Position: %.2f degrees\n", timestamp, position) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed: %s\n",
                strerror(errno));
        return -1;
    }

    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "Warning: fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Quadrature state machine.                                          */
/* Returns 0 on success, -1 on read error.                            */
static int update_quadrature(int a, int b, int *q)
{
    int prev = *q;
    int next = qtable[prev][b - a];

    if (next != prev) {
        *q = next;
        return 0;
    }
    return -1;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    int a_prev = 0, b_prev = 0;
    int q = 0;
    int pulse_count = 0;
    int rc = EXIT_SUCCESS;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed: %s\n",
                strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGTERM) failed: %s\n",
                strerror(errno));
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    if (open_log_file() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Encoder monitoring started. Press Ctrl+C to exit.\n");
    printf("  Channel A: GPIO%d | Channel B: GPIO%d | P/R: %.1f\n",
           GPIO_A, GPIO_B, PULSES_PER_REV);

    while (g_running) {
        int a = gpioRead(GPIO_A);
        int b = gpioRead(GPIO_B);

        if (a < 0 || b < 0) {
            fprintf(stderr, "Error: gpioRead failed (A=%d, B=%d).\n", a, b);
            rc = EXIT_FAILURE;
            break;
        }

        if (update_quadrature(a, b, &q) != 0) {
            /* No valid transition — skip this sample */
            gpioDelay(SAMPLE_DELAY_US);
            continue;
        }

        /* Quadrature state: 0..3 -> 0..3 pulses per revolution */
        int pulses = q;

        if (pulses > 0) {
            pulse_count++;
            double position = (double)pulse_count / PULSES_PER_REV * 360.0;

            if (log_position(position) != 0) {
                fprintf(stderr, "Error: failed to log position.\n");
            }
        }

        gpioDelay(SAMPLE_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return rc;
}

