    if (open_log_file() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Encoder monitoring started. Press Ctrl+C to exit.\n");
    printf("  Channel A: GPIO%d | Channel B: GPIO%d | P/R: %.1f\n",
           GPIO_A, GPIO_B, PULSES_PER_REV);

    while (g_running) {
        int a = gpioRead(GPIO_A);
        int b = gpioRead(GPIO_B);

        if (a < 0 || b < 0) {
            fprintf(stderr, "Error: gpioRead failed (A=%d, B=%d).\n", a, b);
            rc = EXIT_FAILURE;
            break;
        }

        if (update_quadrature(a, b, &q) != 0) {
            /* No valid transition — skip this sample */
            gpioDelay(SAMPLE_DELAY_US);
            continue;
        }

        /* Quadrature state: 0..3 -> 0..3 pulses per revolution */
        int pulses = q;

        if (pulses > 0) {
            pulse_count++;
            double position = (double)pulse_count / PULSES_PER_REV * 360.0;

            if (log_position(position) != 0) {
                fprintf(stderr, "Error: failed to log position.\n");
            }
        }

        gpioDelay(SAMPLE_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return rc;
}

