/*
 * ADPD144RI Red/IR Photometric Sensor Logger
 * Board:  Raspberry Pi 3 Model B+
 * Bus:    I2C bus 1 (GPIO2 = SDA, GPIO3 = SCL)
 * Sensor: ADPD144RI at I2C address 0x48
 * LED:    GPIO17 (active-high)
 *
 * Logs timestamped red/IR samples to adpd144ri_log.txt every 100 ms.
 * Lights the LED when IR > 2000.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADPD144RI_ADDR  0x48
#define GPIO_LED       17
#define IR_THRESHOLD   2000
#define SAMPLE_PERIOD_US 100000  /* 100 ms */

/* ADPD144RI register addresses (16-bit, big-endian on the bus) */
#define REG_RED_DATA   0x00
#define REG_IR_DATA    0x02
#define REG_CONFIG     0x0A

/* Config register bits */
#define CFG_MODE         0x00
#define CFG_ADC_GAIN     0x01
#define CFG_ADC_TIME     0x02
#define CFG_ADC_GAIN_2   0x04
#define CFG_ADC_TIME_2   0x08
#define CFG_ADC_GAIN_4   0x0C
#define CFG_ADC_TIME_4   0x10
#define CFG_ADC_GAIN_8   0x14
#define CFG_ADC_TIME_8   0x18
#define CFG_ADC_GAIN_16  0x1C
#define CFG_ADC_TIME_16  0x20
#define CFG_MODE_SD       0x00
#define CFG_MODE_SD2      0x01
#define CFG_MODE_SD4      0x02
#define CFG_MODE_SD8      0x03
#define CFG_MODE_SD16     0x04

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a 16-bit big-endian value to a 16-bit register address */
static int i2c_write_reg16(int fd, uint16_t reg, uint16_t value)
{
    uint8_t buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (value >> 8) & 0xFF;
    buf[3] = value & 0xFF;

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a 16-bit big-endian value from a 16-bit register address */
static int i2c_read_reg16(int fd, uint16_t reg, uint16_t *value)
{
    uint8_t reg_buf[2];
    uint8_t data[2];

    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;

    if (write(fd, reg_buf, sizeof(reg_buf)) != (ssize_t)sizeof(reg_buf)) {
        fprintf(stderr, "I2C write (reg select 0x%04X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (read(fd, data, sizeof(data)) != (ssize_t)sizeof(data)) {
        fprintf(stderr, "I2C read from reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *value = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

/* Configure the ADPD144RI for single-shot mode with 16-bit ADC time */
static int configure_adpd144ri(int fd)
{
    uint16_t config = CFG_MODE_SD16;
    if (i2c_write_reg16(fd, REG_CONFIG, config) < 0)
        return -1;

    /* Allow the sensor to settle after configuration */
    gpioDelay(10000); /* 10 ms */
    return 0;
}

/* Trigger a single-shot conversion and read the two 16-bit data registers */
static int read_adpd144ri(int fd, uint16_t *red, uint16_t *ir)
{
    if (i2c_write_reg16(fd, REG_CONFIG, CFG_MODE_SD16) < 0)
        return -1;

    gpioDelay(20000); /* 20 ms conversion time */

    if (i2c_read_reg16(fd, REG_RED_DATA, red) < 0)
        return -1;

    if (i2c_read_reg16(fd, REG_IR_DATA, ir) < 0)
        return -1;

    return 0;
}

/* Log a single data row to the CSV file */
static int log_data(FILE *fp, uint16_t red, uint16_t ir)
{
    time_t t = time(NULL);
    struct tm tm;
    char timestamp[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%u,%u\n", timestamp, red, ir) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* Cleanup all resources */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    uint16_t red_value, ir_value;
    int consecutive_errors = 0;

    /* --- Signal handling for graceful shutdown --- */
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO17 as output and ensure LED is off --- */
    if (gpioSetMode(GPIO_LED, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d) failed\n", GPIO_LED);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_LED, 0);

    /* --- Open I2C bus --- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, ADPD144RI_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                ADPD144RI_ADDR, strerror(errno));
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Configure sensor --- */
    if (configure_adpd144ri(g_i2c_fd) < 0) {
        fprintf(stderr, "Failed to configure ADPD144RI (sensor may be absent)\n");
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    g_log_fp = fopen("adpd144ri_log.txt", "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "fopen(adpd144ri_log.txt) failed: %s\n", strerror(errno));
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "timestamp,red,ir\n");
        fflush(g_log_fp);
    }

    printf("ADPD144RI logger started. Logging to adpd144ri_log.txt\n");
    printf("Press Ctrl+C to stop.\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        if (read_adpd144ri(g_i2c_fd, &red_value, &ir_value) == 0) {
            consecutive_errors = 0;

            if (log_data(g_log_fp, red_value, ir_value) < 0) {
                fprintf(stderr, "Logging failed; continuing\n");
            }

            if (ir_value > IR_THRESHOLD) {
                gpioWrite(GPIO_LED, 1);
                printf("IR threshold exceeded (%u > %d) - LED ON\n",
                       ir_value, IR_THRESHOLD);
            } else {
                gpioWrite(GPIO_LED, 0);
            }
        } else {
            consecutive_errors++;
            fprintf(stderr, "I2C read error (%d consecutive)\n", consecutive_errors);

            if (consecutive_errors >= 10) {
                fprintf(stderr, "Too many consecutive I2C errors; aborting.\n");
                break;
            }
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    gpioWrite(GPIO_LED, 0);
    cleanup();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

