#define ADPD144RI_REG_RESULT1  0x01
#define ADPD144RI_REG_RESULT2  0x02
#define ADPD144RI_REG_RESULT3  0x03

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg16(int fd, uint8_t reg, uint16_t val)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(val >> 8);
    buf[2] = (uint8_t)(val & 0xFF);

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t reg_buf = reg;
    uint8_t data[2];

    if (write(fd, &reg_buf, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (read(fd, data, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor initialization                                               */
/* ------------------------------------------------------------------ */
static int sensor_init(int fd)
{
    uint16_t part_id;

    /* Verify device identity */
    if (i2c_read_reg16(fd, ADPD144RI_REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Cannot read PART_ID — sensor may be absent or "
                        "bus error.\n");
        return -1;
    }
    if (part_id != 0x1444) {
        fprintf(stderr, "Unexpected PART_ID 0x%04X (expected 0x1444).\n",
                part_id);
        return -1;
    }
    printf("ADPD144RI detected (PART_ID=0x%04X).\n", part_id);

    /* Configure interrupt map: map all 16 channels to INT_MAP0 */
    if (i2c_write_reg16(fd, ADPD144RI_REG_INT_MAP0, 0x0000) != 0)
        return -1;

    /* Clear any pending interrupt */
    if (i2c_write_reg16(fd, ADPD144RI_REG_INT_CLR, 0x0001) != 0)
        return -1;

    /* Enable all 16 channels */
    if (i2c_write_reg16(fd, ADPD144RI_REG_INT_EN, 0x0001) != 0)
        return -1;

    /* Start with no interrupts active */
    if (i2c_write_reg16(fd, ADPD144RI_REG_IRQ_ENABLE, 0x0000) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read IR value (16-bit, big-endian)                                 */
/* ------------------------------------------------------------------ */
static int read_ir_value(int fd, uint16_t *ir_out)
{
    uint16_t result;

    if (i2c_read_reg16(fd, ADPD144RI_REG_RESULT0, &result) != 0)
        return -1;

    *ir_out = result;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, uint16_t ir_value)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(fp, "%s,%u\n", timestamp, ir_value);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output.\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, ADPD144RI_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                ADPD144RI_ADDR, strerror(errno));
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (sensor_init(g_i2c_fd) != 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Logging IR readings to %s every %d ms. Press Ctrl+C to stop.\n",
           LOG_FILE, SAMPLE_PERIOD / 1000);

    while (g_running) {
        uint16_t ir_value;

        if (read_ir_value(g_i2c_fd, &ir_value) != 0) {
            fprintf(stderr, "I2C read error — continuing.\n");
        } else {
            log_data(g_log_fp, ir_value);

            if (ir_value > IR_THRESHOLD) {
                gpioWrite(LED_GPIO, 1);
            } else {
                gpioWrite(LED_GPIO, 0);
            }
        }

        usleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

