/*
 * MAX9814 Audio Peak Detector for Raspberry Pi 5
 *
 * Wiring:
 *   MAX9814 OUT  -> GPIO17 (BCM)
 *   MAX9814 GAIN -> GPIO18 (BCM, LOW = 60 dB)
 *   MAX9814 VDD  -> 3.3 V
 *   MAX9814 GND  -> GND
 *
 * Build: gcc -O2 -Wall -o audio_peak audio_peak.c -lpigpio -lrt
 * Run:   sudo ./audio_peak
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define GPIO_INPUT 17          /* MAX9814 OUT  (analog -> digital) */
#define GPIO_OUTPUT 18        /* MAX9814 GAIN  (digital output) */
#define LOG_FILE "audio_log.txt"
#define POLL_DELAY_US 10000    /* 10 ms polling interval */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly               */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a timestamped level event to the log file                    */
/* ------------------------------------------------------------------ */
static int log_event(int level)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        fprintf(stderr, "localtime_r() failed\n");
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s %d\n", ts, level) < 0) {
        fprintf(stderr, "fprintf() to log failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose() on log failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Install signal handlers for clean shutdown ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure GPIO17 as input ---- */
    if (gpioSetMode(GPIO_INPUT, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(input=%d) failed\n", GPIO_INPUT);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Configure GPIO18 as output and drive it LOW ---- */
    if (gpioSetMode(GPIO_OUTPUT, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(output=%d) failed\n", GPIO_OUTPUT);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(GPIO_OUTPUT, 0) != 0) {
        fprintf(stderr, "gpioWrite(output=%d, 0) failed\n", GPIO_OUTPUT);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MAX9814 audio peak detector running.\n");
    printf("  Input  : GPIO%d (MAX9814 OUT)\n", GPIO_INPUT);
    printf("  Gain   : GPIO%d (LOW = 60 dB)\n", GPIO_OUTPUT);
    printf("  Log    : %s\n", LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    /* ---- Main polling loop ---- */
    int prev_level = 0;
    int first_sample = 1;

    while (g_running) {
        int level = gpioRead(GPIO_INPUT);

        if (level < 0) {
            fprintf(stderr, "gpioRead(input=%d) failed\n", GPIO_INPUT);
            break;
        }

        /* Detect rising edge: 0 -> 1 */
        if (level == 1 && prev_level == 0) {
            if (log_event(level) != 0) {
                fprintf(stderr, "Failed to log event.\n");
            }
        }

        prev_level = level;
        first_sample = 0;

        gpioDelay(POLL_DELAY_US);
    }

    /* ---- Clean shutdown ---- */
    gpioWrite(GPIO_OUTPUT, 0);   /* best-effort: leave GAIN LOW */
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

