/*
 * flow_monitor.c — Raspberry Pi Zero W
 * Sensirion SLF3S‑4000B liquid flow sensor monitor
 *
 * Wiring:
 *   SLF3S SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   SLF3S SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   SLF3S VDD  -> 3.3 V
 *   SLF3S GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o flow_monitor flow_monitor.c -lm
 *
 * Run:
 *   ./flow_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- SLF3S‑4000B constants ------------------------------------------------ */
#define I2C_BUS        "/dev/i2c-1"
#define SLF3S_ADDR     0x60
#define SLF3S_FLOW_MSB 0x00
#define SLF3S_FLOW_LSB 0x01
#define SLF3S_FLOW_CRC 0x02
#define SLF3S_MEASRATE 0x03
#define SLF3S_RESET    0x0F
#define SLF3S_RESET_CMD 0x80
#define SLF3S_MEASRATE_CMD 0x01
#define SLF3S_MEASRATE_MS 1000
#define SLF3S_SCALE     0.001f   /* uL per LSB (SLF3S‑4000B) */
#define LOG_FILE       "flow_log.csv"
#define SAMPLE_PERIOD_S 1.0f

/* ---- Globals for signal-safe cleanup ------------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd = -1;
static FILE    *g_log_fp = NULL;

/* -------------------------------------------------------------------------- */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* -------------------------------------------------------------------------- */
/* CRC-8 as used by Sensirion: poly 0x31, init 0xFF, no final XOR             */
static uint8_t sensirion_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* -------------------------------------------------------------------------- */
/* Write a single command byte to the sensor (no register address prefix)     */
static int slf3s_write_cmd(int fd, uint8_t cmd)
{
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "[SLF3S] write_cmd(0x%02X) failed: %s\n",
                cmd, strerror(errno));
        return -1;
    }
    return 0;
}

/* -------------------------------------------------------------------------- */
/* Read three bytes: MSB, LSB, CRC, then verify CRC                        */
static int slf3s_read3(int fd, uint8_t *msb, uint8_t *lsb, uint8_t *crc)
{
    uint8_t buf[3];
    ssize_t n = read(fd, buf, sizeof(buf));
    if (n != 3) {
        fprintf(stderr, "[SLF3S] read3 failed: expected 3 bytes, got %zd (%s)\n",
                n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }
    *msb = buf[0];
    *lsb = buf[1];
    *crc = buf[2];
    if (sensirion_crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "[SLF3S] CRC mismatch: calc=0x%02X recv=0x%02X\n",
                sensirion_crc8(buf, 2), buf[2]);
        return -1;
    }
    return 0;
}

/* -------------------------------------------------------------------------- */
/* Trigger a measurement and wait for the latest conversion                  */
static int slf3s_read_flow(int fd, float *flow_uL_min)
{
    if (slf3s_write_cmd(fd, SLF3S_MEASRATE_CMD) < 0)
        return -1;

    /* Measurement rate = 1 ms, so ~1 s = 1000 conversions */
    usleep(SLF3S_MEASRATE_MS * 1000);

    uint8_t msb, lsb, crc;
    if (slf3s_read3(fd, &msb, &lsb, &crc) < 0)
        return -1;

    int16_t raw = (int16_t)((msb << 8) | lsb);
    *flow_uL_min = (float)raw * SLF3S_SCALE;
    return 0;
}

/* -------------------------------------------------------------------------- */
static void cleanup(void)
{
    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* -------------------------------------------------------------------------- */
int main(void)
{
    /* ---- Signal handling ----------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ----------------------------------------------- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SLF3S_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                SLF3S_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open log file once ------------------------------------------ */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Reset sensor -------------------------------------------------- */
    if (slf3s_write_cmd(g_i2c_fd, SLF3S_RESET_CMD) < 0) {
        fprintf(stderr, "Sensor reset failed; continuing anyway.\n");
    }
    usleep(2000);  /* allow reset to complete */

    /* ---- Main loop ---------------------------------------------------- */
    while (g_running) {
        float flow_uL_min;
        if (slf3s_read_flow(g_i2c_fd, &flow_uL_min) == 0) {
            time_t now = time(NULL);
            struct tm tm_buf;
            struct tm *t = localtime_r(&now, &tm_buf);
            char ts[32];
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
            fprintf(g_log_fp, "%s,%.3f\n", ts, flow_uL_min);
            fflush(g_log_fp);
            printf("%s  flow: %.3f uL/min\n", ts, flow_uL_min);
        } else {
            fprintf(stderr, "Read failed; will retry next cycle.\n");
        }
        sleep(SAMPLE_PERIOD_S);
    }

    /* ---- Graceful shutdown ------------------------------------------- */
    cleanup();
    return EXIT_SUCCESS;
}

