/*
 * air_quality_monitor.c — Raspberry Pi Zero W + Honeywell MICS-VZ-89TE
 *
 * Reads TVOC (ppb) and eCO2 (ppm) from the MICS-VZ-89TE on I2C bus 1,
 * computes an IAQ index, and logs timestamped rows to air_quality_log.csv
 * every 5 s.  Handles SIGINT for clean shutdown.
 *
 * Build:  gcc -O2 -Wall -Wextra -o air_quality_monitor air_quality_monitor.c
 * Run:    ./air_quality_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS        1
#define LOG_FILE       "air_quality_log.csv"
#define SAMPLE_PERIOD  5          /* seconds between samples */
#define MAX_RETRIES    3

/* MICS-VZ-89TE register addresses (16-bit, big-endian on the wire) */
#define REG_TVOC_LOW    0x00
#define REG_TVOC_HIGH   0x01
#define REG_ECO2_LOW    0x02
#define REG_ECO2_HIGH   0x03
#define REG_COMMAND     0x0F

/* Command opcodes */
#define CMD_READ_MEAS   0x01
#define CMD_RESET       0x80

/* Globals for signal-safe cleanup */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly               */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit register address, then a command byte               */
/* ------------------------------------------------------------------ */
static int write_reg_addr(uint8_t reg, uint8_t cmd)
{
    char buf[2];
    buf[0] = (char)(reg >> 8);
    buf[1] = (char)(reg & 0xFF);

    if (i2cWriteDevice(g_i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(0x%02X, 0x%02X) failed: %s\n",
                reg, cmd, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian register pair                         */
/* ------------------------------------------------------------------ */
static int read_reg16(uint8_t reg_low, uint16_t *out)
{
    char cmd[2];
    char data[2];

    cmd[0] = (char)(reg_low >> 8);
    cmd[1] = (char)(reg_low & 0xFF);

    if (i2cWriteDevice(g_i2c_handle, cmd, 2) != 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(reg 0x%02X) failed: %s\n",
                reg_low, strerror(errno));
        return -1;
    }

    if (i2cReadDevice(g_i2c_handle, data, 2) != 2) {
        fprintf(stderr, "[ERROR] i2cReadDevice(reg 0x%02X) failed: %s\n",
                reg_low, strerror(errno));
        return -1;
    }

    *out = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Reset the sensor (command 0x80)                                   */
/* ------------------------------------------------------------------ */
static int reset_sensor(void)
{
    if (write_reg_addr(REG_COMMAND, CMD_RESET) != 0)
        return -1;

    /* Allow the reset to complete */
    gpioDelay(10000); /* 10 ms */

    /* After reset the sensor may return a zero reading; this is normal. */
    uint16_t dummy;
    if (read_reg16(REG_TVOC_LOW, &dummy) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read TVOC (ppb) and eCO2 (ppm) from the sensor                      */
/* ------------------------------------------------------------------ */
static int read_sensor_data(uint16_t *tvoc, uint16_t *eco2)
{
    if (write_reg_addr(REG_COMMAND, CMD_READ_MEAS) != 0)
        return -1;

    /* Small delay so the sensor can prepare the response */
    gpioDelay(10000);

    if (read_reg16(REG_TVOC_LOW, tvoc) != 0)
        return -1;
    if (read_reg16(REG_ECO2_LOW, eco2) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Compute an IAQ index from TVOC and eCO2                             */
/* ------------------------------------------------------------------ */
static float calculate_iaq(uint16_t tvoc, uint16_t eco2)
{
    float iaq = 0.0f;

    if (tvoc > 0 && eco2 > 0) {
        /* MICS-VZ-89TE datasheet: IAQ = (TVOC / 1000) + (eCO2 / 100) */
        iaq = (float)tvoc / 1000.0f + (float)eco2 / 100.0f;
    }

    /* Clamp to a reasonable range */
    if (iaq < 0.0f)   iaq = 0.0f;
    if (iaq > 100.0f) iaq = 100.0f;

    return iaq;
}

/* ------------------------------------------------------------------ */
/* Log one data row to the CSV file                                   */
/* ------------------------------------------------------------------ */
static int log_data(float iaq, uint16_t tvoc, uint16_t eco2)
{
    time_t     rawtime;
    struct tm  timeinfo;
    char       timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(g_log_file, "%s,%.2f,%u,%u\n", timestamp, iaq, tvoc, eco2) < 0) {
        fprintf(stderr, "[ERROR] fprintf to log file failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "[ERROR] fflush log file failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call multiple times                       */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    uint16_t tvoc = 0, eco2 = 0;
    float    iaq  = 0.0f;
    int      rc   = EXIT_FAILURE;

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus 1 at address 0x27 (MICS-VZ-89TE default) --- */
    g_i2c_handle = i2cOpen(I2C_BUS, 0x27, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x27) failed: %s\n",
                I2C_BUS, strerror(errno));
        goto cleanup;
    }

    /* --- Open log file (append mode) --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,iaq_index,TVOC_ppb,eCO2_ppm\n");
        fflush(g_log_file);
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGINT) failed: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGTERM) failed: %s\n", strerror(errno));
    }

    /* --- Reset sensor (guaranteed to succeed) --- */
    if (reset_sensor() != 0) {
        fprintf(stderr, "[WARN] Sensor reset failed; continuing anyway.\n");
    }

    /* --- Main sampling loop --- */
    while (g_running) {
        if (read_sensor_data(&tvoc, &eco2) != 0) {
            fprintf(stderr, "[WARN] Sensor read failed; will retry next cycle.\n");
        } else {
            iaq = calculate_iaq(tvoc, eco2);

            if (log_data(iaq, tvoc, eco2) != 0) {
                fprintf(stderr, "[WARN] Logging failed; continuing.\n");
            } else {
                printf("%s  TVOC=%u ppb  eCO2=%u ppm  IAQ=%.2f\n",
                       "sample", tvoc, eco2, iaq);
            }
        }

        /* Sleep in 100 ms increments so SIGINT is caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD * 10 && g_running; i++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    rc = EXIT_SUCCESS;

cleanup:
    cleanup();
    return rc;
}

