/*
 * TTP223B capacitive touch sensor monitor for Raspberry Pi 5 (BCM GPIO).
 *
 * Wiring:
 *   TTP223B VCC  -> 3.3 V (physical pin 1)
 *   TTP223B GND  -> GND   (physical pin 9)
 *   TTP223B OUT  -> GPIO17 (physical pin 11)
 *   TTP223B INT  -> unused (no interrupt-driven variant used here)
 *
 * The TTP223B output is HIGH while touched and LOW while released.
 * A HIGH reading sustained for more than 5 s triggers an intrusion alert.
 *
 * Build:  gcc -O2 -Wall -Wextra -o ttp223_tamper ttp223_tamper.c
 */

#include <errno.h>
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#include <gpiod.h>

#define GPIO_CHIP_NAME   "gpiochip4"   /* RP1 GPIO controller on Pi 5 */
#define GPIO_LINE_OFFSET 17            /* BCM 17, physical pin 11 */
#define POLL_INTERVAL_MS 100           /* 100 ms polling interval */
#define INTRUSION_THRESHOLD_S 5        /* 5 s of continuous HIGH */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
    }
}

/* ------------------------------------------------------------------ */
static void print_intrusion_alert(void)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL) {
        if (strftime(timestamp, sizeof(timestamp),
                     "%Y-%m-%d %H:%M:%S", &timeinfo) > 0) {
            printf("[ALERT] Touch detected on GPIO%d for more than %d s "
                   "(timestamp: %s)\n",
                   GPIO_LINE_OFFSET, INTRUSION_THRESHOLD_S,
                   timestamp);
        } else {
            printf("[ALERT] Touch detected on GPIO%d for more than %d s\n",
                   GPIO_LINE_OFFSET, INTRUSION_THRESHOLD_S);
        }
    } else {
        printf("[ALERT] Touch detected on GPIO%d for more than %d s\n",
               GPIO_LINE_OFFSET, INTRUSION_THRESHOLD_S);
    }
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    struct timespec poll_ts;
    struct timespec high_start;
    int ret = EXIT_FAILURE;

    install_signal_handlers();

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n",
                GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get the GPIO line for BCM 17 */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (line == NULL) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    /* Request the line as input with the consumer label */
    if (gpiod_line_request_input(line, "ttp223_tamper") < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as input: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    printf("Monitoring TTP223B touch sensor on GPIO%d (BCM). "
           "Press Ctrl+C to exit.\n", GPIO_LINE_OFFSET);
    fflush(stdout);

    /* Seed the high_start timestamp */
    clock_gettime(CLOCK_MONOTONIC, &high_start);

    while (g_running) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Error reading GPIO line %d: %s\n",
                    GPIO_LINE_OFFSET, strerror(errno));
            goto cleanup;
        }

        if (value == 1) {
            /* HIGH reading — track duration */
            clock_gettime(CLOCK_MONOTONIC, &poll_ts);
            double elapsed = (poll_ts.tv_sec - high_start.tv_sec)
                            + (poll_ts.tv_nsec - high_start.tv_nsec) / 1e9;

            if (elapsed >= (double)INTRUSION_THRESHOLD_S) {
                print_intrusion_alert();
                high_start.tv_sec = poll_ts.tv_sec;
                high_start.tv_nsec = poll_ts.tv_nsec;
            }
        } else {
            /* LOW reading — reset timer */
            high_start.tv_sec = poll_ts.tv_sec;
            high_start.tv_nsec = poll_ts.tv_nsec;
        }

        poll_ts.tv_nsec += POLL_INTERVAL_MS * 1000000L;
        if (poll_ts.tv_nsec >= 1000000000L) {
            poll_ts.tv_sec += 1000;
            poll_ts.tv_nsec -= 1000000000L;
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (line != NULL) {
        gpiod_line_release(line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    if (ret == EXIT_SUCCESS) {
        printf("\nExiting gracefully.\n");
    }
    return ret;
}

