    }

    if (snd_pcm_hw_params_set_kbit_rate_near(hw, BITS_PER_SAMPLE * CHANNELS) < 0) {
        fprintf(stderr, "snd_pcm_hw_params_set_kbit_rate_near: %s\n", strerror(errno));
