/*
 * Raspberry Pi 4 Model B – INMP441 I2S MEMS Microphone Capture
 *
 * Wiring:
 *   INMP441 SCLK  -> GPIO 11 (BCM)
 *   INMP441 DOUT  -> GPIO 9  (BCM)
 *   INMP441 DIN   -> GPIO 10 (BCM)
 *   INMP441 CS    -> GPIO 8  (BCM)
 *   INMP441 L/R   -> GPIO 17 (BCM)
 *   INMP441 VDD   -> 3.3 V
 *   INMP441 GND   -> GND
 *
 * The INMP441 is a dual-channel I2S microphone; the L/R pin selects
 * which channel is presented to the PCM stream.  We drive GPIO 17
 * HIGH to select the left channel.
 *
 * The Raspberry Pi 4 has no I2S peripheral; the PCM stream is
 * accessed via ALSA on the /dev/snd/pcmC0D0c interface.
 *
 * Build:  gcc -O2 -Wall -Wextra -o capture capture.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/soundcard.h>

#define GPIO_CHIP_NAME      "gpiochip4"
#define GPIO_LINE_SELECT    17          /* BCM 17 */
#define SAMPLE_RATE         16000        /* Hz */
#define BITS_PER_SAMPLE     16
#define CHANNELS            1
#define RECORD_SECONDS      5
#define SAMPLE_DELAY_US     (1000000 / SAMPLE_RATE)

#define PCM_DEVICE          "/dev/snd/pcmC0D0c"
#define OUTPUT_FILE         "audio_capture.pcm"
#define I2S_BCLK_DIVISOR    100         /* 100 MHz / 16000 Hz = 6.25 kHz */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * mmap a single ALSA PCM stream so we can read it directly from
 * /dev/snd/pcmC0D0c without going through the kernel's stream
 * ioctl() interface.
 */
static int pcm_mmap(const char *device, int *fd_out)
{
    int fd = open(device, O_RDWR | O_CLOEXEC);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", device, strerror(errno));
        return -1;
    }

    struct snd_pcm_hw_params *hw = snd_pcm_alloc_new();
    if (!hw) {
        fprintf(stderr, "snd_pcm_alloc_new: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    if (snd_pcm_hw_params_set_access(hw, SND_PCM_ACCESS_RW_INTERLEAVED) < 0) {
        fprintf(stderr, "snd_pcm_hw_params_set_access: %s\n", strerror(errno));
        snd_pcm_free_hw_params(hw);
        close(fd);
        return -1;
    }

    if (snd_pcm_hw_params_set_format(hw, SND_PCM_FORMAT_S16_LE) < 0) {
        fprintf(stderr, "snd_pcm_hw_params_set_format: %s\n", strerror(errno));
        snd_pcm_free_hw_params(hw);
        close(fd);
        return -1;
    }

    if (snd_pcm_hw_params_set_channels(hw, CHANNELS) < 0) {
        fprintf(stderr, "snd_pcm_hw_params_set_channels: %s\n", strerror(errno));
        snd_pcm_free_hw_params(hw);
        close(fd);
        return -1;
    }

    if (snd_pcm_hw_params_set_rate_near(hw, NULL, &SAMPLE_RATE, 0) < 0) {
        fprintf(stderr, "snd_pcm_hw_params_set_rate_near: %s\n", strerror(errno));
        snd_pcm_free_hw_params(hw);
        close(fd);
