/*
 * Flame sensor monitor for Raspberry Pi 4 Model B
 *
 * Hardware:
 *   - SainSmart IR Flame Sensor Module (LM393 comparator with IR photodiode)
 *     DO  -> GPIO4  (BCM)
 *     VCC -> 3.3 V
 *     GND -> GND
 *
 *   - Adafruit 4 W PWM fan driver on GPIO18 (BCM)
 *     VCC -> 3.3 V
 *     GND -> GND
 *     PWM -> GPIO18
 *
 * Behavior:
 *   Polls GPIO4 every 50 ms.  When the digital output goes LOW (flame
 *   detected), drives GPIO18 at 100 Hz to drive a cooling fan.
 *   Logs start, flame, end, and shutdown events to flame_log.txt.
 *   On SIGINT/SIGTERM stops PWM, resets GPIOs, terminates driver, closes
 *   log file.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o flame_monitor flame_monitor.c -lpigpio -lrt
 *   (pigpio must be installed via sudo)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLAME_SENSOR_PIN 4
#define FAN_PIN          18
#define PWM_FREQUENCY    100          /* Hz */
#define PWM_RANGE        1000         /* duty 0..1000 */
#define POLL_INTERVAL_US 50000       /* 50 ms */
#define DEBOUNCE_US      50000       /* 50 ms */
#define LOG_FILE         "flame_log.txt"

static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_event(const char *msg)
{
    if (!g_log)
        return;

    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    if (t)
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    else
        snprintf(ts, sizeof(ts), "UNKNOWN");

    fprintf(g_log, "%s %s\n", ts, msg);
    fflush(g_log);
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */
static int safe_read(int pin)
{
    int v = gpioRead(pin);
    if (v < 0) {
        char buf[128];
        snprintf(buf, sizeof(buf), "ERROR: gpioRead(%d) failed", pin);
        log_event(buf);
        return -1;
    }
    return v;
}

static int safe_write(int pin, int val)
{
    if (gpioWrite(pin, val) < 0) {
        char buf[128];
        snprintf(buf, sizeof(buf), "ERROR: gpioWrite(%d, %d) failed", pin, val);
        log_event(buf);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Fan control                                                        */
/* ------------------------------------------------------------------ */
static int fan_on(void)
{
    if (safe_write(FAN_PIN, 1) < 0)
        return -1;
    return 0;
}

static int fan_off(void)
{
    if (safe_write(FAN_PIN, 0) < 0)
        return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    fan_off();
    gpioSetMode(FAN_PIN, PI_INPUT);
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioTerminate();
    if (g_log) {
        log_event("Program terminated");
        fclose(g_log);
        g_log = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "ERROR: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- log file --- */
    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        perror("ERROR: cannot open log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_event("Program started");

    /* --- GPIO configuration --- */
    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) < 0) {
        log_event("ERROR: failed to set flame sensor pin mode");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(FAN_PIN, PI_OUTPUT) < 0) {
        log_event("ERROR: failed to set fan pin mode");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- PWM setup --- */
    if (gpioSetPWMfrequency(FAN_PIN, PWM_FREQUENCY) < 0) {
        log_event("ERROR: failed to set PWM frequency");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(FAN_PIN, PWM_RANGE) < 0) {
        log_event("ERROR: failed to set PWM range");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioPWM(FAN_PIN, 0) < 0) {
        log_event("ERROR: failed to initialise PWM duty");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        log_event("ERROR: failed to install signal handlers");
        cleanup();
        return EXIT_FAILURE;
    }

    int last_flame = 0;
    uint32_t last_change_tick = gpioTick();

    /* --- main loop --- */
    while (g_running) {
        int flame = safe_read(FLAME_SENSOR_PIN);
        if (flame < 0) {
            /* Sensor read error: wait and retry */
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        uint32_t now = gpioTick();
        uint32_t elapsed = now - last_change_tick;
        last_change_tick = now;

        if (flame == 0 && last_flame == 1) {
            /* Rising edge: flame detected */
            if (fan_on() == 0) {
                log_event("Flame detected");
            }
        } else if (flame == 1 && last_flame == 0) {
            /* Falling edge: flame cleared */
            if (fan_off() == 0) {
                log_event("Flame cleared");
            }
        }

        last_flame = flame;

        /* Sensor-absent detection: no valid reading for ~5 s */
        if (flame < 0) {
            uint32_t since_last_ok = elapsed - last_change_tick;
            if (since_last_ok > 5000000) {
                log_event("WARNING: no valid flame sensor reading for 5 s "
                          "(sensor absent or wiring fault?)");
                last_flame = 0;   /* reset so we don't spam on sensor-absent */
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    /* --- graceful shutdown --- */
    cleanup();
    return EXIT_SUCCESS;
}

