#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_MODE        0
#define SPI_BITS        8
#define GPIO_TRIGGER    23
#define GPIO_DATA_READY 24
#define LOG_FILE        "radar_heatmap.bin"
#define FRAME_PERIOD_US 100000
#define FRAME_SIZE      32768
#define HEATMAP_SAMPLES 256
#define NUM_FRAMES      10

#define MAGIC_NUMBER    4144
#define FRAME_HEADER_SIZE 40
#define DATA_HEADER_SIZE 4
#define DATA_SIZE        FRAME_SIZE

typedef struct {
    uint32_t start_freq;
    uint32_t end_freq;
    uint16_t num_chirps;
    uint16_t num_samples;
} mmw_config_t;

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int spi_init(void) {
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI max speed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

static int spi_transfer(uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int trigger_frame(void) {
    if (gpioWrite(GPIO_TRIGGER, 1) < 0) {
        fprintf(stderr, "Error setting trigger pin high: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(1000);
    if (gpioWrite(GPIO_TRIGGER, 0) < 0) {
        fprintf(stderr, "Error setting trigger pin low: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_data_ready(void) {
    int val = gpioRead(GPIO_DATA_READY);
    if (val < 0) {
        fprintf(stderr, "Error reading data ready pin: %s\n", strerror(errno));
        return -1;
    }
    return val;
}

static int log_frame(const uint8_t *data, int frame_num) {
    if (fwrite(&MAGIC_NUMBER, sizeof(MAGIC_NUMBER), 1, g_log_fp) != 1) {
        fprintf(stderr, "Error writing magic number: %s\n", strerror(errno));
        return -1;
    }
    if (fwrite(&frame_num, sizeof(frame_num), 1, g_log_fp) != 1) {
        fprintf(stderr, "Error writing frame number: %s\n", strerror(errno));
        return -1;
    }
    if (fwrite(data, 1, DATA_SIZE, g_log_fp) != DATA_SIZE) {
        fprintf(stderr, "Error writing heatmap data: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(GPIO_TRIGGER, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO%d as output: %s\n", GPIO_TRIGGER, strerror(errno));
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(GPIO_DATA_READY, PI_INPUT) < 0) {
        fprintf(stderr, "Error setting GPIO%d as input: %s\n", GPIO_DATA_READY, strerror(errno));
        gpioTerminate();
        return 1;
    }

    g_spi_fd = spi_init();
    if (g_spi_fd < 0) {
        gpioTerminate();
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "wb");
    if (!g_log_fp) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    uint8_t *frame = malloc(FRAME_SIZE);
    if (!frame) {
        fprintf(stderr, "Error allocating heatmap frame buffer\n");
        cleanup();
        return 1;
    }

    printf("Radar heatmap acquisition started. Press Ctrl+C to stop.\n");

    while (g_running) {
        if (trigger_frame() < 0) {
            fprintf(stderr, "Trigger failed, retrying...\n");
            gpioDelay(100000);
            continue;
        }

        int ready = read_data_ready();
        if (ready < 0) {
            fprintf(stderr, "Data ready read error, retrying...\n");
            gpioDelay(100000);
            continue;
        }
        if (ready == 0) {
            gpioDelay(10000);
            continue;
        }

        if (spi_transfer(frame, frame, FRAME_SIZE) < 0) {
            fprintf(stderr, "SPI transfer failed, retrying...\n");
            gpioDelay(100000);
            continue;
        }

        int frame_num = 0;
        for (int i = 0; i < NUM_FRAMES && g_running; i++) {
            if (log_frame(frame, frame_num++) < 0) {
                fprintf(stderr, "Log write failed, stopping.\n");
                break;
            }
        }
    }

    free(frame);
    cleanup();
    printf("Radar heatmap acquisition stopped.\n");
    return 0;
}

