/*
 * KY026 Flame Sensor Monitor — Raspberry Pi Zero W
 *
 * Wiring:
 *   KY026 VCC  -> 3.3 V (Pin 1)
 *   KY026 GND  -> GND   (Pin 9)
 *   KY026 D0   -> GPIO20 (Pin 38, BCM 20)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o flame_monitor flame_monitor.c
 *
 * Run:
 *   ./flame_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>

#define GPIO_CHIP_NAME  "gpiochip0"
#define GPIO_LINE       20          /* BCM 20 */
#define LOG_FILE        "flame_log.txt"
#define POLL_INTERVAL_US 100000     /* 100 ms */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                         */
/* ------------------------------------------------------------------ */
static int gpio_export(int line)
{
    char path[128];
    int fd, len;

    if (line < 0 || line > 31) {
        fprintf(stderr, "Invalid GPIO line number: %d\n", line);
        return -1;
    }

    /* Export the line so it is guaranteed to exist on the chip. */
    len = snprintf(path, sizeof(path), "/sys/class/gpio/export");
    if (len < 0 || (size_t)len >= sizeof(path)) {
        fprintf(stderr, "Path buffer too small for GPIO export\n");
        return -1;
    }
    if (snprintf(path + len, sizeof(path) - (size_t)len, "%d", line) < 0 ||
        (size_t)len + snprintf(path + len, sizeof(path) - (size_t)len, "%d", line) >= sizeof(path)) {
        fprintf(stderr, "Path buffer too small for GPIO export\n");
        return -1;
    }

    fd = open(path, O_WRONLY);
    if (fd == -1) {
        if (errno == EBUSY) {
            /* The line was already exported; nothing to do. */
            return 0;
        }
        fprintf(stderr, "Failed to export GPIO line %d: %s\n",
                line, strerror(errno));
        return -1;
    }

    /* Write the line number and flush. */
    if (write(fd, "0", 1) == -1) {
        fprintf(stderr, "Failed to write GPIO line %d: %s\n",
                line, strerror(errno));
        close(fd);
        return -1;
    }
    if (fsync(fd) == -1) {
        fprintf(stderr, "Warning: fsync failed on GPIO export: %s\n",
                strerror(errno));
    }
    close(fd);
    return 0;
}

static int gpio_unexport(int line)
{
    char path[128];
    int fd, len;

    if (line < 0 || line > 31) {
        fprintf(stderr, "Invalid GPIO line number: %d\n", line);
        return -1;
    }

    len = snprintf(path, sizeof(path), "/sys/class/gpio/unexport");
    if (len < 0 || (size_t)len >= sizeof(path)) {
        fprintf(stderr, "Path buffer too small for GPIO unexport\n");
        return -1;
    }
    if (snprintf(path + len, sizeof(path) - (size_t)len, "%d", line) < 0 ||
        (size_t)len + snprintf(path + len, sizeof(path) - (size_t)len, "%d", line) >= sizeof(path)) {
        fprintf(stderr, "Path buffer too small for GPIO unexport\n");
        return -1;
    }

    fd = open(path, O_WRONLY);
    if (fd == -1) {
        if (errno != EBUSY) {
            fprintf(stderr, "Failed to open GPIO unexport for %d: %s\n",
                    line, strerror(errno));
            return -1;
        }
        /* The line was never exported; nothing to do. */
        return 0;
    }

    /* Write the line number and flush. */
    if (write(fd, "0", 1) == -1) {
        fprintf(stderr, "Failed to write GPIO unexport for %d: %s\n",
                line, strerror(errno));
        close(fd);
        return -1;
    }
    if (fsync(fd) == -1) {
        fprintf(stderr, "Warning: fsync failed on GPIO unexport: %s\n",
                strerror(errno));
    }
    close(fd);
    return 0;
}

static int gpio_set_direction(int line, const char *direction)
{
    char path[256];
    int fd, len;

    if (line < 0 || line > 31) {
        fprintf(stderr, "Invalid GPIO line number: %d\n", line);
        return -1;
    }

    len = snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", line);
    if (len < 0 || (size_t)len >= sizeof(path)) {
        fprintf(stderr, "Path buffer too small for GPIO direction\n");
        return -1;
    }
    if (snprintf(path + len, sizeof(path) - (size_t)len, "%s", direction) < 0 ||
        (size_t)len + snprintf(path + len, sizeof(path) - (size_t)len, "%s", direction) >= sizeof(path)) {
        fprintf(stderr, "Path buffer too small for GPIO direction\n");
        return -1;
    }

    fd = open(path, O_WRONLY);
    if (fd == -1) {
        fprintf(stderr, "Failed to open GPIO direction for %d: %s\n",
                line, strerror(errno));
        return -1;
    }

    if (write(fd, direction, strlen(direction)) == -1) {
        fprintf(stderr, "Failed to write GPIO direction for %d: %s\n",
                line, strerror(errno));
        close(fd);
        return -1;
    }

    if (fsync(fd) == -1) {
        fprintf(stderr, "Warning: fsync failed on GPIO direction: %s\n",
                strerror(errno));
    }
    close(fd);
    return 0;
}

static int gpio_get_value(int line)
{
    char path[256];
    int fd, len;
    char value;
    int ret;

    if (line < 0 || line > 31) {
        fprintf(stderr, "Invalid GPIO line number: %d\n", line);
        return -1;
    }

    len = snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", line);
    if (len < 0 || (size_t)len >= sizeof(path)) {
        fprintf(stderr, "Path buffer too small for GPIO value\n");
        return -1;
    }
    if (snprintf(path + len, sizeof(path) - (size_t)len, "%c", '0') < 0 ||
        (size_t)len + snprintf(path + len, sizeof(path) - (size_t)len, "%c", '0') >= sizeof(path)) {
        fprintf(stderr, "Path buffer too small for GPIO value\n");
        return -1;
    }

    fd = open(path, O_RDONLY);
    if (fd == -1) {
        fprintf(stderr, "Failed to open GPIO value for %d: %s\n",
                line, strerror(errno));
        return -1;
    }

    ret = read(fd, &value, 1);
    if (ret == -1) {
        fprintf(stderr, "Failed to read GPIO value for %d: %s\n",
                line, strerror(errno));
        close(fd);
        return -1;
    }
    if (ret == 0) {
        fprintf(stderr, "GPIO value read returned 0 bytes for %d\n", line);
        close(fd);
        return -1;
    }

    if (fsync(fd) == -1) {
        fprintf(stderr, "Warning: fsync failed on GPIO value: %s\n",
                strerror(errno));
    }
    close(fd);

    /* '0' or '1' — return as integer. */
    return (value == '1') ? 1 : 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_event(const char *timestamp, int state)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return -1;
    }

    if (fprintf(fp, "%s,%d\n", timestamp, state) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fflush(fp) == EOF) {
        fprintf(stderr, "Failed to flush log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) == EOF) {
        fprintf(stderr, "Failed to close log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int prev_state = -1;
    int ret = EXIT_SUCCESS;

    if (install_signal_handlers() == -1) {
        return EXIT_FAILURE;
    }

    /* Export the GPIO line so it is guaranteed to exist on the chip. */
    if (gpio_export(GPIO_LINE) == -1) {
        return EXIT_FAILURE;
    }

    /* Set the line as input. */
    if (gpio_set_direction(GPIO_LINE, "in") == -1) {
        gpio_unexport(GPIO_LINE);
        return EXIT_FAILURE;
    }

    printf("Monitoring KY026 flame sensor on GPIO%d (BCM). Press Ctrl+C to exit.\n",
           GPIO_LINE);

    while (g_running) {
        int current_state = gpio_get_value(GPIO_LINE);
        if (current_state == -1) {
            /* Error reading the sensor; back off and retry. */
            usleep(POLL_INTERVAL_US);
            continue;
        }

        if (current_state != prev_state) {
