/*
 * OPT3001 Ambient Light Sensor reader for Raspberry Pi Zero W
 * I2C bus 1, continuous conversion mode, automatic full-scale range.
 * Reads lux every ~100 ms and appends a timestamped entry to
 * light_data.txt on every successful conversion.
 *
 * Build:  gcc -O2 -Wall -Wextra -o opt3001_reader opt3001_reader.c
 * Run:    ./opt3001_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define OPT3001_ADDR   0x44
#define LOG_FILE       "light_data.txt"
#define SAMPLE_MS      100

/* OPT3001 register addresses */
#define REG_RESULT     0x00
#define REG_CONFIG     0x01
#define REG_MANUF_ID   0x0D
#define REG_DEV_ID     0x0E

/* Config register bits */
#define CFG_OS         0x8000  /* Operational status / mode */
#define CFG_MHD        0x0000  /* High range / low range */
#define CFG_FSR        0x0000  /* Full-scale range */
#define CFG_MODE       0x0000  /* Continuous conversion */
#define CFG_INT_EN     0x0000  /* Disable interrupts */
#define CFG_INT_THS    0x0000  /* No threshold */
#define CFG_INT_MODE   0x0000  /* No mode */
#define CFG_INT_EN     0x0000  /* Disable interrupts */

/* Lux resolution for auto-range (1 LSB = 0.5 lux) */
#define LUX_PER_LSB    0.5f

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* Write a 16-bit value to an OPT3001 register (big-endian on wire). */
static int opt3001_write_reg(int fd, uint8_t reg, uint16_t value)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(value >> 8);
    buf[2] = (uint8_t)(value & 0xFF);

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a 16-bit value from an OPT3001 register (big-endian on wire). */
static int opt3001_read_reg(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t reg_buf = reg;
    uint8_t data[2];

    if (write(fd, &reg_buf, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (read(fd, data, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

/* Read the 16-bit result register and convert to lux. */
static int opt3001_read_lux(int fd, float *lux_out)
{
    uint16_t raw;
    uint16_t manuf_id, dev_id;

    if (opt3001_read_reg(fd, REG_RESULT, &raw) < 0)
        return -1;

    if (opt3001_read_reg(fd, REG_MANUF_ID, &manuf_id) < 0)
        return -1;

    if (opt3001_read_reg(fd, REG_DEV_ID, &dev_id) < 0)
        return -1;

    /* Validate device identity (0x5449 = OPT3001). */
    if (manuf_id != 0x5449 || dev_id != 0x5449) {
        fprintf(stderr, "Sensor identity mismatch: "
                "manuf=0x%04X dev=0x%04X (expected 0x5449)\n",
                manuf_id, dev_id);
        return -1;
    }

    /* Check operational status bit (OS) in config register. */
    uint16_t cfg;
    if (opt3001_read_reg(fd, REG_CONFIG, &cfg) < 0)
        return -1;

    if (!(cfg & CFG_OS)) {
        fprintf(stderr, "OPT3001 not in operational mode (OS=0x%04X)\n", cfg);
        return -1;
    }

    /* Clear OS bit to start a new conversion. */
    if (opt3001_write_reg(fd, REG_CONFIG, CFG_OS | 0x0001) < 0)
        return -1;

    /* Wait for OS bit to clear (conversion complete). */
    for (int i = 0; i < 20; i++) {
        if (opt3001_read_reg(fd, REG_CONFIG, &cfg) < 0)
            return -1;
        if (!(cfg & CFG_OS))
            break;
        usleep(5000);
    }
    if (cfg & CFG_OS) {
        fprintf(stderr, "OPT3001 conversion timeout\n");
        return -1;
    }

    /* Read result register. */
    if (opt3001_read_reg(fd, REG_RESULT, &raw) < 0)
        return -1;

    /* Full-scale range bits (bits 12:11 of config) */
    uint16_t fsr = (cfg >> 11) & 0x0003;
    if (fsr == 0x03) {
        /* Auto-range: lux = raw * 0.5 */
        *lux_out = (float)raw * LUX_PER_LSB;
    } else {
        /* Fixed range: lux = raw * (fsr / 4095) */
        *lux_out = (float)raw * (float)fsr / 4095.0f;
    }

    return 0;
}

static int log_data(float lux)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%.2f\n", ts, lux) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    /* Signal handling for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire I2C slave address */
    if (ioctl(fd, I2C_SLAVE, OPT3001_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                OPT3001_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("OPT3001 reader started on %s (addr 0x%02X). Logging to %s\n",
           I2C_BUS, OPT3001_ADDR, LOG_FILE);

    while (g_running) {
        float lux;
        if (opt3001_read_lux(fd, &lux) == 0) {
            printf("Lux: %.2f\n", lux);
            if (log_data(lux) < 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
        } else {
            fprintf(stderr, "Read failed; will retry.\n");
        }

        /* Sleep SAMPLE_MS, but wake early on signal */
        for (int ms = 0; ms < SAMPLE_MS && g_running; ms += 10)
            usleep(10 * 1000);
    }

    printf("\nShutting down cleanly.\n");
    close(fd);
    return EXIT_SUCCESS;
}

