    if (opt3001_read_reg(fd, REG_CONFIG, &cfg) < 0)
        return -1;

    if (!(cfg & CFG_OS)) {
        fprintf(stderr, "OPT3001 not in operational mode (OS=0x%04X)\n", cfg);
        return -1;
    }

    /* Clear OS bit to start a new conversion. */
    if (opt3001_write_reg(fd, REG_CONFIG, CFG_OS | 0x0001) < 0)
        return -1;

    /* Wait for OS bit to clear (conversion complete). */
    for (int i = 0; i < 20; i++) {
        if (opt3001_read_reg(fd, REG_CONFIG, &cfg) < 0)
            return -1;
        if (!(cfg & CFG_OS))
            break;
        usleep(5000);
    }
    if (cfg & CFG_OS) {
        fprintf(stderr, "OPT3001 conversion timeout\n");
        return -1;
    }

    /* Read result register. */
    if (opt3001_read_reg(fd, REG_RESULT, &raw) < 0)
        return -1;

    /* Full-scale range bits (bits 12:11 of config) */
    uint16_t fsr = (cfg >> 11) & 0x0003;
    if (fsr == 0x03) {
        /* Auto-range: lux = raw * 0.5 */
        *lux_out = (float)raw * LUX_PER_LSB;
    } else {
        /* Fixed range: lux = raw * (fsr / 4095) */
        *lux_out = (float)raw * (float)fsr / 4095.0f;
    }

    return 0;
}

static int log_data(float lux)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%.2f\n", ts, lux) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    /* Signal handling for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire I2C slave address */
    if (ioctl(fd, I2C_SLAVE, OPT3001_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                OPT3001_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("OPT3001 reader started on %s (addr 0x%02X). Logging to %s\n",
           I2C_BUS, OPT3001_ADDR, LOG_FILE);

    while (g_running) {
        float lux;
        if (opt3001_read_lux(fd, &lux) == 0) {
            printf("Lux: %.2f\n", lux);
            if (log_data(lux) < 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
        } else {
            fprintf(stderr, "Read failed; will retry.\n");
        }

        /* Sleep SAMPLE_MS, but wake early on signal */
        for (int ms = 0; ms < SAMPLE_MS && g_running; ms += 10)
            usleep(10 * 1000);
    }

    printf("\nShutting down cleanly.\n");
    close(fd);
    return EXIT_SUCCESS;
}

