 * Board:  Raspberry Pi 3 Model B+
 * Bus:    /dev/gpiochip0 (BCM numbering)
 * Sensor: SainSmart IR Flame Detection Module
 * Line:   GPIO 17 (BCM 17), active-low, pulled-up
 *
 * Build:  gcc -Wall -Wextra -O2 -o flame_detect flame_detect.c -lgpiod
 * Run:    ./flame_detect
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME  "gpiochip0"
#define GPIO_LINE       17          /* BCM 17 */
#define POLL_INTERVAL_S 1           /* seconds between readings */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_sigint_handler(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm timeinfo;

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        snprintf(buf, len, "UNKNOWN");
        return;
    }
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &timeinfo);
}

static void log_flame_status(int flame_detected)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));

    if (flame_detected) {
        printf("%s - Flame Detected: YES\n", ts);
    } else {
        printf("%s - Flame Detected: NO\n", ts);
    }
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_request *req = NULL;
    struct gpiod_line_settings *settings = NULL;
    struct gpiod_line_config *line_cfg = NULL;
    struct gpiod_request_config *req_cfg = NULL;
    struct gpiod_line_request_config *req_cfg2 = NULL;
    int ret = EXIT_FAILURE;

    /* --- Signal handling ------------------------------------------- */
    if (install_sigint_handler() < 0) {
        return EXIT_FAILURE;
    }

    /* --- Open the GPIO chip ----------------------------------------- */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Configure the line request -------------------------------- */
    settings = gpiod_line_settings_new();
    if (settings == NULL) {
        fprintf(stderr, "gpiod_line_settings_new() failed\n");
        goto cleanup;
    }

    line_cfg = gpiod_line_config_new();
    if (line_cfg == NULL) {
        fprintf(stderr, "gpiod_line_config_new() failed\n");
        goto cleanup;
    }

    req_cfg = gpiod_request_config_new();
    if (req_cfg == NULL) {
        fprintf(stderr, "gpiod_request_config_new() failed\n");
        goto cleanup;
    }

    req_cfg2 = gpiod_line_request_config_new();
    if (req_cfg2 == NULL) {
        fprintf(stderr, "gpiod_line_request_config_new() failed\n");
        goto cleanup;
    }

    /* --- Line settings: input, active-low, pull-up ------------------ */
    gpiod_line_settings_set_direction(settings, GPIOD_LINE_DIRECTION_INPUT);
    gpiod_line_settings_set_bias(settings, GPIOD_LINE_BIAS_PULL_UP);
    gpiod_line_settings_set_edge_detection(settings, GPIOD_LINE_EDGE_NONE);

    /* --- Line config: single BCM 17 ------------------------------- */
    if (gpiod_line_config_add_line_settings(line_cfg, &(unsigned int){GPIO_LINE}, 1, settings) < 0) {
        fprintf(stderr, "gpiod_line_config_add_line_settings() failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* --- Request config: consumer label ---------------------------- */
    gpiod_request_config_set_consumer(req_cfg, "flame_detect");

    /* --- Request the line ------------------------------------------ */
    req = gpiod_chip_request_lines(chip, req_cfg, line_cfg);
    if (req == NULL) {
        fprintf(stderr, "gpiod_chip_request_lines() failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* --- Request config (second pass) for the request object -------- */
    gpiod_line_request_config_set_consumer(req_cfg2, "flame_detect");

    /* --- Main loop -------------------------------------------------- */
    while (g_running) {
        int value = gpiod_line_request_get_value(req, GPIO_LINE);
        if (value < 0) {
            fprintf(stderr, "gpiod_line_request_get_value() failed: %s\n", strerror(errno));
            goto cleanup;
        }

        /* SainSmart module is active-low: 0 = flame detected, 1 = no flame */
        log_flame_status(value == 0 ? 1 : 0);

        /* Sleep for the polling interval */
        sleep(POLL_INTERVAL_S);
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Release the line request */
    if (req != NULL) {
        gpiod_line_request_release(req);
    }

    /* Release the request config (optional but safe) */
    if (req_cfg2 != NULL) {
        gpiod_line_request_config_free(req_cfg2);
    }

    /* Free the request config */
    if (req_cfg != NULL) {
        gpiod_request_config_free(req_cfg);
    }

    /* Free the line config */
    if (line_cfg != NULL) {
        gpiod_line_config_free(line_cfg);
    }

    /* Free the line settings */
    if (settings != NULL) {
        gpiod_line_settings_free(settings);
    }

    /* Close the chip */
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    return ret;
}

