#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LEFT_PIN 17
#define CENTER_PIN 18
#define RIGHT_PIN 27
#define POLL_DELAY_US 50000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor(int pin) {
    int value = gpioRead(pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", pin, value);
        return -1;
    }
    return value;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LEFT_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", LEFT_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(CENTER_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", CENTER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(RIGHT_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", RIGHT_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        int left = read_sensor(LEFT_PIN);
        int center = read_sensor(CENTER_PIN);
        int right = read_sensor(RIGHT_PIN);

        if (left == -1 || center == -1 || right == -1) {
            break;
        }

        printf("Left: %d, Center: %d, Right: %d\n", left, center, right);
        fflush(stdout);

        usleep(POLL_DELAY_US);
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

