/*
 * TTP226 8-channel digital touch sensor reader for Raspberry Pi Zero W.
 *
 * Wiring (BCM numbering):
 *   TTP226 OUT1 -> GPIO2  (pin 3)
 *   TTP226 OUT2 -> GPIO3  (pin 5)
 *   TTP226 OUT3 -> GPIO4  (pin 7)
 *   TTP226 OUT4 -> GPIO5  (pin 8)
 *   TTP226 OUT5 -> GPIO6  (pin 10)
 *   TTP226 OUT6 -> GPIO7  (pin 11)
 *   TTP226 OUT7 -> GPIO8  (pin 12)
 *   TTP226 OUT8 -> GPIO9  (pin 14)
 *
 * The TTP226 is configured for direct GPIO output; the program reads the
 * lines directly and prints the binary state of each channel.
 *
 * Build:  gcc -O2 -Wall -Wextra -o ttp226_reader ttp226_reader.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>

#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_US 100000  /* 100 ms */

/* BCM GPIO pin numbers connected to TTP226 OUT1..OUT8 */
static const unsigned int gpio_pins[NUM_CHANNELS] = {
    2, 3, 4, 5, 6, 7, 8, 9
};

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void print_timestamp(void)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char buf[32];

    if (localtime_r(&now, &tm_info) != NULL &&
        strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &tm_info) > 0) {
        printf("[%s] ", buf);
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_CHANNELS];
    int line_handles[NUM_CHANNELS];
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = NULL;
        line_handles[i] = -1;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error: failed to install SIGINT handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error: failed to install SIGTERM handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Pi Zero W) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Error: failed to open gpiochip0: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire each line and request it as input */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, gpio_pins[i]);
        if (lines[i] == NULL) {
