        fprintf(stderr, "Error: cannot install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error: cannot install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on RPi 3 B+) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Error: cannot open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire each GPIO line as input with pull-down */
    for (i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, gpio_pins[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "Error: cannot get GPIO line %u: %s\n",
                    gpio_pins[i], strerror(errno));
            goto cleanup;
        }

        ret = gpiod_line_request_input_flags(lines[i], "ttp226-reader",
                                              GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN);
        if (ret < 0) {
            fprintf(stderr, "Error: cannot request GPIO line %u as input: %s\n",
                    gpio_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    printf("TTP226 8-channel touch sensor reader started.\n");
    printf("Sampling every %u ms. Press Ctrl+C to exit.\n", SAMPLE_INTERVAL_US);

    while (program_running) {
        int values[NUM_CHANNELS];
        int ret;

        ret = gpiod_line_get_value_all(lines, values);
        if (ret < 0) {
            fprintf(stderr, "Error: gpiod_line_get_value_all failed: %s\n",
                    strerror(errno));
            break;
        }

        for (i = 0; i < NUM_CHANNELS; i++)
            printf("CH%d=%d ", i + 1, values[i]);

        printf("\n");
        fflush(stdout);

        sleep_ms(SAMPLE_INTERVAL_US);
    }

    printf("\nExiting...\n");

cleanup:
    for (i = 0; i < NUM_CHANNELS; i++) {
        if (lines[i] != NULL)
            gpiod_line_release(lines[i]);
    }
    if (chip != NULL)
        gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

