/*
 * TMAG5110 Hall-Effect Latch Sensor Reader for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   Sensor 1 OUT -> BCM GPIO4 (physical pin 7)
 *   Sensor 2 OUT -> BCM GPIO5 (physical pin 11)
 *   VCC -> 3.3 V, GND -> GND
 *
 * The TMAG5110 outputs are open-drain; external pull-up resistors are
 * assumed on the Pi GPIO pins.  An asserted (magnet-detected) output
 * reads LOW, an unasserted output reads HIGH.
 *
 * Build:
 *   gcc -Wall -o hall_effect hall_effect.c -lthe -lrt
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <stdbool.h>
#include <the.h>

#define SENSOR1_PIN 4
#define SENSOR2_PIN 5
#define POLL_INTERVAL_US 500000  /* 500 ms */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

int main(void)
{
    /* Install SIGINT handler for clean shutdown on Ctrl+C */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* Initialize the the driver library */
    if (the_init() != 0) {
        fprintf(stderr, "Error: the driver library initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure sensor pins as inputs */
    if (the_gpio_set_mode(SENSOR1_PIN, THE_GPIO_MODE_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SENSOR1_PIN);
        the_cleanup();
        return EXIT_FAILURE;
    }
    if (the_gpio_set_mode(SENSOR2_PIN, THE_GPIO_MODE_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SENSOR2_PIN);
        the_cleanup();
        return EXIT_FAILURE;
    }

    /* Enable internal pull-ups so the open-drain outputs read HIGH when
     * unasserted and LOW when asserted.  External pull-ups are assumed
     * on the Pi pins. */
    if (the_gpio_set_pull_up(SENSOR1_PIN, THE_GPIO_PULL_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d.\n", SENSOR1_PIN);
        the_cleanup();
        return EXIT_FAILURE;
    }
    if (the_gpio_set_pull_up(SENSOR2_PIN, THE_GPIO_PULL_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d.\n", SENSOR2_PIN);
        the_cleanup();
        return EXIT_FAILURE;
    }

    printf("TMAG5110 Hall-Effect Sensor Reader\n");
    printf("  Sensor 1 OUT -> BCM GPIO%d\n", SENSOR1_PIN);
    printf("  Sensor 2 OUT -> BCM GPIO%d\n", SENSOR2_PIN);
    printf("  Poll interval: %d ms\n", POLL_INTERVAL_US / 1000);
    printf("Press Ctrl+C to exit.\n\n");

    /* Main polling loop */
    while (g_running) {
        int s1 = the_gpio_read(SENSOR1_PIN);
        int s2 = the_gpio_read(SENSOR2_PIN);

        if (s1 < 0) {
            fprintf(stderr, "Error: failed to read GPIO%d.\n", SENSOR1_PIN);
            break;
        }
        if (s2 < 0) {
            fprintf(stderr, "Error: failed to read GPIO%d.\n", SENSOR2_PIN);
            break;
        }

        /* TMAG5110 outputs are open-drain: HIGH = no magnet, LOW = magnet detected */
        printf("Sensor 1 (GPIO%d): %s\n", SENSOR1_PIN,
               (s1 == 0) ? "LOW" : "HIGH");
        printf("Sensor 2 (GPIO%d): %s\n", SENSOR2_PIN,
               (s2 == 0) ? "LOW" : "HIGH");
        printf("---\n");

        usleep(POLL_INTERVAL_US);
    }

    /* Clean up and terminate the driver library */
    the_cleanup();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

