{
    (void)sig;
    g_running = 0;
}

static void print_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        snprintf(buf, len, "1970-01-01T00:00:00");
        return;
    }
    struct tm tmv;
    if (localtime_r(&now, &tmv) == NULL) {
        snprintf(buf, len, "1970-01-01T00:00:00");
        return;
    }
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tmv);
}

int main(void)
{
