                                            GPIOD_LINE_REQUEST_FLAG_BIAS_DISABLE) < 0) {
            fprintf(stderr, "Failed to request GPIO line %u as input: %s\n",
                    sensor_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    printf("TTP226 touch sensor reader started. Press Ctrl-C to exit.\n");
    fflush(stdout);

    /* --- Main polling loop --- */
    while (g_running) {
        char ts[32];
        print_timestamp(ts, sizeof(ts));

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int val = gpiod_line_get_value(lines[i]);
            if (val < 0) {
                fprintf(stderr, "Error reading GPIO %u: %s\n",
                        sensor_pins[i], strerror(errno));
                goto cleanup;
            }
            printf("%s,%d", ts, val);
        }
        printf("\n");
        fflush(stdout);

        usleep(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup:
    /* --- Release lines and close chip --- */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (lines[i] != NULL) {
            gpiod_line_release(lines[i]);
            lines[i] = NULL;
        }
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    return ret;
}

