/*
 * TTP226 8-channel capacitive touch sensor reader for Raspberry Pi 4 Model B.
 *
 * Wiring (BCM numbering):
 *   Channel 1 -> GPIO 2  (physical pin 3)
 *   Channel 2 -> GPIO 3  (physical pin 5)
 *   Channel 3 -> GPIO 4  (physical pin 7)
 *   Channel 4 -> GPIO 17 (physical pin 11)
 *   Channel 5 -> GPIO 27 (physical pin 13)
 *   Channel 6 -> GPIO 22 (physical pin 15)
 *   Channel 7 -> GPIO 10 (physical pin 19)
 *   Channel 8 -> GPIO 9  (physical pin 21)
 *
 * Build:  gcc -O2 -Wall -Wextra -o ttp226 ttp226.c
 * Run:    ./ttp226
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>

#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_US 50000   /* 50 ms */

static const unsigned int sensor_pins[NUM_CHANNELS] = {
    2, 3, 4, 17, 27, 22, 10, 9
};

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void print_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        snprintf(buf, len, "1970-01-01T00:00:00");
        return;
    }
    struct tm tmv;
    if (localtime_r(&now, &tmv) == NULL) {
        snprintf(buf, len, "1970-01-01T00:00:00");
        return;
    }
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tmv);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_CHANNELS];
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_CHANNELS; i++)
        lines[i] = NULL;

    /* --- Install signal handlers for graceful shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open the default gpiochip (gpiochip4 on Pi 4 with 5.10+ kernel) --- */
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (chip == NULL) {
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (chip == NULL) {
        chip = gpiod_chip_open_by_label("pinctrl-bcm2835");
    }
    if (chip == NULL) {
        chip = gpiod_chip_open_lookup("gpiochip4");
    }
    if (chip == NULL) {
        chip = gpiod_chip_open_lookup("gpiochip0");
    }
    if (chip == NULL) {
        fprintf(stderr, "Failed to open any gpiochip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Request each line as input with bias disabled --- */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "Failed to get GPIO line %u: %s\n",
                    sensor_pins[i], strerror(errno));
            goto cleanup;
        }

        if (gpiod_line_request_input_flags(lines[i], "ttp226",
                                            GPIOD_LINE_REQUEST_FLAG_BIAS_DISABLE) < 0) {
            fprintf(stderr, "Failed to request GPIO line %u as input: %s\n",
                    sensor_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    printf("TTP226 touch sensor reader started. Press Ctrl-C to exit.\n");
    fflush(stdout);

    /* --- Main polling loop --- */
    while (g_running) {
        char ts[32];
        print_timestamp(ts, sizeof(ts));

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int val = gpiod_line_get_value(lines[i]);
            if (val < 0) {
                fprintf(stderr, "Error reading GPIO %u: %s\n",
                        sensor_pins[i], strerror(errno));
                goto cleanup;
            }
            printf("%s,%d", ts, val);
        }
        printf("\n");
        fflush(stdout);

        usleep(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup:
    /* --- Release lines and close chip --- */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (lines[i] != NULL) {
            gpiod_line_release(lines[i]);
            lines[i] = NULL;
        }
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    return ret;
}

