/*
 * Raspberry Pi Zero W – Omron D7E‑1 Tilt Sensor Monitor
 *
 * Wiring:
 *   D7E‑1 OUT  -> GPIO4  (BCM pin 7)
 *   D7E‑1 VCC  -> 3.3 V
 *   D7E‑1 GND  -> GND
 *
 * The D7E‑1 has an internal pull-up; the program configures the pin as
 * input with the internal pull-up enabled so that the pin reads HIGH
 * when the sensor is idle and LOW when the tilt switch closes the
 * internal circuit to GND.
 *
 * Build:  gcc -O2 -Wall -Wextra -o tilt_monitor tilt_monitor.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <pigpio.h>

#define TILT_GPIO 4          /* BCM pin 4 */
#define POLL_MS    100       /* polling interval in milliseconds */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler – set flag so main loop exits and cleanup runs.     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read the tilt sensor and print the current state.                  */
/* Returns 0 on success, -1 on read error.                             */
/* ------------------------------------------------------------------ */
static int read_tilt_sensor(int gpio_pin, int *out_value)
{
    int v = gpioRead(gpio_pin);
    if (v < 0) {
        fprintf(stderr, "Error: gpioRead(%d) failed (rc=%d)\n",
                gpio_pin, v);
        return -1;
    }
    *out_value = v;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log the tilt state to the console.                                  */
/* ------------------------------------------------------------------ */
static void log_tilt_state(int tilt_state)
{
    if (tilt_state == 0) {
        printf("Tilted\n");
    } else if (tilt_state == 1) {
        printf("Not Tilted\n");
    } else {
        fprintf(stderr, "Error: unexpected tilt state %d\n", tilt_state);
    }
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Install SIGINT handler for clean shutdown ---- */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure GPIO4 as input with internal pull-up ---- */
    if (gpioSetMode(TILT_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_INPUT) failed\n",
                TILT_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(TILT_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(%d, PI_PUD_UP) failed\n",
                TILT_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Main polling loop ---- */
    bool first_read = true;

    while (g_running) {
        int tilt_state = 0;

        if (read_tilt_sensor(TILT_GPIO, &tilt_state) != 0) {
            /* Read error already reported; keep running and retry. */
            gpioDelay(POLL_MS * 1000);
            continue;
        }

        if (tilt_state != first_read) {
            log_tilt_state(tilt_state);
            first_read = tilt_state;
        }

        gpioDelay(POLL_MS * 1000);   /* 100 ms */
    }

    /* ---- Clean shutdown ---- */
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

