/*
 * Si1145 UV Index & Ambient Light Logger for Raspberry Pi 4 Model B
 * I2C bus 1, bus address 0x53
 * Logs timestamp, UV index, and visible ambient light to uv_als_log.csv
 * Handles I2C errors, SIGINT/SIGTERM, and resource cleanup.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SI1145_ADDR        0x53
#define I2C_BUS            "/dev/i2c-1"
#define LOG_FILE           "uv_als_log.csv"
#define SAMPLE_INTERVAL_S  1

/* Si1145 register addresses */
#define SI1145_REG_PART_ID      0x00
#define SI1145_REG_HW_KEY       0x07
#define SI1145_REG_UCOEF0       0x10
#define SI1145_REG_ALS_VIS_DATA0 0x22
#define SI1145_REG_ALS_VIS_DATA1 0x23
#define SI1145_REG_ALS_IR_DATA0  0x24
#define SI1145_REG_ALS_IR_DATA1  0x25
#define SI1145_REG_UCOEF1       0x11
#define SI1145_REG_UCOEF2       0x12
#define SI1145_REG_UCOEF3       0x13
#define SI1145_REG_MEAS_RATE0   0x08
#define SI1145_REG_MEAS_RATE1   0x09
#define SI1145_REG_ALS_RATE     0x0A
#define SI1145_REG_PARAM_WR     0x17
#define SI1145_REG_COMMAND      0x18
#define SI1145_REG_RESPONSE     0x20

#define SI1145_CMD_RESET        0x01
#define SI1145_CMD_PARAM_QUERY  0x80
#define SI1145_CMD_PARAM_SET    0xA0
#define SI1145_CMD_ALS_FORCE    0x06
#define SI1145_CMD_ALS_AUTO     0x05
#define SI1145_CMD_PS_FORCE     0x05
#define SI1145_CMD_PS_AUTO      0x04
#define SI1145_CMD_PS_FORCE_PSALS 0x0F

#define SI1145_PARAM_CHLIST    0x01
#define SI1145_PARAM_PS1_ADCMUX 0x02
#define SI1145_PARAM_ALS_VIS_ADCMUX 0x03
#define SI1145_PARAM_ALS_IR_ADCMUX 0x04
#define SI1145_PARAM_PS_ADC_GAIN 0x05
#define SI1145_PARAM_ALS_ADC_GAIN 0x06
#define SI1145_PARAM_PS_ADC_COUNTER 0x07
#define SI1145_PARAM_ALS_ADC_COUNTER 0x08
#define SI1145_PARAM_MEAS_RATE 0x09
#define SI1145_PARAM_ALS_RATE 0x0A
#define SI1145_PARAM_PS_RATE 0x0B
#define SI1145_PARAM_PSALS_RATE 0x0C
#define SI1145_PARAM_UCOEF0 0x0F
#define SI1145_PARAM_UCOEF1 0x10
#define SI1145_PARAM_UCOEF2 0x11
#define SI1145_PARAM_UCOEF3 0x12
#define SI1145_PARAM_RESPONSE 0x13

#define SI1145_PART_ID         0x45

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read16 from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int si1145_wait_response(int fd, uint8_t expected_cmd) {
    uint8_t resp;
    for (int i = 0; i < 20; i++) {
        if (i2c_read_reg8(fd, SI1145_REG_RESPONSE, &resp) < 0) return -1;
        if ((resp & 0x0F) == expected_cmd) return 0;
        usleep(10000);
    }
    fprintf(stderr, "Si1145 response timeout for cmd 0x%02X\n", expected_cmd);
    return -1;
}

static int si1145_write_param(int fd, uint8_t param, uint8_t value) {
    if (i2c_write_reg8(fd, SI1145_REG_PARAM_WR, value) < 0) return -1;
    if (i2c_write_reg8(fd, SI1145_REG_COMMAND, SI1145_CMD_PARAM_SET | param) < 0) return -1;
    return si1145_wait_response(fd, SI1145_CMD_PARAM_SET | param);
}

static int si1145_init(int fd) {
    uint8_t part_id;
    if (i2c_read_reg8(fd, SI1145_REG_PART_ID, &part_id) < 0) return -1;
    if (part_id != SI1145_PART_ID) {
        fprintf(stderr, "Si1145 not detected (PART_ID=0x%02X, expected 0x%02X)\n", part_id, SI1145_PART_ID);
        return -1;
    }

    if (i2c_write_reg8(fd, SI1145_REG_HW_KEY, 0x17) < 0) return -1;
    if (i2c_write_reg8(fd, SI1145_REG_MEAS_RATE0, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, SI1145_REG_MEAS_RATE1, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, SI1145_REG_ALS_RATE, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, SI1145_REG_PSALS_RATE, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, SI1145_REG_ALS_VIS_ADCMUX, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, SI1145_REG_ALS_IR_ADCMUX, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, SI1145_REG_PS_ADC_GAIN, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, SI1145_REG_ALS_ADC_GAIN, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, SI1145_REG_PS_ADC_COUNTER, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, SI1145_REG_ALS_ADC_COUNTER, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, SI1145_REG_MEAS_RATE0, 0x0A) < 0) return -1;
    if (i2c_write_reg8(fd, SI1145_REG_MEAS_RATE1, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, SI1145_REG_COMMAND, SI1145_CMD_RESET) < 0) return -1;
    if (si1145_wait_response(fd, SI1145_CMD_RESET) < 0) return -1;
    usleep(100000);
    return 0;
}

static int si1145_read_uv_index(int fd, float *uv_index) {
    if (i2c_write_reg8(fd, SI1145_REG_COMMAND, SI1145_CMD_ALS_FORCE) < 0) return -1;
    if (si1145_wait_response(fd, SI1145_CMD_ALS_FORCE) < 0) return -1;
    uint16_t als_vis;
    if (i2c_read_reg16(fd, SI1145_REG_ALS_VIS_DATA0, &als_vis) < 0) return -1;
    *uv_index = (float)als_vis / 100.0f;
    return 0;
}

static int si1145_read_ambient_light(int fd, uint16_t *als_vis, uint16_t *als_ir) {
    if (i2c_write_reg8(fd, SI1145_REG_COMMAND, SI1145_CMD_ALS_FORCE) < 0) return -1;
    if (si1145_wait_response(fd, SI1145_CMD_ALS_FORCE) < 0) return -1;
    uint16_t als_vis_raw, als_ir_raw;
    if (i2c_read_reg16(fd, SI1145_REG_ALS_VIS_DATA0, &als_vis_raw) < 0) return -1;
    if (i2c_read_reg16(fd, SI1145_REG_ALS_IR_DATA0, &als_ir_raw) < 0) return -1;
    *als_vis = als_vis_raw;
    *als_ir = als_ir_raw;
    return 0;
}

static void log_data(FILE *fp, float uv_index, uint16_t als_vis, uint16_t als_ir) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) return;
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f,%u,%u\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            uv_index, als_vis, als_ir);
    fflush(fp);
}

static void cleanup(void) {
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
