/*
 * Raspberry Pi 5 – Dual SLF3S-0600F Liquid Flow Sensor Monitor
 *
 * Wiring:
 *   Sensor 1: I2C bus 1 (GPIO2/3), SDA=GPIO2, SCL=GPIO3
 *   Sensor 2: I2C bus 1 (GPIO2/3), SDA=GPIO2, SCL=GPIO3
 *   Alarm:    GPIO17 (BCM), active-high
 *
 * Build:  gcc -O2 -Wall -o flow_monitor flow_monitor.c -lpigpio -lrt
 * Run:    sudo ./flow_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS          "/dev/i2c-1"
#define ALARM_GPIO       17
#define FLOW_LOG_FILE    "flow_log.txt"
#define NUM_SENSORS      2
#define SAMPLE_PERIOD_S  1
#define START_CMD_LEN    2
#define START_CMD_VAL    0x36
#define MEAS_CMD_LEN     2
#define MEAS_CMD_VAL     0x36
#define CRC_POLY         0x31
#define CRC_INIT         0xFF
#define FLOW_THRESHOLD   0.5f
#define MAX_FLOW_RATE    10.0f
#define MAX_SENSORS     4
#define MAX_READINGS    100

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Sensirion CRC-8 (polynomial 0x31, init 0xFF)                        */
/* ------------------------------------------------------------------ */
static uint8_t sensirion_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = CRC_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ CRC_POLY : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int fd, const uint8_t *cmd, size_t len)
{
    if (write(fd, cmd, len) != (ssize_t)len) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "I2C read failed: got %zd of %zu bytes: %s\n",
                n, len, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor abstraction                                                  */
/* ------------------------------------------------------------------ */
typedef struct {
    int fd;
    float flow_rate;
    int valid;
} sensor_t;

static int sensor_init(sensor_t *s)
{
    s->fd = open(I2C_BUS, O_RDWR);
    if (s->fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(s->fd, I2C_SLAVE, 0x60) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE) failed: %s\n", strerror(errno));
        close(s->fd);
        s->fd = -1;
        return -1;
    }
    return 0;
}

static int sensor_start(sensor_t *s)
{
    uint8_t cmd[START_CMD_LEN] = { START_CMD_VAL, MEAS_CMD_VAL };
    return i2c_write_cmd(s->fd, cmd, START_CMD_LEN);
}

static int sensor_read(sensor_t *s, float *out)
{
    uint8_t buf[9];
    if (i2c_read_bytes(s->fd, buf, sizeof(buf)) < 0)
        return -1;

    /* 9 bytes: 2 start + 2 meas + 2 CRC + 2 data + 1 CRC */
    if (sensirion_crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on start command\n");
        return -1;
    }
    if (sensirion_crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "CRC mismatch on measurement data\n");
        return -1;
    }

    int16_t raw = (int16_t)((buf[6] << 8) | buf[7]);
    *out = (float)raw / 60.0f;
    s->valid = 1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_flow_rate(FILE *fp, float avg)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, %.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, avg);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    gpioWrite(ALARM_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ALARM_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d) failed\n", ALARM_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(ALARM_GPIO, 0);

    g_i2c_fd = -1;
    g_log_fp = fopen(FLOW_LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", FLOW_LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    sensor_t sensors[NUM_SENSORS];
    for (int i = 0; i < NUM_SENSORS; i++)
        sensors[i].fd = -1;

    for (int i = 0; i < NUM_SENSORS; i++) {
        if (sensor_init(&sensors[i]) < 0) {
            fprintf(stderr, "Sensor %d init failed\n", i + 1);
            cleanup();
            return EXIT_FAILURE;
        }
    }

    /* Start both sensors */
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (sensor_start(&sensors[i]) < 0) {
            fprintf(stderr, "Sensor %d start failed\n", i + 1);
            cleanup();
            return EXIT_FAILURE;
        }
    }

    /* First measurement is available after ~100 ms */
    usleep(100000);

    int readings[MAX_SENSORS][MAX_READINGS];
    int readings_count = 0;
    int alarm_active = 0;

    while (g_running) {
        float sum = 0.0f;
        int valid_count = 0;

        for (int s = 0; s < NUM_SENSORS; s++) {
            if (!sensors[s].valid) {
                if (readings_count < MAX_READINGS)
                    readings[s][readings_count++] = -1.0f;
                continue;
            }

            float flow;
            if (sensor_read(&sensors[s], &flow) < 0) {
                fprintf(stderr, "Sensor %d read failed\n", s + 1);
                sensors[s].valid = 0;
                if (readings_count < MAX_READINGS)
                    readings[s][readings_count++] = -1.0f;
                continue;
            }

            sum += flow;
            valid_count++;
            readings[s][readings_count - 1] = flow;
        }

        if (readings_count > 0) {
            float avg = (valid_count > 0) ? (sum / valid_count) : 0.0f;
            log_flow_rate(g_log_fp, avg);

            if (valid_count == 0) {
                alarm_active = 0;
            } else if (avg < FLOW_THRESHOLD && !alarm_active) {
                gpioWrite(ALARM_GPIO, 1);
                alarm_active = 1;
                printf("ALARM: avg flow %.2f ml/min < %.2f ml/min\n",
                       avg, FLOW_THRESHOLD);
            } else if (avg >= FLOW_THRESHOLD && alarm_active) {
                gpioWrite(ALARM_GPIO, 0);
                alarm_active = 0;
                printf("Flow normal (%.2f ml/min >= %.2f ml/min)\n",
                       avg, FLOW_THRESHOLD);
            }
        }

        /* Sleep SAMPLE_PERIOD_S seconds, but wake early on signal */
        for (int s = 0; s < SAMPLE_PERIOD_S && g_running; s++)
            sleep(1);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

