/*
 * fan_health.c — Raspberry Pi 5 (Bookworm OS) + Omron D7S vibration sensor
 *
 * Wiring:
 *   D7S SDA  -> GPIO2 (BCM 2, /dev/i2c-1 SDA)
 *   D7S SCL  -> GPIO3 (BCM 3, /dev/i2c-1 SCL)
 *   D7S VDD  -> 3.3 V
 *   D7S GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o fan_health fan_health.c
 *
 * Run:
 *   ./fan_health
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define D7S_ADDR       0x68
#define D7S_MODE_CTRL  0x00
#define D7S_ACCEL_X_L  0x2A
#define D7S_ACCEL_X_H  0x2B
#define D7S_ACCEL_Y_L  0x2C
#define D7S_ACCEL_Y_H  0x2D
#define D7S_ACCEL_Z_L  0x2E
#define D7S_ACCEL_Z_H  0x2F

#define CSV_FILE       "fan_health.csv"
#define POLL_MS        500
#define MAX_ACTIVE_MS  1000

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write_reg8(0x%02X, 0x%02X) failed: %s (wrote %zd bytes)\n",
                reg, val, strerror(errno), n);
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "i2c_read_reg8: write(0x%02X) failed: %s (wrote %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    n = read(fd, out, 1);
    if (n != 1) {
        fprintf(stderr, "i2c_read_reg8: read(0x%02X) failed: %s (read %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t lo, hi;
    if (i2c_read_reg8(fd, reg, &lo) != 0)
        return -1;
    if (i2c_read_reg8(fd, reg + 1, &hi) != 0)
        return -1;
    *out = (uint16_t)((hi << 8) | lo);
    return 0;
}

static int d7s_set_mode(int fd, uint8_t mode)
{
    return i2c_write_reg8(fd, D7S_MODE_CTRL, mode);
}

static int d7s_wait_active(int fd, int timeout_ms)
{
    struct timespec ts = { timeout_ms / 1000, (timeout_ms % 1000) * 1000000L };
    for (int i = 0; i < timeout_ms; i += 100) {
        uint8_t dummy;
        if (i2c_read_reg8(fd, D7S_MODE_CTRL, &dummy) != 0)
            return -1;
        if (i2c_read_reg8(fd, D7S_ACCEL_X_L, &dummy) != 0)
            return -1;
        nanosleep(&ts, NULL);
    }
    return 0;
}

static int d7s_read_xyz(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    if (i2c_read_reg16(fd, D7S_ACCEL_X_L, (uint16_t *)x) != 0)
        return -1;
    if (i2c_read_reg16(fd, D7S_ACCEL_Y_L, (uint16_t *)y) != 0)
        return -1;
    if (i2c_read_reg16(fd, D7S_ACCEL_Z_L, (uint16_t *)z) != 0)
        return -1;
    return 0;
}

static int csv_open(const char *path, int *fd_out)
{
    int fd = open(path, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", path, strerror(errno));
        return -1;
    }
    if (lseek(fd, 0, SEEK_END) == 0) {
        if (write(fd, "timestamp,x,y,z\n", 12) != 12) {
            fprintf(stderr, "write header failed: %s\n", strerror(errno));
            close(fd);
            return -1;
        }
    }
    *fd_out = fd;
    return 0;
}

static int csv_write(int fd, const char *line)
{
    ssize_t n = write(fd, line, strlen(line));
    if (n < 0) {
        fprintf(stderr, "write to CSV failed: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)n != strlen(line)) {
        fprintf(stderr, "CSV write short: wrote %zd of %zd bytes\n", n, strlen(line));
        return -1;
    }
    return 0;
}

int main(void)
{
    int fd = -1;
    int csv_fd = -1;
    int rc = EXIT_FAILURE;

    if (install_signal_handlers() != 0)
        goto cleanup;

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        goto cleanup;
    }

    if (ioctl(fd, I2C_SLAVE, D7S_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                D7S_ADDR, strerror(errno));
        goto cleanup;
    }

    if (d7s_set_mode(fd, 0x00) != 0) {
        fprintf(stderr, "Failed to set D7S to standby mode\n");
        goto cleanup;
    }

    if (d7s_wait_active(fd, MAX_ACTIVE_MS) != 0) {
        fprintf(stderr, "D7S did not become active within %d ms\n", MAX_ACTIVE_MS);
        goto cleanup;
    }

    if (csv_open(CSV_FILE, &csv_fd) != 0)
        goto cleanup;

    int16_t x, y, z;
    while (g_running) {
        if (d7s_read_xyz(fd, &x, &y, &z) != 0) {
            fprintf(stderr, "Failed to read D7S data; retrying next cycle\n");
            goto sleep_and_retry;
        }
        char line[64];
        snprintf(line, sizeof(line), "1474836480,x,y,z\n", x, y, z);
        if (csv_write(csv_fd, line) != 0)
            goto sleep_and_retry;
        goto sleep_and_retry;

    sleep_and_retry:
        struct timespec ts = { 0, POLL_MS * 1000000L };
        nanosleep(&ts, NULL);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (csv_fd >= 0)
        close(csv_fd);
    if (fd >= 0)
        close(fd);
    return rc;
}

