/*
 * Raspberry Pi 4 Model B — Dual KY-032 IR Obstacle Avoidance Sensor
 *   Sensor 1 OUT -> GPIO23 (BCM)
 *   Sensor 2 OUT -> GPIO24 (BCM)
 *   LED (anode) -> GPIO25 (BCM) via 220-330 ohm resistor to GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o obstacle_avoidance obstacle_avoidance.c
 * Run:    sudo ./obstacle_avoidance
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <pigpio.h>

#define SENSOR_1_PIN 23
#define SENSOR_2_PIN 24
#define LED_PIN     25

#define POLL_DELAY_US  100000   /* 100 ms */
#define LED_ON_US      500000   /* 500 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

int main(void)
{
    int rc;

    rc = install_signal_handlers();
    if (rc != 0)
        return EXIT_FAILURE;

    rc = gpioInitialise();
    if (rc < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n", rc);
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SENSOR_1_PIN);
        goto cleanup;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SENSOR_2_PIN);
        goto cleanup;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", LED_PIN);
        goto cleanup;
    }

    /* Start with LED off */
    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise LED state on GPIO%d.\n", LED_PIN);
        goto cleanup;
    }

    printf("Obstacle avoidance system started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int s1 = gpioRead(SENSOR_1_PIN);
        int s2 = gpioRead(SENSOR_2_PIN);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "Warning: gpioRead failed (s1=%d, s2=%d).\n", s1, s2);
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        /* KY-032 OUT is active-LOW: obstacle detected when reading is 0 */
        bool obstacle = (s1 == 0 || s2 == 0);

        if (obstacle) {
            if (gpioWrite(LED_PIN, 1) != 0) {
                fprintf(stderr, "Warning: failed to turn LED on.\n");
            }
            gpioDelay(LED_ON_US);
            if (gpioWrite(LED_PIN, 0) != 0) {
                fprintf(stderr, "Warning: failed to turn LED off.\n");
            }
        } else {
            gpioDelay(POLL_DELAY_US);
        }
    }

    /* Ensure LED is off on exit */
    gpioWrite(LED_PIN, 0);

cleanup:
    gpioTerminate();
    return (g_running == 0) ? EXIT_SUCCESS : EXIT_FAILURE;
}

