code:
/*
 * Conveyor belt stall detection using two E18-D80NK IR obstacle sensors.
 *
 * Wiring (Raspberry Pi 4 Model B, BCM numbering):
 *   Sensor 1 OUT -> GPIO17 (physical pin 11)
 *   Sensor 2 OUT -> GPIO18 (physical pin 12)
 *   VCC -> 3.3 V, GND -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o stall_detect stall_detect.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <stdbool.h>

#define SENSOR1_PIN 17
#define SENSOR2_PIN 18
#define STALL_LOG_FILE "stall_log.txt"
#define STALL_DURATION_SEC 2
#define POLL_INTERVAL_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_stall_event(void)
{
    FILE *fp = fopen(STALL_LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening %s: %s\n",
                STALL_LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        fclose(fp);
        return;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        fclose(fp);
        return;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return;
    }

    if (fprintf(fp, "%s - Conveyor belt stall confirmed\n", timestamp) < 0) {
        fprintf(stderr, "Error writing to %s: %s\n",
                STALL_LOG_FILE, strerror(errno));
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing %s: %s\n",
                STALL_LOG_FILE, strerror(errno));
    }
}

/* ------------------------------------------------------------------ */
/* Sensor reading                                                      */
/* ------------------------------------------------------------------ */
/*
 * E18-D80NK modules are active-high: the OUT pin reads HIGH when
 * an object is detected and LOW when the line is clear.
 */
static int read_sensor(int pin)
{
    int val = gpioRead(pin);
    if (val < 0) {
        fprintf(stderr, "gpioRead(%d) failed: %s\n",
                pin, strerror(errno));
        return -1;
    }
    return val;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialize the driver library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise() failed\n");
        return EXIT_FAILURE;
    }

    /* Configure sensor pins as inputs */
    if (gpioSetMode(SENSOR1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_INPUT) failed\n", SENSOR1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_INPUT) failed\n", SENSOR2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Enable internal pull-ups so the pins read HIGH when no object is
     * detected (E18-D80NK modules drive the line LOW when an object is
     * detected, so a pull-up keeps the pin defined when the sensor is
     * disconnected or the module is absent). */
    if (gpioSetPullUpDown(SENSOR1_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown(%d, PI_PUD_UP) failed\n",
                SENSOR1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR2_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown(%d, PI_PUD_UP) failed\n",
                SENSOR2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Conveyor belt stall detection started.\n");
    printf("  Sensor 1: GPIO%d\n  Sensor 2: GPIO%d\n", SENSOR1_PIN, SENSOR2_PIN);
    printf("  Log file: %s\n", STALL_LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    bool stall_active = false;
    time_t stall_start = 0;
    int consecutive_errors = 0;

    while (g_running) {
        int s1 = read_sensor(SENSOR1_PIN);
        int s2 = read_sensor(SENSOR2_PIN);

        if (s1 < 0 || s2 < 0) {
            consecutive_errors++;
            if (consecutive_errors >= 10) {
                fprintf(stderr, "Too many consecutive sensor read errors; aborting.\n");
                break;
            }
            usleep(POLL_INTERVAL_US);
            continue;
        }
        consecutive_errors = 0;

        /* Stall confirmed only when both sensors read LOW (no object) */
        if (s1 == 0 && s2 == 0) {
            if (!stall_active) {
                stall_active = true;
                stall_start = time(NULL);
                printf("Conveyor belt stall confirmed.\n");
            } else {
                time_t now = time(NULL);
                if (difftime(now, stall_start) >= STALL_DURATION_SEC) {
                    log_stall_event();
                    stall_active = false;
                }
            }
        } else {
            stall_active = false;
        }

        usleep(POLL_INTERVAL_US);
    }

    /* Clean shutdown */
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

