/*
 * TMAG5170-Q1 3D Hall-Effect I2C Sensor Logger
 * Board:  Raspberry Pi 4 Model B
 * Bus:    I2C bus 1 (GPIO2 = SDA, GPIO3 = SCL)
 * Sensor: Texas Instruments TMAG5170-Q1
 *
 * Reads X/Y/Z magnetic field values every 100 ms and logs them to
 * magnetic_log.csv with ISO-8601 timestamps.  Handles I2C errors and
 * terminates cleanly on SIGINT/SIGTERM.
 *
 * Build:  gcc -O2 -Wall -Wextra -o mag_log mag_log.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- TMAG5170-Q1 constants (per TI datasheet) ---- */
#define I2C_BUS        "/dev/i2c-1"
#define TMAG5170_ADDR  0x20

#define REG_DEVICE_ID  0x00
#define REG_HW_KEY     0x01
#define REG_MEAS_CFG   0x0A
#define REG_X_CH_RESULT 0x04
#define REG_Y_CH_RESULT 0x06
#define REG_Z_CH_RESULT 0x08

#define HW_KEY_VAL     0x17
#define MEAS_CFG_VAL   0x0C   /* 50 mT range, continuous conversion, all axes */

#define LOG_FILE       "magnetic_log.csv"
#define SAMPLE_PERIOD_US 100000  /* 100 ms */

/* ---- Globals for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to a register; returns 0 on success, -1 on error.   */
static int reg_write(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from a register; returns 0 on success, -1 on error.  */
static int reg_read(int fd, uint8_t reg, uint8_t *out)
{
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    n = read(fd, out, 1);
    if (n != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the TMAG5170-Q1: verify device ID, write HW key, configure. */
static int init_sensor(int fd)
{
    uint8_t id = 0;
    if (reg_read(fd, REG_DEVICE_ID, &id) != 0)
        return -1;
    if (id != 0x20) {
        fprintf(stderr, "TMAG5170-Q1 not detected (device ID 0x%02X, "
                        "expected 0x20). Check wiring and address.\n", id);
        return -1;
    }

    if (reg_write(fd, REG_HW_KEY, HW_KEY_VAL) != 0)
        return -1;

    if (reg_write(fd, REG_MEAS_CFG, MEAS_CFG_VAL) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one axis channel (X, Y, or Z) and convert raw LSBs to mT.     */
static int read_axis(int fd, uint8_t ch, float *out_mt)
{
    uint8_t raw = 0;
    if (reg_read(fd, REG_X_CH_RESULT + (ch << 1), &raw) != 0)
        return -1;
    int16_t signed_raw = (int16_t)raw;
    /* 16-bit signed value; LSB = 0.5 mT / 32768 */
    *out_mt = (float)signed_raw * 0.00048828125f;
    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        /* Issue a library cleanup command (0x80 0x00 0x00 0x00) */
        uint8_t cmd[4] = { 0x80, 0x00, 0x00, 0x00 };
        ssize_t n = write(g_i2c_fd, cmd, sizeof(cmd));
        if (n != (ssize_t)sizeof(cmd))
            fprintf(stderr, "Warning: failed to send cleanup command: %s\n",
                    strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, TMAG5170_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                TMAG5170_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* ---- Initialise sensor ---- */
    if (init_sensor(g_i2c_fd) != 0) {
        fprintf(stderr, "Sensor initialisation failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open log file (append) ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "Timestamp,X_mT,Y_mT,Z_mT\n");
        fflush(g_log_fp);
    }

    printf("TMAG5170-Q1 logging started. Press Ctrl-C to stop.\n");

    /* ---- Main sampling loop ---- */
    while (g_running) {
        float x = 0.0f, y = 0.0f, z = 0.0f;
        int ok = 1;

        if (read_axis(g_i2c_fd, 0x04, &x) != 0) ok = 0;
        if (read_axis(g_i2c_fd, 0x06, &y) != 0) ok = 0;
        if (read_axis(g_i2c_fd, 0x08, &z) != 0) ok = 0;

        if (ok) {
            time_t now = time(NULL);
            struct tm tm_buf;
            struct tm *t = localtime_r(&now, &tm_buf);
            char ts[32];
            strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
            fprintf(g_log_fp, "%s,%.4f,%.4f,%.4f\n", ts, x, y, z);
            fflush(g_log_fp);
            printf("%s  X: %.4f mT  Y: %.4f mT  Z: %.4f mT\n", ts, x, y, z);
        } else {
            fprintf(stderr, "Sensor read error — continuing.\n");
        }

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

