code:
/*
 * Raspberry Pi Zero W — SEN0193 Water Level Sensor Monitor
 *
 * Wiring:
 *   SEN0193 VCC  -> 3.3 V (pin 1)
 *   SEN0193 GND  -> GND   (pin 9)
 *   SEN0193 OUT  -> GPIO23 (pin 16, BCM 23)
 *   (internal pull-down enabled so line is LOW when dry)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o flood_monitor flood_monitor.c -lpigpio -lrt
 *   (pigpio must be installed; run as root or with appropriate permissions)
 *
 * Run:
 *   sudo ./flood_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define SENSOR_PIN      23          /* BCM GPIO23 */
#define POLL_INTERVAL_S 2           /* seconds between readings */
#define REINIT_DELAY_S  60          /* seconds between re-initialization attempts */
#define LOG_FILE        "flood_log.txt"

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_message(const char *message)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        return;
    }

    time_t t = time(NULL);
    if (t != (time_t)-1) {
        struct tm tm;
        if (localtime_r(&t, &tm) != NULL) {
            fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d %s\n",
                    tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                    tm.tm_hour, tm.tm_min, tm.tm_sec, message);
        } else {
            fprintf(fp, "[time-error] %s\n", message);
        }
    } else {
        fprintf(fp, "[time-error] %s\n", message);
    }

    if (fclose(fp) != 0) {
        perror("fclose(" LOG_FILE ")");
    }
}

/* ------------------------------------------------------------------ */
/* Sensor read                                                         */
/* ------------------------------------------------------------------ */
/*
 * Returns 1 if water is detected (sensor output HIGH), 0 otherwise,
 * or -1 on read error.
 */
static int read_sensor(int pin)
{
    int level = gpioRead(pin);
    if (level < 0) {
        log_message("ERROR: gpioRead failed on pin");
        return -1;
    }
    return level;
}

/* ------------------------------------------------------------------ */
/* Initialization                                                       */
/* ------------------------------------------------------------------ */
static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        log_message("ERROR: pigpio initialisation failed");
        return -1;
    }

    if (gpioSetMode(SENSOR_PIN, PI_INPUT) != 0) {
        log_message("ERROR: gpioSetMode failed");
        gpioTerminate();
        return -1;
    }

    /*
     * Enable internal pull-down so the line is LOW when the sensor
     * is dry (active-high sensor output).
     */
    if (gpioSetPullUpDown(SENSOR_PIN, PI_PUD_DOWN) != 0) {
        log_message("ERROR: gpioSetPullUpDown failed");
        gpioTerminate();
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    log_message("INFO: Flood monitor started (GPIO23, polling every 2 s)");

    while (g_running) {
        int sensor_value = read_sensor(SENSOR_PIN);

        if (sensor_value == 1) {
            log_message("ALERT: Water detected!");
            printf("ALERT: Water detected!\n");
            fflush(stdout);
        } else if (sensor_value < 0) {
            /* Read error — attempt to re-initialize after REINIT_DELAY_S */
            log_message("ERROR: Sensor read failed — re-initializing GPIO");
            gpioTerminate();
            gpioDelay(REINIT_DELAY_S * 1000000);
            if (initialize_gpio() != 0) {
                log_message("ERROR: Re-initialization failed — exiting");
                break;
            }
        }

        /* Sleep in 100 ms slices so signals are caught promptly */
        for (int i = 0; i < POLL_INTERVAL_S * 10 && g_running; i++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    log_message("INFO: Flood monitor stopping");
    cleanup();
    return EXIT_SUCCESS;
}

