/*
 * RPM logger for Raspberry Pi 4 Model B (Bookworm or later).
 *
 * Sensor : Melexis MLX90217 Hall-effect sensor
 * Wiring : VCC  -> 3.3 V (pin 1)
 *          GND  -> GND  (pin 9)
 *          OUT  -> BCM GPIO4 (pin 7)
 *
 * The MLX90217 output is open-collector style; the Pi's internal pull-up
 * keeps the line high when the sensor is idle.  A rising edge on the
 * BCM GPIO4 line indicates a new revolution.
 *
 * Build:  gcc -O2 -Wall -Wextra -o rpm_logger rpm_logger.c -lpigpio -lrt
 * Run   :  sudo ./rpm_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

#define GPIO_PIN        4
#define LOG_FILE        "rpm_log.txt"
#define SAMPLE_WINDOW_S 1
#define TIMESTAMP_LEN   32

static volatile sig_atomic_t g_running = 1;
static volatile uint64_t    g_pulse_count = 0;
static FILE                *g_log_fp     = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */

static void log_rpm(FILE *fp, const char *timestamp, uint64_t pulse_count)
{
    if (fp == NULL) {
        fprintf(stderr, "Error: log file pointer is NULL.\n");
        return;
    }
    if (fprintf(fp, "%s %llu\n", timestamp, (unsigned long long)pulse_count) < 0) {
        perror("fprintf to log file");
    }
    if (fflush(fp) != 0) {
        perror("fflush log file");
    }
}

static void log_rpm_to_console(uint64_t pulse_count)
{
    char ts[TIMESTAMP_LEN];
    time_t now = time(NULL);
    struct tm tm_info;

    if (localtime_r(&now, &tm_info) != NULL) {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
    } else {
        snprintf(ts, sizeof(ts), "UNKNOWN");
    }
    printf("%s %llu\n", ts, (unsigned long long)pulse_count);
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* GPIO alert callback (runs in pigpio thread)                         */
/* ------------------------------------------------------------------ */

static void pulse_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)tick;
    (void)userdata;

    if (level == 1) {
        g_pulse_count++;
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */

static void cleanup(void)
{
    /* Disable the alert callback so no more callbacks fire during
     * the cleanup sequence. */
    gpioSetAlertFuncEx(GPIO_PIN, NULL, NULL);

    /* Disable the timer so no more timer callbacks fire. */
    gpioSetTimerFuncEx(0, 0, NULL, NULL);

    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }

    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    int rc;

    /* --- Initialise pigpio ------------------------------------------ */
    rc = gpioInitialise();
    if (rc < 0) {
        fprintf(stderr, "pigpio initialisation failed (code %d).\n", rc);
        return EXIT_FAILURE;
    }

    /* --- Open log file ---------------------------------------------- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        perror("fopen log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers ----------------------------------- */
    if (install_signal_handlers() != 0) {
        fclose(g_log_fp);
        g_log_fp = NULL;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO4 as input with internal pull-up ----------- */
    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for GPIO%d.\n", GPIO_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown failed for GPIO%d.\n", GPIO_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Register alert callback for rising edges ------------------ */
    rc = gpioSetAlertFuncEx(GPIO_PIN, pulse_callback, NULL);
    if (rc != 0) {
        fprintf(stderr, "gpioSetAlertFuncEx failed for GPIO%d (code %d).\n",
                GPIO_PIN, rc);
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Start a 1-second timer to trigger the callback every second */
    rc = gpioSetTimerFuncEx(0, SAMPLE_WINDOW_S, NULL, NULL);
    if (rc != 0) {
        fprintf(stderr, "gpioSetTimerFuncEx failed (code %d).\n", rc);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("RPM logger started.  GPIO%d, logging to %s every %d s.\n",
           GPIO_PIN, LOG_FILE, SAMPLE_WINDOW_S);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main loop -------------------------------------------------- */
    while (g_running) {
        /* Sleep for 100 ms so we can respond promptly to signals. */
        gpioDelay(100 * 1000);  /* microseconds */

        /* Atomically read and reset the pulse count. */
        uint64_t pulses = 0;
        __sync_synchronize();
        pulses = __sync_fetch_and_and(&g_pulse_count, 0);

        /* Log to file and console. */
        log_rpm(g_log_fp, NULL, pulses);
        log_rpm_to_console(pulses);

        /* Reset the counter so the next sample window starts fresh. */
        __sync_synchronize();
        __sync_store_and_update_and_fetch(&g_pulse_count, 0);
    }

    /* --- Graceful shutdown ----------------------------------------- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

