#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_A_GPIO 17
#define SENSOR_B_GPIO 27
#define LOG_FILE_NAME "rotation_log.txt"
#define POLL_DELAY_US 100000

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;
static pthread_mutex_t state_mutex = PTHREAD_MUTEX_INITIALIZER;

typedef struct {
    int last_state;
    int current_state;
} QuadratureState;

static QuadratureState sensor_a_state = {0, 0};
static QuadratureState sensor_b_state = {0, 0};

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static void log_rotation_event(const char *event_type) {
    struct timespec ts;
    struct tm tm_info;
    char timestamp[32];

    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
        return;
    }

    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    if (fprintf(log_file, "%s.%03ld: %s\n", timestamp, ts.tv_nsec / 1000000, event_type) < 0) {
        fprintf(stderr, "fprintf to log file failed: %s\n", strerror(errno));
    } else {
        fflush(log_file);
    }
}

static void sensor_a_isr(int gpio, int level, uint32_t tick, void *user_data) {
    (void)gpio;
    (void)tick;
    (void)user_data;

    if (level == 1) {
        pthread_mutex_lock(&state_mutex);
        sensor_a_state.current_state = 1;
        pthread_mutex_unlock(&state_mutex);
    }
}

static void sensor_b_isr(int gpio, int level, uint32_t tick, void *user_data) {
    (void)gpio;
    (void)tick;
    (void)user_data;

    if (level == 1) {
        pthread_mutex_lock(&state_mutex);
        sensor_b_state.current_state = 1;
        pthread_mutex_unlock(&state_mutex);
    }
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(SENSOR_A_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_A_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(SENSOR_B_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_B_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPullUpDown(SENSOR_A_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", SENSOR_A_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPullUpDown(SENSOR_B_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", SENSOR_B_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioSetAlertFuncEx(SENSOR_A_GPIO, sensor_a_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function for GPIO %d\n", SENSOR_A_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioSetAlertFuncEx(SENSOR_B_GPIO, sensor_b_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function for GPIO %d\n", SENSOR_B_GPIO);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }

    gpioTerminate();
    pthread_mutex_destroy(&state_mutex);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (initialize_gpio() != 0) {
        return 1;
    }

    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE_NAME, strerror(errno));
        gpioTerminate();
        pthread_mutex_destroy(&state_mutex);
        return 1;
    }

    printf("Monitoring rotation on GPIO %d and GPIO %d. Press Ctrl+C to exit.\n", SENSOR_A_GPIO, SENSOR_B_GPIO);

    while (program_running) {
        usleep(POLL_DELAY_US);
    }

    printf("\nShutting down gracefully...\n");

    cleanup();

    return 0;
}

