static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static int setup_gpio(void)
{
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        syslog(LOG_ERR, "Failed to set touch sensor pin %d as input", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set LED pin %d as output", LED_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(LED_PIN, 0) != 0) {
        syslog(LOG_ERR, "Failed to initialise LED pin %d to LOW", LED_PIN);
        gpioTerminate();
        return -1;
    }

    syslog(LOG_INFO, "GPIO initialised: touch sensor on BCM %d, LED on BCM %d", TOUCH_SENSOR_PIN, LED_PIN);
    return 0;
}

static void cleanup_gpio(void)
{
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

