/*
 * TTP223B capacitive touch sensor → LED toggle on Raspberry Pi 3 Model B+
 * Sensor OUT  → GPIO17 (physical pin 11)
 * LED        → GPIO18 (physical pin 12)
 *
 * Build:  gcc -O2 -Wall -Wextra -o touch_led touch_led.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>

#define TOUCH_PIN  17
#define LED_PIN    18
#define DEBOUNCE_MS 50

static volatile sig_atomic_t g_running = 1;

static void sighandler(int signo)
{
    (void)signo;
    g_running = 0;
}

static void sleep_ms(unsigned int ms)
{
    struct timespec ts = {
        .tv_sec  = ms / 1000,
        .tv_nsec = (long)(ms % 1000) * 1000000L
    };
    while (nanosleep(&ts, &ts) == -1 && errno == EINTR) {
        /* retry after interruption */
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *touch_line = NULL;
    struct gpiod_line *led_line = NULL;
    int ret = EXIT_FAILURE;

    /* --- signal handling for graceful shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- open the default gpiochip (gpiochip0 on RPi 3B+) --- */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "gpiod_chip_open_by_name: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    touch_line = gpiod_chip_get_line(chip, TOUCH_PIN);
    if (touch_line == NULL) {
        fprintf(stderr, "gpiod_chip_get_line(%d): %s\n", TOUCH_PIN, strerror(errno));
        goto cleanup;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (led_line == NULL) {
        fprintf(stderr, "gpiod_chip_get_line(%d): %s\n", LED_PIN, strerror(errno));
        goto cleanup;
    }

    /* --- request touch line as input with rising-edge event detection --- */
    if (gpiod_line_request_rising_edge_events(touch_line, "touch_led") < 0) {
        fprintf(stderr, "gpiod_line_request_rising_edge_events(%d): %s\n",
                TOUCH_PIN, strerror(errno));
        goto cleanup;
    }

    /* --- request LED line as output, initial value LOW --- */
    if (gpiod_line_request_output(led_line, "touch_led", 0) < 0) {
        fprintf(stderr, "gpiod_line_request_output(%d): %s\n", LED_PIN, strerror(errno));
        goto cleanup;
    }

    printf("Touch sensor ready. Touch GPIO%d to toggle LED on GPIO%d.\n",
           TOUCH_PIN, LED_PIN);
    printf("Press Ctrl+C to exit.\n");

    int led_state = 0;
    int last_touch = 0;

    while (g_running) {
        /* --- wait for a rising-edge event on the touch line --- */
        int ev = gpiod_line_event_wait(touch_line, NULL); /* block indefinitely */
        if (ev < 0) {
            if (errno == EINTR) {
                continue; /* interrupted by signal — check g_running */
            }
            fprintf(stderr, "gpiod_line_event_wait: %s\n", strerror(errno));
            break;
        }
        if (ev == 0) {
            continue; /* timeout (should not happen with NULL timeout) */
        }

        /* --- read the event to clear it --- */
        struct gpiod_line_event event;
        if (gpiod_line_event_read(touch_line, &event) < 0) {
            fprintf(stderr, "gpiod_line_event_read: %s\n", strerror(errno));
            continue;
        }

        if (event.event_type != GPIOD_LINE_EVENT_RISING_EDGE) {
            continue;
        }

        /* --- software debounce: ignore events within DEBOUNCE_MS --- */
        if (last_touch != 0) {
            unsigned int elapsed_ms = (unsigned int)(time(NULL) - last_touch_time);
            if (elapsed_ms < DEBOUNCE_MS) {
                continue;
            }
        }

        last_touch = 1;
        last_touch_time = time(NULL);

        /* --- toggle LED --- */
        led_state = !led_state;
        if (gpiod_line_set_value(led_line, led_state) < 0) {
            fprintf(stderr, "gpiod_line_set_value(%d): %s\n", LED_PIN, strerror(errno));
            break;
        }
        printf("Touch detected → LED %s\n", led_state ? "ON" : "OFF");
    }

    /* --- ensure LED is off on exit --- */
    if (led_line != NULL) {
        (void)gpiod_line_set_value(led_line, 0);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (touch_line != NULL) {
        gpiod_line_release(touch_line);
    }
    if (led_line != NULL) {
        gpiod_line_release(led_line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    if (ret == EXIT_SUCCESS) {
        printf("\nExiting cleanly.\n");
    }
    return ret;
}

