/*
 * TTP223B dual-capacitive touch sensor monitor with LED feedback.
 *
 * Board:  Raspberry Pi Zero W
 * Library: pigpio (http://abyz.me.uk/rpi/pigpio/)
 *
 * Wiring:
 *   TTP223B #1  -> GPIO4  (BCM)
 *   TTP223B #2  -> GPIO17 (BCM)
 *   LED #1     -> GPIO27 (BCM) via ~330 Ω resistor to GND
 *   LED #2     -> GPIO22 (BCM) via ~330 Ω resistor to GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o touch_led touch_led.c -lpigpio -lrt
 * Run:    sudo ./touch_led
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SENSOR_1_PIN  4
#define SENSOR_2_PIN  17
#define LED_1_PIN     27
#define LED_2_PIN     22

#define BUFFER_SIZE   100
#define POLL_DELAY_US 50000   /* 50 ms polling interval */

/* ------------------------------------------------------------------ */
/* Circular buffer                                                      */
/* ------------------------------------------------------------------ */

typedef struct {
    int sensor_pin;
    time_t timestamp;
    int state;          /* 0 = released, 1 = touched */
} LogEntry;

typedef struct {
    LogEntry entries[BUFFER_SIZE];
    int head;
    int count;
    int overflow;
} CircularBuffer;

static CircularBuffer g_log;

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

static void cb_init(CircularBuffer *cb)
{
    cb->head  = 0;
    cb->count = 0;
    cb->overflow = 0;
}

static void cb_add(CircularBuffer *cb, int sensor_pin, time_t ts, int state)
{
    cb->entries[cb->head].sensor_pin = sensor_pin;
    cb->entries[cb->head].timestamp  = ts;
    cb->entries[cb->head].state      = state;

    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE)
        cb->count++;
    else
        cb->overflow++;
}

static void cb_print(CircularBuffer *cb)
{
    printf("\n--- Log Buffer Contents (%d entries, %d overflow) ---\n",
           cb->count, cb->overflow);
    for (int i = 0; i < cb->count; i++) {
        int idx = (cb->head - cb->count + i + BUFFER_SIZE) % BUFFER_SIZE;
        printf("  [%2d] Sensor %d  %ld  State %d\n",
               i, cb->entries[idx].sensor_pin,
               (long)cb->entries[idx].timestamp,
               cb->entries[idx].state);
    }
    printf("--- End of Log Buffer ---\n\n");
}

/* ------------------------------------------------------------------ */
/* Signal handling                                                      */
/* ------------------------------------------------------------------ */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */

static void cleanup(void)
{
    /* Turn off LEDs before terminating pigpio */
    gpioWrite(LED_1_PIN, 0);
    gpioWrite(LED_2_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- GPIO configuration ---- */
    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SENSOR_1_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SENSOR_2_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(LED_1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", LED_1_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(LED_2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", LED_2_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Start from a known state */
    if (gpioWrite(LED_1_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise LED1 state.\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioWrite(LED_2_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise LED2 state.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    cb_init(&g_log);

    printf("Monitoring TTP223B sensors on GPIO%d and GPIO%d.\n"
           "LED1 on GPIO%d, LED2 on GPIO%d. Press Ctrl+C to exit.\n",
           SENSOR_1_PIN, SENSOR_2_PIN, LED_1_PIN, LED_2_PIN);

    /* ---- Main polling loop ---- */
    bool prev1 = false;
    bool prev2 = false;

    while (g_running) {
        int v1 = gpioRead(SENSOR_1_PIN);
        int v2 = gpioRead(SENSOR_2_PIN);

        if (v1 < 0) {
            fprintf(stderr, "Warning: gpioRead failed on sensor 1 (GPIO%d).\n",
                    SENSOR_1_PIN);
            gpioDelay(POLL_DELAY_US);
            continue;
        }
        if (v2 < 0) {
            fprintf(stderr, "Warning: gpioRead failed on sensor 2 (GPIO%d).\n",
                    SENSOR_2_PIN);
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        /* TTP223B is active-high: 1 = touched, 0 = released */
        bool cur1 = (v1 == 1);
        bool cur2 = (v2 == 1);

        /* Log transitions */
        if (cur1 != prev1) {
            time_t now = time(NULL);
            cb_add(&g_log, SENSOR_1_PIN, now, cur1 ? 1 : 0);
        }
        if (cur2 != prev2) {
            time_t now = time(NULL);
            cb_add(&g_log, SENSOR_2_PIN, now, cur2 ? 1 : 0);
        }

        /* Drive LEDs */
        if (gpioWrite(LED_1_PIN, cur1) != 0) {
            fprintf(stderr, "Warning: gpioWrite failed on LED1 (GPIO%d).\n",
                    LED_1_PIN);
        }
        if (gpioWrite(LED_2_PIN, cur2) != 0) {
            fprintf(stderr, "Warning: gpioWrite failed on LED2 (GPIO%d).\n",
                    LED_2_PIN);

        }

        prev1 = cur1;
        prev2 = cur2;

        gpioDelay(POLL_DELAY_US);
    }

