/*
 * Raindrop Sensor Monitor — Raspberry Pi 4 Model B
 *
 * Wiring:
 *   Raindrop Sensor Module digital output -> GPIO17 (BCM)
 *   Raindrop Sensor Module VCC              -> 3.3 V (Pin 1)
 *   Raindrop Sensor Module GND              -> GND  (Pin 6)
 *   Internal pull-up enabled on GPIO17
 *
 * Behaviour:
 *   Polls GPIO17 every 500 ms.  A LOW level (0) indicates rain
 *   (active-low module), a HIGH level (1) indicates no rain.
 *   Only logs to /var/log/rain_events.log on state change.
 *   Graceful shutdown on SIGINT / SIGTERM.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define GPIO_PIN        17
#define LOG_FILE        "/var/log/rain_events.log"
#define POLL_INTERVAL_US 500000  /* 500 ms */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_event(const char *message)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }

    if (g_log_fp == NULL) {
        g_log_fp = fopen(LOG_FILE, "a");
        if (g_log_fp == NULL) {
            fprintf(stderr, "fopen(%s) failed: %s\n",
                    LOG_FILE, strerror(errno));
            return -1;
        }
    }

    if (fprintf(g_log_fp, "%s %s\n", timestamp, message) < 0) {
        fprintf(stderr, "fprintf() failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "fflush() failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* GPIO setup                                                          */
/* ------------------------------------------------------------------ */
static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_INPUT) failed\n", GPIO_PIN);
        return -1;
    }

    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown(%d, PI_PUD_UP) failed\n",
                GPIO_PIN);
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }

    /* gpioTerminate() is safe to call even if pigpio was never initialised */
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    int last_state = -1;  /* force initial log */

    while (g_running) {
        int level = gpioRead(GPIO_PIN);
        if (level < 0) {
            fprintf(stderr, "gpioRead(%d) failed\n", GPIO_PIN);
            break;
        }

        if (level != last_state) {
            const char *msg = (level == 0) ? "Rain Detected" : "No Rain";
            if (log_event(msg) != 0) {
                break;
            }
            last_state = level;
        }

        usleep(POLL_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

