#include <unistd.h>
#include <pigpio.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 18
#define DEBOUNCE_US 5000
#define SAMPLE_INTERVAL_US 100000
#define LOG_FILE "shaft_log.txt"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", gpio_pin, pigpio_error(value));
        return -1;
    }
    return value;
}

static void log_data(int sensor1_state, int sensor2_state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        fclose(fp);
        return;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return;
    }

    if (fprintf(fp, "%s,%d,%d\n", timestamp, sensor1_state, sensor2_state) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
    }
}

static double calculate_rpm(int sensor1_state, int sensor2_state) {
    static int last_sensor1_state = -1;
    static int last_sensor2_state = -1;
    static int first_sample = 1;

    if (first_sample) {
        last_sensor1_state = sensor1_state;
        last_sensor2_state = sensor2_state;
        first_sample = 0;
        return 0.0;
    }

    if (sensor1_state != last_sensor1_state) {
        gpioDelay(DEBOUNCE_US);
        int confirmed_state = read_sensor(SENSOR_1_GPIO);
        if (confirmed_state < 0) return -1.0;
        if (confirmed_state != sensor1_state) {
