/*
 * Bridge Integrity Monitor — Raspberry Pi Zero W
 *
 * Sensors : 2 × Omron D7E-3 digital tilt sensors
 *   Sensor 1 on GPIO17 (BCM), internal pull-down enabled
 *   Sensor 2 on GPIO18 (BCM), internal pull-down enabled
 * Alarm  : Active-high buzzer/LED on GPIO27 (BCM)
 *
 * Build   : gcc -O2 -Wall -Wextra -o bridge_monitor bridge_monitor.c
 * Run     : sudo ./bridge_monitor   (root needed for hardware PWM/LED)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>

#include <pigpio.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define SENSOR_1_PIN 17
#define SENSOR_2_PIN 18
#define ALARM_PIN    27

/* ---- Timing / state ---- */
#define POLL_INTERVAL_US  100000   /* 100 ms */
#define ALARM_ACTIVE_S    2        /* seconds */
#define LOG_FILE          "bridge_integrity.log"

/* ---- Globals for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag only; do NOT call non-async-signal-safe  */
/* functions from here.                                                */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write an ISO-8601 timestamped message to the log file.              */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int log_event(const char *event_type)
{
    time_t now;
    struct tm tm_info;
    char timestamp[32];

    if (g_log_fp == NULL) {
        fprintf(stderr, "Error: log file not open.\n");
        return -1;
    }

    time(&now);
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "Error: localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error: strftime failed.\n");
        return -1;
    }

    if (fprintf(g_log_fp, "%s - %s\n", timestamp, event_type) < 0) {
        fprintf(stderr, "Error: fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "Warning: fflush failed: %s\n", strerror(errno));
        /* non-fatal */
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Activate the alarm buzzer for ALARM_ACTIVE_S seconds.              */
/* ------------------------------------------------------------------ */
static void activate_alarm(void)
{
    if (gpioWrite(ALARM_PIN, 1) != 0) {
        fprintf(stderr, "Error: failed to set alarm HIGH.\n");
        return;
    }
    printf("Alarm activated.\n");

    /* Sleep in 100 ms slices so we can respond to signals promptly. */
    for (int i = 0; i < ALARM_ACTIVE_S * 10 && g_running; i++) {
        gpioDelay(POLL_INTERVAL_US);
    }

    if (gpioWrite(ALARM_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to set alarm LOW.\n");
    }
    printf("Alarm deactivated.\n");
}

/* ------------------------------------------------------------------ */
/* Cleanup — safe to call multiple times.                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Ensure alarm is off before releasing resources. */
    if (gpioInitialise() >= 0) {
        gpioWrite(ALARM_PIN, 0);
    }

    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }

    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int ret;

    /* ---- Initialize pigpio ---- */
    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (code %d).\n", ret);
        return EXIT_FAILURE;
    }

    /* ---- Configure sensor pins as inputs with pull-down ---- */
    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SENSOR_1_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SENSOR_2_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: failed to set pull-down on GPIO%d.\n", SENSOR_1_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: failed to set pull-down on GPIO%d.\n", SENSOR_2_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Configure alarm pin as output, initially LOW ---- */
    if (gpioSetMode(ALARM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", ALARM_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioWrite(ALARM_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize alarm LOW.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGTERM) failed: %s\n", strerror(errno));
    }

    printf("Bridge integrity monitor started.\n");
    printf("  Sensor 1: GPIO%d\n  Sensor 2: GPIO%d\n  Alarm:   GPIO%d\n",
           SENSOR_1_PIN, SENSOR_2_PIN, ALARM_PIN);
    printf("  Logging to '%s'. Press Ctrl+C to exit.\n", LOG_FILE);

    /* ---- Main polling loop ---- */
    while (g_running) {
        int s1 = gpioRead(SENSOR_1_PIN);
        int s2 = gpioRead(SENSOR_2_PIN);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "Error: gpioRead failed (s1=%d, s2=%d).\n", s1, s2);
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        /* Log tilt-start events. */
        if (s1 == 1) {
            log_event("tilt-start");
        }
        if (s2 == 1) {
            log_event("tilt-start");
        }

        /* Log threshold-exceeded events. */
        if (s1 == 1 && s2 == 0) {
            log_event("threshold-exceeded");
        }
        if (s1 == 0 && s2 == 1) {
            log_event("threshold-exceeded");
        }

        /* Log tilt-end events. */
        if (s1 == 0) {
            log_event("tilt-end");
        }
        if (s2 == 0) {
            log_event("tilt-end");
        }

        /* Activate alarm if either sensor stays HIGH for ALARM_ACTIVE_S. */
        if (s1 == 1 || s2 == 1) {
            if (s1 == 1 && s2 == 1) {
                log_event("alarm-active");
            }
            activate_alarm();
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

