/*
 * seismic.c — Omron D7S-A0011 seismic sensor monitor for Raspberry Pi 3 B+
 *
 * Wiring:
 *   D7S SDA  -> GPIO2  (BCM)
 *   D7S SCL  -> GPIO3  (BCM)
 *   D7S VDD  -> 3.3 V
 *   D7S GND  -> GND
 *   Alert LED -> GPIO17 (BCM) via 330 Ω resistor to GND
 *
 * Build:
 *   gcc -O2 -Wall -o seismic seismic.c -lthe -lm -lrt
 *
 * Run:
 *   ./seismic
 */

