#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <the/therm.h>

#define I2C_BUS        "/dev/i2c-1"
#define D7S_ADDR       0x48
#define ALERT_GPIO     17
#define VIBRATION_THRESHOLD 500
#define POLL_INTERVAL_MS  100
#define LOG_FILE        "seismic_events.log"
#define MAX_RETRIES     3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_byte(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor initialization                                               */
/* ------------------------------------------------------------------ */
static int init_sensor(void)
{
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, D7S_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                D7S_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return -1;
    }

    /* Probe: try a dummy read to confirm the sensor is present */
    uint8_t dummy;
    if (i2c_read_block(g_i2c_fd, 0x00, &dummy, 1) < 0) {
        fprintf(stderr, "Sensor not responding at 0x%02X — check wiring.\n",
                D7S_ADDR);
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return -1;
    }

    /* Clear the power-down bit in CTRL1 (bit 0) */
    if (i2c_write_byte(g_i2c_fd, 0x00, 0x01) < 0) {
        fprintf(stderr, "Failed to clear power-down bit.\n");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return -1;
    }

    /* Allow the sensor to settle after power-up */
    usleep(100000);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read vibration magnitude (returns -1 on error)                     */
/* ------------------------------------------------------------------ */
static int read_vibration(void)
{
    uint8_t buf[2];
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (i2c_read_block(g_i2c_fd, 0x00, buf, 2) == 0)
            return (int)((uint16_t)buf[1] | ((uint16_t)buf[0] << 8));
        usleep(10000);
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Event logging                                                       */
/* ------------------------------------------------------------------ */
static void log_event(int magnitude)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);

    if (g_log_fp) {
        fprintf(g_log_fp, "%s, %d\n", ts, magnitude);
        fflush(g_log_fp);
    }
    printf("%s, %d\n", ts, magnitude);
}

/* ------------------------------------------------------------------ */
/* Alert LED control                                                    */
/* ------------------------------------------------------------------ */
static void trigger_alert(void)
{
    if (g_i2c_fd < 0) return;
    if (g_i2c_fd >= 0) {
        if (i2c_write_byte(g_i2c_fd, 0x00, 0x01) < 0)
            fprintf(stderr, "Warning: failed to set alert LED high.\n");
    }
    sleep(1);
    if (g_i2c_fd >= 0) {
        if (i2c_write_byte(g_i2c_fd, 0x00, 0x00) < 0)
            fprintf(stderr, "Warning: failed to set alert LED low.\n");
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (init_sensor() < 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Seismic monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int mag = read_vibration();
        if (mag < 0) {
            fprintf(stderr, "Read failed after %d retries; continuing.\n",
                    MAX_RETRIES);
        } else if (mag > VIBRATION_THRESHOLD) {
            log_event(mag);
            trigger_alert();
        }
        usleep(POLL_INTERVAL_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

