/*
 * obstacle.c — KY-032 IR obstacle sensors on Raspberry Pi 5 (BCM numbering)
 *
 * Wiring:
 *   Sensor 1 OUT -> GPIO4  (BCM)
 *   Sensor 2 OUT -> GPIO17 (BCM)
 *   Sensor 3 OUT -> GPIO27 (BCM)
 *   Sensor 4 OUT -> GPIO22 (BCM)
 *   LED anode   -> GPIO18 (BCM) via ~330 Ω resistor
 *   LED cathode -> GND
 *
 * The KY-032 is active-low: its OUT pin reads 0 when an object is
 * detected.  The LED is driven HIGH when any sensor reads 0.
 *
 * Build:  gcc -O2 -Wall -Wextra -o obstacle obstacle.c
 */

#include <errno.h>
#include <signal.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#include <gpiod.h>

#define NUM_SENSORS   4
#define POLL_MS       50
#define CONSUMER      "obstacle"

static const unsigned int sensor_pins[NUM_SENSORS] = {4, 17, 27, 22};
static const unsigned int led_pin          = 18;

static volatile sig_atomic_t g_running = 1;

static void sighandler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *sensor_lines[NUM_SENSORS];
    struct gpiod_line *led_line = NULL;
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_SENSORS; i++)
        sensor_lines[i] = NULL;
    led_line = NULL;

    if (install_signal_handlers() == -1)
        return EXIT_FAILURE;

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (chip == NULL) {
        /* Fallback: let the user try gpiochip0 on older kernels */
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (chip == NULL) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        sensor_lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (sensor_lines[i] == NULL) {
            fprintf(stderr, "Failed to get sensor line %u: %s\n",
                    sensor_pins[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_input(sensor_lines[i], CONSUMER) < 0) {
            fprintf(stderr, "Failed to request sensor line %u as input: %s\n",
                    sensor_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    led_line = gpiod_chip_get_line(chip, led_pin);
    if (led_line == NULL) {
        fprintf(stderr, "Failed to get LED line %u: %s\n",
                led_pin, strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(led_line, CONSUMER, 0) < 0) {
        fprintf(stderr, "Failed to request LED line %u as output: %s\n",
                led_pin, strerror(errno));
        goto cleanup;
    }

    printf("Obstacle detection started.  Press Ctrl+C to exit.\n");

    while (g_running) {
        int any_object = 0;

        for (int i = 0; i < NUM_SENSORS; i++) {
            int val = gpiod_line_get_value(sensor_lines[i]);
            if (val < 0) {
                fprintf(stderr, "Warning: read failed on sensor %d (pin %u): %s\n",
                        i, sensor_pins[i], strerror(errno));
                continue;
            }
            /* KY-032 is active-low: 0 => object detected */
            if (val == 0)
                any_object = 1;
        }

        if (gpiod_line_set_value(led_line, any_object) < 0) {
            fprintf(stderr, "Warning: failed to set LED: %s\n", strerror(errno));
        }

        struct timespec ts = { 0, POLL_MS * 1000000L };
        nanosleep(&ts, NULL);
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (led_line != NULL)
        gpiod_line_set_value(led_line, 0);
    if (led_line != NULL)
        gpiod_line_release(led_line);
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (sensor_lines[i] != NULL)
            gpiod_line_release(sensor_lines[i]);
    }
    if (chip != NULL)
        gpiod_chip_close(chip);

    return ret;
}

