/*
 * flame_monitor.c — KY026 flame-sensor monitor for Raspberry Pi 3 Model B+
 *
 * Build:  gcc -O2 -Wall -Wextra -o flame_monitor flame_monitor.c -lgpiod
 * Run:    sudo ./flame_monitor
 *
 * Five KY026 digital outputs are wired to BCM GPIO 2, 3, 4, 17, 27
 * (physical pins 3, 5, 7, 11, 13).  Each sensor is polled once per second.
 * On a confirmed HIGH->LOW transition the event is appended to
 * /var/log/flame_events.log and reported via syslog.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <syslog.h>
#include <gpiod.h>

#define NUM_SENSORS      5
#define POLL_INTERVAL_S  1
#define DEBOUNCE_MS      50
#define LOG_FILE         "/var/log/flame_events.log"
#define GPIO_CHIP_NAME   "gpiochip0"

static const unsigned int sensor_pins[NUM_SENSORS] = {2, 3, 4, 17, 27};

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction(SIGINT) failed: %s", strerror(errno));
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction(SIGTERM) failed: %s", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_event(int sensor_id, const char *message)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        syslog(LOG_ERR, "time() failed: %s", strerror(errno));
        return;
    }

    struct tm tm_utc;
    if (gmtime_r(&now, &tm_utc) == NULL) {
        syslog(LOG_ERR, "gmtime_r() failed");
        return;
    }

    char ts_buf[32];
    if (strftime(ts_buf, sizeof(ts_buf), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        syslog(LOG_ERR, "strftime() failed");
        return;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        syslog(LOG_ERR, "fopen(%s) failed: %s", LOG_FILE, strerror(errno));
        return;
    }

    if (flock(fileno(fp), LOCK_EX) != 0) {
        syslog(LOG_ERR, "flock(LOCK_EX) failed: %s", strerror(errno));
        fclose(fp);
        return;
    }

    if (fprintf(fp, "%s - Sensor ID: %d (GPIO %u) - %s\n",
                ts_buf, sensor_id, sensor_pins[sensor_id],
                message) < 0) {
        syslog(LOG_ERR, "fprintf() failed: %s", strerror(errno));
    }

    if (fflush(fp) != 0) {
        syslog(LOG_ERR, "fflush() failed: %s", strerror(errno));
    }

    if (flock(fileno(fp), LOCK_UN) != 0) {
        syslog(LOG_ERR, "flock(LOCK_UN) failed: %s", strerror(errno));
    }

    if (fclose(fp) != 0) {
        syslog(LOG_ERR, "fclose() failed: %s", strerror(errno));
    }

    syslog(LOG_INFO, "%s - Sensor ID: %d (GPIO %u) - %s",
           ts_buf, sensor_id, sensor_pins[sensor_id], message);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    openlog("flame_monitor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting flame-monitor daemon");

    if (install_signal_handlers() != 0) {
        syslog(LOG_ERR, "Failed to install signal handlers; aborting");
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        syslog(LOG_ERR, "gpiod_chip_open_by_name(%s) failed: %s",
               GPIO_CHIP_NAME, strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    struct gpiod_line *lines[NUM_SENSORS];
    int line_acquired = 0;

    for (int i = 0; i < NUM_SENSORS; i++) {
        lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (lines[i] == NULL) {
            syslog(LOG_ERR, "gpiod_chip_get_line(%u) failed: %s",
                   sensor_pins[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_input(lines[i], "flame_monitor") != 0) {
            syslog(LOG_ERR, "gpiod_line_request_input(GPIO %u) failed: %s",
                   sensor_pins[i], strerror(errno));
            lines[i] = NULL;
            goto cleanup;
        }
        line_acquired++;
    }

    syslog(LOG_INFO, "Monitoring %d flame sensor(s) on GPIO pins %u, %u, %u, %u, %u",
           line_acquired, sensor_pins[0], sensor_pins[1], sensor_pins[2],
           sensor_pins[3], sensor_pins[4]);

    int prev_state[NUM_SENSORS];
    for (int i = 0; i < NUM_SENSORS; i++) {
        prev_state[i] = gpiod_line_get_value(lines[i]);
        if (prev_state[i] < 0) {
            syslog(LOG_ERR, "gpiod_line_get_value(GPIO %u) failed: %s",
                   sensor_pins[i], strerror(errno));
            prev_state[i] = 0;
        }
    }

    while (g_running) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            int cur = gpiod_line_get_value(lines[i]);
            if (cur < 0) {
                syslog(LOG_ERR, "gpiod_line_get_value(GPIO %u) failed: %s",
                       sensor_pins[i], strerror(errno));
                continue;
            }

            if (cur == 0 && prev_state[i] == 1) {
                /* Debounce: wait 50 ms and re-read */
                usleep(DEBOUNCE_MS * 1000);

                int debounced = gpiod_line_get_value(lines[i]);
                if (debounced < 0) {
                    syslog(LOG_ERR, "gpiod_line_get_value(GPIO %u) failed: %s",
                           sensor_pins[i], strerror(errno));
                    continue;
                }

                if (debounced == 0) {
                    log_event(i + 1, "Flame Detected");
                }
            }

            prev_state[i] = cur;
        }
        sleep(POLL_INTERVAL_S);
    }

cleanup:
    syslog(LOG_INFO, "Shutting down flame-monitor daemon");

    for (int i = 0; i < line_acquired; i++) {
        if (lines[i] != NULL) {
            gpiod_line_release(lines[i]);
        }
    }

    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    closelog();
    return EXIT_SUCCESS;
}

