/*
 * TTP226 8-channel capacitive touch sensor reader for Raspberry Pi 3 Model B+.
 *
 * Wiring (BCM numbering):
 *   TTP226 OUT0 -> GPIO 5
 *   TTP226 OUT1 -> GPIO 6
 *   TTP226 OUT2 -> GPIO 13
 *   TTP226 OUT3 -> GPIO 19
 *   TTP226 OUT4 -> GPIO 26
 *   TTP226 OUT5 -> GPIO 12
 *   TTP226 OUT6 -> GPIO 16
 *   TTP226 OUT7 -> GPIO 20
 *
 * Build:  gcc -Wall -Wextra -O2 -o ttp226 ttp226.c -lgpiod
 * Run:    sudo ./ttp226
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_US 50000   /* 50 ms */

static const unsigned int touch_pins[NUM_CHANNELS] = {
    5, 6, 13, 19, 26, 12, 16, 20
};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void print_timestamp(void)
{
    time_t rawtime;
    struct tm timeinfo;
    char buf[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL &&
        strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%S", &timeinfo) > 0) {
        printf("[%s] ", buf);
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_CHANNELS];
    int prev_states[NUM_CHANNELS];
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_CHANNELS; i++)
        lines[i] = NULL;

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on RPi 3 B+) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Request each line as input */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, touch_pins[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "Failed to get GPIO line %u: %s\n",
                    touch_pins[i], strerror(errno));
            goto cleanup;
        }

        if (gpiod_line_request_input(lines[i], "ttp226-reader") < 0) {
            fprintf(stderr, "Failed to request GPIO line %u as input: %s\n",
                    touch_pins[i], strerror(errno));
            goto cleanup;
        }

        prev_states[i] = gpiod_line_get_value(lines[i]);
        if (prev_states[i] < 0) {
            fprintf(stderr, "Failed to read initial value from GPIO %u: %s\n",
                    touch_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    printf("TTP226 touch sensor monitoring started. Press Ctrl-C to exit.\n");
    fflush(stdout);

    while (program_running) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int cur = gpiod_line_get_value(lines[i]);
            if (cur < 0) {
                fprintf(stderr, "Error reading GPIO %u: %s\n",
                        touch_pins[i], strerror(errno));
                goto cleanup;
            }

            if (cur != prev_states[i]) {
                print_timestamp();
                printf("Sensor %d (GPIO %u) - %s\n",
                       i, touch_pins[i],
                       cur ? "Touched" : "Released");
                fflush(stdout);
                prev_states[i] = cur;
            }
        }
        usleep(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup:
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (lines[i] != NULL)
            gpiod_line_release(lines[i]);
    }
    if (chip != NULL)
        gpiod_chip_close(chip);

    return ret;
}

