/*
 * OPT3001 ambient light sensor reader for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   OPT3001 SDA  -> GPIO2  (pin 3, I2C bus 1)
 *   OPT3001 SCL  -> GPIO3  (pin 5, I2C bus 1)
 *   OPT3001 VDD  -> 3.3 V
 *   OPT3001 GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o opt3001_reader opt3001_reader.c
 *
 * Run:
 *   ./opt3001_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define OPT3001_ADDR   0x44
#define LOG_FILE       "light_data.txt"
#define SAMPLE_PERIOD  1          /* seconds */
#define CONFIG_DELAY   100        /* microseconds */

/* OPT3001 register addresses */
#define REG_RESULT     0x00
#define REG_CONFIG     0x01
#define REG_MANUF_ID   0x7E
#define REG_DEV_ID     0x7F

/* OPT3001 command bits (MSB first) */
#define CMD_READ       0x2400
#define CMD_WRITE      0x2000

/* Config register bits */
#define CFG_INT_EN     0x01
#define CFG_ADC_GAIN   0x0C
#define CFG_ADC_PGA    0x30
#define CFG_ADC_MODE   0x20
#define CFG_ADC_DR     0x08

/* PGA = 1 LSB = 0.5 mV  ->  1.024 mV / 0.5 mV = 2.048 counts */
#define ADC_GAIN_1V   0x0C
#define ADC_PGA_1V    0x30
#define ADC_MODE_CONT 0x20
#define ADC_DR_100MS  0x08

/* 16-bit big-endian -> 16-bit little-endian conversion */
static inline uint16_t be16_to_le16(uint16_t v)
{
    return (uint16_t)((v >> 8) | (v << 8));
}

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write16(int fd, uint8_t reg, uint16_t val)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(val >> 8);
    buf[2] = (uint8_t)(val & 0xFF);

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write16(reg=0x%02X): %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t cmd = reg;
    uint8_t buf[2];

    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "i2c_read16: write reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_read16: read reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int opt3001_init(int fd)
{
    uint16_t manuf_id = 0, dev_id = 0;

    if (i2c_read16(fd, REG_MANUF_ID, &manuf_id) != 0) {
        fprintf(stderr, "Cannot read OPT3001 manufacturer ID.\n");
        return -1;
    }
    if (i2c_read16(fd, REG_DEV_ID, &dev_id) != 0) {
        fprintf(stderr, "Cannot read OPT3001 device ID.\n");
        return -1;
    }

    printf("OPT3001 detected (manuf=0x%04X, dev=0x%04X)\n", manuf_id, dev_id);

    /* Write configuration: continuous conversion, PGA=1.024 mV, 100 ms DR */
    uint16_t cfg = CFG_INT_EN | ADC_GAIN_1V | ADC_PGA_1V | ADC_MODE_CONT | ADC_DR_100MS;
    if (i2c_write16(fd, REG_CONFIG, cfg) != 0) {
        fprintf(stderr, "Cannot write OPT3001 config register.\n");
        return -1;
    }

    /* Wait for the first conversion to complete */
    usleep(CONFIG_DELAY * 1000);

    return 0;
}

static int opt3001_read_lux(int fd, float *lux_out)
{
    uint16_t raw = 0;

    if (i2c_read16(fd, REG_RESULT, &raw) != 0) {
        fprintf(stderr, "Cannot read OPT3001 result register.\n");
        return -1;
    }

    /* Byte-swap big-endian result to little-endian host order */
    raw = be16_to_le16(raw);

    /* Check error bit (bit 15) */
    if (raw & 0x8000) {
        fprintf(stderr, "OPT3001 error flag set (raw=0x%04X).\n", raw);
        return -1;
    }

    /* Result is 16-bit, upper 12 bits are the exponent, lower 4 bits are the mantissa */
    uint16_t exponent = (raw >> 4) & 0x0FFF;
    uint16_t mantissa = raw & 0x0FFF;

    /* Mantissa is in counts; 1 LSB = 0.5 mV, PGA=1.024 mV -> 2.048 counts per LSB */
    *lux_out = (float)mantissa / 2.048f;
    return 0;
}

static int log_data(const char *filename, const char *timestamp, float lux)
{
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open log file '%s': %s\n", filename, strerror(errno));
        return -1;
    }

    if (fprintf(fp, "%s, %.2f\n", timestamp, lux) < 0) {
        fprintf(stderr, "Cannot write to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "Cannot flush log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Cannot close log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, OPT3001_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                OPT3001_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    if (opt3001_init(g_i2c_fd) != 0) {
        fprintf(stderr, "OPT3001 initialization failed.\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("Starting light data logging to %s (Ctrl+C to stop)\n", LOG_FILE);

    while (g_running) {
        time_t rawtime = time(NULL);
        if (rawtime == (time_t)-1) {
            fprintf(stderr, "time() failed: %s\n", strerror(errno));
            sleep(SAMPLE_PERIOD);
            continue;
        }

        struct tm timeinfo;
        if (localtime_r(&rawtime, &timeinfo) == NULL) {
            fprintf(stderr, "localtime_r() failed\n");
            sleep(SAMPLE_PERIOD);
            continue;
        }

        char timestamp[32];
        if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                     &timeinfo) == 0) {
            fprintf(stderr, "strftime() failed\n");
            sleep(SAMPLE_PERIOD);
            continue;
        }

        float lux = 0.0f;
        if (opt3001_read_lux(g_i2c_fd, &lux) != 0) {
            sleep(SAMPLE_PERIOD);
            continue;
        }

        if (log_data(LOG_FILE, timestamp, lux) != 0) {
            sleep(SAMPLE_PERIOD);
            continue;
        }

        printf("%s, %.2f lux\n", timestamp, lux);
        fflush(stdout);

        sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down...\n");
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return EXIT_SUCCESS;
}

