            sleep(SAMPLE_PERIOD);
            continue;
        }

        float lux = 0.0f;
        if (opt3001_read_lux(g_i2c_fd, &lux) != 0) {
            sleep(SAMPLE_PERIOD);
            continue;
        }

        if (log_data(LOG_FILE, timestamp, lux) != 0) {
            sleep(SAMPLE_PERIOD);
            continue;
        }

        printf("%s, %.2f lux\n", timestamp, lux);
        fflush(stdout);

        sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down...\n");
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return EXIT_SUCCESS;
}

