#define LOG_FILE "fire_events.log"
#define POLL_INTERVAL_US 500000
#define ALERT_DURATION_US 1000000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(const char *message) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }
    if (log_file != NULL) {
        if (fprintf(log_file, "%s: %s\n", timestamp, message) < 0) {
            fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
            return -1;
        }
        if (fflush(log_file) != 0) {
            fprintf(stderr, "fflush failed: %s\n", strerror(errno));
            return -1;
        }
    } else {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }
    return 0;
}

static int read_flame_sensor(int pin) {
    int value = gpioRead(pin);
    if (value < 0) {
        fprintf(stderr, "gpioRead failed on pin %d: %s\n", pin, pigpio_error(value));
        return -1;
    }
    return value;
}

static int set_alert_pin(int pin, int state) {
    int result = gpioWrite(pin, state);
    if (result < 0) {
        fprintf(stderr, "gpioWrite failed on pin %d: %s\n", pin, pigpio_error(result));
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(ALERT_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set flame sensor pin %d as input\n", FLAME_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(ALERT_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set alert pin %d as output\n", ALERT_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioWrite(ALERT_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialise alert pin %d to LOW\n", ALERT_PIN);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int flame_value = read_flame_sensor(FLAME_SENSOR_PIN);
        if (flame_value < 0) {
            log_event("Error reading flame sensor");
        } else if (flame_value == 0) {
            if (set_alert_pin(ALERT_PIN, 1) != 0) {
                log_event("Error setting alert pin HIGH");
            } else {
                log_event("Flame detected!");
                gpioDelay(ALERT_DURATION_US);
                if (set_alert_pin(ALERT_PIN, 0) != 0) {
                    log_event("Error setting alert pin LOW");
                }
            }
        } else {
            log_event("No flame detected");
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

