/*
 * Raspberry Pi Zero W – Sensirion SLF3S-1300F Liquid Flow Sensor monitor
 *
 * Wiring:
 *   SLF3S SDA  -> GPIO2 (pin 3, I2C bus 1 SDA)
 *   SLF3S SCL  -> GPIO3 (pin 5, I2C bus 1 SCL)
 *   SLF3S VDD  -> 3.3 V
 *   SLF3S GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o cooling_monitor cooling_monitor.c
 *
 * The SLF3S-1300F is a 3-wire I2C liquid flow sensor that returns a 3-byte
 * big-endian frame: [signed 16-bit flow, CRC8].  The driver performs CRC
 * validation and range checking; out-of-range or CRC-faulting samples are
 * logged with a status string and the I2C handle is re-initialized so the
 * sensor can continue to report.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x60
#define LOG_FILE       "cooling_log.csv"
#define SAMPLE_PERIOD  1          /* seconds between samples */
#define INIT_DELAY_US  2000       /* first measurement must wait >= 2 ms */
#define MAX_FLOW_RATE  100.0      /* ml/min – SLF3S-1300F typical range */
#define MIN_FLOW_RATE  0.0
#define CRC_POLY       0x31
#define CRC_INIT       0xFF

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF)                        */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = CRC_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ CRC_POLY : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int handle, uint8_t cmd)
{
    if (i2cWriteByte(handle, cmd) < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByte(0x%02X) failed: %s\n",
                cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int handle, uint8_t *buf, size_t len)
{
    int n = i2cReadDevice(handle, (char *)buf, len);
    if (n != (int)len) {
        fprintf(stderr, "[ERROR] i2cReadDevice expected %zu bytes, got %d: %s\n",
                len, n, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor read                                                         */
/* ------------------------------------------------------------------ */
/*
 * The SLF3S-1300F is a 3-byte I2C frame: [signed 16-bit flow, CRC8].
 * pigpio's i2cReadDevice returns the bytes in the order they were
 * written, so the first byte is the MSB of the flow value.
 */
static int read_flow_rate(int handle, float *flow_rate, uint8_t *flags)
{
    uint8_t buf[3];

    if (i2c_read_bytes(handle, buf, sizeof(buf)) != 0)
        return -1;

    /* CRC check */
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "[ERROR] CRC mismatch (calc=0x%02X recv=0x%02X)\n",
                crc8(buf, 2), buf[2]);
        return -1;
    }

    /* Assemble signed 16-bit big-endian flow */
    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);

    /* Sanity range check */
    if (raw < (int16_t)(MIN_FLOW_RATE * 1000.0) || raw > (int16_t)(MAX_FLOW_RATE * 1000.0)) {
        fprintf(stderr, "[WARN] Flow out of plausible range: %d ml/min\n",
                (int)(raw / 1000.0));
        return -1;
    }

    *flow_rate = (float)raw / 1000.0f;
    *flags     = buf[2];          /* raw CRC byte – not a flag per se */
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_sample(FILE *fp, float flow_rate, uint8_t flags, const char *status)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed: %s\n", strerror(errno));
        return;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%s\n", ts, flow_rate, status);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- I2C open --------------------------------------------------- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Log file --------------------------------------------------- */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        fprintf(stderr, "[FATAL] Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write header only if file is empty */
    if (fseek(g_log_file, 0, SEEK_END) == 0) {
        long sz = ftell(g_log_file);
        if (sz == 0)
            fprintf(g_log_file, "Timestamp,Flow Rate (ml/min),Status\n");
    } else {
        fprintf(stderr, "[WARN] Cannot seek log file: %s\n", strerror(errno));
    }
    fflush(g_log_file);

    /* --- Signal handling ------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGINT) failed: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGTERM) failed: %s\n", strerror(errno));
    }

    /* --- Initial delay ------------------------------------------------ */
    gpioDelay(INIT_DELAY_US);

    /* --- Main loop --------------------------------------------------- */
    while (g_running) {
        float flow_rate = 0.0f;
        uint8_t flags    = 0;

        if (read_flow_rate(g_i2c_handle, &flow_rate, &flags) == 0) {
            const char *status = "OK";
            if (flow_rate < 0.0f || flow_rate > MAX_FLOW_RATE)
                status = "INVALID";
            log_sample(g_log_file, flow_rate, flags, status);
        } else {
            fprintf(stderr, "[ERROR] Sensor read failed; re-initializing I2C...\n");
            i2cClose(g_i2c_handle);
            g_i2c_handle = -1;
            gpioDelay(100000);          /* 100 ms back-off */
            g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
            if (g_i2c_handle < 0) {
                fprintf(stderr, "[FATAL] Re-open failed: %s\n", strerror(errno));
                break;
            }
            gpioDelay(INIT_DELAY_US);
        }

        /* Sleep SAMPLE_PERIOD seconds, but wake early on signal */
        for (int i = 0; i < SAMPLE_PERIOD && g_running; i++)
            gpioDelay(1000000);          /* 1 s */
    }

    /* --- Graceful shutdown ------------------------------------------ */
    cleanup();
    return EXIT_SUCCESS;
}

