#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>

#define LEFT_SENSOR_PIN 17
#define MIDDLE_SENSOR_PIN 27
#define RIGHT_SENSOR_PIN 22
#define LOG_FILE "path_log.csv"
#define POLL_INTERVAL_MS 50

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signum) {
    (void)signum;
    program_running = 0;
}

static int gpio_init(int *pins, int num_pins) {
    int chip_fd = open("/dev/gpiochip0", O_RDWR);
    if (chip_fd < 0) {
        fprintf(stderr, "Error opening /dev/gpiochip0: %s\n", strerror(errno));
        return -1;
    }

    unsigned int gpio_pins[num_pins];
    for (int i = 0; i < num_pins; i++) {
        gpio_pins[i] = (unsigned int)pins[i];
    }

    for (int i = 0; i < num_pins; i++) {
        int ret = ioctl(chip_fd, GPIO_GET_LINE, &gpio_pins[i]);
        if (ret < 0) {
            fprintf(stderr, "Error getting GPIO line %u: %s\n", gpio_pins[i], strerror(errno));
            close(chip_fd);
            return -1;
        }
    }

    for (int i = 0; i < num_pins; i++) {
        int ret = ioctl(chip_fd, GPIO_SET_LINE, &gpio_pins[i]);
        if (ret < 0) {
            fprintf(stderr, "Error setting GPIO line %u: %s\n", gpio_pins[i], strerror(errno));
            close(chip_fd);
            return -1;
        }
    }

    return chip_fd;
}

static int gpio_read(int chip_fd, int pin) {
    unsigned int gpio_pin = (unsigned int)pin;
    int ret = ioctl(chip_fd, GPIO_GET_LINE_VALUE, &gpio_pin);
    if (ret < 0) {
        fprintf(stderr, "Error reading GPIO line %u: %s\n", pin, strerror(errno));
        return -1;
    }
    return ret;
}

static int gpio_set_input(int chip_fd, int pin) {
    unsigned int gpio_pin = (unsigned int)pin;
    int ret = ioctl(chip_fd, GPIO_SET_LINE_DIRECTION, &gpio_pin);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO line %u as input: %s\n", pin, strerror(errno));
        return -1;
    }
    return 0;
}

static int gpio_set_output(int chip_fd, int pin) {
    unsigned int gpio_pin = (unsigned int)pin;
    int ret = ioctl(chip_fd, GPIO_SET_LINE_DIRECTION, &gpio_pin);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO line %u as output: %s\n", pin, strerror(errno));
        return -1;
    }
    return 0;
}

static int gpio_release(int chip_fd, int pin) {
    unsigned int gpio_pin = (unsigned int)pin;
    int ret = ioctl(chip_fd, GPIO_SET_LINE_DIRECTION, &gpio_pin);
    if (ret < 0) {
        fprintf(stderr, "Error releasing GPIO line %u: %s\n", pin, strerror(errno));
        return -1;
    }
    return 0;
}

static int log_data(FILE *fp, int left, int middle, int right) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        return -1;
    }

    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, left, middle, right) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    int pins[] = {LEFT_SENSOR_PIN, MIDDLE_SENSOR_PIN, RIGHT_SENSOR_PIN};
    int num_pins = sizeof(pins) / sizeof(pins[0]);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int chip_fd = gpio_init(pins, num_pins);
    if (chip_fd < 0) {
        return EXIT_FAILURE;
    }

    if (gpio_set_input(chip_fd, pins[0]) < 0 ||
        gpio_set_input(chip_fd, pins[1]) < 0 ||
        gpio_set_input(chip_fd, pins[2]) < 0) {
        close(chip_fd);
        return EXIT_FAILURE;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        close(chip_fd);
        return EXIT_FAILURE;
    }

    printf("Starting data logging to %s. Press Ctrl+C to stop.\n", LOG_FILE);

    while (program_running) {
        int left = gpio_read(chip_fd, pins[0]);
        int middle = gpio_read(chip_fd, pins[1]);
        int right = gpio_read(chip_fd, pins[2]);

        if (left < 0 || middle < 0 || right < 0) {
            fprintf(stderr, "Error reading sensor data, exiting.\n");
            break;
        }

        if (log_data(fp, left, middle, right) < 0) {
            fprintf(stderr, "Error logging data, exiting.\n");
            break;
        }

        usleep(POLL_INTERVAL_MS * 1000);
    }

    printf("\nCleaning up...\n");

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
    }

    if (gpio_release(chip_fd, pins[0]) < 0 ||
        gpio_release(chip_fd, pins[1]) < 0 ||
        gpio_release(chip_fd, pins[2]) < 0) {
        fprintf(stderr, "Error releasing GPIO lines, exiting.\n");
        return EXIT_FAILURE;
    }

    if (close(chip_fd) < 0) {
        fprintf(stderr, "Error closing GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    printf("Data logging stopped.\n");
    return EXIT_SUCCESS;
}

