/*
 * touch_lamp.c — TTP223 capacitive touch sensor toggles an LED on Raspberry Pi 5.
 *
 * Wiring (BCM numbering):
 *   TTP223 OUT  -> GPIO23 (physical pin 16)
 *   LED anode   -> GPIO24 (physical pin 18) via ~330 Ω resistor
 *   LED cathode -> GND
 *   TTP223 VCC  -> 3.3 V (physical pin 1)
 *   TTP223 GND  -> GND (physical pin 9)
 *
 * Build:  gcc -O2 -Wall -Wextra -o touch_lamp touch_lamp.c
 * Run:    ./touch_lamp   (requires rpi-gpio group access to /dev/gpiochip4)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>

#define TOUCH_GPIO    23
#define LED_GPIO      24
#define LOG_FILE      "touch_log.txt"
#define POLL_TIMEOUT  1          /* seconds */
#define POLL_INTERVAL 0          /* zero-delay poll so events fire promptly */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                         */
/* ------------------------------------------------------------------ */
static int gpio_init(int chip_fd, unsigned int gpio)
{
    struct gpio_request_config req;
    memset(&req, 0, sizeof(req));
    req.consumer = "touch_lamp";
    req.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    req.flags = 0;

    if (ioctl(chip_fd, GPIOD_LINE_REQUEST, &req) < 0) {
        fprintf(stderr, "Error requesting GPIO %u as input: %s\n",
                gpio, strerror(errno));
        return -1;
    }
    return 0;
}

static int gpio_set_output(int chip_fd, unsigned int gpio)
{
    struct gpio_request_config req;
    memset(&req, 0, sizeof(req));
    req.consumer = "touch_lamp";
    req.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    req.flags = 0;

    if (ioctl(chip_fd, GPIOD_LINE_REQUEST, &req) < 0) {
        fprintf(stderr, "Error requesting GPIO %u as output: %s\n",
                gpio, strerror(errno));
        return -1;
    }
    return 0;
}

static int gpio_read(int chip_fd, unsigned int gpio)
{
    int val = -1;
    if (ioctl(chip_fd, GPIOD_LINE_GET_VALUE, &val) < 0) {
        fprintf(stderr, "Error reading GPIO %u: %s\n",
                gpio, strerror(errno));
        return -1;
    }
    return val;
}

static int gpio_write(int chip_fd, unsigned int gpio, int value)
{
    if (ioctl(chip_fd, GPIOD_LINE_SET_VALUE, &value) < 0) {
        fprintf(stderr, "Error writing GPIO %u: %s\n",
                gpio, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_event(FILE *fp, int led_state)
{
    time_t rawtime;
    struct tm tm_info;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &tm_info) == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%dT%H:%M:%S%z", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        return -1;
    }

    if (fprintf(fp, "%s LED=%d\n", timestamp, led_state) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(int chip_fd)
{
    if (g_log != NULL) {
        fclose(g_log);
        g_log = NULL;
    }

    if (chip_fd >= 0) {
        /* Release LED line before touching touch line to avoid errors */
        (void)gpio_write(chip_fd, LED_GPIO, 0);
        (void)gpio_release(chip_fd, LED_GPIO);
        (void)gpio_release(chip_fd, TOUCH_GPIO);
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int chip_fd = -1;
    int ret = EXIT_FAILURE;

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n",
                strerror(errno));
        goto out;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering SIGTERM handler: %s\n",
                strerror(errno));
        goto out;
    }

    /* ---- Open log file ---- */
    g_log = fopen(LOG_FILE, "a");
    if (g_log == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        goto out;
    }

    /* ---- Open GPIO chip ---- */
    chip_fd = open("/dev/gpiochip4", O_RDWR);
    if (chip_fd < 0) {
        fprintf(stderr, "Error opening /dev/gpiochip4: %s\n",
                strerror(errno));
        goto out;
    }

    /* ---- Initialize touch line ---- */
    if (gpio_init(chip_fd, TOUCH_GPIO) < 0) {
        goto out;
    }

    /* ---- Initialize LED line ---- */
    if (gpio_set_output(chip_fd, LED_GPIO) < 0) {
        goto out;
    }

    /* ---- Main polling loop ---- */
    while (g_running) {
        int touch_val = gpio_read(chip_fd, TOUCH_GPIO);
        if (touch_val < 0) {
            /* Transient read error — brief pause then retry */
            usleep(100000);
            continue;
        }

        if (touch_val == 1) {
            int led_state = !led_state;
            if (gpio_write(chip_fd, LED_GPIO, led_state) < 0) {
                /* Non-fatal: continue polling */
            }

            if (log_event(g_log, led_state) < 0) {
                /* Non-fatal: continue polling */
            }

            usleep(500000); /* 0.5 s debounce / settle */
        }

        usleep(POLL_INTERVAL * 1000000); /* 0 s poll interval */
    }

    ret = EXIT_SUCCESS;

out:
    cleanup(chip_fd);
    return ret;
}

