/*
 * TMAG5110A1 Hall-effect latch sensor monitor for Raspberry Pi 4 Model B.
 *
 * Three TMAG5110A1A1 sensors are connected via an open-drain output:
 *   - Sensor 1 OUT -> GPIO4  (BCM)
 *   - Sensor 2 OUT -> GPIO17 (BCM)
 *   - Sensor 3 OUT -> GPIO27 (BCM)
 *
 * The TMAG5110A1A1 has a south-pole Hall-effect sensor: the output
 * is LOW when a magnet is present (magnet-present = logic 0),
 * and HIGH when the magnet is removed (magnet-removed = logic 1).
 *
 * Build:  gcc -O2 -Wall -Wextra -o magnet_monitor magnet_monitor.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define SENSOR1_PIN  4
#define SENSOR2_PIN  17
#define SENSOR3_PIN  27

#define LOG_FILE      "magnet_log.txt"
#define POLL_DELAY_US 100000   /* 100 ms */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0)
        perror("warning: sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) != 0)
        perror("warning: sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_event(int sensor_id, int state)
{
    time_t rawtime;
    struct tm tm_info;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &tm_info) == NULL) {
        fprintf(stderr, "Error: localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%dT%H:%M:%S%z", &tm_info) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return;
    }

    if (fprintf(g_log_fp, "%s - Sensor %d: %s\n",
                timestamp, sensor_id,
                state ? "magnet present" : "magnet removed") < 0) {
        fprintf(stderr, "Error: fprintf to log failed: %s\n", strerror(errno));
        return;
    }

    if (fflush(g_log_fp) != 0)
        perror("warning: fflush failed");
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int pins[3] = { SENSOR1_PIN, SENSOR2_PIN, SENSOR3_PIN };
    const char *names[3] = { "Sensor 1", "Sensor 2", "Sensor 3" };
    int prev_state[3] = { -1, -1, -1 };
    int rc = EXIT_SUCCESS;

    install_signal_handlers();

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < 3; i++) {
        if (gpioSetMode(pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode(%d, PI_INPUT) failed\n", pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
        if (gpioSetPullUpDown(pins[i], PI_PUD_UP) != 0) {
            fprintf(stderr, "Error: gpioSetPullUpDown(%d, PI_PUD_UP) failed\n", pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error: cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Monitoring TMAG5110A1A1 sensors on GPIO%d, %d, %d...\n",
           SENSOR1_PIN, SENSOR2_PIN, SENSOR3_PIN);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        for (int i = 0; i < 3; i++) {
            int level = gpioRead(pins[i]);
            if (level < 0) {
                fprintf(stderr, "Error: gpioRead(%d) failed\n", pins[i]);
                continue;
            }

            /* Log only on state change; ignore the initial reading. */
            if (level != prev_state[i]) {
                log_event(i + 1, level);
                prev_state[i] = level;
            }
        }
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return rc;
}

