/*
 * Si1182-A-GM Heart-Rate Monitor for Raspberry Pi 4 Model B
 *
 * Reads the Si1182 optical heart-rate sensor on I2C bus 1, applies a
 * five-sample moving average filter to the raw heart-rate register,
 * validates the filtered BPM value, and appends valid readings to
 * heart_rate.csv.
 *
 * Build:  gcc -O2 -Wall -Wextra -o si1182_hr si1182_hr.c -lm
 * Run:    ./si1182_hr
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <math.h>
#include <pigpio.h>

/* ---- Si1182 constants (per datasheet) ---- */
#define SI1182_I2C_BUS        1
#define SI1182_I2C_ADDR       0x60

#define SI1182_REG_PART_ID    0x00
#define SI1182_REG_HW_REV    0x01
#define SI1182_REG_HW_KEY    0x07
#define SI1182_REG_MEAS_RATE 0x08
#define SI1182_REG_HR_DATA   0x0A
#define SI1182_REG_HR_CONFIG 0x0B

#define SI1182_PART_ID_EXPECTED 0x82
#define SI1182_HW_REV_EXPECTED  0x00

#define SI1182_HR_CONFIG_DEFAULT 0x00
#define SI1182_MEAS_RATE_DEFAULT 0x0A  /* 10 ms measurement rate */

#define MOVING_AVG_SIZE 5
#define SAMPLE_PERIOD_US 1000000  /* 1 second */
#define MAX_RETRIES      3

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Low-level I2C helpers                                              */
/* ------------------------------------------------------------------ */
static int si1182_read_reg(int handle, uint8_t reg, uint8_t *val)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %s\n",
                reg, pigpio_error(rc));
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int si1182_write_reg(int handle, uint8_t reg, uint8_t val)
{
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %s\n",
                reg, val, pigpio_error(rc));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor initialization                                               */
/* ------------------------------------------------------------------ */
static int si1182_init(int handle)
{
    uint8_t part_id, hw_rev;

    /* Verify sensor identity */
    if (si1182_read_reg(handle, SI1182_REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Cannot read PART_ID — sensor absent or bus error.\n");
        return -1;
    }
    if (part_id != SI1182_PART_ID_EXPECTED) {
        fprintf(stderr,
                "PART_ID mismatch: got 0x%02X, expected 0x%02X "
                "(sensor not present or wrong device).\n",
                part_id, SI1182_PART_ID_EXPECTED);
        return -1;
    }

    if (si1182_read_reg(handle, SI1182_REG_HW_REV, &hw_rev) != 0) {
        fprintf(stderr, "Cannot read HW_REV — sensor absent or bus error.\n");
        return -1;
    }
    if (hw_rev != SI1182_HW_REV_EXPECTED) {
        fprintf(stderr,
                "HW_REV mismatch: got 0x%02X, expected 0x%02X "
                "(sensor not present or wrong device).\n",
                hw_rev, SI1182_HW_REV_EXPECTED);
        return -1;
    }

    /* Write HW_KEY (required per datasheet) */
    if (si1182_write_reg(handle, SI1182_REG_HW_KEY, 0x00) != 0)
        return -1;

    /* Set measurement rate (10 ms) */
    if (si1182_write_reg(handle, SI1182_REG_MEAS_RATE,
                          SI1182_MEAS_RATE_DEFAULT) != 0)
        return -1;

    /* Configure heart-rate data: enable HR, 1 sample, 1 Hz update */
    if (si1182_write_reg(handle, SI1182_REG_HR_CONFIG,
                          SI1182_HR_CONFIG_DEFAULT) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Moving-average filter                                              */
/* ------------------------------------------------------------------ */
static int moving_average(int *buf, int size, int new_val, int *out)
{
    buf[size - 1] = new_val;
    int sum = 0;
    for (int i = 0; i < size; i++)
        sum += buf[i];
    *out = sum / size;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read heart-rate BPM (returns 0 on success, -1 on error)            */
/* ------------------------------------------------------------------ */
static int read_heart_rate(int handle, int *bpm_out)
{
    uint8_t hr_raw;
    int     buf[MOVING_AVG_SIZE];
    int     idx = 0;
    int     rc;

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        rc = si1182_read_reg(handle, SI1182_REG_HR_DATA, &hr_raw);
        if (rc == 0) {
            int bpm = (int)hr_raw;
            if (moving_average(buf, MOVING_AVG_SIZE, bpm, &bpm) == 0) {
                *bpm_out = bpm;
                return 0;
            }
            fprintf(stderr, "Moving-average filter returned %d BPM.\n", bpm);
            return -1;
        }
        fprintf(stderr, "I2C read error (attempt %d/%d): %s\n",
                attempt + 1, MAX_RETRIES, pigpio_error(rc));
        if (attempt < MAX_RETRIES - 1)
            gpioDelay(100000);  /* 100 ms backoff */
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Log a valid reading                                                 */
/* ------------------------------------------------------------------ */
static int log_heart_rate(FILE *fp, int bpm)
{
    time_t     rawtime;
    struct tm  tm_info;
    char       ts[32];

    time(&rawtime);
    localtime_r(&rawtime, &tm_info);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);

    if (fprintf(fp, "%s,%d\n", ts, bpm) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int     bpm;
    int     rc;

    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* --- open I2C --- */
    g_i2c_handle = i2cOpen(SI1182_I2C_BUS, SI1182_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (bus %d, addr 0x%02X): %s\n",
                SI1182_I2C_BUS, SI1182_I2C_ADDR,
                pigpio_error(g_i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- sensor init --- */
    if (si1182_init(g_i2c_handle) != 0) {
        fprintf(stderr, "Si1182 initialisation failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- open log file --- */
    g_log_file = fopen("heart_rate.csv", "a");
    if (!g_log_file) {
        fprintf(stderr, "Cannot open heart_rate.csv: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,bpm\n");
        fflush(g_log_file);
    }

    /* --- signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Si1182 heart-rate monitor started. Press Ctrl+C to stop.\n");

    /* --- main loop --- */
    while (g_running) {
        if (read_heart_rate(g_i2c_handle, &bpm) == 0) {
            if (bpm >= 30 && bpm <= 220) {
                if (log_heart_rate(g_log_file, bpm) != 0) {
                    fprintf(stderr, "Logging failed; continuing.\n");
                }
            } else {
                fprintf(stderr,
                        "BPM out of range: %d (valid 30–220).\n", bpm);
            }
        } else {
            fprintf(stderr, "Heart-rate read failed; will retry next cycle.\n");
        }

        /* Sleep 1 s, but wake early on signal */
        for (int i = 0; i < 10 && g_running; i++)
            gpioDelay(100000);  /* 100 ms × 10 = 1 s */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

