/*
 * touch_counter.c — TTP226 8-channel capacitive touch sensor → 8-bit binary counter
 *
 * Board : Raspberry Pi Zero W
 * Library: libgpiod (modern GPIO character-device API)
 *
 * Wiring
 *   TTP226 OUT1..OUT8  -> BCM 5, 6, 7, 8, 9, 10, 11, 12 (active-high)
 *   Counter bit 0     -> BCM 17
 *   Counter bit 7     -> BCM 24
 *
 * Build
 *   gcc -O2 -Wall -Wextra -o touch_counter touch_counter.c -lgpiod
 *
 * Run
 *   sudo ./touch_counter
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define STABILIZE_MS  200
#define POLL_MS       10
#define LOG_FILE      "touch_log.txt"

static const unsigned int sensor_pins[NUM_CHANNELS] = {5, 6, 7, 8, 9, 10, 11, 12};
static const unsigned int counter_pins[NUM_CHANNELS] = {17, 18, 19, 20, 21, 22, 23, 24};

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static void sleep_ms(unsigned int ms)
{
    struct timespec ts = { ms / 1000, (long)(ms % 1000) * 1000000L };
    nanosleep(&ts, NULL);
}

static void log_touch_event(FILE *fp, int channel, int counter)
{
    time_t t = time(NULL);
    struct tm tm_utc;
    char ts[32];

    if (gmtime_r(&t, &tm_utc) == NULL) {
        fprintf(stderr, "gmtime_r failed: %s\n", strerror(errno));
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%DT%H:%M:%SZ", &tm_utc);

    if (fprintf(fp, "%s, Channel: %d, Counter: %d\n", ts, channel, counter) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
    } else {
        fflush(fp);
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *sensor_lines[NUM_CHANNELS];
    struct gpiod_line *counter_lines[NUM_CHANNELS];
    int ret = EXIT_FAILURE;
    int prev_counter = 0;
    int i;

    for (i = 0; i < NUM_CHANNELS; i++)
        sensor_lines[i] = counter_lines[i] = NULL;

    /* --- Signal handling ---------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Open GPIO chip ------------------------------------------------ */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "gpiod_chip_open_by_name: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Acquire sensor lines (inputs) --------------------------------- */
    for (i = 0; i < NUM_CHANNELS; i++) {
        sensor_lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (sensor_lines[i] == NULL) {
            fprintf(stderr, "gpiod_chip_get_line(sensor, BCM %u): %s\n",
                    sensor_pins[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_input(sensor_lines[i], "touch_counter") < 0) {
            fprintf(stderr, "gpiod_line_request_input(sensor, BCM %u): %s\n",
                    sensor_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    /* --- Acquire counter lines (outputs) ------------------------------- */
    for (i = 0; i < NUM_CHANNELS; i++) {
        counter_lines[i] = gpiod_chip_get_line(chip, counter_pins[i]);
        if (counter_lines[i] == NULL) {
            fprintf(stderr, "gpiod_chip_get_line(counter, BCM %u): %s\n",
                    counter_pins[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_output(counter_lines[i], "touch_counter", 0) < 0) {
            fprintf(stderr, "gpiod_line_request_output(counter, BCM %u): %s\n",
                    counter_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    /* --- Stabilize sensor lines ---------------------------------------- */
    printf("Stabilizing sensor lines for %d ms...\n", STABILIZE_MS);
    sleep_ms(STABILIZE_MS);
    printf("Sensor stabilization complete.\n");

    /* --- Main polling loop ---------------------------------------------- */
    while (g_running) {
        int touched = 0;
        int counter = prev_counter;

        for (i = 0; i < NUM_CHANNELS; i++) {
            int val = gpiod_line_get_value(sensor_lines[i]);
            if (val < 0) {
                fprintf(stderr, "gpiod_line_get_value(sensor, BCM %u): %s\n",
                        sensor_pins[i], strerror(errno));
                continue;
            }
            if (val == 1) {
                touched = 1;
                counter = (counter + 1) & 0xFF;
            }
        }

        if (touched) {
            /* Drive counter bits via bulk write (bit 0 on BCM 17, bit 7 on BCM 24) */
            unsigned int bits[NUM_CHANNELS] = {0};
            for (i = 0; i < NUM_CHANNELS; i++) {
                bits[i] |= (counter >> i) & 1;
            }
            if (gpiod_line_set_value_bulk(counter_lines, bits) < 0) {
                fprintf(stderr, "gpiod_line_set_value_bulk: %s\n", strerror(errno));
            }

            log_touch_event(stdout, i, counter);
            printf("Touch on channel %d | Counter: %d\n", i, counter);
        }

        prev_counter = counter;
        sleep_ms(POLL_MS);
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup:
    /* --- Reset outputs to 0 --------------------------------------------- */
    for (i = 0; i < NUM_CHANNELS; i++) {
        if (counter_lines[i] != NULL)
            gpiod_line_set_value(counter_lines[i], 0);
    }

    /* --- Release lines ----------------------------------------------- */
    for (i = 0; i < NUM_CHANNELS; i++) {
        if (sensor_lines[i] != NULL)
            gpiod_line_release(sensor_lines[i]);
        if (counter_lines[i] != NULL)
            gpiod_line_release(counter_lines[i]);
    }

    if (chip != NULL)
        gpiod_chip_close(chip);

    return ret;
}

