#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>

#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 18
#define LOG_FILE "/var/log/tilt_events.log"
#define DEBOUNCE_MS 50
#define POLL_INTERVAL_MS 100

static volatile sig_atomic_t running = 1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(int sensor_number) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (log_fp != NULL) {
        fprintf(log_fp, "%s, Sensor %d tilted\n", timestamp, sensor_number);
        fflush(log_fp);
    } else {
        fprintf(stderr, "Log file not open; event lost: %s, Sensor %d tilted\n", timestamp, sensor_number);
    }
}

static int log_init(void) {
    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    return 0;
}

static int gpio_init(int gpio) {
    int ret;
    struct gpio_request_config config = {
        .consumer = "tilt-monitor",
        .request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT,
        .flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP
    };

    ret = ioctl(gpiod_chip_open_by_number(0), GPIOD_LINE_REQUEST, &config, gpio);
    if (ret < 0) {
        fprintf(stderr, "Failed to request GPIO %d: %s\n", gpio, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_sensor(int gpio) {
    int value;
    int ret;

    ret = ioctl(gpiod_chip_open_by_number(0), GPIOD_LINE_GET_VALUE, gpio);
    if (ret < 0) {
        fprintf(stderr, "Failed to read GPIO %d: %s\n", gpio, strerror(errno));
        return -1;
    }
    value = ret;
    return value;
}

int main(void) {
    int prev1 = 1, prev2 = 1;
    int ret;
    struct timespec ts;
    struct timespec debounce_ts;

    debounce_ts.tv_sec = 0;
    debounce_ts.tv_nsec = DEBOUNCE_MS * 1000000L;

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (log_init() != 0) {
        return 1;
    }

    if (gpio_init(SENSOR1_GPIO) != 0) {
        fclose(log_fp);
        return 1;
    }
    if (gpio_init(SENSOR2_GPIO) != 0) {
        close(log_fp);
        return 1;
    }

    printf("Tilt sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int val1 = read_sensor(SENSOR1_GPIO);
        int val2 = read_sensor(SENSOR2_GPIO);

        if (val1 < 0 || val2 < 0) {
            fprintf(stderr, "Sensor read error; continuing...\n");
            usleep(POLL_INTERVAL_MS * 1000);
            continue;
        }

        if (val1 == 0 && prev1 == 1) {
            log_event(1);
            prev1 = 0;
        }
        if (val2 == 0 && prev2 == 1) {
            log_event(2);
            prev2 = 0;
        }

        prev1 = val1;
        prev2 = val2;

        ts.tv_sec = 0;
        ts.tv_nsec = POLL_INTERVAL_MS * 1000000L;
        nanosleep(&ts, NULL);
    }

    printf("\nShutting down...\n");
    close(log_fp);
    return 0;
}

