/*
 * obstacle_avoid.c — Raspberry Pi 3 Model B+
 *
 * Reads two TCRT5000 IR obstacle sensors (active-low: 0 = obstacle, 1 = clear)
 * on GPIO17 and GPIO27, drives an LED on GPIO22, and logs to obstacle_log.csv.
 *
 * Build:  gcc -O2 -Wall -Wextra -o obstacle_avoid obstacle_avoid.c
 * Run:    sudo ./obstacle_avoid
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>

#include <pigpio.h>

#define SENSOR1_PIN  17
#define SENSOR2_PIN  27
#define LED_PIN      22

#define LOG_FILE     "obstacle_log.csv"
#define POLL_DELAY_US 100000   /* 100 ms */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_sample(int s1, int s2, int led)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    if (t == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }

    if (fprintf(g_log_fp, "%s,%d,%d,%d\n", ts, s1, s2, led) < 0) {
        fprintf(stderr, "fprintf() to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "fflush() failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }

    /* Ensure LED is off before releasing pigpio resources */
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Install signal handlers for graceful shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure sensor pins as inputs --- */
    if (gpioSetMode(SENSOR1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(SENSOR1_PIN) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(SENSOR2_PIN) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Configure LED pin as output and ensure it is off --- */
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(LED_PIN) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "gpioWrite(LED_PIN, 0) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Open log file for appending --- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Cannot open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_fp) == 0) {
        if (fprintf(g_log_fp, "timestamp,sensor1,sensor2,led_state\n") < 0) {
            fprintf(stderr, "Cannot write CSV header: %s\n", strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
        if (fflush(g_log_fp) != 0) {
            fprintf(stderr, "fflush() after header failed: %s\n", strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
    }

    printf("Obstacle avoidance started.  Ctrl+C to exit.\n");

    /* --- Main polling loop --- */
    while (g_running) {
        int s1 = gpioRead(SENSOR1_PIN);
        int s2 = gpioRead(SENSOR2_PIN);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "gpioRead error: sensor1=%d sensor2=%d\n", s1, s2);
            /* Brief pause before retrying to avoid log flooding on bus error */
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        /* Active-low: 0 = obstacle, 1 = clear */
        int obstacle = (s1 == 0 && s2 == 0) ? 1 : 0;

        if (gpioWrite(LED_PIN, obstacle) != 0) {
            fprintf(stderr, "gpioWrite(LED_PIN, %d) failed\n", obstacle);
        }

        if (log_sample(s1, s2, obstacle) != 0) {
            fprintf(stderr, "Logging failed; continuing.\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

