/*
 * Raspberry Pi 4 Model B – TDK InvenSense ICS-40180 analog MEMS microphone
 *
 * Wiring:
 *   ICS-40180 OUT  -> GPIO4  (BCM 4, physical pin 7)
 *   LED anode     -> GPIO17 (BCM 17, physical pin 11) via 330 Ω resistor
 *   LED cathode   -> GND
 *
 * The ICS-40180 outputs a voltage proportional to sound pressure level.
 * We sample the pin as a digital input at ~8 kHz and treat a HIGH
 * reading as a sound-peak event.  For each peak we turn the LED on
 * for 100 ms and then turn it off.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o mic_peak mic_peak.c -lpigpio -lrt
 * Run:
 *   sudo ./mic_peak
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define MIC_PIN      4          /* BCM 4 – analog output of ICS-40180 */
#define LED_PIN      17         /* BCM 17 – LED current-limiting resistor */
#define SAMPLE_US    125        /* 8 kHz sampling period (µs) */
#define LED_ON_US    100000     /* 100 ms LED on-time (µs) */
#define POLL_TIMEOUT_MS 1000

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler – only set flag; never call library functions here.  */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Return monotonic milliseconds since program start.                 */
/* ------------------------------------------------------------------ */
static uint64_t monotonic_ms(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        return 0;
    }
    return (uint64_t)ts.tv_sec * 1000ULL + (uint64_t)ts.tv_nsec / 1000000ULL;
}

/* ------------------------------------------------------------------ */
/* Read the digital state of MIC_PIN with a timeout.                   */
/* Returns 0 or 1 on success, -1 on timeout, -2 on read error.         */
/* ------------------------------------------------------------------ */
static int read_mic_with_timeout(uint64_t deadline_ms)
{
    int level = gpioRead(MIC_PIN);
    if (level < 0) {
        return -2;
    }
    if (level == 1) {
        return 1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Turn the LED on for LED_ON_US µs, then turn it off.                 */
/* ------------------------------------------------------------------ */
static void trigger_led(void)
{
    if (gpioWrite(LED_PIN, 1) != 0) {
        fprintf(stderr, "Warning: failed to turn LED on\n");
    }
    gpioDelay(LED_ON_US);
    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Warning: failed to turn LED off\n");
    }
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Install SIGINT handler ---- */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (code %d).\n",
                gpioInitialise());
        return EXIT_FAILURE;
    }

    /* ---- Configure pins ---- */
    if (gpioSetMode(MIC_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set MIC_PIN %d as input.\n",
                MIC_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set LED_PIN %d as output.\n",
                LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Start with LED off */
    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize LED_PIN %d to 0.\n",
                LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Sampling ICS-40180 on GPIO%d at ~8 kHz.  Press Ctrl+C to exit.\n",
           MIC_PIN);
    fflush(stdout);

    uint64_t last_peak_ms = 0;
    uint64_t next_sample  = monotonic_ms();

    /* ---- Main sampling loop ---- */
    while (g_running) {
        uint64_t now = monotonic_ms();
        if (now < next_sample) {
            /* Sleep until the next scheduled sample time */
            uint64_t sleep_us = (uint64_t)(next_sample - now);
            if (sleep_us > 0) {
                gpioDelay((unsigned)sleep_us);
            }
            continue;
        }

        /* Read MIC_PIN with a timeout so we can re-schedule */
        int level = read_mic_with_timeout(now + POLL_TIMEOUT_MS);
        if (level < 0) {
            if (level == -2) {
                fprintf(stderr, "Error: gpioRead failed on MIC_PIN %d.\n",
                        MIC_PIN);
            }
            break;
        }

        if (level == 1) {
            uint64_t peak_ms = now;
            if (peak_ms > last_peak_ms) {
                printf("Sound peak detected at %llu ms\n", (unsigned long long)peak_ms);
                fflush(stdout);
                last_peak_ms = peak_ms;
                trigger_led();
            }
        }

        /* Schedule next sample */
        next_sample = now + SAMPLE_US;
    }

    /* ---- Clean shutdown ---- */
    printf("\nShutting down...\n");
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

