/*
 * SunFounder 3-Way Tracing Sensor reader for Raspberry Pi 4 Model B
 *
 * Wiring (BCM numbering):
 *   Left  sensor  -> GPIO17 (physical pin 11)
 *   Center sensor -> GPIO27 (physical pin 13)
 *   Right sensor  -> GPIO22 (physical pin 15)
 *   VCC          -> 3.3 V (physical pin 1)
 *   GND          -> GND  (physical pin 9)
 *
 * Each sensor pin is configured as an active-low input with an internal
 * pull-up resistor enabled.  The sensor output is active-low: it reads
 * 0 when the object is detected (reflectance strong) and 1 when the
 * object is absent (reflectance weak).
 *
 * Build:  gcc -O2 -Wall -Wextra -o tracing_sensor tracing_sensor.c -lpigpio -lrt
 * Run:    sudo ./tracing_sensor
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <pigpio.h>

#define LEFT_SENSOR_PIN  17
#define CENTER_SENSOR_PIN 27
#define RIGHT_SENSOR_PIN  22

#define POLL_INTERVAL_US  100000   /* 100 ms */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* GPIO setup                                                          */
/* ------------------------------------------------------------------ */
static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n",
                gpioInitialise());
        return -1;
    }

    /* Configure each sensor pin as input with internal pull-up. */
    if (gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n",
                LEFT_SENSOR_PIN);
        return -1;
    }
    if (gpioSetMode(CENTER_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n",
                CENTER_SENSOR_PIN);
        return -1;
    }
    if (gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n",
                RIGHT_SENSOR_PIN);
        return -1;
    }

    /* Enable internal pull-up resistors so the pins read HIGH when
     * the sensor output is HIGH (object absent). */
    if (gpioSetPullUpDown(LEFT_SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d.\n",
                LEFT_SENSOR_PIN);
        return -1;
    }
    if (gpioSetPullUpDown(CENTER_SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d.\n",
                CENTER_SENSOR_PIN);
        return -1;
    }
    if (gpioSetPullUpDown(RIGHT_SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d.\n",
                RIGHT_SENSOR_PIN);
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor reading                                                      */
/* ------------------------------------------------------------------ */
static int read_sensor(int pin)
{
    int value = gpioRead(pin);
    if (value < 0) {
        fprintf(stderr, "Error: gpioRead failed on GPIO%d (code %d).\n",
                pin, value);
        return -1;
    }
    return value;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("3-Way Tracing Sensor reader started.\n");
    printf("  Left  sensor : GPIO%d\n", LEFT_SENSOR_PIN);
    printf("  Center sensor: GPIO%d\n", CENTER_SENSOR_PIN);
    printf("  Right sensor : GPIO%d\n", RIGHT_SENSOR_PIN);
    printf("  Poll interval: %d ms\n", POLL_INTERVAL_US / 1000);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (g_running) {
        int left  = read_sensor(LEFT_SENSOR_PIN);
        int center = read_sensor(CENTER_SENSOR_PIN);
        int right  = read_sensor(RIGHT_SENSOR_PIN);

        if (left < 0 || center < 0 || right < 0) {
            fprintf(stderr, "Warning: sensor read error, continuing.\n");
        } else {
            printf("Left: %d  Center: %d  Right: %d\n", left, center, right);
            fflush(stdout);
        }

        /* Sleep 100 ms in 10 ms slices so signals are caught promptly. */
        for (int i = 0; i < 10 && g_running; i++) {
            gpioDelay(10000); /* 10 ms */
        }
    }

    /* Clean resource release on all exit paths. */
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

