/*
 * Si1175 ALS Reader for Raspberry Pi 4 Model B
 * I2C bus 1, fixed 100 ms sampling interval.
 *
 * Build:  gcc -O2 -Wall -Wextra -o si1175_reader si1175_reader.c
 * Run:    sudo ./si1175_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- Si1175 register definitions (per datasheet) ---- */
#define SI1175_I2C_ADDR        0x49
#define SI1175_REG_PART_ID     0x00
#define SI1175_REG_HW_KEY      0x07
#define SI1175_REG_ALS_VIS_DATA0 0x22
#define SI1175_REG_ALS_VIS_DATA1 0x23

#define SI1175_PART_ID_EXPECTED 0x82

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s (wrote %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    n = read(fd, out, 1);
    if (n != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t lo, hi;
    if (i2c_read_reg8(fd, reg, &lo) < 0)
        return -1;
    if (i2c_read_reg8(fd, reg + 1, &hi) < 0)
        return -1;
    *out = (uint16_t)((hi << 8) | lo);
    return 0;
}

/* ------------------------------------------------------------------ */
static int si1175_init(int fd)
{
    uint8_t part_id = 0;

    /* Verify sensor presence */
    if (i2c_read_reg8(fd, SI1175_REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "Cannot read PART_ID — sensor may be absent or bus error.\n");
        return -1;
    }
    if (part_id != SI1175_PART_ID_EXPECTED) {
        fprintf(stderr, "Unexpected PART_ID 0x%02X (expected 0x%02X). "
                        "Wrong sensor or wiring issue.\n",
                part_id, SI1175_PART_ID_EXPECTED);
        return -1;
    }
    printf("Si1175 detected (PART_ID = 0x%02X).\n", part_id);

    /* Write HW_KEY to enable ALS-visible channel */
    if (i2c_write_reg8(fd, SI1175_REG_HW_KEY, 0x00) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
static int si1175_read_als_vis(int fd, uint16_t *als_vis)
{
    return i2c_read_reg16(fd, SI1175_REG_ALS_VIS_DATA0, als_vis);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Signal handling for clean shutdown ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus 1 ---- */
    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Acquire Si1175 slave address ---- */
    if (ioctl(g_i2c_fd, I2C_SLAVE, SI1175_I2C_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                SI1175_I2C_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* ---- Initialize sensor ---- */
    if (si1175_init(g_i2c_fd) < 0) {
        fprintf(stderr, "Si1175 initialization failed.\n");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    printf("Si1175 ALS reader started. Press Ctrl+C to exit.\n");

    /* ---- Main sampling loop ---- */
    while (g_running) {
        uint16_t als_vis = 0;
        if (si1175_read_als_vis(g_i2c_fd, &als_vis) < 0) {
            fprintf(stderr, "ALS read error — continuing.\n");
        } else {
            printf("ALS_VIS: %u\n", als_vis);
        }
        usleep(100 * 1000); /* 100 ms */
    }

    /* ---- Clean shutdown ---- */
    printf("\nShutting down...\n");
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return EXIT_SUCCESS;
}

