/*
 * Raspberry Pi 3 Model B+ — 3-Way Tracking Sensor (IR reflectance) reader.
 *
 * Wiring (BCM numbering):
 *   GPIO2  -> sensor left  digital output
 *   GPIO3  -> sensor middle digital output
 *   GPIO4  -> sensor right  digital output
 *
 * Each sensor line is read via a separate ioctl call to the kernel
 * GPIO character device (/dev/gpiochip0/gpio2, /dev/gpiochip0/gpio3,
 * /dev/gpiochip0/gpio4).  The program checks every step of the
 * driver call sequence and reports errors with the exact sequence of
 * failures that occurred.
 *
 * Build:  gcc -O2 -Wall -Wextra -o sensor_reader sensor_reader.c
 */

#include <errno.h>
#include <fcntl.h>
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

#include <linux/gpio.h>
#include <sys/ioctl.h>

#define NUM_SENSORS   3
#define POLL_MS       100

static const unsigned int sensor_pins[NUM_SENSORS] = { 2, 3, 4 };

static volatile sig_atomic_t g_stop = 0;

static void sigint_handler(int signo)
{
    (void)signo;
    g_stop = 1;
}

static void install_sigint_handler(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1)
        perror("warning: sigaction(SIGINT) failed");
}

/*
 * Read a single GPIO line using a kernel GPIO character-device ioctl.
 * Returns 0 on success and stores the value in *out; returns -1 on
 * any error.  The error message is printed to stderr.
 */
static int read_gpio_line(int fd, unsigned int pin, int *out)
{
    if (fd < 0 || out == NULL) {
        fprintf(stderr, "read_gpio_line: invalid argument\n");
        return -1;
    }

    if (ioctl(fd, GPIO_GET_LINE, &pin) < 0) {
        fprintf(stderr, "read_gpio_line: GPIO_GET_LINE(pin=%u) failed: %s\n",
                pin, strerror(errno));
        return -1;
    }

    if (ioctl(fd, GPIO_GET_VALUE, out) < 0) {
        fprintf(stderr, "read_gpio_line: GPIO_GET_VALUE(pin=%u) failed: %s\n",
                pin, strerror(errno));
        return -1;
    }

    return 0;
}

static int open_and_check_sensor(unsigned int pin)
{
    char path[32];
    snprintf(path, sizeof(path), "/dev/gpiochip0/gpio%d", pin);

    int fd = open(path, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "open_sensor(%u): %s\n", pin, strerror(errno));
        return -1;
    }

    int val = -1;
    if (read_gpio_line(fd, pin, &val) < 0) {
        fprintf(stderr, "open_sensor(%u): read failed\n", pin);
        close(fd);
        return -1;
    }

    if (close(fd) < 0) {
        fprintf(stderr, "open_sensor(%u): close failed: %s\n",
                pin, strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    install_sigint_handler();

    printf("Polling 3-Way Tracking Sensor (IR reflectance) every %d ms.\n",
           POLL_MS);
    printf("Press Ctrl-C to exit.\n");
    fflush(stdout);

    while (!g_stop) {
        int left  = -1, middle = -1, right = -1;
        int any_err = 0;

        for (int i = 0; i < NUM_SENSORS; i++) {
            unsigned int pin = sensor_pins[i];

            if (open_and_check_sensor(pin) < 0) {
                any_err = 1;
                continue;
            }

            if (g_stop) {
                fprintf(stderr, "Interrupted by signal.\n");
                break;
            }

            if (i == 0) {
                left  = (int)val;
            } else if (i == 1) {
                middle = (int)val;
            } else {
                right = (int)val;
            }
        }

        if (g_stop) {
            break;
        }

        if (any_err) {
            fprintf(stderr, "Sensor read failed; continuing.\n");
            continue;
        }

        printf("L:%d M:%d R:%d\n", left, middle, right);
        fflush(stdout);

        struct timespec ts = { 0, POLL_MS * 1000000L };
        nanosleep(&ts, NULL);
    }

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

