 * Read all 8 channels in one batch so the sensor is held idle for a short
 * time and the read is atomic with respect to the touch sensor's internal
 * state.
 */
static int read_touch_sensor(struct gpiod_line_request *request,
                              int *values[NUM_CHANNELS])
{
    int ret = 0;

    for (int i = 0; i < NUM_CHANNELS; i++) {
        int v = gpiod_line_request_get_value(request, gpio_pins[i]);
        if (v < 0) {
            fprintf(stderr, "gpiod_line_request_get_value failed on GPIO%d: %s\n",
                    gpio_pins[i], strerror(errno));
            ret = -1;
        }
        values[i] = v;
    }
    return ret;
}

static void format_output(const int values[NUM_CHANNELS],
                          char *out, size_t out_len)
{
    int idx = 0;
    for (int i = 0; i < NUM_CHANNELS; i++) {
        int v = values[i];
        if (v < 0)
            snprintf(out + idx, out_len - (size_t)idx, " CH%d=%d", i + 1, v);
        else
            snprintf(out + idx, out_len - (size_t)idx, " CH%d=%d", i + 1, v);
        idx += strlen(" CH%d=%d", i + 1, v + 1);
    }
    out[out_len - 1] = '\0';
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_request *request = NULL;
    int values[NUM_CHANNELS];
    char output[128];
    struct timespec ts;
    struct timespec deadline;

    install_signal_handlers();

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    request = gpiod_chip_request_lines(chip, NULL, gpio_pins, NUM_CHANNELS);
    if (!request) {
        fprintf(stderr, "Failed to request GPIO lines: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

