        format_output(values, output, sizeof(output));

        printf("[%ld.%03ld] %s\n",
               (long)ts.tv_sec, ts.tv_nsec / 1000000L, output);
        fflush(stdout);

        sleep_ms(200);
    }

    if (request)
        gpiod_line_request_release(request);
    if (chip)
        gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

