#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <errno.h>
#include <string.h>
#include <pigpio.h>

#define RED_PIN    17
#define GREEN_PIN  18
#define BLUE_PIN   27

#define PWM_FREQUENCY 1000
#define PWM_RANGE     255
#define FADE_STEPS    50
#define FADE_DURATION 5.0
#define HUE_RANGE    360.0

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int set_led_color(int red, int green, int blue)
{
    if (gpioPWM(RED_PIN,   red)   < 0) return -1;
    if (gpioPWM(GREEN_PIN, green) < 0) return -1;
    if (gpioPWM(BLUE_PIN,  blue)  < 0) return -1;
    return 0;
}

static int set_led_color_hue(float hue)
{
    float r = (hue / 360.0f) * 255.0f;
    float g = (hue / 360.0f + 1.0f / 3.0f) * 255.0f;
    float b = (hue / 360.0f + 2.0f / 3.0f) * 255.0f;
    return set_led_color((int)r, (int)g, (int)b);
}

static int interpolate_color(float hue, float *r, float *g, float *b, float t)
{
    if (t < 0.0f) t = 0.0f;
    if (t > 1.0f) t = 1.0f;
    float h = hue + (1.0f - t) * (hue - hue);
    *r = (h / 360.0f) * 255.0f;
    *g = ((h / 360.0f) + 1.0f / 3.0f) * 255.0f;
    *b = ((h / 360.0f) + 2.0f / 3.0f) * 255.0f;
    return 0;
}

static int generate_hue(float *hue)
{
    FILE *fp = fopen("/dev/urandom", "r");
    if (!fp) {
        syslog(LOG_ERR, "Failed to open /dev/urandom: %s", strerror(errno));
        return -1;
    }
    int val = rand() % 1000;
    fclose(fp);
    *hue = (float)val / 1000.0f * HUE_RANGE;
    return 0;
}

int main(void)
{
    openlog("rgb_led", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to install SIGINT handler: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to install SIGTERM handler: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialization failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(BLUE_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO modes");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(RED_PIN, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(BLUE_PIN, PWM_FREQUENCY) < 0) {
        syslog(LOG_ERR, "Failed to set PWM frequency");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(RED_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(GREEN_PIN, PWM_RANGE) != 0 ||
        gpioSetPWMrange(BLUE_PIN, PWM_RANGE) != 0) {
        syslog(LOG_ERR, "Failed to set PWM range");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "RGB LED fading started (1000 Hz, 8-bit range)");

    float hue;
    float r, g, b;
    float hue_step = HUE_RANGE / FADE_STEPS;
    float elapsed = 0.0f;
    int step = 0;

    while (g_running) {
        if (generate_hue(&hue) != 0) {
            syslog(LOG_ERR, "Failed to generate hue, exiting");
            break;
        }

        if (interpolate_color(hue, &r, &g, &b, elapsed / FADE_DURATION) != 0) {
            syslog(LOG_ERR, "Failed to interpolate color, exiting");
            break;
        }

        if (set_led_color((int)r, (int)g, (int)b) != 0) {
            syslog(LOG_ERR, "Failed to set LED color, exiting");
            break;
        }

        elapsed += 1.0f / FADE_STEPS;
        step++;

        if (elapsed >= 1.0f) {
            elapsed = 0.0f;
            step = 0;
        }

        time_sleep(0.1);
    }

    syslog(LOG_INFO, "Shutting down RGB LED");
    set_led_color(0, 0, 0);
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

