/*
 * TCS34725 Color Sensor Reader with GPIO LED Threshold Indicator
 * Board:  Raspberry Pi 4 Model B
 * Bus:    /dev/i2c-1 (BCM pins 2 = SDA, 3 = SCL)
 * Sensor: TCS34725 (A0=A1=A2=0, PON=0x01, AEN=0x02, ATIME=0x80, R=0x01, G=0x02, B=0x04, C=0x05)
 * LED:    GPIO 17 (BCM)
 *
 * Build:  gcc -O2 -Wall -o tcs34725 tcs34725.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#include <pigpio.h>

/* ---- TCS34725 constants ---- */
#define TCS34725_I2C_ADDR      0x29
#define TCS34725_COMMAND_BIT   0x80

#define TCS34725_ENABLE        0x00
#define TCS34725_ATIME         0x01
#define TCS34725_ID            0x12
#define TCS34725_STATUS        0x13
#define TCS34725_CDATAL        0x14
#define TCS34725_CDATAH        0x15
#define TCS34725_RDATAL        0x16
#define TCS34725_RDATAH        0x17
#define TCS34725_GDATAL        0x18
#define TCS34725_GDATAH        0x19
#define TCS34725_BDATAL        0x1A
#define TCS34725_BDATAH        0x1B

#define TCS34725_ENABLE_PON    0x01
#define TCS34725_ENABLE_AEN    0x02

#define TCS34725_ATIME_154MS   0x80  /* 0.154 ms × (256 − 0x80) = 154 ms */

#define TCS34725_ID_VALUE      0x44

/* ---- GPIO / pin constants ---- */
#define LED_GPIO               17

/* ---- Threshold / timing ---- */
#define RED_THRESHOLD          200
#define I2C_BUS               "/dev/i2c-1"
#define POLL_INTERVAL_US      200000  /* 200 ms */
#define MAX_RETRIES            3

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static int  g_led_pin = LED_GPIO;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to a TCS34725 register.                               */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int tcs_write_reg(uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { (uint8_t)(TCS34725_COMMAND_BIT | reg), value };

    if (write(g_i2c_fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from a TCS34725 register.                             */
/* Returns 0 on success (value stored in *out), -1 on error.           */
/* ------------------------------------------------------------------ */
static int tcs_read_reg(uint8_t reg, uint8_t *out)
{
    uint8_t cmd = (uint8_t)(TCS34725_COMMAND_BIT | reg);

    if (write(g_i2c_fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (read(g_i2c_fd, out, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the TCS34725 sensor.                                    */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int tcs34725_init(void)
{
    uint8_t id = 0;

    /* Probe: read ID register */
    if (tcs_read_reg(TCS34725_ID, &id) != 0)
        return -1;

    if (id != TCS34725_ID_VALUE) {
        fprintf(stderr, "Unexpected TCS34725 ID: 0x%02X (expected 0x%02X)\n",
                id, TCS34725_ID_VALUE);
        return -1;
    }

    /* Power on */
    if (tcs_write_reg(TCS34725_ENABLE, TCS34725_ENABLE_PON) != 0)
        return -1;
    usleep(3000);  /* allow PON to settle */

    /* Enable RGBC */
    if (tcs_write_reg(TCS34725_ENABLE, TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN) != 0)
        return -1;

    /* Set integration time to ~154 ms */
    if (tcs_write_reg(TCS34725_ATIME, TCS34725_ATIME_154MS) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read 8 bytes of RGBC data and convert to 16-bit values.            */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int tcs34725_read_rgbc(uint16_t *r, uint16_t *g, uint16_t *b, uint16_t *c)
{
    uint8_t data[8];

    if (tcs_read_reg(TCS34725_CDATAL, &data[0]) != 0) return -1;
    if (tcs_read_reg(TCS34725_CDATAH, &data[1]) != 0) return -1;
    if (tcs_read_reg(TCS34725_RDATAL, &data[2]) != 0) return -1;
    if (tcs_read_reg(TCS34725_RDATAH, &data[3]) != 0) return -1;
    if (tcs_read_reg(TCS34725_GDATAL, &data[4]) != 0) return -1;
    if (tcs_read_reg(TCS34725_GDATAH, &data[5]) != 0) return -1;
    if (tcs_read_reg(TCS34725_BDATAL, &data[6]) != 0) return -1;
    if (tcs_read_reg(TCS34725_BDATAH, &data[7]) != 0) return -1;

    *c = (uint16_t)((data[1] << 8) | data[0]);
    *r = (uint16_t)((data[3] << 8) | data[2]);
    *g = (uint16_t)((data[5] << 8) | data[4]);
    *b = (uint16_t)((data[7] << 8) | data[6]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Calibrate RGBC values (subtract dark / ambient baseline).          */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int tcs34725_calibrate(uint16_t *r, uint16_t *g, uint16_t *b, uint16_t *c,
                              uint16_t *rd, uint16_t *gd, uint16_t *bd,
                              uint16_t *cd)
{
    if (tcs34725_read_rgbc(r, g, b, c) != 0)
        return -1;

    if (tcs34725_read_rgbc(rd, gd, bd, cd) != 0)
        return -1;

    *r -= *rd;
    *g -= *gd;
    *b -= *bd;
    *c -= *cd;

    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        /* Power down sensor */
        (void)tcs_write_reg(TCS34725_ENABLE, 0x00);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_led_pin >= 0) {
        gpioWrite(g_led_pin, 0);
        gpioSetMode(g_led_pin, PI_INPUT);
        g_led_pin = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    uint16_t r, g, b, c, rd, gd, bd, cd;

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure LED GPIO ---- */
    if (gpioSetMode(g_led_pin, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", g_led_pin);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(g_led_pin, 0);

    /* ---- Open I2C bus ---- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, TCS34725_I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                TCS34725_I2C_ADDR, strerror(errno));
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Initialize sensor ---- */
    if (tcs34725_init() != 0) {
        fprintf(stderr, "TCS34725 initialization failed\n");
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("TCS34725 initialized. Polling every %d ms. Press Ctrl+C to exit.\n",
           POLL_INTERVAL_US / 1000);

    /* ---- Main loop ---- */
    while (g_running) {
        if (tcs34725_calibrate(&r, &g, &b, &c, &rd, &gd, &bd, &cd) != 0) {
            fprintf(stderr, "Calibration failed; re-initializing sensor...\n");
            close(g_i2c_fd);
            g_i2c_fd = -1;
            usleep(100000);
            g_i2c_fd = open(I2C_BUS, O_RDWR);
            if (g_i2c_fd < 0) {
                fprintf(stderr, "Failed to reopen I2C bus: %s\n", strerror(errno));
                break;
            }
            if (ioctl(g_i2c_fd, I2C_SLAVE, TCS34725_I2C_ADDR) < 0) {
                fprintf(stderr, "Failed to set I2C slave address: %s\n",
                        strerror(errno));
                break;
            }
            if (tcs34725_init() != 0) {
                fprintf(stderr, "Re-initialization failed\n");
                break;
            }
            continue;
        }

        bool led_on = (r > RED_THRESHOLD);

        if (gpioWrite(g_led_pin, led_on ? 1 : 0) != 0) {
            fprintf(stderr, "Failed to write LED GPIO %d\n", g_led_pin);
        }

        printf("R: %5u  G: %5u  B: %5u  C: %5u  |  LED: %s\n",
               r, g, b, c, led_on ? "ON" : "OFF");

        usleep(POLL_INTERVAL_US);
    }

    /* ---- Graceful cleanup ---- */
