/*
 * Raspberry Pi 4 Model B – BH1750 ambient-light sensor → WS2812B LED brightness
 *
 * Wiring:
 *   BH1750 SDA  → GPIO2  (I2C bus 1)
 *   BH1750 SCL  → GPIO3  (I2C bus 1)
 *   BH1750 VCC  → 3.3 V
 *   BH1750 GND  → GND
 *   WS2812B DIN → GPIO18 (BCM 18, hardware PWM0)
 *   WS2812B VCC → 5 V
 *   WS2812B GND → GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o light_led light_led.c
 *
 * Run:
 *   sudo ./light_led   (or ensure user is in the 'gpio' group)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS          "/dev/i2c-1"
#define BH1750_ADDR      0x5C          /* ADDR pin low */
#define BH1750_CONV_MS   180           /* conversion time after command   */

#define LED_GPIO         18            /* BCM 18 – hardware PWM0 */
#define NUM_LEDS         10
#define WS2812_BITSB    24            /* WS2812B: 24 bits per LED */

#define LOG_MIN          0.1f          /* log base 10 */
#define LOG_MAX          1000.0f       /* lux range */
#define MAX_LUX          10000.0f      /* clamp above this */

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* --------------------------- Signal handling ----------------------------- */
static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) != 0)
        perror("sigaction(SIGTERM)");
}

/* --------------------------- I2C helpers --------------------------------- */
static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n", addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

/*
 * Issue a measurement command to the BH1750 and wait for the conversion
 * to complete.  Returns 0 on success, -1 on error.
 */
static int bh1750_read(int fd, float *lux_out)
{
    uint8_t cmd = 0x10;  /* continuous high-resolution mode */

    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "BH1750 write command failed: %s\n", strerror(errno));
        return -1;
    }

    /* Poll every 5 ms until the LED is on or the sensor times out */
    for (int i = 0; i < BH1750_CONV_MS / 5; i++) {
        uint8_t buf[2];
        ssize_t n = read(fd, buf, sizeof(buf));
        if (n == 2) {
            uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
            *lux_out = (float)raw / 1.2f;
            return 0;
        }
        if (n < 0) {
            fprintf(stderr, "BH1750 read error: %s\n", strerror(errno));
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "BH1750: no data yet (got %d bytes)\n", n);
            usleep(5000);
            continue;
        }
        /* n > 0 but < 2: partial read – discard and retry */
        fprintf(stderr, "BH1750: partial read (%zd bytes)\n", n);
        usleep(5000);
        continue;
    }

    fprintf(stderr, "BH1750 conversion timeout after %d ms\n", BH1750_CONV_MS);
    return -1;
}

/* --------------------------- WS2812B helpers ----------------------------- */
/*
 * Generate a single WS2812B bit frame for one LED.
 * pigpio hardware PWM on GPIO18 supports up to ~1.5 MHz carrier frequency
 * (WS2812B datasheet: 400–800 kHz).  We use a 1.0 MHz carrier and
 * 16-bit resolution for precision.
 */
static void ws2812_send_bit(int level)
{
    /* 1.0 MHz carrier → 1 us high, 1 us low = 1 bit */
    if (gpioHardwarePWM(LED_GPIO, 1000000, level ? 1000 : 0) < 0) {
        fprintf(stderr, "gpioHardwarePWM failed\n");
        return;
    }
    usleep(1);
}

static void ws2812_send_byte(uint8_t byte)
{
    for (int i = 0; i < 8; i++) {
        ws2812_send_bit(byte & 0x01);
        byte >>= 1;
    }
}

static void ws2812_send_led(uint32_t color)
{
    /* WS2812B expects 24 bits per LED, MSB first */
    for (int b = 23; b >= 0; b--) {
        ws2812_send_bit((color >> b) & 0x01);
    }
}

static void ws2812_clear(void)
{
    for (int i = 0; i < NUM_LEDS; i++) {
        uint32_t c = (uint32_t)(1 << 24);  /* white */
        ws2812_send_led(c);
    }
}

static void ws2812_update(void)
{
    ws2812_clear();
    for (int i = 0; i < NUM_LEDS; i++) {
        uint32_t c = (uint32_t)(1 << 24);  /* white */
        ws2812_send_led(c);
    }
}

/* ------------------------------- Main ------------------------------------ */
int main(void)
{
    install_signal_handlers();

    /* --- pigpio init ---------------------------------------------------- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- I2C init ------------------------------------------------------- */
    g_i2c_fd = i2c_open(I2C_BUS, BH1750_ADDR);
    if (g_i2c_fd < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- WS2812B setup ------------------------------------------------- */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d) failed\n", LED_GPIO);
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Start with LEDs off */
    ws2812_clear();

    /* --- Main loop ------------------------------------------------------ */
    while (g_running) {
        float lux = 0.0f;

        if (bh1750_read(g_i2c_fd, &lux) != 0) {
            fprintf(stderr, "BH1750 read failed; retrying in 1 s...\n");
            sleep(1);
            continue;
        }

        if (lux > MAX_LUX) {
            lux = MAX_LUX;
        }

        float log_val = log10f(lux);
        if (log_val < LOG_MIN) log_val = LOG_MIN;
        if (log_val > LOG_MAX) log_val = LOG_MAX;

        float brightness = (log_val - LOG_MIN) /
                           (LOG_MAX - LOG_MIN) * (1.0f - LOG_MIN) + LOG_MIN;

        uint32_t color = (uint32_t)(brightness * 255.0f);
        color = (color << 24) | (color << 16) | (color << 8) | color;

        ws2812_send_led(color);

        usleep(50000);  /* 50 ms loop cadence */
    }

