/*
 * Raspberry Pi 4 Model B – BH1750 ambient-light sensor → WS2812B LED brightness
 *
 * Wiring:
 *   BH1750 SDA  → GPIO2  (I2C bus 1)
 *   BH1750 SCL  → GPIO3  (I2C bus 1)
 *   BH1750 VCC  → 3.3 V
 *   BH1750 GND  → GND
 *   WS2812B DIN → GPIO18 (BCM 18, hardware PWM0)
 *   WS2812B VCC → 5 V
 *   WS2812B GND → GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o light_led light_led.c
 *
 * Run:
 *   sudo ./light_led   (or ensure user is in the 'gpio' group)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS          "/dev/i2c-1"
#define BH1750_ADDR      0x5C          /* ADDR pin low */
#define BH1750_CONV_MS   180           /* conversion time after command   */

#define LED_GPIO         18            /* BCM 18 – hardware PWM0 */
#define NUM_LEDS         10
#define WS2812_BITSB    24            /* WS2812B: 24 bits per LED */

#define LOG_MIN          0.1f          /* log base 10 */
#define LOG_MAX          1000.0f       /* lux range */
#define MAX_LUX          10000.0f      /* clamp above this */

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* --------------------------- Signal handling ----------------------------- */
static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) != 0)
        perror("sigaction(SIGTERM)");
}

/* --------------------------- I2C helpers --------------------------------- */
static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n", addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

/*
 * Issue a measurement command to the BH1750 and wait for the conversion
 * to complete.  Returns 0 on success, -1 on error.
 */
static int bh1750_read(int fd, float *lux_out)
{
    uint8_t cmd = 0x10;  /* continuous high-resolution mode */

    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "BH1750 write command failed: %s\n", strerror(errno));
        return -1;
    }

    /* Poll every 5 ms until the LED is on or the sensor times out */
    for (int i = 0; i < BH1750_CONV_MS / 5; i++) {
        uint8_t buf[2];
        ssize_t n = read(fd, buf, sizeof(buf));
        if (n == 2) {
            uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
            *lux_out = (float)raw / 1.2f;
            return 0;
        }
        if (n < 0) {
            fprintf(stderr, "BH1750 read error: %s\n", strerror(errno));
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "BH1750: no data yet (got %d bytes)\n", n);
            usleep(5000);
            continue;
        }
        /* n > 0 but < 2: partial read – discard and retry */
        fprintf(stderr, "BH1750: partial read (%zd bytes)\n", n);
        usleep(5000);
        continue;
    }

    fprintf(stderr, "BH1750 conversion timeout after %d ms\n", BH1750_CONV_MS);
    return -1;
}

/* --------------------------- WS2812B helpers ----------------------------- */
/*
 * Generate a single WS2812B bit frame for one LED.
 * pigpio hardware PWM on GPIO18 supports up to ~1.5 MHz carrier frequency
 * (WS2812B datasheet: 400–800 kHz).  We use a 1.0 MHz carrier and
 * 16-bit resolution for precision.
 */
static void ws2812_send_bit(int level)
{
    /* 1.0 MHz carrier → 1 us high, 1 us low = 1 bit */
    if (gpioHardwarePWM(LED_GPIO, 1000000, level ? 1000 : 0) < 0) {
        fprintf(stderr, "gpioHardwarePWM failed\n");
        return;
    }
    usleep(1);
}

static void ws2812_send_byte(uint8_t byte)
{
    for (int i = 0; i < 8; i++) {
        ws2812_send_bit(byte & 0x01);
        byte >>= 1;
    }
}

static void ws2812_send_led(uint32_t color)
{
    /* WS2812B expects 24 bits per LED, MSB first */
    for (int b = 23; b >= 0; b--) {
        ws2812_send_bit((color >> b) & 0x01);
    }
}

static void ws2812_clear(void)
{
    for (int i = 0; i < NUM_LEDS; i++) {
        uint32_t c = (uint32_t)(1 << 24);  /* white */
        ws2812_send_led(c);
    }
}

static void ws2812_update(void)
{
    ws2812_clear();
    for (int i = 0; i < NUM_LEDS; i++) {
        uint32_t c = (uint32_t)(1 << 24);  /* white */
        ws2812_send_led(c);
    }
}

/* ------------------------------- Main ------------------------------------ */
int main(void)
{
    install_signal_handlers();

    /* --- pigpio init ---------------------------------------------------- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- I2C init ------------------------------------------------------- */
    g_i2c_fd = i2c_open(I2C_BUS, BH1750_ADDR);
    if (g_i2c_fd < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- WS2812B setup ------------------------------------------------- */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d) failed\n", LED_GPIO);
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Start with LEDs off */
    ws2812_clear();

    /* --- Main loop ------------------------------------------------------ */
    while (g_running) {
        float lux = 0.0f;

        if (bh1750_read(g_i2c_fd, &lux) != 0) {
            fprintf(stderr, "BH1750 read failed; retrying in 1 s...\n");
            sleep(1);
            continue;
        }

        if (lux > MAX_LUX) {
            lux = MAX_LUX;
        }

        float log_val = log10f(lux);
        if (log_val < LOG_MIN) log_val = LOG_MIN;
        if (log_val > LOG_MAX) log_val = LOG_MAX;

        float brightness = (log_val - LOG_MIN) /
                           (LOG_MAX - LOG_MIN) * (1.0f - LOG_MIN) + LOG_MIN;

        uint32_t color = (uint32_t)(brightness * 255.0f);
        color = (color << 24) | (color << 16) | (color << 8) | color;

        ws2812_send_led(color);

        usleep(50000);  /* 50 ms loop cadence */
    }

    /* --- Cleanup -------------------------------------------------------- */
    ws2812_clear();
    close(g_i2c_fd);
    gpioTerminate();

    return EXIT_SUCCESS;
}

code:
/*
 * Raspberry Pi Zero W – BH1750 ambient light sensor → APA102 LED brightness control
 *
 * Hardware:
 *   BH1750  I2C  → /dev/i2c-1  (SDA = GPIO2, SCL = GPIO3)
 *   APA102   SPI  → /dev/spidev0.0 (MOSI = GPIO10, MISO = GPIO9, SCLK = GPIO11)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o light_led light_led.c -lm
 *
 * Run:
 *   ./light_led
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <math.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/spi/spidev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SPI_BUS        "/dev/spidev0.0"
#define SPI_SPEED_HZ   1000000U   /* 1 MHz */
#define SPI_BITS        8
#define SPI_DELAY_US    0

#define BH1750_ADDR     0x10
#define BH1750_PWR_ON   0x01
#define BH1750_RESET    0x07
#define BH1750_CONT_CONV 0x10
#define BH1750_CONV_TIME_US 180000U  /* 120 ms worst-case */

#define NUM_LEDS 16

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */

static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n", addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

/*
 * Write a single command byte to the BH1750.
 * Returns 0 on success, -1 on error.
 */
static int bh1750_write_cmd(int fd, uint8_t cmd)
{
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "BH1750 write(0x%02X): %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read the 2-byte result from the BH1750.
 * Returns 0 on success and stores the raw value in *raw.
 * Returns -1 on error.
 */
static int bh1750_read_raw(int fd, uint16_t *raw)
{
    uint8_t buf[2];
    ssize_t n = read(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "BH1750 read: expected 2 bytes, got %zd (%s)\n",
                n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }
    *raw = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/*
 * Read the ambient light level from the BH1750.
 * Returns 0 on success and stores the raw value in *raw.
 * Returns -1 on error.
 */
static int bh1750_read(int fd, uint16_t *raw)
{
    if (bh1750_write_cmd(fd, BH1750_PWR_ON) < 0)
        return -1;
    if (bh1750_write_cmd(fd, BH1750_RESET) < 0)
        return -1;
    if (bh1750_write_cmd(fd, BH1750_PWR_ON) < 0)
        return -1;

    /* Trigger a one-shot conversion */
    if (bh1750_write_cmd(fd, BH1750_CONT_CONV) < 0)
        return -1;

    usleep(BH1750_CONV_TIME_US);

    return bh1750_read_raw(fd, raw);
}

/* ------------------------------------------------------------------ */
/* SPI helpers                                                          */
/* ------------------------------------------------------------------ */

static int spi_open(const char *bus)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }
    uint8_t mode = SPI_MODE_0;
    uint8_t bits = SPI_BITS;
    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

/*
 * Send a 32-bit zero start frame.
 * Returns 0 on success, -1 on error.
 */
static int spi_send_zero_start(int fd)
{
    uint8_t tx[4] = {0, 0, 0, 0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = 0,
        .len = 4,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = SPI_DELAY_US,
    };
    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI send_zero_start: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Send one 32-bit LED frame.
 * brightness: 0–255, blue: 0–255, green: 0–255, red: 0–255.
 * Returns 0 on success, -1 on error.
 */
static int spi_send_led_frame(int fd, uint8_t brightness, uint8_t blue,
                              uint8_t green, uint8_t red)
{
    uint8_t tx[4] = {
        (uint8_t)(0x7F << 24),
        (uint8_t)(brightness << 16),
        (uint8_t)(blue << 8),
        (uint8_t)green
    };
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = 0,
        .len = 4,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = SPI_DELAY_US,
    };
    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI send_led_frame: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Send a 32-bit end frame.
 * Returns 0 on success, -1 on error.
 */
static int spi_send_zero_end(int fd)
{
    uint8_t tx[4] = {0, 0, 0, 0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = 0,
        .len = 4,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = SPI_DELAY_US,
    };
    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI send_zero_end: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* APA102 helpers                                                       */
/* ------------------------------------------------------------------ */

static void apa102_send_frame(int fd, uint8_t brightness, uint8_t blue,
                               uint8_t green, uint8_t red)
{
    if (spi_send_zero_start(fd) < 0)
        return;
    if (spi_send_led_frame(fd, brightness, blue, green, red) < 0)
        return;
    if (spi_send_zero_end(fd) < 0)
        return;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    int i2c_fd = -1;
    int spi_fd = -1;
    int rc = EXIT_FAILURE;

    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        goto cleanup;
    }

    /* Open I2C bus to BH1750 */
    i2c_fd = i2c_open(I2C_BUS, BH1750_ADDR);
    if (i2c_fd < 0)
        goto cleanup;

    /* Open SPI bus to APA102 */
    spi_fd = spi_open(SPI_BUS);
    if (spi_fd < 0)
        goto cleanup;

    printf("BH1750 light sensor and APA102 LED controller running.\n");
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t raw = 0;
        if (bh1750_read(i2c_fd, &raw) < 0) {
            fprintf(stderr, "BH1750 read failed; continuing.\n");
            usleep(100000);
            continue;
        }

        /* Convert raw ADC value to lux (simplified linear approximation) */
        float lux = (float)raw / 1.2f;

        /* Scale lux to 0–255 for APA102 brightness */
        uint8_t brightness = (uint8_t)(lux / 4.0f);

        /* Sanity check: BH1750 range is 0–65535, lux ~ 0–10000 */
        if (brightness > 255)
            brightness = 255;

        /* Send one LED frame for each LED in the strip */
        for (int i = 0; i < NUM_LEDS; i++) {
            apa102_send_frame(spi_fd, brightness, 0, 0, 0);
        }

        usleep(50000);  /* 50 ms cadence */
    }

    rc = EXIT_SUCCESS;

cleanup:
    printf("\nShutting down...\n");

    /* Turn off all LEDs */
    if (spi_fd >= 0) {
        if (spi_fd >= 0) {
            spi_send_zero_start(spi_fd);
            for (int i = 0; i < NUM_LEDS; i++)
                apa102_send_frame(spi_fd, 0, 0, 0, 0);
            spi_send_zero_end(spi_fd);
            close(spi_fd);
            spi_fd = -1;
        }
    }

    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }

    printf("Done.\n");
    return rc;
}

