static int spi_send_led_frame(int fd, uint8_t brightness, uint8_t blue,
                              uint8_t green, uint8_t red)
{
    uint8_t tx[4] = {
        (uint8_t)(0x7F << 24),
        (uint8_t)(brightness << 16),
        (uint8_t)(blue << 8),
        (uint8_t)green
    };
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = 0,
        .len = 4,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = SPI_DELAY_US,
    };
    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI send_led_frame: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Send a 32-bit end frame.
 * Returns 0 on success, -1 on error.
 */
static int spi_send_zero_end(int fd)
{
    uint8_t tx[4] = {0, 0, 0, 0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = 0,
        .len = 4,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = SPI_DELAY_US,
    };
    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI send_zero_end: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* APA102 helpers                                                       */
/* ------------------------------------------------------------------ */

static void apa102_send_frame(int fd, uint8_t brightness, uint8_t blue,
                               uint8_t green, uint8_t red)
{
    if (spi_send_zero_start(fd) < 0)
        return;
    if (spi_send_led_frame(fd, brightness, blue, green, red) < 0)
        return;
    if (spi_send_zero_end(fd) < 0)
        return;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    int i2c_fd = -1;
    int spi_fd = -1;
    int rc = EXIT_FAILURE;

    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        goto cleanup;
    }

    /* Open I2C bus to BH1750 */
    i2c_fd = i2c_open(I2C_BUS, BH1750_ADDR);
    if (i2c_fd < 0)
        goto cleanup;

    /* Open SPI bus to APA102 */
    spi_fd = spi_open(SPI_BUS);
    if (spi_fd < 0)
        goto cleanup;

    printf("BH1750 light sensor and APA102 LED controller running.\n");
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t raw = 0;
        if (bh1750_read(i2c_fd, &raw) < 0) {
            fprintf(stderr, "BH1750 read failed; continuing.\n");
            usleep(100000);
            continue;
        }

        /* Convert raw ADC value to lux (simplified linear approximation) */
        float lux = (float)raw / 1.2f;

        /* Scale lux to 0–255 for APA102 brightness */
        uint8_t brightness = (uint8_t)(lux / 4.0f);

        /* Sanity check: BH1750 range is 0–65535, lux ~ 0–10000 */
        if (brightness > 255)
            brightness = 255;

        /* Send one LED frame for each LED in the strip */
        for (int i = 0; i < NUM_LEDS; i++) {
            apa102_send_frame(spi_fd, brightness, 0, 0, 0);
        }

        usleep(50000);  /* 50 ms cadence */
    }

    rc = EXIT_SUCCESS;

cleanup:
    printf("\nShutting down...\n");

    /* Turn off all LEDs */
    if (spi_fd >= 0) {
        if (spi_fd >= 0) {
            spi_send_zero_start(spi_fd);
            for (int i = 0; i < NUM_LEDS; i++)
                apa102_send_frame(spi_fd, 0, 0, 0, 0);
            spi_send_zero_end(spi_fd);
            close(spi_fd);
            spi_fd = -1;
        }
    }

    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }

    printf("Done.\n");
    return rc;
}

