#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <sys/wait.h>

#define I2C_BUS        "/dev/i2c-1"
#define SPI_DEVICE     "/dev/spidev0.0"
#define SPI_SPEED_HZ   1000000
#define SPI_BITS        8
#define SPI_MODE        0

#define BH1750_ADDR_1  0x5C
#define BH1750_ADDR_2  0x5D

#define NUM_SENSORS    3
#define FADE_DURATION  500
#define LOOP_DELAY     100
#define CONVERSION_MS  180

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int install_signal_handler(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return -1;
    }
    return 0;
}

static int spi_init(void) {
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("open SPI device");
        return -1;
    }
    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl SPI_IOC_WR_MODE");
        close(fd);
        return -1;
    }
    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl SPI_IOC_WR_BITS_PER_WORD");
        close(fd);
        return -1;
    }
    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl SPI_IOC_WR_MAX_SPEED_HZ");
        close(fd);
        return -1;
    }
    return fd;
}

static int i2c_init(void) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open I2C device");
        return -1;
    }
    return fd;
}

static int bh1750_read(int fd, uint8_t addr, uint16_t *raw) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("ioctl I2C_SLAVE");
        return -1;
    }
    uint8_t cmd = 0x10;
    if (write(fd, &cmd, 1) != 1) {
        perror("write measurement command");
        return -1;
    }
    usleep(CONVERSION_MS * 1000);
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        perror("read measurement data");
        return -1;
    }
    *raw = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int fade_led(int fd, int target, int duration_ms) {
    int steps = duration_ms / 10;
    if (steps <= 0) steps = 1;
    int step_delay_ms = duration_ms / steps;
    int current = 0;
    for (int i = 0; i < steps && g_running; i++) {
        if (current < target) current++;
        else if (current > target) current--;
        uint8_t buf[4];
        buf[0] = 0x00;
        buf[1] = (uint8_t)(current * 3);
        buf[2] = (uint8_t)(current * 3);
        buf[3] = (uint8_t)(current * 3);
        if (write(fd, buf, 4) != 4) {
            perror("write LED data");
            return -1;
        }
        usleep(step_delay_ms * 1000);
    }
    return 0;
}

static int set_led_brightness(int fd, int brightness) {
    uint8_t buf[4];
    buf[0] = 0x00;
    buf[1] = (uint8_t)brightness;
    buf[2] = (uint8_t)brightness;
    buf[3] = (uint8_t)brightness;
    if (write(fd, buf, 4) != 4) {
        perror("write LED data");
        return -1;
    }
    return 0;
}

int main(void) {
    int i2c_fd = -1, spi_fd = -1;
    int bh1750_addrs[NUM_SENSORS] = {BH1750_ADDR_1, BH1750_ADDR_2};
    int bh1750_handles[NUM_SENSORS];
    int sensor_count = 0;
    int ret = 1;

    if (install_signal_handler() < 0) {
        goto cleanup;
    }

    i2c_fd = i2c_init();
    if (i2c_fd < 0) {
        goto cleanup;
    }

    spi_fd = spi_init();
    if (spi_fd < 0) {
        goto cleanup;
    }

    for (int i = 0; i < NUM_SENSORS; i++) {
        bh1750_handles[i] = -1;
    }

    while (g_running) {
        int readings[NUM_SENSORS];
        int valid = 0;
        for (int i = 0; i < NUM_SENSORS; i++) {
            uint16_t raw;
            if (bh1750_handles[i] >= 0) {
                if (bh1750_read(bh1750_handles[i], bh1750_addrs[i], &raw) == 0) {
                    readings[i] = (int)raw;
                    valid++;
                } else {
                    fprintf(stderr, "Sensor %d (0x%02X) read error\n", i, bh1750_addrs[i]);
                    readings[i] = 0;
                }
            } else {
                bh1750_handles[i] = i2c_fd;
                if (bh1750_addrs[i] == BH1750_ADDR_1) {
                    bh1750_handles[i] = i2c_fd;
                } else {
                    bh1750_handles[i] = i2c_fd;
                }
                if (bh1750_read(bh1750_handles[i], bh1750_addrs[i], &raw) == 0) {
                    readings[i] = (int)raw;
                    valid++;
                } else {
                    readings[i] = 0;
                }
            }
        }

        int sum = 0;
        for (int i = 0; i < NUM_SENSORS; i++) {
            sum += readings[i];
        }
        int avg = (valid > 0) ? (sum / valid) : 0;

        printf("Average light: %d\n", avg);

        if (fade_led(spi_fd, avg, FADE_DURATION) < 0) {
            fprintf(stderr, "Fade LED failed\n");
        }

        usleep(LOOP_DELAY * 1000);
    }

    ret = 0;

cleanup:
    if (spi_fd >= 0) {
        set_led_brightness(spi_fd, 0);
        close(spi_fd);
    }
    for (int i = 0; i < sensor_count; i++) {
        if (bh1750_handles[i] >= 0) {
            close(bh1750_handles[i]);
        }
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    return ret;
}

