#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 17
#define LED_PIN 18

#define BLINK_ON_MS 500
#define BLINK_OFF_MS 500
#define RAPID_BLINK_ON_MS 100
#define RAPID_BLINK_OFF_MS 100
#define ERROR_BLINK_ON_MS 100
#define ERROR_BLINK_OFF_MS 100
#define ERROR_BUZZER_ON_MS 200
#define ERROR_BUZZER_OFF_MS 200
#define ERROR_BUZZER_SHORT_MS 200
#define ERROR_BUZZER_SHORT2_MS 200
#define ERROR_BUZZER_LONG_MS 600
#define POLL_INTERVAL_MS 50
#define NUM_READINGS 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *msg) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "[%s] %s\n", ts, msg);
}

static void safe_set_mode(unsigned pin, unsigned mode) {
    if (gpioSetMode(pin, mode) < 0) {
        log_event("Error: failed to set GPIO mode");
    }
}

static void safe_write(unsigned pin, unsigned value) {
    if (gpioWrite(pin, value) < 0) {
        log_event("Error: failed to write to GPIO");
    }
}

static void safe_read(unsigned pin, unsigned *value) {
    int v = gpioRead(pin);
    if (v < 0) {
        log_event("Error: failed to read GPIO");
    } else {
        *value = v;
    }
}

static void blink_led(int on_ms, int off_ms) {
    safe_write(LED_PIN, 1);
    gpioDelay(on_ms * 1000);
    safe_write(LED_PIN, 0);
    gpioDelay(off_ms * 1000);
}

static void rapid_blink_led(int on_ms, int off_ms) {
    for (int i = 0; i < 5 && running; i++) {
        safe_write(LED_PIN, 1);
        gpioDelay(on_ms * 1000);
        safe_write(LED_PIN, 0);
        gpioDelay(off_ms * 1000);
    }
}

static void error_buzzer(void) {
    safe_write(BUZZER_PIN, 1);
    gpioDelay(ERROR_BUZZER_ON_MS * 1000);
    safe_write(BUZZER_PIN, 0);
    gpioDelay(ERROR_BUZZER_OFF_MS * 1000);
    safe_write(BUZZER_PIN, 1);
    gpioDelay(ERROR_BUZZER_SHORT_MS * 1000);
    safe_write(BUZZER_PIN, 0);
    gpioDelay(ERROR_BUZZER_SHORT2_MS * 1000);
    safe_write(BUZZER_PIN, 1);
    gpioDelay(ERROR_BUZZER_LONG_MS * 1000);
    safe_write(BUZZER_PIN, 0);
    gpioDelay(ERROR_BUZZER_OFF_MS * 1000);
}

static void self_test(void) {
    log_event("Starting self-test...");
    safe_write(LED_PIN, 1);
    gpioDelay(BLINK_ON_MS * 1000);
    safe_write(LED_PIN, 0);
    gpioDelay(BLINK_OFF_MS * 1000);
    safe_write(LED_PIN, 1);
    gpioDelay(BLINK_ON_MS * 1000);
    safe_write(LED_PIN, 0);
    gpioDelay(BLINK_OFF_MS * 1000);

    int persistent_low = 0;
    for (int i = 0; i < NUM_READINGS && running; i++) {
        unsigned val;
        safe_read(FLAME_SENSOR_PIN, &val);
        if (val == 0) {
            persistent_low = 1;
        }
        gpioDelay(POLL_INTERVAL_MS * 1000);
    }

    if (persistent_low) {
        log_event("Flame detected on all readings - error!");
        rapid_blink_led(ERROR_BLINK_ON_MS, ERROR_BLINK_OFF_MS);
        error_buzzer();
        return;
    }

    log_event("Self-test complete.");
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        log_event("Warning: failed to install SIGINT handler");
    }

    safe_set_mode(FLAME_SENSOR_PIN, PI_INPUT);
    safe_set_mode(BUZZER_PIN, PI_OUTPUT);
    safe_set_mode(LED_PIN, PI_OUTPUT);

    log_event("GPIO initialised. Monitoring flame sensor...");

    while (running) {
        unsigned val;
        safe_read(FLAME_SENSOR_PIN, &val);
        if (val == 0) {
            log_event("Flame detected!");
            safe_write(BUZZER_PIN, 1);
            safe_write(LED_PIN, 1);
            while (running) {
                safe_read(FLAME_SENSOR_PIN, &val);
                if (val == 1) {
                    safe_write(BUZZER_PIN, 0);
                    safe_write(LED_PIN, 0);
                    break;
                }
                gpioDelay(POLL_INTERVAL_MS * 1000);
            }
        } else {
            safe_write(BUZZER_PIN, 0);
            safe_write(LED_PIN, 0);
        }
        gpioDelay(POLL_INTERVAL_MS * 1000);
    }

    safe_write(BUZZER_PIN, 0);
    safe_write(LED_PIN, 0);
    gpioTerminate();
    log_event("Program terminated.");
    return 0;
}

