/*
 * Raspberry Pi 4 Model B — BH1750 ambient light sensor reader with LED indicator.
 *
 * Hardware:
 *   - BH1750 on /dev/i2c-1 (I2C bus 1, address 0x10)
 *   - LED on GPIO17 (BCM 17, 50 % duty cycle, 50 Hz square wave)
 *
 * Behavior:
 *   - Reads lux once per second.
 *   - Stores the last 60 readings in a circular buffer.
 *   - Computes the average of the buffer.
 *   - Blinks the LED at 0.5–5 Hz depending on the average lux.
 *   - On I2C error, prints an error and skips the sample.
 *   - On SIGINT, cleans up GPIO and I2C resources.
 *
 * Build:  gcc -O2 -Wall -Wextra -o light_monitor light_monitor.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define I2C_BUS        "/dev/i2c-1"
#define BH1750_ADDR    0x10
#define BH1750_PWR_ON  0x01
#define BH1750_RESET   0x07
#define BH1750_CONT_HRES 0x10  /* High-resolution, continuous mode */

#define LED_GPIO       17
#define BUFFER_SIZE    60
#define SAMPLE_PERIOD  1.0   /* seconds */

#define MIN_FREQ_HZ    0.5
#define MAX_FREQ_HZ    5.0
#define MAX_LUX        1000

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Circular buffer                                                      */
/* ------------------------------------------------------------------ */

typedef struct {
    float buffer[BUFFER_SIZE];
    int   head;
    int   count;
} CircularBuffer;

static void cb_init(CircularBuffer *cb)
{
    memset(cb->buffer, 0, sizeof(cb->buffer));
    cb->head  = 0;
    cb->count = 0;
}

static void cb_push(CircularBuffer *cb, float value)
{
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE)
        cb->count++;
}

static float cb_average(const CircularBuffer *cb)
{
    if (cb->count == 0)
        return 0.0f;

    float sum = 0.0f;
    for (int i = 0; i < cb->count; i++)
        sum += cb->buffer[i];
    return sum / (float)cb->count;
}

/* ------------------------------------------------------------------ */
/* BH1750                                                             */
/* ------------------------------------------------------------------ */

static int bh1750_write(int fd, uint8_t cmd)
{
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "BH1750 write(0x%02X) failed: %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int bh1750_read(int fd, uint16_t *raw)
{
    uint8_t buf[2];
    ssize_t n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "BH1750 read failed: got %zd bytes (%s)\n", n, strerror(errno));
        return -1;
    }
    *raw = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

static int bh1750_init(int fd)
{
    if (bh1750_write(fd, BH1750_PWR_ON) < 0) return -1;
    if (bh1750_write(fd, BH1750_RESET) < 0) return -1;
    if (bh1750_write(fd, BH1750_CONT_HRES) < 0) return -1;
    return 0;
}

static int bh1750_read_lux(int fd, float *lux_out)
{
    uint16_t raw;
    if (bh1750_read(fd, &raw) < 0)
        return -1;

    /* BH1750 datasheet: 1 lux resolution, 0.5 ms conversion time.
     * For high-resolution mode, the result is already in lux.
     */
    *lux_out = (float)raw / 1.2f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* LED control                                                          */
/* ------------------------------------------------------------------ */

static void led_set_duty(float lux)
{
    float freq = MIN_FREQ_HZ + (lux / MAX_LUX) * (MAX_FREQ_HZ - MIN_FREQ_HZ);
    float period_us = 1.0f / freq;
    int half_us = (int)(period_us / 2.0f);

    if (half_us < 1)
        half_us = 1;

    int on_us  = half_us;
    int off_us = half_us;

    if (lux > 500.0f) {
        on_us  = half_us;
        off_us = half_us;
    } else if (lux > 300.0f) {
        on_us  = half_us;
        off_us = (int)(period_us / 3.0f);
    } else if (lux > 200.0f) {
        on_us  = (int)(period_us / 4.0f);
        off_us = (int)(period_us / 2.0f);
    } else {
        on_us  = (int)(period_us / 5.0f);
        off_us = (int)(period_us / 1.0f);
    }

    if (on_us > 0) {
        if (on_us > 1000) on_us = 1000;
        if (on_us < 1)   on_us = 1;
        gpioWrite(LED_GPIO, 1);
        usleep(on_us * 1000);
    }
    if (off_us > 0) {
        if (off_us > 1000) off_us = 1000;
        if (off_us < 1)   off_us = 1;
        gpioWrite(LED_GPIO, 0);
        usleep(off_us * 1000);
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */

static void cleanup(int i2c_fd, int led_pin)
{
    if (led_pin >= 0) {
        /* Unexport the GPIO so it is not used by the kernel. */
        if (gpiod_line_request_output(led_pin, "light_monitor", 0) >= 0)
            gpiod_line_release(led_pin);
    }
    if (i2c_fd >= 0)
        close(i2c_fd);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    int i2c_fd = -1;
    int led_pin = LED_GPIO;
    bool led_requested = false;

    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n", BH1750_ADDR, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* ---- Initialize BH1750 ---- */
    if (bh1750_init(i2c_fd) < 0) {
        fprintf(stderr, "BH1750 initialization failed.\n");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    /* ---- Request LED GPIO ---- */
    if (gpiod_line_request_output(LED_GPIO, "light_monitor", 0) < 0) {
        fprintf(stderr, "Cannot request GPIO %d: %s\n", LED_GPIO, strerror(errno));
        close(i2c_fd);
        return EXIT_FAILURE;
    }
    led_requested = true;

    CircularBuffer lux_buffer;
    cb_init(&lux_buffer);

    printf("Light sensor monitoring started. Press Ctrl-C to exit.\n");

    while (g_running) {
        float lux = 0.0f;

        if (bh1750_read_lux(i2c_fd, &lux) < 0) {
            fprintf(stderr, "Sensor read failed; will retry next cycle.\n");
        } else {
            cb_push(&lux_buffer, lux);
            float avg = cb_average(&lux_buffer);
            printf("Lux: %.2f  Avg: %.2f\n", lux, avg);
            led_set_duty(avg);
        }

        /* Sleep for the sample period, but wake early on signal. */
        for (int i = 0; i < 10 && g_running; i++)
            usleep(100000);  /* 100 ms */
    }

    /* ---- Cleanup ---- */
    printf("\nShutting down...\n");
    if (led_requested) {
        gpioWrite(LED_GPIO, 0);
        gpiod_line_release(LED_GPIO);
    }
    if (i2c_fd >= 0)
        close(i2c_fd);

    return EXIT_SUCCESS;
}

