/*
 * 74HC595 7-segment display driver for Raspberry Pi (BCM numbering)
 *
 * Wiring:
 *   GPIO17 (BCM) -> 74HC595 DIN  (data input)
 *   GPIO18 (BCM) -> 74HC595 CLK  (clock)
 *   GPIO27 (BCM) -> 74HC595 LATCH (storage register select)
 *
 * The 74HC595 is configured for 8-bit shift register mode, with the
 * latch line held low while data is shifted in, then held high to
 * latch the data into the register.  The display segments are
 * decoded from the 8 shift register outputs Q0..Q7 as follows:
 *   Q0 -> a, Q1 -> b, Q2 -> c, Q3 -> d, Q4 -> e, Q5 -> f, Q6 -> g, Q7 -> dp
 *
 * Build:  gcc -O2 -Wall -Wextra -o shift7 seg7.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define DATA_PIN   17   /* BCM 17  -> 74HC595 DIN  */
#define CLOCK_PIN  18   /* BCM 18  -> 74HC595 CLK  */
#define LATCH_PIN  27   /* BCM 27  -> 74HC595 LATCH */

#define BLINK_ON_MS  500
#define BLINK_OFF_MS 500

/* Segment patterns for digits 0-9 (common-cathode, active-high) */
static const unsigned char digit_patterns[10] = {
    0x3F, /* 0 */
    0x06, /* 1 */
    0x5B, /* 2 */
    0x4F, /* 3 */
    0x66, /* 4 */
    0x6D, /* 5 */
    0x7D, /* 6 */
    0x07, /* 7 */
    0x7F, /* 8 */
    0x6F  /* 9 */
};

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/*
