/*
 * blink_button.c — Blink an LED on GPIO17 (BCM) with a 2-second period
 * while waiting for a falling-edge event on GPIO18 (BCM).
 *
 * Build:  gcc -O2 -Wall -Wextra -o blink_button blink_button.c -lgpiod
 * Run:    sudo ./blink_button   (or ensure user is in the 'gpio' group)
 */
#include <errno.h>
#include <gpiod.h>
#include <signal.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#define LED_PIN    17
#define BUTTON_PIN 18
#define CHIP_NAME  "gpiochip0"
#define PERIOD_SEC 2

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handler(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    return sigaction(SIGINT, &sa, NULL);
}

static void sleep_seconds(unsigned int seconds)
{
    while (seconds > 0 && g_running) {
        unsigned int chunk = (seconds > 1000) ? 1000 : seconds;
        usleep(chunk * 1000000U);
        seconds -= chunk;
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *led_line = NULL;
    struct gpiod_line *button_line = NULL;
    int ret = EXIT_FAILURE;

    if (install_signal_handler() != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n",
                CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (led_line == NULL) {
        fprintf(stderr, "Failed to get LED line %d: %s\n",
                LED_PIN, strerror(errno));
        goto cleanup;
    }

    button_line = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (button_line == NULL) {
        fprintf(stderr, "Failed to get button line %d: %s\n",
                BUTTON_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(led_line, "blink_button", 0) < 0) {
        fprintf(stderr, "Failed to request LED line %d as output: %s\n",
                LED_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_falling_edge_events(button_line, "blink_button") < 0) {
        fprintf(stderr, "Failed to request falling-edge events on button line %d: %s\n",
                BUTTON_PIN, strerror(errno));
        goto cleanup;
    }

    printf("Blinking LED on GPIO%d every %d second(s) while waiting for button on GPIO%d.\n",
           LED_PIN, PERIOD_SEC);
    printf("Press Ctrl-C to exit.\n");
    fflush(stdout);

    while (g_running) {
        if (gpiod_line_event_wait(button_line, &(struct timespec){ .tv_sec = 1, .tv_nsec = 0 }) > 0) {
            struct gpiod_line_event event;
            if (gpiod_line_event_read(button_line, &event) == 0) {
                if (event.event_type == GPIOD_LINE_EVENT_FALLING_EDGE) {
                    printf("Button pressed — stopping blink.\n");
                    fflush(stdout);

                    if (gpiod_line_set_value(led_line, 0) < 0) {
                        fprintf(stderr, "Failed to turn off LED: %s\n",
                                strerror(errno));
                    }
                    ret = EXIT_SUCCESS;
                    break;
                }
            }
        }
        if (!g_running) {
            break;
        }
        sleep_seconds(PERIOD_SEC);
    }

cleanup:
    if (led_line != NULL) {
        gpiod_line_set_value(led_line, 0);
        gpiod_line_release(led_line);
    }
    if (button_line != NULL) {
        gpiod_line_release(button_line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    return ret;
}

