/*
 * LED button blinker with error checking for the pigpio library.
 *
 * Wiring (BCM numbering):
 *   GPIO24 (physical pin 18)  -> LED anode (via 330 ohm) -> GND
 *   GPIO22 (physical pin 15)  -> button to 3.3 V
 *   (internal pull-down on GPIO22 if available)
 *
 * Behavior:
 *   - LED starts OFF.
 *   - While button is held, blink LED 500 ms on / 500 ms off.
 *   - LED turns OFF immediately when button is released.
 *   - Runs until Ctrl-C or SIGTERM.
 *
 * Build:  gcc -Wall -Wextra -O2 -o led_button led_button.c -lpigpio -lrt
 * Run:    sudo ./led_button
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <pigpio.h>

#define LED_PIN    24          /* BCM 24, physical pin 18 */
#define BUTTON_PIN 22          /* BCM 22, physical pin 15 */

#define BLINK_ON_MS  500
#define BLINK_OFF_MS 500

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0)
        perror("warning: sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) != 0)
        perror("warning: sigaction(SIGTERM)");
}

int main(void)
{
    int rc = EXIT_SUCCESS;

    install_signal_handlers();

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (code %d).\n",
                gpioInitialise());
        return EXIT_FAILURE;
    }

    /* ---- LED pin ---- */
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(LED_PIN=%d, OUTPUT) failed.\n",
                LED_PIN);
        rc = EXIT_FAILURE;
        goto cleanup;
    }
    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Error: gpioWrite(LED_PIN=%d, 0) failed.\n",
                LED_PIN);
        rc = EXIT_FAILURE;
        goto cleanup;
    }

    /* ---- Button pin ---- */
    if (gpioSetMode(BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(BUTTON_PIN=%d, INPUT) failed.\n",
                BUTTON_PIN);
        rc = EXIT_FAILURE;
        goto cleanup;
    }
    if (gpioSetPullUpDown(BUTTON_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(BUTTON_PIN=%d, DOWN) failed.\n",
                BUTTON_PIN);
        rc = EXIT_FAILURE;
        goto cleanup;
    }

    printf("LED button blinker running.  Press Ctrl-C to exit.\n");

    while (g_running) {
        int button_state = gpioRead(BUTTON_PIN);
        if (button_state < 0) {
            fprintf(stderr, "Error: gpioRead(BUTTON_PIN=%d) failed (code %d).\n",
                    BUTTON_PIN, button_state);
            rc = EXIT_FAILURE;
            break;
        }

        if (button_state == 0) {
            /* Button pressed (active low with pull-down). */
            if (gpioWrite(LED_PIN, 1) != 0) {
                fprintf(stderr, "Error: gpioWrite(LED_PIN=%d, 1) failed.\n",
                        LED_PIN);
                rc = EXIT_FAILURE;
                break;
            }

            /* Blink: 500 ms on, 500 ms off. */
            gpioDelay(BLINK_ON_MS * 1000);   /* microseconds */
            if (!g_running)
                break;

            if (gpioWrite(LED_PIN, 0) != 0) {
                fprintf(stderr, "Error: gpioWrite(LED_PIN=%d, 0) failed.\n",
                        LED_PIN);
                rc = EXIT_FAILURE;
                break;
            }
            gpioDelay(BLINK_OFF_MS * 1000);
        } else {
            /* Button released. Turn LED off immediately. */
            if (gpioWrite(LED_PIN, 0) != 0) {
                fprintf(stderr, "Error: gpioWrite(LED_PIN=%d, 0) failed.\n",
                        LED_PIN);
                rc = EXIT_FAILURE;
                break;
            }
        }

        gpioDelay(10000);   /* 10 ms poll interval */
    }

cleanup:
    /* Ensure LED is off before releasing resources. */
    if (gpioWrite(LED_PIN, 0) != 0)
        fprintf(stderr, "Warning: failed to turn LED off during cleanup.\n");

    gpioTerminate();
    return rc;
}

