/*
 * LSM303DLHC Impact Detector for Raspberry Pi Zero W
 *
 * Wiring:
 *   LSM303DLHC SDA -> Pi GPIO2 (I2C bus 1 SDA)
 *   LSM303DLHC SCL -> Pi GPIO3 (I2C bus 1 SCL)
 *   LSM303DLHC VDD -> 3.3 V
 *   LSM303DLHC GND -> GND
 *   LSM303DLHC SDO -> GND  (for SA0 low)
 *   Impact LED / buzzer -> Pi GPIO17 (BCM 17)
 *
 * Build:
 *   gcc -O2 -Wall -o impact_detect impact_detect.c -lpigpio -lrt
 *   (pigpio must be installed; run as root or with appropriate permissions)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <errno.h>
#include <getopt.h>
#include <pigpio.h>

/* ---- Configuration ---- */
#define I2C_BUS              1
#define LSM303_ACCEL_ADDR    0x19   /* AD0 low (SA0 = 0) */
#define LSM303_ACCEL_CTRL_REG1 0x20
#define LSM303_ACCEL_OUT_X_L  0x28
#define LSM303_ACCEL_OUT_X_H  0x29
#define LSM303_ACCEL_OUT_Y_L  0x2A
#define LSM303_ACCEL_OUT_Y_H  0x2B
#define LSM303_ACCEL_OUT_Z_L  0x2C
#define LSM303_ACCEL_OUT_Z_H  0x2D

#define ACCEL_SCALE_FACTOR   16384.0f  /* LSB per G at ±2 G */
#define ACCEL_FS_2G          2.0f      /* Full scale setting */
#define ACCEL_TEMP_REG       0x0C
#define ACCEL_TEMP_OUT_L     0x0E
#define ACCEL_TEMP_OUT_H     0x0F

#define GPIO_PIN             17
#define IMPACT_PULSE_US      50000    /* 50 ms */
#define POLL_DELAY_US        100000   /* 100 ms */
#define LOG_FILE             "impact_log.txt"
#define DEFAULT_THRESHOLD    2.0f
#define MAX_RETRIES          3

/* ---- Globals ---- */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;
static float threshold = DEFAULT_THRESHOLD;

/* ---- Prototypes ---- */
static int  init_lsm303(void);
static int  read_accel(float *x, float *y, float *z);
static float calc_magnitude(float x, float y, float z);
static void trigger_impact(void);
static void log_data(float x, float y, float z);
static void cleanup(void);
static void signal_handler(int sig);

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    /* Ensure GPIO is left in a safe state */
    gpioWrite(GPIO_PIN, 0);
    gpioTerminate();
}

/* ---- Initialize LSM303DLHC ---- */
static int init_lsm303(void)
{
    /* Verify sensor presence by reading the temperature register */
    int reg = i2cReadByteData(i2c_handle, ACCEL_TEMP_REG);
    if (reg < 0) {
        fprintf(stderr, "Error: LSM303DLHC not detected on I2C bus %d addr 0x%02X (reg 0x%02X).\n",
                I2C_BUS, LSM303_ACCEL_ADDR, ACCEL_TEMP_REG);
        return -1;
    }

    /* Standby mode to allow configuration changes */
    if (i2cWriteByteData(i2c_handle, LSM303_ACCEL_CTRL_REG1, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to set accelerometer to standby mode.\n");
        return -1;
    }

    /* Set full scale to ±2 G (FS = 0) */
    if (i2cWriteByteData(i2c_handle, LSM303_ACCEL_CTRL_REG1, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to set accelerometer full scale.\n");
        return -1;
    }

    /* Enable accelerometer (X, Y, Z axes) */
    if (i2cWriteByteData(i2c_handle, LSM303_ACCEL_CTRL_REG1, 0x07) < 0) {
        fprintf(stderr, "Error: Failed to enable accelerometer.\n");
        return -1;
    }

    return 0;
}

/* ---- Read accelerometer data ---- */
static int read_accel(float *x, float *y, float *z)
{
    char buf[6];

    /* Read 6 bytes starting at OUT_X_L (0x28) */
    if (i2cReadI2CBlockData(i2c_handle, LSM303_ACCEL_OUT_X_L | 0x80, buf, 6) != 6) {
        fprintf(stderr, "Error: Failed to read accelerometer data block.\n");
        return -1;
    }

    /* Combine little-endian two's-complement values */
    int16_t raw_x = (int16_t)((buf[1] << 8) | (uint8_t)buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | (uint8_t)buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | (uint8_t)buf[4]);

    *x = (float)raw_x / ACCEL_SCALE_FACTOR;
    *y = (float)raw_y / ACCEL_SCALE_FACTOR;
    *z = (float)raw_z / ACCEL_SCALE_FACTOR;

    return 0;
}

/* ---- Calculate G-force magnitude ---- */
static float calc_magnitude(float x, float y, float z)
{
    return sqrtf(x * x + y * y + z * z);
}

/* ---- Trigger impact (GPIO17 pulse) ---- */
static void trigger_impact(void)
{
    if (gpioWrite(GPIO_PIN, 1) < 0) {
        fprintf(stderr, "Warning: Failed to set GPIO%d HIGH.\n", GPIO_PIN);
        return;
    }
    gpioDelay(IMPACT_PULSE_US);
    if (gpioWrite(GPIO_PIN, 0) < 0) {
        fprintf(stderr, "Warning: Failed to set GPIO%d LOW.\n", GPIO_PIN);
    }
}

/* ---- Log data to file ---- */
static void log_data(float x, float y, float z)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(log_file, "%s, X: %.3f G, Y: %.3f G, Z: %.3f G\n", timestamp, x, y, z);
    fflush(log_file);
}

/* ---- Main ---- */
int main(int argc, char *argv[])
{
    int opt;

    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                threshold = (float)atof(optarg);
                if (threshold < 0.0f) {
                    fprintf(stderr, "Error: Threshold must be non-negative.\n");
                    return EXIT_FAILURE;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold_g]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO17 as output, initially LOW */
    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as output.\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_PIN, 0);

    /* Open I2C bus */
    i2c_handle = i2cOpen(I2C_BUS, LSM303_ACCEL_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at addr 0x%02X (err=%d).\n",
                I2C_BUS, LSM303_ACCEL_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize accelerometer */
    if (init_lsm303() != 0) {
        fprintf(stderr, "Error: LSM303DLHC initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register signal handlers */
    signal(SIGINT,  signal_handler);
    signal(SIGTERM, signal_handler);

    printf("LSM303DLHC Impact Detector running. Threshold: %.2f G\n", threshold);
    printf("Press Ctrl+C to exit.\n");

    float x, y, z;
    int consecutive_errors = 0;

    while (program_running) {
        if (read_accel(&x, &y, &z) == 0) {
            consecutive_errors = 0;
            float magnitude = calc_magnitude(x, y, z);
            if (magnitude > threshold) {
                printf("Impact detected! Magnitude: %.3f G\n", magnitude);
                trigger_impact();
                log_data(x, y, z);
            }
        } else {
            consecutive_errors++;
            fprintf(stderr, "Warning: I2C read error (attempt %d/%d).\n",
                    consecutive_errors, MAX_RETRIES);
            if (consecutive_errors >= MAX_RETRIES) {
                fprintf(stderr, "Error: Max consecutive I2C errors reached. Exiting.\n");
                break;
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    cleanup();
    printf("Program terminated cleanly.\n");
    return EXIT_SUCCESS;
}

