/*
 * Raspberry Pi Zero W – ADPD188BI ALS/RGB Color Sensor Logger
 *
 * Wiring:
 *   ADPD188BI SDA  -> GPIO2  (I2C bus 1 SDA)
 *   ADPD188BI SCL  -> GPIO3  (I2C bus 1 SCL)
 *   ADPD188BI VDD  -> 3.3 V
 *   ADPD188BI GND  -> GND
 *   LED anode     -> GPIO18 (BCM) via 330 Ω resistor
 *   LED cathode   -> GND
 *
 * Build:  gcc -O2 -Wall -o color_logger color_logger.c -lpigpio -lrt
 * Run:    sudo ./color_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS          1
#define I2C_ADDR         0x48
#define LED_GPIO         18
#define PWM_RANGE        1000
#define PWM_FREQ         1000
#define SAMPLE_PERIOD_US 500000   /* 500 ms */
#define RETRY_DELAY_US   100000   /* 100 ms */

/* ADPD188BI register addresses (16-bit, big-endian on the bus) */
#define REG_ALS_LSB      0x00
#define REG_ALS_MSB      0x01
#define REG_RED_LSB      0x02
#define REG_RED_MSB      0x03
#define REG_GREEN_LSB    0x04
#define REG_GREEN_MSB    0x05
#define REG_BLUE_LSB     0x06
#define REG_BLUE_MSB     0x07
#define REG_COMMAND      0x08

/* Command register opcodes */
#define CMD_RESET        0x01
#define CMD_START        0x02
#define CMD_STOP         0x03

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    /* Ensure LED is off before terminating pigpio */
    gpioWrite(LED_GPIO, 0);
    gpioPWM(LED_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit big-endian value to a 16-bit register address.       */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int write_reg16(uint8_t reg, uint16_t value)
{
    char buf[3];
    buf[0] = (char)(reg >> 8);
    buf[1] = (char)(reg & 0xFF);
    buf[2] = (char)(value & 0xFF);

    if (i2cWriteDevice(g_i2c_handle, buf, 3) != 3) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit big-endian value from a 16-bit register address.      */
/* Returns 0 on success and stores value in *out; -1 on error.         */
/* ------------------------------------------------------------------ */
static int read_reg16(uint8_t reg, uint16_t *out)
{
    char cmd[2];
    char data[2];

    cmd[0] = (char)(reg >> 8);
    cmd[1] = (char)(reg & 0xFF);

    if (i2cWriteDevice(g_i2c_handle, cmd, 2) != 2) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (i2cReadDevice(g_i2c_handle, data, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the ADPD188BI: reset, start ALS/RGB, then enable the    */
/* ALS channel and set the red/green/blue LED drive strength.          */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int init_sensor(void)
{
    uint16_t val;

    /* 1. Software reset */
    if (write_reg16(REG_COMMAND, CMD_RESET) != 0)
        return -1;
    gpioDelay(10000);  /* 10 ms settle */

    /* 2. Start ALS + RGB engine */
    if (write_reg16(REG_COMMAND, CMD_START) != 0)
        return -1;
    gpioDelay(10000);

    /* 3. Enable ALS channel (bit 0 of ALS_EN) */
    if (write_reg16(0x0F, 0x0001) != 0)
        return -1;

    /* 4. Set red/green/blue LED drive strength (bits 7:4 of LED_DRIVE) */
    if (write_reg16(0x10, 0x0F) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read all four channels and combine ALS LSB/MSB into a 16-bit value. */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int read_channels(uint16_t *als, uint16_t *red, uint16_t *green,
                         uint16_t *blue)
{
    if (read_reg16(REG_ALS_LSB,  als) != 0) return -1;
    if (read_reg16(REG_ALS_MSB,  als) != 0) return -1;
    if (read_reg16(REG_RED_LSB,  red) != 0) return -1;
    if (read_reg16(REG_RED_MSB,  red) != 0) return -1;
    if (read_reg16(REG_GREEN_LSB, green) != 0) return -1;
    if (read_reg16(REG_GREEN_MSB, green) != 0) return -1;
    if (read_reg16(REG_BLUE_LSB,  blue) != 0) return -1;
    if (read_reg16(REG_BLUE_MSB,  blue) != 0) return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Map ALS value (0–65535) to PWM duty cycle (0–PWM_RANGE).            */
/* Returns 0 on success, -1 on error.                                 */
/* ------------------------------------------------------------------ */
static int map_als_to_pwm(uint16_t als)
{
    if (als == 0) {
        gpioPWM(LED_GPIO, 0);
        return 0;
    }
    if (als >= 65535) als = 65534;
    int duty = (int)(((float)als / 65535.0f) * (float)PWM_RANGE);
    if (gpioPWM(LED_GPIO, duty) != 0) {
        fprintf(stderr, "gpioPWM failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static void log_data(uint16_t als, uint16_t r, uint16_t g, uint16_t b)
{
    time_t rawtime;
    struct tm timeinfo;
    char ts[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(g_log_file, "%s,%u,%u,%u,%u\n", ts, als, r, g, b);
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    uint16_t als, red, green, blue;

    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- I2C open ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (bus %d, addr 0x%02X): %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Sensor init ---- */
    if (init_sensor() != 0) {
        fprintf(stderr, "Sensor initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- GPIO setup ---- */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d) failed\n", LED_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioSetPWMrange(LED_GPIO, PWM_RANGE);
    gpioSetPWMfrequency(LED_GPIO, PWM_FREQ);

    /* ---- Log file ---- */
    g_log_file = fopen("color_log.csv", "a");
    if (!g_log_file) {
        fprintf(stderr, "fopen(color_log.csv) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    /* Write header only if file is empty */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0)
        fprintf(g_log_file, "timestamp,als,red,green,blue\n");

    /* ---- Signals ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Logging color data to color_log.csv. Press Ctrl+C to stop.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        if (read_channels(&als, &red, &green, &blue) == 0) {
            if (map_als_to_pwm(als) != 0) {
                fprintf(stderr, "PWM update failed; retrying in 100 ms\n");
                gpioDelay(RETRY_DELAY_US);
                continue;
            }
            log_data(als, red, green, blue);
        } else {
            fprintf(stderr, "Sensor read error; retrying in 100 ms\n");
            gpioDelay(RETRY_DELAY_US);
            continue;
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

