/*
 * Raspberry Pi Zero W – FXOS8700CQ Impact Monitor
 *
 * Reads the Adafruit FXOS8700CQ 6‑Axis Accelerometer/Magnetometer over I2C
 * bus 1 at 50 ms intervals, computes the acceleration magnitude, and
 * logs impact events to "impact_log.txt".
 *
 * Wiring:
 *   FXOS8700CQ SDA  -> GPIO2 (pin 3, I2C bus 1 SDA)
 *   FXOS8700CQ SCL  -> GPIO3 (pin 5, I2C bus 1 SCL)
 *   FXOS8700CQ VDD  -> 3.3 V
 *   FXOS8700CQ GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o impact_monitor impact_monitor.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

