#define FXOS8700_I2C_ADDR        0x52
#define FXOS8700_REG_STATUS       0x00
#define FXOS8700_REG_OUT_X_MSB    0x01
#define FXOS8700_REG_WHO_AM_I     0x0D
#define FXOS8700_WHO_AM_I_VAL     0xC7
#define FXOS8700_REG_CTRL_REG1    0x2A
#define FXOS8700_REG_CTRL_REG2    0x2B
#define FXOS8700_REG_M_CTRL       0x5B
#define FXOS8700_REG_XYZ_DATA_CFG 0x0E

/* ±2 g full-scale range */
#define FXOS8700_RANGE_2G         0x00
/* 200 Hz ODR, 12.5 ms sample period */
#define FXOS8700_ODR_200HZ        0x0D
/* Standby mode */
#define FXOS8700_MODE_STANDBY     0x00
/* Active mode */
#define FXOS8700_MODE_ACTIVE      0x01

#define I2C_BUS_DEV                "/dev/i2c-1"
#define LOG_FILE                   "impact_log.txt"
#define SAMPLE_PERIOD_US           50000   /* 50 ms */
#define IMPACT_THRESHOLD          2.0f    /* g */
#define MAX_RETRIES                3

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    n = read(fd, out, 1);
    if (n != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "I2C block read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* FXOS8700CQ initialization                                          */
/* ------------------------------------------------------------------ */
static int fxos8700_init(int fd)
{
    uint8_t who_am_i = 0;

    /* Verify device identity */
    if (i2c_read_reg8(fd, FXOS8700_REG_WHO_AM_I, &who_am_i) != 0)
        return -1;
    if (who_am_i != FXOS8700_WHO_AM_I_VAL) {
        fprintf(stderr,
                "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, FXOS8700_WHO_AM_I_VAL);
        return -1;
    }

    /* Standby mode before configuration */
    if (i2c_write_reg8(fd, FXOS8700_REG_CTRL_REG1, FXOS8700_MODE_STANDBY) != 0)
        return -1;
    usleep(1000);

    /* ±2 g full-scale range */
    if (i2c_write_reg8(fd, FXOS8700_REG_M_CTRL, FXOS8700_RANGE_2G) != 0)
        return -1;

    /* Standby -> active mode */
    if (i2c_write_reg8(fd, FXOS8700_REG_CTRL_REG1, FXOS8700_MODE_ACTIVE) != 0)
        return -1;
    usleep(1000);

    /* Enable all axes (X/Y/Z) in active mode */
    if (i2c_write_reg8(fd, FXOS8700_REG_CTRL_REG2, 0x03) != 0)
        return -1;

    /* Enable data ready interrupt (optional) */
    if (i2c_write_reg8(fd, FXOS8700_REG_XYZ_DATA_CFG, 0x00) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read acceleration (g) and compute magnitude                         */
/* ------------------------------------------------------------------ */
static int read_acceleration(int fd, float *x, float *y, float *z)
{
    uint8_t status = 0;
    uint8_t data[6];
    int16_t raw_x, raw_y, raw_z;
    int retries = 0;

    /* Poll status register until data-ready bit (bit 0) is set */
    do {
        if (i2c_read_reg8(fd, FXOS8700_REG_STATUS, &status) != 0)
            return -1;
        if (++retries > MAX_RETRIES) {
            fprintf(stderr, "Sensor data-ready timeout\n");
            return -1;
        }
        usleep(1000);
    } while (!(status & 0x01));

    /* Read 6 bytes starting at OUT_X_MSB */
    if (i2c_read_block(fd, FXOS8700_REG_OUT_X_MSB, data, 6) != 0)
        return -1;

    raw_x = (int16_t)((data[0] << 8) | data[1]);
    raw_y = (int16_t)((data[2] << 8) | data[3]);
    raw_z = (int16_t)((data[4] << 8) | data[5]);

    /* ±2 g range: 16384 LSB/g */
    *x = (float)raw_x / 16384.0f;
    *y = (float)raw_y / 16384.0f;
    *z = (float)raw_z / 16384.0f;

    return 0;
}

static float compute_magnitude(float x, float y, float z)
{
    return sqrtf(x * x + y * y + z * z);
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_impact(float x, float y, float z, float magnitude)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        fclose(fp);
        return;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.3f,%.3f,%.3f,%.3f\n", ts, x, y, z, magnitude);
    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        /* Put sensor in standby before closing */
        (void)i2c_write_reg8(g_i2c_fd, FXOS8700_REG_CTRL_REG1,
                             FXOS8700_MODE_STANDBY);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS_DEV, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS_DEV, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, FXOS8700_I2C_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                FXOS8700_I2C_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (fxos8700_init(g_i2c_fd) != 0) {
        fprintf(stderr, "FXOS8700CQ initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("FXOS8700CQ impact monitor running. Press Ctrl-C to exit.\n");

    while (g_running) {
        float x, y, z, magnitude;

        if (read_acceleration(g_i2c_fd, &x, &y, &z) != 0) {
