/*
 * GY-50 L3G4200D gyroscope calibration and logging for Raspberry Pi Zero W
 * I2C bus 1, 20 Hz sampling, 100-sample calibration, alert on axis > 50 dps.
 *
 * Build:  gcc -O2 -Wall -Wextra -o gyro_log gyro_log.c
 * Run:    ./gyro_log
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- L3G4200D constants (datasheet rev 1.3) ---- */
#define L3G4200D_ADDR        0x33
#define L3G4200D_WHO_AM_I    0x0F
#define L3G4200D_WHO_AM_I_VAL 0xD3
#define L3G4200D_CTRL_REG1   0x20
#define L3G4200D_CTRL_REG4   0x23
#define L3G4200D_OUT_X_L     0x28
#define L3G4200D_OUT_X_H     0x29
#define L3G4200D_OUT_Y_L     0x2A
#define L3G4200D_OUT_Y_H     0x2B
#define L3G4200D_OUT_Z_L     0x2C
#define L3G4200D_OUT_Z_H     0x2D

#define GYRO_SCALE_250DPS    0.000061f   /* LSB per dps at 250 dps range */
#define THRESHOLD_DPS        50.0f
#define SAMPLE_PERIOD_US     50000       /* 20 Hz */
#define CAL_SAMPLES          100
#define LOG_FILE             "gyro_log.txt"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ---- Signal handler ---- */
static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ---- */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_write_reg8(0x%02X, 0x%02X) failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8 write(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, out, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8 read(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *out)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg16 write(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_read_reg16 read(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = (int16_t)((uint16_t)buf[1] << 8 | buf[0]);
    return 0;
}

/* ---- Gyroscope ---- */
static int gyro_init(int fd)
{
    uint8_t who;
    if (i2c_read_reg8(fd, L3G4200D_WHO_AM_I, &who) != 0)
        return -1;
    if (who != L3G4200D_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, L3G4200D_WHO_AM_I_VAL);
        return -1;
    }
    if (i2c_write_reg8(fd, L3G4200D_CTRL_REG1, 0x00) != 0)
        return -1;   /* reset */
    if (i2c_write_reg8(fd, L3G4200D_CTRL_REG4, 0x00) != 0)
        return -1;   /* 250 dps, 8 kHz ODR */
    return 0;
}

static int gyro_read(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    if (i2c_read_reg16(fd, L3G4200D_OUT_X_L, x) != 0) return -1;
    if (i2c_read_reg16(fd, L3G4200D_OUT_Y_L, y) != 0) return -1;
    if (i2c_read_reg16(fd, L3G4200D_OUT_Z_L, z) != 0) return -1;
    return 0;
}

/* ---- Calibration ---- */
static int gyro_calibrate(int fd, float *x_off, float *y_off, float *z_off)
{
    int16_t x, y, z;
    long sx = 0, sy = 0, sz = 0;
    int n = 0;

    printf("Calibrating gyroscope (%d samples)...\n", CAL_SAMPLES);
    for (int i = 0; i < CAL_SAMPLES && g_running; i++) {
        if (gyro_read(fd, &x, &y, &z) != 0) {
            fprintf(stderr, "Calibration read failed at sample %d\n", i);
            return -1;
        }
        sx += x;
        sy += y;
        sz += z;
        usleep(10000);  /* 10 ms between samples */
        n++;
    }
    if (n == 0) {
        fprintf(stderr, "Calibration failed: no samples taken\n");
        return -1;
    }
    *x_off = (float)sx / n;
    *y_off = (float)sy / n;
    *z_off = (float)sz / n;
    printf("Calibration complete: X=%.2f Y=%.2f Z=%.2f\n",
           *x_off, *y_off, *z_off);
    return 0;
}

/* ---- Logging ---- */
static void log_data(FILE *fp, float x, float y, float z)
{
    char ts[32];
    time_t t = time(NULL);
    struct tm tmv;
    if (localtime_r(&t, &tmv) != NULL)
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tmv);
    else
        snprintf(ts, sizeof(ts), "1970-01-01T00:00:00");
    fprintf(fp, "%s,%.2f,%.2f,%.2f\n", ts, x, y, z);
    fflush(fp);
}

static void log_alert(FILE *fp, float x, float y, float z)
{
    char ts[32];
    time_t t = time(NULL);
    struct tm tmv;
    if (localtime_r(&t, &tmv) != NULL)
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tmv);
    else
        snprintf(ts, sizeof(ts), "1970-01-01T00:00:00");
    fprintf(fp, "%s,ALERT,X=%.2f,Y=%.2f,Z=%.2f\n", ts, x, y, z);
    fflush(fp);
    fprintf(stderr, "ALERT: X=%.2f Y=%.2f Z=%.2f\n", x, y, z);
}

/* ---- Main ---- */
int main(void)
{
    float x_off = 0.0f, y_off = 0.0f, z_off = 0.0f;

    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 */
    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(/dev/i2c-1) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, L3G4200D_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                L3G4200D_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* Initialize / verify sensor */
    if (gyro_init(g_i2c_fd) != 0) {
        fprintf(stderr, "Gyroscope not detected or init failed\n");
        fclose(g_log_fp);
        g_log_fp = NULL;
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* Calibrate */
    if (gyro_calibrate(g_i2c_fd, &x_off, &y_off, &z_off) != 0) {
        fprintf(stderr, "Calibration failed; continuing without offsets\n");
    }

    printf("Logging to %s at 20 Hz. Press Ctrl-C to stop.\n", LOG_FILE);

    /* Main loop */
    while (g_running) {
        int16_t rx, ry, rz;
        if (gyro_read(g_i2c_fd, &rx, &ry, &rz) != 0) {
            fprintf(stderr, "Gyro read error; continuing\n");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        float x = (float)rx - x_off;
        float y = (float)ry - y_off;
        float z = (float)rz - z_off;

        log_data(g_log_fp, x, y, z);

        if (fabsf(x) > THRESHOLD_DPS || fabsf(y) > THRESHOLD_DPS || fabsf(z) > THRESHOLD_DPS) {
            log_alert(g_log_fp, x, y, z);
        }

        usleep(SAMPLE_PERIOD_US);
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return EXIT_SUCCESS;
}

