#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define ADXL345_ADDRESS 0x48
#define ADXL345_REG_DEVID 0x00
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_DATA_FORMAT 0x31
#define ADXL345_REG_DATAX0 0x32
#define ADXL345_DEVID_VALUE 0xE5
#define ADXL345_FULL_RES_MODE 0x08
#define ADXL345_RANGE_2G 0x00
#define ACCEL_THRESHOLD_G 2.0f
#define LED_GPIO 17
#define SAMPLE_INTERVAL_US 100000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int adxl345_init(void) {
    int devid = i2cReadByteData(i2c_handle, ADXL345_REG_DEVID);
    if (devid < 0) {
        fprintf(stderr, "Error: I2C read failed for DEVID register: %d\n", devid);
        return -1;
    }
    if (devid != ADXL345_DEVID_VALUE) {
        fprintf(stderr, "Error: ADXL345 not detected (DEVID=0x%02X, expected 0x%02X)\n",
                devid & 0xFF, ADXL345_DEVID_VALUE);
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, ADXL345_REG_DATA_FORMAT, ADXL345_RANGE_2G) < 0) {
        fprintf(stderr, "Error: Failed to set DATA_FORMAT register\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, ADXL345_REG_POWER_CTL, ADXL345_FULL_RES_MODE) < 0) {
        fprintf(stderr, "Error: Failed to set POWER_CTL register\n");
        return -1;
    }

    return 0;
}

static int read_acceleration(float *x, float *y, float *z) {
    char buffer[6];
    int16_t raw_x, raw_y, raw_z;

    if (i2cReadI2CBlockData(i2c_handle, ADXL345_REG_DATAX0, buffer, 6) != 6) {
        fprintf(stderr, "Error: I2C block read failed\n");
        return -1;
    }

    raw_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    raw_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    raw_z = (int16_t)((buffer[5] << 8) | buffer[4]);

    *x = (float)raw_x / 256.0f;
    *y = (float)raw_y / 256.0f;
    *z = (float)raw_z / 256.0f;

    return 0;
}

static void log_data(float x, float y, float z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, x, y, z);
    fflush(log_file);
}

static void check_threshold(float x, float y, float z) {
    if (fabsf(x) > ACCEL_THRESHOLD_G || fabsf(y) > ACCEL_THRESHOLD_G || fabsf(z) > ACCEL_THRESHOLD_G) {
        gpioWrite(LED_GPIO, 1);
    } else {
        gpioWrite(LED_GPIO, 0);
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, ADXL345_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (adxl345_init() < 0) {
        fprintf(stderr, "Error: ADXL345 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen("accel_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        cleanup();
        return EXIT_FAILURE;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float x, y, z;

    while (!terminate) {
        if (read_acceleration(&x, &y, &z) == 0) {
            log_data(x, y, z);
            check_threshold(x, y, z);
        } else {
            fprintf(stderr, "Warning: Failed to read acceleration data\n");
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

