/*
 * compass.c — GY-51 LSM303DLHC compass on Raspberry Pi Zero W
 *
 * Wiring (I2C bus 1):
 *   LSM303DLHC VIN  -> Pi 3V3 (pin 1)
 *   LSM303DLHC GND  -> Pi GND  (pin 9)
 *   LSM303DLHC SDA  -> Pi GPIO2 / SDA1 (pin 3)
 *   LSM303DLHC SCL  -> Pi GPIO3 / SCL1 (pin 5)
 *
 * Build:  gcc -O2 -Wall -Wextra -o compass compass.c -lm
 * Run:    ./compass
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- LSM303DLHC I2C addresses ---- */
#define LSM303_ACCEL_ADDR  0x19
#define LSM303_MAG_ADDR    0x1E

/* ---- LSM303DLHC registers ---- */
#define LSM303_ACCEL_WHO_AM_I 0x0F
#define LSM303_ACCEL_CTRL_REG1 0x20
#define LSM303_ACCEL_OUT_X_L   0x28
#define LSM303_MAG_WHO_AM_I    0x0F
#define LSM303_MAG_MR_REG      0x02
#define LSM303_MAG_OUT_X_L     0x28

/* ---- Conversion constants ---- */
#define ACCEL_SCALE  0.000061f   /* g/LSB  (±2 g range) */
#define MAG_SCALE    0.00014f   /* G/LSB (1.3 gauss range) */

#define I2C_BUS        "/dev/i2c-1"
#define LOG_FILE       "compass_log.txt"
#define SAMPLE_PERIOD_US 100000  /* 100 ms */

/* ---- Globals for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static int g_accel_fd = -1;
static int g_mag_fd   = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8: write reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "i2c_read_reg8: read reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_write_reg8: write reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_burst: write reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "i2c_read_burst: read %zu bytes from 0x%02X failed: %s\n",
                len, reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* LSM303DLHC driver                                                    */
/* ------------------------------------------------------------------ */

static int accel_init(void)
{
    uint8_t whoami = 0;
    if (i2c_read_reg8(g_accel_fd, LSM303_ACCEL_WHO_AM_I, &whoami) != 0)
        return -1;
    if (whoami != 0xD0) {
        fprintf(stderr, "Accel WHO_AM_I mismatch: 0x%02X (expected 0xD0)\n", whoami);
        return -1;
    }

    /* CTRL_REG1: accel enable, ODR = 100 Hz (0x57) */
    if (i2c_write_reg8(g_accel_fd, LSM303_ACCEL_CTRL_REG1, 0x57) != 0)
        return -1;
    return 0;
}

static int mag_init(void)
{
    uint8_t whoami = 0;
    if (i2c_read_reg8(g_mag_fd, LSM303_MAG_WHO_AM_I, &whoami) != 0)
        return -1;
    if (whoami != 0xD5) {
        fprintf(stderr, "Mag WHO_AM_I mismatch: 0x%02X (expected 0xD5)\n", whoami);
        return -1;
    }

    /* MR_REG: temp comp, ultra-high perf, normal mode (0x0C) */
    if (i2c_write_reg8(g_mag_fd, LSM303_MAG_MR_REG, 0x0C) != 0)
        return -1;
    return 0;
}

static int accel_read(float *ax, float *ay, float *az)
{
    uint8_t buf[6];
    if (i2c_read_burst(g_accel_fd, LSM303_ACCEL_OUT_X_L | 0x80, buf, 6) != 0)
        return -1;

    int16_t x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t z = (int16_t)((buf[5] << 8) | buf[4]);

    *ax = (float)x * ACCEL_SCALE;
    *ay = (float)y * ACCEL_SCALE;
    *az = (float)z * ACCEL_SCALE;
    return 0;
}

static int mag_read(float *mx, float *my, float *mz)
{
    uint8_t buf[6];
    if (i2c_read_burst(g_mag_fd, LSM303_MAG_OUT_X_L | 0x80, buf, 6) != 0)
        return -1;

    int16_t x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t z = (int16_t)((buf[5] << 8) | buf[4]);

    *mx = (float)x * MAG_SCALE;
    *my = (float)y * MAG_SCALE;
    *mz = (float)z * MAG_SCALE;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Tilt-compensated heading                                               */
/* ------------------------------------------------------------------ */

static float heading_compensated(float ax, float ay, float az,
                                  float mx, float my, float mz)
{
    float roll  = atan2f(ay, az);
    float pitch = atan2f(-ax, sqrtf(ay * ay + az * az));

    float mx_comp = mx * cosf(pitch) + mz * sinf(pitch);
    float my_comp = mx * sinf(roll) * sinf(pitch) + my * cosf(roll) - mz * sinf(roll) * sinf(pitch);

    return atan2f(my_comp, mx_comp) * 180.0f / (float)M_PI;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */

static void log_sample(float heading, float ax, float ay, float az,
                       float mx, float my, float mz)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        return;
    }

    /* Write CSV header if file is empty */
    long pos = ftell(fp);
    if (pos == 0) {
        fprintf(fp, "timestamp,heading_deg,ax_g,ay_g,az_g,mx_g,my_g,mz_g\n");
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s,%.2f,%.4f,%.4f,%.4f,%.4f,%.4f,%.4f\n",
                ts, heading, ax, ay, az, mx, my, mz);
    } else {
        fprintf(stderr, "localtime_r failed\n");
    }

    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_accel_fd = open(I2C_BUS, O_RDWR);
    if (g_accel_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    g_mag_fd = open(I2C_BUS, O_RDWR);
    if (g_mag_fd < 0) {
        fprintf(stderr, "open(%s) failed for mag: %s\n", I2C_BUS, strerror(errno));
        close(g_accel_fd);
        return EXIT_FAILURE;
    }

    /* Acquire accel device */
    if (ioctl(g_accel_fd, I2C_SLAVE, LSM303_ACCEL_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE accel) failed: %s\n", strerror(errno));
        goto fail;
    }
    if (accel_init() != 0) {
        fprintf(stderr, "Accel init failed\n");
        goto fail;
    }

    /* Acquire mag device */
    if (ioctl(g_mag_fd, I2C_SLAVE, LSM303_MAG_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE mag) failed: %s\n", strerror(errno));
        goto fail;
    }
    if (mag_init() != 0) {
        fprintf(stderr, "Mag init failed\n");
        goto fail;
    }

    printf("LSM303DLHC compass running. Press Ctrl-C to stop.\n");

    while (g_running) {
        float ax, ay, az, mx, my, mz;

        if (accel_read(&ax, &ay, &az) != 0) {
            fprintf(stderr, "Accel read error — continuing\n");
        } else if (mag_read(&mx, &my, &mz) != 0) {
            fprintf(stderr, "Mag read error — continuing\n");
        } else {
            float heading = heading_compensated(ax, ay, az, mx, my, mz);
            log_sample(heading, ax, ay, az, mx, my, mz);
            printf("Heading: %.2f deg  |  Accel: %.4f,%.4f,%.4f g  |  Mag: %.4f,%.4f,%.4f G\n",
                   heading, ax, ay, az, mx, my, mz);
        }

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");

    if (g_accel_fd >= 0) close(g_accel_fd);
    if (g_mag_fd   >= 0) close(g_mag_fd);

    return EXIT_SUCCESS;

fail:
    if (g_accel_fd >= 0) close(g_accel_fd);
    if (g_mag_fd   >= 0) close(g_mag_fd);
    return EXIT_FAILURE;
}

