/*
 * IMP23ABSU dual-microphone TDOA logger for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   Sensor 1 (S1)  -> I2C bus 1, address 0x20
 *   Sensor 2 (S2)  -> I2C bus 1, address 0x21
 *   VDD  -> 3.3 V
 *   GND -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o tdoa_logger tdoa_logger.c -lm
 *
 * Run:
 *   ./tdoa_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SENSOR1_ADDR   0x20
#define SENSOR2_ADDR   0x21
#define LOG_FILE       "audio_log.dat"
#define SAMPLE_PERIOD  10000   /* microseconds (10 ms) */
#define MAX_RETRIES    3

/* IMP23ABSU 16-bit signed sample register (datasheet example) */
#define SAMPLE_REG     0x00

static volatile sig_atomic_t g_running = 1;
static int g_fd1 = -1;
static int g_fd2 = -1;
static FILE *g_log = NULL;

/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_fd1 >= 0) {
        close(g_fd1);
        g_fd1 = -1;
    }
    if (g_fd2 >= 0) {
        close(g_fd2);
        g_fd2 = -1;
    }
    if (g_log) {
        fclose(g_log);
        g_log = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* Open an I2C device and set the slave address.                        */
static int i2c_open(int addr)
{
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit signed sample from an I2C sensor.                     */
/* Returns 0 on success, -1 on error.                                  */
static int read_sensor16(int fd, int16_t *out)
{
    uint8_t reg = SAMPLE_REG;
    uint8_t buf[2];

    /* Write the register pointer */
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "write(reg) failed: %s\n", strerror(errno));
        return -1;
    }
    /* Read two bytes of sample data */
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "read(sample) failed: %s\n", strerror(errno));
        return -1;
    }
    *out = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
static double calc_tdoa(int16_t s1, int16_t s2)
