/*
 * ADIS16448 IMU reader for Raspberry Pi 4 Model B
 * SPI bus 0, CS0 (GPIO8 / BCM 8), mode 3, max 1 MHz
 * Reads gyroscope and accelerometer data via the single-register read protocol.
 *
 * Build:  gcc -O2 -Wall -o adis16448 adis16448.c -lpigpio -lrt
 * Run:    sudo ./adis16448
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#include <pigpio.h>

/* ---- ADIS16448 register addresses ---- */
#define ADIS16448_REG_GYRO_X_L  0x04
#define ADIS16448_REG_GYRO_X_H  0x05
#define ADIS16448_REG_GYRO_Y_L  0x06
#define ADIS16448_REG_GYRO_Y_H  0x07
#define ADIS16448_REG_GYRO_Z_L  0x08
#define ADIS16448_REG_GYRO_Z_H  0x09
#define ADIS16448_REG_ACCEL_X_L 0x0A
#define ADIS16448_REG_ACCEL_X_H 0x0B
#define ADIS16448_REG_ACCEL_Y_L 0x0C
#define ADIS16448_REG_ACCEL_Y_H 0x0D
#define ADIS16448_REG_ACCEL_Z_L 0x0E
#define ADIS16448_REG_ACCEL_Z_H 0x0F

/* ---- SPI configuration ---- */
#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U   /* 1 MHz */
#define SPI_MODE        SPI_MODE_3
#define SPI_BITS        8
#define SPI_DELAY_US    0

/* ---- Scaling factors ---- */
#define GYRO_SCALE        0.02f   /* dps per LSB */
#define ACCEL_SCALE       0.00025f /* g per LSB */

/* ---- Sampling ---- */
#define SAMPLE_PERIOD_US 100000U  /* 100 ms */

/* ---- Globals for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_spi_fd = -1;
static int  g_pigpio_initialized = 0;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int spi_transfer(int fd, const uint8_t *tx, uint8_t *rx, size_t len)
{
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = len;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = SPI_DELAY_US;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int spi_read_register(int fd, uint8_t reg, int16_t *out)
{
    uint8_t tx[2] = { (uint8_t)(reg | 0x80), 0x00 };
    uint8_t rx[2] = { 0, 0 };

    if (spi_transfer(fd, tx, rx, sizeof(tx)) < 0)
        return -1;

    /* Second 16-bit transfer: read the 16-bit data response */
    tx[0] = 0x00;
    if (spi_transfer(fd, tx, rx, sizeof(rx)) < 0)
        return -1;

    *out = (int16_t)((rx[0] << 8) | rx[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
static int read_gyro(int fd, float *gx, float *gy, float *gz)
{
    int16_t raw;
    if (spi_read_register(fd, ADIS16448_REG_GYRO_X_L, &raw) < 0)
        return -1;
    *gx = (float)raw * GYRO_SCALE;
    if (spi_read_register(fd, ADIS16448_REG_GYRO_Y_L, &raw) < 0)
        return -1;
    *gy = (float)raw * GYRO_SCALE;
    if (spi_read_register(fd, ADIS16448_REG_GYRO_Z_L, &raw) < 0)
        return -1;
    *gz = (float)raw * GYRO_SCALE;
    return 0;
}

/* ------------------------------------------------------------------ */
static int read_accel(int fd, float *ax, float *ay, float *az)
{
    int16_t raw;
    if (spi_read_register(fd, ADIS16448_REG_ACCEL_X_L, &raw) < 0)
        return -1;
    *ax = (float)raw * ACCEL_SCALE;
    if (spi_read_register(fd, ADIS16448_REG_ACCEL_Y_L, &raw) < 0)
        return -1;
    *ay = (float)raw * ACCEL_SCALE;
    if (spi_read_register(fd, ADIS16448_REG_ACCEL_Z_L, &raw) < 0)
        return -1;
    *az = (float)raw * ACCEL_SCALE;
    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    if (g_pigpio_initialized) {
        gpioTerminate();
        g_pigpio_initialized = 0;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }
    g_pigpio_initialized = 1;

    /* ---- Open SPI device ---- */
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", SPI_DEVICE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    uint8_t mode = SPI_MODE;
    uint8_t bits = SPI_BITS;
    uint32_t speed = SPI_SPEED_HZ;

    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ADIS16448 SPI reader started. Press Ctrl+C to stop.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        float gx, gy, gz, ax, ay, az;

        if (read_gyro(g_spi_fd, &gx, &gy, &gz) < 0) {
            fprintf(stderr, "Gyro read error; continuing.\n");
        } else if (read_accel(g_spi_fd, &ax, &ay, &az) < 0) {
            fprintf(stderr, "Accel read error; continuing.\n");
        } else {
            printf("Gyro: X=%.3f dps, Y=%.3f dps, Z=%.3f dps | "
                   "Accel: X=%.3f g, Y=%.3f g, Z=%.3f g\n",
                   gx, gy, gz, ax, ay, az);
        }

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

