        close(g_spi_fd);
        g_spi_fd = -1;
    }
    if (g_pigpio_initialized) {
        gpioTerminate();
        g_pigpio_initialized = 0;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }
    g_pigpio_initialized = 1;

    /* ---- Open SPI device ---- */
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", SPI_DEVICE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    uint8_t mode = SPI_MODE;
    uint8_t bits = SPI_BITS;
    uint32_t speed = SPI_SPEED_HZ;

    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ADIS16448 SPI reader started. Press Ctrl+C to stop.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        float gx, gy, gz, ax, ay, az;

        if (read_gyro(g_spi_fd, &gx, &gy, &gz) < 0) {
            fprintf(stderr, "Gyro read error; continuing.\n");
        } else if (read_accel(g_spi_fd, &ax, &ay, &az) < 0) {
            fprintf(stderr, "Accel read error; continuing.\n");
        } else {
            printf("Gyro: X=%.3f dps, Y=%.3f dps, Z=%.3f dps | "
                   "Accel: X=%.3f g, Y=%.3f g, Z=%.3f g\n",
                   gx, gy, gz, ax, ay, az);
        }

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

