#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- ADIS16448 register addresses ---- */
#define ADIS16448_REG_GYRO_X_L  0x04
#define ADIS16448_REG_GYRO_X_H  0x05
#define ADIS16448_REG_GYRO_Y_L  0x06
#define ADIS16448_REG_GYRO_Y_H  0x07
#define ADIS16448_REG_GYRO_Z_L  0x08
#define ADIS16448_REG_GYRO_Z_H  0x09
#define ADIS16448_REG_ACCEL_X_L 0x0A
#define ADIS16448_REG_ACCEL_X_H 0x0B
#define ADIS16448_REG_ACCEL_Y_L 0x0C
#define ADIS16448_REG_ACCEL_Y_H 0x0D
#define ADIS16448_REG_ACCEL_Z_L 0x0E
#define ADIS16448_REG_ACCEL_Z_H 0x0F

/* ---- SPI parameters ---- */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000          /* 1 MHz */
#define SPI_FLAGS   0                /* Mode 0, active-low CE */

/* ---- Scaling factors (datasheet) ---- */
#define GYRO_SCALE  0.05f            /* deg/sec per LSB */
#define ACCEL_SCALE 0.00025f         /* g per LSB */

/* ---- Timing ---- */
#define STALL_US  40                /* ADIS16448 stall after first transfer */

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;                 /* let main loop exit cleanly       */
}

/* ------------------------------------------------------------------ */
/* Read one 16-bit register (two 16-bit transfers: cmd + dummy).      */
/* Returns 0 on success, -1 on SPI error.                              */
/* ------------------------------------------------------------------ */
static int read_register(uint8_t reg, int16_t *out)
{
    char tx[2], rx[2];
    int  ret;

    tx[0] = (char)(reg | 0x80);   /* bit 15 = 1 -> read command        */
    tx[1] = 0x00;

    ret = spiXfer(g_spi_handle, tx, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI read command failed for reg 0x%02X (ret=%d)\n",
