    gpioDelay(STALL_US);           /* stall >= 40 us per datasheet      */

    tx[0] = 0x00;
    tx[1] = 0x00;

    ret = spiXfer(g_spi_handle, tx, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI dummy transfer failed for reg 0x%02X (ret=%d)\n",
                reg, ret);
        return -1;
