           SPI_CHANNEL, SPI_SPEED);
    printf("Press Ctrl-C to stop.\n\n");

    /* ---- Main loop ---- */
    while (g_running) {
        rc = read_gyro(&gx, &gy, &gz);
        if (rc != 0) {
            fprintf(stderr, "Gyro read failed; continuing\n");
            rc = read_accel(&ax, &ay, &az);
            if (rc != 0) {
                fprintf(stderr, "Accel read failed; continuing\n");
            }
            gpioDelay(100000);          /* 100 ms */
            continue;
        }

        rc = read_accel(&ax, &ay, &az);
        if (rc != 0) {
            fprintf(stderr, "Accel read failed; continuing\n");
        }

        printf("Gyro: X=%7.2f  Y=%7.2f  Z=%7.2f  deg/sec\n",
               gx * GYRO_SCALE, gy * GYRO_SCALE, gz * GYRO_SCALE);
        printf("Accel: X=%7.2f  Y=%7.2f  Z=%7.2f  g\n",
               ax * ACCEL_SCALE, ay * ACCEL_SCALE, az * ACCEL_SCALE);
        printf("---\n");

        gpioDelay(100000);            /* 100 ms */
    }

    /* ---- Clean shutdown ---- */
    printf("\nShutting down...\n");
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

