static int i2c_read_reg16(int fd, uint8_t reg, int16_t *out)
{
    uint8_t buf[2];
    ssize_t n = read(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s (read %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    *out = (int16_t)((uint16_t)buf[0] | ((uint16_t)buf[1] << 8));
    return 0;
}

/* Initialize the MPU-6886: wake, configure, and verify. Returns 0 on success, -1 on error. */
static int mpu6886_init(int fd)
{
    /* Wake up: clear SLEEP bit in PWR_MGMT_1 */
    if (i2c_write_reg8(fd, REG_PWR_MGMT_1, 0x00) < 0)
        return -1;
    usleep(100000); /* allow oscillator to stabilize */

    /* Sample rate divider = 7 → 1 kHz / (1 + 7) = 125 Hz */
    if (i2c_write_reg8(fd, REG_SMPLRT_DIV, 0x07) < 0)
        return -1;

    /* DLPF_CFG = 3 → 8 Hz bandwidth, 1.2 ms delay */
    if (i2c_write_reg8(fd, REG_CONFIG, 0x03) < 0)
        return -1;

    /* Verify device presence by reading PWR_MGMT_2 (should be 0x00) */
    int2c = i2c_read_reg16(fd, REG_PWR_MGMT_2, NULL);
    if (int2c < 0)
        return -1;
    if (int2c != 0x00) {
        fprintf(stderr, "PWR_MGMT_2 read mismatch: got 0x%02X, expected 0x00\n", int2c);
        return -1;
    }

    return 0;
}

int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    /* Install SIGINT handler for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the I2C bus */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the MPU-6886 slave address */
    if (ioctl(fd, I2C_SLAVE, MPU6886_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                MPU6886_ADDR, strerror(errno));
        goto cleanup;
    }

    /* Initialize the sensor */
    if (mpu6886_init(fd) < 0) {
        fprintf(stderr, "MPU-6886 initialization failed (sensor absent or bus error).\n");
        goto cleanup;
    }

    printf("MPU-6886 initialized. Reading every 50 ms (Ctrl-C to stop)...\n");

    /* Main acquisition loop */
    while (g_running) {
        int16_t accel_x = 0, accel_y = 0, accel_z = 0;
        int16_t gyro_x  = 0, gyro_y  = 0, gyro_z  = 0;

        int ok = 0;
        for (int attempt = 0; attempt < 3 && g_running; attempt++) {
            if (i2c_read_reg16(fd, REG_GYRO_XOUT_H, &gyro_x) == 0 &&
                i2c_read_reg16(fd, REG_GYRO_XOUT_H + 2, &gyro_y) == 0 &&
                i2c_read_reg16(fd, REG_GYRO_XOUT_H + 4, &gyro_z) == 0 &&
                i2c_read_reg16(fd, REG_ACCEL_XOUT_H, &accel_x) == 0 &&
                i2c_read_reg16(fd, REG_ACCEL_XOUT_H + 2, &accel_y) == 0 &&
                i2c_read_reg16(fd, REG_ACCEL_XOUT_H + 4, &accel_z) == 0) {
                ok = 1;
                break;
            }
            usleep(10000); /* 10 ms backoff before retry */
        }

        if (!ok) {
            fprintf(stderr, "Read failed after 3 attempts; continuing.\n");
            continue;
        }

        /* Convert raw values to physical units */
        float accel_x_f = (float)accel_x / ACCEL_SCALE;
        float accel_y_f = (float)accel_y / ACCEL_SCALE;
        float accel_z_f = (float)accel_z / ACCEL_SCALE;
        float gyro_x_f  = (float)gyro_x  / GYRO_SCALE;
        float gyro_y_f  = (float)gyro_y  / GYRO_SCALE;
        float gyro_z_f  = (float)gyro_z  / GYRO_SCALE;

        printf("Accel: X=%.2f g, Y=%.2f g, Z=%.2f g | Gyro: X=%.2f °/s, Y=%.2f °/s, Z=%.2f °/s\n",
               accel_x_f, accel_y_f, accel_z_f,
               gyro_x_f, gyro_y_f, gyro_z_f);

        usleep(50000); /* 50 ms sampling interval */
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0)
        close(fd);
    return rc;
}

