/*
 * ADXL345 Impact Detector for Raspberry Pi Zero W
 *
 * Wiring:
 *   ADXL345 SDA -> GPIO2 (I2C bus 1 SDA)
 *   ADXL345 SCL -> GPIO3 (I2C bus 1 SCL)
 *   ADXL345 VCC -> 3.3 V
 *   ADXL345 GND -> GND
 *   Red LED     -> GPIO17 (BCM) with 330 ohm series resistor
 *
 * Build: gcc -O2 -Wall -o impact impact.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADXL345_ADDR   0x48
#define ADXL345_REG_DEVID 0x00
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_DATAX0 0x32
#define ADXL345_REG_BW_RATE 0x2C
#define ADXL345_REG_FILTER_CTL 0x2C
#define ADXL345_DEVID_VAL 0xE5

#define LED_GPIO        17
#define IMPACT_THRESHOLD_G 2.5f
#define SCALE_FACTOR    256.0f   /* LSB/g for ±2 g full resolution */
#define POLL_INTERVAL_US 10000   /* 10 ms */
#define LED_ON_TIME_US  500000   /* 500 ms */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, out, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C burst read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* ADXL345 helpers                                                     */
/* ------------------------------------------------------------------ */
static int adxl345_init(int fd)
{
    uint8_t devid = 0;
    if (i2c_read_reg8(fd, ADXL345_REG_DEVID, &devid) != 0)
        return -1;
    if (devid != ADXL345_DEVID_VAL) {
        fprintf(stderr, "ADXL345 not detected (DEVID=0x%02X, expected 0x%02X)\n",
                devid, ADXL345_DEVID_VAL);
        return -1;
    }

    /* Standby first so filter config takes effect */
    if (i2c_write_reg8(fd, ADXL345_REG_POWER_CTL, 0x00) != 0)
        return -1;
    usleep(1000);

    /* ±2 g full resolution, 100 Hz ODR */
    if (i2c_write_reg8(fd, ADXL345_REG_BW_RATE, 0x0A) != 0)
        return -1;
    if (i2c_write_reg8(fd, ADXL345_REG_FILTER_CTL, 0x00) != 0)
        return -1;
    if (i2c_write_reg8(fd, ADXL345_REG_POWER_CTL, 0x08) != 0)
        return -1;
    usleep(1000);
    return 0;
}

static int adxl345_read_xyz(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t buf[6];
    if (i2c_read_burst(fd, ADXL345_REG_DATAX0, buf, 6) != 0)
        return -1;
    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Impact detection                                                    */
/* ------------------------------------------------------------------ */
static bool is_impact(float x, float y, float z)
{
    float mag = sqrtf(x * x + y * y + z * z);
    return mag > IMPACT_THRESHOLD_G;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_impact(float x, float y, float z, float mag)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(g_log_fp, "%s, X=%.2f, Y=%.2f, Z=%.2f, Mag=%.2f g\n",
            ts, x, y, z, mag);
    fflush(g_log_fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- LED GPIO --- */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* --- I2C --- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, ADXL345_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                ADXL345_ADDR, strerror(errno));
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- ADXL345 init --- */
    if (adxl345_init(g_i2c_fd) != 0) {
        fprintf(stderr, "ADXL345 initialisation failed\n");
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Log file --- */
    g_log_fp = fopen("impact_log.txt", "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open impact_log.txt: %s\n", strerror(errno));
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signals --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ADXL345 impact detector running. Press Ctrl+C to exit.\n");

    /* --- Main loop --- */
    while (g_running) {
        int16_t x, y, z;
        if (adxl345_read_xyz(g_i2c_fd, &x, &y, &z) != 0) {
            fprintf(stderr, "Read error; continuing after 100 ms\n");
            usleep(100000);
            continue;
        }

        float fx = (float)x / SCALE_FACTOR;
        float fy = (float)y / SCALE_FACTOR;
        float fz = (float)z / SCALE_FACTOR;

        if (is_impact(fx, fy, fz)) {
            printf("Impact detected! X=%.2f Y=%.2f Z=%.2f g\n", fx, fy, fz);
            gpioWrite(LED_GPIO, 1);
            log_impact(fx, fy, fz, sqrtf(fx * fx + fy * fy + fz * fz));
            gpioDelay(LED_ON_TIME_US);
            gpioWrite(LED_GPIO, 0);
        }

        usleep(POLL_INTERVAL_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

