 *   ICM-20602 SDA  -> GPIO2 (pin 3, I2C bus 1 SDA)
 *   ICM-20602 SCL  -> GPIO3 (pin 5, I2C bus 1 SCL)
 *   ICM-20602 VDD  -> 3.3 V
 *   ICM-20602 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -o imu_logger imu_logger.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS        1
#define ICM20602_ADDR  0x68

/* ICM-20602 register addresses */
#define REG_WHO_AM_I    0x75
#define WHO_AM_I_VAL    0x68
#define REG_PWR_MGMT_1  0x6B
#define REG_GYRO_XOUT_H 0x43
#define REG_ACCEL_XOUT_H 0x3B

#define SAMPLE_PERIOD_US 100000  /* 100 ms -> 10 Hz */

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void log_error(const char *msg)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    if (t)
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    else
        snprintf(ts, sizeof(ts), "unknown-time");

    fprintf(stderr, "[%s] ERROR: %s (errno=%d: %s)\n",
            ts, msg, errno, strerror(errno));
}

/* ------------------------------------------------------------------ */
static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc < 0) {
        log_error("i2cReadI2CBlockData failed");
        return -1;
    }
    if ((uint32_t)rc != len) {
        log_error("i2cReadI2CBlockData short read");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int init_imu(void)
{
    int handle = i2cOpen(I2C_BUS, ICM20602_ADDR, 0);
    if (handle < 0) {
        log_error("i2cOpen failed");
        return -1;
    }

    /* Verify device identity */
    int who = i2cReadByteData(handle, REG_WHO_AM_I);
    if (who < 0) {
        log_error("Failed to read WHO_AM_I register");
        i2cClose(handle);
        return -1;
    }
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, WHO_AM_I_VAL);
        i2cClose(handle);
        return -1;
    }

    /* Wake up: clear SLEEP bit in PWR_MGMT_1 (0x6B) */
    if (i2cWriteByteData(handle, REG_PWR_MGMT_1, 0x00) < 0) {
        log_error("Failed to write PWR_MGMT_1");
        i2cClose(handle);
        return -1;
    }
    gpioDelay(10000);  /* 10 ms settle */

    return handle;
}

/* ------------------------------------------------------------------ */
static int read_imu_data(int handle, int16_t *ax, int16_t *ay, int16_t *az,
                         int16_t *gx, int16_t *gy, int16_t *gz)
{
    uint8_t buf[12];

    if (i2c_read_block(handle, REG_ACCEL_XOUT_H, buf, 6) < 0)
        return -1;
    *ax = (int16_t)((buf[0]  << 8) | buf[1]);
    *ay = (int16_t)((buf[2]  << 8) | buf[3]);
    *az = (int16_t)((buf[4]  << 8) | buf[5]);

    if (i2c_read_block(handle, REG_GYRO_XOUT_H, buf, 6) < 0)
        return -1;
    *gx = (int16_t)((buf[0]  << 8) | buf[1]);
    *gy = (int16_t)((buf[2]  << 8) | buf[3]);
    *gz = (int16_t)((buf[4]  << 8) | buf[5]);

    return 0;
}

/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, int16_t ax, int16_t ay, int16_t az,
                     int16_t gx, int16_t gy, int16_t gz)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    if (t)
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    else
        snprintf(ts, sizeof(ts), "unknown-time");

    fprintf(fp, "%s,%d,%d,%d,%d,%d,%d\n",
            ts, ax, ay, az, gx, gy, gz);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        log_error("sigaction(SIGINT) failed");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        log_error("gpioInitialise failed");
        return EXIT_FAILURE;
    }

    g_i2c_handle = init_imu();
    if (g_i2c_handle < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen("imu_log.csv", "a");
    if (!g_log_file) {
        log_error("fopen(imu_log.csv) failed");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_file) == 0)
        fprintf(g_log_file, "timestamp,accel_x,accel_y,accel_z,gyro_x,gyro_y,gyro_z\n");

    printf("Logging ICM-20602 data to imu_log.csv at 10 Hz. Press Ctrl+C to stop.\n");

    while (g_running) {
        int16_t ax, ay, az, gx, gy, gz;
        if (read_imu_data(g_i2c_handle, &ax, &ay, &az, &gx, &gy, &gz) == 0) {
            log_data(g_log_file, ax, ay, az, gx, gy, gz);
        } else {
            log_error("Failed to read IMU data");
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    if (g_log_file)  fclose(g_log_file);
    if (g_i2c_handle >= 0) i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

