/*
 * GY-45 MMA8451Q Impact Detector for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   MMA8451Q SDA -> GPIO2 (I2C bus 1 SDA)
 *   MMA8451Q SCL -> GPIO3 (I2C bus 1 SCL)
 *   MMA8451Q VDD -> 3.3 V
 *   MMA8451Q GND -> GND
 *   LED anode   -> GPIO17 (BCM) via 330 ohm resistor
 *   LED cathode -> GND
 *
 * Build: gcc -O2 -Wall -o impact impact.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <math.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS        "/dev/i2c-1"
#define MMA8451_ADDR   0x1D

#define REG_ID         0x00
#define REG_STATUS     0x02
#define REG_OUT_X_MSB  0x01
#define REG_OUT_X_LSB  0x02
#define REG_OUT_Y_MSB  0x03
#define REG_OUT_Y_LSB  0x04
#define REG_OUT_Z_MSB  0x05
#define REG_OUT_Z_LSB  0x06
#define REG_CTRL_REG1  0x2A
#define REG_CTRL_REG2  0x2B
#define REG_CTRL_REG3  0x2C
#define REG_CTRL_REG4  0x2D

#define LED_PIN        17
#define IMPACT_THRESHOLD 2.0f   /* 2 g in g units */
#define POLL_DELAY_US  100000   /* 100 ms */
#define LED_ON_DELAY_US 500000 /* 500 ms */

#define ID_VALUE       0x44     /* GY-45 / MMA8451Q ID register value */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read block from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_mma8451(int fd)
{
    uint8_t id = 0;
    if (i2c_read_reg(fd, REG_ID, &id) < 0)
        return -1;
    if (id != ID_VALUE) {
        fprintf(stderr, "MMA8451Q ID mismatch: got 0x%02X, expected 0x%02X\n", id, ID_VALUE);
        return -1;
    }

    /* Standby mode to allow configuration changes */
    if (i2c_write_reg(fd, REG_CTRL_REG1, 0x00) < 0)
        return -1;

    /* CTRL_REG2: 800 Hz ODR, normal mode */
    if (i2c_write_reg(fd, REG_CTRL_REG2, 0x40) < 0)
        return -1;

    /* CTRL_REG3: 4 mg/LSB, high-resolution mode */
    if (i2c_write_reg(fd, REG_CTRL_REG3, 0x08) < 0)
        return -1;

    /* CTRL_REG4: Z-axis high-resolution, +/-2g range */
    if (i2c_write_reg(fd, REG_CTRL_REG4, 0x20) < 0)
        return -1;

    /* CTRL_REG1: enable X/Y/Z axes, normal mode */
    if (i2c_write_reg(fd, REG_CTRL_REG1, 0x0F) < 0)
        return -1;

    return 0;
}

static int read_acceleration(int fd, float *x, float *y, float *z)
{
    uint8_t buf[6];
    if (i2c_read_block(fd, REG_OUT_X_MSB, buf, 6) < 0)
        return -1;

    int16_t raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_y = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t raw_z = (int16_t)((buf[4] << 8) | buf[5]);

    /* +/-2g range: 1 g = 1024 counts */
    *x = (float)raw_x / 1024.0f;
    *y = (float)raw_y / 1024.0f;
    *z = (float)raw_z / 1024.0f;

    return 0;
}

static bool is_impact(float x, float y, float z)
{
    return (fabsf(x) > IMPACT_THRESHOLD ||
            fabsf(y) > IMPACT_THRESHOLD ||
            fabsf(z) > IMPACT_THRESHOLD);
}

static void log_impact(float x, float y, float z)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(g_log_fp, "%s, X: %.2f g, Y: %.2f g, Z: %.2f g\n", ts, x, y, z);
    fflush(g_log_fp);
}

static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, MMA8451_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                MMA8451_ADDR, strerror(errno));
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_mma8451(g_i2c_fd) < 0) {
        fprintf(stderr, "MMA8451Q initialisation failed\n");
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen("impact_log.txt", "a");
    if (!g_log_fp) {
        fprintf(stderr, "Failed to open impact_log.txt: %s\n", strerror(errno));
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MMA8451Q impact detector running. Press Ctrl+C to exit.\n");

    while (g_running) {
        float x, y, z;
        if (read_acceleration(g_i2c_fd, &x, &y, &z) < 0) {
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (is_impact(x, y, z)) {
            printf("Impact detected! X: %.2f g, Y: %.2f g, Z: %.2f g\n", x, y, z);
            gpioWrite(LED_PIN, 1);
            log_impact(x, y, z);
            gpioDelay(LED_ON_DELAY_US);
            gpioWrite(LED_PIN, 0);
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

