#include <linux/i2c-dev.h>

#define TMAG5273_ADDR 0x29
#define I2C_BUS "/dev/i2c-1"
#define LOG_FILE "magnetic_field_log.csv"
#define SAMPLE_INTERVAL_SEC 1

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_sensor(void) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, TMAG5273_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", TMAG5273_ADDR, strerror(errno));
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    if (i2c_write_reg8(i2c_fd, 0x80, 0x00) < 0) {
        fprintf(stderr, "Failed to reset sensor\n");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    usleep(10000);
    return 0;
}

static int read_magnetic_field(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t x_raw, y_raw, z_raw;
    if (i2c_read_reg8(i2c_fd, 0x04, &x_raw) < 0) return -1;
    if (i2c_read_reg8(i2c_fd, 0x06, &y_raw) < 0) return -1;
    if (i2c_read_reg8(i2c_fd, 0x08, &z_raw) < 0) return -1;
    *x = (int16_t)((x_raw << 8) | y_raw);
    *y = (int16_t)((y_raw << 8) | z_raw);
    *z = (int16_t)((z_raw << 8) | x_raw);
    return 0;
}

static int log_data(FILE *fp, int16_t x, int16_t y, int16_t z) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }
    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, x, y, z) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int ensure_log_header(void) {
    FILE *check = fopen(LOG_FILE, "r");
    if (check) {
        fclose(check);
        return 0;
    }
    if (errno != ENOENT) {
        fprintf(stderr, "Error checking log file: %s\n", strerror(errno));
        return -1;
    }
    log_fp = fopen(LOG_FILE, "w");
    if (!log_fp) {
        fprintf(stderr, "Failed to create log file: %s\n", strerror(errno));
        return -1;
    }
    if (fprintf(log_fp, "timestamp,x,y,z\n") < 0) {
        fprintf(stderr, "Failed to write header: %s\n", strerror(errno));
        fclose(log_fp);
        log_fp = NULL;
        return -1;
    }
    if (fflush(log_fp) != 0) {
        fprintf(stderr, "fflush header failed: %s\n", strerror(errno));
        fclose(log_fp);
        log_fp = NULL;
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction SIGINT failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction SIGTERM failed: %s\n", strerror(errno));
        return 1;
    }
    if (ensure_log_header() < 0) {
        return 1;
    }
    if (init_sensor() < 0) {
        return 1;
    }
    while (running) {
        int16_t x, y, z;
        if (read_magnetic_field(&x, &y, &z) == 0) {
            if (log_data(log_fp, x, y, z) < 0) {
                fprintf(stderr, "Logging failed, continuing...\n");
            }
        } else {
            fprintf(stderr, "Sensor read failed, continuing...\n");
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    return 0;
}

