/*
 * ADXL345 Free-Fall Detector for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   ADXL345 SDA  -> GPIO2  (physical pin 3, I2C bus 1)
 *   ADXL345 SCL  -> GPIO3  (physical pin 5, I2C bus 1)
 *   ADXL345 INT1 -> GPIO17 (physical pin 11, BCM 17)
 *   ADXL345 VCC  -> 3.3 V
 *   ADXL345 GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o freefall freefall.c -lpigpio -lrt
 *   (pigpio must be installed; run as root or with appropriate permissions.)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <pigpio.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADXL345_ADDR   0x48
#define ADXL345_REG_DEVID 0x00
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_DATAX0 0x32
#define ADXL345_REG_INT_ENABLE 0x2E
#define ADXL345_REG_INT_MAP 0x2F
#define ADXL345_REG_INT_SOURCE 0x30
#define ADXL345_REG_DATA_FORMAT 0x31
#define ADXL345_REG_BW_RATE 0x2C
#define ADXL345_REG_FILTER_CTL 0x2A
#define ADXL345_DEVID_EXPECTED 0xE5

#define GPIO_INT_PIN 17
#define LOG_FILE "freefall_log.csv"

static volatile sig_atomic_t g_running = 1;
static volatile sig_atomic_t g_freefall_active = 0;
static volatile uint32_t g_freefall_start_tick = 0;
static int g_i2c_fd = -1;
static int g_log_fd = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int adxl345_init(int fd)
{
    uint8_t devid = 0;
    if (i2c_read_reg8(fd, ADXL345_REG_DEVID, &devid) != 0) {
        fprintf(stderr, "Cannot read ADXL345 device ID — sensor absent or bus error.\n");
        return -1;
    }
    if (devid != ADXL345_DEVID_EXPECTED) {
        fprintf(stderr, "Unexpected device ID 0x%02X (expected 0x%02X). Wrong sensor?\n",
                devid, ADXL345_DEVID_EXPECTED);
        return -1;
    }

    /* Standby mode before any configuration so configuration writes take effect. */
    if (i2c_write_reg8(fd, ADXL345_REG_POWER_CTL, 0x00) != 0)
        return -1;

    /* Data format: full resolution, +/- 2 g range, right-justified, 4-wire. */
    if (i2c_write_reg8(fd, ADXL345_REG_DATA_FORMAT, 0x0B) != 0)
        return -1;

    /* Bandwidth rate: 100 Hz. */
    if (i2c_write_reg8(fd, ADXL345_REG_BW_RATE, 0x0A) != 0)
        return -1;

    /* Filter control: 4 samples average, 100 Hz ODR. */
    if (i2c_write_reg8(fd, ADXL345_REG_FILTER_CTL, 0x0B) != 0)
        return -1;

    /* Enable free-fall interrupt on INT1. */
    if (i2c_write_reg8(fd, ADXL345_REG_INT_ENABLE, 0x04) != 0)
        return -1;

    /* Map all interrupts to INT1. */
    if (i2c_write_reg8(fd, ADXL345_REG_INT_MAP, 0x01) != 0)
        return -1;

    /* Power on, measurement mode. */
    if (i2c_write_reg8(fd, ADXL345_REG_POWER_CTL, 0x08) != 0)
        return -1;

    return 0;
}

static int read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t buf[6];
    if (write(fd, (uint8_t[]){ADXL345_REG_DATAX0}, 1) != 1) {
        fprintf(stderr, "I2C write (reg select) failed: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, buf, 6) != 6) {
        fprintf(stderr, "I2C read of 6 bytes failed: %s\n", strerror(errno));
        return -1;
    }
    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

static void log_data(FILE *fp, int16_t x, int16_t y, int16_t z)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
        return;
    }
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    int ms = (int)(ts.tv_nsec / 1000000);
    fprintf(fp, "%s.%03d,%d,%d,%d\n", timestamp, ms, x, y, z);
    fflush(fp);
}

static void freefall_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level != 1) {
        /* Only act on rising edge (falling into free-fall). */
        return;
    }

    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
        return;
    }

    g_freefall_active = 1;
    g_freefall_start_tick = (uint32_t)ts.tv_sec * 1000000U + (uint32_t)(ts.tv_nsec / 1000U);
}

static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        /* Disable interrupts before tearing down. */
        if (i2c_write_reg8(g_i2c_fd, ADXL345_REG_INT_ENABLE, 0x00) != 0)
            fprintf(stderr, "Warning: failed to disable interrupts during cleanup.\n");
        i2c_write_reg8(g_i2c_fd, ADXL345_REG_POWER_CTL, 0x00);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_log_fd >= 0) {
        fclose(g_log_fd);
        g_log_fd = -1;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, ADXL345_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                ADXL345_ADDR, strerror(errno));
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (adxl345_init(g_i2c_fd) != 0) {
        fprintf(stderr, "ADXL345 initialisation failed.\n");
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_INT_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input.\n", GPIO_INT_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(GPIO_INT_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO%d.\n", GPIO_INT_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFuncEx(GPIO_INT_PIN, RISING_EDGE, 0, freefall_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR on GPIO%d.\n", GPIO_INT_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_fd = fopen(LOG_FILE, "a");
    if (g_log_fd == NULL) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty. */
    if (ftell(g_log_fd) == 0) {
        fprintf(g_log_fd, "Timestamp,X,Y,Z\n");
        fflush(g_log_fd);
    }

    printf("Free-fall detection started. Logging to %s. Press Ctrl+C to exit.\n", LOG_FILE);

    while (g_running) {
        /* Poll the event file descriptor for up to 100 ms. */
        fd_set fds;
        struct timeval tv;
        FD_ZERO(&fds);
        FD_SET(g_i2c_fd, &fds);
        tv.tv_sec = 0;
        tv.tv_usec = 100000;

        int rc = select(g_i2c_fd + 1, &fds, NULL, NULL, &tv);
        if (rc < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "select() error: %s\n", strerror(errno));
            break;
        }
        if (rc == 0) {
            /* Timeout — no event. */
            continue;
        }

        /* Read the interrupt source to clear it. */
        uint8_t int_src = 0;
        if (i2c_read_reg8(g_i2c_fd, ADXL345_REG_INT_SOURCE, &int_src) != 0) {
            fprintf(stderr, "Warning: could not read INT_SOURCE.\n");
            continue;
        }

        if (int_src & 0x04) {
            /* Free-fall event detected. */
            int16_t x, y, z;
            if (read_acceleration(g_i2c_fd, &x, &y, &z) == 0) {
                log_data(g_log_fd, x, y, z);
            } else {
                fprintf(stderr, "Failed to read acceleration data.\n");
            }
            g_freefall_active = 0;
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

