code:
/*
 * LSM6DSR IMU Fall Detection Logger for Raspberry Pi 3 Model B+
 * Bus: I2C-1 (SDA=GPIO2, SCL=GPIO3)
 * Output: motion_log.txt (CSV: timestamp,ax,ay,az,gx,gy,gz,magnitude,fall_state)
 * Build: gcc -O2 -Wall -o lsm6dsr_fall lsm6dsr_fall.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- LSM6DSR constants ---- */
#define LSM6DSR_ADDR        0x49
#define WHO_AM_I            0x0F
#define WHO_AM_I_VAL        0x6A
#define CTRL1_XL            0x10
#define CTRL2_G             0x11
#define OUTX_L_G            0x22
#define OUTX_L_XL           0x28
#define OUTX_H_G            0x24
#define OUTX_H_XL           0x2A

#define ACCEL_RANGE_2G      0x00
#define GYRO_RANGE_250DPS   0x00
#define ODR_104HZ           0x40

#define FALL_LOW_THRESHOLD  0.2f   /* g */
#define FALL_HIGH_THRESHOLD 2.5f   /* g */
#define FALL_WINDOW_SEC     1.0f   /* seconds */

#define I2C_BUS             "/dev/i2c-1"
#define LOG_FILE            "motion_log.txt"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ---- Signal handler ---- */
static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ---- */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        perror("i2c_write_reg8: write");
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        perror("i2c_read_reg8: write");
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        perror("i2c_read_reg8: read");
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *val)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        perror("i2c_read_reg16: write");
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        perror("i2c_read_reg16: read");
        return -1;
    }
    *val = (int16_t)((buf[1] << 8) | buf[0]);
    return 0;
}

/* ---- Sensor init ---- */
static int init_lsm6dsr(int fd)
{
    uint8_t who;
    if (i2c_read_reg8(fd, WHO_AM_I, &who) < 0) {
        fprintf(stderr, "WHO_AM_I read failed\n");
        return -1;
    }
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, WHO_AM_I_VAL);
        return -1;
    }

    /* ±2 g, ±250 dps, ODR 104 Hz */
    if (i2c_write_reg8(fd, CTRL1_XL, (ACCEL_RANGE_2G << 2) | GYRO_RANGE_250DPS | ODR_104HZ) < 0)
        return -1;
    if (i2c_write_reg8(fd, CTRL2_G, ODR_104HZ) < 0)
        return -1;

    return 0;
}

/* ---- Read 6 axes ---- */
static int read_imu_data(int fd, float *ax, float *ay, float *az,
                         float *gx, float *gy, float *gz)
{
    int16_t rx, ry, rz, gx_raw, gy_raw, gz_raw;

    if (i2c_read_reg16(fd, OUTX_L_XL, &rx) < 0) return -1;
    if (i2c_read_reg16(fd, OUTX_H_XL, &ry) < 0) return -1;
    if (i2c_read_reg16(fd, OUTX_L_G,  &gx_raw) < 0) return -1;
    if (i2c_read_reg16(fd, OUTX_H_G,  &gy_raw) < 0) return -1;
    if (i2c_read_reg16(fd, OUTX_L_G,  &gz_raw) < 0) return -1;

    *ax = (float)rx / 16384.0f;
    *ay = (float)ry / 16384.0f;
    *az = (float)rz / 16384.0f;
    *gx = (float)gx_raw / 131.0f;
    *gy = (float)gy_raw / 131.0f;
    *gz = (float)gz_raw / 131.0f;
    return 0;
}

/* ---- Fall state machine ---- */
static const char *fall_state_str(int state)
{
    switch (state) {
        case 0: return "IDLE";
        case 1: return "FREEFALL";
        case 2: return "IMPACT";
