        }
    } else {
        if (in_freefall) {
            if (mag > FALL_HIGH_THRESHOLD) {
                *state = 2;
                printf("Impact detected (mag=%.3f g)\n", mag);
                in_freefall = 0;
            } else {
                *state = 0;
                in_freefall = 0;
            }
        }
    }
}

/* ---- Logging ---- */
static void log_data(FILE *fp, float ax, float ay, float az,
                     float gx, float gy, float gz, int state)
{
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.4f,%.4f,%.4f,%.4f,%.4f,%.4f,%.4f,%s\n",
            ts, ax, ay, az, gx, gy, gz, mag, fall_state_str(state));
    fflush(fp);
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ---- Main ---- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open " I2C_BUS);
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, LSM6DSR_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        cleanup();
        return EXIT_FAILURE;
    }

    if (init_lsm6dsr(g_i2c_fd) < 0) {
        fprintf(stderr, "LSM6DSR init failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("fopen " LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(g_log_fp, "# timestamp,ax,ay,az,gx,gy,gz,magnitude,fall_state\n");
    fflush(g_log_fp);

    printf("LSM6DSR fall detection started. Ctrl+C to exit.\n");

    while (g_running) {
        float ax, ay, az, gx, gy, gz;
        if (read_imu_data(g_i2c_fd, &ax, &ay, &az, &gx, &gy, &gz) < 0) {
            fprintf(stderr, "I2C read error; continuing\n");
            sleep(1);
            continue;
        }

        float mag = sqrtf(ax * ax + ay * ay + az * az);
        int state = 0;
        fall_detect(ax, ay, az, &state);

        log_data(g_log_fp, ax, ay, az, gx, gy, gz, state);
        usleep(10000); /* 10 ms */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

