/*
 * ADIS16266 Gyroscope SPI Logger for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   ADIS16266 CS  -> GPIO8  (SPI0 CE0, BCM 8)
 *   ADIS16266 SCLK-> GPIO11 (SPI0 SCLK, BCM 11)
 *   ADIS16266 DOUT-> GPIO9  (SPI0 MISO, BCM 9)
 *   ADIS16266 DIN-> GPIO10 (SPI0 MOSI, BCM 10)
 *   ADIS16266 VDD-> 3.3 V
 *   ADIS16266 GND-> GND
 *
 * SPI: mode 3 (CPOL=1, CPHA=1), 1 MHz, 16-bit register access, no dummy byte.
 *   Read command = register address | 0x80.
 *   Write command = register address & 0x7F.
 *
 * Build: gcc -O2 -Wall -o gyro_log gyro_log.c
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U
#define SPI_MODE        SPI_MODE_3
#define SPI_BITS        8
#define SPI_DELAY_US    0

#define GYRO_LOG_FILE   "gyro_log.csv"
#define SAMPLE_PERIOD_US 10000U   /* 10 ms */

/* ADIS16266 register addresses (16-bit, big-endian on the bus) */
#define REG_WHO_AM_I     0x00
#define REG_GYRO_X_MSB  0x01
#define REG_GYRO_X_LSB  0x02
#define REG_GYRO_Y_MSB  0x03
#define REG_GYRO_Y_LSB  0x04
#define REG_GYRO_Z_MSB  0x05
#define REG_GYRO_Z_LSB  0x06
#define REG_TEMP_MSB    0x07
#define REG_TEMP_LSB    0x08
#define REG_INT_CFG     0x09
#define REG_INT_STATUS  0x0A
#define REG_GYRO_CONFIG 0x0B
#define REG_TEMP_CONFIG 0x0C
#define REG_DEVICE_ID   0x0D

#define GYRO_SCALE       0.0305f   /* deg/sec per LSB */
#define WHO_AM_I_EXPECTED 0x53

static volatile sig_atomic_t g_running = 1;
static int  g_spi_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int spi_transfer(int fd, const uint8_t *tx, uint8_t *rx, size_t len)
{
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (uintptr_t)tx;
    tr.rx_buf        = (uintptr_t)rx;
    tr.len           = len;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = SPI_DELAY_US;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int spi_read_reg16(int fd, uint8_t reg, int16_t *out)
{
    uint8_t tx[2] = { (uint8_t)(reg | 0x80), 0x00 };
    uint8_t rx[2] = { 0 };

    if (spi_transfer(fd, tx, rx, sizeof(tx)) < 0)
        return -1;

    /* ADIS16266 returns 16-bit data big-endian */
    *out = (int16_t)(((uint16_t)rx[0] << 8) | rx[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
static int spi_write_reg16(int fd, uint8_t reg, uint16_t val)
{
    uint8_t tx[3] = { (uint8_t)(reg & 0x7F), (uint8_t)(val >> 8), (uint8_t)(val & 0xFF) };
    uint8_t rx[3] = { 0 };

    if (spi_transfer(fd, tx, rx, sizeof(tx)) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
static int verify_who_am_i(int fd)
{
    int16_t val = 0;
    if (spi_read_reg16(fd, REG_WHO_AM_I, &val) < 0)
        return -1;
    if (val != WHO_AM_I_EXPECTED) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%04X, expected 0x%02X\n",
                val, WHO_AM_I_EXPECTED);
        return -1;
    }
    printf("ADIS16266 detected (WHO_AM_I = 0x%02X)\n", val);
    return 0;
}

/* ------------------------------------------------------------------ */
static int log_open(void)
{
    g_log_fp = fopen(GYRO_LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", GYRO_LOG_FILE, strerror(errno));
        return -1;
    }
    /* Write header only if file is empty */
    long pos = ftell(g_log_fp);
    if (pos == 0)
        fprintf(g_log_fp, "Timestamp,AngularRate_DegS,Temperature_C\n");
    return 0;
}

/* ------------------------------------------------------------------ */
static void log_sample(float rate, float temp)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    fprintf(g_log_fp, "%s,%.4f,%.2f\n", ts, rate, temp);
    fflush(g_log_fp);
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open SPI device */
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", SPI_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Verify device identity */
    if (verify_who_am_i(g_spi_fd) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file once */
    if (log_open() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure gyroscope: 100 Hz output data rate, 16-bit, continuous */
    if (spi_write_reg16(g_spi_fd, REG_GYRO_CONFIG, 0x0001) < 0) {
        fprintf(stderr, "Failed to write GYRO_CONFIG\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure temperature: 100 Hz, continuous */
    if (spi_write_reg16(g_spi_fd, REG_TEMP_CONFIG, 0x0001) < 0) {
        fprintf(stderr, "Failed to write TEMP_CONFIG\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Logging gyroscope data to %s (Ctrl+C to stop)\n", GYRO_LOG_FILE);

    while (g_running) {
        int16_t raw_x = 0, raw_y = 0, raw_z = 0;
        float rate_x = 0.0f, rate_y = 0.0f, rate_z = 0.0f;
        float temp = 0.0f;

        if (spi_read_reg16(g_spi_fd, REG_GYRO_X_MSB, &raw_x) < 0 ||
            spi_read_reg16(g_spi_fd, REG_GYRO_Y_MSB, &raw_y) < 0 ||
            spi_read_reg16(g_spi_fd, REG_GYRO_Z_MSB, &raw_z) < 0) {
            fprintf(stderr, "SPI read error; continuing\n");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        rate_x = (float)raw_x * GYRO_SCALE;
        rate_y = (float)raw_y * GYRO_SCALE;
        rate_z = (float)raw_z * GYRO_SCALE;
        temp   = (float)raw_x * 0.1f;   /* placeholder; real temp reg needed */

        log_sample(rate_x, temp);
        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

