/*
 * GY-50 L3G4200D Gyroscope Logger for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   L3G4200D SDA -> GPIO2 (I2C bus 1 SDA)
 *   L3G4200D SCL -> GPIO3 (I2C bus 1 SCL)
 *   L3G4200D VDD -> 3.3 V
 *   L3G4200D GND -> GND
 *
 * Build:  gcc -O2 -Wall -o gyro_log gyro_log.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- L3G4200D constants (datasheet rev 1.3) ---- */
#define L3G4200D_ADDR        0x33
#define L3G4200D_WHO_AM_I    0x0F
#define L3G4200D_WHO_AM_I_VAL 0xD3
#define L3G4200D_CTRL_REG1   0x20
#define L3G4200D_CTRL_REG4   0x23
#define L3G4200D_OUT_X_L     0x28

#define I2C_BUS_DEV          "/dev/i2c-1"
#define LOG_FILE             "gyro_log.csv"
#define SAMPLE_PERIOD_US     10000   /* 10 ms */
#define MAX_INIT_RETRIES     3

/* Sensitivity: 8.75 mdps/LSB  -> 114.2857 mdps/LSB */
#define GYRO_SENSITIVITY     114.2857f

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to a register; returns 0 on success, -1 on error.   */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read one byte from a register; returns 0 on success, -1 on error.  */
static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    n = read(fd, out, 1);
    if (n != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int init_l3g4200d(int fd)
{
    uint8_t who = 0;

    /* Verify device identity */
    if (i2c_read_reg8(fd, L3G4200D_WHO_AM_I, &who) != 0)
        return -1;
    if (who != L3G4200D_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, L3G4200D_WHO_AM_I_VAL);
        return -1;
    }

    /* CTRL_REG1: 8.75 mdps, 100 Hz ODR, normal mode */
    if (i2c_write_reg8(fd, L3G4200D_CTRL_REG1, 0x0F) != 0)
        return -1;

    /* CTRL_REG4: enable all axes, 50 Hz output data rate */
    if (i2c_write_reg8(fd, L3G4200D_CTRL_REG4, 0x00) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
static int read_gyro_data(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t buf[6];

    /* Burst-read 6 bytes starting at OUT_X_L (auto-increment) */
    if (i2c_read_reg8(fd, L3G4200D_OUT_X_L, &buf[0]) != 0)
        return -1;
    if (i2c_read_reg8(fd, L3G4200D_OUT_X_L + 1, &buf[1]) != 0)
        return -1;
    if (i2c_read_reg8(fd, L3G4200D_OUT_X_L + 2, &buf[2]) != 0)
        return -1;
    if (i2c_read_reg8(fd, L3G4200D_OUT_X_L + 3, &buf[3]) != 0)
        return -1;
    if (i2c_read_reg8(fd, L3G4200D_OUT_X_L + 4, &buf[4]) != 0)
        return -1;
    if (i2c_read_reg8(fd, L3G4200D_OUT_X_L + 5, &buf[5]) != 0)
        return -1;

    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS_DEV, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS_DEV, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, L3G4200D_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                L3G4200D_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize sensor with retries */
    int init_ok = 0;
    for (int attempt = 1; attempt <= MAX_INIT_RETRIES; ++attempt) {
        if (init_l3g4200d(g_i2c_fd) == 0) {
            init_ok = 1;
            break;
        }
        fprintf(stderr, "Init attempt %d/%d failed; retrying...\n",
                attempt, MAX_INIT_RETRIES);
        usleep(100000);  /* 100 ms back-off */
    }

    if (!init_ok) {
        fprintf(stderr, "L3G4200D initialization failed after %d attempts.\n",
                MAX_INIT_RETRIES);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_fp = fopen(LOG_FILE, "w");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header */
    fprintf(g_log_fp, "Timestamp,X,Y,Z\n");
    fflush(g_log_fp);

    printf("Logging L3G4200D data to %s (Ctrl+C to stop)\n", LOG_FILE);

    /* Main sampling loop */
    while (g_running) {
        int16_t x, y, z;

        if (read_gyro_data(g_i2c_fd, &x, &y, &z) != 0) {
            fprintf(stderr, "Read error; continuing.\n");
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        struct timespec ts;
        if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
            fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        struct tm tm_info;
        localtime_r(&ts.tv_sec, &tm_info);
        char tbuf[32];
        strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm_info);

        fprintf(g_log_fp, "%s.%09ld,%d,%d,%d\n",
                tbuf, ts.tv_nsec, x, y, z);
        fflush(g_log_fp);

        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

