/*
 * Conveyor control monitor using two DRV5032 Hall-effect sensors.
 *
 * Hardware (Raspberry Pi 4 Model B):
 *   DRV5032 H1  -> GPIO17 (BCM)
 *   DRV5032 H2  -> GPIO27 (BCM)
 *   DRV5032 VCC -> 3.3 V (pin 1)
 *   DRV5032 GND -> GND  (pin 6)
 *
 * DRV5032 digital outputs are open-drain; internal pull-ups are enabled
 * so the line reads logic-high when the sensor is energised.
 *
 * Build:  gcc -O2 -Wall -Wextra -o conveyor conveyor.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

#define HALL_SENSOR_1_PIN 17
#define HALL_SENSOR_2_PIN 27
#define LOG_FILE          "conveyor_log.txt"
#define POLL_INTERVAL_US  50000   /* 50 ms */

/* ------------------------------------------------------------------ */
/* Globals                                                            */
/* ------------------------------------------------------------------ */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                    */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */

/*
 * Append a timestamped sensor reading to the log file.
 * Returns 0 on success, -1 on failure.
 */
static int log_sensor_data(int pin, int value)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return -1;
    }

    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[40];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp),
             sizeof(timestamp) - strlen(timestamp),
             ".%03ld", ts.tv_nsec / 1000000L);

    fprintf(fp, "%s, Pin: %d, Value: %d\n", timestamp, pin, value);
    fclose(fp);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor reading                                                      */
/* ------------------------------------------------------------------ */

/*
 * Read a GPIO line with error checking.
 * Returns 0 or 1 on success, -1 on failure.
 */
static int read_sensor(int pin)
{
    int value = gpioRead(pin);
    if (value < 0) {
        fprintf(stderr, "gpioRead failed on pin %d: %s\n",
                pin, pigpio_error(value));
        return -1;
    }
    return value;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure pins as inputs with internal pull-ups enabled. */
    if (gpioSetMode(HALL_SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", HALL_SENSOR_1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(HALL_SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", HALL_SENSOR_2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(HALL_SENSOR_1_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO%d\n", HALL_SENSOR_1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(HALL_SENSOR_2_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO%d\n", HALL_SENSOR_2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Conveyor control monitor started.\n");
    printf("  Sensor 1: GPIO%d\n", HALL_SENSOR_1_PIN);
    printf("  Sensor 2: GPIO%d\n", HALL_SENSOR_2_PIN);
    printf("  Log file: %s\n", LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        int s1 = read_sensor(HALL_SENSOR_1_PIN);
        int s2 = read_sensor(HALL_SENSOR_2_PIN);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "Sensor read error — aborting.\n");
            break;
        }

        if (log_sensor_data(HALL_SENSOR_1_PIN, s1) != 0) {
            fprintf(stderr, "Logging error — aborting.\n");
            break;
        }
        if (log_sensor_data(HALL_SENSOR_2_PIN, s2) != 0) {
            fprintf(stderr, "Logging error — aborting.\n");
            break;
        }

        if (s1 == 1 && s2 == 1) {
            printf("Conveyor halted — both sensors energised.\n");
