#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MMA8452Q_ADDR  0x53
#define WHO_AM_I       0x0D
#define WHO_AM_I_VAL   0x49
#define CTRL_REG1      0x2A
#define CTRL_REG4      0x33
#define OUT_X_L        0x01
#define OUT_X_H        0x02
#define OUT_Y_L        0x03
#define OUT_Y_H        0x04
#define OUT_Z_L        0x05
#define OUT_Z_H        0x06
#define DATA_RATE_100HZ 0x0A
#define TILT_THRESHOLD 45.0
#define LOG_FILE       "fall_log.txt"
#define LOOP_DELAY_MS  10

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C block read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_mma8452q(int fd) {
    uint8_t who_am_i = 0;
    if (i2c_read_reg(fd, WHO_AM_I, &who_am_i) < 0) {
        return -1;
    }
    if (who_am_i != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who_am_i, WHO_AM_I_VAL);
        return -1;
    }

    if (i2c_write_reg(fd, CTRL_REG1, 0x00) < 0) return -1;
    if (i2c_write_reg(fd, CTRL_REG4, 0x00) < 0) return -1;

    if (i2c_write_reg(fd, CTRL_REG1, 0x01) < 0) return -1;
    if (i2c_write_reg(fd, CTRL_REG4, DATA_RATE_100HZ) < 0) return -1;

    if (i2c_write_reg(fd, CTRL_REG1, 0x00) < 0) return -1;
    if (i2c_write_reg(fd, CTRL_REG4, 0x00) < 0) return -1;

    return 0;
}

static int read_accel(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read_block(fd, OUT_X_L, buf, 6) < 0) {
        return -1;
    }
    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);
    return 0;
}

static float calculate_tilt(int16_t x, int16_t y, int16_t z) {
    float xg = (float)x / 4096.0f;
    float yg = (float)y / 4096.0f;
    float zg = (float)z / 4096.0f;
    float tilt = atan2f(yg, sqrtf(xg * xg + zg * zg)) * 180.0f / (float)M_PI;
    return tilt;
}

static void log_fall(int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(g_log_fp, "%s, X: %d, Y: %d, Z: %d\n", timestamp, x, y, z);
    fflush(g_log_fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus '%s': %s\n", I2C_BUS, strerror(errno));
        fclose(g_log_fp);
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, MMA8452Q_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", MMA8452Q_ADDR, strerror(errno));
        close(g_i2c_fd);
        fclose(g_log_fp);
        return 1;
    }

    if (init_mma8452q(g_i2c_fd) < 0) {
        fprintf(stderr, "Error initializing MMA8452Q sensor.\n");
        close(g_i2c_fd);
        fclose(g_log_fp);
        return 1;
    }

    printf("MMA8452Q initialized. Polling at ~100 Hz. Press Ctrl+C to exit.\n");

    while (g_running) {
        int16_t x, y, z;
        if (read_accel(g_i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Read error, skipping iteration.\n");
            usleep(LOOP_DELAY_MS * 1000);
            continue;
        }

        float tilt = calculate_tilt(x, y, z);
        if (tilt > TILT_THRESHOLD) {
            log_fall(x, y, z);
        }

        usleep(LOOP_DELAY_MS * 1000);
    }

    printf("\nShutting down...\n");
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
    }
    if (g_log_fp) {
        fclose(g_log_fp);
    }
    return 0;
}

