/*
 * LIS3MDL Metal Detector — Raspberry Pi 3 Model B+
 * I2C bus 1, address 0x19 (SDO tied to GND)
 * 10 Hz sampling, metal-detector alert (> 800 mG)
 *
 * Build:  gcc -O2 -Wall -Wextra -o metal_detector metal_detector.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- LIS3MDL constants (datasheet rev 1.3) ---- */
#define LIS3MDL_ADDR        0x19
#define LIS3MDL_WHO_AM_I    0x0F
#define LIS3MDL_WHO_AM_I_VAL 0x33
#define LIS3MDL_CTRL_REG1   0x20
#define LIS3MDL_CTRL_REG2   0x21
#define LIS3MDL_CTRL_REG3   0x22
#define LIS3MDL_CTRL_REG4   0x23
#define LIS3MDL_OUT_X_L     0x28
#define LIS3MDL_OUT_X_H     0x29
#define LIS3MDL_OUT_Y_L     0x2A
#define LIS3MDL_OUT_Y_H     0x2B
#define LIS3MDL_OUT_Z_L     0x2C
#define LIS3MDL_OUT_Z_H     0x2D

#define CTRL_REG1_DOF       0x00
#define CTRL_REG1_MODE      0x02
#define CTRL_REG1_ODR       0x05
#define CTRL_REG2_M_CTRL    0x0C
#define CTRL_REG3_M_CTRL    0x0E
#define CTRL_REG4_M_CTRL    0x0F

#define M_CTRL_ALL_ON       0x0D
#define M_CTRL_Z_EN         0x01
#define M_CTRL_Y_EN         0x02
#define M_CTRL_X_EN         0x04

#define M_SENSITIVITY_4GAUSS 0.146f   /* mG/LSB at ±4 gauss */
#define METAL_THRESHOLD_MG   800.0f
#define SAMPLE_PERIOD_US     100000  /* 10 Hz */

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ---- Signal handler ---- */
static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ---- I2C helpers ---- */
static int i2c_write_reg(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "i2c_write_reg(0x%02X, 0x%02X) failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_reg write(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "i2c_read_reg read(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "i2c_read_burst write(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "i2c_read_burst read(0x%02X, %zu) failed: %s\n",
                reg, len, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- Sensor init ---- */
static int init_lis3mdl(int fd)
{
    uint8_t who;
    if (i2c_read_reg(fd, LIS3MDL_WHO_AM_I, &who) != 0)
        return -1;
    if (who != LIS3MDL_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, LIS3MDL_WHO_AM_I_VAL);
        return -1;
    }

    /* CTRL_REG1: ODR = 10 Hz (0x06), all axes enabled (0x7F) */
    if (i2c_write_reg(fd, LIS3MDL_CTRL_REG1, 0x7F) != 0)
        return -1;

    /* CTRL_REG2: ±4 gauss (0x00) */
    if (i2c_write_reg(fd, LIS3MDL_CTRL_REG2, 0x00) != 0)
        return -1;

    /* CTRL_REG3: continuous-conversion mode (0x00) */
    if (i2c_write_reg(fd, LIS3MDL_CTRL_REG3, 0x00) != 0)
        return -1;

    /* CTRL_REG4: no auto-increment (0x00) */
    if (i2c_write_reg(fd, LIS3MDL_CTRL_REG4, 0x00) != 0)
        return -1;

    return 0;
}

/* ---- Read 6 bytes of X/Y/Z data ---- */
static int read_magnetometer(int fd, float *x, float *y, float *z)
{
    uint8_t raw[6];
    if (i2c_read_burst(fd, LIS3MDL_OUT_X_L, raw, sizeof(raw)) != 0)
        return -1;

    int16_t x_raw = (int16_t)((raw[1] << 8) | raw[0]);
    int16_t y_raw = (int16_t)((raw[3] << 8) | raw[2]);
    int16_t z_raw = (int16_t)((raw[5] << 8) | raw[4]);

    *x = (float)x_raw * M_SENSITIVITY_4GAUSS - 100.0f;
    *y = (float)y_raw * M_SENSITIVITY_4GAUSS - 100.0f;
    *z = (float)z_raw * M_SENSITIVITY_4GAUSS - 100.0f;
    return 0;
}

/* ---- Metal-detector alert ---- */
static void check_metal(float x, float y, float z)
{
    float mag = sqrtf(x * x + y * y + z * z);
    if (mag > METAL_THRESHOLD_MG) {
        fprintf(stderr, "ALERT: metal detected! |M|=%.2f mG\n", mag);
    }
}

/* ---- Log one sample ---- */
static int log_sample(FILE *fp, float x, float y, float z)
{
    if (fprintf(fp, "%.2f,%.2f,%.2f\n", x, y, z) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush log failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ---- Main ---- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open /dev/i2c-1 failed: %s\n", strerror(errno));
