    }

    if (init_lis3mdl(g_i2c_fd) != 0) {
        fprintf(stderr, "LIS3MDL initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen("magnetic_log.txt", "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen magnetic_log.txt failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("LIS3MDL metal detector running. Ctrl+C to stop.\n");

    while (g_running) {
        float x, y, z;
        if (read_magnetometer(g_i2c_fd, &x, &y, &z) != 0) {
            fprintf(stderr, "Sensor read error — re-initializing.\n");
            if (init_lis3mdl(g_i2c_fd) != 0) {
                fprintf(stderr, "Re-init failed; will retry next cycle.\n");
