#define ADXL354_POWER_CTL_RUN 0x04

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_transfer(int fd, uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };
    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }
    return 0;
}

static int adxl354_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t tx[2] = { (uint8_t)(reg & 0x7F), value };
    uint8_t rx[2] = {0};
    return spi_transfer(fd, tx, rx, 2);
}

static int adxl354_read_reg(int fd, uint8_t reg, uint8_t *value) {
    uint8_t tx[2] = { (uint8_t)(reg | 0x80), 0x00 };
    uint8_t rx[2] = {0};
    if (spi_transfer(fd, tx, rx, 2) < 0) return -1;
    *value = rx[1];
    return 0;
}

static int adxl354_read_axis(int fd, uint8_t reg_l, uint8_t reg_h, int32_t *out) {
    uint8_t tx[3] = { (uint8_t)(reg_l & 0x7F), 0x80, 0x00 };
    uint8_t rx[3] = {0};
    if (spi_transfer(fd, tx, rx, 3) < 0) return -1;
    uint8_t lo = rx[1], hi = rx[2];
    int32_t raw = (int32_t)((uint32_t)hi << 8 | (uint32_t)lo) >> 4;
    if (raw & 0x0400) raw |= 0xF000;
    *out = raw;
    return 0;
}

static int adxl354_reset(int fd) {
    if (adxl354_write_reg(fd, ADXL354_REG_RESET, ADXL354_RESET_VALUE) < 0) return -1;
    usleep(1000);
    uint8_t status = 0;
    for (int i = 0; i < 10; i++) {
        if (adxl354_read_reg(fd, ADXL354_REG_STATUS, &status) < 0) return -1;
        if (status & ADXL354_STATUS_STABLE) return 0;
        usleep(1000);
    }
    fprintf(stderr, "ADXL354 reset timeout\n");
    return -1;
}

static int adxl354_init(int fd) {
    uint8_t partid = 0;
    if (adxl354_read_reg(fd, ADXL354_REG_PARTID, &partid) < 0) {
        fprintf(stderr, "Failed to read PARTID\n");
        return -1;
    }
    if (partid != ADXL354_PARTID_VALUE) {
        fprintf(stderr, "Unexpected PARTID: 0x%02X (expected 0x%02X)\n", partid, ADXL354_PARTID_VALUE);
        return -1;
    }
    if (adxl354_reset(fd) < 0) return -1;
    if (adxl354_write_reg(fd, ADXL354_REG_POWER_CTL, ADXL354_POWER_CTL_RUN) < 0) return -1;
    usleep(1000);
    return 0;
}

static int read_acceleration(int fd, int32_t *x, int32_t *y, int32_t *z) {
    if (adxl354_read_axis(fd, ADXL354_REG_XDATA_L, ADXL354_REG_XDATA_H, x) < 0) return -1;
    if (adxl354_read_axis(fd, ADXL354_REG_YDATA_L, ADXL354_REG_YDATA_H, y) < 0) return -1;
    if (adxl354_read_axis(fd, ADXL354_REG_ZDATA_L, ADXL354_REG_ZDATA_H, z) < 0) return -1;
    return 0;
}

static void log_data(FILE *fp, int32_t x, int32_t y, int32_t z) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, X: %d, Y: %d, Z: %d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, x, y, z);
    fflush(fp);
}

int main(void) {
    struct sigaction sa = { .sa_handler = signal_handler };
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return 1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        return 1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return 1;
    }

    if (adxl354_init(spi_fd) < 0) {
        fprintf(stderr, "ADXL354 initialization failed\n");
        close(spi_fd);
        return 1;
    }

    log_file = fopen("vibration_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(spi_fd);
        return 1;
    }

    while (running) {
        int32_t x, y, z;
        if (read_acceleration(spi_fd, &x, &y, &z) == 0) {
            log_data(log_file, x, y, z);
        } else {
            fprintf(stderr, "Failed to read acceleration data\n");
        }
        usleep(100000);
    }

    fprintf(stderr, "\nShutting down...\n");
    if (log_file) fclose(log_file);
    if (spi_fd >= 0) close(spi_fd);
    return 0;
}

