#include <pigpio.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 3
#define SPI_BITS 8
#define SPI_DELAY_USECS 0

#define ADIS16362_REG_GYRO_X_MSB 0x04
#define ADIS16362_REG_GYRO_X_LSB 0x05
#define ADIS16362_REG_GYRO_Y_MSB 0x06
#define ADIS16362_REG_GYRO_Y_LSB 0x07
#define ADIS16362_REG_GYRO_Z_MSB 0x08
#define ADIS16362_REG_GYRO_Z_LSB 0x09
#define ADIS16362_REG_ACCEL_X_MSB 0x0A
#define ADIS16362_REG_ACCEL_X_LSB 0x0B
#define ADIS16362_REG_ACCEL_Y_MSB 0x0C
#define ADIS16362_REG_ACCEL_Y_LSB 0x0D
#define ADIS16362_REG_ACCEL_Z_MSB 0x0E
#define ADIS16362_REG_ACCEL_Z_LSB 0x0F

#define GYRO_SCALE 0.05f
#define ACCEL_SCALE 0.0025f

#define SAMPLE_DELAY_US 10000

static int spi_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error: Failed to open SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error: Failed to set SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error: Failed to set SPI bits per word: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error: Failed to set SPI max speed: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

static int spi_transfer(uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS,
        .delay_usecs = SPI_DELAY_USECS,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error: SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int adis16362_read_register(uint8_t reg_msb, uint8_t *value) {
    uint8_t tx[2] = {reg_msb | 0x80, 0x00};
    uint8_t rx[2] = {0};

    if (spi_transfer(tx, rx, 2) < 0) {
        return -1;
    }

    *value = rx[1];
    return 0;
}

static int read_gyro_data(float *x, float *y, float *z) {
    uint8_t gyro_x_msb, gyro_x_lsb, gyro_y_msb, gyro_y_lsb, gyro_z_msb, gyro_z_lsb;

    if (adis16362_read_register(ADIS16362_REG_GYRO_X_MSB, &gyro_x_msb) < 0) return -1;
    if (adis16362_read_register(ADIS16362_REG_GYRO_X_LSB, &gyro_x_lsb) < 0) return -1;
    if (adis16362_read_register(ADIS16362_REG_GYRO_Y_MSB, &gyro_y_msb) < 0) return -1;
    if (adis16362_read_register(ADIS16362_REG_GYRO_Y_LSB, &gyro_y_lsb) < 0) return -1;
    if (adis16362_read_register(ADIS16362_REG_GYRO_Z_MSB, &gyro_z_msb) < 0) return -1;
    if (adis16362_read_register(ADIS16362_REG_GYRO_Z_LSB, &gyro_z_lsb) < 0) return -1;

    int16_t gyro_x = (int16_t)((gyro_x_msb << 8) | gyro_x_lsb);
    int16_t gyro_y = (int16_t)((gyro_y_msb << 8) | gyro_y_lsb);
    int16_t gyro_z = (int16_t)((gyro_z_msb << 8) | gyro_z_lsb);

    *x = (float)gyro_x * GYRO_SCALE;
    *y = (float)gyro_y * GYRO_SCALE;
    *z = (float)gyro_z * GYRO_SCALE;
    return 0;
}

static int read_accel_data(float *x, float *y, float *z) {
    uint8_t accel_x_msb, accel_x_lsb, accel_y_msb, accel_y_lsb, accel_z_msb, accel_z_lsb;

    if (adis16362_read_register(ADIS16362_REG_ACCEL_X_MSB, &accel_x_msb) < 0) return -1;
    if (adis16362_read_register(ADIS16362_REG_ACCEL_X_LSB, &accel_x_lsb) < 0) return -1;
    if (adis16362_read_register(ADIS16362_REG_ACCEL_Y_MSB, &accel_y_msb) < 0) return -1;
    if (adis16362_read_register(ADIS16362_REG_ACCEL_Y_LSB, &accel_y_lsb) < 0) return -1;
    if (adis16362_read_register(ADIS16362_REG_ACCEL_Z_MSB, &accel_z_msb) < 0) return -1;
    if (adis16362_read_register(ADIS16362_REG_ACCEL_Z_LSB, &accel_z_lsb) < 0) return -1;

    int16_t accel_x = (int16_t)((accel_x_msb << 8) | accel_x_lsb);
    int16_t accel_y = (int16_t)((accel_y_msb << 8) | accel_y_lsb);
    int16_t accel_z = (int16_t)((accel_z_msb << 8) | accel_z_lsb);

    *x = (float)accel_x * ACCEL_SCALE;
    *y = (float)accel_y * ACCEL_SCALE;
    *z = (float)accel_z * ACCEL_SCALE;
    return 0;
}

static int log_data(float x_gyro, float y_gyro, float z_gyro, float x_accel, float y_accel, float z_accel) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
        fprintf(stderr, "Error: clock_gettime failed: %s\n", strerror(errno));
        return -1;
    }

    if (fprintf(log_file, "%ld.%09ld,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
                (long)ts.tv_sec, ts.tv_nsec,
                x_gyro, y_gyro, z_gyro, x_accel, y_accel, z_accel) < 0) {
        fprintf(stderr, "Error: Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    if (spi_init() < 0) {
        gpioTerminate();
        return 1;
    }

    log_file = fopen("imu_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open imu_log.csv: %s\n", strerror(errno));
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    fprintf(log_file, "Timestamp,X_Gyro,Y_Gyro,Z_Gyro,X_Accel,Y_Accel,Z_Accel\n");
    fflush(log_file);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: Failed to register signal handler: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    float x_gyro, y_gyro, z_gyro, x_accel, y_accel, z_accel;

    while (program_running) {
        if (read_gyro_data(&x_gyro, &y_gyro, &z_gyro) < 0) {
            fprintf(stderr, "Warning: Failed to read gyro data, skipping sample\n");
        } else if (read_accel_data(&x_accel, &y_accel, &z_accel) < 0) {
            fprintf(stderr, "Warning: Failed to read accel data, skipping sample\n");
        } else {
            if (log_data(x_gyro, y_gyro, z_gyro, x_accel, y_accel, z_accel) < 0) {
                fprintf(stderr, "Warning: Failed to log data\n");
            }
        }
        gpioDelay(SAMPLE_DELAY_US);
    }

    cleanup();
    return 0;
}

