        return 1;
    }

    if (spi_init() < 0) {
        gpioTerminate();
        return 1;
    }

    log_file = fopen("imu_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open imu_log.csv: %s\n", strerror(errno));
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    fprintf(log_file, "Timestamp,X_Gyro,Y_Gyro,Z_Gyro,X_Accel,Y_Accel,Z_Accel\n");
    fflush(log_file);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: Failed to register signal handler: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    float x_gyro, y_gyro, z_gyro, x_accel, y_accel, z_accel;

    while (program_running) {
        if (read_gyro_data(&x_gyro, &y_gyro, &z_gyro) < 0) {
            fprintf(stderr, "Warning: Failed to read gyro data, skipping sample\n");
        } else if (read_accel_data(&x_accel, &y_accel, &z_accel) < 0) {
            fprintf(stderr, "Warning: Failed to read accel data, skipping sample\n");
        } else {
            if (log_data(x_gyro, y_gyro, z_gyro, x_accel, y_accel, z_accel) < 0) {
                fprintf(stderr, "Warning: Failed to log data\n");
            }
        }
        gpioDelay(SAMPLE_DELAY_US);
    }

    cleanup();
    return 0;
}

