#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>

#define GPIO_PIN 17
#define GPIO_CHIP "/dev/gpiochip4"
#define POLL_INTERVAL_SEC 1

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo) {
    (void)signo;
    g_running = 0;
}

static void install_signal_handler(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
    }
}

static void log_timestamped(const char *msg) {
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        perror("time");
        return;
    }
    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        perror("localtime_r");
        return;
    }
    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }
    printf("[%s] %s\n", ts, msg);
    fflush(stdout);
}

int main(void) {
    install_signal_handler();

    int fd = open(GPIO_CHIP, O_RDWR);
    if (fd == -1) {
        perror("open gpiochip4");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, GPIO_GET_LINE EINVAL, &GPIO_PIN) == -1) {
        perror("GPIO_GET_LINE");
        close(fd);
        return EXIT_FAILURE;
    }

    if (ioctl(fd, GPIO_SET_DIRECTION_OUTPUT, &GPIO_PIN) == -1) {
        perror("GPIO_SET_DIRECTION_OUTPUT");
        close(fd);
        return EXIT_FAILURE;
    }

    if (ioctl(fd, GPIO_SET_VALUE, &GPIO_PIN) == -1) {
        perror("GPIO_SET_VALUE");
        close(fd);
        return EXIT_FAILURE;
    }

    log_timestamped("Self-parking sequence started");

    for (int i = 0; i < 10 && g_running; i++) {
        sleep(POLL_INTERVAL_SEC);
        if (!g_running) break;

        if (ioctl(fd, GPIO_READ, &GPIO_PIN) == -1) {
            perror("GPIO_READ");
            log_timestamped("Error reading sensor value");
            break;
        }

        int val = (int)GPIO_PIN;
        if (val == 0) {
            log_timestamped("Obstacle detected!");
        }
    }

    if (g_running) {
        log_timestamped("Self-parking sequence completed");
    }

    if (close(fd) == -1) {
        perror("close");
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}

