/*
 * KY032 IR obstacle-avoidance sensor poll for Raspberry Pi 3 Model B+.
 *
 * Wiring:
 *   Sensor 1 OUT  -> GPIO17 (physical pin 11)
 *   Sensor 2 OUT  -> GPIO27 (physical pin 13)
 *   Sensor VCC    -> 3.3 V (physical pin 1)
 *   Sensor GND    -> GND  (physical pin 6)
 *
 * The KY032 module outputs a logic-0 level when an obstacle is
 * detected and logic-1 when the path is clear.  We read both lines
 * together via a single bulk read so the sensor outputs are sampled
 * simultaneously.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o ky032_poll ky032_poll.c
 *
 * Run:
 *   ./ky032_poll
 */

#include <errno.h>
#include <fcntl.h>
#include <signal.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#include <linux/gpio.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <sys/ioctl.h>
#include <sys/stat.h>
#include <sys/types.h>

#define GPIOCHIP_NAME      "/dev/gpiochip0"
#define GPIO17_OFFSET      17
#define GPIO27_OFFSET      27
#define POLL_INTERVAL_MS   100
#define I2C_BUS            "/dev/i2c-1"
#define I2C_BUS_ADDR       0x27

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handler(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    return sigaction(SIGINT, &sa, NULL);
}

/*
 * Open the I2C bus and target the KY032 module at the given address.
 * Returns a valid file descriptor on success, or -1 on failure.
 */
static int i2c_open(const char *bus, unsigned int addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus '%s': %s\n",
                bus, strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n",
                addr, strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

/*
 * Read the two KY032 lines together using a combined SMBus-style
 * read transaction.  Returns 0 on success, -1 on error.
 */
static int read_sensor_data(int fd, unsigned int *s1, unsigned int *s2)
{
    unsigned char tx[2] = {0, 0};
    unsigned char rx[2] = {0, 0};
    struct i2c_msg msgs[2];
    struct i2c_rdwr_ioctl_data data;

    /* Write the register pointer (0x00) to both lines. */
    msgs[0].addr  = I2C_BUS_ADDR;
    msgs[0].flags = 0;
    msgs[0].len   = 1;
    msgs[0].buf   = tx;

    /* Read both lines simultaneously. */
    msgs[1].addr  = I2C_BUS_ADDR;
    msgs[1].flags = I2C_M_RD;
    msgs[1].len   = 2;
    msgs[1].buf   = rx;

    data.msgs  = msgs;
    data.nmsgs = 2;

    if (ioctl(fd, I2C_RDWR, &data) < 0) {
        fprintf(stderr, "Error reading sensor data: %s\n", strerror(errno));
        return -1;
    }

    *s1 = rx[0];
    *s2 = rx[1];
    return 0;
}

/*
 * Convert the raw sensor value (0 or 1) to a human-readable
 * obstacle-detection status string.
 */
static const char *status_str(unsigned int raw)
{
    return (raw == 0) ? "OBSTACLE DETECTED" : "PATH CLEAR";
}

int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    if (install_signal_handler() != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    fd = i2c_open(I2C_BUS, I2C_BUS_ADDR);
    if (fd < 0) {
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, I2C_BUS_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n",
                I2C_BUS_ADDR, strerror(errno));
        goto cleanup;
    }

    printf("KY032 obstacle-avoidance poll started.\n");
    printf("  Sensor 1: GPIO%d (physical pin 11)\n", GPIO17_OFFSET);
    printf("  Sensor 2: GPIO%d (physical pin 13)\n", GPIO27_OFFSET);
    printf("  Poll interval: %d ms\n", POLL_INTERVAL_MS);
    printf("Press Ctrl+C to exit.\n\n");

    while (g_running) {
        unsigned int s1 = 0, s2 = 0;

        if (read_sensor_data(fd, &s1, &s2) < 0) {
            fprintf(stderr, "Sensor read failed; continuing.\n");
        } else {
            time_t now = time(NULL);
            struct tm tm_buf;
            struct tm *t = localtime_r(&now, &tm_buf);
            char ts[32] = {0};
            if (t) {
                strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
            } else {
                snprintf(ts, sizeof(ts), "<unknown-time>");
            }

            printf("[%s] Sensor1: %s | Sensor2: %s\n",
                   ts, status_str(s1), status_str(s2));
            fflush(stdout);
        }

        /* Sleep in 1 ms increments so SIGINT is caught promptly. */
        for (int i = 0; i < POLL_INTERVAL_MS * 1000 && g_running; i++) {
            usleep(1000);
        }
    }

    printf("\nExiting gracefully.\n");
    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return rc;
}

