code:
/*
 * LSM6DSR IMU reader for Raspberry Pi 3 Model B+
 * Uses pigpio for I2C communication.
 *
 * Wiring:
 *   LSM6DSR SDA  -> GPIO 2 (I2C bus 1 SDA)
 *   LSM6DSR SCL  -> GPIO 3 (I2C bus 1 SCL)
 *   LSM6DSR VDD  -> 3.3 V
 *   LSM6DSR GND  -> GND
 *
 * Build:  gcc -O2 -Wall -o lsm6dsr lsm6dsr.c -lpigpio -lrt
 * Run:    sudo ./lsm6dsr
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- LSM6DSR constants (datasheet rev 1.5) ---- */
#define LSM6DSR_ADDR        0x49          /* SA0 = 0  (SDO/SA0 tied to GND) */
#define WHO_AM_I            0x0F
#define WHO_AM_I_VAL        0x6B          /* expected */
#define CTRL1_XL           0x10
#define CTRL2_G            0x11
#define OUTX_L_G           0x22          /* gyro X low  */
#define OUTX_L_XL           0x28         /* accel X low */

#define SAMPLE_PERIOD_US    100000       /* 100 ms */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int16_t le16(const uint8_t *p)
{
    return (int16_t)((uint16_t)p[0] | ((uint16_t)p[1] << 8));
}

/* ------------------------------------------------------------------ */
static int lsm6dsr_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "I2C block read failed (reg 0x%02X, want %u, got %d): %s\n",
                reg, len, rc, pigpio_error(rc));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int lsm6dsr_write_reg(int handle, uint8_t reg, uint8_t val)
{
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %s\n",
                reg, val, pigpio_error(rc));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int lsm6dsr_init(int handle)
{
    uint8_t who = 0;

    /* Verify device identity */
    if (i2cReadByteData(handle, WHO_AM_I) < 0) {
        fprintf(stderr, "Cannot read WHO_AM_I register.\n");
        return -1;
    }
    who = (uint8_t)i2cReadByteData(handle, WHO_AM_I);
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X.\n",
                who, WHO_AM_I_VAL);
        return -1;
    }

    /* Standby mode before configuring axes */
    if (lsm6dsr_write_reg(handle, CTRL1_XL, 0x00) < 0)
        return -1;

    /* Gyro: 8 kHz, 245 dps, continuous update */
    if (lsm6dsr_write_reg(handle, CTRL2_G, 0x00) < 0)
        return -1;

    /* Accelerometer: 8 kHz, 2 g, continuous update */
    if (lsm6dsr_write_reg(handle, CTRL1_XL, 0x40) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
static int lsm6dsr_read_all(int handle, int16_t *ax, int16_t *ay, int16_t *az,
                            int16_t *gx, int16_t *gy, int16_t *gz)
{
    uint8_t buf[6];

    if (lsm6dsr_read_block(handle, OUTX_L_XL, buf, 6) < 0)
        return -1;

    *ax = le16(&buf[0]);
    *ay = le16(&buf[2]);
    *az = le16(&buf[4]);
    /* buf[6] is OUTX_L_G — skipped; gyro data follows in the next burst */
    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    int16_t ax, ay, az, gx, gy, gz;

    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* --- I2C open --------------------------------------------------- */
    g_i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (bus 1, addr 0x%02X): %s\n",
                LSM6DSR_ADDR, pigpio_error(g_i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- sensor init ------------------------------------------------ */
    if (lsm6dsr_init(g_i2c_handle) < 0) {
        fprintf(stderr, "LSM6DSR initialisation failed.\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- signal handling ------------------------------------------- */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("LSM6DSR ready. Press Ctrl+C to stop.\n");

    /* --- main loop -------------------------------------------------- */
    while (g_running) {
        if (lsm6dsr_read_all(g_i2c_handle, &ax, &ay, &az, &gx, &gy, &gz) < 0) {
            fprintf(stderr, "Read error — continuing.\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }
        printf("Accel: X=%6d Y=%6d Z=%6d  |  Gyro: X=%6d Y=%6d Z=%6d\n",
               ax, ay, az, gx, gy, gz);
        fflush(stdout);
        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* --- clean shutdown --------------------------------------------- */
    printf("\nShutting down...\n");
    i2cClose(g_i2c_handle);
    g_i2c_handle = -1;
    gpioTerminate();
    return EXIT_SUCCESS;
}

