static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write_reg8(0x%02X, 0x%02X) failed: %s (wrote %zd bytes)\n",
                reg, value, strerror(errno), n);
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *dst, size_t len)
{
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "i2c_read_block: write reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    n = read(fd, dst, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "i2c_read_block: read %zu bytes from 0x%02X failed: %s (got %zd)\n",
                len, reg, strerror(errno), n);
        return -1;
    }
    return 0;
}

