/*
 * ADXL345 Tilt Monitor for Raspberry Pi 5
 *
 * Reads acceleration data from an ADXL345 accelerometer over I2C and logs
 * tilt events exceeding a threshold to /var/log/tilt_events.log every 100 ms.
 *
 * Wiring:
 *   ADXL345 SDA -> GPIO 2 (I2C1 SDA)
 *   ADXL345 SCL -> GPIO 3 (I2C1 SCL)
 *   ADXL345 VDD -> 3.3 V
 *   ADXL345 GND -> GND
 *
 * Build: gcc -O2 -Wall -o tilt_monitor tilt_monitor.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- ADXL345 constants ---- */
#define ADXL345_ADDRESS        0x48
#define ADXL345_REG_DEVID      0x00
#define ADXL345_REG_POWER_CTL  0x2D
#define ADXL345_REG_DATA_FORMAT 0x31
#define ADXL345_REG_DATAX0     0x32
#define ADXL345_DEVID          0xE5

/* ---- Application constants ---- */
#define I2C_BUS                 "/dev/i2c-1"
#define LOG_FILE                "/var/log/tilt_events.log"
#define TILT_THRESHOLD          30.0f
#define SAMPLE_INTERVAL_US      100000  /* 100 ms */
#define DEVID_EXPECTED          0xE5

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                          */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = val;
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C burst read from 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* ADXL345 initialization                                              */
/* ------------------------------------------------------------------ */
static int adxl345_init(int fd)
{
    uint8_t devid = 0;
    if (i2c_read_reg8(fd, ADXL345_REG_DEVID, &devid) != 0) {
        fprintf(stderr, "Cannot read DEVID — sensor absent or bus error.\n");
        return -1;
    }
    if (devid != ADXL345_DEVID) {
        fprintf(stderr, "DEVID mismatch: got 0x%02X, expected 0x%02X.\n",
                devid, ADXL345_DEVID);
        return -1;
    }

    /* Standby first so configuration changes take effect */
    if (i2c_write_reg8(fd, ADXL345_REG_POWER_CTL, 0x00) != 0)
        return -1;

    /* Data format: full resolution, +/- 2 g, right-justified */
    if (i2c_write_reg8(fd, ADXL345_REG_DATA_FORMAT, 0x0B) != 0)
        return -1;

    /* Power on, measurement mode */
    if (i2c_write_reg8(fd, ADXL345_REG_POWER_CTL, 0x08) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read acceleration (X/Y/Z)                                          */
/* ------------------------------------------------------------------ */
static int read_acceleration(int fd, float *x, float *y, float *z)
{
    uint8_t buf[6];
    if (i2c_read_burst(fd, ADXL345_REG_DATAX0, buf, sizeof(buf)) != 0)
        return -1;

    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);

    /* +/- 2 g full resolution: 4 mg/LSB => 1 g = 256 LSB */
    *x = (float)raw_x / 256.0f;
    *y = (float)raw_y / 256.0f;
    *z = (float)raw_z / 256.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Tilt angle (degrees) from X/Y acceleration                         */
/* ------------------------------------------------------------------ */
static float calculate_tilt_angle(float x, float y)
{
    float angle = atan2f(y, x) * 180.0f / (float)M_PI;
    if (angle < 0.0f)
        angle += 360.0f;
    return angle;
}

/* ------------------------------------------------------------------ */
/* Log tilt event                                                     */
/* ------------------------------------------------------------------ */
static int log_tilt_event(float tilt_angle)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }

    if (fprintf(g_log_fp, "%s - Tilt angle: %.2f degrees\n", ts, tilt_angle) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE (0x%02X) failed: %s\n",
                ADXL345_ADDRESS, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Initialize ADXL345 ---- */
    if (adxl345_init(g_i2c_fd) != 0) {
        fprintf(stderr, "ADXL345 initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ADXL345 tilt monitor started. Logging to %s. Press Ctrl+C to exit.\n",
           LOG_FILE);

    /* ---- Main sampling loop ---- */
    while (g_running) {
        float x, y, z;

        if (read_acceleration(g_i2c_fd, &x, &y, &z) != 0) {
            fprintf(stderr, "Read error — continuing after %d ms.\n",
                    SAMPLE_INTERVAL_US / 1000);
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        float tilt = calculate_tilt_angle(x, y);

        if (tilt > TILT_THRESHOLD) {
            if (log_tilt_event(tilt) != 0)
                fprintf(stderr, "Logging failed for tilt %.2f.\n", tilt);
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down cleanly.\n");
    cleanup();
    return EXIT_SUCCESS;
}

