/*
 * KY038 Sound Sensor Monitor (Raspberry Pi 3 Model B+)
 *
 * Wiring:
 *   KY038 VCC  -> 3.3 V (pin 1)
 *   KY038 GND  -> GND   (pin 9)
 *   KY038 OUT  -> GPIO17 (pin 11, BCM 17)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o sound_monitor sound_monitor.c
 *
 * Usage:
 *   ./sound_monitor <threshold>
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN        17
#define WINDOW_SECONDS  5
#define SAMPLE_DELAY_US 1000   /* 1 ms */
#define PAUSE_SECONDS   1

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                         */
/* ------------------------------------------------------------------ */
static int gpio_init(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n",
                gpioInitialise());
        return -1;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_INPUT) failed.\n",
                GPIO_PIN);
        gpioTerminate();
        return -1;
    }

    /* Enable internal pull-down so the pin reads LOW when the sensor
     * is idle (KY038 OUT is open-collector-style). */
    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Warning: gpioSetPullUpDown(%d, PI_PUD_DOWN) failed.\n",
                GPIO_PIN);
        /* Non-fatal: continue anyway. */
    }

    return 0;
}

static int gpio_cleanup(void)
{
    gpioTerminate();
    return 0;
}

