/*
 * door_access.c — Raspberry Pi 4 Model B
 *
 * Controls two 12 V electromagnetic door locks via TIP120-driven 5 V relay
 * modules on the GPIO bus.
 *
 *   Door A  : BCM GPIO17 (active HIGH = lock energized / closed)
 *   Door B  : BCM GPIO27 (active HIGH = lock energized / closed)
 *
 *   HIGH  = relay energized  -> lock energized -> door locked
 *   LOW  = relay de-energized -> lock de-energized -> door unlocked
 *
 * Build:  gcc -Wall -Wextra -O2 -o door_access door_access.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define DOOR_A_PIN    17
#define DOOR_B_PIN    27
#define ACCESS_LOG    "access_log.txt"
#define UNLOCK_TIME   5          /* seconds to keep door unlocked  */
#define MIN_CODE      100000     /* six-digit lower bound            */
#define MAX_CODE      999999     /* six-digit upper bound             */
#define MAX_RETRIES   3          /* consecutive unlock failures      */
#define UNLOCK_RETRIES 3         /* total unlock failures per cycle  */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void handle_signal(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void sleep_seconds(unsigned int seconds)
{
    while (seconds > 0 && g_running) {
        unsigned int chunk = (seconds > 1) ? 1 : seconds;
        sleep(chunk);
        seconds -= chunk;
    }
}

/* ------------------------------------------------------------------ */
static int generate_random_code(void)
{
    return (rand() % (MAX_CODE - MIN_CODE + 1)) + MIN_CODE;
}

/* ------------------------------------------------------------------ */
static int log_access(const char *code)
{
    FILE *fp = fopen(ACCESS_LOG, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", ACCESS_LOG, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%06d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, (unsigned int)code);

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing %s: %s\n", ACCESS_LOG, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int unlock_door(struct gpiod_line *line)
{
    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Failed to set line LOW: %s\n", strerror(errno));
        return -1;
    }
    printf("Door unlocked.\n");
    fflush(stdout);
    return 0;
}

/* ------------------------------------------------------------------ */
static int lock_door(struct gpiod_line *line)
{
    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Failed to set line HIGH: %s\n", strerror(errno));
        return -1;
    }
    printf("Door locked.\n");
    fflush(stdout);
    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(struct gpiod_chip *chip,
                    struct gpiod_line *line_a,
                    struct gpiod_line *line_b)
{
    if (line_a) {
        gpiod_line_set_value(line_a, 1);   /* lock doors */
        gpiod_line_release(line_a);
    }
    if (line_b) {
        gpiod_line_set_value(line_b, 1);
        gpiod_line_release(line_b);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line_a = NULL;
    struct gpiod_line *line_b = NULL;
    int rc = EXIT_FAILURE;

    /* ---- Signal handling ------------------------------------------ */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- GPIO setup via libgpiod ----------------------------------- */
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        /* Fallback: try gpiochip0 on older kernels */
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    line_a = gpiod_chip_get_line(chip, DOOR_A_PIN);
    if (!line_a) {
        fprintf(stderr, "Failed to get line %d: %s\n", DOOR_A_PIN, strerror(errno));
        goto cleanup;
    }

    line_b = gpiod_chip_get_line(chip, DOOR_B_PIN);
    if (!line_b) {
        fprintf(stderr, "Failed to get line %d: %s\n", DOOR_B_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line_a, "door_access", 1) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n",
                DOOR_A_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line_b, "door_access", 1) < 0) {
        fprintf(stderr, "Failed to request line %d as output: %s\n",
                DOOR_B_PIN, strerror(errno));
        goto cleanup;
    }

    /* Ensure doors start locked */
    if (gpiod_line_set_value(line_a, 1) < 0 || gpiod_line_set_value(line_b, 1) < 0) {
        fprintf(stderr, "Failed to initialize line states: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Door access control system started.\n");
    printf("  Door A: BCM GPIO%d\n", DOOR_A_PIN);
    printf("  Door B: BCM GPIO%d\n", DOOR_B_PIN);
    printf("  Access log: %s\n", ACCESS_LOG);
    printf("  Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* ---- Main loop ------------------------------------------------- */
    while (g_running) {
        int code = generate_random_code();
        printf("Generated security code: %d\n", code);
        fflush(stdout);

        if (unlock_door(line_a) < 0) {
            goto cleanup;
        }

        if (unlock_door(line_b) < 0) {
            goto cleanup;
        }

        for (int attempt = 0; attempt < UNLOCK_RETRIES && g_running; attempt++) {
            char input[16];
            printf("Enter security code (or Ctrl+C to exit): ");
            fflush(stdout);

            if (fgets(input, sizeof(input), stdin) == NULL) {
                if (feof(stdin)) {
                    printf("\nInput stream closed.\n");
                } else {
                    fprintf(stderr, "Error reading input: %s\n", strerror(errno));
                }
                break;
            }

            /* Strip trailing newline */
            input[strcspn(input, "\n")] = '\0';

            if (input[0] == '\0') {
                printf("Invalid input. Please enter a number.\n");
                continue;
            }

            char *endptr = NULL;
            long entered = strtol(input, &endptr, 10);
            if (endptr == input || *endptr != '\0') {
                printf("Invalid input. Please enter a numeric code.\n");
                continue;
            }

            if (entered != code) {
                printf("Access denied.\n");
            } else {
                if (log_access((const char *)code) < 0) {
                    printf("Access denied (log write failed).\n");
                } else {
                    printf("Access granted.\n");
                }
            }

            for (int i = 0; i < UNLOCK_RETRIES && g_running; i++) {
                sleep_seconds(UNLOCK_TIME);
            }
        }

        if (!g_running) {
            break;
        }

        if (lock_door(line_a) < 0) {
            goto cleanup;
        }
        if (lock_door(line_b) < 0) {
            goto cleanup;
        }
    }

    rc = EXIT_SUCCESS;

cleanup:
    cleanup(chip, line_a, line_b);
    printf("Door access control system stopped.\n");
    return rc;
}

