                printf("Invalid input. Please enter a number.\n");
                continue;
            }

            char *endptr = NULL;
            long entered = strtol(input, &endptr, 10);
            if (endptr == input || *endptr != '\0') {
                printf("Invalid input. Please enter a numeric code.\n");
                continue;
            }

            if (entered != code) {
                printf("Access denied.\n");
            } else {
                if (log_access((const char *)code) < 0) {
                    printf("Access denied (log write failed).\n");
                } else {
                    printf("Access granted.\n");
                }
            }

            for (int i = 0; i < UNLOCK_RETRIES && g_running; i++) {
                sleep_seconds(UNLOCK_TIME);
            }
        }

        if (!g_running) {
            break;
        }

        if (lock_door(line_a) < 0) {
            goto cleanup;
        }
        if (lock_door(line_b) < 0) {
            goto cleanup;
        }
    }

    rc = EXIT_SUCCESS;

cleanup:
    cleanup(chip, line_a, line_b);
    printf("Door access control system stopped.\n");
    return rc;
}

