/*
 * BH1750FVI light sensor reader for Raspberry Pi 3 Model B+
 * Uses pigpio for I2C communication.
 *
 * Wiring:
 *   BH1750 VCC  -> 3.3 V (Pin 1)
 *   BH1750 GND  -> GND   (Pin 6)
 *   BH1750 SDA  -> GPIO2 (Pin 3, I2C bus 1 SDA)
 *   BH1750 SCL  -> GPIO3 (Pin 5, I2C bus 1 SCL)
 *   ADDR pin    -> GND  (I2C address 0x10)
 *
 * Build: gcc -Wall -Wextra -O2 -o light_logger light_logger.c -lpigpio -lrt
 * Run:   sudo ./light_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define BH1750_ADDR    0x10
#define LOG_FILE       "light_log.txt"
#define SAMPLE_PERIOD  5          /* seconds between samples */
#define CONVERSION_MS  180        /* BH1750 max conversion time */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    struct tm tm_info;
    if (localtime_r(&now, &tm_info) != NULL) {
        strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm_info);
    } else {
        snprintf(buf, len, "1970-01-01 00:00:00");
    }
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int bh1750_write_command(int handle, uint8_t cmd)
{
    if (i2cWriteByte(handle, cmd) < 0) {
        return -1;
    }
    return 0;
}

static int bh1750_read_data(int handle, uint8_t *buf, int count)
{
    int bytes = i2cReadDevice(handle, (char *)buf, count);
    if (bytes != count) {
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* BH1750 driver                                                      */
/* ------------------------------------------------------------------ */
static int bh1750_init(int handle)
{
    /* Power on + reset */
    if (bh1750_write_command(handle, 0x01) < 0) {
        return -1;
    }
    gpioDelay(10000);  /* 10 ms power-on delay */

    /* Continuous high-resolution mode (1 lx resolution) */
    if (bh1750_write_command(handle, 0x10) < 0) {
        return -1;
    }
    gpioDelay(180000); /* 180 ms conversion time */
    return 0;
}

static int bh1750_read_lux(int handle, float *lux_out)
{
    uint8_t data[2];

    if (bh1750_read_data(handle, data, 2) < 0) {
        return -1;
    }

    uint16_t raw = ((uint16_t)data[0] << 8) | data[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_data(const char *filename, float lux)
{
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        perror("fopen");
        return -1;
    }

    char ts[32];
    get_timestamp(ts, sizeof(ts));

    if (fprintf(fp, "Timestamp: %s, Lux: %.2f\n", ts, lux) < 0) {
        perror("fprintf");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- I2C open --- */
    int handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "i2cOpen failed (bus %d, addr 0x%02X): %d\n",
                I2C_BUS, BH1750_ADDR, handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Sensor init --- */
    if (bh1750_init(handle) < 0) {
        fprintf(stderr, "BH1750 init failed (sensor may be absent or unresponsive)\n");
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("BH1750 light sensor logging started. Press Ctrl-C to stop.\n");

    /* --- Main loop --- */
    while (g_running) {
        float lux = 0.0f;

        if (bh1750_read_lux(handle, &lux) < 0) {
            fprintf(stderr, "BH1750 read error — skipping sample\n");
        } else {
            if (log_data(LOG_FILE, lux) < 0) {
                fprintf(stderr, "Logging failed\n");
            } else {
                printf("Lux: %.2f\n", lux);
            }
        }

        /* Sleep in 100 ms increments so SIGINT is caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD * 10 && g_running; i++) {
            gpioDelay(100000);  /* 100 ms */
        }
    }

    /* --- Cleanup --- */
    printf("\nShutting down...\n");
    i2cClose(handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

