/*
 * Theremin using MPR121 capacitive touch sensor on Raspberry Pi 4 Model B.
 *
 * Build:  gcc -O2 -Wall -Wextra -o theremin theremin.c -lpigpio -lrt
 * Run:    sudo ./theremin
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/socket.h>
#include <sys/ioctl.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define MPR121_ADDR        0x41
#define MPR121_TOUCHSTATUS 0x00
#define MPR121_ELECONFIG    0x5E
#define MPR121_SOFTRESET    0x80
#define MPR121_MHDR         0x2B
#define MPR121_NHDR         0x2C
#define MPR121_NCLR         0x2D
#define MPR121_FDLR         0x2E
#define MPR121_MHDF         0x2F
#define MPR121_NHDF         0x30
#define MPR121_NCLF         0x31
#define MPR121_FDLF         0x32
#define MPR121_NHDT         0x33
#define MPR121_NCLT         0x34
#define MPR121_FDLT         0x35
#define MPR121_E0TTH        0x41
#define MPR121_E0RTH        0x42
#define MPR121_DEBOUNCE     0x5B
#define MPR121_CONFIG1      0x5C
#define MPR121_CONFIG2      0x5D
#define MPR121_ECR          0x5E
#define MPR121_TOUCHSTATUS  0x00

#define PORT               12345
#define PWM_PIN            18
#define PWM_FREQUENCY      1000
#define PWM_RANGE          1000
#define PLAYBACK_DURATION  5
#define SAMPLE_PERIOD_US   20000
#define LOG_FILE           "frequency_log.txt"
#define I2C_BUS            "/dev/i2c-1"
#define TCP_BUF_SIZE       1024
#define MPR121_ELECTRODES  12

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static int g_server_fd = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int mpr121_write_reg(uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(g_i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int mpr121_init(void)
{
    if (mpr121_write_reg(MPR121_SOFTRESET, 0x63) < 0) return -1;
    gpioDelay(1000);

    if (mpr121_write_reg(MPR121_ECR, 0x00) < 0) return -1;
    gpioDelay(1000);

    if (mpr121_write_reg(MPR121_MHDR, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NHDR, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NCLR, 0x0E) < 0) return -1;
    if (mpr121_write_reg(MPR121_FDLR, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_MHDF, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NHDF, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NCLF, 0x0E) < 0) return -1;
    if (mpr121_write_reg(MPR121_FDLF, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_NHDT, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_NCLT, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_FDLT, 0x00) < 0) return -1;

    for (int i = 0; i < MPR121_ELECTRODES; i++) {
        if (mpr121_write_reg(MPR121_E0TTH + i * 2, 0x0F) < 0) return -1;
        if (mpr121_write_reg(MPR121_E0RTH + i * 2, 0x0A) < 0) return -1;
    }

    if (mpr121_write_reg(MPR121_DEBOUNCE, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_CONFIG1, 0x10) < 0) return -1;
    if (mpr121_write_reg(MPR121_CONFIG2, 0x20) < 0) return -1;
    if (mpr121_write_reg(MPR121_ECR, 0x8F) < 0) return -1;
    gpioDelay(1000);

    return 0;
}

static int mpr121_read_touch_status(uint16_t *touch_status)
{
    uint8_t buf[2];
    if (read(g_i2c_fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read of touch status failed: %s\n", strerror(errno));
        return -1;
    }
    *touch_status = ((uint16_t)buf[1] << 8) | buf[0];
    return 0;
}

static double calculate_frequency(uint16_t touch_status)
{
    if (touch_status == 0) return 0.0;
    double sum = 0.0;
    for (int i = 0; i < MPR121_ELECTRODES; i++) {
        if (touch_status & (1 << i)) {
            sum += (double)i + 1.0;
        }
    }
    return 440.0 * (1.0 + (sum / MPR121_ELECTRODES));
}

static void play_tone(int frequency, int duration_seconds)
{
    if (frequency <= 0) {
        gpioPWM(PWM_PIN, 0);
        return;
    }

    int pwm_range = 1000;
    int pwm_freq = gpioSetPWMfrequency(PWM_PIN, frequency);
    if (pwm_freq < 0) {
        fprintf(stderr, "Failed to set PWM frequency: %s\n", pigpio_error(pwm_freq));
        return;
    }

    int pwm_dutycycle = gpioSetPWMrange(PWM_PIN, pwm_range);
    if (pwm_dutycycle < 0) {
        fprintf(stderr, "Failed to set PWM range: %s\n", pigpio_error(pwm_dutycycle));
        return;
    }

    double elapsed = 0.0;
    while (elapsed < duration_seconds && g_running) {
        uint16_t touch_status = 0;
        if (mpr121_read_touch_status(&touch_status) < 0) {
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }
        double freq = calculate_frequency(touch_status);
        if (freq > 0.0) {
            FILE *fp = fopen(LOG_FILE, "a");
            if (fp) {
                time_t t = time(NULL);
                struct tm tm = *localtime(&t);
                fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.2f\n",
                        tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                        tm.tm_hour, tm.tm_min, tm.tm_sec, freq);
                fclose(fp);
            }
        }
        gpioDelay(SAMPLE_PERIOD_US);
        elapsed += SAMPLE_PERIOD_US / 1000000.0;
    }

    gpioPWM(PWM_PIN, 0);
}

static void handle_tcp_connection(int client_fd)
{
    char buffer[TCP_BUF_SIZE];
    ssize_t bytes_received = recv(client_fd, buffer, sizeof(buffer) - 1, 0);
    if (bytes_received < 0) {
        perror("recv failed");
        close(client_fd);
        return;
    }
    if (bytes_received == 0) {
        close(client_fd);
        return;
    }
    buffer[bytes_received] = '\0';

    if (strncmp(buffer, "MOTION_DETECTED:", 16) == 0) {
        if (strstr(buffer, "MySecretKey") != NULL) {
            printf("Authenticating motion detected...\n");
            play_tone(440, PLAYBACK_DURATION);
            const char *ack = "OK\n";
            send(client_fd, ack, strlen(ack), 0);
        } else {
            const char *err = "Invalid authentication key\n";
            send(client_fd, err, strlen(err), 0);
        }
    } else {
        const char *err = "Invalid command format\n";
        send(client_fd, err, strlen(err), 0);
    }
    close(client_fd);
}

static int setup_i2c(void)
{
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", MPR121_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return -1;
    }
    if (mpr121_init() < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return -1;
    }
    return 0;
}

static int setup_tcp_server(void)
{
    int fd = socket(AF_INET, SOCK_STREAM, 0);
    if (fd < 0) {
        perror("socket failed");
        return -1;
    }
    int opt = 1;
    if (setsockopt(fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt failed");
        close(fd);
        return -1;
    }
    struct sockaddr_in addr = {0};
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port = htons(PORT);
    if (bind(fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("bind failed");
        close(fd);
        return -1;
    }
    if (listen(fd, 3) < 0) {
        perror("listen failed");
        close(fd);
        return -1;
    }
    return fd;
}

int main(void)
{
    struct sigaction sa = {0};
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (setup_i2c() < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_server_fd = setup_tcp_server();
    if (g_server_fd < 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Theremin server listening on port %d...\n", PORT);

    while (g_running) {
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        int client_fd = accept(g_server_fd, (struct sockaddr *)&client_addr, &client_len);
        if (client_fd < 0) {
            if (errno == EINTR && !g_running) break;
            perror("accept failed");
            continue;
        }
        handle_tcp_connection(client_fd);
    }

    printf("\nShutting down...\n");
    if (g_i2c_fd >= 0) {
        gpioPWM(PWM_PIN, 0);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_server_fd >= 0) {
        close(g_server_fd);
        g_server_fd = -1;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

