        g_log_fp = NULL;
    }

    /* Stop PWM on LED */
    if (gpioInitialise() >= 0) {
        gpioPWM(LED_GPIO, 0);
        gpioTerminate();
    }
}

/* ------------------------------------------------------------------ */
/* Write a single byte to an 8-bit register. Returns 0 on success, -1 on error. */
static int reg_write8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read N bytes starting at `reg` into `buf`. Returns 0 on success, -1 on error. */
static int reg_read(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: got %zd of %zu (%s)\n",
                reg, n, len, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read the six bytes of Z-axis data and compute the magnitude. */
static int read_magnetometer(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t buf[6];
    if (reg_read(fd, LSM303_M_OUT_Z_L_Z, buf, sizeof(buf)) != 0)
        return -1;

    *z = (int16_t)((buf[2] << 8) | buf[1]);
    *y = (int16_t)((buf[4] << 8) | buf[3]);
    *x = (int16_t)((buf[6] << 8) | buf[5]);
    return 0;
}

/* ------------------------------------------------------------------ */
static int calculate_magnitude(int16_t x, int16_t y, int16_t z)
{
    /* High-resolution mode: 1 mg/LSB → 1 mg/LSB */
    return (int)((x * x + y * y + z * z) / 1000.0);
}

/* ------------------------------------------------------------------ */
static void set_led_brightness(int magnitude)
{
    int duty = (magnitude * PWM_RANGE) / 1000;
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;
    gpioPWM(LED_GPIO, duty);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus 1 ---- */
    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open /dev/i2c-1: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, LSM303_I2C_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                LSM303_I2C_ADDR, strerror(errno));
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Configure magnetometer ---- */
    if (reg_write8(g_i2c_fd, LSM303_M_CTRL, LSM303_M_CTRL_SMPL) != 0) {
        fprintf(stderr, "Failed to set magnetometer sample rate\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (reg_write8(g_i2c_fd, LSM303_M_CTRL, LSM303_M_CTRL_ZEN_8) != 0) {
        fprintf(stderr, "Failed to set Z-axis resolution\n");
        cleanup();
        return EXIT_FAILURE;
    }
    /* Start measurements */
    if (reg_write8(g_i2c_fd, LSM303_M_CTRL, LSM303_M_CTRL_ZEN_8 | 0x80) != 0) {
        fprintf(stderr, "Failed to start magnetometer\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Configure LED GPIO ---- */
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioSetPWMrange(LED_GPIO, PWM_RANGE);
    gpioSetPWMfrequency(LED_GPIO, PWM_FREQ);
    gpioPWM(LED_GPIO, 0);

    /* ---- Open log file ---- */
    g_log_fp = fopen("mag_log.txt", "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open mag_log.txt: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    fprintf(g_log_fp, "--- LSM303DLHC magnetometer logging started ---\n");
    fflush(g_log_fp);

    /* ---- Main loop ---- */
    while (g_running) {
        int16_t x, y, z;
        if (read_magnetometer(g_i2c_fd, &x, &y, &z) != 0) {
            fprintf(stderr, "Sensor read error — skipping sample\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        int magnitude = calculate_magnitude(x, y, z);
        set_led_brightness(magnitude);

        fprintf(g_log_fp, "Mag: %d\n", magnitude);
        fflush(g_log_fp);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    fprintf(stderr, "\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

