/*
 * HMC5883L magnetometer reader with hard-iron offset tracking.
 *
 * Board:  Raspberry Pi Zero W
 * Bus:    I2C bus 1 (GPIO2 = SDA, GPIO3 = SCL)
 * Sensor: HMC5883L (DD0 = 0, 0x01 = 0x70)
 *
 * Build:  gcc -O2 -Wall -Wextra -o hmc5883l_offset hmc5883l_offset.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#include <pigpio.h>

/* ---- HMC5883L constants (datasheet rev 1.3) ---- */
#define HMC5883L_ADDR        0x3C
#define HMC5883L_CONFIG_A    0x00
#define HMC5883L_CONFIG_B    0x01
#define HMC5883L_MODE        0x02
#define HMC5883L_DATA_X_MSB  0x03
#define HMC5883L_DATA_Z_MSB  0x05
#define HMC5883L_DATA_Y_MSB  0x07

#define HMC5883L_CONFIG_A_VAL 0x70   /* 1 SPS, normal measurement */
#define HMC5883L_CONFIG_B_VAL 0x20   /* 8-average, 15 Hz output rate */
#define HMC5883L_MODE_VAL    0x00   /* Continuous-consecutive mode */

#define I2C_BUS        "/dev/i2c-1"
#define SAMPLE_PERIOD_US 500000   /* 500 ms */
#define WINDOW_SIZE     100

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a single byte to an 8-bit register. Returns 0 on success, -1 on error. */
static int reg_write(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s (wrote %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read `len` bytes starting at `reg` into `buf`. Returns 0 on success, -1 on error. */
static int reg_read(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s (got %zd bytes)\n",
                reg, strerror(errno), n);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read the 6 raw magnetic field samples (X, Z, Y) and return them in order. */
static int read_magnetometer(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t raw[6];
    if (reg_read(fd, HMC5883L_DATA_X_MSB, raw, sizeof(raw)) != 0)
        return -1;

    *x = (int16_t)((raw[0] << 8) | raw[1]);
    *z = (int16_t)((raw[2] << 8) | raw[3]);
    *y = (int16_t)((raw[4] << 8) | raw[5]);
    return 0;
}

/* ------------------------------------------------------------------ */
static void apply_offsets(int16_t x, int16_t y, int16_t z,
                           int16_t *x_off, int16_t *y_off, int16_t *z_off,
                           int *idx, int *sum, int *count)
{
    *x_off  += x;
    *y_off  += y;
    *z_off  += z;
    *sum   += x;
    *sum   += y;
    *sum   += z;
    *count++;
    if (*count > WINDOW_SIZE) {
        *x_off  -= (*sum / *count) / WINDOW_SIZE;
        *y_off  -= (*sum / *count) / WINDOW_SIZE;
        *z_off  -= (*sum / *count) / WINDOW_SIZE;
        *sum   = 0;
        *count = 0;
    }
    *x = x - *x_off;
    *y = y - *y_off;
    *z = z - *z_off;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    int16_t x_off = 0, y_off = 0, z_off = 0;
    int  x_sum = 0, y_sum = 0, z_sum = 0;
    int  x_count = 0, y_count = 0, z_count = 0;

    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, HMC5883L_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                HMC5883L_ADDR, strerror(errno));
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Configure HMC5883L ---- */
    if (reg_write(g_i2c_fd, HMC5883L_CONFIG_A, HMC5883L_CONFIG_A_VAL) != 0 ||
        reg_write(g_i2c_fd, HMC5883L_CONFIG_B, HMC5883L_CONFIG_B_VAL) != 0 ||
        reg_write(g_i2c_fd, HMC5883L_MODE, HMC5883L_MODE_VAL) != 0) {
        fprintf(stderr, "HMC5883L configuration failed\n");
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Main sampling loop ---- */
    while (g_running) {
        int16_t x, y, z;

        if (read_magnetometer(g_i2c_fd, &x, &y, &z) != 0) {
            fprintf(stderr, "I2C read error — continuing\n");
        } else {
            apply_offsets(x, y, z, &x_off, &y_off, &z_off,
                          &x_count, &x_sum, &x_count);
            printf("X: %6d  Y: %6d  Z: %6d\n", x, y, z);
            fflush(stdout);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* ---- Cleanup ---- */
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

