/*
 * LSM303D accelerometer monitor for Raspberry Pi Zero W
 *
 * Wiring:
 *   LSM303D SDA  -> Pi GPIO2  (physical pin 3, I2C bus 1 SDA)
 *   LSM303D SCL  -> Pi GPIO3  (physical pin 5, I2C bus 1 SCL)
 *   LSM303D INT1 -> Pi GPIO23 (physical pin 16)
 *   LSM303D VDD  -> 3.3 V
 *   LSM303D GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o lsm303d_mon lsm303d_mon.c -lgpiod
 *
 * Run:
 *   ./lsm303d_mon
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- LSM303D register definitions (datasheet rev 1.3) ---- */
#define LSM303D_ADDR        0x19

#define REG_WHO_AM_I        0x0F
#define WHO_AM_I_VAL        0x49

#define REG_CTRL1_XL        0x20
#define REG_CTRL2_G         0x21
#define REG_CTRL3_C         0x22
#define REG_CTRL4         0x23
#define REG_CTRL5         0x24
#define REG_CTRL6         0x25
#define REG_CTRL7         0x26
#define REG_CTRL8         0x27

#define REG_OUTX_L_XL       0x28
#define REG_OUTX_H_XL       0x29
#define REG_OUTY_L_XL       0x2A
#define REG_OUTY_H_XL       0x2B
#define REG_OUZ_L_XL       0x2C
#define REG_OUZ_H_XL       0x2D

#define REG_INT1_THS        0x10
#define REG_INT1_DURATION   0x11
#define REG_INT1_EN         0x12

#define REG_STATUS          0x27

/* Sensitivity: 0.061 mg/LSB for ±2 g range */
#define ACCEL_SENSITIVITY   0.061f

#define BUFFER_SIZE         64
#define SAMPLE_PERIOD_US    10000   /* 10 ms */
#define SAMPLES_TO_DISPLAY  10

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ---- */

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *val)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read16 from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *val = (int16_t)((uint16_t)buf[1] << 8 | buf[0]);
    return 0;
}

