    if (i2c_write_reg8(fd, REG_CTRL4, 0x00) != 0)
        return -1;

    /* CTRL5: 50 Hz ODR for accelerometer */
    if (i2c_write_reg8(fd, REG_CTRL5, 0x00) != 0)
        return -1;

    /* CTRL6: 50 Hz ODR for magnetometer */
    if (i2c_write_reg8(fd, REG_CTRL6, 0x00) != 0)
        return -1;

    /* CTRL7: 50 Hz ODR for accelerometer */
    if (i2c_write_reg8(fd, REG_CTRL7, 0x00) != 0)
        return -1;

    /* CTRL8: enable INT1 on rising edge */
    if (i2c_write_reg8(fd, REG_CTRL8, 0x04) != 0)
        return -1;

    /* INT1_THS: 2000 mg threshold (0x7E) */
    if (i2c_write_reg8(fd, REG_INT1_THS, 0x7E) != 0)
        return -1;

