        int idx = (cb->head - 1 - i + BUFFER_SIZE) % BUFFER_SIZE;
        printf("  X: %7.2f  Y: %7.2f  Z: %7.2f  ", cb->x[idx], cb->y[idx], cb->z[idx]);
