        if (gpiod_line_set_value(line1, 1) != 0) {
            perror("gpiod_line_set_value(line1, 1)");
            goto cleanup;
        }
        if (gpiod_line_set_value(line2, 0) != 0) {
            perror("gpiod_line_set_value(line2, 0)");
            goto cleanup;
