    if (line1 != NULL)
        (void)gpiod_line_set_value(line1, 0);
    if (line2 != NULL)
        (void)gpiod_line_set_value(line2, 0);

    if (line1 != NULL)
        gpiod_line_release(line1);
    if (line2 != NULL)
        gpiod_line_release(line2);
    if (chip != NULL)
        gpiod_chip_close(chip);

    if (rc == EXIT_SUCCESS)
        printf("\nClean shutdown complete.\n");
    return rc;
}

