/*
 * Dual-factor door-lock authentication system for Raspberry Pi 4 Model B.
 *
 * Ports:
 *   /dev/serial0  ->  GPIO14 (RX) + GPIO15 (TX)  ->  9600 8N1
 *   /dev/serial1  ->  GPIO18 (RX) + GPIO19 (TX)  ->  9600 8N1
 *
 * Relays (active-HIGH):
 *   GPIO17 -> 12 V electromagnetic lock 1
 *   GPIO27 -> 12 V electromagnetic lock 2
 *
 * Expected 6-digit code:  "123456"
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o door_lock dual_lock.c -lpigpio -lrt
 * Run:
 *   sudo ./door_lock
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <time.h>
#include <pigpio.h>

/* ---- Pin / UART / timing constants ---- */
#define LOCK1_PIN    17
#define LOCK2_PIN    27
#define UART0        "/dev/serial0"
#define UART1        "/dev/serial1"
#define BAUD_RATE    9600
#define CODE_LEN     6
#define EXPECTED_CODE "123456"
#define LOCK_DURATION_MS 2000
#define READ_TIMEOUT_MS 5000
#define POLL_DELAY_US  1000

/* ---- Globals for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_uart0 = -1;
static int  g_uart1 = -1;
static int  g_lock1 = 0;
static int  g_lock2 = 0;

/* ---- Library helpers ---- */
static void log_error(const char *msg)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];
    if (localtime_r(&t, &tm))
        strftime(ts, sizeof ts, "%Y-%m-%d %H:%M:%S", &tm);
    else
        snprintf(ts, sizeof ts, "unknown-time");
    fprintf(stderr, "[%s] ERROR: %s (errno=%d: %s)\n",
            ts, msg, errno, strerror(errno));
}

static void log_info(const char *msg)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];
    if (localtime_r(&t, &tm))
        strftime(ts, sizeof ts, "%Y-%m-%d %H:%M:%S", &tm);
    else
        snprintf(ts, sizeof ts, "unknown-time");
    printf("[%s] INFO: %s\n", ts, msg);
}

/* ---- GPIO helpers ---- */
static int safe_set_mode(unsigned pin, unsigned mode)
{
    if (gpioSetMode(pin, mode) < 0) {
        log_error("gpioSetMode failed");
        return -1;
    }
    return 0;
}

static int safe_write(unsigned pin, unsigned level)
{
    if (gpioWrite(pin, level) < 0) {
        log_error("gpioWrite failed");
        return -1;
    }
    return 0;
}

static void safe_set_locks(int l1, int l2)
{
    if (l1 < 0) safe_write(LOCK1_PIN, 0);
    if (l2 < 0) safe_write(LOCK2_PIN, 0);
}

/* ---- UART helpers ---- */
static int uart_open(const char *path, int baud)
{
    int h = serOpen(path, baud, 0);
    if (h < 0) {
        log_error("serOpen failed");
        return -1;
    }
    return h;
}

static int uart_read_nonblock(int handle, char *buf, size_t buf_len, int timeout_ms)
{
    int n = serDataAvailable(handle);
    if (n < 0) {
        log_error("serDataAvailable failed");
        return -1;
    }
    if (n == 0)
        return 0;

    size_t got = 0;
    while (got < buf_len && n > 0) {
        int c = serReadByte(handle);
        if (c < 0) {
            log_error("serReadByte failed");
            return -1;
        }
        if (c == '\n' || c == '\r') {
            buf[got] = '\0';
            break;
        }
        buf[got++] = (char)c;
        n = serDataAvailable(handle);
    }
    return (int)got;
}

/* ---- Code processing ---- */
static int code_matches(const char *c)
{
    if (c == NULL || *c == '\0')
        return 0;
    return strcmp(c, EXPECTED_CODE) == 0;
}

static int process_code(const char *code)
{
    if (!code_matches(code))
        return 0;
    if (safe_write(LOCK1_PIN, 1) < 0 || safe_write(LOCK2_PIN, 1) < 0) {
        log_error("Failed to energize relays");
        return -1;
    }
    gpioDelay(LOCK_DURATION_MS * 1000);
    safe_set_locks(0, 0);
    log_info("Door locks energized and de-energized successfully.");
    return 0;
}

/* ---- Signal handler ---- */
static void on_signal(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Main ---- */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return EXIT_FAILURE;
    }

    /* ---- GPIO setup ---- */
    if (safe_set_mode(LOCK1_PIN, PI_OUTPUT) < 0 ||
        safe_set_mode(LOCK2_PIN, PI_OUTPUT) < 0) {
        log_error("Failed to set GPIO modes");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    safe_set_locks(0, 0);

    /* ---- UART setup ---- */
    g_uart0 = uart_open(UART0, BAUD_RATE);
    if (g_uart0 < 0) {
        log_error("Failed to open UART0");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_uart1 = uart_open(UART1, BAUD_RATE);
    if (g_uart1 < 0) {
        log_error("Failed to open UART1");
        serClose(g_uart0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof sa);
    sa.sa_handler = on_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        log_error("sigaction failed");
        serClose(g_uart0);
        serClose(g_uart1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_info("Dual-factor door-lock system started.");

    char code[CODE_LEN + 1];
    char rx_buf[CODE_LEN + 1];
    int  rx_len = 0;

    while (g_running) {
        int n0 = uart_read_nonblock(g_uart0, rx_buf, sizeof rx_buf, READ_TIMEOUT_MS);
        if (n0 < 0) {
            log_error("UART0 read error; resetting");
            rx_len = 0;
            continue;
        }
        if (n0 > 0) {
            for (int i = 0; i < n0; i++) {
                if (rx_len < CODE_LEN) {
                    rx_buf[rx_len++] = rx_buf[i];
                } else {
                    rx_len = CODE_LEN;  /* overflow: reset */
                }
            }
            rx_buf[rx_len] = '\0';
            if (rx_len == CODE_LEN) {
                char c = rx_buf[CODE_LEN - 1];
                if (c >= '0' && c <= '9') {
                    char temp[CODE_LEN + 1];
                    strncpy(temp, rx_buf, CODE_LEN);
                    temp[CODE_LEN] = '\0';
                    if (process_code(temp) == 0) {
                        log_info("Authentication complete.");
                    }
                } else {
                    log_error("Invalid code received (non-digit)");
                }
            } else {
                log_error("Code buffer overflow; resetting");
                rx_len = 0;
            }
        }

        int n1 = uart_read_nonblock(g_uart1, rx_buf, sizeof rx_buf, READ_TIMEOUT_MS);
        if (n1 < 0) {
            log_error("UART1 read error; resetting");
            rx_len = 0;
            continue;
        }
        if (n1 > 0) {
            for (int i = 0; i < n1; i++) {
                if (rx_len < CODE_LEN) {
                    rx_buf[rx_len++] = rx_buf[i];
                } else {
                    rx_len = CODE_LEN;  /* overflow: reset */
                }
            }
            rx_buf[rx_len] = '\0';
            if (rx_len == CODE_LEN) {
                char c = rx_buf[CODE_LEN - 1];
                if (c >= '0' && c <= '9') {
                    char temp[CODE_LEN + 1];
                    strncpy(temp, rx_buf, CODE_LEN);
                    temp[CODE_LEN] = '\0';
                    if (process_code(temp) == 0) {
                        log_info("Authentication complete.");
                    }
                } else {
                    log_error("Invalid code received (non-digit)");
                }
            } else {
                log_error("Code buffer overflow; resetting");
                rx_len = 0;
            }
        }
    }

    /* ---- Cleanup ---- */
    log_info("Shutting down...");
    safe_set_locks(0, 0);
    if (g_uart0 >= 0) serClose(g_uart0);
    if (g_uart1 >= 0) serClose(g_uart1);
    gpioTerminate();
    return EXIT_SUCCESS;
}

