#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F
#define ACCEL_CONFIG 0x1C
#define ACCEL_SCALE 2.0f
#define BUFFER_SIZE 100
#define TIMER_INTERVAL_MS 10

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int timer_fd = -1;
static int32_t accel_x[BUFFER_SIZE];
static int32_t accel_y[BUFFER_SIZE];
static int32_t accel_z[BUFFER_SIZE];
static int head = 0;
static int tail = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read 16-bit from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *val = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int init_mpu6050(int fd) {
    if (i2c_write_reg8(fd, PWR_MGMT_1, 0x00) < 0) return -1;
    usleep(100000);
    if (i2c_write_reg8(fd, ACCEL_CONFIG, 0x00) < 0) return -1;
    return 0;
}

static int read_accel(int fd, int16_t *x, int16_t *y, int16_t *z) {
    if (i2c_read_reg16(fd, ACCEL_XOUT_H, x) < 0) return -1;
    if (i2c_read_reg16(fd, ACCEL_YOUT_H, y) < 0) return -1;
    if (i2c_read_reg16(fd, ACCEL_ZOUT_H, z) < 0) return -1;
    return 0;
}

static void timer_callback(int sig, siginfo_t *si, void *uc) {
    (void)sig; (void)si; (void)uc;
    int16_t raw_x, raw_y, raw_z;
    if (read_accel(i2c_fd, &raw_x, &raw_y, &raw_z) < 0) {
        fprintf(stderr, "Error reading accelerometer data\n");
        return;
    }
    accel_x[head] = (int32_t)raw_x;
    accel_y[head] = (int32_t)raw_y;
    accel_z[head] = (int32_t)raw_z;
    head = (head + 1) % BUFFER_SIZE;
    if (head == tail) tail = (tail + 1) % BUFFER_SIZE;

    char buf[256];
    snprintf(buf, sizeof(buf), "X=%d Y=%d Z=%d", raw_x, raw_y, raw_z);
    write(1, buf, strlen(buf));
}

static int init_timer(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_sigaction = timer_callback;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = SA_RESTART;
    if (sigaction(SIGRTMIN, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return -1;
    }

    struct sigevent sev;
    memset(&sev, 0, sizeof(sev));
    sev.sigev_notify = SIGEV_SIGNAL;
    sev.sigev_signo = SIGRTMIN;
    sev.sigev_value.sival_ptr = &timer_fd;

    if (timer_create(CLOCK_MONOTONIC, &sev, &timer_fd) < 0) {
        fprintf(stderr, "timer_create failed: %s\n", strerror(errno));
        return -1;
    }

    struct itimerspec its;
    its.it_interval.tv_sec = TIMER_INTERVAL_MS / 1000;
    its.it_interval.tv_nsec = (TIMER_INTERVAL_MS % 1000) * 1000000L;
    its.it_value = its.it_interval;
    if (timer_settime(timer_fd, 0, &its, NULL) < 0) {
        fprintf(stderr, "timer_settime failed: %s\n", strerror(errno));
        timer_create(-1, NULL, NULL);
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (timer_fd != -1) {
        timer_settime(timer_fd, 0, NULL);
        timer_delete(timer_fd);
        timer_fd = -1;
    }
    if (i2c_fd != -1) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        cleanup();
        return 1;
    }

    if (init_mpu6050(i2c_fd) < 0) {
        fprintf(stderr, "MPU6050 initialization failed (sensor absent or bus error)\n");
        cleanup();
        return 1;
    }

    if (init_timer() < 0) {
        fprintf(stderr, "Timer initialization failed\n");
        cleanup();
        return 1;
    }

    printf("MPU6050 initialized. Sampling at 100 Hz. Press Ctrl+C to exit.\n");

    while (running) {
        pause();
    }

    printf("\nExiting...\n");
    cleanup();
    return 0;
}

