/*
 * relay_toggle.c — Toggle four 5V relay modules on a Raspberry Pi 3 Model B+.
 *
 * Relays (BCM GPIO):
 *   Relay 1  -> GPIO18
 *   Relay 2  -> GPIO23
 *   Relay 3  -> GPIO24
 *   Relay 4  -> GPIO25
 *
 * Each relay is driven by a prime-numbered second interval:
 *   Relay 1: 2 s   (prime 2)
 *   Relay 2: 3 s   (prime 3)
 *   Relay 3: 5 s   (prime 5)
 *   Relay 4: 7 s   (prime 7)
 *
 * All drivers are checked for errors; on every exit path (SIGINT/SIGTERM)
 * the program turns off all relays and releases every resource.
 *
 * Build:  gcc -O2 -Wall -Wextra -o relay_toggle relay_toggle.c
 */

#include <errno.h>
#include <signal.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#include <gpiod.h>

#define NUM_RELAYS      4
#define GPIO_CHIP_NAME  "gpiochip0"

static const unsigned int relay_pins[NUM_RELAYS] = { 18, 23, 24, 25 };
static const int          intervals[NUM_RELAYS]    = { 2, 3, 5, 7 };

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */
static int set_relay(struct gpiod_line *line, int value)
{
    if (gpiod_line_set_value(line, value) < 0) {
        fprintf(stderr, "gpiod_line_set_value(%d) failed: %s\n",
                value, strerror(errno));
        return -1;
    }
    return 0;
}

static int all_relays_off(struct gpiod_line *lines[NUM_RELAYS])
{
    for (int i = 0; i < NUM_RELAYS; i++)
        if (set_relay(lines[i], 0) < 0)
            return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_RELAYS];
    bool lines_acquired = false;
    bool init_failed = false;

    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = NULL;
    }

    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "gpiod_chip_open_by_name(%s) failed: %s\n",
                GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "gpiod_chip_get_line(%u) failed: %s\n",
