#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define SOUND_SENSOR_PIN 17
#define RELAY_PIN 27
#define RELAY_DURATION_SEC 3
#define POLL_INTERVAL_US 100000
#define LOG_FILE "alarm_log.txt"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_alarm_event(void) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (!localtime_r(&t, &tm_info)) {
        fprintf(stderr, "localtime_r() failed\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s - Sound detected!\n", timestamp) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SOUND_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialize relay to OFF state\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    int relay_active = 0;

    while (running) {
        int sound_detected = gpioRead(SOUND_SENSOR_PIN);
        if (sound_detected < 0) {
            fprintf(stderr, "Error reading sound sensor on GPIO%d\n", SOUND_SENSOR_PIN);
            break;
        }

        if (sound_detected == 1 && !relay_active) {
            printf("Sound detected! Activating relay for %d seconds...\n", RELAY_DURATION_SEC);

            if (gpioWrite(RELAY_PIN, 1) != 0) {
                fprintf(stderr, "Failed to activate relay\n");
                break;
            }

            relay_active = 1;

            if (log_alarm_event() != 0) {
                fprintf(stderr, "Failed to log alarm event\n");
            }

            for (int i = 0; i < RELAY_DURATION_SEC * 10 && running; i++) {
                gpioDelay(POLL_INTERVAL_US / 10);
            }

            if (gpioWrite(RELAY_PIN, 0) != 0) {
                fprintf(stderr, "Failed to deactivate relay\n");
                break;
            }

            relay_active = 0;
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();

    return EXIT_SUCCESS;
}

