/*
 * MPU-6050 Gyroscope Monitor for Raspberry Pi 3 Model B+
 * Uses pigpio for I2C communication.
 *
 * Wiring:
 *   MPU-6050 SDA -> GPIO2 (BCM)
 *   MPU-6050 SCL -> GPIO3 (BCM)
 *   MPU-6050 VCC -> 3.3V
 *   MPU-6050 GND -> GND
 *
 * Build: gcc -o gyro_monitor gyro_monitor.c -lpigpio -lrt
 * Run:   sudo ./gyro_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MPU6050_ADDR 0x68

#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43
#define GYRO_YOUT_H 0x45
#define GYRO_ZOUT_H 0x47

#define BUFFER_SIZE 100
#define THRESHOLD 50.0f

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} gyro_data_t;

static gyro_data_t gyro_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

static int i2c_handle = -1;

static void add_gyro_data(float x, float y, float z) {
    gyro_buffer[buffer_index].x = (int16_t)(x * 1000.0f);
    gyro_buffer[buffer_index].y = (int16_t)(y * 1000.0f);
    gyro_buffer[buffer_index].z = (int16_t)(z * 1000.0f);
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

static float calculate_magnitude(float x, float y, float z) {
    return sqrtf(x * x + y * y + z * z);
}

static void check_threshold(float magnitude) {
    if (magnitude > THRESHOLD) {
        printf("Threshold exceeded! Magnitude: %.2f degrees/second\n", magnitude);
    }
}

static int init_mpu6050(void) {
    i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }

    // Wake up the MPU-6050 (clear sleep bit)
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error writing to PWR_MGMT_1 register\n");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    return 0;
}

static int read_gyro_data(gyro_data_t *data) {
    char buf[6];

    // Read 6 bytes starting from GYRO_XOUT_H
    if (i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error reading gyro data\n");
        return -1;
    }

    data->x = (int16_t)((buf[0] << 8) | buf[1]);
    data->y = (int16_t)((buf[2] << 8) | buf[3]);
    data->z = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_mpu6050() != 0) {
        fprintf(stderr, "MPU-6050 initialisation failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MPU-6050 Gyroscope Monitor started. Press Ctrl+C to exit.\n");

    while (running) {
        gyro_data_t gyro_data;

        if (read_gyro_data(&gyro_data) == 0) {
            float x = (float)gyro_data.x / 1000.0f;
            float y = (float)gyro_data.y / 1000.0f;
            float z = (float)gyro_data.z / 1000.0f;

            add_gyro_data(x, y, z);
            check_threshold(calculate_magnitude(x, y, z));
        } else {
            fprintf(stderr, "Failed to read gyro data. Retrying...\n");
        }

        gpioDelay(10000); // 10ms delay
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

