    return 0;
}

static int read_gyro_data(gyro_data_t *data) {
    char buf[6];

    // Read 6 bytes starting from GYRO_XOUT_H
    if (i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error reading gyro data\n");
        return -1;
    }

    data->x = (int16_t)((buf[0] << 8) | buf[1]);
    data->y = (int16_t)((buf[2] << 8) | buf[3]);
    data->z = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_mpu6050() != 0) {
        fprintf(stderr, "MPU-6050 initialisation failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MPU-6050 Gyroscope Monitor started. Press Ctrl+C to exit.\n");

    while (running) {
        gyro_data_t gyro_data;

        if (read_gyro_data(&gyro_data) == 0) {
            float x = (float)gyro_data.x / 1000.0f;
            float y = (float)gyro_data.y / 1000.0f;
            float z = (float)gyro_data.z / 1000.0f;

            add_gyro_data(x, y, z);
            check_threshold(calculate_magnitude(x, y, z));
        } else {
            fprintf(stderr, "Failed to read gyro data. Retrying...\n");
        }

        gpioDelay(10000); // 10ms delay
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

