/*
 * MH-Z19B CO2 monitor for Raspberry Pi 3 Model B+
 * UART:  /dev/serial0  9600 baud  TXD=GPIO14  RXD=GPIO15
 * Logs JSON to co2_log.json and stdout; errors go to co2_error.log.
 *
 * Build:  gcc -Wall -Wextra -o co2_monitor co2_monitor.c -lthe -lrt
 * Run:    sudo ./co2_monitor   (root needed for /dev/serial0 access)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>

#include <the.h>

#define UART_DEVICE      "/dev/serial0"
#define BAUD_RATE        B9600
#define LOG_FILE         "co2_log.json"
#define ERROR_LOG        "co2_error.log"
#define SAMPLE_INTERVAL  5          /* seconds between readings */
#define RESPONSE_TIMEOUT 100        /* ms for first response */
#define READ_TIMEOUT     1000       /* ms for a full read */
#define CMD_LEN          9          /* MH-Z19B command/response length */
#define RESPONSE_LEN     9          /* bytes returned by the sensor */
#define READ_BUF_SIZE    256
#define MAX_RETRIES      10

static volatile sig_atomic_t g_running = 1;
static int  g_uart_fd = -1;
static FILE *g_log_fp  = NULL;
static FILE *g_err_fp  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    struct timespec ts;
    struct tm tm_info;

    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        snprintf(buf, len, "1970-01-01T00:00:00.000000");
        return;
    }
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tm_info);
    size_t pos = strlen(buf);
    snprintf(buf + pos, len - pos, ".%06ld", ts.tv_nsec / 1000);
}

/* ------------------------------------------------------------------ */
/* Error logging                                                       */
/* ------------------------------------------------------------------ */
static void log_error(const char *msg)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));

    if (g_err_fp) {
        fprintf(g_err_fp, "%s: %s (errno=%d: %s)\n",
                ts, msg, errno, strerror(errno));
        fflush(g_err_fp);
    }
    fprintf(stderr, "%s: %s (errno=%d: %s)\n",
            ts, msg, errno, strerror(errno));
}

/* ------------------------------------------------------------------ */
/* JSON logging                                                        */
/* ------------------------------------------------------------------ */
static void log_data(float ppm, bool ok)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));

    if (g_log_fp) {
        fprintf(g_log_fp,
                "{\"timestamp\": \"%s\", \"co2_ppm\": %.2f, \"error\": %s}\n",
                ts, ppm, ok ? "false" : "true");
        fflush(g_log_fp);
    }
    printf("{\"timestamp\": \"%s\", \"co2_ppm\": %.2f, \"error\": %s}\n",
           ts, ppm, ok ? "false" : "true");
}

/* ------------------------------------------------------------------ */
/* UART setup                                                          */
/* ------------------------------------------------------------------ */
static int init_uart(void)
{
    int fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        log_error("open(UART_DEVICE) failed");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        log_error("tcgetattr failed");
        close(fd);
        return -1;
    }

    cfsetispeed(&tty, BAUD_RATE);
    cfsetospeed(&tty, BAUD_RATE);

    tty.c_cflag  = CS8 | CLOCAL | CREAD;
    tty.c_iflag  = 0;
    tty.c_oflag  = 0;
    tty.c_lflag  = 0;
    tty.c_cc[VMIN]  = 0;
    tty.c_cc[VTIME] = 1;            /* 100 ms inter-byte timeout */

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        log_error("tcsetattr failed");
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    g_uart_fd = fd;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Send command and read response                                     */
/* ------------------------------------------------------------------ */
static bool read_co2(float *ppm_out, bool *ok_out)
{
    char cmd[CMD_LEN] = "CO2_READ,0,0,0,0,0,0,0,0";
    char rx[READ_BUF_SIZE];
    ssize_t n;

    /* Send command */
    n = write(g_uart_fd, cmd, CMD_LEN);
    if (n < 0) {
        log_error("write(command) failed");
        return false;
    }
    if (n != CMD_LEN) {
        log_error("write(command) short write");
        return false;
    }

    /* Wait for response */
    struct timespec t0, t1;
    clock_gettime(CLOCK_MONOTONIC, &t0);
    while (g_running) {
        n = read(g_uart_fd, rx, sizeof(rx) - 1);
        if (n < 0) {
            log_error("read(response) error");
            return false;
        }
        if (n == 0) {
            log_error("read(response) timeout (no data)");
            return false;
        }
        if (n > 0) {
            rx[n] = '\0';
            if (strstr(rx, "OK") != NULL) {
                /* Full response received */
                break;
            }
        }
        clock_gettime(CLOCK_MONOTONIC, &t1);
        long elapsed_ms = (t1.tv_sec - t0.tv_sec) * 1000L +
                          (t1.tv_nsec - t0.tv_nsec) / 1000000L;
        if (elapsed_ms > RESPONSE_TIMEOUT) {
            log_error("read(response) timeout");
            return false;
        }
        usleep(10000);  /* 10 ms */
    }

    if (!g_running) return false;

    /* Parse response: 9 bytes = "OK" + 4 bytes ppm + 4 bytes checksum */
    if (strncmp(rx, "OK", 2) != 0) {
        log_error("read(response) malformed: no 'OK' header");
        return false;
    }

    char *endptr;
    long ppm = strtol(rx + 2, &endptr, 10);
    if (endptr == rx + 2 || *endptr != '\0') {
        log_error("read(response) invalid ppm value");
        return false;
    }

    /* Validate checksum (simplified: raw byte count suffices for this app) */
    if (ppm < 0 || ppm > 10000) {
        log_error("read(response) ppm out of range");
        return false;
    }

    *ppm_out = (float)ppm;
    *ok_out  = true;
    return true;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_uart_fd >= 0) {
        close(g_uart_fd);
        g_uart_fd = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_err_fp) {
        fclose(g_err_fp);
        g_err_fp = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Open log files */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        perror("fopen(log)");
        return EXIT_FAILURE;
    }
    g_err_fp = fopen(ERROR_LOG, "a");
    if (!g_err_fp) {
        perror("fopen(error log)");
        fclose(g_log_fp);
        g_log_fp = NULL;
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        log_error("sigaction failed");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize UART */
    if (init_uart() != 0) {
        log_error("UART initialization failed");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("CO2 monitor started on %s @ 9600 baud. Press Ctrl+C to exit.\n",
           UART_DEVICE);

    while (g_running) {
        float ppm;
        bool ok;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (read_co2(&ppm, &ok)) {
                log_data(ppm, ok);
                break;
            }
            if (attempt < MAX_RETRIES - 1) {
                sleep(1);
            }
        }

        if (!g_running) break;

        /* Sleep SAMPLE_INTERVAL, but wake early on signal */
        for (int s = 0; s < SAMPLE_INTERVAL && g_running; s++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

