/*
 * Raspberry Pi 5 – BH1750 ambient light sensor + RGB relay lamp controller
 *
 * Hardware:
 *   - BH1750 on I2C bus 1, address 0x10 (ADDR pin tied to GND)
 *   - RED relay on GPIO 17 (BCM), GREEN on GPIO 27, BLUE on GPIO 22
 *
 * Behavior:
 *   - Polls the BH1750 every 1 s, waits 120 ms after each conversion
 *   - Logs timestamp, lux, and relay states to lighting_log.txt
 *   - Turns on RED when lux < 50, GREEN when 50–150, BLUE when 150–300
 *   - All three when lux > 300
 *   - Handles I2C errors, file errors, and clean shutdown on signals
 *
 * Build:  gcc -O2 -Wall -Wextra -o light_control light_control.c -lpigpio -lrt
 * Run:    sudo ./light_control
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define BH1750_ADDR          0x10          /* ADDR pin tied to GND          */
#define BH1750_CONV_MS       120           /* conversion wait (ms)          */
#define POLL_INTERVAL_S      1             /* sampling interval (s)        */
#define LUX_THRESHOLD_RED     50
#define LUX_THRESHOLD_GREEN  150
#define LUX_THRESHOLD_BLUE   300
#define LOG_FILE             "lighting_log.txt"
#define GPIO_RED             17
#define GPIO_GREEN           27
#define GPIO_BLUE            22

/* BH1750 commands */
#define BH1750_CMD_CONT     0x10           /* continuous high-resolution mode */
#define BH1750_CMD_ONE_HR   0x10           /* one-time high-resolution       */
#define BH1750_ONE_HR_MS    120            /* one-time conversion time (ms) */

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd = -1;
static FILE    *g_log_fp = NULL;

/* --------------------------- Function prototypes -------------------------- */
static int  init_i2c(void);
static int  read_bh1750(uint16_t *lux_out);
static void set_relay(int gpio, int on);
static void log_data(uint16_t lux, int red, int green, int blue);
static void cleanup(void);
static void signal_handler(int sig);

/* ------------------------------- Main ------------------------------------ */
int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure relay GPIOs as outputs, ensure OFF */
    int relays[] = {GPIO_RED, GPIO_GREEN, GPIO_BLUE};
    for (size_t i = 0; i < sizeof(relays) / sizeof(relays[0]); ++i) {
        if (gpioSetMode(relays[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", relays[i]);
            cleanup();
            return EXIT_FAILURE;
        }
        gpioWrite(relays[i], 0);
    }

    /* Initialize I2C */
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Light control started. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t lux = 0;

        if (read_bh1750(&lux) != 0) {
            fprintf(stderr, "BH1750 read error – skipping cycle\n");
        } else {
            int red   = (lux < LUX_THRESHOLD_RED) ? 1 : 0;
            int green = (lux < LUX_THRESHOLD_GREEN) ? 1 : 0;
            int blue  = (lux < LUX_THRESHOLD_BLUE) ? 1 : 0;

            set_relay(GPIO_RED,   red);
            set_relay(GPIO_GREEN, green);
            set_relay(GPIO_BLUE,  blue);

            log_data(lux, red, green, blue);
        }

        sleep(POLL_INTERVAL_S);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

/* --------------------------- I2C / sensor init ---------------------------- */
static int init_i2c(void)
{
    g_i2c_fd = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "i2cOpen failed (bus %d, addr 0x%02X): %s\n",
                I2C_BUS, BH1750_ADDR, strerror(errno));
        return -1;
    }

    /* Start continuous high-resolution mode */
    if (i2cWriteByte(g_i2c_fd, BH1750_CMD_CONT) != 0) {
        fprintf(stderr, "Failed to write BH1750 command: %s\n", strerror(errno));
        i2cClose(g_i2c_fd);
        g_i2c_fd = -1;
        return -1;
    }

    return 0;
}

static int read_bh1750(uint16_t *lux_out)
{
    if (lux_out == NULL) {
        return -1;
    }

    /* Trigger one-time high-resolution conversion */
    if (i2cWriteByte(g_i2c_fd, BH1750_CMD_ONE_HR) != 0) {
        fprintf(stderr, "i2cWriteByte (one-shot) failed: %s\n", strerror(errno));
        return -1;
    }

    /* Wait for conversion to complete */
    gpioDelay(BH1750_ONE_HR_MS * 1000);  /* microseconds */

    /* Read 2 bytes from the sensor */
    char buf[2];
    int n = i2cReadDevice(g_i2c_fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "i2cReadDevice returned %d: %s\n", n, strerror(errno));
        return -1;
    }

    /* BH1750 returns 2 data bytes in big-endian order */
    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *lux_out = raw;
    return 0;
}

/* --------------------------- Relay control -------------------------------- */
static void set_relay(int gpio, int on)
{
    if (gpioWrite(gpio, on) != 0) {
        fprintf(stderr, "gpioWrite(%d, %d) failed\n", gpio, on);
    }
}

/* --------------------------- Logging -------------------------------------- */
static void log_data(uint16_t lux, int red, int green, int blue)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(g_log_fp, "%s, Lux: %u, Red: %d, Green: %d, Blue: %d\n",
                ts, lux, red, green, blue) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
    }

    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
    }
}

/* --------------------------- Cleanup ------------------------------------- */
static void cleanup(void)
{
    /* Turn off all relays */
    set_relay(GPIO_RED,   0);
    set_relay(GPIO_GREEN, 0);
    set_relay(GPIO_BLUE,  0);

    /* Close log file */
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }

    /* Close I2C if open */
    if (g_i2c_fd >= 0) {
        i2cClose(g_i2c_fd);
        g_i2c_fd = -1;
    }

    /* Release pigpio resources */
    gpioTerminate();
}

/* --------------------------- Signal handler ------------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

