/*
 * Raspberry Pi 5 – BH1750 ambient light sensor + RGB relay lamp controller
 *
 * Hardware:
 *   - BH1750 on I2C bus 1, address 0x10 (ADDR pin tied to GND)
 *   - RED relay on GPIO 17 (BCM), GREEN on GPIO 27, BLUE on GPIO 22
 *
 * Behavior:
 *   - Polls the BH1750 every 1 s, waits 120 ms after each conversion
 *   - Logs timestamp, lux, and relay states to lighting_log.txt
 *   - Turns on RED when lux < 50, GREEN when 50–150, BLUE when 150–300
 *   - All three when lux > 300
 *   - Handles I2C errors, file errors, and clean shutdown on signals
 *
 * Build:  gcc -O2 -Wall -Wextra -o light_control light_control.c -lpigpio -lrt
 * Run:    sudo ./light_control
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

