        fprintf(stderr, "i2cWriteByte (one-shot) failed: %s\n", strerror(errno));
        return -1;
    }

    /* Wait for conversion to complete */
    gpioDelay(BH1750_ONE_HR_MS * 1000);  /* microseconds */

    /* Read 2 bytes from the sensor */
    char buf[2];
