/* --------------------------- Relay control -------------------------------- */
static void set_relay(int gpio, int on)
{
    if (gpioWrite(gpio, on) != 0) {
        fprintf(stderr, "gpioWrite(%d, %d) failed\n", gpio, on);
    }
}

/* --------------------------- Logging -------------------------------------- */
static void log_data(uint16_t lux, int red, int green, int blue)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(g_log_fp, "%s, Lux: %u, Red: %d, Green: %d, Blue: %d\n",
                ts, lux, red, green, blue) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
    }

    if (fflush(g_log_fp) != 0) {
