/*
 * Dual L298N motor driver control with proportional speed
 * based on simulated ultrasonic distance readings.
 *
 * Board:  Raspberry Pi 3 Model B+
 * Library: pigpio (http://abyz.me.uk/rpi/pigpio/)
 *
 * Wiring:
 *   Motor A IN1 -> GPIO17 (BCM)
 *   Motor A IN2 -> GPIO18 (BCM)  [PWM0]
 *   Motor B IN3 -> GPIO22 (BCM)
 *   Motor B IN4 -> GPIO23 (BCM)  [PWM1]
 *
 * Build:  gcc -O2 -Wall -o motor_control motor_control.c -lpigpio -lrt
 * Run:    sudo ./motor_control
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18   /* PWM0 */
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23   /* PWM1 */

/* ---- PWM parameters ---- */
#define PWM_FREQUENCY 1000   /* Hz */
#define PWM_RANGE     255    /* duty-cycle steps */

/* ---- Distance parameters ---- */
#define MIN_DISTANCE_CM 10.0f
#define MAX_DISTANCE_CM 100.0f
#define THRESHOLD_CM    50.0f

/* ---- Control loop ---- */
#define LOOP_DELAY_US 100000  /* 100 ms */

/* ---- Globals ---- */
static volatile sig_atomic_t g_running = 1;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Motor primitives ---- */
static int motor_stop(void)
{
    if (gpioWrite(MOTOR_A_IN1, 0) < 0) return -1;
    if (gpioWrite(MOTOR_A_IN2, 0) < 0) return -1;
    if (gpioWrite(MOTOR_B_IN3, 0) < 0) return -1;
    if (gpioWrite(MOTOR_B_IN4, 0) < 0) return -1;
    return 0;
}

static int motor_forward(float duty)
{
    if (gpioWrite(MOTOR_A_IN1, 1) < 0) return -1;
    if (gpioWrite(MOTOR_A_IN2, 1) < 0) return -1;
    if (gpioWrite(MOTOR_B_IN3, 1) < 0) return -1;
    if (gpioWrite(MOTOR_B_IN4, 1) < 0) return -1;
    if (gpioPWM(MOTOR_A_IN2, (int)duty) < 0) return -1;
    if (gpioPWM(MOTOR_B_IN4, (int)duty) < 0) return -1;
    return 0;
}

static int motor_backward(float duty)
{
    if (gpioWrite(MOTOR_A_IN1, 1) < 0) return -1;
    if (gpioWrite(MOTOR_A_IN2, 0) < 0) return -1;
    if (gpioWrite(MOTOR_B_IN3, 1) < 0) return -1;
    if (gpioWrite(MOTOR_B_IN4, 0) < 0) return -1;
    if (gpioPWM(MOTOR_A_IN2, (int)duty) < 0) return -1;
    if (gpioPWM(MOTOR_B_IN4, (int)duty) < 0) return -1;
    return 0;
}

/* ---- Proportional speed control ---- */
static int set_motor_speed(int motor, float distance)
{
    float duty = 0.0f;

    if (distance < THRESHOLD_CM) {
        duty = (distance - MIN_DISTANCE_CM) /
               (MAX_DISTANCE_CM - MIN_DISTANCE_CM) * PWM_RANGE;
        if (duty > PWM_RANGE) duty = PWM_RANGE;
        if (duty < 0.0f) duty = 0.0f;
    } else {
        duty = 0.0f;
    }

    int pwm_val = (int)duty;
    if (gpioPWM(motor, pwm_val) < 0) {
        fprintf(stderr, "gpioPWM failed for motor %d (pwm_val=%d)\n", motor, pwm_val);
        return -1;
    }
    return 0;
}

/* ---- Main ---- */
int main(void)
{
    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure motor control pins ---- */
    if (gpioSetMode(MOTOR_A_IN1, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", MOTOR_A_IN1);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(MOTOR_A_IN2, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", MOTOR_A_IN2);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(MOTOR_B_IN3, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", MOTOR_B_IN3);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(MOTOR_B_IN4, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", MOTOR_B_IN4);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Set PWM frequency ---- */
    if (gpioSetPWMfrequency(MOTOR_A_IN2, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO%d\n", MOTOR_A_IN2);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(MOTOR_B_IN4, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO%d\n", MOTOR_B_IN4);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Set PWM range ---- */
    if (gpioSetPWMrange(MOTOR_A_IN2, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO%d\n", MOTOR_A_IN2);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(MOTOR_B_IN4, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO%d\n", MOTOR_B_IN4);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Ensure motors are stopped ---- */
    if (motor_stop() < 0) {
        fprintf(stderr, "Failed to stop motors initially\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        motor_stop();
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        motor_stop();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Motor control started. Press Ctrl+C to exit.\n");

    /* ---- Main control loop ---- */
    while (g_running) {
        float distance_a = 50.0f;   /* Motor A distance (cm) */
        float distance_b = 75.0f;   /* Motor B distance (cm) */

        /* Forward if distance < threshold, else backward */
        if (distance_a < THRESHOLD_CM) {
            if (motor_forward(set_motor_speed(0, distance_a)) < 0) {
                fprintf(stderr, "Motor forward failed\n");
            }
        } else {
            if (motor_backward(set_motor_speed(0, distance_a)) < 0) {
                fprintf(stderr, "Motor backward failed\n");
            }
        }

        if (distance_b < THRESHOLD_CM) {
            if (motor_forward(set_motor_speed(0, distance_b)) < 0) {
                fprintf(stderr, "Motor forward failed\n");
            }
        } else {
            if (motor_backward(set_motor_speed(0, distance_b)) < 0) {
                fprintf(stderr, "Motor backward failed\n");
            }
        }

        gpioDelay(LOOP_DELAY_US);
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    motor_stop();
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

