    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure motor control pins ---- */
    if (gpioSetMode(MOTOR_A_IN1, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", MOTOR_A_IN1);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(MOTOR_A_IN2, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", MOTOR_A_IN2);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(MOTOR_B_IN3, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", MOTOR_B_IN3);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(MOTOR_B_IN4, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", MOTOR_B_IN4);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Set PWM frequency ---- */
    if (gpioSetPWMfrequency(MOTOR_A_IN2, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO%d\n", MOTOR_A_IN2);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(MOTOR_B_IN4, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency on GPIO%d\n", MOTOR_B_IN4);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Set PWM range ---- */
    if (gpioSetPWMrange(MOTOR_A_IN2, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO%d\n", MOTOR_A_IN2);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(MOTOR_B_IN4, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range on GPIO%d\n", MOTOR_B_IN4);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Ensure motors are stopped ---- */
    if (motor_stop() < 0) {
        fprintf(stderr, "Failed to stop motors initially\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        motor_stop();
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        motor_stop();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Motor control started. Press Ctrl+C to exit.\n");

    /* ---- Main control loop ---- */
    while (g_running) {
        float distance_a = 50.0f;   /* Motor A distance (cm) */
        float distance_b = 75.0f;   /* Motor B distance (cm) */

        /* Forward if distance < threshold, else backward */
        if (distance_a < THRESHOLD_CM) {
            if (motor_forward(set_motor_speed(0, distance_a)) < 0) {
                fprintf(stderr, "Motor forward failed\n");
            }
        } else {
            if (motor_backward(set_motor_speed(0, distance_a)) < 0) {
                fprintf(stderr, "Motor backward failed\n");
            }
        }

        if (distance_b < THRESHOLD_CM) {
            if (motor_forward(set_motor_speed(0, distance_b)) < 0) {
                fprintf(stderr, "Motor forward failed\n");
            }
        } else {
            if (motor_backward(set_motor_speed(0, distance_b)) < 0) {
                fprintf(stderr, "Motor backward failed\n");
            }
        }

        gpioDelay(LOOP_DELAY_US);
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    motor_stop();
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

