/*
 * Door-lock control using a 28BYJ-48 stepper motor via an L293D H-bridge.
 *
 * Wiring (Raspberry Pi BCM numbering):
 *   GPIO17 -> L293D IN1
 *   GPIO18 -> L293D IN2
 *   GPIO27 -> L293D IN3
 *   GPIO22 -> L293D IN4
 *   GPIO24 -> LOCK button (active-LOW, internal pull-up)
 *   GPIO23 -> UNLOCK button (active-LOW, internal pull-up)
 *
 * Build:  gcc -O2 -Wall -Wextra -o door_lock door_lock.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <pigpio.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define MOTOR_PIN1 17
#define MOTOR_PIN2 18
#define MOTOR_PIN3 27
#define MOTOR_PIN4 22
#define LOCK_PIN   24
#define UNLOCK_PIN 23

/* ---- Motor parameters ---- */
#define STEPS_PER_REVOLUTION 512          /* 28BYJ-48: 512 half-steps/rev */
#define STEP_DELAY_US        2000         /* 2 ms between half-steps */
#define ROTATION_STEPS      512           /* 1/4 turn per press */

/* ---- Button flags ---- */
typedef struct {
    bool locked;
    bool unlocked;
} ButtonState;

/* ---- Signal handling ---- */
static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Motor helpers ---- */
static void motor_off(void)
{
    gpioWrite(MOTOR_PIN1, 0);
    gpioWrite(MOTOR_PIN2, 0);
    gpioWrite(MOTOR_PIN3, 0);
    gpioWrite(MOTOR_PIN4, 0);
}

static void motor_step(int step)
{
    /* Full-step two-phase sequence: phase A -> phase B -> phase C -> phase D */
    switch (step) {
        case 0:  gpioWrite(MOTOR_PIN1, 1); gpioWrite(MOTOR_PIN2, 0);
                gpioWrite(MOTOR_PIN3, 0); gpioWrite(MOTOR_PIN4, 0); break;
        case 1:  gpioWrite(MOTOR_PIN1, 0); gpioWrite(MOTOR_PIN2, 1);
                gpioWrite(MOTOR_PIN3, 0); gpioWrite(MOTOR_PIN4, 0); break;
        case 2:  gpioWrite(MOTOR_PIN1, 0); gpioWrite(MOTOR_PIN2, 0);
                gpioWrite(MOTOR_PIN3, 1); gpioWrite(MOTOR_PIN4, 0); break;
        case 3:  gpioWrite(MOTOR_PIN1, 0); gpioWrite(MOTOR_PIN2, 0);
                gpioWrite(MOTOR_PIN3, 0); gpioWrite(MOTOR_PIN4, 1); break;
        default: motor_off(); break;
    }
}

static void motor_rotate(int steps, int direction)
{
    if (direction == 0) {
        for (int i = 0; i < steps && g_running; i++)
            motor_step(direction + i % 4);
    } else {
        for (int i = 0; i < steps && g_running; i++)
            motor_step(direction - i % 4);
    }
}

/* ---- Button helpers ---- */
static ButtonState read_buttons(void)
{
    ButtonState bs = { false, false };
    int lv = gpioRead(LOCK_PIN);
    int uv = gpioRead(UNLOCK_PIN);

    if (lv == 0) bs.locked = true;
    if (uv == 0) bs.unlocked = true;

    return bs;
}

static void update_button_state(ButtonState *bs)
{
    gpioDelay(10000); /* 10 ms debounce */
    int lv = gpioRead(LOCK_PIN);
    int uv = gpioRead(UNLOCK_PIN);

    if (lv == 0 && !bs->locked) bs->locked = true;
    if (uv == 0 && !bs->unlocked) bs->unlocked = true;
}

/* ---- Lock/unlock ---- */
static void lock_door(void)
{
    printf("Locking door...\n");
    fflush(stdout);

    ButtonState bs = read_buttons();
    if (bs.locked) {
        printf("Door is already locked.\n");
        fflush(stdout);
        return;
    }

    if (!g_running) return;

    motor_rotate(ROTATION_STEPS, 1);
    motor_off();
    printf("Door locked.\n");
    fflush(stdout);
}

static void unlock_door(void)
{
    printf("Unlocking door...\n");
    fflush(stdout);

    ButtonState bs = read_buttons();
    if (bs.unlocked) {
        printf("Door is already unlocked.\n");
        fflush(stdout);
        return;
    }

    if (!g_running) return;

    motor_rotate(ROTATION_STEPS, -1);
    motor_off();
    printf("Door unlocked.\n");
    fflush(stdout);
}

/* ---- Main ---- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure motor pins as outputs */
    if (gpioSetMode(MOTOR_PIN1, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_PIN2, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_PIN3, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_PIN4, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set motor pin modes.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure button pins as inputs with pull-ups */
    if (gpioSetMode(LOCK_PIN, PI_INPUT) != 0 ||
        gpioSetMode(UNLOCK_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set button pin modes.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(LOCK_PIN, PI_PUD_UP) != 0 ||
        gpioSetPullUpDown(UNLOCK_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set button pull-ups.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Door-lock control ready. Press LOCK (GPIO24) to lock, UNLOCK (GPIO23) to unlock.\n");
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    ButtonState button_state = { false, false };

    while (g_running) {
        ButtonState bs = read_buttons();
        update_button_state(&button_state);

        if (button_state.locked && !button_state.unlocked) {
            lock_door();
        } else if (button_state.unlocked && !button_state.locked) {
            unlock_door();
        }

        gpioDelay(10000); /* 10 ms poll interval */
    }

    /* Clean shutdown */
    motor_off();
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

