#include <linux/i2c.h>
#include <sys/stat.h>
#include <sys/types.h>

#define MPU6050_ADDR 0x68
#define MPU6050_PWR_MGMT_1 0x6B
#define MPU6050_ACCEL_XOUT_H 0x3B
#define MPU6050_ACCEL_YOUT_H 0x3D
#define MPU6050_ACCEL_ZOUT_H 0x3F
#define PWM_CHIP 2
#define PWM_CHANNEL 0
#define PWM_PERIOD_NS 20000000
#define PWM_DUTY_NS 0
#define LOG_FILE "solar_tracker.log"
#define I2C_BUS "/dev/i2c-1"
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static int pwm_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    for (int i = 0; i < MAX_RETRIES; i++) {
        if (write(fd, buf, 2) == 2) return 0;
        usleep(1000 << i);
    }
    return -1;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, int len) {
    for (int i = 0; i < MAX_RETRIES; i++) {
        if (write(fd, &reg, 1) == 1) {
            if (read(fd, buf, len) == len) return 0;
        }
        usleep(1000 << i);
    }
    return -1;
}

static int init_mpu6050(int fd) {
    if (i2c_write_byte(fd, MPU6050_PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Could not wake MPU6050\n");
        return -1;
    }
    usleep(100000);
    return 0;
}

static int read_accel(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read_burst(fd, MPU6050_ACCEL_XOUT_H, buf, 6) < 0) {
        fprintf(stderr, "Error: Could not read accelerometer data\n");
        return -1;
    }
    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

static float calculate_pitch(int16_t x, int16_t y, int16_t z) {
    float roll = atan2f((float)(x - z), (float)(y - z)) * 180.0f / M_PI;
    float pitch = atan2f((float)(y), sqrtf((float)(x * x) + (float)(z * z))) * 180.0f / M_PI;
    return pitch;
}

static int init_pwm(void) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d", PWM_CHIP, PWM_CHANNEL);
    pwm_fd = open(path, O_WRONLY);
    if (pwm_fd < 0) {
        perror("Error opening PWM sysfs");
        return -1;
    }
    FILE *ef = fopen(path "/period", "w");
    if (ef) { fprintf(ef, "%d", PWM_PERIOD_NS); fclose(ef); }
    else { perror("Error setting period"); close(pwm_fd); pwm_fd = -1; return -1; }
    FILE *df = fopen(path "/duty_cycle", "w");
    if (df) { fprintf(df, "%d", PWM_DUTY_NS); fclose(df); }
    else { perror("Error setting duty cycle"); close(pwm_fd); pwm_fd = -1; return -1; }
    return 0;
}

static int set_pwm_duty_cycle(int duty_ns) {
    if (pwm_fd < 0) return -1;
    FILE *fp = fopen("/sys/class/pwm/pwmchip2/pwm0/duty_cycle", "w");
    if (!fp) { perror("Error opening duty_cycle"); return -1; }
    fprintf(fp, "%d", duty_ns);
    fclose(fp);
    return 0;
}

static int init_log(void) {
    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) { perror("Error opening log file"); return -1; }
    return 0;
}

static void log_data(float pitch, float roll, int solar_angle) {
    if (!log_fp) return;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_fp, "%d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f,%d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, pitch, roll, solar_angle);
    fflush(log_fp);
}

static void cleanup(void) {
    if (pwm_fd >= 0) { set_pwm_duty_cycle(0); close(pwm_fd); pwm_fd = -1; }
    if (log_fp) { fclose(log_fp); log_fp = NULL; }
    if (i2c_fd >= 0) { close(i2c_fd); i2c_fd = -1; }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) { perror("Error opening I2C bus"); return 1; }
    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Error setting I2C slave address");
        cleanup();
        return 1;
    }
    if (init_mpu6050(i2c_fd) < 0) { cleanup(); return 1; }

    if (init_pwm() < 0) { cleanup(); return 1; }

    if (init_log() < 0) { cleanup(); return 1; }

    int16_t x, y, z;
    float pitch, roll;
    int solar_angle = 0;

    while (running) {
        if (read_accel(i2c_fd, &x, &y, &z) == 0) {
            pitch = calculate_pitch(x, y, z);
            roll = atan2f((float)(x - z), (float)(y - z)) * 180.0f / M_PI;
            solar_angle = 90 - (int)(roll / 5.0f);
            if (set_pwm_duty_cycle(PWM_PERIOD_NS - (solar_angle * 1000000)) < 0) {
                fprintf(stderr, "Error setting PWM duty cycle\n");
            }
            log_data(pitch, roll, solar_angle);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }
        usleep(100000);
    }

    cleanup();
    return 0;
}

