#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define NUM_RELAYS 4
#define FADE_DURATION 1800
#define FADE_STEP_US 10000
#define SCHEDULE_FILE "lighting_schedule.txt"

static const int relay_pins[NUM_RELAYS] = {4, 17, 27, 22};
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_schedule(const char *filename, int *schedule) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Error opening schedule file '%s': %s\n", filename, strerror(errno));
        return -1;
    }

    char line[256];
    int i = 0;
    while (fgets(line, sizeof(line), fp)) {
        if (i >= NUM_RELAYS) break;
        if (sscanf(line, "%d:%d:%d,%d,%d",
                   &schedule[i].hour, &schedule[i].minute, &schedule[i].second,
                   &schedule[i].relay_num, &schedule[i].state) != 5) {
            fprintf(stderr, "Invalid schedule entry: %s", line);
            fclose(fp);
            return -1;
        }
        i++;
    }
    fclose(fp);
    return 0;
}

static int get_current_time(int *hour, int *minute, int *second) {
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (!timeinfo) return -1;
    *hour = timeinfo->tm_hour;
    *minute = timeinfo->tm_min;
    *second = timeinfo->tm_sec;
    return 0;
}

static int is_time_between(int hour, int minute, int second, int target_hour, int target_minute, int target_second) {
    if (hour < 0 || hour > 23 || minute < 0 || minute > 59 || second < 0 || second > 59) return 0;
    if (target_hour < 0 || target_hour > 23 || target_minute < 0 || target_minute > 59 || target_second < 0 || target_second > 59) return 0;
    if (hour == target_hour && minute == target_minute && second == target_second) return 1;
    if (hour < target_hour) return 1;
    if (hour > target_hour) return 0;
    if (minute < target_minute) return 1;
    if (minute > target_minute) return 0;
    return (second >= target_second);
}

static int set_relay(int pin, int state) {
    if (gpioWrite(pin, state) != 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", pin);
        return -1;
    }
    printf("Relay on GPIO %d set to %s\n", pin, state ? "ON" : "OFF");
    return 0;
}

static int fade_lamp(int pin, int target_brightness) {
    int current_brightness = gpioRead(pin);
    if (current_brightness < 0) {
        fprintf(stderr, "Error reading GPIO %d\n", pin);
        return -1;
    }
    if (current_brightness == target_brightness) return 0;

    int step = FADE_DURATION / FADE_STEP_US;
    int increment = (target_brightness - current_brightness) / step;
    if (increment > 0) {
        increment = 1;
    } else if (increment < 0) {
        increment = -1;
    }

    for (int i = 0; i < step && running; i++) {
        int brightness = current_brightness + increment;
        if (gpioPWM(pin, brightness) != 0) {
            fprintf(stderr, "Error setting PWM on GPIO %d\n", pin);
            return -1;
        }
        current_brightness = brightness;
        gpioDelay(FADE_STEP_US);
    }
    return set_relay(pin, (target_brightness > current_brightness) ? 1 : 0);
}

static int control_lamp(int pin, int target_hour, int target_minute, int target_second, int target_brightness) {
    int current_hour, current_minute, current_second;
    if (get_current_time(&current_hour, &current_minute, &current_second) != 0) {
        fprintf(stderr, "Error getting current time\n");
        return -1;
    }
    if (is_time_between(current_hour, current_minute, current_second, target_hour, target_minute, target_second)) {
        if (target_brightness > 100) target_brightness = 100;
        if (target_brightness < 0) target_brightness = 0;
        printf("Time is %d:%02d:%02d, target is %d:%02d:%02d, brightness %d\n",
               current_hour, current_minute, current_second, target_hour, target_minute, target_second, target_brightness);
        return fade_lamp(pin, target_brightness);
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpioSetMode(relay_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error setting GPIO %d as output\n", relay_pins[i]);
            gpioTerminate();
            return 1;
        }
        if (gpioWrite(relay_pins[i], 0) != 0) {
            fprintf(stderr, "Error initializing GPIO %d to LOW\n", relay_pins[i]);
            gpioTerminate();
            return 1;
        }
    }

    int schedule[NUM_RELAYS];
    if (read_schedule(SCHEDULE_FILE, schedule) != 0) {
        gpioTerminate();
        return 1;
    }

    printf("Smart Home Lighting System started. Press Ctrl+C to exit.\n");

    while (running) {
        int current_hour, current_minute, current_second;
        if (get_current_time(&current_hour, &current_minute, &current_second) != 0) {
            fprintf(stderr, "Error getting current time\n");
            break;
        }

        for (int i = 0; i < NUM_RELAYS; i++) {
            int target_hour = schedule[i].hour;
            int target_minute = schedule[i].minute;
            int target_second = schedule[i].second;
            int target_brightness = schedule[i].state ? 100 : 0;
            if (control_lamp(relay_pins[i], target_hour, target_minute, target_second, target_brightness) != 0) {
                fprintf(stderr, "Error controlling relay %d\n", i);
            }
        }
        gpioDelay(1000000);
    }

    printf("\nShutting down...\n");
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpioWrite(relay_pins[i], 0);
    }
    gpioTerminate();
    printf("Smart Home Lighting System stopped.\n");
    return 0;
}

