/*
 * Theremin-like application for Raspberry Pi Zero W
 * HC-SR04 ultrasonic distance sensor -> PWM buzzer frequency
 *
 * Wiring (BCM numbering):
 *   GPIO23 (physical 16) -> HC-SR04 TRIG
 *   GPIO24 (physical 18) -> HC-SR04 ECHO
 *   GPIO18 (physical 12) -> PWM buzzer
 *
 * Build: gcc -O2 -Wall -o theremin theremin.c -lpigpio -lrt
 * Run:   sudo ./theremin
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      23
#define ECHO_PIN         24
#define BUZZER_PIN       18

#define SPEED_OF_SOUND   34300.0          /* cm/s at ~20 C */
#define MIN_DISTANCE_CM  10.0             /* HC-SR04 minimum rated range */
#define MAX_DISTANCE_CM  400.0            /* HC-SR04 maximum rated range */
#define MIN_FREQUENCY    1000             /* Hz */
#define MAX_FREQUENCY    2000             /* Hz */
#define TRIGGER_PULSE_US 10               /* 10 us trigger pulse */
#define ECHO_TIMEOUT_US  30000             /* 30 ms timeout for echo */
#define LOOP_DELAY_US    20000             /* 20 ms loop delay (~50 Hz) */
#define MEASURE_GAP_US   60000             /* 60 ms gap between measurements */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Issue a 10 us trigger pulse on the TRIGGER_PIN.
 * Returns 0 on success, -1 on failure.
 */
static int trigger_sensor(void)
{
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN high\n");
        return -1;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN low\n");
        return -1;
    }
    return 0;
}

/*
 * Measure the echo pulse width in microseconds.
 * Returns the pulse width in microseconds, or -1 on timeout / error.
 */
static long measure_echo(void)
{
    uint32_t start_tick = 0, end_tick = 0;
    uint32_t deadline;

    /* Wait for echo to go high (start of pulse) */
    deadline = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - deadline) >= 0) {
            fprintf(stderr, "Error: echo start timeout (sensor absent or not responding)\n");
            return -1;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo to go low (end of pulse) */
    deadline = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - deadline) >= 0) {
            fprintf(stderr, "Error: echo end timeout (out of range)\n");
            return -1;
        }
    }
    end_tick = gpioTick();

    return (long)(end_tick - start_tick);
}

/*
 * Convert distance (cm) to frequency (Hz).
 * Returns the clamped frequency, or -1 on invalid distance.
 */
static int distance_to_frequency(double distance_cm)
{
    if (distance_cm < MIN_DISTANCE_CM || distance_cm > MAX_DISTANCE_CM) {
        fprintf(stderr, "Warning: distance %.2f cm out of range [%d, %d] cm\n",
                distance_cm, MIN_DISTANCE_CM, MAX_DISTANCE_CM);
        return -1;
    }
    double freq = (SPEED_OF_SOUND / 2.0) / distance_cm * 1000.0;
    if (freq < MIN_FREQUENCY) freq = MIN_FREQUENCY;
    if (freq > MAX_FREQUENCY) freq = MAX_FREQUENCY;
    return (int)freq;
}

/*
 * Set the buzzer frequency using pigpio hardware PWM.
 * Returns 0 on success, -1 on failure.
 */
static int set_buzzer_frequency(int frequency_hz)
{
    if (gpioSetPWMfrequency(BUZZER_PIN, frequency_hz) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed for pin %d\n", BUZZER_PIN);
        return -1;
    }
    if (gpioPWM(BUZZER_PIN, 128) < 0) {   /* 50% duty cycle */
        fprintf(stderr, "Error: gpioPWM failed for pin %d\n", BUZZER_PIN);
        return -1;
    }
    return 0;
}

int main(void)
{
    /* Install SIGINT handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for TRIGGER_PIN %d\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for ECHO_PIN %d\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for BUZZER_PIN %d\n", BUZZER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite failed for TRIGGER_PIN\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Allow sensor to settle */
    gpioDelay(500000);  /* 500 ms */

    printf("Theremin started. Press Ctrl+C to exit.\n");

    while (g_running) {
        if (trigger_sensor() != 0) {
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        long pulse_us = measure_echo();
        if (pulse_us < 0) {
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        double distance_cm = (double)pulse_us * SPEED_OF_SOUND / 2000000.0;
        int freq = distance_to_frequency(distance_cm);

        if (freq < 0) {
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        if (set_buzzer_frequency(freq) != 0) {
            gpioDelay(LOOP_DELAY_US);
            continue;
        }

        printf("Distance: %.2f cm  ->  Frequency: %d Hz\n", distance_cm, freq);

        /* Enforce minimum measurement gap */
        gpioDelay(MEASURE_GAP_US);
    }

    /* Graceful shutdown */
    gpioPWM(BUZZER_PIN, 0);
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    printf("\nTheremin stopped.\n");
    return EXIT_SUCCESS;
}

