/*
 * RGB LED proximity indicator for Raspberry Pi 3 Model B+
 * Uses pigpio hardware PWM on BCM pins 17 (red), 22 (green), 27 (blue)
 * at 1 kHz, driven common-anode (active-high).
 *
 * Build:  gcc -O2 -Wall -o rgb_proximity rgb_proximity.c -lpigpio -lrt
 * Run:    sudo ./rgb_proximity
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define RED_PIN    17
#define GREEN_PIN  22
#define BLUE_PIN   27

#define PWM_FREQ   1000          /* 1 kHz */
#define PWM_RANGE  255            /* 8-bit resolution */
#define PWM_DUTY   128            /* 50 % of range */

#define LOOP_DELAY_US 10000       /* 10 ms per frame */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", RED_PIN);
        return -1;
    }
    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", GREEN_PIN);
        return -1;
    }
    if (gpioSetMode(BLUE_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", BLUE_PIN);
        return -1;
    }

    if (gpioSetPWMfrequency(RED_PIN, PWM_FREQ) != 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO%d.\n", RED_PIN);
        return -1;
    }
    if (gpioSetPWMfrequency(GREEN_PIN, PWM_FREQ) != 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO%d.\n", GREEN_PIN);
        return -1;
    }
    if (gpioSetPWMfrequency(BLUE_PIN, PWM_FREQ) != 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO%d.\n", BLUE_PIN);
        return -1;
    }

    if (gpioSetPWMrange(RED_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO%d.\n", RED_PIN);
        return -1;
    }
    if (gpioSetPWMrange(GREEN_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO%d.\n", GREEN_PIN);
        return -1;
    }
    if (gpioSetPWMrange(BLUE_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO%d.\n", BLUE_PIN);
        return -1;
    }

    if (gpioPWM(RED_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize PWM duty on GPIO%d.\n", RED_PIN);
        return -1;
    }
    if (gpioPWM(GREEN_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize PWM duty on GPIO%d.\n", GREEN_PIN);
        return -1;
    }
    if (gpioPWM(BLUE_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize PWM duty on GPIO%d.\n", BLUE_PIN);
        return -1;
    }

    return 0;
}

static void set_led_color(int red, int green, int blue)
{
    if (gpioPWM(RED_PIN, red) != 0) {
        fprintf(stderr, "Warning: failed to set PWM duty on GPIO%d.\n", RED_PIN);
    }
    if (gpioPWM(GREEN_PIN, green) != 0) {
        fprintf(stderr, "Warning: failed to set PWM duty on GPIO%d.\n", GREEN_PIN);
    }
    if (gpioPWM(BLUE_PIN, blue) != 0) {
        fprintf(stderr, "Warning: failed to set PWM duty on GPIO%d.\n", BLUE_PIN);
    }
}

static void cleanup(void)
{
    /* Best-effort LED off and PWM disable */
    gpioPWM(RED_PIN, 0);
    gpioPWM(GREEN_PIN, 0);
    gpioPWM(BLUE_PIN, 0);
    gpioPWM(RED_PIN, 0);
    gpioPWM(GREEN_PIN, 0);
    gpioPWM(BLUE_PIN, 0);
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("RGB proximity indicator running. Press Ctrl+C to exit.\n");

    while (g_running) {
        double t = (double)time(NULL) / 60.0;   /* 60-second period */
        double phase = t * 2.0 * M_PI;          /* 0..2π */
        double r = 1.0 + sin(phase);             /* 0..2 */
        double g = 1.0 + sin(phase + 2.0 * M_PI / 3.0); /* 0..2 */
        double b = 1.0 + sin(phase + 4.0 * M_PI / 3.0); /* 0..2 */

        if (r > 2.0) r = 2.0;
        if (g > 2.0) g = 2.0;
        if (b > 2.0) b = 2.0;

        int red   = (int)(r   * PWM_DUTY / 2.0);
        int green = (int)(g   * PWM_DUTY / 2.0);
        int blue  = (int)(b   * PWM_DUTY / 2.0);

        set_led_color(red, green, blue);

        usleep(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

