#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>
#include <string.h>

#define BUTTON_PIN 17
#define BUZZER_PIN 18
#define DEBOUNCE_US 50000
#define PWM_DUTY 128
#define PWM_FREQ 44000

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t play_flag = 0;
static volatile sig_atomic_t melody_index = 0;

static const int melody[] = {
    262, 294, 330, 349, 392, 440, 494, 523, 587, 659, 698, 784, 880, 988, 1047, 1175, 1319, 1397, 1568, 1760, 1960, 2093, 2345, 2637, 2794, 3111, 3322, 3520, 3951, 4186, 4699, 5274, 5588, 6272, 6645, 8372, 12544
};

static volatile uint32_t last_press_tick = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void button_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)userdata;

    if (level != 0) return;

    uint32_t diff = tick - last_press_tick;
    if (diff < DEBOUNCE_US) return;
    last_press_tick = tick;

    play_flag = 1;
}

static int play_tone(int frequency) {
    if (frequency <= 0) return -1;
    if (gpioSetPWMfrequency(BUZZER_PIN, frequency) < 0) return -1;
    if (gpioPWM(BUZZER_PIN, PWM_DUTY) < 0) return -1;
    return 0;
}

static void play_melody(void) {
    while (play_flag && melody_index < (int)sizeof(melody) / sizeof(melody[0])) {
        if (play_tone(melody[melody_index]) < 0) {
            fprintf(stderr, "Error: Failed to play tone %d Hz\n", melody[melody_index]);
            return;
        }
        melody_index++;
        usleep(100000);
    }
    gpioPWM(BUZZER_PIN, 0);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: Failed to set button pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: Failed to set pull-up on button pin\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set buzzer pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(BUZZER_PIN, PWM_FREQ) < 0) {
        fprintf(stderr, "Error: Failed to set PWM frequency\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioPWM(BUZZER_PIN, 0) < 0) {
        fprintf(stderr, "Error: Failed to initialise PWM duty cycle\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFuncEx(BUTTON_PIN, FALLING_EDGE, 0, button_isr, NULL) < 0) {
        fprintf(stderr, "Error: Failed to set ISR function\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction SIGINT");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction SIGTERM");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Doorbell ready. Press the button (GPIO17) to play melody.\n");

    while (running) {
        if (play_flag) {
            play_melody();
            play_flag = 0;
        }
        usleep(10000);
    }

    gpioPWM(BUZZER_PIN, 0);
    gpioSetISRFuncEx(BUTTON_PIN, FALLING_EDGE, 0, NULL, NULL);
    gpioTerminate();
    printf("Doorbell stopped.\n");
    return EXIT_SUCCESS;
}

