/*
 * SW420 vibration sensor monitor for Raspberry Pi 3 Model B+
 * Sensor digital output -> GPIO17 (BCM, physical pin 11)
 * Library: pigpio (edge-triggered polling on both edges)
 *
 * Build:  gcc -O2 -Wall -Wextra -o sw420_monitor sw420_monitor.c -lpigpio -lrt
 * Run:    sudo ./sw420_monitor [poll_ms]
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define GPIO_PIN          17
#define LOG_FILE          "vibration_events.log"
#define WINDOW_SIZE       5
#define ALERT_THRESHOLD   3
#define DEFAULT_POLL_MS   1000

/* ------------------------------------------------------------------ */
/* Globals                                                            */
/* ------------------------------------------------------------------ */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                    */
/* ------------------------------------------------------------------ */

static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

static void get_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        snprintf(buf, len, "UNKNOWN");
        return;
    }
    struct tm tmv;
    if (localtime_r(&now, &tmv) == NULL) {
        snprintf(buf, len, "UNKNOWN");
        return;
    }
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tmv);
}

static void log_event(FILE *fp, int value)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));
    if (fprintf(fp, "%s, GPIO%d, %d\n", ts, GPIO_PIN, value) < 0) {
        fprintf(stderr, "Warning: fprintf to log failed: %s\n", strerror(errno));
    } else {
        if (fflush(fp) != 0) {
            fprintf(stderr, "Warning: fflush failed: %s\n", strerror(errno));
        }
    }
}

static void check_alert(FILE *fp, int values[], int n)
{
    int high_count = 0;
    for (int i = 0; i < n; i++) {
        if (values[i] == 1) high_count++;
    }
    if (high_count >= ALERT_THRESHOLD) {
        char ts[32];
        get_timestamp(ts, sizeof(ts));
        printf("EARTHQUAKE ALERT: %s\n", ts);
        if (fprintf(fp, "%s, ALERT: GPIO%d, HIGH count=%d\n", ts, GPIO_PIN, high_count) < 0) {
            fprintf(stderr, "Warning: fprintf to log failed: %s\n", strerror(errno));
        } else {
            if (fflush(fp) != 0) {
                fprintf(stderr, "Warning: fflush failed: %s\n", strerror(errno));
            }
        }
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(int argc, char *argv[])
{
    int poll_ms = DEFAULT_POLL_MS;
    if (argc > 1) {
        poll_ms = atoi(argv[1]);
        if (poll_ms <= 0) {
            fprintf(stderr, "Error: poll_ms must be positive (got %d)\n", poll_ms);
            return EXIT_FAILURE;
        }
    }

    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- GPIO setup ---- */
    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO%d\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Enable internal pull-down so the line is defined when the sensor
     * is disconnected (SW420 module output is open-collector). */
    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Warning: gpioSetPullUpDown failed for GPIO%d\n", GPIO_PIN);
    }

    /* ---- Open log file ---- */
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: cannot open %s: %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGTERM) failed: %s\n", strerror(errno));
    }

    /* ---- Event buffer ---- */
    int values[WINDOW_SIZE];
    for (int i = 0; i < WINDOW_SIZE; i++) values[i] = 0;

    printf("Monitoring SW420 on GPIO%d (poll %d ms). Press Ctrl+C to exit.\n",
           GPIO_PIN, poll_ms);

    /* ---- Main loop ---- */
    while (g_running) {
        int v = gpioRead(GPIO_PIN);
        if (v < 0) {
            fprintf(stderr, "Error: gpioRead failed on GPIO%d\n", GPIO_PIN);
            break;
        }

        log_event(fp, v);
        check_alert(fp, values, WINDOW_SIZE);

        /* Slide the window: oldest value is overwritten by the new one. */
        for (int i = 0; i < WINDOW_SIZE - 1; i++) {
            values[i] = values[i + 1];
        }
        values[WINDOW_SIZE - 1] = v;

        gpioDelay(poll_ms * 1000); /* pigpio microseconds */
    }

    /* ---- Cleanup ---- */
    printf("\nShutting down...\n");
    if (fclose(fp) != 0) {
        fprintf(stderr, "Warning: fclose failed: %s\n", strerror(errno));
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

