/*
 * LSM303DLHC magnetometer compass reader for Raspberry Pi Zero W.
 *
 * Wiring:
 *   LSM303DLHC SDA  -> Pi GPIO2  (physical pin 3)
 *   LSM303DLHC SCL  -> Pi GPIO3  (physical pin 5)
 *   LSM303DLHC VDD  -> 3.3 V
 *   LSM303DLHC GND  -> GND
 *   LSM303DLHC SDO  -> GND  (I2C address 0x0C, 7-bit)
 *
 * Build:  gcc -O2 -Wall -Wextra -o mag_comp mag_comp.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- LSM303DLHC magnetometer constants ---- */
#define LSM303_I2C_ADDR  0x0C          /* 7-bit address, SDO tied to GND */
#define I2C_BUS          "/dev/i2c-1"
#define CSV_FILENAME     "mag_log.csv"

#define REG_M_HXL        0x02          /* X-axis high byte  */
#define REG_M_HXL_LSB    0x03          /* X-axis low byte  */
#define REG_M_ZXL        0x04          /* Z-axis high byte  */
#define REG_M_ZXL_LSB    0x05          /* Z-axis low byte  */
#define REG_M_YXL        0x06          /* Y-axis high byte  */
#define REG_M_YXL_LSB    0x07          /* Y-axis low byte  */

#define X_OFFSET  10
#define Y_OFFSET  -5
#define Z_OFFSET  20

/* ---- Compass directions ---- */
typedef enum { DIR_N, DIR_NE, DIR_E, DIR_SE, DIR_S, DIR_SW, DIR_W, DIR_NW }
    compass_dir_t;

static const char *dir_name(compass_dir_t d)
{
    switch (d) {
        case DIR_N:  return "N";
        case DIR_NE: return "NE";
        case DIR_E:  return "E";
        case DIR_SE: return "SE";
        case DIR_S:  return "S";
        case DIR_SW: return "SW";
        case DIR_W:  return "W";
        case DIR_NW: return "NW";
        default:     return "UNKNOWN";
    }
}

/* ---- Globals for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_csv  = NULL;

/* ------------------------------------------------------------------ */
static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    ssize_t n = write(fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write_reg8(0x%02X, 0x%02X) failed: %s\n",
                reg, val, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    ssize_t n = write(fd, &reg, 1);
    if (n != 1) {
        fprintf(stderr, "i2c_read_reg8: write(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    n = read(fd, out, 1);
    if (n != 1) {
        fprintf(stderr, "i2c_read_reg8: read(0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int read_magnetometer(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t xl, xl_l, zl, zl_l, yl, yl_l;

    if (i2c_read_reg8(fd, REG_M_HXL, &xl)  != 0) return -1;
    if (i2c_read_reg8(fd, REG_M_HXL_LSB, &xl_l) != 0) return -1;
    if (i2c_read_reg8(fd, REG_M_ZXL, &zl)  != 0) return -1;
    if (i2c_read_reg8(fd, REG_M_ZXL_LSB, &zl_l) != 0) return -1;
    if (i2c_read_reg8(fd, REG_M_YXL, &yl)  != 0) return -1;
    if (i2c_read_reg8(fd, REG_M_YXL_LSB, &yl_l) != 0) return -1;

    *x = (int16_t)(((uint16_t)xl << 8) | (uint16_t)xl_l);
    *y = (int16_t)(((uint16_t)yl << 8) | (uint16_t)yl_l);
    *z = (int16_t)(((uint16_t)zl << 8) | (uint16_t)zl_l);
    return 0;
}

/* ------------------------------------------------------------------ */
static compass_dir_t calc_heading(int16_t x, int16_t y)
{
    double h = atan2((double)y, (double)x) * 180.0 / M_PI;
    if (h < 0.0)   h += 360.0;
    if (h < 45.0)  return DIR_N;
    if (h < 135.0) return DIR_NE;
    if (h < 225.0) return DIR_E;
    if (h < 315.0) return DIR_SE;
    return DIR_S;
}

/* ------------------------------------------------------------------ */
static compass_dir_t calc_heading_z(int16_t x, int16_t y, int16_t z)
{
    double h = atan2((double)z, sqrt((double)x * x + (double)y * y)) * 180.0 / M_PI;
    if (h < 0.0)   h += 360.0;
    if (h < 45.0)  return DIR_N;
    if (h < 135.0) return DIR_NE;
    if (h < 225.0) return DIR_E;
    if (h < 315.0) return DIR_SE;
    return DIR_S;
}

/* ------------------------------------------------------------------ */
static void log_sample(FILE *fp, int16_t x, int16_t y, int16_t z)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s, %d, %d, %d, %d\n", ts, x, y, z, 0);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
static compass_dir_t calc_dir(int16_t x, int16_t y)
{
    compass_dir_t d = calc_heading(x, y);
    if (d == DIR_N)   return DIR_N;
    if (d == DIR_NE)  return DIR_NE;
    if (d == DIR_E)   return DIR_E;
    if (d == DIR_SE)  return DIR_SE;
    if (d == DIR_S)   return DIR_S;
    if (d == DIR_SW)  return DIR_SW;
    if (d == DIR_W)   return DIR_W;
    return DIR_N;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_csv) {
        fclose(g_csv);
        g_csv = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, LSM303_I2C_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                LSM303_I2C_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open CSV (append; write header if file does not exist) ---- */
    int file_exists = (access(CSV_FILENAME, F_OK) == 0);
    g_csv = fopen(CSV_FILENAME, "a");
    if (!g_csv) {
        fprintf(stderr, "fopen(%s) failed: %s\n", CSV_FILENAME, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (!file_exists) {
        fprintf(g_csv, "Timestamp, Calibrated X, Calibrated Y, Calibrated Z, Heading\n");
        fflush(g_csv);
    }

    printf("LSM303DLHC compass running.  Press Ctrl-C to stop.\n");

    /* ---- Main sampling loop ---- */
    while (g_running) {
        int16_t x, y, z;

        if (read_magnetometer(g_i2c_fd, &x, &y, &z) != 0) {
            fprintf(stderr, "I2C read error; skipping sample.\n");
        } else {
            int16_t cx = x - X_OFFSET;
            int16_t cy = y - Y_OFFSET;
            int16_t cz = z - Z_OFFSET;

            compass_dir_t dir = calc_heading(x, y);
            int heading = (int)(atan2((double)cy, (double)cx) * 180.0 / M_PI + 360.0) % 360;

            log_sample(g_csv, cx, cy, cz);
            printf("X=%d Y=%d Z=%d  |  %s  (heading %d deg)\n",
                   x, y, z, dir_name(dir), heading);
        }

        sleep(1);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

