/*
 * TTP223 capacitive touch sensor → relay toggle (pigpio)
 * Board : Raspberry Pi 4 Model B
 * Sensor: TTP223 on GPIO4  (BCM), pull-down enabled
 * Relay  : 5 V on GPIO17 (BCM), active-high
 *
 * Build: gcc -O2 -Wall -Wextra -o relay_touch relay_touch.c -lpigpio -lrt
 * Run  : sudo ./relay_touch
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_PIN      4
#define RELAY_PIN      17
#define DEBOUNCE_US    200000          /* 200 ms */
#define POLL_US        10000           /* 10 ms  */
#define LOG_FILE       "relay_log.json"

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_relay_state(int state)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(log)");
        return;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("time");
        fclose(fp);
        return;
    }

    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S%z", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return;
    }

    fprintf(fp,
            "{\"timestamp\":\"%s\",\"relay_state\":\"%s\"}\n",
            ts, state ? "ON" : "OFF");

    if (fclose(fp) != 0)
        perror("fclose(log)");
}

/* ------------------------------------------------------------------ */
/* pigpio ISR — runs in a pigpio thread                              */
/* ------------------------------------------------------------------ */
static void touch_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)level;
    (void)tick;
    (void)userdata;

    static uint32_t last_tick = 0;
    uint32_t now = tick;

    /* pigpio tick wraps every ~72 min; handle the wrap */
    if (now < last_tick)
        last_tick = now + (DEBOUNCE_US - (last_tick - now));
    else
        last_tick = now;

    if (last_tick - now < DEBOUNCE_US)
        return;                 /* within debounce window — ignore */

