/*
 * TTP223 capacitive touch sensor → relay toggle (pigpio)
 * Board : Raspberry Pi 4 Model B
 * Sensor: TTP223 on GPIO4  (BCM), pull-down enabled
 * Relay  : 5 V on GPIO17 (BCM), active-high
 *
 * Build: gcc -O2 -Wall -Wextra -o relay_touch relay_touch.c -lpigpio -lrt
 * Run  : sudo ./relay_touch
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_PIN      4
#define RELAY_PIN      17
#define DEBOUNCE_US    200000          /* 200 ms */
#define POLL_US        10000           /* 10 ms  */
#define LOG_FILE       "relay_log.json"

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_relay_state(int state)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(log)");
        return;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("time");
        fclose(fp);
        return;
    }

    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S%z", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return;
    }

    fprintf(fp,
            "{\"timestamp\":\"%s\",\"relay_state\":\"%s\"}\n",
            ts, state ? "ON" : "OFF");

    if (fclose(fp) != 0)
        perror("fclose(log)");
}

/* ------------------------------------------------------------------ */
/* pigpio ISR — runs in a pigpio thread                              */
/* ------------------------------------------------------------------ */
static void touch_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)level;
    (void)tick;
    (void)userdata;

    static uint32_t last_tick = 0;
    uint32_t now = tick;

    /* pigpio tick wraps every ~72 min; handle the wrap */
    if (now < last_tick)
        last_tick = now + (DEBOUNCE_US - (last_tick - now));
    else
        last_tick = now;

    if (last_tick - now < DEBOUNCE_US)
        return;                 /* within debounce window — ignore */

    int prev_state = gpioRead(RELAY_PIN);
    if (prev_state < 0) {
        fprintf(stderr, "gpioRead(RELAY_PIN) failed\n");
        return;
    }

    int new_state = !prev_state;
    if (gpioWrite(RELAY_PIN, new_state) < 0) {
        fprintf(stderr, "gpioWrite(RELAY_PIN, %d) failed\n", new_state);
        return;
    }

    log_relay_state(new_state);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise() failed\n");
        return EXIT_FAILURE;
    }

    /* ---- configure pins ---- */
    if (gpioSetMode(TOUCH_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode(TOUCH_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(TOUCH_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "gpioSetPullUpDown(TOUCH_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(RELAY_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- ensure relay starts OFF ---- */
    if (gpioWrite(RELAY_PIN, 0) < 0) {
        fprintf(stderr, "gpioWrite(RELAY_PIN, 0) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- register ISR ---- */
    if (gpioSetISRFuncEx(TOUCH_PIN, EITHER_EDGE, 0, touch_isr, NULL) < 0) {
        fprintf(stderr, "gpioSetISRFuncEx(TOUCH_PIN) failed\n");
        gpioWrite(RELAY_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Touch sensor monitoring started.\n");
    printf("  Touch pin : GPIO%d (BCM)\n", TOUCH_PIN);
    printf("  Relay pin : GPIO%d (BCM)\n", RELAY_PIN);
    printf("  Log file  : %s\n", LOG_FILE);
    printf("Press Ctrl+C to exit.\n");

    /* ---- main loop ---- */
    while (g_running)
        gpioDelay(POLL_US);

    /* ---- graceful shutdown ---- */
    printf("\nShutting down...\n");

    /* Force relay OFF */
    if (gpioWrite(RELAY_PIN, 0) < 0)
        perror("gpioWrite(RELAY_PIN, 0) during shutdown");

    /* Append final OFF entry to log */
    log_relay_state(0);

    /* Release ISR */
    gpioSetISRFuncEx(TOUCH_PIN, EITHER_EDGE, 0, NULL, NULL);

    /* Release pigpio */
    gpioTerminate();

