#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <pigpio.h>

#define NUM_RELAYS 4
#define MOISTURE_THRESHOLD 30
#define RELAY_DURATION 5
#define GAP_DURATION 1
#define LOG_FILE "irrigation_log.txt"
#define TIMESTAMP_LEN 32

static const int relay_pins[NUM_RELAYS] = {17, 23, 24, 25};
static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpioSetMode(relay_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO%d as output\n", relay_pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioWrite(relay_pins[i], 1) != 0) {
            fprintf(stderr, "Error: failed to set GPIO%d high\n", relay_pins[i]);
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

static void deactivate_all_relays(void) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpioWrite(relay_pins[i], 1);
    }
}

static void log_irrigation(int relay_number, int moisture_level) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[TIMESTAMP_LEN];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return;
    }

    if (log_file != NULL) {
        if (fprintf(log_file, "%s, Relay %d, Moisture: %d\n", timestamp, relay_number, moisture_level) < 0) {
            fprintf(stderr, "Error: failed to write to log file\n");
        } else {
            if (fflush(log_file) != 0) {
                fprintf(stderr, "Error: failed to flush log file\n");
            }
        }
    } else {
        fprintf(stderr, "Error: log file is not open\n");
    }
}

static void activate_relay(int relay_number, int duration_seconds) {
    if (gpioWrite(relay_pins[relay_number], 0) != 0) {
        fprintf(stderr, "Error: failed to activate relay %d\n", relay_number);
        return;
    }
    gpioDelay(duration_seconds * 1000000);
    if (gpioWrite(relay_pins[relay_number], 1) != 0) {
        fprintf(stderr, "Error: failed to deactivate relay %d\n", relay_number);
    }
}

static int simulate_moisture_level(void) {
    static int seed = 0;
    static int last_seed = 0;
    if (seed == last_seed) {
        srand((unsigned int)time(NULL));
    }
    last_seed = seed;
    seed = seed * 17 + 23;
    return rand() % 101;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to install SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to install SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (initialize_gpio() != 0) {
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        deactivate_all_relays();
        gpioTerminate();
        return 1;
    }

    printf("Smart Irrigation System started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int moisture_level = simulate_moisture_level();

        if (moisture_level < MOISTURE_THRESHOLD) {
            for (int i = 0; i < NUM_RELAYS; i++) {
                if (!program_running) break;
                activate_relay(i, RELAY_DURATION);
                if (i < NUM_RELAYS - 1) {
                    gpioDelay(GAP_DURATION * 1000000);
                }
                log_irrigation(i + 1, moisture_level);
            }
        }

        gpioDelay(10 * 1000000);
    }

    printf("\nShutting down...\n");
    deactivate_all_relays();
    gpioTerminate();
    if (log_file != NULL) {
        if (fclose(log_file) != 0) {
            fprintf(stderr, "Error: failed to close log file: %s\n", strerror(errno));
        }
    }
    printf("Smart Irrigation System stopped.\n");
    return 0;
}

