/*
 * Automated Plant Watering System for Raspberry Pi Zero W
 * Uses the libthe library (libthe.so) to control SG90 servos.
 *
 * Wiring:
 *   - Valve servo (GPIO17, physical pin 11, BCM)
 *   - Nozzle servo (GPIO18, physical pin 12, BCM)
 *
 * Compile: gcc -Wall -Wextra -O2 -o watering watering.c -lthe -lrt
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>
#include <errno.h>

#include <the.h>

#define VALVE_GPIO 17
#define NOZZLE_GPIO 18

#define MOISTURE_THRESHOLD 50
#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500

#define SERVO_OPEN_VALVE 1500
#define SERVO_NOZZLE_STEP 500
#define SERVO_CLOSE_VALVE 500

#define NOZZLE_POSITIONS 5
#define NOZZLE_POSITIONS_PULSE_WIDTHS {500, 1000, 1500, 2000, 2500}
#define NOZZLE_POSITIONS_DELAY 2

#define SPRAY_DURATION 5
#define CYCLE_DELAY 5

#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int set_servo_pulse_width(int gpio, int pulse_width) {
    if (pulse_width < SERVO_MIN_PULSE_WIDTH || pulse_width > SERVO_MAX_PULSE_WIDTH) {
        fprintf(stderr, "Error: Invalid pulse width %d for GPIO %d\n", pulse_width, gpio);
        return -1;
    }

    int rc = the_servo_pulse_width(gpio, pulse_width);
    if (rc != 0) {
        fprintf(stderr, "Error: Failed to set pulse width for GPIO %d (rc=%d)\n", gpio, rc);
        return -1;
    }
    return 0;
}

static int open_valve(void) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (set_servo_pulse_width(VALVE_GPIO, SERVO_OPEN_VALVE) == 0) {
            return 0;
        }
        fprintf(stderr, "Warning: Failed to open valve (attempt %d/%d)\n", attempt + 1, MAX_RETRIES);
        usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

static int close_valve(void) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (set_servo_pulse_width(VALVE_GPIO, SERVO_CLOSE_VALVE) == 0) {
            return 0;
        }
        fprintf(stderr, "Warning: Failed to close valve (attempt %d/%d)\n", attempt + 1, MAX_RETRIES);
        usleep(RETRY_DELAY_MS * 1000);
    }
    return -1;
}

static int sweep_nozzle(int gpio, int *pulse_widths, int num_positions, int delay_ms) {
    for (int i = 0; i < num_positions; i++) {
        if (!g_running) {
            return -1;
        }
        if (set_servo_pulse_width(gpio, pulse_widths[i]) != 0) {
            fprintf(stderr, "Error: Failed to set nozzle position %d\n", i);
            return -1;
        }
        usleep(delay_ms * 1000);
    }
    return 0;
}

static void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "[%s] ERROR: %s (errno=%d: %s)\n", timestamp, message, errno, strerror(errno));
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Failed to register SIGINT handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to register SIGTERM handler");
        return EXIT_FAILURE;
    }

    if (the_servo_init() != 0) {
        fprintf(stderr, "Error: Failed to initialize the servo library\n");
        return EXIT_FAILURE;
    }

    int moisture_sequence[] = {20, 40, 60, 80, 100};
    int sequence_length = sizeof(moisture_sequence) / sizeof(moisture_sequence[0]);

    printf("Starting automated watering system...\n");

    while (g_running) {
        for (int i = 0; i < sequence_length; i++) {
            int moisture = moisture_sequence[i];

            if (moisture < MOISTURE_THRESHOLD) {
                printf("Moisture level: %d (below threshold %d). Activating watering cycle.\n", moisture, MOISTURE_THRESHOLD);

                if (open_valve() != 0) {
                    fprintf(stderr, "Error: Failed to open valve. Aborting watering cycle.\n");
                    break;
                }

                for (int j = 0; j < NOZZLE_POSITIONS; j++) {
                    if (!g_running) {
                        break;
                    }
                    if (sweep_nozzle(NOZZLE_GPIO, NOZZLE_POSITIONS_PULSE_WIDTHS, NOZZLE_POSITIONS_DELAY, NOZZLE_POSITIONS_DELAY) != 0) {
                        fprintf(stderr, "Error: Failed to sweep nozzle. Aborting watering cycle.\n");
                        break;
                    }
                    if (set_servo_pulse_width(NOZZLE_GPIO, SERVO_CLOSE_VALVE) != 0) {
                        fprintf(stderr, "Error: Failed to close nozzle. Aborting watering cycle.\n");
                        break;
                    }
                    usleep(SPRAY_DURATION * 1000);
                }

                if (close_valve() != 0) {
                    fprintf(stderr, "Error: Failed to close valve. Aborting watering cycle.\n");
                    break;
                }

                printf("Watering cycle complete.\n");
                usleep(CYCLE_DELAY * 1000);
            } else {
                printf("Moisture level: %d (above threshold %d). No watering needed.\n", moisture, MOISTURE_THRESHOLD);
                usleep(CYCLE_DELAY * 1000);
            }
        }
    }

    printf("Shutting down watering system...\n");
    the_servo_stop(0);
    the_servo_cleanup();
    printf("Watering system stopped.\n");

    return EXIT_SUCCESS;
}

