/*
 * MPU-6050 Gyroscope Logger for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   MPU-6050 VCC  -> 3.3V (Pin 1)
 *   MPU-6050 GND  -> GND  (Pin 9)
 *   MPU-6050 SCL  -> GPIO3 / SCL (Pin 5)
 *   MPU-6050 SDA  -> GPIO2 / SDA (Pin 3)
 *   MPU-6050 AD0  -> GND  (I2C address 0x68)
 *
 * Build: gcc -O2 -Wall -o gyro_log gyro_log.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MPU6050_ADDR   0x68

#define REG_SMPLRT_DIV  0x19
#define REG_CONFIG      0x1A
#define REG_GYRO_XOUT_H 0x43
#define REG_PWR_MGMT_1  0x6B

#define SAMPLE_RATE_HZ  10
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int i2c_write_reg(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read block from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int mpu6050_init(int fd)
{
    if (i2c_write_reg(fd, REG_PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Failed to wake MPU-6050 (PWR_MGMT_1).\n");
        return -1;
    }
    usleep(100000);

    if (i2c_write_reg(fd, REG_SMPLRT_DIV, 0x07) < 0) {
        fprintf(stderr, "Failed to set sample rate divider.\n");
        return -1;
    }

    if (i2c_write_reg(fd, REG_CONFIG, 0x01) < 0) {
        fprintf(stderr, "Failed to set config register.\n");
        return -1;
    }

    return 0;
}

static int read_gyro_data(int fd, int16_t *gx, int16_t *gy, int16_t *gz)
{
    uint8_t buf[6];
    if (i2c_read_block(fd, REG_GYRO_XOUT_H, buf, 6) < 0) {
        return -1;
    }

    *gx = (int16_t)((buf[0] << 8) | buf[1]);
    *gy = (int16_t)((buf[2] << 8) | buf[3]);
    *gz = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

static void log_data(FILE *fp, int16_t gx, int16_t gy, int16_t gz)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
        perror("clock_gettime");
        return;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(fp, "%s.%03ld,%d,%d,%d\n", timestamp, ts.tv_nsec / 1000000, gx, gy, gz);
    fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                MPU6050_ADDR, strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    if (mpu6050_init(fd) < 0) {
        fprintf(stderr, "MPU-6050 initialization failed.\n");
        close(fd);
        return EXIT_FAILURE;
    }

    FILE *fp = fopen("gyro_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open gyro_log.txt: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("MPU-6050 logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        int16_t gx, gy, gz;
        if (read_gyro_data(fd, &gx, &gy, &gz) < 0) {
            fprintf(stderr, "Error reading gyroscope data. Continuing...\n");
        } else {
            log_data(fp, gx, gy, gz);
        }
        usleep(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly...\n");
    fclose(fp);
    close(fd);
    return EXIT_SUCCESS;
}

