    if (gpioSetMode(MOTOR_IN1, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_IN2, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_IN3, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_IN4, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set motor pin modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure button pins as inputs with pull-ups */
    if (gpioSetMode(LOCK_BUTTON, PI_INPUT) < 0 ||
        gpioSetMode(UNLOCK_BUTTON, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set button pin modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set button pull-ups\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register SIGINT handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        motor_stop_coils();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Door lock control ready. Press Ctrl-C to exit.\n");
    fflush(stdout);

    lock_state_t lock_state = UNLOCKED;

    while (g_running) {
        int lock_pressed = debounce_button(LOCK_BUTTON);
        int unlock_pressed = debounce_button(UNLOCK_BUTTON);

        if (lock_pressed == 1 && lock_state == UNLOCKED) {
            if (motor_lock() < 0) {
                fprintf(stderr, "Error during lock operation\n");
            }
            lock_state = LOCKED;
        } else if (unlock_pressed == 1 && lock_state == LOCKED) {
            if (motor_unlock() < 0) {
                fprintf(stderr, "Error during unlock operation\n");
            }
            lock_state = UNLOCKED;
        }

        gpioDelay(10000); /* 10 ms poll interval */
    }

    /* Graceful shutdown */
    motor_stop_coils();
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
