/*
 * HC-SR04 ultrasonic distance logger for Raspberry Pi 4 Model B (64-bit).
 *
 * Wiring (BCM numbering):
 *   GPIO17 (output)  -> HC-SR04 TRIG
 *   GPIO18 (input)   -> HC-SR04 ECHO  (level-shifter recommended between
 *                        HC-SR04 and Pi to reduce 5 V to 3.3 V)
 *
 * Build:  gcc -O2 -Wall -Wextra -o hcsr04_log hcsr04_log.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>

#define TRIGGER_PIN      17
#define ECHO_PIN         18
#define LOG_FILE         "distance_log.txt"
#define SAMPLE_PERIOD_S  1
#define MEASURE_PERIOD_S 0.1
#define ECHO_TIMEOUT_US  50000   /* 50 ms */
#define TRIGGER_PULSE_US 10      /* 10 us */
#define LOOP_DELAY_S     0.1     /* 100 ms between measurements */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static void sleep_us(unsigned int us)
{
    struct timespec ts = {
        .tv_sec  = us / 1000000U,
        .tv_nsec = (long)(us % 1000000U) * 1000L
    };
    nanosleep(&ts, NULL);
}

static void sleep_ms(unsigned int ms)
{
    struct timespec ts = {
        .tv_sec  = ms / 1000U,
        .tv_nsec = (long)(ms % 1000U) * 1000000L
    };
    nanosleep(&ts, NULL);
}

/*
 * Measure distance in centimetres.
 * Returns -1 on timeout or I/O error.
 */
static int measure_distance(int fd)
{
    /* Ensure trigger starts low */
    if (ioctl(fd, GPIO_TRIGGER, TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set TRIGGER low: %s\n", strerror(errno));
        return -1;
    }
    sleep_us(5);

    /* 10 us trigger pulse */
    if (ioctl(fd, GPIO_TRIGGER, TRIGGER_PIN, TRIGGER_PULSE_US) < 0) {
        fprintf(stderr, "Error: failed to send trigger pulse: %s\n", strerror(errno));
        return -1;
    }

    /* Wait for echo rising edge (timeout) */
    unsigned int waited = 0;
    while (1) {
        int v = ioctl(fd, GPIO_READ, ECHO_PIN);
        if (v < 0) {
            fprintf(stderr, "Error: failed to read ECHO: %s\n", strerror(errno));
            return -1;
        }
        if (v == 1) {
            break;
        }
        if (waited >= ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: echo rising-edge timeout\n");
            return -1;
        }
        sleep_us(1);
        waited += 1000;
    }

    /* Wait for echo falling edge (timeout) */
    waited = 0;
    while (1) {
        int v = ioctl(fd, GPIO_READ, ECHO_PIN);
        if (v < 0) {
            fprintf(stderr, "Error: failed to read ECHO: %s\n", strerror(errno));
            return -1;
        }
        if (v == 0) {
            break;
        }
        if (waited >= ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: echo falling-edge timeout\n");
            return -1;
        }
        sleep_us(1);
        waited += 1000;
    }

    /* Distance = (pulse width * speed of sound) / 2 */
    unsigned int pulse_us = waited;
    int distance_cm = (int)((pulse_us / 1000000.0) * 34300.0 / 2.0);
    return distance_cm;
}

static void log_distance(FILE *fp, int distance)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(fp, "%s,%d\n", ts, distance);
    fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction(SIGTERM): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open log file once and keep it open for the lifetime of the program */
    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        fprintf(stderr, "Error: cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open GPIO chip 0 (gpiochip0 on Pi 4) */
    int chip_fd = open("/dev/gpiochip0", O_RDWR);
    if (chip_fd < 0) {
        fprintf(stderr, "Error: cannot open /dev/gpiochip0: %s\n", strerror(errno));
        fclose(g_log);
        return EXIT_FAILURE;
    }

    /* Request trigger line as output, initial value low */
    if (ioctl(chip_fd, GPIO_REQUEST, TRIGGER_PIN, GPIOD_LINE_REQUEST_DIRECTION_OUTPUT) < 0) {
        fprintf(stderr, "Error: request TRIGGER_PIN failed: %s\n", strerror(errno));
        close(chip_fd);
        fclose(g_log);
        return EXIT_FAILURE;
    }
    if (ioctl(chip_fd, GPIO_SET_VALUE, TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: set TRIGGER_PIN low failed: %s\n", strerror(errno));
        close(chip_fd);
        fclose(g_log);
        return EXIT_FAILURE;
    }

    /* Request echo line as input */
    if (ioctl(chip_fd, GPIO_REQUEST, ECHO_PIN, GPIOD_LINE_REQUEST_DIRECTION_INPUT) < 0) {
        fprintf(stderr, "Error: request ECHO_PIN failed: %s\n", strerror(errno));
        close(chip_fd);
        fclose(g_log);
        return EXIT_FAILURE;
    }

    printf("HC-SR04 logger started. Logging to %s every %d s. Press Ctrl+C to stop.\n",
           LOG_FILE, SAMPLE_PERIOD_S);

    while (g_running) {
        int distance = measure_distance(chip_fd);
        log_distance(g_log, distance);
        sleep_ms(LOOP_DELAY_S);
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    if (ioctl(chip_fd, GPIO_SET_VALUE, TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Warning: failed to reset TRIGGER_PIN: %s\n", strerror(errno));
    }
    close(chip_fd);
    if (g_log) {
        fclose(g_log);
        g_log = NULL;
    }
    printf("Done.\n");
    return EXIT_SUCCESS;
}

