/*
 * VL53L1X Time-of-Flight Distance Sensor with Relay Control
 * Board:  Raspberry Pi 4 Model B
 * Bus:    I2C bus 1 (GPIO2 = SDA, GPIO3 = SCL)
 * Sensor: VL53L1X at default address 0x29
 * Relay:  GPIO18 (BCM)
 *
 * Build:  gcc -O2 -Wall -o vl53l1x_relay vl53l1x_relay.c -lpigpio -lrt
 * Run:    sudo ./vl53l1x_relay
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

/* ---- Configuration ---- */
#define I2C_BUS        "/dev/i2c-1"
#define VL53L1X_ADDR   0x29
#define RELAY_PIN      18
#define DIST_THRESHOLD 50          /* cm */
#define POLL_DELAY_US  100000      /* 100 ms */

/* ---- VL53L1X register addresses ---- */
#define VL53L1X_REG_SOFT_RESET              0x0000
#define VL53L1X_REG_SYSTEM_MODE_START       0x0001
#define VL53L1X_REG_RESULT_RANGE_STATUS     0x0089
#define VL53L1X_REG_RESULT_DISTANCE         0x0096
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR  0x0086

/* ---- Globals for cleanup ---- */
static int      g_i2c_fd = -1;
static bool     g_running = true;

/* ---- Signal handler ---- */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = false;
}

/* ---- I2C helpers ---- */
static int i2c_write_reg16(int fd, uint16_t reg, uint8_t value)
{
    uint8_t buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "I2C write to reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint16_t reg, uint8_t *buf, size_t len)
{
    uint8_t addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;
    if (write(fd, addr, 2) != 2) {
        fprintf(stderr, "I2C write (addr) to reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read from reg 0x%04X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- VL53L1X driver ---- */
static int vl53l1x_init(int fd)
{
    /* Soft reset */
    if (i2c_write_reg16(fd, VL53L1X_REG_SOFT_RESET, 0x00) < 0)
        return -1;
    gpioDelay(1000);  /* 1 ms */

    /* Clear any pending interrupt */
    if (i2c_write_reg16(fd, VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0)
        return -1;

    /* Start ranging (mode 1, 100 ms inter-measurement) */
    if (i2c_write_reg16(fd, VL53L1X_REG_SYSTEM_MODE_START, 0x40) < 0)
        return -1;

    return 0;
}

static int vl53l1x_read_distance(int fd, uint16_t *distance_cm)
{
    uint8_t status;
    uint8_t dist_buf[2];

    /* Poll range status */
    if (i2c_read_reg16(fd, VL53L1X_REG_RESULT_RANGE_STATUS, &status, 1) < 0)
        return -1;

    if ((status & 0x01) == 0) {
        /* No new data available */
        return 1;
    }

    /* Read 2 bytes distance */
    if (i2c_read_reg16(fd, VL53L1X_REG_RESULT_DISTANCE, dist_buf, 2) < 0)
        return -1;

    *distance_cm = ((uint16_t)dist_buf[0] << 8) | dist_buf[1];
    /* Clear interrupt so next measurement can be polled */
    if (i2c_write_reg16(fd, VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0)
        return -1;

    return 0;
}

/* ---- Relay control ---- */
static void relay_set(int pin, int state)
{
    if (gpioWrite(pin, state) < 0) {
        fprintf(stderr, "gpioWrite(%d, %d) failed: %s\n",
                pin, state, strerror(errno));
    }
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        /* Stop ranging */
        (void)i2c_write_reg16(g_i2c_fd, VL53L1X_REG_SYSTEM_MODE_START, 0x00);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    /* Ensure relay is off */
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
}

/* ---- Main ---- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure relay pin */
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d, OUTPUT) failed\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_PIN, 0);

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, VL53L1X_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                VL53L1X_ADDR, strerror(errno));
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (vl53l1x_init(g_i2c_fd) < 0) {
        fprintf(stderr, "VL53L1X initialization failed (sensor absent or bus error)\n");
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handler */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("VL53L1X distance monitor started. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t distance = 0;

        int rc = vl53l1x_read_distance(g_i2c_fd, &distance);
        if (rc == 0) {
            printf("Distance: %u cm\n", distance);
            if (distance <= DIST_THRESHOLD) {
                relay_set(RELAY_PIN, 1);
            } else {
                relay_set(RELAY_PIN, 0);
            }
        } else if (rc < 0) {
            fprintf(stderr, "Sensor read error (rc=%d)\n", rc);
            /* Keep relay in safe state (off) on sensor failure */
            relay_set(RELAY_PIN, 0);
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

