code:
/*
 * MPU-6050 Gyroscope Reader for Raspberry Pi 3 Model B+
 * Uses pigpio for I2C communication.
 *
 * Wiring:
 *   MPU-6050 SDA -> GPIO2 (BCM 2, I2C bus 1 SDA)
 *   MPU-6050 SCL -> GPIO3 (BCM 3, I2C bus 1 SCL)
 *   MPU-6050 VCC -> 3.3 V
 *   MPU-6050 GND -> GND
 *   MPU-6050 AD0 -> GND (I2C address 0x68)
 *
 * Build: gcc -Wall -Wextra -O2 -o mpu6050 mpu6050.c -lpigpio -lrt
 * Run:   sudo ./mpu6050
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define MPU6050_ADDR   0x68

/* MPU-6050 registers */
#define REG_SMPLRT_DIV  0x19
#define REG_CONFIG      0x1A
#define REG_GYRO_CONFIG 0x1B
#define REG_GYRO_XOUT_H 0x43
#define REG_PWR_MGMT_1  0x6B

/* Scaling factor for default ±250 °/s range */
#define GYRO_SCALE 250.0f

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int mpu6050_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%02X (rc=%d)\n",
                value, reg, rc);
        return -1;
    }
    return 0;
}

static int mpu6050_read_reg(int handle, uint8_t reg, uint8_t *value)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X (rc=%d)\n", reg, rc);
        return -1;
    }
    *value = (uint8_t)rc;
    return 0;
}

static int mpu6050_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "Error reading block from 0x%02X (rc=%d, expected %u)\n",
                reg, rc, len);
        return -1;
    }
    return 0;
}

static int mpu6050_init(int handle)
{
    /* Wake up the MPU-6050 (clear SLEEP bit) */
    if (mpu6050_write_reg(handle, REG_PWR_MGMT_1, 0x00) < 0)
        return -1;
    usleep(100000); /* 100 ms stabilization */

    /* Sample rate divider = 7 → 1 kHz / (1 + 7) = 125 Hz */
    if (mpu6050_write_reg(handle, REG_SMPLRT_DIV, 0x07) < 0)
        return -1;

    /* DLPF_CFG = 3 → 8 Hz bandwidth, 1.23 ms delay */
    if (mpu6050_write_reg(handle, REG_CONFIG, 0x03) < 0)
        return -1;

    /* Gyro full-scale range ±250 °/s */
    if (mpu6050_write_reg(handle, REG_GYRO_CONFIG, 0x00) < 0)
        return -1;

    return 0;
}

static int read_gyro(int handle, float *x, float *y, float *z)
{
    uint8_t buf[6];

    if (mpu6050_read_block(handle, REG_GYRO_XOUT_H, buf, 6) < 0)
        return -1;

    int16_t raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_y = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t raw_z = (int16_t)((buf[4] << 8) | buf[5]);

    *x = (float)raw_x / GYRO_SCALE;
    *y = (float)raw_y / GYRO_SCALE;
    *z = (float)raw_z / GYRO_SCALE;

    return 0;
}

int main(void)
{
    int handle = -1;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X (rc=%d)\n",
                I2C_BUS, MPU6050_ADDR, handle);
        goto cleanup_gpio;
    }

    if (mpu6050_init(handle) < 0) {
        fprintf(stderr, "MPU-6050 initialization failed (sensor absent or bus error)\n");
        goto cleanup_i2c;
    }

    printf("MPU-6050 initialized. Reading gyroscope data (Ctrl+C to exit)...\n");

    while (g_running) {
        float x, y, z;

        if (read_gyro(handle, &x, &y, &z) == 0) {
            printf("X: %7.2f °/s, Y: %7.2f °/s, Z: %7.2f °/s\n", x, y, z);
        } else {
            fprintf(stderr, "Failed to read gyroscope data\n");
        }

        usleep(100000); /* 100 ms */
    }

    printf("\nExiting...\n");
    rc = EXIT_SUCCESS;

cleanup_i2c:
    if (handle >= 0)
        i2cClose(handle);

cleanup_gpio:
    gpioTerminate();
    return rc;
}

