/*
 * Automated Plant Watering System for Raspberry Pi 4 Model B
 * Relays on GPIO17, GPIO18, GPIO27, GPIO22 (BCM numbering)
 * API: libgpiod (modern Linux GPIO character-device interface)
 * Compile: gcc -o watering watering.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define NUM_RELAYS 4
#define RELAY_PINS {17, 18, 27, 22}
#define WATERING_DURATION_SEC 5
#define CYCLE_INTERVAL_SEC 86400
#define POLL_INTERVAL_SEC 60
#define LOG_FILE "watering_log.txt"

static const unsigned int relay_pins[NUM_RELAYS] = RELAY_PINS;

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signum) {
    (void)signum;
    program_running = 0;
}

static int log_cycle_start(void) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (!localtime_r(&now, &tm_info)) {
        fprintf(stderr, "localtime_r() failed\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s\n", timestamp) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int set_relay(struct gpiod_line *line, int value) {
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Failed to set relay GPIO %u to %d: %s\n",
                gpiod_line_offset(line), value, strerror(errno));
        return -1;
    }
    return 0;
}

static int activate_relay(struct gpiod_line *line) {
    if (set_relay(line, 0) < 0) {
        return -1;
    }
    printf("Relay on GPIO %u activated\n", gpiod_line_offset(line));
    return 0;
}

static int deactivate_relay(struct gpiod_line *line) {
    if (set_relay(line, 1) < 0) {
        return -1;
    }
    printf("Relay on GPIO %u deactivated\n", gpiod_line_offset(line));
    return 0;
}

static void cleanup_gpio(struct gpiod_chip *chip, struct gpiod_line *lines[]) {
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "Failed to open gpiochip4: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    struct gpiod_line *lines[NUM_RELAYS];
    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %u: %s\n",
                    relay_pins[i], strerror(errno));
            cleanup_gpio(chip, lines);
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpiod_line_request_output(lines[i], "watering-system", 1) < 0) {
            fprintf(stderr, "Failed to request GPIO %u as output: %s\n",
                    relay_pins[i], strerror(errno));
            cleanup_gpio(chip, lines);
            return EXIT_FAILURE;
        }
    }

    if (log_cycle_start() < 0) {
        cleanup_gpio(chip, lines);
        return EXIT_FAILURE;
    }

    printf("Watering system started. Logging cycles to '%s'. Press Ctrl+C to exit.\n",
           LOG_FILE);

    while (program_running) {
        for (int i = 0; i < NUM_RELAYS && program_running; i++) {
            if (activate_relay(lines[i]) < 0) {
                cleanup_gpio(chip, lines);
                return EXIT_FAILURE;
            }
            sleep(WATERING_DURATION_SEC);
            if (program_running) {
                deactivate_relay(lines[i]);
            }
        }

        if (program_running) {
            if (log_cycle_start() < 0) {
                cleanup_gpio(chip, lines);
                return EXIT_FAILURE;
            }
        }

        for (int i = 0; i < CYCLE_INTERVAL_SEC / POLL_INTERVAL_SEC && program_running; i++) {
            sleep(POLL_INTERVAL_SEC);
        }
    }

    printf("\nShutting down...\n");
    cleanup_gpio(chip, lines);
    return EXIT_SUCCESS;
}

