/*
 * Smart Lighting Sunrise Effect for Raspberry Pi 4 Model B
 * Uses pigpio for hardware PWM on four GPIO pins.
 *
 * Wiring:
 *   GPIO17 -> Relay 1
 *   GPIO18 -> Relay 2
 *   GPIO27 -> Relay 3
 *   GPIO22 -> Relay 4
 *
 * Compile: gcc -o smart_lighting smart_lighting.c -lpigpio -lrt
 * Run:     sudo ./smart_lighting
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_RELAYS 4
#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define STEP_DELAY 1
#define TOTAL_DURATION 1800  /* 30 minutes in seconds */

static const int relay_pins[NUM_RELAYS] = {17, 18, 27, 22};
static const int num_relays = NUM_RELAYS;

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    FILE *fp = fopen("smart_lighting.log", "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

static int set_relay(int gpio, int state) {
    if (gpioWrite(gpio, state) != 0) {
        log_event("Error: gpioWrite failed for GPIO");
        return -1;
    }
    char msg[64];
    snprintf(msg, sizeof(msg), "Relay on GPIO%d set to %s", gpio, state ? "ON" : "OFF");
    log_event(msg);
    return 0;
}

static int initialize_gpio(void) {
    for (int i = 0; i < num_relays; i++) {
        if (gpioSetMode(relay_pins[i], PI_OUTPUT) != 0) {
            char msg[128];
            snprintf(msg, sizeof(msg), "Error: gpioSetMode failed for GPIO%d", relay_pins[i]);
            log_event(msg);
            return -1;
        }
        if (set_relay(relay_pins[i], 0) != 0) {
            return -1;
        }
    }
    return 0;
}

static int initialize_pwm(void) {
    if (gpioSetPWMfrequency(0, PWM_FREQUENCY) != 0) {
        log_event("Error: gpioSetPWMfrequency failed");
        return -1;
    }
    if (gpioSetPWMrange(0, PWM_RANGE) != 0) {
        log_event("Error: gpioSetPWMrange failed");
        return -1;
    }
    return 0;
}

static void sunrise_sequence(void) {
    int step = 0;
    int delay_seconds = TOTAL_DURATION / num_relays;

    while (running && step <= 255) {
        for (int i = 0; i < num_relays; i++) {
            if (gpioPWM(relay_pins[i], step) != 0) {
                log_event("Error: gpioPWM failed for GPIO");
                return;
            }
        }
        char msg[128];
        snprintf(msg, sizeof(msg), "Sunrise step %d/%d (step=%d, delay=%ds)",
                 step + 1, 256, step, delay_seconds);
        log_event(msg);

        step++;
        sleep(delay_seconds);
    }

    /* Turn off all relays */
    for (int i = 0; i < num_relays; i++) {
        if (gpioPWM(relay_pins[i], 0) != 0) {
            log_event("Error: gpioPWM failed for GPIO during shutdown");
            return;
        }
    }
    log_event("Sunrise sequence complete.");
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (gpioInitialise() < 0) {
        log_event("Error: pigpio initialisation failed");
        return 1;
    }

    if (initialize_gpio() != 0) {
        log_event("Error: GPIO initialization failed");
        gpioTerminate();
        return 1;
    }

    if (initialize_pwm() != 0) {
        log_event("Error: PWM initialization failed");
        gpioTerminate();
        return 1;
    }

    log_event("Smart lighting sunrise sequence started.");
    sunrise_sequence();

    gpioTerminate();
    log_event("Smart lighting sunrise sequence stopped.");
    return 0;
}

