/*
 * MPU-6050 Gyroscope Monitor — Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   MPU-6050 SDA -> GPIO2 (BCM)
 *   MPU-6050 SCL -> GPIO3 (BCM)
 *   MPU-6050 VCC -> 3.3 V
 *   MPU-6050 GND -> GND
 *   LED anode   -> GPIO17 (BCM) via 330 Ω resistor
 *   LED cathode -> GND
 *
 * Build:
 *   gcc -O2 -Wall -o gyro_monitor gyro_monitor.c -lpigpio -lrt
 * Run:
 *   sudo ./gyro_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ---- Configuration ---- */
#define I2C_BUS              1
#define MPU6050_ADDR         0x68
#define LED_GPIO             17
#define BUFFER_SIZE          100
#define SAMPLE_PERIOD_US     50000   /* 50 ms -> 20 Hz */
#define THRESHOLD_DEGS_S    250.0f
#define MAX_REINIT_ATTEMPTS  3

/* ---- MPU-6050 registers ---- */
#define PWR_MGMT_1           0x6B
#define GYRO_XOUT_H          0x43
#define GYRO_YOUT_H          0x45
#define GYRO_ZOUT_H          0x47

/* ---- Data structure ---- */
typedef struct {
    struct timespec timestamp;
    int16_t  x;
    int16_t  y;
    int16_t  z;
} gyro_data_t;

/* ---- Circular buffer ---- */
static gyro_data_t gyro_buffer[BUFFER_SIZE];
static int       buffer_index = 0;
static int       buffer_count = 0;

/* ---- Globals ---- */
static int  i2c_handle = -1;
static volatile sig_atomic_t running = 1;

/* ---- Prototypes ---- */
static int  init_mpu6050(void);
static int  read_gyro_data(gyro_data_t *data);
static void add_to_buffer(gyro_data_t data);
static void check_threshold(int16_t x, int16_t y, int16_t z);
static void signal_handler(int sig);
static void cleanup(void);

/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* --- LED GPIO setup --- */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* --- I2C open --- */
    i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (bus %d, addr 0x%02X): %d\n",
                I2C_BUS, MPU6050_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- MPU-6050 init --- */
    if (init_mpu6050() != 0) {
        fprintf(stderr, "Error: MPU-6050 initialisation failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Signals --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* --- Main loop --- */
    while (running) {
        gyro_data_t data;

        if (read_gyro_data(&data) != 0) {
            fprintf(stderr, "Warning: I2C read failed, attempting re-initialisation...\n");
            for (int attempt = 1; attempt <= MAX_REINIT_ATTEMPTS && running; ++attempt) {
                fprintf(stderr, "  Attempt %d/%d...\n", attempt, MAX_REINIT_ATTEMPTS);
                i2cClose(i2c_handle);
                i2c_handle = i2cOpen(I2C_BUS, MPU6050_ADDR, 0);
                if (i2c_handle < 0) {
                    fprintf(stderr, "    Failed to re-open I2C: %d\n", i2c_handle);
                    if (attempt < MAX_REINIT_ATTEMPTS) usleep(1000000);
                    continue;
                }
                if (init_mpu6050() == 0) {
                    fprintf(stderr, "    Re-initialisation successful.\n");
                    break;
                }
                fprintf(stderr, "    Re-initialisation failed.\n");
                i2cClose(i2c_handle);
                i2c_handle = -1;
            }
            if (i2c_handle < 0) {
                fprintf(stderr, "Error: I2C re-initialisation failed after %d attempts.\n",
                        MAX_REINIT_ATTEMPTS);
                break;
            }
            continue;
        }

        add_to_buffer(data);
        check_threshold(data.x, data.y, data.z);
        usleep(SAMPLE_PERIOD_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

/* ------------------------------------------------------------------ */
/* Initialise MPU-6050: wake up, verify device presence.                */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int init_mpu6050(void)
{
    /* Wake up: clear SLEEP bit in PWR_MGMT_1 (0x6B) */
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: failed to write PWR_MGMT_1 (0x%02X).\n", PWR_MGMT_1);
        return -1;
    }
    usleep(100000);  /* allow oscillator to stabilise */

    /* Verify device presence by reading WHO_AM_I (0x75) */
    int who = i2cReadByteData(i2c_handle, 0x75);
    if (who < 0) {
        fprintf(stderr, "Error: failed to read WHO_AM_I (0x%02X).\n", 0x75);
        return -1;
    }
    if (who != 0x68) {
        fprintf(stderr, "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x68).\n", who);
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read 6 bytes of gyro data (X, Y, Z) from GYRO_XOUT_H.               */
/* Returns 0 on success, -1 on failure.                               */
/* ------------------------------------------------------------------ */
static int read_gyro_data(gyro_data_t *data)
{
    char raw[6];

    if (i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, raw, 6) != 6) {
        fprintf(stderr, "Error: i2cReadI2CBlockData failed (reg 0x%02X).\n",
                GYRO_XOUT_H);
        return -1;
    }

    data->timestamp = clock_gettime(CLOCK_MONOTONIC);
    data->x = (int16_t)((raw[0] << 8) | (uint8_t)raw[1]);
    data->y = (int16_t)((raw[2] << 8) | (uint8_t)raw[3]);
    data->z = (int16_t)((raw[4] << 8) | (uint8_t)raw[5]);

    return 0;
}

/* ------------------------------------------------------------------ */
/* Append data to the circular buffer.                                 */
/* ------------------------------------------------------------------ */
static void add_to_buffer(gyro_data_t data)
{
    gyro_buffer[buffer_index] = data;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) ++buffer_count;
}

/* ------------------------------------------------------------------ */
/* Check if any axis exceeds the threshold.                           */
/* ------------------------------------------------------------------ */
static void check_threshold(int16_t x, int16_t y, int16_t z)
{
    bool exceeded = (fabsf((float)x) > THRESHOLD_DEGS_S ||
                     fabsf((float)y) > THRESHOLD_DEGS_S ||
                     fabsf((float)z) > THRESHOLD_DEGS_S);

    if (exceeded) {
        gpioWrite(LED_GPIO, 1);
    } else {
        gpioWrite(LED_GPIO, 0);
    }
}

/* ------------------------------------------------------------------ */
/* Signal handler — set flag only, defer heavy work to main loop.     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ------------------------------------------------------------------ */
/* Release all resources.                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

