            mpu_read_reg16(fd, REG_GYRO_YOUT_H, &yh) < 0 ||
            mpu_read_reg16(fd, REG_GYRO_YOUT_H + 1, &yl) < 0 ||
            mpu_read_reg16(fd, REG_GYRO_ZOUT_H, &zh) < 0 ||
            mpu_read_reg16(fd, REG_GYRO_ZOUT_H + 1, &zl) < 0) {
