        *y = (int16_t)((yh << 8) | yl);
        *z = (int16_t)((zh << 8) | zl);
        return 0;
    }

    fprintf(stderr, "Gyro read failed after %d retries\n", MAX_SPI_RETRIES);
    return -1;
}

