/*
 * MPU-9250 Gyroscope SPI Logger for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   MPU-9250 SDA -> GPIO2 (BCM 2, /dev/gpiochip0 line 2)
 *   MPU-9250 SCL -> GPIO3 (BCM 3, /dev/gpiochip0 line 3)
 *   MPU-9250 VDD -> 3.3 V
 *   MPU-9250 GND -> GND
 *   MPU-9250 CS  -> GPIO8 (BCM 8, /dev/gpiochip0 line 8)  [manual chip-select]
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o gyro_log gyro_log.c -lgpiod
 *
 * Run:
 *   ./gyro_log
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE        "/dev/spidev0.0"
#define GPIO_CHIP         "/dev/gpiochip0"
#define CS_LINE_OFFSET    8          /* BCM 8 on gpiochip0 */
#define SPI_SPEED_HZ      1000000    /* 1 MHz */
#define SPI_BITS_PER_WORD 8
#define SPI_MODE          SPI_MODE_0
#define LOG_FILE          "gyro_log.txt"
#define SAMPLE_PERIOD_MS  10
#define MAX_SPI_RETRIES   3

/* MPU-9250 register addresses (from datasheet) */
#define REG_SMPLRT_DIV   0x19
#define REG_GYRO_CONFIG  0x1B
#define REG_GYRO_XOUT_H  0x43
#define REG_PWR_MGMT_1   0x6B
#define REG_WHO_AM_I     0x75

#define WHO_AM_I_VAL     0x68

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* SPI helpers                                                         */
/* ------------------------------------------------------------------ */

static int spi_open(const char *device)
{
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", device, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

/*
 * Read a 16-bit big-endian register from the MPU-9250.
 * Returns 0 on success and stores the value in *out; -1 on error.
 */
static int mpu_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t tx[3] = { reg, 0x00, 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = 3;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS_PER_WORD;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI read reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }

    *out = ((uint16_t)rx[0] << 8) | rx[1];
    return 0;
}

/* Write a 16-bit big-endian value to a register on the MPU-9250. */
static int mpu_write_reg16(int fd, uint8_t reg, uint16_t val)
{
    uint8_t tx[3] = { reg, (uint8_t)(val >> 8), (uint8_t)(val & 0xFF) };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = 3;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS_PER_WORD;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI write reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* GPIO chip helpers                                                    */
/* ------------------------------------------------------------------ */

static struct gpiod_line *cs_line = NULL;

static int cs_init(void)
{
    struct gpiod_chip *chip = gpiod_chip_open(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open(%s): %s\n", GPIO_CHIP, strerror(errno));
        return -1;
    }

    cs_line = gpiod_chip_get_line(chip, CS_LINE_OFFSET);
    if (!cs_line) {
        fprintf(stderr, "gpiod_chip_get_line(%d): %s\n",
                CS_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(cs_line, "mpu9250-cs", 1) < 0) {
        fprintf(stderr, "gpiod_line_request_output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

static void cs_release(void)
{
    if (cs_line) {
        gpiod_line_set_value(cs_line, 1);   /* de-assert CS */
        gpiod_line_release(cs_line);
        cs_line = NULL;
    }
    if (cs_line) gpiod_chip_close(gpiod_chip_open(GPIO_CHIP));
}

/* ------------------------------------------------------------------ */
/* MPU-9250 initialization                                              */
/* ------------------------------------------------------------------ */

static int mpu_init(int fd)
{
    uint16_t who = 0;

    if (mpu_read_reg16(fd, REG_WHO_AM_I, &who) < 0)
        return -1;

    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%04X, expected 0x%02X\n",
                who, WHO_AM_I_VAL);
        return -1;
    }

    /* Wake up the device (clear SLEEP bit) */
    if (mpu_write_reg16(fd, REG_PWR_MGMT_1, 0x00) < 0)
        return -1;
    usleep(100000);  /* allow oscillator to stabilize */

    /* Sample rate divider = 7 -> 1 kHz / (1 + 7) = 125 Hz */
    if (mpu_write_reg16(fd, REG_SMPLRT_DIV, 0x07) < 0)
        return -1;

    /* Gyro full-scale range = +/- 250 deg/s */
    if (mpu_write_reg16(fd, REG_GYRO_CONFIG, 0x00) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Data acquisition                                                     */
/* ------------------------------------------------------------------ */

static int read_gyro(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint16_t xh, xl, yh, yl, zh, zl;

    for (int attempt = 0; attempt < MAX_SPI_RETRIES; attempt++) {
        if (mpu_read_reg16(fd, REG_GYRO_XOUT_H, &xh) < 0 ||
            mpu_read_reg16(fd, REG_GYRO_XOUT_H + 1, &xl) < 0 ||
            mpu_read_reg16(fd, REG_GYRO_YOUT_H, &yh) < 0 ||
            mpu_read_reg16(fd, REG_GYRO_YOUT_H + 1, &yl) < 0 ||
            mpu_read_reg16(fd, REG_GYRO_ZOUT_H, &zh) < 0 ||
            mpu_read_reg16(fd, REG_GYRO_ZOUT_H + 1, &zl) < 0) {
            usleep(10000);
            continue;
        }

        *x = (int16_t)((xh << 8) | xl);
        *y = (int16_t)((yh << 8) | yl);
        *z = (int16_t)((zh << 8) | zl);
        return 0;
    }

    fprintf(stderr, "Gyro read failed after %d retries\n", MAX_SPI_RETRIES);
    return -1;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */

static int log_open(void)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    return fp;
}

static void log_data(FILE *fp, int16_t x, int16_t y, int16_t z)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
        fprintf(stderr, "clock_gettime: %s\n", strerror(errno));
        return;
    }

    struct tm tm_buf;
    struct tm *tm = localtime_r(&ts.tv_sec, &tm_buf);
    if (!tm) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }

    char tbuf[32];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%dT%H:%M:%S", tm);
    fprintf(fp, "%s.%09ldZ,%d,%d,%d\n", tbuf, ts.tv_nsec, x, y, z);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    int spi_fd = -1;
    FILE *log_fp = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    spi_fd = spi_open(SPI_DEVICE);
    if (spi_fd < 0)
        goto cleanup;

