#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 3900000
#define SPI_MODE 0
#define SPI_BITS 8
#define LED_PIN 17
#define BUFFER_SIZE 64
#define THRESHOLD 200.0
#define SAMPLE_DELAY_US 1000

typedef struct {
    time_t timestamp;
    int16_t x;
    int16_t y;
    int16_t z;
} gyro_data_t;

static gyro_data_t gyro_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;
static volatile sig_atomic_t program_running = 1;
static int spi_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI max speed: %s\n", strerror(errno));
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

static int read_gyro_data(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t tx[3] = {0x68, 0x01, 0x00};
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error during SPI transfer: %s\n", strerror(errno));
        return -1;
    }

    *x = (int16_t)((rx[0] << 8) | rx[1]);
    *y = (int16_t)((rx[1] << 8) | rx[2]);
    *z = (int16_t)((rx[2] << 8) | 0x00);

    return 0;
}

static void add_to_buffer(time_t timestamp, int16_t x, int16_t y, int16_t z) {
    gyro_buffer[buffer_index].timestamp = timestamp;
    gyro_buffer[buffer_index].x = x;
    gyro_buffer[buffer_index].y = y;
    gyro_buffer[buffer_index].z = z;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
}

static void print_buffer(void) {
    printf("Timestamp,X,Y,Z\n");
    for (int i = 0; i < buffer_count; i++) {
        int idx = (buffer_index - buffer_count + i + BUFFER_SIZE) % BUFFER_SIZE;
        char ts[32];
        struct tm *tm_info = localtime(&gyro_buffer[idx].timestamp);
        if (tm_info) {
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);
        } else {
            snprintf(ts, sizeof(ts), "unknown");
        }
        printf("%s,%d,%d,%d\n", ts, gyro_buffer[idx].x, gyro_buffer[idx].y, gyro_buffer[idx].z);
    }
    fflush(stdout);
}

static void check_threshold(int16_t x, int16_t y, int16_t z) {
    if (fabs((double)x) > THRESHOLD || fabs((double)y) > THRESHOLD || fabs((double)z) > THRESHOLD) {
        printf("Warning: Threshold exceeded! X=%d Y=%d Z=%d\n", x, y, z);
        for (int i = 0; i < 5 && program_running; i++) {
            gpioWrite(LED_PIN, 1);
            gpioDelay(500000);
            gpioWrite(LED_PIN, 0);
            gpioDelay(500000);
        }
    }
}

static void cleanup(void) {
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    if (spi_init() < 0) {
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("MPU-6050 SPI monitor started. Press Ctrl-C to exit.\n");

    while (program_running) {
        int16_t x, y, z;
        if (read_gyro_data(&x, &y, &z) == 0) {
            time_t now = time(NULL);
            if (now == (time_t)-1) {
                fprintf(stderr, "Error getting time: %s\n", strerror(errno));
            } else {
                add_to_buffer(now, x, y, z);
                check_threshold(x, y, z);
            }
        } else {
            fprintf(stderr, "Error reading gyro data\n");
        }
        gpioDelay(SAMPLE_DELAY_US);
    }

    printf("\nShutting down...\n");
    print_buffer();
    cleanup();
    return 0;
}

