        fprintf(stderr, "Error during SPI transfer: %s\n", strerror(errno));
        return -1;
    }

    *x = (int16_t)((rx[0] << 8) | rx[1]);
    *y = (int16_t)((rx[1] << 8) | rx[2]);
    *z = (int16_t)((rx[2] << 8) | 0x00);

    return 0;
}

static void add_to_buffer(time_t timestamp, int16_t x, int16_t y, int16_t z) {
    gyro_buffer[buffer_index].timestamp = timestamp;
    gyro_buffer[buffer_index].x = x;
    gyro_buffer[buffer_index].y = y;
    gyro_buffer[buffer_index].z = z;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
}

static void print_buffer(void) {
    printf("Timestamp,X,Y,Z\n");
    for (int i = 0; i < buffer_count; i++) {
        int idx = (buffer_index - buffer_count + i + BUFFER_SIZE) % BUFFER_SIZE;
        char ts[32];
        struct tm *tm_info = localtime(&gyro_buffer[idx].timestamp);
        if (tm_info) {
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", tm_info);
        } else {
            snprintf(ts, sizeof(ts), "unknown");
        }
        printf("%s,%d,%d,%d\n", ts, gyro_buffer[idx].x, gyro_buffer[idx].y, gyro_buffer[idx].z);
    }
    fflush(stdout);
}

static void check_threshold(int16_t x, int16_t y, int16_t z) {
    if (fabs((double)x) > THRESHOLD || fabs((double)y) > THRESHOLD || fabs((double)z) > THRESHOLD) {
        printf("Warning: Threshold exceeded! X=%d Y=%d Z=%d\n", x, y, z);
        for (int i = 0; i < 5 && program_running; i++) {
            gpioWrite(LED_PIN, 1);
            gpioDelay(500000);
            gpioWrite(LED_PIN, 0);
            gpioDelay(500000);
        }
    }
}

static void cleanup(void) {
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    if (spi_init() < 0) {
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("MPU-6050 SPI monitor started. Press Ctrl-C to exit.\n");

    while (program_running) {
        int16_t x, y, z;
        if (read_gyro_data(&x, &y, &z) == 0) {
            time_t now = time(NULL);
            if (now == (time_t)-1) {
                fprintf(stderr, "Error getting time: %s\n", strerror(errno));
            } else {
                add_to_buffer(now, x, y, z);
                check_threshold(x, y, z);
            }
        } else {
            fprintf(stderr, "Error reading gyro data\n");
        }
        gpioDelay(SAMPLE_DELAY_US);
    }

    printf("\nShutting down...\n");
    print_buffer();
    cleanup();
    return 0;
}

