/*
 * MPU-6050 Tilt Logger for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   MPU-6050 SDA -> GPIO2 (I2C bus 1 SDA)
 *   MPU-6050 SCL -> GPIO3 (I2C bus 1 SCL)
 *   MPU-6050 VCC -> 3.3 V
 *   MPU-6050 GND -> GND
 *   LED anode   -> GPIO21 (BCM) via 330 ohm resistor
 *   LED cathode -> GND
 *
 * Build:  gcc -O2 -Wall -o tilt_logger tilt_logger.c -lm
 * Run:    sudo ./tilt_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- MPU-6050 constants (verified against datasheet) ---- */
#define MPU6050_ADDR        0x68
#define PWR_MGMT_1          0x6B
#define ACCEL_XOUT_H        0x3B
#define ACCEL_YOUT_H        0x3D
#define ACCEL_ZOUT_H        0x3F
#define ACCEL_CONFIG        0x1C
#define SMPLRT_DIV          0x19
#define PWR_MGMT_1_VAL      0x00
#define ACCEL_CONFIG_VAL    0x00
#define SMPLRT_DIV_VAL      0x07

/* ---- GPIO / LED constants ---- */
#define LED_GPIO            21
#define I2C_BUS             "/dev/i2c-1"

/* ---- Tilt thresholds (degrees) ---- */
#define TILT_THRESHOLD      45.0f

/* ---- Globals for cleanup ---- */
static int  g_i2c_fd = -1;
static bool g_running = true;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = false;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                          */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    uint8_t val;
    if (read(fd, &val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = val;
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *out)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read 16-bit from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* MPU-6050 initialization                                              */
/* ------------------------------------------------------------------ */
static int mpu6050_init(int fd)
{
    if (i2c_write_reg8(fd, PWR_MGMT_1, PWR_MGMT_1_VAL) < 0)
        return -1;
    usleep(100000);  /* allow oscillator to stabilize */

    if (i2c_write_reg8(fd, ACCEL_CONFIG, ACCEL_CONFIG_VAL) < 0)
        return -1;
    if (i2c_write_reg8(fd, SMPLRT_DIV, SMPLRT_DIV_VAL) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read raw accelerometer data                                        */
/* ------------------------------------------------------------------ */
static int read_raw_accel(int fd, int16_t *ax, int16_t *ay, int16_t *az)
{
    if (i2c_read_reg16(fd, ACCEL_XOUT_H, ax) < 0) return -1;
    if (i2c_read_reg16(fd, ACCEL_YOUT_H, ay) < 0) return -1;
    if (i2c_read_reg16(fd, ACCEL_ZOUT_H, az) < 0) return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Compute roll and pitch from raw accelerometer data                   */
/* ------------------------------------------------------------------ */
static void compute_tilt(int16_t ax, int16_t ay, int16_t az,
                         float *roll, float *pitch)
{
    /* raw values are 16-bit two's complement; convert to +/- 2 g */
    float fx = (float)ax / 16384.0f;
    float fy = (float)ay / 16384.0f;
    float fz = (float)az / 16384.0f;

    *roll  = atan2f(fy, fz) * 180.0f / (float)M_PI;
    *pitch = atan2f(-fx, sqrtf(fy * fy + fz * fz)) * 180.0f / (float)M_PI;
}

/* ------------------------------------------------------------------ */
/* Append a CSV line to the log file                                  */
/* ------------------------------------------------------------------ */
static int log_tilt_data(float roll, float pitch)
{
    FILE *fp = fopen("tilt_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "Cannot open tilt_log.txt: %s\n", strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.2f\n", ts, roll, pitch);
    fclose(fp);
    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Install signal handler ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus ---- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                MPU6050_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* ---- Initialize sensor ---- */
    if (mpu6050_init(g_i2c_fd) < 0) {
        fprintf(stderr, "MPU-6050 initialization failed.\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* ---- Configure LED GPIO ---- */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed: %s\n",
                LED_GPIO, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    printf("MPU-6050 tilt logger started. Press Ctrl+C to exit.\n");

    /* ---- Main sampling loop ---- */
    while (g_running) {
        int16_t ax, ay, az;

        if (read_raw_accel(g_i2c_fd, &ax, &ay, &az) < 0) {
            fprintf(stderr, "Read error; continuing.\n");
            usleep(100000);
            continue;
        }

        float roll, pitch;
        compute_tilt(ax, ay, az, &roll, &pitch);

        /* LED control */
        int led_state = (fabsf(roll) > TILT_THRESHOLD ||
                         fabsf(pitch) > TILT_THRESHOLD) ? 1 : 0;
        gpioWrite(LED_GPIO, led_state);

        /* Log to file */
        if (log_tilt_data(roll, pitch) < 0) {
            fprintf(stderr, "Logging failed; continuing.\n");
        }

        printf("Roll: %.2f deg, Pitch: %.2f deg, LED: %s\n",
               roll, pitch, led_state ? "ON" : "OFF");

        usleep(100000);  /* 100 ms */
    }

    /* ---- Cleanup ---- */
    gpioWrite(LED_GPIO, 0);
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

