#define GPIO_PIN 17
#define PROXIMITY_THRESHOLD 100
#define LOG_FILE "biometric_log.txt"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define POLL_DELAY_MS 100

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write reg error: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int si1145_init(int fd) {
    uint8_t part_id;
    if (i2c_read_byte(fd, SI1145_REG_PART_ID, &part_id) < 0) {
        return -1;
    }
    if (part_id != SI1145_PART_ID) {
        fprintf(stderr, "Unexpected Part ID: 0x%02X (expected 0x%02X)\n", part_id, SI1145_PART_ID);
        return -1;
    }
    if (i2c_write_byte(fd, SI1145_REG_HW_KEY, SI1145_HW_KEY_VAL) < 0) return -1;
    if (i2c_write_byte(fd, SI1145_REG_MEAS_RATE0, SI1145_MEAS_RATE_100MS) < 0) return -1;
    if (i2c_write_byte(fd, SI1145_REG_COMMAND, SI1145_CMD_PSALS_AUTO_AUTO_AUTO_EN) < 0) return -1;
    return 0;
}

static int si1145_read_data(int fd, uint16_t *ambient_light, uint16_t *proximity) {
    uint8_t als_data, ps_data;
    if (i2c_read_byte(fd, SI1145_REG_ALS_VIS_DATA0, &als_data) < 0) return -1;
    if (i2c_read_byte(fd, SI1145_REG_PS1_DATA0, &ps_data) < 0) return -1;
    *ambient_light = (uint16_t)als_data;
    *proximity = (uint16_t)ps_data;
    return 0;
}

static void log_data(FILE *fp, uint16_t ambient_light, uint16_t proximity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,AmbientLight:%u,Proximity:%u\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            ambient_light, proximity);
    fflush(fp);
}

static void control_led(int gpio_pin, uint16_t proximity) {
    int val = (proximity > PROXIMITY_THRESHOLD) ? 1 : 0;
    if (gpioWrite(gpio_pin, val) < 0) {
        fprintf(stderr, "GPIO write error: %s\n", strerror(errno));
    }
}

static void cleanup(void) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open I2C bus");
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, SI1145_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        cleanup();
        return 1;
    }
    if (si1145_init(i2c_fd) < 0) {
        fprintf(stderr, "Si1145 initialization failed\n");
        cleanup();
        return 1;
    }
    if (si1145_write_byte(i2c_fd, SI1145_REG_COMMAND, SI1145_CMD_PSALS_AUTO_AUTO_AUTO_EN) < 0) {
        fprintf(stderr, "Failed to start PSALS auto mode\n");
        cleanup();
        return 1;
    }
    usleep(10000);
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen log");
        cleanup();
        return 1;
    }
    printf("Si1145 initialized. Logging to %s\n", LOG_FILE);
    while (running) {
        uint16_t ambient_light = 0, proximity = 0;
        int success = 0;
        for (int attempt = 0; attempt < MAX_RETRIES && running; attempt++) {
            if (si1145_read_data(i2c_fd, &ambient_light, &proximity) == 0) {
                success = 1;
                break;
            }
            fprintf(stderr, "Read attempt %d failed\n", attempt + 1);
            usleep(RETRY_DELAY_MS * 1000);
        }
        if (success) {
