/*
 * ADXRS290 dual-axis gyroscope reader for Raspberry Pi Zero W
 * SPI channel 0, CE0 (GPIO8, BCM), 1 MHz, mode 0 (CPOL=0, CPHA=0)
 * Samples X/Y axes at ~100 Hz, logs to gyro_data.csv
 *
 * Build:  gcc -O2 -Wall -o gyro gyro.c -lm
 * Run:    ./gyro
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U
#define SPI_BITS        8
#define SPI_MODE        SPI_MODE_0
#define SAMPLE_DELAY_US 10000U   /* 10 ms -> ~100 Hz */
#define MAX_RETRIES     3

/* ADXRS290 register addresses (8-bit, read bit = 0x80) */
#define REG_GYRO_X_RATE  0x00
#define REG_GYRO_Y_RATE  0x02

static volatile sig_atomic_t g_running = 1;
static int  g_spi_fd = -1;
static FILE *g_fp    = NULL;

/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int spi_init(void)
{
    uint8_t mode = SPI_MODE;
    uint8_t bits = SPI_BITS;
    uint32_t speed = SPI_SPEED_HZ;

    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        perror("open(" SPI_DEVICE ")");
        return -1;
    }

    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl(SPI_IOC_WR_MODE)");
        goto fail;
    }
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl(SPI_IOC_WR_BITS_PER_WORD)");
        goto fail;
    }
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl(SPI_IOC_WR_MAX_SPEED_HZ)");
        goto fail;
    }
    return 0;

fail:
    close(g_spi_fd);
    g_spi_fd = -1;
    return -1;
}

/* ------------------------------------------------------------------ */
/* ADXRS290 SPI read: send (reg | 0x80) | 0x00, receive 2 bytes.
 * Response byte 0 = dummy, byte 1 = data (MSB first).               */
static int spi_read_reg(uint8_t reg, int16_t *out)
{
    uint8_t tx[2] = { (uint8_t)(reg | 0x80), 0x00 };
    uint8_t rx[2] = { 0, 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = 2;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("ioctl(SPI_IOC_MESSAGE)");
        return -1;
    }

    int16_t val = (int16_t)(((uint16_t)rx[0] << 8) | rx[1]);
    *out = val;
    return 0;
}

/* ------------------------------------------------------------------ */
static int log_sample(time_t ts, int16_t x, int16_t y)
{
    struct tm tm_info;
    struct tm *tm_ptr = localtime_r(&ts, &tm_info);
    if (!tm_ptr) {
        perror("localtime_r");
        return -1;
    }

    char ts_str[32];
    strftime(ts_str, sizeof(ts_str), "%Y-%m-%d %H:%M:%S", tm_ptr);
    int64_t us = (int64_t)(ts - tm_ptr->tm_gmtoff) * 1000000LL;

    if (fprintf(g_fp, "%s.%06ld,%d,%d\n", ts_str, (long)us, x, y) < 0) {
        perror("fprintf");
        return -1;
    }
    if (fflush(g_fp) != 0) {
        perror("fflush");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_fp) {
        fflush(g_fp);
        fclose(g_fp);
        g_fp = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

