{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed.\n");
        return EXIT_FAILURE;
    }

    g_fp = fopen("gyro_data.csv", "w");
    if (!g_fp) {
        perror("fopen(gyro_data.csv)");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header */
    if (fprintf(g_fp, "timestamp_sec_us,x_rate,y_rate\n") < 0) {
        perror("fprintf(header)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (fflush(g_fp) != 0) {
        perror("fflush(header)");
        cleanup();
        return EXIT_FAILURE;
    }

    int consecutive_failures = 0;

    while (g_running) {
        int16_t x = 0, y = 0;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; ++attempt) {
            if (spi_read_reg(REG_GYRO_X_RATE, &x) == 0 &&
                spi_read_reg(REG_GYRO_Y_RATE, &y) == 0) {
                ok = 1;
                break;
            }
            consecutive_failures++;
            fprintf(stderr, "SPI read attempt %d/%d failed.\n",
                    attempt + 1, MAX_RETRIES);
            if (g_running) {
                usleep(10000U);
            }
        }

        if (ok) {
            time_t now = time(NULL);
            if (now == (time_t)-1) {
                perror("time");
            } else {
                if (log_sample(now, x, y) < 0) {
                    fprintf(stderr, "Logging failed; aborting.\n");
                    break;
                }
            }
        } else {
            consecutive_failures++;
            fprintf(stderr, "All %d SPI read attempts failed; re-initializing SPI.\n",
                    MAX_RETRIES);
            if (spi_init() < 0) {
                fprintf(stderr, "SPI re-initialization failed.\n");
                break;
            }
            if (consecutive_failures >= MAX_RETRIES) {
                fprintf(stderr, "Too many consecutive failures; aborting.\n");
                break;
            }
        }

        usleep(SAMPLE_DELAY_US);
    }

    cleanup();
    return (g_running) ? EXIT_SUCCESS : EXIT_FAILURE;
}

