#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define SENSOR_1_GPIO 23
#define SENSOR_2_GPIO 24
#define ALERT_GPIO    17
#define SEISMIC_THRESHOLD_MS 500
#define ALERT_DURATION_US   2000000
#define POLL_DELAY_US       10000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(void) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(log_file, "%s - Seismic event detected!\n", timestamp) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
    }
}

static void alert_callback(int gpio, int level, uint32_t tick) {
    (void)tick;
    if (gpio == ALERT_GPIO) {
        static uint32_t alert_start_tick = 0;
        static int alert_active = 0;

        if (level == 1) {
            if (!alert_active) {
                alert_active = 1;
                alert_start_tick = gpioTick();
            } else if (gpioTick() - alert_start_tick >= ALERT_DURATION_US) {
                if (gpioWrite(ALERT_GPIO, 0) != 0) {
                    fprintf(stderr, "Failed to write alert pin LOW\n");
                }
                alert_active = 0;
            }
        } else if (level == 0) {
            alert_active = 0;
        }
    }
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SENSOR_1_GPIO);
        return -1;
    }
    if (gpioSetMode(SENSOR_2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SENSOR_2_GPIO);
        return -1;
    }
    if (gpioSetMode(ALERT_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", ALERT_GPIO);
        return -1;
    }

    if (gpioSetPullUpDown(SENSOR_1_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO%d\n", SENSOR_1_GPIO);
        return -1;
    }
    if (gpioSetPullUpDown(SENSOR_2_GPIO, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set pull-down on GPIO%d\n", SENSOR_2_GPIO);
        return -1;
    }

    if (gpioSetAlertFunc(SENSOR_1_GPIO, alert_callback) != 0) {
        fprintf(stderr, "Failed to register alert callback on GPIO%d\n", SENSOR_1_GPIO);
        return -1;
    }
    if (gpioSetAlertFunc(SENSOR_2_GPIO, alert_callback) != 0) {
        fprintf(stderr, "Failed to register alert callback on GPIO%d\n", SENSOR_2_GPIO);
        return -1;
    }

    if (gpioWrite(ALERT_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to initialize alert pin LOW\n");
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    log_file = fopen("seismic_events.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring tilt sensors on GPIO%d and GPIO%d. Alert on GPIO%d. Press Ctrl+C to exit.\n",
           SENSOR_1_GPIO, SENSOR_2_GPIO, ALERT_GPIO);

    while (running) {
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down gracefully...\n");

    if (log_file != NULL) {
        if (fclose(log_file) != 0) {
            fprintf(stderr, "Failed to close log file: %s\n", strerror(errno));
        }
        log_file = NULL;
    }

    gpioWrite(ALERT_GPIO, 0);
    gpioTerminate();

    return EXIT_SUCCESS;
}

