    log_file = fopen("seismic_events.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring tilt sensors on GPIO%d and GPIO%d. Alert on GPIO%d. Press Ctrl+C to exit.\n",
           SENSOR_1_GPIO, SENSOR_2_GPIO, ALERT_GPIO);

    while (running) {
        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down gracefully...\n");

    if (log_file != NULL) {
        if (fclose(log_file) != 0) {
            fprintf(stderr, "Failed to close log file: %s\n", strerror(errno));
        }
        log_file = NULL;
    }

    gpioWrite(ALERT_GPIO, 0);
    gpioTerminate();

    return EXIT_SUCCESS;
}

