#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000
#define SPI_FLAGS   0
#define LED_PIN     17
#define BUFFER_SIZE 100
#define THRESHOLD   20.0f
#define SAMPLE_US   10000

typedef struct {
    struct timespec timestamp;
    float rate;
} GyroData;

typedef struct {
    GyroData data[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} CircularBuffer;

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static CircularBuffer gyro_buffer;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_circular_buffer(CircularBuffer *cb) {
    memset(cb, 0, sizeof(*cb));
    if (pthread_mutex_init(&cb->mutex, NULL) != 0) {
        perror("pthread_mutex_init");
        return -1;
    }
    return 0;
}

static void cleanup_circular_buffer(CircularBuffer *cb) {
    pthread_mutex_destroy(&cb->mutex);
}

static int add_to_buffer(CircularBuffer *cb, float rate) {
    if (pthread_mutex_lock(&cb->mutex) != 0) {
        perror("pthread_mutex_lock");
        return -1;
    }
    cb->data[cb->head].rate = rate;
    clock_gettime(CLOCK_MONOTONIC, &cb->data[cb->head].timestamp);
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count == BUFFER_SIZE) {
        cb->tail = (cb->tail + 1) % BUFFER_SIZE;
    } else {
        cb->count++;
    }
    if (pthread_mutex_unlock(&cb->mutex) != 0) {
        perror("pthread_mutex_unlock");
        return -1;
    }
    return 0;
}

static int read_gyro_rate(float *rate_out) {
    char tx[2] = {0x80, 0x00};
    char rx[2] = {0};
    int ret = spiXfer(spi_handle, tx, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "spiXfer failed: %s\n", pigpio_error(ret));
        return -1;
    }
    int16_t raw = (int16_t)(((uint8_t)rx[0] << 8) | (uint8_t)rx[1]);
    *rate_out = (float)raw;
    return 0;
}

static void control_led(int state) {
    if (gpioWrite(LED_PIN, state) != 0) {
        fprintf(stderr, "gpioWrite failed: %s\n", pigpio_error(state));
    }
}

static void *gyro_thread(void *arg) {
    (void)arg;
    float rate;
    while (running) {
        if (read_gyro_rate(&rate) == 0) {
            if (add_to_buffer(&gyro_buffer, rate) != 0) {
                fprintf(stderr, "Buffer add failed\n");
            }
            printf("Rate: %.2f deg/s\n", rate);
            if (rate > THRESHOLD) {
                control_led(1);
            } else {
                control_led(0);
            }
        } else {
            fprintf(stderr, "Gyro read error\n");
        }
        gpioDelay(SAMPLE_US);
    }
    return NULL;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed\n");
        gpioTerminate();
        return 1;
    }
    gpioWrite(LED_PIN, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed: %s\n", pigpio_error(spi_handle));
        gpioTerminate();
        return 1;
    }

    if (init_circular_buffer(&gyro_buffer) != 0) {
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup_circular_buffer(&gyro_buffer);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    pthread_t gyro_tid;
    if (pthread_create(&gyro_tid, NULL, gyro_thread, NULL) != 0) {
        perror("pthread_create");
        cleanup_circular_buffer(&gyro_buffer);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    pthread_join(gyro_tid, NULL);

    control_led(0);
    cleanup_circular_buffer(&gyro_buffer);
    spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

