/*
 * Smart Sunset Simulator for Raspberry Pi Zero W
 *
 * Three dimmable lamps (BCM GPIO17, GPIO18, GPIO27) are sequentially
 * faded from full brightness to off over a user-supplied duration in
 * seconds.  PWM is driven via the hardware PWM subsystem at 100 Hz,
 * with a 0-255 duty-cycle range (no software PWM used).
 *
 * Build:  gcc -O2 -Wall -Wextra -o sunset sunset.c
 * Run:    ./sunset <duration_seconds>
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>

#include <pigpio.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define LAMP1_PIN 17
#define LAMP2_PIN 18
#define LAMP3_PIN 27

/* ---- PWM parameters ---- */
#define PWM_FREQUENCY 100          /* Hz */
#define PWM_RANGE     255          /* duty-cycle resolution */
#define FADE_STEPS    100          /* steps per lamp per fade cycle */
#define FADE_DELAY_US 10000        /* 10 ms per step (100 Hz) */

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_pigpio_initialized = 0;

/* ------------------------------------------------------------------ */
/* Signal handler — async-signal-safe: only set flag, no I/O        */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Turn off all three lamps and release pigpio resources             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_pigpio_initialized) {
        /* Best-effort: turn off each lamp */
        gpioPWM(LAMP1_PIN, 0);
        gpioPWM(LAMP2_PIN, 0);
        gpioPWM(LAMP3_PIN, 0);
        gpioTerminate();
        g_pigpio_initialized = 0;
    }
}

/* ------------------------------------------------------------------ */
/* Validate user input: must be an integer 1–3600 seconds             */
/* ------------------------------------------------------------------ */
static int validate_duration(const char *arg)
{
    errno = 0;
    char *endptr = NULL;
    long val = strtol(arg, &endptr, 10);

    if (errno != 0 || endptr == arg || *endptr != '\0' ||
        val < 1 || val > 3600) {
        fprintf(stderr,
                "Error: duration must be an integer 1–3600 seconds.\n");
        return -1;
    }
    return (int)val;
}

/* ------------------------------------------------------------------ */
/* Fade a single lamp from current duty cycle to target duty cycle   */
/* over the given duration in seconds.  Returns 0 on success.         */
/* ------------------------------------------------------------------ */
static int fade_lamp(int pin, int current, int target, int duration_sec)
{
    int steps = FADE_STEPS;
    int step_us = FADE_DELAY_US;
    int increment = (target - current) / steps;

    if (increment < 0) {
        /* Fade off — reverse direction */
        increment = -increment;
    }

    for (int i = 0; i < steps && g_running; i++) {
        int duty = current + (i + 1) * increment;
        if (gpioPWM(pin, duty) < 0) {
            fprintf(stderr,
                    "Warning: gpioPWM failed on pin %d (duty %d).\n",
                    pin, duty);
            return -1;
        }
        current = duty;
        usleep(step_us);
    }

    if (!g_running) {
        return -1;
    }

    if (gpioPWM(pin, target) < 0) {
        fprintf(stderr,
                "Warning: gpioPWM failed on pin %d (target %d).\n",
                pin, target);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                               */
/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    if (argc != 2) {
        fprintf(stderr,
                "Usage: %s <duration_seconds>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int duration = validate_duration(argv[1]);
    if (duration < 0) {
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }
    g_pigpio_initialized = 1;

    /* ---- Configure lamp pins as outputs ---- */
    int pins[] = { LAMP1_PIN, LAMP2_PIN, LAMP3_PIN };
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) < 0) {
            fprintf(stderr,
                    "Error: gpioSetMode failed for pin %d.\n", pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
    }

    /* ---- Start with all lamps off ---- */
    if (gpioPWM(LAMP1_PIN, 0) < 0 ||
        gpioPWM(LAMP2_PIN, 0) < 0 ||
        gpioPWM(LAMP3_PIN, 0) < 0) {
        fprintf(stderr, "Error: initial gpioPWM off failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed: %s\n",
                strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: sigaction(SIGTERM) failed: %s\n",
                strerror(errno));
    }

    /* ---- Main sequence: each lamp for 1/3 of the total duration ---- */
    int phase = 0;
    int lamp_index = 0;

    while (g_running && phase < duration) {
        int lamp_pin = pins[lamp_index];
        int target = (lamp_index == 0) ? 0 : 100;
        int current = (lamp_index == 0) ? 100 : 0;

        if (fade_lamp(lamp_pin, current, target, duration - phase) < 0) {
            fprintf(stderr, "Error: fade failed during lamp %d.\n",
                    lamp_index + 1);
            cleanup();
            return EXIT_FAILURE;
        }

        phase += FADE_STEPS * FADE_DELAY_US / 1000000; /* microseconds */
        lamp_index = (lamp_index + 1) % 3;
    }

    /* ---- Final off and cleanup ---- */
    if (gpioPWM(LAMP1_PIN, 0) < 0 ||
        gpioPWM(LAMP2_PIN, 0) < 0 ||
        gpioPWM(LAMP3_PIN, 0) < 0) {
        fprintf(stderr, "Warning: final gpioPWM off failed.\n");
    }

    cleanup();
    return EXIT_SUCCESS;
}

