/*
 * traffic_light.c — Traffic light simulation on Raspberry Pi 4 Model B
 *
 * Relays (5 V, active-low): GPIO17, GPIO22, GPIO23, GPIO24 (BCM)
 *   LOW  → relay energized (ON)
 *   HIGH → relay de-energized (OFF)
 *
 * Sequence (10 s, 2 s, 10 s, 3 s, repeat):
 *   Red   10 s
 *   Red+Yellow 2 s
 *   Green  10 s
 *   Yellow  3 s
 *
 * Build:  gcc -O2 -Wall -Wextra -o traffic_light traffic_light.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RED_PIN   17
#define YELLOW_PIN 22
#define GREEN_PIN  23
#define BLUE_PIN   24

#define RED_ON_S   10
