#define NUM_PINS 4

static const int pins[NUM_PINS] = { RED_PIN, YELLOW_PIN, GREEN_PIN, BLUE_PIN };

static volatile sig_atomic_t g_running = 1;

static void handle_signal(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int set_all(int state)
{
    for (int i = 0; i < NUM_PINS; i++) {
        if (gpioWrite(pins[i], state) != 0) {
            fprintf(stderr, "gpioWrite failed on pin %d\n", pins[i]);
            return -1;
        }
    }
    return 0;
}

static int set_all_off(void)
{
    return set_all(1); /* HIGH = OFF for active-low relays */
}

static int set_all_on(void)
{
    return set_all(0); /* LOW  = ON  for active-low relays */
}

