/*
 * MPR121 Capacitive Touch Relay Controller for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   MPR121 SDA -> GPIO2 (I2C bus 1 SDA)
 *   MPR121 SCL -> GPIO3 (I2C bus 1 SCL)
 *   MPR121 ADDR -> GND  (I2C address 0x5E)
 *   MPR121 VDD -> 3.3 V
 *   MPR121 GND -> GND
 *   Relay IN  -> GPIO17 (BCM)
 *   Relay VCC -> 5 V
 *   Relay GND -> GND
 *
 * Behavior:
 *   - Polls electrode 0 every 10 ms.
 *   - Toggles GPIO17 on every touch event to the relay.
 *   - Debounces touch events with a 100 ms delay.
 *   - Logs all I2C, GPIO, and configuration errors to touch_relay.log.
 *   - Handles SIGINT/SIGTERM for clean shutdown.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS        "/dev/i2c-1"
#define MPR121_ADDR    0x5E
#define RELAY_GPIO     17
#define DEBOUNCE_MS    100
#define POLL_MS        10
#define LOG_FILE       "touch_relay.log"

/* MPR121 register addresses */
#define MPR121_TOUCHSTATUS_L  0x00
#define MPR121_TOUCHSTATUS_H  0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_MHDR             0x2B
#define MPR121_NHDR             0x2C
#define MPR121_NCLR             0x2D
#define MPR121_FDLR             0x2E
#define MPR121_MHDF             0x2F
#define MPR121_NHDF             0x30
#define MPR121_NCLF             0x31
#define MPR121_FDLF             0x32
#define MPR121_NHDT             0x33
#define MPR121_NCLT             0x34
#define MPR121_FDLT             0x35
#define MPR121_E0TTH            0x41
#define MPR121_E0RTH            0x42
#define MPR121_DEBOUNCE         0x5B
#define MPR121_CONFIG1          0x5C
#define MPR121_CONFIG2          0x5D
#define MPR121_ECR              0x5E

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log = NULL;

static void log_error(const char *msg) {
    if (!g_log) return;
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(g_log, "[%04d-%02d-%02d %02d:%02d:%02d] %s (errno=%d: %s)\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, msg, errno, strerror(errno));
    fflush(g_log);
}

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        log_error("I2C write to MPR121 failed");
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        log_error("I2C write (reg select) failed");
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        log_error("I2C read from MPR121 failed");
        return -1;
    }
    return 0;
}

static int mpr121_init(int fd) {
    /* Soft reset */
    if (i2c_write_reg8(fd, MPR121_ECR, 0x00) < 0) return -1;
    usleep(1000);

    /* Stop mode */
    if (i2c_write_reg8(fd, MPR121_ECR, 0x00) < 0) return -1;

    /* Touch / release thresholds for electrode 0 */
    if (i2c_write_reg8(fd, MPR121_E0TTH, 0x0A) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_E0RTH, 0x0A) < 0) return -1;

    /* Debounce: 3 samples for touch, 3 for release */
    if (i2c_write_reg8(fd, MPR121_DEBOUNCE, 0x33) < 0) return -1;

    /* FFI = 6 samples, CDC = 16 µA */
    if (i2c_write_reg8(fd, MPR121_CONFIG1, 0x10) < 0) return -1;

    /* CDT = 0.5 µs, SFI = 4 samples, ESI = 4 µA */
    if (i2c_write_reg8(fd, MPR121_CONFIG2, 0x20) < 0) return -1;

    /* Enable 12 electrodes, baseline tracking */
    if (i2c_write_reg8(fd, MPR121_ECR, 0x8C) < 0) return -1;

    return 0;
}

static int read_touch_status(int fd, uint16_t *status) {
    uint8_t lo, hi;
    if (i2c_read_reg8(fd, MPR121_TOUCHSTATUS_L, &lo) < 0) return -1;
    if (i2c_read_reg8(fd, MPR121_TOUCHSTATUS_H, &hi) < 0) return -1;
    *status = (uint16_t)((hi << 8) | lo);
    return 0;
}

int main(void) {
    /* Open log file */
    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        log_error("pigpio initialization failed");
        fclose(g_log);
        return EXIT_FAILURE;
    }

    /* Configure relay GPIO */
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        log_error("Failed to set GPIO17 as output");
        gpioTerminate();
        fclose(g_log);
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        log_error("Failed to open I2C bus");
        gpioWrite(RELAY_GPIO, 0);
        gpioTerminate();
        fclose(g_log);
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        log_error("Failed to set I2C slave address");
        close(g_i2c_fd);
        gpioWrite(RELAY_GPIO, 0);
        gpioTerminate();
        fclose(g_log);
        return EXIT_FAILURE;
    }

    /* Initialize MPR121 */
    if (mpr121_init(g_i2c_fd) < 0) {
        log_error("MPR121 initialization failed");
        close(g_i2c_fd);
        gpioWrite(RELAY_GPIO, 0);
        gpioTerminate();
        fclose(g_log);
        return EXIT_FAILURE;
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MPR121 touch relay controller running. Press Ctrl+C to exit.\n");

    uint16_t prev_touch = 0;
    int relay_state = 0;

    while (g_running) {
        uint16_t touch_status = 0;
        if (read_touch_status(g_i2c_fd, &touch_status) < 0) {
            log_error("Failed to read touch status");
            usleep(POLL_MS * 1000);
            continue;
        }

        /* Electrode 0 touch event */
        if ((touch_status & 0x0001) && !(prev_touch & 0x0001)) {
            relay_state = !relay_state;
            if (gpioWrite(RELAY_GPIO, relay_state) < 0) {
                log_error("Failed to write GPIO17");
            } else {
                printf("Relay toggled to %s\n", relay_state ? "ON" : "OFF");
            }
            usleep(DEBOUNCE_MS * 1000);
        }

        prev_touch = touch_status;
        usleep(POLL_MS * 1000);
    }

    /* Cleanup */
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    if (g_log) fclose(g_log);

    printf("Shutdown complete.\n");
    return EXIT_SUCCESS;
}

