    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        return;
    }

    if (fprintf(log_file, "%s - Flame Detected\n", timestamp) < 0) {
        fprintf(stderr, "Error writing to log file\n");
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error flushing log file\n");
    }
}

static void activate_buzzer_and_led(void) {
