        }

        if (level == 0 && last_level == 1) {
            flame_count++;
        } else {
            flame_count = 0;
            last_level = level;
        }

        if (flame_count >= DEBOUNCE_COUNT) {
            log_flame_event();
            activate_buzzer_and_led();
            while (running) {
                int current_level = read_flame_sensor();
                if (current_level < 0) {
                    fprintf(stderr, "Error reading flame sensor, exiting.\n");
                    running = 0;
                    break;
                }
                if (current_level == 1) {
                    break;
                }
                gpioDelay(DEBOUNCE_DELAY_MS * 1000);
            }
            deactivate_buzzer_and_led();
            flame_count = 0;
        }

        gpioDelay(DEBOUNCE_DELAY_MS * 1000);
    }

    printf("Cleaning up...\n");
    if (log_file != NULL) {
        if (fclose(log_file) != 0) {
            perror("Error closing log file");
        }
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

