#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/time.h>
#include <the_driver_library.h>

#define SOLENOID_1_PIN 17
#define SOLENOID_2_PIN 27
#define DISPENSE_DURATION_MS 1000
#define DISPENSE_INTERVAL_MS 5000
#define LOG_FILE "dispense_log.txt"

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signum) {
    (void)signum;
    program_running = 0;
}

static int log_dispense_event(FILE *log_file, int solenoid1_pin, int solenoid2_pin, int duration_ms) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime() failed\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s, solenoid1_pin=%d, solenoid2_pin=%d, duration_ms=%d\n",
                timestamp, solenoid1_pin, solenoid2_pin, duration_ms) < 0) {
        fprintf(stderr, "Error: Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error: Failed to flush log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int activate_solenoid(int pin) {
    if (the_driver_library_call(pin, 1) != 0) {
        fprintf(stderr, "Error: Failed to activate solenoid on pin %d\n", pin);
        return -1;
    }
    return 0;
}

static int deactivate_solenoid(int pin) {
    if (the_driver_library_call(pin, 0) != 0) {
        fprintf(stderr, "Error: Failed to deactivate solenoid on pin %d\n", pin);
        return -1;
    }
    return 0;
}

static int dispense(int solenoid1_pin, int solenoid2_pin, int duration_ms) {
    if (activate_solenoid(solenoid1_pin) != 0) {
        return -1;
    }
    if (activate_solenoid(solenoid2_pin) != 0) {
        deactivate_solenoid(solenoid1_pin);
        return -1;
    }

    struct timeval start_time, end_time;
    gettimeofday(&start_time, NULL);

    while (program_running) {
        struct timeval current_time;
        gettimeofday(&current_time, NULL);

        long elapsed_ms = (current_time.tv_sec - start_time.tv_sec) * 1000L +
                          (current_time.tv_usec - start_time.tv_usec) / 1000L;

        if (elapsed_ms >= duration_ms) {
            break;
        }
        usleep(10000);
    }

    if (deactivate_solenoid(solenoid2_pin) != 0) {
        return -1;
    }
    if (deactivate_solenoid(solenoid1_pin) != 0) {
        return -1;
    }

    return 0;
}

int main(void) {
    FILE *log_file = NULL;
    int ret = 0;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

