#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define MOTOR_A_FORWARD 17
#define MOTOR_A_BACKWARD 18
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23
#define MOTOR_A_ENABLE 24
#define MOTOR_B_ENABLE 25

#define LOG_FILE "balance_log.txt"
#define OBSTACLE_THRESHOLD 20.0
#define PWM_RANGE 255
#define LOOP_DELAY_US 50000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%.2f,%.2f,%d,%d\n", timestamp, tilt_error, distance, motor_a_speed, motor_b_speed) < 0) {
        perror("fprintf to log file failed");
        return -1;
    }
    fflush(log_file);
    return 0;
}

static int set_motor_speed(int motor, int speed) {
    if (speed < 0 || speed > PWM_RANGE) {
        fprintf(stderr, "Invalid motor speed %d for motor %d\n", speed, motor);
        return -1;
    }
    if (motor == 1) {
        if (gpioWrite(MOTOR_A_ENABLE, 1) < 0) return -1;
        if (gpioPWM(MOTOR_A_FORWARD, speed) < 0) return -1;
        if (gpioPWM(MOTOR_A_BACKWARD, 0) < 0) return -1;
    } else if (motor == 2) {
        if (gpioWrite(MOTOR_B_ENABLE, 1) < 0) return -1;
        if (gpioPWM(MOTOR_B_FORWARD, speed) < 0) return -1;
        if (gpioPWM(MOTOR_B_BACKWARD, 0) < 0) return -1;
    } else {
        fprintf(stderr, "Invalid motor number %d\n", motor);
        return -1;
    }
    return 0;
}

static void stop_motors(void) {
    gpioPWM(MOTOR_A_FORWARD, 0);
    gpioPWM(MOTOR_A_BACKWARD, 0);
    gpioPWM(MOTOR_B_FORWARD, 0);
    gpioPWM(MOTOR_B_BACKWARD, 0);
    gpioWrite(MOTOR_A_ENABLE, 0);
    gpioWrite(MOTOR_B_ENABLE, 0);
}

static void cleanup(void) {
    stop_motors();
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction failed");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(MOTOR_A_FORWARD, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_B_FORWARD, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_A_ENABLE, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_B_ENABLE, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetPWMrange(MOTOR_A_FORWARD, PWM_RANGE) < 0 ||
        gpioSetPWMrange(MOTOR_A_BACKWARD, PWM_RANGE) < 0 ||
        gpioSetPWMrange(MOTOR_B_FORWARD, PWM_RANGE) < 0 ||
        gpioSetPWMrange(MOTOR_B_BACKWARD, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return 1;
    }

    if (gpioWrite(MOTOR_A_ENABLE, 0) < 0 ||
        gpioWrite(MOTOR_B_ENABLE, 0) < 0) {
        fprintf(stderr, "Failed to initialise enable pins LOW\n");
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        gpioTerminate();
        return 1;
    }

    float Kp = 1.0, Ki = 0.1, Kd = 0.01;
    float integral = 0.0, previous_error = 0.0;
    float tilt_error = 0.0, distance = 0.0;
    int motor_a_speed = 0, motor_b_speed = 0;

    while (running) {
        tilt_error = (float)(rand() % 200 - 100) / 10.0;
        distance = (float)(rand() % 398 + 2);

        if (distance < OBSTACLE_THRESHOLD) {
            motor_a_speed = -128;
            motor_b_speed = -128;
        } else {
            integral += tilt_error;
            float error = tilt_error;
            float derivative = error - previous_error;
            previous_error = error;
            float output = Kp * error + Ki * integral + Kd * derivative;
            motor_a_speed = (int)output;
            motor_b_speed = (int)output;
            if (motor_a_speed > PWM_RANGE) motor_a_speed = PWM_RANGE;
            if (motor_a_speed < -PWM_RANGE) motor_a_speed = -PWM_RANGE;
            if (motor_b_speed > PWM_RANGE) motor_b_speed = PWM_RANGE;
            if (motor_b_speed < -PWM_RANGE) motor_b_speed = -PWM_RANGE;
        }

        if (set_motor_speed(1, motor_a_speed) < 0 || set_motor_speed(2, motor_b_speed) < 0) {
            fprintf(stderr, "Motor control error\n");
            break;
        }

        if (log_data(tilt_error, distance, motor_a_speed, motor_b_speed) < 0) {
            fprintf(stderr, "Logging error\n");
            break;
        }

        gpioDelay(LOOP_DELAY_US);
    }

    cleanup();
    return 0;
}

