/*
 * TTP223 Capacitive Touch Sensor → Relay Toggle
 * Board:  Raspberry Pi 3 Model B+
 * Sensor: TTP223 (logic-HIGH touch output)
 *   VCC  → 5 V (pin 2)
 *   GND  → GND (pin 6)
 *   OUT  → GPIO4  (pin 7, BCM 4)
 * Relay: 5 V active-high relay
 *   VCC  → 5 V (pin 2)
 *   IN   → GPIO17 (pin 11, BCM 17)
 *   GND  → GND (pin 6)
 *
 * Build:  gcc -O2 -Wall -Wextra -o touch_relay touch_relay.c -lpigpio -lrt
 * Run:    sudo ./touch_relay
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN        17
#define DEBOUNCE_MS      50
#define POLL_DELAY_US    10000   /* 10 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (code %d).\n",
                gpioInitialise());
        return -1;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n",
                TOUCH_SENSOR_PIN);
        return -1;
    }

    /* TTP223 logic-HIGH output: internal pull-down so the line is
     * defined when the sensor is absent or disconnected. */
    if (gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: failed to set pull-down on GPIO%d.\n",
                TOUCH_SENSOR_PIN);
        return -1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n",
                RELAY_PIN);
        return -1;
    }

    /* Ensure the relay starts in the OFF state. */
    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize relay state on GPIO%d.\n",
                RELAY_PIN);
        return -1;
    }

    return 0;
}

static void cleanup(void)
{
    /* Best-effort cleanup: turn relay off and terminate pigpio. */
    (void)gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
}

int main(void)
{
    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Touch sensor monitoring started.\n");
    printf("  Touch sensor : GPIO%d (BCM)\n", TOUCH_SENSOR_PIN);
    printf("  Relay         : GPIO%d (BCM)\n", RELAY_PIN);
    printf("  Debounce      : %d ms\n", DEBOUNCE_MS);
    printf("  Press Ctrl-C to exit.\n");
    fflush(stdout);

    bool relay_state = false;
    bool first_touch = true;

    while (g_running) {
        int touch_level = gpioRead(TOUCH_SENSOR_PIN);

        if (touch_level < 0) {
            fprintf(stderr, "Warning: gpioRead failed on GPIO%d (code %d).\n",
                    TOUCH_SENSOR_PIN, touch_level);
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (touch_level == 1) {
            if (first_touch) {
                first_touch = false;
            } else {
                gpioDelay(DEBOUNCE_MS * 1000);
                int confirm = gpioRead(TOUCH_SENSOR_PIN);
                if (confirm < 0) {
                    fprintf(stderr, "Warning: gpioRead failed on GPIO%d (code %d).\n",
                            TOUCH_SENSOR_PIN, confirm);
                    continue;
                }
                if (confirm == 1) {
                    relay_state = !relay_state;
                    if (gpioWrite(RELAY_PIN, relay_state ? 1 : 0) != 0) {
                        fprintf(stderr, "Warning: gpioWrite failed on GPIO%d.\n",
                                RELAY_PIN);
                    } else {
                        printf("Touch detected → Relay %s\n",
                               relay_state ? "ACTIVATED" : "DEACTIVATED");
                        fflush(stdout);
                    }
                }
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

