/*
 * mood_light.c — ALSA audio RMS -> RGB LED mood light for Raspberry Pi 3 B+
 *
 * Build:  gcc -O2 -Wall -Wextra -o mood_light mood_light.c -lpigpio -lm
 * Run:    sudo ./mood_light [sensitivity]
 *
 * Hardware:
 *   - Red   LED on GPIO17 (BCM), green on GPIO18 (BCM), blue on GPIO27 (BCM)
 *   - Common-cathode LED: drive each GPIO high to turn on the corresponding
 *     color.  Use current-limiting resistors (e.g. 330 ohms) between the
 *     LED and the 3.3 V supply.
 *
 * ALSA available at compile time (alsa-lib >= 1.1.0).
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

/* ---- Configuration ---- */
#define RED_PIN    17
#define GREEN_PIN  18
#define BLUE_PIN   27

#define ALSA_DEVICE  "default"
#define SAMPLE_RATE 8000
#define PERIOD_SIZE 1024
#define SENSITIVITY_DEFAULT 1.0
#define UPDATE_MS     10

/* ---- Globals ---- */
static volatile sig_atomic_t g_running = 1;
static double g_sensitivity = SENSITIVITY_DEFAULT;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Color mapping ---- */
static void map_rms_to_color(double rms)
{
    double r = (rms / 100.0) * g_sensitivity;
    double g = (rms / 100.0) * g_sensitivity;
    double b = (rms / 100.0) * g_sensitivity;

    if (r > 1.0) r = 1.0;
    if (g > 1.0) g = 1.0;
    if (b > 1.0) b = 1.0;

    int ir = (int)(r * 255.0);
    int ig = (int)(g * 255.0);
    int ib = (int)(b * 255.0);

    if (ir < 0) ir = 0; if (ir > 255) ir = 255;
    if (ig < 0) ig = 0; if (ig > 255) ig = 255;
    if (ib < 0) ib = 0; if (ib > 255) ib = 255;

    gpioPWM(RED_PIN,   ir);
    gpioPWM(GREEN_PIN, ig);
    gpioPWM(BLUE_PIN,  ib);
}

/* ---- PWM via pigpio software-doubler (single channel) ---- */
static void pwm_set(int pin, int duty_percent)
{
    if (duty_percent < 0) duty_percent = 0;
    if (duty_percent > 100) duty_percent = 100;

    int on_us  = (gpioTick() + duty_percent * 1000000 / 100) % 1000000;
    int off_us = (1000000 - on_us) / 2;

    if (on_us > 0) {
        gpioWrite(pin, 1);
        gpioDelay(on_us);
    }
    if (off_us > 0) {
        gpioWrite(pin, 0);
        gpioDelay(off_us);
    }
}

/* ---- ALSA helpers (only available when ALSA is available) ---- */
#if defined(alsa_available)

static int alsa_init(void)
{
    int err = snd_pcm_open(&s_handle, ALSA_DEVICE, SND_PCM_STREAM_CAPTURE, 0);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_open failed: %s\n", snd_strerror(err));
        return -1;
    }

    err = snd_pcm_hw_params_alloca(s_handle, &s_hw_params);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_hw_params_alloca failed: %s\n", snd_strerror(err));
        snd_pcm_close(s_handle);
        s_handle = NULL;
        return -1;
    }

    err = snd_pcm_hw_params_set_access(s_handle, s_hw_params, SND_PCM_ACCESS_RW_INTERLEAVED);
    if (err < 0) {
        fprintf(stderr, "set_access failed: %s\n", snd_strerror(err));
        goto fail;
    }

    err = snd_pcm_hw_params_set_format(s_handle, s_hw_params, SND_PCM_FORMAT_S16_LE);
    if (err < 0) {
        fprintf(stderr, "set_format S16_LE failed: %s\n", snd_strerror(err));
        goto fail;
    }

    err = snd_pcm_hw_params_set_channels(s_handle, s_hw_params, 1);
    if (err < 0) {
        fprintf(stderr, "set_channels failed: %s\n", snd_strerror(err));
        goto fail;
    }

    err = snd_pcm_hw_params_set_rate_near(s_handle, s_hw_params, &SAMPLE_RATE, NULL);
    if (err < 0) {
        fprintf(stderr, "set_rate_near failed: %s\n", snd_strerror(err));
        goto fail;
    }

    err = snd_pcm_hw_params_set_period_size_near(s_handle, s_hw_params, &PERIOD_SIZE, NULL);
    if (err < 0) {
        fprintf(stderr, "set_period_size_near failed: %s\n", snd_strerror(err));
        goto fail;
    }

    err = snd_pcm_hw_params(s_handle, s_hw_params);
    if (err < 0) {
        fprintf(stderr, "hw_params apply failed: %s\n", snd_strerror(err));
        goto fail;
    }

    err = snd_pcm_prepare(s_handle);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_prepare failed: %s\n", snd_strerror(err));
        goto fail;
    }

    return 0;

fail:
    snd_pcm_close(s_handle);
    s_handle = NULL;
    return -1;
}

static int alsa_read_frame(short *buf, int frames)
{
    int err = snd_pcm_readi(s_handle, buf, frames);
    if (err < 0) {
        if (errno == EPIPE) {
            fprintf(stderr, "Buffer overrun, recovering...\n");
            snd_pcm_prepare(s_handle);
        } else if (errno == ESTRPIPE) {
            fprintf(stderr, "Stream suspended, resuming...\n");
            snd_pcm_resume(s_handle);
        } else {
            fprintf(stderr, "snd_pcm_readi failed: %s\n", snd_strerror(err));
        }
        return -1;
    }
    return 0;
}

static void alsa_close(void)
{
    if (s_handle) {
        snd_pcm_drain(s_handle);
        snd_pcm_close(s_handle);
        s_handle = NULL;
    }
}

#endif /* defined(alsa_available) */

int main(int argc, char *argv[])
{
    if (argc > 1) {
        g_sensitivity = atof(argv[1]);
        if (g_sensitivity <= 0.0) {
            fprintf(stderr, "Invalid sensitivity value: %s\n", argv[1]);
            return EXIT_FAILURE;
        }
    }

    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- GPIO setup ---- */
    gpioSetMode(RED_PIN,   PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN,  PI_OUTPUT);

    /* Start with LEDs off */
    gpioWrite(RED_PIN,   0);
    gpioWrite(GREEN_PIN, 0);
    gpioWrite(BLUE_PIN,  0);

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* ---- ALSA init (only available when ALSA is available) ---- */
#if defined(alsa_available)
    if (alsa_init() != 0) {
        fprintf(stderr, "ALSAMODIFY unavailable or ALSA not available.\n");
        fprintf(stderr, "Continuing with simulated audio input (sine wave).\n");
    }
#else
    fprintf(stderr, "ALSAMODIFY unavailable or ALSA not available.\n");
    fprintf(stderr, "Continuing with simulated audio input (sine wave).\n");
#endif

    /* ---- Main loop ---- */
    short *buffer = NULL;
    int frames = 0;
    int frame_count = 0;

    while (g_running) {
        if (buffer) {
            free(buffer);
            buffer = NULL;
        }

        buffer = (short *)malloc(PERIOD_SIZE * sizeof(short));
        if (!buffer) {
            fprintf(stderr, "malloc failed: %s\n", strerror(errno));
            break;
        }

        int err = 0;
        if (alsa_available()) {
            err = alsa_read_frame(buffer, PERIOD_SIZE);
        } else {
            /* Simulate: sine wave with amplitude proportional to RMS */
            for (int i = 0; i < PERIOD_SIZE; i++) {
                double rms = 0.0;
                for (int j = 0; j < frame_count; j++) {
                    double s = (double)buffer[j];
                    rms += s * s;
                }
                rms = rms / (double)frame_count;
                rms = sqrt(rms);
                buffer[i] = (short)(rms * 100.0);
            }
        }

        if (err < 0) {
            if (g_running) {
                fprintf(stderr, "Error reading audio, continuing...\n");
            }
            break;
        }

        frame_count = (frame_count + PERIOD_SIZE) / PERIOD_SIZE;
        if (frame_count >= 100) {
            double rms = 0.0;
            for (int i = 0; i < frame_count; i++) {
                rms += (double)buffer[i] * (double)buffer[i];
            }
            rms = rms / (double)frame_count;
            rms = sqrt(rms);
            map_rms_to_color(rms);
            frame_count = 0;
        }

        gpioDelay(UPDATE_MS * 1000);
    }

    /* ---- Cleanup ---- */
    if (buffer) {
        free(buffer);
    }

    /* Turn off LEDs */
    gpioWrite(RED_PIN,   0);
    gpioWrite(GREEN_PIN, 0);
    gpioWrite(BLUE_PIN,  0);

    if (alsa_available()) {
        alsa_close();
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

