#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS        1
#define TCS34725_ADDR  0x29
#define TCS34725_ENABLE 0x00
#define TCS34725_ATIME  0x01
#define TCS34725_CDATA  0x14
#define TCS34725_RDATA  0x16
#define TCS34725_GDATA  0x18
#define TCS34725_BDATA  0x1A

#define ENABLE_PON  0x01
#define ENABLE_AEN  0x02

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
