/*
 * Sunrise/sunset simulation for Raspberry Pi 3 Model B+
 * Four 5 V relay modules (active-low) on BCM GPIO17, 27, 22, 23.
 * Sunrise: 1 h  -> duty 0..100
 * Daytime: 6 h  -> duty 100
 * Sunset:  1 h  -> duty 100..0
 * Nighttime:14.4 h -> duty 100..0
 *
 * Build:  gcc -O2 -Wall -Wextra -o sunrise sunset.c -lpigpio -lrt
 * Run:    sudo ./sunrise
 */
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_RELAYS 4
#define SUNRISE_HR   1
#define DAYTIME_HR   6
#define SUNSET_HR    1
#define NIGHTTIME_HR 14.4
#define PWM_STEPS    100
#define PWM_STEP_US  10000   /* 10 ms per step */

static const int relay_pins[NUM_RELAYS] = {17, 27, 22, 23};

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void all_relays_off(void)
{
    for (int i = 0; i < NUM_RELAYS; i++)
        gpioWrite(relay_pins[i], 1);   /* active-low: 1 = off */
}

static void set_all_lamps(int duty)
{
    for (int i = 0; i < NUM_RELAYS; i++)
        gpioWrite(relay_pins[i], 0);   /* active-low: 0 = on */
    gpioDelay(duty * PWM_STEP_US);
    for (int i = 0; i < NUM_RELAYS; i++)
        gpioWrite(relay_pins[i], 1);   /* active-low: 1 = off */
    gpioDelay((PWM_STEPS - duty) * PWM_STEP_US);
}

static void sunrise_step(int duty)
{
    for (int i = 0; i < PWM_STEPS && g_running; i++)
        set_all_lamps(duty);
}

static void daytime_step(void)
{
    for (int i = 0; i < (int)(DAYTIME_HR * 3600.0 / 60.0) && g_running; i++)
        set_all_lamps(100);
}

static void sunset_step(int duty)
{
    for (int i = 0; i < PWM_STEPS && g_running; i++)
        set_all_lamps(duty);
}

static void nighttime_step(void)
{
    for (int i = 0; i < (int)(NIGHTTIME_HR * 3600.0 / 60.0) && g_running; i++)
        set_all_lamps(100);
}

static void sleep_hrs(double hrs)
{
    while (hrs > 0.0 && g_running) {
        double h = hrs > 1.0 ? 1.0 : hrs;
        sleep((unsigned)h);
        hrs -= h;
    }
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpioSetMode(relay_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO%d as output\n", relay_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        /* Relay is active-low: start with all off */
        gpioWrite(relay_pins[i], 1);
    }

    printf("Sunrise/sunset simulation started. Ctrl+C to exit.\n");

    while (g_running) {
        all_relays_off();

        sunrise_step(0);
        sleep_hrs(SUNRISE_HR);

        if (!g_running) break;

        daytime_step();
        sleep_hrs(DAYTIME_HR);

        if (!g_running) break;

        int duty = 100;
        sunset_step(duty);
        sleep_hrs(SUNSET_HR);

        if (!g_running) break;

        nighttime_step();
        sleep_hrs(NIGHTTIME_HR);
    }

    all_relays_off();
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

