        return -1;
    }

    return 0;
}

static int capture_video(void) {
    time_t rawtime;
    struct tm timeinfo;
    char filename[MAX_FILENAME_LEN];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(filename, sizeof(filename), "%Y%m%d_%H%M%S.h264", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    char filepath[MAX_FILENAME_LEN];
    snprintf(filepath, sizeof(filepath), "%s%s", VIDEO_DIR, filename);

    char command[256];
    snprintf(command, sizeof(command), "raspivid -o %s -t %d 2>>/home/pi/errors.log", filepath, CAPTURE_DURATION_SEC * 1000);

    int ret = system(command);
    if (ret == -1) {
        fprintf(stderr, "Failed to execute raspivid: %s\n", strerror(errno));
        return -1;
    }
    if (!WIFEXITED(ret) || WEXITSTATUS(ret) != 0) {
        fprintf(stderr, "Raspivid exited with status %d\n", WEXITSTATUS(ret));
        return -1;
    }

    printf("Video captured: %s\n", filepath);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    printf("Monitoring KY-033 on GPIO %d (active-low). Press Ctrl+C to exit.\n", GPIO_PIN);

    while (running) {
        int val = gpioRead(GPIO_PIN);
        if (val < 0) {
            fprintf(stderr, "gpioRead failed on pin %d: %s\n", GPIO_PIN, strerror(errno));
            break;
        }

        if (val == 0) {
            struct timespec ts = {0, DEBOUNCE_MS * 1000000L};
            nanosleep(&ts, NULL);

            if (log_motion_event() != 0) {
                fprintf(stderr, "Failed to log motion event\n");
            }

            if (capture_video() != 0) {
                fprintf(stderr, "Failed to capture video\n");
            }
        }

        usleep(10000);
    }

    printf("\nShutting down...\n");

    if (log_fp != NULL) {
        if (fclose(log_fp) != 0) {
            fprintf(stderr, "Failed to close log file: %s\n", strerror(errno));
        }
        log_fp = NULL;
    }

    gpioTerminate();
    printf("Cleanup complete.\n");
    return 0;
}

