/*
 * MPU-6050 Gyroscope Logger for Raspberry Pi 4 Model B
 * I2C bus 1, AD0 low (0x68), 100 Hz sampling, 10 ms interval.
 * Logs timestamp (Unix epoch ms), X, Y, Z deg/s to gyro_log.csv.
 * Handles I2C errors by re-initializing the sensor up to 3 times.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MPU6050_ADDR   0x68
#define PWR_MGMT_1     0x6B
#define GYRO_XOUT_H    0x43
#define GYRO_YOUT_H    0x45
#define GYRO_ZOUT_H    0x47
#define SAMPLE_PERIOD_US 10000  /* 10 ms = 100 Hz */
#define LOG_FILE       "gyro_log.csv"
#define MAX_REINIT_ATTEMPTS 3

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;
static int g_i2c_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read 16-bit from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *val = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int init_mpu6050(int fd) {
    /* Wake up: clear SLEEP bit in PWR_MGMT_1 */
    if (i2c_write_reg8(fd, PWR_MGMT_1, 0x00) < 0) {
        return -1;
    }
    /* Allow time for oscillator to stabilize */
    usleep(100000); /* 100 ms */
    return 0;
}

static int read_gyro_data(int fd, int16_t *gx, int16_t *gy, int16_t *gz) {
    if (i2c_read_reg16(fd, GYRO_XOUT_H, gx) < 0) return -1;
    if (i2c_read_reg16(fd, GYRO_YOUT_H, gy) < 0) return -1;
    if (i2c_read_reg16(fd, GYRO_ZOUT_H, gz) < 0) return -1;
    return 0;
}

static void cleanup(void) {
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to install signal handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", MPU6050_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (init_mpu6050(g_i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize MPU-6050 (sensor may be absent or bus error).\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(g_log_fp, 0, SEEK_END);
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "timestamp_ms,X_degps,Y_degps,Z_degps\n");
        fflush(g_log_fp);
    }

    int reinit_count = 0;
    while (g_running) {
        int16_t gx, gy, gz;
        if (read_gyro_data(g_i2c_fd, &gx, &gy, &gz) == 0) {
            struct timespec ts;
            clock_gettime(CLOCK_REALTIME, &ts);
            double timestamp = (double)ts.tv_sec + (double)ts.tv_nsec / 1.0e9;
            fprintf(g_log_fp, "%.3f,%d,%d,%d\n", timestamp, gx, gy, gz);
            fflush(g_log_fp);
            reinit_count = 0;
        } else {
            fprintf(stderr, "Gyro read failed, re-initializing sensor...\n");
            if (init_mpu6050(g_i2c_fd) < 0) {
                fprintf(stderr, "Re-initialization failed. Retrying in 1 second.\n");
                sleep(1);
                reinit_count++;
            } else {
                reinit_count = 0;
            }
        }

        if (reinit_count >= MAX_REINIT_ATTEMPTS) {
            fprintf(stderr, "Max re-initialization attempts reached. Exiting.\n");
            break;
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

