#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <pigpio.h>

#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22
#define MOISTURE_THRESHOLD 30
#define LOG_FILE "irrigation_log.txt"
#define SLEEP_INTERVAL 5

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO%d as output\n", pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioWrite(pins[i], 1) != 0) {
            fprintf(stderr, "Error: failed to initialise GPIO%d HIGH (relay OFF)\n", pins[i]);
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

static void log_data(int moisture, int relay1_state, int relay2_state,
                      int relay3_state, int relay4_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Moisture: %d, Relay1: %s, Relay2: %s, Relay3: %s, Relay4: %s\n",
            timestamp,
            moisture,
            relay1_state ? "ON" : "OFF",
            relay2_state ? "ON" : "OFF",
            relay3_state ? "ON" : "OFF",
            relay4_state ? "ON" : "OFF");
    fflush(log_file);
}

static void irrigate(int moisture) {
    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    int states[] = {0, 0, 0, 0};

    if (moisture < MOISTURE_THRESHOLD) {
        for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
            if (moisture >= (i + 1)) {
                if (gpioWrite(pins[i], 0) != 0) {
                    fprintf(stderr, "Error: failed to activate relay on GPIO%d\n", pins[i]);
                } else {
                    states[i] = 1;
                }
            } else {
                if (gpioWrite(pins[i], 1) != 0) {
                    fprintf(stderr, "Error: failed to deactivate relay on GPIO%d\n", pins[i]);
                } else {
                    states[i] = 0;
                }
            }
        }
    } else {
        for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
            if (gpioWrite(pins[i], 1) != 0) {
                fprintf(stderr, "Error: failed to deactivate relay on GPIO%d\n", pins[i]);
            } else {
                states[i] = 0;
            }
        }
    }

    log_data(moisture, states[0], states[1], states[2], states[3]);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (initialize_gpio() != 0) {
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    printf("Smart Greenhouse Irrigation System started. Press Ctrl+C to exit.\n");

    while (running) {
        int moisture = rand() % 100 + 1;
        irrigate(moisture);
        gpioDelay(SLEEP_INTERVAL * 1000000);
    }

    printf("\nShutting down...\n");
    for (size_t i = 0; i < sizeof(RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN) / sizeof(RELAY1_PIN); ++i) {
        gpioWrite(RELAY1_PIN, 1);
        gpioWrite(RELAY2_PIN, 1);
        gpioWrite(RELAY3_PIN, 1);
        gpioWrite(RELAY4_PIN, 1);
    }
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
    printf("Smart Greenhouse Irrigation System stopped.\n");
    return 0;
}

