/*
 * Free-Fall Detector for Raspberry Pi 3 Model B+
 * Sensor : Analog Devices ADXL345 accelerometer
 * Bus    : I2C bus 1 (GPIO2 = SDA, GPIO3 = SCL)
 * Address: 0x48 (ALT ADDRESS pin tied to GND)
 * Alarm  : GPIO27 (BCM numbering)
 *
 * Build  : gcc -O2 -Wall -Wextra -o freefall freefall.c -lm
 * Run    : sudo ./freefall
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <math.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* ---- ADXL345 constants (verified against ST datasheet rev 3.4) ---- */
#define ADXL345_ADDRESS        0x48
#define ADXL345_REG_DEVID      0x00
#define ADXL345_REG_POWER_CTL  0x2D
#define ADXL345_REG_DATA_FORMAT 0x31
#define ADXL345_REG_DATAX0     0x32
#define ADXL345_DEVID          0xE5

/* Data format: full-resolution, +/-200g range -> bits[1:0] = 0x0B */
#define ADXL345_DATA_FORMAT_200G 0x0B

/* Free-fall threshold: 0.2 g in g units */
#define FREEFALL_THRESHOLD_G  0.2f

/* Alarm GPIO pin (BCM numbering) */
#define ALARM_GPIO_PIN 27

/* I2C bus device on Raspberry Pi 3 Model B+ */
#define I2C_BUS_DEVICE "/dev/i2c-1"

/* Free-fall duration (seconds) */
#define FREEFALL_DURATION 0.5

/* Alarm hold duration (seconds) */
#define ALARM_HOLD_DURATION 5.0

/* Sampling interval (microseconds) */
#define SAMPLE_INTERVAL_US 100000

/* ---- Globals for cleanup ---- */
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;
static volatile sig_atomic_t g_running = 1;

/* ---- Signal handler ---- */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ---- I2C helpers ---- */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "I2C burst read from 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- ADXL345 initialization ---- */
static int adxl345_init(int fd)
{
    uint8_t devid = 0;

    if (i2c_read_reg8(fd, ADXL345_REG_DEVID, &devid) != 0)
        return -1;

    if (devid != ADXL345_DEVID) {
        fprintf(stderr, "ADXL345 not detected (DEVID=0x%02X, expected 0x%02X)\n",
                devid, ADXL345_DEVID);
        return -1;
    }

    /* Standby first so configuration changes take effect */
    if (i2c_write_reg8(fd, ADXL345_REG_POWER_CTL, 0x00) != 0)
        return -1;

    /* Data format: full-resolution, +/-200g */
    if (i2c_write_reg8(fd, ADXL345_REG_DATA_FORMAT, ADXL345_DATA_FORMAT_200G) != 0)
        return -1;

    /* Power-up, measurement mode */
    if (i2c_write_reg8(fd, ADXL345_REG_POWER_CTL, 0x08) != 0)
        return -1;

    return 0;
}

/* ---- Read 6 bytes of acceleration (little-endian) ---- */
static int adxl345_read_accel(int fd, float *x, float *y, float *z)
{
    uint8_t buf[6];
    if (i2c_read_burst(fd, ADXL345_REG_DATAX0, buf, sizeof(buf)) != 0)
        return -1;

    int16_t raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    int16_t raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    int16_t raw_z = (int16_t)((buf[5] << 8) | buf[4]);

    /* +/-200g full-resolution -> 4 mg/LSB = 0.004 g/LSB */
    *x = (float)raw_x * 0.004f;
    *y = (float)raw_y * 0.004f;
    *z = (float)raw_z * 0.004f;

    return 0;
}

/* ---- Free-fall detection ---- */
static bool detect_freefall(float x, float y, float z)
{
    return (fabsf(x) < FREEFALL_THRESHOLD_G &&
            fabsf(y) < FREEFALL_THRESHOLD_G &&
            fabsf(z) < FREEFALL_THRESHOLD_G);
}

/* ---- Log a confirmed free-fall event ---- */
static void log_freefall(float x, float y, float z)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    fprintf(g_log_fp, "%s,%.3f,%.3f,%.3f\n", ts, x, y, z);
    fflush(g_log_fp);
}

/* ---- Alarm control ---- */
static void trigger_alarm(void)
{
    if (g_i2c_fd >= 0) {
        if (i2c_write_reg8(g_i2c_fd, ADXL345_REG_POWER_CTL, 0x00) != 0)
            fprintf(stderr, "Warning: failed to put ADXL345 in standby during alarm.\n");
    }
    if (ALARM_GPIO_PIN >= 0) {
        if (g_i2c_fd >= 0) {
            if (i2c_write_reg8(g_i2c_fd, ADXL345_REG_POWER_CTL, 0x00) != 0)
                fprintf(stderr, "Warning: failed to put ADXL345 in standby during alarm.\n");
        }
        if (gpioWrite(ALARM_GPIO_PIN, 1) != 0)
            fprintf(stderr, "Warning: failed to set GPIO%d high.\n", ALARM_GPIO_PIN);
    }
}

static void deactivate_alarm(void)
{
    if (ALARM_GPIO_PIN >= 0) {
        if (gpioWrite(ALARM_GPIO_PIN, 0) != 0)
            fprintf(stderr, "Warning: failed to set GPIO%d low.\n", ALARM_GPIO_PIN);
    }
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    deactivate_alarm();

    if (g_i2c_fd >= 0) {
        if (i2c_write_reg8(g_i2c_fd, ADXL345_REG_POWER_CTL, 0x00) != 0)
            fprintf(stderr, "Warning: failed to put ADXL345 in standby during cleanup.\n");
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }

    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
}

/* ---- Main ---- */
int main(void)
{
    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS_DEVICE, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS_DEVICE, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                ADXL345_ADDRESS, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Initialize ADXL345 */
    if (adxl345_init(g_i2c_fd) != 0) {
        fprintf(stderr, "ADXL345 initialization failed.\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_fp = fopen("freefall.log", "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Cannot open freefall.log: %s\n", strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Configure alarm GPIO */
    if (gpioSetMode(ALARM_GPIO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Cannot set GPIO%d as output.\n", ALARM_GPIO_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    deactivate_alarm();

    /* Install signal handler */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Cannot install SIGINT handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Free-fall detection started. Press Ctrl+C to exit.\n");

    time_t freefall_start = 0;
    bool in_freefall = false;

    while (g_running) {
        float x, y, z;

        if (adxl345_read_accel(g_i2c_fd, &x, &y, &z) != 0) {
            fprintf(stderr, "Read error; continuing.\n");
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        if (detect_freefall(x, y, z)) {
            if (!in_freefall) {
                in_freefall = true;
                freefall_start = time(NULL);
                printf("Free-fall detected!\n");
            } else {
                if (difftime(time(NULL), freefall_start) >= FREEFALL_DURATION) {
                    printf("Free-fall confirmed!\n");
                    log_freefall(x, y, z);
                    trigger_alarm();

                    /* Hold alarm for the specified duration */
                    time_t hold_start = time(NULL);
                    while (g_running && (time(NULL) - hold_start < ALARM_HOLD_DURATION)) {
                        sleep(1);
                    }
                    deactivate_alarm();
                }
            }
        } else {
            in_freefall = false;
        }

        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

