/*
 * HC-SR04 ultrasonic distance measurement on Raspberry Pi Zero W.
 *
 * Wiring:
 *   HC-SR04 TRIG -> GPIO4  (BCM)
 *   HC-SR04 ECHO -> GPIO18 (BCM)
 *   5 V            -> 5 V pin
 *   GND           -> GND pin
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o hcsr04 hcsr04.c -lpigpio -lrt
 *   (pigpio must be installed via sudo pigpio run or similar.)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

#define TRIG_PIN        4
#define ECHO_PIN        18

#define TRIG_PULSE_US   10
#define TRIGGER_INTERVAL_MS 200
#define MAX_DISTANCE_CM 400.0
#define TIMEOUT_US      23200   /* ~4 m round-trip; beyond this we discard */
#define ECHO_TIMEOUT_US 100000  /* 100 ms with 5 µs ECHO pulse => 200 m */
#define LOG_FILE        "distance_log.txt"

static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;
static pthread_mutex_t g_mutex = PTHREAD_MUTEX_INITIALIZER;

/* ------------------------------------------------------------------ */
/* 32-bit tick counter (pigpio tick wraps every ~71.6 min)            */
/* ------------------------------------------------------------------ */
static volatile uint32_t g_tick = 0;

static void tick_inc(void)
{
    g_tick++;
}

static uint32_t tick_diff(uint32_t now, uint32_t prev)
{
    return (now >= prev) ? (now - prev) : (0xFFFFFFFFu - prev + now + 1u);
}

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */
static void trigger_pulse(void)
{
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(TRIG_PULSE_US);
    gpioWrite(TRIG_PIN, 0);
}

/*
 * Returns distance in cm, or -1.0 on timeout / error.
 * Uses a pigpio alert callback to capture the rising and falling edges.
 */
static double measure_distance(void)
{
    uint32_t t0, t_rise, t_fall, pulse_us;

    /* Reset echo state */
    t0 = gpioTick();
    t_rise = 0;
    t_fall = 0;
    pulse_us = 0;

    /* Rising edge: echo goes HIGH */
    if (gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL) != 0) {
        fprintf(stderr, "Error: failed to set alert on ECHO_PIN\n");
        return -1.0;
    }
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_alert, NULL) != 0) {
        fprintf(stderr, "Error: failed to set alert on ECHO_PIN\n");
        return -1.0;
    }

    trigger_pulse();

    /* Wait for rising edge (echo start) */
    while (g_running) {
        if (gpioTick() - t0 > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo rising edge\n");
            return -1.0;
        }
        gpioDelay(100);
    }

    t_rise = gpioTick();

    /* Wait for falling edge (echo end) */
    while (g_running) {
        if (gpioTick() - t_rise > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for echo falling edge\n");
            return -1.0;
        }
        gpioDelay(100);
    }

    t_fall = gpioTick();

    pulse_us = tick_diff(g_tick, t_rise);
    if (pulse_us == 0 || pulse_us > TIMEOUT_US) {
        fprintf(stderr, "Invalid pulse width: %u us\n", pulse_us);
        return -1.0;
    }

    double distance = (pulse_us / 1000000.0) * 34300.0 / 2.0;
    return distance;
}

static void echo_alert(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        t_rise = tick;
    } else if (level == 0) {
        t_fall = tick;
        pulse_us = tick_diff(g_tick, t_rise);
        if (pulse_us > 0 && pulse_us <= TIMEOUT_US) {
            double dist = (pulse_us / 1000000.0) * 34300.0 / 2.0;
            if (dist <= MAX_DISTANCE_CM) {
                pthread_mutex_lock(&g_mutex);
                if (g_log) {
                    struct timespec ts;
                    clock_gettime(CLOCK_REALTIME, &ts);
                    fprintf(g_log, "%ld.%09ld,%.2f\n",
                            (long)ts.tv_sec, (long)ts.tv_nsec, dist);
