{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TRIG_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set TRIG_PIN mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set ECHO_PIN mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts LOW */
    gpioWrite(TRIG_PIN, 0);
    gpioDelay(1000);

    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        perror("fopen(" LOG_FILE ")");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetAlertFuncEx(ECHO_PIN, echo_alert, NULL) != 0) {
        fprintf(stderr, "Failed to set alert callback on ECHO_PIN\n");
        fclose(g_log);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started. Press Ctrl+C to exit.\n");

    while (g_running) {
        double dist = measure_distance();
        if (dist > 0.0) {
            printf("Distance: %.2f cm\n", dist);
        }
        gpioDelay(TRIGGER_INTERVAL_MS * 1000);
    }

    /* Cleanup */
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);
    gpioWrite(TRIG_PIN, 0);
    fclose(g_log);
    gpioTerminate();
    pthread_mutex_destroy(&g_mutex);

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

