/*
 * LIS3DH Free-Fall / Impact Detector for Raspberry Pi 5
 *
 * Wiring:
 *   LIS3DH SDA -> GPIO2 (I2C bus 1 SDA)
 *   LIS3DH SCL -> GPIO3 (I2C bus 1 SCL)
 *   LIS3DH VDD -> 3.3 V
 *   LIS3DH GND -> GND
 *   Buzzer    -> GPIO17 (BCM)
 *
 * Build:
 *   gcc -O2 -Wall -o lis3dh_fall lis3dh_fall.c -lpigpio -lrt
 *   (pigpio must be installed; run as root or with appropriate permissions)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ---- LIS3DH constants (datasheet rev 1.3) ---- */
#define LIS3DH_ADDR        0x19   /* SA0 tied to GND on Adafruit breakout */
#define LIS3DH_CTRL_REG1   0x20
#define LIS3DH_CTRL_REG4   0x23
#define LIS3DH_OUT_X_L      0x28
#define LIS3DH_OUT_X_H      0x29
#define LIS3DH_OUT_Y_L      0x2A
#define LIS3DH_OUT_Y_H      0x2B
#define LIS3DH_OUT_Z_L      0x2C
#define LIS3DH_OUT_Z_H      0x2D

#define CTRL_REG1_VAL       0x77  /* 1000: enable XYZ axes, 50 Hz ODR */
#define CTRL_REG4_VAL       0x00  /* 0000: +/- 2 g full-scale, high-resolution off */

#define BUZZER_GPIO         17
#define I2C_BUS             1
#define I2C_RETRIES         3
#define SAMPLE_PERIOD_US    10000  /* 10 ms */

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read one 16-bit little-endian axis word from the LIS3DH.            */
/* Returns 0 on success, -1 on failure.                                 */
/* ------------------------------------------------------------------ */
static int read_axis(int handle, uint8_t reg, int16_t *out)
{
    for (int attempt = 0; attempt < I2C_RETRIES; attempt++) {
        int rc = i2cReadWordData(handle, reg);
        if (rc >= 0) {
            /* pigpio returns (high << 8) | low; swap to little-endian. */
            *out = (int16_t)((rc & 0xFF) << 8 | (rc >> 8) & 0xFF);
            return 0;
        }
        fprintf(stderr, "I2C read failed (reg 0x%02X, attempt %d/%d): %d\n",
                reg, attempt + 1, I2C_RETRIES, rc);
        gpioDelay(1000);  /* 1 ms back-off */
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Read all three axes and compute the magnitude of the acceleration.  */
/* Returns 0 on success, -1 on failure.                                 */
/* ------------------------------------------------------------------ */
static int read_acceleration(int handle, double *mag)
{
    int16_t x, y, z;

    if (read_axis(handle, LIS3DH_OUT_X_L, &x) != 0) return -1;
    if (read_axis(handle, LIS3DH_OUT_Y_L, &y) != 0) return -1;
    if (read_axis(handle, LIS3DH_OUT_Z_L, &z) != 0) return -1;

    /* +/- 2 g full-scale => 16384 LSB/g */
    double xg = (double)x / 16384.0;
    double yg = (double)y / 16384.0;
    double zg = (double)z / 16384.0;

    *mag = sqrt(xg * xg + yg * yg + zg * zg);
    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(BUZZER_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    double freefall_threshold = 0.2;
    double impact_threshold   = 1.5;

    if (argc > 1) freefall_threshold = atof(argv[1]);
    if (argc > 2) impact_threshold   = atof(argv[2]);

    if (freefall_threshold <= 0.0 || impact_threshold <= 0.0) {
        fprintf(stderr, "Error: thresholds must be positive.\n");
        return EXIT_FAILURE;
    }

    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- I2C open ---- */
    g_i2c_handle = i2cOpen(I2C_BUS, LIS3DH_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, LIS3DH_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Configure buzzer GPIO ---- */
    if (gpioSetMode(BUZZER_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output.\n", BUZZER_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(BUZZER_GPIO, 0);

    /* ---- Configure LIS3DH ---- */
    if (i2cWriteByteData(g_i2c_handle, LIS3DH_CTRL_REG1, CTRL_REG1_VAL) < 0) {
        fprintf(stderr, "Error writing CTRL_REG1.\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (i2cWriteByteData(g_i2c_handle, LIS3DH_CTRL_REG4, CTRL_REG4_VAL) < 0) {
        fprintf(stderr, "Error writing CTRL_REG4.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Signal handling ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("LIS3DH free-fall / impact detector running.\n");
    printf("  Free-fall threshold: %.2f g\n", freefall_threshold);
    printf("  Impact threshold:   %.2f g\n", impact_threshold);
    printf("  Buzzer on GPIO%d\n", BUZZER_GPIO);
    printf("Press Ctrl+C to exit.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        double mag = 0.0;

        if (read_acceleration(g_i2c_handle, &mag) != 0) {
            fprintf(stderr, "Sensor read failed; continuing.\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        printf("Acceleration magnitude: %.2f g\n", mag);

        if (mag < freefall_threshold) {
            printf("Free-fall detected!\n");
        } else if (mag > impact_threshold) {
            printf("Impact detected!\n");
            gpioWrite(BUZZER_GPIO, 1);
            gpioDelay(1000000);  /* 1 second */
            gpioWrite(BUZZER_GPIO, 0);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

