    if (i2cWriteByteData(g_i2c_handle, LIS3DH_CTRL_REG1, CTRL_REG1_VAL) < 0) {
        fprintf(stderr, "Error writing CTRL_REG1.\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (i2cWriteByteData(g_i2c_handle, LIS3DH_CTRL_REG4, CTRL_REG4_VAL) < 0) {
        fprintf(stderr, "Error writing CTRL_REG4.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Signal handling ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("LIS3DH free-fall / impact detector running.\n");
    printf("  Free-fall threshold: %.2f g\n", freefall_threshold);
    printf("  Impact threshold:   %.2f g\n", impact_threshold);
    printf("  Buzzer on GPIO%d\n", BUZZER_GPIO);
    printf("Press Ctrl+C to exit.\n");

    /* ---- Main loop ---- */
    while (g_running) {
        double mag = 0.0;

        if (read_acceleration(g_i2c_handle, &mag) != 0) {
            fprintf(stderr, "Sensor read failed; continuing.\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        printf("Acceleration magnitude: %.2f g\n", mag);

        if (mag < freefall_threshold) {
            printf("Free-fall detected!\n");
        } else if (mag > impact_threshold) {
            printf("Impact detected!\n");
            gpioWrite(BUZZER_GPIO, 1);
            gpioDelay(1000000);  /* 1 second */
            gpioWrite(BUZZER_GPIO, 0);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

