/*
 * Autonomous line-follower robot for Raspberry Pi 5.
 *
 * Hardware:
 *   - SunFounder 3-Way Tracking Sensor (IR reflectance, digital GPIO)
 *     Left  sensor -> GPIO4  (BCM)
 *     Center sensor -> GPIO17 (BCM)
 *     Right sensor -> GPIO27 (BCM)
 *   - Active-high alert LED/buzzer on GPIO22 (BCM)
 *
 * Behavior:
 *   Polls the three sensor pins every 10 ms.
 *   - Center sensor reads "no line" (logic 1) for five consecutive readings
 *     -> drive alert HIGH for 2 s, then stop.
 *   - Center sensor reads "line" (logic 0)  -> drive forward.
 *   - Left sensor reads "line"  -> turn left.
 *   - Right sensor reads "line"  -> turn right.
 *   - All sensors read "no line"  -> stop.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o line_follower line_follower.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <time.h>

#include <pigpio.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define LEFT_SENSOR_PIN  4
#define CENTER_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN  27
#define ALERT_PIN         22

/* ---- Circular buffer ---- */
#define BUFFER_SIZE 5

typedef struct {
    int left;
    int center;
    int right;
} sensor_data_t;

static sensor_data_t circular_buffer[BUFFER_SIZE];
static int buffer_index = 0;

static volatile sig_atomic_t program_running = 1;

/* ---- Forward declarations ---- */
static void signal_handler(int sig);
static void log_sensor_data(int left, int center, int right);
static void check_line_and_drive(int left, int center, int right);
static void trigger_alert(void);
static void cleanup(void);

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

/* ------------------------------------------------------------------ */
static void log_sensor_data(int left, int center, int right)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    printf("[%s] Left: %d, Center: %d, Right: %d\n",
           timestamp, left, center, right);
    fflush(stdout);

    circular_buffer[buffer_index].left  = left;
    circular_buffer[buffer_index].center = center;
    circular_buffer[buffer_index].right = right;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

/* ------------------------------------------------------------------ */
static void check_line_and_drive(int left, int center, int right)
{
    if (center == 1) {
        /* No line detected for five consecutive readings */
        if (buffer_index == 0 || circular_buffer[buffer_index - 1].center == 1) {
            trigger_alert();
            return;
