#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SI7210_ADDR 0x60
#define RELAY_GPIO 17
#define THRESHOLD_MG 5000.0
#define LOG_FILE "magnetic_events.txt"
#define POLL_TIMEOUT_MS 50
#define SAMPLE_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *msg) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[64];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s: %s\n", ts, msg);
    } else {
        fprintf(fp, "(unknown time): %s\n", msg);
    }
    fclose(fp);
}

static int read_magnetic_field(int handle, float *field_out) {
    char buf[3];
    int rc = i2cReadDevice(handle, buf, 3);
    if (rc != 3) {
        return -1;
    }
    int16_t raw = (int16_t)((buf[0] << 8) | (uint8_t)buf[1]);
    *field_out = (float)raw * 0.0001f;
    return 0;
}

static void control_relay(int gpio, int state) {
    if (gpioWrite(gpio, state) != 0) {
        log_event("Error: failed to write relay GPIO");
    }
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI7210_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting relay GPIO mode\n");
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error registering signal handler: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    log_event("Program started");

    while (running) {
        float field;
        if (read_magnetic_field(i2c_handle, &field) != 0) {
            log_event("Error: failed to read magnetic field");
            control_relay(RELAY_GPIO, 0);
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        char msg[128];
        snprintf(msg, sizeof(msg), "Magnetic field: %.2f mT", field);
        log_event(msg);

        if (field > THRESHOLD_MG) {
            control_relay(RELAY_GPIO, 1);
            log_event("Relay activated");
        } else {
            control_relay(RELAY_GPIO, 0);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    log_event("Program shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

