#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <gpiod.h>

#define PORT 5000
#define GPIO_PIN 18
#define BUFFER_SIZE 1024
#define LOG_FILE "relay_log.txt"

static volatile sig_atomic_t running = 1;
static int server_fd = -1;
static int client_fd = -1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *relay_line = NULL;

static void signal_handler(int signum) {
    (void)signum;
    running = 0;
}

static void log_event(const char *event) {
    if (!log_file) return;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    fflush(log_file);
}

static int gpio_init(void) {
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return -1;
    }
    relay_line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!relay_line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        chip = NULL;
        return -1;
    }
    if (gpiod_line_request_output(relay_line, "relay_control", 0) < 0) {
        perror("gpiod_line_request_output");
        gpiod_chip_close(chip);
        chip = NULL;
        relay_line = NULL;
        return -1;
    }
    return 0;
}

static int gpio_set(int value) {
    if (!relay_line) return -1;
    if (gpiod_line_set_value(relay_line, value) < 0) {
        perror("gpiod_line_set_value");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (relay_line) {
        gpiod_line_set_value(relay_line, 0);
        gpiod_line_release(relay_line);
        relay_line = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
    if (server_fd >= 0) {
        close(server_fd);
        server_fd = -1;
    }
    if (client_fd >= 0) {
        close(client_fd);
        client_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen");
        return EXIT_FAILURE;
    }

    if (gpio_init() < 0) {
        log_event("GPIO initialization failed");
        cleanup();
        return EXIT_FAILURE;
    }
    log_event("GPIO initialized successfully");

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        perror("socket");
        log_event("Socket creation failed");
        cleanup();
        return EXIT_FAILURE;
    }
    log_event("Socket created");

    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt");
        log_event("setsockopt failed");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sockaddr_in address;
    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind");
        log_event("Bind failed");
        cleanup();
        return EXIT_FAILURE;
    }
    log_event("Socket binded");

    if (listen(server_fd, 3) < 0) {
        perror("listen");
        log_event("Listen failed");
        cleanup();
        return EXIT_FAILURE;
    }
    log_event("Socket listening");

    while (running) {
        struct sockaddr_in client_addr;
        socklen_t addrlen = sizeof(client_addr);
        client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &addrlen);
        if (client_fd < 0) {
            if (errno == EINTR && !running) break;
            perror("accept");
            log_event("Accept failed");
            continue;
        }
        log_event("Connection accepted");

        char buffer[BUFFER_SIZE];
        ssize_t valread = read(client_fd, buffer, BUFFER_SIZE - 1);
        if (valread < 0) {
            perror("read");
            log_event("Read failed");
            close(client_fd);
            client_fd = -1;
            continue;
        }
        if (valread == 0) {
            log_event("Client disconnected");
            close(client_fd);
            client_fd = -1;
            continue;
        }
        buffer[valread] = '\0';
        log_event("Received command");

        char *command = strtok(buffer, " \t\r\n");
        while (command) {
            if (strcmp(command, "ON") == 0) {
                if (gpio_set(1) == 0) {
                    log_event("Relay ON");
                } else {
                    log_event("Failed to turn relay ON");
                }
            } else if (strcmp(command, "OFF") == 0) {
                if (gpio_set(0) == 0) {
                    log_event("Relay OFF");
                } else {
                    log_event("Failed to turn relay OFF");
                }
            } else {
                log_event("Invalid command");
            }
            command = strtok(NULL, " \t\r\n");
        }
        free(buffer);
    }

    log_event("Shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

