 * flow_monitor.c — Raspberry Pi Zero W
 *
 * Monitors two Sensirion SLF3S‑1300F liquid-flow sensors on I2C bus 1
 * (addresses 0x38 and 0x39) and controls a safety relay on GPIO 18
 * (BCM) based on flow-rate thresholds.  Logs flow data to flow_log.txt.
 *
 * Build:  gcc -Wall -Wextra -O2 -o flow_monitor flow_monitor.c -lpigpio -lrt
 * Run:    sudo ./flow_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */

#define I2C_BUS              1
#define SENSOR1_ADDR         0x38
#define SENSOR2_ADDR         0x39
#define RELAY_GPIO           18
#define FLOW_THRESHOLD_ML_MIN 5.0f
#define POLL_DELAY_US        100000          /* 100 ms */
#define LOG_FILE             "flow_log.txt"

/* SLF3S‑1300F start-measurement command (datasheet, two bytes) */
static const uint8_t CMD_START_MEAS[2] = { 0x36, 0x2C };

/* ------------------------------- Globals --------------------------------- */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle1 = -1;
static int g_i2c_handle2 = -1;

/* --------------------------- Forward declarations ------------------------ */

static void signal_handler(int sig);
static void cleanup(void);
static int  init_i2c_sensor(int addr);
static int  start_measurement(int handle);
static int  read_flow_rate(int handle, float *flow_rate);
static void log_flow_data(float flow1, float flow2);
static void control_relay(float flow1, float flow2);

/* ------------------------------- Signal ---------------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- I2C / sensor -------------------------------- */

static int init_i2c_sensor(int addr)
{
    int handle = i2cOpen(I2C_BUS, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, addr, strerror(errno));
        return -1;
    }

    /* Start a measurement by writing the two-byte start-measurement command. */
    if (start_measurement(handle) != 0) {
        fprintf(stderr, "[ERROR] start_measurement(0x%02X) failed\n", addr);
        i2cClose(handle);
        return -1;
    }

    return handle;
}

static int start_measurement(int handle)
{
    int rc = i2cWriteDevice(handle, (char *)CMD_START_MEAS, 2);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] start_measurement: i2cWriteDevice failed: %s\n",
                strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read three bytes from the sensor and compute the CRC-8.
 * Returns 0 on success, -1 on I/O error, -2 on CRC mismatch.
 */
static int read_flow_rate(int handle, float *flow_rate)
{
    char buf[3];
    int  bytes_read;
    uint8_t crc;
    int16_t raw;

    bytes_read = i2cReadDevice(handle, buf, 3);
    if (bytes_read != 3) {
        fprintf(stderr, "[WARN] i2cReadDevice(handle=%d) returned %d: %s\n",
                handle, bytes_read, bytes_read < 0 ? strerror(errno) : "short read");
        return -1;
    }

    /* Sensirion CRC-8: polynomial 0x31, initial value 0xFF, no final XOR. */
    crc = 0xFF;
    for (int i = 0; i < 2; i++) {
        crc ^= (uint8_t)buf[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }

    if (crc != (uint8_t)buf[2]) {
        fprintf(stderr, "[WARN] CRC mismatch (handle=%d): calc=0x%02X recv=0x%02X\n",
                handle, crc, (uint8_t)buf[2]);
        return -2;
    }

    raw = (int16_t)(((uint8_t)buf[0] << 8) | (uint8_t)buf[1]);
    *flow_rate = (float)raw / 60.0f;          /* ml/min */
    return 0;
}

/* ------------------------------- Logging --------------------------------- */

static void log_flow_data(float flow1, float flow2)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "[WARN] fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        return;
    }

    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "[WARN] clock_gettime failed: %s\n", strerror(errno));
        fclose(fp);
        return;
    }

    struct tm tm_buf;
    struct tm *tm = localtime_r(&ts.tv_sec, &tm_buf);
    if (!tm) {
        fprintf(stderr, "[WARN] localtime_r failed\n");
        fclose(fp);
        return;
    }

    char tbuf[32];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s.%03ld, Flow1: %.2f ml/min, Flow2: %.2f ml/min\n",
            tbuf, ts.tv_nsec / 1000000L, flow1, flow2);
    fflush(fp);
    fclose(fp);
}

/* ------------------------------- Relay ----------------------------------- */

static void control_relay(float flow1, float flow2)
{
    int target = (flow1 < FLOW_THRESHOLD_ML_MIN || flow2 < FLOW_THRESHOLD_ML_MIN)
                  ? 1
                  : 0;

    if (gpioWrite(RELAY_GPIO, target) != 0) {
        fprintf(stderr, "[WARN] gpioWrite(%d, %d) failed\n", RELAY_GPIO, target);
    }
}

/* --------------------------------- Main ---------------------------------- */

int main(void)
{
    /* --- pigpio init ---------------------------------------------------- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] gpioInitialise() failed\n");
        return EXIT_FAILURE;
    }

    /* --- relay GPIO setup ------------------------------------------------ */
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "[FATAL] gpioSetMode(%d, PI_OUTPUT) failed\n", RELAY_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);                 /* relay de-energized at start */

    /* --- signal handlers ------------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[FATAL] sigaction failed: %s\n", strerror(errno));
        gpioWrite(RELAY_GPIO, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- open I2C handles ------------------------------------------------ */
    g_i2c_handle1 = init_i2c_sensor(SENSOR1_ADDR);
    if (g_i2c_handle1 < 0) {
        gpioWrite(RELAY_GPIO, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_i2c_handle2 = init_i2c_sensor(SENSOR2_ADDR);
    if (g_i2c_handle2 < 0) {
        i2cClose(g_i2c_handle1);
        g_i2c_handle1 = -1;
        gpioWrite(RELAY_GPIO, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- start measurements --------------------------------------------- */
    if (start_measurement(g_i2c_handle1) != 0 || start_measurement(g_i2c_handle2) != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Flow monitoring started.  Sensor1=0x%02X  Sensor2=0x%02X  Relay=GPIO%d\n",
           SENSOR1_ADDR, SENSOR2_ADDR, RELAY_GPIO);
    printf("Threshold: %.1f ml/min.  Press Ctrl+C to exit.\n", FLOW_THRESHOLD_ML_MIN);

    /* --- main loop ------------------------------------------------------- */
    while (g_running) {
        float flow1 = 0.0f, flow2 = 0.0f;
        int   rc1 = read_flow_rate(g_i2c_handle1, &flow1);
        int   rc2 = read_flow_rate(g_i2c_handle2, &flow2);

        if (rc1 == 0 && rc2 == 0) {
            log_flow_data(flow1, flow2);
            control_relay(flow1, flow2);
        } else {
            fprintf(stderr, "[WARN] read failed (s1=%d, s2=%d); skipping cycle\n",
                    rc1, rc2);
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* --- graceful shutdown ---------------------------------------------- */
    printf("\nShutting down...\n");
    gpioWrite(RELAY_GPIO, 0);
    if (g_i2c_handle1 >= 0) i2cClose(g_i2c_handle1);
    if (g_i2c_handle2 >= 0) i2cClose(g_i2c_handle2);
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

