        syslog(LOG_ERR, "gpioTerminate() failed: %s", strerror(errno));
        return -1;
    }
    return 0;
}

static int motor_run(unsigned hold_us)
{
    if (motor_start() < 0) return -1;
    usleep(hold_us);
    return motor_stop() < 0 ? -1 : 0;
}

static int check_rain(void)
{
    int level = gpioRead(RAIN_SENSOR_PIN);
    if (level < 0) {
        syslog(LOG_ERR, "gpioRead(pin=%d) failed: %s", RAIN_SENSOR_PIN, strerror(errno));
        return 0;
    }
    return (level == 0) ? 1 : 0;
}

int main(void)
{
    openlog("rain_window", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction(SIGINT) failed: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction(SIGTERM) failed: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "gpioInitialise() failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode(RAIN_SENSOR_PIN) failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PUD_UP) < 0) {
        syslog(LOG_ERR, "gpioSetPullUpDown(RAIN_SENSOR_PIN) failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(MOTOR_ENA_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode(motor pins) failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (motor_stop() < 0) {
        syslog(LOG_ERR, "Initial motor_stop() failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Rain window controller started (GPIO17=rain, GPIO22-24=motor)");

    int dry_count = 0;
    int last_rain = check_rain();

    while (g_running) {
        int rain = check_rain();
        if (rain < 0) {
            /* Sensor read error — back off briefly and retry */
            usleep(POLL_INTERVAL_US);
            continue;
        }

        if (rain && !last_rain) {
            syslog(LOG_INFO, "Rain detected (dry -> wet)");
            if (motor_run(MOTOR_HOLD_US) < 0) {
                syslog(LOG_ERR, "Motor run failed");
            } else {
                syslog(LOG_INFO, "Window closed successfully");
            }
            dry_count = 0;
        } else if (!rain && last_rain) {
            dry_count++;
            if (dry_count >= DRY_CONSECUTIVE) {
                syslog(LOG_INFO, "Sensor dry for %d polls, resetting", dry_count);
                dry_count = 0;
            }
        } else {
            dry_count = 0;
        }

        last_rain = rain;
        usleep(POLL_INTERVAL_US);
    }

    syslog(LOG_INFO, "Shutting down");
    motor_stop_and_release();
    closelog();
    return EXIT_SUCCESS;
}

