/*
 * Door-lock servo controller for Raspberry Pi (pigpio)
 *
 * Wiring:
 *   Servo signal  -> GPIO 18 (physical pin 12, BCM 18)
 *   Lock button   -> GPIO 21 (physical pin 24, BCM 21) to GND
 *   Unlock button -> GPIO 22 (physical pin 25, BCM 22) to GND
 *   Internal pull-up resistors enabled on all three buttons.
 *
 * Behaviour:
 *   Polls the two buttons in a tight loop.  On lock button press
 *   (GPIO 21) a 2000 us pulse width is issued to lock the door.
 *   On unlock button press (GPIO 22) a 1000 us pulse width is issued
 *   to unlock the door.  A short delay after button release
 *   prevents a single press from being registered multiple times.
 *   SIGINT/SIGTERM causes a graceful shutdown: servo stopped,
 *   final API call(), and clean exit.
 *
 * Build:  gcc -O2 -Wall -Wextra -o door_lock door_lock.c -lpigpio -lrt
 * Run:    sudo ./door_lock
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <unistd.h>
#include <pigpio.h>

#define SERVO_PIN      18          /* BCM 18, physical pin 12 */
#define LOCK_BUTTON_PIN 21          /* BCM 21, physical pin 24 */
#define UNLOCK_BUTTON_PIN 22        /* BCM 22, physical pin 25 */

#define SERVO_LOCK_US  2000        /* 2000 us pulse width -> lock */
#define SERVO_UNLOCK_US 1000       /* 1000 us pulse width -> unlock */
#define SERVO_STOP_US   0          /* 0 us pulse width -> stop servo */

#define POLL_DELAY_US  10000       /* 10 ms poll interval */
#define DEBOUNCE_DELAY_US 50000    /* 50 ms debounce after release */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Issue a single pulse width to the servo pin and report success.     */
/* Returns 0 on success, -1 on pigpio error.                           */
/* ------------------------------------------------------------------ */
static int send_pulse(int pulse_us)
{
    if (gpioServo(SERVO_PIN, pulse_us) < 0) {
        fprintf(stderr, "Error: gpioServo failed for pulse %d us\n", pulse_us);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Issue a stop pulse (0 us) and report success.                       */
/* ------------------------------------------------------------------ */
static int stop_servo(void)
{
    if (send_pulse(SERVO_STOP_US) < 0)
        return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Issue a servo command and verify the API returned success.          */
/* Returns 0 on success, -1 on pigpio error or API failure.           */
/* ------------------------------------------------------------------ */
static int issue_servo_command(int pulse_us)
{
    if (send_pulse(pulse_us) < 0)
        return -1;

    if (gpioDelay(5000) < 0) {          /* 5 ms settle */
        fprintf(stderr, "Warning: gpioDelay failed during pulse\n");
    }

    if (gpioServo(SERVO_PIN, 0) < 0) {  /* stop PWM */
        fprintf(stderr, "Warning: gpioServo stop failed after pulse\n");
    }

    if (gpioDelay(5000) < 0) {
        fprintf(stderr, "Warning: gpioDelay failed during stop\n");
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise pigpio and configure all pins.                           */
/* Returns 0 on success, -1 on failure.                               */
/* ------------------------------------------------------------------ */
static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(SERVO_PIN) failed\n");
        return -1;
    }

    if (gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(LOCK_BUTTON_PIN) failed\n");
        return -1;
    }

    if (gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(UNLOCK_BUTTON_PIN) failed\n");
        return -1;
    }

    if (gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(LOCK_BUTTON_PIN) failed\n");
        return -1;
    }

    if (gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(UNLOCK_BUTTON_PIN) failed\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a button with internal pull-up; returns 1 if pressed, 0 if not. */
/* ------------------------------------------------------------------ */
static int read_button(int pin)
{
    return (gpioRead(pin) == 0) ? 1 : 0;
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() < 0) {
        return EXIT_FAILURE;
    }

    printf("Door-lock servo controller started.\n");
    printf("  Servo signal: GPIO %d (BCM)\n", SERVO_PIN);
    printf("  Lock button:  GPIO %d (BCM)\n", LOCK_BUTTON_PIN);
    printf("  Unlock button: GPIO %d (BCM)\n", UNLOCK_BUTTON_PIN);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        int lock_pressed  = read_button(LOCK_BUTTON_PIN);
        int unlock_pressed = read_button(UNLOCK_BUTTON_PIN);

        if (lock_pressed) {
            printf("Lock button pressed -> issuing 2000 us pulse\n");
            if (issue_servo_command(SERVO_LOCK_US) < 0) {
                fprintf(stderr, "Error: failed to issue lock pulse\n");
                break;
            }
        }

        if (unlock_pressed) {
            printf("Unlock button pressed -> issuing 1000 us pulse\n");
            if (issue_servo_command(SERVO_UNLOCK_US) < 0) {
                fprintf(stderr, "Error: failed to issue unlock pulse\n");
                break;
            }
        }

        /* Debounce: wait for release of both buttons before next poll */
        while (g_running) {
            if (!lock_pressed && !unlock_pressed)
                break;
            gpioDelay(1000);  /* 1 ms */
        }

        /* Small delay to avoid busy-waiting */
        gpioDelay(DEBOUNCE_DELAY_US);
    }

    /* Graceful shutdown */
    printf("\nShutting down...\n");
    stop_servo();
    if (gpioServo(SERVO_PIN, 0) < 0) {
        fprintf(stderr, "Warning: failed to stop servo PWM during shutdown\n");
    }
    gpioDelay(5000);  /* 5 ms settle */

    if (gpioTerminate() < 0) {
        fprintf(stderr, "Warning: gpioTerminate failed\n");
    }

    printf("Shutdown complete.\n");
    return EXIT_SUCCESS;
}

