#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

#define PIR_GPIO 4
#define FLOODLIGHT_GPIO 17
#define LOG_FILE "security_log.txt"
#define POLL_INTERVAL_US 100000
#define FLOODLIGHT_DURATION_SEC 60

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int log_event(const char *event_type, const char *message)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Error getting time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (!localtime_r(&t, &tm_info)) {
        fprintf(stderr, "Error converting time to local time\n");
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s - %s: %s\n", timestamp, event_type, message) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static int floodlight_on(void)
{
    if (gpioWrite(FLOODLIGHT_GPIO, 1) < 0) {
        fprintf(stderr, "Error turning floodlight ON: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int floodlight_off(void)
{
    if (gpioWrite(FLOODLIGHT_GPIO, 0) < 0) {
        fprintf(stderr, "Error turning floodlight OFF: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int floodlight_set_duration(int duration_sec)
{
    if (gpioSetMode(FLOODLIGHT_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting floodlight GPIO mode: %s\n", strerror(errno));
        return -1;
    }
    if (gpioWrite(FLOODLIGHT_GPIO, 0) < 0) {
        fprintf(stderr, "Error initializing floodlight to OFF: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PIR_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "Error setting PIR GPIO mode: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLOODLIGHT_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting floodlight GPIO mode: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (floodlight_set_duration(FLOODLIGHT_DURATION_SEC) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Error setting PIR pull-down: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error installing SIGINT handler: %s\n", strerror(errno));
        floodlight_off();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error installing SIGTERM handler: %s\n", strerror(errno));
        floodlight_off();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Motion detection system started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int pir_value = gpioRead(PIR_GPIO);
        if (pir_value < 0) {
            fprintf(stderr, "Error reading PIR sensor: %s\n", strerror(errno));
            break;
        }

        if (pir_value == 1) {
            printf("Motion detected!\n");

            if (log_event("Motion Detected", "Motion detected by floodlight") < 0) {
                break;
            }

            if (floodlight_on() < 0) {
                break;
            }

            time_t start_time = time(NULL);
            if (start_time == (time_t)-1) {
                fprintf(stderr, "Error getting start time: %s\n", strerror(errno));
                floodlight_off();
                break;
            }

            while (g_running) {
                time_t current_time = time(NULL);
                if (current_time == (time_t)-1) {
                    fprintf(stderr, "Error getting current time: %s\n", strerror(errno));
                    break;
                }

                if (difftime(current_time, start_time) >= FLOODLIGHT_DURATION_SEC) {
                    break;
                }

                gpioDelay(POLL_INTERVAL_US);
            }

            if (floodlight_off() < 0) {
                break;
            }

            time_t end_time = time(NULL);
            if (end_time == (time_t)-1) {
                fprintf(stderr, "Error getting end time: %s\n", strerror(errno));
                break;
            }

            double duration = difftime(end_time, start_time);
            char duration_str[32];
            if (duration >= 60.0) {
                snprintf(duration_str, sizeof(duration_str), "%.2f", duration);
            } else {
                snprintf(duration_str, sizeof(duration_str), "%.2f", duration);
            }

            if (log_event("Floodlight Deactivated", duration_str) < 0) {
                break;
            }

            printf("Floodlight deactivated after %.2f seconds.\n", duration);
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    floodlight_off();
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

