/*
 * MPR121 Capacitive Touch Relay Toggle (Raspberry Pi 5)
 *
 * Wiring:
 *   MPR121 SDA -> GPIO2 (I2C bus 1 SDA)
 *   MPR121 SCL -> GPIO3 (I2C bus 1 SCL)
 *   MPR121 ADDR -> GND  (I2C address 0x5D)
 *   Relay IN   -> GPIO17 (BCM)
 *
 * Behavior:
 *   On a fresh rising-edge touch of electrode 0, the relay toggles.
 *   A 200 ms debounce window is applied to electrode 0.
 *   The relay is left in its known state on startup and shutdown.
 *   Robust error handling and clean resource release on every exit path.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o mpr121_relay mpr121_relay.c -lpigpio -lrt
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Configuration ---- */
#define I2C_BUS              1
#define MPR121_ADDR          0x5D
#define RELAY_GPIO           17
#define DEBOUNCE_MS          200
#define POLL_DELAY_US        10000   /* 10 ms */
#define I2C_READ_RETRY_COUNT 3

/* ---- MPR121 Register Map ---- */
#define MPR121_TOUCHSTATUS_L  0x00
#define MPR121_TOUCHSTATUS_H  0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_SOFTRESET       0x80
#define MPR121_MHDR            0x2B
#define MPR121_NHDR            0x2C
#define MPR121_NCL            0x2D
#define MPR121_FDL            0x2E
#define MPR121_NHD            0x2F
#define MPR121_NCL_CFG        0x30
#define MPR121_FDL_CFG        0x31
#define MPR121_E0TTH          0x41
#define MPR121_E0RTH          0x42
#define MPR121_DEBOUNCE       0x5B
#define MPR121_CONFIG1        0x5C
#define MPR121_CONFIG2        0x5D
#define MPR121_AUTOCONFIG      0x7B
#define MPR121_ECR            0x5E

/* ---- Globals ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ---- Signal Handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Helpers ---- */
static void msleep(unsigned ms)
{
    while (ms > 0 && g_running) {
        unsigned chunk = (ms > 1000) ? 1000 : ms;
        gpioDelay(chunk * 1000);
        ms -= chunk;
    }
}

/* ---- I2C Helpers ---- */
static int i2c_write_reg8(int handle, uint8_t reg, uint8_t val)
{
    char buf[2] = { (char)reg, (char)val };
    for (int attempt = 0; attempt < I2C_READ_RETRY_COUNT; attempt++) {
        if (i2cWriteDevice(handle, buf, 2) == 0)
            return 0;
        gpioDelay(1000); /* 1 ms backoff */
    }
    return -1;
}

static int i2c_read_reg8(int handle, uint8_t reg, uint8_t *val)
{
    char reg_buf[1] = { (char)reg };
    for (int attempt = 0; attempt < I2C_READ_RETRY_COUNT; attempt++) {
        if (i2cWriteDevice(handle, reg_buf, 1) != 0) {
            gpioDelay(1000);
            continue;
        }
        char data[1];
        if (i2cReadDevice(handle, data, 1) != 1) {
            gpioDelay(1000);
            continue;
        }
        *val = (uint8_t)data[0];
        return 0;
    }
    return -1;
}

/* ---- MPR121 Initialization ---- */
static int mpr121_init(int handle)
{
    /* Soft reset */
    if (i2c_write_reg8(handle, MPR121_SOFTRESET, 0x63) != 0) {
        fprintf(stderr, "Error: MPR121 soft reset failed.\n");
        return -1;
    }
    msleep(100); /* 100 ms settle after reset */

    /* Baseline filtering (MPR121 datasheet defaults) */
    if (i2c_write_reg8(handle, MPR121_MHDR, 0x01) != 0) return -1;
    if (i2c_write_reg8(handle, MPR121_NHDR, 0x01) != 0) return -1;
    if (i2c_write_reg8(handle, MPR121_NCL, 0x00) != 0) return -1;
    if (i2c_write_reg8(handle, MPR121_FDL, 0x00) != 0) return -1;
    if (i2c_write_reg8(handle, MPR121_NHD, 0x00) != 0) return -1;
    if (i2c_write_reg8(handle, MPR121_NCL_CFG, 0x01) != 0) return -1;
    if (i2c_write_reg8(handle, MPR121_FDL_CFG, 0x01) != 0) return -1;

    /* Debounce: 3 samples for both rising and falling edges */
    if (i2c_write_reg8(handle, MPR121_DEBOUNCE, 0x33) != 0) return -1;

    /* FFI = 6 samples, CDC = 16 µA */
    if (i2c_write_reg8(handle, MPR121_CONFIG1, 0x10) != 0) return -1;

    /* CDT = 0.5 µs, SFI = 4 samples, ESI = 4 µA */
    if (i2c_write_reg8(handle, MPR121_CONFIG2, 0x20) != 0) return -1;

    /* Auto-config: range = 16 uA, baseline tracking = 16 uA */
    if (i2c_write_reg8(handle, MPR121_AUTOCONFIG, 0x0B) != 0) return -1;

    /* Enable 12 electrodes, baseline tracking, no charge current */
    if (i2c_write_reg8(handle, MPR121_ECR, 0x8C) != 0) return -1;

    return 0;
}

/* ---- Relay Control ---- */
static void relay_set(bool on)
{
    if (gpioWrite(RELAY_GPIO, on ? 1 : 0) != 0) {
        fprintf(stderr, "Warning: gpioWrite failed on GPIO %d.\n", RELAY_GPIO);
    }
}

/* ---- Main ---- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure relay GPIO */
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d.\n", RELAY_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    relay_set(false); /* Ensure known OFF state */

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d). Sensor may be absent or bus error.\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize MPR121 */
    if (mpr121_init(g_i2c_handle) != 0) {
        fprintf(stderr, "Error: MPR121 initialization failed.\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MPR121 ready. Touch electrode 0 to toggle relay. Ctrl+C to exit.\n");

    bool relay_state = false;
    bool last_touch = false;

    while (g_running) {
        uint8_t lo, hi;
        if (i2c_read_reg8(g_i2c_handle, MPR121_TOUCHSTATUS_L, &lo) != 0 ||
            i2c_read_reg8(g_i2c_handle, MPR121_TOUCHSTATUS_H, &hi) != 0) {
            fprintf(stderr, "Warning: I2C read error, retrying...\n");
            msleep(100);
            continue;
        }

        uint16_t touch_status = (uint16_t)((hi << 8) | lo);
        bool touched = (touch_status & 0x0001) != 0;

        /* Fresh rising-edge detection with debounce */
        if (touched && !last_touch) {
            msleep(DEBOUNCE_MS);
            uint8_t lo2, hi2;
            if (i2c_read_reg8(g_i2c_handle, MPR121_TOUCHSTATUS_L, &lo2) == 0 &&
                i2c_read_reg8(g_i2c_handle, MPR121_TOUCHSTATUS_H, &hi2) == 0) {
                uint16_t touch_status2 = (uint16_t)((hi2 << 8) | lo2);
                if ((touch_status2 & 0x0001) == 0) {
                    relay_set(!relay_state);
                    relay_state = !relay_state;
                    printf("Relay toggled to %s\n", relay_state ? "ON" : "OFF");
                }
            }
        }
        last_touch = touched;
        gpioDelay(POLL_DELAY_US);
    }

    /* Cleanup */
    relay_set(false);
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

