static int server_fd = -1;
static FILE *log_file = NULL;

static void log_message(const char *fmt, ...) {
    va_list args;
    va_start(args, fmt);
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    if (log_file) {
        fprintf(log_file, "%s ", ts);
        vfprintf(log_file, fmt, args);
        fputc('\n', log_file);
        fflush(log_file);
    }
    vsyslog(LOG_USER, fmt, args);
    va_end(args);
}

static int set_servo_angle(int angle) {
    if (angle < SERVO_ANGLE_MIN || angle > SERVO_ANGLE_MAX) {
        log_message("Error: Invalid servo angle %d (must be %d-%d)", angle, SERVO_ANGLE_MIN, SERVO_ANGLE_MAX);
        return -1;
    }
    int pulse_width = SERVO_MIN_PULSE + (angle * (SERVO_MAX_PULSE - SERVO_MIN_PULSE) / (SERVO_ANGLE_MAX - SERVO_ANGLE_MIN));
    if (gpioServo(SERVO_PIN, pulse_width) != 0) {
        log_message("Error: gpioServo failed for pin %d", SERVO_PIN);
        return -1;
    }
    return 0;
}

static int read_pir_sensor(void) {
    int value = gpioRead(PIR_PIN);
    if (value < 0) {
        log_message("Error: gpioRead failed for pin %d", PIR_PIN);
        return -1;
    }
    return value;
}

static void handle_client(int client_fd) {
    char buffer[BUFFER_SIZE];
    ssize_t bytes_received = recv(client_fd, buffer, BUFFER_SIZE - 1, 0);
    if (bytes_received < 0) {
        log_message("Error: recv failed: %s", strerror(errno));
        close(client_fd);
        return;
    }
    if (bytes_received == 0) {
        log_message("Client disconnected");
        close(client_fd);
        return;
    }
    buffer[bytes_received] = '\0';
    log_message("Received: %s", buffer);

    if (strncmp(buffer, "the library's API call ", 20) == 0) {
        int angle = atoi(buffer + 20);
        if (angle >= SERVO_ANGLE_MIN && angle <= SERVO_ANGLE_MAX) {
            if (set_servo_angle(angle) == 0) {
                log_message("Servo set to angle %d", angle);
            } else {
                log_message("Error: Failed to set servo angle %d", angle);
            }
        } else {
            log_message("Error: Invalid servo angle %d (must be %d-%d)", angle, SERVO_ANGLE_MIN, SERVO_ANGLE_MAX);
        }
    } else if (strncmp(buffer, "PIR", 3) == 0) {
        int pir_value = read_pir_sensor();
        if (pir_value < 0) {
            log_message("Error: Failed to read PIR sensor");
        } else {
            char response[64];
            snprintf(response, sizeof(response), "PIR:%d", pir_value);
            send(client_fd, response, strlen(response), 0);
            log_message("PIR: %s", response);
        }
    } else {
        log_message("Unknown command: %s", buffer);
    }
    close(client_fd);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (server_fd != -1) {
        close(server_fd);
        server_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
    closelog();
}

int main(void) {
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        log_message("Error: pigpio initialisation failed");
        fclose(log_file);
        log_file = NULL;
        return EXIT_FAILURE;
    }

    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetMode(PIR_PIN, PI_INPUT);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        log_message("Error: socket creation failed: %s", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        log_message("Warning: setsockopt failed: %s", strerror(errno));
    }

    struct sockaddr_in address;
    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        log_message("Error: bind failed: %s", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (listen(server_fd, 3) < 0) {
        log_message("Error: listen failed: %s", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    log_message("Server listening on port %d", PORT);

    while (running) {
        struct sockaddr_in client_addr;
        socklen_t addrlen = sizeof(client_addr);
        int client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &addrlen);
        if (client_fd < 0) {
            if (errno == EINTR && !running) {
                break;
            }
            log_message("Error: accept failed: %s", strerror(errno));
            continue;
        }
        char ip_str[INET_ADDRSTRLEN];
        inet_ntop(AF_INET, &client_addr.sin_addr, ip_str, sizeof(ip_str));
        char client_port_str[16];
        snprintf(client_port_str, sizeof(client_port_str), ":%d", ntohs(client_addr.sin_port));
        char client_addr_str[128];
        snprintf(client_addr_str, sizeof(client_addr_str), "%s:%s", ip_str, client_port_str);
        log_message("Connection accepted from %s", client_addr_str);
        handle_client(client_fd);
    }

    log_message("Shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

