/*
 * Grow-light controller for Raspberry Pi 3 Model B+
 * Sensor : BH1750FVI (I2C address 0x10, 1-wire, 1-shot mode)
 * Relay  : GPIO23 (BCM) — active-high relay module
 * Log    : grow_log.txt (timestamp, lux, relay_state)
 *
 * Build  : gcc -O2 -Wall -Wextra -o grow_light grow_light.c -lpigpio -lrt
 * Run    : sudo ./grow_light
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define BH1750_ADDR        0x10
#define BH1750_CONT_HRES   0x10  /* 1-shot, high-resolution, ~120 ms */
#define BH1750_MEAS_MS     120   /* wait after trigger */
#define BH1750_CONV_MS     180   /* worst-case conversion time */
#define GROW_LIGHT_PIN     23
#define LUX_THRESHOLD      150
#define SAMPLE_INTERVAL_S  2
#define LOG_FILE           "grow_log.txt"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int bh1750_read_lux(int handle, float *lux_out)
{
    uint8_t cmd = BH1750_CONT_HRES;
    uint8_t buf[2];

    if (i2cWriteDevice(handle, (char *)&cmd, 1) != 0) {
        fprintf(stderr, "[BH1750] i2cWriteDevice (trigger) failed: %s\n",
                strerror(errno));
        return -1;
    }

    /* Wait for conversion to complete (max ~180 ms) */
    gpioDelay(BH1750_CONV_MS * 1000);

    if (i2cReadDevice(handle, (char *)buf, 2) != 2) {
        fprintf(stderr, "[BH1750] i2cReadDevice failed: %s\n",
                strerror(errno));
        return -1;
    }

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, float lux, int relay_state)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[LOG] localtime_r failed: %s\n", strerror(errno));
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s, %.2f, %d\n", ts, lux, relay_state) < 0) {
        fprintf(stderr, "[LOG] fprintf failed: %s\n", strerror(errno));
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "[LOG] fflush failed: %s\n", strerror(errno));
    }
}

/* ------------------------------------------------------------------ */
/* Relay control                                                       */
/* ------------------------------------------------------------------ */
static int relay_set(int state)
{
    if (gpioWrite(GROW_LIGHT_PIN, state) != 0) {
        fprintf(stderr, "[RELAY] gpioWrite(%d) failed\n", state);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    /* Ensure relay is off before terminating pigpio */
    gpioWrite(GROW_LIGHT_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- relay pin setup --- */
    if (gpioSetMode(GROW_LIGHT_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, OUTPUT) failed\n", GROW_LIGHT_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (relay_set(0) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- I2C open --- */
    g_i2c_handle = i2cOpen(1, BH1750_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(1, 0x%02X) failed: %s\n",
                BH1750_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- log file --- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- signals --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Grow-light controller started.  BH1750 @ 0x%02X, relay GPIO%d, threshold %d lux.\n",
           BH1750_ADDR, GROW_LIGHT_PIN, LUX_THRESHOLD);
    printf("Press Ctrl+C to exit.\n");

    /* --- main loop --- */
    while (g_running) {
        float lux = 0.0f;

        if (bh1750_read_lux(g_i2c_handle, &lux) != 0) {
            fprintf(stderr, "[ERROR] BH1750 read failed — skipping cycle\n");
        } else {
            int relay_state = (lux < LUX_THRESHOLD) ? 1 : 0;
            if (relay_set(relay_state) != 0) {
                fprintf(stderr, "[ERROR] Relay write failed\n");
            }
            log_data(g_log_fp, lux, relay_state);
            printf("Lux: %.2f  Relay: %s\n", lux, relay_state ? "ON" : "OFF");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_S * 10 && g_running; i++) {
            gpioDelay(100 * 1000); /* 100 ms */
        }
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

