        fprintf(stderr, "gpioSetMode(%d, OUTPUT) failed\n", GROW_LIGHT_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (relay_set(0) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- I2C open --- */
    g_i2c_handle = i2cOpen(1, BH1750_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(1, 0x%02X) failed: %s\n",
                BH1750_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- log file --- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- signals --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Grow-light controller started.  BH1750 @ 0x%02X, relay GPIO%d, threshold %d lux.\n",
           BH1750_ADDR, GROW_LIGHT_PIN, LUX_THRESHOLD);
    printf("Press Ctrl+C to exit.\n");

    /* --- main loop --- */
    while (g_running) {
        float lux = 0.0f;

        if (bh1750_read_lux(g_i2c_handle, &lux) != 0) {
            fprintf(stderr, "[ERROR] BH1750 read failed — skipping cycle\n");
        } else {
            int relay_state = (lux < LUX_THRESHOLD) ? 1 : 0;
            if (relay_set(relay_state) != 0) {
                fprintf(stderr, "[ERROR] Relay write failed\n");
            }
            log_data(g_log_fp, lux, relay_state);
            printf("Lux: %.2f  Relay: %s\n", lux, relay_state ? "ON" : "OFF");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_S * 10 && g_running; i++) {
            gpioDelay(100 * 1000); /* 100 ms */
        }
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

