/*
 * Raspberry Pi 3 Model B+ — TAL220B load-cell monitor with HX711 + solenoid lock.
 *
 * Wiring:
 *   HX711 DOUT  -> GPIO23 (physical pin 16)
 *   HX711 SCK   -> GPIO24 (physical pin 18)
 *   Solenoid    -> GPIO25 (physical pin 22)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o load_cell_monitor load_cell_monitor.c \
 *       -lgpiod -lm
 *
 * Run:
 *   ./load_cell_monitor --scale 1000.0 --duration 500
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <math.h>
#include <gpiod.h>

#include <syslog.h>
#include <getopt.h>
#include <errno.h>

/* ----------------------------- Configuration ----------------------------- */

#define HX711_DOUT_PIN  23          /* GPIO23 — physical pin 16 */
#define HX711_SCK_PIN   24          /* GPIO24 — physical pin 18 */
#define SOLENOID_PIN    25          /* GPIO25 — physical pin 22 */

#define DEFAULT_THRESHOLD_G 1000.0
#define DEFAULT_SCALE_FACTOR  1000.0
#define DEFAULT_DURATION_MS   500
#define NUM_READINGS_TARE    10
#define NUM_READINGS_MEASURE 5
#define HX711_TIMEOUT_US    1000000  /* 1 s */
#define HX711_READ_RETRIES   3
#define HX711_READ_DELAY_US  1
#define SOLENOID_PULSE_US   200000   /* 200 ms */

/* ------------------------------- Globals --------------------------------- */

static volatile sig_atomic_t g_running = 1;

/* --------------------------- Signal handling ----------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- GPIO helpers -------------------------------- */

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *dout = NULL;
static struct gpiod_line *sck  = NULL;
static struct gpiod_line *sol  = NULL;

static void cleanup_gpio(void)
{
    if (sol) {
        gpiod_line_set_value(sol, 0);
        gpiod_line_release(sol);
        sol = NULL;
    }
    if (dout) {
        gpiod_line_release(dout);
        dout = NULL;
    }
    if (sck) {
        gpiod_line_release(sck);
        sck = NULL;
    }
    if (chip) {
        gpiod_chip_close(chip);
        chip = NULL;
    }
}

static int init_gpio(void)
{
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open gpiochip0: %s", strerror(errno));
        return -1;
    }

    dout = gpiod_chip_get_line(chip, HX711_DOUT_PIN);
    if (!dout) {
        syslog(LOG_ERR, "Failed to get DOUT line (GPIO%d): %s",
               HX711_DOUT_PIN, strerror(errno));
        return -1;
    }
    if (gpiod_line_request_input(dout, "hx711_dout") < 0) {
        syslog(LOG_ERR, "Failed to request DOUT as input: %s",
               strerror(errno));
        return -1;
    }

    sck = gpiod_chip_get_line(chip, HX711_SCK_PIN);
    if (!sck) {
        syslog(LOG_ERR, "Failed to get SCK line (GPIO%d): %s",
               HX711_SCK_PIN, strerror(errno));
        return -1;
    }
    if (gpiod_line_request_output(sck, "hx711_sck", 0) < 0) {
        syslog(LOG_ERR, "Failed to request SCK as output: %s",
               strerror(errno));
        return -1;
    }

    sol = gpiod_chip_get_line(chip, SOLENOID_PIN);
    if (!sol) {
        syslog(LOG_ERR, "Failed to get solenoid line (GPIO%d): %s",
               SOLENOID_PIN, strerror(errno));
        return -1;
    }
    if (gpiod_line_request_output(sol, "solenoid", 0) < 0) {
        syslog(LOG_ERR, "Failed to request solenoid as output: %s",
               strerror(errno));
        return -1;
    }

    return 0;
}

/* --------------------------- HX711 driver -------------------------------- */

/*
 * Read 24 bits from the HX711.
 * Returns 0 on success and stores the signed 24-bit value in *out.
 * Returns -1 on timeout or GPIO error.
 */
static int hx711_read(int32_t *out)
{
    if (!out)
        return -1;

    /* Wait for DOUT to go LOW (data ready). */
    uint64_t waited = 0;
    while (gpiod_line_get_value(dout) == 1) {
        if (waited >= HX711_TIMEOUT_US) {
            syslog(LOG_ERR, "HX711 timeout waiting for DOUT LOW");
            return -1;
        }
        usleep(HX711_READ_DELAY_US);
        waited += HX711_READ_DELAY_US;
    }

    uint32_t value = 0;
    for (int i = 0; i < 24; i++) {
        if (gpiod_line_set_value(sck, 1) < 0) {
            syslog(LOG_ERR, "SCK high write failed: %s", strerror(errno));
            return -1;
        }
        usleep(1);

        value <<= 1;
        int bit = gpiod_line_get_value(dout);
        if (bit < 0) {
            syslog(LOG_ERR, "DOUT read failed: %s", strerror(errno));
            return -1;
        }
        if (bit)
            value |= 1;

        if (gpiod_line_set_value(sck, 0) < 0) {
            syslog(LOG_ERR, "SCK low write failed: %s", strerror(errno));
            return -1;
        }
        usleep(1);
    }

    /* 25th clock pulse: Channel A, Gain 128 (default). */
    if (gpiod_line_set_value(sck, 1) < 0) {
        syslog(LOG_ERR, "SCK high (25th) failed: %s", strerror(errno));
        return -1;
    }
    usleep(1);
    if (gpiod_line_set_value(sck, 0) < 0) {
        syslog(LOG_ERR, "SCK low (25th) failed: %s", strerror(errno));
        return -1;
    }
    usleep(1);

    /* Convert 24-bit two's-complement to signed 32-bit. */
    if (value & 0x800000)
        value |= 0xFF000000;

    *out = (int32_t)value;
    return 0;
}

/* --------------------------- Weight calculation --------------------------- */

static double calculate_weight(int32_t raw, double scale_factor)
{
    return (double)raw / scale_factor;
}

/* --------------------------- Command-line parsing ------------------------- */

static void parse_arguments(int argc, char *argv[], double *threshold,
                            double *scale_factor, int *duration_ms)
{
    *threshold = DEFAULT_THRESHOLD_G;
    *scale_factor = DEFAULT_SCALE_FACTOR;
    *duration_ms  = DEFAULT_DURATION_MS;

    int opt;
    while ((opt = getopt(argc, argv, "t:s:d:")) != -1) {
        switch (opt) {
        case 't':
            *threshold = atof(optarg);
            if (*threshold <= 0.0) {
                fprintf(stderr, "Threshold must be positive.\n");
                exit(EXIT_FAILURE);
            }
            break;
        case 's':
            *scale_factor = atof(optarg);
            if (*scale_factor <= 0.0) {
                fprintf(stderr, "Scale factor must be positive.\n");
                exit(EXIT_FAILURE);
            }
            break;
        case 'd':
            *duration_ms = atoi(optarg);
            if (*duration_ms <= 0) {
                fprintf(stderr, "Duration must be positive.\n");
                exit(EXIT_FAILURE);
            }
            break;
        default:
            fprintf(stderr,
                    "Usage: %s [--scale <factor>] [--duration <ms>]\n",
                    argv[0]);
            exit(EXIT_FAILURE);
        }
    }
}

/* --------------------------- Main loop ----------------------------------- */

static void main_loop(double threshold, double scale_factor, int duration_ms)
{
    int32_t raw[NUM_READINGS_MEASURE];
    double weight[NUM_READINGS_MEASURE];
    double sum = 0.0;
    int valid = 0;

    while (g_running) {
        for (int i = 0; i < NUM_READINGS_MEASURE; i++) {
            int32_t r;
            if (hx711_read(&r) == 0) {
                raw[i] = r;
                weight[i] = calculate_weight(r, scale_factor);
                sum += weight[i];
                valid++;
            } else {
                syslog(LOG_ERR, "HX711 read failed (attempt %d/%d)",
                       i + 1, NUM_READINGS_MEASURE);
            }
            usleep(10000); /* 10 ms between driver calls */
        }

        if (valid == NUM_READINGS_MEASURE) {
            double avg = sum / (double)valid;
            syslog(LOG_INFO, "Weight: %.2f g (avg of %d samples)",
                   avg, valid);

            if (avg > threshold) {
                syslog(LOG_WARNING, "Threshold exceeded: %.2f g > %.2f g",
                       avg, threshold);
                if (gpiod_line_set_value(sol, 1) < 0) {
                    syslog(LOG_ERR, "Failed to activate solenoid: %s",
                           strerror(errno));
                } else {
                    usleep(SOLENOID_PULSE_US);
                    if (gpiod_line_set_value(sol, 0) < 0) {
                        syslog(LOG_ERR, "Failed to deactivate solenoid: %s",
                               strerror(errno));
                    }
                }
            }
        } else {
            syslog(LOG_ERR, "Insufficient valid readings (%d/%d); skipping cycle",
                   valid, NUM_READINGS_MEASURE);
        }

        /* Sleep for the configured duration, checking g_running every 100 ms. */
        for (int ms = 0; ms < duration_ms && g_running; ms += 100) {
            usleep(100000);
        }
    }
}

/* ------------------------------- Main ------------------------------------ */

int main(int argc, char *argv[])
{
    openlog("load_cell_monitor", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction failed: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    parse_arguments(argc, argv, &g_threshold, &g_scale_factor, &g_duration_ms);

    if (init_gpio() < 0) {
        syslog(LOG_ERR, "GPIO initialization failed; aborting.");
        cleanup_gpio();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Load cell monitor started (threshold=%.2f g, scale=%.2f, "
                      "duration=%d ms)",
           g_threshold, g_scale_factor, g_duration_ms);

    main_loop(g_threshold, g_scale_factor, g_duration_ms);

    syslog(LOG_INFO, "Shutting down.");
    cleanup_gpio();
    closelog();
    return EXIT_SUCCESS;
}

