#define MQTT_CLIENT_ID  "relay_controller_1"
#define MQTT_TOPIC      "home/lights/control"
#define MQTT_KEEPALIVE  60
#define MQTT_TOPIC_QOS  0
#define MQTT_TOPIC_LEN  64
#define MQTT_MSG_LEN    256
#define GPIO_INIT_ERR   -1
#define GPIO_SET_ERR    -2
#define GPIO_READ_ERR   -3
#define MQTT_INIT_ERR   -4
#define MQTT_CONNECT_ERR -5
#define MQTT_SUBSCRIBE_ERR -6
#define MQTT_DISCONNECT_ERR -7
#define MQTT_LOOP_ERR    -8
#define MQTT_ERR_VAL     -9

static volatile sig_atomic_t g_running = 1;
static int g_gpio_initialized = 0;
static int g_mqtt_initialized = 0;
static int g_mqtt_connected = 0;
static pthread_mutex_t g_gpio_mutex = PTHREAD_MUTEX_INITIALIZER;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */
static int gpio_init(void)
{
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return GPIO_INIT_ERR;
    }
    g_gpio_initialized = 1;

    if (pthread_mutex_lock(&g_gpio_mutex) != 0) {
        syslog(LOG_ERR, "pthread_mutex_lock failed");
        return GPIO_INIT_ERR;
    }

    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "gpioSetMode failed on pin %d", GPIO_PIN);
        pthread_mutex_unlock(&g_gpio_mutex);
        return GPIO_SET_ERR;
    }

    if (gpioWrite(GPIO_PIN, 0) != 0) {
        syslog(LOG_ERR, "gpioWrite failed on pin %d", GPIO_PIN);
        pthread_mutex_unlock(&g_gpio_mutex);
        return GPIO_SET_ERR;
    }

    syslog(LOG_INFO, "GPIO %d initialised (LOW)", GPIO_PIN);
    pthread_mutex_unlock(&g_gpio_mutex);
    return 0;
}

static int gpio_set(int state)
{
    if (pthread_mutex_lock(&g_gpio_mutex) != 0) {
        syslog(LOG_ERR, "pthread_mutex_lock failed");
        return GPIO_SET_ERR;
    }

    if (gpioWrite(GPIO_PIN, state) != 0) {
        syslog(LOG_ERR, "gpioWrite failed on pin %d (state=%d)", GPIO_PIN, state);
        pthread_mutex_unlock(&g_gpio_mutex);
        return GPIO_SET_ERR;
    }

    syslog(LOG_INFO, "GPIO %d set to %d", GPIO_PIN, state);
    pthread_mutex_unlock(&g_gpio_mutex);
    return 0;
}

static int gpio_read(void)
{
    if (pthread_mutex_lock(&g_gpio_mutex) != 0) {
        syslog(LOG_ERR, "pthread_mutex_lock failed");
        return GPIO_READ_ERR;
    }

    int val = gpioRead(GPIO_PIN);
    pthread_mutex_unlock(&g_gpio_mutex);
    return (val < 0) ? GPIO_READ_ERR : val;
}

/* ------------------------------------------------------------------ */
/* MQTT helpers                                                        */
/* ------------------------------------------------------------------ */
static int mqtt_init(void)
{
    int rc = mosquitto_lib_init();
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "mosquitto_lib_init failed: %s", mosquitto_strerror(rc));
        return MQTT_INIT_ERR;
    }

    mosquitto_message_callback_set(NULL, on_message);
    mosquitto_connect_callback_set(NULL, on_connect);
    mosquitto_disconnect_callback_set(NULL, on_disconnect);

    mosquitto_reconnect_delay_set(NULL, 5);

    g_mqtt_initialized = 1;

    int rc2 = mosquitto_lib_connect(NULL, MQTT_BROKER, MQTT_PORT, MQTT_KEEPALIVE);
    if (rc2 != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "mosquitto_lib_connect failed: %s", mosquitto_strerror(rc2));
        g_mqtt_initialized = 0;
        return MQTT_INIT_ERR;
    }

    g_mqtt_connected = 1;
    syslog(LOG_INFO, "MQTT connected to %s:%d", MQTT_BROKER, MQTT_PORT);
    return 0;
}

static void mqtt_cleanup(void)
{
    if (g_mqtt_initialized) {
        if (g_mqtt_connected) {
            mosquitto_disconnect(NULL);
            g_mqtt_connected = 0;
        }
        mosquitto_lib_disconnect(NULL);
        g_mqtt_initialized = 0;
    }
    if (g_gpio_initialized) {
        gpioWrite(GPIO_PIN, 0);
        gpioTerminate();
        g_gpio_initialized = 0;
    }
}

static void on_connect(int rc)
{
    (void)rc;
    syslog(LOG_INFO, "MQTT connected");
}

static void on_disconnect(int rc)
{
    (void)rc;
    syslog(LOG_INFO, "MQTT disconnected");
}

static void on_message(struct mosquitto *m, void *userdata,
                        const struct mosquitto_message *message)
{
    (void)m;
    (void)userdata;

    if (message->payloadlen > 0) {
        char payload[MQTT_MSG_LEN];
        size_t len = (size_t)message->payloadlen < MQTT_MSG_LEN - 1
                     ? (size_t)message->payloadlen
                     : MQTT_MSG_LEN - 1;
        memcpy(payload, message->payload, len);
        payload[len] = '\0';

        syslog(LOG_INFO, "Received message: %s", payload);

        if (strcmp(payload, "ON") == 0) {
            if (gpio_set(1) != 0) {
                syslog(LOG_ERR, "Failed to set GPIO HIGH");
            } else {
                syslog(LOG_INFO, "Relay ON");
            }
        } else if (strcmp(payload, "OFF") == 0) {
            if (gpio_set(0) != 0) {
                syslog(LOG_ERR, "Failed to set GPIO LOW");
            } else {
                syslog(LOG_INFO, "Relay OFF");
            }
        } else {
            syslog(LOG_ERR, "Invalid payload: %s", payload);
        }
    } else {
        syslog(LOG_ERR, "Empty payload received");
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    openlog("mqtt_relay", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction failed: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    if (gpio_init() != 0) {
        syslog(LOG_ERR, "GPIO initialisation failed, exiting");
        closelog();
        return EXIT_FAILURE;
    }

    if (mqtt_init() != 0) {
        syslog(LOG_ERR, "MQTT initialisation failed, exiting");
        gpio_set(0);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (mosquitto_subscribe(NULL, NULL, MQTT_TOPIC, MQTT_TOPIC_QOS) != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "mosquitto_subscribe failed: %s", mosquitto_strerror(MQTT_SUBSCRIBE_ERR));
        mqtt_cleanup();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Relay controller started");

    while (g_running) {
        int rc = mosquitto_loop(NULL, 100, 1);
        if (rc != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "mosquitto_loop error: %s", mosquitto_strerror(rc));
            if (rc == MQTT_LOOP_ERR) {
                syslog(LOG_WARNING, "MQTT loop error, retrying in 5 s");
                sleep(5);
            }
        }
    }

    syslog(LOG_INFO, "Shutting down");
    mqtt_cleanup();
    closelog();
    return EXIT_SUCCESS;
}

