#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>

#define SERVO1 7
#define SERVO2 8
#define SERVO3 9
#define SERVO4 10
#define SERVO5 11

#define SERVO1_POS 1000
#define SERVO2_POS 1500
#define SERVO3_POS 2000
#define SERVO4_POS 500
#define SERVO5_POS 2500

#define PULSE_WIDTH_MIN 500
#define PULSE_WIDTH_MAX 2500
#define PULSE_WIDTH_RANGE (PULSE_WIDTH_MAX - PULSE_WIDTH_MIN)
#define PULSE_WIDTH_CENTER (PULSE_WIDTH_MIN + PULSE_WIDTH_RANGE / 2)

#define SERVO_COUNT 5

static const int servo_pins[SERVO_COUNT] = {SERVO1, SERVO2, SERVO3, SERVO4, SERVO5};
static const int servo_positions[SERVO_COUNT] = {SERVO1_POS, SERVO2_POS, SERVO3_POS, SERVO4_POS, SERVO5_POS};

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    for (int i = 0; i < SERVO_COUNT; i++) {
        if (gpioSetMode(servo_pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as output.\n", servo_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    for (int i = 0; i < SERVO_COUNT; i++) {
        int pulse_width = (int)(((float)servo_positions[i] / PULSE_WIDTH_CENTER) * PULSE_WIDTH_RANGE) + PULSE_WIDTH_MIN;
        if (pulse_width < PULSE_WIDTH_MIN) pulse_width = PULSE_WIDTH_MIN;
        if (pulse_width > PULSE_WIDTH_MAX) pulse_width = PULSE_WIDTH_MAX;

        if (gpioServo(servo_pins[i], pulse_width) != 0) {
            fprintf(stderr, "Error: failed to start PWM on GPIO %d.\n", servo_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    printf("Servos moving to target positions...\n");

    for (int i = 0; i < 30; i++) {
        gpioDelay(100000); /* 100 ms */
    }

    for (int i = 0; i < SERVO_COUNT; i++) {
        if (gpioServo(servo_pins[i], 0) != 0) {
            fprintf(stderr, "Error: failed to stop PWM on GPIO %d.\n", servo_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    gpioTerminate();
    printf("Servos stopped. Program terminated.\n");
    return EXIT_SUCCESS;
}

