/*
 * Closed-loop DC motor speed control for a Raspberry Pi 3 Model B+
 * using two DRV8833 H-bridges and quadrature encoders.
 *
 * Wiring (BCM numbering):
 *   Motor A PWM  -> GPIO 17 (IN1)
 *   Motor A DIR  -> GPIO 18 (IN2)
 *   Motor B PWM  -> GPIO 22 (IN3)
 *   Motor B DIR  -> GPIO 23 (IN4)
 *   Encoder A A   -> GPIO 4  (phase A)
 *   Encoder A B   -> GPIO 5  (phase B)
 *   Encoder B A   -> GPIO 6  (phase A)
 *   Encoder B B   -> GPIO 12 (phase B)
 *
 * Build:  gcc -O2 -Wall -o motor_ctrl motor_ctrl.c -lpigpio -lm
 * Run:    sudo ./motor_ctrl
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define MOTOR_A_PWM  17
#define MOTOR_A_DIR  18
#define MOTOR_B_PWM  22
#define MOTOR_B_DIR  23

#define ENC_A_A      4
#define ENC_A_B      5
#define ENC_B_A      6
#define ENC_B_B      12

/* ---- Control parameters ---- */
#define PWM_FREQ_HZ   10000          /* 10 kHz PWM */
#define PWM_RANGE     255            /* 8-bit resolution */
#define TARGET_RPM    50.0           /* target speed in RPM */
#define TIC_PER_REV   64             /* encoder ticks per revolution */
#define STALL_TIMEOUT_S 2.0          /* seconds without a tick before warning */
#define LOOP_DELAY_US  100000        /* 100 ms control loop period */

/* ---- Globals ---- */
static volatile int g_motor_a_ticks = 0;
static volatile int g_motor_b_ticks = 0;
static volatile bool g_running      = true;

/* ---- PI gains ---- */
static const double Kp = 0.5;
static const double Ki = 0.1;

/* ---- Per-motor state ---- */
typedef struct {
    double target_rpm;
    double current_rpm;
    double integral;
    double last_error;
    int   pwm_duty;
    bool  running;
} MotorState;

static MotorState g_motor_a = { .target_rpm = TARGET_RPM, .running = true };
static MotorState g_motor_b = { .target_rpm = TARGET_RPM, .running = true };

/* ---- Forward declarations ---- */
static void encoder_a_isr(int gpio, int level, uint32_t tick, void *user);
static void encoder_b_isr(int gpio, int level, uint32_t tick, void *user);
static void motor_a_control(void);
static void motor_b_control(void);
static void signal_handler(int sig);
static void cleanup(void);

/* ------------------------------------------------------------------ */
/* ISR callbacks (pigpio dispatches on a dedicated thread)             */
/* ------------------------------------------------------------------ */
static void encoder_a_isr(int gpio, int level, uint32_t tick, void *user)
{
    (void)gpio; (void)tick; (void)user;
    if (level == 1) {
        g_motor_a_ticks++;
        g_motor_b_ticks++;
    }
}

