#define BH1750_ADDR 0x10
#define BH1750_CMD_POWER_ON 0x01
#define BH1750_CMD_RESET 0x07
#define BH1750_CMD_CONT_HIGHRES 0x10
#define GPIO_RELAY 17
#define LUX_THRESHOLD_DAWN 50
#define LUX_THRESHOLD_DUSK 200
#define LOG_FILE "chicken_coop_log.txt"
#define I2C_BUS 1
