#define BH1750_CONV_TIME_MS 180

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_bh1750(int handle) {
    if (i2cWriteByteData(handle, BH1750_CMD_POWER_ON, 0x00) < 0) {
        fprintf(stderr, "BH1750 power-on failed: %s\n", strerror(errno));
        return -1;
    }
    if (i2cWriteByteData(handle, BH1750_CMD_RESET, 0x00) < 0) {
        fprintf(stderr, "BH1750 reset failed: %s\n", strerror(errno));
