#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#include <pigpio.h>

#define TOUCH_SENSOR_GPIO 4
#define RELAY_GPIO        17
#define DEBOUNCE_DELAY_US 50000   /* 50 ms  */
#define LOOP_SLEEP_US     10000   /* 10 ms  */
#define POLL_TIMEOUT_US   1000000 /* 1 s   */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — async-signal-safe: only sets a flag.             */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Return a heap-allocated ISO-8601 timestamp string.                 */
/* Caller must free().                                              */
/* ------------------------------------------------------------------ */
static char *get_timestamp(void)
{
    time_t rawtime;
    struct tm timeinfo;
    char *buf = malloc(32);
    if (!buf) {
        perror("malloc");
        return NULL;
    }

    time(&rawtime);
    if (!localtime_r(&rawtime, &timeinfo)) {
        perror("localtime_r");
        free(buf);
        return NULL;
    }

    if (strftime(buf, 32, "%Y-%m-%dT%H:%M:%S%z", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        free(buf);
        return NULL;
    }
    return buf;
}

/* ------------------------------------------------------------------ */
/* Log a relay state change with a timestamp.                          */
/* ------------------------------------------------------------------ */
static void log_relay_state(int state)
{
    char *ts = get_timestamp();
    if (!ts) {
        fprintf(stderr, "Failed to generate timestamp\n");
        return;
    }

    if (state == 1)
        printf("[%s] Relay ON\n", ts);
    else
        printf("[%s] Relay OFF\n", ts);

    free(ts);
}

/* ------------------------------------------------------------------ */
/* Debounce: wait DEBOUNCE_DELAY_US microseconds while the sensor   */
/* stays HIGH.  Returns 1 if stable, 0 if not.                        */
/* ------------------------------------------------------------------ */
static int debounce_touch(int gpio)
{
    uint32_t start = gpioTick();
    while (gpioRead(gpio) == 1) {
        if (!g_running)
            return 0;
        if ((int32_t)(gpioTick() - start) >= DEBOUNCE_DELAY_US)
            return 1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins --- */
    if (gpioSetMode(TOUCH_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", TOUCH_SENSOR_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Start with relay OFF */
    if (gpioWrite(RELAY_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to initialise relay state\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int relay_state = 0;

    /* --- Main loop --- */
    while (g_running) {
        int touch = gpioRead(TOUCH_SENSOR_GPIO);
        if (touch < 0) {
            fprintf(stderr, "gpioRead failed on GPIO %d\n", TOUCH_SENSOR_GPIO);
            break;
        }

        if (touch == 1) {
            /* Debounce: must stay HIGH for DEBOUNCE_DELAY_US */
            if (debounce_touch(TOUCH_SENSOR_GPIO)) {
                if (gpioWrite(RELAY_GPIO, relay_state ? 0 : 1) != 0) {
                    fprintf(stderr, "gpioWrite failed on GPIO %d\n", RELAY_GPIO);
                    break;
                }
                relay_state = !relay_state;
                log_relay_state(relay_state);
            }
        }

        /* Wait for sensor to return LOW before allowing next toggle */
        if (debounce_touch(TOUCH_SENSOR_GPIO)) {
            if (gpioWrite(RELAY_GPIO, 0) != 0) {
                fprintf(stderr, "gpioWrite failed on GPIO %d\n", RELAY_GPIO);
                break;
            }
            relay_state = 0;
            log_relay_state(relay_state);
        }

        /* Sleep 10 ms (interruptible by signals) */
        gpioDelay(LOOP_SLEEP_US);
    }

    /* --- Clean shutdown --- */
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return EXIT_SUCCESS;
}

