#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define FLOW_SENSOR_PIN 17
#define SOLENOID_PIN 27
#define LOG_FILE "water_flow.log"
#define DEBOUNCE_US 1000000
#define SAMPLE_INTERVAL_US 1000000
#define FLOW_THRESHOLD_HIGH 5.0
#define FLOW_THRESHOLD_LOW 4.5
#define PULSE_COUNT 0
#define SOLENOID_OPEN 1
#define SOLENOID_CLOSED 0

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
static volatile int pulse_count = 0;
static volatile int solenoid_state = SOLENOID_OPEN;
static volatile int pulse_count_last = 0;
static volatile int pulse_count_last_valid = 0;
static volatile uint32_t last_pulse_tick = 0;
static volatile int pulse_count_valid = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file);
}

static void pulse_callback(int gpio, int level, uint32_t tick) {
    (void)gpio;
    if (level == 1) {
        uint32_t elapsed = tick - last_pulse_tick;
        if (last_pulse_tick != 0 && elapsed > DEBOUNCE_US) {
            pthread_mutex_lock(&pulse_mutex);
            pulse_count++;
            pthread_mutex_unlock(&pulse_mutex);
            last_pulse_tick = tick;
        }
    }
}

static double calculate_flow_rate(int pulse_count, double elapsed_seconds) {
    if (elapsed_seconds <= 0.0) return 0.0;
    return (double)pulse_count / elapsed_seconds * 60.0;
}

static void control_solenoid(double flow_rate) {
    if (flow_rate > FLOW_THRESHOLD_HIGH && solenoid_state == SOLENOID_OPEN) {
        solenoid_state = SOLENOID_CLOSED;
        if (gpioWrite(SOLENOID_PIN, SOLENOID_CLOSED) != 0) {
            log_event("ERROR: Failed to write solenoid pin LOW");
        } else {
            log_event("Solenoid valve closed (flow > 5.0 LPM)");
        }
    } else if (flow_rate < FLOW_THRESHOLD_LOW && solenoid_state == SOLENOID_CLOSED) {
        solenoid_state = SOLENOID_OPEN;
        if (gpioWrite(SOLENOID_PIN, SOLENOID_OPEN) != 0) {
            log_event("ERROR: Failed to write solenoid pin HIGH");
        } else {
            log_event("Solenoid valve opened (flow < 4.5 LPM)");
        }
    }
}

static void *flow_monitor_thread(void *arg) {
    (void)arg;
    uint32_t start_tick = gpioTick();
    while (running) {
        uint32_t now_tick = gpioTick();
        uint32_t elapsed_us = now_tick - start_tick;
        if (elapsed_us >= SAMPLE_INTERVAL_US) {
            start_tick = now_tick;
            uint32_t elapsed_us = 0;
            uint32_t now_tick = gpioTick();
            uint32_t elapsed_us = now_tick - start_tick;
            if (pulse_count_valid) {
                double flow_rate = calculate_flow_rate(pulse_count, elapsed_us / 1000000.0);
                control_solenoid(flow_rate);
                char log_message[128];
                snprintf(log_message, sizeof(log_message), "Flow rate: %.2f LPM, Solenoid: %s",
                         flow_rate, solenoid_state == SOLENOID_OPEN ? "OPEN" : "CLOSED");
                log_event(log_message);
            }
        }
        gpioDelay(1000);
    }
    return NULL;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set flow sensor pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set solenoid pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(FLOW_SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on flow sensor pin\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(SOLENOID_PIN, SOLENOID_OPEN) != 0) {
        fprintf(stderr, "Failed to initialize solenoid to open state\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

