#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <math.h>
#include <stdbool.h>
#include <fcntl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <sys/select.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <pigpio.h>

#define HX711_DATA_PIN 23
#define HX711_SCK_PIN  24
#define SERVO_PIN      18
#define TCP_IP         "127.0.0.1"
#define TCP_PORT       12345
#define CONFIG_FILE    "config.ini"
#define DISPENSING_LOG "dispensing_log.json"
#define MAX_RETRIES    1000
#define SERVO_MIN_US   1000
#define SERVO_MAX_US   2000
#define SERVO_SETTLE_US 1000000
#define API_TIMEOUT_MS 1000
#define API_RETRY_DELAY_MS 100
#define API_RETRY_MAX  10

static volatile sig_atomic_t running = 1;
static int server_fd = -1;
static int client_fd = -1;
static int hx711_fd = -1;
static double calibration_factor = 1.0;
static int api_call_fd = -1;
static int api_call_state = 0;
static int api_call_error_code = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cleanup(void) {
    if (api_call_fd >= 0) {
        if (api_call_state == 0) {
            close(api_call_fd);
            api_call_fd = -1;
        }
    }
    if (client_fd >= 0) {
        close(client_fd);
        client_fd = -1;
    }
    if (server_fd >= 0) {
        close(server_fd);
        server_fd = -1;
    }
    if (hx711_fd >= 0) {
        close(hx711_fd);
        hx711_fd = -1;
    }
    gpioTerminate();
}

static int read_config(const char *filename, double *factor) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Warning: cannot open %s: %s. Using default calibration factor %.2f\n",
                filename, strerror(errno), 1.0);
        *factor = 1.0;
        return 0;
    }
    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        if (strncmp(line, "calibration_factor", 16) == 0) {
            if (sscanf(line, "calibration_factor = %lf", factor) != 1) {
                fprintf(stderr, "Warning: invalid calibration factor in %s. Using default %.2f\n",
                        filename, 1.0);
                *factor = 1.0;
            }
            break;
        }
    }
    fclose(fp);
    return 0;
}

static int read_hx711(int fd, long *out) {
    int i;
    long count = 0;
    int timeout = 0;

    for (i = 0; i < MAX_RETRIES; i++) {
        if (gpioWrite(fd, HX711_SCK_PIN, 1) < 0) return -1;
        gpioDelay(1);
        if (gpioWrite(fd, HX711_SCK_PIN, 0) < 0) return -1;
        gpioDelay(1);

        for (int bit = 0; bit < 24; bit++) {
            if (gpioWrite(fd, HX711_SCK_PIN, 1) < 0) return -1;
            gpioDelay(1);
            if (gpioWrite(fd, HX711_SCK_PIN, 0) < 0) return -1;
            gpioDelay(1);

            if (gpioRead(fd, HX711_DATA_PIN) == 1) {
                count |= (1L << bit);
            }
        }

        if (gpioWrite(fd, HX711_SCK_PIN, 1) < 0) return -1;
        gpioDelay(1);
        if (gpioWrite(fd, HX711_SCK_PIN, 0) < 0) return -1;
        gpioDelay(1);

        if (count != 0) {
            *out = count;
            return 0;
        }
        timeout++;
        if (timeout > 1000) return -1;
    }
    return -1;
}

static long read_hx711_raw(int fd) {
    long count = 0;
    int i;
    for (i = 0; i < MAX_RETRIES; i++) {
        if (read_hx711(fd, &count) == 0) return count;
    }
    return 0;
}

static double hx711_to_grams(long raw) {
    return (double)raw / calibration_factor;
}

static int set_servo_pulsewidth(int fd, int pulsewidth_us) {
    if (pulsewidth_us < SERVO_MIN_US) pulsewidth_us = SERVO_MIN_US;
    if (pulsewidth_us > SERVO_MAX_US) pulsewidth_us = SERVO_MAX_US;
    if (gpioServo(fd, pulsewidth_us) < 0) return -1;
    return 0;
}

static int api_call_init(void) {
    api_call_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (api_call_fd < 0) {
        perror("socket");
        return -1;
    }
    int reuse = 1;
    if (setsockopt(api_call_fd, SOL_SOCKET, SO_REUSEADDR, &reuse, sizeof(reuse)) < 0) {
        perror("setsockopt");
        close(api_call_fd);
        api_call_fd = -1;
        return -1;
    }
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(TCP_IP);
    addr.sin_port = htons(TCP_PORT);
    if (connect(api_call_fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("connect");
        close(api_call_fd);
        api_call_fd = -1;
        return -1;
    }
    return 0;
}

static int api_call_send(const char *msg) {
    size_t len = strlen(msg);
    ssize_t sent = 0;
    while (sent < len) {
        ssize_t n = send(api_call_fd, msg + sent, len - sent, 0);
        if (n < 0) {
            if (errno == EINTR) continue;
            perror("send");
            return -1;
        }
        sent += n;
    }
    return 0;
}

static int api_call_receive(char *buf, size_t buf_size) {
    size_t total = 0;
    while (total < buf_size - 1) {
        ssize_t n = recv(api_call_fd, buf + total, buf_size - 1 - total, 0);
        if (n < 0) {
            if (errno == EINTR) continue;
            perror("recv");
            return -1;
        }
        if (n == 0) return 0;
        total += n;
    }
    buf[total] = '\0';
    return (int)total;
}

static int api_call_open_dispenser(int target_weight) {
    char msg[256];
    snprintf(msg, sizeof(msg), "open_dispenser %d", target_weight);
    if (api_call_send(msg) < 0) return -1;
    return 0;
}

static int api_call_close_dispenser(int target_weight) {
    char msg[256];
    snprintf(msg, sizeof(msg), "close_dispenser %d", target_weight);
    if (api_call_send(msg) < 0) return -1;
    return 0;
}

static int api_call_read_weight(int *out) {
    char msg[256];
    snprintf(msg, sizeof(msg), "read_weight");
    if (api_call_send(msg) < 0) return -1;
    char resp[256];
    if (api_call_receive(resp, sizeof(resp)) < 0) return -1;
    if (sscanf(resp, "%d", out) != 1) {
        fprintf(stderr, "Invalid weight response: %s\n", resp);
        return -1;
    }
    return 0;
}

static int api_call_calibrate(int target_weight, int actual_weight) {
    char msg[256];
    snprintf(msg, sizeof(msg), "calibrate %d %d", target_weight, actual_weight);
    if (api_call_send(msg) < 0) return -1;
    return 0;
}

static int api_call_map_pulsewidth(int target_weight) {
    int pulsewidth = (int)lround((target_weight / 1000.0) * (SERVO_MAX_US - SERVO_MIN_US) + SERVO_MIN_US);
    char msg[256];
    snprintf(msg, sizeof(msg), "map_pulsewidth %d", pulsewidth);
    if (api_call_send(msg) < 0) return -1;
    return 0;
}

static int api_call_send_data(int actual_weight) {
    char msg[256];
    snprintf(msg, sizeof(msg), "send_data %d", actual_weight);
    if (api_call_send(msg) < 0) return -1;
    return 0;
}

static int log_dispensing_event(int target_weight, int actual_weight, const char *error_msg) {
    FILE *fp = fopen(DISPENSING_LOG, "a");
    if (!fp) {
        perror("fopen dispensing_log");
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "{\"timestamp\": \"%s\", \"target_weight\": %d, \"actual_weight\": %d, \"error\": \"%s\"}\n",
            ts, target_weight, actual_weight, error_msg ? error_msg : "null");
    fclose(fp);
    return 0;
}

static int dispense(int target_weight) {
    if (api_call_open_dispenser(target_weight) < 0) {
        fprintf(stderr, "API call to open dispenser failed\n");
        return -1;
    }
    gpioDelay(SERVO_SETTLE_US);

    if (api_call_send_data(0) < 0) {
        fprintf(stderr, "API call to send data failed\n");
        api_call_close_dispenser(target_weight);
        return -1;
    }

    int actual_weight = 0;
    if (api_call_read_weight(&actual_weight) < 0) {
        fprintf(stderr, "API call to read weight failed\n");
        api_call_close_dispenser(target_weight);
        return -1;
    }

    if (api_call_calibrate(target_weight, actual_weight) < 0) {
        fprintf(stderr, "API call to calibrate failed\n");
        api_call_close_dispenser(target_weight);
        return -1;
    }

    if (api_call_map_pulsewidth(target_weight) < 0) {
        fprintf(stderr, "API call to map pulsewidth failed\n");
        api_call_close_dispenser(target_weight);
        return -1;
    }

    if (api_call_send_data(actual_weight) < 0) {
        fprintf(stderr, "API call to send data failed\n");
        api_call_close_dispenser(target_weight);
        return -1;
    }

    return 0;
}

static void handle_client(int client_fd) {
    char buffer[256];
    ssize_t n = recv(client_fd, buffer, sizeof(buffer) - 1, 0);
    if (n < 0) {
        perror("recv");
        log_dispensing_event(0, 0, "network error");
        close(client_fd);
        client_fd = -1;
        return;
    }
    if (n == 0) {
        close(client_fd);
        client_fd = -1;
        return;
    }
    buffer[n] = '\0';
    char *endptr;
    long target_weight = strtol(buffer, &endptr, 10);
    if (*endptr != '\0' || errno == ERANGE) {
        fprintf(stderr, "Invalid weight: %s\n", buffer);
        log_dispensing_event(0, 0, "invalid weight");
        close(client_fd);
        client_fd = -1;
        return;
    }
    if (dispense((int)target_weight) < 0) {
        fprintf(stderr, "Dispensing failed\n");
        log_dispensing_event(0, 0, "dispensing failed");
    } else {
        log_dispensing_event((int)target_weight, (int)actual_weight, NULL);
    }
    close(client_fd);
    client_fd = -1;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    hx711_fd = open("/dev/gpiochip0", O_RDWR);
    if (hx711_fd < 0) {
        perror("open /dev/gpiochip0");
        gpioTerminate();
        return 1;
    }
    if (ioctl(hx711_fd, I2C_SLAVE, 0) < 0) {
        perror("ioctl I2C_SLAVE");
        close(hx711_fd);
        gpioTerminate();
        return 1;
    }

    if (read_config(CONFIG_FILE, &calibration_factor) < 0) {
        fprintf(stderr, "Using default calibration factor: %.2f\n", calibration_factor);
    }

    if (api_call_init() < 0) {
        fprintf(stderr, "API socket initialisation failed\n");
        cleanup();
        return 1;
    }

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        perror("socket");
        cleanup();
        return 1;
    }
    int reuse = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &reuse, sizeof(reuse)) < 0) {
        perror("setsockopt");
        close(server_fd);
        cleanup();
        return 1;
    }
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port = htons(TCP_PORT);
    if (bind(server_fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("bind");
        close(server_fd);
        cleanup();
        return 1;
    }
    if (listen(server_fd, 3) < 0) {
        perror("listen");
        close(server_fd);
        cleanup();
        return 1;
    }
    printf("Listening on %s:%d...\n", TCP_IP, TCP_PORT);

    while (running) {
        struct sockaddr_in caddr;
        socklen_t clen = sizeof(caddr);
        client_fd = accept(server_fd, (struct sockaddr *)&caddr, &clen);
        if (client_fd < 0) {
            if (errno == EINTR) continue;
            perror("accept");
            continue;
        }
        printf("Client connected from %s:%d\n", inet_ntoa(caddr.sin_addr), ntohs(caddr.sin_port));
        handle_client(client_fd);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

