/*
 * TTP223 capacitive touch sensor → relay toggle on Raspberry Pi 3 Model B+.
 *
 * Wiring:
 *   TTP223 VCC  → 5 V (pin 2 or 4)
 *   TTP223 GND  → GND (pin 6)
 *   TTP223 OUT  → GPIO 4  (BCM 4, pin 7)
 *   Relay IN    → GPIO 17 (BCM 17, pin 11)
 *   Relay VCC   → 5 V
 *   Relay GND   → GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o touch_relay touch_relay.c -lpigpio -lrt
 *   (pigpio must be installed via apt: sudo apt install pigpio)
 *
 * Usage:
 *   ./touch_relay [-d delay_ms]
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN        17
#define DEFAULT_DEBOUNCE_MS 50
#define POLL_DELAY_US     10000   /* 10 ms */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) != 0)
        perror("sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_relay_state(int state)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    printf("%s Relay: %s\n", timestamp, state ? "ON" : "OFF");
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* Debounced rising-edge detection                                     */
/* ------------------------------------------------------------------ */
static int detect_rising_edge(int *last_state)
{
    int current = gpioRead(TOUCH_SENSOR_PIN);
    if (current < 0) {
        fprintf(stderr, "gpioRead failed on pin %d\n", TOUCH_SENSOR_PIN);
        return -1;
    }

    if (current == 1 && *last_state == 0) {
        gpioDelay(POLL_DELAY_US);
        int confirm = gpioRead(TOUCH_SENSOR_PIN);
        if (confirm < 0) {
            fprintf(stderr, "gpioRead failed on pin %d\n", TOUCH_SENSOR_PIN);
            *last_state = 0;
            return -1;
        }
        if (confirm == 1) {
            *last_state = 1;
            return 1;
        }
    }

    *last_state = current;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Relay control                                                        */
/* ------------------------------------------------------------------ */
static int relay_set(int state)
{
    if (gpioWrite(RELAY_PIN, state) < 0) {
        fprintf(stderr, "gpioWrite failed on pin %d\n", RELAY_PIN);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    int delay_ms = DEFAULT_DEBOUNCE_MS;

    if (argc > 1) {
        char *endptr = NULL;
        long val = strtol(argv[1], &endptr, 10);
        if (endptr == argv[1] || *endptr != '\0' || val <= 0 || val > 100000) {
            fprintf(stderr, "Invalid delay argument: %s\n", argv[1]);
            return EXIT_FAILURE;
        }
        delay_ms = (int)val;
    }

    install_signal_handlers();

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed for touch sensor pin %d\n",
                TOUCH_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed for relay pin %d\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure relay starts in OFF state */
    if (relay_set(0) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int relay_state = 0;
    int last_touch = 0;

    printf("Monitoring TTP223 touch sensor on GPIO %d. Relay on GPIO %d.\n",
           TOUCH_SENSOR_PIN, RELAY_PIN);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (g_running) {
        int rising = detect_rising_edge(&last_touch);
        if (rising < 0) {
            /* Transient read error — keep running but log it */
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (rising) {
            relay_state = !relay_state;
            if (relay_set(relay_state) < 0) {
                /* Relay control failure — keep running but log it */
            } else {
                log_relay_state(relay_state);
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* Clean shutdown */
    relay_set(0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

