/*
 * servo_key.c — Servo control via keyboard on Raspberry Pi 4/5
 *
 * Build:  gcc -O2 -Wall -Wextra -o servo_key servo_key.c
 * Run:    ./servo_key
 *
 * Hardware:
 *   - Servo signal pin: GPIO18 (BCM 18, physical pin 12)
 *   - 50 Hz PWM, 20 ms period
 *   - Pulse width 1500–2500 µs for an SG90
 *
 * Keyboard:
 *   '+'   -> angle += 10°
 *   '-'   -> angle -= 10°
 *   'q'   -> quit
 *   Ctrl-C -> quit
 */

