#define PWM_DUTY_0      500000UL    /* 500 µs  -> 0°    */
#define PWM_DUTY_180    2500000UL   /* 2500 µs -> 180°  */
#define MIN_PULSE_US    500
#define MAX_PULSE_US    2500
#define ANGLE_STEP      10
#define KEYBUF_SIZE     16

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handler(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    return sigaction(SIGINT, &sa, NULL);
}

/*
 * mmap a single GPIO bank and map the PWM registers.
 * Returns a pointer to the PWM base address or NULL on failure.
 */
static unsigned int *map_pwm_regs(void)
{
    unsigned int *p = (unsigned int *)mmap(NULL, sizeof(unsigned int), PROT_READ | PROT_WRITE, MAP_SHARED, -1, 4);
    if (p == MAP_FAILED) {
        perror("mmap");
        return NULL;
    }
    return p;
}

static void unmap_pwm_regs(unsigned int *p)
{
    if (p && p >= (unsigned int *)PWM_BASE && p < (unsigned int *)(PWM_BASE + 4)) {
        munmap((void *)p, sizeof(unsigned int));
    }
}

/*
 * Set the servo pulse width in microseconds.
 * Returns 0 on success, -1 on error.
 */
static int set_servo_pulse(unsigned int pulse_us)
{
    if (pulse_us < MIN_PULSE_US || pulse_us > MAX_PULSE_US) {
        fprintf(stderr, "Error: pulse width %u us out of range [%d, %d]\n",
                pulse_us, MIN_PULSE_US, MAX_PULSE_US);
        return -1;
    }

    unsigned int *p = map_pwm_regs();
    if (!p) {
        return -1;
    }

    unsigned int pwm = (PWM_PERIOD_NS - pulse_us) / 2;
    if (ioctl(pwm, PWM_CTL, pwm) < 0) {
        perror("ioctl PWM_CTL");
        unmap_pwm_regs(p);
        return -1;
    }

    unmap_pwm_regs(p);
    return 0;
}

static int restore_terminal_state(void)
{
    struct termios orig;
    if (tcgetattr(STDIN_FILENO, &orig) != 0) {
        perror("tcgetattr");
        return -1;
    }
    if (tcsetattr(STDIN_FILENO, TCSANOW, &orig) != 0) {
        perror("tcsetattr");
        return -1;
    }
    return 0;
}

static int save_terminal_state(void)
{
    struct termios orig;
    if (tcgetattr(STDIN_FILENO, &orig) != 0) {
        perror("tcgetattr");
        return -1;
    }
    if (tcsetattr(STDIN_FILENO, TCSANOW, &orig) != 0) {
        perror("tcsetattr");
        return -1;
    }
    return 0;
}

