{
    if (install_signal_handler() != 0) {
        fprintf(stderr, "Failed to install SIGINT handler\n");
        return EXIT_FAILURE;
    }

    if (save_terminal_state() != 0) {
        fprintf(stderr, "Failed to save terminal state\n");
        return EXIT_FAILURE;
    }

    if (set_servo_pulse(PWM_DUTY_90) != 0) {
        fprintf(stderr, "Failed to start servo\n");
        restore_terminal_state();
        return EXIT_FAILURE;
    }

    int angle = 90;
    char keybuf[KEYBUF_SIZE];
    int keybuf_len = 0;

    while (g_running) {
        int c = getchar();
        if (c == EOF) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "Error reading key: %s\n", strerror(errno));
            break;
