            if (angle > 180) angle = 180;
            if (set_servo_pulse((unsigned int)((long)PWM_DUTY_90 + (long)(angle - 90) * 1500 / 180)) != 0) {
                break;
            }
            printf("Angle: %d degrees\n", angle);
        } else if (c == '-') {
            angle -= ANGLE_STEP;
            if (angle < 0) angle = 0;
            if (set_servo_pulse((unsigned int)((long)PWM_DUTY_0 + (long)angle * 2500 / 180)) != 0) {
                break;
            }
            printf("Angle: %d degrees\n", angle);
        } else if (c == 'q' || c == 'Q') {
            break;
        } else if (c != '\n') {
            keybuf[keybuf_len++] = (char)c;
        }

        if (keybuf_len >= KEYBUF_SIZE) {
            keybuf_len = KEYBUF_SIZE - 1;
        }

        if (keybuf_len > 0) {
            int i;
            for (i = 0; i < keybuf_len; i++) {
                keybuf[i] = (char)toupper((unsigned char)keybuf[i]);
            }
            keybuf[i] = '\0';
            printf("Key: %s\n", keybuf);
        }

        fflush(stdout);
    }

    /* Stop PWM pulses */
    if (set_servo_pulse(0) != 0) {
        fprintf(stderr, "Warning: failed to stop servo\n");
    }

    restore_terminal_state();
    return EXIT_SUCCESS;
}

