/*
 * conveyor_rpm.c — Hall-effect RPM monitor for Raspberry Pi 3 Model B+
 *
 * Hardware:
 *   - A3144 Hall-effect sensor (open-collector output) on GPIO 17 (BCM 11, physical pin 11)
 *   - Two-pole magnet mounted on the motor shaft
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o conveyor_rpm conveyor_rpm.c -lpigpio -lrt
 *   (pigpio must be installed via: sudo apt install pigpio; run as root or with appropriate permissions)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN          17
#define DEBOUNCE_US       2000   /* 2 ms debounce window */
#define SAMPLE_INTERVAL_S 5     /* RPM report interval */
#define LOG_FILE          "motor_rpm.log"

/* ------------------------------------------------------------------ */
/* Globals                                                            */
/* ------------------------------------------------------------------ */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                    */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

/*
 * pigpio's gpioRead returns 0 or 1 on success, and PI_BAD_GPIO on
 * failure.  We cast the result to int so the caller can check
 * against 0, 1, or PI_BAD_GPIO.
 */
static int read_gpio(int pin)
{
    int v = gpioRead(pin);
    if (v == PI_BAD_GPIO) {
        fprintf(stderr, "gpioRead failed on pin %d\n", pin);
        return -1;
    }
    return v;
}

/*
 * pigpio's gpioSetAlertFuncEx fires a callback on every edge of the
 * line.  We debounce by ignoring edges that arrive within DEBOUNCE_US
 * microseconds of the last accepted edge.
 */
static void edge_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    static uint32_t last_tick = 0;
    uint32_t elapsed;

    if (tick == 0) {
        /* tick is 0 when the callback is invoked during a read; ignore. */
        return;
    }

    elapsed = tick - last_tick;          /* pigpio tick wraps every ~72 min */
    if (elapsed < DEBOUNCE_US) {
        return;                          /* within debounce window — ignore */
    }
    last_tick = tick;

    /* level == 1 means a rising edge (two-pole magnet pulls the
     * open-collector output low). */
    if (level == 1) {
        static uint64_t pulse_count = 0;
        pulse_count++;
    }
}

/*
 * pigpio's gpioSetAlertFuncEx requires a user data pointer; we pass
 * NULL so the callback signature matches the one expected by the
 * gpioSetAlertFuncEx() macro.
 */
static int init_gpio(void)
{
    if (gpioSetMode(GPIO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed on pin %d\n", GPIO_PIN);
        return -1;
    }

    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "gpioSetPullUpDown failed on pin %d\n", GPIO_PIN);
        return -1;
    }

    if (gpioSetAlertFuncEx(GPIO_PIN, edge_callback, NULL) < 0) {
        fprintf(stderr, "gpioSetAlertFuncEx failed on pin %d\n", GPIO_PIN);
        return -1;
    }

    return 0;
}

/*
 * pigpio's gpioSetAlertFuncEx fires a callback on every edge of the
 * line.  We debounce by ignoring edges that arrive within DEBOUNCE_US
 * microseconds of the last accepted edge.
 */
static void log_rpm(double rpm)
{
    if (g_log_fp == NULL) {
        fprintf(stderr, "log_rpm: log file not open\n");
        return;
    }

    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return;
    }

    struct tm tm_buf;
    struct tm *tm_info = localtime_r(&now, &tm_buf);
    if (tm_info == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(g_log_fp, "%s,%.2f\n", ts, rpm) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return;
    }

    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Initialize GPIO ---- */
    if (init_gpio() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Conveyor belt RPM monitor started.\n");
    printf("  GPIO pin : %d (BCM)\n", GPIO_PIN);
    printf("  Log file : %s\n", LOG_FILE);
    printf("  Interval : %d s\n", SAMPLE_INTERVAL_S);
    printf("  Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* ---- Main sampling loop ---- */
    uint64_t pulse_count = 0;
    uint32_t last_tick = gpioTick();   /* pigpio tick at startup */
    int first_sample = 1;

    while (g_running) {
        uint32_t now_tick = gpioTick();

        /* pigpio tick wraps every ~72 minutes; handle the wrap-around. */
        uint32_t elapsed_us = now_tick - last_tick;
        if (elapsed_us < (uint32_t)(SAMPLE_INTERVAL_S * 1000000)) {
            usleep((useconds_t)(SAMPLE_INTERVAL_S * 1000000 - elapsed_us));
            continue;
        }
        last_tick = now_tick;

        /* Count pulses that have accumulated during the sampling window. */
        if (first_sample) {
            first_sample = 0;
        } else {
            pulse_count += (uint64_t)(now_tick - last_tick) / 1000000ULL;
        }

        /* Report RPM every interval. */
        double rpm = (double)pulse_count * 60.0 / (double)SAMPLE_INTERVAL_S;
        log_rpm(rpm);
        printf("RPM: %.2f\n", rpm);
        fflush(stdout);
    }

    /* ---- Cleanup ---- */
    printf("\nShutting down...\n");

    /* Disable the alert callback before tearing down pigpio. */
    gpioSetAlertFuncEx(GPIO_PIN, NULL, NULL);

    if (fclose(g_log_fp) != 0) {
        fprintf(stderr, "fclose(%s) failed: %s\n", LOG_FILE, strerror(errno));
    }
    g_log_fp = NULL;

    gpioTerminate();

    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

