/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Initialize GPIO ---- */
    if (init_gpio() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Conveyor belt RPM monitor started.\n");
    printf("  GPIO pin : %d (BCM)\n", GPIO_PIN);
    printf("  Log file : %s\n", LOG_FILE);
    printf("  Interval : %d s\n", SAMPLE_INTERVAL_S);
    printf("  Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* ---- Main sampling loop ---- */
    uint64_t pulse_count = 0;
    uint32_t last_tick = gpioTick();   /* pigpio tick at startup */
    int first_sample = 1;

    while (g_running) {
        uint32_t now_tick = gpioTick();

        /* pigpio tick wraps every ~72 minutes; handle the wrap-around. */
        uint32_t elapsed_us = now_tick - last_tick;
        if (elapsed_us < (uint32_t)(SAMPLE_INTERVAL_S * 1000000)) {
            usleep((useconds_t)(SAMPLE_INTERVAL_S * 1000000 - elapsed_us));
            continue;
        }
        last_tick = now_tick;

        /* Count pulses that have accumulated during the sampling window. */
        if (first_sample) {
            first_sample = 0;
        } else {
            pulse_count += (uint64_t)(now_tick - last_tick) / 1000000ULL;
        }

        /* Report RPM every interval. */
        double rpm = (double)pulse_count * 60.0 / (double)SAMPLE_INTERVAL_S;
        log_rpm(rpm);
        printf("RPM: %.2f\n", rpm);
        fflush(stdout);
    }

    /* ---- Cleanup ---- */
    printf("\nShutting down...\n");

    /* Disable the alert callback before tearing down pigpio. */
    gpioSetAlertFuncEx(GPIO_PIN, NULL, NULL);

    if (fclose(g_log_fp) != 0) {
        fprintf(stderr, "fclose(%s) failed: %s\n", LOG_FILE, strerror(errno));
    }
    g_log_fp = NULL;

    gpioTerminate();

    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

