/*
 * TTP223 capacitive touch sensor -> active-high relay toggle.
 * Board:  Raspberry Pi 5 (BCM numbering)
 * Sensor: TTP223 on BCM GPIO4  (active HIGH)
 * Relay:  5 V active-HIGH relay on BCM GPIO17
 * Polling interval: 50 ms
 * Relay stays HIGH until touch is released; if touch is sustained
 * for >10 s the relay is forced OFF and ignored until released.
 *
 * Build:  gcc -O2 -Wall -Wextra -o touch_relay touch_relay.c -lpigpio -lrt
 * Run:    sudo ./touch_relay
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <time.h>
#include <pigpio.h>

#define TOUCH_PIN      4
#define RELAY_PIN      17
#define POLL_DELAY_US  50000          /* 50 ms */
#define STAY_TIMEOUT_S 10             /* seconds */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) != 0)
        perror("sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
static int safe_set_mode(unsigned pin, unsigned mode)
{
    if (gpioSetMode(pin, mode) != 0) {
        fprintf(stderr, "gpioSetMode(%u, %u) failed\n", pin, mode);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int safe_set_value(unsigned pin, unsigned level)
{
    if (gpioWrite(pin, level) != 0) {
        fprintf(stderr, "gpioWrite(%u, %u) failed\n", pin, level);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup_relay(void)
{
    (void)gpioWrite(RELAY_PIN, 0);   /* relay OFF */
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    int rc = EXIT_FAILURE;

    install_signal_handlers();

    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise() failed\n");
        return EXIT_FAILURE;
    }

    if (safe_set_mode(TOUCH_PIN, PI_INPUT) != 0 ||
        safe_set_mode(RELAY_PIN, PI_OUTPUT) != 0) {
        cleanup_relay();
        return EXIT_FAILURE;
    }

    /* Start from a known state: relay OFF */
    if (safe_set_value(RELAY_PIN, 0) != 0) {
        cleanup_relay();
        return EXIT_FAILURE;
    }

    bool relay_on = false;
    bool touched   = false;
    time_t start_touch = 0;
    bool force_off  = false;

    printf("TTP223 touch sensor -> relay toggle (BCM GPIO%d -> BCM GPIO%d)\n",
           TOUCH_PIN, RELAY_PIN);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        int level = gpioRead(TOUCH_PIN);
        if (level < 0) {
            fprintf(stderr, "gpioRead(%d) failed\n", TOUCH_PIN);
            break;
        }

        if (level == 1) {
            if (!touched) {
                touched = true;
                start_touch = time(NULL);
                printf("Touch detected (sustained for >%d s)\n",
                       STAY_TIMEOUT_S);
            } else {
                if (start_touch == 0) {
                    start_touch = time(NULL);
                }
                if (difftime(time(NULL), start_touch) > STAY_TIMEOUT_S) {
                    printf("Touch sustained >%d s -> forcing relay OFF\n",
                           STAY_TIMEOUT_S);
                    if (safe_set_value(RELAY_PIN, 0) != 0) {
                        break;
                    }
                    relay_on = false;
                    force_off = true;
                }
            }
        } else {
            touched = false;
            if (relay_on) {
                if (safe_set_value(RELAY_PIN, 0) != 0) {
                    break;
                }
                relay_on = false;
            }
        }

        if (force_off) {
            if (safe_set_value(RELAY_PIN, 0) != 0) {
                break;
            }
            force_off = false;
        }

        if (level == 1) {
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (!relay_on) {
            if (safe_set_value(RELAY_PIN, 1) != 0) {
                break;
            }
            relay_on = true;
        }

        gpioDelay(POLL_DELAY_US);
    }

    rc = EXIT_SUCCESS;

    cleanup_relay();
    return rc;
}

