#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define PWM_PIN          18
#define VALVE_ENABLE_PIN 23
#define FLOW_SENSOR_PIN  24

#define PWM_RANGE        255
#define PWM_FREQ         1000
#define SAMPLE_PERIOD_US 100000  /* 100 ms */
#define MAX_FLOW_RATE    10.0    /* L/min */
#define MIN_FLOW_RATE    0.0
#define Kp               1.0

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;

/* Flow-rate state updated by the ISR */
static volatile double g_flow_rate = 0.0;
static volatile uint32_t g_pulse_count = 0;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Flow sensor ISR: increment pulse count on each rising edge         */
/* ------------------------------------------------------------------ */
static void flow_sensor_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)level;
    (void)tick;
    (void)userdata;
    g_pulse_count++;
}

/* ------------------------------------------------------------------ */
/* CSV logging                                                          */
/* ------------------------------------------------------------------ */
static void log_data(double flow_rate, int valve_position)
{
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: log file not open.\n");
        return;
    }

    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }

    long timestamp_ms = (long)ts.tv_sec * 1000L + ts.tv_nsec / 1000000L;

    fprintf(g_log_file, "%ld,%.2f,%d\n", timestamp_ms, flow_rate, valve_position);
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
/* Proportional controller                                              */
/* ------------------------------------------------------------------ */
static int calculate_valve_position(double target_flow_rate)
{
    if (target_flow_rate < MIN_FLOW_RATE) {
        target_flow_rate = MIN_FLOW_RATE;
    } else if (target_flow_rate > MAX_FLOW_RATE) {
        target_flow_rate = MAX_FLOW_RATE;
    }

    double error = target_flow_rate - g_flow_rate;
    int duty_cycle = (int)(Kp * error);

    if (duty_cycle < 0) {
        duty_cycle = 0;
    } else if (duty_cycle > PWM_RANGE) {
        duty_cycle = PWM_RANGE;
    }

    return duty_cycle;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Stop PWM */
    if (gpioPWM(PWM_PIN, 0) < 0) {
        fprintf(stderr, "Warning: gpioPWM(0) failed during cleanup.\n");
    }

    /* Drive valve enable low (solenoid de-energized) */
    if (gpioWrite(VALVE_ENABLE_PIN, 0) < 0) {
        fprintf(stderr, "Warning: gpioWrite(VALVE_ENABLE_PIN, 0) failed during cleanup.\n");
    }

    /* Close log file */
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }

    /* Terminate pigpio */
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    int opt;

    /* Parse command-line target flow rate */
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                double target_flow_rate = atof(optarg);
                if (target_flow_rate < MIN_FLOW_RATE || target_flow_rate > MAX_FLOW_RATE) {
                    fprintf(stderr, "Error: target flow rate must be between %.1f and %.1f L/min.\n",
                            MIN_FLOW_RATE, MAX_FLOW_RATE);
                    return EXIT_FAILURE;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-t target_flow_rate_Lmin]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (optind != argc - 1) {
        fprintf(stderr, "Error: target flow rate must be provided as a command-line argument.\n");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure PWM pin */
    if (gpioSetMode(PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(PWM_PIN) failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(PWM_PIN, PWM_FREQ) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure valve enable pin */
    if (gpioSetMode(VALVE_ENABLE_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(VALVE_ENABLE_PIN) failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioWrite(VALVE_ENABLE_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(VALVE_ENABLE_PIN, 1) failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure flow sensor pin */
    if (gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(FLOW_SENSOR_PIN) failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register ISR for flow sensor */
    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, 0, flow_sensor_isr, NULL) < 0) {
        fprintf(stderr, "Error: gpioSetISRFuncEx failed for flow sensor pin %d.\n", FLOW_SENSOR_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_file = fopen("flow_log.csv", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: cannot open flow_log.csv: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp_ms,flow_rate_Lmin,valve_position\n");
        fflush(g_log_file);
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Flow control started. Target flow rate: %.2f L/min\n", target_flow_rate);
    printf("PWM pin: GPIO%d, Valve enable: GPIO%d, Flow sensor: GPIO%d\n",
           PWM_PIN, VALVE_ENABLE_PIN, FLOW_SENSOR_PIN);
    printf("Logging to flow_log.csv every 100 ms. Press Ctrl+C to exit.\n");

    /* Main control loop */
    while (g_running) {
        /* Atomically read flow rate and pulse count */
        double current_flow_rate = g_flow_rate;
        uint32_t pulses = g_pulse_count;

        /* Compute duty cycle */
        int valve_position = calculate_valve_position(target_flow_rate);

        /* Set PWM duty cycle */
        if (gpioPWM(PWM_PIN, valve_position) < 0) {
            fprintf(stderr, "Warning: gpioPWM failed.\n");
        }

        /* Log data */
        log_data(current_flow_rate, valve_position);

        /* Wait for next sample period */
        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

