    if (optind != argc - 1) {
        fprintf(stderr, "Error: target flow rate must be provided as a command-line argument.\n");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure PWM pin */
    if (gpioSetMode(PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(PWM_PIN) failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(PWM_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(PWM_PIN, PWM_FREQ) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure valve enable pin */
    if (gpioSetMode(VALVE_ENABLE_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(VALVE_ENABLE_PIN) failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioWrite(VALVE_ENABLE_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(VALVE_ENABLE_PIN, 1) failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure flow sensor pin */
    if (gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(FLOW_SENSOR_PIN) failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register ISR for flow sensor */
    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, 0, flow_sensor_isr, NULL) < 0) {
        fprintf(stderr, "Error: gpioSetISRFuncEx failed for flow sensor pin %d.\n", FLOW_SENSOR_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_file = fopen("flow_log.csv", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: cannot open flow_log.csv: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp_ms,flow_rate_Lmin,valve_position\n");
        fflush(g_log_file);
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Flow control started. Target flow rate: %.2f L/min\n", target_flow_rate);
    printf("PWM pin: GPIO%d, Valve enable: GPIO%d, Flow sensor: GPIO%d\n",
           PWM_PIN, VALVE_ENABLE_PIN, FLOW_SENSOR_PIN);
    printf("Logging to flow_log.csv every 100 ms. Press Ctrl+C to exit.\n");

    /* Main control loop */
    while (g_running) {
        /* Atomically read flow rate and pulse count */
        double current_flow_rate = g_flow_rate;
        uint32_t pulses = g_pulse_count;

        /* Compute duty cycle */
        int valve_position = calculate_valve_position(target_flow_rate);

        /* Set PWM duty cycle */
        if (gpioPWM(PWM_PIN, valve_position) < 0) {
            fprintf(stderr, "Warning: gpioPWM failed.\n");
        }

        /* Log data */
        log_data(current_flow_rate, valve_position);

        /* Wait for next sample period */
        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

