/*
 * Two-factor door access control for Raspberry Pi 3 Model B+
 * RFID reader : YLI YM-180 on SPI0 CE0 (channel 0) at 100 kHz
 * Lock 1     : GPIO 17 (BCM)  electromagnetic lock
 * Lock 2     : GPIO 27 (BCM)  electromagnetic lock
 * Button     : GPIO 22 (BCM)  active-low with internal pull-up
 *
 * Build:  gcc -O2 -Wall -Wextra -o door_access door_access.c -lpigpio -lrt
 * Run  :  sudo ./door_access
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define LOCK_1_PIN  17
#define LOCK_2_PIN  27
#define BUTTON_PIN  22

/* ---- SPI configuration ---- */
#define SPI_CHANNEL  0          /* CE0 on SPI0 */
#define SPI_SPEED    100000     /* 100 kHz */
#define SPI_FLAGS    0          /* Mode 0, active-low CE */

/* ---- Timing ---- */
#define DEBOUNCE_US  50000      /* 50 ms */
#define ENGAGE_US   5000000     /* 5 s  */
#define POLL_US     100000      /* 100 ms */

/* ---- RFID response ---- */
#define RFID_TAG_LEN 10
#define RFID_VALID   0x0A0B0C0D0E0F101A
#define RFID_NO_TAG  0x00000000

/* ---- Globals ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static FILE *g_log_file  = NULL;

/* ---- Prototypes ---- */
static void signal_handler(int sig);
static void log_event(const char *msg);
static int  read_rfid(uint8_t *data, size_t len);
static bool validate_rfid(const uint8_t *data);
static void engage_lock(int pin);
static void disengage_lock(int pin);
static void button_press(void);
static void cleanup(void);

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void log_event(const char *msg)
{
    if (!g_log_file)
        return;

    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    if (t)
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    else
        snprintf(ts, sizeof(ts), "UNKNOWN");

    fprintf(g_log_file, "[%s] %s\n", ts, msg);
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
static int read_rfid(uint8_t *data, size_t len)
{
    if (len < 1)
        return -1;

    for (int i = 0; i < 4 && g_running; i++) {
        int rc = spiXfer(g_spi_handle, data, data, len);
        if (rc == (int)len)
            return 0;
        if (rc < 0)
            log_event("SPI transfer failed");
        else
            log_event("SPI transfer incomplete");
        gpioDelay(1000);
    }
    return -1;
}

/* ------------------------------------------------------------------ */
static bool validate_rfid(const uint8_t *data)
{
    if (data == NULL || data[0] == 0)
        return false;

    uint32_t raw = ((uint32_t)data[0] << 24) |
                   ((uint32_t)data[1] << 16) |
                   ((uint32_t)data[2] << 8)  |
                   ((uint32_t)data[3]);
    return raw == RFID_VALID;
}

/* ------------------------------------------------------------------ */
static void engage_lock(int pin)
{
    if (gpioWrite(pin, 1) < 0)
        log_event("Failed to engage lock");
    else
        log_event("Lock engaged");
}

static void disengage_lock(int pin)
{
    if (gpioWrite(pin, 0) < 0)
        log_event("Failed to disengage lock");
    else
        log_event("Lock disengaged");
}

/* ------------------------------------------------------------------ */
static void button_press(void)
{
    if (gpioSetMode(BUTTON_PIN, PI_INPUT) < 0)
        log_event("Failed to set button pin as input");
    if (gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP) < 0)
        log_event("Failed to set button pull-up");

    uint32_t start = gpioTick();
    while (g_running) {
        int level = gpioRead(BUTTON_PIN);
        if (level < 0) {
            log_event("Failed to read button");
            break;
        }
        if (level == 0) {                 /* active-low */
            uint32_t elapsed = gpioTick() - start;
            if (elapsed >= DEBOUNCE_US)
                return;
        }
        gpioDelay(1000);
    }
    log_event("Button press detected");
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Force locks to engaged (HIGH) state */
    engage_lock(LOCK_1_PIN);
    engage_lock(LOCK_2_PIN);

    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_file = fopen("/var/log/door_access.log", "a");
    if (!g_log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Configure GPIO pins ---- */
    if (gpioSetMode(LOCK_1_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(LOCK_2_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(BUTTON_PIN, PI_INPUT)  < 0) {
        log_event("Failed to set GPIO modes");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Ensure locks start engaged */
    engage_lock(LOCK_1_PIN);
    engage_lock(LOCK_2_PIN);

    /* ---- Open SPI ---- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        log_event("Failed to open SPI interface");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_event("Door access control started");

    /* ---- Main loop ---- */
    while (g_running) {
        uint8_t tag[RFID_TAG_LEN];
        if (read_rfid(tag, sizeof(tag)) == 0) {
            if (validate_rfid(tag)) {
                log_event("Valid RFID tag detected");
                engage_lock(LOCK_1_PIN);
                engage_lock(LOCK_2_PIN);
                button_press();
                disengage_lock(LOCK_1_PIN);
                disengage_lock(LOCK_2_PIN);
                log_event("Access granted");
            } else {
                log_event("Invalid RFID tag");
            }
        } else {
            log_event("Failed to read RFID tag");
        }
        gpioDelay(POLL_US);
    }

    log_event("Door access control shutting down");
    cleanup();
    return EXIT_SUCCESS;
}

