#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

#define MOTOR1_ENA 23
#define MOTOR1_IN1 24
#define MOTOR1_IN2 25
#define MOTOR2_ENB 12
#define MOTOR2_IN3 16
#define MOTOR2_IN4 20

#define ENCODER1_A 5
#define ENCODER1_B 6
#define ENCODER2_A 26
#define ENCODER2_B 19

#define PWM_FREQUENCY 100
#define PWM_RANGE 1000
#define SAMPLE_INTERVAL_MS 100
#define TARGET_SPEED_RPM 60.0
#define KP 1.0
#define KI 0.1
#define KD 0.01

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static int pigpio_initialized = 0;
static int gpio_initialized = 0;
static pthread_mutex_t motor1_count_mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_mutex_t motor2_count_mutex = PTHREAD_MUTEX_INITIALIZER;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_motor_speed(int motor, int speed) {
    if (speed < 0) speed = 0;
    if (speed > 100) speed = 100;

    int en_pin, in1_pin, in2_pin;
    if (motor == 1) {
        en_pin = MOTOR1_ENA;
        in1_pin = MOTOR1_IN1;
        in2_pin = MOTOR1_IN2;
    } else if (motor == 2) {
        en_pin = MOTOR2_ENB;
        in1_pin = MOTOR2_IN3;
        in2_pin = MOTOR2_IN4;
    } else {
        fprintf(stderr, "Invalid motor number: %d\n", motor);
        return -1;
    }

    if (gpioWrite(en_pin, 1) < 0) {
        fprintf(stderr, "Failed to set ENA high for motor %d\n", motor);
        return -1;
    }

    if (motor == 1) {
        if (speed <= 50) {
            if (gpioWrite(in1_pin, 1) < 0 || gpioWrite(in2_pin, 0) < 0) {
                fprintf(stderr, "Failed to set motor 1 direction\n");
                return -1;
            }
        } else {
            if (gpioWrite(in1_pin, 1) < 0 || gpioWrite(in2_pin, 1) < 0) {
                fprintf(stderr, "Failed to set motor 1 direction\n");
                return -1;
            }
        }
    } else {
        if (speed <= 50) {
            if (gpioWrite(in1_pin, 0) < 0 || gpioWrite(in2_pin, 1) < 0) {
                fprintf(stderr, "Failed to set motor 2 direction\n");
                return -1;
            }
        } else {
            if (gpioWrite(in1_pin, 0) < 0 || gpioWrite(in2_pin, 0) < 0) {
                fprintf(stderr, "Failed to set motor 2 direction\n");
                return -1;
            }
        }
    }

    return 0;
}

static int read_encoder(int motor, int *count) {
    if (count == NULL) return -1;
    if (motor != 1 && motor != 2) {
        fprintf(stderr, "Invalid motor number: %d\n", motor);
        return -1;
    }

    int a_pin, b_pin;
    if (motor == 1) {
        a_pin = ENCODER1_A;
        b_pin = ENCODER1_B;
    } else {
        a_pin = ENCODER2_A;
        b_pin = ENCODER2_B;
    }

    int a_val, b_val;
    if (gpioRead(a_pin) < 0 || gpioRead(b_pin) < 0) {
        fprintf(stderr, "Failed to read encoder pins for motor %d\n", motor);
        return -1;
    }

    a_val = gpioRead(a_pin);
    b_val = gpioRead(b_pin);

    if (a_val < 0 || b_val < 0) {
        fprintf(stderr, "Failed to read encoder pins for motor %d\n", motor);
        return -1;
    }

    if (a_val == b_val) {
        *count += 1;
    } else {
        *count -= 1;
    }

    return 0;
}

static double calculate_pid(double setpoint, double actual, double *integral, double *prev_error, double dt) {
    double error = setpoint - actual;
    double derivative = (error - *prev_error) / dt;
    *integral += error * dt;
    double output = KP * error + KI * (*integral) + KD * derivative;
    *prev_error = error;
    return output;
}

static void *encoder_thread(void *arg) {
    (void)arg;
    int motor = 1;
    int count = 0;
    double integral = 0.0;
    double prev_error = 0.0;
    double dt = (double)SAMPLE_INTERVAL_MS / 1000.0;

    while (running) {
        if (pthread_mutex_lock(&motor1_count_mutex) != 0) {
            fprintf(stderr, "Mutex lock failed for motor 1\n");
            break;
        }
        if (read_encoder(motor, &count) != 0) {
            pthread_mutex_unlock(&motor1_count_mutex);
            break;
        }
        pthread_mutex_unlock(&motor1_count_mutex);

        double speed_rpm = (count * 60.0) / dt;
        double pid_output = calculate_pid(TARGET_SPEED_RPM, speed_rpm, &integral, &prev_error, dt);

        int pwm_value = (int)(pid_output * 10.0);
        if (pwm_value < 0) pwm_value = 0;
        if (pwm_value > PWM_RANGE) pwm_value = PWM_RANGE;

        if (set_motor_speed(motor, pwm_value) != 0) {
            fprintf(stderr, "Failed to set motor speed\n");
            break;
        }

        if (log_file != NULL) {
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            char timestamp[64];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
            fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f\n", timestamp, KP, KI, KD, pid_output);
            fflush(log_file);
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000);
    }

    return NULL;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    pigpio_initialized = 1;

    if (gpioSetMode(MOTOR1_ENA, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR1_IN1, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR1_IN2, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR2_ENB, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR2_IN3, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR2_IN4, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set motor GPIO modes\n");
        goto cleanup;
    }

    if (gpioSetMode(ENCODER1_A, PI_INPUT) < 0 ||
        gpioSetMode(ENCODER1_B, PI_INPUT) < 0 ||
        gpioSetMode(ENCODER2_A, PI_INPUT) < 0 ||
        gpioSetMode(ENCODER2_B, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set encoder GPIO modes\n");
        goto cleanup;
    }

    if (gpioSetPullUpDown(ENCODER1_A, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(ENCODER1_B, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(ENCODER2_A, PI_PUD_UP) < 0 ||
        gpioSetPullUpDown(ENCODER2_B, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set encoder pull-up/down\n");
        goto cleanup;
    }

    if (gpioSetPWMfrequency(MOTOR1_IN1, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(MOTOR1_IN2, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(MOTOR2_IN3, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(MOTOR2_IN4, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        goto cleanup;
    }

    if (gpioSetPWMrange(MOTOR1_IN1, PWM_RANGE) < 0 ||
        gpioSetPWMrange(MOTOR1_IN2, PWM_RANGE) < 0 ||
        gpioSetPWMrange(MOTOR2_IN3, PWM_RANGE) < 0 ||
        gpioSetPWMrange(MOTOR2_IN4, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        goto cleanup;
    }

    log_file = fopen("motor_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        goto cleanup;
    }

    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,P,K,I,KD,Output\n");
        fflush(log_file);
    }

    pthread_t encoder_thread1, encoder_thread2;
    if (pthread_create(&encoder_thread1, NULL, encoder_thread, NULL) != 0) {
        fprintf(stderr, "Failed to create encoder thread 1\n");
        goto cleanup;
    }
    if (pthread_create(&encoder_thread2, NULL, encoder_thread, NULL) != 0) {
        fprintf(stderr, "Failed to create encoder thread 2\n");
        running = 0;
        pthread_join(encoder_thread1, NULL);
        goto cleanup;
    }

    while (running) {
        gpioDelay(100000);
    }

    pthread_join(encoder_thread1, NULL);
    pthread_join(encoder_thread2, NULL);

cleanup:
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (pigpio_initialized) {
        gpioWrite(MOTOR1_ENA, 0);
        gpioWrite(MOTOR1_IN1, 0);
        gpioWrite(MOTOR1_IN2, 0);
        gpioWrite(MOTOR2_ENB, 0);
        gpioWrite(MOTOR2_IN3, 0);
        gpioWrite(MOTOR2_IN4, 0);
        gpioTerminate();
        pigpio_initialized = 0;
    }
    return 0;
}

