/*
 * MPR121 Capacitive Touch Relay Controller for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   MPR121 SDA -> GPIO 2 (I2C bus 1 SDA)
 *   MPR121 SCL -> GPIO 3 (I2C bus 1 SCL)
 *   MPR121 ADDR -> GND  (I2C address 0x5C)
 *   Relay IN   -> GPIO 17 (BCM)
 *   Relay VCC  -> 5V
 *   Relay GND  -> GND
 *
 * Behavior:
 *   - Polls all 12 electrodes every 50 ms.
 *   - Relay is HIGH when any electrode is touched, LOW when all are released.
 *   - Every relay state change is logged to relay_log.txt with a timestamp.
 *   - Clean shutdown on SIGINT.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MPR121_ADDR    0x5C

/* MPR121 register addresses */
#define MPR121_TOUCHSTATUS_L  0x00
#define MPR121_TOUCHSTATUS_H  0x01
#define MPR121_ELECONFIG      0x5E
#define MPR121_SOFTRESET      0x80
#define MPR121_MHDR           0x2B
#define MPR121_NHDR           0x2C
#define MPR121_NCLR           0x2D
#define MPR121_FDLR           0x2E
#define MPR121_MHDF           0x2F
#define MPR121_NHDF           0x30
#define MPR121_NCLF           0x31
#define MPR121_FDLF           0x32
#define MPR121_NHDT           0x33
#define MPR121_NCLT           0x34
#define MPR121_FDLT           0x35
#define MPR121_E0TTH          0x41
#define MPR121_E0RTH          0x42
#define MPR121_ELECONFIG1     0x5E
#define MPR121_ELECONFIG2     0x5F
#define MPR121_ELECONFIG3     0x60
#define MPR121_ELECONFIG4     0x61
#define MPR121_ELECONFIG5     0x62
#define MPR121_ELECONFIG6     0x63
#define MPR121_ELECONFIG7     0x64
#define MPR121_ELECONFIG8     0x65
#define MPR121_ELECONFIG9     0x66
#define MPR121_ELECONFIG10    0x67
#define MPR121_ELECONFIG11    0x68
#define MPR121_ELECONFIG12    0x69
#define MPR121_ELECONFIG13    0x6A
#define MPR121_ELECONFIG14    0x6B
#define MPR121_ELECONFIG15    0x6C
#define MPR121_ELECONFIG16    0x6D
#define MPR121_ELECONFIG17    0x6E
#define MPR121_ELECONFIG18    0x6F
#define MPR121_ELECONFIG19    0x70
#define MPR121_ELECONFIG20    0x71
#define MPR121_ELECONFIG21    0x72
#define MPR121_ELECONFIG22    0x73
#define MPR121_ELECONFIG23    0x74
#define MPR121_ELECONFIG24    0x75
#define MPR121_ELECONFIG25    0x76
#define MPR121_ELECONFIG26    0x77
#define MPR121_ELECONFIG27    0x78
#define MPR121_ELECONFIG28    0x79
#define MPR121_ELECONFIG29    0x7A
#define MPR121_ELECONFIG30    0x7B
#define MPR121_ELECONFIG31    0x7C
#define MPR121_ELECONFIG32    0x7D
#define MPR121_ELECONFIG33    0x7E
#define MPR121_ELECONFIG34    0x7F

#define RELAY_GPIO 17
#define LOG_FILE  "relay_log.txt"
#define POLL_MS   50

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void log_relay_state(int state) {
    if (!g_log_fp) return;
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(g_log_fp, "%s - Relay state: %s\n", ts, state ? "ON" : "OFF");
    fflush(g_log_fp);
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int mpr121_init(int fd) {
    /* Soft reset */
    if (i2c_write_reg8(fd, MPR121_SOFTRESET, 0x63) < 0) return -1;
    usleep(10000);

    /* Filtering configuration */
    if (i2c_write_reg8(fd, MPR121_MHDR, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_NHDR, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_NCLR, 0x0E) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_FDLR, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_MHDF, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_NHDF, 0x05) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_NCLF, 0x01) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_FDLF, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_NHDT, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_NCLT, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_FDLT, 0x00) < 0) return -1;

    /* Touch / release thresholds for all 12 electrodes */
    for (int i = 0; i < 12; i++) {
        if (i2c_write_reg8(fd, MPR121_E0TTH + i * 2, 0x0F) < 0) return -1;
        if (i2c_write_reg8(fd, MPR121_E0RTH + i * 2, 0x0A) < 0) return -1;
    }

    /* Enable 12 electrodes, run mode */
    if (i2c_write_reg8(fd, MPR121_ELECONFIG, 0x0C) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_ELECONFIG1, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_ELECONFIG2, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_ELECONFIG3, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_ELECONFIG4, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_ELECONFIG5, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_ELECONFIG6, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_ELECONFIG7, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_ELECONFIG8, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_ELECONFIG9, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_ELECONFIG10, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_ELECONFIG11, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_ELECONFIG12, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_ELECONFIG13, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_ELECONFIG14, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_ELECONFIG15, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_ELECONFIG16, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_ELECONFIG17, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_ELECONFIG18, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_ELECONFIG19, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_ELECONFIG20, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_ELECONFIG21, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_ELECONFIG22, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_ELECONFIG23, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_ELECONFIG24, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_ELECONFIG25, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_ELECONFIG26, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_ELECONFIG27, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_ELECONFIG28, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_ELECONFIG29, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_ELECONFIG30, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, MPR121_ELECONFIG31, 0x00) < 0) return -1;
