/*
 * Water Distribution Schedule for Raspberry Pi 4 Model B
 * Two Adafruit Solenoid Valves (Product ID 997) via relay modules.
 *
 * Wiring:
 *   - Valve 1 relay: GPIO 17 (BCM)
 *   - Valve 2 relay: GPIO 18 (BCM)
 *   - 12 V supply (via relay) to Valve 1 solenoid
 *   - 12 V supply (via relay) to Valve 2 solenoid
 *
 * Relay logic (active-high):
 *   GPIO HIGH  -> relay ON  -> solenoid OPEN
 *   GPIO LOW   -> relay OFF -> solenoid CLOSED
 *
 * Build: gcc -Wall -Wextra -O2 -o water_schedule water_schedule.c -lpigpio -lrt
 * Run:   sudo ./water_schedule
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define VALVE_1_GPIO 17
#define VALVE_2_GPIO 18

#define VALVE_1_DURATION_MS 500
#define VALVE_2_DURATION_MS 1000
#define PAUSE_1_MS         5000
#define PAUSE_2_MS         10000
#define LOG_FILE           "valve_log.txt"

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly               */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write an ISO 8601 timestamped message to the log file               */
/* ------------------------------------------------------------------ */
static void log_event(const char *message)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed; logging without timestamp.\n");
        return;
    }

    struct tm tm_buf;
    struct tm *tm_info = localtime_r(&now, &tm_buf);
    if (tm_info == NULL) {
        fprintf(stderr, "localtime_r() failed; logging without timestamp.\n");
        return;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", tm_info) == 0) {
        fprintf(stderr, "strftime() failed; logging without timestamp.\n");
        return;
    }

    if (g_log_fp != NULL) {
        fprintf(g_log_fp, "%s: %s\n", timestamp, message);
        fflush(g_log_fp);
    } else {
        fprintf(stderr, "[%s] %s\n", timestamp, message);
    }
}

/* ------------------------------------------------------------------ */
/* Activate a solenoid for the given duration in milliseconds         */
/* ------------------------------------------------------------------ */
static void activate_solenoid(int gpio, int duration_ms)
{
    if (gpioWrite(gpio, 1) < 0) {
        fprintf(stderr, "gpioWrite(%d, 1) failed\n", gpio);
        return;
    }
    log_event("Valve activated");

    /* gpioDelay is microseconds; convert ms to us */
    gpioDelay(duration_ms * 1000);

    if (gpioWrite(gpio, 0) < 0) {
        fprintf(stderr, "gpioWrite(%d, 0) failed\n", gpio);
    }
    log_event("Valve deactivated");
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call multiple times                       */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Ensure both valves are de-energized */
    gpioWrite(VALVE_1_GPIO, 0);
    gpioWrite(VALVE_2_GPIO, 0);

    if (g_log_fp != NULL) {
        log_event("Program terminated — valves de-energized");
        fclose(g_log_fp);
        g_log_fp = NULL;
    }

    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure relay GPIOs as outputs, default LOW ---- */
    if (gpioSetMode(VALVE_1_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed\n", VALVE_1_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(VALVE_2_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed\n", VALVE_2_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioWrite(VALVE_1_GPIO, 0) != 0 || gpioWrite(VALVE_2_GPIO, 0) != 0) {
        fprintf(stderr, "Failed to initialize relay GPIOs to LOW\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        cleanup();
        return EXIT_FAILURE;
    }

    log_event("Program started — valves de-energized");

    /* ---- Main scheduling loop ---- */
    while (g_running) {
        /* ---- Valve 1: 500 ms ON, 5 s PAUSE ---- */
        activate_solenoid(VALVE_1_GPIO, VALVE_1_DURATION_MS);
        if (!g_running) break;
        gpioDelay(PAUSE_1_MS * 1000);

        /* ---- Valve 2: 1000 ms ON, 10 s PAUSE ---- */
        activate_solenoid(VALVE_2_GPIO, VALVE_2_DURATION_MS);
        if (!g_running) break;
        gpioDelay(PAUSE_2_MS * 1000);
    }

    /* ---- Clean shutdown ---- */
    cleanup();
    return EXIT_SUCCESS;
}

