/*
 * MPR121 Capacitive Touch Sensor Relay Controller
 * Board:  Raspberry Pi Zero W
 * Bus:    I2C bus 1 (SDA=GPIO2, SCL=GPIO3)
 * Relay:  GPIO17 (BCM)
 *
 * Build:  gcc -O2 -Wall -o mpr121_relay mpr121_relay.c -lpigpio -lrt
 * Run:    sudo ./mpr121_relay
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- MPR121 register definitions ---- */
#define MPR121_ADDR        0x41
#define MPR121_TOUCHSTATUS 0x00
#define MPR121_ELECTRODE0_T 0x41
#define MPR121_ELECTRODE0_R 0x42
#define MPR121_MHDR         0x2B
#define MPR121_NHDR         0x2C
#define MPR121_NCLR         0x2D
#define MPR121_FDLR         0x2E
#define MPR121_MHDF         0x2F
#define MPR121_NHDF         0x30
#define MPR121_NCLF         0x31
#define MPR121_FDLF         0x32
#define MPR121_NHDT         0x33
#define MPR121_NCLT         0x34
#define MPR121_FDLT         0x35
#define MPR121_E0TTH        0x41
#define MPR121_E0RTH        0x42
#define MPR121_ECR          0x5E
#define MPR121_SOFTRESET    0x80

/* ---- Configuration ---- */
#define I2C_BUS             1
#define RELAY_GPIO          17
#define NUM_ELECTRODES      12
#define STABILIZE_MS        100
#define LOOP_DELAY_MS       100

/* ---- Globals ---- */
static int i2c_handle = -1;
static volatile sig_atomic_t running = 1;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ---- I2C helpers ---- */
static int i2c_write_reg8(int handle, uint8_t reg, uint8_t val)
{
    char buf[2] = { (char)reg, (char)val };
    if (i2cWriteDevice(handle, buf, 2) != 0) {
        fprintf(stderr, "I2C write to reg 0x%02X failed\n", reg);
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int handle, uint8_t reg, uint8_t *val)
{
    char reg_buf[1] = { (char)reg };
    if (i2cWriteDevice(handle, reg_buf, 1) != 0) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed\n", reg);
        return -1;
    }
    char data[1];
    if (i2cReadDevice(handle, data, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed\n", reg);
        return -1;
    }
    *val = (uint8_t)data[0];
    return 0;
}

/* ---- MPR121 initialization ---- */
static int mpr121_init(int handle)
{
    /* Soft reset */
    if (i2c_write_reg8(handle, MPR121_SOFTRESET, 0x63) != 0)
        return -1;
    gpioDelay(10000); /* 10 ms */

    /* Stop mode */
    if (i2c_write_reg8(handle, MPR121_ECR, 0x00) != 0)
        return -1;

    /* Filter / charge configuration */
    if (i2c_write_reg8(handle, MPR121_MHDR, 0x01) != 0) return -1;
    if (i2c_write_reg8(handle, MPR121_NHDR, 0x01) != 0) return -1;
    if (i2c_write_reg8(handle, MPR121_NCLR, 0x0E) != 0) return -1;
    if (i2c_write_reg8(handle, MPR121_FDLR, 0x00) != 0) return -1;
    if (i2c_write_reg8(handle, MPR121_MHDF, 0x01) != 0) return -1;
    if (i2c_write_reg8(handle, MPR121_NHDF, 0x05) != 0) return -1;
    if (i2c_write_reg8(handle, MPR121_NCLF, 0x01) != 0) return -1;
    if (i2c_write_reg8(handle, MPR121_FDLF, 0x00) != 0) return -1;
    if (i2c_write_reg8(handle, MPR121_NHDT, 0x00) != 0) return -1;
    if (i2c_write_reg8(handle, MPR121_NCLT, 0x00) != 0) return -1;
    if (i2c_write_reg8(handle, MPR121_FDLT, 0x00) != 0) return -1;

    /* Touch / release thresholds for all 12 electrodes */
    for (int i = 0; i < NUM_ELECTRODES; i++) {
        if (i2c_write_reg8(handle, MPR121_ELECTRODE0_T + (i * 2), 0x0F) != 0) return -1;
        if (i2c_write_reg8(handle, MPR121_ELECTRODE0_R + (i * 2), 0x0A) != 0) return -1;
    }

    /* Enable 12 electrodes, baseline tracking, run mode */
    if (i2c_write_reg8(handle, MPR121_ECR, 0x8F) != 0)
        return -1;

    gpioDelay(STABILIZE_MS * 1000); /* 100 ms stabilization */
    return 0;
}

/* ---- Read touch status ---- */
static int mpr121_read_touch_status(int handle, uint16_t *touch_status)
{
    uint8_t lo, hi;
    if (i2c_read_reg8(handle, MPR121_TOUCHSTATUS, &lo) != 0)
        return -1;
    if (i2c_read_reg8(handle, MPR121_TOUCHSTATUS + 1, &hi) != 0)
        return -1;
    *touch_status = ((uint16_t)hi << 8) | lo;
    return 0;
}

/* ---- Relay control ---- */
static void relay_toggle(int gpio)
{
    int level = gpioRead(gpio);
    if (level < 0) {
        fprintf(stderr, "GPIO read failed on pin %d\n", gpio);
        return;
    }
    if (gpioWrite(gpio, !level) != 0) {
        fprintf(stderr, "GPIO write failed on pin %d\n", gpio);
    }
    printf("Relay %s\n", level ? "OFF" : "ON");
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X\n",
                I2C_BUS, MPR121_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize MPR121 */
    if (mpr121_init(i2c_handle) != 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure relay GPIO */
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0); /* Start with relay off */

    /* Signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MPR121 relay controller running. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (running) {
        uint16_t touch_status = 0;
        if (mpr121_read_touch_status(i2c_handle, &touch_status) == 0) {
            if (touch_status > 0) {
                relay_toggle(RELAY_GPIO);
            }
        } else {
            fprintf(stderr, "Error reading touch status\n");
        }
        gpioDelay(LOOP_DELAY_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

