code:
/*
 * Raspberry Pi 5 — HC-SR501 PIR motion detector + door strike relay
 *
 * Wiring:
 *   HC-SR501 VCC  -> 5 V (pin 2)
 *   HC-SR501 GND  -> GND (pin 6)
 *   HC-SR501 OUT  -> GPIO17 (BCM, pin 11) — input, pull-down
 *   Relay IN      -> GPIO18 (BCM, pin 12) — output
 *   Relay VCC     -> 5 V or 12 V depending on relay type
 *   Relay GND     -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o door_monitor door_monitor.c -ldriver
 *
 * Run:
 *   ./door_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <stdbool.h>
#include <stdint.h>
#include <driver.h>

#define PIR_GPIO        17
#define RELAY_GPIO      18
#define LOG_FILE        "door_events.log"
#define POLL_INTERVAL_US 50000   /* 50 ms */
#define UNLOCK_MS       500      /* door strike unlock duration */
#define UNLOCK_COOLDOWN_S 2      /* ignore further events for 2 s */
#define UNLOCK_COOLDOWN_US (UNLOCK_COOLDOWN_S * 1000000)

static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_event(int motion, int unlocked)
{
    if (!g_log)
        return;

    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char tbuf[32];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(g_log, "%s.%03ld - Motion: %d, Door Unlocked: %d\n",
            tbuf, ts.tv_nsec / 1000000L, motion, unlocked);
    fflush(g_log);
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */
static int init_gpio(void)
{
    if (driver_init() != DRIVER_INIT_SUCCESS)
        return -1;

    if (driver_set_input(PIR_GPIO, PI_INPUT_PULL_DOWN) != DRIVER_INIT_SUCCESS)
        return -1;

    if (driver_set_output(RELAY_GPIO, PI_OUTPUT) != DRIVER_INIT_SUCCESS)
        return -1;

    if (driver_write(RELAY_GPIO, PI_OUTPUT_OFF) != DRIVER_INIT_SUCCESS)
        return -1;

    return DRIVER_INIT_SUCCESS;
}

static void cleanup_gpio(void)
{
    driver_write(RELAY_GPIO, PI_OUTPUT_OFF);
    driver_close();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        perror("fopen(" LOG_FILE ")");
        return EXIT_FAILURE;
    }

    if (init_gpio() != DRIVER_INIT_SUCCESS) {
        fprintf(stderr, "Failed to initialize GPIO. "
                        "Is the driver library loaded?\n");
        fclose(g_log);
        g_log = NULL;
        return EXIT_FAILURE;
    }

    printf("Monitoring HC-SR501 PIR on GPIO%d, relay on GPIO%d. "
           "Press Ctrl+C to exit.\n", PIR_GPIO, RELAY_GPIO);

    int last_state = 0;
    bool in_cooldown = false;

    while (g_running) {
        int pir = driver_read(PIR_GPIO);
        if (pir < 0) {
            fprintf(stderr, "Error reading PIR GPIO %d\n", PIR_GPIO);
            break;
        }

        if (pir == 1 && last_state == 0) {
            if (!in_cooldown) {
                printf("Motion detected!\n");

                if (driver_write(RELAY_GPIO, PI_OUTPUT_ON) != DRIVER_INIT_SUCCESS) {
                    fprintf(stderr, "Error activating relay\n");
                    break;
                }

                log_event(1, 1);

                /* Hold unlock for the configured duration */
                for (int elapsed = 0; elapsed < UNLOCK_MS && g_running; elapsed += 100) {
                    usleep(100000);
                }

                if (driver_write(RELAY_GPIO, PI_OUTPUT_OFF) != DRIVER_INIT_SUCCESS) {
                    fprintf(stderr, "Error deactivating relay\n");
                    break;
                }

                in_cooldown = true;
                printf("Door strike unlocked for %d ms.\n", UNLOCK_MS);

                /* Enforce rate limiting */
                for (int s = 0; s < UNLOCK_COOLDOWN_S && g_running; s++) {
                    sleep(1);
                }
                in_cooldown = false;
            }
        }

        last_state = pir;
        usleep(POLL_INTERVAL_US);
    }

    cleanup_gpio();
    if (g_log) {
        fclose(g_log);
        g_log = NULL;
    }
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

