#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MOTOR1_GPIO 17
#define MOTOR2_GPIO 27
#define MIN_DUTY_CYCLE 0
#define MAX_DUTY_CYCLE 255
#define MIN_DURATION_MS 50
#define MAX_DURATION_MS 200
#define MIN_STEPS 5
#define MAX_STEPS 15
#define STEP_DELAY_US 10000  /* 10 ms */

static volatile sig_atomic_t shutdown_flag = 0;

static void signal_handler(int sig) {
    (void)sig;
    shutdown_flag = 1;
}

static int generate_pattern(int *duty_cycles, int *duration_ms, int num_steps) {
    if (num_steps < MIN_STEPS || num_steps > MAX_STEPS) {
        fprintf(stderr, "Error: Number of steps must be between %d and %d.\n",
                MIN_STEPS, MAX_STEPS);
        return -1;
    }

    srand((unsigned int)time(NULL));

    for (int i = 0; i < num_steps; i++) {
        duty_cycles[i] = rand() % (MAX_DUTY_CYCLE - MIN_DUTY_CYCLE + 1) + MIN_DUTY_CYCLE;
        duration_ms[i] = rand() % (MAX_DURATION_MS - MIN_DURATION_MS + 1) + MIN_DURATION_MS;
    }

    return 0;
}

static int play_pattern(int *duty_cycles, int *duration_ms, int num_steps) {
    for (int i = 0; i < num_steps; i++) {
        if (gpioPWM(MOTOR1_GPIO, duty_cycles[i]) < 0) {
            fprintf(stderr, "Error: gpioPWM failed for Motor 1 on step %d.\n", i);
            return -1;
        }
        if (gpioPWM(MOTOR2_GPIO, duty_cycles[i]) < 0) {
            fprintf(stderr, "Error: gpioPWM failed for Motor 2 on step %d.\n", i);
            return -1;
        }

        usleep(duration_ms[i] * 1000);

        if (gpioPWM(MOTOR1_GPIO, 0) < 0) {
            fprintf(stderr, "Error: gpioPWM failed to stop Motor 1 on step %d.\n", i);
            return -1;
        }
        if (gpioPWM(MOTOR2_GPIO, 0) < 0) {
            fprintf(stderr, "Error: gpioPWM failed to stop Motor 2 on step %d.\n", i);
            return -1;
        }
    }
    return 0;
}

int main(void) {
    int num_steps = 0;
    int *duty_cycles = NULL;
    int *duration_ms = NULL;
    int ret = 1;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    if (gpioSetMode(MOTOR1_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output.\n", MOTOR1_GPIO);
        goto cleanup;
    }
    if (gpioSetMode(MOTOR2_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output.\n", MOTOR2_GPIO);
        goto cleanup;
    }

    if (gpioSetPWMrange(MOTOR1_GPIO, 255) < 0) {
        fprintf(stderr, "Error: Failed to set PWM range for Motor 1.\n");
        goto cleanup;
    }
    if (gpioSetPWMrange(MOTOR2_GPIO, 255) < 0) {
        fprintf(stderr, "Error: Failed to set PWM range for Motor 2.\n");
        goto cleanup;
    }

    signal(SIGINT, signal_handler);

    printf("Generating haptic patterns on GPIO %d and GPIO %d. Press Ctrl+C to stop.\n",
           MOTOR1_GPIO, MOTOR2_GPIO);

    while (!shutdown_flag) {
        num_steps = rand() % (MAX_STEPS - MIN_STEPS + 1) + MIN_STEPS;
        duty_cycles = (int *)malloc(num_steps * sizeof(int));
        duration_ms = (int *)malloc(num_steps * sizeof(int));

        if (duty_cycles == NULL || duration_ms == NULL) {
            fprintf(stderr, "Error: Memory allocation failed.\n");
            goto cleanup;
        }

        if (generate_pattern(duty_cycles, duration_ms, num_steps) != 0) {
            fprintf(stderr, "Error: Failed to generate pattern.\n");
            goto cleanup;
        }

        if (play_pattern(duty_cycles, duration_ms, num_steps) != 0) {
            fprintf(stderr, "Error: Failed to play pattern.\n");
            goto cleanup;
        }

        free(duty_cycles);
        free(duration_ms);
        duty_cycles = NULL;
        duration_ms = NULL;

        usleep(500000);  /* 0.5 s between patterns */
    }

    printf("\nShutting down gracefully...\n");
    ret = 0;

cleanup:
    if (duty_cycles != NULL) free(duty_cycles);
    if (duration_ms != NULL) free(duration_ms);
    if (gpioInitialise() >= 0) {
        gpioPWM(MOTOR1_GPIO, 0);
        gpioPWM(MOTOR2_GPIO, 0);
    }
    return ret;
}

