code:
/*
 * Raspberry Pi 4 Model B — HX711 Load Cell + Solenoid Lock Monitor
 *
 * Wiring:
 *   HX711 DOUT  -> GPIO4  (BCM)
 *   HX711 PWR   -> 3.3 V
 *   HX711 GND   -> GND
 *   HX711 SCK   -> GPIO17 (BCM)
 *   Solenoid    -> GPIO27 (BCM), active-high
 *
 * Build:  gcc -O2 -Wall -Wextra -o solenoid_monitor solenoid_monitor.c -lpigpio -lrt
 * Run:    sudo ./solenoid_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define HX711_DATA_PIN   4
#define HX711_CLOCK_PIN  17
#define SOLENOID_PIN     27

/* ---- Calibration ---- */
#define DEFAULT_SCALE     1.0f
#define DEFAULT_OFFSET    0.0f
#define CALIBRATION_FILE  "calibration.txt"
#define LOG_FILE          "weight_log.txt"
#define WEIGHT_THRESHOLD  10.0f   /* kg */
#define SAMPLE_PERIOD_US  500000  /* 500 ms */
#define HX711_TIMEOUT_US  500000  /* 0.5 s timeout for a single read */

/* ---- Globals ---- */
static volatile sig_atomic_t g_running = 1;
static float g_scale = DEFAULT_SCALE;
static float g_offset = DEFAULT_OFFSET;
static int g_pigpio_ready = 0;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* HX711 helpers                                                       */
/* ------------------------------------------------------------------ */
/* Returns 0 on success, -1 on timeout / error. */
static int hx711_read(int32_t *out_value)
{
    if (out_value == NULL) {
        return -1;
    }

    /* Wait for DOUT to go low (data ready). */
    uint32_t waited = 0;
    while (gpioRead(HX711_DATA_PIN) == 1) {
        if (waited >= HX711_TIMEOUT_US) {
            return -1;  /* timeout */
        }
        gpioDelay(100);  /* 100 us */
        waited += 100;
    }

    uint32_t value = 0;
    for (int i = 0; i < 24; i++) {
        if (gpioWrite(HX711_CLOCK_PIN, 1) < 0) {
            return -1;
        }
        gpioDelay(1);  /* >=0.2 us high pulse */
        if (gpioWrite(HX711_CLOCK_PIN, 0) < 0) {
            return -1;
        }
        gpioDelay(1);  /* >=0.2 us low pulse */
        value <<= 1;
        if (gpioRead(HX711_DATA_PIN) == 1) {
            value |= 1;
        }
    }

    /* 25th clock pulse to set gain = 128 (default) and select channel A. */
    if (gpioWrite(HX711_CLOCK_PIN, 1) < 0) {
        return -1;
    }
    gpioDelay(1);
    if (gpioWrite(HX711_CLOCK_PIN, 0) < 0) {
        return -1;
    }
    gpioDelay(1);

    /* Sign-extend 24-bit two's complement to 32-bit. */
    if (value & 0x800000) {
        value |= 0xFF000000;
    }

    *out_value = (int32_t)value;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Solenoid control                                                    */
/* ------------------------------------------------------------------ */
static int solenoid_set(int state)
{
    if (gpioWrite(SOLENOID_PIN, state) < 0) {
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Calibration                                                       */
/* ------------------------------------------------------------------ */
static int load_calibration(const char *filename, float *scale, float *offset)
{
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp) != NULL) {
        char key[64];
        char val[64];
        if (sscanf(line, "%63[^=]=%63s", key, val) == 2) {
            if (strcmp(key, "scale") == 0) {
                *scale = strtof(val, NULL);
            } else if (strcmp(key, "offset") == 0) {
                *offset = strtof(val, NULL);
            }
        }
    }

    fclose(fp);
    return 0;
}

static int save_calibration(const char *filename, float scale, float offset)
{
    FILE *fp = fopen(filename, "w");
    if (fp == NULL) {
        return -1;
    }
    fprintf(fp, "scale=%.4f\noffset=%.4f\n", scale, offset);
    fclose(fp);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Weight calculation                                                 */
/* ------------------------------------------------------------------ */
static float calculate_weight(int32_t raw)
{
    return ((float)raw - g_offset) / g_scale;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_weight(float weight)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) != NULL) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, %.2f kg\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, weight);
    } else {
        fprintf(fp, "unknown-time, %.2f kg\n", weight);
    }

    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }
    g_pigpio_ready = 1;

    /* ---- Configure GPIO pins ---- */
    if (gpioSetMode(HX711_DATA_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set HX711_DATA_PIN %d as input\n", HX711_DATA_PIN);
        goto cleanup;
    }
    if (gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set HX711_CLOCK_PIN %d as output\n", HX711_CLOCK_PIN);
        goto cleanup;
    }
    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set SOLENOID_PIN %d as output\n", SOLENOID_PIN);
        goto cleanup;
    }

    /* Start with solenoid de-energized. */
    if (solenoid_set(0) < 0) {
        fprintf(stderr, "Failed to initialise solenoid state\n");
        goto cleanup;
    }

    /* ---- Load calibration (or use defaults) ---- */
    float scale = DEFAULT_SCALE;
    float offset = DEFAULT_OFFSET;
    if (load_calibration(CALIBRATION_FILE, &scale, &offset) != 0) {
        fprintf(stderr, "Warning: could not load calibration from %s; using defaults\n",
                CALIBRATION_FILE);
    }

    /* ---- One-time startup calibration: average 100 zero-load readings ---- */
    int32_t sum = 0;
    int valid = 0;
    for (int i = 0; i < 100; i++) {
        int32_t raw;
        if (hx711_read(&raw) == 0) {
            sum += raw;
            valid++;
        } else {
            fprintf(stderr, "Warning: HX711 read failed during startup calibration (attempt %d)\n", i + 1);
        }
        gpioDelay(10000);  /* 10 ms between readings */
    }

    if (valid == 0) {
        fprintf(stderr, "Error: no valid readings during startup calibration\n");
        goto cleanup;
    }

    float avg_raw = (float)sum / valid;
    offset = avg_raw - (float)g_offset;
    g_offset = offset;
    printf("Startup calibration: offset=%.2f\n", offset);

    /* ---- Main loop ---- */
    while (g_running) {
        int32_t raw;
        if (hx711_read(&raw) != 0) {
            fprintf(stderr, "Warning: HX711 read timeout — skipping cycle\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        float weight = calculate_weight(raw);

        /* Log each reading. */
        log_weight(weight);

        /* Engage solenoid if weight exceeds threshold. */
        if (weight > WEIGHT_THRESHOLD) {
            if (solenoid_set(1) == 0) {
                printf("Weight %.2f kg exceeds threshold %.2f kg — solenoid ENGAGED\n",
                       weight, WEIGHT_THRESHOLD);
            } else {
                fprintf(stderr, "Failed to engage solenoid\n");
            }
        } else {
