#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>

#define RAIN_SENSOR_PIN 4
#define MOTOR_IN1_PIN 17
#define MOTOR_IN2_PIN 18
#define MOTOR_PWM_PIN 27
#define PWM_FREQUENCY 1000
#define PWM_DUTY_CYCLE 150
#define MOTOR_RUN_TIME 5
#define DEBOUNCE_READINGS 5
#define DEBOUNCE_DELAY_MS 50
#define CHECK_INTERVAL_SEC 60
#define LOG_FILE "/var/log/window_control.log"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_rain_sensor(void) {
    int low_count = 0;
    for (int i = 0; i < DEBOUNCE_READINGS; i++) {
        int level = gpioRead(RAIN_SENSOR_PIN);
        if (level == 0) {
            low_count++;
        }
        gpioDelay(DEBOUNCE_DELAY_MS * 1000);
    }
    return (low_count >= 3) ? 1 : 0;
}

static int control_motor(int direction) {
    int in1, in2, pwm;
    if (direction == 1) {
        in1 = 1;
        in2 = 0;
        pwm = 1;
    } else if (direction == 0) {
        in1 = 0;
        in2 = 0;
        pwm = 0;
    } else {
        syslog(LOG_ERR, "Invalid motor direction: %d", direction);
        return -1;
    }
    if (gpioWrite(MOTOR_IN1_PIN, in1) < 0) {
        syslog(LOG_ERR, "Failed to write IN1");
        return -1;
    }
    if (gpioWrite(MOTOR_IN2_PIN, in2) < 0) {
        syslog(LOG_ERR, "Failed to write IN2");
        return -1;
    }
    if (gpioPWM(MOTOR_PWM_PIN, pwm) < 0) {
        syslog(LOG_ERR, "Failed to set PWM");
        return -1;
    }
    return 0;
}

static void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    syslog(LOG_INFO, "%s: %s", timestamp, message);
}

static void stop_motor(void) {
    gpioWrite(MOTOR_IN1_PIN, 0);
    gpioWrite(MOTOR_IN2_PIN, 0);
    gpioPWM(MOTOR_PWM_PIN, 0);
}

int main(void) {
    openlog("window_control", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting window control system...");

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT) < 0) {
        syslog(LOG_ERR, "Failed to set rain sensor pin mode");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_PWM_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set motor GPIO modes");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(MOTOR_PWM_PIN, PWM_FREQUENCY) < 0) {
        syslog(LOG_ERR, "Failed to set PWM frequency");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to set signal handlers");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Rain sensor monitoring started on GPIO%d", RAIN_SENSOR_PIN);
    syslog(LOG_INFO, "Motor control on GPIO%d, %d, %d", MOTOR_IN1_PIN, MOTOR_IN2_PIN, MOTOR_PWM_PIN);

    while (running) {
        if (read_rain_sensor()) {
            syslog(LOG_INFO, "Rain detected!");
            log_event("Rain detected!");
            if (control_motor(1) == 0) {
                log_event("Motor started to close window.");
                for (int i = 0; i < MOTOR_RUN_TIME && running; i++) {
                    gpioDelay(1000000);
                }
                stop_motor();
                log_event("Motor stopped.");
            } else {
                syslog(LOG_ERR, "Motor control failed.");
            }
            syslog(LOG_INFO, "Window closing sequence complete.");
            for (int i = 0; i < CHECK_INTERVAL_SEC && running; i++) {
                gpioDelay(1000000);
            }
        } else {
            syslog(LOG_INFO, "No rain detected.");
            for (int i = 0; i < CHECK_INTERVAL_SEC && running; i++) {
                gpioDelay(1000000);
            }
        }
    }

    syslog(LOG_INFO, "Shutting down...");
    stop_motor();
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

