        for (int i = 0; i < 10 && g_running; i++) {
            gpioDelay(SAMPLE_INTERVAL_US / 10);
        }
    }

    printf("\nShutting down...\n");
    log_event("Stock monitoring stopped");
    cleanup();
    return EXIT_SUCCESS;
}

