/*
 * Raspberry Pi 4 Model B - Kitchen Ingredient Stock Monitor
 *
 * Hardware:
 *   - TAL220B load cell + HX711 amplifier
 *     - DT  -> GPIO23 (BCM)
 *     - SCK -> GPIO24 (BCM)
 *   - Solenoid lock control
 *     - Actuator -> GPIO17 (BCM)
 *
 * Build: gcc -O2 -Wall -o stock_monitor stock_monitor.c -lpigpio -lrt
 * Run:   sudo ./stock_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define DT_PIN      23
#define SCK_PIN     24
#define LOCK_PIN    17

#define WEIGHT_THRESHOLD 100.0f   /* grams */
#define LOCK_DURATION_US 5000000  /* 5 seconds in microseconds */
#define SAMPLE_INTERVAL_US 1000000 /* 1 second in microseconds */
#define HX711_TIMEOUT_US   1000000 /* 1 second timeout for HX711 conversion */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* HX711 bit-bang read                                                    */
/* ------------------------------------------------------------------ */
/*
 * Returns 0 on success (value stored in *out), -1 on timeout/error.
 * The HX711 DT line is driven LOW on a valid conversion; we poll until
 * it reads LOW or timeout.
 */
static int hx711_read(int dt_pin, long *out)
{
    int i;
    int timeout = 0;

    /* Wait for DT to go LOW (data ready) */
    while (gpioRead(dt_pin) == 1) {
        if (timeout++ >= HX711_TIMEOUT_US) {
            return -1; /* timeout waiting for data ready */
        }
        gpioDelay(100); /* 100 us poll interval */
    }

    /* Read 24 data bits MSB-first */
    long value = 0;
    for (i = 0; i < 24; i++) {
        gpioWrite(SCK_PIN, 1);
        gpioDelay(1); /* HX711 needs >=0.2 us high pulse */
        value <<= 1;
        if (gpioRead(dt_pin) == 1) {
            value |= 1;
        }
        gpioWrite(SCK_PIN, 0);
        gpioDelay(1);
    }

    /* 25th pulse to set gain = 128 (default) */
    gpioWrite(SCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(SCK_PIN, 0);
    gpioDelay(1);

    /* Sign-extend 24-bit two's-complement to 32-bit */
    if (value & 0x800000) {
        value |= ~0xFFFFFFL;
    }

    *out = value;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Solenoid lock control                                                */
/* ------------------------------------------------------------------ */
static int solenoid_lock(int lock_pin)
{
    if (gpioWrite(lock_pin, 1) != 0) {
        return -1;
    }
    gpioDelay(LOCK_DURATION_US);
    if (gpioWrite(lock_pin, 0) != 0) {
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_event(const char *message)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (g_log_file != NULL) {
        fprintf(g_log_file, "%s: %s\n", timestamp, message);
        fflush(g_log_file);
    } else {
        fprintf(stderr, "%s: [log file error] %s\n", timestamp, message);
    }
}

