/*
 * Raspberry Pi 4 Model B — HX711 Load Cell Security System
 *
 * Wiring:
 *   HX711 DOUT  -> GPIO4  (BCM)
 *   HX711 PWR   -> 3.3 V
 *   HX711 GND   -> GND
 *   Solenoid    -> GPIO27 (BCM) via transistor (e.g. TIP31C) or relay
 *
 * Build:  gcc -O2 -Wall -o security security.c -lm
 * Run:    sudo ./security
 */

#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <math.h>
#include <fcntl.h>
#include <sys/file.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define HX711_DOUT_PIN  4
#define HX711_CLK_PIN   17
#define SOLENOID_PIN    27

/* ---- Timing constants (microseconds) ---- */
#define CLK_PULSE_US    2
#define DOUT_TIMEOUT_US 100000   /* 100 ms */
#define LOOP_DELAY_US   10000    /* 10 ms */

/* ---- Calibration ---- */
#define CALIBRATION_FILE "calibration.txt"
#define WEIGHT_THRESHOLD_KG 5.0
#define SAMPLE_INTERVAL_S   1

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static FILE *g_log_fp = NULL;
static FILE *g_calib_fp = NULL;
static int g_fd = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read 24-bit signed value from HX711. Returns 0 on success, -1 on timeout. */
static int hx711_read(int fd, int32_t *out)
{
    uint32_t raw = 0;
    int i;

    /* Wait for DOUT to go low (data ready). Timeout after DOUT_TIMEOUT_US. */
    for (i = 0; i < DOUT_TIMEOUT_US; i += 10) {
        int v = read(fd, (uint8_t *)&raw, 1);
        if (v != 1)
            return -1;
        if (raw & 0x80)
            break;
        usleep(10);
    }
    if (i >= DOUT_TIMEOUT_US)
        return -1;

    /* Read remaining 23 bits. */
    for (i = 0; i < 23; i++) {
        if (write(fd, (uint8_t *)&raw, 1) != 1)
            return -1;
        if (write(fd, (uint8_t *)&raw, 1) != 1)
            return -1;
    }

    /* 25th clock pulse to set gain 128 (default). */
    if (write(fd, (uint8_t *)&raw, 1) != 1)
        return -1;

    /* Convert 24-bit two's-complement to signed 32-bit. */
    raw >>= 8;
    raw >>= 8;
    raw >>= 8;
    if (raw & 0x800000)
        raw |= 0xFF000000;

    *out = (int32_t)raw;
    return 0;
}

/* ------------------------------------------------------------------ */
static int calibrate_hx711(int fd, double *calibration)
{
    int32_t raw;
    double sum = 0.0;

    printf("Place a known weight on the load cell and press Enter to calibrate...\n");
    if (fflush(stdout) == EOF)
        return -1;

    if (getchar() == EOF) {
        fprintf(stderr, "Error: no input received.\n");
        return -1;
    }

    printf("Reading raw value...\n");
    if (hx711_read(fd, &raw) != 0) {
        fprintf(stderr, "Error: HX711 read timeout.\n");
        return -1;
    }

    printf("Raw value: %d\n", raw);
    sum = (double)raw;
    printf("Enter the expected weight in kg: ");
    if (scanf("%lf", calibration) != 1) {
        fprintf(stderr, "Error: invalid input.\n");
        return -1;
    }
    if (fflush(stdout) == EOF)
        return -1;

    printf("Calibration factor: %.6f\n", *calibration);
    return 0;
}

/* ------------------------------------------------------------------ */
static double calculate_weight(int32_t raw, double calibration)
{
    return (double)raw / calibration;
}

/* ------------------------------------------------------------------ */
static int log_event(double weight)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t == NULL) {
        fprintf(stderr, "Error: localtime_r failed.\n");
        return -1;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    if (g_log_fp == NULL) {
        fprintf(stderr, "Error: log file not open.\n");
        return -1;
    }

    if (flock(g_fd, LOCK_EX) == -1) {
        perror("flock(LOCK_EX)");
        return -1;
    }

    if (fprintf(g_log_fp, "%s, %.2f kg\n", ts, weight) < 0) {
        perror("fprintf");
        flock(g_fd, LOCK_UN);
        return -1;
    }

    if (fflush(g_log_fp) == EOF) {
        perror("fflush");
        flock(g_fd, LOCK_UN);
        return -1;
    }

    if (flock(g_fd, LOCK_UN) == -1) {
        perror("flock(LOCK_UN)");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
static int engage_solenoid(void)
{
    if (g_fd == -1) {
        fprintf(stderr, "Error: driver not initialized.\n");
        return -1;
    }

    if (write(SOLENOID_PIN, "1", 1) != 1) {
        perror("write solenoid high");
        return -1;
    }
    printf("Solenoid engaged.\n");
    return 0;
}

/* ------------------------------------------------------------------ */
static void disengage_solenoid(void)
{
    if (g_fd == -1) {
        fprintf(stderr, "Error: driver not initialized.\n");
        return;
    }
    if (write(SOLENOID_PIN, "0", 1) != 1) {
        perror("write solenoid low");
    }
    printf("Solenoid disengaged.\n");
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    disengage_solenoid();
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_calib_fp != NULL) {
        fclose(g_calib_fp);
        g_calib_fp = NULL;
    }
    if (g_fd != -1) {
        close(g_fd);
        g_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    int fd;
    double calibration = 1.0;
    int32_t raw;
    double weight;
    bool first_calibration = true;

    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_fp = fopen("security.log", "a");
    if (g_log_fp == NULL) {
        perror("fopen security.log");
        return EXIT_FAILURE;
    }

    /* ---- Open calibration file ---- */
    g_calib_fp = fopen(CALIBRATION_FILE, "w");
    if (g_calib_fp == NULL) {
        perror("fopen calibration.txt");
        fclose(g_log_fp);
        g_log_fp = NULL;
        return EXIT_FAILURE;
    }

    /* ---- Open HX711 device ---- */
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open /dev/i2c-1");
        fclose(g_log_fp);
        g_log_fp = NULL;
        fclose(g_calib_fp);
        g_calib_fp = NULL;
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, 0) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        fclose(g_log_fp);
        g_log_fp = NULL;
        fclose(g_calib_fp);
        g_calib_fp = NULL;
        return EXIT_FAILURE;
    }

    /* ---- Initialize HX711 ---- */
    if (write(fd, (uint8_t *)&raw, 1) != 1) {
        perror("write HX711 init");
        close(fd);
        fclose(g_log_fp);
        g_log_fp = NULL;
        fclose(g_calib_fp);
        g_calib_fp = NULL;
        return EXIT_FAILURE;
    }
    usleep(1000);

    /* ---- Calibration ---- */
    if (calibrate_hx711(fd, &calibration) != 0) {
        fprintf(stderr, "Calibration failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }
    first_calibration = false;

    printf("Calibration complete. Starting monitoring...\n");

    /* ---- Main loop ---- */
    while (g_running) {
        if (hx711_read(fd, &raw) != 0) {
            fprintf(stderr, "Error: HX711 read timeout.\n");
            sleep(1);
            continue;
        }

        weight = calculate_weight(raw, calibration);

        if (weight > WEIGHT_THRESHOLD_KG) {
            printf("Weight: %.2f kg\n", weight);
            if (log_event(weight) != 0)
                fprintf(stderr, "Warning: failed to log event.\n");

            if (engage_solenoid() != 0) {
                fprintf(stderr, "Error: failed to engage solenoid.\n");
            } else {
                /* Keep solenoid engaged for 5 seconds. */
                for (int i = 0; i < 50 && g_running; i++)
                    sleep(0.1);
                disengage_solenoid();
            }
        }

        if (first_calibration && weight > 0.0) {
            fprintf(g_calib_fp, "%.6f\n", calibration);
            fflush(g_calib_fp);
            first_calibration = false;
        }

        usleep(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

