    if (g_log_fp == NULL) {
        fprintf(stderr, "Error: log file not open.\n");
        return -1;
    }

    if (flock(g_fd, LOCK_EX) == -1) {
        perror("flock(LOCK_EX)");
        return -1;
    }

    if (fprintf(g_log_fp, "%s, %.2f kg\n", ts, weight) < 0) {
        perror("fprintf");
        flock(g_fd, LOCK_UN);
        return -1;
    }

    if (fflush(g_log_fp) == EOF) {
        perror("fflush");
        flock(g_fd, LOCK_UN);
        return -1;
    }

    if (flock(g_fd, LOCK_UN) == -1) {
        perror("flock(LOCK_UN)");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
static int engage_solenoid(void)
{
    if (g_fd == -1) {
        fprintf(stderr, "Error: driver not initialized.\n");
        return -1;
    }

    if (write(SOLENOID_PIN, "1", 1) != 1) {
        perror("write solenoid high");
        return -1;
    }
    printf("Solenoid engaged.\n");
    return 0;
}

/* ------------------------------------------------------------------ */
static void disengage_solenoid(void)
{
    if (g_fd == -1) {
        fprintf(stderr, "Error: driver not initialized.\n");
        return;
    }
    if (write(SOLENOID_PIN, "0", 1) != 1) {
        perror("write solenoid low");
    }
    printf("Solenoid disengaged.\n");
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    disengage_solenoid();
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_calib_fp != NULL) {
        fclose(g_calib_fp);
        g_calib_fp = NULL;
    }
    if (g_fd != -1) {
        close(g_fd);
        g_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    int fd;
    double calibration = 1.0;
    int32_t raw;
    double weight;
    bool first_calibration = true;

    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_fp = fopen("security.log", "a");
    if (g_log_fp == NULL) {
        perror("fopen security.log");
        return EXIT_FAILURE;
    }

    /* ---- Open calibration file ---- */
    g_calib_fp = fopen(CALIBRATION_FILE, "w");
    if (g_calib_fp == NULL) {
        perror("fopen calibration.txt");
        fclose(g_log_fp);
        g_log_fp = NULL;
        return EXIT_FAILURE;
    }

    /* ---- Open HX711 device ---- */
    fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("open /dev/i2c-1");
        fclose(g_log_fp);
        g_log_fp = NULL;
        fclose(g_calib_fp);
        g_calib_fp = NULL;
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, 0) < 0) {
        perror("ioctl I2C_SLAVE");
        close(fd);
        fclose(g_log_fp);
        g_log_fp = NULL;
        fclose(g_calib_fp);
        g_calib_fp = NULL;
        return EXIT_FAILURE;
    }

    /* ---- Initialize HX711 ---- */
    if (write(fd, (uint8_t *)&raw, 1) != 1) {
        perror("write HX711 init");
        close(fd);
        fclose(g_log_fp);
        g_log_fp = NULL;
        fclose(g_calib_fp);
        g_calib_fp = NULL;
        return EXIT_FAILURE;
    }
    usleep(1000);

    /* ---- Calibration ---- */
    if (calibrate_hx711(fd, &calibration) != 0) {
        fprintf(stderr, "Calibration failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }
    first_calibration = false;

    printf("Calibration complete. Starting monitoring...\n");

    /* ---- Main loop ---- */
    while (g_running) {
        if (hx711_read(fd, &raw) != 0) {
            fprintf(stderr, "Error: HX711 read timeout.\n");
            sleep(1);
            continue;
        }

        weight = calculate_weight(raw, calibration);

        if (weight > WEIGHT_THRESHOLD_KG) {
            printf("Weight: %.2f kg\n", weight);
            if (log_event(weight) != 0)
                fprintf(stderr, "Warning: failed to log event.\n");

            if (engage_solenoid() != 0) {
                fprintf(stderr, "Error: failed to engage solenoid.\n");
            } else {
                /* Keep solenoid engaged for 5 seconds. */
                for (int i = 0; i < 50 && g_running; i++)
                    sleep(0.1);
                disengage_solenoid();
            }
        }

        if (first_calibration && weight > 0.0) {
            fprintf(g_calib_fp, "%.6f\n", calibration);
            fflush(g_calib_fp);
            first_calibration = false;
        }

        usleep(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

