/*
 * KY022 IR Obstacle Avoidance Sensor → Songle SRD-05VDC-SL Relay Toggle
 * Board:  Raspberry Pi 3 Model B+
 * Sensor: Keywish KY022 (active-low)
 * Relay:  Songle SRD-05VDC-SL (active-high)
 *
 * Wiring:
 *   KY022 OUT  → GPIO16 (BCM)
 *   KY022 VCC  → 3.3 V (pin 1)
 *   KY022 GND  → GND   (pin 6)
 *   SRD-05VDC-SL IN → GPIO20 (BCM)
 *   SRD-05VDC-SL VCC → 5 V (pin 2 or 4)
 *   SRD-05VDC-SL GND → GND   (pin 6)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o relay_toggle relay_toggle.c
 *
 * Run:
 *   sudo ./relay_toggle
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>

#include <pigpio.h>

#define SENSOR_PIN  16          /* KY022 OUT  (BCM) */
#define RELAY_PIN   20          /* SRD-05VDC-SL IN (BCM) */

#define LOG_FILE    "relay_events.log"
#define POLL_US     100000      /* 100 ms poll interval */

/* ------------------------------------------------------------------ */
/* Globals                                                            */
/* ------------------------------------------------------------------ */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                    */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                            */
/* ------------------------------------------------------------------ */

static void log_event(const char *event)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        fclose(fp);
        return;
    }

    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        fclose(fp);
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S%z", &tm) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return;
    }

    if (fprintf(fp, "%s %s\n", ts, event) < 0) {
        fprintf(stderr, "fprintf() to log file failed: %s\n", strerror(errno));
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose() on log file failed: %s\n", strerror(errno));
    }
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                       */
/* ------------------------------------------------------------------ */

/*
 * Read the KY022 sensor.  The sensor is active-low: a LOW reading
 * means an obstacle is present.  The relay is active-high, so we
 * toggle the relay when the sensor reads LOW.
 */
static int read_sensor(void)
{
    int v = gpioRead(SENSOR_PIN);
    if (v < 0) {
        fprintf(stderr, "gpioRead(SENSOR_PIN=%d) failed: %d\n",
                SENSOR_PIN, v);
        return -1;
    }
    return v;
}

static int write_relay(int state)
{
    int rc = gpioWrite(RELAY_PIN, state);
    if (rc < 0) {
        fprintf(stderr, "gpioWrite(RELAY_PIN=%d, %d) failed: %d\n",
                RELAY_PIN, state, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                               */
/* ------------------------------------------------------------------ */

int main(void)
{
    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed (code %d)\n",
                gpioInitialise());
        return EXIT_FAILURE;
    }

    /* ---- Configure sensor pin as input ---- */
    if (gpioSetMode(SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(SENSOR_PIN=%d, PI_INPUT) failed\n",
                SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Configure relay pin as output, initial state LOW ---- */
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(RELAY_PIN=%d, PI_OUTPUT) failed\n",
                RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "gpioWrite(RELAY_PIN=%d, 0) initial state failed\n",
                RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int relay_state = 0;   /* 0 = OFF, 1 = ON */

    /* ---- Main polling loop ---- */
    while (g_running) {
        int sensor_value = read_sensor();
        if (sensor_value < 0) {
            /* Sensor read error — wait and retry rather than crash */
            gpioDelay(POLL_US);
            continue;
        }

        /* KY022 is active-low: obstacle present when sensor reads LOW */
        if (sensor_value == 0) {
            relay_state = !relay_state;
            if (write_relay(relay_state) == 0) {
                const char *msg = relay_state ? "ON" : "OFF";
                log_event(msg);
                printf("Obstacle detected → relay %s\n", msg);
            }
        }

        gpioDelay(POLL_US);
    }

    /* ---- Clean shutdown ---- */
    gpioWrite(RELAY_PIN, 0);   /* ensure relay is OFF */
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

