/*
 * PIR Motion Detector with Buzzer Alarm
 * Board:  Raspberry Pi 4 Model B
 * PIR:    HC-SR501 on GPIO17 (BCM), active-high 3.3 V output
 * Buzzer: 5 V on GPIO18 (BCM)
 * Build:  gcc -O2 -Wall -o pir_buzzer pir_buzzer.c -lpigpio -lrt
 * Run:    sudo ./pir_buzzer
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PIR_PIN      17
#define BUZZER_PIN   18
#define BUZZER_MS    2000          /* buzzer on time in milliseconds */
#define POLL_MS      100           /* polling interval in milliseconds */
#define LOG_FILE     "motion_log.txt"

static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — graceful shutdown                                   */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a timestamped entry to the log file                            */
/* ------------------------------------------------------------------ */
static int log_motion(void)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        perror("time");
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        perror("localtime_r");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(g_log, "%s Motion detected\n", ts) < 0) {
        perror("fprintf");
        return -1;
    }

    if (fflush(g_log) != 0) {
        perror("fflush");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Activate the buzzer for BUZZER_MS milliseconds                      */
/* ------------------------------------------------------------------ */
static int activate_buzzer(int duration_ms)
{
    if (gpioWrite(BUZZER_PIN, 1) != 0) {
        fprintf(stderr, "gpioWrite(buzzer ON) failed\n");
        return -1;
    }

    usleep(duration_ms * 1000);

    if (gpioWrite(BUZZER_PIN, 0) != 0) {
        fprintf(stderr, "gpioWrite(buzzer OFF) failed\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call multiple times                        */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Ensure buzzer is off */
    gpioWrite(BUZZER_PIN, 0);

    if (g_log != NULL) {
        fclose(g_log);
        g_log = NULL;
    }

    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed (run as root?)\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure GPIO pins ---- */
    if (gpioSetMode(PIR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(PIR_PIN=%d) failed\n", PIR_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(BUZZER_PIN=%d) failed\n", BUZZER_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Start with buzzer off */
    if (gpioWrite(BUZZER_PIN, 0) != 0) {
        fprintf(stderr, "gpioWrite(BUZZER_PIN, 0) initial state failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log = fopen(LOG_FILE, "a");
    if (g_log == NULL) {
        perror("fopen(" LOG_FILE ")");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("PIR motion detector running.  PIR=GPIO%d  Buzzer=GPIO%d  Log=%%s\n",
           PIR_PIN, BUZZER_PIN, LOG_FILE);
    printf("Press Ctrl-C to exit.\n");

    /* ---- Main polling loop ---- */
    while (g_running) {
        int pir = gpioRead(PIR_PIN);
        if (pir < 0) {
            fprintf(stderr, "gpioRead(PIR_PIN=%d) failed\n", PIR_PIN);
            break;
        }

        if (pir == 1) {
            printf("Motion detected!\n");

            if (activate_buzzer(BUZZER_MS) != 0) {
                fprintf(stderr, "Buzzer activation failed\n");
                break;
            }

            if (log_motion() != 0) {
                fprintf(stderr, "Logging failed\n");
                break;
            }
        }

        usleep(POLL_MS * 1000);
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

