/*
 * Timed Watering System — Raspberry Pi 3 Model B+
 * Valve: Parker Hannifin Series 9 General Purpose Miniature Solenoid Valve
 *   (12 V, 1.6 W) via external N-channel MOSFET or relay module
 *   -> GPIO18 (BCM), active-low logic (0 = off, 1 = on)
 * Duration is read from watering.conf (duration=<seconds>)
 * Build: gcc -O2 -Wall -Wextra -o watering watering.c
 */

#define _POSIX_C_SOURCE 200809L

#include <errno.h>
#include <fcntl.h>
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#include <gpiod.h>

#define GPIO_CHIP_NAME  "gpiochip0"
#define GPIO_LINE_OFFSET 18
#define CONFIG_FILE     "watering.conf"
#define MIN_DURATION    1
#define MAX_DURATION    3600
#define POLL_INTERVAL_US 100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

static int read_config(const char *filename, int *duration)
{
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Error opening config file '%s': %s\n",
                filename, strerror(errno));
        return -1;
    }

    char line[256];
    int found = 0;

    while (fgets(line, sizeof(line), fp)) {
        /* Strip trailing newline */
        line[strcspn(line, "\r\n")] = '\0';

        if (strncmp(line, "duration=", 9) == 0) {
            char *endptr = NULL;
            errno = 0;
            long val = strtol(line + 9, &endptr, 10);
            if (errno != 0 || endptr == line + 9 || *endptr != '\0') {
                fprintf(stderr, "Invalid duration value in config: '%s'\n", line);
                fclose(fp);
                return -1;
            }
            if (val < MIN_DURATION || val > MAX_DURATION) {
                fprintf(stderr, "Duration out of range: %ld (must be %d–%d)\n",
                        val, MIN_DURATION, MAX_DURATION);
                fclose(fp);
                return -1;
            }
            *duration = (int)val;
            found = 1;
            break;
        }
    }

    if (!found) {
        fprintf(stderr, "Config file '%s' does not contain 'duration=' line.\n", filename);
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

static int set_gpio(struct gpiod_line *line, int value)
{
    if (gpiod_line_set_value(line, value) < 0) {
        fprintf(stderr, "Error setting GPIO line value to %d: %s\n",
                value, strerror(errno));
        return -1;
    }
    return 0;
}

static int sleep_duration(int seconds)
{
    struct timespec req = {
        .tv_sec  = seconds,
        .tv_nsec = 0
    };
    struct timespec rem;

    while (nanosleep(&req, &rem) == -1) {
        if (errno != EINTR) {
            fprintf(stderr, "nanosleep failed: %s\n", strerror(errno));
            return -1;
        }
        if (!g_running) {
            return 0;
        }
        req = rem;
    }
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_output(line, "watering-system", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    int duration = 0;
    if (read_config(CONFIG_FILE, &duration) != 0) {
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Watering duration: %d seconds\n", duration);
    printf("Starting watering cycle...\n");

    if (set_gpio(line, 1) < 0) {
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (sleep_duration(duration) < 0) {
        set_gpio(line, 0);
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    if (set_gpio(line, 0) < 0) {
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Watering cycle complete.\n");

    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return EXIT_SUCCESS;
}

