/*
 * Line-follower robot for Raspberry Pi Zero W
 * Sensor : Keywish 3-Way IR Tracking Sensor (active-low digital outputs)
 * Driver : L298N dual H-bridge (PWM-capable)
 * Bus    : GPIO / PWM bus (BCM numbering)
 *
 * Wiring (BCM):
 *   Left sensor  -> GPIO4  (active-low)
 *   Middle sensor-> GPIO17 (active-low)
 *   Right sensor -> GPIO27 (active-low)
 *   PWM left     -> GPIO22 (PWM0)
 *   PWM right    -> GPIO23 (PWM1)
 *   PWM enable   -> GPIO24 (PWM0_EN)
 *   PWM enable   -> GPIO25 (PWM1_EN)
 *
 * Build: gcc -O2 -Wall -o line_follower line_follower.c -lpigpio -lrt
 * Run  : sudo ./line_follower
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define LEFT_SENSOR_PIN  4
#define MIDDLE_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN  27
#define PWM_LEFT_PIN      22
#define PWM_RIGHT_PIN     23
#define PWM_ENABLE_LEFT   24
#define PWM_ENABLE_RIGHT  25

/* ---- Motor speeds (0-255) ---- */
#define BASE_SPEED       150
#define TURN_SPEED_LEFT  128   /* 50 % of base speed */
#define TURN_SPEED_RIGHT 128   /* 50 % of base speed */

/* ---- Sampling / timing ---- */
#define SAMPLE_PERIOD_US 10000   /* 10 ms */
#define PWM_FREQUENCY     1000   /* Hz */

/* ---- Globals ---- */
static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Motor helpers ---- */
static void motor_stop(void)
{
    gpioPWM(PWM_LEFT_PIN, 0);
    gpioPWM(PWM_RIGHT_PIN, 0);
    gpioPWM(PWM_ENABLE_LEFT, 0);
    gpioPWM(PWM_ENABLE_RIGHT, 0);
}

static void motor_set_speed(int left_speed, int right_speed)
{
    if (left_speed < 0)   left_speed = 0;
    if (right_speed < 0)  right_speed = 0;
    if (left_speed > 255) left_speed = 255;
    if (right_speed > 255) right_speed = 255;

    gpioPWM(PWM_LEFT_PIN,   left_speed);
    gpioPWM(PWM_RIGHT_PIN,  right_speed);
    gpioPWM(PWM_ENABLE_LEFT, left_speed);
    gpioPWM(PWM_ENABLE_RIGHT, right_speed);
}

/* ---- Sensor reading (active-low) ---- */
static int read_sensor(int pin)
{
    int v = gpioRead(pin);
    return (v == 0) ? 1 : 0;   /* active-low: 1 = sensor detected */
}

/* ---- Logging ---- */
static void log_data(int left, int middle, int right, int left_speed, int right_speed)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(g_log_file, "%s,%d,%d,%d,%d,%d\n",
            timestamp, left, middle, right, left_speed, right_speed);
    fflush(g_log_file);
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    motor_stop();
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ---- Main ---- */
int main(void)
{
    int left, middle, right;
    int left_speed, right_speed;

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure sensor pins as inputs ---- */
    if (gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT) != 0 ||
        gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT) != 0 ||
        gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set sensor pin modes.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Configure PWM pins as outputs ---- */
    if (gpioSetMode(PWM_LEFT_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(PWM_RIGHT_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(PWM_ENABLE_LEFT, PI_OUTPUT) != 0 ||
        gpioSetMode(PWM_ENABLE_RIGHT, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set PWM pin modes.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Set PWM frequency ---- */
    if (gpioSetPWMfrequency(PWM_LEFT_PIN, PWM_FREQUENCY) != 0 ||
        gpioSetPWMfrequency(PWM_RIGHT_PIN, PWM_FREQUENCY) != 0) {
        fprintf(stderr, "Error: failed to set PWM frequency.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_file = fopen("trace_log.txt", "a");
    if (!g_log_file) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Install signal handler ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Warning: failed to install SIGINT handler");
    }

    printf("Line-follower running. Press Ctrl+C to stop.\n");

    /* ---- Main control loop ---- */
    while (g_running) {
        left  = read_sensor(LEFT_SENSOR_PIN);
        middle = read_sensor(MIDDLE_SENSOR_PIN);
        right = read_sensor(RIGHT_SENSOR_PIN);

        /* ---- Control law ---- */
        if (middle) {
            /* Middle sensor active: drive straight at base speed */
            left_speed = right_speed = BASE_SPEED;
        } else if (left) {
            /* Only left sensor active: turn right */
            left_speed = 0;
            right_speed = TURN_SPEED_LEFT;
        } else if (right) {
            /* Only right sensor active: turn left */
            left_speed = TURN_SPEED_RIGHT;
            right_speed = 0;
        } else {
            /* No sensor active: stop */
            left_speed = right_speed = 0;
        }

        motor_set_speed(left_speed, right_speed);
        log_data(left, middle, right, left_speed, right_speed);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

