#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x10
#define GPIO_RELAY 23
#define LUX_THRESHOLD 150
#define LOG_FILE "grow_log.txt"
#define MEASUREMENT_DELAY_MS 180
#define POLL_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *msg) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char tbuf[32];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(fp, "%s.%03ld: %s\n", tbuf, ts.tv_nsec / 1000000, msg);
    fclose(fp);
}

static int read_bh1750(int fd, float *lux) {
    unsigned char cmd = 0x10;
    if (write(fd, &cmd, 1) != 1) {
        log_event("I2C write error");
        return -1;
    }
    usleep(MEASUREMENT_DELAY_MS * 1000);
    unsigned char buf[2];
    if (read(fd, buf, 2) != 2) {
        log_event("I2C read error");
        return -1;
    }
    unsigned int raw = ((unsigned int)buf[0] << 8) | buf[1];
    *lux = (float)raw / 1.2f;
    return 0;
}

static void control_relay(int gpio, int state) {
    if (gpioWrite(gpio, state) != 0) {
        log_event("GPIO write error");
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", BH1750_ADDR, strerror(errno));
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(GPIO_RELAY, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", GPIO_RELAY);
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }
    gpioWrite(GPIO_RELAY, 0);

    log_event("Program started");

    int relay_state = 0;
    while (running) {
        float lux;
        if (read_bh1750(i2c_fd, &lux) == 0) {
            char msg[128];
            snprintf(msg, sizeof(msg), "Lux: %.2f", lux);
            log_event(msg);
            if (lux < LUX_THRESHOLD && relay_state == 0) {
                control_relay(GPIO_RELAY, 1);
                relay_state = 1;
                log_event("Grow lamp turned on");
            } else if (lux >= LUX_THRESHOLD && relay_state == 1) {
                control_relay(GPIO_RELAY, 0);
                relay_state = 0;
                log_event("Grow lamp turned off");
            }
        } else {
            log_event("Sensor read failed, continuing");
        }
        usleep(POLL_INTERVAL_US);
    }

    control_relay(GPIO_RELAY, 0);
    log_event("Program stopped");
    close(i2c_fd);
    gpioTerminate();
    return 0;
}

