/*
 * Door lock control using a servo motor on a Raspberry Pi.
 *
 * Wiring (BCM numbering):
 *   GPIO18  -> Servo signal (PWM)
 *   GPIO21  -> Lock button (active-low, pull-up)
 *   GPIO22  -> Unlock button (active-low, pull-up)
 *
 * Servo: 1000 us pulse width  -> lock (0 degrees)
 *         2000 us pulse width -> unlock (180 degrees)
 *         500 us or 2500 us     -> invalid (error)
 *
 * Build:  gcc -O2 -Wall -Wextra -o door_lock door_lock.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <pigpio.h>

#define SERVO_PIN      18
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22

#define SERVO_MIN_PULSE_WIDTH  1000   /* 0 degrees   */
#define SERVO_MAX_PULSE_WIDTH  2000   /* 180 degrees */
#define SERVO_SAFE_MIN_PULSE_WIDTH 500
#define SERVO_SAFE_MAX_PULSE_WIDTH 2500

#define DEBOUNCE_DELAY_US  100000   /* 100 ms        */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int set_servo_pulse_width(int pin, int pulse_width_us)
{
    if (pulse_width_us < SERVO_SAFE_MIN_PULSE_WIDTH ||
        pulse_width_us > SERVO_SAFE_MAX_PULSE_WIDTH) {
        fprintf(stderr, "Error: pulse width %d us out of safe range "
                        "[%d, %d] on GPIO %d\n",
                pulse_width_us, SERVO_SAFE_MIN_PULSE_WIDTH,
                SERVO_SAFE_MAX_PULSE_WIDTH, pin);
        return -1;
    }

    if (gpioServo(pin, pulse_width_us) < 0) {
        fprintf(stderr, "Error: gpioServo failed on GPIO %d (pulse %d us)\n",
                pin, pulse_width_us);
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    /* Stop PWM signal on the servo pin before terminating pigpio. */
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
}

int main(void)
{
    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Configure button pins as inputs with pull-up --- */
    if (gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input.\n",
                LOCK_BUTTON_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input.\n",
                UNLOCK_BUTTON_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO %d.\n",
                LOCK_BUTTON_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO %d.\n",
                UNLOCK_BUTTON_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Configure servo pin as output --- */
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n",
                SERVO_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Ensure servo is not actively driving the pin at startup --- */
    if (gpioServo(SERVO_PIN, 0) < 0) {
        fprintf(stderr, "Warning: initial gpioServo call failed "
                        "(pigpio may be in a non-interactive mode).\n");
    }

    printf("Door lock control ready.\n");
    printf("  Lock button : GPIO%d (active-low, pull-up)\n", LOCK_BUTTON_PIN);
    printf("  Unlock button: GPIO%d (active-low, pull-up)\n", UNLOCK_BUTTON_PIN);
    printf("  Servo pin   : GPIO%d\n", SERVO_PIN);
    printf("Press Ctrl+C to exit.\n");

    bool lock_pressed = false;
    bool unlock_pressed = false;

    while (g_running) {
        int lock_state = gpioRead(LOCK_BUTTON_PIN);
        int unlock_state = gpioRead(UNLOCK_BUTTON_PIN);

        if (lock_state == 0 && !lock_pressed) {
            /* Button pressed (active-low) */
            printf("Lock button pressed. Setting servo to %d us.\n",
                   SERVO_MIN_PULSE_WIDTH);
            if (set_servo_pulse_width(SERVO_PIN, SERVO_MIN_PULSE_WIDTH) == 0) {
                lock_pressed = true;
            } else {
                fprintf(stderr, "Error: failed to set servo to lock position.\n");
            }
            gpioDelay(DEBOUNCE_DELAY_US);
        }

        if (unlock_state == 0 && !unlock_pressed) {
            /* Button pressed (active-low) */
            printf("Unlock button pressed. Setting servo to %d us.\n",
                   SERVO_MAX_PULSE_WIDTH);
            if (set_servo_pulse_width(SERVO_PIN, SERVO_MAX_PULSE_WIDTH) == 0) {
                unlock_pressed = true;
            } else {
                fprintf(stderr, "Error: failed to set servo to unlock position.\n");
            }
            gpioDelay(DEBOUNCE_DELAY_US);
        }

        /* Reset pressed flags when button is released */
        if (lock_state == 1) {
            lock_pressed = false;
        }
        if (unlock_state == 1) {
            unlock_pressed = false;
        }

        gpioDelay(10000); /* 10 ms poll interval */
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

