            if (set_servo_pulse_width(SERVO_PIN, SERVO_MAX_PULSE_WIDTH) == 0) {
                unlock_pressed = true;
            } else {
                fprintf(stderr, "Error: failed to set servo to unlock position.\n");
            }
            gpioDelay(DEBOUNCE_DELAY_US);
        }

        /* Reset pressed flags when button is released */
        if (lock_state == 1) {
            lock_pressed = false;
        }
        if (unlock_state == 1) {
            unlock_pressed = false;
        }

        gpioDelay(10000); /* 10 ms poll interval */
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

