/*
 * Haptic feedback system for Raspberry Pi 4 Model B
 *
 * Two Precision Microdrives 310-101 vibration motors are driven through
 * external driver circuits on GPIO17 (BCM) and GPIO27 (BCM).
 *
 * Build:  gcc -O2 -Wall -Wextra -o vib_haptic vib_haptic.c -lpigpio -lrt
 * Run:    sudo ./vib_haptic
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <pigpio.h>

#define MOTOR1_PIN 17
#define MOTOR2_PIN 27

#define MOTOR1_DURATION_MS  200
#define MOTOR2_DURATION_MS  300

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(MOTOR1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", MOTOR1_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(MOTOR2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", MOTOR2_PIN);
        gpioTerminate();
        return -1;
    }

    /* Ensure both pins start in a known low state. */
    if (gpioWrite(MOTOR1_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise GPIO%d low.\n", MOTOR1_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(MOTOR2_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise GPIO%d low.\n", MOTOR2_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int drive_motor(int pin, int duration_ms)
{
    if (gpioWrite(pin, 1) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d high.\n", pin);
        return -1;
    }
    gpioDelay((unsigned)duration_ms * 1000);
    if (gpioWrite(pin, 0) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d low.\n", pin);
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    /* Stop both motors and release the GPIO lines. */
    gpioWrite(MOTOR1_PIN, 0);
    gpioWrite(MOTOR2_PIN, 0);
    gpioTerminate();
}

int main(void)
{
    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Haptic feedback system started. Press Ctrl+C to exit.\n");

    while (g_running) {
        if (drive_motor(MOTOR1_PIN, MOTOR1_DURATION_MS) != 0) {
            cleanup();
            return EXIT_FAILURE;
        }
        if (!g_running) {
            break;
        }
        if (drive_motor(MOTOR2_PIN, MOTOR2_DURATION_MS) != 0) {
            cleanup();
            return EXIT_FAILURE;
        }
    }

    cleanup();
    printf("Haptic feedback system stopped.\n");
    return EXIT_SUCCESS;
}

