/*
 * sound_alarm.c — Sound-triggered alarm for Raspberry Pi 5
 *
 * Build:  gcc -O2 -Wall -Wextra -o sound_alarm sound_alarm.c
 * Run:    ./sound_alarm --sound_sensor
 *         ./sound_alarm --alarm_node
 *
 * GPIO wiring (BCM numbering):
 *   GPIO17 (BCM) — LM393 sound sensor digital output (active-low)
 *   GPIO27 (BCM) — Alarm LED (active-high)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <fcntl.h>
#include <sys/socket.h>
#include <sys/ioctl.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <zmq.h>

/* ---- Configuration ---- */
#define GPIO_CHIP_NAME      "gpiochip4"   /* RP1 GPIO controller on Pi 5 */
#define SOUND_SENSOR_PIN    17            /* BCM 17 — LM393 digital out */
#define ALARM_LED_PIN       27            /* BCM 27 — alarm LED */
#define SOUND_ALERTS_TOPIC  "SOUND_ALERTS"
#define ZMQ_PORT            5555
#define POLL_INTERVAL_US    10000         /* 10 ms */
#define LED_ON_TIME_S        1            /* seconds */

/* ---- Globals for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static int g_gpio_fd = -1;
static int g_zmq_ctx = -1;
static int g_zmq_sock = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int gpio_init(void)
{
    g_gpio_fd = open("/dev/gpiochip4", O_RDWR);
    if (g_gpio_fd < 0) {
        perror("open /dev/gpiochip4");
        return -1;
    }

    unsigned int pins[2] = { SOUND_SENSOR_PIN, ALARM_LED_PIN };
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        unsigned int p = pins[i];
        if (ioctl(g_gpio_fd, GPIO_GET_LINE, &p) < 0) {
            perror("GPIO_GET_LINE");
            close(g_gpio_fd);
            g_gpio_fd = -1;
            return -1;
        }
        if (ioctl(g_gpio_fd, GPIO_SET_DIRECTION, &p) < 0) {
            perror("GPIO_SET_DIRECTION");
            close(g_gpio_fd);
            g_gpio_fd = -1;
            return -1;
        }
        if (ioctl(g_gpio_fd, GPIO_SET_OUTPUT, &p) < 0) {
            perror("GPIO_SET_OUTPUT");
            close(g_gpio_fd);
            g_gpio_fd = -1;
            return -1;
        }
        if (ioctl(g_gpio_fd, GPIO_SET_VALUE, &p) < 0) {
            perror("GPIO_SET_VALUE");
            close(g_gpio_fd);
            g_gpio_fd = -1;
            return -1;
        }
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int gpio_read(unsigned int pin)
{
    int v;
    if (ioctl(g_gpio_fd, GPIO_GET_LINE, &pin) < 0) {
        perror("GPIO_GET_LINE");
        return -1;
    }
    if (ioctl(g_gpio_fd, GPIO_GET_VALUE, &v) < 0) {
        perror("GPIO_GET_VALUE");
        return -1;
    }
    return v;
}

/* ------------------------------------------------------------------ */
static int gpio_write(unsigned int pin, int value)
{
    int v;
    if (ioctl(g_gpio_fd, GPIO_GET_LINE, &pin) < 0) {
        perror("GPIO_GET_LINE");
        return -1;
    }
    if (ioctl(g_gpio_fd, GPIO_SET_VALUE, &v) < 0) {
        perror("GPIO_SET_VALUE");
        return -1;
    }
    if (value != v) {
        if (ioctl(g_gpio_fd, GPIO_SET_VALUE, &value) < 0) {
            perror("GPIO_SET_VALUE");
            return -1;
        }
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int zmq_init(void)
{
    g_zmq_ctx = zmq_ctx_new();
    if (!g_zmq_ctx) {
        perror("zmq_ctx_new");
        return -1;
    }

    g_zmq_sock = zmq_socket(g_zmq_ctx, ZMQ_SOCKET_TYPE_CLIENT);
    if (g_zmq_sock < 0) {
        perror("zmq_socket");
        zmq_ctx_destroy(g_zmq_ctx);
        g_zmq_ctx = NULL;
        return -1;
    }

    int rc = zmq_connect(g_zmq_sock, "tcp://localhost:%d",
                         ZMQ_CONNECT_TIMEOUT);
    if (rc != 0) {
        fprintf(stderr, "zmq_connect failed: %s\n", zmq_strerror(rc));
        zmq_close(g_zmq_sock);
        g_zmq_sock = -1;
        zmq_ctx_destroy(g_zmq_ctx);
        g_zmq_ctx = NULL;
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static void zmq_close_socket(void)
{
    if (g_zmq_sock >= 0) {
        zmq_close(g_zmq_sock);
        g_zmq_sock = -1;
    }
}

/* ------------------------------------------------------------------ */
static void zmq_ctx_destroy(void)
{
    if (g_zmq_ctx >= 0) {
        zmq_ctx_destroy(g_zmq_ctx);
        g_zmq_ctx = -1;
    }
}

/* ------------------------------------------------------------------ */
static int zmq_send_alert(void)
{
    char message[256];
    int len = snprintf(message, sizeof(message),
                       "Sound detected on GPIO%d\n", SOUND_SENSOR_PIN);
    if (len < 0 || (size_t)len >= sizeof(message)) {
        fprintf(stderr, "snprintf failed\n");
        return -1;
    }

    int rc = zmq_send(g_zmq_sock, message, (size_t)len, 0);
    if (rc != (int)len) {
        perror("zmq_send");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_gpio_fd >= 0) {
        (void)gpio_write(ALARM_LED_PIN, 0);
        close(g_gpio_fd);
        g_gpio_fd = -1;
    }
    if (g_zmq_sock >= 0) {
        zmq_close(g_zmq_sock);
        g_zmq_sock = -1;
    }
    if (g_zmq_ctx >= 0) {
        zmq_ctx_destroy(g_zmq_ctx);
        g_zmq_ctx = -1;
    }
}

/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    const char *mode = (argc > 1) ? argv[1] : "sound_sensor";
    const char *help = "--help";

    if (strcmp(mode, "--help") == 0 || strcmp(mode, "-h") == 0) {
        printf("Usage: %s [--sound_sensor] | [--alarm_node]\n", argv[0]);
        return EXIT_SUCCESS;
    }

    if (strcmp(mode, "--sound_sensor") == 0) {
        printf("Mode: sound_sensor\n");
    } else if (strcmp(mode, "--alarm_node") == 0) {
        printf("Mode: alarm_node\n");
    } else {
        fprintf(stderr, "Invalid mode: %s\n", mode);
        return EXIT_FAILURE;
    }

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction SIGINT");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction SIGTERM");
        return EXIT_FAILURE;
    }

    /* ---- GPIO init ---- */
    if (gpio_init() < 0) {
        return EXIT_FAILURE;
    }

    /* ---- ZeroMQ init ---- */
    if (zmq_init() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Main loop ---- */
    while (g_running) {
        if (strcmp(mode, "--sound_sensor") == 0) {
            int val = gpio_read(SOUND_SENSOR_PIN);
            if (val < 0) {
                fprintf(stderr, "GPIO read error\n");
                break;
            }
            if (val == 0) {                 /* active-low: 0 = sound detected */
                if (zmq_send_alert() < 0) {
                    fprintf(stderr, "Failed to send alert\n");
                    break;
                }
            }
        } else {                            /* alarm_node: subscribe */
            char message[256];
            int rc = zmq_recv(g_zmq_sock, message, sizeof(message) - 1,
                              0);
            if (rc < 0) {
                perror("zmq_recv");
                break;
            }
            if (rc == 0) {
                fprintf(stderr, "Empty message received\n");
                continue;
            }
            printf("Received: %s\n", message);
            if (gpio_write(ALARM_LED_PIN, 1) < 0) {
                fprintf(stderr, "Failed to turn on LED\n");
                break;
            }
            sleep(LED_ON_TIME_S);
            if (gpio_write(ALARM_LED_PIN, 0) < 0) {
                fprintf(stderr, "Failed to turn off LED\n");
                break;
            }
        }
        usleep(POLL_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

