    }

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction SIGINT");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction SIGTERM");
        return EXIT_FAILURE;
    }

    /* ---- GPIO init ---- */
    if (gpio_init() < 0) {
        return EXIT_FAILURE;
    }

    /* ---- ZeroMQ init ---- */
    if (zmq_init() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Main loop ---- */
    while (g_running) {
        if (strcmp(mode, "--sound_sensor") == 0) {
            int val = gpio_read(SOUND_SENSOR_PIN);
            if (val < 0) {
                fprintf(stderr, "GPIO read error\n");
                break;
            }
            if (val == 0) {                 /* active-low: 0 = sound detected */
                if (zmq_send_alert() < 0) {
                    fprintf(stderr, "Failed to send alert\n");
                    break;
                }
            }
        } else {                            /* alarm_node: subscribe */
            char message[256];
            int rc = zmq_recv(g_zmq_sock, message, sizeof(message) - 1,
                              0);
            if (rc < 0) {
                perror("zmq_recv");
                break;
            }
            if (rc == 0) {
                fprintf(stderr, "Empty message received\n");
                continue;
            }
            printf("Received: %s\n", message);
            if (gpio_write(ALARM_LED_PIN, 1) < 0) {
                fprintf(stderr, "Failed to turn on LED\n");
                break;
            }
            sleep(LED_ON_TIME_S);
            if (gpio_write(ALARM_LED_PIN, 0) < 0) {
                fprintf(stderr, "Failed to turn off LED\n");
                break;
            }
        }
        usleep(POLL_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

