/*
 * NEC IR Remote Decoder for Raspberry Pi 3 Model B+
 * IR receiver: TSOP38238 on GPIO17 (BCM)
 * Decoder:  NEC protocol (9 ms mark, 4.5 ms space header,
 *            560 us mark for each bit, 1690 us space = logic 1,
 *            560 us space = logic 0)
 * Output:  decoded command (32-bit) published to MQTT broker
 *
 * Build:  gcc -O2 -Wall -Wextra -o ir_decoder ir_decoder.c -lm
 * Run:    sudo ./ir_decoder
 */

#include <stdio.h>
