#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MULTICAST_ADDR  "239.255.255.250"
#define MULTICAST_PORT  5005
#define NUM_SENSORS     4
#define BH1750_CONV_MS  180
#define LOOP_DELAY_S    1

static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

static int i2c_open(int bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int bh1750_read(int fd, float *lux)
{
    uint8_t cmd[2] = { 0x10, 0x00 };
    if (write(fd, cmd, 2) != 2) {
        fprintf(stderr, "BH1750 write failed: %s\n", strerror(errno));
        return -1;
    }
    usleep(BH1750_CONV_MS * 1000);

    uint8_t buf[2];
    ssize_t n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "BH1750 read failed (got %zd bytes): %s\n",
                n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }
    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux = (float)raw / 1.2f;
    return 0;
}

static int udp_init(void)
{
    int sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock < 0) {
        perror("socket");
        return -1;
    }
    int ttl = 1;
    if (setsockopt(sock, IPPROTO_IP, IP_MULTICAST_TTL, &ttl, sizeof(ttl)) < 0) {
        perror("setsockopt(IP_MULTICAST_TTL)");
        close(sock);
        return -1;
    }
    return sock;
}

static void udp_send(int sock, const char *data)
{
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port   = htons(MULTICAST_PORT);
    if (inet_pton(AF_INET, MULTICAST_ADDR, &addr.sin_addr) != 1) {
        fprintf(stderr, "inet_pton(%s) failed\n", MULTICAST_ADDR);
        return;
    }
    if (sendto(sock, data, strlen(data), 0,
               (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("sendto");
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int i2c_fds[NUM_SENSORS];
    for (int i = 0; i < NUM_SENSORS; i++)
        i2c_fds[i] = -1;

    for (int i = 0; i < NUM_SENSORS; i++)
        i2c_fds[i] = i2c_open(I2C_BUS, 0x20 + i);

    int udp_sock = udp_init();
    if (udp_sock < 0) {
        for (int i = 0; i < NUM_SENSORS; i++)
            close(i2c_fds[i]);
        return EXIT_FAILURE;
    }

    while (!terminate) {
        char data[256];
        int idx = 0;
        for (int s = 0; s < NUM_SENSORS; s++) {
            if (i2c_fds[s] < 0) {
                if (idx > 0) data[idx - 1] = ',';
                data[idx++] = '0';
                data[idx] = '\0';
                continue;
            }
            float lux;
            if (bh1750_read(i2c_fds[s], &lux) < 0) {
                if (idx > 0) data[idx - 1] = ',';
                data[idx++] = '0';
                data[idx] = '\0';
                continue;
            }
            if (idx > 0) data[idx - 1] = ';';
            int len = snprintf(data + idx, sizeof(data) - idx, "%d,%.1f", s + 1, lux);
            if (len < 0 || (size_t)len >= sizeof(data) - idx) {
                if (idx > 0) data[idx - 1] = ',';
                data[idx++] = '0';
                data[idx] = '\0';
                continue;
            }
            idx += len;
        }
        if (idx > 0) data[idx - 1] = '\0';

        udp_send(udp_sock, data);
        sleep(LOOP_DELAY_S);
    }

    for (int i = 0; i < NUM_SENSORS; i++)
        close(i2c_fds[i]);
    close(udp_sock);
    return EXIT_SUCCESS;
}

