/*
 * Raspberry Pi Zero W – Honeywell AWM7300V mass airflow sensor logger
 *
 * Wiring:
 *   AWM7300V SDA  -> GPIO2  (pin 3, I2C bus 1 SDA)
 *   AWM7300V SCL  -> GPIO3  (pin 5, I2C bus 1 SCL)
 *   AWM7300V VDD  -> 3.3 V
 *   AWM7300V GND  -> GND
 *
 * Build:  gcc -O2 -Wall -Wextra -o airflow_logger airflow_logger.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define LOG_FILE       "airflow_log.txt"
#define READ_INTERVAL  1          /* seconds between readings */
#define MAX_RETRIES    3
#define RETRY_DELAY_MS 100        /* 100 ms between retries */

/* AWM7300V register addresses (from datasheet) */
#define AWM7300V_REG_FLOW_MSB  0x00
#define AWM7300V_REG_FLOW_LSB  0x01

/* MUX channel 0: 14-bit flow resolution, 0.5 SLPM resolution */
#define AWM7300V_MUX_CH0     0x00

/* 14-bit flow value from the two data bytes (upper 14 bits) */
#define FLOW_MASK 0x3FFF

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Write a zero-length I2C transaction to generate a start condition.   */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int i2c_start(void)
{
    if (ioctl(g_i2c_fd, I2C_SLAVE, AWM7300V_REG_FLOW_MSB) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                AWM7300V_REG_FLOW_MSB, strerror(errno));
        return -1;
    }

    /* Zero-length write – this generates a start condition. */
    if (write(g_i2c_fd, NULL, 0) < 0) {
        fprintf(stderr, "I2C start condition write failed: %s\n",
                strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read two bytes from the sensor and convert to SLPM.                */
/* Returns 0 on success and stores flow in *out_slpm; -1 on error.     */
/* ------------------------------------------------------------------ */
static int read_airflow(float *out_slpm)
{
    uint8_t buf[2];
    int  rc;

    for (int attempt = 1; attempt <= MAX_RETRIES; ++attempt) {
        rc = i2c_start();
        if (rc != 0)
            goto retry;

        /* Read two data bytes (MSB first). */
        ssize_t n = read(g_i2c_fd, buf, sizeof(buf));
        if (n == (ssize_t)sizeof(buf)) {
            uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
            *out_slpm = (float)(raw & FLOW_MASK) / 4.0f;
            return 0;
        }

retry:
        if (n < 0)
            fprintf(stderr, "I2C read failed (attempt %d/%d): %s\n",
                    attempt, MAX_RETRIES, strerror(errno));
        else
            fprintf(stderr, "I2C read short: %zd bytes (attempt %d/%d)\n",
                    n, attempt, MAX_RETRIES);

        if (attempt < MAX_RETRIES)
            usleep(RETRY_DELAY_MS * 1000);
    }

    return -1;
}

/* ------------------------------------------------------------------ */
static void log_airflow(float slpm)
{
    time_t     now;
    struct tm  tm_info;
    char       ts[32];

    time(&now);
    localtime_r(&now, &tm_info);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(g_log_fp, "%s,%.2f\n", ts, slpm);
    fflush(g_log_fp);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Signal handling ------------------------------------------ */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open log file --------------------------------------------- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus --------------------------------------------- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Configure sensor: MUX channel 0 -------------------------- */
    if (ioctl(g_i2c_fd, I2C_SLAVE, AWM7300V_REG_FLOW_MSB) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                AWM7300V_REG_FLOW_MSB, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* MUX channel 0: 14-bit flow resolution, 0.5 SLPM resolution. */
    uint8_t mux_cmd = AWM7300V_MUX_CH0;
    if (write(g_i2c_fd, &mux_cmd, 1) != 1) {
        fprintf(stderr, "Failed to set MUX channel 0: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("AWM7300V logger started. Logging to %s every %d s.\n",
           LOG_FILE, READ_INTERVAL);
    printf("Press Ctrl+C to stop.\n");

    /* ---- Main loop ------------------------------------------------- */
    while (g_running) {
        float slpm;
        if (read_airflow(&slpm) == 0) {
            log_airflow(slpm);
            printf("Flow: %.2f SLPM\n", slpm);
        } else {
            fprintf(stderr, "Sensor read failed after %d retries; "
                            "continuing.\n", MAX_RETRIES);
        }
        sleep(READ_INTERVAL);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

