#define AS7341_ID_VALUE        0x44
#define AS7341_ENABLE_PON      0x01
#define AS7341_ENABLE_SP_EN    0x02
#define AS7341_SMUX_CLEAR      0x01
#define AS7341_SMUX_F1          0x02
#define AS7341_SMUX_F2          0x04
#define AS7341_SMUX_F3          0x08
#define AS7341_SMUX_F4          0x10
#define AS7341_SMUX_F5          0x20
#define AS7341_SMUX_F6          0x40
#define AS7341_SMUX_F7          0x80
#define AS7341_SMUX_F8          0x00
#define AS7341_SMUX_NIR         0x00
#define AS7341_SMUX_CLEAR_NIR    0x03

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read16 from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *value = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor initialization                                               */
/* ------------------------------------------------------------------ */
static int sensor_init(int fd)
{
    uint8_t id = 0;

    /* Verify device identity */
    if (i2c_read_reg8(fd, AS7341_REG_IDENT, &id) != 0) {
        fprintf(stderr, "Cannot read AS7341 ID register.\n");
        return -1;
    }
    if (id != AS7341_ID_VALUE) {
        fprintf(stderr, "Unexpected AS7341 ID: 0x%02X (expected 0x%02X).\n",
                id, AS7341_ID_VALUE);
        return -1;
    }
    printf("AS7341 detected (ID = 0x%02X).\n", id);

    /* Power on */
    if (i2c_write_reg8(fd, AS7341_REG_ENABLE, AS7341_ENABLE_PON) != 0)
        return -1;
    usleep(10000);  /* 10 ms settle */

    /* Clear spectral measurement mode */
    if (i2c_write_reg8(fd, AS7341_REG_SMUX, AS7341_SMUX_CLEAR) != 0)
        return -1;

    /* Enable spectral measurement (F1-F8, Clear, NIR) */
    if (i2c_write_reg8(fd, AS7341_REG_SP_EN, AS7341_ENABLE_SP_EN) != 0)
        return -1;

    /* Set measurement rate to 1 sample per second (0x00 = 1 Hz) */
    if (i2c_write_reg8(fd, AS7341_REG_ALS_RATE, 0x00) != 0)
        return -1;

    /* Start spectral measurement */
    if (i2c_write_reg8(fd, AS7341_REG_ENABLE, AS7341_ENABLE_PON | AS7341_ENABLE_SP_EN) != 0)
        return -1;

    printf("AS7341 initialized: spectral measurement enabled.\n");
    return 0;
}

/* ------------------------------------------------------------------ */
/* Data acquisition                                                    */
/* ------------------------------------------------------------------ */
static int read_spectral_data(int fd, uint16_t *f1, uint16_t *f2,
                              uint16_t *f3, uint16_t *f4,
                              uint16_t *f5, uint16_t *f6,
                              uint16_t *f7, uint16_t *f8,
                              uint16_t *clear, uint16_t *nir)
{
    if (i2c_read_reg16(fd, AS7341_REG_ALS_RATE1, f1) != 0) return -1;
    if (i2c_read_reg16(fd, AS7341_REG_ALS_RATE3, f2) != 0) return -1;
    if (i2c_read_reg16(fd, AS7341_REG_ALS_RATE5, f3) != 0) return -1;
    if (i2c_read_reg16(fd, AS7341_REG_ALS_RATE7, f4) != 0) return -1;
    if (i2c_read_reg16(fd, AS7341_REG_ALS_RATE9, f5) != 0) return -1;
    if (i2c_read_reg16(fd, AS7341_REG_ALS_RATE11, f6) != 0) return -1;
    if (i2c_read_reg16(fd, AS7341_REG_ALS_RATE13, f7) != 0) return -1;
    if (i2c_read_reg16(fd, AS7341_REG_ALS_RATE15, f8) != 0) return -1;
    if (i2c_read_reg16(fd, AS7341_REG_ALS_RATE17, clear) != 0) return -1;
    if (i2c_read_reg16(fd, AS7341_REG_ALS_RATE19, nir) != 0) return -1;

    /* F1-F8 are already read via AS7341_REG_ALS_RATE1..AS7341_REG_ALS_RATE8 */
    uint16_t f9, f10, f11, f12;
    if (i2c_read_reg16(fd, AS7341_REG_ALS_RATE21, f9) != 0) return -1;
    if (i2c_read_reg16(fd, AS7341_REG_ALS_RATE23, f10) != 0) return -1;
    if (i2c_read_reg16(fd, AS7341_REG_ALS_RATE25, f11) != 0) return -1;
    if (i2c_read_reg16(fd, AS7341_REG_ALS_RATE27, f12) != 0) return -1;

    /* F9-F12 are aliases for F5-F8 */
    *f5 = f9; *f6 = f10; *f7 = f11; *f8 = f12;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Lux approximation (simplified)                                      */
/* ------------------------------------------------------------------ */
static float calculate_lux(uint16_t f1, uint16_t f2, uint16_t f3,
                           uint16_t f4, uint16_t f5,
                           uint16_t f6, uint16_t f7, uint16_t f8,
                           uint16_t clear, uint16_t nir)
{
    /* Simplified approximation: lux ~ (clear + NIR) * (F1 + F2) / 10000 */
    float lux = ((float)clear + (float)nir) * (f1 + f2) / 10000.0f;
    if (lux < 0.0f) lux = 0.0f;
    return lux;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, uint16_t f1, uint16_t f2,
                    uint16_t f3, uint16_t f4,
                    uint16_t f5, uint16_t f6,
                    uint16_t f7, uint16_t f8,
                    uint16_t clear, uint16_t nir,
                    float lux)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%.2f\n",
                timestamp, f1, f2, f3, f4, f5, f6, f7, f8, clear, lux) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        /* Power down the sensor */
        (void)i2c_write_reg8(g_i2c_fd, AS7341_REG_ENABLE, 0x00);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, AS7341_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                AS7341_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (sensor_init(g_i2c_fd) != 0) {
        fprintf(stderr, "AS7341 initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "timestamp,f1,f2,f3,f4,f5,f6,f7,f8,clear,nir,lux\n");
        fflush(g_log_fp);
    }

    printf("Starting spectral logging to %s every %d s. Press Ctrl+C to stop.\n",
           LOG_FILE, SAMPLE_PERIOD);

    while (g_running) {
        uint16_t f1, f2, f3, f4, f5, f6, f7, f8, clear, nir;

        if (read_spectral_data(g_i2c_fd, &f1, &f2, &f3, &f4, &f5,
                               &f6, &f7, &f8, &clear, &nir) != 0) {
            fprintf(stderr, "Failed to read spectral data; continuing.\n");
        } else {
            float lux = calculate_lux(f1, f2, f3, f4, f5,
                                      f6, f7, f8, clear, nir);
            if (log_data(g_log_fp, f1, f2, f3, f4, f5, f6, f7, f8, clear, nir, lux) != 0) {
                fprintf(stderr, "Failed to log data.\n");
            } else {
                printf("F1=%u F2=%u F3=%u F4=%u F5=%u F6=%u F7=%u F8=%u "
                       "Clear=%u NIR=%u Lux=%.2f\n",
                       f1, f2, f3, f4, f5, f6, f7, f8, clear, nir, lux);
            }
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD && g_running; i++)
            sleep(1);
    }

    printf("\nShutting down cleanly.\n");
    cleanup();
    return EXIT_SUCCESS;
}

