/*
 * seismic_logger.c — Raspberry Pi Zero W
 *
 * Reads tri-axial acceleration data from an Omron D7S seismic sensor
 * over I2C (/dev/i2c-1) and logs timestamped X, Y, Z values in g
 * to a CSV file (default: seismic_data.csv).
 *
 * Build:  gcc -O2 -Wall -Wextra -o seismic_logger seismic_logger.c
 * Usage:  ./seismic_logger [-a i2c_addr] [-i interval_sec] [-f filename]
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define DEFAULT_I2C_ADDR        0x68
#define DEFAULT_INTERVAL_SEC    1
#define DEFAULT_FILENAME        "seismic_data.csv"
#define MAX_RETRIES             3
#define RETRY_DELAY_MS          10
#define I2C_BUS                 "/dev/i2c-1"
#define ERROR_LOG_FILE          "seismic_error.log"

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1)
        perror("warning: sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) == -1)
        perror("warning: sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) != NULL)
        strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm);
    else
        snprintf(buf, len, "1970-01-01 00:00:00");
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_byte(int fd, uint8_t byte)
{
    if (write(fd, &byte, 1) != 1) {
        char ts[32];
        get_timestamp(ts, sizeof(ts));
        fprintf(stderr, "%s: I2C write error (0x%02X): %s\n",
                ts, byte, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        char ts[32];
        get_timestamp(ts, sizeof(ts));
        fprintf(stderr, "%s: I2C read error: %s\n", ts, strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        char ts[32];
        get_timestamp(ts, sizeof(ts));
        fprintf(stderr, "%s: I2C read short: got %zd of %zu bytes\n",
                ts, n, len);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor abstraction                                                  */
/* ------------------------------------------------------------------ */
/*
 * D7S output: 6 bytes of acceleration data (X, Y, Z each 2 bytes).
 * Little-endian: [X_L, X_H, Y_L, Y_H, Z_L, Z_H]  ->  X, Y, Z
 * Each 16-bit sample is left-justified in a 24-bit field (bits 15..8).
 */
static int read_acceleration(int fd, float *x_g, float *y_g, float *z_g)
{
    uint8_t raw[6];
    int ok = 0;

    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        if (i2c_read_block(fd, raw, sizeof(raw)) == 0) {
            ok = 1;
            break;
        }
        if (attempt < MAX_RETRIES - 1)
            usleep(RETRY_DELAY_MS * 1000);
    }

    if (!ok) {
        char ts[32];
        get_timestamp(ts, sizeof(ts));
        fprintf(stderr, "%s: Failed to read acceleration after %d attempts\n",
                ts, MAX_RETRIES);
        return -1;
    }

    int16_t x_raw = (int16_t)((raw[1] << 8) | raw[0]);
    int16_t y_raw = (int16_t)((raw[3] << 8) | raw[2]);
    int16_t z_raw = (int16_t)((raw[5] << 8) | raw[4]);

    /* D7S: 16-bit left-justified in 24-bit field; scale factor ~ 0.000061 g/LSB */
    *x_g = (float)x_raw * 0.000061f;
    *y_g = (float)y_raw * 0.000061f;
    *z_g = (float)z_raw * 0.000061f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* CSV logging                                                         */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, float x_g, float y_g, float z_g)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));
    if (fprintf(fp, "%s,%.6f,%.6f,%.6f\n", ts, x_g, y_g, z_g) < 0) {
        char ts[32];
        get_timestamp(ts, sizeof(ts));
        fprintf(stderr, "%s: fprintf to CSV failed: %s\n", ts, strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        char ts[32];
        get_timestamp(ts, sizeof(ts));
        fprintf(stderr, "%s: fflush CSV failed: %s\n", ts, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Error logging                                                       */
/* ------------------------------------------------------------------ */
static void log_error(const char *msg)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));
    FILE *fp = fopen(ERROR_LOG_FILE, "a");
    if (fp) {
        fprintf(fp, "%s: %s\n", ts, msg);
        fclose(fp);
    }
    fprintf(stderr, "%s: %s\n", ts, msg);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    int i2c_addr = DEFAULT_I2C_ADDR;
    int interval = DEFAULT_INTERVAL_SEC;
    char filename[256];
    snprintf(filename, sizeof(filename), "%s", DEFAULT_FILENAME);

    int opt;
    while ((opt = getopt(argc, argv, "a:i:f:h")) != -1) {
        switch (opt) {
        case 'a':
            i2c_addr = (int)strtol(optarg, NULL, 0);
            if (i2c_addr <= 0 || i2c_addr > 0x7F) {
                fprintf(stderr, "Error: invalid I2C address 0x%02X\n", i2c_addr);
                return EXIT_FAILURE;
            }
            break;
        case 'i':
            interval = (int)strtol(optarg, NULL, 0);
            if (interval <= 0) {
                fprintf(stderr, "Error: interval must be positive\n");
                return EXIT_FAILURE;
            }
            break;
        case 'f':
            if (strlen(optarg) >= sizeof(filename) - 1) {
                fprintf(stderr, "Error: filename too long\n");
                return EXIT_FAILURE;
            }
            strncpy(filename, optarg, sizeof(filename) - 1);
            filename[sizeof(filename) - 1] = '\0';
            break;
        case 'h':
        default:
            fprintf(stderr, "Usage: %s [-a i2c_addr] [-i interval_sec] [-f filename]\n", argv[0]);
            return EXIT_FAILURE;
        }
    }

    install_signal_handlers();

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        char ts[32];
        get_timestamp(ts, sizeof(ts));
        fprintf(stderr, "%s: open(%s) failed: %s\n", ts, I2C_BUS, strerror(errno));
        log_error("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    /* Set slave address */
    if (ioctl(g_i2c_fd, I2C_SLAVE, i2c_addr) < 0) {
        char ts[32];
        get_timestamp(ts, sizeof(ts));
        fprintf(stderr, "%s: ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                ts, i2c_addr, strerror(errno));
        log_error("Failed to set I2C slave address");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* Open CSV log */
    g_log_fp = fopen(filename, "a");
    if (!g_log_fp) {
        char ts[32];
        get_timestamp(ts, sizeof(ts));
        fprintf(stderr, "%s: fopen(%s) failed: %s\n", ts, filename, strerror(errno));
        log_error("Failed to open CSV log file");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_fp) == 0)
        fprintf(g_log_fp, "timestamp,x_g,y_g,z_g\n");

    printf("Seismic logger started.  I2C addr=0x%02X  interval=%ds  log=%s\n",
           i2c_addr, interval, filename);
    printf("Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        float x_g, y_g, z_g;
        if (read_acceleration(g_i2c_fd, &x_g, &y_g, &z_g) == 0) {
            if (log_data(g_log_fp, x_g, y_g, z_g) != 0)
                log_error("Failed to log data");
        } else {
            log_error("Failed to read acceleration data");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < interval * 10 && g_running; ++i)
            usleep(100 * 1000);
    }

    /* Graceful shutdown */
    printf("\nShutting down...\n");
    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    printf("Done.\n");
    return EXIT_SUCCESS;
}

