}

/* ------------------------------------------------------------------ */
/* CSV logging                                                         */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, float x_g, float y_g, float z_g)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));
    if (fprintf(fp, "%s,%.6f,%.6f,%.6f\n", ts, x_g, y_g, z_g) < 0) {
        char ts[32];
        get_timestamp(ts, sizeof(ts));
        fprintf(stderr, "%s: fprintf to CSV failed: %s\n", ts, strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        char ts[32];
        get_timestamp(ts, sizeof(ts));
        fprintf(stderr, "%s: fflush CSV failed: %s\n", ts, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Error logging                                                       */
/* ------------------------------------------------------------------ */
static void log_error(const char *msg)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));
    FILE *fp = fopen(ERROR_LOG_FILE, "a");
    if (fp) {
        fprintf(fp, "%s: %s\n", ts, msg);
        fclose(fp);
    }
    fprintf(stderr, "%s: %s\n", ts, msg);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    int i2c_addr = DEFAULT_I2C_ADDR;
    int interval = DEFAULT_INTERVAL_SEC;
    char filename[256];
    snprintf(filename, sizeof(filename), "%s", DEFAULT_FILENAME);

    int opt;
    while ((opt = getopt(argc, argv, "a:i:f:h")) != -1) {
        switch (opt) {
        case 'a':
            i2c_addr = (int)strtol(optarg, NULL, 0);
            if (i2c_addr <= 0 || i2c_addr > 0x7F) {
                fprintf(stderr, "Error: invalid I2C address 0x%02X\n", i2c_addr);
                return EXIT_FAILURE;
            }
            break;
        case 'i':
            interval = (int)strtol(optarg, NULL, 0);
            if (interval <= 0) {
                fprintf(stderr, "Error: interval must be positive\n");
                return EXIT_FAILURE;
            }
            break;
        case 'f':
            if (strlen(optarg) >= sizeof(filename) - 1) {
                fprintf(stderr, "Error: filename too long\n");
                return EXIT_FAILURE;
            }
            strncpy(filename, optarg, sizeof(filename) - 1);
            filename[sizeof(filename) - 1] = '\0';
            break;
        case 'h':
        default:
            fprintf(stderr, "Usage: %s [-a i2c_addr] [-i interval_sec] [-f filename]\n", argv[0]);
            return EXIT_FAILURE;
        }
    }

    install_signal_handlers();

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        char ts[32];
        get_timestamp(ts, sizeof(ts));
        fprintf(stderr, "%s: open(%s) failed: %s\n", ts, I2C_BUS, strerror(errno));
        log_error("Failed to open I2C bus");
        return EXIT_FAILURE;
    }

    /* Set slave address */
    if (ioctl(g_i2c_fd, I2C_SLAVE, i2c_addr) < 0) {
        char ts[32];
        get_timestamp(ts, sizeof(ts));
        fprintf(stderr, "%s: ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                ts, i2c_addr, strerror(errno));
        log_error("Failed to set I2C slave address");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* Open CSV log */
    g_log_fp = fopen(filename, "a");
    if (!g_log_fp) {
        char ts[32];
        get_timestamp(ts, sizeof(ts));
        fprintf(stderr, "%s: fopen(%s) failed: %s\n", ts, filename, strerror(errno));
        log_error("Failed to open CSV log file");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_fp) == 0)
        fprintf(g_log_fp, "timestamp,x_g,y_g,z_g\n");

    printf("Seismic logger started.  I2C addr=0x%02X  interval=%ds  log=%s\n",
           i2c_addr, interval, filename);
    printf("Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        float x_g, y_g, z_g;
        if (read_acceleration(g_i2c_fd, &x_g, &y_g, &z_g) == 0) {
            if (log_data(g_log_fp, x_g, y_g, z_g) != 0)
                log_error("Failed to log data");
        } else {
            log_error("Failed to read acceleration data");
        }

        /* Sleep in 100 ms increments so signals are caught promptly */
        for (int i = 0; i < interval * 10 && g_running; ++i)
            usleep(100 * 1000);
    }

    /* Graceful shutdown */
    printf("\nShutting down...\n");
    if (g_log_fp) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    printf("Done.\n");
    return EXIT_SUCCESS;
}

