#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define BH1750_ADDR    0x5C
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5000
#define MULTICAST_TTL  1
#define SAMPLE_PERIOD  1

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int bh1750_read(int fd, float *lux_out)
{
    uint8_t cmd = 0x10;
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "BH1750 write (power on) failed: %s\n", strerror(errno));
        return -1;
    }
    usleep(180000);

    uint8_t buf[2];
    ssize_t n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "BH1750 read failed (got %zd bytes): %s\n", n, strerror(errno));
        return -1;
    }

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static int send_multicast(int sockfd, float lux)
{
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_port   = htons(MULTICAST_PORT);
    if (inet_pton(AF_INET, MULTICAST_ADDR, &addr.sin_addr) != 1) {
        fprintf(stderr, "Invalid multicast address: %s\n", MULTICAST_ADDR);
        return -1;
    }

    char msg[64];
    int len = snprintf(msg, sizeof(msg), "%.2f", lux);
    if (len < 0 || (size_t)len >= sizeof(msg)) {
        fprintf(stderr, "snprintf failed\n");
        return -1;
    }

    if (sendto(sockfd, msg, (size_t)len, 0,
               (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        fprintf(stderr, "sendto failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open " I2C_BUS);
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("socket");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    int ttl = MULTICAST_TTL;
    if (setsockopt(sockfd, IPPROTO_IP, IP_MULTICAST_TTL, &ttl, sizeof(ttl)) < 0) {
        perror("setsockopt IP_MULTICAST_TTL");
        close(sockfd);
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (g_running) {
        float lux;
        if (bh1750_read(i2c_fd, &lux) == 0) {
            if (send_multicast(sockfd, lux) != 0) {
                fprintf(stderr, "Multicast send failed\n");
            }
        } else {
            fprintf(stderr, "BH1750 read failed; retrying in %d s\n", SAMPLE_PERIOD);
        }
        sleep(SAMPLE_PERIOD);
    }

    close(sockfd);
    close(i2c_fd);
    return EXIT_SUCCESS;
}

