/*
 * AWR1642 mmWave radar UART reader for Raspberry Pi 3 Model B+
 * Uses pigpio for UART communication.
 *
 * Wiring:
 *   AWR1642 UART_TX  -> Pi GPIO15 (RXD)
 *   AWR1642 UART_RX  -> Pi GPIO14 (TXD)
 *   AWR1642 GND      -> Pi GND
 *   AWR1642 3V3      -> Pi 3V3 (pin 1)
 *   AWR1642 GND      -> Pi GND (pin 9)
 *
 * Build: gcc -O2 -Wall -o radar_reader radar_reader.c -lpigpio -lrt
 * Run:   sudo ./radar_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define UART_DEVICE      "/dev/ttyS0"
#define BAUD_RATE        921600
#define CSV_FILENAME     "radar_data.csv"
#define READ_BUF_SIZE    4096
#define SYNC_LEN        8
#define TLV_HEADER_LEN  8
#define MAX_OBJECTS      64

/* AWR1642 mmWave TLV frame header (16 bytes total):
 *   4 bytes magic word (little-endian: 0x0102 0x0304 0x0506 0x0708)
 *   4 bytes version
 *   4 bytes total packet length
 *   4 bytes platform
 *   4 bytes frame number
 *   4 bytes time
 *   4 bytes num_detected_obj
 *   4 bytes num_tlvs
 */
typedef struct {
    uint32_t magic[4];
    uint32_t version;
    uint32_t total_len;
    uint32_t platform;
    uint32_t frame_num;
    uint32_t time;
    uint32_t num_detected_obj;
    uint32_t num_tlvs;
} __attribute__((packed)) frame_header_t;

/* TLV header (8 bytes):
 *   4 bytes type
 *   4 bytes length
 */
typedef struct {
    uint32_t type;
    uint32_t length;
} __attribute__((packed)) tlv_header_t;

/* AWR1642 TLV payload types:
 *   0x01: Object detection results (range, velocity, snr, etc.)
 *   1: Number of objects
 */
typedef struct {
    uint16_t range_idx;
    uint16_t doppler_idx;
    uint16_t snr;
    uint16_t x;
    uint16_t y;
    uint16_t z;
    uint16_t velocity;
} __attribute__((packed)) object_t;

static volatile sig_atomic_t g_running = 1;
static int  g_uart_handle = -1;
static FILE *g_csv_file    = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_uart_handle >= 0) {
        serClose(g_uart_handle);
        g_uart_handle = -1;
    }
    if (g_csv_file != NULL) {
        fflush(g_csv_file);
        fclose(g_csv_file);
        g_csv_file = NULL;
    }
    gpioTerminate();
}

static int init_uart(void)
{
    g_uart_handle = serOpen(UART_DEVICE, BAUD_RATE, 0);
    if (g_uart_handle < 0) {
        fprintf(stderr, "Error opening UART %s: %s\n",
                UART_DEVICE, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_csv(void)
{
    g_csv_file = fopen(CSV_FILENAME, "a");
    if (g_csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file %s: %s\n",
                CSV_FILENAME, strerror(errno));
        return -1;
    }
    /* Write header only if file is empty */
    if (ftell(g_csv_file) == 0) {
        fprintf(g_csv_file, "timestamp,object_index,range_m,velocity_mps\n");
        fflush(g_csv_file);
    }
    return 0;
}

/*
 * Synchronize on the 8-byte little-endian magic word.
 * Returns 0 on success, -1 on timeout or error.
 */
static int sync_magic_word(int handle)
{
    uint8_t buf[SYNC_LEN];
    int idx = 0;
    uint32_t start_tick = gpioTick();

    while (g_running) {
        int n = serRead(handle, (char *)buf, sizeof(buf));
        if (n < 0) {
            fprintf(stderr, "UART read error: %s\n", strerror(errno));
            return -1;
        }
        if (n == 0) {
            /* No data available; check timeout */
            if ((gpioTick() - start_tick) / 1000 > 1000) {
                fprintf(stderr, "Timeout waiting for magic word\n");
                return -1;
            }
            continue;
        }

        for (int i = 0; i < n; i++) {
            if (buf[i] == 0x02 && buf[i + 1] == 0x01 &&
                buf[i + 2] == 0x04 && buf[i + 3] == 0x06 &&
                buf[i + 4] == 0x08 && buf[i + 5] == 0x10 &&
                buf[i + 6] == 0x20 && buf[i + 7] == 0x40) {
                return 0;
            }
            buf[idx++] = buf[i];
            if (idx >= SYNC_LEN) {
                /* Buffer overflow; reset */
                idx = 0;
                break;
            }
        }
    }
    return -1;
}

static int read_frame(int handle, frame_header_t *header)
{
    int n = serRead(handle, (char *)header, sizeof(frame_header_t));
    if (n < 0) {
        fprintf(stderr, "UART read error: %s\n", strerror(errno));
        return -1;
    }
    if (n == 0) {
        return 1; /* timeout */
    }
    if (n < (int)sizeof(frame_header_t)) {
        fprintf(stderr, "Incomplete frame header (%d bytes)\n", n);
        return -1;
    }

    /* Validate magic word */
    uint32_t *m = (uint32_t *)header;
    for (int i = 0; i < 4; i++) {
        if (m[i] != 0x0102 || m[i + 1] != 0x0304 ||
            m[i + 2] != 0x0506 || m[i + 3] != 0x0708) {
            fprintf(stderr, "Invalid magic word: 0x%08x 0x%08x 0x%08x 0x%08x\n",
                    m[i], m[i + 1], m[i + 2], m[i + 3]);
            return -1;
        }
    }

    /* Validate total packet length */
    uint32_t total_len = header->total_len;
    if (total_len < sizeof(frame_header_t) || total_len > READ_BUF_SIZE) {
        fprintf(stderr, "Invalid total packet length: %u\n", total_len);
        return -1;
    }

    /* Read remaining payload */
    uint8_t *payload = malloc(total_len - sizeof(frame_header_t));
    if (payload == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return -1;
    }

    n = serRead(handle, (char *)payload, total_len - sizeof(frame_header_t));
    if (n < 0) {
        fprintf(stderr, "UART read error: %s\n", strerror(errno));
        free(payload);
        return -1;
    }
    if (n == 0) {
        fprintf(stderr, "Frame payload read timeout\n");
        free(payload);
        return -1;
    }
    if (n < (int)(total_len - sizeof(frame_header_t))) {
        fprintf(stderr, "Incomplete frame payload (%d of %u bytes)\n",
                n, total_len - sizeof(frame_header_t));
        free(payload);
        return -1;
    }

    /* Parse TLVs */
    int obj_count = 0;
    for (uint32_t i = 0; i < header->num_tlvs; i++) {
        tlv_header_t *tlv = (tlv_header_t *)(payload + sizeof(frame_header_t) + i * TLV_HEADER_LEN);
        if (tlv->length > header->total_len - sizeof(frame_header_t) - sizeof(tlv_header_t) - i * TLV_HEADER_LEN) {
            fprintf(stderr, "TLV length exceeds frame bounds\n");
            break;
        }
        if (tlv->type == 0x01 && tlv->length >= sizeof(object_t)) {
            uint8_t *obj = payload + sizeof(frame_header_t) + sizeof(tlv_header_t) + i * TLV_HEADER_LEN;
            int num_objs = tlv->length / sizeof(object_t);
            for (int j = 0; j < num_objs; j++) {
                if (obj_count >= MAX_OBJECTS) break;
                object_t *obj_t = (object_t *)obj + j;
                float range_m = (float)obj_t->range_idx * 0.0435f; /* AWR1642: ~0.0435 m/idx */
                float velocity_mps = (float)obj_t->velocity * 0.0435f; /* AWR1642: ~0.0435 m/s/doppler */
                if (fprintf(g_csv_file, "%ld,%d,%.3f,%.3f\n",
                            (long)time(NULL), obj_count, range_m, velocity_mps) < 0) {
                    fprintf(stderr, "CSV write error: %s\n", strerror(errno));
                    free(payload);
                    return -1;
                }
                obj_count++;
            }
        }
    }

    free(payload);
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (init_uart() != 0) {
        cleanup();
        return 1;
    }

    if (init_csv() != 0) {
        cleanup();
        return 1;
    }

    printf("AWR1642 radar reader started. Press Ctrl+C to stop.\n");

    while (g_running) {
        if (sync_magic_word(g_uart_handle) != 0) {
            if (!g_running) break;
            continue;
        }

        frame_header_t header;
        if (read_frame(g_uart_handle, &header) != 0) {
            if (!g_running) break;
            continue;
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

