#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <termios.h>
#include <sys/select.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B115200
#define LINE_BUF_SIZE 512
#define READ_TIMEOUT_SEC 2
#define POLL_INTERVAL_SEC 0.5

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int init_uart(const char *device, speed_t baud)
{
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        fprintf(stderr, "Error opening UART %s: %s\n", device, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error from tcgetattr: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, baud);
    cfsetispeed(&tty, baud);

    tty.c_cflag &= ~PARENB;
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CSIZE;
    tty.c_cflag |= CS8;
    tty.c_cflag |= CLOCAL | CREAD;

    tty.c_iflag &= ~(IXON | IXOFF | IXANY);
    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);

    tty.c_oflag &= ~OPOST;
    tty.c_oflag &= ~ONLCR;

    tty.c_lflag &= ~(ICANON | ECHO | ECHOE | ISIG);

    tty.c_cc[VMIN]  = 0;
    tty.c_cc[VTIME] = 5; /* 0.5 s inter-byte timeout */

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error from tcsetattr: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

static void format_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm timeinfo;

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &timeinfo);
}

static void log_detection(FILE *fp, const char *line)
{
    char ts[32];
    char range[32];

    if (sscanf(line, "%31s,%31s", ts, range) == 2) {
        format_timestamp(ts, sizeof(ts));
        printf("Timestamp: %s, Range: %.2f meters\n", ts, atof(range));
        fflush(fp);
    } else {
        fprintf(stderr, "Warning: malformed detection line: %s\n", line);
    }
}

int main(void)
{
    char line_buf[LINE_BUF_SIZE];
    size_t line_len = 0;
    int uart_fd = -1;
    FILE *log_fp = NULL;
    int exit_code = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error installing SIGINT handler: %s\n", strerror(errno));
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error installing SIGTERM handler: %s\n", strerror(errno));
        goto cleanup;
    }

    uart_fd = init_uart(UART_DEVICE, BAUD_RATE);
    if (uart_fd < 0) {
        goto cleanup;
    }

    log_fp = fopen("radar_detection.log", "a");
    if (log_fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        goto cleanup;
    }

    printf("Radar data acquisition started on %s at 115200 8N1. Press Ctrl+C to stop.\n", UART_DEVICE);

    while (g_running) {
        fd_set readfds;
        struct timeval timeout;

        FD_ZERO(&readfds);
        FD_SET(uart_fd, &readfds);

        timeout.tv_sec  = READ_TIMEOUT_SEC;
        timeout.tv_usec = 0;

        int sel = select(uart_fd + 1, &readfds, NULL, NULL, &timeout);
        if (sel < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "Error from select(): %s\n", strerror(errno));
            goto cleanup;
        }
        if (sel == 0) {
            /* Timeout — sensor absent or bus error */
            fprintf(stderr, "Timeout: no data from radar in %d seconds\n", READ_TIMEOUT_SEC);
            continue;
        }

        char ch;
        ssize_t n = read(uart_fd, &ch, 1);
        if (n < 0) {
            if (errno == EINTR) {
                continue;
            }
            fprintf(stderr, "Error reading from UART: %s\n", strerror(errno));
            goto cleanup;
        }
        if (n == 0) {
            /* Should not happen with VTIME > 0 */
            continue;
        }

        if (ch == '\n') {
            line_buf[line_len] = '\0';
            if (line_len > 0) {
                log_detection(log_fp, line_buf);
                line_len = 0;
            }
        } else if (ch != '\r') {
            if (line_len < LINE_BUF_SIZE - 1) {
                line_buf[line_len++] = ch;
            } else {
                fprintf(stderr, "Warning: line exceeded buffer, discarding\n");
                line_len = 0;
            }
        }
    }

    exit_code = EXIT_SUCCESS;

cleanup:
    if (uart_fd >= 0) {
        tcflush(uart_fd, TCIOFLUSH);
        close(uart_fd);
    }
    if (log_fp != NULL) {
        fclose(log_fp);
    }
    printf("\nRadar data acquisition stopped.\n");
    return exit_code;
}

