#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <stdint.h>
#include <stdbool.h>
#include <pigpio.h>

#define LEFT_SENSOR_PIN 4
#define MIDDLE_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27
#define UART_DEVICE "/dev/ttyAMA0"
#define BAUD_RATE B115200
#define POLL_DELAY_US 100000

static volatile sig_atomic_t running = 1;
static int uart_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_uart(void) {
    uart_fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_NDELAY);
    if (uart_fd < 0) {
        fprintf(stderr, "Error opening UART %s: %s\n", UART_DEVICE, strerror(errno));
        return -1;
    }

    struct termios options;
    if (tcgetattr(uart_fd, &options) != 0) {
        fprintf(stderr, "Error getting UART attributes: %s\n", strerror(errno));
        close(uart_fd);
        uart_fd = -1;
        return -1;
    }

    cfsetispeed(&options, BAUD_RATE);
    cfsetospeed(&options, BAUD_RATE);

    options.c_cflag = (options.c_cflag & ~CSIZE) | CS8;
    options.c_cflag |= (CLOCAL | CREAD);
    options.c_cflag &= ~(PARENB | PARODD);
    options.c_cflag &= ~CSTOPB;
    options.c_cflag &= ~CRTSCTS;

    options.c_iflag = IGNPAR;
    options.c_iflag &= ~(IXON | IXOFF | IXANY);
    options.c_iflag &= ~(INLCR | ICRNL);

    options.c_oflag = 0;
    options.c_lflag = 0;

    if (tcsetattr(uart_fd, TCSANOW, &options) != 0) {
        fprintf(stderr, "Error setting UART attributes: %s\n", strerror(errno));
        close(uart_fd);
        uart_fd = -1;
        return -1;
    }

    return 0;
}

static int read_sensor(int pin) {
    int value = gpioRead(pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %s\n", pin, pigpio_error(value));
        return -1;
    }
    return value;
}

static void log_sensor_data(int left, int middle, int right) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Left: %d, Middle: %d, Right: %d\n", timestamp, left, middle, right);
}

static void send_emergency_stop(void) {
    if (uart_fd < 0) {
        fprintf(stderr, "UART not initialized; cannot send emergency stop.\n");
        return;
    }

    if (write(uart_fd, "EMERGENCY STOP!\n", 16) < 0) {
        fprintf(stderr, "Error writing to UART: %s\n", strerror(errno));
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction SIGINT");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction SIGTERM");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (init_uart() != 0) {
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", LEFT_SENSOR_PIN);
        close(uart_fd);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", MIDDLE_SENSOR_PIN);
        close(uart_fd);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", RIGHT_SENSOR_PIN);
        close(uart_fd);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(LEFT_SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", LEFT_SENSOR_PIN);
        close(uart_fd);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(MIDDLE_SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", MIDDLE_SENSOR_PIN);
        close(uart_fd);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(RIGHT_SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", RIGHT_SENSOR_PIN);
        close(uart_fd);
        gpioTerminate();
        return 1;
    }

    printf("KY-033 sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int left = read_sensor(LEFT_SENSOR_PIN);
        int middle = read_sensor(MIDDLE_SENSOR_PIN);
        int right = read_sensor(RIGHT_SENSOR_PIN);

        if (left < 0 || middle < 0 || right < 0) {
            fprintf(stderr, "Sensor read error; continuing...\n");
        } else {
            log_sensor_data(left, middle, right);

            if (left == 0 && middle == 0 && right == 0) {
                send_emergency_stop();
            }
        }

        usleep(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    if (uart_fd >= 0) {
        close(uart_fd);
    }
    gpioTerminate();
    return 0;
}
